-- [40000000001] function private.is_admin()
CREATE OR REPLACE FUNCTION private.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.profiles
    where profiles.id = auth.uid()
      and profiles.role = 'admin'
  );
$function$


-- [40000000002] function private.is_conversation_member(p_conversation_id uuid, p_user_id uuid)
CREATE OR REPLACE FUNCTION private.is_conversation_member(p_conversation_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select exists (
    select 1
    from public.tgg_conversation_members cm
    where cm.conversation_id=p_conversation_id
      and cm.user_id=p_user_id
  );
$function$


-- [40000000003] function private.tgg_accept_contract(p_character_id uuid, p_contract_key text)
CREATE OR REPLACE FUNCTION private.tgg_accept_contract(p_character_id uuid, p_contract_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_contract public.tgg_world_career_contracts%rowtype;
  v_rep integer:=0;
  v_step public.tgg_world_contract_chain_steps%rowtype;
  v_prev text;
  v_contact text;
  v_trust integer:=0;
  v_existing public.tgg_world_character_contracts%rowtype;
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select * into v_char
  from public.world_characters
  where id=p_character_id and user_id=v_uid and character_status='active';
  if v_char.id is null then raise exception 'character ownership mismatch'; end if;

  select * into v_contract
  from public.tgg_world_career_contracts
  where contract_key=p_contract_key and enabled=true;
  if v_contract.contract_key is null then raise exception 'contract unavailable'; end if;

  if v_char.active_career is distinct from v_contract.career_key then
    raise exception 'active career does not match contract';
  end if;

  select coalesce(reputation,0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=p_character_id and career_key=v_contract.career_key;

  if coalesce(v_rep,0)<coalesce(v_contract.reputation_required,0) then
    raise exception 'reputation requirement not met';
  end if;

  select * into v_step
  from public.tgg_world_contract_chain_steps
  where contract_key=p_contract_key
  order by step_order
  limit 1;

  if found then
    v_prev:=nullif(v_step.unlock_condition->>'previous_contract','');
    if v_prev is not null and not exists(
      select 1 from public.tgg_world_character_contracts
      where character_id=p_character_id and contract_key=v_prev and status='completed'
    ) then
      raise exception 'previous contract required';
    end if;

    if v_step.unlock_condition ? 'reputation'
       and v_rep<coalesce((v_step.unlock_condition->>'reputation')::integer,0) then
      raise exception 'chain reputation requirement not met';
    end if;

    v_contact:=nullif(v_step.unlock_condition->>'relationship_contact','');
    if v_contact is not null and v_step.unlock_condition ? 'trust_score' then
      select coalesce(trust_score,0) into v_trust
      from public.tgg_world_contact_relationships
      where character_id=p_character_id and contact_key=v_contact;
      if coalesce(v_trust,0)<coalesce((v_step.unlock_condition->>'trust_score')::integer,0) then
        raise exception 'relationship trust requirement not met';
      end if;
    end if;
  end if;

  select * into v_existing
  from public.tgg_world_character_contracts
  where character_id=p_character_id and contract_key=p_contract_key
  for update;

  if found and v_existing.status='completed' and not v_contract.repeatable then
    return v_existing.id;
  end if;

  insert into public.tgg_world_character_contracts(
    character_id,contract_key,status,progress,accepted_at,completed_at,updated_at
  )
  values(p_character_id,p_contract_key,'active','{}'::jsonb,now(),null,now())
  on conflict(character_id,contract_key) do update
  set status='active',
      progress=case
        when public.tgg_world_character_contracts.status='completed' and v_contract.repeatable
          then '{}'::jsonb
        else public.tgg_world_character_contracts.progress
      end,
      accepted_at=case
        when public.tgg_world_character_contracts.status='completed' and v_contract.repeatable
          then now()
        else public.tgg_world_character_contracts.accepted_at
      end,
      completed_at=case
        when public.tgg_world_character_contracts.status='completed' and v_contract.repeatable
          then null
        else public.tgg_world_character_contracts.completed_at
      end,
      updated_at=now()
  returning id into v_id;

  return v_id;
end;
$function$


-- [40000000004] function private.tgg_accept_gig(p_character_id uuid, p_gig_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_accept_gig(p_character_id uuid, p_gig_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  if not exists(
    select 1 from public.world_characters wc
    where wc.id=p_character_id and wc.user_id=v_uid
  ) then
    raise exception 'character ownership mismatch';
  end if;

  update public.tgg_world_character_gigs
  set status='accepted',
      accepted_at=coalesce(accepted_at,now()),
      updated_at=now()
  where id=p_gig_id
    and character_id=p_character_id
    and status='available'
    and (expires_at is null or expires_at > now())
  returning id into v_id;

  if v_id is null then raise exception 'gig unavailable'; end if;

  perform private.tgg_world_onboarding_event(p_character_id,'gig_accepted',v_id::text);

  return v_id;
end;
$function$


-- [40000000005] function private.tgg_actionable_blogger_live_state(p_live jsonb)
CREATE OR REPLACE FUNCTION private.tgg_actionable_blogger_live_state(p_live jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_drift jsonb:='[]'::jsonb;
  v_missing jsonb:='[]'::jsonb;
  v_drift_count integer:=0;
  v_missing_count integer:=0;
  v_out jsonb;
begin
  select coalesce(jsonb_agg(x),'[]'::jsonb)
  into v_drift
  from jsonb_array_elements(coalesce(p_live->'drift','[]'::jsonb)) x
  where
    not exists(
      select 1
      from public.tgg_site_routes r
      where split_part(r.path,'#',1)=x->>'path'
    )
    or exists(
      select 1
      from public.tgg_site_routes r
      where split_part(r.path,'#',1)=x->>'path'
        and r.is_active=true
    );

  select coalesce(jsonb_agg(x),'[]'::jsonb)
  into v_missing
  from jsonb_array_elements(coalesce(p_live->'missing_pages','[]'::jsonb)) x
  where
    not exists(
      select 1
      from public.tgg_site_routes r
      where split_part(r.path,'#',1)=coalesce(x->>'path',x#>>'{}')
    )
    or exists(
      select 1
      from public.tgg_site_routes r
      where split_part(r.path,'#',1)=coalesce(x->>'path',x#>>'{}')
        and r.is_active=true
    );

  v_drift_count:=jsonb_array_length(v_drift);
  v_missing_count:=jsonb_array_length(v_missing);

  v_out:=coalesce(p_live,'{}'::jsonb)
    || jsonb_build_object(
      'raw_drift_count',coalesce((p_live->>'drift_count')::integer,0),
      'raw_ok',coalesce((p_live->>'ok')::boolean,false),
      'drift',v_drift,
      'drift_count',v_drift_count,
      'missing_pages',v_missing,
      'suppressed_inactive_legacy_drift',
        greatest(coalesce((p_live->>'drift_count')::integer,0)-v_drift_count,0),
      'ok',(v_drift_count=0 and v_missing_count=0),
      'classification','active_or_unknown_routes_only'
    );

  return v_out;
end;
$function$


-- [40000000006] function private.tgg_activation_consistency_alerts_owner()
CREATE OR REPLACE FUNCTION private.tgg_activation_consistency_alerts_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','ACTIVATION-MONITOR-ONE-FINAL-1.0',
    'open_mismatches',(
      select count(*)
      from private.tgg_activation_consistency_alerts
      where resolved_at is null
    ),
    'alerts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'item_key',item_key,
        'alert_type',alert_type,
        'expected_complete',expected_complete,
        'queue_status',queue_status,
        'first_seen_at',first_seen_at,
        'last_seen_at',last_seen_at
      ) order by last_seen_at desc,id desc)
      from private.tgg_activation_consistency_alerts
      where resolved_at is null
    ),'[]'::jsonb),
    'generated_at',now()
  );
end
$function$


-- [40000000007] function private.tgg_activation_consistency_monitor()
CREATE OR REPLACE FUNCTION private.tgg_activation_consistency_monitor()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid;
  v_audit jsonb;
  v_mismatch jsonb;
  v_key text;
  v_expected boolean;
  v_queue_status text;
  v_alert_type text;
  v_seen_keys text[]:=array[]::text[];
  v_open integer:=0;
begin
  select id into v_owner
  from auth.users
  where raw_app_meta_data->>'tgg_role'='owner'
  order by created_at
  limit 1;

  if v_owner is null then
    raise exception 'OWNER_NOT_FOUND';
  end if;

  perform set_config('request.jwt.claim.sub',v_owner::text,true);
  perform private.tgg_refresh_one_final_activation_queue_all();

  v_audit:=private.tgg_activation_queue_consistency_audit_owner();

  for v_mismatch in
    select value
    from jsonb_array_elements(coalesce(v_audit->'mismatches','[]'::jsonb))
  loop
    v_key:=v_mismatch->>'key';
    v_expected:=coalesce((v_mismatch->>'should_be_complete')::boolean,false);
    v_queue_status:=v_mismatch->>'queue_status';
    v_alert_type:=case
      when v_queue_status is null then 'queue_missing'
      when v_expected then 'queue_stale_pending'
      else 'queue_false_complete'
    end;
    v_seen_keys:=array_append(v_seen_keys,v_key);

    insert into private.tgg_activation_consistency_alerts(
      item_key,alert_type,expected_complete,queue_status,details
    )
    values(
      v_key,v_alert_type,v_expected,v_queue_status,
      jsonb_build_object(
        'monitor_version','ACTIVATION-MONITOR-ONE-FINAL-1.1',
        'audit_version',v_audit->>'version'
      )
    )
    on conflict(item_key,alert_type) where resolved_at is null
    do update set
      expected_complete=excluded.expected_complete,
      queue_status=excluded.queue_status,
      last_seen_at=now(),
      details=private.tgg_activation_consistency_alerts.details||excluded.details;
  end loop;

  update private.tgg_activation_consistency_alerts
  set resolved_at=now(),last_seen_at=now()
  where resolved_at is null
    and not (item_key=any(v_seen_keys));

  select count(*) into v_open
  from private.tgg_activation_consistency_alerts
  where resolved_at is null;

  perform private.tgg_track_activation_state_changes();

  return jsonb_build_object(
    'ok',v_open=0,
    'version','ACTIVATION-MONITOR-ONE-FINAL-1.1',
    'checked_items',coalesce((v_audit->>'checked_items')::integer,0),
    'open_mismatches',v_open,
    'audit_ok',coalesce((v_audit->>'ok')::boolean,false),
    'generated_at',now()
  );
end
$function$


-- [40000000008] function private.tgg_activation_queue_consistency_audit_owner()
CREATE OR REPLACE FUNCTION private.tgg_activation_queue_consistency_audit_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
  v_dist_master_complete boolean:=false;
  v_dist_legal_complete boolean:=false;
  v_dist_provider_complete boolean:=false;
  v_membership_complete boolean:=false;
  v_stripe_webhook_complete boolean:=false;
  v_broadcast_complete boolean:=false;
  v_calls_complete boolean:=false;
  v_auth_hardening_complete boolean:=false;
  v_edge_cleanup_complete boolean:=false;
  v_blogger_complete boolean:=false;
  v_custom_smtp_complete boolean:=false;
  v_mismatches jsonb:='[]'::jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  select not exists(
    select 1
    from jsonb_array_elements(coalesce(public.tgg_distribution_master_reuse_status()->'groups','[]'::jsonb)) g
    where not coalesce((g->>'confirmed_intentional')::boolean,false)
  ) into v_dist_master_complete;

  select not exists(
    select 1
    from public.mixtapes m
    join public.artists a on a.id=m.artist_id
    left join public.tgg_distribution_release_metadata dm
      on dm.release_id=m.id
     and dm.owner_user_id=v_uid
    where a.user_id=v_uid
      and m.status='published'::public.mixtape_status
      and exists(select 1 from public.tracks t where t.mixtape_id=m.id)
      and (
        dm.release_id is null
        or not coalesce(dm.rights_confirmed,false)
        or nullif(btrim(coalesce(dm.label_name,'')),'') is null
        or nullif(btrim(coalesce(dm.copyright_line,'')),'') is null
        or nullif(btrim(coalesce(dm.publishing_line,'')),'') is null
        or coalesce(jsonb_array_length(dm.territories),0)=0
      )
  ) into v_dist_legal_complete;

  select coalesce(enabled,false) and mode='production' and coalesce(endpoint_configured,false)
  into v_dist_provider_complete
  from public.tgg_provider_runtime_config
  where provider_key='distribution.provider';

  select coalesce(enabled,false) and mode='production' and coalesce(endpoint_configured,false)
  into v_stripe_webhook_complete
  from public.tgg_provider_runtime_config
  where provider_key='stripe.webhook';

  select exists(
    select 1
    from public.tgg_membership_tiers t
    join public.artists a on a.id=t.artist_id
    where a.user_id=v_uid
      and t.is_active
      and t.stripe_payment_link_verified
  ) and coalesce(v_stripe_webhook_complete,false)
  into v_membership_complete;

  select coalesce(enabled,false) and mode='production' and coalesce(endpoint_configured,false)
  into v_broadcast_complete
  from public.tgg_provider_runtime_config
  where provider_key='broadcast.sfu_turn';

  select coalesce((public.tgg_call_validation_final_health()->>'validated')::boolean,false)
  into v_calls_complete;

  select exists(
    select 1
    from public.v98_blogger_connections
    where status='connected'
      and revoked_at is null
      and coalesce(last_error,'')=''
  ) into v_blogger_complete;

  select exists(
    select 1
    from private.tgg_one_final_activation_queue q
    where q.item_key='custom_auth_smtp'
      and q.status='complete'
      and coalesce((q.evidence->>'user_marked_complete_or_skip')::boolean,false)
  ) into v_custom_smtp_complete;

  v_auth_hardening_complete:=false;
  v_edge_cleanup_complete:=false;

  with expected as (
    select * from (values
      ('blogger_maintenance_oauth',v_blogger_complete),
      ('custom_auth_smtp',v_custom_smtp_complete),
      ('distribution_master_assignment',v_dist_master_complete),
      ('distribution_legal_metadata',v_dist_legal_complete),
      ('distribution_provider',v_dist_provider_complete),
      ('membership_tier',v_membership_complete),
      ('stripe_webhook_signing_secret',v_stripe_webhook_complete),
      ('sfu_turn_provider',v_broadcast_complete),
      ('second_call_user',v_calls_complete),
      ('supabase_leaked_password_protection',v_auth_hardening_complete),
      ('edge_physical_cleanup',v_edge_cleanup_complete)
    ) as x(item_key,should_be_complete)
  ),
  mismatches as (
    select
      e.item_key,
      e.should_be_complete,
      q.status as queue_status,
      q.last_checked_at
    from expected e
    left join private.tgg_one_final_activation_queue q using(item_key)
    where q.item_key is null
       or (e.should_be_complete and q.status<>'complete')
       or (not e.should_be_complete and q.status='complete')
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'key',item_key,
    'should_be_complete',should_be_complete,
    'queue_status',queue_status,
    'last_checked_at',last_checked_at
  ) order by item_key),'[]'::jsonb)
  into v_mismatches
  from mismatches;

  return jsonb_build_object(
    'ok',jsonb_array_length(v_mismatches)=0,
    'version','ACTIVATION-CONSISTENCY-ONE-FINAL-1.2',
    'checked_items',11,
    'mismatch_count',jsonb_array_length(v_mismatches),
    'mismatches',v_mismatches,
    'source_truth',jsonb_build_object(
      'blogger_maintenance_oauth',v_blogger_complete,
      'custom_auth_smtp',v_custom_smtp_complete,
      'distribution_master_assignment',v_dist_master_complete,
      'distribution_legal_metadata',v_dist_legal_complete,
      'distribution_provider',v_dist_provider_complete,
      'membership_tier',v_membership_complete,
      'stripe_webhook_signing_secret',v_stripe_webhook_complete,
      'sfu_turn_provider',v_broadcast_complete,
      'second_call_user',v_calls_complete,
      'supabase_leaked_password_protection',v_auth_hardening_complete,
      'edge_physical_cleanup',v_edge_cleanup_complete
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000009] function private.tgg_activation_state_history_owner(p_limit integer)
CREATE OR REPLACE FUNCTION private.tgg_activation_state_history_owner(p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
  v_limit integer:=greatest(1,least(coalesce(p_limit,25),100));
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','ACTIVATION-HISTORY-ONE-FINAL-1.0',
    'items',coalesce((
      select jsonb_agg(jsonb_build_object(
        'item_key',h.item_key,
        'old_status',h.old_status,
        'new_status',h.new_status,
        'changed_at',h.changed_at
      ) order by h.changed_at desc,h.id desc)
      from (
        select *
        from private.tgg_activation_state_history
        order by changed_at desc,id desc
        limit v_limit
      ) h
    ),'[]'::jsonb),
    'generated_at',now()
  );
end
$function$


