-- [40000000011] function private.tgg_admin_review_audiobook(p_audiobook_id uuid, p_action text, p_note text)
CREATE OR REPLACE FUNCTION private.tgg_admin_review_audiobook(p_audiobook_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_book public.tgg_audiobooks;
      v_owner uuid;
      v_status text;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
      if not exists(select 1 from public.profiles p where p.id=v_uid and p.role='admin') then
        raise exception 'ADMIN_REQUIRED';
      end if;

      select * into v_book
      from public.tgg_audiobooks
      where id=p_audiobook_id
      for update;

      if v_book.id is null then raise exception 'AUDIOBOOK_NOT_FOUND'; end if;
      if v_book.status<>'pending' then raise exception 'AUDIOBOOK_NOT_PENDING'; end if;
      if p_action not in ('approve','request_changes','reject') then raise exception 'INVALID_ACTION'; end if;
      if p_action in ('request_changes','reject')
        and nullif(btrim(coalesce(p_note,'')),'') is null then
        raise exception 'NOTE_REQUIRED';
      end if;

      v_status:=case
        when p_action='approve' then 'published'
        when p_action='request_changes' then 'changes_requested'
        else 'rejected'
      end;

      update public.tgg_audiobooks
      set status=v_status,
          visibility=case when v_status='published' then 'public' else 'private' end,
          admin_note=nullif(btrim(coalesce(p_note,'')),''),
          published_at=case when v_status='published' then now() else null end,
          updated_at=now()
      where id=p_audiobook_id;

      select a.user_id into v_owner
      from public.artists a
      where a.id=v_book.artist_id;

      if v_owner is not null then
        insert into public.notifications(
          recipient_id,actor_id,notification_type,entity_type,entity_id,title,body
        )
        values(
          v_owner,v_uid,'audiobook_review','audiobook',p_audiobook_id,
          case
            when v_status='published' then 'Audiobook approved'
            when v_status='changes_requested' then 'Changes requested on your audiobook'
            else 'Audiobook rejected'
          end,
          coalesce(nullif(btrim(coalesce(p_note,'')),''),'Your audiobook submission was reviewed.')
        );
      end if;

      return jsonb_build_object(
        'ok',true,
        'audiobook_id',p_audiobook_id,
        'status',v_status,
        'reviewed_by',v_uid
      );
    end;
    $function$


-- [40000000012] function private.tgg_admin_review_merch(p_product_id uuid, p_action text, p_note text)
CREATE OR REPLACE FUNCTION private.tgg_admin_review_merch(p_product_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text;
  v_creator uuid;
  v_new text;
  v_link text;
  v_native_ready boolean:=false;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;

  if not exists (
    select 1
    from public.profiles
    where id=auth.uid()
      and role='admin'
  ) then
    raise exception 'ADMIN_REQUIRED';
  end if;

  select status,creator_id,stripe_payment_link_url
  into v_status,v_creator,v_link
  from public.merch_products
  where id=p_product_id
  for update;

  if v_status is null then raise exception 'MERCH_NOT_FOUND'; end if;
  if p_action not in ('approve','request_changes','reject') then
    raise exception 'INVALID_ACTION';
  end if;
  if v_status<>'pending' then raise exception 'INVALID_STATUS'; end if;

  if p_action='approve' then
    select coalesce(enabled,false)
      and mode='production'
      and coalesce(endpoint_configured,false)
    into v_native_ready
    from public.tgg_provider_runtime_config
    where provider_key='stripe'
    limit 1;

    if not coalesce(v_native_ready,false)
       and nullif(btrim(coalesce(v_link,'')),'') is null
    then
      raise exception 'CHECKOUT_PATH_REQUIRED'
        using detail='Native Stripe checkout is unavailable. Add a Stripe Payment Link before approval.';
    end if;

    v_new='published';
  elsif p_action='request_changes' then
    v_new='changes_requested';
  else
    v_new='rejected';
  end if;

  if p_action in ('request_changes','reject')
     and nullif(trim(coalesce(p_note,'')),'') is null
  then
    raise exception 'NOTE_REQUIRED';
  end if;

  update public.merch_products
  set status=v_new,
      admin_note=nullif(trim(coalesce(p_note,'')),''),
      published_at=case when v_new='published' then now() else published_at end,
      updated_at=now()
  where id=p_product_id;

  insert into public.notifications(
    recipient_id,actor_id,notification_type,entity_type,entity_id,title,body
  )
  values(
    (select user_id from public.artists where id=v_creator),
    auth.uid(),
    'merch_review',
    'merch_product',
    p_product_id,
    case
      when v_new='published' then 'Merch approved'
      when v_new='changes_requested' then 'Changes requested'
      else 'Merch rejected'
    end,
    coalesce(nullif(trim(p_note),''),'Your merchandise submission was reviewed.')
  );

  return jsonb_build_object(
    'ok',true,
    'product_id',p_product_id,
    'previous_status',v_status,
    'status',v_new,
    'reviewed_by',auth.uid()
  );
end
$function$


-- [40000000013] function private.tgg_admin_review_mixtape(p_mixtape_id uuid, p_action text, p_note text)
CREATE OR REPLACE FUNCTION private.tgg_admin_review_mixtape(p_mixtape_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role public.user_role;
  v_mixtape public.mixtapes%rowtype;
  v_artist_user_id uuid;
  v_track_count bigint;
  v_protected_count bigint;
  v_new_status public.mixtape_status;
  v_note text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;

  select p.role into v_role
  from public.profiles p
  where p.id = auth.uid();

  if v_role is distinct from 'admin'::public.user_role then
    raise exception 'ADMIN_REQUIRED';
  end if;

  if p_action not in ('approve','request_changes','reject') then
    raise exception 'INVALID_ACTION';
  end if;

  select * into v_mixtape
  from public.mixtapes
  where id = p_mixtape_id
  for update;

  if not found then raise exception 'MIXTAPE_NOT_FOUND'; end if;

  if p_action='approve'
     and v_mixtape.status <> 'pending'::public.mixtape_status
  then
    raise exception 'ONLY_PENDING_RELEASES_CAN_BE_APPROVED';
  end if;

  select a.user_id into v_artist_user_id
  from public.artists a
  where a.id=v_mixtape.artist_id;

  select count(*)::bigint,
         count(*) filter (
           where nullif(trim(t.audio_path),'') is not null
         )::bigint
    into v_track_count,v_protected_count
  from public.tracks t
  where t.mixtape_id=v_mixtape.id;

  if p_action='approve' then
    if v_track_count < 1 then raise exception 'APPROVAL_BLOCKED_NO_TRACKS'; end if;
    if v_protected_count <> v_track_count then raise exception 'APPROVAL_BLOCKED_UNPROTECTED_TRACK'; end if;
    v_new_status := 'published'::public.mixtape_status;
    v_note := nullif(trim(coalesce(p_note,'')),'');
    update public.mixtapes
    set status=v_new_status,
        release_date=coalesce(release_date,now()),
        admin_note=v_note
    where id=v_mixtape.id;
  elsif p_action='request_changes' then
    v_new_status := 'changes_requested'::public.mixtape_status;
    v_note := nullif(trim(coalesce(p_note,'')),'');
    if v_note is null then raise exception 'NOTE_REQUIRED_FOR_CHANGES'; end if;
    update public.mixtapes
    set status=v_new_status,admin_note=v_note
    where id=v_mixtape.id;
  else
    v_new_status := 'rejected'::public.mixtape_status;
    v_note := nullif(trim(coalesce(p_note,'')),'');
    if v_note is null then raise exception 'NOTE_REQUIRED_FOR_REJECTION'; end if;
    update public.mixtapes
    set status=v_new_status,admin_note=v_note
    where id=v_mixtape.id;
  end if;

  if v_artist_user_id is not null then
    insert into public.notifications(
      recipient_id,actor_id,notification_type,entity_type,entity_id,title,body
    )
    values(
      v_artist_user_id,
      auth.uid(),
      'mixtape_review',
      'mixtape',
      v_mixtape.id,
      case v_new_status
        when 'published'::public.mixtape_status then 'Mixtape approved'
        when 'changes_requested'::public.mixtape_status then 'Changes requested on your mixtape'
        else 'Mixtape submission rejected'
      end,
      case v_new_status
        when 'published'::public.mixtape_status
          then 'Your mixtape "' || v_mixtape.title || '" is now published.'
        when 'changes_requested'::public.mixtape_status
          then 'Your mixtape "' || v_mixtape.title || '" needs changes. ' || coalesce(v_note,'')
        else 'Your mixtape "' || v_mixtape.title || '" was rejected. ' || coalesce(v_note,'')
      end
    );
  end if;

  return jsonb_build_object(
    'ok',true,
    'mixtape_id',v_mixtape.id,
    'previous_status',v_mixtape.status,
    'status',v_new_status,
    'track_count',v_track_count,
    'protected_audio_count',v_protected_count,
    'reviewed_by',auth.uid()
  );
end
$function$


-- [40000000014] function private.tgg_admin_review_promotion(p_campaign_id uuid, p_action text, p_note text)
CREATE OR REPLACE FUNCTION private.tgg_admin_review_promotion(p_campaign_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_admin uuid;
  v_creator_artist_id uuid;
  v_creator_user_id uuid;
  v_old text;
  v_new text;
begin
  v_admin:=auth.uid();
  if v_admin is null then raise exception 'AUTH_REQUIRED'; end if;

  if not exists (
    select 1 from public.profiles
    where id=v_admin and role='admin'
  ) then raise exception 'ADMIN_REQUIRED'; end if;

  select creator_id,status
    into v_creator_artist_id,v_old
  from public.promotion_campaigns
  where id=p_campaign_id
  for update;

  if not found then raise exception 'CAMPAIGN_NOT_FOUND'; end if;
  if v_old <> 'pending' then raise exception 'INVALID_STATUS'; end if;

  select a.user_id into v_creator_user_id
  from public.artists a
  where a.id=v_creator_artist_id;

  if p_action='approve' then
    v_new='approved';
  elsif p_action='reject' then
    if nullif(trim(p_note),'') is null then raise exception 'NOTE_REQUIRED'; end if;
    v_new='rejected';
  elsif p_action='request_changes' then
    if nullif(trim(p_note),'') is null then raise exception 'NOTE_REQUIRED'; end if;
    v_new='draft';
  else
    raise exception 'INVALID_ACTION';
  end if;

  update public.promotion_campaigns
  set status=v_new,
      admin_note=case when p_action='approve' then null else trim(p_note) end,
      updated_at=now()
  where id=p_campaign_id;

  if v_creator_user_id is not null then
    insert into public.notifications(
      recipient_id,actor_id,notification_type,entity_type,entity_id,title,body
    )
    values(
      v_creator_user_id,
      v_admin,
      'promotion_review',
      'promotion_campaign',
      p_campaign_id,
      'Promotion review update',
      'Your promotion campaign was reviewed: ' || v_new ||
      case
        when nullif(trim(p_note),'') is not null then ' — ' || trim(p_note)
        else ''
      end
    );
  end if;

  return jsonb_build_object(
    'ok',true,'campaign_id',p_campaign_id,'status',v_new,'reviewed_by',v_admin
  );
end
$function$


-- [40000000015] function private.tgg_admin_review_video(p_video_id uuid, p_action text, p_note text)
CREATE OR REPLACE FUNCTION private.tgg_admin_review_video(p_video_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text;
  v_artist_id uuid;
  v_owner_user_id uuid;
  v_new_status text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;

  if not exists (
    select 1 from public.profiles p
    where p.id=auth.uid() and p.role='admin'
  ) then raise exception 'ADMIN_REQUIRED'; end if;

  select v.status,v.artist_id
    into v_status,v_artist_id
  from public.videos v
  where v.id=p_video_id
  for update;

  if v_status is null then raise exception 'VIDEO_NOT_FOUND'; end if;
  if v_status <> 'pending' then raise exception 'VIDEO_NOT_PENDING'; end if;
  if p_action not in ('approve','request_changes','reject') then raise exception 'INVALID_ACTION'; end if;
  if p_action in ('request_changes','reject')
     and nullif(trim(coalesce(p_note,'')),'') is null
  then raise exception 'NOTE_REQUIRED'; end if;

  select a.user_id into v_owner_user_id
  from public.artists a
  where a.id=v_artist_id;

  v_new_status :=
    case
      when p_action='approve' then 'published'
      when p_action='request_changes' then 'changes_requested'
      else 'rejected'
    end;

  update public.videos
  set status=v_new_status,
      visibility=case when v_new_status='published' then 'public' else visibility end,
      release_date=case when v_new_status='published' then coalesce(release_date,current_date) else release_date end,
      admin_note=nullif(trim(coalesce(p_note,'')),''),
      updated_at=now()
  where id=p_video_id;

  if v_owner_user_id is not null then
    insert into public.media_assets(
      id,owner_id,media_type,title,description,source_url,status,visibility,metadata,updated_at,published_at
    )
    select
      v.id,
      v_owner_user_id,
      'video',
      v.title,
      v.description,
      nullif(v.video_url,''),
      case when v_new_status='published' then 'published' else 'draft' end,
      case when v_new_status='published' then 'public' else v.visibility end,
      jsonb_build_object('source','videos','video_id',v.id::text),
      now(),
      case when v_new_status='published' then now() else null end
    from public.videos v
    where v.id=p_video_id
    on conflict (id) do update
    set owner_id=excluded.owner_id,
        title=excluded.title,
        description=excluded.description,
        source_url=excluded.source_url,
        status=excluded.status,
        visibility=excluded.visibility,
        updated_at=now(),
        published_at=excluded.published_at;

    insert into public.notifications(
      recipient_id,actor_id,notification_type,entity_type,entity_id,title,body
    )
    values(
      v_owner_user_id,
      auth.uid(),
      'video_review',
      'video',
      p_video_id,
      case
        when v_new_status='published' then 'Video approved'
        when v_new_status='changes_requested' then 'Changes requested on your video'
        else 'Video rejected'
      end,
      coalesce(nullif(trim(p_note),''),'Your video submission was reviewed.')
    );
  end if;

  return jsonb_build_object(
    'ok',true,'video_id',p_video_id,'status',v_new_status,'reviewed_by',auth.uid()
  );
end
$function$


-- [40000000016] function private.tgg_advance_npc_schedules()
CREATE OR REPLACE FUNCTION private.tgg_advance_npc_schedules()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare r record; n integer:=0; v_min integer; v_group text;
begin
  v_min := extract(hour from now() at time zone 'utc')::integer*60
         + extract(minute from now() at time zone 'utc')::integer;
  v_group := case when extract(isodow from now() at time zone 'utc') between 1 and 5 then 'weekday' else 'weekend' end;

  for r in
    select distinct on (s.npc_key)
      s.npc_key,s.location_key,s.activity_key,s.end_minute
    from public.tgg_world_npc_schedules s
    where s.enabled=true
      and s.start_minute <= v_min and s.end_minute > v_min
      and s.day_group in (v_group,'day','night')
    order by s.npc_key,s.priority desc,s.start_minute desc
  loop
    insert into public.tgg_world_npc_runtime_state(npc_key,location_key,activity_key,mood,social_state,next_transition_at,updated_at)
    values(r.npc_key,r.location_key,r.activity_key,'neutral','{}'::jsonb,
           date_trunc('day',now() at time zone 'utc') + make_interval(mins=>r.end_minute),
           now())
    on conflict(npc_key) do update
      set location_key=excluded.location_key,
          activity_key=excluded.activity_key,
          next_transition_at=excluded.next_transition_at,
          updated_at=now();
    n:=n+1;
  end loop;
  perform private.tgg_worker_mark('npc-schedule','ok',jsonb_build_object('updated',n));
  return n;
exception when others then
  perform private.tgg_worker_mark('npc-schedule','error',jsonb_build_object('error',sqlerrm));
  raise;
end;
$function$


-- [40000000017] function private.tgg_apply_progression_event(p_character_id uuid, p_event_type text, p_source_key text, p_payload jsonb)
CREATE OR REPLACE FUNCTION private.tgg_apply_progression_event(p_character_id uuid, p_event_type text, p_source_key text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_event_id uuid;
  v_effects jsonb := '{}'::jsonb;
  v_xp integer := greatest(coalesce((p_payload->>'career_xp')::integer,0),0);
  v_rep integer := coalesce((p_payload->>'reputation')::integer,0);
  v_season_xp integer := greatest(coalesce((p_payload->>'season_xp')::integer,0),0);
  v_influence integer := greatest(coalesce((p_payload->>'influence')::integer,0),0);
  v_npc text := p_payload->>'npc_key';
  v_ladder text := p_payload->>'ladder_key';
  v_ladder_points integer := greatest(coalesce((p_payload->>'ladder_points')::integer,0),0);
  v_faction text := p_payload->>'faction_key';
  v_faction_delta integer := coalesce((p_payload->>'faction_standing')::integer,0);
  v_district text := p_payload->>'district_key';
  v_district_rep integer := coalesce((p_payload->>'district_reputation')::integer,0);
  v_crew_id uuid;
  v_crew_xp integer := greatest(coalesce((p_payload->>'crew_xp')::integer,0),0);
  v_business_id uuid;
  v_business_xp integer := greatest(coalesce((p_payload->>'business_xp')::integer,0),0);
  v_career text;
  v_mod jsonb:='{}'::jsonb;
  v_xp_multiplier numeric:=1;
  v_business_multiplier numeric:=1;
  v_season_multiplier numeric:=1;
  v_career_cap integer:=10;
  v_career_xp_per_level integer:=100;
begin
  if p_event_type not in (
    'contract_completed','gig_completed','job_completed','tournament_completed',
    'dialogue_choice','dynamic_event_completed','business_operation_completed',
    'crew_contract_completed','challenge_completed','story_chapter_completed',
    'creative_mission_completed','career_mission_completed'
  ) then raise exception 'unsupported progression event type'; end if;

  if not exists(select 1 from public.world_characters wc where wc.id=p_character_id) then
    raise exception 'character not found';
  end if;

  select active_career into v_career from public.world_characters where id=p_character_id;

  if v_career is not null then
    select coalesce(level_cap,10),greatest(coalesce(xp_per_level,100),1)
    into v_career_cap,v_career_xp_per_level
    from public.tgg_world_career_tracks
    where career_key=v_career and enabled=true;
    v_career_cap:=coalesce(v_career_cap,10);
    v_career_xp_per_level:=coalesce(v_career_xp_per_level,100);
  end if;

  select greatest(coalesce((value->>'value')::numeric,1),0)
  into v_season_multiplier
  from public.tgg_world_economy_config
  where config_key='season_xp_multiplier';
  v_season_multiplier:=coalesce(v_season_multiplier,1);

  v_mod:=private.tgg_world_effective_modifiers(p_character_id);
  v_xp_multiplier:=greatest(coalesce((v_mod->>'career_xp_multiplier')::numeric,1),1);
  v_business_multiplier:=greatest(coalesce((v_mod->>'business_xp_multiplier')::numeric,1),1);
  v_xp:=greatest(round(v_xp*v_xp_multiplier)::integer,0);
  v_business_xp:=greatest(round(v_business_xp*v_business_multiplier)::integer,0);
  v_season_xp:=greatest(round(v_season_xp*v_season_multiplier)::integer,0);

  insert into public.tgg_world_progression_event_log(character_id,event_type,source_key,payload)
  values(p_character_id,p_event_type,p_source_key,coalesce(p_payload,'{}'::jsonb))
  returning id into v_event_id;

  if v_xp>0 and v_career is not null then
    insert into public.world_character_careers(character_id,career_key,career_level,career_xp,unlocked,metadata,updated_at)
    values(p_character_id,v_career,1,v_xp,true,'{}'::jsonb,now())
    on conflict(character_id,career_key) do update
    set career_xp=public.world_character_careers.career_xp+excluded.career_xp,
        career_level=least(v_career_cap,greatest(public.world_character_careers.career_level,1+((public.world_character_careers.career_xp+excluded.career_xp)/v_career_xp_per_level)::integer)),
        updated_at=now();
  end if;

  if v_rep<>0 and v_career is not null then
    insert into public.tgg_world_career_reputation(character_id,career_key,reputation,tier,metadata,updated_at)
    values(p_character_id,v_career,greatest(v_rep,0),1,'{}'::jsonb,now())
    on conflict(character_id,career_key) do update
    set reputation=greatest(0,public.tgg_world_career_reputation.reputation+v_rep),
        tier=greatest(1,1+greatest(0,public.tgg_world_career_reputation.reputation+v_rep)/25),
        updated_at=now();
  end if;

  if v_season_xp>0 then
    insert into public.tgg_world_character_season_progress(character_id,season_key,season_level,season_xp,unlocked_rewards,updated_at)
    select p_character_id,s.season_key,1,v_season_xp,'[]'::jsonb,now()
    from public.tgg_world_seasons s
    where s.enabled=true and (s.starts_at is null or s.starts_at<=now()) and (s.ends_at is null or s.ends_at>=now())
    order by s.starts_at desc nulls last limit 1
    on conflict(character_id,season_key) do update
    set season_xp=public.tgg_world_character_season_progress.season_xp+excluded.season_xp,
        updated_at=now();

    update public.tgg_world_character_season_progress sp
    set season_level=coalesce((
      select max(r.reward_level)
      from public.tgg_world_season_rewards r
      where r.season_key=sp.season_key
        and r.required_xp<=sp.season_xp
    ),1),
    updated_at=now()
    where sp.character_id=p_character_id
      and exists(
        select 1 from public.tgg_world_seasons s
        where s.season_key=sp.season_key
          and s.enabled=true
          and (s.starts_at is null or s.starts_at<=now())
          and (s.ends_at is null or s.ends_at>=now())
      );
  end if;

  if v_influence>0 then
    insert into public.tgg_world_character_influence(character_id,career_influence,updated_at)
    values(p_character_id,v_influence,now())
    on conflict(character_id) do update
    set career_influence=public.tgg_world_character_influence.career_influence+v_influence,
        influence_tier=case
          when public.tgg_world_character_influence.total_influence+v_influence>=1000 then 'icon'
          when public.tgg_world_character_influence.total_influence+v_influence>=500 then 'citywide'
          when public.tgg_world_character_influence.total_influence+v_influence>=200 then 'district'
          else 'local'
        end,updated_at=now();
  end if;

  if v_faction is not null and v_faction_delta<>0 then
    insert into public.tgg_world_character_factions(character_id,faction_key,standing,rank_level,loyalty,status,updated_at)
    values(p_character_id,v_faction,greatest(-100,least(100,v_faction_delta)),1,0,'neutral',now())
    on conflict(character_id,faction_key) do update
    set standing=greatest(-100,least(100,public.tgg_world_character_factions.standing+v_faction_delta)),
        status=case
          when greatest(-100,least(100,public.tgg_world_character_factions.standing+v_faction_delta))>=60 then 'favored'
          when greatest(-100,least(100,public.tgg_world_character_factions.standing+v_faction_delta))<=-40 then 'hostile'
          when public.tgg_world_character_factions.status='neutral' then 'neutral'
          else 'member'
        end,updated_at=now();
  end if;

  if v_district is not null and v_district_rep<>0 then
    insert into public.tgg_world_character_district_reputation(character_id,district_key,reputation,tier,notoriety,metadata,updated_at)
    values(p_character_id,v_district,greatest(v_district_rep,0),1,0,'{}'::jsonb,now())
    on conflict(character_id,district_key) do update
    set reputation=greatest(0,public.tgg_world_character_district_reputation.reputation+v_district_rep),
        tier=greatest(1,1+greatest(0,public.tgg_world_character_district_reputation.reputation+v_district_rep)/25),
        updated_at=now();
  end if;

  if p_payload ? 'crew_id' and v_crew_xp>0 then
    v_crew_id:=(p_payload->>'crew_id')::uuid;
    if exists(select 1 from public.tgg_world_crew_members m where m.crew_id=v_crew_id and m.character_id=p_character_id and m.left_at is null) then
      insert into public.tgg_world_crew_progression(crew_id,crew_xp,rank_level,reputation,unlocks,updated_at)
      values(v_crew_id,v_crew_xp,1,0,'{}'::jsonb,now())
      on conflict(crew_id) do update
      set crew_xp=public.tgg_world_crew_progression.crew_xp+v_crew_xp,
          rank_level=greatest(public.tgg_world_crew_progression.rank_level,
            coalesce((select max(r.rank_level) from public.tgg_world_crew_ranks r
                      where r.required_crew_xp<=public.tgg_world_crew_progression.crew_xp+v_crew_xp),1)),
          updated_at=now();
    end if;
  end if;

  if p_payload ? 'business_id' and v_business_xp>0 then
    v_business_id:=(p_payload->>'business_id')::uuid;
    update public.tgg_world_character_businesses b
    set business_xp=b.business_xp+v_business_xp,
        business_level=least(
          coalesce((
            select greatest(coalesce((bt.progression->>'levels')::integer,5),1)
            from public.tgg_world_business_types bt
            where bt.business_type_key=b.business_type_key
          ),5),
          greatest(b.business_level,1+((b.business_xp+v_business_xp)/250))
        ),
        updated_at=now()
    where b.id=v_business_id and b.character_id=p_character_id;
  end if;

  if v_npc is not null and exists(select 1 from public.tgg_world_npc_profiles n where n.npc_key=v_npc) then
    insert into public.tgg_world_npc_memory_events(character_id,npc_key,memory_type,memory_key,weight,sentiment,payload)
    values(p_character_id,v_npc,p_event_type,coalesce(p_source_key,p_event_type),
      greatest(coalesce((p_payload->>'memory_weight')::integer,1),1),
      greatest(-100,least(100,coalesce((p_payload->>'sentiment')::integer,0))),p_payload);
  end if;

  if v_ladder is not null and v_ladder_points>0
     and exists(select 1 from public.tgg_world_tournament_ladders l where l.ladder_key=v_ladder and l.enabled=true) then
    insert into public.tgg_world_character_ladder_state(character_id,ladder_key,ladder_points,division_key,wins,losses,streak,updated_at)
    values(
      p_character_id,
      v_ladder,
      v_ladder_points,
      coalesce((
        select d->>'key'
        from public.tgg_world_tournament_ladders l
        cross join lateral jsonb_array_elements(l.divisions) d
        where l.ladder_key=v_ladder and l.enabled=true
          and (d->>'min_points')::integer<=v_ladder_points
        order by (d->>'min_points')::integer desc
        limit 1
      ),'rookie'),
      case when coalesce((p_payload->>'won')::boolean,false) then 1 else 0 end,
      case when coalesce((p_payload->>'won')::boolean,false) then 0 else 1 end,
      case when coalesce((p_payload->>'won')::boolean,false) then 1 else -1 end,
      now()
    )
    on conflict(character_id,ladder_key) do update
    set ladder_points=public.tgg_world_character_ladder_state.ladder_points+excluded.ladder_points,
        division_key=coalesce((
          select d->>'key'
          from public.tgg_world_tournament_ladders l
          cross join lateral jsonb_array_elements(l.divisions) d
          where l.ladder_key=v_ladder and l.enabled=true
            and (d->>'min_points')::integer<=public.tgg_world_character_ladder_state.ladder_points+excluded.ladder_points
          order by (d->>'min_points')::integer desc
          limit 1
        ),public.tgg_world_character_ladder_state.division_key),
        wins=public.tgg_world_character_ladder_state.wins+excluded.wins,
        losses=public.tgg_world_character_ladder_state.losses+excluded.losses,
        streak=case when excluded.wins=1 then greatest(1,public.tgg_world_character_ladder_state.streak+1)
                    else least(-1,public.tgg_world_character_ladder_state.streak-1) end,
        updated_at=now();
  end if;

  if p_event_type='contract_completed' and p_source_key is not null then
    update public.tgg_world_character_contracts set status='completed',completed_at=now(),updated_at=now()
    where character_id=p_character_id and contract_key=p_source_key and status='active';
  elsif p_event_type='gig_completed' and p_source_key is not null then
    update public.tgg_world_character_gigs set status='completed',completed_at=now(),updated_at=now()
    where character_id=p_character_id and gig_key=p_source_key and status='accepted';
  elsif p_event_type='challenge_completed' and p_source_key is not null then
    update public.tgg_world_character_challenges set status='completed',completed_at=now(),updated_at=now()
    where character_id=p_character_id and challenge_key=p_source_key and status='active';
  elsif p_event_type='story_chapter_completed' and p_source_key is not null then
    update public.tgg_world_character_story_state
    set flags=flags||jsonb_build_object('completed_chapter',p_source_key),updated_at=now()
    where character_id=p_character_id and status='active';
  end if;

  v_effects:=private.tgg_recompute_progression(p_character_id)
    || jsonb_build_object(
      'effective_modifiers',v_mod,
      'applied_career_xp',v_xp,
      'applied_business_xp',v_business_xp,
      'career_xp_multiplier',v_xp_multiplier,
      'business_xp_multiplier',v_business_multiplier,
      'season_xp_multiplier',v_season_multiplier,
      'applied_season_xp',v_season_xp
    );

  update public.tgg_world_progression_event_log
  set processed_effects=v_effects
  where id=v_event_id;

  return v_event_id;
end;
$function$


-- [40000000018] function private.tgg_apply_provider_staging_to_activation_queue()
CREATE OR REPLACE FUNCTION private.tgg_apply_provider_staging_to_activation_queue()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_dist record;
  v_broadcast record;
  v_count integer:=0;
  v_updates integer:=0;
  v_dist_secret boolean:=false;
  v_broadcast_secret boolean:=false;
  v_creator_os_version integer:=0;
begin
  select coalesce(nullif(m#>>'{runtime,edge_version}','')::integer,0)
  into v_creator_os_version
  from (select public.tgg_v5000_production_manifest() as m) q;

  if v_creator_os_version<=0 then
    v_creator_os_version:=coalesce((
      select (config->>'creator_os_runtime_version')::integer
      from public.tgg_master_shared_settings
      where setting_key='runtime_manifest' and is_published=true
      limit 1
    ),0);
  end if;

  select exists(
    select 1
    from private.tgg_provider_secret_registry
    where provider_key='distribution.provider'
      and status in ('stored','verified','runtime_verified')
  ) into v_dist_secret;

  select exists(
    select 1
    from private.tgg_provider_secret_registry
    where provider_key='broadcast.sfu_turn'
      and status in ('stored','verified','runtime_verified')
  ) into v_broadcast_secret;

  select * into v_dist
  from private.tgg_provider_activation_staging
  where provider_key='distribution.provider';

  if found then
    update private.tgg_one_final_activation_queue q
    set
      status=case
        when q.status='complete' then 'complete'
        when v_dist.status='verified' and v_dist_secret then 'ready'
        when v_dist.status in ('staged','verified') then 'external_action'
        else q.status
      end,
      next_action=case
        when q.status='complete' then null
        when v_dist.status='verified' and not v_dist_secret then
          'Open Creator OS → Finish Setup, enter the real DSP production credential, save it to Vault, and complete authenticated provider verification.'
        when v_dist.status='verified' then
          'DSP credential is stored. Complete authenticated provider verification before enabling production delivery.'
        when v_dist.status='staged' then
          'DSP endpoint is staged. Open Creator OS → Finish Setup, enter the real production credential, save it to Vault, and run verification.'
        else q.next_action
      end,
      evidence=coalesce(q.evidence,'{}'::jsonb)||jsonb_build_object(
        'provider_key','distribution.provider',
        'endpoint_staged',v_dist.endpoint_url is not null,
        'endpoint_reachability_verified',v_dist.status='verified',
        'runtime_endpoint_configured',v_dist.endpoint_url is not null,
        'endpoint_url',v_dist.endpoint_url,
        'secret_reference','tgg_distribution_provider_secret',
        'staging_status',v_dist.status,
        'secret_value_stored',v_dist_secret,
        'credentials_verified',false,
        'credential_only_remaining',v_dist.status='verified' and not v_dist_secret,
        'provider_still_requires_real_external_endpoint',false,
        'external_provider_still_required',false,
        'external_provider_credentials_still_required',not v_dist_secret,
        'creator_os_version',v_creator_os_version,
        'runtime_bookkeeping_refreshed_at',now()
      ),
      last_checked_at=now()
    where item_key='distribution_provider';

    get diagnostics v_count=row_count;
    v_updates:=v_updates+v_count;
  end if;

  select * into v_broadcast
  from private.tgg_provider_activation_staging
  where provider_key='broadcast.sfu_turn';

  if found then
    update private.tgg_one_final_activation_queue q
    set
      status=case
        when q.status='complete' then 'complete'
        when v_broadcast.status='verified' and v_broadcast_secret then 'ready'
        when v_broadcast.status in ('staged','verified') then 'external_action'
        else q.status
      end,
      next_action=case
        when q.status='complete' then null
        when v_broadcast.status='verified' and not v_broadcast_secret then
          'Open Creator OS → Finish Setup, enter the real LiveKit credentials, save them to Vault, and complete authenticated SFU/TURN verification.'
        when v_broadcast.status='verified' then
          'LiveKit credential is stored. Complete authenticated SFU/TURN verification before enabling production transport.'
        when v_broadcast.status='staged' then
          'LiveKit endpoint is staged. Open Creator OS → Finish Setup, enter the real production credentials, save them to Vault, and run verification.'
        else q.next_action
      end,
      evidence=coalesce(q.evidence,'{}'::jsonb)||jsonb_build_object(
        'provider_key','broadcast.sfu_turn',
        'endpoint_staged',v_broadcast.endpoint_url is not null,
        'endpoint_reachability_verified',v_broadcast.status='verified',
        'runtime_endpoint_configured',v_broadcast.endpoint_url is not null,
        'endpoint_url',v_broadcast.endpoint_url,
        'secret_reference','tgg_broadcast_provider_secret',
        'staging_status',v_broadcast.status,
        'secret_value_stored',v_broadcast_secret,
        'credentials_verified',false,
        'credential_only_remaining',v_broadcast.status='verified' and not v_broadcast_secret,
        'provider_still_requires_real_external_endpoint',false,
        'external_provider_still_required',false,
        'external_provider_credentials_still_required',not v_broadcast_secret,
        'same_origin_secret_bridge_ready',true,
        'creator_os_version',v_creator_os_version,
        'runtime_bookkeeping_refreshed_at',now()
      ),
      last_checked_at=now()
    where item_key='sfu_turn_provider';

    get diagnostics v_count=row_count;
    v_updates:=v_updates+v_count;
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','PROVIDER-ACTIVATION-QUEUE-ONE-FINAL-1.3',
    'updates',v_updates,
    'creator_os_version',v_creator_os_version,
    'distribution_secret_present',v_dist_secret,
    'broadcast_secret_present',v_broadcast_secret,
    'generated_at',now()
  );
end
$function$


-- [40000000019] function private.tgg_attach_merch_checkout_session(p_request_id uuid, p_checkout_session_id text)
CREATE OR REPLACE FUNCTION private.tgg_attach_merch_checkout_session(p_request_id uuid, p_checkout_session_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.tgg_merch_checkout_reservations;
begin
  if auth.role()<>'service_role' then
    raise exception 'service_role_required';
  end if;

  if nullif(btrim(coalesce(p_checkout_session_id,'')),'') is null then
    raise exception 'checkout_session_required';
  end if;

  update public.tgg_merch_checkout_reservations
  set checkout_session_id=coalesce(checkout_session_id,p_checkout_session_id),
      updated_at=now()
  where request_id=p_request_id
    and status='pending'
  returning * into v;

  if v.id is null then
    raise exception 'reservation_not_pending';
  end if;

  if v.checkout_session_id<>p_checkout_session_id then
    raise exception 'checkout_session_mismatch';
  end if;

  return jsonb_build_object(
    'reservation_id',v.id,
    'checkout_session_id',v.checkout_session_id,
    'status',v.status
  );
end
$function$


-- [40000000020] function private.tgg_authenticated_e2e_reconcile()
CREATE OR REPLACE FUNCTION private.tgg_authenticated_e2e_reconcile()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry boolean:=false;
  v_return boolean:=false;
  v_roundtrip boolean:=false;
  v_actor uuid;
  v_milestone_id uuid;
  v_acceptance jsonb;
begin
  select actor_user_id
  into v_actor
  from private.tgg_veil_audit_ledger
  where allowed=true
    and route_key in ('artist_world','artist_games_tv')
  order by decided_at desc
  limit 1;

  if v_actor is not null then
    select exists(
      select 1
      from private.tgg_veil_audit_ledger
      where actor_user_id=v_actor
        and allowed=true
        and route_key in ('artist_world','artist_games_tv')
    ) into v_entry;

    select exists(
      select 1
      from private.tgg_veil_audit_ledger
      where actor_user_id=v_actor
        and allowed=true
        and route_key='artist_creator_os'
    ) into v_return;
  end if;

  v_roundtrip:=v_entry and v_return;

  select id,acceptance
  into v_milestone_id,v_acceptance
  from public.tgg_build_milestones
  where release_id='433251c2-3ca3-4d95-a535-8b438f0e094c'
    and milestone_key='authenticated-user-e2e'
  limit 1;

  if v_milestone_id is not null then
    update public.tgg_build_milestones
    set acceptance=jsonb_build_array(
      'PASS: real sign-in/session evidence exists — 2 sessions in 24h, 1 refreshed',
      'READY / REAL SESSION PRESENT: Creator OS runtime validates bearer JWT and returns READY bundle after onboarding; direct dashboard-view audit evidence is not recorded',
      'PASS: upload/project evidence — 1 authenticated-owned cover object, 1 authenticated-owned mixtape-audio object, 2 projects owned by recent-session user',
      'PASS: creator action evidence — 5 actions tied to recent-session user, including 1 completed this week',
      case when v_roundtrip
        then 'PASS: portal/return evidence — authenticated VEIL ledger contains a real allowed portal entry and allowed return to Creator OS'
        else 'EVIDENCE-GATED: portal/return — waiting for one real authenticated Matrix/Lewis entry plus return to Creator OS; ledger remains un-fabricated'
      end,
      'CODE-VERIFIED ONLY: live Creator OS signOut uses sb.auth.signOut() then reload; no durable logout audit event exists, so real logout is not falsely claimed',
      'DEFERRED EXTERNAL: LiveKit production credentials',
      'DEFERRED EXTERNAL: real second-device WebRTC validation',
      'DEFERRED EXTERNAL: DSP production credential',
      'DEFERRED EXTERNAL: Supabase leaked-password-protection setting',
      'PROTECTED: CodeSync remains review-only and untouched'
    ),
    status=case when v_roundtrip then 'testing' else 'active' end,
    updated_at=now()
    where id=v_milestone_id;
  end if;

  return jsonb_build_object(
    'ok',true,
    'portal_entry_evidence',v_entry,
    'creator_os_return_evidence',v_return,
    'portal_roundtrip_complete',v_roundtrip,
    'logout_code_verified',true,
    'logout_event_verified',false,
    'milestone_status',case when v_roundtrip then 'testing' else 'active' end,
    'fabricated_evidence',false
  );
end $function$


-- [40000000021] function private.tgg_autobuilder_idea_status_impl(p_idea_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_autobuilder_idea_status_impl(p_idea_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if not private.tgg_is_owner_fresh() then raise exception 'OWNER_REQUIRED' using errcode='42501'; end if;

  perform private.tgg_autobuilder_sync_idea_status();

  return jsonb_build_object(
    'ok',true,
    'ideas',(
      select coalesce(jsonb_agg(jsonb_build_object(
        'idea_id',i.id,'title',i.idea_title,'idea',i.idea_text,'status',i.status,
        'release_id',i.build_release_id,'release_key',r.release_key,
        'release_status',r.status,'created_at',i.created_at,'updated_at',i.updated_at,
        'tasks',(select coalesce(jsonb_agg(jsonb_build_object(
          'task_key',t.task_key,'title',t.title,'status',t.status,'agent_type',t.agent_type,
          'retry_count',t.retry_count,'last_result',t.last_result
        ) order by t.priority),'[]'::jsonb)
          from public.tgg_build_milestones m
          join public.tgg_build_tasks t on t.milestone_id=m.id
          where m.release_id=i.build_release_id)
      ) order by i.created_at desc),'[]'::jsonb)
      from public.tgg_autobuilder_ideas i
      left join public.tgg_build_releases r on r.id=i.build_release_id
      where i.owner_user_id=v_uid and (p_idea_id is null or i.id=p_idea_id)
    ),
    'controller',(select to_jsonb(c) from public.tgg_autobuilder_controller c where id=1),
    'generated_at',now()
  );
end
$function$


-- [40000000022] function private.tgg_autobuilder_submit_idea(p_idea text, p_title text)
CREATE OR REPLACE FUNCTION private.tgg_autobuilder_submit_idea(p_idea text, p_title text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_text text:=btrim(coalesce(p_idea,''));
  v_title text:=nullif(btrim(coalesce(p_title,'')),'');
  v_hash text;
  v_existing public.tgg_autobuilder_ideas;
  v_idea public.tgg_autobuilder_ideas;
  v_project_id uuid;
  v_release_id uuid;
  v_release_key text;
  v_milestone_id uuid;
  v_read uuid; v_plan uuid; v_build uuid; v_test uuid; v_repair uuid; v_stage uuid;
  v_seq integer;
  v_tick jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if not private.tgg_is_owner_fresh() then raise exception 'OWNER_REQUIRED' using errcode='42501'; end if;
  if char_length(v_text)<3 or char_length(v_text)>12000 then
    raise exception 'IDEA_LENGTH_INVALID' using errcode='22023';
  end if;

  v_hash:=md5(lower(regexp_replace(v_text,'\s+',' ','g')));

  select * into v_existing
  from public.tgg_autobuilder_ideas
  where owner_user_id=v_uid and idea_hash=v_hash
  limit 1;

  if v_existing.id is not null then
    return jsonb_build_object(
      'ok',true,'duplicate',true,'idea_id',v_existing.id,'status',v_existing.status,
      'build_release_id',v_existing.build_release_id,'message','This idea is already in the Auto Builder.'
    );
  end if;

  insert into public.tgg_autobuilder_ideas(owner_user_id,idea_title,idea_text,idea_hash,status,metadata)
  values(v_uid,coalesce(v_title,left(v_text,80)),v_text,v_hash,'queued',
    jsonb_build_object('source','creator_os_idea_reader_writer','auto_compile',true))
  returning * into v_idea;

  select id into v_project_id
  from public.tgg_build_projects
  where project_key='tru-go-getta-master'
  limit 1;
  if v_project_id is null then raise exception 'MASTER_BUILD_PROJECT_MISSING'; end if;

  select coalesce(max(sequence_no),1000)+1 into v_seq from public.tgg_build_releases;
  v_release_key:='IDEA-'||upper(substr(replace(v_idea.id::text,'-',''),1,8));

  insert into public.tgg_build_releases(
    project_id,release_key,name,sequence_no,status,target_environment,metadata
  ) values(
    v_project_id,v_release_key,coalesce(v_title,left(v_text,80)),v_seq,'queued','staging',
    jsonb_build_object(
      'idea_id',v_idea.id,'idea_hash',v_hash,'idea_text',v_text,'source','idea_reader_writer',
      'canonical',false,'development_only',true,'development_scope_approved',true,
      'auto_builder_claim_allowed',true,'historical_only',false,'historical_backlog',false,
      'production_promotion_performed',false,'production_deploy_performed',false,
      'production_promotion_requires_approval',true,'read_before_write_required',true,
      'reuse_existing_systems_required',true,'duplicate_work_forbidden',true
    )
  ) returning id into v_release_id;

  insert into public.tgg_build_milestones(
    release_id,milestone_key,name,sequence_no,weight,status,acceptance
  ) values(
    v_release_id,v_release_key||'-PIPELINE','Idea → Read → Plan → Write → Test → Fix → Stage',1,1,'queued',
    jsonb_build_array(
      'Read current live architecture before changing anything',
      'Reuse or extend existing systems instead of duplicating features',
      'Write only safe development/staging changes automatically',
      'Run security, dependency, regression, and drift checks',
      'Repair safe failures automatically',
      'Never auto-promote production or fabricate credentials/legal facts'
    )
  ) returning id into v_milestone_id;

  insert into public.tgg_build_tasks(milestone_id,task_key,title,description,task_type,priority,risk_level,status,agent_type,acceptance,existing_work_state,max_retries)
  values(v_milestone_id,v_release_key||'-READ','Read current system','Read live Creator OS, database schema, routes, existing features, checkpoints, and related code. Identify completed/overlapping work and return a reuse map before any write. Idea: '||v_text,'analysis',10,'low','ready','reader',
    jsonb_build_array('existing work checked','duplicate work identified and skipped','affected surfaces mapped','safe change boundary identified'),'missing',3)
  returning id into v_read;

  insert into public.tgg_build_tasks(milestone_id,task_key,title,description,task_type,priority,risk_level,status,agent_type,acceptance,existing_work_state,max_retries)
  values(v_milestone_id,v_release_key||'-PLAN','Compile idea into implementation plan','Turn the idea and reader output into a concrete implementation plan using the existing architecture. Produce the smallest complete change set and acceptance tests.','design',20,'low','queued','planner',
    jsonb_build_array('plan references reader evidence','existing systems reused','security/RLS requirements included','rollback path defined'),'missing',3)
  returning id into v_plan;

  insert into public.tgg_build_tasks(milestone_id,task_key,title,description,task_type,priority,risk_level,status,agent_type,acceptance,existing_work_state,max_retries)
  values(v_milestone_id,v_release_key||'-WRITE','Build and write the idea','Implement the approved development/staging plan across database, Edge Function, routes, configuration, or content surfaces as applicable. Do not touch production promotion.','build',30,'medium','queued','builder',
    jsonb_build_array('implementation matches plan','no duplicate system created','RLS/security preserved','existing canonical production boundary preserved'),'missing',3)
  returning id into v_build;

  insert into public.tgg_build_tasks(milestone_id,task_key,title,description,task_type,priority,risk_level,status,agent_type,acceptance,existing_work_state,max_retries)
  values(v_milestone_id,v_release_key||'-TEST','Test the new idea','Run applicable SQL/RPC tests, security advisor, dependency health, source-hook verification, regression checks, and production drift verification.','qa',40,'low','queued','qa',
    jsonb_build_array('functional tests pass','security checks pass or intentional info documented','dependency health passes','production drift remains zero'),'missing',3)
  returning id into v_test;

  insert into public.tgg_build_tasks(milestone_id,task_key,title,description,task_type,priority,risk_level,status,agent_type,acceptance,existing_work_state,max_retries)
  values(v_milestone_id,v_release_key||'-FIX','Auto-fix safe failures','Read test failures and repair safe low/medium-risk issues. Reuse existing repair paths. If a fix requires secrets, legal decisions, destructive operations, or production approval, mark blocked instead.','repair',50,'medium','queued','repair',
    jsonb_build_array('safe failures repaired','unsafe/external gates left blocked with exact reason','no production promotion'),'missing',3)
  returning id into v_repair;

  insert into public.tgg_build_tasks(milestone_id,task_key,title,description,task_type,priority,risk_level,status,agent_type,acceptance,existing_work_state,max_retries)
  values(v_milestone_id,v_release_key||'-STAGE','Verify staging-ready result','Perform final staging verification, summarize changes, preserve rollback evidence, and mark the idea complete only when all acceptance evidence passes.','staging',60,'medium','queued','staging',
    jsonb_build_array('staging verification complete','rollback evidence recorded','production untouched','idea outcome summarized'),'missing',3)
  returning id into v_stage;

  insert into public.tgg_build_dependencies(task_id,depends_on_task_id,dependency_type) values
    (v_plan,v_read,'hard'),(v_build,v_plan,'hard'),(v_test,v_build,'hard'),(v_repair,v_test,'hard'),(v_stage,v_repair,'hard');

  update public.tgg_autobuilder_ideas
  set status='compiled',build_release_id=v_release_id,updated_at=now(),
      metadata=metadata||jsonb_build_object('release_key',v_release_key,'pipeline_task_count',6,'compiled_at',now())
  where id=v_idea.id
  returning * into v_idea;

  perform public.tgg_build_refresh_ready_tasks();
  v_tick:=private.tgg_autobuilder_tick();

  return jsonb_build_object(
    'ok',true,'duplicate',false,'idea_id',v_idea.id,'status',v_idea.status,
    'release_id',v_release_id,'release_key',v_release_key,'pipeline_task_count',6,
    'autobuilder_tick',v_tick
  );
end
$function$


-- [40000000023] function private.tgg_autobuilder_sync_idea_status()
CREATE OR REPLACE FUNCTION private.tgg_autobuilder_sync_idea_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_updated integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if not private.tgg_is_owner_fresh() then raise exception 'OWNER_REQUIRED' using errcode='42501'; end if;

  update public.tgg_autobuilder_ideas i
  set status=s.new_status,
      updated_at=case when i.status is distinct from s.new_status then now() else i.updated_at end,
      metadata=i.metadata||jsonb_build_object(
        'task_total',s.task_total,'task_complete',s.task_complete,
        'task_blocked',s.task_blocked,'task_active',s.task_active,'last_sync_at',now()
      )
  from (
    select
      i2.id,
      count(t.id)::integer as task_total,
      count(t.id) filter(where t.status in ('complete','passed','skipped'))::integer as task_complete,
      count(t.id) filter(where t.status='blocked')::integer as task_blocked,
      count(t.id) filter(where t.status in ('ready','designing','building','testing','repairing','staging','running','queued'))::integer as task_active,
      case
        when count(t.id)>0 and count(t.id)=count(t.id) filter(where t.status in ('complete','passed','skipped')) then 'complete'
        when count(t.id) filter(where t.status='blocked')>0
          and count(t.id) filter(where t.status in ('ready','designing','building','testing','repairing','staging','running'))=0 then 'blocked'
        when count(t.id) filter(where t.status in ('ready','designing','building','testing','repairing','staging','running'))>0 then 'building'
        else 'compiled'
      end as new_status
    from public.tgg_autobuilder_ideas i2
    left join public.tgg_build_milestones m on m.release_id=i2.build_release_id
    left join public.tgg_build_tasks t on t.milestone_id=m.id
    where i2.owner_user_id=v_uid and i2.status<>'canceled'
    group by i2.id
  ) s
  where i.id=s.id
    and (i.status is distinct from s.new_status
      or coalesce((i.metadata->>'task_total')::integer,-1)<>s.task_total
      or coalesce((i.metadata->>'task_complete')::integer,-1)<>s.task_complete
      or coalesce((i.metadata->>'task_blocked')::integer,-1)<>s.task_blocked
      or coalesce((i.metadata->>'task_active')::integer,-1)<>s.task_active);

  get diagnostics v_updated=row_count;

  update public.tgg_build_releases r
  set status=case
      when i.status='complete' then 'complete'
      when i.status='blocked' then 'blocked'
      when i.status='building' then 'active'
      else r.status
    end,
    updated_at=case when r.status is distinct from case
      when i.status='complete' then 'complete'
      when i.status='blocked' then 'blocked'
      when i.status='building' then 'active'
      else r.status
    end then now() else r.updated_at end
  from public.tgg_autobuilder_ideas i
  where i.owner_user_id=v_uid and i.build_release_id=r.id;

  return jsonb_build_object('ok',true,'updated',v_updated,'synced_at',now());
end
$function$


-- [40000000024] function private.tgg_autobuilder_tick()
CREATE OR REPLACE FUNCTION private.tgg_autobuilder_tick()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ctrl public.tgg_autobuilder_controller%rowtype;
  v_state jsonb;
  v_gap jsonb;
  v_result jsonb;
  v_ready integer:=0;
  v_running integer:=0;
  v_approval integer:=0;
  v_blocked integer:=0;
  v_unfinished integer:=0;
  v_external integer:=0;
  v_auto_gaps integer:=0;
  v_controller_status text;
begin
  select * into v_ctrl
  from public.tgg_autobuilder_controller
  where id=1
  for update;

  if v_ctrl.id is null then raise exception 'AUTOBUILDER_CONTROLLER_MISSING'; end if;

  if not v_ctrl.enabled then
    update public.tgg_autobuilder_controller set status='paused',updated_at=now() where id=1;
    return jsonb_build_object('ok',true,'status','paused','reason','controller_disabled','checked_at',now());
  end if;

  v_state:=public.tgg_autobuilder_detect_state();
  v_gap:=case when v_ctrl.mode='gap_only_bulk' then private.tgg_gap_only_bulk_state() else '{}'::jsonb end;

  v_ready:=coalesce((v_state->>'ready')::integer,0);
  v_running:=coalesce((v_state->>'running')::integer,0);
  v_approval:=coalesce((v_state->>'approval_required')::integer,0);
  v_blocked:=coalesce((v_state->>'blocked')::integer,0);
  v_unfinished:=coalesce((v_state->>'unfinished')::integer,0);
  v_external:=coalesce((v_gap->>'external_or_human_gaps')::integer,0);
  v_auto_gaps:=coalesce((v_gap->>'auto_fixable_gaps')::integer,0);

  if v_ready>0 then
    v_result:=public.tgg_autobuilder_run_cycle();
  else
    v_controller_status:=case
      when v_running>0 then 'running'
      when v_unfinished=0 and v_auto_gaps=0 then 'complete'
      when v_approval>0 then 'waiting_approval'
      when v_blocked>0 or v_auto_gaps>0 then 'blocked'
      else 'idle'
    end;

    v_result:=jsonb_build_object(
      'status',v_controller_status,
      'state',v_state,
      'gap_only_bulk',v_gap,
      'external_or_human_gaps',v_external,
      'cycle_created',false,
      'duplicate_work_skipped',true,
      'checked_at',now()
    );

    update public.tgg_autobuilder_controller
    set status=v_controller_status,
        last_cycle_at=now(),
        last_cycle_result=v_result,
        updated_at=now()
    where id=1;
  end if;

  insert into public.tgg_operational_recovery_checkpoints(checkpoint_key,state,source,details)
  values(
    'autobuilder_always_on',
    case when coalesce(v_result->>'status','') in ('blocked','waiting_approval') then 'attention' else 'ready' end,
    'private.tgg_autobuilder_tick',
    jsonb_build_object(
      'enabled',true,
      'controller_mode',v_ctrl.mode,
      'heartbeat','5_minute_database_watchdog',
      'gap_only_bulk_enabled',(v_ctrl.mode='gap_only_bulk'),
      'gap_only_bulk_state',v_gap,
      'safe_auto_claim',true,
      'skip_completed',true,
      'skip_duplicate_work',true,
      'production_auto_promotion',false,
      'external_credentials_auto_created',false,
      'approval_gates_preserved',true,
      'historical_noncanonical_excluded',true,
      'agent_executor','hourly_chatgpt_automation',
      'last_state',v_state,
      'last_result',v_result,
      'checked_at',now()
    )
  )
  on conflict(checkpoint_key) do update
  set state=excluded.state,source=excluded.source,details=excluded.details;

  return jsonb_build_object(
    'ok',true,
    'controller_mode',v_ctrl.mode,
    'state',v_state,
    'gap_only_bulk',v_gap,
    'result',v_result,
    'checked_at',now()
  );
end
$function$


-- [40000000025] function private.tgg_automation_hygiene_health()
CREATE OR REPLACE FUNCTION private.tgg_automation_hygiene_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_stale_once jsonb;
  v_membership_bad boolean:=false;
  v_codesync_recent jsonb;
  v_provider_recent jsonb;
  v_codesync_ok boolean:=false;
  v_provider_ok boolean:=false;
  v_codesync_schedule text;
  v_provider_schedule text;
  v_consistency_schedule text;
  v_codesync_active boolean:=false;
  v_provider_active boolean:=false;
  v_consistency_active boolean:=false;
  v_history_active boolean:=false;
  v_rpc_job_active boolean:=false;
  v_rpc_job_schedule text;
  v_rpc_refreshed timestamptz;
  v_rpc_fresh boolean:=false;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
    'jobid',j.jobid,'jobname',j.jobname,'schedule',j.schedule
  ) order by j.jobid),'[]'::jsonb)
  into v_stale_once
  from cron.job j
  where j.active
    and lower(coalesce(j.jobname,'')) like '%once%';

  select schedule,active into v_codesync_schedule,v_codesync_active
  from cron.job where jobname='tgg-code-sync-controller' limit 1;

  select schedule,active into v_provider_schedule,v_provider_active
  from cron.job where jobname='tgg-provider-endpoint-verifier' limit 1;

  select schedule,active into v_consistency_schedule,v_consistency_active
  from cron.job where jobname='tgg-one-final-activation-consistency-monitor' limit 1;

  select exists(
    select 1 from cron.job
    where jobname='tgg-one-final-activation-history'
      and active
  ) into v_history_active;

  select
    coalesce((select active from cron.job where jobname='tgg-codesync-rpc-registry-refresh' limit 1),false),
    (select schedule from cron.job where jobname='tgg-codesync-rpc-registry-refresh' limit 1)
  into v_rpc_job_active,v_rpc_job_schedule;

  select updated_at
  into v_rpc_refreshed
  from public.tgg_code_sync_rpc_state
  where id=1;

  v_rpc_fresh:=
    v_rpc_refreshed is not null
    and v_rpc_refreshed > now()-interval '2 hours';

  select exists(
    select 1
    from public.tgg_membership_tiers t
    where t.is_active
      and not exists(
        select 1
        from public.tgg_provider_runtime_config c
        where c.provider_key='stripe.webhook'
          and c.enabled
          and c.mode='production'
          and c.endpoint_configured
      )
  ) into v_membership_bad;

  select coalesce(jsonb_agg(jsonb_build_object(
    'status',q.status,'start_time',q.start_time,'end_time',q.end_time
  ) order by q.start_time desc),'[]'::jsonb),
         coalesce(bool_and(q.status='succeeded'),false)
  into v_codesync_recent,v_codesync_ok
  from (
    select d.status,d.start_time,d.end_time
    from cron.job_run_details d
    join cron.job j on j.jobid=d.jobid
    where j.jobname='tgg-code-sync-controller'
      and d.end_time is not null
    order by d.start_time desc
    limit 3
  ) q;

  select coalesce(jsonb_agg(jsonb_build_object(
    'status',q.status,'start_time',q.start_time,'end_time',q.end_time
  ) order by q.start_time desc),'[]'::jsonb),
         coalesce(bool_and(q.status='succeeded'),false)
  into v_provider_recent,v_provider_ok
  from (
    select d.status,d.start_time,d.end_time
    from cron.job_run_details d
    join cron.job j on j.jobid=d.jobid
    where j.jobname='tgg-provider-endpoint-verifier'
      and d.end_time is not null
    order by d.start_time desc
    limit 3
  ) q;

  return jsonb_build_object(
    'ok',
      jsonb_array_length(v_stale_once)=0
      and not v_membership_bad
      and v_codesync_ok
      and v_provider_ok
      and coalesce(v_codesync_active,false)
      and coalesce(v_provider_active,false)
      and coalesce(v_consistency_active,false)
      and not v_history_active
      and coalesce(v_rpc_job_active,false)
      and v_rpc_fresh
      and position('second' in lower(coalesce(v_codesync_schedule,'')))=0
      and coalesce(v_provider_schedule,'')<>coalesce(v_consistency_schedule,''),
    'version','AUTOMATION-HYGIENE-ONE-FINAL-1.7',
    'stale_active_once_jobs',v_stale_once,
    'unsafe_active_membership',v_membership_bad,
    'codesync_schedule',v_codesync_schedule,
    'provider_verifier_schedule',v_provider_schedule,
    'consistency_monitor_schedule',v_consistency_schedule,
    'duplicate_history_job_active',v_history_active,
    'rpc_registry_job_active',coalesce(v_rpc_job_active,false),
    'rpc_registry_job_schedule',v_rpc_job_schedule,
    'rpc_registry_last_refreshed_at',v_rpc_refreshed,
    'rpc_registry_fresh',v_rpc_fresh,
    'codesync_high_frequency_seconds_schedule',
      position('second' in lower(coalesce(v_codesync_schedule,'')))>0,
    'provider_consistency_staggered',
      coalesce(v_provider_schedule,'')<>coalesce(v_consistency_schedule,''),
    'codesync_latest_completed',v_codesync_recent,
    'provider_verifier_latest_completed',v_provider_recent,
    'codesync_recent_ok',v_codesync_ok,
    'provider_verifier_recent_ok',v_provider_ok,
    'checked_at',now()
  );
end
$function$


-- [40000000026] function private.tgg_autonomic_capture_event()
CREATE OR REPLACE FUNCTION private.tgg_autonomic_capture_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text;
  v_type text;
  v_id uuid;
begin
  v_id := new.id;
  v_status := coalesce(to_jsonb(new)->>'status','');
  v_type := tg_table_name||':insert';

  insert into public.tgg_autonomic_events(
    event_key,source_table,source_id,event_type,payload,status
  )
  values(
    'evt:'||tg_table_name||':'||v_id::text,
    tg_table_name,
    v_id,
    v_type,
    to_jsonb(new),
    'new'
  )
  on conflict(event_key) do nothing;

  return new;
end $function$


-- [40000000027] function private.tgg_backup_hash_parity_matrix()
CREATE OR REPLACE FUNCTION private.tgg_backup_hash_parity_matrix()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with baseline as (
    select notes
    from public.tgg_production_baselines
    where status='locked'
    order by locked_at desc
    limit 1
  ),
  expected as (
    select
      x->>'path' as path,
      (x->>'backup_id')::uuid as backup_id,
      x->>'body_hash' as contract_body_hash,
      b.notes#>>array['page_hashes',x->>'path'] as live_page_hash_reference
    from baseline b,
         lateral jsonb_array_elements(
           coalesce(b.notes#>'{validated_backup_contract,backups}','[]'::jsonb)
         ) x
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'path',e.path,
        'backup_id',e.backup_id,
        'contract_hash',e.contract_body_hash,
        'recorded_hash',coalesce(
          bk.metadata->>'v516_body_hash',
          bk.metadata->>'body_hash',
          bk.metadata->>'body_content_hash',
          bk.metadata->>'content_hash',
          bk.content_hash
        ),
        'live_page_hash_reference',e.live_page_hash_reference,
        'backup_present',bk.id is not null,
        'object_present',o.name is not null,
        'matches',
          bk.id is not null
          and o.name is not null
          and e.contract_body_hash is not null
          and coalesce(
            bk.metadata->>'v516_body_hash',
            bk.metadata->>'body_hash',
            bk.metadata->>'body_content_hash',
            bk.metadata->>'content_hash',
            bk.content_hash
          )=e.contract_body_hash
      )
      order by e.path
    ),
    '[]'::jsonb
  )
  from expected e
  left join public.v98_blogger_backups bk on bk.id=e.backup_id
  left join storage.objects o
    on o.bucket_id='v98-blogger-backups'
   and o.name=bk.storage_path;
$function$


-- [40000000028] function private.tgg_blogger_reconnect_link_create_owner()
CREATE OR REPLACE FUNCTION private.tgg_blogger_reconnect_link_create_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
  v_token text;
  v_hash text;
  v_expires timestamptz:=now()+interval '60 minutes';
  v_blog_url text:='https://trugogettamixtapes.blogspot.com/';
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  -- Exactly one active reconnect link per owner/blog.
  update public.tgg_blogger_reconnect_links
  set used_at=coalesce(used_at,now())
  where user_id=v_uid
    and blog_url=v_blog_url
    and used_at is null;

  v_token:=encode(extensions.gen_random_bytes(32),'hex');
  v_hash:=encode(extensions.digest(v_token,'sha256'),'hex');

  insert into public.tgg_blogger_reconnect_links(
    token_hash,user_id,blog_url,expires_at
  )
  values(v_hash,v_uid,v_blog_url,v_expires);

  return jsonb_build_object(
    'ok',true,
    'version','BLOGGER-RECONNECT-V516',
    'url',
      'https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/v98-blogger-connect-link?token='
      ||v_token,
    'expires_at',v_expires,
    'one_time',true,
    'valid_minutes',60
  );
end
$function$


-- [40000000029] function private.tgg_booking_career_mission_trigger()
CREATE OR REPLACE FUNCTION private.tgg_booking_career_mission_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_char uuid;
begin
  if new.status='completed' and old.status is distinct from 'completed' then
    select id into v_char
    from public.world_characters
    where user_id=new.provider_user_id and character_status='active'
    limit 1;

    if v_char is not null then
      perform private.tgg_world_credit_career_mission_event(
        v_char,
        'booking_complete',
        'booking',
        new.id::text,
        jsonb_build_object('service',new.service,'scheduled_for',new.scheduled_for)
      );
      perform private.tgg_world_credit_contract_event(
        v_char,
        'booking_complete',
        'booking',
        new.id::text,
        jsonb_build_object('service',new.service,'scheduled_for',new.scheduled_for)
      );
      perform private.tgg_world_credit_gig_event(
        v_char,
        'booking_complete',
        'booking',
        new.id::text,
        jsonb_build_object('service',new.service,'scheduled_for',new.scheduled_for)
      );
    end if;
  end if;
  return new;
end;
$function$


-- [40000000030] function private.tgg_booking_request_guard()
CREATE OR REPLACE FUNCTION private.tgg_booking_request_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
begin
  if new.requester_user_id<>old.requester_user_id
     or new.provider_user_id<>old.provider_user_id then
    raise exception 'booking_parties_immutable';
  end if;

  if v_uid is null then
    return new;
  end if;

  if new.provider_note is distinct from old.provider_note
     and v_uid<>old.provider_user_id then
    raise exception 'provider_note_provider_only';
  end if;

  if new.scheduled_for is distinct from old.scheduled_for
     and v_uid<>old.provider_user_id then
    raise exception 'scheduled_for_provider_only';
  end if;

  if new.status is distinct from old.status then
    if old.status in ('completed','declined','canceled') then
      raise exception 'booking_terminal_status_immutable';
    end if;

    if v_uid=old.provider_user_id then
      if not (
        (old.status='pending' and new.status in ('accepted','declined'))
        or (old.status='accepted' and new.status in ('completed','declined'))
      ) then
        raise exception 'invalid_provider_booking_transition';
      end if;
    elsif v_uid=old.requester_user_id then
      if not (old.status in ('pending','accepted') and new.status='canceled') then
        raise exception 'invalid_requester_booking_transition';
      end if;
    else
      raise exception 'booking_update_not_authorized';
    end if;
  end if;

  return new;
end;
$function$


-- [40000000031] function private.tgg_call_invite_expiry_watch()
CREATE OR REPLACE FUNCTION private.tgg_call_invite_expiry_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text:='missing';
  v_expires_at timestamptz;
  v_claimed boolean:=false;
  v_seconds bigint;
  v_level text;
  v_payload jsonb;
begin
  select
    case when i.status='pending' and i.expires_at<=now() then 'expired' else i.status end,
    i.expires_at,
    i.claimed_by_user_id is not null
  into v_status,v_expires_at,v_claimed
  from private.tgg_call_validation_invites i
  order by i.created_at desc
  limit 1;

  if v_expires_at is not null then
    v_seconds:=greatest(extract(epoch from (v_expires_at-now()))::bigint,0);
  end if;

  v_level:=case
    when v_claimed then 'clear'
    when v_status='expired' then 'warning'
    when v_status='pending' and coalesce(v_seconds,0)<=7200 then 'advisory'
    else 'clear'
  end;

  v_payload:=jsonb_build_object(
    'ok',v_level in ('clear','advisory'),
    'version','CALL-INVITE-EXPIRY-WATCH-1.1',
    'status',v_status,
    'claimed',v_claimed,
    'expires_at',v_expires_at,
    'expires_in_seconds',v_seconds,
    'warning_window_seconds',7200,
    'level',v_level,
    'core_blocking',false,
    'checked_at',now()
  );

  if v_level in ('clear','advisory') then
    update public.tgg_operational_alerts
    set status='resolved',
        last_seen=now(),
        last_payload=v_payload
    where alert_key='calls:validation_invite_expiry'
      and status<>'resolved';
  else
    insert into public.tgg_operational_alerts(
      alert_key,status,severity,subsystem,
      first_seen,last_seen,occurrence_count,last_payload
    )
    values(
      'calls:validation_invite_expiry',
      'open',
      'warning',
      'calls',
      now(),now(),1,v_payload
    )
    on conflict(alert_key) do update
    set status='open',
        severity='warning',
        subsystem='calls',
        last_seen=now(),
        occurrence_count=public.tgg_operational_alerts.occurrence_count+1,
        last_payload=excluded.last_payload;
  end if;

  return v_payload;
end
$function$


-- [40000000032] function private.tgg_call_validation_finalize(p_room_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_call_validation_finalize(p_room_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_inv private.tgg_call_validation_invites%rowtype;
  v_valid boolean:=false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if not exists(
    select 1 from public.tgg_call_participants
    where room_id=p_room_id and user_id=v_uid and left_at is null
  ) then
    raise exception 'ROOM_ACCESS_DENIED' using errcode='42501';
  end if;

  select * into v_inv
  from private.tgg_call_validation_invites
  where room_id=p_room_id
    and status in ('claimed','completed')
    and (inviter_user_id=v_uid or claimed_by_user_id=v_uid)
  order by created_at desc
  limit 1
  for update;

  if not found then
    raise exception 'CALL_VALIDATION_INVITE_NOT_FOUND';
  end if;

  select exists(
    select 1
    from public.tgg_call_signals o
    join public.tgg_call_signals a
      on a.room_id=o.room_id
     and a.signal_type='answer'
     and a.sender_id<>o.sender_id
    where o.room_id=p_room_id
      and o.signal_type='offer'
      and exists(
        select 1 from public.tgg_call_participants po
        where po.room_id=p_room_id and po.user_id=o.sender_id
      )
      and exists(
        select 1 from public.tgg_call_participants pa
        where pa.room_id=p_room_id and pa.user_id=a.sender_id
      )
  ) into v_valid;

  if not v_valid then
    return jsonb_build_object(
      'ok',false,
      'validated',false,
      'room_id',p_room_id,
      'reason','distinct_offer_answer_exchange_required'
    );
  end if;

  if v_inv.status<>'completed' then
    update private.tgg_call_validation_invites
    set status='completed',completed_at=now()
    where invite_id=v_inv.invite_id;
  end if;

  return jsonb_build_object(
    'ok',true,
    'validated',true,
    'room_id',p_room_id,
    'status','completed',
    'distinct_offer_answer_senders',true,
    'completed_at',coalesce(v_inv.completed_at,now())
  );
end;
$function$


-- [40000000033] function private.tgg_call_validation_invite_claim(p_invite_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_call_validation_invite_claim(p_invite_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_inv private.tgg_call_validation_invites%rowtype;
  v_conversation uuid;
  v_room uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select *
  into v_inv
  from private.tgg_call_validation_invites
  where invite_id=p_invite_id
  for update;

  if not found then
    raise exception 'CALL_VALIDATION_INVITE_NOT_FOUND';
  end if;

  if v_inv.inviter_user_id=v_uid then
    raise exception 'SECOND_DISTINCT_USER_REQUIRED';
  end if;

  if v_inv.status='claimed' and v_inv.claimed_by_user_id=v_uid then
    return jsonb_build_object(
      'ok',true,
      'idempotent',true,
      'conversation_id',v_inv.conversation_id,
      'room_id',v_inv.room_id,
      'inviter_user_id',v_inv.inviter_user_id,
      'claimed_by_user_id',v_inv.claimed_by_user_id
    );
  end if;

  if v_inv.status<>'pending' then
    raise exception 'CALL_VALIDATION_INVITE_NOT_AVAILABLE';
  end if;

  if v_inv.expires_at<=now() then
    update private.tgg_call_validation_invites
    set status='expired'
    where invite_id=p_invite_id;

    raise exception 'CALL_VALIDATION_INVITE_EXPIRED';
  end if;

  insert into public.tgg_conversations(
    created_by,title,project_type,status,last_message_at,created_at,updated_at
  )
  values(
    v_inv.inviter_user_id,
    'ONE-FINAL Call Validation',
    'call_validation',
    'active',
    now(),
    now(),
    now()
  )
  returning id into v_conversation;

  insert into public.tgg_conversation_members(
    conversation_id,user_id,role,joined_at
  )
  values
    (v_conversation,v_inv.inviter_user_id,'owner',now()),
    (v_conversation,v_uid,'member',now())
  on conflict(conversation_id,user_id) do nothing;

  insert into public.tgg_call_rooms(
    created_by,conversation_id,title,room_type,status,is_group,created_at
  )
  values(
    v_inv.inviter_user_id,
    v_conversation,
    'ONE-FINAL Call Validation',
    'video',
    'active',
    false,
    now()
  )
  returning id into v_room;

  insert into public.tgg_call_participants(
    room_id,user_id,mic_enabled,camera_enabled,joined_at
  )
  values
    (v_room,v_inv.inviter_user_id,true,true,now()),
    (v_room,v_uid,true,true,now())
  on conflict(room_id,user_id) do nothing;

  update private.tgg_call_validation_invites
  set
    claimed_by_user_id=v_uid,
    conversation_id=v_conversation,
    room_id=v_room,
    status='claimed',
    claimed_at=now()
  where invite_id=p_invite_id;

  return jsonb_build_object(
    'ok',true,
    'version','CALL-VALIDATION-INVITE-1.0',
    'conversation_id',v_conversation,
    'room_id',v_room,
    'inviter_user_id',v_inv.inviter_user_id,
    'claimed_by_user_id',v_uid,
    'next_step','Both users send real WebRTC offer/answer signals through tgg_call_signal_send.'
  );
end
$function$


-- [40000000034] function private.tgg_call_validation_invite_create()
CREATE OR REPLACE FUNCTION private.tgg_call_validation_invite_create()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_id uuid;
  v_expires timestamptz:=now()+interval '24 hours';
  v_existing private.tgg_call_validation_invites%rowtype;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  perform private.tgg_creator_rate_limit_gate('calls.validation_invite',10,3600);

  update private.tgg_call_validation_invites
  set status='expired'
  where inviter_user_id=v_uid
    and status='pending'
    and expires_at<=now();

  select *
  into v_existing
  from private.tgg_call_validation_invites
  where inviter_user_id=v_uid
    and status='pending'
    and expires_at>now()
  order by created_at desc
  limit 1;

  if v_existing.invite_id is not null then
    perform private.tgg_creator_mutation_audit_log(
      'calls.validation_invite_reuse',
      v_existing.invite_id::text,
      jsonb_build_object('expires_at',v_existing.expires_at)
    );

    return jsonb_build_object(
      'ok',true,
      'version','CALL-VALIDATION-INVITE-1.1',
      'invite_token',v_existing.invite_id,
      'expires_at',v_existing.expires_at,
      'idempotent_reuse',true,
      'requires_second_distinct_user',true
    );
  end if;

  begin
    insert into private.tgg_call_validation_invites(inviter_user_id,expires_at)
    values(v_uid,v_expires)
    returning invite_id into v_id;
  exception when unique_violation then
    select invite_id,expires_at
    into v_id,v_expires
    from private.tgg_call_validation_invites
    where inviter_user_id=v_uid
      and status='pending'
    order by created_at desc
    limit 1;

    if v_id is null then raise; end if;
  end;

  perform private.tgg_creator_mutation_audit_log(
    'calls.validation_invite_create',
    v_id::text,
    jsonb_build_object('expires_at',v_expires)
  );

  return jsonb_build_object(
    'ok',true,
    'version','CALL-VALIDATION-INVITE-1.1',
    'invite_token',v_id,
    'expires_at',v_expires,
    'idempotent_reuse',false,
    'requires_second_distinct_user',true
  );
end;
$function$


-- [40000000035] function private.tgg_call_validation_invite_freshness_check()
CREATE OR REPLACE FUNCTION private.tgg_call_validation_invite_freshness_check()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with latest as (
  select *
  from private.tgg_call_validation_invites
  order by created_at desc
  limit 1
)
select coalesce((
  select jsonb_build_object(
    'ok',
      case
        when claimed_by_user_id is not null then true
        when status='pending' then expires_at>now()
        when status in ('claimed','completed') then true
        else false
      end,
    'version','CALL-INVITE-FRESHNESS-1.0',
    'status',case when status='pending' and expires_at<=now() then 'expired' else status end,
    'has_invite',true,
    'second_user_claimed',claimed_by_user_id is not null,
    'expires_at',expires_at,
    'expires_in_seconds',greatest(extract(epoch from (expires_at-now()))::bigint,0),
    'checked_at',now()
  )
  from latest
),jsonb_build_object(
  'ok',false,
  'version','CALL-INVITE-FRESHNESS-1.0',
  'status','missing',
  'has_invite',false,
  'second_user_claimed',false,
  'expires_at',null,
  'expires_in_seconds',null,
  'checked_at',now()
));
$function$


-- [40000000036] function private.tgg_call_validation_invite_status()
CREATE OR REPLACE FUNCTION private.tgg_call_validation_invite_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_inv private.tgg_call_validation_invites%rowtype;
  v_effective_status text;
  v_role text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  -- Prefer the newest claimed invite whose room is still active and where
  -- the signed-in user is one of the two legitimate participants. This
  -- prevents a newer pending invite from hiding an already-claimed room.
  select i.*
  into v_inv
  from private.tgg_call_validation_invites i
  join public.tgg_call_rooms r on r.id=i.room_id
  where i.status='claimed'
    and r.status='active'
    and r.ended_at is null
    and (i.inviter_user_id=v_uid or i.claimed_by_user_id=v_uid)
  order by i.claimed_at desc nulls last, i.created_at desc
  limit 1;

  if not found then
    -- No active claimed room: show the user's newest invite as before.
    select *
    into v_inv
    from private.tgg_call_validation_invites
    where inviter_user_id=v_uid
    order by created_at desc
    limit 1;
  end if;

  if not found then
    return jsonb_build_object(
      'ok',true,
      'has_invite',false,
      'status','none',
      'can_create',true,
      'current_user_role',null
    );
  end if;

  v_effective_status:=case
    when v_inv.status='pending' and v_inv.expires_at<=now() then 'expired'
    else v_inv.status
  end;

  v_role:=case
    when v_inv.inviter_user_id=v_uid then 'offerer'
    when v_inv.claimed_by_user_id=v_uid then 'responder'
    else null
  end;

  return jsonb_build_object(
    'ok',true,
    'has_invite',true,
    'invite_token',v_inv.invite_id,
    'status',v_effective_status,
    'expires_at',v_inv.expires_at,
    'claimed_at',v_inv.claimed_at,
    'completed_at',v_inv.completed_at,
    'conversation_id',v_inv.conversation_id,
    'room_id',v_inv.room_id,
    'can_create',v_effective_status in ('claimed','expired','completed'),
    'second_user_claimed',v_inv.claimed_by_user_id is not null,
    'current_user_role',v_role,
    'claim_url','https://trugogettamixtapes.blogspot.com/p/artist-dashboard_0633467215.html?join_validation_code=' || v_inv.invite_id::text
  );
end;
$function$


-- [40000000037] function private.tgg_can_join_call_room(p_room_id uuid, p_user_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_can_join_call_room(p_room_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select exists (
    select 1
    from public.tgg_call_rooms r
    where r.id = p_room_id
      and r.status in ('open','active')
      and (
        r.created_by = p_user_id
        or exists (
          select 1
          from public.tgg_call_participants cp
          where cp.room_id = r.id
            and cp.user_id = p_user_id
            and cp.left_at is null
        )
        or exists (
          select 1
          from public.tgg_conversation_members cm
          where cm.conversation_id = r.conversation_id
            and cm.user_id = p_user_id
        )
      )
  );
$function$


-- [40000000038] function private.tgg_choose_dialogue(p_character_id uuid, p_encounter_id uuid, p_choice_key text)
CREATE OR REPLACE FUNCTION private.tgg_choose_dialogue(p_character_id uuid, p_encounter_id uuid, p_choice_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_enc public.tgg_world_character_encounters%rowtype;
  v_choice public.tgg_world_dialogue_choices%rowtype;
  v_rep integer := 0;
  v_terminal boolean := false;
  v_gig uuid;
  v_npc_key text;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  if not exists(
    select 1 from public.world_characters
    where id=p_character_id and user_id=v_uid and character_status='active'
  ) then
    raise exception 'character ownership mismatch';
  end if;

  select * into v_enc
  from public.tgg_world_character_encounters
  where id=p_encounter_id
    and character_id=p_character_id
    and status='active'
  for update;

  if v_enc.id is null then raise exception 'encounter unavailable'; end if;

  select * into v_choice
  from public.tgg_world_dialogue_choices
  where choice_key=p_choice_key
    and node_key=v_enc.current_node_key
    and enabled=true;

  if v_choice.choice_key is null then raise exception 'choice unavailable'; end if;

  if v_choice.conditions ? 'min_reputation' then
    select coalesce(max(r.reputation),0) into v_rep
    from public.tgg_world_career_reputation r
    where r.character_id=p_character_id;

    if v_rep < (v_choice.conditions->>'min_reputation')::integer then
      raise exception 'reputation requirement not met';
    end if;
  end if;

  select e.npc_key into v_npc_key
  from public.tgg_world_encounter_templates e
  where e.encounter_key=v_enc.encounter_key and e.enabled=true
  limit 1;

  insert into public.tgg_world_encounter_choice_log
    (encounter_id,character_id,node_key,choice_key,effect_snapshot,created_at)
  values(
    v_enc.id,p_character_id,v_enc.current_node_key,v_choice.choice_key,
    v_choice.effects,now()
  );

  if v_npc_key is not null then
    insert into public.tgg_world_npc_memory_events(
      character_id,npc_key,memory_type,memory_key,weight,sentiment,payload,occurred_at
    )
    values(
      p_character_id,
      v_npc_key,
      'dialogue_choice',
      v_enc.encounter_key||':'||v_choice.choice_key,
      1,
      0,
      jsonb_build_object(
        'encounter_id',v_enc.id,
        'encounter_key',v_enc.encounter_key,
        'node_key',v_enc.current_node_key,
        'choice_key',v_choice.choice_key,
        'effects',v_choice.effects
      ),
      now()
    );
  end if;

  v_terminal := v_choice.next_node_key is null
    or not exists(
      select 1 from public.tgg_world_dialogue_choices c
      where c.node_key=v_choice.next_node_key and c.enabled=true
    );

  update public.tgg_world_character_encounters
  set current_node_key=coalesce(v_choice.next_node_key,current_node_key),
      status=case when v_terminal then 'completed' else 'active' end,
      completed_at=case when v_terminal then now() else completed_at end,
      state=state||jsonb_build_object(
        'last_choice',v_choice.choice_key,
        'effects',v_choice.effects
      ),
      updated_at=now()
  where id=v_enc.id;

  perform private.tgg_world_onboarding_event(p_character_id,'dialogue_choice',v_choice.choice_key);

  if v_terminal then
    v_gig := private.tgg_offer_first_gig(p_character_id);
  end if;

  return jsonb_build_object(
    'encounter_id',v_enc.id,
    'choice_key',v_choice.choice_key,
    'next_node_key',v_choice.next_node_key,
    'completed',v_terminal,
    'offered_gig_id',v_gig
  );
end;
$function$


-- [40000000039] function private.tgg_cleanup_call_validation_invites()
CREATE OR REPLACE FUNCTION private.tgg_cleanup_call_validation_invites()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_expired integer:=0;
  v_deleted integer:=0;
begin
  update private.tgg_call_validation_invites
  set status='expired'
  where status='pending'
    and expires_at<=now();

  get diagnostics v_expired=row_count;

  delete from private.tgg_call_validation_invites
  where
    (status in ('expired','canceled') and created_at<now()-interval '14 days')
    or
    (status='completed' and completed_at<now()-interval '90 days');

  get diagnostics v_deleted=row_count;

  return jsonb_build_object(
    'ok',true,
    'expired_marked',v_expired,
    'old_invites_deleted',v_deleted,
    'generated_at',now()
  );
end
$function$


-- [40000000040] function private.tgg_cleanup_membership_payment_link_claims()
