-- [40000000041] function private.tgg_cleanup_retired_cron_jobs()
CREATE OR REPLACE FUNCTION private.tgg_cleanup_retired_cron_jobs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_jobid bigint;
  v_removed integer:=0;
begin
  for v_jobid in
    select j.jobid
    from cron.job j
    where j.active
      and (
        j.jobname='tgg-one-final-activation-history'
        or (
          lower(coalesce(j.jobname,'')) like '%once%'
          and exists(
            select 1
            from cron.job_run_details d
            where d.jobid=j.jobid
              and d.status='succeeded'
              and d.end_time is not null
          )
        )
      )
  loop
    perform cron.unschedule(v_jobid);
    v_removed:=v_removed+1;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'version','RETIRED-CRON-CLEANUP-ONE-FINAL-1.1',
    'removed',v_removed,
    'policy','retire any active job named once after one successful completed run; always retire duplicate activation-history job',
    'checked_at',now()
  );
end
$function$


-- [40000000042] function private.tgg_codesync_audit_edge_dependencies()
CREATE OR REPLACE FUNCTION private.tgg_codesync_audit_edge_dependencies()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'private', 'public', 'pg_catalog', 'information_schema', 'pg_temp'
AS $function$
declare
  r record;
  dbrefs int;
  cronrefs int;
  jobrefs int;
  backuprefs int;
  safe_count int;
  pat text;
  active_route_refs int;
begin
  for r in
    select slug
    from private.tgg_edge_function_registry
    where duplicate_candidate
  loop
    pat := '(^|[^A-Za-z0-9_-])' ||
      regexp_replace(r.slug, '([\\.\\+\\*\\?\\[\\^\\]\\$\\(\\)\\{\\}=!<>|:\\-])', '\\\1', 'g') ||
      '([^A-Za-z0-9_-]|$)';

    select count(*) into dbrefs
    from pg_proc p
    join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in ('public','private')
      and p.prokind in ('f','p')
      and pg_get_functiondef(p.oid) ~ pat;

    select count(*) into cronrefs
    from cron.job
    where command ~ pat;

    select count(*) into jobrefs
    from public.tgg_theme_deploy_jobs
    where coalesce(xml_text,'') ~ pat
       or coalesce(payload_text,'') ~ pat
       or coalesce(result::text,'') ~ pat;

    select count(*) into backuprefs
    from public.v98_blogger_backups
    where coalesce(resource_key,'') ~ pat
       or coalesce(metadata::text,'') ~ pat;

    select count(*) into active_route_refs
    from public.tgg_site_routes
    where is_active and path ~ pat;

    if r.slug='creator-os-command-center' and active_route_refs=0 then
      dbrefs := 0;
    end if;

    insert into private.tgg_edge_function_dependency_audit(
      slug,db_function_refs,cron_refs,blogger_job_refs,blogger_backup_refs,total_refs,checked_at
    )
    values(
      r.slug,dbrefs,cronrefs,jobrefs,backuprefs,
      dbrefs+cronrefs+jobrefs+backuprefs,now()
    )
    on conflict(slug) do update set
      db_function_refs=excluded.db_function_refs,
      cron_refs=excluded.cron_refs,
      blogger_job_refs=excluded.blogger_job_refs,
      blogger_backup_refs=excluded.blogger_backup_refs,
      total_refs=excluded.total_refs,
      checked_at=now();

    update private.tgg_edge_function_registry
    set retirement_state = case
      when dbrefs+cronrefs+jobrefs+backuprefs=0 then 'safe_to_retire'
      else 'review'
    end
    where slug=r.slug;
  end loop;

  select count(*) into safe_count
  from private.tgg_edge_function_registry
  where duplicate_candidate and retirement_state='safe_to_retire';

  return jsonb_build_object('ok',true,'safe_to_retire',safe_count,'checked_at',now());
end;
$function$


-- [40000000043] function private.tgg_codesync_dedupe_blogger_backups()
CREATE OR REPLACE FUNCTION private.tgg_codesync_dedupe_blogger_backups()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'private', 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_removed int:=0;
begin
  with baseline_refs as (
    select distinct nullif(x->>'backup_id','')::uuid as backup_id
    from public.tgg_production_baselines b,
         lateral jsonb_array_elements(
           coalesce(b.notes#>'{validated_backup_contract,backups}','[]'::jsonb)
         ) x
    where b.status='locked'
      and nullif(x->>'backup_id','') is not null
  ),
  ranked as (
    select
      b.*,
      first_value(id) over(
        partition by connection_id,user_id,resource_type,resource_key,content_hash
        order by created_at desc,id desc
      ) as kept_id,
      row_number() over(
        partition by connection_id,user_id,resource_type,resource_key,content_hash
        order by created_at desc,id desc
      ) as rn,
      count(*) over(
        partition by connection_id,user_id,resource_type,resource_key,content_hash
      ) as copies
    from public.v98_blogger_backups b
  ),
  safe as (
    select r.*
    from ranked r
    where r.copies>1
      and r.rn>1
      and not exists(
        select 1 from public.v98_blogger_deployments d
        where d.backup_id=r.id
      )
      and not exists(
        select 1 from baseline_refs br
        where br.backup_id=r.id
      )
  ),
  logged as (
    insert into private.tgg_backup_dedupe_log(
      removed_backup_id,kept_backup_id,connection_id,user_id,
      resource_type,resource_key,content_hash,
      removed_storage_bucket,removed_storage_path,reason
    )
    select
      s.id,s.kept_id,s.connection_id,s.user_id,
      s.resource_type,s.resource_key,s.content_hash,
      s.storage_bucket,s.storage_path,
      'Older identical-content backup removed; newest copy, deployment references, and locked-baseline recovery references are preserved.'
    from safe s
    on conflict(removed_backup_id) do nothing
    returning removed_backup_id
  )
  delete from public.v98_blogger_backups b
  using logged l
  where b.id=l.removed_backup_id;

  get diagnostics v_removed = row_count;

  return jsonb_build_object(
    'ok',true,
    'duplicates_removed',v_removed,
    'baseline_references_protected',true,
    'checked_at',now()
  );
end;
$function$


-- [40000000044] function private.tgg_codesync_detect_and_fix()
CREATE OR REPLACE FUNCTION private.tgg_codesync_detect_and_fix()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'private', 'public', 'pg_temp'
AS $function$
declare
  v_fixed int := 0;
  v_errors int := 0;
  v_review int := 0;
  r record;
begin
  for r in
    select id,status,claimed_at,filename
    from public.tgg_theme_deploy_jobs
    where status in ('claimed','processing')
      and claimed_at is not null
      and claimed_at < now() - interval '10 minutes'
  loop
    update public.tgg_theme_deploy_jobs
    set status='pending',
        device_id=null,
        claimed_at=null,
        error=coalesce(error,'') || case when coalesce(error,'')='' then '' else E'\n' end ||
              'Auto-recovered stale deploy claim by Code Sync Controller'
    where id=r.id;

    insert into private.tgg_code_actions(action_type,component_key,status,details)
    values ('recover_stale_deploy_job','deploy_job:'||r.id,'completed',
            jsonb_build_object('filename',r.filename,'previous_status',r.status));
    v_fixed := v_fixed + 1;
  end loop;

  -- Resolve stale Blogger failure issues when a newer verified deployment for
  -- the same resource already exists, or when the failure belongs to the
  -- intentionally removed World E2E verifier test page.
  update private.tgg_code_issues i
  set status='resolved',
      last_seen_at=now(),
      auto_fixed_at=coalesce(i.auto_fixed_at,now())
  from public.v98_blogger_deployments f
  where i.status='open'
    and i.issue_key='blogger_deploy_failed:'||f.id::text
    and f.status='failed'
    and (
      f.resource_key='/p/world-e2e-verifier.html'
      or exists (
        select 1
        from public.v98_blogger_deployments s
        where s.status='verified'
          and s.resource_type is not distinct from f.resource_type
          and s.resource_key is not distinct from f.resource_key
          and s.updated_at > f.updated_at
      )
    );

  for r in
    select f.id,f.resource_type,f.resource_key,f.error_message
    from public.v98_blogger_deployments f
    where f.status='failed'
      and f.updated_at > now() - interval '24 hours'
      and f.resource_key is distinct from '/p/world-e2e-verifier.html'
      and not exists (
        select 1
        from public.v98_blogger_deployments s
        where s.status='verified'
          and s.resource_type is not distinct from f.resource_type
          and s.resource_key is not distinct from f.resource_key
          and s.updated_at > f.updated_at
      )
  loop
    perform private.tgg_codesync_upsert_issue(
      'blogger_deploy_failed:'||r.id,
      'error',
      'blogger:'||coalesce(r.resource_type,'unknown')||':'||coalesce(r.resource_key,r.id::text),
      'Blogger deployment failed',
      jsonb_build_object('deployment_id',r.id,'error',r.error_message)
    );
    v_errors := v_errors + 1;
  end loop;

  select count(*) into v_review
  from private.tgg_edge_function_registry
  where duplicate_candidate and retirement_state='review';

  if v_review > 0 then
    perform private.tgg_codesync_upsert_issue(
      'edge_function_version_chain:review_required',
      'warning',
      'edge_functions',
      'One or more duplicate Edge Functions still require dependency review.',
      jsonb_build_object('needs_review',v_review,'auto_delete',false)
    );
  else
    update private.tgg_code_issues
    set status='resolved',last_seen_at=now()
    where issue_key in (
      'edge_function_version_chain:tgg-creator-os-app',
      'edge_function_version_chain:review_required'
    )
    and status='open';
  end if;

  return jsonb_build_object('ok',true,'fixed',v_fixed,'issues_seen',v_errors,'needs_review',v_review,'checked_at',now());
end;
$function$


-- [40000000045] function private.tgg_codesync_detect_new_edge_duplicates()
CREATE OR REPLACE FUNCTION private.tgg_codesync_detect_new_edge_duplicates()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'private', 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_count int;
begin
  select count(*) into v_count
  from private.tgg_edge_function_registry r
  join private.tgg_edge_deployment_policy p
    on p.family_key=r.family_key
  where r.slug<>p.canonical_slug
    and r.duplicate_candidate
    and r.last_inventory_at > now()-interval '2 minutes'
    and not exists (
      select 1
      from private.tgg_edge_retirement_manifest m
      where m.slug=r.slug
    );

  if v_count>0 then
    perform private.tgg_codesync_upsert_issue(
      'codesync:new_duplicate_edge_function',
      'error',
      'edge_functions',
      'A new versioned duplicate Edge Function was detected. Update the canonical function in place instead.',
      jsonb_build_object('count',v_count)
    );
  else
    update private.tgg_code_issues
    set status='resolved',last_seen_at=now()
    where issue_key='codesync:new_duplicate_edge_function' and status='open';
  end if;

  return jsonb_build_object('ok',v_count=0,'new_duplicate_count',v_count,'checked_at',now());
end;
$function$


-- [40000000046] function private.tgg_codesync_known_regressions()
CREATE OR REPLACE FUNCTION private.tgg_codesync_known_regressions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'private', 'public', 'pg_catalog', 'information_schema', 'pg_temp'
AS $function$
declare
  v_ok boolean:=true;
  v_failures jsonb:='[]'::jsonb;
  v_route jsonb;
  v_drift jsonb;
  v_health_refreshed timestamptz;
begin
  if exists (
    select 1 from information_schema.tables
    where table_schema='public' and table_name like 'v54_%'
  ) then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('v54_legacy_subsystem_reappeared');
  end if;

  if exists (
    select 1 from information_schema.tables
    where table_schema='public' and table_name like 'v58_%'
  ) then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('v58_legacy_database_subsystem_reappeared');
  end if;

  if to_regclass('public.v159_creator_events') is not null then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('v159_legacy_analytics_reappeared');
  end if;

  if to_regclass('public.v122_security_control_status') is not null
     or to_regclass('public.v3923_security_advisor_suppression_audit') is not null
     or to_regclass('public.v3930_creator_os_runtime_readiness') is not null
  then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('retired_legacy_status_tables_reappeared');
  end if;

  if to_regclass('public.tgg_revenue_events') is null then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('tgg_revenue_events_missing');
  end if;

  if not exists (
    select 1
    from pg_class c
    join pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public'
      and c.relname='tgg_revenue_events'
      and c.relrowsecurity
  ) then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('tgg_revenue_events_rls_disabled');
  end if;

  if not has_table_privilege('authenticated','public.tgg_revenue_events','SELECT') then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('tgg_revenue_events_auth_select_missing');
  end if;

  if to_regclass('public.creator_analytics_events') is null then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('creator_analytics_events_missing');
  end if;

  if not (
    has_table_privilege('authenticated','public.creator_analytics_events','SELECT')
    and has_table_privilege('authenticated','public.creator_analytics_events','INSERT')
  ) then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('creator_analytics_events_auth_grants_missing');
  end if;

  if not exists (
    select 1
    from pg_class c
    join pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public'
      and c.relname='creator_analytics_events'
      and c.relrowsecurity
  ) then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('creator_analytics_events_rls_disabled');
  end if;

  if to_regprocedure('public.tgg_record_creator_event(text,uuid,text,text,jsonb)') is null then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('tgg_record_creator_event_missing');
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema='public'
      and table_name='mixtapes'
      and column_name='audio_url'
  ) then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('mixtapes.audio_url_missing');
  end if;

  if to_regclass('public.creator_conversations') is not null
     or to_regclass('public.conversations') is not null
     or to_regclass('public.messages') is not null
  then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('legacy_messaging_tables_reappeared');
  end if;

  v_route:=public.tgg_route_registry_final_health();
  if not coalesce((v_route->>'ok')::boolean,false) then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('route_registry_unhealthy');
  end if;

  select drift_payload,refreshed_at
  into v_drift,v_health_refreshed
  from public.tgg_runtime_health_cache
  where id=1;

  if v_drift is null
     or v_health_refreshed is null
     or v_health_refreshed<now()-interval '15 minutes'
  then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('runtime_health_cache_stale');
  elsif not coalesce((v_drift->>'ok')::boolean,false)
        or coalesce((v_drift->>'drift_count')::integer,0)<>0
  then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('production_drift_detected');
  end if;

  if exists(
    select 1
    from private.tgg_edge_function_registry
    where runtime_state='unknown'
       or duplicate_candidate
  ) then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('edge_classification_regressed');
  end if;

  if exists(
    select 1
    from private.tgg_edge_retirement_manifest
    where approved_state = 'ready'
  ) then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('edge_retirement_queue_reopened');
  end if;

  if v_ok then
    update private.tgg_code_issues
    set status='resolved',last_seen_at=now()
    where issue_key='codesync:known_regression'
      and status='open';
  else
    perform private.tgg_codesync_upsert_issue(
      'codesync:known_regression',
      'error',
      'platform_regression_guard',
      'A previously fixed platform regression has returned.',
      jsonb_build_object(
        'failures',v_failures,
        'health_cache_refreshed_at',v_health_refreshed
      )
    );
  end if;

  return jsonb_build_object(
    'ok',v_ok,
    'version','CODESYNC-KNOWN-REGRESSIONS-ONE-FINAL-1.1',
    'failures',v_failures,
    'production_drift_count',coalesce((v_drift->>'drift_count')::integer,0),
    'health_cache_refreshed_at',v_health_refreshed,
    'full_production_drift_called',false,
    'checked_at',now()
  );
end
$function$


-- [40000000047] function private.tgg_codesync_operational_cleanup()
CREATE OR REPLACE FUNCTION private.tgg_codesync_operational_cleanup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'private', 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_oauth_deleted int:=0;
begin
  delete from public.v98_blogger_oauth_states
  where consumed_at is null
    and expires_at < now();
  get diagnostics v_oauth_deleted = row_count;

  return jsonb_build_object(
    'ok',true,
    'expired_oauth_states_deleted',v_oauth_deleted,
    'provider_tasks_recovered',0,
    'workflow_tasks_recovered',0,
    'recent_dead_letters',0,
    'recent_failed_provider_tasks',0,
    'checked_at',now()
  );
end;
$function$


-- [40000000048] function private.tgg_codesync_refresh_dashboard()
CREATE OR REPLACE FUNCTION private.tgg_codesync_refresh_dashboard()
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'private', 'public', 'pg_temp'
AS $function$
  insert into public.tgg_code_sync_dashboard_state(
    id,components,snapshots,open_issues,auto_fixed,actions,last_scan,updated_at
  )
  values (
    1,
    (select count(*) from private.tgg_code_components),
    (select count(*) from private.tgg_code_snapshots),
    (select count(*) from private.tgg_code_issues where status='open'),
    (select count(*) from private.tgg_code_issues where status='auto_fixed'),
    (select count(*) from private.tgg_code_actions),
    (select max(last_seen_at) from private.tgg_code_components),
    now()
  )
  on conflict(id) do update set
    components=excluded.components,
    snapshots=excluded.snapshots,
    open_issues=excluded.open_issues,
    auto_fixed=excluded.auto_fixed,
    actions=excluded.actions,
    last_scan=excluded.last_scan,
    updated_at=excluded.updated_at;
$function$


-- [40000000049] function private.tgg_codesync_refresh_policy_state()
CREATE OR REPLACE FUNCTION private.tgg_codesync_refresh_policy_state()
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'private', 'public', 'pg_temp'
AS $function$
insert into public.tgg_code_sync_policy_state(
  id,total_families,update_in_place_families,blocked_duplicate_patterns,retirement_ready,retirement_hold,updated_at
)
values(
  1,
  (select count(*) from private.tgg_edge_deployment_policy),
  (select count(*) from private.tgg_edge_deployment_policy where update_in_place),
  (select count(*) from private.tgg_edge_deployment_policy where update_in_place and not allow_versioned_siblings),
  (select count(*) from private.tgg_edge_retirement_manifest where approved_state='ready'),
  (select count(*) from private.tgg_edge_retirement_manifest where approved_state='hold'),
  now()
)
on conflict(id) do update set
  total_families=excluded.total_families,
  update_in_place_families=excluded.update_in_place_families,
  blocked_duplicate_patterns=excluded.blocked_duplicate_patterns,
  retirement_ready=excluded.retirement_ready,
  retirement_hold=excluded.retirement_hold,
  updated_at=excluded.updated_at;
$function$


-- [40000000050] function private.tgg_codesync_refresh_retirement_manifest()
CREATE OR REPLACE FUNCTION private.tgg_codesync_refresh_retirement_manifest()
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'private', 'public', 'pg_temp'
AS $function$
insert into private.tgg_edge_retirement_manifest(
  slug,family_key,canonical_slug,reason,reference_count,approved_state,verified_at
)
select
  r.slug,
  r.family_key,
  c.slug,
  'Duplicate/versioned Edge Function with no active runtime dependency. Canonical function must be updated in place.',
  coalesce(a.total_refs,0),
  case when r.retirement_state='safe_to_retire' then 'ready' else 'hold' end,
  now()
from private.tgg_edge_function_registry r
join private.tgg_edge_function_registry c
  on c.family_key=r.family_key and c.canonical=true
left join private.tgg_edge_function_dependency_audit a
  on a.slug=r.slug
where r.duplicate_candidate
on conflict(slug) do update set
  family_key=excluded.family_key,
  canonical_slug=excluded.canonical_slug,
  reason=excluded.reason,
  reference_count=excluded.reference_count,
  approved_state=case
    when private.tgg_edge_retirement_manifest.approved_state='retired' then 'retired'
    else excluded.approved_state
  end,
  verified_at=now();
$function$


-- [40000000051] function private.tgg_codesync_refresh_rpc_registry()
CREATE OR REPLACE FUNCTION private.tgg_codesync_refresh_rpc_registry()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'private', 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  r record;
  v_db_refs int;
  v_policy_refs int;
  v_state text;
  v_count int:=0;
  v_policy_text text;
begin
  for r in
    select n.nspname as schema_name,p.oid,p.proname as function_name,
           pg_get_function_identity_arguments(p.oid) as identity_args,
           regexp_replace(p.proname,'_v[0-9]+$','') as family_key,
           nullif(substring(p.proname from '_v([0-9]+)$'),'')::int as version_num
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in ('public','private') and p.prokind in ('f','p') and p.proname like 'tgg_%'
  loop
    select count(*) into v_db_refs
    from pg_proc q join pg_namespace nq on nq.oid=q.pronamespace
    where nq.nspname in ('public','private') and q.prokind in ('f','p') and q.oid<>r.oid
      and position(r.function_name in pg_get_functiondef(q.oid)) > 0;

    select count(*) into v_policy_refs
    from pg_policy pol
    where position(r.function_name in coalesce(pg_get_expr(pol.polqual,pol.polrelid),'') || ' ' || coalesce(pg_get_expr(pol.polwithcheck,pol.polrelid),'')) > 0;

    if exists (select 1 from private.tgg_rpc_intentional_version_names i where i.schema_name=r.schema_name and i.function_name=r.function_name and i.keep) then
      v_state:='active';
    elsif r.version_num is not null and v_db_refs=0 and v_policy_refs=0 then
      v_state:='safe_to_retire';
    elsif r.version_num is not null then
      v_state:='consolidate';
    elsif exists (
      select 1 from pg_proc q join pg_namespace nq on nq.oid=q.pronamespace
      where nq.nspname in ('public','private') and nq.nspname<>r.schema_name and q.proname=r.function_name
        and pg_get_function_identity_arguments(q.oid)=r.identity_args
    ) then
      v_state:='wrapper_pair';
    else
      v_state:='active';
    end if;

    insert into private.tgg_rpc_registry(schema_name,function_name,identity_args,family_key,version_num,db_refs,policy_refs,state,notes,last_scanned_at)
    values(r.schema_name,r.function_name,r.identity_args,r.family_key,r.version_num,v_db_refs,v_policy_refs,v_state,
      case when v_policy_refs>0 then 'Referenced by active RLS policies; do not retire without migrating policies.'
           when v_state='safe_to_retire' then 'No database-function or RLS-policy references detected.'
           when v_state='consolidate' then 'Versioned RPC still has dependencies; consolidate before retirement.'
           when v_state='wrapper_pair' then 'Public/private pair preserved pending security-wrapper comparison.'
           else null end, now())
    on conflict(schema_name,function_name,identity_args) do update set
      family_key=excluded.family_key,version_num=excluded.version_num,db_refs=excluded.db_refs,policy_refs=excluded.policy_refs,
      state=case when private.tgg_rpc_registry.state='retired' then 'retired' else excluded.state end,
      notes=excluded.notes,last_scanned_at=now();
    v_count:=v_count+1;
  end loop;

  delete from private.tgg_rpc_registry rr where rr.state<>'retired' and not exists (
    select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname=rr.schema_name and p.proname=rr.function_name
      and pg_get_function_identity_arguments(p.oid)=rr.identity_args);

  insert into public.tgg_code_sync_rpc_state(id,tracked,canonical,consolidate,safe_to_retire,wrapper_pairs,retired,updated_at)
  values(1,(select count(*) from private.tgg_rpc_registry),(select count(*) from private.tgg_rpc_registry where state='canonical'),
    (select count(*) from private.tgg_rpc_registry where state='consolidate'),(select count(*) from private.tgg_rpc_registry where state='safe_to_retire'),
    (select count(*) from private.tgg_rpc_registry where state='wrapper_pair'),(select count(*) from private.tgg_rpc_registry where state='retired'),now())
  on conflict(id) do update set tracked=excluded.tracked,canonical=excluded.canonical,consolidate=excluded.consolidate,safe_to_retire=excluded.safe_to_retire,
    wrapper_pairs=excluded.wrapper_pairs,retired=excluded.retired,updated_at=excluded.updated_at;
  return jsonb_build_object('ok',true,'tracked',v_count,'refreshed_at',now());
end;
$function$


-- [40000000052] function private.tgg_codesync_refresh_workspace_state()
CREATE OR REPLACE FUNCTION private.tgg_codesync_refresh_workspace_state()
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'private', 'public', 'pg_temp'
AS $function$
  insert into public.tgg_code_sync_workspace_state(id,payload,updated_at)
  values (
    1,
    jsonb_build_object(
      'overview',jsonb_build_object(
        'status',(select to_jsonb(s) from public.tgg_code_sync_dashboard_state s where id=1),
        'production',jsonb_build_object(
          'manifest',public.tgg_v5000_production_manifest(),
          'drift',public.tgg_get_production_drift(),
          'workflow_readiness',public.tgg_creator_workflow_readiness(),
          'access_readiness',public.tgg_creator_access_readiness(),
          'external_blockers',public.tgg_external_blockers_final(),
          'optional_upgrades',public.tgg_external_optional_upgrades_final()
        ),
        'edge_functions',jsonb_build_object(
          'total',(select count(*) from private.tgg_edge_function_registry),
          'live',(select count(*) from private.tgg_edge_function_registry where runtime_state='live'),
          'redirected',(select count(*) from private.tgg_edge_function_registry where runtime_state='redirected'),
          'retired',(select count(*) from private.tgg_edge_function_registry where runtime_state='retired_stub'),
          'unknown',(select count(*) from private.tgg_edge_function_registry where runtime_state='unknown'),
          'duplicate_families',(select count(distinct family_key) from private.tgg_edge_function_registry where duplicate_candidate),
          'duplicate_candidates',(select count(*) from private.tgg_edge_function_registry where duplicate_candidate),
          'canonical_functions',(select count(*) from private.tgg_edge_function_registry where canonical),
          'live_v58',(select count(*) from private.tgg_edge_function_registry where slug like 'v58-%' and runtime_state='live'),
          'retired_v58_stubs',(select count(*) from private.tgg_edge_function_registry where slug like 'v58-%' and runtime_state='retired_stub')
        ),
        'rpc',(select to_jsonb(r) from public.tgg_code_sync_rpc_state r where id=1),
        'routes',public.tgg_route_registry_final_health(),
        'schema_cleanup',jsonb_build_object(
          'retired_tables',(select count(*) from private.tgg_table_retirement_log),
          'archived_rows',(select count(*) from private.tgg_table_retirement_rows),
          'v54_tables_remaining',(select count(*) from information_schema.tables where table_schema='public' and table_name like 'v54_%'),
          'v58_tables_remaining',(select count(*) from information_schema.tables where table_schema='public' and table_name like 'v58_%'),
          'v159_present',to_regclass('public.v159_creator_events') is not null,
          'legacy_messaging_tables_remaining',(
            select count(*) from information_schema.tables
            where table_schema='public'
              and table_name in (
                'creator_conversations','creator_conversation_members','creator_messages',
                'conversations','conversation_members','messages',
                'message_attachments','message_reactions','message_reads'
              )
          ),
          'active_v98_tables',(select count(*) from information_schema.tables where table_schema='public' and table_name like 'v98_%')
        ),
        'backup_dedupe',jsonb_build_object(
          'backups',(select count(*) from public.v98_blogger_backups),
          'duplicates_removed',(select count(*) from private.tgg_backup_dedupe_log),
          'duplicate_groups',(
            select count(*) from (
              select connection_id,user_id,resource_type,resource_key,content_hash
              from public.v98_blogger_backups
              group by connection_id,user_id,resource_type,resource_key,content_hash
              having count(*)>1
            ) g
          ),
          'protected_duplicate_rows',(
            with ranked as (
              select
                b.id,
                row_number() over(
                  partition by connection_id,user_id,resource_type,resource_key,content_hash
                  order by created_at desc,id desc
                ) rn,
                count(*) over(
                  partition by connection_id,user_id,resource_type,resource_key,content_hash
                ) copies
              from public.v98_blogger_backups b
            )
            select count(*)
            from ranked r
            where r.copies>1 and r.rn>1
              and exists(select 1 from public.v98_blogger_deployments d where d.backup_id=r.id)
          ),
          'unprotected_duplicate_rows',(
            with baseline_refs as (
              select distinct nullif(x->>'backup_id','')::uuid as backup_id
              from public.tgg_production_baselines b,
                   lateral jsonb_array_elements(
                     coalesce(b.notes#>'{validated_backup_contract,backups}','[]'::jsonb)
                   ) x
              where b.status='locked'
                and nullif(x->>'backup_id','') is not null
            ),
            ranked as (
              select
                b.id,
                row_number() over(
                  partition by connection_id,user_id,resource_type,resource_key,content_hash
                  order by created_at desc,id desc
                ) rn,
                count(*) over(
                  partition by connection_id,user_id,resource_type,resource_key,content_hash
                ) copies
              from public.v98_blogger_backups b
            )
            select count(*)
            from ranked r
            where r.copies>1 and r.rn>1
              and not exists(select 1 from public.v98_blogger_deployments d where d.backup_id=r.id)
              and not exists(select 1 from baseline_refs br where br.backup_id=r.id)
          )
        )
      ),
      'policy',(select to_jsonb(p) from public.tgg_code_sync_policy_state p where id=1),
      'retirement',jsonb_build_object(
        'safe_to_retire',(select count(*) from private.tgg_edge_retirement_manifest where approved_state='ready'),
        'needs_review',(select count(*) from private.tgg_edge_retirement_manifest where approved_state='hold'),
        'retired',(select count(*) from private.tgg_edge_retirement_manifest where approved_state='retired'),
        'total_duplicate_candidates',(select count(*) from private.tgg_edge_retirement_manifest),
        'queue',(
          select coalesce(jsonb_agg(x),'[]'::jsonb)
          from (
            select m.family_key as family,m.slug,m.approved_state as state,m.reference_count as refs,m.canonical_slug
            from private.tgg_edge_retirement_manifest m
            where m.approved_state in ('ready','hold')
            order by case m.approved_state when 'ready' then 0 else 1 end,
                     m.reference_count,m.family_key,m.slug
            limit 100
          ) x
        )
      ),
      'health',private.tgg_codesync_self_check(),
      'issues',(
        select coalesce(jsonb_agg(x),'[]'::jsonb)
        from (
          select issue_key,severity,status,message,details,last_seen_at
          from private.tgg_code_issues
          where status='open'
          order by case severity when 'critical' then 0 when 'error' then 1 when 'warning' then 2 else 3 end,
                   last_seen_at desc
          limit 50
        ) x
      )
    ),
    now()
  )
  on conflict(id) do update set payload=excluded.payload,updated_at=excluded.updated_at;
$function$


-- [40000000053] function private.tgg_codesync_scan_database()
CREATE OR REPLACE FUNCTION private.tgg_codesync_scan_database()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'private', 'public', 'pg_catalog', 'information_schema', 'pg_temp'
AS $function$
declare
  r record;
  v_hash text;
  v_key text;
begin
  for r in
    select
      'db_function'::text as component_type,
      n.nspname || '.' || p.proname as full_name,
      p.proname as object_name,
      pg_get_function_identity_arguments(p.oid) as args,
      pg_get_functiondef(p.oid) as defn
    from pg_proc p
    join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in ('public','private')
      and p.proname like 'tgg_%'
      and p.prokind in ('f','p')
  loop
    v_key := 'db_function:' || r.full_name || '(' || coalesce(r.args,'') || ')';
    v_hash := encode(extensions.digest(r.defn,'sha256'),'hex');

    insert into private.tgg_code_components(
      component_key,component_type,canonical_name,latest_seen_name,content_hash,last_seen_at,last_changed_at,metadata
    )
    values (
      v_key,r.component_type,r.full_name,r.full_name,v_hash,now(),now(),
      jsonb_build_object('args',r.args)
    )
    on conflict(component_key) do update
    set latest_seen_name=excluded.latest_seen_name,
        last_seen_at=now(),
        last_changed_at=case
          when private.tgg_code_components.content_hash is distinct from excluded.content_hash then now()
          else private.tgg_code_components.last_changed_at
        end,
        content_hash=excluded.content_hash,
        metadata=excluded.metadata;

    insert into private.tgg_code_snapshots(component_key,snapshot_hash,snapshot)
    values (v_key,v_hash,jsonb_build_object('name',r.full_name,'args',r.args,'definition',r.defn))
    on conflict do nothing;
  end loop;

  for r in
    select
      'table'::text as component_type,
      table_schema || '.' || table_name as full_name,
      jsonb_agg(
        jsonb_build_object(
          'column',column_name,
          'type',data_type,
          'nullable',is_nullable,
          'default',column_default
        )
        order by ordinal_position
      ) as structure
    from information_schema.columns
    where table_schema in ('public','private')
      and table_name like 'tgg_%'
    group by table_schema,table_name
  loop
    v_key := 'table:' || r.full_name;
    v_hash := encode(extensions.digest(r.structure::text,'sha256'),'hex');

    insert into private.tgg_code_components(
      component_key,component_type,canonical_name,latest_seen_name,content_hash,last_seen_at,last_changed_at,metadata
    )
    values (
      v_key,r.component_type,r.full_name,r.full_name,v_hash,now(),now(),r.structure
    )
    on conflict(component_key) do update
    set last_seen_at=now(),
        last_changed_at=case
          when private.tgg_code_components.content_hash is distinct from excluded.content_hash then now()
          else private.tgg_code_components.last_changed_at
        end,
        content_hash=excluded.content_hash,
        metadata=excluded.metadata;

    insert into private.tgg_code_snapshots(component_key,snapshot_hash,snapshot)
    values (v_key,v_hash,jsonb_build_object('name',r.full_name,'columns',r.structure))
    on conflict do nothing;
  end loop;

  return jsonb_build_object('ok',true,'scanned_at',now());
end;
$function$


-- [40000000054] function private.tgg_codesync_scan_edge_function_metadata()
CREATE OR REPLACE FUNCTION private.tgg_codesync_scan_edge_function_metadata()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'private', 'public', 'pg_temp'
AS $function$
declare
  r record;
  base_name text;
  ver int;
  latest_ver int;
begin
  /*
    Edge Function source is managed by Supabase, not stored in Postgres.
    This scanner tracks known deployed-function names from audit metadata
    and marks obvious version-chain duplicates without deleting them.
  */
  for r in
    select distinct
      regexp_replace(coalesce((details->>'name'), component_key), '^.*:', '') as fn_name
    from private.tgg_code_actions
    where action_type='edge_function_seen'
  loop
    null;
  end loop;

  return jsonb_build_object('ok',true,'scanned_at',now());
end;
$function$


-- [40000000055] function private.tgg_codesync_self_check()
CREATE OR REPLACE FUNCTION private.tgg_codesync_self_check()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'private', 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_last_scan timestamptz;
  v_expected_version int;
  v_expected_hash text;
  v_checkpoint_version int;
  v_checkpoint_hash text;
  v_checkpoint_state text;
  v_live_version int;
  v_live_hash text;
  v_live_checkpoint text;
  v_live_integrity jsonb;
  v_health_refreshed timestamptz;
  v_health_drift_ok boolean:=false;
  v_safe int;
  v_review int;
  v_stale_jobs int;
  v_open int;
begin
  select max(last_seen_at)
  into v_last_scan
  from private.tgg_code_components;

  select deployment_version,source_hash
  into v_expected_version,v_expected_hash
  from private.tgg_edge_function_registry
  where slug='tgg-creator-os-app-v17';

  select
    nullif(m#>>'{runtime,edge_version}','')::int,
    m#>>'{runtime,edge_sha256}',
    m#>>'{recovery,current_version_checkpoint}'
  into v_live_version,v_live_hash,v_live_checkpoint
  from (select public.tgg_v5000_production_manifest() as m) q;

  select public.tgg_v5000_runtime_integrity()
  into v_live_integrity;

  select
    nullif(c.details->>'edge_version','')::int,
    c.control_fingerprint,
    c.state
  into v_checkpoint_version,v_checkpoint_hash,v_checkpoint_state
  from public.tgg_operational_recovery_checkpoints c
  where c.checkpoint_key='creator_os_v5000_live'
  limit 1;

  select refreshed_at,
         coalesce((drift_payload->>'ok')::boolean,false)
  into v_health_refreshed,v_health_drift_ok
  from public.tgg_runtime_health_cache
  where id=1;

  select count(*) filter(where retirement_state='safe_to_retire'),
         count(*) filter(where retirement_state='review')
  into v_safe,v_review
  from private.tgg_edge_function_registry
  where duplicate_candidate;

  select count(*)
  into v_stale_jobs
  from public.tgg_theme_deploy_jobs
  where status in ('claimed','processing')
    and claimed_at < now()-interval '10 minutes';

  if v_last_scan is null or v_last_scan < now()-interval '15 minutes' then
    perform private.tgg_codesync_upsert_issue(
      'codesync:scanner_stale','critical','codesync:controller',
      'Code Sync scanner has not refreshed within the controller cadence.',
      jsonb_build_object('last_scan',v_last_scan)
    );
  else
    update private.tgg_code_issues
    set status='resolved',last_seen_at=now()
    where issue_key='codesync:scanner_stale' and status='open';
  end if;

  if coalesce((v_live_integrity->>'ok')::boolean,false)=false
     or coalesce(v_live_version,0)<>coalesce((v_live_integrity->>'edge_version')::int,0)
     or coalesce(v_live_hash,'')<>coalesce(v_live_integrity->>'fingerprint','')
  then
    perform private.tgg_codesync_upsert_issue(
      'codesync:manifest_drift','error','edge_function:tgg-creator-os-app-v17',
      'Live Creator OS runtime does not match the current production manifest/integrity state.',
      jsonb_build_object(
        'live_manifest_version',v_live_version,
        'live_manifest_hash',v_live_hash,
        'live_checkpoint',v_live_checkpoint,
        'runtime_integrity',v_live_integrity,
        'protected_registry_version',v_expected_version,
        'protected_registry_hash',v_expected_hash,
        'legacy_checkpoint_version',v_checkpoint_version,
        'legacy_checkpoint_hash',v_checkpoint_hash,
        'legacy_checkpoint_state',v_checkpoint_state,
        'protected_registry_mutated',false,
        'legacy_checkpoint_mutated',false
      )
    );
  else
    update private.tgg_code_issues
    set status='resolved',last_seen_at=now(),auto_fixed_at=coalesce(auto_fixed_at,now())
    where issue_key='codesync:manifest_drift' and status='open';
  end if;

  if v_health_refreshed is null
     or v_health_refreshed < now()-interval '15 minutes'
     or not v_health_drift_ok
  then
    perform private.tgg_codesync_upsert_issue(
      'codesync:runtime_health_cache','warning','runtime-health',
      'Cached runtime drift health is stale or unhealthy.',
      jsonb_build_object(
        'refreshed_at',v_health_refreshed,
        'drift_ok',v_health_drift_ok
      )
    );
  else
    update private.tgg_code_issues
    set status='resolved',last_seen_at=now()
    where issue_key='codesync:runtime_health_cache' and status='open';
  end if;

  if v_stale_jobs>0 then
    perform private.tgg_codesync_upsert_issue(
      'codesync:stale_deploy_jobs','warning','deployments',
      'One or more deploy jobs are stuck beyond the recovery threshold.',
      jsonb_build_object('count',v_stale_jobs)
    );
  else
    update private.tgg_code_issues
    set status='resolved',last_seen_at=now()
    where issue_key='codesync:stale_deploy_jobs' and status='open';
  end if;

  select count(*) into v_open
  from private.tgg_code_issues
  where status='open';

  return jsonb_build_object(
    'ok',v_open=0,
    'version','CODESYNC-SELF-CHECK-ONE-FINAL-1.2',
    'last_scan',v_last_scan,
    'safe_to_retire',v_safe,
    'needs_review',v_review,
    'stale_deploy_jobs',v_stale_jobs,
    'open_issues',v_open,
    'health_cache_refreshed_at',v_health_refreshed,
    'health_cache_drift_ok',v_health_drift_ok,
    'full_production_manifest_called',true,
    'live_manifest_validation',true,
    'canonical_version',v_expected_version,
    'canonical_hash',v_expected_hash,
    'protected_registry_version',v_expected_version,
    'protected_registry_hash',v_expected_hash,
    'live_version',v_live_version,
    'live_hash',v_live_hash,
    'live_checkpoint',v_live_checkpoint,
    'protected_registry_mutated',false,
    'legacy_checkpoint_mutated',false,
    'checked_at',now()
  );
end
$function$


-- [40000000056] function private.tgg_codesync_source_integrity()
CREATE OR REPLACE FUNCTION private.tgg_codesync_source_integrity()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_expected_version int;
  v_expected_hash text;
  v_seen_version int;
  v_seen_hash text;
  v_ok boolean:=true;
  v_failures jsonb:='[]'::jsonb;
begin
  select
    nullif(m#>>'{runtime,edge_version}','')::int,
    m#>>'{runtime,edge_sha256}'
  into v_expected_version,v_expected_hash
  from (select public.tgg_v5000_production_manifest() as m) q;

  select latest_seen_version,content_hash
    into v_seen_version,v_seen_hash
  from private.tgg_code_components
  where component_key='edge:tgg-creator-os-app-v17'
     or canonical_name='tgg-creator-os-app-v17'
  order by last_seen_at desc
  limit 1;

  if v_seen_version is not null and v_seen_version<>v_expected_version then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('creator_os_component_version_mismatch');
  end if;

  if coalesce(v_seen_hash,'')<>'' and v_seen_hash<>v_expected_hash then
    v_ok:=false;
    v_failures:=v_failures||jsonb_build_array('creator_os_component_hash_mismatch');
  end if;

  if v_ok then
    update private.tgg_code_issues
    set status='resolved',last_seen_at=now()
    where issue_key='codesync:source_integrity' and status='open';
  else
    perform private.tgg_codesync_upsert_issue(
      'codesync:source_integrity',
      'error',
      'edge_function:tgg-creator-os-app-v17',
      'A copied or indexed Creator OS source no longer matches the live production manifest.',
      jsonb_build_object(
        'expected_version',v_expected_version,
        'expected_hash',v_expected_hash,
        'seen_version',v_seen_version,
        'seen_hash',v_seen_hash,
        'failures',v_failures
      )
    );
  end if;

  return jsonb_build_object(
    'ok',v_ok,
    'expected_version',v_expected_version,
    'expected_hash',v_expected_hash,
    'seen_version',v_seen_version,
    'seen_hash',v_seen_hash,
    'failures',v_failures,
    'checked_at',now()
  );
end;
$function$


-- [40000000057] function private.tgg_codesync_tick()
CREATE OR REPLACE FUNCTION private.tgg_codesync_tick()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  a jsonb;
  b jsonb;
  c jsonb;
  d jsonb;
  f jsonb;
  g jsonb;
  h jsonb;
  v_rpc_tracked integer:=0;
  v_rpc_refreshed timestamptz;
  v_removed_history_jobs integer:=0;
  v_removed_completed_once_jobs integer:=0;
  v_jobid bigint;
begin
  -- Self-heal redundant standalone activation-history cron.
  for v_jobid in
    select jobid
    from cron.job
    where jobname='tgg-one-final-activation-history'
  loop
    perform cron.unschedule(v_jobid);
    v_removed_history_jobs:=v_removed_history_jobs+1;
  end loop;

  -- Self-heal recurring jobs explicitly named "once" after they have
  -- already completed at least one successful run.
  for v_jobid in
    select j.jobid
    from cron.job j
    where j.active
      and lower(coalesce(j.jobname,'')) like '%once%'
      and exists(
        select 1
        from cron.job_run_details d
        where d.jobid=j.jobid
          and d.status='succeeded'
          and d.end_time is not null
      )
  loop
    perform cron.unschedule(v_jobid);
    v_removed_completed_once_jobs:=v_removed_completed_once_jobs+1;
  end loop;

  a:=private.tgg_codesync_scan_database();
  b:=private.tgg_codesync_detect_and_fix();
  perform private.tgg_codesync_audit_edge_dependencies();
  perform private.tgg_codesync_refresh_retirement_manifest();
  d:=private.tgg_codesync_detect_new_edge_duplicates();

  select coalesce(tracked,0),updated_at
  into v_rpc_tracked,v_rpc_refreshed
  from public.tgg_code_sync_rpc_state
  where id=1;

  f:=private.tgg_codesync_known_regressions();
  g:=private.tgg_codesync_operational_cleanup();
  h:=private.tgg_codesync_source_integrity();
  c:=private.tgg_codesync_self_check();
  perform private.tgg_codesync_refresh_dashboard();
  perform private.tgg_codesync_refresh_policy_state();
  perform private.tgg_codesync_refresh_workspace_state();

  return jsonb_build_object(
    'version','CODESYNC-TICK-ONE-FINAL-1.3',
    'scan',a,
    'repair',b,
    'duplicate_guard',d,
    'redundant_history_jobs_removed',v_removed_history_jobs,
    'completed_once_jobs_removed',v_removed_completed_once_jobs,
    'rpc_registry',jsonb_build_object(
      'tracked',v_rpc_tracked,
      'last_refreshed_at',v_rpc_refreshed,
      'refresh_inline',false,
      'dedicated_job','tgg-codesync-rpc-registry-refresh'
    ),
    'regression_guard',f,
    'operational_cleanup',g,
    'source_integrity',h,
    'health',c,
    'tick_at',now()
  );
end
$function$


-- [40000000058] function private.tgg_codesync_upsert_issue(p_issue_key text, p_severity text, p_component_key text, p_message text, p_details jsonb)
CREATE OR REPLACE FUNCTION private.tgg_codesync_upsert_issue(p_issue_key text, p_severity text, p_component_key text, p_message text, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'private', 'public', 'pg_temp'
AS $function$
  insert into private.tgg_code_issues(issue_key,severity,component_key,message,details)
  values (p_issue_key,p_severity,p_component_key,p_message,p_details)
  on conflict(issue_key) do update
  set severity=excluded.severity,
      component_key=excluded.component_key,
      message=excluded.message,
      details=excluded.details,
      last_seen_at=now(),
      status=case
        when private.tgg_code_issues.status in ('resolved','auto_fixed') then 'open'
        else private.tgg_code_issues.status
      end;
$function$


-- [40000000059] function private.tgg_codesync_validate_edge_name(p_slug text)
CREATE OR REPLACE FUNCTION private.tgg_codesync_validate_edge_name(p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'private', 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_family text;
  v_policy private.tgg_edge_deployment_policy%rowtype;
begin
  v_family := regexp_replace(
    regexp_replace(
      regexp_replace(p_slug,'-v[0-9]+$',''),
      '-staging$',''
    ),
    '-sandbox$',''
  );

  select * into v_policy
  from private.tgg_edge_deployment_policy
  where family_key=v_family;

  if found and v_policy.update_in_place and not v_policy.allow_versioned_siblings
     and p_slug<>v_policy.canonical_slug then
    return jsonb_build_object(
      'ok',false,
      'action','update_existing',
      'requested_slug',p_slug,
      'family_key',v_family,
      'canonical_slug',v_policy.canonical_slug,
      'reason','duplicate_version_slug_blocked'
    );
  end if;

  return jsonb_build_object(
    'ok',true,
    'action',case when found then 'update_existing' else 'new_family' end,
    'requested_slug',p_slug,
    'family_key',v_family,
    'canonical_slug',coalesce(v_policy.canonical_slug,p_slug)
  );
end;
$function$


-- [40000000060] function private.tgg_complete_dynamic_event(p_character_id uuid, p_dynamic_event_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_complete_dynamic_event(p_character_id uuid, p_dynamic_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_event public.tgg_world_dynamic_events%rowtype;
  v_template public.tgg_world_dynamic_event_templates%rowtype;
  v_state public.tgg_world_character_event_state%rowtype;
  v_reward jsonb:='{}'::jsonb;
  v_crew_bonus jsonb:='{}'::jsonb;
  v_resolution jsonb:='{}'::jsonb;
  v_outcome_key text:='success';
  v_event_id uuid;
  v_npc text;
  v_contact text;
  v_relationship_xp integer:=0;
  v_business_id uuid;
  v_crew_id uuid;
  v_business_xp integer:=0;
  v_crew_xp integer:=0;
  v_crew_rep_delta integer:=0;
  v_rep_delta integer:=0;
  v_rivalry_delta integer:=0;
  v_loyalty_delta integer:=0;
  v_rare_gig_bonus numeric:=0;
  v_unlock_weight_bonus numeric:=0;
  v_payload jsonb:='{}'::jsonb;
  v_min_seconds integer:=60;
  v_ready_at timestamptz;
  v_current_location text;
  v_relation_a uuid;
  v_relation_b uuid;
  v_relation_rivalry integer:=0;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  if not exists(
    select 1 from public.world_characters
    where id=p_character_id and user_id=v_uid and character_status='active'
  ) then
    raise exception 'character ownership mismatch';
  end if;

  select * into v_event
  from public.tgg_world_dynamic_events
  where id=p_dynamic_event_id
    and status='active'
    and ends_at>now();

  if v_event.id is null then raise exception 'event unavailable'; end if;

  select * into v_state
  from public.tgg_world_character_event_state
  where character_id=p_character_id
    and dynamic_event_id=p_dynamic_event_id
    and status='joined'
  for update;

  if v_state.character_id is null then raise exception 'join event first'; end if;

  select * into v_template
  from public.tgg_world_dynamic_event_templates
  where event_key=v_event.event_key and enabled=true;

  if v_template.event_key is null then raise exception 'event template unavailable'; end if;

  select l.location_key into v_current_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=p_character_id;

  if v_current_location is distinct from v_event.location_key then
    raise exception 'return to % before completing this event',v_event.location_key;
  end if;

  v_min_seconds:=coalesce(
    nullif((v_state.progress->>'min_participation_seconds')::integer,0),
    nullif((v_template.metadata->>'min_participation_seconds')::integer,0),
    least(120,greatest(30,v_template.duration_minutes*3))
  );

  v_ready_at:=coalesce(
    nullif(v_state.progress->>'ready_at','')::timestamptz,
    v_state.joined_at+make_interval(secs=>v_min_seconds)
  );

  if v_state.joined_at is null then raise exception 'event join timestamp missing'; end if;

  if now()<v_ready_at then
    raise exception 'event participation not ready; % seconds remaining',
      greatest(ceil(extract(epoch from (v_ready_at-now())))::integer,1);
  end if;

  v_resolution:=private.tgg_world_dynamic_event_resolution(
    p_character_id,p_dynamic_event_id
  );
  v_outcome_key:=coalesce(v_resolution->>'outcome_key','success');
  v_reward:=coalesce(v_resolution->'reward','{}'::jsonb);

  if v_outcome_key in ('success','win') then
    v_crew_bonus:=coalesce(v_template.outcomes->'crew_bonus','{}'::jsonb);
  end if;

  v_npc:=case
    when cardinality(v_template.npc_keys)>0 then v_template.npc_keys[1]
    else null
  end;

  if v_npc is not null then
    select i.contact_key into v_contact
    from public.tgg_world_npc_profiles n
    join public.tgg_world_industry_contacts i
      on lower(i.display_name)=lower(n.display_name)
     and i.enabled=true
    where n.npc_key=v_npc
    limit 1;
  end if;

  v_rep_delta:=coalesce((v_reward->>'reputation')::integer,0);
  v_relationship_xp:=greatest(coalesce((v_reward->>'relationship_xp')::integer,0),0);
  v_business_xp:=greatest(coalesce((v_reward->>'business_xp')::integer,0),0);
  v_crew_xp:=greatest(
    coalesce((v_reward->>'crew_xp')::integer,0)
    +coalesce((v_crew_bonus->>'crew_xp')::integer,0),
    0
  );
  v_crew_rep_delta:=coalesce((v_reward->>'crew_reputation')::integer,0);
  v_rivalry_delta:=coalesce((v_reward->>'rivalry')::integer,0);
  v_loyalty_delta:=coalesce((v_reward->>'loyalty')::integer,0);
  v_rare_gig_bonus:=greatest(coalesce((v_reward->>'rare_gig_bonus')::numeric,0),0);
  v_unlock_weight_bonus:=greatest(coalesce((v_reward->>'unlock_weight_bonus')::numeric,0),0);

  if v_business_xp>0 then
    select id into v_business_id
    from public.tgg_world_character_businesses
    where character_id=p_character_id and status='active'
    order by business_level desc,updated_at desc
    limit 1;
  end if;

  if v_crew_xp<>0 or v_crew_rep_delta<>0 or
     (v_template.event_type='crew_event' and v_rivalry_delta<>0) then
    select crew_id into v_crew_id
    from public.tgg_world_crew_members
    where character_id=p_character_id and user_id=v_uid and left_at is null
    order by joined_at desc
    limit 1;
  end if;

  if v_rep_delta<0 then
    update public.tgg_world_career_reputation cr
    set reputation=greatest(cr.reputation+v_rep_delta,0),
        tier=greatest(1,1+(greatest(cr.reputation+v_rep_delta,0)/25)),
        updated_at=now()
    from public.world_characters wc
    where wc.id=p_character_id
      and cr.character_id=wc.id
      and cr.career_key=wc.active_career;
  end if;

  if v_relationship_xp>0 and v_contact is not null then
    insert into public.tgg_world_contact_relationships(
      character_id,contact_key,relationship_xp,relationship_level,trust_score,
      meetings_completed,successful_contracts,last_interaction_at,memory,updated_at
    )
    values(
      p_character_id,v_contact,v_relationship_xp,
      greatest(1,1+(v_relationship_xp/100)),0,0,0,now(),
      jsonb_build_object('last_dynamic_event',v_template.event_key),now()
    )
    on conflict(character_id,contact_key) do update
    set relationship_xp=public.tgg_world_contact_relationships.relationship_xp+v_relationship_xp,
        relationship_level=greatest(
          public.tgg_world_contact_relationships.relationship_level,
          1+((public.tgg_world_contact_relationships.relationship_xp+v_relationship_xp)/100)
        ),
        last_interaction_at=now(),
        memory=public.tgg_world_contact_relationships.memory
          ||jsonb_build_object('last_dynamic_event',v_template.event_key),
        updated_at=now();

    insert into public.tgg_world_relationship_events(
      character_id,contact_key,event_type,delta_xp,delta_trust,
      source_type,source_key,memory_patch,created_at
    )
    values(
      p_character_id,v_contact,'dynamic_event_reward',v_relationship_xp,0,
      'dynamic_event',v_template.event_key,
      jsonb_build_object('dynamic_event_id',v_event.id,'outcome_key',v_outcome_key),now()
    );
  end if;

  if v_template.event_type='crew_event' and v_crew_id is not null and v_rivalry_delta<>0 then
    select r.crew_a_id,r.crew_b_id,r.rivalry
    into v_relation_a,v_relation_b,v_relation_rivalry
    from public.tgg_world_crew_relations r
    where r.crew_a_id=v_crew_id or r.crew_b_id=v_crew_id
    order by r.rivalry desc,r.updated_at desc
    limit 1
    for update;

    if v_relation_a is not null then
      update public.tgg_world_crew_relations
      set rivalry=least(100,greatest(0,rivalry+v_rivalry_delta)),
          relation_type=case
            when least(100,greatest(0,rivalry+v_rivalry_delta))>=30 then 'rival'
            when relation_type='rival' and least(100,greatest(0,rivalry+v_rivalry_delta))<30 then 'neutral'
            else relation_type
          end,
          updated_at=now()
      where crew_a_id=v_relation_a and crew_b_id=v_relation_b;
    end if;

  elsif v_npc is not null and (v_rivalry_delta<>0 or v_loyalty_delta<>0) then
    insert into public.tgg_world_character_npc_standing(
      character_id,npc_key,standing,rivalry,loyalty,
      blocked_opportunities,favored_opportunities,memory,updated_at
    )
    values(
      p_character_id,v_npc,0,
      least(100,greatest(0,v_rivalry_delta)),
      least(100,greatest(0,v_loyalty_delta)),
      '[]'::jsonb,'[]'::jsonb,
      jsonb_build_object('last_dynamic_event',v_template.event_key,'outcome_key',v_outcome_key),
      now()
    )
    on conflict(character_id,npc_key) do update
    set rivalry=least(100,greatest(0,
          public.tgg_world_character_npc_standing.rivalry+v_rivalry_delta)),
        loyalty=least(100,greatest(0,
          public.tgg_world_character_npc_standing.loyalty+v_loyalty_delta)),
        memory=public.tgg_world_character_npc_standing.memory
          ||jsonb_build_object('last_dynamic_event',v_template.event_key,'outcome_key',v_outcome_key),
        updated_at=now();
  end if;

  if v_crew_id is not null and v_crew_rep_delta<>0 then
    insert into public.tgg_world_crew_progression(
      crew_id,crew_xp,rank_level,reputation,unlocks,updated_at
    )
    values(
      v_crew_id,0,1,greatest(v_crew_rep_delta,0),'{}'::jsonb,now()
    )
    on conflict(crew_id) do update
    set reputation=greatest(
          0,public.tgg_world_crew_progression.reputation+v_crew_rep_delta
        ),
        updated_at=now();
  end if;

  if v_rare_gig_bonus>0 then
    insert into public.tgg_world_character_modifiers(
      character_id,modifier_key,numeric_value,source_type,source_key,metadata
    )
    values(
      p_character_id,'rare_gig_bonus',v_rare_gig_bonus,
      'dynamic_event',v_event.id::text,
      jsonb_build_object('event_key',v_template.event_key,'outcome_key',v_outcome_key)
    )
    on conflict(character_id,modifier_key,source_type,source_key) do nothing;
  end if;

  if v_unlock_weight_bonus>0 then
    insert into public.tgg_world_character_modifiers(
      character_id,modifier_key,numeric_value,source_type,source_key,metadata
    )
    values(
      p_character_id,'unlock_weight_bonus',v_unlock_weight_bonus,
      'dynamic_event',v_event.id::text,
      jsonb_build_object('event_key',v_template.event_key,'outcome_key',v_outcome_key)
    )
    on conflict(character_id,modifier_key,source_type,source_key) do nothing;
  end if;

  v_payload:=jsonb_strip_nulls(jsonb_build_object(
    'career_xp',greatest(coalesce((v_reward->>'career_xp')::integer,0),0),
    'reputation',greatest(v_rep_delta,0),
    'season_xp',greatest(coalesce((v_reward->>'season_xp')::integer,0),0),
    'business_xp',v_business_xp,
    'business_id',v_business_id,
    'crew_xp',v_crew_xp,
    'crew_id',v_crew_id,
    'npc_key',v_npc
  ));

  v_event_id:=private.tgg_apply_progression_event(
    p_character_id,
    'dynamic_event_completed',
    v_template.event_key,
    v_payload
  );

  if v_template.event_type in ('nightlife','nightlife_event')
     or v_template.trigger_mode='night-window' then
    perform private.tgg_world_credit_challenge_event(
      p_character_id,'night_events_completed','dynamic_event',v_event.id::text
    );
    perform private.tgg_world_credit_faction_mission_event(
      p_character_id,
      'night_events',
      'dynamic_event',
      v_event.id::text,
      jsonb_build_object(
        'event_key',v_template.event_key,
        'event_type',v_template.event_type,
        'outcome_key',v_outcome_key
      )
    );
  end if;

  if v_template.event_key='event-city-festival'
     and v_template.location_key='the-park'
     and v_outcome_key in ('success','win') then
    perform private.tgg_world_credit_faction_mission_event(
      p_character_id,
      'community_wins',
      'dynamic_event',
      v_event.id::text,
      jsonb_build_object(
        'event_key',v_template.event_key,
        'community_event',true,
        'outcome_key',v_outcome_key
      )
    );
  end if;

  update public.tgg_world_character_event_state
  set status='completed',
      outcome=jsonb_build_object(
        'result',v_outcome_key,
        'resolution',v_resolution,
        'rewards',v_reward,
        'crew_bonus',v_crew_bonus,
        'relationship_xp_applied',v_relationship_xp,
        'reputation_delta',v_rep_delta,
        'rivalry_delta',v_rivalry_delta,
        'loyalty_delta',v_loyalty_delta,
        'crew_reputation_delta',v_crew_rep_delta,
        'modifier_rewards',jsonb_strip_nulls(jsonb_build_object(
          'rare_gig_bonus',case when v_rare_gig_bonus>0 then v_rare_gig_bonus else null end,
          'unlock_weight_bonus',case when v_unlock_weight_bonus>0 then v_unlock_weight_bonus else null end
        )),
        'business_id',v_business_id,
        'crew_id',v_crew_id
      ),
      completed_at=now(),
      updated_at=now()
  where character_id=p_character_id
    and dynamic_event_id=p_dynamic_event_id;

  perform private.tgg_recompute_progression(p_character_id);

  return jsonb_build_object(
    'event_id',v_event.id,
    'event_key',v_template.event_key,
    'completed',true,
    'outcome_key',v_outcome_key,
    'resolution',v_resolution,
    'rewards',v_reward,
    'crew_bonus',v_crew_bonus,
    'relationship_xp_applied',v_relationship_xp,
    'reputation_delta',v_rep_delta,
    'rivalry_delta',v_rivalry_delta,
    'loyalty_delta',v_loyalty_delta,
    'crew_reputation_delta',v_crew_rep_delta,
    'business_xp_target',v_business_id,
    'crew_xp_target',v_crew_id,
    'effective_modifiers',private.tgg_world_effective_modifiers(p_character_id),
    'progression_event_id',v_event_id
  );
end;
$function$


-- [40000000061] function private.tgg_completed_provider_handoff_consistency_check()
CREATE OR REPLACE FUNCTION private.tgg_completed_provider_handoff_consistency_check()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with bad as (
  select provider_key,status,required_action
  from public.tgg_provider_handoff
  where status='complete'
    and (
      required_action ilike 'Reauthorize %'
      or required_action ilike 'Enter the real %'
      or required_action ilike 'Complete one real %'
      or required_action ilike 'Enable %'
    )
)
select jsonb_build_object(
  'ok',not exists(select 1 from bad),
  'version','COMPLETED-HANDOFF-CONSISTENCY-1.1',
  'mismatch_count',(select count(*) from bad),
  'mismatches',coalesce((select jsonb_agg(to_jsonb(b) order by provider_key) from bad b),'[]'::jsonb),
  'checked_at',now()
);
$function$


-- [40000000062] function private.tgg_create_collaboration_notification()
CREATE OR REPLACE FUNCTION private.tgg_create_collaboration_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_recipient uuid; v_actor uuid; v_title text; v_body text; v_enabled boolean:=true; begin if tg_op='INSERT' then v_recipient:=new.recipient_id; v_actor:=new.sender_id; v_title:='New collaboration request'; v_body:='You received a collaboration request for '||new.project_title||'.'; elsif tg_op='UPDATE' and old.status='pending' and new.status in ('accepted','declined') then v_recipient:=new.sender_id; v_actor:=new.recipient_id; v_title:=case new.status when 'accepted' then 'Collaboration accepted' else 'Collaboration declined' end; v_body:='Your collaboration request for '||new.project_title||' was '||new.status||'.'; else return new; end if; select coalesce(p.collaboration_enabled,true) into v_enabled from public.notification_preferences p where p.user_id=v_recipient; if v_enabled=false then return new; end if; if not exists(select 1 from public.notifications n where n.recipient_id=v_recipient and n.actor_id=v_actor and n.notification_type='collaboration_'||new.status and n.entity_id=new.id and n.created_at>now()-interval '10 minutes') then insert into public.notifications(recipient_id,actor_id,notification_type,entity_type,entity_id,title,body) values(v_recipient,v_actor,case when tg_op='INSERT' then 'collaboration_request' else 'collaboration_'||new.status end,'collaboration',new.id,v_title,v_body); end if; return new; end $function$


-- [40000000063] function private.tgg_create_community_notification()
CREATE OR REPLACE FUNCTION private.tgg_create_community_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_recipient uuid; v_title text; v_body text; v_type text; v_entity_type text; v_entity_id uuid; v_enabled boolean:=true; begin if tg_table_name='artist_follows' then select a.user_id into v_recipient from public.artists a where a.id=new.artist_id; v_type:='artist_follow';v_entity_type:='artist';v_entity_id:=new.artist_id;v_title:='New follower';v_body:='Someone followed your artist profile.'; if v_recipient is not null then select coalesce(p.follows_enabled,true) into v_enabled from public.notification_preferences p where p.user_id=v_recipient; end if; elsif tg_table_name='release_saves' then select m.user_id into v_recipient from public.mixtapes m where m.id=new.mixtape_id; v_type:='release_save';v_entity_type:='mixtape';v_entity_id:=new.mixtape_id;v_title:='Release saved';v_body:='Someone saved your release.'; if v_recipient is not null then select coalesce(p.saves_enabled,true) into v_enabled from public.notification_preferences p where p.user_id=v_recipient; end if; elsif tg_table_name='release_reactions' then select m.user_id into v_recipient from public.mixtapes m where m.id=new.mixtape_id; v_type:='release_reaction';v_entity_type:='mixtape';v_entity_id:=new.mixtape_id;v_title:='New reaction';v_body:='Someone reacted to your release.'; if v_recipient is not null then select coalesce(p.reactions_enabled,true) into v_enabled from public.notification_preferences p where p.user_id=v_recipient; end if; elsif tg_table_name='release_comments' then select m.user_id into v_recipient from public.mixtapes m where m.id=new.mixtape_id; v_type:='release_comment';v_entity_type:='comment';v_entity_id:=new.id;v_title:='New comment';v_body:='Someone commented on your release.'; if v_recipient is not null then select coalesce(p.comments_enabled,true) into v_enabled from public.notification_preferences p where p.user_id=v_recipient; end if; else return new; end if; if v_recipient is null or v_recipient=new.user_id or v_enabled=false then return new; end if; if not exists(select 1 from public.notifications n where n.recipient_id=v_recipient and n.actor_id=new.user_id and n.notification_type=v_type and n.entity_type=v_entity_type and n.entity_id=v_entity_id and n.created_at>now()-interval '10 minutes') then insert into public.notifications(recipient_id,actor_id,notification_type,entity_type,entity_id,title,body) values(v_recipient,new.user_id,v_type,v_entity_type,v_entity_id,v_title,v_body); end if; return new; end $function$


-- [40000000064] function private.tgg_create_membership_payment_link_claim(p_tier_id uuid, p_fan_user_id uuid, p_request_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_create_membership_payment_link_claim(p_tier_id uuid, p_fan_user_id uuid, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tier record;
  v_claim uuid;
begin
  if p_tier_id is null or p_fan_user_id is null then
    raise exception 'MEMBERSHIP_CLAIM_INPUT_REQUIRED' using errcode='22023';
  end if;

  select
    t.id,t.artist_id,t.name,t.price_cents,t.is_active,t.stripe_payment_link_url,
    t.stripe_payment_link_verified,t.stripe_payment_link_verified_at,
    a.user_id as artist_user_id,a.stage_name
  into v_tier
  from public.tgg_membership_tiers t
  join public.artists a on a.id=t.artist_id
  where t.id=p_tier_id;

  if not found or not v_tier.is_active then
    raise exception 'MEMBERSHIP_TIER_NOT_AVAILABLE' using errcode='P0001';
  end if;

  if v_tier.artist_user_id=p_fan_user_id then
    raise exception 'CREATOR_CANNOT_JOIN_OWN_MEMBERSHIP' using errcode='P0001';
  end if;

  if not coalesce(v_tier.stripe_payment_link_verified,false) then
    raise exception 'MEMBERSHIP_PAYMENT_LINK_NOT_VERIFIED' using errcode='P0001';
  end if;

  if nullif(btrim(coalesce(v_tier.stripe_payment_link_url,'')),'') is null
     or v_tier.stripe_payment_link_url !~ '^https://buy\.stripe\.com/' then
    raise exception 'MEMBERSHIP_PAYMENT_LINK_NOT_CONFIGURED' using errcode='P0001';
  end if;

  if exists (
    select 1
    from public.tgg_memberships m
    where m.artist_id=v_tier.artist_id
      and m.fan_user_id=p_fan_user_id
      and m.status in ('active','pending','paused')
  ) then
    raise exception 'MEMBERSHIP_ALREADY_EXISTS' using errcode='P0001';
  end if;

  update private.tgg_membership_payment_link_claims
  set status='expired'
  where fan_user_id=p_fan_user_id
    and tier_id=p_tier_id
    and status='pending'
    and expires_at<=now();

  insert into private.tgg_membership_payment_link_claims(
    tier_id,artist_id,fan_user_id,request_id
  )
  values(p_tier_id,v_tier.artist_id,p_fan_user_id,p_request_id)
  returning claim_id into v_claim;

  return jsonb_build_object(
    'claim_id',v_claim,
    'client_reference_id','tggmem_'||replace(v_claim::text,'-','_'),
    'tier_id',v_tier.id,
    'artist_id',v_tier.artist_id,
    'artist_name',v_tier.stage_name,
    'tier_name',v_tier.name,
    'price_cents',v_tier.price_cents,
    'payment_link_url',v_tier.stripe_payment_link_url,
    'payment_link_verified',true,
    'expires_at',now()+interval '45 minutes'
  );
end
$function$


-- [40000000065] function private.tgg_create_world_character(p_stage_name text, p_career_key text, p_avatar_config jsonb)
CREATE OR REPLACE FUNCTION private.tgg_create_world_character(p_stage_name text, p_career_key text DEFAULT 'artist'::text, p_avatar_config jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_character uuid;
  v_location uuid;
  v_stage text := btrim(coalesce(p_stage_name,''));
  v_avatar jsonb := coalesce(p_avatar_config,'{}'::jsonb);
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if char_length(v_stage) < 2 or char_length(v_stage) > 40 then raise exception 'stage name must be 2 to 40 characters'; end if;
  if v_stage !~ '^[[:alnum:]][[:alnum:] ._''-]*$' then raise exception 'stage name contains unsupported characters'; end if;
  if jsonb_typeof(v_avatar) <> 'object' then raise exception 'avatar_config must be a JSON object'; end if;
  if not exists(select 1 from public.tgg_world_career_tracks where career_key=p_career_key and enabled=true) then raise exception 'invalid career'; end if;

  select id into v_location from public.tgg_world_locations where location_key='starter-apartment' limit 1;
  if v_location is null then raise exception 'starter apartment is not configured'; end if;

  select id into v_character from public.world_characters where user_id=v_uid limit 1;

  if v_character is not null then
    update public.world_characters
    set stage_name=v_stage,avatar_config=v_avatar,active_career=p_career_key,
        character_status='active',current_location_id=coalesce(current_location_id,v_location),updated_at=now()
    where id=v_character and user_id=v_uid;
  else
    insert into public.world_characters(user_id,stage_name,avatar_config,active_career,current_location_id,character_status)
    values(v_uid,v_stage,v_avatar,p_career_key,v_location,'active')
    returning id into v_character;
  end if;

  insert into public.world_character_careers(character_id,career_key,career_level,career_xp,unlocked,metadata,updated_at)
  values(v_character,p_career_key,1,0,true,jsonb_build_object('source','character_creation'),now())
  on conflict(character_id,career_key) do update set unlocked=true,updated_at=now();

  insert into public.world_character_stats(character_id,stat_key,stat_value,updated_at)
  values(v_character,'energy',100,now()),(v_character,'focus',100,now()),(v_character,'confidence',50,now())
  on conflict(character_id,stat_key) do nothing;

  insert into public.tgg_world_character_onboarding(character_id,current_step_order,status,completed_steps,updated_at)
  values(v_character,1,'active','{}',now())
  on conflict(character_id) do update
  set status=case when public.tgg_world_character_onboarding.status='completed' then 'completed' else 'active' end,
      updated_at=now();

  perform private.tgg_world_onboarding_event(v_character,'world_entered','starter-apartment');
  perform private.tgg_world_onboarding_event(v_character,'career_selected',p_career_key);

  perform private.tgg_world_wallet_ensure_impl();
  perform private.tgg_rotate_challenges(v_character);

  return v_character;
end;
$function$


-- [40000000066] function private.tgg_creator_account_lifecycle_cancel_internal(p_request_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_creator_account_lifecycle_cancel_internal(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_request public.tgg_creator_account_lifecycle_requests;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  update public.tgg_creator_account_lifecycle_requests
  set status='cancelled',cancelled_at=now()
  where id=p_request_id
    and owner_user_id=v_uid
    and status='pending'
  returning * into v_request;

  if v_request.id is null then
    raise exception 'PENDING_ACCOUNT_REQUEST_NOT_FOUND' using errcode='P0002';
  end if;

  insert into private.tgg_creator_mutation_audit(actor_id,action_key,target_id,metadata)
  values(
    v_uid,
    'account_lifecycle_'||v_request.request_type||'_cancelled',
    v_request.id::text,
    jsonb_build_object(
      'operation','cancel',
      'status_before','pending',
      'status_after','cancelled',
      'request_type',v_request.request_type
    )
  );

  return jsonb_build_object(
    'ok',true,
    'request_id',v_request.id,
    'request_type',v_request.request_type,
    'status',v_request.status,
    'cancelled_at',v_request.cancelled_at
  );
end
$function$


-- [40000000067] function private.tgg_creator_account_lifecycle_request_internal(p_request_type text, p_confirmation text)
CREATE OR REPLACE FUNCTION private.tgg_creator_account_lifecycle_request_internal(p_request_type text, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_type text:=lower(trim(coalesce(p_request_type,'')));
  v_confirmation text:=trim(coalesce(p_confirmation,''));
  v_expected text;
  v_readiness jsonb;
  v_request public.tgg_creator_account_lifecycle_requests;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_type not in ('archive','delete') then
    raise exception 'ACCOUNT_LIFECYCLE_TYPE_INVALID' using errcode='22023';
  end if;

  v_expected:=case when v_type='archive' then 'ARCHIVE MY ACCOUNT' else 'DELETE MY ACCOUNT' end;
  if v_confirmation<>v_expected then
    raise exception 'ACCOUNT_LIFECYCLE_CONFIRMATION_REQUIRED' using errcode='22023';
  end if;

  v_readiness:=public.tgg_creator_archive_readiness();
  if coalesce((v_readiness->>'ready')::boolean,false)=false then
    return jsonb_build_object(
      'ok',false,
      'reason','blockers_present',
      'request_type',v_type,
      'readiness',v_readiness
    );
  end if;

  select * into v_request
  from public.tgg_creator_account_lifecycle_requests
  where owner_user_id=v_uid and request_type=v_type and status='pending'
  order by requested_at desc
  limit 1;

  if v_request.id is not null then
    return jsonb_build_object(
      'ok',true,'already_pending',true,
      'request',jsonb_build_object(
        'id',v_request.id,'request_type',v_request.request_type,'status',v_request.status,
        'requested_at',v_request.requested_at,'execute_after',v_request.execute_after
      )
    );
  end if;

  insert into public.tgg_creator_account_lifecycle_requests(
    owner_user_id,request_type,status,execute_after,metadata
  )
  values(
    v_uid,
    v_type,
    'pending',
    case when v_type='archive' then now()+interval '24 hours' else now()+interval '7 days' end,
    jsonb_build_object(
      'readiness_version',v_readiness->>'version',
      'request_source','creator_os_account_panel',
      'destructive_execution_deferred',true
    )
  )
  returning * into v_request;

  insert into private.tgg_creator_mutation_audit(actor_id,action_key,target_id,metadata)
  values(
    v_uid,
    'account_lifecycle_'||v_type||'_requested',
    v_request.id::text,
    jsonb_build_object(
      'operation','request',
      'status_after','pending',
      'request_type',v_type,
      'execute_after',v_request.execute_after
    )
  );

  return jsonb_build_object(
    'ok',true,'already_pending',false,
    'request',jsonb_build_object(
      'id',v_request.id,'request_type',v_request.request_type,'status',v_request.status,
      'requested_at',v_request.requested_at,'execute_after',v_request.execute_after
    ),
    'immediate_destructive_execution',false
  );
end
$function$


-- [40000000068] function private.tgg_creator_account_lifecycle_status_internal()
CREATE OR REPLACE FUNCTION private.tgg_creator_account_lifecycle_status_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_pending jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,
    'request_type',request_type,
    'status',status,
    'requested_at',requested_at,
    'execute_after',execute_after,
    'cancelled_at',cancelled_at,
    'executed_at',executed_at
  ) order by requested_at desc),'[]'::jsonb)
  into v_pending
  from public.tgg_creator_account_lifecycle_requests
  where owner_user_id=v_uid
    and status='pending';

  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-ACCOUNT-LIFECYCLE-1.0',
    'pending',v_pending,
    'pending_count',jsonb_array_length(v_pending),
    'archive_confirmation_phrase','ARCHIVE MY ACCOUNT',
    'delete_confirmation_phrase','DELETE MY ACCOUNT',
    'archive_grace_hours',24,
    'delete_grace_days',7,
    'immediate_destructive_execution',false,
    'generated_at',now()
  );
end
$function$


-- [40000000069] function private.tgg_creator_create_video(p_title text, p_description text, p_video_url text, p_thumbnail_url text, p_release_date date, p_visibility text)
CREATE OR REPLACE FUNCTION private.tgg_creator_create_video(p_title text, p_description text DEFAULT NULL::text, p_video_url text DEFAULT NULL::text, p_thumbnail_url text DEFAULT NULL::text, p_release_date date DEFAULT NULL::date, p_visibility text DEFAULT 'public'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_artist_id uuid;
  v_id uuid;
  v_title text:=btrim(coalesce(p_title,''));
  v_description text:=nullif(btrim(coalesce(p_description,'')),'');
  v_video_url text:=nullif(btrim(coalesce(p_video_url,'')),'');
  v_thumbnail_url text:=nullif(btrim(coalesce(p_thumbnail_url,'')),'');
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;

  select id into v_artist_id
  from public.artists
  where user_id=auth.uid()
  limit 1;

  if v_artist_id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

  if char_length(v_title)<1 or char_length(v_title)>160 then
    raise exception 'TITLE_INVALID';
  end if;
  if v_description is not null and char_length(v_description)>5000 then
    raise exception 'DESCRIPTION_TOO_LONG';
  end if;
  if v_video_url is null or char_length(v_video_url)>2048 then
    raise exception 'VIDEO_URL_INVALID';
  end if;
  if v_thumbnail_url is not null and char_length(v_thumbnail_url)>2048 then
    raise exception 'THUMBNAIL_URL_TOO_LONG';
  end if;
  if p_visibility not in ('public','private') then
    raise exception 'INVALID_VISIBILITY';
  end if;

  insert into public.videos(
    artist_id,title,description,release_date,video_url,thumbnail_url,status,visibility
  )
  values(
    v_artist_id,v_title,v_description,p_release_date,
    v_video_url,v_thumbnail_url,'draft',p_visibility
  )
  returning id into v_id;

  return jsonb_build_object('ok',true,'video_id',v_id,'status','draft');
end
$function$


-- [40000000070] function private.tgg_creator_data_export_bundle_internal()
CREATE OR REPLACE FUNCTION private.tgg_creator_data_export_bundle_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist uuid;
  v_profile jsonb;
  v_releases jsonb;
  v_projects jsonb;
  v_assets jsonb;
  v_tiers jsonb;
  v_memberships jsonb;
  v_security jsonb;
  v_impact jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  select coalesce(to_jsonb(a),'{}'::jsonb)
         - 'user_id'
  into v_profile
  from public.artists a
  where a.id=v_artist;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',m.id,
    'title',m.title,
    'status',m.status,
    'genre',m.genre,
    'release_date',m.release_date,
    'featured',m.featured,
    'play_count',m.play_count,
    'download_count',m.download_count,
    'created_at',m.created_at,
    'updated_at',m.updated_at
  ) order by m.created_at),'[]'::jsonb)
  into v_releases
  from public.mixtapes m
  where m.user_id=v_uid or m.artist_id=v_artist;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',p.id,
    'title',p.title,
    'project_type',p.project_type,
    'status',p.status,
    'bpm',p.bpm,
    'created_at',p.created_at,
    'updated_at',p.updated_at
  ) order by p.created_at),'[]'::jsonb)
  into v_projects
  from public.tgg_studio_projects p
  where p.user_id=v_uid;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',a.id,
    'project_id',a.project_id,
    'asset_type',a.asset_type,
    'name',a.name,
    'storage_path',a.storage_path,
    'created_at',a.created_at
  ) order by a.created_at),'[]'::jsonb)
  into v_assets
  from public.tgg_studio_assets a
  where a.user_id=v_uid
     or a.project_id in (select id from public.tgg_studio_projects where user_id=v_uid);

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',t.id,
    'name',t.name,
    'price_cents',t.price_cents,
    'billing_interval',t.billing_interval,
    'is_active',t.is_active,
    'created_at',t.created_at,
    'updated_at',t.updated_at
  ) order by t.created_at),'[]'::jsonb)
  into v_tiers
  from public.tgg_membership_tiers t
  where t.artist_id=v_artist;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',m.id,
    'tier_id',m.tier_id,
    'status',m.status,
    'started_at',m.started_at,
    'current_period_end',m.current_period_end,
    'created_at',m.created_at,
    'relationship',case when m.artist_id=v_artist then 'artist' when m.fan_user_id=v_uid then 'fan' else 'other' end
  ) order by m.created_at),'[]'::jsonb)
  into v_memberships
  from public.tgg_memberships m
  where m.artist_id=v_artist or m.fan_user_id=v_uid;

  v_security:=private.tgg_creator_sensitive_action_history_internal(100);
  v_impact:=private.tgg_creator_deletion_impact_internal();

  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-DATA-EXPORT-1.0',
    'generated_at',now(),
    'format','json_snapshot',
    'scope','creator_owned_and_creator_related_metadata',
    'exclusions',jsonb_build_array(
      'passwords',
      'access_tokens',
      'refresh_tokens',
      'provider_secrets',
      'webhook_secrets',
      'message_bodies',
      'call_signal_payloads'
    ),
    'profile',coalesce(v_profile,'{}'::jsonb),
    'releases',v_releases,
    'studio_projects',v_projects,
    'studio_assets',v_assets,
    'membership_tiers',v_tiers,
    'memberships',v_memberships,
    'security_history',v_security->'items',
    'deletion_impact',v_impact
  );
end;
$function$


-- [40000000071] function private.tgg_creator_deletion_impact_internal()
CREATE OR REPLACE FUNCTION private.tgg_creator_deletion_impact_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist uuid;
  v_counts jsonb;
  v_total bigint;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  v_counts:=jsonb_build_object(
    'artist_profiles',(select count(*) from public.artists where user_id=v_uid),
    'releases',(select count(*) from public.mixtapes where user_id=v_uid or artist_id=v_artist),
    'tracks',(select count(*) from public.tracks where user_id=v_uid or mixtape_id in (select id from public.mixtapes where user_id=v_uid or artist_id=v_artist)),
    'studio_projects',(select count(*) from public.tgg_studio_projects where user_id=v_uid),
    'studio_assets',(select count(*) from public.tgg_studio_assets where user_id=v_uid or project_id in (select id from public.tgg_studio_projects where user_id=v_uid)),
    'created_conversations',(select count(*) from public.tgg_conversations where created_by=v_uid),
    'sent_messages',(select count(*) from public.tgg_messages where sender_id=v_uid),
    'distribution_requests',(select count(*) from public.tgg_distribution_requests where owner_user_id=v_uid or artist_id=v_artist),
    'membership_tiers',(select count(*) from public.tgg_membership_tiers where artist_id=v_artist),
    'artist_memberships',(select count(*) from public.tgg_memberships where artist_id=v_artist),
    'fan_memberships',(select count(*) from public.tgg_memberships where fan_user_id=v_uid)
  );

  select coalesce(sum(value::bigint),0)
  into v_total
  from jsonb_each_text(v_counts);

  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-DELETION-IMPACT-1.0',
    'artist_id',v_artist,
    'counts',v_counts,
    'affected_rows_estimate',v_total,
    'automatic_delete_enabled',false,
    'policy','preview_only_no_delete_action',
    'warning','Identity deletion currently has cascading relationships. Review and explicitly handle creative/history records before any future account deletion workflow.',
    'generated_at',now()
  );
end;
$function$


-- [40000000072] function private.tgg_creator_device_notification_register(p_device_id text, p_permission_state text, p_pwa_installed boolean, p_subscription jsonb, p_user_agent text)
CREATE OR REPLACE FUNCTION private.tgg_creator_device_notification_register(p_device_id text, p_permission_state text DEFAULT 'default'::text, p_pwa_installed boolean DEFAULT false, p_subscription jsonb DEFAULT NULL::jsonb, p_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_device text:=btrim(coalesce(p_device_id,''));
  v_permission text:=lower(btrim(coalesce(p_permission_state,'default')));
  v_endpoint text:=nullif(btrim(coalesce(p_subscription->>'endpoint','')),'');
  v_p256dh text:=nullif(btrim(coalesce(p_subscription#>>'{keys,p256dh}','')),'');
  v_auth text:=nullif(btrim(coalesce(p_subscription#>>'{keys,auth}','')),'');
  v_ua text:=left(coalesce(p_user_agent,''),500);
  v_row public.tgg_creator_device_notifications;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_device !~ '^[A-Za-z0-9_-]{12,80}$' then raise exception 'DEVICE_ID_INVALID' using errcode='22023'; end if;
  if v_permission not in ('default','granted','denied') then raise exception 'PERMISSION_STATE_INVALID' using errcode='22023'; end if;
  if p_subscription is not null and octet_length(p_subscription::text)>8192 then raise exception 'SUBSCRIPTION_TOO_LARGE' using errcode='22023'; end if;
  if v_endpoint is not null and v_endpoint !~ '^https://' then raise exception 'PUSH_ENDPOINT_INVALID' using errcode='22023'; end if;
  if v_p256dh is not null and length(v_p256dh)>512 then raise exception 'P256DH_TOO_LARGE' using errcode='22023'; end if;
  if v_auth is not null and length(v_auth)>256 then raise exception 'PUSH_AUTH_TOO_LARGE' using errcode='22023'; end if;

  insert into public.tgg_creator_device_notifications(
    owner_user_id,device_id,permission_state,pwa_installed,push_endpoint,push_p256dh,push_auth,
    background_push_capable,user_agent,last_seen_at,updated_at
  )
  values(
    v_uid,v_device,v_permission,coalesce(p_pwa_installed,false),v_endpoint,v_p256dh,v_auth,
    (v_endpoint is not null and v_p256dh is not null and v_auth is not null),nullif(v_ua,''),now(),now()
  )
  on conflict(owner_user_id,device_id) do update
  set permission_state=excluded.permission_state,
      pwa_installed=excluded.pwa_installed,
      push_endpoint=excluded.push_endpoint,
      push_p256dh=excluded.push_p256dh,
      push_auth=excluded.push_auth,
      background_push_capable=excluded.background_push_capable,
      user_agent=excluded.user_agent,
      last_seen_at=now(),
      updated_at=now()
  returning * into v_row;

  return jsonb_build_object(
    'ok',true,
    'device_id',v_row.device_id,
    'permission_state',v_row.permission_state,
    'pwa_installed',v_row.pwa_installed,
    'background_push_capable',v_row.background_push_capable,
    'last_seen_at',v_row.last_seen_at
  );
end
$function$


-- [40000000073] function private.tgg_creator_device_notification_status()
CREATE OR REPLACE FUNCTION private.tgg_creator_device_notification_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-DEVICE-ALERTS-1.0',
    'registered_devices',(select count(*) from public.tgg_creator_device_notifications where owner_user_id=v_uid),
    'permission_granted_devices',(select count(*) from public.tgg_creator_device_notifications where owner_user_id=v_uid and permission_state='granted'),
    'installed_devices',(select count(*) from public.tgg_creator_device_notifications where owner_user_id=v_uid and pwa_installed=true),
    'background_push_capable_devices',(select count(*) from public.tgg_creator_device_notifications where owner_user_id=v_uid and background_push_capable=true),
    'background_push_delivery_ready',false,
    'delivery_mode','browser_local_and_service_worker_foundation',
    'checked_at',now()
  );
end
$function$


-- [40000000074] function private.tgg_creator_device_notification_unregister(p_device_id text)
CREATE OR REPLACE FUNCTION private.tgg_creator_device_notification_unregister(p_device_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_count integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  delete from public.tgg_creator_device_notifications
  where owner_user_id=v_uid and device_id=btrim(coalesce(p_device_id,''));
  get diagnostics v_count=row_count;
  return jsonb_build_object('ok',true,'removed',v_count>0);
end
$function$


-- [40000000075] function private.tgg_creator_mutation_audit_log(p_action_key text, p_target_id text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION private.tgg_creator_mutation_audit_log(p_action_key text, p_target_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_id bigint;
  v_action text:=btrim(coalesce(p_action_key,''));
  v_meta jsonb:=coalesce(p_metadata,'{}'::jsonb);
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if v_action not in (
    'calls.room_reuse',
    'calls.room_start',
    'distribution.submit_reuse',
    'distribution.submit',
    'calls.validation_invite_reuse',
    'calls.validation_invite_create'
  ) then
    raise exception 'AUDIT_ACTION_NOT_ALLOWED';
  end if;

  if jsonb_typeof(v_meta)<>'object' then
    raise exception 'AUDIT_METADATA_MUST_BE_OBJECT';
  end if;
  if octet_length(v_meta::text)>8192 then
    raise exception 'AUDIT_METADATA_TOO_LARGE';
  end if;
  if v_meta::text ~* '"(body|payload|package_snapshot|[^"]*token[^"]*|[^"]*secret[^"]*|password)"[[:space:]]*:'
  then
    raise exception 'AUDIT_SENSITIVE_METADATA_REJECTED';
  end if;

  insert into private.tgg_creator_mutation_audit(actor_id,action_key,target_id,metadata)
  values(v_uid,v_action,p_target_id,v_meta)
  returning id into v_id;

  return v_id;
end;
$function$


-- [40000000076] function private.tgg_creator_mutation_audit_trigger()
CREATE OR REPLACE FUNCTION private.tgg_creator_mutation_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_new jsonb:=case when tg_op<>'DELETE' then to_jsonb(new) else '{}'::jsonb end;
  v_old jsonb:=case when tg_op<>'INSERT' then to_jsonb(old) else '{}'::jsonb end;
  v_actor uuid:=auth.uid();
  v_target text;
  v_meta jsonb;
begin
  if v_actor is null then
    return coalesce(new,old);
  end if;

  if tg_argv[0] not in ('membership_tier.mutate') then
    raise exception 'AUDIT_TRIGGER_ACTION_NOT_ALLOWED';
  end if;

  v_target:=coalesce(
    v_new->>'id',v_new->>'invite_id',
    v_old->>'id',v_old->>'invite_id'
  );

  v_meta:=jsonb_strip_nulls(jsonb_build_object(
    'operation',tg_op,
    'table',tg_table_name,
    'status_before',v_old->>'status',
    'status_after',v_new->>'status',
    'active_before',v_old->>'is_active',
    'active_after',v_new->>'is_active',
    'price_cents',v_new->>'price_cents'
  ));

  insert into private.tgg_creator_mutation_audit(actor_id,action_key,target_id,metadata)
  values(v_actor,tg_argv[0],v_target,v_meta);

  return coalesce(new,old);
end;
$function$


-- [40000000077] function private.tgg_creator_one_bundle()
CREATE OR REPLACE FUNCTION private.tgg_creator_one_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_state public.tgg_creator_one_state;
  v_one integer;
  v_low text;
  v_status text;
  v_checkins bigint:=0;
  v_framework jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select id into v_artist_id from public.artists where user_id=v_uid order by created_at limit 1;

  insert into public.tgg_creator_one_state(owner_user_id,artist_id)
  values(v_uid,v_artist_id)
  on conflict(owner_user_id) do update
  set artist_id=coalesce(excluded.artist_id,public.tgg_creator_one_state.artist_id)
  returning * into v_state;

  select count(*) into v_checkins
  from public.tgg_creator_one_checkins
  where owner_user_id=v_uid;

  v_one:=private.tgg_one_score(v_state.head_score,v_state.mind_score,v_state.body_score,v_state.spirit_score,v_state.soul_score);

  select key into v_low
  from (values
    ('head',v_state.head_score),('mind',v_state.mind_score),('body',v_state.body_score),
    ('spirit',v_state.spirit_score),('soul',v_state.soul_score)
  ) as x(key,score)
  order by score,key
  limit 1;

  v_status:=case
    when v_checkins=0 then 'Set Your Baseline'
    when least(v_state.head_score,v_state.mind_score,v_state.body_score,v_state.spirit_score,v_state.soul_score)>=80 then 'THE ONE'
    when v_one>=75 then 'Aligned'
    when v_one>=60 then 'Balancing'
    else 'Building'
  end;

  select coalesce(jsonb_agg(jsonb_build_object(
    'layer_key',layer_key,
    'display_name',display_name,
    'layer_order',layer_order,
    'purpose',purpose,
    'responsibility',responsibility,
    'can_execute',can_execute,
    'can_block',can_block
  ) order by layer_order),'[]'::jsonb)
  into v_framework
  from public.tgg_one_layers
  where active=true
    and layer_key in ('shadow','head','mind','body','spirit','soul','the_one');

  return jsonb_build_object(
    'ok',true,
    'version','THE-ONE-1.2',
    'canonical_framework','public.tgg_one_layers',
    'framework',v_framework,
    'has_checkin',v_checkins>0,
    'checkin_count',v_checkins,
    'dimensions',jsonb_build_object(
      'head',jsonb_build_object('score',v_state.head_score,'meaning','Direction, attention, decisions and executive control','note',v_state.head_note),
      'mind',jsonb_build_object('score',v_state.mind_score,'meaning','Learning, creativity, thinking and mental clarity','note',v_state.mind_note),
      'body',jsonb_build_object('score',v_state.body_score,'meaning','Energy, physical capacity, routine and execution','note',v_state.body_note),
      'spirit',jsonb_build_object('score',v_state.spirit_score,'meaning','Values, inner drive, courage and emotional energy','note',v_state.spirit_note),
      'soul',jsonb_build_object('score',v_state.soul_score,'meaning','Identity, purpose, meaning and legacy','note',v_state.soul_note)
    ),
    'one',jsonb_build_object(
      'score',case when v_checkins=0 then null else v_one end,
      'status',v_status,
      'focus_dimension',case when v_checkins=0 then null else v_low end,
      'meaning','Creator reflection aligned to the canonical THE ONE framework'
    ),
    'updated_at',v_state.updated_at
  );
end
$function$


-- [40000000078] function private.tgg_creator_one_checkin(p_head integer, p_mind integer, p_body integer, p_spirit integer, p_soul integer, p_head_note text, p_mind_note text, p_body_note text, p_spirit_note text, p_soul_note text)
CREATE OR REPLACE FUNCTION private.tgg_creator_one_checkin(p_head integer, p_mind integer, p_body integer, p_spirit integer, p_soul integer, p_head_note text DEFAULT NULL::text, p_mind_note text DEFAULT NULL::text, p_body_note text DEFAULT NULL::text, p_spirit_note text DEFAULT NULL::text, p_soul_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_one integer;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_head not between 0 and 100 or p_mind not between 0 and 100 or p_body not between 0 and 100
     or p_spirit not between 0 and 100 or p_soul not between 0 and 100 then
    raise exception 'ONE_SCORE_OUT_OF_RANGE' using errcode='22023';
  end if;

  if greatest(
    length(coalesce(p_head_note,'')),length(coalesce(p_mind_note,'')),length(coalesce(p_body_note,'')),
    length(coalesce(p_spirit_note,'')),length(coalesce(p_soul_note,''))
  )>500 then raise exception 'ONE_NOTE_TOO_LONG' using errcode='22023'; end if;

  select id into v_artist_id from public.artists where user_id=v_uid order by created_at limit 1;
  v_one:=private.tgg_one_score(p_head,p_mind,p_body,p_spirit,p_soul);

  insert into public.tgg_creator_one_state(
    owner_user_id,artist_id,head_score,mind_score,body_score,spirit_score,soul_score,
    head_note,mind_note,body_note,spirit_note,soul_note,updated_at
  ) values(
    v_uid,v_artist_id,p_head,p_mind,p_body,p_spirit,p_soul,
    nullif(btrim(p_head_note),''),nullif(btrim(p_mind_note),''),nullif(btrim(p_body_note),''),
    nullif(btrim(p_spirit_note),''),nullif(btrim(p_soul_note),''),now()
  )
  on conflict(owner_user_id) do update
  set artist_id=excluded.artist_id,
      head_score=excluded.head_score,mind_score=excluded.mind_score,body_score=excluded.body_score,
      spirit_score=excluded.spirit_score,soul_score=excluded.soul_score,
      head_note=excluded.head_note,mind_note=excluded.mind_note,body_note=excluded.body_note,
      spirit_note=excluded.spirit_note,soul_note=excluded.soul_note,updated_at=now();

  insert into public.tgg_creator_one_checkins(
    owner_user_id,artist_id,head_score,mind_score,body_score,spirit_score,soul_score,one_score
  ) values(v_uid,v_artist_id,p_head,p_mind,p_body,p_spirit,p_soul,v_one);

  return private.tgg_creator_one_bundle();
end
$function$


-- [40000000079] function private.tgg_creator_rate_limit_gate(p_action_key text, p_limit integer, p_window_seconds integer)
CREATE OR REPLACE FUNCTION private.tgg_creator_rate_limit_gate(p_action_key text, p_limit integer, p_window_seconds integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_bucket timestamptz;
  v_count integer;
  v_action text:=btrim(coalesce(p_action_key,''));
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if v_action not in (
    'messages.send',
    'membership_tier.create',
    'distribution.submit',
    'calls.signal',
    'calls.room_start',
    'distribution.submit.rpc',
    'calls.room_start.rpc',
    'calls.validation_invite'
  ) then
    raise exception 'RATE_LIMIT_ACTION_NOT_ALLOWED';
  end if;

  if p_limit is null or p_limit<1
     or p_window_seconds is null or p_window_seconds<1 or p_window_seconds>86400
  then
    raise exception 'RATE_LIMIT_CONFIG_INVALID';
  end if;

  v_bucket:=to_timestamp(
    floor(extract(epoch from now())/p_window_seconds)*p_window_seconds
  );

  insert into private.tgg_creator_rate_counters(
    actor_id,action_key,bucket_start,bucket_seconds,action_count,updated_at
  )
  values(v_uid,v_action,v_bucket,p_window_seconds,1,now())
  on conflict(actor_id,action_key,bucket_start,bucket_seconds)
  do update set
    action_count=private.tgg_creator_rate_counters.action_count+1,
    updated_at=now()
  where private.tgg_creator_rate_counters.action_count<p_limit
  returning action_count into v_count;

  if v_count is null then
    raise exception 'RATE_LIMITED:%',v_action using errcode='P0001';
  end if;

  if v_count=1 then
    delete from private.tgg_creator_rate_counters
    where actor_id=v_uid
      and action_key=v_action
      and bucket_start<now()-interval '2 days';
  end if;

  return v_count;
end;
$function$


-- [40000000080] function private.tgg_creator_rate_limit_trigger()
CREATE OR REPLACE FUNCTION private.tgg_creator_rate_limit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is not null then
    perform private.tgg_creator_rate_limit_gate(
      tg_argv[0],
      tg_argv[1]::integer,
      tg_argv[2]::integer
    );
  end if;
  return new;
end;
$function$


-- [40000000081] function private.tgg_creator_retention_pulse()
CREATE OR REPLACE FUNCTION private.tgg_creator_retention_pulse()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_prev public.tgg_creator_growth_snapshots;
  v_followers bigint:=0;
  v_referrals bigint:=0;
  v_saves bigint:=0;
  v_unread bigint:=0;
  v_first boolean:=false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  insert into public.notification_preferences(
    user_id,follows_enabled,saves_enabled,reactions_enabled,comments_enabled,collaboration_enabled,updated_at
  )
  values(v_uid,true,true,true,true,true,now())
  on conflict(user_id) do nothing;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is not null then
    select count(*) into v_followers
    from public.artist_follows
    where artist_id=v_artist_id;

    select count(*) into v_saves
    from public.release_saves rs
    join public.mixtapes m on m.id=rs.mixtape_id
    where m.artist_id=v_artist_id
      and m.status='published';
  end if;

  select count(*) into v_referrals
  from public.tgg_referral_claims
  where referrer_user_id=v_uid;

  select count(*) into v_unread
  from public.notifications
  where recipient_id=v_uid
    and read_at is null;

  select * into v_prev
  from public.tgg_creator_growth_snapshots
  where user_id=v_uid;

  v_first:=v_prev.user_id is null;

  insert into public.tgg_creator_growth_snapshots(
    user_id,artist_id,follower_count,referral_count,release_save_count,unread_notification_count,captured_at
  )
  values(v_uid,v_artist_id,v_followers,v_referrals,v_saves,v_unread,now())
  on conflict(user_id) do update
  set artist_id=excluded.artist_id,
      follower_count=excluded.follower_count,
      referral_count=excluded.referral_count,
      release_save_count=excluded.release_save_count,
      unread_notification_count=excluded.unread_notification_count,
      captured_at=excluded.captured_at;

  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-RETENTION-PULSE-1.0',
    'first_snapshot',v_first,
    'current',jsonb_build_object(
      'followers',v_followers,
      'referrals',v_referrals,
      'release_saves',v_saves,
      'unread_notifications',v_unread
    ),
    'since_last_visit',jsonb_build_object(
      'new_followers',case when v_first then 0 else greatest(v_followers-v_prev.follower_count,0) end,
      'new_referrals',case when v_first then 0 else greatest(v_referrals-v_prev.referral_count,0) end,
      'new_release_saves',case when v_first then 0 else greatest(v_saves-v_prev.release_save_count,0) end,
      'unread_change',case when v_first then v_unread else v_unread-v_prev.unread_notification_count end
    ),
    'previous_snapshot_at',case when v_first then null else v_prev.captured_at end,
    'captured_at',now()
  );
end
$function$


-- [40000000082] function private.tgg_creator_sensitive_action_history_internal(p_limit integer)
CREATE OR REPLACE FUNCTION private.tgg_creator_sensitive_action_history_internal(p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_limit integer:=least(greatest(coalesce(p_limit,25),1),100);
  v_items jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,
    'action_key',action_key,
    'target_id',target_id,
    'occurred_at',occurred_at,
    'metadata',jsonb_strip_nulls(jsonb_build_object(
      'operation',metadata->>'operation',
      'table',metadata->>'table',
      'status_before',metadata->>'status_before',
      'status_after',metadata->>'status_after',
      'active_before',metadata->>'active_before',
      'active_after',metadata->>'active_after',
      'price_cents',metadata->>'price_cents',
      'room_type',metadata->>'room_type',
      'provider_key',metadata->>'provider_key',
      'reused',metadata->>'reused'
    ))
  ) order by occurred_at desc),'[]'::jsonb)
  into v_items
  from (
    select id,action_key,target_id,metadata,occurred_at
    from private.tgg_creator_mutation_audit
    where actor_id=v_uid
    order by occurred_at desc
    limit v_limit
  ) q;

  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-SENSITIVE-ACTION-HISTORY-1.0',
    'items',v_items,
    'count',jsonb_array_length(v_items),
    'limit',v_limit,
    'retention_days',180,
    'sensitive_payloads_included',false,
    'generated_at',now()
  );
end;
$function$


