-- [40000000087] function private.tgg_deliver_creator_growth_digests(p_force boolean)
CREATE OR REPLACE FUNCTION private.tgg_deliver_creator_growth_digests(p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  s record;
  v_sent integer:=0;
  v_skipped integer:=0;
  v_schedule_sent integer:=0;
  v_top_title text;
  v_count integer;
  v_urgent integer;
  v_tz text;
  v_local_due text;
begin
  insert into public.tgg_creator_digest_preferences(user_id)
  select distinct a.user_id
  from public.artists a
  join public.profiles p on p.id=a.user_id
  where a.user_id is not null
  on conflict(user_id) do nothing;

  for r in
    select d.*,p.id as profile_id
    from public.tgg_creator_digest_preferences d
    join public.profiles p on p.id=d.user_id
  loop
    if coalesce(r.action_alerts_enabled,true) then
      for s in
        select t.*
        from public.tgg_campaign_tasks t
        where t.owner_user_id=r.user_id
          and t.task_type='growth_social_schedule'
          and t.status='todo'
          and t.due_at is not null
          and (
            (t.due_at>now() and t.due_at<=now()+interval '75 minutes')
            or (t.due_at<=now() and t.due_at>=now()-interval '6 hours')
          )
          and not exists(
            select 1
            from public.notifications n
            where n.recipient_id=r.user_id
              and n.notification_type='growth_social_schedule_due'
              and n.entity_type='campaign_task'
              and n.entity_id=t.id
          )
        order by t.due_at
      loop
        v_tz:=coalesce(nullif(s.metadata->>'timezone',''),'UTC');
        if not exists(select 1 from pg_catalog.pg_timezone_names where name=v_tz) then
          v_tz:='UTC';
        end if;
        v_local_due:=to_char(timezone(v_tz,s.due_at),'Mon DD · HH12:MI AM');

        insert into public.notifications(
          recipient_id,notification_type,entity_type,entity_id,title,body
        )
        values(
          r.user_id,
          'growth_social_schedule_due',
          'campaign_task',
          s.id,
          case when s.due_at<=now() then 'Scheduled post is due' else 'Scheduled post due soon' end,
          coalesce(s.title,'Social post')||' · '||v_local_due||' '||v_tz||
          '. Open Growth → Social Schedule to copy the post.'
        );
        v_schedule_sent:=v_schedule_sent+1;
      end loop;
    end if;

    if not r.digest_enabled then
      continue;
    end if;

    if not (
      p_force
      or extract(hour from timezone('UTC',now()))::integer=r.digest_hour_utc
    ) then
      continue;
    end if;

    if exists(
      select 1 from public.notifications n
      where n.recipient_id=r.user_id
        and n.notification_type='growth_daily_digest'
        and n.created_at>=date_trunc('day',now())
    ) then
      v_skipped:=v_skipped+1;
      continue;
    end if;

    select count(*),
           count(*) filter(where q.priority>=80),
           (array_agg(q.title order by q.priority desc,q.created_at asc))[1]
    into v_count,v_urgent,v_top_title
    from public.tgg_creator_action_queue q
    where q.owner_user_id=r.user_id
      and q.status='open'
      and q.priority>=r.minimum_priority;

    if coalesce(v_count,0)=0 then
      v_skipped:=v_skipped+1;
      continue;
    end if;

    insert into public.notifications(
      recipient_id,notification_type,entity_type,title,body
    )
    values(
      r.user_id,
      'growth_daily_digest',
      'growth_digest',
      'Your Daily Growth Digest',
      case
        when v_urgent>0 then
          v_urgent||' urgent · '||v_count||' total actions. Start with: '||coalesce(v_top_title,'Open Creator OS Growth.')
        else
          v_count||' growth actions are ready. Start with: '||coalesce(v_top_title,'Open Creator OS Growth.')
      end
    );

    v_sent:=v_sent+1;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-DIGEST-DELIVERY-1.1',
    'sent',v_sent,
    'scheduled_post_reminders_sent',v_schedule_sent,
    'skipped',v_skipped,
    'forced',p_force,
    'checked_at',now()
  );
end
$function$


-- [40000000088] function private.tgg_discover_dynamic_events(p_character_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_discover_dynamic_events(p_character_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_career text;
  v_rep integer:=0;
  v_count integer:=0;
  v_max_trust integer:=0;
  v_max_rivalry integer:=0;
  v_max_business_level integer:=0;
  v_max_crew_rivalry integer:=0;
  v_has_active_contract boolean:=false;
  v_mod jsonb;
  v_rare_bonus numeric:=0;
  v_event_weight numeric:=1;
  v_clock jsonb;
  v_hour integer;
  v_collab_bonus numeric:=0;
  v_night_bonus numeric:=0;
  v_street_weight numeric:=1;
begin
  select active_career into v_career
  from public.world_characters
  where id=p_character_id and character_status='active';

  if v_career is null then return 0; end if;

  select coalesce(max(reputation),0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=p_character_id;

  select coalesce(max(trust_score),0) into v_max_trust
  from public.tgg_world_contact_relationships
  where character_id=p_character_id;

  select coalesce(max(rivalry),0) into v_max_rivalry
  from public.tgg_world_character_npc_standing
  where character_id=p_character_id;

  select coalesce(max(business_level),0) into v_max_business_level
  from public.tgg_world_character_businesses
  where character_id=p_character_id and status='active';

  select exists(
    select 1 from public.tgg_world_character_contracts
    where character_id=p_character_id and status='active'
  ) into v_has_active_contract;

  select coalesce(max(r.rivalry),0) into v_max_crew_rivalry
  from public.tgg_world_crew_members m
  join public.tgg_world_crew_relations r
    on m.crew_id=any(array[r.crew_a_id,r.crew_b_id])
  where m.character_id=p_character_id and m.left_at is null;

  v_mod:=private.tgg_world_effective_modifiers(p_character_id);
  v_rare_bonus:=greatest(coalesce((v_mod->>'rare_event_bonus')::numeric,0),0);
  v_event_weight:=greatest(coalesce((v_mod->>'event_weight_multiplier')::numeric,1),0.1);
  v_collab_bonus:=greatest(coalesce((v_mod->>'collab_event_bonus')::numeric,0),0);
  v_night_bonus:=greatest(coalesce((v_mod->>'night_event_bonus')::numeric,0),0);
  v_street_weight:=greatest(coalesce((v_mod->>'street_event_weight')::numeric,1),0.1);
  v_clock:=private.tgg_world_clock();
  v_hour:=coalesce((v_clock->>'local_hour')::integer,0);

  insert into public.tgg_world_character_event_state(
    character_id,dynamic_event_id,status,role_key,progress,outcome,discovered_at,updated_at
  )
  select
    p_character_id,
    e.id,
    'discovered',
    v_career,
    jsonb_build_object(
      'discovery_roll',
      (
        ('x'||substr(md5(p_character_id::text||':'||e.id::text),1,8))::bit(32)::bigint
        % 1000000
      )::numeric/1000000,
      'effective_modifiers',jsonb_build_object(
        'rare_event_bonus',v_rare_bonus,
        'event_weight_multiplier',v_event_weight,
        'collab_event_bonus',v_collab_bonus,
        'night_event_bonus',v_night_bonus,
        'street_event_weight',v_street_weight
      ),
      'world_clock',v_clock
    ),
    '{}'::jsonb,
    now(),
    now()
  from public.tgg_world_dynamic_events e
  join public.tgg_world_dynamic_event_templates t on t.event_key=e.event_key and t.enabled=true
  where e.status in ('scheduled','active')
    and e.ends_at>now()
    and (cardinality(t.participant_roles)=0 or v_career=any(t.participant_roles))
    and (
      not (t.trigger_conditions ? 'min_reputation')
      or v_rep >= coalesce((t.trigger_conditions->>'min_reputation')::integer,0)
    )
    and (
      not (t.trigger_conditions ? 'reputation_gte')
      or v_rep >= coalesce((t.trigger_conditions->>'reputation_gte')::integer,0)
    )
    and (
      not (t.trigger_conditions ? 'min_contact_trust')
      or v_max_trust >= coalesce((t.trigger_conditions->>'min_contact_trust')::integer,0)
    )
    and (
      not (t.trigger_conditions ? 'min_rivalry')
      or v_max_rivalry >= coalesce((t.trigger_conditions->>'min_rivalry')::integer,0)
    )
    and (
      not (t.trigger_conditions ? 'business_level_gte')
      or v_max_business_level >= coalesce((t.trigger_conditions->>'business_level_gte')::integer,0)
    )
    and (
      not (t.trigger_conditions ? 'crew_rivalry_gte')
      or v_max_crew_rivalry >= coalesce((t.trigger_conditions->>'crew_rivalry_gte')::integer,0)
    )
    and (
      not (t.trigger_conditions ? 'contract_active')
      or not coalesce((t.trigger_conditions->>'contract_active')::boolean,false)
      or v_has_active_contract
    )
    and (
      not (t.trigger_conditions ? 'hour_start')
      or not (t.trigger_conditions ? 'hour_end')
      or (
        case
          when (t.trigger_conditions->>'hour_start')::integer
             <= (t.trigger_conditions->>'hour_end')::integer
          then v_hour >= (t.trigger_conditions->>'hour_start')::integer
           and v_hour <  (t.trigger_conditions->>'hour_end')::integer
          else v_hour >= (t.trigger_conditions->>'hour_start')::integer
            or v_hour <  (t.trigger_conditions->>'hour_end')::integer
        end
      )
    )
    and (
      not (t.trigger_conditions ? 'chance')
      or (
        (
          ('x'||substr(md5(p_character_id::text||':'||e.id::text),1,8))::bit(32)::bigint
          % 1000000
        )::numeric/1000000
      ) <= least(
        1,
        (
          greatest(0,coalesce((t.trigger_conditions->>'chance')::numeric,0))
          * v_event_weight
          * case when t.event_type='collab' then 1+v_collab_bonus else 1 end
          * case
              when t.event_type in ('nightlife','nightlife_event') or t.trigger_mode='night-window'
              then 1+v_night_bonus else 1
            end
          * case when t.event_type in ('crew_event','rivalry') then v_street_weight else 1 end
        )
        + case when coalesce((t.metadata->>'rare')::boolean,false) then v_rare_bonus else 0 end
      )
    )
  on conflict(character_id,dynamic_event_id) do nothing;

  get diagnostics v_count=row_count;
  return v_count;
end;
$function$


-- [40000000089] function private.tgg_distribution_master_candidates(p_release_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_distribution_master_candidates(p_release_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_owned boolean:=false;
  v_tracks jsonb;
  v_candidates jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select exists(
    select 1
    from public.mixtapes m
    join public.artists a on a.id=m.artist_id
    where m.id=p_release_id
      and a.user_id=v_uid
  ) into v_owned;

  if not v_owned then
    raise exception 'RELEASE_NOT_FOUND_OR_NOT_OWNED';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'track_id',t.id,
      'track_number',t.track_number,
      'title',t.title,
      'audio_path',t.audio_path,
      'audio_url',t.audio_url,
      'duration_seconds',t.duration_seconds,
      'has_secure_audio',coalesce(t.has_secure_audio,false)
    )
    order by t.track_number
  ),'[]'::jsonb)
  into v_tracks
  from public.tracks t
  where t.mixtape_id=p_release_id;

  with owned_audio as (
    select
      o.id,
      o.bucket_id,
      o.name,
      o.owner_id,
      o.metadata,
      o.created_at,
      trim(both '"' from coalesce(o.metadata->>'eTag','')) as content_hash,
      coalesce((o.metadata->>'size')::bigint,0) as size_bytes,
      coalesce(o.metadata->>'mimetype','audio/mpeg') as mime_type
    from storage.objects o
    where o.bucket_id in ('audio','mixtape-audio')
      and o.owner_id=v_uid::text
      and coalesce(o.metadata->>'mimetype','') like 'audio/%'
  ),
  ranked as (
    select *,
      row_number() over(
        partition by content_hash,size_bytes
        order by case when bucket_id='mixtape-audio' then 0 else 1 end, created_at desc
      ) as rn,
      count(*) over(partition by content_hash,size_bytes) as duplicate_count
    from owned_audio
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'object_id',id,
      'bucket_id',bucket_id,
      'object_name',name,
      'content_hash',content_hash,
      'size_bytes',size_bytes,
      'mime_type',mime_type,
      'created_at',created_at,
      'duplicate_count',duplicate_count,
      'preferred_secure',bucket_id='mixtape-audio'
    )
    order by case when bucket_id='mixtape-audio' then 0 else 1 end, created_at desc
  ),'[]'::jsonb)
  into v_candidates
  from ranked
  where rn=1;

  return jsonb_build_object(
    'ok',true,
    'release_id',p_release_id,
    'tracks',v_tracks,
    'candidates',v_candidates,
    'generated_at',now()
  );
end
$function$


-- [40000000090] function private.tgg_distribution_master_reuse_confirm(p_audio_path text, p_confirmed boolean, p_note text)
CREATE OR REPLACE FUNCTION private.tgg_distribution_master_reuse_confirm(p_audio_path text, p_confirmed boolean, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_count integer:=0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select count(distinct m.id)
  into v_count
  from public.tracks t
  join public.mixtapes m on m.id=t.mixtape_id
  join public.artists a on a.id=m.artist_id
  where a.user_id=v_uid
    and m.status='published'
    and t.audio_path=p_audio_path;

  if v_count<2 then
    raise exception 'MASTER_REUSE_GROUP_NOT_FOUND';
  end if;

  insert into private.tgg_distribution_master_reuse_confirmations(
    owner_user_id,audio_path,confirmed_intentional,confirmed_at,note,updated_at
  )
  values(
    v_uid,p_audio_path,p_confirmed,
    case when p_confirmed then now() else null end,
    nullif(btrim(coalesce(p_note,'')),''),
    now()
  )
  on conflict(owner_user_id,audio_path) do update set
    confirmed_intentional=excluded.confirmed_intentional,
    confirmed_at=excluded.confirmed_at,
    note=excluded.note,
    updated_at=now();

  perform private.tgg_reconcile_distribution_master_reuse_activation_item();
       perform private.tgg_reconcile_distribution_metadata_activation_item();
       perform private.tgg_activation_consistency_monitor();
       return private.tgg_distribution_master_reuse_status();
end
$function$


-- [40000000091] function private.tgg_distribution_master_reuse_status()
CREATE OR REPLACE FUNCTION private.tgg_distribution_master_reuse_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_groups jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  with owned_tracks as (
    select
      t.id as track_id,
      t.mixtape_id as release_id,
      m.title as release_title,
      t.title as track_title,
      t.audio_path
    from public.tracks t
    join public.mixtapes m on m.id=t.mixtape_id
    join public.artists a on a.id=m.artist_id
    where a.user_id=v_uid
      and m.status='published'
      and nullif(btrim(coalesce(t.audio_path,'')),'') is not null
  ),
  dup as (
    select audio_path
    from owned_tracks
    group by audio_path
    having count(distinct release_id)>1
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'audio_path',d.audio_path,
      'confirmed_intentional',coalesce(c.confirmed_intentional,false),
      'confirmed_at',c.confirmed_at,
      'note',c.note,
      'references',(
        select jsonb_agg(jsonb_build_object(
          'release_id',o.release_id,
          'release_title',o.release_title,
          'track_id',o.track_id,
          'track_title',o.track_title
        ) order by o.release_title,o.track_title)
        from owned_tracks o
        where o.audio_path=d.audio_path
      )
    )
    order by d.audio_path
  ),'[]'::jsonb)
  into v_groups
  from dup d
  left join private.tgg_distribution_master_reuse_confirmations c
    on c.owner_user_id=v_uid
   and c.audio_path=d.audio_path;

  return jsonb_build_object(
    'ok',true,
    'groups',v_groups,
    'generated_at',now()
  );
end
$function$


-- [40000000092] function private.tgg_distribution_master_select(p_release_id uuid, p_track_id uuid, p_bucket_id text, p_object_name text)
CREATE OR REPLACE FUNCTION private.tgg_distribution_master_select(p_release_id uuid, p_track_id uuid, p_bucket_id text, p_object_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_owned boolean:=false;
  v_object storage.objects%rowtype;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select exists(
    select 1
    from public.mixtapes m
    join public.artists a on a.id=m.artist_id
    join public.tracks t on t.mixtape_id=m.id
    where m.id=p_release_id
      and t.id=p_track_id
      and a.user_id=v_uid
  ) into v_owned;

  if not v_owned then
    raise exception 'TRACK_NOT_FOUND_OR_NOT_OWNED';
  end if;

  select *
  into v_object
  from storage.objects o
  where o.bucket_id=p_bucket_id
    and o.name=p_object_name
    and o.owner_id=v_uid::text
    and o.bucket_id in ('audio','mixtape-audio')
    and coalesce(o.metadata->>'mimetype','') like 'audio/%'
  limit 1;

  if v_object.id is null then
    raise exception 'AUDIO_OBJECT_NOT_FOUND_OR_NOT_OWNED';
  end if;

  update public.tracks
  set
    audio_path=v_object.name,
    user_id=v_uid
  where id=p_track_id
    and mixtape_id=p_release_id;

  return jsonb_build_object(
    'ok',true,
    'release_id',p_release_id,
    'track_id',p_track_id,
    'bucket_id',v_object.bucket_id,
    'audio_path',v_object.name,
    'content_hash',trim(both '"' from coalesce(v_object.metadata->>'eTag','')),
    'size_bytes',coalesce((v_object.metadata->>'size')::bigint,0),
    'readiness',public.tgg_creator_distribution_readiness(p_release_id),
    'updated_at',now()
  );
end
$function$


-- [40000000093] function private.tgg_distribution_metadata_coverage_check()
CREATE OR REPLACE FUNCTION private.tgg_distribution_metadata_coverage_check()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with published as (
  select id,title from public.mixtapes where status='published'::public.mixtape_status
),
coverage as (
  select
    p.id release_id,p.title,
    (d.release_id is not null) metadata_row_present,
    coalesce(d.rights_confirmed,false) rights_confirmed,
    nullif(btrim(coalesce(d.label_name,'')),'') is not null label_present,
    nullif(btrim(coalesce(d.copyright_line,'')),'') is not null copyright_present,
    nullif(btrim(coalesce(d.publishing_line,'')),'') is not null publishing_present,
    jsonb_array_length(coalesce(d.territories,'[]'::jsonb))>0 territories_present
  from published p
  left join public.tgg_distribution_release_metadata d on d.release_id=p.id
)
select jsonb_build_object(
  'ok',not exists(select 1 from coverage where not metadata_row_present),
  'version','DISTRIBUTION-METADATA-COVERAGE-1.0',
  'published_release_count',(select count(*) from coverage),
  'metadata_row_count',(select count(*) from coverage where metadata_row_present),
  'complete_legal_count',(select count(*) from coverage where rights_confirmed and label_present and copyright_present and publishing_present and territories_present),
  'creator_action_required_count',(select count(*) from coverage where metadata_row_present and not (rights_confirmed and label_present and copyright_present and publishing_present and territories_present)),
  'releases',coalesce((select jsonb_agg(to_jsonb(c) order by title) from coverage c),'[]'::jsonb),
  'policy','Every published release must have a creator-editable metadata row. Legal facts are never auto-filled or auto-confirmed.',
  'checked_at',now()
);
$function$


-- [40000000094] function private.tgg_distribution_track_duration_set(p_release_id uuid, p_track_id uuid, p_duration_seconds integer)
CREATE OR REPLACE FUNCTION private.tgg_distribution_track_duration_set(p_release_id uuid, p_track_id uuid, p_duration_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_owned boolean:=false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if p_duration_seconds is null or p_duration_seconds <= 0 or p_duration_seconds > 86400 then
    raise exception 'INVALID_DURATION_SECONDS' using errcode='22023';
  end if;

  select exists(
    select 1
    from public.mixtapes m
    join public.artists a on a.id=m.artist_id
    join public.tracks t on t.mixtape_id=m.id
    where m.id=p_release_id
      and t.id=p_track_id
      and a.user_id=v_uid
  ) into v_owned;

  if not v_owned then
    raise exception 'TRACK_NOT_FOUND_OR_NOT_OWNED';
  end if;

  update public.tracks
  set duration_seconds=p_duration_seconds
  where id=p_track_id
    and mixtape_id=p_release_id;

  return jsonb_build_object(
    'ok',true,
    'release_id',p_release_id,
    'track_id',p_track_id,
    'duration_seconds',p_duration_seconds,
    'readiness',public.tgg_creator_distribution_readiness(p_release_id),
    'updated_at',now()
  );
end
$function$


-- [40000000095] function private.tgg_edge_physical_cleanup_candidates()
CREATE OR REPLACE FUNCTION private.tgg_edge_physical_cleanup_candidates()
 RETURNS TABLE(slug text, family_key text, canonical_slug text, reference_count integer, runtime_class text, runtime_status text, active_reference_expected boolean, cleanup_action text, eligible boolean, reason text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
  select
    m.slug,
    m.family_key,
    m.canonical_slug,
    m.reference_count,
    i.runtime_class,
    i.status as runtime_status,
    i.active_reference_expected,
    i.cleanup_action,
    (
      m.approved_state='retired'
      and m.reference_count=0
      and coalesce(i.active_reference_expected,false)=false
      and coalesce(i.cleanup_action,'')='audit_before_retire'
      and m.slug<>m.canonical_slug
    ) as eligible,
    case
      when m.approved_state<>'retired' then 'manifest_not_retired'
      when m.reference_count<>0 then 'manifest_reference_count_nonzero'
      when coalesce(i.active_reference_expected,false) then 'runtime_reference_expected'
      when coalesce(i.cleanup_action,'')<>'audit_before_retire' then 'runtime_cleanup_not_approved'
      when m.slug=m.canonical_slug then 'canonical_slug_self_protection'
      else 'eligible_after_external_management_api_delete_capability'
    end as reason
  from private.tgg_edge_retirement_manifest m
  left join public.tgg_edge_function_runtime_inventory i
    on i.function_slug=m.slug
  where i.function_slug is not null;
$function$


-- [40000000096] function private.tgg_enforce_call_capacity()
CREATE OR REPLACE FUNCTION private.tgg_enforce_call_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_is_group boolean;
  v_status text;
  v_active_count integer;
begin
  select r.is_group, r.status
    into v_is_group, v_status
  from public.tgg_call_rooms r
  where r.id = new.room_id
  for update;

  if not found then
    raise exception 'call_room_not_found';
  end if;

  if v_status not in ('open','active') then
    raise exception 'call_room_not_joinable';
  end if;

  if coalesce(v_is_group,false) = false then
    select count(*)
      into v_active_count
    from public.tgg_call_participants cp
    where cp.room_id = new.room_id
      and cp.left_at is null
      and cp.user_id <> new.user_id;

    if v_active_count >= 2 then
      raise exception 'call_room_full';
    end if;
  end if;

  return new;
end;
$function$


-- [40000000097] function private.tgg_enforce_membership_checkout_on_activation()
CREATE OR REPLACE FUNCTION private.tgg_enforce_membership_checkout_on_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_native_ready boolean:=false;
  v_link_ready boolean:=false;
  v_payout_ready boolean:=false;
  v_payout_mode text:='connect';
begin
  if coalesce(new.is_active,false)=true
     and coalesce(new.price_cents,0)>0
  then
    select coalesce(enabled,false)
      and mode='production'
      and coalesce(endpoint_configured,false)
    into v_native_ready
    from public.tgg_provider_runtime_config
    where provider_key='membership.stripe'
    limit 1;

    select
      coalesce(a.membership_payout_mode,'connect'),
      case
        when a.membership_payout_mode='platform' then true
        else (
          a.stripe_account_id is not null
          and coalesce(a.stripe_onboarding_complete,false)
          and coalesce(a.payouts_enabled,false)
        )
      end
    into v_payout_mode,v_payout_ready
    from public.artists a
    where a.id=new.artist_id;

    v_link_ready :=
      coalesce(new.stripe_payment_link_verified,false)
      and nullif(btrim(coalesce(new.stripe_payment_link_url,'')),'') is not null
      and new.stripe_payment_link_url ~ '^https://buy\.stripe\.com/'
      and coalesce(v_payout_ready,false);

    if not coalesce(v_native_ready,false)
       and not coalesce(v_link_ready,false)
    then
      raise exception 'MEMBERSHIP_CHECKOUT_REQUIRED'
        using detail='Paid membership tiers require native Stripe membership checkout OR a verified recurring Stripe Payment Link plus a valid payout mode.';
    end if;
  end if;

  return new;
end
$function$


-- [40000000098] function private.tgg_enforce_merch_checkout_path()
CREATE OR REPLACE FUNCTION private.tgg_enforce_merch_checkout_path()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_native_ready boolean:=false;
  v_link text:=nullif(btrim(coalesce(new.stripe_payment_link_url,'')),'');
begin
  if new.status='published' then
    select coalesce(enabled,false)
      and mode='production'
      and coalesce(endpoint_configured,false)
    into v_native_ready
    from public.tgg_provider_runtime_config
    where provider_key='stripe'
    limit 1;

    if not coalesce(v_native_ready,false) then
      if v_link is null then
        raise exception 'CHECKOUT_PATH_REQUIRED'
          using detail='Stripe runtime is unavailable. Add a Stripe Payment Link before publishing.';
      end if;

      if v_link !~ '^https://buy[.]stripe[.]com/' then
        raise exception 'INVALID_STRIPE_PAYMENT_LINK'
          using detail='Published products require a https://buy.stripe.com/ payment link while native checkout is unavailable.';
      end if;
    end if;
  end if;

  return new;
end
$function$


-- [40000000099] function private.tgg_enforce_merch_publish_checkout_path()
CREATE OR REPLACE FUNCTION private.tgg_enforce_merch_publish_checkout_path()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_native_ready boolean:=false;
begin
  if new.status='published'
     and (tg_op='INSERT' or old.status is distinct from 'published')
  then
    select coalesce(enabled,false)
      and mode='production'
      and coalesce(endpoint_configured,false)
    into v_native_ready
    from public.tgg_provider_runtime_config
    where provider_key='stripe'
    limit 1;

    if not coalesce(v_native_ready,false)
       and nullif(btrim(coalesce(new.stripe_payment_link_url,'')),'') is null
    then
      raise exception 'CHECKOUT_PATH_REQUIRED'
        using detail='Published merchandise requires native Stripe checkout or a valid Stripe Payment Link.';
    end if;
  end if;

  return new;
end
$function$


-- [40000000100] function private.tgg_enforce_one_final_baseline()
CREATE OR REPLACE FUNCTION private.tgg_enforce_one_final_baseline()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.status='locked' and new.version<>'V531-FINAL' then
    raise exception 'ONE_FINAL_BASELINE_GUARD: only V531-FINAL may be locked';
  end if;

  if tg_op='UPDATE'
     and old.version='V531-FINAL'
     and old.status='locked'
     and new.status<>'locked'
  then
    raise exception 'ONE_FINAL_BASELINE_GUARD: V531-FINAL may not be retired';
  end if;

  return new;
end
$function$


-- [40000000101] function private.tgg_enforce_one_final_routes()
CREATE OR REPLACE FUNCTION private.tgg_enforce_one_final_routes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_creator_os text:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-creator-os-app-v17?app=1';
begin
  if new.path ilike '%/functions/v1/creator-os-command-center%' then
    if new.route_key='owner_master_admin' then
      new.path:=v_creator_os||'#master-admin';
    else
      raise exception 'ONE_FINAL_RETIRED_ROUTE_FORBIDDEN';
    end if;
  end if;

  if new.route_key='owner_master_admin' then
    new.path:=v_creator_os||'#master-admin';
    new.title:='Master Admin';
    new.workspace_key:='master_admin';
    new.is_active:=true;
    new.is_primary:=true;
    new.description:='Owner-only Master Admin canonical Creator OS workspace.';
  elsif new.route_key='admin_dashboard' then
    new.path:='/p/admin-dashboard.html';
    new.is_active:=false; new.is_primary:=false;
    new.description:='Legacy Admin alias. Master Admin in Creator OS is canonical.';
  elsif new.route_key='artist_creator_os' then
    new.path:=v_creator_os;
    new.title:='Creator OS · ONE FINAL';
    new.workspace_key:='dashboard';
    new.is_active:=true; new.is_primary:=true;
  elsif new.route_key in ('creator_settings','artist_campaigns','artist_smartlinks','artist_phone') then
    new.is_active:=false; new.is_primary:=false;
    new.description:='Feature consolidated inside canonical Creator OS workspace; duplicate route alias retired.';
  elsif new.route_key in ('artist_opportunities','artist_credits','artist_academy') then
    new.path:='/p/career-os.html';
    new.is_active:=false; new.is_primary:=false;
    new.description:='Career sub-feature consolidated inside Career OS; duplicate route alias retired.';
  elsif new.route_key in ('artist_fans','artist_collaboration') then
    new.path:='/p/backstage.html';
    new.is_active:=false; new.is_primary:=false;
    new.description:='Backstage sub-feature consolidated inside Creator OS audience/connect workspaces; duplicate route alias retired.';
  elsif new.route_key in ('artist_releases','artist_distribution') then
    new.path:='/p/music-hub.html';
    new.is_active:=false; new.is_primary:=false;
    new.description:='Music sub-feature consolidated inside canonical Releases/Music workspaces; duplicate route alias retired.';
  elsif new.route_key in ('artist_calls','artist_live') then
    new.path:='/p/live.html';
    new.is_active:=false; new.is_primary:=false;
    new.description:='Live/calls sub-feature consolidated inside Creator OS Live and Messages; duplicate route alias retired.';
  elsif new.route_key='charts' then
    new.path:='/p/homepage.html';
    new.is_active:=false; new.is_primary:=false;
    new.description:='Charts alias retired until a dedicated charts surface exists; Discover remains canonical.';
  elsif new.route_key='artist_dashboard' then
    new.path:='/p/artist-dashboard_0633467215.html';
    new.is_active:=false; new.is_primary:=false;
    new.description:='Legacy Artist Dashboard compatibility alias. ONE-FINAL Creator OS is canonical.';
  elsif new.route_key='artist_command_center' then
    new.is_active:=false; new.is_primary:=false;
    new.description:='Retired Command Center compatibility route. ONE-FINAL Creator OS is canonical.';
  elsif new.route_key='artist_growth' then
    new.path:=v_creator_os||'#growth';
    new.workspace_key:='growth';
    new.is_active:=true; new.is_primary:=false;
    new.description:='Canonical ONE-FINAL Growth workspace route.';
  elsif new.route_key='releases' then
    new.path:='/search/label/Mixtapes';
    new.is_active:=false; new.is_primary:=false;
    new.description:='Public Releases alias retired; Mixtapes is canonical public catalog route.';
  elsif new.route_key='merch' then
    new.path:='/p/creator-store.html';
    new.is_active:=false; new.is_primary:=false;
    new.description:='Legacy Store alias retired; public_store is canonical.';
  elsif new.path='/p/command-center.html' or new.path like '/p/command-center.html#%' then
    new.is_active:=false; new.is_primary:=false;
    new.description:='Retired Command Center compatibility path. ONE-FINAL Creator OS is canonical.';
  end if;

  return new;
end
$function$


-- [40000000102] function private.tgg_evaluate_economy()
CREATE OR REPLACE FUNCTION private.tgg_evaluate_economy()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare n integer:=0;
begin
  update public.tgg_world_economy_metrics
  set status=case
      when target_min is not null and metric_value < target_min then 'imbalanced'
      when target_max is not null and metric_value > target_max then 'imbalanced'
      else 'healthy' end,
      updated_at=now();
  get diagnostics n = row_count;
  perform private.tgg_worker_mark('economy-evaluator','ok',jsonb_build_object('metrics_checked',n));
  return n;
exception when others then
  perform private.tgg_worker_mark('economy-evaluator','error',jsonb_build_object('error',sqlerrm));
  raise;
end;
$function$


-- [40000000103] function private.tgg_evaluate_story_rules()
CREATE OR REPLACE FUNCTION private.tgg_evaluate_story_rules()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare r record; rule record; n integer:=0; v_prestige integer; v_crew_rank integer; v_business_prestige integer; v_rivalry integer; v_season_level integer;
begin
  for r in select id from public.world_characters where character_status='active' loop
    select coalesce(prestige_level,0) into v_prestige from public.tgg_world_character_prestige where character_id=r.id;
    select coalesce(max(cp.rank_level),0) into v_crew_rank
      from public.tgg_world_crew_progression cp join public.tgg_world_crew_members cm on cm.crew_id=cp.crew_id
      where cm.character_id=r.id and cm.left_at is null;
    select coalesce(max(bp.prestige_level),0) into v_business_prestige
      from public.tgg_world_character_business_prestige bp join public.tgg_world_character_businesses b on b.id=bp.business_id
      where b.character_id=r.id;
    select coalesce(max(s.rivalry),0) into v_rivalry from public.tgg_world_character_npc_standing s where s.character_id=r.id;
    select coalesce(max(sp.season_level),0) into v_season_level from public.tgg_world_character_season_progress sp where sp.character_id=r.id;

    for rule in select * from public.tgg_world_story_generator_rules where enabled=true loop
      if (rule.source_type='prestige' and v_prestige >= coalesce((rule.source_conditions->>'prestige_level_gte')::int,999999))
      or (rule.source_type='crew_progression' and v_crew_rank >= coalesce((rule.source_conditions->>'crew_rank_gte')::int,999999))
      or (rule.source_type='business_prestige' and v_business_prestige >= coalesce((rule.source_conditions->>'prestige_gte')::int,999999))
      or (rule.source_type='npc_rivalry' and v_rivalry >= coalesce((rule.source_conditions->>'rivalry_gte')::int,999999))
      or (rule.source_type='season_progress' and v_season_level >= coalesce((rule.source_conditions->>'season_level_gte')::int,999999))
      then
        if not exists (
          select 1 from public.tgg_world_story_generation_queue q
          where q.character_id=r.id and q.rule_key=rule.rule_key
            and q.queued_at > now()-make_interval(mins=>rule.cooldown_minutes)
        ) then
          insert into public.tgg_world_story_generation_queue(character_id,rule_key,context)
          values(r.id,rule.rule_key,jsonb_build_object('template',rule.story_template));
          n:=n+1;
        end if;
      end if;
    end loop;
  end loop;
  perform private.tgg_worker_mark('story-evaluator','ok',jsonb_build_object('queued',n));
  return n;
exception when others then
  perform private.tgg_worker_mark('story-evaluator','error',jsonb_build_object('error',sqlerrm));
  raise;
end;
$function$


-- [40000000104] function private.tgg_expire_dynamic_events()
CREATE OR REPLACE FUNCTION private.tgg_expire_dynamic_events()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare n integer; v_open_mic jsonb;
begin
  update public.tgg_world_dynamic_events
  set status='expired',updated_at=now()
  where status in ('scheduled','active') and ends_at < now();
  get diagnostics n = row_count;
  v_open_mic := private.tgg_world_open_mic_recover_stale();
  perform private.tgg_worker_mark('dynamic-event-cleanup','ok',jsonb_build_object('expired',n,'open_mic',v_open_mic));
  return n;
exception when others then
  perform private.tgg_worker_mark('dynamic-event-cleanup','error',jsonb_build_object('error',sqlerrm));
  raise;
end;
$function$


-- [40000000105] function private.tgg_external_activation_matrix_payload()
CREATE OR REPLACE FUNCTION private.tgg_external_activation_matrix_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_call jsonb;
  v_secret_names text[];
  v_resend_handoff jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select public.tgg_call_validation_final_health() into v_call;

  select coalesce(array_agg(name order by name),'{}'::text[])
  into v_secret_names
  from vault.decrypted_secrets
  where lower(name) ~ '(livekit|turn|sfu|resend|stripe|dsp|revelator)';

  select coalesce(jsonb_build_object(
    'status',h.status,
    'required_action',h.required_action,
    'notes',h.notes
  ),'{}'::jsonb)
  into v_resend_handoff
  from public.tgg_provider_handoff h
  where h.provider_key='email.resend';

  return jsonb_build_object(
    'payments',jsonb_build_object(
      'payment_link',coalesce((select jsonb_build_object(
        'enabled',enabled,'mode',mode,'endpoint_configured',endpoint_configured,
        'disabled_reason',disabled_reason
      ) from public.tgg_provider_runtime_config where provider_key='stripe.payment_link'),'{}'::jsonb),
      'webhook',coalesce((select jsonb_build_object(
        'enabled',enabled,'mode',mode,'endpoint_configured',endpoint_configured,
        'disabled_reason',disabled_reason,
        'secret_present','tgg_stripe_webhook_secret'=any(v_secret_names)
      ) from public.tgg_provider_runtime_config where provider_key='stripe.webhook'),'{}'::jsonb),
      'full_server_api',coalesce((select jsonb_build_object(
        'enabled',enabled,'mode',mode,'endpoint_configured',endpoint_configured,
        'disabled_reason',disabled_reason
      ) from public.tgg_provider_runtime_config where provider_key='stripe'),'{}'::jsonb),
      'canonical_status','payment_link_and_webhook_production',
      'automatic_internal_blocker',false
    ),
    'email',jsonb_build_object(
      'resend',coalesce((select jsonb_build_object(
        'enabled',enabled,'mode',mode,'endpoint_configured',endpoint_configured,
        'disabled_reason',disabled_reason
      ) from public.tgg_provider_runtime_config where provider_key='email.resend'),'{}'::jsonb),
      'handoff',coalesce(v_resend_handoff,'{}'::jsonb),
      'account_connected',coalesce((v_resend_handoff#>>'{notes,account_connected}')::boolean,false),
      'api_key_objects_exist',coalesce((v_resend_handoff#>>'{notes,api_key_objects_exist}')::boolean,false),
      'api_key_object_count',coalesce((v_resend_handoff#>>'{notes,api_key_object_count}')::integer,0),
      'domain_status',coalesce(v_resend_handoff#>>'{notes,domain_status}','unknown'),
      'secret_present',exists(select 1 from unnest(v_secret_names) s where lower(s) like '%resend%'),
      'external_activation_required',true
    ),
    'distribution',jsonb_build_object(
      'provider',coalesce((select jsonb_build_object(
        'enabled',enabled,'mode',mode,'endpoint_configured',endpoint_configured,
        'disabled_reason',disabled_reason
      ) from public.tgg_provider_runtime_config where provider_key='distribution.provider'),'{}'::jsonb),
      'secret_present',exists(select 1 from unnest(v_secret_names) s where lower(s) ~ '(dsp|revelator)'),
      'external_activation_required',true
    ),
    'broadcast',jsonb_build_object(
      'sfu_turn',coalesce((select jsonb_build_object(
        'enabled',enabled,'mode',mode,'endpoint_configured',endpoint_configured,
        'disabled_reason',disabled_reason
      ) from public.tgg_provider_runtime_config where provider_key='broadcast.sfu_turn'),'{}'::jsonb),
      'secret_present',exists(select 1 from unnest(v_secret_names) s where lower(s) ~ '(livekit|turn|sfu)'),
      'external_activation_required',true
    ),
    'calls',jsonb_build_object(
      'two_user_validation',v_call,
      'external_human_validation_required',not coalesce((v_call->>'validated')::boolean,false)
    ),
    'automatic_internal_provider_work_remaining',0
  );
end;
$function$


-- [40000000106] function private.tgg_external_completion_state_safe()
CREATE OR REPLACE FUNCTION private.tgg_external_completion_state_safe()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with items as (
  select
    provider_key,
    category,
    status,
    required_action,
    safe_fallback,
    target_runtime,
    verification_check,
    coalesce(notes,'{}'::jsonb) notes,
    (
      provider_key='stripe.native'
      and coalesce((notes->>'owner_waived_optional_native_checkout')::boolean,false)
      and coalesce((notes->>'payment_link_fallback_ready')::boolean,false)
      and coalesce((notes->>'webhook_runtime_ready')::boolean,false)
    ) as optional_satisfied
  from public.tgg_provider_handoff
),
stats as (
  select
    count(*) as total_actions,
    count(*) filter(where status='complete' or optional_satisfied) as complete_actions,
    count(*) filter(where coalesce((notes->>'core_blocking')::boolean,false)) as core_blockers,
    count(*) filter(where status<>'complete' and not optional_satisfied) as full_connect_pending
  from items
)
select jsonb_build_object(
  'ok',true,
  'version','EXTERNAL-COMPLETION-ONE-FINAL-1.3',
  'core_complete',(select core_blockers=0 from stats),
  'core_blockers',(select core_blockers from stats),
  'fully_connected',(select full_connect_pending=0 from stats),
  'full_connect_pending',(select full_connect_pending from stats),
  'total_actions',(select total_actions from stats),
  'complete_actions',(select complete_actions from stats),
  'account_level',jsonb_build_object(
    'key','auth.leaked_password_protection',
    'complete',exists(
      select 1 from items
      where provider_key='auth.leaked_password_protection'
        and status='complete'
    ),
    'core_blocking',false,
    'verification','Supabase Security Advisor must no longer report auth_leaked_password_protection'
  ),
  'items',coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'provider_key',provider_key,
        'category',category,
        'status',case when optional_satisfied then 'satisfied_by_accepted_fallback' else status end,
        'required_action',required_action,
        'safe_fallback',safe_fallback,
        'target_runtime',target_runtime,
        'verification_check',verification_check,
        'core_blocking',coalesce((notes->>'core_blocking')::boolean,false),
        'full_connect_only',coalesce((notes->>'full_connect_only')::boolean,false),
        'auto_detected_complete',coalesce((notes->>'auto_detected_complete')::boolean,false),
        'optional_satisfied',optional_satisfied
      )
      order by category,provider_key
    )
    from items
  ),'[]'::jsonb),
  'generated_at',now()
)
from stats;
$function$


-- [40000000107] function private.tgg_external_handoff_packet_owner()
CREATE OR REPLACE FUNCTION private.tgg_external_handoff_packet_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
  v_queue jsonb;
  v_call jsonb;
  v_content jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  v_queue:=public.tgg_one_final_activation_queue();
  v_call:=public.tgg_call_validation_final_health();
  v_content:=public.tgg_content_readiness_final_health();

  return jsonb_build_object(
    'ok',true,
    'version','EXTERNAL-HANDOFF-ONE-FINAL-1.0',
    'core_launch_ready',coalesce((v_queue->>'core_launch_ready')::boolean,true),
    'actionable_remaining',coalesce((v_queue->>'actionable_remaining')::integer,(v_queue->>'remaining')::integer,0),
    'completed_major_items',jsonb_build_array(
      jsonb_build_object('key','blogger_maintenance_oauth','status','complete'),
      jsonb_build_object('key','distribution_master_assignment','status','complete'),
      jsonb_build_object('key','stripe_webhook_signing_secret','status','complete'),
      jsonb_build_object('key','membership_tier','status','complete')
    ),
    'remaining',jsonb_build_array(
      jsonb_build_object(
        'key','distribution_legal_metadata',
        'category','distribution',
        'status','external_action',
        'required_inputs',jsonb_build_array(
          'Real label/imprint for each DSP candidate',
          'Real copyright line',
          'Real publishing line',
          'Territories',
          'Rights confirmation'
        ),
        'candidate_releases',coalesce(v_content->'releases','[]'::jsonb),
        'verification_rpc','tgg_creator_distribution_readiness'
      ),
      jsonb_build_object(
        'key','distribution_provider',
        'category','distribution',
        'status','external_action',
        'provider_candidate','Revelator',
        'endpoint_status','reachable_auth_required',
        'required_inputs',jsonb_build_array(
          'Real Revelator production credential / API secret'
        ),
        'verification_path','Creator OS → Activation Bridge → DSP provider verification'
      ),
      jsonb_build_object(
        'key','sfu_turn_provider',
        'category','live',
        'status','external_action',
        'provider_candidate','LiveKit Cloud',
        'required_inputs',jsonb_build_array(
          'LIVEKIT_URL',
          'LIVEKIT_API_KEY',
          'LIVEKIT_API_SECRET'
        ),
        'verification_path','Creator OS → Activation Bridge → SFU/TURN verification'
      ),
      jsonb_build_object(
        'key','second_call_user',
        'category','calls',
        'status',case
          when coalesce((v_call->>'validated')::boolean,false) then 'complete'
          else 'ready'
        end,
        'required_inputs',jsonb_build_array(
          'Existing second authenticated account/device must claim the invite',
          'One real WebRTC offer-answer exchange'
        ),
        'verification_rpc','tgg_call_validation_final_health'
      ),
      jsonb_build_object(
        'key','supabase_leaked_password_protection',
        'category','hosted_supabase',
        'status','external_action',
        'required_inputs',jsonb_build_array(
          'Enable leaked-password protection in hosted Supabase Auth'
        ),
        'verification','Supabase Security Advisor warning disappears'
      ),
      jsonb_build_object(
        'key','edge_physical_cleanup',
        'category','maintenance',
        'status','external_action',
        'maintenance_only',true,
        'required_inputs',jsonb_build_array(
          'Supabase Management API delete privilege'
        ),
        'runtime_impact',false
      )
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000108] function private.tgg_fan_weekly_missions_refresh()
CREATE OR REPLACE FUNCTION private.tgg_fan_weekly_missions_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_week date:=(date_trunc('week',now()))::date;
  v_follow integer:=0;
  v_save integer:=0;
  v_engage integer:=0;
  v_all_complete boolean:=false;
  v_streak public.tgg_fan_mission_streaks;
  v_badge public.tgg_fan_mission_badges;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  insert into public.tgg_fan_weekly_missions(user_id,week_start,mission_key,title,description,target_value)
  values
    (v_uid,v_week,'follow_artist','Follow one artist','Follow at least one artist this week.',1),
    (v_uid,v_week,'save_release','Save one release','Save at least one release you want to hear again.',1),
    (v_uid,v_week,'engage_twice','Engage twice','React, comment, or complete listening activity two times this week.',2)
  on conflict(user_id,week_start,mission_key) do nothing;

  select count(*) into v_follow
  from public.artist_follows
  where user_id=v_uid and created_at>=v_week::timestamptz;

  select count(*) into v_save
  from public.release_saves
  where user_id=v_uid and created_at>=v_week::timestamptz;

  select
    (select count(*) from public.release_reactions where user_id=v_uid and created_at>=v_week::timestamptz)
    +(select count(*) from public.release_comments where user_id=v_uid and created_at>=v_week::timestamptz and coalesce(hidden_by_creator,false)=false)
    +(select count(*) from public.fan_listening_history where user_id=v_uid and listened_at>=v_week::timestamptz and completed=true)
  into v_engage;

  update public.tgg_fan_weekly_missions
  set current_value=least(target_value,case mission_key
      when 'follow_artist' then v_follow
      when 'save_release' then v_save
      when 'engage_twice' then v_engage
      else current_value end),
      status=case when case mission_key
        when 'follow_artist' then v_follow
        when 'save_release' then v_save
        when 'engage_twice' then v_engage
        else current_value end >= target_value then 'completed' else 'active' end,
      completed_at=case when case mission_key
        when 'follow_artist' then v_follow
        when 'save_release' then v_save
        when 'engage_twice' then v_engage
        else current_value end >= target_value then coalesce(completed_at,now()) else null end,
      updated_at=now()
  where user_id=v_uid and week_start=v_week;

  insert into public.tgg_fan_mission_streaks(user_id)
  values(v_uid)
  on conflict(user_id) do nothing;

  select count(*)=3 into v_all_complete
  from public.tgg_fan_weekly_missions
  where user_id=v_uid and week_start=v_week and status='completed';

  select * into v_streak
  from public.tgg_fan_mission_streaks
  where user_id=v_uid
  for update;

  if v_all_complete and v_streak.last_completed_week is distinct from v_week then
    update public.tgg_fan_mission_streaks
    set current_streak=case when last_completed_week=v_week-7 then current_streak+1 else 1 end,
        best_streak=greatest(best_streak,case when last_completed_week=v_week-7 then current_streak+1 else 1 end),
        last_completed_week=v_week,
        updated_at=now()
    where user_id=v_uid
    returning * into v_streak;

    insert into public.tgg_fan_mission_badges(user_id,badge_key,badge_title,badge_level,metadata)
    values(
      v_uid,
      'fan_week_complete',
      case
        when v_streak.current_streak>=8 then 'Superfan Legend'
        when v_streak.current_streak>=4 then 'Superfan Streak'
        when v_streak.current_streak>=2 then 'Active Supporter'
        else 'First Fan Week'
      end,
      greatest(v_streak.current_streak,1),
      jsonb_build_object('week_start',v_week,'streak',v_streak.current_streak)
    )
    on conflict(user_id,badge_key,badge_level) do nothing
    returning * into v_badge;
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','FAN-MISSIONS-1.0',
    'week_start',v_week,
    'missions',(select coalesce(jsonb_agg(jsonb_build_object(
      'mission_key',mission_key,'title',title,'description',description,
      'current_value',current_value,'target_value',target_value,'status',status,'completed_at',completed_at
    ) order by created_at),'[]'::jsonb)
      from public.tgg_fan_weekly_missions
      where user_id=v_uid and week_start=v_week),
    'streak',to_jsonb(v_streak),
    'badges',(select coalesce(jsonb_agg(jsonb_build_object(
      'title',badge_title,'level',badge_level,'earned_at',earned_at
    ) order by earned_at desc),'[]'::jsonb)
      from public.tgg_fan_mission_badges where user_id=v_uid),
    'generated_at',now()
  );
end
$function$


-- [40000000109] function private.tgg_gap_only_bulk_state()
CREATE OR REPLACE FUNCTION private.tgg_gap_only_bulk_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runtime jsonb:=public.tgg_runtime_drift_guard();
  v_vision jsonb:=public.tgg_one_vision_state();
  v_recorded jsonb:=public.tgg_one_recorded_completeness();
  v_train jsonb:=public.tgg_one_freight_train_state();
  v_scout jsonb:=public.tgg_one_scout_state();
  v_provider jsonb:=public.tgg_provider_health_state();
  v_matrix jsonb:=public.tgg_matrix_gateway_health_state();
  v_lewis jsonb:=public.tgg_lewis_portal_health_state();
  v_exit jsonb:=public.tgg_one_exit_state();
  v_black jsonb:=public.tgg_one_black_box_state();

  v_runtime_failed int:=jsonb_array_length(coalesce(v_runtime->'failed','[]'::jsonb));
  v_browser_fail int:=coalesce((v_vision->>'browser_failures')::int,0);
  v_visual_fail int:=coalesce((v_vision->>'visual_failures')::int,0);
  v_layout_findings int:=coalesce((v_vision->>'overlap_total')::int,0)
                       +coalesce((v_vision->>'clipped_text_total')::int,0)
                       +coalesce((v_vision->>'stuck_loading')::int,0)
                       +coalesce((v_vision->>'duplicate_shell')::int,0)
                       +coalesce((v_vision->>'accessibility_findings')::int,0);
  v_safe_ready int:=coalesce((v_train->>'safe_ready')::int,0);
  v_active_jobs int:=coalesce((v_train->>'active_jobs')::int,0);
  v_open_failures int:=coalesce((v_scout->>'open_build_failures')::int,0);
  v_codesync_review int:=coalesce((v_scout->>'open_codesync_issues')::int,0);
  v_external int:=coalesce((v_provider->>'external_action_required')::int,0);

  v_auth_complete boolean;
  v_launch_complete boolean;
  v_public_complete boolean;
  v_payment_complete boolean;
  v_mobile_complete boolean;
  v_release_complete boolean;
  v_internal_close boolean;

  v_categories jsonb:='[]'::jsonb;
  v_next jsonb:='{}'::jsonb;
  v_pass int:=0;
  v_review int:=0;
  v_blocked int:=0;
  v_status text:='complete';
  v_id uuid;
begin
  select exists(select 1 from public.tgg_build_milestones
    where release_id='433251c2-3ca3-4d95-a535-8b438f0e094c'
      and milestone_key='authenticated-creator-flow' and status='complete')
  into v_auth_complete;

  select exists(select 1 from public.tgg_build_milestones
    where release_id='433251c2-3ca3-4d95-a535-8b438f0e094c'
      and milestone_key in ('final-launch-smoke','final-launch-smoke-validation','launch-smoke-validation')
      and status='complete')
  into v_launch_complete;

  select exists(select 1 from public.tgg_build_milestones
    where release_id='433251c2-3ca3-4d95-a535-8b438f0e094c'
      and milestone_key in ('public-discovery-smoke','public-release-playback-payment-smoke')
      and status='complete')
  into v_public_complete;

  select exists(select 1 from public.tgg_build_milestones
    where release_id='433251c2-3ca3-4d95-a535-8b438f0e094c'
      and milestone_key in ('launch-smoke-public-payments','public-release-playback-payment-smoke')
      and status='complete')
  into v_payment_complete;

  select exists(select 1 from public.tgg_build_milestones
    where release_id='433251c2-3ca3-4d95-a535-8b438f0e094c'
      and milestone_key='notifications-mobile-polish-smoke' and status='complete')
  into v_mobile_complete;

  select exists(select 1 from public.tgg_build_milestones
    where release_id='433251c2-3ca3-4d95-a535-8b438f0e094c'
      and milestone_key='release-lifecycle-smoke' and status='complete')
  into v_release_complete;

  select exists(select 1 from public.tgg_build_milestones
    where release_id='433251c2-3ca3-4d95-a535-8b438f0e094c'
      and milestone_key='safe-internal-build-closure' and status='complete')
  into v_internal_close;

  v_categories:=v_categories||jsonb_build_array(jsonb_build_object(
    'key','runtime_and_architecture',
    'status',case when v_runtime_failed=0 and coalesce((v_recorded->>'ok')::boolean,false) then 'pass' else 'blocked' end,
    'already_completed',v_internal_close,
    'evidence',jsonb_build_object('runtime_failed',v_runtime_failed,'recorded_completeness',coalesce((v_recorded->>'ok')::boolean,false))
  ));
  if v_runtime_failed=0 and coalesce((v_recorded->>'ok')::boolean,false) then v_pass:=v_pass+1; else v_blocked:=v_blocked+1; end if;

  v_categories:=v_categories||jsonb_build_array(jsonb_build_object(
    'key','browser_visual_mobile',
    'status',case when v_browser_fail=0 and v_visual_fail=0 and v_layout_findings=0 then 'pass' else 'blocked' end,
    'already_completed',v_mobile_complete or v_launch_complete,
    'evidence',jsonb_build_object('browser_failures',v_browser_fail,'visual_failures',v_visual_fail,'layout_accessibility_findings',v_layout_findings)
  ));
  if v_browser_fail=0 and v_visual_fail=0 and v_layout_findings=0 then v_pass:=v_pass+1; else v_blocked:=v_blocked+1; end if;

  v_categories:=v_categories||jsonb_build_array(jsonb_build_object(
    'key','authenticated_creator_flow',
    'status',case when v_auth_complete then 'pass' else 'review' end,
    'already_completed',v_auth_complete,
    'canonical_milestone','authenticated-creator-flow',
    'skip_duplicate_smoke_milestones',true
  ));
  if v_auth_complete then v_pass:=v_pass+1; else v_review:=v_review+1; end if;

  v_categories:=v_categories||jsonb_build_array(jsonb_build_object(
    'key','public_discovery_playback',
    'status',case when v_public_complete then 'pass' else 'review' end,
    'already_completed',v_public_complete
  ));
  if v_public_complete then v_pass:=v_pass+1; else v_review:=v_review+1; end if;

  v_categories:=v_categories||jsonb_build_array(jsonb_build_object(
    'key','payments',
    'status',case when v_payment_complete then 'pass' else 'review' end,
    'already_completed',v_payment_complete,
    'accepted_path','payment_link_plus_webhook'
  ));
  if v_payment_complete then v_pass:=v_pass+1; else v_review:=v_review+1; end if;

  v_categories:=v_categories||jsonb_build_array(jsonb_build_object(
    'key','release_lifecycle',
    'status',case when v_release_complete then 'pass' else 'review' end,
    'already_completed',v_release_complete
  ));
  if v_release_complete then v_pass:=v_pass+1; else v_review:=v_review+1; end if;

  v_categories:=v_categories||jsonb_build_array(jsonb_build_object(
    'key','portals_and_return',
    'status',case
      when coalesce(v_matrix->>'status','restricted')='healthy'
       and coalesce(v_lewis->>'status','restricted')='healthy'
       and coalesce(v_exit->>'status','restricted')='ready'
      then 'pass' else 'blocked' end,
    'already_completed',v_launch_complete,
    'evidence',jsonb_build_object('matrix',v_matrix->>'status','lewis',v_lewis->>'status','exit',v_exit->>'status')
  ));
  if coalesce(v_matrix->>'status','restricted')='healthy'
     and coalesce(v_lewis->>'status','restricted')='healthy'
     and coalesce(v_exit->>'status','restricted')='ready'
  then v_pass:=v_pass+1; else v_blocked:=v_blocked+1; end if;

  v_categories:=v_categories||jsonb_build_array(jsonb_build_object(
    'key','safe_internal_backlog',
    'status',case when v_safe_ready=0 and v_active_jobs=0 and v_open_failures=0 then 'pass' else 'blocked' end,
    'already_completed',v_internal_close,
    'evidence',jsonb_build_object('safe_ready',v_safe_ready,'active_jobs',v_active_jobs,'open_build_failures',v_open_failures)
  ));
  if v_safe_ready=0 and v_active_jobs=0 and v_open_failures=0 then v_pass:=v_pass+1; else v_blocked:=v_blocked+1; end if;

  v_categories:=v_categories||jsonb_build_array(jsonb_build_object(
    'key','protected_codesync',
    'status',case when v_codesync_review>0 then 'review' else 'pass' end,
    'already_completed',true,
    'review_only',true,
    'auto_fix_allowed',false,
    'evidence',jsonb_build_object('open_codesync_issues',v_codesync_review)
  ));
  if v_codesync_review>0 then v_review:=v_review+1; else v_pass:=v_pass+1; end if;

  v_categories:=v_categories||jsonb_build_array(jsonb_build_object(
    'key','external_activation',
    'status',case when v_external>0 then 'external' else 'pass' end,
    'already_completed',false,
    'deferred_external',v_external>0,
    'evidence',jsonb_build_object('external_action_required',v_external)
  ));

  v_categories:=v_categories||jsonb_build_array(jsonb_build_object(
    'key','recorded_evidence',
    'status',case when coalesce(v_black->>'status','restricted')<>'restricted' then 'pass' else 'blocked' end,
    'already_completed',true,
    'evidence',jsonb_build_object('black_box_status',v_black->>'status')
  ));
  if coalesce(v_black->>'status','restricted')<>'restricted' then v_pass:=v_pass+1; else v_blocked:=v_blocked+1; end if;

  if v_blocked>0 then
    v_status:='blocked';
  elsif v_external>0 then
    v_status:='external';
  elsif v_review>0 then
    v_status:='review';
  else
    v_status:='complete';
  end if;

  if v_blocked>0 then
    select x into v_next
    from jsonb_array_elements(v_categories) x
    where x->>'status'='blocked'
    limit 1;
  else
    select x into v_next
    from jsonb_array_elements(v_categories) x
    where x->>'status'='review'
      and coalesce((x->>'already_completed')::boolean,false)=false
    limit 1;

    if v_next is null or v_next='{}'::jsonb then
      if v_external>0 then
        v_next:=jsonb_build_object(
          'key','external_activation',
          'status','external',
          'reason','no internal work remains; only real account credentials/settings or second-device actions remain'
        );
      elsif v_review>0 then
        v_next:=jsonb_build_object(
          'key','none_internal',
          'status','complete',
          'reason','only protected review-only items remain'
        );
      else
        v_next:=jsonb_build_object('key','none','status','complete','reason','everything checked');
      end if;
    end if;
  end if;

  insert into private.tgg_gap_master_snapshots(
    version,status,pass_count,review_count,external_count,blocked_count,categories,next_action
  )
  values(
    'GAP-CHECK-EVERYTHING-2.0',v_status,v_pass,v_review,v_external,v_blocked,
    v_categories,coalesce(v_next,'{}'::jsonb)
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',v_blocked=0,
    'mode','check_everything_skip_completed',
    'version','GAP-CHECK-EVERYTHING-2.0',
    'snapshot_id',v_id,
    'status',v_status,
    'checked_at',now(),
    'pass_count',v_pass,
    'review_count',v_review,
    'external_action_required',v_external,
    'blocked_count',v_blocked,
    'categories',v_categories,
    'next_action',coalesce(v_next,'{}'::jsonb),
    'skip_completed',true,
    'skip_duplicate_smoke_milestones',true,
    'nothing_internal_to_repeat',v_safe_ready=0 and v_active_jobs=0 and v_open_failures=0,
    'production_auto_publish',false,
    'production_promotion_allowed',false,
    'preserve_approval_gates',true,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end $function$


-- [40000000110] function private.tgg_generate_balance_recommendations()
CREATE OR REPLACE FUNCTION private.tgg_generate_balance_recommendations()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare r record; n integer:=0;
begin
  for r in
    select br.balance_key,br.metric_key,br.trigger_conditions,br.recommendation,em.metric_value
    from public.tgg_world_balance_rules br
    join public.tgg_world_economy_metrics em on em.metric_key=br.metric_key
    where br.enabled=true and em.status='imbalanced'
  loop
    if not exists (
      select 1 from public.tgg_world_balance_recommendations x
      where x.balance_key=r.balance_key and x.status='open'
        and x.generated_at > now()-interval '1 day'
    ) then
      insert into public.tgg_world_balance_recommendations(balance_key,metric_key,metric_value,recommendation)
      values(r.balance_key,r.metric_key,r.metric_value,r.recommendation);
      n:=n+1;
    end if;
  end loop;
  perform private.tgg_worker_mark('balance-recommender','ok',jsonb_build_object('generated',n));
  return n;
exception when others then
  perform private.tgg_worker_mark('balance-recommender','error',jsonb_build_object('error',sqlerrm));
  raise;
end;
$function$


-- [40000000111] function private.tgg_get_own_artist_payment_status(p_artist_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_get_own_artist_payment_status(p_artist_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_result jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select jsonb_build_object(
    'stripe_onboarding_complete',coalesce(a.stripe_onboarding_complete,false),
    'payouts_enabled',coalesce(a.payouts_enabled,false)
  )
  into v_result
  from public.artists a
  where a.id=p_artist_id
    and a.user_id=v_uid;

  if v_result is null then raise exception 'artist profile not found'; end if;
  return v_result;
end
$function$


-- [40000000112] function private.tgg_get_provider_secret_service(p_provider_key text)
CREATE OR REPLACE FUNCTION private.tgg_get_provider_secret_service(p_provider_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
  v_secret text;
begin
  v_name:=case p_provider_key
    when 'stripe.webhook' then 'tgg_stripe_webhook_secret'
    when 'distribution.provider' then 'tgg_distribution_provider_secret'
    when 'broadcast.sfu_turn' then 'tgg_broadcast_provider_secret'
    when 'email.resend' then 'tgg_resend_api_key'
    when 'webpush.vapid' then 'tgg_webpush_vapid'
    when 'webpush.delivery_hook' then 'tgg_webpush_delivery_hook'
    else null
  end;

  if v_name is null then return null; end if;

  select decrypted_secret into v_secret
  from vault.decrypted_secrets
  where name=v_name
  order by created_at desc
  limit 1;

  return v_secret;
end
$function$


-- [40000000113] function private.tgg_growth_autopilot_complete_step(p_step_key text, p_day integer, p_metadata jsonb)
CREATE OR REPLACE FUNCTION private.tgg_growth_autopilot_complete_step(p_step_key text, p_day integer, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_week date:=(date_trunc('week',now()))::date;
  v_step text:=lower(trim(coalesce(p_step_key,'')));
  v_row public.tgg_growth_autopilot_progress;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_day is null or p_day<1 or p_day>7 then raise exception 'AUTOPILOT_DAY_INVALID' using errcode='22023'; end if;
  if v_step not in ('profile_push','release_push','referral_push','save_push','smart_link','repeat_winner','weekly_close') then
    raise exception 'AUTOPILOT_STEP_INVALID' using errcode='22023';
  end if;
  if octet_length(coalesce(p_metadata,'{}'::jsonb)::text)>2048 then
    raise exception 'AUTOPILOT_METADATA_TOO_LARGE' using errcode='22023';
  end if;

  select id into v_artist_id from public.artists where user_id=v_uid order by created_at limit 1;
  if v_artist_id is null then raise exception 'ARTIST_PROFILE_REQUIRED' using errcode='P0002'; end if;

  insert into public.tgg_growth_autopilot_progress(
    owner_user_id,artist_id,week_start,step_key,day_no,metadata
  )
  values(v_uid,v_artist_id,v_week,v_step,p_day,coalesce(p_metadata,'{}'::jsonb))
  on conflict(owner_user_id,week_start,step_key) do update
  set completed_at=public.tgg_growth_autopilot_progress.completed_at,
      metadata=public.tgg_growth_autopilot_progress.metadata
  returning * into v_row;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-AUTOPILOT-PROGRESS-1.0',
    'step_key',v_row.step_key,
    'day',v_row.day_no,
    'status',v_row.status,
    'completed_at',v_row.completed_at
  );
end
$function$


-- [40000000114] function private.tgg_growth_brain_refresh()
CREATE OR REPLACE FUNCTION private.tgg_growth_brain_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_scorecard jsonb;
  v_forecast jsonb;
  v_audience jsonb;
  v_attribution jsonb;
  v_wins jsonb;
  v_progress jsonb;
  v_score integer:=0;
  v_grade text;
  v_stage text;
  v_focus text:='execution';
  v_action_key text:='execute_weekly_plan';
  v_action_title text:='Execute your weekly Growth plan';
  v_action_rationale text:='Your best move is to complete the next Growth action and create measurable activity.';
  v_confidence integer:=80;
  v_previous_key text;
  v_changed boolean:=false;
  v_signals jsonb;
  v_snapshot_id uuid;
  v_followers bigint:=0;
  v_referrals bigint:=0;
  v_clicks bigint:=0;
  v_shares bigint:=0;
  v_fan_signals bigint:=0;
  v_plays bigint:=0;
  v_downloads bigint:=0;
  v_weekly numeric:=0;
  v_expected numeric:=0;
  v_momentum bigint:=0;
  v_forecast_next jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-BRAIN-1.0',
      'has_artist_profile',false,'generated_at',now()
    );
  end if;

  v_scorecard:=public.tgg_growth_scorecard();
  v_forecast:=public.tgg_growth_forecast();
  v_audience:=public.tgg_growth_audience_intelligence();
  v_attribution:=public.tgg_growth_attribution_funnel();
  v_wins:=public.tgg_growth_wins_summary();
  v_progress:=public.tgg_growth_autopilot_progress();

  v_score:=coalesce((v_scorecard->>'score')::integer,0);
  v_grade:=v_scorecard->>'grade';
  v_stage:=v_scorecard->>'stage';
  v_followers:=coalesce((v_scorecard#>>'{benchmarks,followers}')::bigint,0);
  v_referrals:=coalesce((v_scorecard#>>'{benchmarks,referrals}')::bigint,0);
  v_clicks:=coalesce((v_attribution#>>'{funnel,smart_link_clicks}')::bigint,0);
  v_shares:=coalesce((v_attribution#>>'{funnel,tracked_shares}')::bigint,0);
  v_fan_signals:=
    coalesce((v_attribution#>>'{funnel,followers}')::bigint,0)
    +coalesce((v_attribution#>>'{funnel,release_saves}')::bigint,0)
    +coalesce((v_attribution#>>'{funnel,reactions}')::bigint,0)
    +coalesce((v_attribution#>>'{funnel,comments}')::bigint,0)
    +coalesce((v_attribution#>>'{funnel,referral_conversions}')::bigint,0);
  v_plays:=coalesce((v_scorecard#>>'{benchmarks,release_plays}')::bigint,0);
  v_downloads:=coalesce((v_scorecard#>>'{benchmarks,release_downloads}')::bigint,0);
  v_weekly:=coalesce((v_forecast->>'overall_progress_pct')::numeric,0);
  v_expected:=coalesce((v_forecast->>'expected_progress_pct')::numeric,0);
  v_momentum:=coalesce((v_wins#>>'{last_7_days,momentum_score}')::bigint,0);
  v_forecast_next:=coalesce(v_forecast->'next_best_action','{}'::jsonb);

  if v_weekly+10 < v_expected and nullif(v_forecast_next->>'action_type','') is not null then
    v_focus:='execution';
    v_action_key:=v_forecast_next->>'action_type';
    v_action_title:=coalesce(v_forecast_next->>'title','Catch up your weekly Growth plan');
    v_action_rationale:=coalesce(v_forecast_next->>'rationale','Your weekly execution pace is behind the expected pace.');
    v_confidence:=94;
  elsif v_followers=0 and v_referrals=0 then
    v_focus:='audience_acquisition';
    v_action_key:='earn_first_follower';
    v_action_title:='Earn your first follower';
    v_action_rationale:='Your releases are live, but the audience layer has no follower or referral conversion yet. Push your artist profile and strongest release to people who already know your music.';
    v_confidence:=93;
  elsif v_shares=0 then
    v_focus:='distribution';
    v_action_key:='create_tracked_share';
    v_action_title:='Create your first tracked share';
    v_action_rationale:='Attribution has no tracked shares yet, so the Brain cannot learn which source converts best. Use Growth share tools to create the first measurable distribution signal.';
    v_confidence:=92;
  elsif v_clicks=0 then
    v_focus:='traffic';
    v_action_key:='drive_smart_link_clicks';
    v_action_title:='Drive your first smart-link clicks';
    v_action_rationale:='Tracked sharing exists but no smart-link clicks are registered. Repeat the strongest release/profile push with a clear listen or follow CTA.';
    v_confidence:=90;
  elsif v_fan_signals=0 then
    v_focus:='conversion';
    v_action_key:='convert_first_fan_signal';
    v_action_title:='Convert traffic into one fan signal';
    v_action_rationale:='Traffic is arriving, but it has not converted into a follow, save, reaction, comment, or referral. Tighten the CTA around one specific fan action.';
    v_confidence:=89;
  elsif v_plays+v_downloads=0 then
    v_focus:='content_response';
    v_action_key:='drive_release_response';
    v_action_title:='Drive measurable release response';
    v_action_rationale:='Your audience and traffic layers have activity, but release plays/downloads still need a measurable response.';
    v_confidence:=86;
  elsif v_momentum=0 then
    v_focus:='momentum';
    v_action_key:='repeat_winning_action';
    v_action_title:='Repeat the strongest recent action';
    v_action_rationale:='The funnel has activity but seven-day momentum is still flat. Repeat the channel or CTA that produced the strongest response.';
    v_confidence:=84;
  else
    v_focus:='scaling';
    v_action_key:='scale_winner';
    v_action_title:='Scale the strongest growth loop';
    v_action_rationale:='Core acquisition and conversion signals are active. Concentrate effort on the source and campaign producing the best measured response.';
    v_confidence:=82;
  end if;

  select top_action_key into v_previous_key
  from public.tgg_creator_growth_brain_snapshots
  where owner_user_id=v_uid
  order by created_at desc
  limit 1;

  v_changed:=v_previous_key is not null and v_previous_key<>v_action_key;

  v_signals:=jsonb_build_object(
    'scorecard',jsonb_build_object('score',v_score,'grade',v_grade,'stage',v_stage),
    'weekly',jsonb_build_object(
      'progress_pct',v_weekly,
      'expected_pct',v_expected,
      'pace',v_forecast->>'pace',
      'risk',v_forecast->>'risk'
    ),
    'audience',jsonb_build_object('followers',v_followers,'referrals',v_referrals),
    'attribution',jsonb_build_object(
      'tracked_shares',v_shares,
      'smart_link_clicks',v_clicks,
      'fan_signals',v_fan_signals
    ),
    'content',jsonb_build_object('plays',v_plays,'downloads',v_downloads),
    'momentum_7d',v_momentum,
    'autopilot',jsonb_build_object(
      'completion_percent',coalesce((v_progress->>'completion_percent')::numeric,0)
    )
  );

  insert into public.tgg_creator_growth_brain_snapshots(
    owner_user_id,artist_id,focus_area,top_action_key,top_action_title,
    top_action_rationale,confidence,score,grade,stage,changed_from_previous,
    previous_action_key,signals
  )
  values(
    v_uid,v_artist_id,v_focus,v_action_key,v_action_title,
    v_action_rationale,v_confidence,v_score,v_grade,v_stage,v_changed,
    v_previous_key,v_signals
  )
  returning id into v_snapshot_id;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-BRAIN-1.0',
    'snapshot_id',v_snapshot_id,
    'focus_area',v_focus,
    'top_action',jsonb_build_object(
      'key',v_action_key,
      'title',v_action_title,
      'rationale',v_action_rationale,
      'confidence',v_confidence
    ),
    'changed_from_previous',v_changed,
    'previous_action_key',v_previous_key,
    'score',v_score,
    'grade',v_grade,
    'stage',v_stage,
    'signals',v_signals,
    'generated_at',now()
  );
end
$function$


-- [40000000115] function private.tgg_growth_experiment_record_share(p_variant_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_growth_experiment_record_share(p_variant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_variant public.tgg_growth_experiment_variants;
  v_exp public.tgg_growth_experiments;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select v.* into v_variant
  from public.tgg_growth_experiment_variants v
  join public.tgg_growth_experiments e on e.id=v.experiment_id
  where v.id=p_variant_id and e.owner_user_id=v_uid and e.status='active';

  if v_variant.id is null then raise exception 'EXPERIMENT_VARIANT_NOT_FOUND' using errcode='P0002'; end if;

  select * into v_exp from public.tgg_growth_experiments where id=v_variant.experiment_id;

  insert into public.tgg_growth_experiment_events(experiment_id,variant_id,owner_user_id,event_type,source)
  values(v_variant.experiment_id,v_variant.id,v_uid,'share','creator_os_growth');

  update public.tgg_growth_experiment_variants
  set share_count=share_count+1,updated_at=now()
  where id=v_variant.id
  returning * into v_variant;

  return jsonb_build_object(
    'ok',true,'variant_id',v_variant.id,'variant_key',v_variant.variant_key,
    'share_count',v_variant.share_count,
    'tracking',jsonb_build_object(
      'utm_campaign','growth_ab',
      'utm_medium','variant',
      'utm_source',v_variant.variant_key
    )
  );
end
$function$


-- [40000000116] function private.tgg_growth_experiment_refresh()
CREATE OR REPLACE FUNCTION private.tgg_growth_experiment_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist public.artists;
  v_release public.mixtapes;
  v_link public.tgg_smart_links;
  v_promo jsonb;
  v_items jsonb;
  v_a text;
  v_b text;
  v_exp public.tgg_growth_experiments;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_artist from public.artists where user_id=v_uid order by created_at limit 1;
  if v_artist.id is null then
    return jsonb_build_object('ok',true,'version','GROWTH-EXPERIMENTS-1.0','has_artist_profile',false,'experiments','[]'::jsonb);
  end if;

  select * into v_release
  from public.mixtapes
  where artist_id=v_artist.id and status='published'
  order by coalesce(featured,false) desc,(coalesce(play_count,0)+coalesce(download_count,0)*3) desc,created_at desc
  limit 1;

  if v_release.id is null then
    return jsonb_build_object('ok',true,'version','GROWTH-EXPERIMENTS-1.0','has_artist_profile',true,'experiments','[]'::jsonb);
  end if;

  select * into v_link
  from public.tgg_smart_links
  where owner_user_id=v_uid and release_id=v_release.id and is_active=true
  order by created_at
  limit 1;

  v_promo:=public.tgg_growth_promo_kit();
  v_items:=coalesce(v_promo->'items','[]'::jsonb);
  select x->>'copy' into v_a from jsonb_array_elements(v_items) x where x->>'key'='social_post' limit 1;
  select x->>'copy' into v_b from jsonb_array_elements(v_items) x where x->>'key'='short' limit 1;

  if v_a is null or v_b is null then
    return jsonb_build_object('ok',true,'version','GROWTH-EXPERIMENTS-1.0','has_artist_profile',true,'experiments','[]'::jsonb);
  end if;

  insert into public.tgg_growth_experiments(
    owner_user_id,artist_id,release_id,smart_link_id,experiment_key,title,status
  ) values(
    v_uid,v_artist.id,v_release.id,v_link.id,'promo-copy-'||v_release.id::text,
    'Promo Copy Test · '||v_release.title,'active'
  )
  on conflict(owner_user_id,experiment_key) do update
  set smart_link_id=coalesce(excluded.smart_link_id,public.tgg_growth_experiments.smart_link_id),
      updated_at=now()
  returning * into v_exp;

  insert into public.tgg_growth_experiment_variants(experiment_id,variant_key,label,promo_copy)
  values
    (v_exp.id,'A','Social Post',v_a),
    (v_exp.id,'B','Short / Reel',v_b)
  on conflict(experiment_id,variant_key) do update
  set label=excluded.label,promo_copy=excluded.promo_copy,updated_at=now();

  update public.tgg_growth_experiment_variants v
  set click_count=coalesce((
    select count(*) from public.tgg_smart_link_events sle
    where sle.link_id=v_exp.smart_link_id
      and sle.event_type='click'
      and sle.utm_campaign='growth_ab'
      and sle.utm_medium='variant'
      and upper(coalesce(sle.utm_source,''))=v.variant_key
  ),0),
  updated_at=now()
  where v.experiment_id=v_exp.id;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-EXPERIMENTS-1.0',
    'experiment',jsonb_build_object(
      'id',v_exp.id,
      'title',v_exp.title,
      'status',v_exp.status,
      'release_id',v_exp.release_id,
      'smart_link_id',v_exp.smart_link_id
    ),
    'variants',(
      select coalesce(jsonb_agg(jsonb_build_object(
        'id',v.id,'variant_key',v.variant_key,'label',v.label,'promo_copy',v.promo_copy,
        'share_count',v.share_count,'click_count',v.click_count,
        'ctr',case when v.share_count>0 then round((v.click_count::numeric/v.share_count::numeric)*100,2) else 0 end
      ) order by v.variant_key),'[]'::jsonb)
      from public.tgg_growth_experiment_variants v where v.experiment_id=v_exp.id
    ),
    'winner',(
      select to_jsonb(w) from (
        select variant_key,label,share_count,click_count,
          case when share_count>0 then round((click_count::numeric/share_count::numeric)*100,2) else 0 end as ctr
        from public.tgg_growth_experiment_variants
        where experiment_id=v_exp.id
        order by
          case when share_count>0 then click_count::numeric/share_count::numeric else 0 end desc,
          click_count desc,share_count desc,variant_key
        limit 1
      ) w
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000117] function private.tgg_growth_milestone_sync()
CREATE OR REPLACE FUNCTION private.tgg_growth_milestone_sync()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_followers bigint:=0;
  v_saves bigint:=0;
  v_referrals bigint:=0;
  v_plays bigint:=0;
  v_smart_links bigint:=0;
  v_new integer:=0;
  v_resolved integer:=0;
  v_rc integer:=0;
  v_inserted public.tgg_creator_growth_milestones;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object('ok',true,'version','GROWTH-MILESTONES-1.0','has_artist_profile',false,'new_milestones',0,'resolved_actions',0,'milestones','[]'::jsonb);
  end if;

  select count(*) into v_followers from public.artist_follows where artist_id=v_artist_id;
  select count(*) into v_saves from public.release_saves rs join public.mixtapes m on m.id=rs.mixtape_id where m.artist_id=v_artist_id and m.status='published';
  select count(*) into v_referrals from public.tgg_referral_claims where referrer_user_id=v_uid;
  select coalesce(sum(play_count),0) into v_plays from public.mixtapes where artist_id=v_artist_id and status='published';
  select count(*) into v_smart_links from public.tgg_smart_links where owner_user_id=v_uid and is_active=true;

  if v_followers>0 then
    insert into public.tgg_creator_growth_milestones(owner_user_id,artist_id,milestone_key,milestone_title,milestone_value,metadata)
    values(v_uid,v_artist_id,'first_follower','First follower earned',v_followers,jsonb_build_object('followers',v_followers))
    on conflict(owner_user_id,milestone_key) do nothing
    returning * into v_inserted;
    if v_inserted.id is not null then
      v_new:=v_new+1;
      insert into public.notifications(recipient_id,notification_type,entity_type,entity_id,title,body)
      values(v_uid,'growth_milestone','growth_milestone',v_inserted.id,'Growth milestone unlocked','You earned your first follower.');
    end if;
    update public.tgg_creator_action_queue set status='completed',updated_at=now()
    where owner_user_id=v_uid and source_type='growth' and action_type='earn_first_follower' and status='open';
    get diagnostics v_rc=row_count; v_resolved:=v_resolved+v_rc;
  end if;

  if v_smart_links>0 then
    v_inserted:=null;
    insert into public.tgg_creator_growth_milestones(owner_user_id,artist_id,milestone_key,milestone_title,milestone_value,metadata)
    values(v_uid,v_artist_id,'first_smart_link','First smart link created',v_smart_links,jsonb_build_object('smart_links',v_smart_links))
    on conflict(owner_user_id,milestone_key) do nothing
    returning * into v_inserted;
    if v_inserted.id is not null then
      v_new:=v_new+1;
      insert into public.notifications(recipient_id,notification_type,entity_type,entity_id,title,body)
      values(v_uid,'growth_milestone','growth_milestone',v_inserted.id,'Growth milestone unlocked','Your first smart link is live.');
    end if;
    update public.tgg_creator_action_queue set status='completed',updated_at=now()
    where owner_user_id=v_uid and source_type='growth' and action_type='create_smart_link' and status='open';
    get diagnostics v_rc=row_count; v_resolved:=v_resolved+v_rc;
  end if;

  if v_referrals>0 then
    v_inserted:=null;
    insert into public.tgg_creator_growth_milestones(owner_user_id,artist_id,milestone_key,milestone_title,milestone_value,metadata)
    values(v_uid,v_artist_id,'first_referral','First referral converted',v_referrals,jsonb_build_object('referrals',v_referrals))
    on conflict(owner_user_id,milestone_key) do nothing
    returning * into v_inserted;
    if v_inserted.id is not null then
      v_new:=v_new+1;
      insert into public.notifications(recipient_id,notification_type,entity_type,entity_id,title,body)
      values(v_uid,'growth_milestone','growth_milestone',v_inserted.id,'Growth milestone unlocked','Your first referral converted.');
    end if;
    update public.tgg_creator_action_queue set status='completed',updated_at=now()
    where owner_user_id=v_uid and source_type='growth' and action_type='get_first_referral' and status='open';
    get diagnostics v_rc=row_count; v_resolved:=v_resolved+v_rc;
  end if;

  if v_plays>0 then
    v_inserted:=null;
    insert into public.tgg_creator_growth_milestones(owner_user_id,artist_id,milestone_key,milestone_title,milestone_value,metadata)
    values(v_uid,v_artist_id,'first_play','First tracked play',v_plays,jsonb_build_object('plays',v_plays))
    on conflict(owner_user_id,milestone_key) do nothing
    returning * into v_inserted;
    if v_inserted.id is not null then
      v_new:=v_new+1;
      insert into public.notifications(recipient_id,notification_type,entity_type,entity_id,title,body)
      values(v_uid,'growth_milestone','growth_milestone',v_inserted.id,'Growth milestone unlocked','Your music got its first tracked play.');
    end if;
    update public.tgg_creator_action_queue set status='completed',updated_at=now()
    where owner_user_id=v_uid and source_type='growth' and action_type='drive_first_plays' and status='open';
    get diagnostics v_rc=row_count; v_resolved:=v_resolved+v_rc;
  end if;

  if v_saves>0 then
    v_inserted:=null;
    insert into public.tgg_creator_growth_milestones(owner_user_id,artist_id,milestone_key,milestone_title,milestone_value,metadata)
    values(v_uid,v_artist_id,'first_save','First release save',v_saves,jsonb_build_object('release_saves',v_saves))
    on conflict(owner_user_id,milestone_key) do nothing
    returning * into v_inserted;
    if v_inserted.id is not null then
      v_new:=v_new+1;
      insert into public.notifications(recipient_id,notification_type,entity_type,entity_id,title,body)
      values(v_uid,'growth_milestone','growth_milestone',v_inserted.id,'Growth milestone unlocked','A listener saved your release for the first time.');
    end if;
    update public.tgg_creator_action_queue set status='completed',updated_at=now()
    where owner_user_id=v_uid and source_type='growth' and action_type='earn_first_save' and status='open';
    get diagnostics v_rc=row_count; v_resolved:=v_resolved+v_rc;
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-MILESTONES-1.0',
    'new_milestones',v_new,
    'resolved_actions',v_resolved,
    'milestones',(
      select coalesce(jsonb_agg(jsonb_build_object(
        'milestone_key',milestone_key,'title',milestone_title,'value',milestone_value,'achieved_at',achieved_at
      ) order by achieved_at desc),'[]'::jsonb)
      from public.tgg_creator_growth_milestones where owner_user_id=v_uid
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000118] function private.tgg_growth_record_activity(p_action text, p_context jsonb)
CREATE OR REPLACE FUNCTION private.tgg_growth_record_activity(p_action text, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_action text:=lower(trim(coalesce(p_action,'')));
  v_context jsonb:=coalesce(p_context,'{}'::jsonb);
  v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_action not in ('growth_visit','share_artist','share_release','share_referral','claim_referral','share_achievement') then
    raise exception 'GROWTH_ACTION_INVALID' using errcode='22023';
  end if;
  if octet_length(v_context::text)>2048 then
    raise exception 'GROWTH_CONTEXT_TOO_LARGE' using errcode='22023';
  end if;

  select id into v_artist_id from public.artists where user_id=v_uid order by created_at limit 1;

  if v_action='growth_visit' and exists(
    select 1 from public.tgg_creator_growth_activity
    where owner_user_id=v_uid
      and action_type='growth_visit'
      and created_at>=date_trunc('day',now())
  ) then
    return jsonb_build_object('ok',true,'recorded',false,'reason','daily_visit_already_recorded');
  end if;

  if v_action like 'share_%' and (
    select count(*) from public.tgg_creator_growth_activity
    where owner_user_id=v_uid
      and action_type like 'share_%'
      and created_at>=date_trunc('day',now())
  )>=50 then
    raise exception 'DAILY_SHARE_ACTIVITY_LIMIT_REACHED' using errcode='22023';
  end if;

  insert into public.tgg_creator_growth_activity(owner_user_id,artist_id,action_type,context)
  values(v_uid,v_artist_id,v_action,v_context)
  returning id into v_id;

  return jsonb_build_object('ok',true,'recorded',true,'activity_id',v_id,'action_type',v_action);
end
$function$


-- [40000000119] function private.tgg_growth_shadow_ready_flags()
CREATE OR REPLACE FUNCTION private.tgg_growth_shadow_ready_flags()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_details jsonb;
  v_ready jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select details into v_details
  from public.tgg_operational_recovery_checkpoints
  where checkpoint_key='growth_v1_launch';

  select coalesce(jsonb_object_agg(key,value),'{}'::jsonb)
  into v_ready
  from jsonb_each(coalesce(v_details,'{}'::jsonb))
  where (key like 'growth_%_ready' or key like '%_ui_ready')
    and value='true'::jsonb;

  return v_ready;
end
$function$


-- [40000000120] function private.tgg_growth_weekly_refresh()
CREATE OR REPLACE FUNCTION private.tgg_growth_weekly_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_week date:=(date_trunc('week',now()))::date;
  v_visits integer:=0;
  v_shares integer:=0;
  v_engagement integer:=0;
  v_all_complete boolean:=false;
  v_streak public.tgg_creator_growth_streaks;
  v_prev_complete boolean:=false;
  v_prev_streak integer:=0;
  v_visit_target integer:=3;
  v_share_target integer:=3;
  v_engagement_target integer:=1;
  v_badge public.tgg_creator_growth_badges;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select id into v_artist_id from public.artists where user_id=v_uid order by created_at limit 1;

  if v_artist_id is null then
    return jsonb_build_object('ok',true,'version','GROWTH-WEEKLY-1.1','has_artist_profile',false,'missions','[]'::jsonb);
  end if;

  perform private.tgg_growth_record_activity('growth_visit','{}'::jsonb);

  select exists(
    select 1
    from public.tgg_creator_weekly_missions
    where owner_user_id=v_uid
      and week_start=v_week-7
    group by week_start
    having count(*)=3 and count(*) filter(where status='completed')=3
  ) into v_prev_complete;

  select coalesce(current_streak,0) into v_prev_streak
  from public.tgg_creator_growth_streaks
  where owner_user_id=v_uid;

  if v_prev_complete then
    v_visit_target:=least(5,3+greatest(v_prev_streak,1));
    v_share_target:=least(10,3+(greatest(v_prev_streak,1)*2));
    v_engagement_target:=least(5,1+greatest(v_prev_streak,1));
  end if;

  insert into public.tgg_creator_weekly_missions(owner_user_id,artist_id,week_start,mission_key,title,description,target_value)
  values
    (v_uid,v_artist_id,v_week,'visit_growth','Check Growth on '||v_visit_target||' days','Open the Growth workspace on different days this week.',v_visit_target),
    (v_uid,v_artist_id,v_week,'share_music','Share '||v_share_target||' times','Use your artist, release, or referral share buttons this week.',v_share_target),
    (v_uid,v_artist_id,v_week,'earn_engagement','Earn '||v_engagement_target||' fan signal'||case when v_engagement_target=1 then '' else 's' end,'Get real follower, save, referral, reaction, comment, or smart-link click activity this week.',v_engagement_target)
  on conflict(owner_user_id,week_start,mission_key) do nothing;

  select count(distinct created_at::date) into v_visits
  from public.tgg_creator_growth_activity
  where owner_user_id=v_uid and action_type='growth_visit' and created_at>=v_week::timestamptz;

  select count(*) into v_shares
  from public.tgg_creator_growth_activity
  where owner_user_id=v_uid and action_type in ('share_artist','share_release','share_referral','share_achievement') and created_at>=v_week::timestamptz;

  select
    (select count(*) from public.artist_follows af where af.artist_id=v_artist_id and af.created_at>=v_week::timestamptz)
    +(select count(*) from public.release_saves rs join public.mixtapes m on m.id=rs.mixtape_id where m.artist_id=v_artist_id and rs.created_at>=v_week::timestamptz)
    +(select count(*) from public.release_reactions rr join public.mixtapes m on m.id=rr.mixtape_id where m.artist_id=v_artist_id and rr.created_at>=v_week::timestamptz)
    +(select count(*) from public.release_comments rc join public.mixtapes m on m.id=rc.mixtape_id where m.artist_id=v_artist_id and rc.created_at>=v_week::timestamptz and coalesce(rc.hidden_by_creator,false)=false)
    +(select count(*) from public.tgg_referral_claims r where r.referrer_user_id=v_uid and r.claimed_at>=v_week::timestamptz)
    +(select count(*) from public.tgg_smart_link_events e join public.tgg_smart_links l on l.id=e.link_id where l.owner_user_id=v_uid and e.event_type='click' and e.occurred_at>=v_week::timestamptz)
  into v_engagement;

  update public.tgg_creator_weekly_missions
  set current_value=least(target_value,case mission_key
      when 'visit_growth' then v_visits
      when 'share_music' then v_shares
      when 'earn_engagement' then v_engagement
      else current_value end),
      status=case when case mission_key
        when 'visit_growth' then v_visits
        when 'share_music' then v_shares
        when 'earn_engagement' then v_engagement
        else current_value end >= target_value then 'completed' else 'active' end,
      completed_at=case when case mission_key
        when 'visit_growth' then v_visits
        when 'share_music' then v_shares
        when 'earn_engagement' then v_engagement
        else current_value end >= target_value then coalesce(completed_at,now()) else null end,
      updated_at=now()
  where owner_user_id=v_uid and week_start=v_week;

  select count(*)=3 into v_all_complete
  from public.tgg_creator_weekly_missions
  where owner_user_id=v_uid and week_start=v_week and status='completed';

  insert into public.tgg_creator_growth_streaks(owner_user_id,artist_id)
  values(v_uid,v_artist_id)
  on conflict(owner_user_id) do nothing;

  select * into v_streak from public.tgg_creator_growth_streaks where owner_user_id=v_uid for update;

  if v_all_complete and v_streak.last_completed_week is distinct from v_week then
    update public.tgg_creator_growth_streaks
    set current_streak=case when last_completed_week=v_week-7 then current_streak+1 else 1 end,
        best_streak=greatest(best_streak,case when last_completed_week=v_week-7 then current_streak+1 else 1 end),
        last_completed_week=v_week,
        artist_id=v_artist_id,
        updated_at=now()
    where owner_user_id=v_uid
    returning * into v_streak;

    insert into public.tgg_creator_growth_badges(
      owner_user_id,artist_id,badge_key,badge_title,badge_description,badge_level,metadata
    )
    values(
      v_uid,v_artist_id,'weekly_growth_complete',
      case
        when v_streak.current_streak>=8 then 'Growth Legend'
        when v_streak.current_streak>=4 then 'Growth Grinder'
        when v_streak.current_streak>=2 then 'Growth Streak'
        else 'Growth Starter'
      end,
      'Completed every Growth mission for the week.',
      greatest(v_streak.current_streak,1),
      jsonb_build_object('week_start',v_week,'streak',v_streak.current_streak)
    )
    on conflict(owner_user_id,badge_key,badge_level) do nothing
    returning * into v_badge;

    insert into public.notifications(recipient_id,notification_type,entity_type,entity_id,title,body)
    values(
      v_uid,'growth_week_complete','growth_week',v_badge.id,
      'Weekly Growth streak advanced',
      'You completed all three Growth missions this week.'
    );
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-WEEKLY-1.1',
    'week_start',v_week,
    'adaptive_targets',jsonb_build_object(
      'based_on_previous_completed_week',v_prev_complete,
      'visit_target',v_visit_target,
      'share_target',v_share_target,
      'engagement_target',v_engagement_target
    ),
    'missions',(select coalesce(jsonb_agg(jsonb_build_object(
      'mission_key',mission_key,'title',title,'description',description,
      'current_value',current_value,'target_value',target_value,'status',status,'completed_at',completed_at
    ) order by created_at),'[]'::jsonb)
      from public.tgg_creator_weekly_missions where owner_user_id=v_uid and week_start=v_week),
    'streak',to_jsonb(v_streak),
    'badges',(select coalesce(jsonb_agg(jsonb_build_object(
      'badge_key',badge_key,'title',badge_title,'description',badge_description,
      'level',badge_level,'earned_at',earned_at
    ) order by earned_at desc),'[]'::jsonb)
      from public.tgg_creator_growth_badges where owner_user_id=v_uid),
    'generated_at',now()
  );
end
$function$


-- [40000000121] function private.tgg_growth_weekly_report_impl()
CREATE OR REPLACE FUNCTION private.tgg_growth_weekly_report_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_week date:=date_trunc('week',now())::date;
  v_prev_week date:=(date_trunc('week',now())-interval '7 days')::date;

  cf bigint:=0; pf bigint:=0;
  cs bigint:=0; ps bigint:=0;
  cr bigint:=0; pr bigint:=0;
  cc bigint:=0; pc bigint:=0;
  cref bigint:=0; pref bigint:=0;
  cclk bigint:=0; pclk bigint:=0;
  cshare bigint:=0; pshare bigint:=0;
  cscore bigint:=0; pscore bigint:=0;

  v_top_release jsonb;
  v_missions jsonb;
  v_completed integer:=0;
  v_total integer:=0;
  v_streak jsonb;
  v_next jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object(
      'ok',true,
      'version','GROWTH-WEEKLY-REPORT-1.0',
      'has_artist_profile',false,
      'generated_at',now()
    );
  end if;

  select
    count(*) filter(where created_at>=v_week::timestamptz),
    count(*) filter(where created_at>=v_prev_week::timestamptz and created_at<v_week::timestamptz)
  into cf,pf
  from public.artist_follows
  where artist_id=v_artist_id;

  select
    count(*) filter(where rs.created_at>=v_week::timestamptz),
    count(*) filter(where rs.created_at>=v_prev_week::timestamptz and rs.created_at<v_week::timestamptz)
  into cs,ps
  from public.release_saves rs
  join public.mixtapes m on m.id=rs.mixtape_id
  where m.artist_id=v_artist_id and m.status='published';

  select
    count(*) filter(where rr.created_at>=v_week::timestamptz),
    count(*) filter(where rr.created_at>=v_prev_week::timestamptz and rr.created_at<v_week::timestamptz)
  into cr,pr
  from public.release_reactions rr
  join public.mixtapes m on m.id=rr.mixtape_id
  where m.artist_id=v_artist_id and m.status='published';

  select
    count(*) filter(where rc.created_at>=v_week::timestamptz),
    count(*) filter(where rc.created_at>=v_prev_week::timestamptz and rc.created_at<v_week::timestamptz)
  into cc,pc
  from public.release_comments rc
  join public.mixtapes m on m.id=rc.mixtape_id
  where m.artist_id=v_artist_id
    and m.status='published'
    and coalesce(rc.hidden_by_creator,false)=false;

  select
    count(*) filter(where claimed_at>=v_week::timestamptz),
    count(*) filter(where claimed_at>=v_prev_week::timestamptz and claimed_at<v_week::timestamptz)
  into cref,pref
  from public.tgg_referral_claims
  where referrer_user_id=v_uid;

  select
    count(*) filter(where e.occurred_at>=v_week::timestamptz),
    count(*) filter(where e.occurred_at>=v_prev_week::timestamptz and e.occurred_at<v_week::timestamptz)
  into cclk,pclk
  from public.tgg_smart_link_events e
  join public.tgg_smart_links l on l.id=e.link_id
  where l.owner_user_id=v_uid and e.event_type='click';

  select
    count(*) filter(where created_at>=v_week::timestamptz),
    count(*) filter(where created_at>=v_prev_week::timestamptz and created_at<v_week::timestamptz)
  into cshare,pshare
  from public.tgg_creator_growth_activity
  where owner_user_id=v_uid
    and action_type in ('share_artist','share_release','share_referral');

  cscore:=cf*8+cs*5+cr*3+cc*6+cref*10+cclk+cshare;
  pscore:=pf*8+ps*5+pr*3+pc*6+pref*10+pclk+pshare;

  select jsonb_build_object(
    'release_id',m.id,
    'title',m.title,
    'slug',m.slug,
    'play_count',coalesce(m.play_count,0),
    'download_count',coalesce(m.download_count,0),
    'url',case when nullif(btrim(coalesce(m.slug,'')),'') is null then null
      else 'https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-shell?view=release&slug='||m.slug end
  )
  into v_top_release
  from public.mixtapes m
  where m.artist_id=v_artist_id and m.status='published'
  order by (coalesce(m.play_count,0)+(coalesce(m.download_count,0)*3)) desc,
           coalesce(m.featured,false) desc,
           m.created_at desc
  limit 1;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'mission_key',mission_key,
      'title',title,
      'current_value',current_value,
      'target_value',target_value,
      'status',status
    ) order by created_at),'[]'::jsonb),
    count(*),
    count(*) filter(where status='completed')
  into v_missions,v_total,v_completed
  from public.tgg_creator_weekly_missions
  where owner_user_id=v_uid and week_start=v_week;

  select to_jsonb(s) into v_streak
  from public.tgg_creator_growth_streaks s
  where s.owner_user_id=v_uid;

  select coalesce(jsonb_agg(jsonb_build_object(
    'title',title,'rationale',rationale,'priority',priority,'action_type',action_type
  ) order by priority desc,created_at asc),'[]'::jsonb)
  into v_next
  from (
    select * from public.tgg_creator_action_queue
    where owner_user_id=v_uid and source_type='growth' and status='open'
    order by priority desc,created_at asc
    limit 3
  ) q;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-WEEKLY-REPORT-1.0',
    'week_start',v_week,
    'previous_week_start',v_prev_week,
    'current_week',jsonb_build_object(
      'followers',cf,'saves',cs,'reactions',cr,'comments',cc,
      'referrals',cref,'smart_link_clicks',cclk,'shares',cshare,'score',cscore
    ),
    'previous_week',jsonb_build_object(
      'followers',pf,'saves',ps,'reactions',pr,'comments',pc,
      'referrals',pref,'smart_link_clicks',pclk,'shares',pshare,'score',pscore
    ),
    'week_over_week',jsonb_build_object(
      'score_change',cscore-pscore,
      'trend',case
        when cscore>pscore then 'up'
        when cscore<pscore then 'down'
        else 'flat'
      end
    ),
    'top_release',v_top_release,
    'missions',jsonb_build_object(
      'completed',v_completed,'total',v_total,'items',v_missions
    ),
    'streak',coalesce(v_streak,'{}'::jsonb),
    'next_priorities',v_next,
    'generated_at',now()
  );
end
$function$


-- [40000000122] function private.tgg_guard_artist_financial_fields()
CREATE OR REPLACE FUNCTION private.tgg_guard_artist_financial_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is not null
     and not coalesce(private.is_admin(),false)
     and (
       new.stripe_account_id is distinct from old.stripe_account_id
       or new.stripe_onboarding_complete is distinct from old.stripe_onboarding_complete
       or new.payouts_enabled is distinct from old.payouts_enabled
       or new.membership_payout_mode is distinct from old.membership_payout_mode
     )
  then
    raise exception 'ARTIST_FINANCIAL_FIELDS_SERVER_MANAGED' using errcode='42501';
  end if;

  return new;
end
$function$


-- [40000000123] function private.tgg_guard_collaboration_update()
CREATE OR REPLACE FUNCTION private.tgg_guard_collaboration_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  -- Trusted server-side operations may proceed.
  if v_uid is null then
    return new;
  end if;

  -- Identity and request content are immutable after creation.
  if new.sender_id is distinct from old.sender_id
     or new.recipient_id is distinct from old.recipient_id
     or new.project_title is distinct from old.project_title
     or new.project_type is distinct from old.project_type
     or new.note is distinct from old.note
     or new.created_at is distinct from old.created_at then
    raise exception 'collaboration_request_fields_immutable';
  end if;

  -- Only pending requests may transition.
  if old.status <> 'pending' then
    if new.status is distinct from old.status
       or new.conversation_id is distinct from old.conversation_id then
      raise exception 'collaboration_request_already_resolved';
    end if;
    return new;
  end if;

  if v_uid = old.sender_id then
    if new.status <> 'cancelled' then
      raise exception 'sender_may_only_cancel_request';
    end if;
    if new.conversation_id is distinct from old.conversation_id then
      raise exception 'sender_cannot_link_conversation';
    end if;

  elsif v_uid = old.recipient_id then
    if new.status not in ('accepted','declined') then
      raise exception 'recipient_may_only_accept_or_decline';
    end if;

    if new.status = 'declined'
       and new.conversation_id is distinct from old.conversation_id then
      raise exception 'declined_request_cannot_link_conversation';
    end if;

    if new.status = 'accepted' and new.conversation_id is not null then
      if not (
        exists (
          select 1 from public.tgg_conversation_members m
          where m.conversation_id = new.conversation_id
            and m.user_id = old.sender_id
        )
        and exists (
          select 1 from public.tgg_conversation_members m
          where m.conversation_id = new.conversation_id
            and m.user_id = old.recipient_id
        )
      ) then
        raise exception 'conversation_must_include_both_collaborators';
      end if;
    end if;

  else
    raise exception 'not_collaboration_participant';
  end if;

  new.updated_at := now();
  return new;
end;
$function$


-- [40000000124] function private.tgg_guard_content_item_status()
CREATE OR REPLACE FUNCTION private.tgg_guard_content_item_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_jwt_role text:=coalesce((nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role'),'');
  v_admin boolean:=false;
begin
  if auth.uid() is not null then
    v_admin:=private.is_admin();
  end if;

  if tg_op='INSERT' then
    if new.status in ('APPROVED','PUBLISHED')
       and not (v_admin or v_jwt_role='service_role' or v_jwt_role='') then
      raise exception 'CONTENT_STATUS_REQUIRES_REVIEW' using errcode='42501';
    end if;
  elsif new.status is distinct from old.status then
    if new.status in ('APPROVED','PUBLISHED')
       and not (v_admin or v_jwt_role='service_role' or v_jwt_role='') then
      raise exception 'CONTENT_STATUS_REQUIRES_REVIEW' using errcode='42501';
    end if;
  end if;

  if new.status='PUBLISHED' and new.published_at is null then
    new.published_at:=now();
  end if;

  return new;
end
$function$


-- [40000000125] function private.tgg_guard_membership_activation()
CREATE OR REPLACE FUNCTION private.tgg_guard_membership_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_webhook_ready boolean:=false;
begin
  if coalesce(new.is_active,false)
     and (tg_op='INSERT' or not coalesce(old.is_active,false))
  then
    if not coalesce(new.stripe_payment_link_verified,false) then
      raise exception 'MEMBERSHIP_PAYMENT_LINK_NOT_VERIFIED' using errcode='23514';
    end if;

    if nullif(btrim(coalesce(new.stripe_product_id,'')),'') is null
       or nullif(btrim(coalesce(new.stripe_price_id,'')),'') is null
       or nullif(btrim(coalesce(new.stripe_payment_link_url,'')),'') is null
    then
      raise exception 'MEMBERSHIP_STRIPE_OBJECTS_INCOMPLETE' using errcode='23514';
    end if;

    select coalesce(c.enabled,false)
           and c.mode='production'
           and coalesce(c.endpoint_configured,false)
    into v_webhook_ready
    from public.tgg_provider_runtime_config c
    where c.provider_key='stripe.webhook';

    if not coalesce(v_webhook_ready,false) then
      raise exception 'STRIPE_WEBHOOK_RUNTIME_NOT_READY' using errcode='23514';
    end if;
  end if;

  return new;
end
$function$


-- [40000000126] function private.tgg_guard_message_update()
CREATE OR REPLACE FUNCTION private.tgg_guard_message_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.id is distinct from old.id
     or new.conversation_id is distinct from old.conversation_id
     or new.sender_id is distinct from old.sender_id
     or new.created_at is distinct from old.created_at
  then
    raise exception 'MESSAGE_IDENTITY_FIELDS_IMMUTABLE';
  end if;

  return new;
end
$function$


-- [40000000127] function private.tgg_guard_review_managed_fields()
CREATE OR REPLACE FUNCTION private.tgg_guard_review_managed_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_admin boolean:=private.is_admin();
  v_old_status text:=coalesce(to_jsonb(old)->>'status','');
  v_new_status text:=coalesce(to_jsonb(new)->>'status','');
  v_old_admin_note text:=to_jsonb(old)->>'admin_note';
  v_new_admin_note text:=to_jsonb(new)->>'admin_note';
  v_old_published_at text:=to_jsonb(old)->>'published_at';
  v_new_published_at text:=to_jsonb(new)->>'published_at';
begin
  if v_admin then
    return new;
  end if;

  if to_jsonb(new) ? 'admin_note'
     and v_new_admin_note is distinct from v_old_admin_note
  then
    if not (
      v_old_status in ('changes_requested','rejected')
      and v_new_status='pending'
      and v_new_admin_note is null
    ) then
      raise exception 'REVIEW_ADMIN_NOTE_MANAGED_BY_ADMIN';
    end if;
  end if;

  if to_jsonb(new) ? 'published_at'
     and v_new_published_at is distinct from v_old_published_at
  then
    raise exception 'PUBLISHED_AT_MANAGED_BY_ADMIN';
  end if;

  return new;
end
$function$


-- [40000000128] function private.tgg_insert_track(p_artist_id uuid, p_audio_url text, p_mixtape_id uuid, p_title text, p_track_number integer, p_youtube_url text, p_youtube_video_id text)
CREATE OR REPLACE FUNCTION private.tgg_insert_track(p_artist_id uuid, p_audio_url text, p_mixtape_id uuid, p_title text, p_track_number integer, p_youtube_url text DEFAULT NULL::text, p_youtube_video_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  new_track_id uuid;
  v_status public.mixtape_status;
begin
  if not exists (
    select 1
    from public.artists a
    where a.id=p_artist_id
      and a.user_id=auth.uid()
  ) then
    raise exception 'Artist does not belong to the logged-in user';
  end if;

  select m.status into v_status
  from public.mixtapes m
  where m.id=p_mixtape_id
    and m.artist_id=p_artist_id;

  if v_status is null then
    raise exception 'Mixtape does not belong to this artist';
  end if;

  if v_status not in (
    'draft'::public.mixtape_status,
    'changes_requested'::public.mixtape_status,
    'rejected'::public.mixtape_status
  ) then
    raise exception 'RELEASE_NOT_EDITABLE';
  end if;

  if coalesce(btrim(p_title),'')='' then raise exception 'TRACK_TITLE_REQUIRED'; end if;
  if p_track_number is null or p_track_number<1 then raise exception 'TRACK_NUMBER_INVALID'; end if;

  insert into public.tracks(
    artist_id,mixtape_id,track_number,title,audio_url
  )
  values(
    p_artist_id,p_mixtape_id,p_track_number,btrim(p_title),nullif(btrim(p_audio_url),'')
  )
  returning id into new_track_id;

  return new_track_id;
end
$function$


