-- [40000000134] function private.tgg_join_dynamic_event(p_character_id uuid, p_dynamic_event_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_join_dynamic_event(p_character_id uuid, p_dynamic_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_event public.tgg_world_dynamic_events%rowtype;
  v_template public.tgg_world_dynamic_event_templates%rowtype;
  v_career text;
  v_location text;
  v_min_seconds integer:=60;
  v_existing_joined_at timestamptz;
  v_ready_at timestamptz;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select active_career into v_career
  from public.world_characters
  where id=p_character_id and user_id=v_uid and character_status='active';

  if v_career is null then raise exception 'character ownership mismatch'; end if;

  select e.* into v_event
  from public.tgg_world_dynamic_events e
  where e.id=p_dynamic_event_id
    and e.status='active'
    and e.starts_at<=now()
    and e.ends_at>now();

  if v_event.id is null then raise exception 'event unavailable'; end if;

  select t.* into v_template
  from public.tgg_world_dynamic_event_templates t
  where t.event_key=v_event.event_key and t.enabled=true;

  if v_template.event_key is null then raise exception 'event template unavailable'; end if;

  if cardinality(v_template.participant_roles)>0
     and not (v_career=any(v_template.participant_roles)) then
    raise exception 'career not eligible for event';
  end if;

  select l.location_key into v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=p_character_id;

  if v_location is distinct from v_event.location_key then
    raise exception 'travel to % before joining',v_event.location_key;
  end if;

  v_min_seconds:=coalesce(
    nullif((v_template.metadata->>'min_participation_seconds')::integer,0),
    least(120,greatest(30,v_template.duration_minutes*3))
  );

  select joined_at into v_existing_joined_at
  from public.tgg_world_character_event_state
  where character_id=p_character_id and dynamic_event_id=v_event.id;

  v_ready_at:=coalesce(v_existing_joined_at,now())+make_interval(secs=>v_min_seconds);

  insert into public.tgg_world_character_event_state(
    character_id,dynamic_event_id,status,role_key,progress,outcome,
    discovered_at,joined_at,updated_at
  )
  values(
    p_character_id,v_event.id,'joined',v_career,
    jsonb_build_object(
      'joined_location',v_location,
      'min_participation_seconds',v_min_seconds,
      'ready_at',v_ready_at
    ),
    '{}'::jsonb,
    now(),now(),now()
  )
  on conflict(character_id,dynamic_event_id) do update
  set status=case
      when public.tgg_world_character_event_state.status='completed' then 'completed'
      else 'joined'
    end,
    role_key=v_career,
    joined_at=coalesce(public.tgg_world_character_event_state.joined_at,now()),
    progress=public.tgg_world_character_event_state.progress||jsonb_build_object(
      'joined_location',v_location,
      'min_participation_seconds',v_min_seconds,
      'ready_at',
        coalesce(public.tgg_world_character_event_state.joined_at,now())
        +make_interval(secs=>v_min_seconds)
    ),
    updated_at=now();

  select coalesce(joined_at,now())+make_interval(secs=>v_min_seconds)
  into v_ready_at
  from public.tgg_world_character_event_state
  where character_id=p_character_id and dynamic_event_id=v_event.id;

  return jsonb_build_object(
    'event_id',v_event.id,
    'event_key',v_event.event_key,
    'title',v_template.title,
    'joined',true,
    'min_participation_seconds',v_min_seconds,
    'ready_at',v_ready_at
  );
end;
$function$


-- [40000000135] function private.tgg_latest_operational_dependency_state()
CREATE OR REPLACE FUNCTION private.tgg_latest_operational_dependency_state()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce((
    select jsonb_build_object(
      'state',state,
      'failed_count',failed_count,
      'checked_at',checked_at
    )
    from public.tgg_operational_dependency_checks
    where check_key='active-runtime-dependencies'
    order by checked_at desc
    limit 1
  ),jsonb_build_object(
    'state','unknown',
    'failed_count',0,
    'checked_at',null
  ))
$function$


-- [40000000136] function private.tgg_launch_closeout_ops_snapshot()
CREATE OR REPLACE FUNCTION private.tgg_launch_closeout_ops_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_migration jsonb;
  v_schema_alert_open boolean:=false;
  v_latest_migration_version text;
  v_latest_migration_name text;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select version,name
  into v_latest_migration_version,v_latest_migration_name
  from supabase_migrations.schema_migrations
  order by version desc
  limit 1;

  select jsonb_build_object(
    'migration_history_caught_up',coalesce((details->>'migration_history_caught_up')::boolean,false),
    'migration_sync_required',coalesce((details->>'migration_sync_required')::boolean,false),
    'core_launch_blocking',coalesce((details->>'core_launch_blocking')::boolean,false),
    'schema_attestation_version',details->>'schema_attestation_version',
    'schema_attestation_object_count',coalesce((details->>'schema_attestation_object_count')::int,0),
    'live_only_database_change_count',coalesce(jsonb_array_length(coalesce(details->'live_only_database_changes','[]'::jsonb)),0),
    'edge_runtime_change_count',coalesce(jsonb_array_length(coalesce(details->'edge_runtime_changes','[]'::jsonb)),0),
    'last_recorded_migration_version',v_latest_migration_version,
    'last_recorded_migration_name',v_latest_migration_name,
    'counts_derived_from_inventory',true,
    'latest_migration_derived_live',true
  )
  into v_migration
  from public.tgg_operational_recovery_checkpoints
  where checkpoint_key='migration_hygiene_live'
  limit 1;

  select exists(
    select 1
    from public.tgg_operational_alerts
    where alert_key='production:post_migration_schema_attestation'
      and status<>'resolved'
  )
  into v_schema_alert_open;

  return jsonb_build_object(
    'dependency_state', coalesce((private.tgg_latest_operational_dependency_state()->>'state'),'unknown'),
    'dependency_failures', coalesce((private.tgg_latest_operational_dependency_state()->>'failed_count')::int,0),
    'advisory_alerts', (select count(*) from public.tgg_operational_alerts where status <> 'resolved'),
    'blocking_alerts', (select count(*) from public.tgg_operational_alerts where status <> 'resolved' and severity='critical'),
    'open_incidents', (select count(*) from public.tgg_operational_incidents where status <> 'resolved'),
    'migration_hygiene',coalesce(v_migration,'{}'::jsonb) || jsonb_build_object(
      'schema_attestation_healthy',not v_schema_alert_open
    )
  );
end;
$function$


-- [40000000137] function private.tgg_launch_readiness_internal()
CREATE OR REPLACE FUNCTION private.tgg_launch_readiness_internal()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with
stripe_native as (
  select coalesce(enabled,false) enabled,coalesce(mode,'disabled') mode,
         coalesce(endpoint_configured,false) endpoint_configured,disabled_reason
  from public.tgg_provider_runtime_config where provider_key='stripe'
),
stripe_webhook as (
  select coalesce(enabled,false) enabled,coalesce(endpoint_configured,false) endpoint_configured,disabled_reason
  from public.tgg_provider_runtime_config where provider_key='stripe.webhook'
),
stripe_link as (
  select coalesce(enabled,false) enabled,coalesce(endpoint_configured,false) endpoint_configured
  from public.tgg_provider_runtime_config where provider_key='stripe.payment_link'
),
membership_native as (
  select coalesce(enabled,false) enabled,coalesce(mode,'disabled') mode,
         coalesce(endpoint_configured,false) endpoint_configured,disabled_reason
  from public.tgg_provider_runtime_config where provider_key='membership.stripe'
),
membership_link as (
  select coalesce(enabled,false) enabled,coalesce(endpoint_configured,false) endpoint_configured
  from public.tgg_provider_runtime_config where provider_key='membership.payment_link'
),
dsp as (
  select coalesce(bool_or(coalesce(enabled,false) and coalesce(endpoint_configured,false)),false) connected
  from public.tgg_provider_runtime_config
  where provider_key='distribution.provider'
),
broadcast_provider as (
  select coalesce(enabled,false) enabled,coalesce(endpoint_configured,false) endpoint_configured
  from public.tgg_provider_runtime_config where provider_key='broadcast.sfu_turn'
),
catalog as (
  select
    (select count(*) from public.merch_products where status='published') merch_products,
    (select count(*) from public.tgg_membership_tiers where is_active=true) membership_tiers
),
feature as (select public.tgg_feature_runtime_health() j),
drift as (select private.tgg_runtime_drift_guard_internal() j),
broadcast_health as (select public.tgg_broadcast_engine_health() j),
call_health as (select public.tgg_call_validation_final_health() j),
external as (select public.tgg_external_completion_state() j),
calc as (
  select
    coalesce(((select j->>'ok' from drift))::boolean,false) drift_ok,
    not exists(
      select 1 from jsonb_each((select j->'modules' from feature))
      where coalesce((value->>'ready')::boolean,false)=false
    ) features_ok,
    coalesce((select enabled and endpoint_configured from stripe_webhook),false) webhook_ok,
    coalesce((select enabled and endpoint_configured from stripe_link),false) payment_link_ok,
    coalesce((select enabled and endpoint_configured from membership_link),false) membership_link_ok,
    (select merch_products from catalog) merch_products,
    (select membership_tiers from catalog) membership_tiers,
    (
      to_regprocedure('public.tgg_creator_distribution_package(uuid)') is not null
      and to_regprocedure('public.tgg_creator_distribution_readiness(uuid)') is not null
    ) distribution_package_ok,
    (
      coalesce(((select j->>'control_plane_ready' from broadcast_health))::boolean,false)
      and coalesce(((select j->>'room_authorization_ready' from broadcast_health))::boolean,false)
      and coalesce(((select j->>'public_viewer_tokens_ready' from broadcast_health))::boolean,false)
      and coalesce(((select j->>'host_guest_collab_tokens_ready' from broadcast_health))::boolean,false)
    ) live_core_ok,
    (
      to_regprocedure('public.tgg_start_call_room(uuid,text)') is not null
      and to_regprocedure('public.tgg_call_signal_send(uuid,text,jsonb,uuid)') is not null
    ) calls_core_ok,
    coalesce(((select j->>'fully_connected' from external))::boolean,false) fully_connected
),
final as (
  select *,
    (
      payment_link_ok
      and (
        webhook_ok
        or (merch_products=0 and membership_tiers=0)
      )
    ) commerce_core_ok,
    (
      drift_ok
      and features_ok
      and payment_link_ok
      and (
        webhook_ok
        or (merch_products=0 and membership_tiers=0)
      )
      and distribution_package_ok
      and live_core_ok
      and calls_core_ok
    ) core_launch_ready
  from calc
)
select jsonb_build_object(
  'ok',true,
  'version','LAUNCH-READINESS-ONE-FINAL-1.4',
  'platform_complete',core_launch_ready,
  'core_launch_ready',core_launch_ready,
  'fully_connected',fully_connected,
  'platform_state',case
    when not core_launch_ready then 'ATTENTION'
    when fully_connected then 'FULLY_CONNECTED'
    else 'READY_WITH_FALLBACKS'
  end,
  'internal',jsonb_build_object(
    'creator_os',true,
    'master_admin',true,
    'public_shell',true,
    'feature_modules_ready',(
      select count(*) from jsonb_each((select j->'modules' from feature))
      where coalesce((value->>'ready')::boolean,false)
    ),
    'feature_modules_total',(select count(*) from jsonb_each((select j->'modules' from feature))),
    'drift_guard',drift_ok,
    'edge_function_capacity',jsonb_build_object(
      'used',100,'limit',100,'at_capacity',true,'new_slots_required_for_core',false
    )
  ),
  'payments',jsonb_build_object(
    'ready',commerce_core_ok,
    'webhook_endpoint_live',coalesce((select endpoint_configured from stripe_webhook),false),
    'webhook_endpoint_configured',coalesce((select endpoint_configured from stripe_webhook),false),
    'webhook_runtime_ready',webhook_ok,
    'webhook_signature_verification_ready',webhook_ok,
    'payment_link_checkout_ready',payment_link_ok,
    'native_checkout_ready',
      coalesce((select enabled and endpoint_configured and mode='production' from stripe_native),false),
    'native_checkout_optional',true,
    'native_checkout_blocker',(select disabled_reason from stripe_native),
    'webhook_blocker',case when webhook_ok then null else (select disabled_reason from stripe_webhook) end,
    'published_merch_products',merch_products,
    'catalog_requires_webhook',merch_products>0 or membership_tiers>0,
    'safe_mode',case
      when coalesce((select enabled and endpoint_configured and mode='production' from stripe_native),false)
        then 'native_stripe'
      else 'payment_link_fallback'
    end
  ),
  'memberships',jsonb_build_object(
    'infrastructure_ready',
      membership_link_ok and (webhook_ok or membership_tiers=0),
    'payment_link_checkout_ready',membership_link_ok,
    'owner_platform_settlement_supported',true,
    'connect_required_for_non_owner_creators',true,
    'native_checkout_ready',
      coalesce((select enabled and endpoint_configured and mode='production' from membership_native),false),
    'native_checkout_optional',true,
    'active_tiers',membership_tiers,
    'safe_mode','payment_link_fallback'
  ),
  'distribution',jsonb_build_object(
    'package_builder_ready',distribution_package_ok,
    'provider_connected',(select connected from dsp),
    'provider_optional_for_core',true,
    'safe_mode',case when (select connected from dsp) then 'automated_provider_delivery' else 'package_export' end
  ),
  'live',jsonb_build_object(
    'control_plane_ready',coalesce(((select j->>'control_plane_ready' from broadcast_health))::boolean,false),
    'room_authorization_ready',coalesce(((select j->>'room_authorization_ready' from broadcast_health))::boolean,false),
    'viewer_tokens_ready',coalesce(((select j->>'public_viewer_tokens_ready' from broadcast_health))::boolean,false),
    'guest_tokens_ready',coalesce(((select j->>'host_guest_collab_tokens_ready' from broadcast_health))::boolean,false),
    'sfu_turn_connected',coalesce((select enabled and endpoint_configured from broadcast_provider),false),
    'sfu_turn_optional_for_core',true,
    'safe_mode',case
      when coalesce((select enabled and endpoint_configured from broadcast_provider),false)
        then 'scalable_broadcast'
      else 'control_plane_ready_provider_transport_pending'
    end
  ),
  'calls',jsonb_build_object(
    'core_room_api_ready',to_regprocedure('public.tgg_start_call_room(uuid,text)') is not null,
    'signaling_api_ready',to_regprocedure('public.tgg_call_signal_send(uuid,text,jsonb,uuid)') is not null,
    'two_user_validated',coalesce(((select j->>'validated' from call_health))::boolean,false),
    'two_user_validation_optional_for_core',true,
    'safe_mode',case
      when coalesce(((select j->>'validated' from call_health))::boolean,false) then 'validated'
      else 'core_signaling_ready_validation_pending'
    end
  ),
  'external_actions',jsonb_build_array(
    jsonb_build_object(
      'key','stripe_native_secrets','category','payments',
      'required_for_core',false,
      'required_for_full_connect',
        not coalesce((select enabled and endpoint_configured and mode='production' from stripe_native),false),
      'fallback_available',payment_link_ok,
      'reason',coalesce((select disabled_reason from stripe_native),'ready')
    ),
    jsonb_build_object(
      'key','stripe_webhook_secret','category','payments',
      'required_for_core',merch_products>0 or membership_tiers>0,
      'required_for_full_connect',not webhook_ok,
      'fallback_available',merch_products=0 and membership_tiers=0,
      'reason',case when webhook_ok then 'ready' else coalesce((select disabled_reason from stripe_webhook),'stripe_webhook_secret_missing') end
    ),
    jsonb_build_object(
      'key','dsp_distribution_provider','category','distribution',
      'required_for_core',false,'required_for_full_connect',not (select connected from dsp),
      'fallback_available',true,'fallback','distribution_package_export'
    ),
    jsonb_build_object(
      'key','broadcast_sfu_turn','category','live',
      'required_for_core',false,
      'required_for_full_connect',not coalesce((select enabled and endpoint_configured from broadcast_provider),false),
      'fallback_available',true,'fallback','control_plane_and_token_layer'
    ),
    jsonb_build_object(
      'key','two_user_call_validation','category','calls',
      'required_for_core',false,
      'required_for_full_connect',not coalesce(((select j->>'validated' from call_health))::boolean,false),
      'fallback_available',true,'fallback','core_call_room_and_signaling'
    ),
    jsonb_build_object(
      'key','leaked_password_protection','category','auth',
      'required_for_core',false,'required_for_full_connect',true,
      'fallback_available',false,'reason','supabase_account_setting_required'
    )
  ),
  'generated_at',now()
)
from final;
$function$


-- [40000000138] function private.tgg_legacy_public_route_retirement_check()
CREATE OR REPLACE FUNCTION private.tgg_legacy_public_route_retirement_check()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with bad as (
  select route_key,path,is_active,is_primary
  from public.tgg_site_routes
  where route_key in ('public_mixtape_detail_legacy','admin_dashboard','artist_dashboard','creator_dashboard','artist_command_center')
    and is_active=true
)
select jsonb_build_object(
  'ok',not exists(select 1 from bad),
  'version','LEGACY-PUBLIC-ROUTE-RETIREMENT-1.0',
  'active_legacy_count',(select count(*) from bad),
  'active_legacy_routes',coalesce((select jsonb_agg(to_jsonb(b) order by route_key) from bad b),'[]'::jsonb),
  'canonical_release_route',(select path from public.tgg_site_routes where route_key='public_mixtape_detail' and is_active=true limit 1),
  'checked_at',now()
);
$function$


-- [40000000139] function private.tgg_live_clip_career_mission_trigger()
CREATE OR REPLACE FUNCTION private.tgg_live_clip_career_mission_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_char uuid;
begin
  select id into v_char
  from public.world_characters
  where user_id=new.creator_id and character_status='active'
  limit 1;

  if v_char is not null then
    perform private.tgg_world_credit_career_mission_event(
      v_char,
      'live_clip_created',
      'live_clip',
      new.id::text,
      jsonb_build_object('stream_id',new.stream_id,'clip_kind',new.clip_kind)
    );
    perform private.tgg_world_credit_contract_event(
      v_char,
      'live_clip_created',
      'live_clip',
      new.id::text,
      jsonb_build_object('stream_id',new.stream_id,'clip_kind',new.clip_kind)
    );
  end if;
  return new;
end;
$function$


-- [40000000140] function private.tgg_live_end(p_stream_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_live_end(p_stream_id uuid)
 RETURNS public.live_streams
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.live_streams;
begin
  update public.live_streams
  set status='ENDED',
      actual_end=coalesce(actual_end,now()),
      updated_at=now()
  where id=p_stream_id
    and creator_id=auth.uid()
    and status='LIVE'
  returning * into v;

  if not found then raise exception 'stream_not_live_or_not_owned'; end if;
  return v;
end
$function$


-- [40000000141] function private.tgg_live_join(p_stream_id uuid, p_session_id text)
CREATE OR REPLACE FUNCTION private.tgg_live_join(p_stream_id uuid, p_session_id text)
 RETURNS public.live_stream_viewers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.live_stream_viewers;
  v_stream public.live_streams;
begin
  if auth.uid() is null then raise exception 'authentication_required'; end if;
  if coalesce(trim(p_session_id),'')='' then raise exception 'session_id_required'; end if;

  select * into v_stream
  from public.live_streams
  where id=p_stream_id
    and status='LIVE'
  for update;

  if not found then raise exception 'stream_not_live_or_not_found'; end if;

  if exists(
    select 1
    from public.live_stream_viewers
    where stream_id=p_stream_id
      and session_id=trim(p_session_id)
      and viewer_id=auth.uid()
      and left_at is null
  ) then
    select * into v
    from public.live_stream_viewers
    where stream_id=p_stream_id
      and session_id=trim(p_session_id)
      and viewer_id=auth.uid()
      and left_at is null
    limit 1;
    return v;
  end if;

  insert into public.live_stream_viewers(
    stream_id,viewer_id,session_id,joined_at,left_at,watch_seconds
  )
  values(
    p_stream_id,auth.uid(),trim(p_session_id),now(),null,0
  )
  returning * into v;

  update public.live_streams
  set viewer_count=coalesce(viewer_count,0)+1,
      peak_viewers=greatest(coalesce(peak_viewers,0),coalesce(viewer_count,0)+1),
      total_views=coalesce(total_views,0)+1,
      updated_at=now()
  where id=p_stream_id;

  return v;
end
$function$


-- [40000000142] function private.tgg_live_leave(p_session_id text)
CREATE OR REPLACE FUNCTION private.tgg_live_leave(p_session_id text)
 RETURNS public.live_stream_viewers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v public.live_stream_viewers; v_left timestamptz;
begin
 if auth.uid() is null then raise exception 'authentication_required'; end if;
 if coalesce(trim(p_session_id),'')='' then raise exception 'session_id_required'; end if;
 select * into v from public.live_stream_viewers where session_id=trim(p_session_id) and viewer_id=auth.uid() and left_at is null order by joined_at desc limit 1 for update;
 if not found then raise exception 'viewer_session_not_found'; end if;
 v_left:=now();
 update public.live_stream_viewers set left_at=v_left, watch_seconds=greatest(coalesce(watch_seconds,0),extract(epoch from (v_left-joined_at))::integer) where id=v.id returning * into v;
 update public.live_streams set viewer_count=greatest(coalesce(viewer_count,0)-1,0),updated_at=now() where id=v.stream_id;
 return v;
end $function$


-- [40000000143] function private.tgg_live_schedule(p_content_id uuid, p_title text, p_description text, p_category text, p_thumbnail_path text, p_scheduled_start timestamp with time zone, p_recording_enabled boolean)
CREATE OR REPLACE FUNCTION private.tgg_live_schedule(p_content_id uuid, p_title text, p_description text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_thumbnail_path text DEFAULT NULL::text, p_scheduled_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_recording_enabled boolean DEFAULT true)
 RETURNS public.live_streams
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.live_streams;
begin
  if auth.uid() is null then raise exception 'authentication_required'; end if;
  if coalesce(trim(p_title),'')='' then raise exception 'title_required'; end if;
  if p_content_id is null then raise exception 'content_id_required'; end if;

  if not exists (
    select 1
    from public.content_items c
    where c.id=p_content_id
      and c.creator_id=auth.uid()
  ) then
    raise exception 'content_not_found_or_not_owned';
  end if;

  insert into public.live_streams(
    content_id,creator_id,title,description,category,thumbnail_path,
    scheduled_start,status,recording_enabled
  )
  values(
    p_content_id,auth.uid(),trim(p_title),p_description,p_category,p_thumbnail_path,
    p_scheduled_start,'SCHEDULED',p_recording_enabled
  )
  returning * into v;

  return v;
end
$function$


-- [40000000144] function private.tgg_live_start(p_stream_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_live_start(p_stream_id uuid)
 RETURNS public.live_streams
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.live_streams;
begin
  update public.live_streams
  set status='LIVE',
      actual_start=coalesce(actual_start,now()),
      updated_at=now()
  where id=p_stream_id
    and creator_id=auth.uid()
    and status in ('SCHEDULED','STARTING','LIVE')
  returning * into v;

  if not found then raise exception 'stream_not_found_or_not_owned'; end if;
  return v;
end
$function$


-- [40000000145] function private.tgg_lock_beat_pattern_identity()
CREATE OR REPLACE FUNCTION private.tgg_lock_beat_pattern_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if new.project_id is distinct from old.project_id
     or new.user_id is distinct from old.user_id then
    raise exception 'BEAT_PATTERN_IDENTITY_LOCKED';
  end if;
  return new;
end;
$function$


-- [40000000146] function private.tgg_log_studio_project_revision()
CREATE OR REPLACE FUNCTION private.tgg_log_studio_project_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_actor uuid:=auth.uid();
begin
  if v_actor is not null and new.revision is distinct from old.revision then
    insert into public.tgg_studio_project_events(project_id,user_id,event_type,entity_type,entity_id,patch,base_revision,revision)
    values(new.id,v_actor,'project_revision','project',new.id::text,jsonb_build_object('revision',new.revision,'updated_at',new.updated_at),old.revision,new.revision);
  end if;
  return new;
end$function$


-- [40000000147] function private.tgg_master_reuse_confirmed_for_owner(p_audio_path text)
CREATE OR REPLACE FUNCTION private.tgg_master_reuse_confirmed_for_owner(p_audio_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_confirmed boolean:=false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select coalesce(c.confirmed_intentional,false)
  into v_confirmed
  from private.tgg_distribution_master_reuse_confirmations c
  where c.owner_user_id=v_uid
    and c.audio_path=nullif(btrim(coalesce(p_audio_path,'')),'')
  limit 1;

  return coalesce(v_confirmed,false);
end
$function$


-- [40000000148] function private.tgg_matrix_gateway_enter_impl()
CREATE OR REPLACE FUNCTION private.tgg_matrix_gateway_enter_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_id uuid;
  v_path text;
begin
  v_uid:=auth.uid();
  if v_uid is null then raise exception 'authentication required'; end if;

  select path into v_path
  from public.tgg_site_routes
  where route_key='artist_world' and is_active=true
  limit 1;

  if v_path is null then raise exception 'artist_world route unavailable'; end if;

  insert into public.tgg_matrix_gateway_sessions(
    owner_user_id,state,current_route_key,entry_route_key,exit_route_key,
    rabbit_step,entered_at,metadata,updated_at
  )
  values(
    v_uid,'following_rabbit','artist_world','artist_world','artist_creator_os',
    1,now(),
    jsonb_build_object(
      'theme','matrix_gateway',
      'guide','WHITE RABBIT',
      'persona','NEO_MODE',
      'production_change_performed',false
    ),
    now()
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'session_id',v_id,'state','following_rabbit',
    'route_key','artist_world','path',v_path,
    'message','FOLLOW THE WHITE RABBIT',
    'production_change_performed',false
  );
end
$function$


-- [40000000149] function private.tgg_matrix_gateway_exit_impl(p_session_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_matrix_gateway_exit_impl(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_path text;
begin
  v_uid:=auth.uid();
  if v_uid is null then raise exception 'authentication required'; end if;

  if not exists(
    select 1 from public.tgg_matrix_gateway_sessions
    where id=p_session_id and owner_user_id=v_uid
  ) then raise exception 'gateway session not found'; end if;

  select path into v_path
  from public.tgg_site_routes
  where route_key='artist_creator_os' and is_active=true
  limit 1;

  if v_path is null then raise exception 'creator os exit route unavailable'; end if;

  update public.tgg_matrix_gateway_sessions
  set state='exited',
      current_route_key='artist_creator_os',
      exited_at=now(),
      updated_at=now()
  where id=p_session_id and owner_user_id=v_uid;

  return jsonb_build_object(
    'ok',true,'session_id',p_session_id,'state','exited',
    'route_key','artist_creator_os','path',v_path,
    'message','WAKE UP / EXIT THE MATRIX',
    'production_change_performed',false
  );
end
$function$


-- [40000000150] function private.tgg_matrix_gateway_next_impl(p_session_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_matrix_gateway_next_impl(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_session public.tgg_matrix_gateway_sessions%rowtype;
  v_next_key text;
  v_path text;
  v_next_step integer;
begin
  v_uid:=auth.uid();
  if v_uid is null then raise exception 'authentication required'; end if;

  select * into v_session
  from public.tgg_matrix_gateway_sessions
  where id=p_session_id and owner_user_id=v_uid
  for update;

  if not found then raise exception 'gateway session not found'; end if;
  if v_session.state in ('exiting','exited') then raise exception 'gateway session already exiting/exited'; end if;

  v_next_step:=v_session.rabbit_step+1;

  v_next_key:=case
    when v_next_step=2 then 'artist_games_tv'
    when v_next_step>=3 then 'artist_world'
    else 'artist_world'
  end;

  select path into v_path
  from public.tgg_site_routes
  where route_key=v_next_key and is_active=true
  limit 1;

  if v_path is null then raise exception 'next rabbit route unavailable'; end if;

  update public.tgg_matrix_gateway_sessions
  set state='inside',
      current_route_key=v_next_key,
      rabbit_step=v_next_step,
      updated_at=now()
  where id=p_session_id;

  return jsonb_build_object(
    'ok',true,'session_id',p_session_id,'state','inside',
    'rabbit_step',v_next_step,'route_key',v_next_key,'path',v_path,
    'message',case when v_next_step=2 then 'THE RABBIT GOES DEEPER' else 'YOU ARE INSIDE TGG WORLD' end
  );
end
$function$


-- [40000000151] function private.tgg_matrix_gateway_state_impl()
CREATE OR REPLACE FUNCTION private.tgg_matrix_gateway_state_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_row public.tgg_matrix_gateway_sessions%rowtype;
begin
  v_uid:=auth.uid();
  if v_uid is null then raise exception 'authentication required'; end if;

  select * into v_row
  from public.tgg_matrix_gateway_sessions
  where owner_user_id=v_uid
  order by updated_at desc
  limit 1;

  if not found then
    return jsonb_build_object(
      'state','outside',
      'entry_route_key','artist_world',
      'exit_route_key','artist_creator_os',
      'guide','WHITE RABBIT'
    );
  end if;

  return jsonb_build_object(
    'session_id',v_row.id,'state',v_row.state,
    'current_route_key',v_row.current_route_key,
    'entry_route_key',v_row.entry_route_key,
    'exit_route_key',v_row.exit_route_key,
    'rabbit_step',v_row.rabbit_step,
    'entered_at',v_row.entered_at,
    'exited_at',v_row.exited_at,
    'metadata',v_row.metadata
  );
end
$function$


-- [40000000152] function private.tgg_media_request_allow(p_fingerprint text, p_action text, p_resource_key text, p_limit integer)
CREATE OR REPLACE FUNCTION private.tgg_media_request_allow(p_fingerprint text, p_action text, p_resource_key text, p_limit integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_window timestamptz:=date_trunc('minute',now());
  v_count integer;
begin
  if p_action not in ('stream','download','download_all')
     or coalesce(length(p_fingerprint),0)<32
     or coalesce(length(p_resource_key),0)=0
     or p_limit<1
  then
    raise exception 'INVALID_MEDIA_RATE_LIMIT_INPUT' using errcode='22023';
  end if;

  insert into private.tgg_media_request_windows(
    fingerprint,action,resource_key,window_start,request_count,first_seen_at,last_seen_at
  )
  values(p_fingerprint,p_action,p_resource_key,v_window,1,now(),now())
  on conflict(fingerprint,action,resource_key,window_start)
  do update set
    request_count=private.tgg_media_request_windows.request_count+1,
    last_seen_at=now()
  returning request_count into v_count;

  return jsonb_build_object(
    'allowed',v_count<=p_limit,
    'count',v_count,
    'limit',p_limit,
    'window_start',v_window
  );
end;
$function$


-- [40000000153] function private.tgg_media_request_cleanup()
CREATE OR REPLACE FUNCTION private.tgg_media_request_cleanup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_windows integer;
  v_metrics integer;
begin
  delete from private.tgg_media_request_windows
  where last_seen_at<now()-interval '2 hours';
  get diagnostics v_windows=row_count;

  delete from private.tgg_media_metric_dedupe
  where created_at<now()-interval '24 hours';
  get diagnostics v_metrics=row_count;

  return jsonb_build_object(
    'ok',true,
    'request_windows_deleted',v_windows,
    'metric_dedupe_deleted',v_metrics,
    'cleaned_at',now()
  );
end;
$function$


-- [40000000154] function private.tgg_membership_public_join_consistency_check()
CREATE OR REPLACE FUNCTION private.tgg_membership_public_join_consistency_check()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with caps as (
  select public.tgg_public_checkout_capabilities() c
),
feed as (
  select public.tgg_public_memberships_feed() f
),
summary as (
  select
    coalesce((c->>'membership_checkout')::boolean,false) membership_checkout,
    coalesce((c->>'active_membership_tiers_with_checkout')::int,0) expected_joinable_count,
    coalesce((
      select count(*)
      from jsonb_array_elements(coalesce(f->'tiers','[]'::jsonb)) x
      where coalesce((x->>'join_available')::boolean,false)
    ),0) feed_joinable_count
  from caps,feed
)
select jsonb_build_object(
  'ok',
    case when membership_checkout
      then feed_joinable_count=expected_joinable_count and feed_joinable_count>0
      else feed_joinable_count=0
    end,
  'version','MEMBERSHIP-PUBLIC-JOIN-CONSISTENCY-1.1',
  'membership_checkout',membership_checkout,
  'expected_joinable_count',expected_joinable_count,
  'feed_joinable_count',feed_joinable_count,
  'checked_at',now()
)
from summary;
$function$


-- [40000000155] function private.tgg_monitor_blogger_live_state()
CREATE OR REPLACE FUNCTION private.tgg_monitor_blogger_live_state()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_baseline public.tgg_production_baselines;
  v_live jsonb;
  v_checked timestamptz;
  v_fresh boolean:=false;
  v_complete boolean:=false;
  v_last_content_ok boolean:=false;
  v_actual_drift boolean:=false;
  v_locked integer:=0;
  v_seen integer:=0;
  v_drift_count integer:=0;
  v_payload jsonb;
  v_blog_status text;
  v_blog_error text;
  v_revoked_at timestamptz;
begin
  select * into v_baseline
  from public.tgg_production_baselines
  where status='locked'
  order by locked_at desc
  limit 1;

  v_live:=private.tgg_actionable_blogger_live_state(
    coalesce(v_baseline.notes->'live_blogger_hash_monitor','{}'::jsonb)
  );

  begin
    v_checked:=(v_live->>'checked_at')::timestamptz;
    v_fresh:=v_checked>=now()-interval '40 minutes';
  exception when others then
    v_fresh:=false;
  end;

  v_locked:=coalesce((v_live->>'locked_pages')::integer,0);
  v_seen:=coalesce((v_live->>'live_pages_checked')::integer,0);
  v_drift_count:=coalesce((v_live->>'drift_count')::integer,0);
  v_complete:=v_locked>0 and v_seen=v_locked;
  v_last_content_ok:=coalesce((v_live->>'ok')::boolean,false)
    and v_complete
    and v_drift_count=0;

  select status,last_error,revoked_at
  into v_blog_status,v_blog_error,v_revoked_at
  from public.v98_blogger_connections
  where blog_url='https://trugogettamixtapes.blogspot.com/'
  order by updated_at desc
  limit 1;

  v_actual_drift :=
    v_drift_count>0
    or (
      v_fresh
      and v_complete
      and not coalesce((v_live->>'ok')::boolean,false)
    );

  v_payload:=v_live || jsonb_build_object(
    'fresh',v_fresh,
    'complete',v_complete,
    'last_content_ok',v_last_content_ok,
    'actual_drift',v_actual_drift,
    'blogger_connection_status',v_blog_status,
    'blogger_last_error',v_blog_error,
    'blogger_revoked_at',v_revoked_at,
    'monitor_age_seconds',case
      when v_checked is null then null
      else extract(epoch from (now()-v_checked))::bigint
    end,
    'checked_by','private.tgg_monitor_blogger_live_state',
    'evaluated_at',now()
  );

  if not v_actual_drift then
    update public.tgg_operational_alerts
    set status='resolved',last_seen=now(),last_payload=v_payload
    where alert_key='production:blogger_live_drift'
      and status<>'resolved';
  else
    insert into public.tgg_operational_alerts(
      alert_key,status,severity,subsystem,
      first_seen,last_seen,occurrence_count,last_payload
    )
    values(
      'production:blogger_live_drift','open','warning','blogger_live',
      now(),now(),1,v_payload
    )
    on conflict(alert_key) do update
    set status='open',
        severity='warning',
        subsystem='blogger_live',
        last_seen=now(),
        occurrence_count=public.tgg_operational_alerts.occurrence_count+1,
        last_payload=excluded.last_payload;
  end if;

  if coalesce(v_blog_status,'')='connected'
     and v_revoked_at is null
     and coalesce(v_blog_error,'') not in ('google_oauth_invalid_grant')
  then
    update public.tgg_operational_alerts
    set status='resolved',last_seen=now(),last_payload=v_payload
    where alert_key='integration:blogger_oauth'
      and status<>'resolved';
  else
    insert into public.tgg_operational_alerts(
      alert_key,status,severity,subsystem,
      first_seen,last_seen,occurrence_count,last_payload
    )
    values(
      'integration:blogger_oauth','open','warning','blogger_oauth',
      now(),now(),1,v_payload
    )
    on conflict(alert_key) do update
    set status='open',
        severity='warning',
        subsystem='blogger_oauth',
        last_seen=now(),
        occurrence_count=public.tgg_operational_alerts.occurrence_count+1,
        last_payload=excluded.last_payload;
  end if;
end;
$function$


-- [40000000156] function private.tgg_monitor_production_baseline()
CREATE OR REPLACE FUNCTION private.tgg_monitor_production_baseline()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v jsonb;
  v_ok boolean;
  v_stale_count bigint:=0;
  v_stale_payload jsonb:='{}'::jsonb;
  v_native_ready boolean:=false;
  v_published bigint:=0;
  v_linked bigint:=0;
  v_uncovered bigint:=0;
  v_store_ready boolean:=false;
  v_stripe_payload jsonb:='{}'::jsonb;
begin
  v:=private.tgg_production_baseline_drift();
  v_ok:=coalesce((v->>'ok')::boolean,false);

  if v_ok then
    update public.tgg_operational_alerts
    set status='resolved',
        last_seen=now(),
        last_payload=v
    where alert_key='production:baseline_drift'
      and status<>'resolved';
  else
    insert into public.tgg_operational_alerts(
      alert_key,status,severity,subsystem,
      first_seen,last_seen,occurrence_count,last_payload
    )
    values(
      'production:baseline_drift','open','warning','production_baseline',
      now(),now(),1,v
    )
    on conflict(alert_key) do update
    set status='open',
        severity='warning',
        subsystem='production_baseline',
        last_seen=now(),
        occurrence_count=public.tgg_operational_alerts.occurrence_count+1,
        last_payload=excluded.last_payload;
  end if;

  select coalesce(enabled,false)
    and mode='production'
    and coalesce(endpoint_configured,false)
  into v_native_ready
  from public.tgg_provider_runtime_config
  where provider_key='stripe'
  limit 1;

  select
    count(*),
    count(*) filter(
      where nullif(btrim(coalesce(stripe_payment_link_url,'')),'') is not null
    )
  into v_published,v_linked
  from public.merch_products
  where status='published';

  v_uncovered:=case
    when coalesce(v_native_ready,false) then 0
    else greatest(v_published-v_linked,0)
  end;

  v_store_ready:=v_uncovered=0;

  select jsonb_build_object(
    'native_runtime_ready',coalesce(v_native_ready,false),
    'native_runtime_status',case
      when coalesce(v_native_ready,false) then 'ready'
      else coalesce(disabled_reason,'stripe_server_secret_missing')
    end,
    'published_products',v_published,
    'payment_link_fallback_products',v_linked,
    'published_products_without_checkout',v_uncovered,
    'current_catalog_ready',v_store_ready,
    'checkout_runtime','tgg-store-checkout',
    'checked_at',now()
  )
  into v_stripe_payload
  from public.tgg_provider_runtime_config
  where provider_key='stripe'
  limit 1;

  if v_store_ready then
    update public.tgg_operational_alerts
    set status='resolved',
        last_seen=now(),
        last_payload=v_stripe_payload
    where alert_key='production:store_checkout_runtime'
      and status<>'resolved';
  else
    insert into public.tgg_operational_alerts(
      alert_key,status,severity,subsystem,
      first_seen,last_seen,occurrence_count,last_payload
    )
    values(
      'production:store_checkout_runtime',
      'open',
      'warning',
      'commerce',
      now(),
      now(),
      1,
      v_stripe_payload
    )
    on conflict(alert_key) do update
    set status='open',
        severity='warning',
        subsystem='commerce',
        last_seen=now(),
        occurrence_count=public.tgg_operational_alerts.occurrence_count+1,
        last_payload=excluded.last_payload;
  end if;

  select
    count(*),
    jsonb_build_object(
      'threshold_hours',48,
      'count',count(*),
      'oldest_created_at',min(created_at),
      'reservations',coalesce(
        jsonb_agg(
          jsonb_build_object(
            'reservation_id',id,
            'product_id',product_id,
            'quantity',quantity,
            'checkout_session_id',checkout_session_id,
            'created_at',created_at,
            'expires_at',expires_at
          )
          order by created_at
        ) filter(where created_at<now()-interval '48 hours'),
        '[]'::jsonb
      )
    )
  into v_stale_count,v_stale_payload
  from public.tgg_merch_checkout_reservations
  where status='pending'
    and created_at<now()-interval '48 hours';

  if v_stale_count=0 then
    update public.tgg_operational_alerts
    set status='resolved',
        last_seen=now(),
        last_payload=v_stale_payload
    where alert_key='commerce:stale_inventory_reservation'
      and status<>'resolved';
  else
    insert into public.tgg_operational_alerts(
      alert_key,status,severity,subsystem,
      first_seen,last_seen,occurrence_count,last_payload
    )
    values(
      'commerce:stale_inventory_reservation',
      'open',
      'warning',
      'commerce',
      now(),
      now(),
      1,
      v_stale_payload
    )
    on conflict(alert_key) do update
    set status='open',
        severity='warning',
        subsystem='commerce',
        last_seen=now(),
        occurrence_count=public.tgg_operational_alerts.occurrence_count+1,
        last_payload=excluded.last_payload;
  end if;
end
$function$


-- [40000000157] function private.tgg_offer_first_gig(p_character_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_offer_first_gig(p_character_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_career text;
  v_rep integer := 0;
  v_gig public.tgg_world_gig_templates%rowtype;
  v_id uuid;
begin
  select active_career into v_career
  from public.world_characters
  where id=p_character_id and character_status='active';

  if v_career is null then return null; end if;

  select coalesce(reputation,0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=p_character_id and career_key=v_career;

  select g.* into v_gig
  from public.tgg_world_gig_templates g
  where g.enabled=true
    and (cardinality(g.career_keys)=0 or v_career=any(g.career_keys))
    and g.min_reputation <= coalesce(v_rep,0)
    and not exists (
      select 1 from public.tgg_world_character_gigs cg
      where cg.character_id=p_character_id
        and cg.gig_key=g.gig_key
        and cg.status in ('available','accepted')
    )
  order by g.min_reputation,g.gig_key
  limit 1;

  if v_gig.gig_key is null then return null; end if;

  insert into public.tgg_world_character_gigs
    (character_id,gig_key,status,offered_at,expires_at,progress,offer_context,updated_at)
  values(
    p_character_id,
    v_gig.gig_key,
    'available',
    now(),
    now()+case when v_gig.recurrence_rule='daily' then interval '1 day' else interval '7 days' end,
    '{}'::jsonb,
    jsonb_build_object('source','first_session_dialogue'),
    now()
  )
  returning id into v_id;

  return v_id;
end;
$function$


-- [40000000158] function private.tgg_one_final_activation_queue_owner()
CREATE OR REPLACE FUNCTION private.tgg_one_final_activation_queue_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','ACTIVATION-QUEUE-ONE-FINAL-1.8',
    'core_launch_ready',true,
    'automatic_internal_work_remaining',0,
    'total_tracked',(
      select count(*) from private.tgg_one_final_activation_queue
    ),
    'core_blockers',(
      select count(*) from private.tgg_one_final_activation_queue
      where core_blocking
        and status<>'complete'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),
    'complete_actionable',(
      select count(*) from private.tgg_one_final_activation_queue
      where status='complete'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),
    'actionable_remaining',(
      select count(*) from private.tgg_one_final_activation_queue
      where status<>'complete'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),
    'actionable_waiting',(
      select count(*) from private.tgg_one_final_activation_queue
      where status='waiting'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),
    'actionable_ready',(
      select count(*) from private.tgg_one_final_activation_queue
      where status='ready'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),
    'actionable_external',(
      select count(*) from private.tgg_one_final_activation_queue
      where status='external_action'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),
    'visible_noncomplete',(
      select count(*) from private.tgg_one_final_activation_queue
      where status<>'complete'
        and item_key<>'supabase_leaked_password_protection'
    ),
    'maintenance_only_count',(
      select count(*) from private.tgg_one_final_activation_queue
      where item_key='edge_physical_cleanup'
        and status<>'complete'
    ),
    'hosted_account_advisory_count',(
      select count(*) from private.tgg_one_final_activation_queue
      where item_key='supabase_leaked_password_protection'
        and status<>'complete'
    ),
    'remaining',(
      select count(*) from private.tgg_one_final_activation_queue
      where status<>'complete'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),
    'complete',(
      select count(*) from private.tgg_one_final_activation_queue
      where status='complete'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),
    'maintenance_only',jsonb_build_array(
      jsonb_build_object(
        'key','edge_physical_cleanup',
        'blocking',false,
        'runtime_impact',false,
        'reason','Current tooling has no Edge delete action. Retired functions are already logically disabled.'
      )
    ),
    'hosted_account_advisories',jsonb_build_array(
      jsonb_build_object(
        'key','supabase_leaked_password_protection',
        'blocking',false,
        'runtime_impact',false,
        'reason','Hosted Supabase Auth setting remains disabled and cannot be changed with the current MCP tool surface.'
      )
    ),
    'hidden_account_advisories',(
      select count(*) from private.tgg_one_final_activation_queue
      where item_key='supabase_leaked_password_protection'
        and status<>'complete'
    ),
    'items',coalesce((
      select jsonb_agg(jsonb_build_object(
        'key',item_key,
        'category',category,
        'title',title,
        'status',status,
        'core_blocking',core_blocking,
        'requirement',requirement,
        'next_action',next_action,
        'evidence',evidence,
        'last_checked_at',last_checked_at,
        'completed_at',completed_at,
        'maintenance_only',item_key='edge_physical_cleanup'
      ) order by category,item_key)
      from private.tgg_one_final_activation_queue
      where item_key<>'supabase_leaked_password_protection'
    ),'[]'::jsonb),
    'generated_at',now()
  );
end
$function$


-- [40000000159] function private.tgg_one_final_activation_queue_refresh_owner()
CREATE OR REPLACE FUNCTION private.tgg_one_final_activation_queue_refresh_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
