-- [40000000160] function private.tgg_one_final_operations_summary()
CREATE OR REPLACE FUNCTION private.tgg_one_final_operations_summary()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'open_incidents',(
      select count(*)
      from public.tgg_operational_incidents
      where status <> 'resolved'
    ),
    'blocking_alerts',(
      select count(*)
      from public.tgg_operational_alerts
      where status <> 'resolved'
        and severity='critical'
        and alert_key not in ('control_plane:blocked','one_final:drift_detected')
    ),
    'advisory_alerts',(
      select count(*)
      from public.tgg_operational_alerts
      where status <> 'resolved'
        and not (
          severity='critical'
          and alert_key not in ('control_plane:blocked','one_final:drift_detected')
        )
    ),
    'active_cron_jobs',(
      select count(*)
      from cron.job
      where active
    ),
    'dependency_state',coalesce((
      select state
      from public.tgg_operational_dependency_checks
      where check_key='active-runtime-dependencies'
      order by checked_at desc
      limit 1
    ),'unknown'),
    'dependency_failures',coalesce((
      select failed_count
      from public.tgg_operational_dependency_checks
      where check_key='active-runtime-dependencies'
      order by checked_at desc
      limit 1
    ),0),
    'dependency_checked_at',(
      select checked_at
      from public.tgg_operational_dependency_checks
      where check_key='active-runtime-dependencies'
      order by checked_at desc
      limit 1
    )
  )
$function$


-- [40000000161] function private.tgg_one_score(p_head integer, p_mind integer, p_body integer, p_spirit integer, p_soul integer)
CREATE OR REPLACE FUNCTION private.tgg_one_score(p_head integer, p_mind integer, p_body integer, p_spirit integer, p_soul integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select greatest(0,least(100,round(
    (
      (((p_head+p_mind+p_body+p_spirit+p_soul)::numeric/5)*0.70)
      + ((100-(greatest(p_head,p_mind,p_body,p_spirit,p_soul)-least(p_head,p_mind,p_body,p_spirit,p_soul)))*0.30)
    )
  )::integer));
$function$


-- [40000000162] function private.tgg_operational_attest()
CREATE OR REPLACE FUNCTION private.tgg_operational_attest()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare s jsonb; f text; e bigint; a bigint; r bigint; c bigint; k text; begin s:=private.tgg_operational_control_snapshot(); select count(*) into e from public.tgg_operational_evidence where captured_at>now()-interval '24 hours'; select count(*) into a from public.tgg_operational_alerts where last_seen>now()-interval '24 hours'; select count(*) into r from public.tgg_operational_remediation_queue where updated_at>now()-interval '24 hours'; select count(*) into c from public.tgg_operational_change_log where created_at>now()-interval '24 hours'; f:=md5(s::text||e::text||a::text||r::text||c::text); k:='attestation:'||to_char(now(),'YYYY-MM-DD-HH24-MI'); insert into public.tgg_operational_attestations(attestation_key,state,control_snapshot,evidence_count,alert_count,remediation_count,change_count,fingerprint) values(k,s->>'state',s,e,a,r,c,f) on conflict(attestation_key) do update set attested_at=now(),state=excluded.state,control_snapshot=excluded.control_snapshot,evidence_count=excluded.evidence_count,alert_count=excluded.alert_count,remediation_count=excluded.remediation_count,change_count=excluded.change_count,fingerprint=excluded.fingerprint; end; $function$


-- [40000000163] function private.tgg_operational_capture_evidence()
CREATE OR REPLACE FUNCTION private.tgg_operational_capture_evidence()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb; f text;
begin
 s:=private.tgg_operational_control_snapshot();
 f:=md5(s::text);
 insert into public.tgg_operational_evidence(evidence_key,source,state,payload,fingerprint)
 values('control_snapshot','private.tgg_operational_control_snapshot',case s->>'state' when 'healthy' then 'pass' when 'degraded' then 'warn' when 'blocked' then 'fail' else 'unknown' end,s,f)
 on conflict(evidence_key,fingerprint) do nothing;
 insert into public.tgg_operational_audit_log(event_key,event_type,source,severity,payload)
 values('control_snapshot','evidence_captured','private.tgg_operational_capture_evidence',case s->>'state' when 'blocked' then 'critical' when 'degraded' then 'warning' else 'info' end,s);
end; $function$


-- [40000000164] function private.tgg_operational_control_snapshot()
CREATE OR REPLACE FUNCTION private.tgg_operational_control_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  open_incidents bigint;
  critical_incidents bigint;
  recent_slo jsonb;
  cron_jobs bigint;
  system_health jsonb;
  drift jsonb;
  launch jsonb;
  v_state text;
  v_review_only_drift boolean:=false;
begin
  select count(*) into open_incidents
  from public.tgg_operational_incidents
  where status <> 'resolved';

  select count(*) into critical_incidents
  from public.tgg_operational_incidents
  where status <> 'resolved' and severity='critical';

  select coalesce(jsonb_agg(x order by x->>'subsystem'),'[]'::jsonb)
  into recent_slo
  from (
    select distinct on (subsystem)
      jsonb_build_object(
        'subsystem',subsystem,
        'health',health,
        'snapshot_at',snapshot_at,
        'availability_pct',availability_pct,
        'success_count',success_count,
        'failure_count',failure_count,
        'latency_ms_p95',latency_ms_p95
      ) x
    from public.tgg_operational_slo_snapshots
    order by subsystem,snapshot_at desc
  ) q;

  select count(*) into cron_jobs from cron.job where active;

  system_health:=public.tgg_one_final_system_health();
  drift:=public.tgg_runtime_drift_guard();
  launch:=public.tgg_launch_readiness();
  v_review_only_drift:=private.tgg_review_only_runtime_drift(drift);

  v_state:=case
    when critical_incidents>0 then 'blocked'
    when coalesce((drift->>'ok')::boolean,false)=false and not v_review_only_drift then 'blocked'
    when v_review_only_drift then 'degraded'
    when coalesce((launch->>'core_launch_ready')::boolean,false)=false then 'degraded'
    when coalesce(system_health->>'state','ATTENTION')<>'READY' then 'degraded'
    when open_incidents>0 then 'degraded'
    else 'healthy'
  end;

  return jsonb_build_object(
    'generated_at',now(),
    'state',v_state,
    'open_incidents',open_incidents,
    'critical_incidents',critical_incidents,
    'active_cron_jobs',cron_jobs,
    'latest_slo',recent_slo,
    'review_only_drift',v_review_only_drift,
    'one_final',jsonb_build_object(
      'system_health',system_health,
      'drift',drift,
      'launch',launch,
      'public_version',public.tgg_public_one_final_bundle()->>'version',
      'release_count',jsonb_array_length(public.tgg_public_one_final_bundle()->'releases')
    )
  );
end $function$


-- [40000000165] function private.tgg_operational_cron_history_retention()
CREATE OR REPLACE FUNCTION private.tgg_operational_cron_history_retention()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  delete from cron.job_run_details
  where start_time < now() - interval '30 days';

  delete from private.tgg_creator_rate_counters
  where bucket_start < now() - interval '2 days';

  delete from private.tgg_creator_mutation_audit
  where occurred_at < now() - interval '180 days';
end;
$function$


-- [40000000166] function private.tgg_operational_data_integrity_audit()
CREATE OR REPLACE FUNCTION private.tgg_operational_data_integrity_audit()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v jsonb;
begin
  select public.tgg_creator_data_integrity_readiness() into v;

  if coalesce((v->>'ok')::boolean,false) then
    update public.tgg_operational_alerts
    set status='resolved',last_seen=now(),last_payload=v
    where alert_key='data:creator_integrity'
      and status<>'resolved';
  else
    insert into public.tgg_operational_alerts(alert_key,status,severity,subsystem,first_seen,last_seen,occurrence_count,last_payload)
    values('data:creator_integrity','open','critical','creator_data_integrity',now(),now(),1,v)
    on conflict(alert_key) do update
    set status='open',
        severity='critical',
        subsystem='creator_data_integrity',
        last_seen=now(),
        occurrence_count=public.tgg_operational_alerts.occurrence_count+1,
        last_payload=excluded.last_payload;
  end if;

  return v;
end;
$function$


-- [40000000167] function private.tgg_operational_dependency_check()
CREATE OR REPLACE FUNCTION private.tgg_operational_dependency_check()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s jsonb;
  d bigint:=0;
  f bigint:=0;
  st text;
  fp text;
  handoff jsonb;
  exposure jsonb;
  integrity jsonb;
  lifecycle jsonb;
  idempotency jsonb;
  write_validation jsonb;
  abuse_control jsonb;
  schema_attestation jsonb;
  download_policy_consistency jsonb;
  public_route_contract jsonb;
  membership_join_consistency jsonb;
  completed_handoff_consistency jsonb;
  distribution_metadata_coverage jsonb;
  call_invite_freshness jsonb;
  legacy_public_route_retirement jsonb;
  call_invite_expiry_watch jsonb;
  extra_failures bigint:=0;
  pending_post_change bigint:=0;
begin
  perform private.tgg_refresh_migration_hygiene_runtime_inventory();
  handoff:=private.tgg_sync_provider_handoff_status();
  exposure:=private.tgg_operational_exposure_audit();
  integrity:=private.tgg_operational_data_integrity_audit();
  lifecycle:=public.tgg_creator_lifecycle_integrity_readiness();
  idempotency:=public.tgg_creator_idempotency_readiness();
  write_validation:=public.tgg_creator_write_validation_readiness();
  abuse_control:=public.tgg_creator_abuse_control_readiness();
  schema_attestation:=private.tgg_post_migration_schema_attestation_check();
  download_policy_consistency:=private.tgg_release_download_policy_consistency_check();
  public_route_contract:=private.tgg_public_route_contract_consistency_check();
  membership_join_consistency:=private.tgg_membership_public_join_consistency_check();
  completed_handoff_consistency:=private.tgg_completed_provider_handoff_consistency_check();
  distribution_metadata_coverage:=private.tgg_distribution_metadata_coverage_check();
  call_invite_freshness:=private.tgg_call_validation_invite_freshness_check();
  legacy_public_route_retirement:=private.tgg_legacy_public_route_retirement_check();
  call_invite_expiry_watch:=private.tgg_call_invite_expiry_watch();
  s:=private.tgg_operational_control_snapshot();

  select count(*) into d
  from cron.job
  where active=true and jobname like 'tgg-%';

  with active as (
    select j.jobid,
           coalesce((
             select max(c.changed_at)
             from private.tgg_cron_config_changes c
             where c.jobid=j.jobid
           ),'-infinity'::timestamptz) as config_changed_at
    from cron.job j
    where j.active=true and j.jobname like 'tgg-%'
  ),
  ranked as (
    select d.jobid,d.status,d.return_message,d.start_time,
           row_number() over(partition by d.jobid order by d.start_time desc) rn
    from active a
    join cron.job_run_details d
      on d.jobid=a.jobid
     and d.start_time>=a.config_changed_at
  ),
  per_job as (
    select
      jobid,
      max(status) filter(where rn=1) as latest_status,
      max(return_message) filter(where rn=1) as latest_message,
      max(status) filter(where rn=2) as previous_status
    from ranked
    where rn<=2
    group by jobid
  )
  select count(*) into f
  from per_job
  where latest_status not in ('succeeded','running')
    and not (
      coalesce(latest_message,'')='job startup timeout'
      and previous_status='succeeded'
    );

  with active as (
    select j.jobid,
           coalesce((
             select max(c.changed_at)
             from private.tgg_cron_config_changes c
             where c.jobid=j.jobid
           ),'-infinity'::timestamptz) as config_changed_at
    from cron.job j
    where j.active=true and j.jobname like 'tgg-%'
  )
  select count(*) into pending_post_change
  from active a
  where a.config_changed_at>'-infinity'::timestamptz
    and not exists(
      select 1 from cron.job_run_details d
      where d.jobid=a.jobid and d.start_time>=a.config_changed_at
    );

  extra_failures :=
    case when coalesce((exposure->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((integrity->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((lifecycle->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((idempotency->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((write_validation->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((abuse_control->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((schema_attestation->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((download_policy_consistency->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((public_route_contract->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((membership_join_consistency->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((completed_handoff_consistency->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((distribution_metadata_coverage->>'ok')::boolean,false) then 0 else 1 end
    + case when coalesce((legacy_public_route_retirement->>'ok')::boolean,false) then 0 else 1 end;

  st:=case
    when d=0 then 'unknown'
    when f>0 or extra_failures>0 then 'fail'
    else 'pass'
  end;

  fp:=md5(
    coalesce(s::text,'{}')||d::text||f::text
    ||coalesce(handoff::text,'{}')
    ||coalesce(exposure::text,'{}')
    ||coalesce(integrity::text,'{}')
    ||coalesce(lifecycle::text,'{}')
    ||coalesce(idempotency::text,'{}')
    ||coalesce(write_validation::text,'{}')
    ||coalesce(abuse_control::text,'{}')
    ||coalesce(schema_attestation::text,'{}')
    ||coalesce(download_policy_consistency::text,'{}')
    ||coalesce(public_route_contract::text,'{}')
    ||coalesce(membership_join_consistency::text,'{}')
    ||coalesce(completed_handoff_consistency::text,'{}')
    ||coalesce(distribution_metadata_coverage::text,'{}')
    ||coalesce(call_invite_freshness::text,'{}')
    ||coalesce(legacy_public_route_retirement::text,'{}')
    ||coalesce(call_invite_expiry_watch::text,'{}')
  );

  insert into public.tgg_operational_dependency_checks
    (check_key,state,dependency_count,failed_count,details,fingerprint)
  values(
    'active-runtime-dependencies',
    st,
    d,
    f+extra_failures,
    jsonb_build_object(
      'control',s,
      'active_cron_jobs',d,
      'persistent_failed_active_jobs',f,
      'pending_first_post_config_change_run',pending_post_change,
      'historical_failures_preserved',true,
      'cron_config_change_registry','private.tgg_cron_config_changes',
      'provider_handoff_sync',handoff,
      'database_exposure_audit',exposure,
      'creator_data_integrity_audit',integrity,
      'creator_lifecycle_integrity_audit',lifecycle,
      'creator_idempotency_audit',idempotency,
      'creator_write_validation_audit',write_validation,
      'creator_abuse_control_audit',abuse_control,
      'post_migration_schema_attestation',schema_attestation,
      'release_download_policy_consistency',download_policy_consistency,
      'public_route_contract_consistency',public_route_contract,
      'membership_public_join_consistency',membership_join_consistency,
      'completed_provider_handoff_consistency',completed_handoff_consistency,
      'distribution_metadata_coverage',distribution_metadata_coverage,
      'call_validation_invite_freshness',call_invite_freshness,
      'call_validation_invite_freshness_core_blocking',false,
      'legacy_public_route_retirement',legacy_public_route_retirement,
      'call_validation_invite_expiry_watch',call_invite_expiry_watch,
      'call_validation_invite_expiry_watch_core_blocking',false,
      'schema_attestation_required',true,
      'strategy','latest_two_runs_after_latest_recorded_config_change_plus_dependency_audits',
      'control_state_is_informational',true
    ),
    fp
  )
  on conflict(check_key) do update set
    checked_at=now(),
    state=excluded.state,
    dependency_count=excluded.dependency_count,
    failed_count=excluded.failed_count,
    details=excluded.details,
    fingerprint=excluded.fingerprint;
end
$function$


-- [40000000168] function private.tgg_operational_evaluate_alerts()
CREATE OR REPLACE FUNCTION private.tgg_operational_evaluate_alerts()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s jsonb;
  slo record;
  k text;
  v_drift jsonb;
  v_launch jsonb;
  v_core_blockers integer:=0;
  v_core_complete boolean:=false;
  v_system_ok boolean:=false;
  v_core_issue boolean:=false;
  v_review_only_drift boolean:=false;
begin
  s:=private.tgg_operational_control_snapshot();
  v_drift:=coalesce(s->'one_final'->'drift','{}'::jsonb);
  v_launch:=coalesce(s->'one_final'->'launch','{}'::jsonb);
  v_review_only_drift:=private.tgg_review_only_runtime_drift(v_drift);

  begin
    v_core_blockers:=coalesce((v_launch#>>'{external_completion,core_blockers}')::integer,0);
  exception when others then
    v_core_blockers:=0;
  end;

  v_core_complete :=
    coalesce((v_launch#>>'{external_completion,core_complete}')::boolean,false)
    or coalesce((v_launch->>'core_launch_ready')::boolean,false)
    or coalesce((v_launch->>'platform_complete')::boolean,false);

  begin
    v_system_ok:=coalesce((s#>>'{system_health,ok}')::boolean,false);
  exception when others then
    v_system_ok:=false;
  end;

  v_core_issue :=
    v_core_blockers>0
    or (not coalesce((v_drift->>'ok')::boolean,false) and not v_review_only_drift)
    or not v_system_ok
    or not v_core_complete;

  if s->>'state'='blocked' or (s->>'state'='degraded' and v_core_issue) then
    k:='control_plane:'||coalesce(s->>'state','unknown');

    insert into public.tgg_operational_alerts(alert_key,severity,subsystem,last_payload)
    values(
      k,
      case when s->>'state'='blocked' then 'critical' else 'warning' end,
      'control_plane',
      s
    )
    on conflict(alert_key) do update
    set status='open',
        last_seen=now(),
        occurrence_count=public.tgg_operational_alerts.occurrence_count+1,
        last_payload=excluded.last_payload,
        severity=excluded.severity;

    update public.tgg_operational_alerts
    set status='resolved',
        last_seen=now(),
        last_payload=coalesce(last_payload,'{}'::jsonb)
          || jsonb_build_object(
            'resolution','superseded_by_current_control_plane_state',
            'current_alert_key',k
          )
    where status<>'resolved'
      and alert_key like 'control_plane:%'
      and alert_key<>k;
  else
    update public.tgg_operational_alerts
    set status='resolved',
        last_seen=now(),
        last_payload=coalesce(last_payload,'{}'::jsonb)
          || jsonb_build_object(
            'resolution',case when v_review_only_drift then 'protected_review_only_drift' else 'core_ready_optional_external_actions_pending' end,
            'core_blockers',v_core_blockers,
            'core_complete',v_core_complete,
            'review_only_drift',v_review_only_drift
          )
    where status<>'resolved'
      and alert_key like 'control_plane:%';
  end if;

  if coalesce((v_drift->>'ok')::boolean,false)=false then
    insert into public.tgg_operational_alerts(alert_key,severity,subsystem,last_payload)
    values(
      'one_final:drift_detected',
      case when v_review_only_drift then 'warning' else 'critical' end,
      'one_final',
      v_drift || jsonb_build_object('review_only',v_review_only_drift)
    )
    on conflict(alert_key) do update
    set status='open',
        last_seen=now(),
        occurrence_count=public.tgg_operational_alerts.occurrence_count+1,
        last_payload=excluded.last_payload,
        severity=excluded.severity;
  else
    update public.tgg_operational_alerts
    set status='resolved',last_seen=now()
    where alert_key='one_final:drift_detected'
      and status<>'resolved';
  end if;

  if v_core_blockers>0 or (not v_core_complete and not v_review_only_drift) then
    insert into public.tgg_operational_alerts(alert_key,severity,subsystem,last_payload)
    values('one_final:platform_incomplete','warning','one_final',v_launch)
    on conflict(alert_key) do update
    set status='open',
        last_seen=now(),
        occurrence_count=public.tgg_operational_alerts.occurrence_count+1,
        last_payload=excluded.last_payload,
        severity='warning';
  else
    update public.tgg_operational_alerts
    set status='resolved',
        last_seen=now(),
        last_payload=coalesce(last_payload,'{}'::jsonb)
          || jsonb_build_object(
            'resolution',case when v_review_only_drift then 'core_complete_review_only_drift' else 'core_complete_full_connect_optional' end,
            'core_blockers',v_core_blockers,
            'review_only_drift',v_review_only_drift
          )
    where alert_key='one_final:platform_incomplete'
      and status<>'resolved';
  end if;

  for slo in
    select distinct on (subsystem)
      subsystem,health,availability_pct,success_count,failure_count
    from public.tgg_operational_slo_snapshots
    order by subsystem,snapshot_at desc
  loop
    k:='slo:'||slo.subsystem;

    if slo.health in ('degraded','blocked') then
      insert into public.tgg_operational_alerts(alert_key,severity,subsystem,last_payload)
      values(
        k,
        case when slo.health='blocked' then 'critical' else 'warning' end,
        slo.subsystem,
        jsonb_build_object(
          'health',slo.health,
          'availability_pct',slo.availability_pct,
          'success_count',slo.success_count,
          'failure_count',slo.failure_count
        )
      )
      on conflict(alert_key) do update
      set status='open',
          last_seen=now(),
          occurrence_count=public.tgg_operational_alerts.occurrence_count+1,
          last_payload=excluded.last_payload,
          severity=excluded.severity;
    else
      update public.tgg_operational_alerts
      set status='resolved',last_seen=now()
      where alert_key=k
        and status<>'resolved';
    end if;
  end loop;

  if coalesce((v_drift->>'ok')::boolean,false) then
    update public.tgg_operational_alerts
    set status='resolved',
        last_seen=now(),
        last_payload=coalesce(last_payload,'{}'::jsonb)
          || jsonb_build_object(
            'resolution','baseline_drift_cleared',
            'resolved_drift',v_drift
          )
    where alert_key='production:baseline_drift'
      and status<>'resolved';
  end if;

  update public.tgg_operational_alerts
  set status='resolved',
      last_seen=now(),
      last_payload=coalesce(last_payload,'{}'::jsonb)
        || jsonb_build_object(
          'consolidated_into','integration:blogger_oauth',
          'runtime_impact',false
        )
  where alert_key='maintenance:blogger_reauth_required'
    and status<>'resolved';
end $function$


-- [40000000169] function private.tgg_operational_exposure_audit()
CREATE OR REPLACE FUNCTION private.tgg_operational_exposure_audit()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tables jsonb;
  v_views jsonb;
  v_functions jsonb;
  v_guarded_functions jsonb;
  v_table_count integer:=0;
  v_view_count integer:=0;
  v_function_count integer:=0;
  v_guarded_function_count integer:=0;
  v_public_anon_count integer:=0;
  v_auth_unguarded_count integer:=0;
  v_payload jsonb;
begin
  with exposed as (
    select c.relname
    from pg_catalog.pg_class c
    join pg_catalog.pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public'
      and c.relkind='r'
      and not c.relrowsecurity
      and (
        pg_catalog.has_table_privilege('anon','public.'||pg_catalog.quote_ident(c.relname),'SELECT')
        or pg_catalog.has_table_privilege('anon','public.'||pg_catalog.quote_ident(c.relname),'INSERT')
        or pg_catalog.has_table_privilege('anon','public.'||pg_catalog.quote_ident(c.relname),'UPDATE')
        or pg_catalog.has_table_privilege('anon','public.'||pg_catalog.quote_ident(c.relname),'DELETE')
        or pg_catalog.has_table_privilege('authenticated','public.'||pg_catalog.quote_ident(c.relname),'SELECT')
        or pg_catalog.has_table_privilege('authenticated','public.'||pg_catalog.quote_ident(c.relname),'INSERT')
        or pg_catalog.has_table_privilege('authenticated','public.'||pg_catalog.quote_ident(c.relname),'UPDATE')
        or pg_catalog.has_table_privilege('authenticated','public.'||pg_catalog.quote_ident(c.relname),'DELETE')
      )
  )
  select count(*),coalesce(jsonb_agg(relname order by relname),'[]'::jsonb)
  into v_table_count,v_tables
  from exposed;

  with exposed as (
    select c.relname
    from pg_catalog.pg_class c
    join pg_catalog.pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public'
      and c.relkind='v'
      and (
        pg_catalog.has_table_privilege('anon','public.'||pg_catalog.quote_ident(c.relname),'SELECT')
        or pg_catalog.has_table_privilege('authenticated','public.'||pg_catalog.quote_ident(c.relname),'SELECT')
      )
      and not ('security_invoker=true'=any(coalesce(c.reloptions,array[]::text[])))
  )
  select count(*),coalesce(jsonb_agg(relname order by relname),'[]'::jsonb)
  into v_view_count,v_views
  from exposed;

  with secdef as (
    select p.oid,
           p.proname||'('||pg_catalog.pg_get_function_identity_arguments(p.oid)||')' signature,
           pg_catalog.has_function_privilege('public',p.oid,'EXECUTE') as public_exec,
           pg_catalog.has_function_privilege('anon',p.oid,'EXECUTE') as anon_exec,
           pg_catalog.has_function_privilege('authenticated',p.oid,'EXECUTE') as auth_exec,
           position('auth.uid()' in lower(pg_catalog.pg_get_functiondef(p.oid)))>0 as has_uid_guard
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.prosecdef=true
  ), unsafe as (
    select signature,
           (public_exec or anon_exec) as public_or_anon,
           (auth_exec and not has_uid_guard) as auth_unguarded
    from secdef
    where public_exec or anon_exec or (auth_exec and not has_uid_guard)
  ), guarded as (
    select signature
    from secdef
    where auth_exec and has_uid_guard and not public_exec and not anon_exec
  )
  select
    (select count(*) from unsafe),
    (select coalesce(jsonb_agg(signature order by signature),'[]'::jsonb) from unsafe),
    (select count(*) from unsafe where public_or_anon),
    (select count(*) from unsafe where auth_unguarded),
    (select count(*) from guarded),
    (select coalesce(jsonb_agg(signature order by signature),'[]'::jsonb) from guarded)
  into v_function_count,v_functions,v_public_anon_count,v_auth_unguarded_count,v_guarded_function_count,v_guarded_functions;

  v_payload:=jsonb_build_object(
    'ok',(v_table_count+v_view_count+v_function_count)=0,
    'version','EXPOSURE-AUDIT-1.1',
    'tables_without_rls_with_api_grants',v_table_count,
    'non_invoker_exposed_views',v_view_count,
    'unsafe_security_definer_functions',v_function_count,
    'public_or_anon_security_definer_functions',v_public_anon_count,
    'authenticated_unguarded_security_definer_functions',v_auth_unguarded_count,
    'authenticated_guarded_security_definer_functions',v_guarded_function_count,
    'tables',v_tables,
    'views',v_views,
    'functions',v_functions,
    'guarded_functions_review_inventory',v_guarded_functions,
    'guard_semantics','authenticated SECURITY DEFINER functions are not classified as exposure when direct PUBLIC/anon EXECUTE is absent and the function definition contains auth.uid() ownership/authentication gating',
    'future_default_acl_note','supabase_admin default privileges require platform-level permission; monitor catches newly exposed objects',
    'checked_at',now()
  );

  if (v_table_count+v_view_count+v_function_count)>0 then
    insert into public.tgg_operational_alerts(alert_key,severity,subsystem,last_payload)
    values('security:database_exposure','critical','database_exposure',v_payload)
    on conflict(alert_key) do update
    set status='open',last_seen=now(),occurrence_count=public.tgg_operational_alerts.occurrence_count+1,last_payload=excluded.last_payload,severity='critical';
  else
    update public.tgg_operational_alerts
    set status='resolved',last_seen=now(),last_payload=v_payload
    where alert_key='security:database_exposure' and status<>'resolved';
  end if;

  return v_payload;
end;
$function$


-- [40000000170] function private.tgg_operational_integrity_check()
CREATE OR REPLACE FUNCTION private.tgg_operational_integrity_check()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_state text:='pass';
  v_details jsonb;
  v_fp text;
  v_world jsonb;
begin
  v_world:=private.tgg_world_auto_maintenance();

  select jsonb_build_object(
    'control',private.tgg_operational_control_snapshot(),
    'open_alerts',(
      select count(*) from public.tgg_operational_alerts where status<>'resolved'
    ),
    'open_remediations',(
      select count(*) from public.tgg_operational_remediation_queue
      where status in ('queued','in_progress')
    ),
    'pending_notifications',(
      select count(*) from public.tgg_operational_notification_outbox
      where status='pending'
    ),
    'recent_evidence',(
      select count(*) from public.tgg_operational_evidence
      where captured_at>now()-interval '15 minutes'
    ),
    'world_auto_maintenance',v_world
  )
  into v_details;

  if (v_details->'control'->>'state')='blocked'
     or (v_details->>'open_alerts')::bigint>0
     or coalesce((v_world->>'ok')::boolean,false)=false then
    v_state:='warn';
  end if;

  if (v_details->>'pending_notifications')::bigint>100 then
    v_state:='fail';
  end if;

  v_fp:=md5(v_details::text);

  insert into public.tgg_operational_integrity_checks(
    check_key,state,details,fingerprint
  )
  values('production_control',v_state,v_details,v_fp)
  on conflict(check_key) do update
  set checked_at=now(),
      state=excluded.state,
      details=excluded.details,
      fingerprint=excluded.fingerprint;
end
$function$


-- [40000000171] function private.tgg_operational_queue_alert_notifications()
CREATE OR REPLACE FUNCTION private.tgg_operational_queue_alert_notifications()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 insert into public.tgg_operational_notification_outbox(alert_id,dedupe_key,notification_type,severity,title,body,payload)
 select a.id,'alert:'||a.alert_key,'operational_alert',a.severity,
        case when a.severity='critical' then 'Critical Creator OS operational alert' else 'Creator OS operational warning' end,
        'Operational alert detected for '||a.subsystem||'.',a.last_payload
 from public.tgg_operational_alerts a
 where a.status<>'resolved'
 on conflict(dedupe_key) do update set status=case when tgg_operational_notification_outbox.status='resolved' then 'pending' else tgg_operational_notification_outbox.status end,updated_at=now(),payload=excluded.payload;
 update public.tgg_operational_notification_outbox o set status='resolved',updated_at=now()
 where o.status<>'resolved' and not exists (select 1 from public.tgg_operational_alerts a where a.id=o.alert_id and a.status<>'resolved');
end; $function$


-- [40000000172] function private.tgg_operational_queue_remediation()
CREATE OR REPLACE FUNCTION private.tgg_operational_queue_remediation()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 insert into public.tgg_operational_remediation_queue(alert_id,remediation_key,subsystem,priority,status,action,evidence)
 select a.id,'remediate:'||a.alert_key,a.subsystem,case when a.severity='critical' then 'p1' else 'p2' end,'queued',
        case when a.subsystem='control_plane' then 'Inspect failing control-plane dependency and recover through existing runbook.' else 'Inspect degraded subsystem and recover through its existing production path.' end,
        a.last_payload
 from public.tgg_operational_alerts a
 where a.status<>'resolved'
 on conflict(remediation_key) do update set status=case when tgg_operational_remediation_queue.status='verified' then 'verified' else 'queued' end,updated_at=now(),evidence=excluded.evidence,alert_id=excluded.alert_id;
 update public.tgg_operational_remediation_queue q set status='verified',verified_at=now(),updated_at=now()
 where q.status in ('queued','in_progress') and q.alert_id is not null and not exists(select 1 from public.tgg_operational_alerts a where a.id=q.alert_id and a.status<>'resolved');
end; $function$


-- [40000000173] function private.tgg_operational_record_change(p_change_key text, p_change_type text, p_subsystem text, p_summary text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION private.tgg_operational_record_change(p_change_key text, p_change_type text, p_subsystem text, p_summary text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_id uuid; begin insert into public.tgg_operational_change_log(change_key,change_type,subsystem,status,summary,metadata,completed_at) values(p_change_key,p_change_type,p_subsystem,'completed',p_summary,coalesce(p_metadata,'{}'::jsonb),now()) on conflict(change_key) do update set summary=excluded.summary,metadata=excluded.metadata,status='completed',completed_at=now(); select id into v_id from public.tgg_operational_change_log where change_key=p_change_key; return v_id; end; $function$


-- [40000000174] function private.tgg_operational_record_cron_slo()
CREATE OR REPLACE FUNCTION private.tgg_operational_record_cron_slo()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_success bigint:=0;
  v_failure bigint:=0;
  v_running bigint:=0;
  v_last_end timestamptz;
  v_health text;
  v_active_jobs bigint:=0;
  v_job_ids jsonb:='[]'::jsonb;
  v_pending_post_change bigint:=0;
begin
  select count(*) into v_active_jobs
  from cron.job
  where active=true and jobname like 'tgg-%';

  with active as (
    select j.jobid,
           coalesce((
             select max(c.changed_at)
             from private.tgg_cron_config_changes c
             where c.jobid=j.jobid
           ),'-infinity'::timestamptz) as config_changed_at
    from cron.job j
    where j.active=true and j.jobname like 'tgg-%'
  ),
  ranked as (
    select
      a.jobid,d.status,d.return_message,d.start_time,d.end_time,
      row_number() over(partition by d.jobid order by d.start_time desc) rn
    from active a
    join cron.job_run_details d
      on d.jobid=a.jobid
     and d.start_time>=a.config_changed_at
  ),
  per_job as (
    select
      jobid,
      max(status) filter(where rn=1) as latest_status,
      max(return_message) filter(where rn=1) as latest_message,
      max(status) filter(where rn=2) as previous_status,
      max(end_time) filter(where rn=1) as latest_end
    from ranked
    where rn<=2
    group by jobid
  )
  select
    count(*) filter(
      where latest_status='succeeded'
         or (
           latest_status not in ('succeeded','running')
           and coalesce(latest_message,'')='job startup timeout'
           and previous_status='succeeded'
         )
    ),
    count(*) filter(
      where latest_status not in ('succeeded','running')
        and not (
          coalesce(latest_message,'')='job startup timeout'
          and previous_status='succeeded'
        )
    ),
    count(*) filter(where latest_status='running'),
    max(latest_end),
    coalesce(jsonb_agg(jobid order by jobid),'[]'::jsonb)
  into v_success,v_failure,v_running,v_last_end,v_job_ids
  from per_job;

  with active as (
    select j.jobid,
           coalesce((
             select max(c.changed_at)
             from private.tgg_cron_config_changes c
             where c.jobid=j.jobid
           ),'-infinity'::timestamptz) as config_changed_at
    from cron.job j
    where j.active=true and j.jobname like 'tgg-%'
  )
  select count(*) into v_pending_post_change
  from active a
  where a.config_changed_at>'-infinity'::timestamptz
    and not exists(
      select 1 from cron.job_run_details d
      where d.jobid=a.jobid and d.start_time>=a.config_changed_at
    );

  v_health:=case
    when v_active_jobs=0 then 'unknown'
    when v_failure>0 then 'degraded'
    else 'healthy'
  end;

  insert into public.tgg_operational_slo_snapshots(
    subsystem,health,availability_pct,success_count,failure_count,metadata
  )
  values(
    'pg_cron_runtime',
    v_health,
    case
      when v_success+v_failure=0 then null
      else round(100.0*v_success/(v_success+v_failure),3)
    end,
    v_success,
    v_failure,
    jsonb_build_object(
      'strategy','latest_two_runs_after_latest_recorded_config_change',
      'active_job_count',v_active_jobs,
      'running_count',v_running,
      'pending_first_post_change_run',v_pending_post_change,
      'tracked_job_ids',v_job_ids,
      'last_run_end',v_last_end,
      'historical_failures_preserved',true,
      'transient_startup_timeout_policy','single startup timeout after successful run counted healthy'
    )
  );
end
$function$


-- [40000000175] function private.tgg_operational_recovery_checkpoint()
CREATE OR REPLACE FUNCTION private.tgg_operational_recovery_checkpoint()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare s jsonb; f text; st text; begin s:=private.tgg_operational_control_snapshot(); f:=md5(s::text); st:=case when s->>'state'='healthy' then 'ready' when s->>'state'='degraded' then 'degraded' when s->>'state'='blocked' then 'blocked' else 'unknown' end; insert into public.tgg_operational_recovery_checkpoints(checkpoint_key,state,source,control_fingerprint,details) values('current-production',st,'private.tgg_operational_control_snapshot',f,s) on conflict(checkpoint_key) do update set created_at=now(),state=excluded.state,source=excluded.source,control_fingerprint=excluded.control_fingerprint,details=excluded.details; end; $function$


-- [40000000176] function private.tgg_operational_recovery_drill()
CREATE OR REPLACE FUNCTION private.tgg_operational_recovery_drill()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare s jsonb; k text; begin s:=private.tgg_operational_control_snapshot(); k:='baseline:'||to_char(now(),'YYYYMMDD-HH24MI'); insert into public.tgg_operational_recovery_drills(drill_key,state,scenario,pre_state,post_state,checks,completed_at,notes) values(k,'passed','non-destructive recovery readiness baseline',s,s,jsonb_build_array(jsonb_build_object('check','control_state','result',s->>'state'),jsonb_build_object('check','open_incidents','result',s->>'open_incidents'),jsonb_build_object('check','critical_incidents','result',s->>'critical_incidents')),now(),'Read-only baseline; no production mutation performed.') on conflict(drill_key) do nothing; end; $function$


-- [40000000177] function private.tgg_operational_security_attest()
CREATE OR REPLACE FUNCTION private.tgg_operational_security_attest()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare sd bigint; ae bigint; ne bigint; nr bigint; st text; d jsonb; fp text; begin select count(*) filter(where p.prosecdef),count(*) filter(where p.prosecdef and has_function_privilege('authenticated',p.oid,'EXECUTE')),count(*) filter(where p.prosecdef and has_function_privilege('anon',p.oid,'EXECUTE')) into sd,ae,ne from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'; select count(*) into nr from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and not c.relrowsecurity; d:=jsonb_build_object('security_definer_functions',sd,'authenticated_security_definer',ae,'anon_security_definer',ne,'public_tables_without_rls',nr); st:=case when ne>0 or nr>0 then 'fail' when ae>0 then 'warn' else 'pass' end; fp:=md5(d::text); insert into public.tgg_operational_security_attestations(attestation_key,state,public_security_definer_count,authenticated_security_definer_count,anon_security_definer_count,public_tables_without_rls,details,fingerprint) values('public-api-security',st,sd,ae,ne,nr,d,fp) on conflict(attestation_key) do update set checked_at=now(),state=excluded.state,public_security_definer_count=excluded.public_security_definer_count,authenticated_security_definer_count=excluded.authenticated_security_definer_count,anon_security_definer_count=excluded.anon_security_definer_count,public_tables_without_rls=excluded.public_tables_without_rls,details=excluded.details,fingerprint=excluded.fingerprint; end; $function$


-- [40000000178] function private.tgg_post_migration_schema_attestation_check()
CREATE OR REPLACE FUNCTION private.tgg_post_migration_schema_attestation_check()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_saved_md5 text;
  v_saved_count integer;
  v_current_md5 text;
  v_current_count integer;
  v_ok boolean:=false;
  v_payload jsonb;
begin
  select
    details->>'schema_attestation_md5',
    nullif(details->>'schema_attestation_object_count','')::integer
  into v_saved_md5,v_saved_count
  from public.tgg_operational_recovery_checkpoints
  where checkpoint_key='migration_hygiene_live'
  limit 1;

  if v_saved_md5 is null or v_saved_count is null then
    v_payload:=jsonb_build_object('ok',false,'error','saved_attestation_missing','checked_at',now());
  else
    with fn as (
      select
        n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' as object_key,
        md5(pg_get_functiondef(p.oid)) as definition_md5
      from pg_proc p
      join pg_namespace n on n.oid=p.pronamespace
      where (n.nspname,p.proname) in (
        ('private','tgg_launch_closeout_ops_snapshot'),
        ('public','tgg_launch_closeout_summary'),
        ('public','tgg_livekit_credentials_save'),
        ('private','tgg_apply_provider_staging_to_activation_queue'),
        ('private','tgg_reconcile_distribution_metadata_activation_item'),
        ('private','tgg_reconcile_call_validation_activation_item'),
        ('private','tgg_enforce_one_final_routes'),
        ('private','tgg_runtime_drift_guard_internal'),
        ('public','tgg_v5000_production_manifest'),
        ('private','tgg_refresh_migration_hygiene_runtime_inventory'),
        ('private','tgg_operational_dependency_check'),
        ('private','tgg_post_migration_schema_attestation_check'),
        ('private','tgg_release_download_policy_consistency_check'),
        ('public','tgg_public_one_final_bundle'),
        ('private','tgg_public_route_contract_consistency_check'),
        ('tgg_safe_api','public_memberships_feed'),
        ('private','tgg_membership_public_join_consistency_check'),
        ('private','tgg_sync_provider_handoff_status'),
        ('private','tgg_completed_provider_handoff_consistency_check'),
        ('private','tgg_call_validation_invite_freshness_check'),
        ('private','tgg_distribution_metadata_coverage_check'),
        ('private','tgg_legacy_public_route_retirement_check'),
        ('private','tgg_call_invite_expiry_watch')
      )
    ),
    cons as (
      select 'constraint:'||conname as object_key,md5(pg_get_constraintdef(oid)) as definition_md5
      from pg_constraint
      where conrelid='public.tgg_site_routes'::regclass
        and conname='tgg_site_routes_master_admin_canonical'
    ),
    route_state as (
      select 'route:'||route_key as object_key,
        md5(jsonb_build_object('path',path,'active',is_active,'primary',is_primary,'workspace',workspace_key,'access',access_level)::text) as definition_md5
      from public.tgg_site_routes
      where route_key in ('owner_master_admin','artist_creator_os','creator_expansion_control','public_mixtape_detail_legacy')
    ),
    handoff_state as (
      select 'handoff:'||provider_key as object_key,
        md5(jsonb_build_object('status',status,'required_action',required_action,'verification_check',verification_check,'target_runtime',target_runtime)::text) as definition_md5
      from public.tgg_provider_handoff
      where provider_key in ('distribution.provider','broadcast.sfu_turn','calls.two_user_validation','stripe.native','blogger.oauth')
    ),
    all_items as (
      select * from fn
      union all select * from cons
      union all select * from route_state
      union all select * from handoff_state
    )
    select md5(string_agg(object_key||':'||definition_md5,E'\n' order by object_key)),count(*)
    into v_current_md5,v_current_count
    from all_items;

    v_ok:=v_current_md5=v_saved_md5 and v_current_count=v_saved_count;
    v_payload:=jsonb_build_object(
      'ok',v_ok,
      'version','LIVE-POST-MIGRATION-MONITOR-1.8',
      'saved_md5',v_saved_md5,
      'current_md5',v_current_md5,
      'saved_count',v_saved_count,
      'current_count',v_current_count,
      'volatile_provider_notes_excluded',true,
      'self_monitoring_control_path',true,
      'download_policy_guard_protected',true,
      'public_route_contract_protected',true,'membership_and_completed_handoff_guards_protected',true,'call_invite_and_distribution_metadata_guards_protected',true,
      'checkpoint_key','migration_hygiene_live',
      'checked_at',now()
    );
  end if;

  if coalesce(v_ok,false) then
    update public.tgg_operational_alerts
    set status='resolved',last_seen=now(),last_payload=v_payload
    where alert_key='production:post_migration_schema_attestation' and status<>'resolved';
  else
    insert into public.tgg_operational_alerts(alert_key,status,severity,subsystem,first_seen,last_seen,occurrence_count,last_payload)
    values('production:post_migration_schema_attestation','open','warning','production_schema',now(),now(),1,v_payload)
    on conflict(alert_key) do update
    set status='open',severity='warning',subsystem='production_schema',last_seen=now(),
        occurrence_count=public.tgg_operational_alerts.occurrence_count+1,last_payload=excluded.last_payload;
  end if;

  return v_payload;
end
$function$


-- [40000000179] function private.tgg_prepare_call_rejoin()
CREATE OR REPLACE FUNCTION private.tgg_prepare_call_rejoin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  delete from public.tgg_call_participants
  where room_id = new.room_id
    and user_id = new.user_id
    and left_at is not null;

  return new;
end;
$function$


-- [40000000180] function private.tgg_production_baseline()
CREATE OR REPLACE FUNCTION private.tgg_production_baseline()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
begin
  select to_jsonb(b)
    into v_result
  from public.tgg_production_baselines b
  where b.status='locked'
  order by b.locked_at desc
  limit 1;

  return coalesce(v_result,'{}'::jsonb);
