$function$


-- [40000000181] function private.tgg_production_baseline_drift()
CREATE OR REPLACE FUNCTION private.tgg_production_baseline_drift()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_core jsonb;
  v_expected jsonb;
  v_allowed_access jsonb:='[]'::jsonb;
  v_storage_tightenings jsonb:='{}'::jsonb;
  v_expected_access_full jsonb:='[]'::jsonb;
  v_current jsonb;
  v_backup_matrix jsonb;
  v_bad_backups jsonb;
  v_drift jsonb:='[]'::jsonb;
  v_expected_external text[]:=array[]::text[];
  v_current_external text[]:=array[]::text[];
  v_expected_routes text[]:=array[]::text[];
  v_allowed_routes text[]:=array[]::text[];
  v_current_routes text[]:=array[]::text[];
  v_expected_realtime text[]:=array[]::text[];
  v_allowed_realtime text[]:=array[]::text[];
  v_current_realtime text[]:=array[]::text[];
  v_integrity jsonb:='{}'::jsonb;
  v_expected_pages integer:=0;
  v_valid_payloads integer:=0;
  v_invalid_payloads integer:=0;
  v_baseline_version text;
begin
  v_core:=private.tgg_production_baseline_drift_core();

  select
    b.version,
    coalesce(b.notes#>'{realtime_access_contract,matrix}','[]'::jsonb),
    coalesce(b.notes->'backup_integrity_scan','{}'::jsonb),
    jsonb_array_length(coalesce(b.notes#>'{full_page_snapshot,pages}','[]'::jsonb)),
    coalesce(array(
      select value
      from jsonb_array_elements_text(coalesce(b.notes#>'{route_audit,present}','[]'::jsonb))
      order by value
    ),array[]::text[]),
    coalesce(array(
      select value
      from jsonb_array_elements_text(coalesce(b.notes#>'{realtime_publication,expected_tables}','[]'::jsonb))
      order by value
    ),array[]::text[])
  into v_baseline_version,v_expected,v_integrity,v_expected_pages,v_expected_routes,v_expected_realtime
  from public.tgg_production_baselines b
  where b.status='locked'
  order by b.locked_at desc
  limit 1;

  select coalesce(jsonb_agg(coalesce(st.approved_contract,x) order by x->>'table'),'[]'::jsonb)
  into v_expected
  from jsonb_array_elements(v_expected) x
  left join private.tgg_baseline_security_tightenings st
    on st.baseline_version=v_baseline_version
   and st.object_kind='realtime_table'
   and st.object_key=x->>'table'
   and st.active=true;

  select coalesce(array_agg(object_key order by object_key),array[]::text[])
  into v_allowed_routes
  from private.tgg_baseline_additive_allowances
  where baseline_version=v_baseline_version
    and object_kind='route_path' and active=true;

  select coalesce(array_agg(object_key order by object_key),array[]::text[])
  into v_allowed_realtime
  from private.tgg_baseline_additive_allowances
  where baseline_version=v_baseline_version
    and object_kind='realtime_table' and active=true;

  select coalesce(jsonb_agg(approved_contract order by object_key),'[]'::jsonb)
  into v_allowed_access
  from private.tgg_baseline_additive_allowances
  where baseline_version=v_baseline_version
    and object_kind='realtime_table' and active=true;

  select coalesce(
    jsonb_object_agg(
      object_key,
      to_jsonb(coalesce((approved_contract->>'public')::boolean,false))
      order by object_key
    ),
    '{}'::jsonb
  )
  into v_storage_tightenings
  from private.tgg_baseline_security_tightenings
  where baseline_version=v_baseline_version
    and object_kind='storage_bucket_privacy'
    and active=true;

  select coalesce(array_agg(path order by path),array[]::text[])
  into v_current_routes
  from (
    select distinct split_part(path,'#',1) as path
    from public.tgg_site_routes
    where is_active=true and path like '/p/%'
  ) q;

  select coalesce(array_agg(tablename order by tablename),array[]::text[])
  into v_current_realtime
  from pg_catalog.pg_publication_tables
  where pubname='supabase_realtime' and schemaname='public';

  select coalesce(jsonb_agg(x order by x->>'table'),'[]'::jsonb)
  into v_drift
  from jsonb_array_elements(coalesce(v_core->'drift','[]'::jsonb)) x
  where not (
    x->>'type'='route_contract'
    and v_current_routes=(
      select coalesce(array_agg(distinct z order by z),array[]::text[])
      from unnest(v_expected_routes||v_allowed_routes) z
    )
  )
  and not (
    x->>'type'='realtime_publication'
    and v_current_realtime=(
      select coalesce(array_agg(distinct z order by z),array[]::text[])
      from unnest(v_expected_realtime||v_allowed_realtime) z
    )
  )
  and not (
    x->>'type'='storage_bucket_privacy'
    and ((coalesce(x->'expected','{}'::jsonb) || v_storage_tightenings)
         = coalesce(x->'current','{}'::jsonb))
  );

  if v_drift is null then v_drift:='[]'::jsonb; end if;

  v_current:=private.tgg_realtime_privilege_matrix();

  select coalesce(jsonb_agg(x order by x->>'table'),'[]'::jsonb)
  into v_expected_access_full
  from (
    select x from jsonb_array_elements(v_expected) x
    union all
    select x from jsonb_array_elements(v_allowed_access) x
  ) s;

  if v_expected_access_full is distinct from v_current then
    v_drift:=v_drift || jsonb_build_array(
      jsonb_build_object(
        'type','realtime_access_contract',
        'expected',v_expected_access_full,
        'current',v_current,
        'baseline_tables',jsonb_array_length(v_expected),
        'approved_additive_tables',jsonb_array_length(v_allowed_access)
      )
    );
  end if;

  v_backup_matrix:=private.tgg_backup_hash_parity_matrix();

  select coalesce(jsonb_agg(x),'[]'::jsonb)
  into v_bad_backups
  from jsonb_array_elements(v_backup_matrix) x
  where coalesce((x->>'matches')::boolean,false)=false;

  if jsonb_array_length(v_bad_backups)>0 then
    v_drift:=v_drift || jsonb_build_array(
      jsonb_build_object(
        'type','backup_hash_parity',
        'invalid_count',jsonb_array_length(v_bad_backups),
        'invalid',v_bad_backups
      )
    );
  end if;

  v_valid_payloads:=coalesce((v_integrity->>'valid_backups')::integer,0);
  v_invalid_payloads:=coalesce((v_integrity->>'invalid_backups')::integer,0);

  if not coalesce((v_integrity->>'ok')::boolean,false)
     or v_valid_payloads is distinct from v_expected_pages
     or v_invalid_payloads<>0
  then
    v_drift:=v_drift || jsonb_build_array(
      jsonb_build_object(
        'type','backup_payload_integrity',
        'expected_pages',v_expected_pages,
        'valid_restore_payloads',v_valid_payloads,
        'invalid_restore_payloads',v_invalid_payloads,
        'checked_at',v_integrity->>'checked_at'
      )
    );
  end if;

  select coalesce(array_agg(value order by value),array[]::text[])
  into v_expected_external
  from public.tgg_production_baselines b,
       lateral jsonb_array_elements_text(
         coalesce(b.notes#>'{route_contract,active_external_paths}','[]'::jsonb)
       )
  where b.status='locked';

  select coalesce(array_agg(path order by path),array[]::text[])
  into v_current_external
  from (
    select distinct path
    from public.tgg_site_routes
    where is_active=true and path ~ '^https://'
  ) q;

  if v_expected_external is distinct from v_current_external then
    v_drift:=v_drift || jsonb_build_array(
      jsonb_build_object(
        'type','external_route_contract',
        'expected_paths',to_jsonb(v_expected_external),
        'current_paths',to_jsonb(v_current_external)
      )
    );
  end if;

  return v_core
    || jsonb_build_object(
      'ok',jsonb_array_length(v_drift)=0,
      'drift_count',jsonb_array_length(v_drift),
      'drift',v_drift,
      'realtime_access_tables',jsonb_array_length(v_current),
      'validated_backup_hashes',jsonb_array_length(v_backup_matrix),
      'validated_restore_payloads',v_valid_payloads,
      'invalid_restore_payloads',v_invalid_payloads,
      'expected_external_routes',cardinality(v_expected_external),
      'current_external_routes',cardinality(v_current_external),
      'additive_allowance_registry',jsonb_build_object(
        'baseline',v_baseline_version,
        'route_paths',cardinality(v_allowed_routes),
        'realtime_tables',cardinality(v_allowed_realtime),
        'strict_contracts',true,
        'storage_security_tightenings',(select count(*) from jsonb_object_keys(v_storage_tightenings))
      )
    );
end
$function$


-- [40000000182] function private.tgg_production_baseline_drift_core()
CREATE OR REPLACE FUNCTION private.tgg_production_baseline_drift_core()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_baseline public.tgg_production_baselines;
  v_expected jsonb;
  v_drift jsonb:='[]'::jsonb;
  v_expected_pages integer:=0;
  v_expected_routes text[]:=array[]::text[];
  v_current_routes text[]:=array[]::text[];
  v_expected_realtime text[]:=array[]::text[];
  v_current_realtime text[]:=array[]::text[];
  v_expected_storage jsonb:='{}'::jsonb;
  v_current_storage jsonb:='{}'::jsonb;
  v_storage_regressions jsonb:='{}'::jsonb;
  v_restorable_pages integer:=0;
  v_missing_backup_paths jsonb:='[]'::jsonb;
  v_validated_expected integer:=0;
  v_validated_present integer:=0;
  v_missing_validated jsonb:='[]'::jsonb;
  v_live jsonb:='{}'::jsonb;
  v_live_checked timestamptz;
  v_live_fresh boolean:=false;
  v_live_complete boolean:=false;
  v_live_ok boolean:=false;
  v_live_drift_count integer:=0;
  v_live_locked integer:=0;
  v_live_seen integer:=0;
begin
  select * into v_baseline
  from public.tgg_production_baselines
  where status='locked'
  order by locked_at desc
  limit 1;

  if v_baseline.version is null then
    return jsonb_build_object('ok',false,'error','locked_baseline_missing');
  end if;

  v_expected:=coalesce(v_baseline.notes->'page_hashes','{}'::jsonb);
  select count(*) into v_expected_pages from jsonb_object_keys(v_expected);
  v_live:=coalesce(v_baseline.notes->'live_blogger_hash_monitor','{}'::jsonb);

  begin
    v_live_checked:=(v_live->>'checked_at')::timestamptz;
    v_live_fresh:=v_live_checked>=now()-interval '40 minutes';
  exception when others then
    v_live_fresh:=false;
  end;

  v_live_ok:=coalesce((v_live->>'ok')::boolean,false);
  v_live_drift_count:=coalesce((v_live->>'drift_count')::integer,0);
  v_live_locked:=coalesce((v_live->>'locked_pages')::integer,0);
  v_live_seen:=coalesce((v_live->>'live_pages_checked')::integer,0);
  v_live_complete:=v_live_locked=v_expected_pages and v_live_seen=v_expected_pages and v_expected_pages>0;

  if v_live_drift_count>0 or (v_live_fresh and v_live_complete and not v_live_ok) then
    v_drift:=v_drift || jsonb_build_array(jsonb_build_object(
      'type','blogger_live_content','fresh',v_live_fresh,'complete',v_live_complete,
      'expected_pages',v_expected_pages,'locked_pages',v_live_locked,
      'live_pages_checked',v_live_seen,'drift_count',v_live_drift_count,
      'drift',coalesce(v_live->'drift','[]'::jsonb),
      'missing_pages',coalesce(v_live->'missing_pages','[]'::jsonb),
      'checked_at',v_live->>'checked_at'));
  end if;

  select coalesce(array_agg(value order by value),array[]::text[])
  into v_expected_routes
  from jsonb_array_elements_text(coalesce(v_baseline.notes#>'{route_audit,present}','[]'::jsonb));

  select coalesce(array_agg(path order by path),array[]::text[])
  into v_current_routes
  from (
    select distinct split_part(path,'#',1) as path
    from public.tgg_site_routes
    where is_active=true and path like '/p/%'
  ) q;

  -- Protected baseline routes are minimum requirements. Additive routes do not mutate
  -- the checkpoint and must not be classified as drift.
  if not (v_expected_routes <@ v_current_routes) then
    v_drift:=v_drift || jsonb_build_array(jsonb_build_object(
      'type','route_contract','expected_routes',to_jsonb(v_expected_routes),
      'current_routes',to_jsonb(v_current_routes)));
  end if;

  select coalesce(array_agg(value order by value),array[]::text[])
  into v_expected_realtime
  from jsonb_array_elements_text(coalesce(v_baseline.notes#>'{realtime_publication,expected_tables}','[]'::jsonb));

  select coalesce(array_agg(tablename order by tablename),array[]::text[])
  into v_current_realtime
  from pg_catalog.pg_publication_tables
  where pubname='supabase_realtime' and schemaname='public';

  -- Realtime baseline is likewise a minimum publication contract; additive tables are allowed.
  if not (v_expected_realtime <@ v_current_realtime) then
    v_drift:=v_drift || jsonb_build_array(jsonb_build_object(
      'type','realtime_publication','expected_tables',to_jsonb(v_expected_realtime),
      'current_tables',to_jsonb(v_current_realtime)));
  end if;

  v_expected_storage:=coalesce(v_baseline.notes#>'{storage_contract,buckets}','{}'::jsonb);

  select coalesce(jsonb_object_agg(id,public order by id),'{}'::jsonb)
  into v_current_storage
  from storage.buckets
  where id in ('artist-images','audio','covers','creator-media','media-thumbnails','mixtape-audio','v98-blogger-backups','videos');

  -- Privacy tightening (baseline public=true -> current public=false) is safe hardening.
  -- Drift is only a missing expected bucket or a privacy regression from private to public.
  select coalesce(jsonb_object_agg(e.key,jsonb_build_object('expected',e.value,'current',v_current_storage->e.key)),'{}'::jsonb)
  into v_storage_regressions
  from jsonb_each(v_expected_storage) e
  where not (v_current_storage ? e.key)
     or (coalesce((e.value #>> '{}')::boolean,false)=false and coalesce((v_current_storage->>e.key)::boolean,false)=true);

  if v_storage_regressions <> '{}'::jsonb then
    v_drift:=v_drift || jsonb_build_array(jsonb_build_object(
      'type','storage_bucket_privacy','regressions',v_storage_regressions,
      'expected',v_expected_storage,'current',v_current_storage));
  end if;

  with locked as (
    select x->>'path' as path,x->>'page_id' as page_id
    from jsonb_array_elements(v_baseline.notes#>'{full_page_snapshot,pages}') x
  ), backup_map as (
    select l.path,count(distinct b.id) as backup_records,count(distinct o.name) as backup_objects
    from locked l
    left join public.v98_blogger_backups b on b.resource_type='page' and b.resource_key=l.page_id
    left join storage.objects o on o.bucket_id='v98-blogger-backups' and o.name=b.storage_path
    group by l.path
  )
  select count(*) filter(where backup_records>0 and backup_objects>0),
         coalesce(jsonb_agg(path order by path) filter(where backup_records=0 or backup_objects=0),'[]'::jsonb)
  into v_restorable_pages,v_missing_backup_paths
  from backup_map;

  if v_restorable_pages is distinct from v_expected_pages then
    v_drift:=v_drift || jsonb_build_array(jsonb_build_object(
      'type','rollback_readiness','expected_pages',v_expected_pages,
      'restorable_pages',v_restorable_pages,'missing_paths',v_missing_backup_paths));
  end if;

  with expected as (
    select x->>'path' as path,nullif(x->>'backup_id','')::uuid as backup_id
    from jsonb_array_elements(coalesce(v_baseline.notes#>'{validated_backup_contract,backups}','[]'::jsonb)) x
  ), verified as (
    select e.path,e.backup_id,b.storage_path,o.name as object_name
    from expected e
    left join public.v98_blogger_backups b on b.id=e.backup_id
    left join storage.objects o on o.bucket_id='v98-blogger-backups' and o.name=b.storage_path
  )
  select count(*),
         count(*) filter(where backup_id is not null and storage_path is not null and object_name is not null),
         coalesce(jsonb_agg(path order by path) filter(where backup_id is null or storage_path is null or object_name is null),'[]'::jsonb)
  into v_validated_expected,v_validated_present,v_missing_validated
  from verified;

  if v_validated_expected is distinct from v_expected_pages or v_validated_present is distinct from v_expected_pages then
    v_drift:=v_drift || jsonb_build_array(jsonb_build_object(
      'type','validated_restore_objects','expected_pages',v_expected_pages,
      'validated_manifest_entries',v_validated_expected,'validated_objects_present',v_validated_present,
      'missing_paths',v_missing_validated));
  end if;

  return jsonb_build_object(
    'ok',jsonb_array_length(v_drift)=0,'baseline',v_baseline.version,'checked_at',now(),
    'expected_pages',v_expected_pages,'blogger_live_fresh',v_live_fresh,
    'blogger_live_complete',v_live_complete,'blogger_live_ok',v_live_ok,
    'restorable_pages',v_restorable_pages,'validated_restore_objects',v_validated_present,
    'expected_route_paths',cardinality(v_expected_routes),'current_route_paths',cardinality(v_current_routes),
    'expected_realtime_tables',cardinality(v_expected_realtime),'current_realtime_tables',cardinality(v_current_realtime),
    'storage_buckets_checked',(select count(*) from jsonb_object_keys(v_expected_storage)),
    'drift_count',jsonb_array_length(v_drift),'drift',v_drift);
end
$function$


-- [40000000183] function private.tgg_protect_merch_payment_link()
CREATE OR REPLACE FUNCTION private.tgg_protect_merch_payment_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_changed boolean:=false;
begin
  if tg_op='INSERT' then
    v_changed := nullif(btrim(coalesce(new.stripe_payment_link_url,'')),'') is not null;
  else
    v_changed := new.stripe_payment_link_url is distinct from old.stripe_payment_link_url;
  end if;

  if v_changed and auth.uid() is not null then
    if not coalesce(private.is_admin(),false) then
      raise exception 'PAYMENT_LINK_ADMIN_REQUIRED'
        using detail='Stripe Payment Links may only be assigned by an administrator-controlled flow.';
    end if;
  end if;

  return new;
end
$function$


-- [40000000184] function private.tgg_provider_activation_mark_verified(p_provider_key text, p_verified boolean, p_error text)
CREATE OR REPLACE FUNCTION private.tgg_provider_activation_mark_verified(p_provider_key text, p_verified boolean, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update private.tgg_provider_activation_staging
  set
    status=case when p_verified then 'verified' else 'failed' end,
    last_error=case when p_verified then null else nullif(btrim(coalesce(p_error,'')),'') end,
    verified_at=case when p_verified then now() else null end,
    updated_at=now()
  where provider_key=p_provider_key;

  if not found then
    raise exception 'PROVIDER_NOT_STAGED';
  end if;

  return jsonb_build_object(
    'ok',true,
    'provider_key',p_provider_key,
    'verified',p_verified
  );
end
$function$


-- [40000000185] function private.tgg_provider_activation_stage_owner(p_provider_key text, p_endpoint_url text, p_secret_reference text)
CREATE OR REPLACE FUNCTION private.tgg_provider_activation_stage_owner(p_provider_key text, p_endpoint_url text, p_secret_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
  v_endpoint text:=nullif(btrim(coalesce(p_endpoint_url,'')),'');
  v_secret_ref text:=nullif(btrim(coalesce(p_secret_reference,'')),'');
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  if p_provider_key not in ('distribution.provider','broadcast.sfu_turn') then
    raise exception 'UNSUPPORTED_PROVIDER_KEY' using errcode='22023';
  end if;

  if p_provider_key='distribution.provider'
     and (v_endpoint is null or v_endpoint !~ '^https://[^[:space:]]+$')
  then
    raise exception 'HTTPS_ENDPOINT_REQUIRED' using errcode='22023';
  end if;

  if p_provider_key='broadcast.sfu_turn'
     and (
       v_endpoint is null
       or v_endpoint !~ '^(https|wss)://[^[:space:]]+$'
     )
  then
    raise exception 'HTTPS_OR_WSS_ENDPOINT_REQUIRED' using errcode='22023';
  end if;

  if v_secret_ref is not null and (
       length(v_secret_ref)>160
       or v_secret_ref ~ '[[:space:]]'
       or v_secret_ref ~ '^(sk_|pk_|eyJ|Bearer[[:space:]])'
     )
  then
    raise exception 'SECRET_REFERENCE_ONLY' using errcode='22023';
  end if;

  insert into private.tgg_provider_activation_staging(
    provider_key,endpoint_url,secret_reference,status,last_error,
    staged_by,staged_at,verified_at,updated_at
  )
  values(
    p_provider_key,v_endpoint,v_secret_ref,'staged',null,
    v_uid,now(),null,now()
  )
  on conflict(provider_key) do update set
    endpoint_url=excluded.endpoint_url,
    secret_reference=excluded.secret_reference,
    status='staged',
    last_error=null,
    staged_by=v_uid,
    staged_at=now(),
    verified_at=null,
    updated_at=now();

  return jsonb_build_object(
    'ok',true,
    'provider_key',p_provider_key,
    'status','staged',
    'endpoint_url',v_endpoint,
    'secret_reference',v_secret_ref,
    'secret_value_stored',false,
    'endpoint_transport',
      case when p_provider_key='broadcast.sfu_turn' and v_endpoint like 'wss://%' then 'wss' else 'https' end,
    'next_step',
      'Store the actual provider secret in the server/Edge secret store, verify the endpoint, then enable the provider runtime.'
  );
end
$function$


-- [40000000186] function private.tgg_provider_activation_stage_status()
CREATE OR REPLACE FUNCTION private.tgg_provider_activation_stage_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
  v_rows jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    return jsonb_build_object(
      'ok',true,
      'owner',false,
      'items','[]'::jsonb
    );
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'provider_key',provider_key,
      'endpoint_url',endpoint_url,
      'secret_reference',secret_reference,
      'status',status,
      'last_error',last_error,
      'staged_at',staged_at,
      'verified_at',verified_at,
      'updated_at',updated_at,
      'secret_value_exposed',false
    )
    order by provider_key
  ),'[]'::jsonb)
  into v_rows
  from private.tgg_provider_activation_staging
  where provider_key in ('distribution.provider','broadcast.sfu_turn');

  return jsonb_build_object(
    'ok',true,
    'owner',true,
    'items',v_rows,
    'generated_at',now()
  );
end
$function$


-- [40000000187] function private.tgg_provider_activation_staging_status_owner()
