-- [40000000188] function private.tgg_provider_activation_verification_status_owner()
CREATE OR REPLACE FUNCTION private.tgg_provider_activation_verification_status_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'items',coalesce((
      select jsonb_agg(jsonb_build_object(
        'provider_key',x.provider_key,
        'status',x.status,
        'status_code',x.status_code,
        'timed_out',x.timed_out,
        'error_message',x.error_message,
