        'verification_scope','reachability_only'
      ) order by x.provider_key)
      from (
        select distinct on (provider_key)
          provider_key,status,status_code,timed_out,error_message,
          endpoint_url,probe_url,requested_at,completed_at,id
        from private.tgg_provider_endpoint_checks
        order by provider_key,id desc
      ) x
    ),'[]'::jsonb),
    'generated_at',now()
  );
end;
$function$


-- [40000000189] function private.tgg_provider_activation_verify_owner(p_provider_key text)
CREATE OR REPLACE FUNCTION private.tgg_provider_activation_verify_owner(p_provider_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
  v_endpoint text;
  v_probe text;
  v_host text;
  v_request bigint;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  if p_provider_key not in ('distribution.provider','broadcast.sfu_turn') then
    raise exception 'UNSUPPORTED_PROVIDER_KEY' using errcode='22023';
  end if;

  select endpoint_url
  into v_endpoint
  from private.tgg_provider_activation_staging
  where provider_key=p_provider_key;

  if nullif(btrim(coalesce(v_endpoint,'')),'') is null then
    raise exception 'ENDPOINT_NOT_STAGED' using errcode='22023';
  end if;

  if p_provider_key='distribution.provider' and v_endpoint !~ '^https://[^[:space:]]+$' then
    raise exception 'HTTPS_ENDPOINT_REQUIRED' using errcode='22023';
  end if;

  if p_provider_key='broadcast.sfu_turn'
     and v_endpoint !~ '^(https|wss)://[^[:space:]]+$'
  then
    raise exception 'HTTPS_OR_WSS_ENDPOINT_REQUIRED' using errcode='22023';
  end if;

  v_host:=lower(
    coalesce(
      substring(v_endpoint from '^(?:https|wss)://([^/:?#]+)'),
      ''
    )
  );

  if v_host=''
     or v_host in ('localhost','localhost.localdomain')
     or v_host like '%.localhost'
     or v_host like '%.local'
     or v_host like '%.internal'
     or v_host ~ '^[0-9]{1,3}(\.[0-9]{1,3}){3}$'
     or v_host like '[%]'
  then
    raise exception 'PUBLIC_HOSTNAME_REQUIRED' using errcode='22023';
  end if;

  v_probe:=case
    when v_endpoint like 'wss://%' then 'https://'||substring(v_endpoint from 7)
    else v_endpoint
  end;

  select net.http_get(
    url:=v_probe,
    params:='{}'::jsonb,
    headers:=jsonb_build_object(
      'User-Agent','TGG-Activation-Bridge/1.0',
      'Accept','application/json,text/plain,*/*'
    ),
    timeout_milliseconds:=5000
  )
  into v_request;

  insert into private.tgg_provider_endpoint_checks(
    provider_key,endpoint_url,probe_url,request_id,status,requested_by
  )
  values(
    p_provider_key,v_endpoint,v_probe,v_request,'queued',v_uid
  );

  update private.tgg_provider_activation_staging
  set status='staged',
      last_error=null,
      updated_at=now()
  where provider_key=p_provider_key;

  return jsonb_build_object(
    'ok',true,
    'provider_key',p_provider_key,
    'status','queued',
    'request_id',v_request,
    'endpoint_url',v_endpoint,
    'probe_url',v_probe,
    'verification_scope','reachability_only',
    'credentials_verified',false
  );
end;
$function$


-- [40000000190] function private.tgg_provider_endpoint_collect()
CREATE OR REPLACE FUNCTION private.tgg_provider_endpoint_collect()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_done integer:=0;
  v_success integer:=0;
  v_failed integer:=0;
  v_lock boolean:=false;
  v_queue jsonb;
begin
  perform private.tgg_cleanup_retired_cron_jobs();

  v_lock:=pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended('tgg_activation_queue_refresh',0)
  );

  if not v_lock then
    return jsonb_build_object(
      'ok',true,
      'skipped',true,
      'reason','activation_queue_refresh_busy',
      'processed',0,
      'succeeded',0,
      'failed',0,
      'collected_at',now()
    );
  end if;

  with ready as (
    select
      c.id as check_id,
      c.provider_key,
      r.status_code,
      coalesce(r.timed_out,false) as timed_out,
      r.error_msg
    from private.tgg_provider_endpoint_checks c
    join net._http_response r on r.id=c.request_id
    where c.status='queued'
  ),
  upd as (
    update private.tgg_provider_endpoint_checks c
    set
      status=case
        when r.timed_out=false
         and r.error_msg is null
         and r.status_code between 200 and 499
        then 'succeeded'
        else 'failed'
      end,
      status_code=r.status_code,
      timed_out=r.timed_out,
      error_message=r.error_msg,
      completed_at=now(),
      updated_at=now()
    from ready r
    where c.id=r.check_id
    returning c.id,c.provider_key,c.status,c.status_code,c.error_message
  )
  select
    count(*),
    count(*) filter(where status='succeeded'),
    count(*) filter(where status='failed')
  into v_done,v_success,v_failed
  from upd;

  update private.tgg_provider_activation_staging s
  set status='verified',
      verified_at=now(),
      last_error=null,
      updated_at=now()
  where exists(
    select 1
    from private.tgg_provider_endpoint_checks c
    where c.provider_key=s.provider_key
      and c.status='succeeded'
      and c.id=(
        select max(c2.id)
        from private.tgg_provider_endpoint_checks c2
        where c2.provider_key=s.provider_key
      )
  );

  update private.tgg_provider_activation_staging s
  set status='failed',
      verified_at=null,
      last_error=coalesce((
        select coalesce(c.error_message,'HTTP '||coalesce(c.status_code::text,'unknown'))
        from private.tgg_provider_endpoint_checks c
        where c.provider_key=s.provider_key
        order by c.id desc
        limit 1
      ),'endpoint_probe_failed'),
      updated_at=now()
  where exists(
    select 1
    from private.tgg_provider_endpoint_checks c
    where c.provider_key=s.provider_key
      and c.status='failed'
      and c.id=(
        select max(c2.id)
        from private.tgg_provider_endpoint_checks c2
        where c2.provider_key=s.provider_key
      )
  );

  update public.tgg_provider_runtime_config r
  set endpoint_configured=true,
      disabled_reason=case
        when exists(
          select 1
          from private.tgg_provider_secret_registry s
          where s.provider_key=r.provider_key
            and s.status in ('stored','verified')
        ) then 'provider_auth_verification_pending'
        else 'activation_bridge_secret_required'
      end,
      updated_at=now()
  where r.provider_key in ('distribution.provider','broadcast.sfu_turn')
    and exists(
      select 1
      from private.tgg_provider_activation_staging s
      where s.provider_key=r.provider_key
        and s.status='verified'
    );

  v_queue:=private.tgg_apply_provider_staging_to_activation_queue();

  return jsonb_build_object(
    'ok',true,
    'version','PROVIDER-ENDPOINT-COLLECT-ONE-FINAL-1.3',
    'skipped',false,
    'processed',v_done,
    'succeeded',v_success,
    'failed',v_failed,
    'queue_updates',coalesce((v_queue->>'updates')::integer,0),
    'full_activation_monitor_called',false,
    'collected_at',now()
  );
end
$function$


-- [40000000191] function private.tgg_provider_secret_status_owner()
CREATE OR REPLACE FUNCTION private.tgg_provider_secret_status_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','PROVIDER-SECRET-STATUS-ONE-FINAL-1.1',
    'providers',coalesce((
      select jsonb_agg(jsonb_build_object(
        'provider_key',x.provider_key,
        'status',case
          when r.status is not null then r.status
          when coalesce(c.enabled,false)
            and c.mode='production'
            and coalesce(c.endpoint_configured,false)
            then 'runtime_verified'
          else 'missing'
        end,
        'vault_secret_name',x.vault_secret_name,
        'storage_source',case
          when r.status is not null then 'vault_registry'
          when coalesce(c.enabled,false)
            and c.mode='production'
            and coalesce(c.endpoint_configured,false)
            then 'runtime_secret'
          else null
        end,
        'runtime_ready',coalesce(c.enabled,false)
          and c.mode='production'
          and coalesce(c.endpoint_configured,false),
        'stored_at',r.stored_at,
        'verified_at',coalesce(r.verified_at,c.updated_at),
        'last_error',r.last_error
      ) order by x.provider_key)
      from (
        values
          ('stripe.webhook','tgg_stripe_webhook_secret'),
          ('email.resend','tgg_resend_api_key'),
          ('distribution.provider','tgg_distribution_provider_secret'),
          ('broadcast.sfu_turn','tgg_broadcast_provider_secret')
      ) x(provider_key,vault_secret_name)
      left join private.tgg_provider_secret_registry r
        on r.provider_key=x.provider_key
      left join public.tgg_provider_runtime_config c
        on c.provider_key=x.provider_key
    ),'[]'::jsonb),
    'generated_at',now()
  );
end
$function$


-- [40000000192] function private.tgg_public_content_engine_tick()
CREATE OR REPLACE FUNCTION private.tgg_public_content_engine_tick()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row record;
  v_published integer:=0;
  v_blocked integer:=0;
begin
  for v_row in
    select q.id,q.content_item_id
    from public.tgg_public_content_queue q
    where q.status='queued' and q.scheduled_at<=now()
    order by q.scheduled_at
    for update skip locked
  loop
    if exists(
      select 1 from public.content_items c
      where c.id=v_row.content_item_id
        and upper(c.status)='APPROVED'
        and upper(c.visibility)='PUBLIC'
    ) then
      update public.content_items
      set status='PUBLISHED',published_at=coalesce(published_at,now()),updated_at=now()
      where id=v_row.content_item_id;

      update public.tgg_public_content_queue
      set status='published',published_at=now(),updated_at=now(),last_error=null
      where id=v_row.id;

      v_published:=v_published+1;
    else
      update public.tgg_public_content_queue
      set status='blocked',last_error='content no longer approved/public',updated_at=now()
      where id=v_row.id;

      v_blocked:=v_blocked+1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',true,'version','PUBLIC-CONTENT-ENGINE-1.0',
    'published_count',v_published,'blocked_count',v_blocked,'ran_at',now()
  );
end
$function$


-- [40000000193] function private.tgg_public_epk_impl(p_slug text)
CREATE OR REPLACE FUNCTION private.tgg_public_epk_impl(p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_slug text:=lower(btrim(coalesce(p_slug,'')));
  v_settings public.tgg_epk_settings;
  v_artist public.artists;
  v_press jsonb;
  v_releases jsonb;
begin
  if v_slug !~ '^[a-z0-9][a-z0-9-]{2,63}$' then
    raise exception 'EPK_SLUG_INVALID' using errcode='22023';
  end if;

  select * into v_settings
  from public.tgg_epk_settings
  where lower(public_slug)=v_slug and is_public=true
  limit 1;

  if v_settings.owner_user_id is null then
    return jsonb_build_object('ok',false,'not_found',true);
  end if;

  select * into v_artist from public.artists where id=v_settings.artist_id limit 1;
  if v_artist.id is null then
    return jsonb_build_object('ok',false,'not_found',true);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'item_type',p.item_type,'title',p.title,'publication',p.publication,
    'url',p.url,'published_at',p.published_at,'quote',p.quote,'is_featured',p.is_featured
  ) order by p.is_featured desc,p.published_at desc nulls last,p.created_at desc),'[]'::jsonb)
  into v_press
  from public.tgg_press_items p
  where p.owner_user_id=v_settings.owner_user_id and p.artist_id=v_artist.id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'title',m.title,'slug',m.slug,'cover_url',m.cover_url,'genre',m.genre,'release_date',m.release_date,
    'url',case when m.slug is null then null else
      'https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-shell?view=release&slug='||m.slug end
  ) order by coalesce(m.release_date,m.created_at) desc),'[]'::jsonb)
  into v_releases
  from public.mixtapes m
  where m.artist_id=v_artist.id and m.status='published';

  return jsonb_build_object(
    'ok',true,'version','PUBLIC-EPK-1.0','slug',v_slug,
    'artist',jsonb_build_object(
      'stage_name',v_artist.stage_name,
      'avatar_url',v_artist.avatar_url,
      'website',v_artist.website,
      'instagram',v_artist.instagram,
      'youtube',v_artist.youtube,
      'spotify',v_artist.spotify
    ),
    'epk',jsonb_build_object(
      'headline',v_settings.headline,
      'short_bio',v_settings.short_bio,
      'location',v_settings.location,
      'highlights',v_settings.highlights
    ),
    'press_items',v_press,
    'releases',v_releases
  );
end
$function$


-- [40000000194] function private.tgg_public_route_contract_consistency_check()
CREATE OR REPLACE FUNCTION private.tgg_public_route_contract_consistency_check()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with bundle as (
  select public.tgg_public_one_final_bundle()->'canonical_routes' routes
),
expected as (
  select * from (values
    ('home'::text,'home'::text),
    ('artists','public_artists'),
    ('artist_profile','public_artist_profile'),
    ('mixtape_detail','public_mixtape_detail'),
    ('discover','discover')
  ) v(bundle_key,route_key)
),
compared as (
  select
    e.bundle_key,
    e.route_key,
    b.routes->>e.bundle_key as bundle_path,
    r.path as registry_path,
    r.is_active,
    r.is_primary,
    (b.routes->>e.bundle_key)=r.path and r.is_active=true as ok
  from expected e
  cross join bundle b
  left join public.tgg_site_routes r on r.route_key=e.route_key
)
select jsonb_build_object(
  'ok',not exists(select 1 from compared where not coalesce(ok,false)),
  'version','PUBLIC-ROUTE-CONTRACT-1.0',
  'mismatch_count',(select count(*) from compared where not coalesce(ok,false)),
  'routes',coalesce((select jsonb_agg(to_jsonb(c) order by bundle_key) from compared c),'[]'::jsonb),
  'checked_at',now()
);
$function$


-- [40000000195] function private.tgg_queue_creator_background_push()
CREATE OR REPLACE FUNCTION private.tgg_queue_creator_background_push()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hook text;
  v_request_id bigint;
begin
  if new.recipient_id is null then return new; end if;
  if not exists(
    select 1 from public.tgg_creator_device_notifications d
    where d.owner_user_id=new.recipient_id
      and d.permission_state='granted'
      and d.background_push_capable=true
      and d.push_endpoint is not null
      and d.push_p256dh is not null
      and d.push_auth is not null
  ) then return new; end if;

  v_hook:=private.tgg_get_provider_secret_service('webpush.delivery_hook');
  if v_hook is null then return new; end if;

  select net.http_post(
    url:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-creator-os-app-v17',
    headers:=jsonb_build_object('Content-Type','application/json'),
    body:=jsonb_build_object('action','deliver_creator_push','notification_id',new.id,'delivery_secret',v_hook),
    timeout_milliseconds:=8000
  ) into v_request_id;
  return new;
exception when others then
  return new;
end
$function$


-- [40000000196] function private.tgg_radio_review(p_show_id uuid, p_action text, p_note text)
CREATE OR REPLACE FUNCTION private.tgg_radio_review(p_show_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
    declare
      v_new text;
      v_count integer;
    begin
      if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
      if not exists (
        select 1 from public.profiles p
        where p.id=auth.uid() and p.role='admin'
      ) then raise exception 'ADMIN_REQUIRED'; end if;

      if p_action='approve' then
        v_new='published';
      elsif p_action='reject' then
        v_new='rejected';
      else
        raise exception 'INVALID_ACTION';
      end if;

      update public.tgg_radio_shows
      set status=v_new,
          admin_note=nullif(btrim(coalesce(p_note,'')),''),
          published_at=case when v_new='published' then now() else published_at end,
          updated_at=now()
      where id=p_show_id and status='pending';

      get diagnostics v_count = row_count;
      if v_count=0 then raise exception 'SHOW_NOT_PENDING'; end if;

      return jsonb_build_object('ok',true,'show_id',p_show_id,'status',v_new);
    end;
    $function$


-- [40000000197] function private.tgg_realtime_privilege_matrix()
CREATE OR REPLACE FUNCTION private.tgg_realtime_privilege_matrix()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with rt as (
    select tablename
    from pg_catalog.pg_publication_tables
    where pubname='supabase_realtime'
      and schemaname='public'
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'table',tablename,
      'anon_select',has_table_privilege('anon',format('public.%I',tablename),'SELECT'),
      'anon_insert',has_table_privilege('anon',format('public.%I',tablename),'INSERT'),
      'anon_update',has_table_privilege('anon',format('public.%I',tablename),'UPDATE'),
      'anon_delete',has_table_privilege('anon',format('public.%I',tablename),'DELETE'),
      'auth_select',has_table_privilege('authenticated',format('public.%I',tablename),'SELECT'),
      'auth_insert',has_table_privilege('authenticated',format('public.%I',tablename),'INSERT'),
      'auth_update',has_table_privilege('authenticated',format('public.%I',tablename),'UPDATE'),
      'auth_delete',has_table_privilege('authenticated',format('public.%I',tablename),'DELETE'),
      'policy_count',(
        select count(*)
        from pg_catalog.pg_policies p
        where p.schemaname='public'
          and p.tablename=rt.tablename
      )
    )
    order by tablename
  ),'[]'::jsonb)
  from rt
$function$


-- [40000000198] function private.tgg_recompute_progression(p_character_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_recompute_progression(p_character_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_total_rep integer:=0;
  v_properties integer:=0;
  v_businesses integer:=0;
  v_achievements integer:=0;
  v_prestige integer:=0;
  v_total_influence integer:=0;
  v_vehicle_level integer:=0;
  v_dominant_districts integer:=0;
  v_new_achievement_season_xp integer:=0;
  v_completed_story_arcs integer:=0;
  v_crew_dominant_territories integer:=0;
  v_contracts_completed integer:=0;
  v_night_events_completed integer:=0;
  v_tournament_wins integer:=0;
  v_active_career text;
  v_active_career_level integer:=1;
  v_season_multiplier numeric:=1;
  v_result jsonb:='{}'::jsonb;
begin
  select coalesce(sum(reputation),0) into v_total_rep
  from public.tgg_world_career_reputation where character_id=p_character_id;

  select active_career into v_active_career
  from public.world_characters where id=p_character_id;

  select coalesce(career_level,1) into v_active_career_level
  from public.world_character_careers
  where character_id=p_character_id and career_key=v_active_career;

  select count(*) into v_properties
  from public.tgg_world_character_properties
  where character_id=p_character_id and ownership_status='owned';

  select count(*) into v_businesses
  from public.tgg_world_character_businesses
  where character_id=p_character_id and status='active';

  select coalesce(prestige_level,0) into v_prestige
  from public.tgg_world_character_prestige
  where character_id=p_character_id;

  select coalesce(total_influence,0) into v_total_influence
  from public.tgg_world_character_influence
  where character_id=p_character_id;

  select coalesce(max(vp.vehicle_level),0) into v_vehicle_level
  from public.tgg_world_vehicles v
  join public.tgg_world_vehicle_progression vp on vp.vehicle_id=v.id
  where v.owner_character_id=p_character_id;

  select count(*) into v_dominant_districts
  from public.tgg_world_character_district_reputation
  where character_id=p_character_id and tier>=3;

  select count(*) into v_completed_story_arcs
  from public.tgg_world_character_story_state
  where character_id=p_character_id and status='completed';

  select count(*) into v_crew_dominant_territories
  from public.tgg_world_crew_members cm
  join public.tgg_world_crew_territories ct on ct.crew_id=cm.crew_id
  where cm.character_id=p_character_id
    and cm.left_at is null
    and ct.control_level='dominant';

  select count(*) into v_contracts_completed
  from public.tgg_world_character_contracts c
  join public.tgg_world_career_contracts t on t.contract_key=c.contract_key
  where c.character_id=p_character_id
    and c.status='completed'
    and t.career_key=v_active_career;

  select count(*) into v_night_events_completed
  from public.tgg_world_character_event_state s
  join public.tgg_world_dynamic_events e on e.id=s.dynamic_event_id
  join public.tgg_world_dynamic_event_templates t on t.event_key=e.event_key
  where s.character_id=p_character_id
    and s.status='completed'
    and (t.event_type in ('nightlife','nightlife_event') or t.trigger_mode='night-window');

  select count(*) into v_tournament_wins
  from public.tgg_world_tournament_entries te
  where te.character_id=p_character_id
    and te.status='completed'
    and te.placement=1;

  select greatest(coalesce((value->>'value')::numeric,1),0)
  into v_season_multiplier
  from public.tgg_world_economy_config
  where config_key='season_xp_multiplier';
  v_season_multiplier:=coalesce(v_season_multiplier,1);

  with newly as (
    insert into public.tgg_world_character_achievements(
      character_id,achievement_key,progress,unlocked_at,updated_at
    )
    select
      p_character_id,
      a.achievement_key,
      jsonb_build_object(
        'properties',v_properties,
        'businesses',v_businesses,
        'reputation',v_total_rep,
        'vehicle_level',v_vehicle_level,
        'dominant_districts',v_dominant_districts
      ),
      now(),now()
    from public.tgg_world_achievements a
    where a.enabled=true
      and (
        (a.achievement_key='ach-first-key' and v_properties>=1) or
        (a.achievement_key='ach-first-business' and v_businesses>=1) or
        (a.achievement_key='ach-citywide' and (
          select count(*) from public.tgg_world_character_district_reputation
          where character_id=p_character_id
        )>=6) or
        (a.achievement_key='ach-boss-status' and v_properties>=3 and v_businesses>=2 and v_total_rep>=100) or
        (a.achievement_key='ach-road-ready' and v_vehicle_level>=5) or
        (a.achievement_key='ach-crew-power' and v_crew_dominant_territories>=1)
      )
    on conflict(character_id,achievement_key) do nothing
    returning achievement_key
  )
  select coalesce(sum(coalesce((a.rewards->>'season_xp')::integer,0)),0)
  into v_new_achievement_season_xp
  from newly n
  join public.tgg_world_achievements a on a.achievement_key=n.achievement_key;

  insert into public.tgg_world_character_titles(character_id,title_key,unlocked_at)
  select p_character_id,t.title_key,now()
  from public.tgg_world_titles t
  join public.tgg_world_achievements a
    on lower(a.rewards->>'title')=lower(t.display_name)
  join public.tgg_world_character_achievements ca
    on ca.achievement_key=a.achievement_key and ca.character_id=p_character_id
  where t.enabled=true and ca.unlocked_at is not null and a.rewards ? 'title'
  on conflict do nothing;

  v_new_achievement_season_xp:=greatest(round(v_new_achievement_season_xp*v_season_multiplier)::integer,0);

  if v_new_achievement_season_xp>0 then
    insert into public.tgg_world_character_season_progress(
      character_id,season_key,season_level,season_xp,unlocked_rewards,updated_at
    )
    select
      p_character_id,s.season_key,1,v_new_achievement_season_xp,'[]'::jsonb,now()
    from public.tgg_world_seasons s
    where s.enabled=true
      and (s.starts_at is null or s.starts_at<=now())
      and (s.ends_at is null or s.ends_at>=now())
    order by s.starts_at desc nulls last
    limit 1
    on conflict(character_id,season_key) do update
    set season_xp=public.tgg_world_character_season_progress.season_xp+excluded.season_xp,
        updated_at=now();

    update public.tgg_world_character_season_progress sp
    set season_level=coalesce((
      select max(r.reward_level)
      from public.tgg_world_season_rewards r
      where r.season_key=sp.season_key
        and r.required_xp<=sp.season_xp
    ),1),
    updated_at=now()
    where sp.character_id=p_character_id
      and exists(
        select 1 from public.tgg_world_seasons s
        where s.season_key=sp.season_key
          and s.enabled=true
          and (s.starts_at is null or s.starts_at<=now())
          and (s.ends_at is null or s.ends_at>=now())
      );
  end if;

  insert into public.tgg_world_character_titles(character_id,title_key,unlocked_at)
  select p_character_id,t.title_key,now()
  from public.tgg_world_titles t
  where t.enabled=true
    and (
      (t.title_key='title-beat-architect' and v_active_career='producer' and v_active_career_level>=5) or
      (t.title_key='title-deal-maker' and v_active_career='manager' and v_contracts_completed>=10) or
      (t.title_key='title-night-controller' and v_active_career='dj' and v_night_events_completed>=10) or
      (t.title_key='title-rising-artist' and v_active_career='artist' and v_total_rep>=25) or
      (t.title_key='title-city-legend' and v_prestige>=3) or
      (t.title_key='title-business-mogul' and exists(
         select 1 from public.tgg_world_character_business_prestige bp
         join public.tgg_world_character_businesses b on b.id=bp.business_id
         where b.character_id=p_character_id and bp.prestige_level>=3
      )) or
      (t.title_key='title-crew-boss' and exists(
         select 1 from public.tgg_world_crew_progression cp
         join public.tgg_world_crew_members cm on cm.crew_id=cp.crew_id
         where cm.character_id=p_character_id and cm.left_at is null and cp.rank_level>=5
      ))
    )
  on conflict do nothing;

  insert into public.tgg_world_character_badges(character_id,badge_key,unlocked_at)
  select p_character_id,b.badge_key,now()
  from public.tgg_world_badges b
  where b.enabled=true
    and (
      (b.badge_key='badge-first-property' and v_properties>=1) or
      (b.badge_key='badge-first-business' and v_businesses>=1) or
      (b.badge_key='badge-district-dominant' and v_crew_dominant_territories>=1) or
      (b.badge_key='badge-tournament-winner' and v_tournament_wins>=1) or
      (b.badge_key='badge-rise-up' and exists(
        select 1 from public.tgg_world_character_season_progress sp
        where sp.character_id=p_character_id and sp.season_level>=5
      ))
    )
  on conflict do nothing;

  insert into public.tgg_world_character_collectibles(
    character_id,collectible_key,quantity,acquired_at,metadata
  )
  select p_character_id,c.collectible_key,1,now(),'{}'::jsonb
  from public.tgg_world_collectibles c
  where c.enabled=true
    and (
      (c.collectible_key='collect-mixtape-plaque' and v_total_rep>=100) or
      (c.collectible_key='collect-city-crown' and v_prestige>=3) or
      (c.collectible_key='collect-neon-sign' and exists(
        select 1
        from public.tgg_world_inventory i
        join public.tgg_world_shop_catalog s on s.item_key=i.item_key
        where i.character_id=p_character_id and i.quantity>0
          and lower(s.display_name)=lower('Studio Neon Sign')
      )) or
      (c.collectible_key='collect-red-chain' and exists(
        select 1
        from public.tgg_world_inventory i
        join public.tgg_world_shop_catalog s on s.item_key=i.item_key
        where i.character_id=p_character_id and i.quantity>0
          and lower(s.display_name)=lower('Red Chain')
      )) or
      (c.collectible_key='collect-nova-pass' and exists(
        select 1
        from public.tgg_world_character_event_state es
        join public.tgg_world_dynamic_events de on de.id=es.dynamic_event_id
        where es.character_id=p_character_id
          and es.status='completed'
          and de.event_key='event-nova-club-night'
      ))
    )
  on conflict(character_id,collectible_key) do nothing;

  insert into public.tgg_world_character_endgame(
    character_id,milestone_key,status,progress,completed_at,updated_at
  )
  select
    p_character_id,
    m.milestone_key,
    case
      when m.milestone_key='endgame-city-owner' and v_properties>=3 and v_businesses>=2 then 'completed'
      when m.milestone_key='endgame-district-power' and v_dominant_districts>=3 then 'completed'
      when m.milestone_key='endgame-industry-legend' and v_prestige>=3 and v_completed_story_arcs>=2 then 'completed'
      when m.milestone_key='endgame-city-icon' and v_total_influence>=1000 then 'completed'
      else 'active'
    end,
    jsonb_build_object(
      'properties',v_properties,'businesses',v_businesses,
      'reputation',v_total_rep,'prestige',v_prestige,
      'influence',v_total_influence,'vehicle_level',v_vehicle_level,
      'dominant_districts',v_dominant_districts
    ),
    case
      when (m.milestone_key='endgame-city-owner' and v_properties>=3 and v_businesses>=2)
        or (m.milestone_key='endgame-district-power' and v_dominant_districts>=3)
        or (m.milestone_key='endgame-industry-legend' and v_prestige>=3 and v_completed_story_arcs>=2)
        or (m.milestone_key='endgame-city-icon' and v_total_influence>=1000)
      then now() else null
    end,
    now()
  from public.tgg_world_endgame_milestones m
  where m.enabled=true
  on conflict(character_id,milestone_key) do update
  set status=excluded.status,
      progress=excluded.progress,
      completed_at=coalesce(public.tgg_world_character_endgame.completed_at,excluded.completed_at),
      updated_at=now();

  select count(*) into v_achievements
  from public.tgg_world_character_achievements
  where character_id=p_character_id and unlocked_at is not null;

  v_result:=jsonb_build_object(
    'reputation',v_total_rep,
    'properties',v_properties,
    'businesses',v_businesses,
    'achievements',v_achievements,
    'prestige',v_prestige,
    'influence',v_total_influence,
    'vehicle_level',v_vehicle_level,
    'dominant_districts',v_dominant_districts,
    'crew_dominant_territories',v_crew_dominant_territories,
    'contracts_completed',v_contracts_completed,
    'night_events_completed',v_night_events_completed,
    'tournament_wins',v_tournament_wins,
    'active_career',v_active_career,
    'active_career_level',v_active_career_level,
    'completed_story_arcs',v_completed_story_arcs,
    'season_xp_multiplier',v_season_multiplier,
    'new_achievement_season_xp',v_new_achievement_season_xp
  );
  return v_result;
end;
$function$


-- [40000000199] function private.tgg_reconcile_call_validation_activation_item()
CREATE OR REPLACE FUNCTION private.tgg_reconcile_call_validation_activation_item()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid;
  v_auth_users integer:=0;
  v_non_owner_auth integer:=0;
  v_call jsonb;
  v_validated boolean:=false;
  v_status text;
  v_next text;
  v_invite jsonb:='{}'::jsonb;
  v_runtime_version integer;
  v_runtime_checkpoint text;
begin
  select id
  into v_owner
  from auth.users
  where raw_app_meta_data->>'tgg_role'='owner'
  order by created_at
  limit 1;

  if v_owner is null then
    raise exception 'OWNER_NOT_FOUND';
  end if;

  perform set_config(
    'request.jwt.claims',
    jsonb_build_object(
      'sub',v_owner::text,
      'role','authenticated',
      'app_metadata',jsonb_build_object('tgg_role','owner')
    )::text,
    true
  );

  select count(*),count(*) filter(where id<>v_owner)
  into v_auth_users,v_non_owner_auth
  from auth.users;

  select
    nullif(m#>>'{runtime,edge_version}','')::integer,
    m#>>'{recovery,current_version_checkpoint}'
  into v_runtime_version,v_runtime_checkpoint
  from (select public.tgg_v5000_production_manifest() as m) q;

  v_call:=public.tgg_call_validation_final_health();
  v_validated:=coalesce((v_call->>'validated')::boolean,false);

  if not v_validated and v_non_owner_auth>0 then
    begin
      v_invite:=public.tgg_call_validation_invite_status();

      if not coalesce((v_invite->>'has_invite')::boolean,false)
         or coalesce(v_invite->>'status','')<>'pending'
         or nullif(v_invite->>'expires_at','') is null
         or (v_invite->>'expires_at')::timestamptz<=now()
      then
        v_invite:=private.tgg_call_validation_invite_create();
      end if;
    exception when others then
      v_invite:=jsonb_build_object(
        'ok',false,
        'error_code','CALL_VALIDATION_INVITE_RECONCILE_FAILED'
      );
    end;
  elsif v_non_owner_auth>0 then
    v_invite:=public.tgg_call_validation_invite_status();
  end if;

  v_status:=case
    when v_validated then 'complete'
    when v_non_owner_auth>0 then 'ready'
    else 'external_action'
  end;

  v_next:=case
    when v_validated then null
    when v_non_owner_auth>0 then
      'On a second device/account, open the pending Creator OS validation invite, sign in, claim it, then complete one real offer/answer exchange with the inviter device.'
    else
      'A second legitimate authenticated user/device must sign up first.'
  end;

  update private.tgg_one_final_activation_queue
  set
    status=v_status,
    next_action=v_next,
    evidence=coalesce(evidence,'{}'::jsonb)||jsonb_build_object(
      'auth_users',v_auth_users,
      'non_owner_auth_users',v_non_owner_auth,
      'validated',v_validated,
      'second_user_available',v_non_owner_auth>0,
      'artist_profile_required_for_claim',false,
      'invite_workflow_ready',true,
      'invite_prepared',coalesce((v_invite->>'has_invite')::boolean,false)
                        or coalesce((v_invite->>'ok')::boolean,false),
      'validation_invite_status',v_invite->>'status',
      'validation_invite_expires_at',v_invite->'expires_at',
      'second_user_claimed',coalesce((v_invite->>'second_user_claimed')::boolean,false),
      'creator_os_runtime_version',v_runtime_version,
      'creator_os_runtime_checkpoint',v_runtime_checkpoint,
      'reconciler_version','CALL-ACTIVATION-ONE-FINAL-1.2',
      'reconciled_at',now()
    ),
    last_checked_at=now(),
    completed_at=case
      when v_validated then coalesce(completed_at,now())
      else null
    end
  where item_key='second_call_user';

  return jsonb_build_object(
    'ok',true,
    'version','CALL-ACTIVATION-ONE-FINAL-1.2',
    'status',v_status,
    'auth_users',v_auth_users,
    'non_owner_auth_users',v_non_owner_auth,
    'validated',v_validated,
    'invite_prepared',
      coalesce((v_invite->>'has_invite')::boolean,false)
      or coalesce((v_invite->>'ok')::boolean,false),
    'runtime_version',v_runtime_version,
    'runtime_checkpoint',v_runtime_checkpoint,
    'generated_at',now()
  );
end
$function$


-- [40000000200] function private.tgg_reconcile_distribution_master_reuse_activation_item()
CREATE OR REPLACE FUNCTION private.tgg_reconcile_distribution_master_reuse_activation_item()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_caller uuid:=auth.uid();
  v_caller_role text;
  v_uid uuid;
  v_total integer:=0;
  v_unconfirmed integer:=0;
  v_groups jsonb:='[]'::jsonb;
begin
  if v_caller is not null then
    select raw_app_meta_data->>'tgg_role'
      into v_caller_role
    from auth.users
    where id=v_caller;

    if coalesce(v_caller_role,'')<>'owner' then
      raise exception 'OWNER_REQUIRED' using errcode='42501';
    end if;
  end if;

  select id into v_uid
  from auth.users
  where coalesce(raw_app_meta_data->>'tgg_role','')='owner'
  order by created_at asc
  limit 1;

  with owned_tracks as (
    select t.audio_path,m.id as release_id
    from public.tracks t
    join public.mixtapes m on m.id=t.mixtape_id
    join public.artists a on a.id=m.artist_id
    where a.user_id=v_uid
      and m.status='published'
      and nullif(btrim(coalesce(t.audio_path,'')),'') is not null
  ),
  dup as (
    select audio_path
    from owned_tracks
    group by audio_path
    having count(distinct release_id)>1
  )
  select
    count(*),
    count(*) filter(where not coalesce(c.confirmed_intentional,false)),
    coalesce(jsonb_agg(jsonb_build_object(
      'audio_path',d.audio_path,
      'confirmed_intentional',coalesce(c.confirmed_intentional,false)
    ) order by d.audio_path),'[]'::jsonb)
  into v_total,v_unconfirmed,v_groups
  from dup d
  left join private.tgg_distribution_master_reuse_confirmations c
    on c.owner_user_id=v_uid
   and c.audio_path=d.audio_path;

  update private.tgg_one_final_activation_queue
  set
    status=case when v_unconfirmed=0 then 'complete' else 'external_action' end,
    next_action=case
      when v_unconfirmed=0 then null
      else 'Confirm whether each shared master recording is intentionally reused across the listed published releases, or detach the incorrect reference.'
    end,
    evidence=coalesce(evidence,'{}'::jsonb)||jsonb_build_object(
      'master_reuse_groups',v_total,
      'unconfirmed_master_reuse_groups',v_unconfirmed,
      'groups',v_groups,
      'stored_media_unchanged',true
    ),
    last_checked_at=now(),
    completed_at=case when v_unconfirmed=0 then coalesce(completed_at,now()) else null end
  where item_key='distribution_master_assignment';

  return jsonb_build_object(
    'ok',true,
    'master_reuse_groups',v_total,
    'unconfirmed_master_reuse_groups',v_unconfirmed,
    'groups',v_groups,
    'generated_at',now()
  );
end
$function$


-- [40000000201] function private.tgg_reconcile_distribution_metadata_activation_item()
CREATE OR REPLACE FUNCTION private.tgg_reconcile_distribution_metadata_activation_item()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_caller uuid:=auth.uid();
  v_caller_role text;
  v_uid uuid;
  v_missing integer:=0;
  v_items jsonb:='[]'::jsonb;
  v_unconfirmed_master_groups integer:=0;
  v_creator_os_version integer:=0;
begin
  if v_caller is not null then
    select raw_app_meta_data->>'tgg_role'
      into v_caller_role
    from auth.users
    where id=v_caller;

    if coalesce(v_caller_role,'')<>'owner' then
      raise exception 'OWNER_REQUIRED' using errcode='42501';
    end if;
  end if;

  select id into v_uid
  from auth.users
  where coalesce(raw_app_meta_data->>'tgg_role','')='owner'
  order by created_at asc
  limit 1;

  if v_uid is null then
    raise exception 'OWNER_USER_NOT_FOUND';
  end if;

  select coalesce(nullif(m#>>'{runtime,edge_version}','')::integer,0)
  into v_creator_os_version
  from (select public.tgg_v5000_production_manifest() as m) q;

  if v_creator_os_version<=0 then
    v_creator_os_version:=coalesce((
      select (config->>'creator_os_runtime_version')::integer
      from public.tgg_master_shared_settings
      where setting_key='runtime_manifest' and is_published=true
      limit 1
    ),0);
  end if;

  with owned_tracks as (
    select t.audio_path,m.id as release_id
    from public.tracks t
    join public.mixtapes m on m.id=t.mixtape_id
    join public.artists a on a.id=m.artist_id
    where a.user_id=v_uid
      and m.status='published'
      and nullif(btrim(coalesce(t.audio_path,'')),'') is not null
  ),
  dup as (
    select audio_path
    from owned_tracks
    group by audio_path
    having count(distinct release_id)>1
  )
  select count(*)
  into v_unconfirmed_master_groups
  from dup d
  left join private.tgg_distribution_master_reuse_confirmations c
    on c.owner_user_id=v_uid
   and c.audio_path=d.audio_path
  where not coalesce(c.confirmed_intentional,false);

  with candidate as (
    select
      m.id,m.title,d.label_name,d.copyright_line,d.publishing_line,d.territories,
      coalesce(d.rights_confirmed,false) as rights_confirmed
    from public.mixtapes m
    join public.artists a on a.id=m.artist_id
    left join public.tgg_distribution_release_metadata d
      on d.release_id=m.id and d.owner_user_id=v_uid
    where a.user_id=v_uid
      and m.status='published'
      and exists (
        select 1 from public.tracks t
        where t.mixtape_id=m.id
          and (
            nullif(btrim(coalesce(t.audio_path,'')),'') is not null
            or nullif(btrim(coalesce(t.audio_url,'')),'') is not null
          )
      )
  ),
  missing as (
    select
      id,title,
      jsonb_strip_nulls(jsonb_build_object(
        'label_name_missing',case when nullif(btrim(coalesce(label_name,'')),'') is null then true end,
        'copyright_line_missing',case when nullif(btrim(coalesce(copyright_line,'')),'') is null then true end,
        'publishing_line_missing',case when nullif(btrim(coalesce(publishing_line,'')),'') is null then true end,
        'territories_missing',case when coalesce(jsonb_array_length(coalesce(territories,'[]'::jsonb)),0)=0 then true end,
        'distribution_rights_not_confirmed',case when not rights_confirmed then true end
      )) as missing_fields
    from candidate
    where
      nullif(btrim(coalesce(label_name,'')),'') is null
      or nullif(btrim(coalesce(copyright_line,'')),'') is null
      or nullif(btrim(coalesce(publishing_line,'')),'') is null
      or coalesce(jsonb_array_length(coalesce(territories,'[]'::jsonb)),0)=0
      or not rights_confirmed
  )
  select count(*),
         coalesce(jsonb_agg(jsonb_build_object(
           'release_id',id,'title',title,'missing_fields',missing_fields
         ) order by title),'[]'::jsonb)
  into v_missing,v_items
  from missing;

  update private.tgg_one_final_activation_queue
  set
    status=case
      when v_unconfirmed_master_groups>0 then 'waiting'
      when v_missing=0 then 'complete'
      else 'external_action'
    end,
    requirement='Complete real label, copyright, publishing, territories, and rights confirmation for each valid deliverable DSP candidate.',
    next_action=case
      when v_unconfirmed_master_groups>0 then 'Resolve the distribution master assignment review first.'
      when v_missing=0 then null
      else 'Rights holder must provide/confirm the real legal metadata for the listed release(s).'
    end,
    evidence=coalesce(evidence,'{}'::jsonb)||jsonb_build_object(
      'candidate_releases_missing_metadata',v_missing,
      'releases_missing_legal_metadata',v_items,
      'blocked_by_master_reuse_review',v_unconfirmed_master_groups>0,
      'unconfirmed_master_reuse_groups',v_unconfirmed_master_groups,
      'dependency_order_enforced',true,
      'direct_owned_release_table_audit',true,
      'creator_os_version',v_creator_os_version,
      'runtime_bookkeeping_refreshed_at',now()
    ),
    last_checked_at=now(),
    completed_at=case
      when v_unconfirmed_master_groups=0 and v_missing=0 then coalesce(completed_at,now())
      else null
    end
  where item_key='distribution_legal_metadata';

  return jsonb_build_object(
    'ok',true,
    'creator_os_version',v_creator_os_version,
    'candidate_releases_missing_metadata',v_missing,
    'releases_missing_legal_metadata',v_items,
    'blocked_by_master_reuse_review',v_unconfirmed_master_groups>0,
    'unconfirmed_master_reuse_groups',v_unconfirmed_master_groups,
    'generated_at',now()
  );
end
$function$


-- [40000000202] function private.tgg_reconcile_membership_activation_item()
CREATE OR REPLACE FUNCTION private.tgg_reconcile_membership_activation_item()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
  v_owner uuid;
  v_webhook_ready boolean:=false;
  v_payment_link_ready boolean:=false;
  v_active_tiers integer:=0;
  v_verified_tiers integer:=0;
  v_total_tiers integer:=0;
  v_status text;
  v_next_action text;
  v_tier_id uuid;
  v_product_id text;
  v_price_id text;
  v_payment_link_url text;
  v_payment_link_verified boolean:=false;
begin
  if v_uid is not null then
    select raw_app_meta_data->>'tgg_role'
    into v_role
    from auth.users
    where id=v_uid;

    if coalesce(v_role,'')<>'owner' then
      raise exception 'OWNER_REQUIRED' using errcode='42501';
    end if;
  end if;

  select id into v_owner
  from auth.users
  where coalesce(raw_app_meta_data->>'tgg_role','')='owner'
  order by created_at
  limit 1;

  select
    count(*),
    count(*) filter(where t.is_active),
    count(*) filter(where coalesce(t.stripe_payment_link_verified,false))
  into v_total_tiers,v_active_tiers,v_verified_tiers
  from public.tgg_membership_tiers t
  join public.artists a on a.id=t.artist_id
  where a.user_id=v_owner;

  select
    t.id,
    t.stripe_product_id,
    t.stripe_price_id,
    t.stripe_payment_link_url,
    coalesce(t.stripe_payment_link_verified,false)
  into
    v_tier_id,
    v_product_id,
    v_price_id,
    v_payment_link_url,
    v_payment_link_verified
  from public.tgg_membership_tiers t
  join public.artists a on a.id=t.artist_id
  where a.user_id=v_owner
  order by
    coalesce(t.stripe_payment_link_verified,false) desc,
    t.updated_at desc,
    t.created_at desc
  limit 1;

  select coalesce(enabled and endpoint_configured and mode='production',false)
  into v_webhook_ready
  from public.tgg_provider_runtime_config
  where provider_key='stripe.webhook';

  v_payment_link_ready :=
    v_tier_id is not null
    and v_payment_link_url is not null
    and v_product_id is not null
    and v_price_id is not null;

  v_status:=case
    when v_active_tiers>0 and v_verified_tiers>0 and v_webhook_ready then 'complete'
    when v_verified_tiers>0 and not v_webhook_ready then 'waiting'
    when v_verified_tiers>0 and v_webhook_ready then 'ready'
    else 'ready'
  end;

  v_next_action:=case
    when v_status='complete' then null
    when v_verified_tiers>0 and not v_webhook_ready then
      'Recurring Stripe product, monthly price, and Payment Link are verified. Store/verify the webhook signing secret in Creator OS → Activation Bridge, then activate the tier.'
    when v_verified_tiers>0 and v_webhook_ready then
      'Recurring Stripe billing is verified. Explicitly activate the paid tier.'
    else
      'Create and verify a recurring Stripe Payment Link for the draft tier.'
  end;

  update private.tgg_one_final_activation_queue
  set
    status=v_status,
    next_action=v_next_action,
    evidence=(
      coalesce(evidence,'{}'::jsonb)
      - 'stripe_product_id'
      - 'stripe_price_id'
      - 'stripe_payment_link_id'
      - 'stripe_payment_link_url'
      - 'stripe_live_products'
      - 'stripe_live_payment_links'
      - 'stripe_live_active_products'
      - 'stripe_live_active_payment_links'
      - 'stripe_live_recurring_prices'
      - 'stripe_membership_payment_links'
      - 'supabase_verified_payment_link_tiers'
      - 'webhook_ready'
    ) || jsonb_build_object(
      'total_tiers',v_total_tiers,
      'active_tiers',v_active_tiers,
      'verified_payment_link_tiers',v_verified_tiers,
      'membership_tier_id',v_tier_id,
      'stripe_product_id',v_product_id,
      'stripe_price_id',v_price_id,
      'stripe_payment_link_url',v_payment_link_url,
      'stripe_payment_link_verified',v_payment_link_verified,
      'webhook_ready',v_webhook_ready,
      'recurring_billing_objects_complete',v_payment_link_ready and v_verified_tiers>0,
      'stripe_webhook_runtime_ready',v_webhook_ready,
      'stripe_webhook_endpoint_ready',true,
      'stripe_webhook_pending_reason',case when v_webhook_ready then null else 'activation_bridge_webhook_secret_required' end,
      'membership_reconciler_source','current_owner_tier_source_of_truth',
      'membership_reconciler_fixed_at',now()
    ),
    last_checked_at=now(),
    completed_at=case when v_status='complete' then coalesce(completed_at,now()) else null end
  where item_key='membership_tier';

  return jsonb_build_object(
    'ok',true,
    'status',v_status,
    'total_tiers',v_total_tiers,
    'active_tiers',v_active_tiers,
    'verified_payment_link_tiers',v_verified_tiers,
    'webhook_ready',v_webhook_ready,
    'payment_link_ready',v_payment_link_ready,
    'tier_id',v_tier_id,
    'stripe_product_id',v_product_id,
    'stripe_price_id',v_price_id,
    'stripe_payment_link_url',v_payment_link_url,
    'next_action',v_next_action,
    'generated_at',now()
  );
end
$function$


-- [40000000203] function private.tgg_reconcile_v531_baseline_fields()
CREATE OR REPLACE FUNCTION private.tgg_reconcile_v531_baseline_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_active_routes integer:=0;
  v_published_releases integer:=0;
  v_published_products integer:=0;
  v_linked_products integer:=0;
  v_active_membership_tiers integer:=0;
  v_verified_membership_tiers integer:=0;
  v_native_stripe boolean:=false;
  v_payment_link boolean:=false;
  v_webhook boolean:=false;
  v_distribution boolean:=false;
begin
  if new.version<>'V531-FINAL' then
    return new;
  end if;

  select count(*) into v_active_routes
  from public.tgg_site_routes
  where is_active;

  select count(*) into v_published_releases
  from public.mixtapes
  where status='published'::public.mixtape_status;

  select
    count(*),
    count(*) filter(
      where stripe_payment_link_url ~ '^https://buy\.stripe\.com/'
    )
  into v_published_products,v_linked_products
  from public.merch_products
  where status='published';

  select
    count(*),
    count(*) filter(
      where stripe_payment_link_verified=true
    )
  into v_active_membership_tiers,v_verified_membership_tiers
  from public.tgg_membership_tiers
  where is_active=true;

  select coalesce(enabled,false)
    and mode='production'
    and coalesce(endpoint_configured,false)
  into v_native_stripe
  from public.tgg_provider_runtime_config
  where provider_key='stripe';

  select coalesce(enabled,false)
    and mode='production'
    and coalesce(endpoint_configured,false)
  into v_payment_link
  from public.tgg_provider_runtime_config
  where provider_key='stripe.payment_link';

  select coalesce(enabled,false)
    and mode='production'
    and coalesce(endpoint_configured,false)
  into v_webhook
  from public.tgg_provider_runtime_config
  where provider_key='stripe.webhook';

  select coalesce(enabled,false)
    and mode='production'
    and coalesce(endpoint_configured,false)
  into v_distribution
  from public.tgg_provider_runtime_config
  where provider_key='distribution.provider';

  new.public_routes:=v_active_routes;
  new.public_catalog_releases:=v_published_releases;

  new.payments_ready :=
    case
      when v_published_products=0 and v_active_membership_tiers=0 then true
      when coalesce(v_native_stripe,false) and coalesce(v_webhook,false) then true
      when coalesce(v_payment_link,false)
        and coalesce(v_webhook,false)
        and v_published_products=v_linked_products
        and v_active_membership_tiers=v_verified_membership_tiers then true
      else false
    end;

  new.distribution_ready:=coalesce(v_distribution,false);

  return new;
end
$function$


-- [40000000204] function private.tgg_record_merch_checkout_completed(p_checkout_session_id text, p_payment_intent_id text, p_product_id uuid, p_creator_id uuid, p_buyer_user_id uuid, p_quantity integer, p_amount_total bigint, p_currency text, p_customer_email text, p_shipping jsonb)
CREATE OR REPLACE FUNCTION private.tgg_record_merch_checkout_completed(p_checkout_session_id text, p_payment_intent_id text, p_product_id uuid, p_creator_id uuid, p_buyer_user_id uuid, p_quantity integer, p_amount_total bigint, p_currency text, p_customer_email text, p_shipping jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing uuid;
  v_product public.merch_products;
  v_reservation public.tgg_merch_checkout_reservations;
  v_order_id uuid;
  v_expected bigint;
  v_shipping jsonb:=coalesce(p_shipping,'{}'::jsonb);
begin
  if auth.role()<>'service_role' then
    raise exception 'service_role_required';
  end if;

  if nullif(btrim(coalesce(p_checkout_session_id,'')),'') is null then
    raise exception 'checkout_session_required';
  end if;
  if p_quantity is null or p_quantity<1 or p_quantity>10 then
    raise exception 'quantity_invalid';
  end if;
  if p_amount_total is null or p_amount_total<0 then
    raise exception 'amount_invalid';
  end if;
  if char_length(coalesce(p_currency,''))<>3 then
    raise exception 'currency_invalid';
  end if;
  if jsonb_typeof(v_shipping)<>'object' or octet_length(v_shipping::text)>16384 then
    raise exception 'shipping_invalid';
  end if;

  select id into v_existing
  from public.tgg_merch_orders
  where checkout_session_id=p_checkout_session_id;

  if v_existing is not null then
    return v_existing;
  end if;

  select *
  into v_product
  from public.merch_products
  where id=p_product_id
    and creator_id=p_creator_id
    and status='published'
  for update;

  if v_product.id is null then
    raise exception 'published_product_not_found';
  end if;

  v_expected := (v_product.price_cents::bigint * p_quantity::bigint);
  if v_expected<>p_amount_total then
    raise exception 'amount_mismatch';
  end if;
  if upper(v_product.currency)<>upper(p_currency) then
    raise exception 'currency_mismatch';
  end if;

  select *
  into v_reservation
  from public.tgg_merch_checkout_reservations
  where checkout_session_id=p_checkout_session_id
  order by created_at desc
  limit 1
  for update;

  if v_reservation.id is not null then
    if v_reservation.status in ('expired','released') then
      raise exception 'reservation_inactive';
    end if;
    if v_reservation.product_id<>p_product_id
       or v_reservation.creator_id<>p_creator_id
       or v_reservation.quantity<>p_quantity then
      raise exception 'reservation_mismatch';
    end if;

    if v_reservation.status='pending' then
      update public.tgg_merch_checkout_reservations
      set status='completed',
          completed_at=now(),
          updated_at=now()
      where id=v_reservation.id;
    end if;
  else
    -- Legacy pre-reservation checkout fallback.
    if v_product.inventory is not null then
      if v_product.inventory<p_quantity then
        raise exception 'inventory_insufficient';
      end if;

      update public.merch_products
      set inventory=inventory-p_quantity,
          updated_at=now()
      where id=v_product.id;
    end if;
  end if;

  insert into public.tgg_merch_orders(
    product_id,creator_id,buyer_user_id,
    checkout_session_id,payment_intent_id,
    quantity,amount_total,currency,
    customer_email,shipping,status
  )
  values(
    p_product_id,p_creator_id,p_buyer_user_id,
    p_checkout_session_id,
    nullif(btrim(coalesce(p_payment_intent_id,'')),''),
    p_quantity,p_amount_total,upper(p_currency),
    nullif(btrim(coalesce(p_customer_email,'')),''),
    v_shipping,'paid'
  )
  returning id into v_order_id;

  return v_order_id;
end
$function$


-- [40000000205] function private.tgg_record_merch_refund(p_event_id text, p_payment_intent_id text, p_charge_id text, p_amount_refunded bigint, p_currency text)
CREATE OR REPLACE FUNCTION private.tgg_record_merch_refund(p_event_id text, p_payment_intent_id text, p_charge_id text, p_amount_refunded bigint, p_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.tgg_merch_orders;
  v_new_amount bigint;
  v_new_status text;
begin
  if auth.role()<>'service_role' then
    raise exception 'service_role_required';
  end if;

  if nullif(btrim(coalesce(p_event_id,'')),'') is null then
    raise exception 'event_id_required';
  end if;

  if nullif(btrim(coalesce(p_payment_intent_id,'')),'') is null then
    return jsonb_build_object('handled',false,'reason','payment_intent_missing');
  end if;

  if p_amount_refunded is null or p_amount_refunded<0 then
    raise exception 'refund_amount_invalid';
  end if;

  select *
  into v_order
  from public.tgg_merch_orders
  where payment_intent_id=p_payment_intent_id
  order by created_at desc
  limit 1
  for update;

  if v_order.id is null then
    return jsonb_build_object(
      'handled',false,
      'reason','merch_order_not_found',
      'payment_intent_id',p_payment_intent_id
    );
  end if;

  if upper(v_order.currency)<>upper(coalesce(p_currency,'')) then
    raise exception 'refund_currency_mismatch';
  end if;

  v_new_amount:=least(
    v_order.amount_total,
    greatest(v_order.refunded_amount, p_amount_refunded)
  );

  v_new_status:=case
    when v_new_amount>=v_order.amount_total then 'refunded'
    when v_new_amount>0 then 'partially_refunded'
    else v_order.status
  end;

  update public.tgg_merch_orders
  set refunded_amount=v_new_amount,
      refunded_at=case
        when v_new_amount>0 then coalesce(refunded_at,now())
        else refunded_at
      end,
      stripe_charge_id=coalesce(
        nullif(btrim(coalesce(p_charge_id,'')),''),
        stripe_charge_id
      ),
      last_refund_event_id=p_event_id,
      status=v_new_status,
      updated_at=now()
  where id=v_order.id;

  return jsonb_build_object(
    'handled',true,
    'order_id',v_order.id,
    'status',v_new_status,
    'refunded_amount',v_new_amount,
    'amount_total',v_order.amount_total,
    'inventory_restocked',false
  );
end
$function$


-- [40000000206] function private.tgg_record_mixtape_download(p_mixtape_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_record_mixtape_download(p_mixtape_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count bigint;
begin
  update public.mixtapes
  set download_count=coalesce(download_count,0)+1
  where id=p_mixtape_id
    and status='published'::public.mixtape_status
  returning download_count into v_count;

  return v_count;
end;
$function$


-- [40000000207] function private.tgg_record_mixtape_metric(p_mixtape_id uuid, p_metric text, p_fingerprint text, p_resource_key text, p_bucket_seconds integer)
CREATE OR REPLACE FUNCTION private.tgg_record_mixtape_metric(p_mixtape_id uuid, p_metric text, p_fingerprint text, p_resource_key text, p_bucket_seconds integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_bucket timestamptz;
  v_inserted boolean:=false;
  v_count bigint;
begin
  if p_metric not in ('play','download')
     or coalesce(length(p_fingerprint),0)<32
     or coalesce(length(p_resource_key),0)=0
     or p_bucket_seconds<10
  then
    raise exception 'INVALID_MEDIA_METRIC_INPUT' using errcode='22023';
  end if;

  v_bucket:=to_timestamp(
    floor(extract(epoch from now())/p_bucket_seconds)*p_bucket_seconds
  );

  insert into private.tgg_media_metric_dedupe(
    fingerprint,metric,mixtape_id,resource_key,bucket_start
  )
  values(p_fingerprint,p_metric,p_mixtape_id,p_resource_key,v_bucket)
  on conflict do nothing;

  get diagnostics v_inserted = row_count;

  if v_inserted then
    if p_metric='play' then
      update public.mixtapes
      set play_count=coalesce(play_count,0)+1
      where id=p_mixtape_id
        and status='published'::public.mixtape_status
      returning play_count into v_count;
    else
      update public.mixtapes
      set download_count=coalesce(download_count,0)+1
      where id=p_mixtape_id
        and status='published'::public.mixtape_status
      returning download_count into v_count;
    end if;
  else
    select case when p_metric='play' then play_count else download_count end
    into v_count
    from public.mixtapes
    where id=p_mixtape_id;
  end if;

  return jsonb_build_object(
    'count',v_count,
    'counted',v_inserted,
    'metric',p_metric,
    'bucket_start',v_bucket
  );
end;
$function$


-- [40000000208] function private.tgg_record_mixtape_play(p_mixtape_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_record_mixtape_play(p_mixtape_id uuid)
