declare
  v_count bigint;
begin
  update public.mixtapes
  set play_count=coalesce(play_count,0)+1
  where id=p_mixtape_id
    and status='published'::public.mixtape_status
  returning play_count into v_count;

  return v_count;
end;
$function$


-- [40000000209] function private.tgg_record_public_mixtape_event(p_event_type text, p_mixtape_id uuid, p_session_id text, p_source text, p_metadata jsonb, p_visitor_hash text)
CREATE OR REPLACE FUNCTION private.tgg_record_public_mixtape_event(p_event_type text, p_mixtape_id uuid, p_session_id text DEFAULT NULL::text, p_source text DEFAULT 'blogger'::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_visitor_hash text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_creator uuid;
 v_id uuid;
 v_window interval;
 v_meta jsonb;
begin
 if p_event_type not in ('play','download','release_view','track_play','share') then
   raise exception 'unsupported event';
 end if;
 select m.artist_id into v_creator from public.mixtapes m where m.id=p_mixtape_id and m.status='published' limit 1;
 if v_creator is null then raise exception 'release unavailable'; end if;
 v_meta=case when p_metadata is null or jsonb_typeof(p_metadata)<>'object' then '{}'::jsonb else p_metadata end;
 if pg_column_size(v_meta)>4096 then raise exception 'metadata too large'; end if;
 v_window=case p_event_type when 'release_view' then interval '10 minutes' when 'play' then interval '30 seconds' when 'track_play' then interval '30 seconds' when 'download' then interval '5 minutes' when 'share' then interval '2 minutes' else interval '1 minute' end;
 if p_visitor_hash is not null and exists(
   select 1 from public.creator_analytics_events e
   where e.mixtape_id=p_mixtape_id and e.event_type=p_event_type and e.visitor_hash=p_visitor_hash and e.occurred_at>now()-v_window
 ) then return null; end if;
 insert into public.creator_analytics_events(creator_id,mixtape_id,event_type,session_id,source,metadata,occurred_at,visitor_hash)
 values(v_creator,p_mixtape_id,p_event_type,left(nullif(p_session_id,''),128),left(coalesce(nullif(p_source,''),'blogger'),64),v_meta,now(),p_visitor_hash)
 returning id into v_id;
 return v_id;
end;$function$


-- [40000000210] function private.tgg_record_release_status_change()
CREATE OR REPLACE FUNCTION private.tgg_record_release_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_type text;
  v_note text;
  v_user_id uuid;
begin
  if tg_table_name = 'mixtapes' then
    v_project_type := 'mixtape';
    v_note := new.admin_note;
    v_user_id := new.user_id;
  elsif tg_table_name = 'site_videos' then
    v_project_type := 'video';
    v_note := null;
    v_user_id := new.user_id;
  elsif tg_table_name = 'merch_products' then
    v_project_type := 'merch';
    v_note := new.admin_note;
    v_user_id := new.user_id;
  else
    raise exception 'unsupported release workflow table: %', tg_table_name;
  end if;

  if tg_op = 'INSERT' then
    insert into public.release_status_history(project_type, project_id, user_id, old_status, new_status, note, changed_by)
    values (v_project_type, new.id, v_user_id, null, coalesce(new.status::text, 'draft'), v_note, auth.uid());
  elsif new.status is distinct from old.status then
    insert into public.release_status_history(project_type, project_id, user_id, old_status, new_status, note, changed_by)
    values (v_project_type, new.id, v_user_id, old.status::text, coalesce(new.status::text, 'draft'), v_note, auth.uid());
  end if;
  return new;
end;
$function$


-- [40000000211] function private.tgg_record_stripe_webhook_event(p_event_id text, p_event_type text, p_livemode boolean, p_object_id text, p_checkout_session_id text, p_payment_intent_id text, p_amount bigint, p_currency text, p_handled_kind text, p_result jsonb)
CREATE OR REPLACE FUNCTION private.tgg_record_stripe_webhook_event(p_event_id text, p_event_type text, p_livemode boolean, p_object_id text, p_checkout_session_id text, p_payment_intent_id text, p_amount bigint, p_currency text, p_handled_kind text, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
begin
  if auth.role()<>'service_role' then
    raise exception 'service_role_required';
  end if;

  if nullif(btrim(coalesce(p_event_id,'')),'') is null then
    raise exception 'event_id_required';
  end if;

  if nullif(btrim(coalesce(p_event_type,'')),'') is null then
    raise exception 'event_type_required';
  end if;

  if octet_length(coalesce(p_result,'{}'::jsonb)::text)>16384 then
    raise exception 'event_result_too_large';
  end if;

  select id into v_id
  from public.tgg_stripe_webhook_events
  where stripe_event_id=p_event_id;

  if v_id is not null then
    return jsonb_build_object(
      'id',v_id,
      'duplicate',true
    );
  end if;

  insert into public.tgg_stripe_webhook_events(
    stripe_event_id,event_type,livemode,object_id,
    checkout_session_id,payment_intent_id,amount,currency,
    handled_kind,result
  )
  values(
    p_event_id,p_event_type,coalesce(p_livemode,true),
    nullif(btrim(coalesce(p_object_id,'')),''),
    nullif(btrim(coalesce(p_checkout_session_id,'')),''),
    nullif(btrim(coalesce(p_payment_intent_id,'')),''),
    p_amount,
    nullif(upper(btrim(coalesce(p_currency,''))),''),
    coalesce(nullif(btrim(coalesce(p_handled_kind,'')),''),'observed'),
    coalesce(p_result,'{}'::jsonb)
  )
  returning id into v_id;

  return jsonb_build_object(
    'id',v_id,
    'duplicate',false
  );
end
$function$


-- [40000000212] function private.tgg_recording_career_mission_trigger()
CREATE OR REPLACE FUNCTION private.tgg_recording_career_mission_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_char uuid;
  v_failed integer:=0;
begin
  if new.status='completed' and old.status is distinct from 'completed' then
    select id into v_char
    from public.world_characters
    where user_id=new.user_id and character_status='active'
    limit 1;

    if v_char is not null then
      select count(*) into v_failed
      from public.tgg_recording_takes
      where session_id=new.id
        and coalesce((metadata->>'failed')::boolean,false)=true;

      perform private.tgg_world_credit_career_mission_event(
        v_char,
        'recording_session_complete',
        'recording_session',
        new.id::text,
        jsonb_build_object('failed_takes',v_failed,'project_id',new.project_id)
      );
      perform private.tgg_world_credit_contract_event(
        v_char,
        'recording_session_complete',
        'recording_session',
        new.id::text,
        jsonb_build_object('failed_takes',v_failed,'project_id',new.project_id)
      );
    end if;
  end if;
  return new;
end;
$function$


-- [40000000213] function private.tgg_redeem_membership_payment_link_claim(p_client_reference_id text, p_checkout_session_id text, p_stripe_subscription_id text, p_stripe_customer_id text, p_customer_email text)
CREATE OR REPLACE FUNCTION private.tgg_redeem_membership_payment_link_claim(p_client_reference_id text, p_checkout_session_id text, p_stripe_subscription_id text, p_stripe_customer_id text, p_customer_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_claim_id uuid;
  v_claim record;
  v_membership_id uuid;
begin
  if coalesce(p_client_reference_id,'') !~ '^tggmem_[0-9a-fA-F_]{36}$' then
    return jsonb_build_object('handled',false,'reason','not_tgg_membership_claim');
  end if;

  begin
    v_claim_id:=replace(substr(p_client_reference_id,8),'_','-')::uuid;
  exception when others then
    return jsonb_build_object('handled',false,'reason','claim_reference_invalid');
  end;

  select *
  into v_claim
  from private.tgg_membership_payment_link_claims
  where claim_id=v_claim_id
  for update;

  if not found then
    return jsonb_build_object('handled',false,'reason','claim_not_found');
  end if;

  if v_claim.status='consumed' then
    select id into v_membership_id
    from public.tgg_memberships
    where artist_id=v_claim.artist_id
      and fan_user_id=v_claim.fan_user_id;

    return jsonb_build_object(
      'handled',true,
      'idempotent',true,
      'membership_id',v_membership_id,
      'claim_id',v_claim.claim_id
    );
  end if;

  if v_claim.status<>'pending' or v_claim.expires_at<=now() then
    if v_claim.status='pending' then
      update private.tgg_membership_payment_link_claims
      set status='expired'
      where claim_id=v_claim.claim_id;
    end if;
    return jsonb_build_object('handled',false,'reason','claim_not_active');
  end if;

  insert into public.tgg_memberships(
    tier_id,artist_id,fan_user_id,status,started_at,
    stripe_customer_id,stripe_subscription_id,cancel_at_period_end,
    created_at,updated_at
  )
  values(
    v_claim.tier_id,v_claim.artist_id,v_claim.fan_user_id,'active',now(),
    nullif(p_stripe_customer_id,''),nullif(p_stripe_subscription_id,''),false,
    now(),now()
  )
  on conflict(artist_id,fan_user_id) do update set
    tier_id=excluded.tier_id,
    status='active',
    started_at=coalesce(public.tgg_memberships.started_at,excluded.started_at),
    stripe_customer_id=coalesce(excluded.stripe_customer_id,public.tgg_memberships.stripe_customer_id),
    stripe_subscription_id=coalesce(excluded.stripe_subscription_id,public.tgg_memberships.stripe_subscription_id),
    cancel_at_period_end=false,
    updated_at=now()
  returning id into v_membership_id;

  update private.tgg_membership_payment_link_claims
  set
    status='consumed',
    checkout_session_id=nullif(p_checkout_session_id,''),
    stripe_subscription_id=nullif(p_stripe_subscription_id,''),
    consumed_at=now()
  where claim_id=v_claim.claim_id;

  return jsonb_build_object(
    'handled',true,
    'membership_id',v_membership_id,
    'claim_id',v_claim.claim_id,
    'tier_id',v_claim.tier_id,
    'artist_id',v_claim.artist_id,
    'fan_user_id',v_claim.fan_user_id,
    'customer_email',p_customer_email
  );
end
$function$


-- [40000000214] function private.tgg_referral_claim(p_code text)
CREATE OR REPLACE FUNCTION private.tgg_referral_claim(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_code text:=upper(btrim(coalesce(p_code,'')));
  v_ref public.tgg_referral_codes;
  v_claim public.tgg_referral_claims;
  v_actor uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;
  if v_code !~ '^[A-Z0-9]{8,16}$' then
    raise exception 'REFERRAL_CODE_INVALID' using errcode='22023';
  end if;

  if exists(select 1 from public.tgg_referral_claims where referred_user_id=v_uid) then
    select * into v_claim
    from public.tgg_referral_claims
    where referred_user_id=v_uid;

    return jsonb_build_object(
      'ok',true,
      'already_claimed',true,
      'referrer_user_id',v_claim.referrer_user_id,
      'claimed_at',v_claim.claimed_at
    );
  end if;

  select * into v_ref
  from public.tgg_referral_codes
  where code=v_code and is_active=true
  limit 1;

  if v_ref.id is null then
    raise exception 'REFERRAL_CODE_NOT_FOUND' using errcode='P0002';
  end if;
  if v_ref.owner_user_id=v_uid then
    raise exception 'SELF_REFERRAL_NOT_ALLOWED' using errcode='22023';
  end if;

  insert into public.tgg_referral_claims(
    referral_code_id,referrer_user_id,referred_user_id
  )
  values(v_ref.id,v_ref.owner_user_id,v_uid)
  returning * into v_claim;

  select id into v_actor
  from public.profiles
  where id=v_uid
  limit 1;

  if exists(select 1 from public.profiles where id=v_ref.owner_user_id) then
    insert into public.notifications(
      recipient_id,actor_id,notification_type,entity_type,entity_id,title,body
    )
    values(
      v_ref.owner_user_id,
      v_actor,
      'referral_claim',
      'referral',
      v_claim.id,
      'New referral joined',
      'Someone used your TRU GO GETTA referral code.'
    );
  end if;

  return jsonb_build_object(
    'ok',true,
    'already_claimed',false,
    'referrer_user_id',v_claim.referrer_user_id,
    'claimed_at',v_claim.claimed_at
  );
end
$function$


-- [40000000215] function private.tgg_referral_get_or_create()
CREATE OR REPLACE FUNCTION private.tgg_referral_get_or_create()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_row public.tgg_referral_codes;
  v_code text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select * into v_row
  from public.tgg_referral_codes
  where owner_user_id=v_uid and is_active=true
  order by created_at asc
  limit 1;

  if v_row.id is null then
    loop
      v_code:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
      begin
        insert into public.tgg_referral_codes(owner_user_id,code)
        values(v_uid,v_code)
        returning * into v_row;
        exit;
      exception when unique_violation then
        null;
      end;
    end loop;
  end if;

  return jsonb_build_object(
    'ok',true,
    'code',v_row.code,
    'created_at',v_row.created_at,
    'claim_count',(select count(*) from public.tgg_referral_claims c where c.referrer_user_id=v_uid)
  );
end
$function$


-- [40000000216] function private.tgg_refresh_blogger_activation_item()
CREATE OR REPLACE FUNCTION private.tgg_refresh_blogger_activation_item()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text;
  v_error text;
  v_revoked timestamptz;
  v_ready boolean:=false;
begin
  select status,last_error,revoked_at
  into v_status,v_error,v_revoked
  from public.v98_blogger_connections
  where blog_url='https://trugogettamixtapes.blogspot.com/'
  order by updated_at desc
  limit 1;

  v_ready :=
    v_status='connected'
    and v_revoked is null
    and coalesce(v_error,'') not ilike '%reauth_required%'
    and coalesce(v_error,'') not ilike '%invalid_grant%';

  insert into private.tgg_one_final_activation_queue(
    item_key,category,title,status,core_blocking,auto_detectable,
    requirement,next_action,evidence,last_checked_at,completed_at
  )
  values(
    'blogger_maintenance_oauth',
    'blogger',
    'Blogger maintenance OAuth',
    case when v_ready then 'complete' else 'external_action' end,
    false,
    true,
    'Maintain a valid Blogger OAuth refresh token for future page/theme maintenance writes.',
    case when v_ready then null else 'Reconnect Blogger OAuth to refresh the maintenance token. Live public Blogger runtime remains verified.' end,
    jsonb_build_object(
      'connection_status',v_status,
      'last_error',v_error,
      'revoked',v_revoked is not null,
      'live_runtime_blocking',false
    ),
    now(),
    case when v_ready then now() else null end
  )
  on conflict(item_key) do update set
    category=excluded.category,
    title=excluded.title,
    status=excluded.status,
    core_blocking=excluded.core_blocking,
    auto_detectable=excluded.auto_detectable,
    requirement=excluded.requirement,
    next_action=excluded.next_action,
    evidence=excluded.evidence,
    last_checked_at=excluded.last_checked_at,
    completed_at=case
      when excluded.status='complete'
      then coalesce(private.tgg_one_final_activation_queue.completed_at,excluded.completed_at)
      else null
    end;

  return jsonb_build_object(
    'ok',true,
    'item','blogger_maintenance_oauth',
    'complete',v_ready,
    'generated_at',now()
  );
end
$function$


-- [40000000217] function private.tgg_refresh_fan_intelligence(p_artist_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_refresh_fan_intelligence(p_artist_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_count integer := 0;
begin
  if v_user is null then raise exception 'Authentication required'; end if;

  if p_artist_id is not null and not exists (
    select 1 from public.artists a
    where a.id=p_artist_id and a.user_id=v_user
  ) then
    raise exception 'artist not owned';
  end if;

  delete from public.tgg_fan_intelligence_snapshots s
  where s.creator_user_id=v_user
    and (p_artist_id is null or s.artist_id=p_artist_id);

  insert into public.tgg_fan_intelligence_snapshots(
    creator_user_id,artist_id,fan_user_id,
    engagement_score,recency_score,loyalty_score,
    fan_state,recommended_action,last_seen_at,calculated_at
  )
  select
    v_user,
    fj.artist_id,
    fj.user_id,
    least(100,greatest(0,
      least(coalesce(fj.streams_count,0),40)
      + least(coalesce(fj.saves_count,0),10)*3
      + least(coalesce(fj.comments_count,0),10)*4
      + least(coalesce(fj.events_count,0),5)*5
      + least(coalesce(fj.rooms_count,0),5)*4
      + case when coalesce(fj.supporter,false) then 20 else 0 end
    ))::int,
    case
      when fj.last_seen_at is null then 0
      when fj.last_seen_at >= now()-interval '3 days' then 100
      when fj.last_seen_at >= now()-interval '7 days' then 85
      when fj.last_seen_at >= now()-interval '30 days' then 60
      when fj.last_seen_at >= now()-interval '90 days' then 30
      else 10
    end::int,
    least(100,greatest(0,
      case coalesce(fj.journey_stage,'listener')
        when 'supporter' then 100
        when 'superfan' then 90
        when 'regular' then 75
        when 'fan' then 55
        else 30
      end
      + case when coalesce(fj.supporter,false) then 10 else 0 end
    ))::int,
    case
      when coalesce(fj.supporter,false) then 'supporter'
      when coalesce(fj.journey_stage,'')='superfan' then 'superfan'
      when fj.last_seen_at is null or fj.last_seen_at<now()-interval '90 days' then 'dormant'
      when fj.last_seen_at<now()-interval '30 days' then 'slipping'
      when fj.first_seen_at>=now()-interval '14 days' then 'new'
      else 'active'
    end,
    case
      when coalesce(fj.supporter,false) then 'Reward loyalty with exclusive access or recognition.'
      when coalesce(fj.journey_stage,'')='superfan' then 'Invite to a private room, early listen, or street-team mission.'
      when fj.last_seen_at is null or fj.last_seen_at<now()-interval '90 days' then 'Run a low-frequency win-back touchpoint tied to a new release or event.'
      when fj.last_seen_at<now()-interval '30 days' then 'Re-engage with a targeted update, event invite, or personalized release recommendation.'
      when fj.first_seen_at>=now()-interval '14 days' then 'Welcome them and guide them toward saving, following, or joining a Circle.'
      else 'Keep nurturing with relevant releases, Rooms, and events.'
    end,
    fj.last_seen_at,
    now()
  from public.tgg_fan_journey fj
  join public.artists a on a.id=fj.artist_id
  where a.user_id=v_user
    and (p_artist_id is null or fj.artist_id=p_artist_id);

  get diagnostics v_count=row_count;
  return v_count;
end
$function$


-- [40000000218] function private.tgg_refresh_gigs()
CREATE OR REPLACE FUNCTION private.tgg_refresh_gigs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  r record;
  g record;
  n integer:=0;
  v_rep integer;
  v_inserted integer:=0;
  v_interval interval;
begin
  update public.tgg_world_character_gigs
  set status='expired',updated_at=now()
  where status in ('available','accepted')
    and expires_at is not null
    and expires_at<=now();

  for r in
    select id,active_career
    from public.world_characters
    where character_status='active'
  loop
    for g in
      select *
      from public.tgg_world_gig_templates
      where enabled=true
        and (cardinality(career_keys)=0 or r.active_career=any(career_keys))
      order by min_reputation,gig_key
    loop
      select coalesce(rep.reputation,0) into v_rep
      from public.tgg_world_career_reputation rep
      where rep.character_id=r.id
        and rep.career_key=r.active_career;

      v_interval:=case
        when g.recurrence_rule='daily' then interval '1 day'
        when g.recurrence_rule='weekly' then interval '7 days'
        else interval '1 day'
      end;

      if coalesce(v_rep,0)>=g.min_reputation
         and not exists(
           select 1
           from public.tgg_world_character_gigs cg
           where cg.character_id=r.id
             and cg.gig_key=g.gig_key
             and cg.status in ('available','accepted')
             and (cg.expires_at is null or cg.expires_at>now())
         )
         and not exists(
           select 1
           from public.tgg_world_character_gigs cg
           where cg.character_id=r.id
             and cg.gig_key=g.gig_key
             and greatest(
               cg.offered_at,
               coalesce(cg.completed_at,cg.offered_at)
             ) > now()-v_interval
         )
      then
        insert into public.tgg_world_character_gigs(
          character_id,gig_key,status,offered_at,expires_at,offer_context,updated_at
        )
        values(
          r.id,g.gig_key,'available',now(),now()+v_interval,
          jsonb_build_object(
            'generated_by','gig-refresh',
            'recurrence_rule',g.recurrence_rule,
            'recurrence_interval_seconds',extract(epoch from v_interval)::integer
          ),
          now()
        )
        on conflict do nothing;

        get diagnostics v_inserted=row_count;
        n:=n+v_inserted;
      end if;
    end loop;
  end loop;

  perform private.tgg_worker_mark(
    'gig-refresh','ok',
    jsonb_build_object(
      'generated',n,
      'recurrence_enforced',true,
      'expired_open_rows_closed',true
    )
  );
  return n;
exception when others then
  perform private.tgg_worker_mark(
    'gig-refresh','error',
    jsonb_build_object('error',sqlerrm)
  );
  raise;
end;
$function$


-- [40000000219] function private.tgg_refresh_live_reaction_count(p_stream_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_refresh_live_reaction_count(p_stream_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  insert into public.public_live_reaction_counts_v1(
    stream_id,fire,heart,clap,hundred,total,updated_at
  )
  select
    p_stream_id,
    count(*) filter(where reaction_type='fire')::bigint,
    count(*) filter(where reaction_type='heart')::bigint,
    count(*) filter(where reaction_type='clap')::bigint,
    count(*) filter(where reaction_type='100')::bigint,
    count(*)::bigint,
    now()
  from public.live_reactions
  where stream_id=p_stream_id
  on conflict(stream_id) do update
  set fire=excluded.fire,
      heart=excluded.heart,
      clap=excluded.clap,
      hundred=excluded.hundred,
      total=excluded.total,
      updated_at=excluded.updated_at;
$function$


-- [40000000220] function private.tgg_refresh_migration_hygiene_runtime_inventory()
CREATE OR REPLACE FUNCTION private.tgg_refresh_migration_hygiene_runtime_inventory()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version integer;
  v_checkpoint text;
  v_latest_migration_version text;
  v_latest_migration_name text;
  v_versions jsonb;
  v_changes jsonb;
  v_already_tracked boolean:=false;
begin
  select
    nullif(m#>>'{runtime,edge_version}','')::integer,
    m#>>'{recovery,current_version_checkpoint}'
  into v_version,v_checkpoint
  from (select public.tgg_v5000_production_manifest() as m) q;

  if v_version is null then
    return jsonb_build_object('ok',false,'error','creator_os_runtime_version_missing');
  end if;

  select version,name
  into v_latest_migration_version,v_latest_migration_name
  from supabase_migrations.schema_migrations
  order by version desc
  limit 1;

  select
    coalesce(details->'edge_runtime_versions','[]'::jsonb),
    coalesce(details->'edge_runtime_changes','[]'::jsonb)
  into v_versions,v_changes
  from public.tgg_operational_recovery_checkpoints
  where checkpoint_key='migration_hygiene_live'
  limit 1;

  if v_versions is null then
    raise exception 'MIGRATION_HYGIENE_CHECKPOINT_MISSING';
  end if;

  select exists(
    select 1
    from jsonb_array_elements_text(v_versions) x
    where x::integer=v_version
  )
  into v_already_tracked;

  if not v_already_tracked then
    v_versions:=v_versions || to_jsonb(v_version);
    v_changes:=v_changes || jsonb_build_array(
      'Creator OS v'||v_version::text||' runtime deployment (auto-recorded)'
    );
  end if;

  update public.tgg_operational_recovery_checkpoints
  set details=details || jsonb_build_object(
    'creator_os_version',v_version,
    'creator_os_checkpoint',coalesce(v_checkpoint,'creator_os_v5000_v'||v_version::text),
    'edge_runtime_versions',v_versions,
    'edge_runtime_changes',v_changes,
    'edge_runtime_change_count',jsonb_array_length(v_changes),
    'last_recorded_migration_version',v_latest_migration_version,
    'last_recorded_migration_name',v_latest_migration_name,
    'runtime_inventory_auto_refresh',true,
    'runtime_inventory_refreshed_at',now()
  )
  where checkpoint_key='migration_hygiene_live';

  return jsonb_build_object(
    'ok',true,
    'creator_os_version',v_version,
    'creator_os_checkpoint',v_checkpoint,
    'already_tracked',v_already_tracked,
    'edge_runtime_change_count',jsonb_array_length(v_changes),
    'latest_migration_version',v_latest_migration_version,
    'latest_migration_name',v_latest_migration_name,
    'refreshed_at',now()
  );
end
$function$


-- [40000000221] function private.tgg_refresh_one_final_activation_queue()
CREATE OR REPLACE FUNCTION private.tgg_refresh_one_final_activation_queue()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_artist_id uuid;
  v_content jsonb;
  v_membership jsonb;
  v_call jsonb;
  v_dist boolean:=false;
  v_broadcast boolean:=false;
  v_webhook boolean:=false;
  v_meta_missing integer:=0;
  v_master_reuse integer:=0;
  v_total_tiers integer:=0;
  v_active_tiers integer:=0;
  v_verified_tiers integer:=0;
  v_second_user boolean:=false;
  v_rows integer:=0;
begin
  select id
  into v_uid
  from auth.users
  where raw_app_meta_data->>'tgg_role'='owner'
  order by created_at
  limit 1;

  if v_uid is null then
    raise exception 'OWNER_NOT_FOUND';
  end if;

  select id
  into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  perform set_config('request.jwt.claim.sub',v_uid::text,true);

  v_content:=public.tgg_content_readiness_final_health();
  v_membership:=public.tgg_membership_checkout_final_health();
  v_call:=public.tgg_call_validation_final_health();

  v_meta_missing:=coalesce(
    (v_content->'summary'->>'candidate_releases_missing_distribution_metadata')::integer,
    0
  );
  v_master_reuse:=coalesce(
    (v_content->'summary'->>'master_reuse_review_releases')::integer,
    0
  );

  select count(*)
  into v_total_tiers
  from public.tgg_membership_tiers
  where artist_id=v_artist_id;

  v_active_tiers:=coalesce((v_membership->>'active_tier_count')::integer,0);
  v_verified_tiers:=coalesce((v_membership->>'verified_payment_link_tier_count')::integer,0);

  select coalesce(enabled,false)
         and mode='production'
         and coalesce(endpoint_configured,false)
  into v_dist
  from public.tgg_provider_runtime_config
  where provider_key='distribution.provider';

  select coalesce(enabled,false)
         and mode='production'
         and coalesce(endpoint_configured,false)
  into v_broadcast
  from public.tgg_provider_runtime_config
  where provider_key='broadcast.sfu_turn';

  select coalesce(enabled,false)
         and mode='production'
         and coalesce(endpoint_configured,false)
  into v_webhook
  from public.tgg_provider_runtime_config
  where provider_key='stripe.webhook';

  select exists(
    select 1 from auth.users where id<>v_uid
  ) into v_second_user;

  insert into private.tgg_one_final_activation_queue(
    item_key,category,title,status,core_blocking,auto_detectable,
    requirement,next_action,evidence,last_checked_at,completed_at
  )
  values
  (
    'distribution_master_assignment','distribution','Distribution master assignment review',
    case when v_master_reuse=0 then 'complete' else 'external_action' end,
    false,true,
    'Each published DSP release must have reviewed master-audio assignment, including intentional shared-master reuse where applicable.',
    case
      when v_master_reuse=0 then null
      else 'Review and confirm or correct the unresolved shared-master assignment before DSP delivery.'
    end,
    jsonb_build_object(
      'master_reuse_review_releases',v_master_reuse,
      'stored_media_unchanged',true,
      'distribution_submission_blocked_until_resolved',v_master_reuse>0,
      'base_refresh_version','ACTIVATION-QUEUE-BASE-1.5'
    ),
    now(),case when v_master_reuse=0 then now() else null end
  ),
  (
    'distribution_legal_metadata','distribution','Distribution legal metadata',
    case
      when v_master_reuse>0 then 'waiting'
      when v_meta_missing=0 then 'complete'
      else 'external_action'
    end,
    false,true,
    'Complete real label, copyright, publishing, territories, and rights confirmation for each valid deliverable DSP candidate.',
    case
      when v_master_reuse>0 then 'Resolve the master-assignment review first.'
      when v_meta_missing=0 then null
      else 'Rights holder must provide/confirm the real legal metadata.'
    end,
    jsonb_build_object(
      'candidate_releases_missing_metadata',v_meta_missing,
      'blocked_by_master_reuse_review',v_master_reuse>0,
      'base_refresh_version','ACTIVATION-QUEUE-BASE-1.5'
    ),
    now(),case when v_master_reuse=0 and v_meta_missing=0 then now() else null end
  ),
  (
    'distribution_provider','distribution','Production DSP provider',
    case when v_dist then 'complete' else 'external_action' end,
    false,true,
    'Connect a production distribution endpoint with server-side authentication.',
    case when v_dist then null else 'Provide a real DSP/distributor endpoint and server-side credentials.' end,
    jsonb_build_object(
      'provider_connected',v_dist,
      'adapter_contract_ready',true,
      'package_builder_ready',true,
      'base_refresh_version','ACTIVATION-QUEUE-BASE-1.5'
    ),
    now(),case when v_dist then now() else null end
  ),
  (
    'membership_tier','memberships','Paid membership tier',
    case
      when v_active_tiers>0 and v_verified_tiers>0 and v_webhook then 'complete'
      when v_verified_tiers>0 and not v_webhook then 'waiting'
      when v_total_tiers>0 then 'ready'
      else 'external_action'
    end,
    false,true,
    'Create a real paid tier and attach a server-verified recurring Stripe Payment Link.',
    case
      when v_total_tiers=0 then 'Choose real tier name, monthly price, and benefits.'
      when v_verified_tiers=0 then 'Create and server-verify the recurring Stripe Payment Link.'
      when not v_webhook then 'Restore the Stripe webhook signing secret/runtime, then activate the verified tier.'
      when v_active_tiers=0 then 'Activate the verified paid tier.'
      else null
    end,
    jsonb_build_object(
      'total_tiers',v_total_tiers,
      'active_tiers',v_active_tiers,
      'verified_payment_link_tiers',v_verified_tiers,
      'owner_platform_settlement_ready',coalesce((v_membership->>'creator_payout_ready')::boolean,false),
      'webhook_ready',v_webhook,
      'base_refresh_version','ACTIVATION-QUEUE-BASE-1.5'
    ),
    now(),case when v_active_tiers>0 and v_verified_tiers>0 and v_webhook then now() else null end
  ),
  (
    'sfu_turn_provider','live','Scalable Live SFU/TURN',
    case when v_broadcast then 'complete' else 'external_action' end,
    false,true,
    'Connect LiveKit-compatible or equivalent SFU/TURN infrastructure.',
    case when v_broadcast then null else 'Provide a real SFU/TURN service URL and server-side API credentials.' end,
    jsonb_build_object(
      'provider_connected',v_broadcast,
      'adapter_contract_ready',true,
      'control_plane_ready',true,
      'base_refresh_version','ACTIVATION-QUEUE-BASE-1.5'
    ),
    now(),case when v_broadcast then now() else null end
  ),
  (
    'second_call_user','calls','Two-user call validation',
    case
      when coalesce((v_call->>'validated')::boolean,false) then 'complete'
      when v_second_user then 'ready'
      else 'external_action'
    end,
    false,true,
    'Validate one real two-user call with offer and answer signaling.',
    case
      when coalesce((v_call->>'validated')::boolean,false) then null
      when v_second_user then 'Use the existing second authenticated account/device to claim the validation invite and complete one real offer-answer exchange.'
      else 'A second legitimate authenticated user/device must sign up first.'
    end,
    jsonb_build_object(
      'second_user_available',v_second_user,
      'artist_profile_required_for_claim',false,
      'validated',coalesce((v_call->>'validated')::boolean,false),
      'invite_workflow_ready',true,
      'base_refresh_version','ACTIVATION-QUEUE-BASE-1.5'
    ),
    now(),case when coalesce((v_call->>'validated')::boolean,false) then now() else null end
  ),
  (
    'supabase_leaked_password_protection','hosted_supabase','Leaked-password protection',
    'external_action',
    false,false,
    'Enable Supabase Auth leaked-password protection in hosted project settings.',
    'Requires hosted Supabase account/Management API control.',
    jsonb_build_object(
      'sql_auto_detectable',false,
      'security_advisor_warning','auth_leaked_password_protection',
      'base_refresh_version','ACTIVATION-QUEUE-BASE-1.5'
    ),
    now(),null
  ),
  (
    'edge_physical_cleanup','hosted_supabase','Physical retired Edge cleanup',
    'external_action',
    false,false,
    'Physically delete retired Edge Functions.',
    'Requires Supabase Management API delete privilege.',
    jsonb_build_object(
      'physical_function_count',100,
      'runtime_risk_blocking',false,
      'base_refresh_version','ACTIVATION-QUEUE-BASE-1.5'
    ),
    now(),null
  )
  on conflict(item_key) do update set
    category=excluded.category,
    title=excluded.title,
    status=excluded.status,
    core_blocking=excluded.core_blocking,
    auto_detectable=excluded.auto_detectable,
    requirement=excluded.requirement,
    next_action=excluded.next_action,
    evidence=coalesce(private.tgg_one_final_activation_queue.evidence,'{}'::jsonb)||excluded.evidence,
    last_checked_at=excluded.last_checked_at,
    completed_at=case
      when excluded.status='complete'
        then coalesce(private.tgg_one_final_activation_queue.completed_at,excluded.completed_at)
      else null
    end;

  get diagnostics v_rows=row_count;

  return jsonb_build_object(
    'ok',true,
    'version','ACTIVATION-QUEUE-BASE-1.5',
    'rows_refreshed',v_rows,
    'core_blockers',(
      select count(*) from private.tgg_one_final_activation_queue
      where core_blocking and status<>'complete'
    ),
    'remaining',(
      select count(*) from private.tgg_one_final_activation_queue
      where status<>'complete'
    ),
    'ready',(
      select count(*) from private.tgg_one_final_activation_queue
      where status='ready'
    ),
    'complete',(
      select count(*) from private.tgg_one_final_activation_queue
      where status='complete'
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000222] function private.tgg_refresh_one_final_activation_queue_all()
CREATE OR REPLACE FUNCTION private.tgg_refresh_one_final_activation_queue_all()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_core jsonb;
  v_blogger jsonb;
  v_staging jsonb;
  v_distribution_metadata jsonb;
  v_master_reuse jsonb;
  v_membership jsonb;
  v_calls jsonb;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('tgg_activation_queue_refresh',0)
  );

  v_core:=private.tgg_refresh_one_final_activation_queue();
  v_distribution_metadata:=private.tgg_reconcile_distribution_metadata_activation_item();
  v_master_reuse:=private.tgg_reconcile_distribution_master_reuse_activation_item();
  v_membership:=private.tgg_reconcile_membership_activation_item();
  v_calls:=private.tgg_reconcile_call_validation_activation_item();
  v_blogger:=private.tgg_refresh_blogger_activation_item();
  v_staging:=private.tgg_apply_provider_staging_to_activation_queue();

  return jsonb_build_object(
    'ok',true,
    'version','ACTIVATION-QUEUE-ONE-FINAL-1.8',
    'serialization','pg_advisory_xact_lock',
    'core',v_core,
    'distribution_metadata',v_distribution_metadata,
    'distribution_master_reuse',v_master_reuse,
    'membership',v_membership,
    'calls',v_calls,
    'blogger',v_blogger,
    'provider_staging',v_staging,
    'remaining',(select count(*) from private.tgg_one_final_activation_queue where status<>'complete'),
    'waiting',(select count(*) from private.tgg_one_final_activation_queue where status='waiting'),
    'external_actions',(select count(*) from private.tgg_one_final_activation_queue where status='external_action'),
    'ready',(select count(*) from private.tgg_one_final_activation_queue where status='ready'),
    'complete',(select count(*) from private.tgg_one_final_activation_queue where status='complete'),
    'generated_at',now()
  );
end;
$function$


-- [40000000223] function private.tgg_refresh_player_loop(p_character_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_refresh_player_loop(p_character_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_gigs integer:=0;
  v_challenges integer:=0;
  v_events integer:=0;
begin
  perform private.tgg_schedule_dynamic_events();
  perform private.tgg_refresh_gigs();
  v_challenges:=private.tgg_rotate_challenges(p_character_id);
  v_events:=private.tgg_discover_dynamic_events(p_character_id);

  select count(*) into v_gigs
  from public.tgg_world_character_gigs
  where character_id=p_character_id
    and status in ('available','accepted')
    and (expires_at is null or expires_at>now());

  return jsonb_build_object(
    'gigs_open',v_gigs,
    'new_challenges',v_challenges,
    'new_events',v_events
  );
end;
$function$


-- [40000000224] function private.tgg_refresh_public_artist_follow_count(p_artist_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_refresh_public_artist_follow_count(p_artist_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_artist_id is null then return; end if;

  insert into public.public_artist_follow_counts_v1(artist_id,followers,updated_at)
  select
    p_artist_id,
    (select count(*) from public.artist_follows f where f.artist_id=p_artist_id),
    now()
  where exists (select 1 from public.artists a where a.id=p_artist_id)
  on conflict (artist_id) do update
  set followers=excluded.followers,
      updated_at=now();
end
$function$


