-- [40000000230] function private.tgg_refresh_runtime_integrity_state_v1()
CREATE OR REPLACE FUNCTION private.tgg_refresh_runtime_integrity_state_v1()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manifest jsonb;
  v_edge_version integer;
  v_fingerprint text;
  v_checkpoint text;
  v_checkpoint_state text;
begin
  v_manifest:=public.tgg_v5000_production_manifest();

  v_edge_version:=nullif(v_manifest#>>'{runtime,edge_version}','')::integer;
  v_fingerprint:=nullif(v_manifest#>>'{runtime,edge_sha256}','');
  v_checkpoint:=nullif(v_manifest#>>'{recovery,current_version_checkpoint}','');
  v_checkpoint_state:=coalesce(nullif(v_manifest#>>'{recovery,checkpoint_state}',''),'ready');

  if v_edge_version is null or v_fingerprint is null or v_checkpoint is null then
    return;
  end if;

  insert into public.tgg_runtime_integrity_state_v1(
    id,live_state,live_fingerprint,live_edge_version,
    current_checkpoint,versioned_state,versioned_fingerprint,updated_at
  )
  values(
    1,
    v_checkpoint_state,
    v_fingerprint,
    v_edge_version,
    v_checkpoint,
    v_checkpoint_state,
    v_fingerprint,
    now()
  )
  on conflict(id) do update
  set live_state=excluded.live_state,
      live_fingerprint=excluded.live_fingerprint,
      live_edge_version=excluded.live_edge_version,
      current_checkpoint=excluded.current_checkpoint,
      versioned_state=excluded.versioned_state,
      versioned_fingerprint=excluded.versioned_fingerprint,
      updated_at=excluded.updated_at;
end
$function$


-- [40000000231] function private.tgg_refresh_supporter_health()
CREATE OR REPLACE FUNCTION private.tgg_refresh_supporter_health()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_count integer:=0;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  insert into public.tgg_supporter_health_snapshots(
    creator_user_id,artist_id,fan_user_id,membership_id,
    health_score,supporter_state,lifetime_support_cents,current_tier_id,
    current_period_end,recommended_action,calculated_at
  )
  select
    v_uid,m.artist_id,m.fan_user_id,m.id,
    greatest(0,least(100,
      case when m.status='active' then 55 when m.status in ('canceled','cancelled') then 10 else 25 end
      + case when coalesce(m.cancel_at_period_end,false) then -25 else 10 end
      + case when m.started_at<now()-interval '90 days' then 15 else 5 end
      + case when coalesce(fi.loyalty_score,0)>=70 then 10 else 0 end
    )),
    case
      when m.status not in ('active','trialing') then 'churned'
      when coalesce(m.cancel_at_period_end,false)
        or (m.current_period_end is not null and m.current_period_end<now()+interval '10 days') then 'at_risk'
      when m.started_at>now()-interval '30 days' then 'new'
      when m.started_at<now()-interval '180 days' then 'loyal'
      else 'active'
    end,
    coalesce(st.total_cents,0),
    m.tier_id,m.current_period_end,
    case
      when m.status not in ('active','trialing') then 'Invite back with a relevant new release or supporter benefit.'
      when coalesce(m.cancel_at_period_end,false) then 'Review cancellation risk and offer a meaningful retention touchpoint.'
      when m.started_at>now()-interval '30 days' then 'Welcome this new supporter and show them their member benefits.'
      when m.started_at<now()-interval '180 days' then 'Recognize this loyal supporter with an exclusive thank-you or early access.'
      else 'Keep this supporter engaged with regular member-only value.'
    end,
    now()
  from public.tgg_memberships m
  join public.artists a on a.id=m.artist_id and a.user_id=v_uid
  left join public.tgg_fan_intelligence_snapshots fi
    on fi.creator_user_id=v_uid
   and fi.artist_id=m.artist_id
   and fi.fan_user_id=m.fan_user_id
  left join lateral (
    select sum(s.amount_cents)::bigint total_cents
    from public.tgg_support_transactions s
    where s.artist_id=m.artist_id
      and s.fan_user_id=m.fan_user_id
      and s.status in ('paid','succeeded','complete','completed')
  ) st on true
  on conflict (creator_user_id,artist_id,fan_user_id)
  do update set
    membership_id=excluded.membership_id,
    health_score=excluded.health_score,
    supporter_state=excluded.supporter_state,
    lifetime_support_cents=excluded.lifetime_support_cents,
    current_tier_id=excluded.current_tier_id,
    current_period_end=excluded.current_period_end,
    recommended_action=excluded.recommended_action,
    calculated_at=now();

  get diagnostics v_count=row_count;
  return v_count;
end
$function$


-- [40000000232] function private.tgg_register_tournament(p_character_id uuid, p_tournament_key text, p_crew_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_register_tournament(p_character_id uuid, p_tournament_key text, p_crew_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_t public.tgg_world_tournaments%rowtype;
  v_rep integer:=0;
  v_existing public.tgg_world_tournament_entries%rowtype;
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select * into v_char from public.world_characters
  where id=p_character_id and user_id=v_uid and character_status='active';
  if v_char.id is null then raise exception 'character ownership mismatch'; end if;

  select * into v_t from public.tgg_world_tournaments
  where tournament_key=p_tournament_key and enabled=true;
  if v_t.tournament_key is null then raise exception 'tournament unavailable'; end if;

  select coalesce(max(reputation),0) into v_rep
  from public.tgg_world_career_reputation where character_id=p_character_id;

  if v_t.entry_conditions ? 'career'
     and coalesce(v_t.entry_conditions->>'career','')<>coalesce(v_char.active_career,'') then
    raise exception 'career requirement not met';
  end if;

  if v_t.entry_conditions ? 'reputation_gte'
     and v_rep<coalesce((v_t.entry_conditions->>'reputation_gte')::integer,0) then
    raise exception 'reputation requirement not met';
  end if;

  if coalesce((v_t.entry_conditions->>'crew_required')::boolean,false) then
    if p_crew_id is null then raise exception 'crew required'; end if;
  end if;

  if p_crew_id is not null and not exists(
    select 1 from public.tgg_world_crew_members m
    where m.crew_id=p_crew_id and m.character_id=p_character_id and m.left_at is null
  ) then
    raise exception 'crew membership required';
  end if;

  select * into v_existing
  from public.tgg_world_tournament_entries
  where tournament_key=p_tournament_key and character_id=p_character_id
  for update;

  if found and v_existing.status='completed'
     and v_existing.updated_at>now()-make_interval(mins=>v_t.cooldown_minutes) then
    raise exception 'tournament cooldown active';
  end if;

  insert into public.tgg_world_tournament_entries(
    tournament_key,character_id,crew_id,status,score,placement,result,registered_at,updated_at
  )
  values(p_tournament_key,p_character_id,p_crew_id,'registered',0,null,'{}'::jsonb,now(),now())
  on conflict(tournament_key,character_id) do update
    set crew_id=excluded.crew_id,status='registered',score=0,placement=null,result='{}'::jsonb,
        registered_at=now(),updated_at=now()
  returning id into v_id;

  return v_id;
end;
$function$


-- [40000000233] function private.tgg_release_download_policy_consistency_check()
CREATE OR REPLACE FUNCTION private.tgg_release_download_policy_consistency_check()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with mismatches as (
    select
      m.id release_id,
      m.title release_title,
      m.download_access,
      m.allow_track_downloads,
      t.id track_id,
      t.title track_title,
      t.download_policy
    from public.mixtapes m
    join public.tracks t on t.mixtape_id=m.id
    where m.status='published'::public.mixtape_status
      and m.download_access='anyone'
      and m.allow_track_downloads=true
      and coalesce(t.has_secure_audio,false)=true
      and nullif(btrim(t.audio_path),'') is not null
      and t.download_policy<>'public'
  )
  select jsonb_build_object(
    'ok',not exists(select 1 from mismatches),
    'version','DOWNLOAD-POLICY-CONSISTENCY-1.0',
    'mismatch_count',(select count(*) from mismatches),
    'mismatches',coalesce((select jsonb_agg(to_jsonb(m) order by release_title,track_title) from mismatches m),'[]'::jsonb),
    'rule','published release with download_access=anyone and allow_track_downloads=true must expose secure tracks with download_policy=public',
    'checked_at',now()
  );
$function$


-- [40000000234] function private.tgg_release_merch_checkout_reservation(p_request_id uuid, p_checkout_session_id text, p_reason text)
CREATE OR REPLACE FUNCTION private.tgg_release_merch_checkout_reservation(p_request_id uuid, p_checkout_session_id text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.tgg_merch_checkout_reservations;
begin
  if auth.role()<>'service_role' then
    raise exception 'service_role_required';
  end if;

  select * into v
  from public.tgg_merch_checkout_reservations
  where (
    (p_request_id is not null and request_id=p_request_id)
    or (
      nullif(btrim(coalesce(p_checkout_session_id,'')),'') is not null
      and checkout_session_id=p_checkout_session_id
    )
  )
  order by created_at desc
  limit 1
  for update;

  if v.id is null then
    return jsonb_build_object('handled',false,'reason','reservation_not_found');
  end if;

  if v.status<>'pending' then
    return jsonb_build_object(
      'handled',true,
      'reservation_id',v.id,
      'status',v.status,
      'inventory_released',false,
      'duplicate',true
    );
  end if;

  if v.inventory_reserved then
    update public.merch_products
    set inventory=coalesce(inventory,0)+v.quantity,
        updated_at=now()
    where id=v.product_id;
  end if;

  update public.tgg_merch_checkout_reservations
  set status=case when p_reason='expired' then 'expired' else 'released' end,
      released_at=now(),
      updated_at=now()
  where id=v.id;

  return jsonb_build_object(
    'handled',true,
    'reservation_id',v.id,
    'status',case when p_reason='expired' then 'expired' else 'released' end,
    'inventory_released',v.inventory_reserved,
    'quantity',v.quantity
  );
end
$function$


-- [40000000235] function private.tgg_remaining_activation_handoff_owner()
CREATE OR REPLACE FUNCTION private.tgg_remaining_activation_handoff_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','REMAINING-HANDOFF-ONE-FINAL-1.0',
    'summary',jsonb_build_object(
      'actionable_remaining',(
        select count(*) from private.tgg_one_final_activation_queue
        where status<>'complete'
          and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
      ),
      'ready_now',(
        select count(*) from private.tgg_one_final_activation_queue
        where status='ready'
          and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
      ),
      'waiting_on_dependency',(
        select count(*) from private.tgg_one_final_activation_queue
        where status='waiting'
          and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
      ),
      'external_input_required',(
        select count(*) from private.tgg_one_final_activation_queue
        where status='external_action'
          and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
      ),
      'maintenance_only',(
        select count(*) from private.tgg_one_final_activation_queue
        where item_key='edge_physical_cleanup' and status<>'complete'
      ),
      'hosted_account_advisories',(
        select count(*) from private.tgg_one_final_activation_queue
        where item_key='supabase_leaked_password_protection' and status<>'complete'
      ),
      'core_blockers',(
        select count(*) from private.tgg_one_final_activation_queue
        where core_blocking and status<>'complete'
      )
    ),
    'ready_now',coalesce((
      select jsonb_agg(jsonb_build_object(
        'key',item_key,'title',title,'next_action',next_action,'evidence',evidence
      ) order by category,item_key)
      from private.tgg_one_final_activation_queue
      where status='ready'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),'[]'::jsonb),
    'waiting_on_dependency',coalesce((
      select jsonb_agg(jsonb_build_object(
        'key',item_key,'title',title,'next_action',next_action,'evidence',evidence
      ) order by category,item_key)
      from private.tgg_one_final_activation_queue
      where status='waiting'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),'[]'::jsonb),
    'external_input_required',coalesce((
      select jsonb_agg(jsonb_build_object(
        'key',item_key,'title',title,'requirement',requirement,'next_action',next_action
      ) order by category,item_key)
      from private.tgg_one_final_activation_queue
      where status='external_action'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),'[]'::jsonb),
    'maintenance_only',coalesce((
      select jsonb_agg(jsonb_build_object(
        'key',item_key,'title',title,'next_action',next_action
      ))
      from private.tgg_one_final_activation_queue
      where item_key='edge_physical_cleanup' and status<>'complete'
    ),'[]'::jsonb),
    'hosted_account_advisories',coalesce((
      select jsonb_agg(jsonb_build_object(
        'key',item_key,'title',title,'next_action',next_action
      ))
      from private.tgg_one_final_activation_queue
      where item_key='supabase_leaked_password_protection' and status<>'complete'
    ),'[]'::jsonb),
    'generated_at',now()
  );
end
$function$


-- [40000000236] function private.tgg_remaining_handoff_packet_owner()
CREATE OR REPLACE FUNCTION private.tgg_remaining_handoff_packet_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','REMAINING-HANDOFF-ONE-FINAL-1.0',
    'actionable_remaining',(
      select count(*)
      from private.tgg_one_final_activation_queue
      where status<>'complete'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),
    'actionable',coalesce((
      select jsonb_agg(jsonb_build_object(
        'key',item_key,
        'title',title,
        'status',status,
        'category',category,
        'requirement',requirement,
        'next_action',next_action,
        'evidence',case
          when item_key='distribution_legal_metadata' then jsonb_build_object(
            'candidate_titles',coalesce(evidence->'candidate_titles','[]'::jsonb),
            'candidate_count',coalesce((evidence->>'current_candidate_count')::integer,0),
            'previous_real_legal_values_found',coalesce((evidence->>'previous_real_legal_values_found')::boolean,false)
          )
          when item_key='distribution_provider' then jsonb_build_object(
            'provider_candidate',evidence->>'provider_candidate',
            'endpoint_url',evidence->>'endpoint_url',
            'endpoint_reachability_verified',coalesce((evidence->>'endpoint_reachability_verified')::boolean,false),
            'credentials_verified',coalesce((evidence->>'credentials_verified')::boolean,false),
            'direct_plugin_found',false
          )
          when item_key='sfu_turn_provider' then jsonb_build_object(
            'provider_candidate',evidence->>'provider_candidate',
            'endpoint_pattern',evidence->>'provider_endpoint_pattern',
            'direct_plugin_found',false
          )
          when item_key='second_call_user' then jsonb_build_object(
            'auth_users',coalesce((evidence->>'auth_users')::integer,0),
            'second_auth_account_exists',coalesce((evidence->>'second_auth_account_exists')::boolean,false),
            'invite_created',coalesce((evidence->>'validation_invite_created')::boolean,false),
            'invite_status',evidence->>'validation_invite_status',
            'validated',coalesce((evidence->>'validated')::boolean,false)
          )
          else '{}'::jsonb
        end
      ) order by
        case item_key
          when 'distribution_legal_metadata' then 1
          when 'distribution_provider' then 2
          when 'sfu_turn_provider' then 3
          when 'second_call_user' then 4
          else 99
        end
      )
      from private.tgg_one_final_activation_queue
      where status<>'complete'
        and item_key not in ('supabase_leaked_password_protection','edge_physical_cleanup')
    ),'[]'::jsonb),
    'maintenance',coalesce((
      select jsonb_agg(jsonb_build_object(
        'key',item_key,'title',title,'status',status,'next_action',next_action
      ))
      from private.tgg_one_final_activation_queue
      where item_key='edge_physical_cleanup'
        and status<>'complete'
    ),'[]'::jsonb),
    'hosted_advisories',coalesce((
      select jsonb_agg(jsonb_build_object(
        'key',item_key,'title',title,'status',status,'next_action',next_action
      ))
      from private.tgg_one_final_activation_queue
      where item_key='supabase_leaked_password_protection'
        and status<>'complete'
    ),'[]'::jsonb),
    'generated_at',now()
  );
end
$function$


-- [40000000237] function private.tgg_reserve_merch_checkout(p_request_id uuid, p_product_id uuid, p_quantity integer, p_expires_at timestamp with time zone)
CREATE OR REPLACE FUNCTION private.tgg_reserve_merch_checkout(p_request_id uuid, p_product_id uuid, p_quantity integer, p_expires_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing public.tgg_merch_checkout_reservations;
  v_product public.merch_products;
  v_reservation_id uuid;
  v_reserved boolean:=false;
begin
  if auth.role()<>'service_role' then
    raise exception 'service_role_required';
  end if;

  if p_request_id is null then raise exception 'request_id_required'; end if;
  if p_product_id is null then raise exception 'product_id_required'; end if;
  if p_quantity is null or p_quantity<1 or p_quantity>10 then
    raise exception 'quantity_invalid';
  end if;
  if p_expires_at is null or p_expires_at<=now() then
    raise exception 'expires_at_invalid';
  end if;

  select * into v_existing
  from public.tgg_merch_checkout_reservations
  where request_id=p_request_id
  for update;

  if v_existing.id is not null then
    if v_existing.product_id<>p_product_id
       or v_existing.quantity<>p_quantity then
      raise exception 'request_id_payload_mismatch';
    end if;

    if v_existing.status<>'pending' then
      raise exception 'request_id_not_reusable';
    end if;

    select * into v_product
    from public.merch_products
    where id=v_existing.product_id;

    if v_product.product_type<>'physical' then
      raise exception 'digital_fulfillment_not_configured';
    end if;

    return jsonb_build_object(
      'reservation_id',v_existing.id,
      'request_id',v_existing.request_id,
      'product_id',v_existing.product_id,
      'creator_id',v_existing.creator_id,
      'quantity',v_existing.quantity,
      'inventory_reserved',v_existing.inventory_reserved,
      'checkout_session_id',v_existing.checkout_session_id,
      'status',v_existing.status,
      'expires_at',v_existing.expires_at,
      'title',v_product.title,
      'description',v_product.description,
      'product_type',v_product.product_type,
      'price_cents',v_product.price_cents,
      'currency',v_product.currency,
      'image_url',v_product.image_url,
      'duplicate_request',true
    );
  end if;

  select * into v_product
  from public.merch_products
  where id=p_product_id
    and status='published'
  for update;

  if v_product.id is null then
    raise exception 'product_not_available';
  end if;

  if v_product.product_type<>'physical' then
    raise exception 'digital_fulfillment_not_configured';
  end if;

  if v_product.price_cents is null or v_product.price_cents<50 then
    raise exception 'product_price_invalid';
  end if;

  if v_product.inventory is not null then
    if v_product.inventory<p_quantity then
      raise exception 'inventory_insufficient';
    end if;

    update public.merch_products
    set inventory=inventory-p_quantity,
        updated_at=now()
    where id=v_product.id;

    v_reserved:=true;
  end if;

  insert into public.tgg_merch_checkout_reservations(
    request_id,product_id,creator_id,quantity,
    inventory_reserved,status,expires_at
  )
  values(
    p_request_id,v_product.id,v_product.creator_id,p_quantity,
    v_reserved,'pending',p_expires_at
  )
  returning id into v_reservation_id;

  return jsonb_build_object(
    'reservation_id',v_reservation_id,
    'request_id',p_request_id,
    'product_id',v_product.id,
    'creator_id',v_product.creator_id,
    'quantity',p_quantity,
    'inventory_reserved',v_reserved,
    'checkout_session_id',null,
    'status','pending',
    'expires_at',p_expires_at,
    'title',v_product.title,
    'description',v_product.description,
    'product_type',v_product.product_type,
    'price_cents',v_product.price_cents,
    'currency',v_product.currency,
    'image_url',v_product.image_url,
    'duplicate_request',false
  );
end
$function$


-- [40000000238] function private.tgg_review_only_runtime_drift(p_drift jsonb)
CREATE OR REPLACE FUNCTION private.tgg_review_only_runtime_drift(p_drift jsonb)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select
    coalesce((p_drift->>'ok')::boolean,false)=false
    and jsonb_array_length(coalesce(p_drift->'failed','[]'::jsonb))=1
    and (p_drift->'failed'->>0)='public_bundle_version'
    and coalesce((
      select config->>'public_shell_version'
      from public.tgg_master_shared_settings
      where setting_key='runtime_manifest' and is_published=true
      limit 1
    ),'') <> coalesce(public.tgg_public_one_final_bundle()->>'version','')
$function$


-- [40000000239] function private.tgg_rotate_all_challenges()
CREATE OR REPLACE FUNCTION private.tgg_rotate_all_challenges()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare r record; n integer:=0; c integer;
begin
  for r in select id from public.world_characters where character_status='active' loop
    c := private.tgg_rotate_challenges(r.id);
    n := n + c;
  end loop;
  perform private.tgg_worker_mark('challenge-rotation','ok',jsonb_build_object('inserted',n));
  return n;
exception when others then
  perform private.tgg_worker_mark('challenge-rotation','error',jsonb_build_object('error',sqlerrm));
  raise;
end;
$function$


-- [40000000240] function private.tgg_rotate_challenges(p_character_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_rotate_challenges(p_character_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_count integer:=0;
begin
  update public.tgg_world_character_challenges c
  set status='expired',updated_at=now()
  from public.tgg_world_challenge_templates t
  where c.character_id=p_character_id
    and c.challenge_key=t.challenge_key
    and c.status='active'
    and t.enabled=true
    and c.period_key<>private.tgg_world_challenge_period(t.cadence);

  insert into public.tgg_world_character_challenges(
    character_id,challenge_key,period_key,status,progress,streak_count,updated_at
  )
  select
    p_character_id,
    c.challenge_key,
    private.tgg_world_challenge_period(c.cadence),
    'active',
    '{}'::jsonb,
    0,
    now()
  from public.tgg_world_challenge_templates c
  where c.enabled=true
  on conflict(character_id,challenge_key,period_key) do nothing;

  get diagnostics v_count=row_count;
  return v_count;
end;
$function$


-- [40000000241] function private.tgg_runtime_browser_observe_v1_impl(p_flow_key text, p_capture jsonb)
CREATE OR REPLACE FUNCTION private.tgg_runtime_browser_observe_v1_impl(p_flow_key text, p_capture jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_headers jsonb := '{}'::jsonb;
  v_origin text := '';
  v_build text := coalesce(p_capture->>'build','');
  v_path text := coalesce(p_capture->>'page_path','');
  v_load_ms integer := greatest(0,least(120000,coalesce((p_capture->>'load_ms')::integer,0)));
  v_workspace text;
  v_expected_workspace text;
  v_contract_key text;
  v_pass boolean := false;
  v_verified integer := 0;
  v_required integer := 0;
  v_now timestamptz := clock_timestamp();
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  begin
    v_headers := coalesce(nullif(current_setting('request.headers',true),'')::jsonb,'{}'::jsonb);
  exception when others then
    v_headers := '{}'::jsonb;
  end;
  v_origin := coalesce(v_headers->>'origin','');

  if not (
    v_origin = 'https://trugogettamixtapes.blogspot.com'
    or v_origin = 'https://xsofowzvwetamhyuvlpj.supabase.co'
    or v_origin ~ '^https://([a-z0-9-]+\\.)?trugogettamixtapes\\.com$'
  ) then
    raise exception 'BROWSER_ORIGIN_REQUIRED' using errcode='42501';
  end if;

  if p_flow_key is null or p_flow_key <> all(array[
    'command_center_runtime','creator_profile_runtime','expansion_runtime','growth_runtime',
    'messenger_runtime','music_library_runtime','notifications_runtime','protected_audio_runtime',
    'release_pro_runtime','session_recovery_runtime','supporters_runtime'
  ]) then
    raise exception 'UNKNOWN_BROWSER_QA_FLOW' using errcode='22023';
  end if;

  if v_build not in ('ARTIST-HQ-V3-AUTO-QA-V1','CREATOR-OS-AUTO-QA-V1') then
    raise exception 'UNAPPROVED_QA_BUILD' using errcode='22023';
  end if;

  if coalesce((p_capture->>'browser_context')::boolean,false) is not true
     or coalesce((p_capture->>'auth_present')::boolean,false) is not true
     or coalesce((p_capture->>'rendered')::boolean,false) is not true
     or coalesce((p_capture->>'blocking_error_count')::integer,1) <> 0
     or v_load_ms <= 0 then
    raise exception 'INCOMPLETE_BROWSER_CAPTURE' using errcode='22023';
  end if;

  v_expected_workspace := case p_flow_key
    when 'command_center_runtime' then 'dashboard'
    when 'expansion_runtime' then 'expansion'
    when 'growth_runtime' then 'growth'
    when 'messenger_runtime' then 'messages'
    when 'music_library_runtime' then 'library'
    when 'release_pro_runtime' then 'releases'
    when 'supporters_runtime' then 'supporters'
    else null
  end;
  v_workspace := nullif(p_capture->>'workspace','');

  if p_flow_key='release_pro_runtime' then
    v_pass := v_workspace='releases'
      and coalesce((p_capture->>'workspace_schema_ok')::boolean,false)
      and coalesce((p_capture->>'control_responded')::boolean,false)
      and (
        coalesce((p_capture->>'workspace_rpc_ok')::boolean,false)
        or (
          coalesce((p_capture->>'release_create_path_ok')::boolean,false)
          and coalesce(p_capture->>'release_create_rpc','')='tgg_creator_create_mixtape_draft'
          and coalesce(p_capture->>'release_create_validation','')='TITLE_INVALID'
          and coalesce((p_capture->>'release_mutation_performed')::boolean,true) is false
        )
      );
  elsif v_expected_workspace is not null then
    v_pass := v_workspace = v_expected_workspace
      and coalesce((p_capture->>'workspace_schema_ok')::boolean,false)
      and coalesce((p_capture->>'workspace_rpc_ok')::boolean,false)
      and coalesce((p_capture->>'control_responded')::boolean,false);
  elsif p_flow_key='creator_profile_runtime' then
    v_pass := coalesce((p_capture->>'profile_visible')::boolean,false)
      and coalesce((p_capture->>'control_responded')::boolean,false);
  elsif p_flow_key='notifications_runtime' then
    v_pass := coalesce((p_capture->>'notifications_rpc_ok')::boolean,false)
      and coalesce((p_capture->>'control_responded')::boolean,false);
  elsif p_flow_key='session_recovery_runtime' then
    v_pass := coalesce((p_capture->>'session_recovered')::boolean,false)
      and coalesce((p_capture->>'control_responded')::boolean,false);
  elsif p_flow_key='protected_audio_runtime' then
    v_pass := coalesce((p_capture->>'signed_audio_ok')::boolean,false)
      and (
        coalesce((p_capture->>'playback_started')::boolean,false)
        or coalesce((p_capture->>'media_fetch_ok')::boolean,false)
      )
      and coalesce((p_capture->>'control_responded')::boolean,false);
  end if;

  if not v_pass then
    raise exception 'FLOW_EVIDENCE_NOT_SUFFICIENT' using errcode='22023';
  end if;

  insert into private.tgg_browser_runtime_observations_v1(
    user_id,flow_key,status,origin,build,page_path,load_ms,capture,first_observed_at,last_observed_at
  ) values (
    v_uid,p_flow_key,'passed',v_origin,v_build,v_path,v_load_ms,
    (p_capture - 'access_token' - 'refresh_token' - 'user_id' - 'email'),v_now,v_now
  )
  on conflict(user_id,flow_key) do update set
    status='passed',origin=excluded.origin,build=excluded.build,page_path=excluded.page_path,
    load_ms=excluded.load_ms,capture=excluded.capture,last_observed_at=excluded.last_observed_at;

  update public.tgg_browser_runtime_evidence_gate
  set status='passed',
      browser_verified=true,
      evidence=jsonb_build_object(
        'source','authenticated_browser_auto_qa_v1',
        'required',true,
        'verified',true,
        'database_contract_only',false,
        'origin',v_origin,
        'build',v_build,
        'page_path',v_path,
        'load_ms',v_load_ms,
        'captured_at',v_now,
        'flow_key',p_flow_key
      ),
      checked_at=v_now,
      updated_at=v_now
  where flow_key=p_flow_key and evidence_required;

  update public.tgg_browser_qa_execution_matrix
  set status='passed',browser_verified=true,updated_at=v_now
  where flow_key=p_flow_key;

  v_contract_key := case p_flow_key
    when 'command_center_runtime' then 'creator_command_center'
    when 'creator_profile_runtime' then 'creator_profile'
    when 'expansion_runtime' then 'expansion'
    when 'growth_runtime' then 'growth'
    when 'messenger_runtime' then 'messenger'
    when 'music_library_runtime' then 'music_library'
    when 'notifications_runtime' then 'notifications'
    when 'protected_audio_runtime' then 'protected_audio'
    when 'release_pro_runtime' then 'release_pro'
    when 'session_recovery_runtime' then 'session_recovery'
    when 'supporters_runtime' then 'supporters'
  end;

  update public.tgg_runtime_qa_contract_matrix
  set status='passed',updated_at=v_now,
      metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
        'browser_verified',true,'browser_evidence_source','authenticated_browser_auto_qa_v1','browser_verified_at',v_now
      )
  where contract_key=v_contract_key;

  insert into public.tgg_runtime_qa_contract_evidence(
    matrix_id,evidence_source,evidence_type,status,source_ref,evidence,captured_at,expires_at,created_at
  )
  select m.id,'authenticated_browser_auto_qa_v1','browser_execution_capture','passed',p_flow_key,
         jsonb_build_object('flow_key',p_flow_key,'origin',v_origin,'build',v_build,'page_path',v_path,'load_ms',v_load_ms),
         v_now,null,v_now
  from public.tgg_runtime_qa_contract_matrix m
  where m.contract_key=v_contract_key
    and not exists (
      select 1 from public.tgg_runtime_qa_contract_evidence e
      where e.matrix_id=m.id and e.evidence_source='authenticated_browser_auto_qa_v1' and e.status='passed'
    );

  select count(*) into v_required from public.tgg_browser_runtime_evidence_gate where evidence_required;
  select count(*) into v_verified from public.tgg_browser_runtime_evidence_gate where evidence_required and browser_verified and status='passed';

  insert into public.tgg_final_launch_blocker_matrix(blocker_key,category,status,blocking,evidence,captured_at,created_at)
  values(
    'browser_qa_evidence','runtime',
    case when v_required>0 and v_verified=v_required then 'complete' else 'pending' end,
    not (v_required>0 and v_verified=v_required),
    jsonb_build_object(
      'reason',case when v_required>0 and v_verified=v_required then 'All required authenticated browser runtime evidence has been captured.' else 'Authenticated browser runtime evidence is still incomplete.' end,
      'required_flows',v_required,
      'verified_flows',v_verified,
      'remaining_flows',greatest(v_required-v_verified,0),
      'source','authenticated_browser_auto_qa_v1',
      'last_verified_flow',p_flow_key,
      'database_contract_only',false,
      'sql_override_allowed',false
    ),v_now,v_now
  );

  return jsonb_build_object('ok',true,'flow_key',p_flow_key,'status','passed','required',v_required,'verified',v_verified,'remaining',greatest(v_required-v_verified,0),'captured_at',v_now);
end
$function$


-- [40000000242] function private.tgg_runtime_drift_guard_internal()
CREATE OR REPLACE FUNCTION private.tgg_runtime_drift_guard_internal()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with
manifest as (
  select config j
  from public.tgg_master_shared_settings
  where setting_key='runtime_manifest' and is_published=true
),
pub as (select public.tgg_public_one_final_bundle() j),
feat as (select public.tgg_feature_runtime_health() j),
blogger as (
  select coalesce((
    select d.status='verified'
      and coalesce((d.verification->>'api_ok')::boolean,false)
    from public.v98_blogger_deployments d
    where d.verification->>'api_ok'='true'
    order by d.updated_at desc
    limit 1
  ),false) runtime_verified
),
checks as (
  select * from (values
    ('public_bundle_version',
      (select j->>'version' from pub)=
      coalesce((select j->>'public_shell_version' from manifest),'ONE-FINAL-CANONICAL-1.0')
    ),
    ('public_home_route',(select j->'canonical_routes'->>'home' from pub)='/'),
    ('public_release_feed',jsonb_array_length(coalesce((select j->'releases' from pub),'[]'::jsonb))>0),
    ('feature_manifest',(select j->>'version' from feat) in ('FEATURE-RUNTIME-1.1','FEATURE-RUNTIME-1.2')),
    ('all_features_ready',not exists(
      select 1 from jsonb_each((select j->'modules' from feat))
      where coalesce((value->>'ready')::boolean,false)=false
    )),
    ('blogger_runtime_verified',(select runtime_verified from blogger)),
    ('creator_os_route',exists(
      select 1 from public.tgg_site_routes
      where route_key='artist_creator_os'
        and is_active=true
        and path=(select j->>'canonical_creator_os' from manifest)
    )),
    ('master_admin_route',exists(
      select 1 from public.tgg_site_routes
      where route_key='owner_master_admin'
        and is_active=true
        and path=(select j->>'canonical_master_admin' from manifest)
    )),
    ('owner_console_registered',
      coalesce((select j->>'owner_console_url' from manifest),'')=
      'https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-creator-os-app-v17?app=1#master-admin'
    ),
    ('retired_command_center_absent',not exists(
      select 1 from public.tgg_site_routes
      where is_active and path ilike '%/functions/v1/creator-os-command-center%'
    )),
    ('legacy_dashboard_hidden',not exists(
      select 1 from public.tgg_site_routes
      where route_key='artist_dashboard' and is_active=true
    )),
    ('duplicate_upload_hidden',not exists(
      select 1 from public.tgg_site_routes
      where route_key='submit_music' and is_active=true
    ))
  ) v(check_key,ok)
)
select jsonb_build_object(
  'ok',bool_and(ok),
  'version','DRIFT-GUARD-ONE-FINAL-1.9',
  'checks',jsonb_object_agg(check_key,ok),
  'failed',coalesce(jsonb_agg(check_key) filter(where not ok),'[]'::jsonb),
  'generated_at',now()
)
from checks;
$function$


-- [40000000243] function private.tgg_schedule_dynamic_events()
CREATE OR REPLACE FUNCTION private.tgg_schedule_dynamic_events()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_count integer:=0;
  v_clock jsonb;
  v_hour integer;
  v_is_weekend boolean;
begin
  v_clock:=private.tgg_world_clock();
  v_hour:=coalesce((v_clock->>'local_hour')::integer,0);
  v_is_weekend:=coalesce((v_clock->>'is_weekend')::boolean,false);

  update public.tgg_world_dynamic_events
  set status='active',updated_at=now()
  where status='scheduled' and starts_at<=now() and ends_at>now();

  with eligible as (
    select
      t.*,
      row_number() over(order by t.priority desc,t.event_key) as rn
    from public.tgg_world_dynamic_event_templates t
    where t.enabled=true
      and not exists(
        select 1
        from public.tgg_world_dynamic_events e
        where e.event_key=t.event_key
          and e.created_at > now()-make_interval(mins=>t.cooldown_minutes)
      )
      and (
        t.trigger_mode<>'weekend'
        or v_is_weekend
      )
      and (
        t.trigger_mode<>'seasonal'
        or exists(
          select 1 from public.tgg_world_seasons s
          where s.enabled=true
            and (s.starts_at is null or s.starts_at<=now())
            and (s.ends_at is null or s.ends_at>=now())
        )
      )
      and (
        t.trigger_mode<>'night-window'
        or not (t.trigger_conditions ? 'hour_start')
        or not (t.trigger_conditions ? 'hour_end')
        or (
          case
            when (t.trigger_conditions->>'hour_start')::integer
               <= (t.trigger_conditions->>'hour_end')::integer
            then v_hour >= (t.trigger_conditions->>'hour_start')::integer
             and v_hour <  (t.trigger_conditions->>'hour_end')::integer
            else v_hour >= (t.trigger_conditions->>'hour_start')::integer
              or v_hour <  (t.trigger_conditions->>'hour_end')::integer
          end
        )
      )
  )
  insert into public.tgg_world_dynamic_events(
    event_key,location_key,status,starts_at,ends_at,world_state,spawned_by,created_at,updated_at
  )
  select
    e.event_key,
    e.location_key,
    'active',
    now(),
    now()+make_interval(mins=>e.duration_minutes),
    jsonb_build_object(
      'title',e.title,
      'event_type',e.event_type,
      'priority',e.priority,
      'participant_roles',e.participant_roles,
      'world_clock',v_clock
    ),
    'scheduler',
    now(),
    now()
  from eligible e
  where e.rn<=3;

  get diagnostics v_count=row_count;
  return v_count;
end;
$function$


-- [40000000244] function private.tgg_schema_attestation_reconcile(p_reason text, p_expected_changed_keys text[])
CREATE OR REPLACE FUNCTION private.tgg_schema_attestation_reconcile(p_reason text, p_expected_changed_keys text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_saved jsonb;
  v_current jsonb;
  v_md5 text;
  v_count integer;
  v_changed text[];
  v_expected text[];
begin
  select details->'schema_attestation_objects'
  into v_saved
  from public.tgg_operational_recovery_checkpoints
  where checkpoint_key='migration_hygiene_live'
  limit 1;

  if v_saved is null then
    raise exception 'SCHEMA_ATTESTATION_CHECKPOINT_MISSING';
  end if;

  with fn as (
    select n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' object_key,
           md5(pg_get_functiondef(p.oid)) definition_md5
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where p.prokind='f'
    and (n.nspname,p.proname) in (
      ('private','tgg_launch_closeout_ops_snapshot'),('public','tgg_launch_closeout_summary'),
      ('public','tgg_livekit_credentials_save'),('private','tgg_apply_provider_staging_to_activation_queue'),
      ('private','tgg_reconcile_distribution_metadata_activation_item'),('private','tgg_reconcile_call_validation_activation_item'),
      ('private','tgg_enforce_one_final_routes'),('private','tgg_runtime_drift_guard_internal'),
      ('public','tgg_v5000_production_manifest'),('private','tgg_refresh_migration_hygiene_runtime_inventory'),
      ('private','tgg_operational_dependency_check'),('private','tgg_post_migration_schema_attestation_check'),
      ('private','tgg_release_download_policy_consistency_check'),('public','tgg_public_one_final_bundle'),
      ('private','tgg_public_route_contract_consistency_check'),('tgg_safe_api','public_memberships_feed'),
      ('private','tgg_membership_public_join_consistency_check'),('private','tgg_sync_provider_handoff_status'),
      ('private','tgg_completed_provider_handoff_consistency_check'),('private','tgg_call_validation_invite_freshness_check'),
      ('private','tgg_distribution_metadata_coverage_check'),('private','tgg_legacy_public_route_retirement_check'),
      ('private','tgg_call_invite_expiry_watch')
    )
  ),
  cons as (
    select 'constraint:'||conname object_key,md5(pg_get_constraintdef(oid)) definition_md5
    from pg_constraint where conrelid='public.tgg_site_routes'::regclass
      and conname='tgg_site_routes_master_admin_canonical'
  ),
  route_state as (
    select 'route:'||route_key object_key,
           md5(jsonb_build_object(
             'path',path,'active',is_active,'primary',is_primary,
             'workspace',workspace_key,'access',access_level
           )::text) definition_md5
    from public.tgg_site_routes
    where route_key in ('owner_master_admin','artist_creator_os','creator_expansion_control','public_mixtape_detail_legacy')
  ),
  handoff_state as (
    select 'handoff:'||provider_key object_key,
           md5(jsonb_build_object(
             'status',status,'required_action',required_action,
             'verification_check',verification_check,'target_runtime',target_runtime
           )::text) definition_md5
    from public.tgg_provider_handoff
    where provider_key in ('distribution.provider','broadcast.sfu_turn','calls.two_user_validation','stripe.native','blogger.oauth')
  ),
  all_items as (
    select * from fn union all select * from cons union all select * from route_state union all select * from handoff_state
  )
  select
    jsonb_object_agg(object_key,definition_md5 order by object_key),
    md5(string_agg(object_key||':'||definition_md5,E'
' order by object_key)),
    count(*)::integer
  into v_current,v_md5,v_count
  from all_items;

  select coalesce(array_agg(k order by k),array[]::text[])
  into v_changed
  from (
    select coalesce(c.key,s.key) k
    from jsonb_each_text(v_current) c
    full join jsonb_each_text(v_saved) s using(key)
    where c.value is distinct from s.value
  ) d;

  select coalesce(array_agg(x order by x),array[]::text[])
  into v_expected
  from unnest(coalesce(p_expected_changed_keys,array[]::text[])) x;

  if v_changed is distinct from v_expected then
    return jsonb_build_object(
      'ok',false,
      'error','unexpected_schema_attestation_diff',
      'expected_changed_keys',to_jsonb(v_expected),
      'actual_changed_keys',to_jsonb(v_changed),
      'checkpoint_updated',false
    );
  end if;

  update public.tgg_operational_recovery_checkpoints
  set details=details||jsonb_build_object(
        'schema_attestation_md5',v_md5,
        'schema_attestation_object_count',v_count,
        'schema_attestation_objects',v_current,
        'schema_attested_at',now(),
        'schema_attestation_refreshed_at',now(),
        'schema_attestation_refresh_reason',p_reason,
        'schema_attestation_last_approved_changed_keys',to_jsonb(v_changed)
      )
  where checkpoint_key='migration_hygiene_live';

  return jsonb_build_object(
    'ok',true,
    'checkpoint_updated',true,
    'changed_keys',to_jsonb(v_changed),
    'object_count',v_count,
    'attestation_md5',v_md5,
    'reconciled_at',now()
  );
end
$function$


-- [40000000245] function private.tgg_seed_release_public_content(p_owner_user_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_seed_release_public_content(p_owner_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row record;
  v_created integer:=0;
  v_item_id uuid;
begin
  if p_owner_user_id is null then
    raise exception 'OWNER_REQUIRED' using errcode='22023';
  end if;

  for v_row in
    select m.id,m.title,m.slug,m.description,m.created_at
    from public.mixtapes m
    join public.artists a on a.id=m.artist_id
    where a.user_id=p_owner_user_id
      and m.status='published'
      and nullif(btrim(coalesce(m.slug,'')),'') is not null
    order by m.created_at desc
  loop
    insert into public.content_items(
      creator_id,content_type,status,visibility,title,summary,target_url,source_type,source_id,metadata
    )
    values(
      p_owner_user_id,
      'POST',
      'APPROVED',
      'PUBLIC',
      v_row.title,
      nullif(btrim(coalesce(v_row.description,'')),''),
      'https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-shell?view=release&slug='||v_row.slug,
      'mixtape',
      v_row.id,
      jsonb_build_object('promo_kind','release_spotlight','slug',v_row.slug)
    )
    on conflict(creator_id,source_type,source_id,content_type)
    where source_type is not null and source_id is not null and status<>'DELETED'
    do update set
      title=excluded.title,
      summary=excluded.summary,
      target_url=excluded.target_url,
      metadata=excluded.metadata,
      visibility='PUBLIC',
      updated_at=now()
    returning id into v_item_id;

    insert into public.tgg_public_content_queue(
      content_item_id,owner_user_id,channel,scheduled_at,status
    )
    select
      v_item_id,
      p_owner_user_id,
      'discover',
      now()+make_interval(hours=>greatest(v_created,0)*12),
      'queued'
    where not exists(
      select 1 from public.tgg_public_content_queue q
      where q.content_item_id=v_item_id
        and q.status in ('queued','published')
    );

    v_created:=v_created+1;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'version','PUBLIC-CONTENT-RELEASE-SEED-1.0',
    'processed_releases',v_created,
    'candidate_count',(select count(*) from public.content_items c where c.creator_id=p_owner_user_id and c.status='APPROVED' and c.visibility='PUBLIC'),
    'queued_count',(select count(*) from public.tgg_public_content_queue q where q.owner_user_id=p_owner_user_id and q.status='queued'),
    'generated_at',now()
  );
end
$function$


-- [40000000246] function private.tgg_signup_password_guard()
CREATE OR REPLACE FUNCTION private.tgg_signup_password_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions'
AS $function$
declare
  v_enforce boolean := false;
  v_token_text text;
  v_token uuid;
  v_expected_hash text;
  v_purpose text;
  v_found boolean := false;
begin
  if tg_op='INSERT' then
    if coalesce(new.encrypted_password,'')='' then
      return new;
    end if;
  elsif tg_op='UPDATE' then
    if not (
      old.encrypted_password is distinct from new.encrypted_password
      and coalesce(new.raw_user_meta_data->>'repaired_unconfirmed_account','false')='true'
      and coalesce(old.raw_user_meta_data->>'repaired_unconfirmed_account','false')<>'true'
    ) then
      return new;
    end if;
  else
    return new;
  end if;

  select enforcement_enabled into v_enforce
  from private.tgg_signup_password_guard_config where id=1;

  v_token_text := coalesce(new.raw_user_meta_data->>'tgg_signup_approval','');
  v_purpose := coalesce(new.raw_user_meta_data->>'signup_source','creator_os_direct');

  if v_token_text <> '' then
    begin
      v_token := v_token_text::uuid;
      v_expected_hash := encode(extensions.digest(lower(coalesce(new.email,'')),'sha256'),'hex');
      delete from private.tgg_signup_password_approvals
      where token=v_token
        and email_hash=v_expected_hash
        and purpose=v_purpose
        and expires_at>now()
      returning true into v_found;
    exception when others then
      v_found := false;
    end;
  end if;

  if v_found then
    new.raw_user_meta_data := coalesce(new.raw_user_meta_data,'{}'::jsonb) - 'tgg_signup_approval';
    return new;
  end if;

  if coalesce(v_enforce,false) then
    raise exception using errcode='P0001', message='TGG_PASSWORD_APPROVAL_REQUIRED';
  end if;

  return new;
end;
$function$


-- [40000000247] function private.tgg_snapshot_leaderboards(p_period_key text)
CREATE OR REPLACE FUNCTION private.tgg_snapshot_leaderboards(p_period_key text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_period text := coalesce(p_period_key,to_char(date_trunc('week',now() at time zone 'utc')::date,'IYYY-"W"IW'));
  v_count integer := 0;
begin
  insert into public.tgg_world_leaderboard_snapshots(leaderboard_key,season_key,period_key,ranking,generated_at)
  select
    l.leaderboard_key,
    l.season_key,
    v_period,
    case l.metric_key
      when 'career_reputation' then (
        select coalesce(jsonb_agg(jsonb_build_object('character_id',x.character_id,'value',x.val) order by x.val desc),'[]'::jsonb)
        from (
          select character_id,sum(reputation)::numeric val
          from public.tgg_world_career_reputation
          group by character_id
          order by val desc
          limit 100
        ) x
      )
      when 'business_xp' then (
        select coalesce(jsonb_agg(jsonb_build_object('character_id',x.character_id,'value',x.val) order by x.val desc),'[]'::jsonb)
        from (
          select character_id,sum(business_xp)::numeric val
          from public.tgg_world_character_businesses
          group by character_id
          order by val desc
          limit 100
        ) x
      )
      when 'achievement_count' then (
        select coalesce(jsonb_agg(jsonb_build_object('character_id',x.character_id,'value',x.val) order by x.val desc),'[]'::jsonb)
        from (
          select character_id,count(*)::numeric val
          from public.tgg_world_character_achievements
          where unlocked_at is not null
          group by character_id
          order by val desc
          limit 100
        ) x
      )
      else '[]'::jsonb
    end,
    now()
  from public.tgg_world_leaderboard_definitions l
  where l.enabled=true
  on conflict(leaderboard_key,period_key) do update
    set ranking=excluded.ranking,generated_at=now();

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$


-- [40000000248] function private.tgg_start_encounter(p_character_id uuid, p_encounter_key text)
CREATE OR REPLACE FUNCTION private.tgg_start_encounter(p_character_id uuid, p_encounter_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_template public.tgg_world_encounter_templates%rowtype;
  v_location_key text;
  v_rep integer := 0;
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  if not exists(
    select 1 from public.world_characters
    where id=p_character_id and user_id=v_uid and character_status='active'
  ) then
    raise exception 'character ownership mismatch';
  end if;

  select e.* into v_template
  from public.tgg_world_encounter_templates e
  where e.encounter_key=p_encounter_key and e.enabled=true;

  if v_template.encounter_key is null then raise exception 'encounter unavailable'; end if;

  select l.location_key into v_location_key
  from public.world_characters wc
  join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=p_character_id;

  if v_location_key is distinct from v_template.location_key then
    raise exception 'character is not at encounter location';
  end if;

  if v_template.trigger_conditions ? 'min_reputation' then
    select coalesce(max(r.reputation),0) into v_rep
    from public.tgg_world_career_reputation r
    where r.character_id=p_character_id;

    if v_rep < (v_template.trigger_conditions->>'min_reputation')::integer then
      raise exception 'reputation requirement not met';
    end if;
  end if;

  select ce.id into v_id
  from public.tgg_world_character_encounters ce
  where ce.character_id=p_character_id
    and ce.encounter_key=p_encounter_key
    and ce.status='active'
  order by ce.started_at desc
  limit 1;

  if v_id is not null then return v_id; end if;

  if not v_template.repeatable and exists(
    select 1 from public.tgg_world_character_encounters ce
    where ce.character_id=p_character_id
      and ce.encounter_key=p_encounter_key
      and ce.status='completed'
  ) then
    raise exception 'encounter already completed';
  end if;

  if exists(
    select 1 from public.tgg_world_character_encounters ce
    where ce.character_id=p_character_id
      and ce.encounter_key=p_encounter_key
      and ce.completed_at is not null
      and ce.completed_at > now()-make_interval(mins=>v_template.cooldown_minutes)
  ) then
    raise exception 'encounter is on cooldown';
  end if;

  insert into public.tgg_world_character_encounters
    (character_id,encounter_key,status,current_node_key,state,started_at,updated_at)
  values(
    p_character_id,p_encounter_key,'active',v_template.root_node_key,
    jsonb_build_object('started_location',v_location_key),
    now(),now()
  )
  returning id into v_id;

  return v_id;
end;
$function$


-- [40000000249] function private.tgg_store_provider_secret(p_provider_key text, p_secret_value text)
CREATE OR REPLACE FUNCTION private.tgg_store_provider_secret(p_provider_key text, p_secret_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text;
  v_name text;
  v_secret text:=nullif(btrim(coalesce(p_secret_value,'')),'');
  v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select raw_app_meta_data->>'tgg_role'
  into v_role
  from auth.users
  where id=v_uid;

  if v_role<>'owner' then raise exception 'OWNER_REQUIRED' using errcode='42501'; end if;

  if p_provider_key not in (
    'stripe.webhook',
    'distribution.provider',
    'broadcast.sfu_turn',
    'email.resend'
  ) then
    raise exception 'UNSUPPORTED_PROVIDER_KEY' using errcode='22023';
  end if;

  if v_secret is null or length(v_secret)<8 or length(v_secret)>4096 then
    raise exception 'INVALID_SECRET_VALUE' using errcode='22023';
  end if;

  if p_provider_key='email.resend' and v_secret !~ '^re_' then
    raise exception 'INVALID_RESEND_API_KEY' using errcode='22023';
  end if;

  v_name:=case p_provider_key
    when 'stripe.webhook' then 'tgg_stripe_webhook_secret'
    when 'distribution.provider' then 'tgg_distribution_provider_secret'
    when 'broadcast.sfu_turn' then 'tgg_broadcast_provider_secret'
    when 'email.resend' then 'tgg_resend_api_key'
  end;

  select id into v_id
  from vault.secrets
  where name=v_name
  order by created_at desc
  limit 1;

  if v_id is null then
    perform vault.create_secret(
      v_secret,v_name,'TGG provider secret stored through owner-only Activation Bridge',null
    );
  else
    perform vault.update_secret(
      v_id,v_secret,v_name,'TGG provider secret stored through owner-only Activation Bridge',null
    );
  end if;

  insert into private.tgg_provider_secret_registry(
    provider_key,vault_secret_name,status,last_error,stored_by,stored_at,updated_at
  )
  values(
    p_provider_key,v_name,'stored',null,v_uid,now(),now()
  )
  on conflict(provider_key) do update set
    vault_secret_name=excluded.vault_secret_name,
    status='stored',
    last_error=null,
    stored_by=v_uid,
    stored_at=now(),
    updated_at=now();

  update public.tgg_provider_runtime_config
     set disabled_reason=case
       when p_provider_key='stripe.webhook' then 'webhook_secret_stored_verification_pending'
       when p_provider_key='distribution.provider' then 'provider_endpoint_or_verification_pending'
       when p_provider_key='broadcast.sfu_turn' then 'provider_endpoint_or_verification_pending'
       when p_provider_key='email.resend' then 'resend_key_stored_runtime_verification_pending'
       else disabled_reason
     end,
     updated_at=now()
   where provider_key=p_provider_key;

  update private.tgg_one_final_activation_queue
     set status=case when item_key='stripe_webhook_signing_secret' then 'ready' else status end,
         next_action=case
           when item_key='stripe_webhook_signing_secret' then
             'Signing secret is stored in Vault. Verify one signed Stripe webhook event to finish activation.'
           when item_key='distribution_provider' then
             'Provider secret is stored. Stage the real HTTPS DSP endpoint and verify provider delivery.'
           when item_key='sfu_turn_provider' then
             'Provider secret is stored. Stage the HTTPS/WSS SFU/TURN endpoint and verify room/token issuance.'
           else next_action
         end,
         evidence=coalesce(evidence,'{}'::jsonb)||jsonb_build_object(
           'vault_secret_stored',true,
           'vault_secret_name',v_name,
           'secret_value_exposed',false,
           'stored_at',now()
         ),
         last_checked_at=now()
   where (p_provider_key='stripe.webhook' and item_key='stripe_webhook_signing_secret')
      or (p_provider_key='distribution.provider' and item_key='distribution_provider')
      or (p_provider_key='broadcast.sfu_turn' and item_key='sfu_turn_provider');

  return jsonb_build_object(
    'ok',true,
    'provider_key',p_provider_key,
    'status','stored',
    'vault_secret_name',v_name,
    'secret_returned',false,
    'stored_at',now()
  );
end;
$function$


-- [40000000250] function private.tgg_submit_audiobook(p_audiobook_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_submit_audiobook(p_audiobook_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_count integer;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  if not exists(
    select 1
    from public.tgg_audiobooks b
    join public.artists a on a.id=b.artist_id
    where b.id=p_audiobook_id
      and a.user_id=v_uid
      and b.status in ('draft','changes_requested')
  ) then
    raise exception 'AUDIOBOOK_NOT_SUBMITTABLE';
  end if;

  select count(*) into v_count
  from public.tgg_audiobook_chapters
  where audiobook_id=p_audiobook_id;

  if v_count<1 then raise exception 'AUDIOBOOK_CHAPTER_REQUIRED'; end if;

  update public.tgg_audiobooks
  set status='pending',visibility='private',admin_note=null,updated_at=now()
  where id=p_audiobook_id;

  return jsonb_build_object(
    'ok',true,
    'audiobook_id',p_audiobook_id,
    'status','pending',
    'chapter_count',v_count
  );
end
$function$


-- [40000000251] function private.tgg_submit_merch(p_product_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_submit_merch(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_creator uuid;
  v_status text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;

  select a.id,mp.status
    into v_creator,v_status
  from public.merch_products mp
  join public.artists a on a.id=mp.creator_id
  where mp.id=p_product_id
    and a.user_id=auth.uid()
  for update;

  if v_creator is null then raise exception 'MERCH_NOT_FOUND_OR_NOT_OWNER'; end if;
  if v_status not in ('draft','changes_requested') then raise exception 'INVALID_STATUS'; end if;

  update public.merch_products
  set status='pending',admin_note=null
  where id=p_product_id;

  return jsonb_build_object('ok',true,'product_id',p_product_id,'status','pending');
end
$function$


-- [40000000252] function private.tgg_submit_mixtape(p_mixtape_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_submit_mixtape(p_mixtape_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_artist_id uuid;
  v_status text;
  v_track_count integer;
  v_protected_count integer;
begin
  if v_user_id is null then raise exception 'AUTH_REQUIRED'; end if;

  select a.id into v_artist_id
  from public.artists a
  where a.user_id=v_user_id
  limit 1;

  if v_artist_id is null then raise exception 'ARTIST_PROFILE_NOT_FOUND'; end if;

  select status::text into v_status
  from public.mixtapes
  where id=p_mixtape_id and artist_id=v_artist_id
  for update;

  if v_status is null then raise exception 'RELEASE_NOT_OWNED'; end if;
  if v_status not in ('draft','changes_requested','rejected') then
    raise exception 'INVALID_SUBMISSION_STATUS';
  end if;

  select count(*)::integer,
         count(*) filter (
           where audio_path is not null and btrim(audio_path) <> ''
         )::integer
    into v_track_count, v_protected_count
  from public.tracks
  where mixtape_id=p_mixtape_id
    and artist_id=v_artist_id;

  if v_track_count < 1 then raise exception 'TRACK_REQUIRED'; end if;
  if v_protected_count <> v_track_count then raise exception 'PROTECTED_AUDIO_REQUIRED'; end if;

  update public.mixtapes
  set status='pending',
      admin_note=null
  where id=p_mixtape_id and artist_id=v_artist_id;

  return jsonb_build_object(
    'ok',true,'mixtape_id',p_mixtape_id,'status','pending','track_count',v_track_count
  );
end
$function$


-- [40000000253] function private.tgg_submit_promotion(p_campaign_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_submit_promotion(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_creator uuid;
  v_status text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;

  select a.id into v_creator
  from public.artists a
  where a.user_id=auth.uid();

  if v_creator is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

  select status into v_status
  from public.promotion_campaigns
  where id=p_campaign_id
    and creator_id=v_creator
  for update;

  if not found then raise exception 'CAMPAIGN_NOT_FOUND'; end if;
  if v_status not in ('draft','rejected') then raise exception 'INVALID_STATUS'; end if;

  update public.promotion_campaigns
  set status='pending',admin_note=null,updated_at=now()
  where id=p_campaign_id;

  return jsonb_build_object('ok',true,'campaign_id',p_campaign_id,'status','pending');
end
$function$


