-- [40000000255] function private.tgg_sync_creator_action_notifications()
CREATE OR REPLACE FUNCTION private.tgg_sync_creator_action_notifications()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_count integer:=0;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  insert into public.tgg_creator_digest_preferences(user_id)
  values(v_uid)
  on conflict(user_id) do nothing;

  insert into public.notifications(
    recipient_id,actor_id,notification_type,entity_type,entity_id,title,body
  )
  select
    q.owner_user_id,null,'creator_action','creator_action',q.id,
    'Creator action: '||q.title,q.rationale
  from public.tgg_creator_action_queue q
  join public.tgg_creator_digest_preferences p on p.user_id=q.owner_user_id
  where q.owner_user_id=v_uid
    and q.status='open'
    and p.action_alerts_enabled
    and q.priority>=p.minimum_priority
    and not exists (
      select 1
      from public.notifications n
      where n.recipient_id=q.owner_user_id
        and n.notification_type='creator_action'
        and n.entity_id=q.id
    );

  get diagnostics v_count=row_count;
  return v_count;
end
$function$


-- [40000000256] function private.tgg_sync_creator_ownership()
CREATE OR REPLACE FUNCTION private.tgg_sync_creator_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare aid uuid; auid uuid;
begin
  if TG_TABLE_NAME in ('mixtapes','tracks','products') then
    if NEW.user_id is not null and NEW.artist_id is null then
      select a.id into aid from public.artists a where a.user_id=NEW.user_id order by a.created_at asc limit 1;
      NEW.artist_id:=aid;
    elsif NEW.user_id is null and NEW.artist_id is not null then
      select a.user_id into auid from public.artists a where a.id=NEW.artist_id limit 1;
      NEW.user_id:=auid;
    end if;
  elsif TG_TABLE_NAME='merch_products' then
    if NEW.user_id is not null and NEW.creator_id is null then
      select a.id into aid from public.artists a where a.user_id=NEW.user_id order by a.created_at asc limit 1;
      NEW.creator_id:=aid;
    elsif NEW.user_id is null and NEW.creator_id is not null then
      select a.user_id into auid from public.artists a where a.id=NEW.creator_id limit 1;
      NEW.user_id:=auid;
    end if;
  end if;
  return NEW;
end;
$function$


