-- [40000000258] function private.tgg_sync_media_published()
CREATE OR REPLACE FUNCTION private.tgg_sync_media_published()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if NEW.status is distinct from OLD.status or TG_OP='INSERT' then
    NEW.published := (NEW.status='published');
  elsif NEW.published is distinct from OLD.published then
    NEW.status := case when NEW.published then 'published' else 'draft' end;
  end if;
  return NEW;
end;
$function$


-- [40000000259] function private.tgg_sync_membership_webhook_revenue()
CREATE OR REPLACE FUNCTION private.tgg_sync_membership_webhook_revenue()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_artist uuid;
begin
  if new.handled_kind<>'membership_payment_link' then
    return new;
  end if;

  begin
    v_artist := nullif(new.result->>'artist_id','')::uuid;
  exception when others then
    v_artist := null;
  end;

  if v_artist is null or coalesce(new.amount,0)<=0 then
    return new;
  end if;

  insert into public.tgg_revenue_events(
    artist_id,source_kind,source_id,external_id,amount_cents,currency,status,test_mode,occurred_at,metadata,updated_at
  )
  values(
    v_artist,
    'membership_payment',
    new.stripe_event_id,
    coalesce(new.payment_intent_id,new.checkout_session_id),
    greatest(coalesce(new.amount,0),0),
    upper(coalesce(new.currency,'USD')),
    'paid',
    not coalesce(new.livemode,false)
      or coalesce(new.checkout_session_id,'') like 'cs_test_%',
    coalesce(new.created_at,now()),
    coalesce(new.result,'{}'::jsonb) || jsonb_build_object(
      'event_type',new.event_type,
      'checkout_session_id',new.checkout_session_id,
      'payment_intent_id',new.payment_intent_id
    ),
    now()
  )
  on conflict(source_kind,source_id) do update set
    external_id=excluded.external_id,
    amount_cents=excluded.amount_cents,
    currency=excluded.currency,
    status=excluded.status,
    test_mode=excluded.test_mode,
    metadata=excluded.metadata,
    updated_at=now();

  return new;
end;
$function$


-- [40000000260] function private.tgg_sync_merch_order_revenue()
CREATE OR REPLACE FUNCTION private.tgg_sync_merch_order_revenue()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.tgg_revenue_events(
    artist_id,source_kind,source_id,external_id,amount_cents,currency,status,test_mode,occurred_at,metadata,updated_at
  )
  values(
    new.creator_id,
    'merch_order',
    new.id::text,
    coalesce(new.payment_intent_id,new.checkout_session_id),
    greatest(coalesce(new.amount_total,0)-coalesce(new.refunded_amount,0),0),
    upper(coalesce(new.currency,'USD')),
    case
      when coalesce(new.refunded_amount,0)>=coalesce(new.amount_total,0) and coalesce(new.amount_total,0)>0 then 'refunded'
      else coalesce(new.status,'pending')
    end,
    coalesce(new.checkout_session_id,'') like 'cs_test_%',
    coalesce(new.created_at,now()),
    jsonb_build_object(
      'product_id',new.product_id,
      'quantity',new.quantity,
      'checkout_session_id',new.checkout_session_id,
      'payment_intent_id',new.payment_intent_id
    ),
    now()
  )
  on conflict(source_kind,source_id) do update set
    external_id=excluded.external_id,
    amount_cents=excluded.amount_cents,
    currency=excluded.currency,
    status=excluded.status,
    test_mode=excluded.test_mode,
    metadata=excluded.metadata,
    updated_at=now();
  return new;
end;
$function$


-- [40000000261] function private.tgg_sync_provider_handoff_status()
CREATE OR REPLACE FUNCTION private.tgg_sync_provider_handoff_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_stripe_ready boolean:=false;
  v_dsp_ready boolean:=false;
  v_broadcast_ready boolean:=false;
  v_calls_validated boolean:=false;
  v_blogger_ready boolean:=false;
  v_runtime_version integer;
begin
  select nullif(m#>>'{runtime,edge_version}','')::integer
  into v_runtime_version
  from (select public.tgg_v5000_production_manifest() as m) q;

  select coalesce(enabled,false) and coalesce(endpoint_configured,false) and mode='production'
  into v_stripe_ready
  from public.tgg_provider_runtime_config
  where provider_key='stripe';

  select coalesce(bool_or(coalesce(enabled,false) and coalesce(endpoint_configured,false)),false)
  into v_dsp_ready
  from public.tgg_provider_runtime_config
  where provider_key in ('distribution.provider','distribution.provider');

  select coalesce((public.tgg_broadcast_engine_health()->>'sfu_connected')::boolean,false)
  into v_broadcast_ready;

  select coalesce((public.tgg_call_validation_final_health()->>'validated')::boolean,false)
  into v_calls_validated;

  select coalesce(status='connected' and revoked_at is null and coalesce(last_error,'')<>'google_oauth_invalid_grant',false)
  into v_blogger_ready
  from public.v98_blogger_connections
  where blog_url='https://trugogettamixtapes.blogspot.com/'
  order by updated_at desc
  limit 1;

  update public.tgg_provider_handoff
  set status=case when v_stripe_ready then 'complete' else 'external_action_required' end,
      updated_at=now(),
      notes=coalesce(notes,'{}'::jsonb)||jsonb_build_object('auto_detected_complete',v_stripe_ready,'last_auto_check',now())
  where provider_key='stripe.native';

  update public.tgg_provider_handoff
  set status=case when v_dsp_ready then 'complete' else 'provider_delivery_required' end,
      updated_at=now(),
      notes=coalesce(notes,'{}'::jsonb)||jsonb_build_object('auto_detected_complete',v_dsp_ready,'last_auto_check',now(),'creator_os_version',v_runtime_version)
  where provider_key='distribution.provider';

  update public.tgg_provider_handoff
  set status=case when v_broadcast_ready then 'complete' else 'scale_provider_required' end,
      updated_at=now(),
      notes=coalesce(notes,'{}'::jsonb)||jsonb_build_object('auto_detected_complete',v_broadcast_ready,'last_auto_check',now(),'creator_os_version',v_runtime_version)
  where provider_key='broadcast.sfu_turn';

  update public.tgg_provider_handoff
  set status=case when v_calls_validated then 'complete' else 'validation_required' end,
      updated_at=now(),
      notes=coalesce(notes,'{}'::jsonb)||jsonb_build_object('auto_detected_complete',v_calls_validated,'last_auto_check',now(),'creator_os_version',v_runtime_version)
  where provider_key='calls.two_user_validation';

  update public.tgg_provider_handoff
  set status=case when v_blogger_ready then 'complete' else 'reauthorization_required' end,
      required_action=case
        when v_blogger_ready then 'Blogger OAuth is connected and healthy. No reauthorization action is required.'
        else 'Reauthorize Blogger OAuth through the existing v98-blogger-connector. The public site remains live; this restores authenticated maintenance/deploy access.'
      end,
      updated_at=now(),
      notes=(coalesce(notes,'{}'::jsonb) - 'action_url' - 'action_label')
        || case when v_blogger_ready then '{}'::jsonb else jsonb_build_object(
          'action_url','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/v98-blogger-connector',
          'action_label','Reconnect Blogger'
        ) end
        || jsonb_build_object('auto_detected_complete',v_blogger_ready,'last_auto_check',now())
  where provider_key='blogger.oauth';

  return jsonb_build_object(
    'stripe_native',v_stripe_ready,
    'distribution_provider',v_dsp_ready,
    'broadcast_sfu_turn',v_broadcast_ready,
    'calls_two_user_validated',v_calls_validated,
    'blogger_oauth',v_blogger_ready,
    'generated_at',now()
  );
end;
$function$


-- [40000000262] function private.tgg_sync_public_artist_directory()
CREATE OR REPLACE FUNCTION private.tgg_sync_public_artist_directory()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op='DELETE' then
    delete from public.public_artist_directory_v1
    where artist_id=old.id;
    return old;
  end if;

  insert into public.public_artist_directory_v1(
    artist_id,user_id,stage_name,bio,avatar_url,instagram,website,youtube,soundcloud,spotify,created_at,updated_at
  )
  values(
    new.id,new.user_id,new.stage_name,new.bio,new.avatar_url,new.instagram,new.website,new.youtube,new.soundcloud,new.spotify,new.created_at,now()
  )
  on conflict (artist_id) do update
  set user_id=excluded.user_id,
      stage_name=excluded.stage_name,
      bio=excluded.bio,
      avatar_url=excluded.avatar_url,
      instagram=excluded.instagram,
      website=excluded.website,
      youtube=excluded.youtube,
      soundcloud=excluded.soundcloud,
      spotify=excluded.spotify,
      created_at=excluded.created_at,
      updated_at=now();

  return new;
end;
$function$


-- [40000000263] function private.tgg_sync_public_artist_follow_count()
CREATE OR REPLACE FUNCTION private.tgg_sync_public_artist_follow_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='DELETE' then
    perform private.tgg_refresh_public_artist_follow_count(old.artist_id);
    return old;
  elsif tg_op='UPDATE' then
    perform private.tgg_refresh_public_artist_follow_count(old.artist_id);
    if new.artist_id is distinct from old.artist_id then
      perform private.tgg_refresh_public_artist_follow_count(new.artist_id);
    end if;
    return new;
  else
    perform private.tgg_refresh_public_artist_follow_count(new.artist_id);
    return new;
  end if;
end
$function$


-- [40000000264] function private.tgg_sync_public_membership_tier()
CREATE OR REPLACE FUNCTION private.tgg_sync_public_membership_tier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_stage_name text;
begin
  if tg_op='DELETE' then
    delete from public.public_membership_tiers_directory_v1
    where tier_id=old.id;
    return old;
  end if;

  if new.is_active
     and new.stripe_payment_link_verified
     and nullif(btrim(coalesce(new.stripe_payment_link_url,'')),'') is not null
  then
    select stage_name into v_stage_name
    from public.artists
    where id=new.artist_id;

    insert into public.public_membership_tiers_directory_v1(
      tier_id,artist_id,stage_name,name,description,price_cents,
      benefits,checkout_url,created_at,updated_at
    )
    values(
      new.id,new.artist_id,v_stage_name,new.name,new.description,new.price_cents,
      coalesce(new.benefits,'[]'::jsonb),new.stripe_payment_link_url,
      new.created_at,now()
    )
    on conflict(tier_id) do update
    set artist_id=excluded.artist_id,
        stage_name=excluded.stage_name,
        name=excluded.name,
        description=excluded.description,
        price_cents=excluded.price_cents,
        benefits=excluded.benefits,
        checkout_url=excluded.checkout_url,
        created_at=excluded.created_at,
        updated_at=now();
  else
    delete from public.public_membership_tiers_directory_v1
    where tier_id=new.id;
  end if;

  return new;
end
$function$


