-- [40000000270] function private.tgg_sync_support_transaction_revenue()
CREATE OR REPLACE FUNCTION private.tgg_sync_support_transaction_revenue()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.tgg_revenue_events(
    artist_id,source_kind,source_id,external_id,amount_cents,currency,status,test_mode,occurred_at,metadata,updated_at
  )
  values(
    new.artist_id,
    'support_transaction',
    new.id::text,
    coalesce(new.stripe_payment_intent_id,new.stripe_checkout_session_id,new.stripe_subscription_id),
    greatest(coalesce(new.amount_cents,0),0),
    upper(coalesce(new.currency,'USD')),
    coalesce(new.status,'pending'),
    coalesce(new.stripe_checkout_session_id,'') like 'cs_test_%'
      or coalesce((new.metadata->>'test_mode')::boolean,false),
    coalesce(new.paid_at,new.created_at,now()),
    coalesce(new.metadata,'{}'::jsonb) || jsonb_build_object(
      'transaction_type',new.transaction_type,
      'platform_fee_cents',new.platform_fee_cents
    ),
    now()
  )
  on conflict(source_kind,source_id) do update set
    external_id=excluded.external_id,
    amount_cents=excluded.amount_cents,
    currency=excluded.currency,
    status=excluded.status,
    test_mode=excluded.test_mode,
    occurred_at=excluded.occurred_at,
    metadata=excluded.metadata,
    updated_at=now();
  return new;
end;
$function$


-- [40000000271] function private.tgg_sync_video_project_duration()
CREATE OR REPLACE FUNCTION private.tgg_sync_video_project_duration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_project_id uuid;
begin
 v_project_id:=coalesce(new.project_id,old.project_id);
 update public.tgg_creative_projects
 set duration_seconds=coalesce((select max(t.start_seconds+t.duration_seconds) from public.tgg_video_timeline_items t where t.project_id=v_project_id),0),updated_at=now()
 where id=v_project_id and project_type='video';
 return coalesce(new,old);
end$function$


-- [40000000272] function private.tgg_track_access_policy(p_track_id uuid, p_mode text)
CREATE OR REPLACE FUNCTION private.tgg_track_access_policy(p_track_id uuid, p_mode text DEFAULT 'stream'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  t public.tracks%rowtype;
  m public.mixtapes%rowtype;
  u uuid := auth.uid();
  email_confirmed timestamptz;
begin
  if p_mode not in ('stream','download') then raise exception 'INVALID_ACCESS_MODE' using errcode='22023'; end if;
  select * into t from public.tracks where id=p_track_id;
  if not found then raise exception 'TRACK_NOT_FOUND' using errcode='P0002'; end if;
  select * into m from public.mixtapes where id=t.mixtape_id;
  if not found then raise exception 'MIXTAPE_NOT_FOUND' using errcode='P0002'; end if;
  if m.status::text <> 'published' then raise exception 'MIXTAPE_NOT_PUBLISHED' using errcode='42501'; end if;
  if t.audio_path is null or btrim(t.audio_path)='' then raise exception 'AUDIO_PATH_NOT_CONFIGURED' using errcode='22023'; end if;
  if p_mode='download' then
    if t.download_policy='stream_only' then raise exception 'DOWNLOAD_NOT_ALLOWED' using errcode='42501';
    elsif t.download_policy='account_required' and u is null then raise exception 'ACCOUNT_REQUIRED' using errcode='42501';
    elsif t.download_policy='email_required' then
      if u is null then raise exception 'ACCOUNT_REQUIRED' using errcode='42501'; end if;
      select email_confirmed_at into email_confirmed from auth.users where id=u;
      if email_confirmed is null then raise exception 'VERIFIED_EMAIL_REQUIRED' using errcode='42501'; end if;
    end if;
  end if;
  return jsonb_build_object('track_id',t.id,'mixtape_id',t.mixtape_id,'audio_path',t.audio_path,'download_policy',t.download_policy,'mode',p_mode,'user_id',u);
end;
$function$


-- [40000000273] function private.tgg_track_activation_state_changes()
CREATE OR REPLACE FUNCTION private.tgg_track_activation_state_changes()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_changed integer:=0;
begin
  with latest as (
    select distinct on (item_key)
      item_key,new_status
    from private.tgg_activation_state_history
    order by item_key,changed_at desc,id desc
  ),
  current_state as (
    select item_key,status,evidence
    from private.tgg_one_final_activation_queue
  ),
  changed as (
    select
      c.item_key,
      l.new_status as old_status,
      c.status as new_status,
      c.evidence
    from current_state c
    left join latest l using(item_key)
    where l.item_key is null
       or l.new_status is distinct from c.status
  )
  insert into private.tgg_activation_state_history(
    item_key,old_status,new_status,evidence
  )
  select item_key,old_status,new_status,evidence
  from changed;

  get diagnostics v_changed=row_count;

  return jsonb_build_object(
    'ok',true,
    'version','ACTIVATION-HISTORY-ONE-FINAL-1.0',
    'changes_recorded',v_changed,
    'generated_at',now()
  );
end
$function$


-- [40000000274] function private.tgg_trigger_blogger_live_monitor()
CREATE OR REPLACE FUNCTION private.tgg_trigger_blogger_live_monitor()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text;
  v_request_id bigint;
  v_status text;
  v_revoked_at timestamptz;
  v_baseline_version text;
begin
  select version into v_baseline_version
  from public.tgg_production_baselines
  where status='locked'
  order by locked_at desc
  limit 1;

  select status,revoked_at into v_status,v_revoked_at
  from public.v98_blogger_connections
  where blog_url='https://trugogettamixtapes.blogspot.com/'
  order by updated_at desc
  limit 1;

  if coalesce(v_status,'')<>'connected' or v_revoked_at is not null then
    update public.tgg_production_baselines
    set notes = notes || jsonb_build_object(
      'blogger_hash_monitor_runtime',
      jsonb_build_object('status','paused_oauth_unavailable','connection_status',v_status,'revoked_at',v_revoked_at,'checked_at',now())
    )
    where version=v_baseline_version;
    return 0;
  end if;

  select monitor_token into v_token
  from public.tgg_blogger_monitor_runtime
  where id=1 and active=true;
  if v_token is null then raise exception 'blogger_monitor_runtime_unavailable'; end if;

  select net.http_post(
    url := 'https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-tmp-video-page-scan',
    body := '{}'::jsonb,
    params := '{}'::jsonb,
    headers := jsonb_build_object('Content-Type','application/json','x-tgg-monitor-token',v_token),
    timeout_milliseconds := 120000
  ) into v_request_id;
  return v_request_id;
end;
$function$


-- [40000000275] function private.tgg_trigger_pending_blogger_patches()
CREATE OR REPLACE FUNCTION private.tgg_trigger_pending_blogger_patches()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text;
  v_status text;
  v_revoked timestamptz;
  v_pending integer;
  v_request bigint;
begin
  select status,revoked_at into v_status,v_revoked
  from public.v98_blogger_connections
  where blog_url='https://trugogettamixtapes.blogspot.com/'
  order by updated_at desc
  limit 1;

  select count(*) into v_pending
  from public.tgg_blogger_pending_patches
  where status='staged';

  if v_pending=0
     or coalesce(v_status,'')<>'connected'
     or v_revoked is not null
  then
    return 0;
  end if;

  select monitor_token into v_token
  from public.tgg_blogger_monitor_runtime
  where id=1 and active=true;

  if v_token is null then
    return 0;
  end if;

  select net.http_post(
    url:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-final-batch-deploy',
    body:='{}'::jsonb,
    params:='{}'::jsonb,
    headers:=jsonb_build_object(
      'Content-Type','application/json',
      'x-tgg-monitor-token',v_token
    ),
    timeout_milliseconds:=120000
  )
  into v_request;

  return v_request;
end
$function$


-- [40000000276] function private.tgg_unified_version_refresh(p_creator_os_version integer, p_creator_os_sha256 text, p_public_shell_version integer, p_public_shell_sha256 text)
CREATE OR REPLACE FUNCTION private.tgg_unified_version_refresh(p_creator_os_version integer DEFAULT NULL::integer, p_creator_os_sha256 text DEFAULT NULL::text, p_public_shell_version integer DEFAULT NULL::integer, p_public_shell_sha256 text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_prev jsonb:=coalesce((select details from public.tgg_operational_recovery_checkpoints where checkpoint_key='unified_version_manifest'),'{}'::jsonb);
  v_growth jsonb:=coalesce((select details from public.tgg_operational_recovery_checkpoints where checkpoint_key='growth_v1_launch'),'{}'::jsonb);
  v_migration jsonb;
  v_closeout jsonb:=coalesce((select details from public.tgg_operational_recovery_checkpoints where checkpoint_key='production_build_closeout'),'{}'::jsonb);
  v_builder text;
  v_creator integer;
  v_creator_sha text;
  v_shell integer;
  v_shell_sha text;
  v_brain text;
  v_dependency_state text;
  v_dependency_failures integer:=0;
  v_open_alerts integer:=0;
  v_drift jsonb;
  v_cron jsonb;
  v_manifest jsonb;
  v_watchdog_schedule text;
begin
  perform private.tgg_refresh_migration_hygiene_runtime_inventory();
  perform private.tgg_operational_dependency_check();
  perform private.tgg_operational_record_cron_slo();
  perform private.tgg_operational_evaluate_alerts();

  select details into v_migration from public.tgg_operational_recovery_checkpoints where checkpoint_key='migration_hygiene_live';

  select coalesce(last_cycle_result->>'canonical_source_version',last_cycle_result->'speed_booster'->>'canonical_source_version','V223')
  into v_builder from public.tgg_autobuilder_controller where id=1;

  v_creator:=coalesce(
    p_creator_os_version,
    nullif(v_prev#>>'{runtime,creator_os,version}','')::integer,
    nullif(v_growth->>'creator_os_version','')::integer,
    nullif(v_closeout->>'creator_os_edge_runtime','')::integer,
    161
  );
  v_creator_sha:=coalesce(nullif(p_creator_os_sha256,''),nullif(v_prev#>>'{runtime,creator_os,sha256}',''),nullif(v_closeout->>'creator_os_edge_sha256',''),'');
  v_shell:=coalesce(
    p_public_shell_version,
    nullif(v_prev#>>'{runtime,public_shell,version}','')::integer,
    nullif(v_growth->>'public_shell_fan_pwa_version','')::integer,
    16
  );
  v_shell_sha:=coalesce(nullif(p_public_shell_sha256,''),nullif(v_prev#>>'{runtime,public_shell,sha256}',''),''); 

  select version_key into v_brain
  from public.tgg_brain_versions
  where status='active'
  order by activated_at desc nulls last,created_at desc
  limit 1;

  select state,failed_count into v_dependency_state,v_dependency_failures
  from public.tgg_operational_dependency_checks
  where check_key='active-runtime-dependencies';

  select count(*) into v_open_alerts from public.tgg_operational_alerts where status<>'resolved';
  v_drift:=public.tgg_get_production_drift();

  select schedule into v_watchdog_schedule
  from cron.job
  where jobname='tgg-autobuilder-continuous-watchdog' and active=true
  order by jobid desc
  limit 1;

  select jsonb_build_object(
    'health',health,'availability_pct',availability_pct,'failure_count',failure_count,'snapshot_at',snapshot_at
  )
  into v_cron
  from public.tgg_operational_slo_snapshots
  where subsystem='pg_cron_runtime'
  order by snapshot_at desc
  limit 1;

  v_manifest:=jsonb_build_object(
    'version','UNIFIED-UPGRADE-MANIFEST-1.0',
    'platform_version','V5000',
    'canonical_release','V5000',
    'autobuilder_source_version',coalesce(v_builder,'V223'),
    'canonical_boundary','AB-006',
    'runtime',jsonb_build_object(
      'creator_os',jsonb_build_object('function','tgg-creator-os-app-v17','version',v_creator,'sha256',v_creator_sha,'status','ACTIVE'),
      'public_shell',jsonb_build_object('function','tgg-public-shell','version',v_shell,'sha256',v_shell_sha,'status','ACTIVE')
    ),
    'components',jsonb_build_object(
      'growth',jsonb_build_object(
        'component_version',v_growth->>'component_version',
        'autopilot_version',v_growth->>'growth_autopilot_version',
        'weekly_version',v_growth->>'growth_weekly_missions_version',
        'coach_version',v_growth->>'growth_coach_version',
        'brain_version',v_growth->>'growth_brain_version',
        'forecast_version',v_growth->>'growth_forecast_version',
        'attribution_version',v_growth->>'growth_attribution_funnel_version',
        'audience_intelligence_version',v_growth->>'growth_audience_intelligence_version',
        'fan_pwa_version',v_growth->>'public_fan_pwa_version',
        'the_one_version',v_growth->>'the_one_model_version'
      ),
      'brain',coalesce(v_brain,'TGG-BRAIN-1.0'),
      'schema_attestation',v_migration->>'schema_attestation_version',
      'route_baseline',v_drift->>'baseline'
    ),
    'automation',jsonb_build_object(
      'enabled',true,
      'watchdog_job','tgg-autobuilder-continuous-watchdog',
      'watchdog_schedule',coalesce(v_watchdog_schedule,'not_scheduled'),
      'safe_auto_claim',true,
      'adaptive_batching',true,
      'production_auto_publish',false,
      'high_risk_auto_execute',false,
      'external_credentials_auto_created',false,
      'approval_gates_preserved',true
    ),
    'health',jsonb_build_object(
      'dependency_state',v_dependency_state,
      'dependency_failures',coalesce(v_dependency_failures,0),
      'open_alerts',v_open_alerts,
      'production_drift_count',coalesce((v_drift->>'drift_count')::integer,0),
      'cron',coalesce(v_cron,'{}'::jsonb),
      'production_build_status',v_closeout->>'status'
    ),
    'auto_refresh',true,
    'refreshed_at',now()
  );

  insert into public.tgg_operational_recovery_checkpoints(checkpoint_key,state,source,details)
  values(
    'unified_version_manifest',
    case when coalesce(v_dependency_failures,0)=0 and v_open_alerts=0 and coalesce((v_drift->>'drift_count')::integer,0)=0 then 'ready' else 'degraded' end,
    'private.tgg_unified_version_refresh',
    v_manifest
  )
  on conflict(checkpoint_key) do update
  set state=excluded.state,source=excluded.source,details=excluded.details;

  update public.tgg_operational_recovery_checkpoints
  set details=details||jsonb_build_object(
    'creator_os_version',v_creator,
    'current_creator_os_runtime',v_creator,
    'current_creator_os_sha256',v_creator_sha,
    'current_public_shell_runtime',v_shell,
    'current_public_shell_sha256',v_shell_sha,
    'unified_upgrade_manifest','UNIFIED-UPGRADE-MANIFEST-1.0',
    'unified_upgrade_refreshed_at',now()
  )
  where checkpoint_key='growth_v1_launch';

  update public.tgg_operational_recovery_checkpoints
  set details=details||jsonb_build_object(
    'creator_os_edge_runtime',v_creator,
    'creator_os_edge_sha256',v_creator_sha,
    'current_creator_os_runtime',v_creator,
    'current_public_shell_runtime',v_shell,
    'current_builder_source_version',coalesce(v_builder,'V223'),
    'unified_upgrade_manager_ready',true,
    'unified_upgrade_refreshed_at',now()
  )
  where checkpoint_key='production_build_closeout';

  update public.tgg_operational_recovery_checkpoints
  set details=details||jsonb_build_object(
    'current_creator_os_runtime',v_creator,
    'current_creator_os_sha256',v_creator_sha,
    'current_public_shell_runtime',v_shell,
    'current_public_shell_sha256',v_shell_sha,
    'current_builder_source_version',coalesce(v_builder,'V223'),
    'unified_upgrade_manifest','UNIFIED-UPGRADE-MANIFEST-1.0',
    'unified_upgrade_refreshed_at',now()
  )
  where checkpoint_key='migration_hygiene_live';

  return v_manifest;
end
$function$


-- [40000000277] function private.tgg_unified_version_status_impl()
CREATE OR REPLACE FUNCTION private.tgg_unified_version_status_impl()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    (select details from public.tgg_operational_recovery_checkpoints where checkpoint_key='unified_version_manifest'),
    '{}'::jsonb
  );
$function$


-- [40000000278] function private.tgg_validate_merch_checkout_path()
CREATE OR REPLACE FUNCTION private.tgg_validate_merch_checkout_path()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_native_ready boolean:=false;
begin
  if new.status='published' then
    select coalesce(enabled,false)
      and mode='production'
      and coalesce(endpoint_configured,false)
    into v_native_ready
    from public.tgg_provider_runtime_config
    where provider_key='stripe'
    limit 1;

    if not coalesce(v_native_ready,false)
       and nullif(btrim(coalesce(new.stripe_payment_link_url,'')),'') is null
    then
      raise exception 'published product requires an active checkout path';
    end if;
  end if;

  return new;
end
$function$


-- [40000000279] function private.tgg_validate_mixtape_publishable()
CREATE OR REPLACE FUNCTION private.tgg_validate_mixtape_publishable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_playable integer:=0;
begin
  if new.status='published'::public.mixtape_status
     and (
       tg_op='INSERT'
       or old.status is distinct from new.status
     )
  then
    select count(*)
    into v_playable
    from public.tracks t
    where t.mixtape_id=new.id
      and (
        (
          nullif(btrim(coalesce(t.audio_path,'')),'') is not null
          and coalesce(t.has_secure_audio,false)=true
        )
        or nullif(btrim(coalesce(t.audio_url,'')),'') is not null
      );

    if v_playable<1 then
      raise exception 'RELEASE_PUBLISH_REQUIRES_PLAYABLE_TRACK'
        using detail='A release must contain at least one playable track before it can be published.';
    end if;
  end if;

  return new;
end
$function$


-- [40000000280] function private.tgg_verify_membership_payment_link(p_tier_id uuid, p_payment_link_url text, p_stripe_product_id text, p_stripe_price_id text)
CREATE OR REPLACE FUNCTION private.tgg_verify_membership_payment_link(p_tier_id uuid, p_payment_link_url text, p_stripe_product_id text, p_stripe_price_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_url text:=nullif(btrim(coalesce(p_payment_link_url,'')),'');
begin
  if v_url is null or v_url !~ '^https://buy\.stripe\.com/' then
    raise exception 'PAYMENT_LINK_URL_INVALID' using errcode='22023';
  end if;

  update public.tgg_membership_tiers
  set
    stripe_payment_link_url=v_url,
    stripe_product_id=nullif(btrim(coalesce(p_stripe_product_id,'')),''),
    stripe_price_id=nullif(btrim(coalesce(p_stripe_price_id,'')),''),
    stripe_payment_link_verified=true,
    stripe_payment_link_verified_at=now(),
    updated_at=now()
  where id=p_tier_id;

  if not found then
    raise exception 'TIER_NOT_FOUND' using errcode='P0001';
  end if;

  return jsonb_build_object(
    'ok',true,
    'tier_id',p_tier_id,
    'payment_link_verified',true,
    'verified_at',now()
  );
end
$function$


-- [40000000281] function private.tgg_video_create(p_title text, p_description text, p_genre text, p_release_date date, p_explicit_content boolean, p_video_url text, p_thumbnail_url text, p_visibility text, p_featured boolean, p_allow_downloads boolean)
CREATE OR REPLACE FUNCTION private.tgg_video_create(p_title text, p_description text DEFAULT NULL::text, p_genre text DEFAULT NULL::text, p_release_date date DEFAULT NULL::date, p_explicit_content boolean DEFAULT false, p_video_url text DEFAULT NULL::text, p_thumbnail_url text DEFAULT NULL::text, p_visibility text DEFAULT 'private'::text, p_featured boolean DEFAULT false, p_allow_downloads boolean DEFAULT false)
 RETURNS public.videos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.videos;
  v_artist_id uuid;
  v_user_id uuid:=auth.uid();
  v_title text:=btrim(coalesce(p_title,''));
  v_description text:=nullif(btrim(coalesce(p_description,'')),'');
  v_genre text:=nullif(btrim(coalesce(p_genre,'')),'');
  v_video_url text:=nullif(btrim(coalesce(p_video_url,'')),'');
  v_thumbnail_url text:=nullif(btrim(coalesce(p_thumbnail_url,'')),'');
begin
  if v_user_id is null then raise exception 'authentication_required'; end if;
  if char_length(v_title)<1 or char_length(v_title)>160 then raise exception 'title_invalid'; end if;
  if v_description is not null and char_length(v_description)>5000 then raise exception 'description_too_long'; end if;
  if v_genre is not null and char_length(v_genre)>120 then raise exception 'genre_too_long'; end if;
  if v_video_url is not null and char_length(v_video_url)>2048 then raise exception 'video_url_too_long'; end if;
  if v_thumbnail_url is not null and char_length(v_thumbnail_url)>2048 then raise exception 'thumbnail_url_too_long'; end if;
  if p_visibility not in ('public','private','unlisted') then raise exception 'invalid_visibility'; end if;

  select a.id into v_artist_id
  from public.artists a
  where a.user_id=v_user_id
  limit 1;

  if v_artist_id is null then raise exception 'creator_profile_required'; end if;

  insert into public.videos(
    artist_id,title,description,genre,release_date,explicit_content,
    video_url,thumbnail_url,visibility,featured,allow_downloads,status
  )
  values(
    v_artist_id,v_title,v_description,v_genre,p_release_date,p_explicit_content,
    coalesce(v_video_url,''),v_thumbnail_url,p_visibility,p_featured,p_allow_downloads,'draft'
  )
  returning * into v;

  insert into public.media_assets(
    id,owner_id,media_type,title,description,source_url,status,visibility,metadata,published_at
  )
  values(
    v.id,v_user_id,'video',v.title,v.description,nullif(v.video_url,''),
    'draft',v.visibility,jsonb_build_object('source','videos','video_id',v.id::text),null
  )
  on conflict(id) do update
  set owner_id=excluded.owner_id,
      title=excluded.title,
      description=excluded.description,
      source_url=excluded.source_url,
      status='draft',
      visibility=excluded.visibility,
      updated_at=now(),
      published_at=null;

  return v;
end
$function$


-- [40000000282] function private.tgg_video_publish(p_video_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_video_publish(p_video_id uuid)
 RETURNS public.videos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
    declare
      v public.videos;
    begin
      if auth.uid() is null then raise exception 'authentication_required'; end if;

      if not exists (
        select 1 from public.profiles p
        where p.id=auth.uid() and p.role='admin'
      ) then
        raise exception 'admin_required';
      end if;

      update public.videos
      set visibility='public',
          status='published',
          release_date=coalesce(release_date,current_date),
          updated_at=now()
      where id=p_video_id
        and status='pending'
        and (
          coalesce(video_url,'') <> ''
          or (storage_bucket is not null and storage_path is not null)
        )
      returning * into v;

      if not found then raise exception 'video_not_pending_or_not_ready'; end if;

      insert into public.media_assets(
        id,owner_id,media_type,title,description,
        storage_bucket,storage_path,source_url,
        status,visibility,metadata,updated_at,published_at
      )
      values(
        v.id,
        (select a.user_id from public.artists a where a.id=v.artist_id limit 1),
        'video',v.title,v.description,
        v.storage_bucket,v.storage_path,nullif(v.video_url,''),
        'published','public',
        jsonb_build_object('source','videos','video_id',v.id::text),
        now(),now()
      )
      on conflict(id) do update
      set owner_id=excluded.owner_id,
          title=excluded.title,
          description=excluded.description,
          storage_bucket=excluded.storage_bucket,
          storage_path=excluded.storage_path,
          source_url=excluded.source_url,
          status='published',
          visibility='public',
          metadata=excluded.metadata,
          updated_at=now(),
          published_at=now();

      return v;
    end
    $function$


-- [40000000283] function private.tgg_video_record_event(p_video_id uuid, p_event_type text, p_watch_seconds numeric, p_event_metadata jsonb)
CREATE OR REPLACE FUNCTION private.tgg_video_record_event(p_video_id uuid, p_event_type text, p_watch_seconds numeric DEFAULT NULL::numeric, p_event_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_asset uuid;
  v_type text:=btrim(coalesce(p_event_type,''));
  v_meta jsonb:=coalesce(p_event_metadata,'{}'::jsonb);
  v_watch numeric:=greatest(coalesce(p_watch_seconds,0),0);
begin
  if auth.uid() is null then raise exception 'authentication_required'; end if;
  if char_length(v_type)<1 or char_length(v_type)>64 then raise exception 'event_type_invalid'; end if;
  if v_watch>86400 then raise exception 'watch_seconds_too_large'; end if;
  if jsonb_typeof(v_meta)<>'object' then raise exception 'event_metadata_invalid'; end if;
  if octet_length(v_meta::text)>8192 then raise exception 'event_metadata_too_large'; end if;

  if not exists(
    select 1 from public.videos
    where id=p_video_id and status='published' and visibility='public'
  ) then
    raise exception 'video_not_public_or_not_found';
  end if;

  select id into v_asset
  from public.media_assets
  where id=p_video_id and media_type='video'
  limit 1;

  if v_asset is null then
    select id into v_asset
    from public.media_assets
    where metadata->>'video_id'=p_video_id::text
      and media_type='video'
    limit 1;
  end if;

  if v_asset is null then raise exception 'video_media_asset_missing'; end if;

  insert into public.video_engagement_events(
    media_asset_id,viewer_id,event_type,watch_seconds,event_metadata
  )
  values(v_asset,auth.uid(),v_type,v_watch,v_meta)
  returning id into v_id;

  if v_type in ('view','play','started') then
    update public.videos
    set play_count=coalesce(play_count,0)+1,
        updated_at=now()
    where id=p_video_id;
  end if;

  return v_id;
end
$function$


-- [40000000284] function private.tgg_video_track_lock_guard()
CREATE OR REPLACE FUNCTION private.tgg_video_track_lock_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=(select auth.uid());
  v_project uuid;
  v_old_track integer;
  v_new_track integer;
begin
  if v_uid is null then return case when tg_op='DELETE' then old else new end; end if;
  if tg_op='INSERT' then
    v_project:=new.project_id; v_new_track:=new.track_index;
    if exists(select 1 from private.tgg_video_studio_track_states s where s.project_id=v_project and s.track_index=v_new_track and s.locked) then
      raise exception 'TRACK_LOCKED:T%',v_new_track using errcode='42501';
    end if;
    return new;
  elsif tg_op='UPDATE' then
    v_project:=old.project_id; v_old_track:=old.track_index; v_new_track:=new.track_index;
    if exists(select 1 from private.tgg_video_studio_track_states s where s.project_id=v_project and s.track_index=v_old_track and s.locked) then
      raise exception 'TRACK_LOCKED:T%',v_old_track using errcode='42501';
    end if;
    if (new.project_id,new.track_index) is distinct from (old.project_id,old.track_index) and exists(select 1 from private.tgg_video_studio_track_states s where s.project_id=new.project_id and s.track_index=v_new_track and s.locked) then
      raise exception 'TRACK_LOCKED:T%',v_new_track using errcode='42501';
    end if;
    return new;
  else
    v_project:=old.project_id; v_old_track:=old.track_index;
    if exists(select 1 from private.tgg_video_studio_track_states s where s.project_id=v_project and s.track_index=v_old_track and s.locked) then
      raise exception 'TRACK_LOCKED:T%',v_old_track using errcode='42501';
    end if;
    return old;
  end if;
end$function$


-- [40000000285] function private.tgg_video_update(p_video_id uuid, p_title text, p_description text, p_genre text, p_release_date date, p_explicit_content boolean, p_thumbnail_url text, p_visibility text, p_featured boolean, p_allow_downloads boolean)
CREATE OR REPLACE FUNCTION private.tgg_video_update(p_video_id uuid, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_genre text DEFAULT NULL::text, p_release_date date DEFAULT NULL::date, p_explicit_content boolean DEFAULT NULL::boolean, p_thumbnail_url text DEFAULT NULL::text, p_visibility text DEFAULT NULL::text, p_featured boolean DEFAULT NULL::boolean, p_allow_downloads boolean DEFAULT NULL::boolean)
 RETURNS public.videos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.videos;
  v_artist_id uuid;
  v_user_id uuid:=auth.uid();
begin
  if v_user_id is null then raise exception 'authentication_required'; end if;

  if p_title is not null and (char_length(btrim(p_title))<1 or char_length(btrim(p_title))>160) then
    raise exception 'title_invalid';
  end if;
  if p_description is not null and char_length(p_description)>5000 then raise exception 'description_too_long'; end if;
  if p_genre is not null and char_length(p_genre)>120 then raise exception 'genre_too_long'; end if;
  if p_thumbnail_url is not null and char_length(p_thumbnail_url)>2048 then raise exception 'thumbnail_url_too_long'; end if;
  if p_visibility is not null and p_visibility not in ('public','private','unlisted') then raise exception 'invalid_visibility'; end if;

  select a.id into v_artist_id
  from public.artists a
  where a.user_id=v_user_id
  limit 1;

  if v_artist_id is null then raise exception 'creator_profile_required'; end if;

  update public.videos
  set title=coalesce(nullif(btrim(p_title),''),title),
      description=coalesce(p_description,description),
      genre=coalesce(p_genre,genre),
      release_date=coalesce(p_release_date,release_date),
      explicit_content=coalesce(p_explicit_content,explicit_content),
      thumbnail_url=coalesce(p_thumbnail_url,thumbnail_url),
      visibility=coalesce(p_visibility,visibility),
      featured=coalesce(p_featured,featured),
      allow_downloads=coalesce(p_allow_downloads,allow_downloads),
      updated_at=now()
  where id=p_video_id
    and artist_id=v_artist_id
    and status in ('draft','changes_requested')
  returning * into v;

  if not found then raise exception 'video_not_editable_or_not_owned'; end if;

  insert into public.media_assets(
    id,owner_id,media_type,title,description,source_url,status,visibility,metadata,updated_at,published_at
  )
  values(
    v.id,v_user_id,'video',v.title,v.description,nullif(v.video_url,''),
    'draft',v.visibility,jsonb_build_object('source','videos','video_id',v.id::text),now(),null
  )
  on conflict(id) do update
  set owner_id=excluded.owner_id,
      title=excluded.title,
      description=excluded.description,
      source_url=excluded.source_url,
      status='draft',
      visibility=excluded.visibility,
      updated_at=now(),
      published_at=null;

  return v;
end
$function$


-- [40000000286] function private.tgg_webpush_bootstrap_service(p_vapid_json text, p_hook_secret text)
CREATE OR REPLACE FUNCTION private.tgg_webpush_bootstrap_service(p_vapid_json text, p_hook_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_vapid text:=nullif(btrim(coalesce(p_vapid_json,'')),'');
  v_hook text:=nullif(btrim(coalesce(p_hook_secret,'')),'');
  v_id uuid;
begin
  if current_user not in ('service_role','postgres') and session_user not in ('service_role','postgres') then
    raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if v_vapid is null or length(v_vapid)>4096 then raise exception 'VAPID_INVALID' using errcode='22023'; end if;
  if v_hook is null or length(v_hook)<32 or length(v_hook)>512 then raise exception 'HOOK_SECRET_INVALID' using errcode='22023'; end if;

  select id into v_id from vault.secrets where name='tgg_webpush_vapid' order by created_at desc limit 1;
  if v_id is null then
    perform vault.create_secret(v_vapid,'tgg_webpush_vapid','TGG Web Push VAPID keypair',null);
  else
    perform vault.update_secret(v_id,v_vapid,'tgg_webpush_vapid','TGG Web Push VAPID keypair',null);
  end if;

  v_id:=null;
  select id into v_id from vault.secrets where name='tgg_webpush_delivery_hook' order by created_at desc limit 1;
  if v_id is null then
    perform vault.create_secret(v_hook,'tgg_webpush_delivery_hook','TGG Web Push internal delivery hook',null);
  else
    perform vault.update_secret(v_id,v_hook,'tgg_webpush_delivery_hook','TGG Web Push internal delivery hook',null);
  end if;

  insert into private.tgg_provider_secret_registry(provider_key,vault_secret_name,status,last_error,stored_by,stored_at,verified_at,updated_at)
  values
    ('webpush.vapid','tgg_webpush_vapid','verified',null,null,now(),now(),now()),
    ('webpush.delivery_hook','tgg_webpush_delivery_hook','verified',null,null,now(),now(),now())
  on conflict(provider_key) do update set
    vault_secret_name=excluded.vault_secret_name,status='verified',last_error=null,verified_at=now(),updated_at=now();

  insert into public.tgg_provider_handoff(
    provider_key,category,status,required_action,safe_fallback,target_runtime,verification_check,notes,updated_at
  )
  values(
    'webpush.background','notifications','complete',
    'Users enable browser notifications per device.',
    'in_app_notifications','tgg-creator-os-app-v17',
    'service_worker + VAPID + notification trigger + Edge sender',
    jsonb_build_object('vapid_private_in_vault',true,'delivery_hook_in_vault',true,'private_material_exposed',false),
    now()
  )
  on conflict(provider_key) do update set
    status='complete',required_action=excluded.required_action,safe_fallback=excluded.safe_fallback,
    target_runtime=excluded.target_runtime,verification_check=excluded.verification_check,notes=excluded.notes,updated_at=now();

  return jsonb_build_object('ok',true,'stored',true,'secret_returned',false);
end
$function$


-- [40000000287] function private.tgg_worker_mark(p_worker text, p_status text, p_detail jsonb)
CREATE OR REPLACE FUNCTION private.tgg_worker_mark(p_worker text, p_status text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  insert into public.tgg_world_worker_health(worker_key,worker_group,last_run_at,last_status,last_detail,run_count,error_count,updated_at)
  values(p_worker,'runtime',now(),p_status,coalesce(p_detail,'{}'::jsonb),1,case when p_status='error' then 1 else 0 end,now())
  on conflict(worker_key) do update
    set last_run_at=now(),
        last_status=p_status,
        last_detail=coalesce(p_detail,'{}'::jsonb),
        run_count=public.tgg_world_worker_health.run_count+1,
        error_count=public.tgg_world_worker_health.error_count + case when p_status='error' then 1 else 0 end,
        updated_at=now();
end;
$function$


-- [40000000288] function private.tgg_world_actions_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_actions_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_character uuid;
  v_location text;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select wc.id,l.location_key
  into v_character,v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.user_id=v_uid and wc.character_status='active'
  limit 1;

  if v_character is null then
    return jsonb_build_object(
      'character_id',null,
      'current_location',null,
      'travel',coalesce((
        select jsonb_agg(jsonb_build_object('location_key',l.location_key,'name',l.name) order by l.name)
        from public.tgg_world_locations l where l.enabled=true
      ),'[]'::jsonb),
      'encounters','[]'::jsonb,
      'active_encounter',null,
      'gigs','[]'::jsonb,
      'challenges','[]'::jsonb
    );
  end if;

  return jsonb_build_object(
    'character_id',v_character,
    'current_location',v_location,
    'travel',coalesce((
      select jsonb_agg(jsonb_build_object('location_key',l.location_key,'name',l.name) order by l.name)
      from public.tgg_world_locations l
      where l.enabled=true
    ),'[]'::jsonb),
    'encounters',coalesce((
      select jsonb_agg(jsonb_build_object(
        'encounter_key',e.encounter_key,
        'title',e.title,
        'npc_key',e.npc_key,
        'location_key',e.location_key
      ) order by e.priority desc,e.title)
      from public.tgg_world_encounter_templates e
      where e.enabled=true and e.location_key=v_location
    ),'[]'::jsonb),
    'active_encounter',(
      select jsonb_build_object(
        'id',ce.id,
        'encounter_key',ce.encounter_key,
        'current_node_key',ce.current_node_key,
        'node',jsonb_build_object(
          'speaker_name',n.speaker_name,
          'text_body',n.text_body,
          'tone',n.tone
        ),
        'choices',coalesce((
          select jsonb_agg(jsonb_build_object(
            'choice_key',c.choice_key,
            'label',c.label,
            'conditions',c.conditions
          ) order by c.choice_order)
          from public.tgg_world_dialogue_choices c
          where c.node_key=ce.current_node_key and c.enabled=true
        ),'[]'::jsonb)
      )
      from public.tgg_world_character_encounters ce
      join public.tgg_world_dialogue_nodes n on n.node_key=ce.current_node_key
      where ce.character_id=v_character and ce.status='active'
      order by ce.started_at desc limit 1
    ),
    'gigs',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',g.id,
        'gig_key',g.gig_key,
        'title',t.title,
        'status',g.status,
        'location_key',t.location_key,
        'expires_at',g.expires_at,
        'progress',g.progress,
        'objectives',t.objectives,
        'rewards',t.rewards,
        'relationship_weight',private.tgg_world_relationship_opportunity_weight(v_character,g.gig_key)
      ) order by
        case when g.status='accepted' then 1 else 0 end desc,
        private.tgg_world_relationship_opportunity_weight(v_character,g.gig_key) desc,
        g.offered_at desc)
      from public.tgg_world_character_gigs g
      join public.tgg_world_gig_templates t on t.gig_key=g.gig_key
      where g.character_id=v_character
        and g.status in ('available','accepted')
        and (g.expires_at is null or g.expires_at>now())
    ),'[]'::jsonb),
    'challenges',coalesce((
      select jsonb_agg(jsonb_build_object(
        'challenge_key',c.challenge_key,
        'display_name',t.display_name,
        'cadence',t.cadence,
        'category',t.category,
        'period_key',c.period_key,
        'progress',c.progress,
        'requirements',t.requirements,
        'rewards',t.rewards
      ) order by t.cadence,t.display_name)
      from public.tgg_world_character_challenges c
      join public.tgg_world_challenge_templates t on t.challenge_key=c.challenge_key
      where c.character_id=v_character and c.status='active'
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000289] function private.tgg_world_activity_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_activity_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_uid uuid := auth.uid(); v_character uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select id into v_character from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if v_character is null then raise exception 'active world character not found'; end if;

  return jsonb_build_object(
    'city_news',coalesce((select jsonb_agg(jsonb_build_object(
      'news_key',n.news_key,'headline',n.headline,'body',n.body,'category',n.category,
      'district_key',n.district_key,'importance',n.importance,'published_at',n.published_at
    ) order by n.importance desc,n.published_at desc)
    from public.tgg_world_city_news n where n.expires_at is null or n.expires_at>now()),'[]'::jsonb),

    'story_queue',coalesce((select jsonb_agg(jsonb_build_object(
      'id',q.id,'rule_key',q.rule_key,'status',q.status,'context',q.context,'queued_at',q.queued_at
    ) order by q.queued_at desc)
    from public.tgg_world_story_generation_queue q where q.character_id=v_character and q.status='queued'),'[]'::jsonb),

    'progression_events',coalesce((select jsonb_agg(jsonb_build_object(
      'id',p.id,'event_type',p.event_type,'source_key',p.source_key,
      'effects',p.processed_effects,'created_at',p.created_at
    ) order by p.created_at desc)
    from (select * from public.tgg_world_progression_event_log where character_id=v_character order by created_at desc limit 25) p),'[]'::jsonb),

    'leaderboards',coalesce((select jsonb_agg(jsonb_build_object(
      'leaderboard_key',l.leaderboard_key,'display_name',l.display_name,
      'latest',(
        select jsonb_build_object('period_key',s.period_key,'ranking',s.ranking,'generated_at',s.generated_at)
        from public.tgg_world_leaderboard_snapshots s
        where s.leaderboard_key=l.leaderboard_key
        order by s.generated_at desc limit 1
      )
    ) order by l.display_name)
    from public.tgg_world_leaderboard_definitions l where l.enabled),'[]'::jsonb),

    'elite_events',coalesce((select jsonb_agg(jsonb_build_object(
      'elite_event_key',e.elite_event_key,'title',e.title,'event_type',e.event_type,
      'location_key',e.location_key,'entry_conditions',e.entry_conditions,'rewards',e.rewards
    ) order by e.prestige_tier,e.title)
    from public.tgg_world_elite_events e where e.enabled),'[]'::jsonb)
  );
end;
$function$


-- [40000000290] function private.tgg_world_apply_consequence_rules(p_character_id uuid, p_trigger_type text, p_trigger_key text, p_source_type text, p_source_id text)
CREATE OR REPLACE FUNCTION private.tgg_world_apply_consequence_rules(p_character_id uuid, p_trigger_type text, p_trigger_key text, p_source_type text, p_source_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_career text;
  v_rule record;
  v_npc text;
  v_standing integer;
  v_loyalty integer;
  v_rivalry integer;
  v_favor_contract text;
  v_favor_gig text;
  v_inserted integer;
  v_count integer:=0;
  v_effects jsonb;
  v_application_id uuid;
  v_rare_gig_bonus numeric:=0;
  v_unlock_encounter text;
  v_unlock_status text;
begin
  if not exists(select 1 from public.world_characters where id=p_character_id) then
    return jsonb_build_object('applied',0,'reason','character_not_found');
  end if;

  select active_career into v_career
  from public.world_characters where id=p_character_id;

  for v_rule in
    select *
    from public.tgg_world_consequence_rules r
    where r.enabled=true
      and r.trigger_type=p_trigger_type
      and r.trigger_key=p_trigger_key
      and (
        not (r.condition ? 'career')
        or r.condition->>'career'=v_career
      )
    order by r.priority desc,r.rule_key
  loop
    if not v_rule.repeatable and exists(
      select 1 from public.tgg_world_consequence_applications a
      where a.character_id=p_character_id and a.rule_key=v_rule.rule_key
    ) then
      continue;
    end if;

    v_application_id:=null;
    insert into public.tgg_world_consequence_applications(
      character_id,rule_key,source_type,source_id,applied_effects,applied_at
    )
    values(
      p_character_id,v_rule.rule_key,p_source_type,p_source_id,v_rule.effects,now()
    )
    on conflict(character_id,rule_key,source_type,source_id) do nothing
    returning id into v_application_id;

    if v_application_id is null then continue; end if;

    v_npc:=nullif(v_rule.effects->>'npc','');
    if v_npc is null or not exists(
      select 1 from public.tgg_world_npc_profiles n where n.npc_key=v_npc
    ) then
      continue;
    end if;

    v_standing:=coalesce((v_rule.effects->>'standing_delta')::integer,0);
    v_loyalty:=coalesce((v_rule.effects->>'loyalty_delta')::integer,0);
    v_rivalry:=coalesce((v_rule.effects->>'rivalry_delta')::integer,0);
    v_favor_contract:=nullif(v_rule.effects->>'favor_contract','');
    v_favor_gig:=nullif(v_rule.effects->>'favor_gig','');
    v_rare_gig_bonus:=greatest(coalesce((v_rule.effects->>'rare_gig_bonus')::numeric,0),0);
    v_unlock_encounter:=nullif(v_rule.effects->>'unlock_encounter','');
    v_unlock_status:=null;

    insert into public.tgg_world_character_npc_standing(
      character_id,npc_key,standing,rivalry,loyalty,
      blocked_opportunities,favored_opportunities,memory,updated_at
    )
    values(
      p_character_id,v_npc,
      greatest(-100,least(100,v_standing)),
      greatest(0,least(100,v_rivalry)),
      greatest(0,least(100,v_loyalty)),
      '[]'::jsonb,
      (
        select coalesce(jsonb_agg(x),'[]'::jsonb)
        from (
          select to_jsonb(v_favor_contract) x where v_favor_contract is not null
          union
          select to_jsonb(v_favor_gig) where v_favor_gig is not null
        ) q
      ),
      jsonb_build_object(
        'last_rule',v_rule.rule_key,
        'last_trigger_type',p_trigger_type,
        'last_trigger_key',p_trigger_key
      ),
      now()
    )
    on conflict(character_id,npc_key) do update
    set standing=greatest(-100,least(100,
          public.tgg_world_character_npc_standing.standing+v_standing)),
        rivalry=greatest(0,least(100,
          public.tgg_world_character_npc_standing.rivalry+v_rivalry)),
        loyalty=greatest(0,least(100,
          public.tgg_world_character_npc_standing.loyalty+v_loyalty)),
        favored_opportunities=(
          select coalesce(jsonb_agg(distinct elem),'[]'::jsonb)
          from jsonb_array_elements(
            public.tgg_world_character_npc_standing.favored_opportunities
            || case when v_favor_contract is null then '[]'::jsonb else jsonb_build_array(v_favor_contract) end
            || case when v_favor_gig is null then '[]'::jsonb else jsonb_build_array(v_favor_gig) end
          ) elem
        ),
        memory=public.tgg_world_character_npc_standing.memory
          || jsonb_build_object(
            'last_rule',v_rule.rule_key,
            'last_trigger_type',p_trigger_type,
            'last_trigger_key',p_trigger_key
          ),
        updated_at=now();

    if v_rare_gig_bonus>0 then
      insert into public.tgg_world_character_modifiers(
        character_id,modifier_key,numeric_value,source_type,source_key,metadata
      )
      values(
        p_character_id,'rare_gig_bonus',v_rare_gig_bonus,
        'consequence_rule',v_application_id::text,
        jsonb_build_object(
          'rule_key',v_rule.rule_key,
          'npc_key',v_npc,
          'source_type',p_source_type,
          'source_id',p_source_id
        )
      )
      on conflict(character_id,modifier_key,source_type,source_key) do nothing;
    end if;

    if v_unlock_encounter is not null then
      v_unlock_status:=case
        when exists(
          select 1 from public.tgg_world_encounter_templates e
          where e.encounter_key=v_unlock_encounter and e.enabled=true
        ) then 'catalog_ready'
        else 'catalog_missing'
      end;

      update public.tgg_world_consequence_applications
      set applied_effects=applied_effects||jsonb_build_object(
        'unlock_encounter_status',v_unlock_status
      )
      where id=v_application_id;

      update public.tgg_world_character_npc_standing
      set memory=memory||jsonb_build_object(
            case when v_unlock_status='catalog_ready'
              then 'unlocked_encounter'
              else 'pending_encounter_unlock'
            end,
            v_unlock_encounter,
            'encounter_unlock_status',
            v_unlock_status
          ),
          updated_at=now()
      where character_id=p_character_id and npc_key=v_npc;
    end if;

    v_count:=v_count+1;
  end loop;

  return jsonb_build_object(
    'applied',v_count,
    'trigger_type',p_trigger_type,
    'trigger_key',p_trigger_key
  );
end;
$function$


-- [40000000291] function private.tgg_world_apply_district_progress(p_character_id uuid, p_location_key text, p_amount integer)
CREATE OR REPLACE FUNCTION private.tgg_world_apply_district_progress(p_character_id uuid, p_location_key text, p_amount integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_district text;
  v_rep integer;
  v_tier integer;
begin
  select district_key into v_district
  from public.tgg_world_locations
  where location_key=p_location_key;

  if v_district is null then
    return jsonb_build_object('updated',false,'reason','district_not_found');
  end if;

  insert into public.tgg_world_character_district_reputation(
    character_id,district_key,reputation,tier,notoriety,metadata,updated_at
  )
  values(
    p_character_id,v_district,greatest(p_amount,0),1,0,'{}'::jsonb,now()
  )
  on conflict(character_id,district_key) do update
  set reputation=greatest(0,public.tgg_world_character_district_reputation.reputation+greatest(p_amount,0)),
      tier=greatest(
        public.tgg_world_character_district_reputation.tier,
        case
          when public.tgg_world_character_district_reputation.reputation+greatest(p_amount,0)>=100 then 4
          when public.tgg_world_character_district_reputation.reputation+greatest(p_amount,0)>=50 then 3
          when public.tgg_world_character_district_reputation.reputation+greatest(p_amount,0)>=20 then 2
          else 1
        end
      ),
      updated_at=now()
  returning reputation,tier into v_rep,v_tier;

  return jsonb_build_object(
    'updated',true,'district_key',v_district,'reputation',v_rep,'tier',v_tier
  );
end;
$function$


-- [40000000292] function private.tgg_world_auto_maintenance()
CREATE OR REPLACE FUNCTION private.tgg_world_auto_maintenance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_expired_listings integer:=0;
  v_rls_missing integer:=0;
  v_direct_dml integer:=0;
  v_private_definer_exposure integer:=0;
  v_public_definers integer:=0;
  v_realtime_missing integer:=0;
  v_module_path_missing integer:=0;
  v_module_sort_collisions integer:=0;
  v_screen_sort_collisions integer:=0;
  v_worker_errors integer:=0;
  v_ok boolean;
  v_detail jsonb;
begin
  v_expired_listings:=private.tgg_world_property_market_expire();

  select count(*) into v_rls_missing
  from pg_catalog.pg_class c
  join pg_catalog.pg_namespace n on n.oid=c.relnamespace
  where n.nspname='public'
    and c.relkind='r'
    and c.relname like 'tgg_world_%'
    and not c.relrowsecurity;

  select count(distinct g.table_name) into v_direct_dml
  from information_schema.role_table_grants g
  where g.table_schema='public'
    and g.table_name like 'tgg_world_%'
    and g.grantee='authenticated'
    and g.privilege_type in ('INSERT','UPDATE','DELETE')
    and g.table_name not in ('tgg_world_phone_state','tgg_world_presence');

  select count(*) into v_private_definer_exposure
  from pg_catalog.pg_proc p
  join pg_catalog.pg_namespace n on n.oid=p.pronamespace
  where n.nspname='private'
    and p.prosecdef
    and p.proname like 'tgg_world_%'
    and (
      has_function_privilege('public',p.oid,'EXECUTE')
      or has_function_privilege('anon',p.oid,'EXECUTE')
    );

  select count(*) into v_public_definers
  from pg_catalog.pg_proc p
  join pg_catalog.pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public'
    and p.prosecdef
    and p.proname like 'tgg_world_%'
    and pg_catalog.has_function_privilege('anon',p.oid,'EXECUTE');

  with expected(table_name) as (
    select unnest(array[
      'live_stream_viewers','live_streams','tgg_call_participants','tgg_call_rooms',
      'tgg_call_signals','tgg_live_chat_messages','tgg_live_guest_requests',
      'tgg_studio_project_presence','tgg_world_character_business_competitions',
      'tgg_world_character_business_operations','tgg_world_character_business_prestige',
      'tgg_world_character_creative_missions','tgg_world_character_elite_events',
      'tgg_world_character_event_state','tgg_world_character_jobs',
      'tgg_world_character_property_upgrades','tgg_world_character_story_state',
      'tgg_world_crew_contract_runs','tgg_world_crew_territories','tgg_world_dynamic_events',
      'tgg_world_incident_occurrences','tgg_world_music_sessions','tgg_world_npc_runtime_state',
      'tgg_world_open_mic_events','tgg_world_open_mic_performances','tgg_world_open_mic_queue',
      'tgg_world_open_mic_reactions','tgg_world_party_invites','tgg_world_presence',
      'tgg_world_property_listings','tgg_world_social_comments','tgg_world_social_reactions',
      'tgg_world_studio_session_members','tgg_world_studio_sessions',
      'tgg_world_vehicle_progression','tgg_world_workouts',
      'tgg_world_character_endgame','tgg_world_crew_activity',
      'tgg_world_npc_memory_events','tgg_world_encounter_choice_log',
      'tgg_world_character_modifiers',
      'tgg_world_character_challenges',
      'tgg_world_career_mission_progress',
      'tgg_world_character_contracts',
      'tgg_world_character_faction_missions',
      'world_parties','world_party_members'
    ]::text[])
  )
  select count(*) into v_realtime_missing
  from expected e
  where not exists(
    select 1
    from pg_catalog.pg_publication_tables p
    where p.pubname='supabase_realtime'
      and p.schemaname='public'
      and p.tablename=e.table_name
  );

  with defs as (
    select string_agg(pg_get_functiondef(p.oid), E'
') as src
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid=p.pronamespace
    where (n.nspname='private' and p.proname='tgg_world_ui_payload')
       or (n.nspname='public' and p.proname='tgg_world_ui_payload')
  ),
  mods as (
    select m.module_key,split_part(m.data_path,'.',1) as top_key
    from public.tgg_world_ui_modules m
    where m.enabled=true
  )
  select count(*) into v_module_path_missing
  from mods m,defs d
  where d.src not like '%'''||replace(m.top_key,'''','''''')||'''%';

  select count(*) into v_module_sort_collisions
  from (
    select screen_key,sort_order
    from public.tgg_world_ui_modules
    where enabled=true
    group by screen_key,sort_order
    having count(*)>1
  ) x;

  select count(*) into v_screen_sort_collisions
  from (
    select sort_order
    from public.tgg_world_ui_screens
    where enabled=true
    group by sort_order
    having count(*)>1
  ) x;

  select count(*) into v_worker_errors
  from public.tgg_world_worker_health
  where worker_key<>'auto-maintenance'
    and last_status='error';

  v_ok := v_rls_missing=0
      and v_direct_dml=0
      and v_private_definer_exposure=0
      and v_public_definers=0
      and v_realtime_missing=0
      and v_module_path_missing=0
      and v_module_sort_collisions=0
      and v_screen_sort_collisions=0
      and v_worker_errors=0;

  v_detail:=jsonb_build_object(
    'ok',v_ok,
    'checked_at',now(),
    'safe_repairs',jsonb_build_object(
      'expired_property_listings_restored',v_expired_listings
    ),
    'checks',jsonb_build_object(
      'world_tables_without_rls',v_rls_missing,
      'unexpected_authenticated_direct_dml_tables',v_direct_dml,
      'private_security_definer_public_or_anon_exposure',v_private_definer_exposure,
      'public_world_security_definer_functions',v_public_definers,
      'missing_realtime_publications',v_realtime_missing,
      'enabled_module_missing_payload_top_key',v_module_path_missing,
      'module_sort_order_collisions',v_module_sort_collisions,
      'screen_sort_order_collisions',v_screen_sort_collisions,
      'worker_errors',v_worker_errors
    ),
    'intentional_direct_write_tables',jsonb_build_array(
      'tgg_world_phone_state','tgg_world_presence'
    ),
    'protected_baseline_mutated',false,
    'real_money_changed',false
  );

  perform private.tgg_worker_mark(
    'auto-maintenance',
    case when v_ok then 'ok' else 'error' end,
    v_detail
  );

  return v_detail;
end
$function$


-- [40000000293] function private.tgg_world_business_competitions_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_business_competitions_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  return jsonb_build_object(
    'character_id',v_char,
    'businesses',coalesce((
      select jsonb_agg(jsonb_build_object(
        'business_id',b.id,
        'business_name',b.business_name,
        'business_type_key',b.business_type_key,
        'business_level',b.business_level,
        'business_xp',b.business_xp,
        'reputation',b.reputation,
        'competitions',coalesce((
          select jsonb_agg(jsonb_build_object(
            'competition_key',c.competition_key,
            'title',c.title,
            'metric_key',c.metric_key,
            'duration_hours',c.duration_hours,
            'rewards',c.rewards,
            'eligible',b.business_type_key=any(c.business_type_keys),
            'run',(
              select jsonb_build_object(
                'id',r.id,'status',r.status,'score',r.score,'result',r.result,
                'started_at',r.started_at,'completed_at',r.completed_at,
                'ready_at',r.started_at+make_interval(hours=>c.duration_hours),
                'ready_to_complete',
                  r.status='running'
                  and now()>=r.started_at+make_interval(hours=>c.duration_hours)
              )
              from public.tgg_world_character_business_competitions r
              where r.business_id=b.id and r.competition_key=c.competition_key
              order by r.updated_at desc limit 1
            )
          ) order by c.duration_hours,c.title)
          from public.tgg_world_business_competitions c
          where c.enabled=true and b.business_type_key=any(c.business_type_keys)
        ),'[]'::jsonb)
      ) order by b.business_level desc,b.business_name)
      from public.tgg_world_character_businesses b
      where b.character_id=v_char and b.status='active'
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000294] function private.tgg_world_business_loop_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_business_loop_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_rep integer:=0;
  v_balance bigint:=0;
  v_price_multiplier numeric:=1;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  perform private.tgg_world_wallet_ensure_impl();

  select balance into v_balance
  from public.tgg_world_wallets
  where user_id=v_uid;

  select greatest(coalesce((value->>'value')::numeric,1),0)
  into v_price_multiplier
  from public.tgg_world_economy_config
  where config_key='property_price_multiplier';
  v_price_multiplier:=coalesce(v_price_multiplier,1);

  select coalesce(max(reputation),0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char;

  return jsonb_build_object(
    'wallet',jsonb_build_object(
      'balance',coalesce(v_balance,0),
      'currency','tgg_credits',
      'virtual_currency',true,
      'real_money',false
    ),
    'reputation',v_rep,
    'property_price_multiplier',v_price_multiplier,
    'property_catalog',coalesce((
      select jsonb_agg(jsonb_build_object(
        'property_key',p.property_key,
        'display_name',p.display_name,
        'property_type',p.property_type,
        'district_key',p.district_key,
        'base_price',p.base_price_credits,
        'price',round(p.base_price_credits*v_price_multiplier)::integer,
        'required_reputation',p.required_reputation,
        'business_slots',p.business_slots,
        'owned',exists(
          select 1 from public.tgg_world_character_properties cp
          where cp.character_id=v_char and cp.property_key=p.property_key and cp.ownership_status='owned'
        ),
        'can_afford',coalesce(v_balance,0)>=round(p.base_price_credits*v_price_multiplier)::integer,
        'reputation_ready',v_rep>=p.required_reputation
      ) order by p.required_reputation,p.base_price_credits)
      from public.tgg_world_property_catalog p
      where p.enabled=true
    ),'[]'::jsonb),
    'properties',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',cp.id,
        'property_key',cp.property_key,
        'display_name',pc.display_name,
        'property_type',pc.property_type,
        'business_slots',pc.business_slots,
        'business_count',(select count(*) from public.tgg_world_character_businesses b where b.property_id=cp.id and b.status in ('active','paused')),
        'compatible_businesses',coalesce((
          select jsonb_agg(jsonb_build_object(
            'business_type_key',bt.business_type_key,
            'display_name',bt.display_name,
            'required_reputation',bt.required_reputation,
            'reputation_ready',v_rep>=bt.required_reputation
          ) order by bt.display_name)
          from public.tgg_world_business_types bt
          where bt.enabled=true and pc.property_type=any(bt.allowed_property_types)
        ),'[]'::jsonb)
      ) order by cp.acquired_at)
      from public.tgg_world_character_properties cp
      join public.tgg_world_property_catalog pc on pc.property_key=cp.property_key
      where cp.character_id=v_char and cp.ownership_status='owned'
    ),'[]'::jsonb),
    'businesses',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',b.id,
        'business_name',b.business_name,
        'business_type_key',b.business_type_key,
        'business_type_name',bt.display_name,
        'business_level',b.business_level,
        'business_xp',b.business_xp,
        'reputation',b.reputation,
        'status',b.status,
        'property_id',b.property_id,
        'staff',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',s.id,'role_key',s.role_key,'staff_name',s.staff_name,
            'skill',s.skill,'loyalty',s.loyalty,'status',s.status
          ) order by s.hired_at)
          from public.tgg_world_business_staff s
          where s.business_id=b.id and s.status='active'
        ),'[]'::jsonb),
        'staff_roles',coalesce((
          select jsonb_agg(jsonb_build_object(
            'role_key',r.role_key,'display_name',r.display_name,'effects',r.effects
          ) order by r.display_name)
          from public.tgg_world_business_staff_roles r
          where r.enabled=true and b.business_type_key=any(r.business_type_keys)
        ),'[]'::jsonb),
        'operations',coalesce((
          select jsonb_agg(jsonb_build_object(
            'operation_key',o.operation_key,
            'display_name',o.display_name,
            'duration_minutes',o.duration_minutes,
            'requirements',o.requirements,
            'rewards',o.rewards,
            'running',exists(
              select 1 from public.tgg_world_character_business_operations ro
              where ro.business_id=b.id and ro.operation_key=o.operation_key and ro.status='running'
            )
          ) order by o.display_name)
          from public.tgg_world_business_operations o
          where o.enabled=true and b.business_type_key=any(o.business_type_keys)
        ),'[]'::jsonb),
        'running_operations',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',ro.id,
            'operation_key',ro.operation_key,
            'display_name',o.display_name,
            'started_at',ro.started_at,
            'duration_minutes',o.duration_minutes,
            'ready_at',ro.started_at+make_interval(mins=>o.duration_minutes)
          ) order by ro.started_at)
          from public.tgg_world_character_business_operations ro
          join public.tgg_world_business_operations o on o.operation_key=ro.operation_key
          where ro.business_id=b.id and ro.status='running'
        ),'[]'::jsonb)
      ) order by b.created_at)
      from public.tgg_world_character_businesses b
      join public.tgg_world_business_types bt on bt.business_type_key=b.business_type_key
      where b.character_id=v_char and b.status in ('active','paused')
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000295] function private.tgg_world_business_prestige_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_business_prestige_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  return jsonb_build_object(
    'character_id',v_char,
    'businesses',coalesce((
      select jsonb_agg(jsonb_build_object(
        'business_id',b.id,
        'business_name',b.business_name,
        'business_type_key',b.business_type_key,
        'business_level',b.business_level,
        'reputation',b.reputation,
        'prestige',jsonb_build_object(
          'level',coalesce(bp.prestige_level,0),
          'xp',coalesce(bp.prestige_xp,0),
          'unlocks',coalesce(bp.unlocks,'{}'::jsonb)
        ),
        'levels',coalesce((
          select jsonb_agg(jsonb_build_object(
            'prestige_level',p.prestige_level,
            'title',p.title,
            'requirements',p.requirements,
            'perks',p.perks,
            'claimed',coalesce(bp.prestige_level,0)>=p.prestige_level,
            'requirements_ready',
              b.business_level>=coalesce((p.requirements->>'business_level')::integer,0)
              and b.reputation>=coalesce((p.requirements->>'reputation')::integer,0)
          ) order by p.prestige_level)
          from public.tgg_world_business_prestige_levels p
          where p.enabled=true
        ),'[]'::jsonb)
      ) order by coalesce(bp.prestige_level,0) desc,b.business_level desc,b.business_name)
      from public.tgg_world_character_businesses b
      left join public.tgg_world_character_business_prestige bp on bp.business_id=b.id
      where b.character_id=v_char and b.status='active'
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000296] function private.tgg_world_buy_property(p_property_key text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_buy_property(p_property_key text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_prop public.tgg_world_property_catalog%rowtype;
  v_wallet public.tgg_world_wallets%rowtype;
  v_req public.tgg_world_property_purchase_requests%rowtype;
  v_key text:=btrim(coalesce(p_idempotency_key,''));
  v_rep integer:=0;
  v_owned uuid;
  v_result jsonb;
  v_price_multiplier numeric:=1;
  v_price integer:=0;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if char_length(v_key)<8 or char_length(v_key)>120 then raise exception 'idempotency_key_required'; end if;

  select * into v_char from public.world_characters
  where user_id=v_uid and character_status='active' limit 1;
  if v_char.id is null then raise exception 'active_character_required'; end if;

  select * into v_req from public.tgg_world_property_purchase_requests
  where user_id=v_uid and idempotency_key=v_key;
  if found then
    if v_req.property_key<>p_property_key then raise exception 'idempotency_key_reuse_mismatch'; end if;
    return v_req.result||jsonb_build_object('replayed',true);
  end if;

  select * into v_prop from public.tgg_world_property_catalog
  where property_key=p_property_key and enabled=true;
  if v_prop.property_key is null then raise exception 'property_unavailable'; end if;

  select greatest(coalesce((value->>'value')::numeric,1),0)
  into v_price_multiplier
  from public.tgg_world_economy_config
  where config_key='property_price_multiplier';
  v_price_multiplier:=coalesce(v_price_multiplier,1);
  v_price:=greatest(round(v_prop.base_price_credits*v_price_multiplier)::integer,0);

  select id into v_owned from public.tgg_world_character_properties
  where character_id=v_char.id and property_key=p_property_key and ownership_status='owned' limit 1;
  if v_owned is not null then
    return jsonb_build_object(
      'ok',true,'already_owned',true,'property_id',v_owned,'property_key',p_property_key,
      'virtual_currency',true,'price_multiplier',v_price_multiplier,'real_money',false
    );
  end if;

  select coalesce(max(reputation),0) into v_rep
  from public.tgg_world_career_reputation where character_id=v_char.id;

  if v_rep<v_prop.required_reputation then
    v_result:=jsonb_build_object(
      'ok',false,'reason','reputation_required',
      'required_reputation',v_prop.required_reputation,'current_reputation',v_rep,
      'total_cost',v_price,'price_multiplier',v_price_multiplier,
      'virtual_currency',true,'real_money',false
    );
    insert into public.tgg_world_property_purchase_requests(
      user_id,character_id,idempotency_key,property_key,total_cost,status,result
    )
    values(v_uid,v_char.id,v_key,p_property_key,v_price,'rejected',v_result);
    return v_result;
  end if;

  perform private.tgg_world_wallet_ensure_impl();
  select * into v_wallet from public.tgg_world_wallets where user_id=v_uid for update;

  if v_wallet.balance<v_price then
    v_result:=jsonb_build_object(
      'ok',false,'reason','insufficient_virtual_credits','balance',v_wallet.balance,
      'total_cost',v_price,'currency','tgg_credits','virtual_currency',true,
      'price_multiplier',v_price_multiplier,'real_money',false
    );
    insert into public.tgg_world_property_purchase_requests(
      user_id,character_id,idempotency_key,property_key,total_cost,status,result
    )
    values(v_uid,v_char.id,v_key,p_property_key,v_price,'rejected',v_result);
    return v_result;
  end if;

  update public.tgg_world_wallets
  set balance=balance-v_price,updated_at=now()
  where user_id=v_uid returning * into v_wallet;

  insert into public.tgg_world_wallet_ledger(
    user_id,character_id,entry_type,amount,balance_after,reference_type,reference_key,metadata
  )
  values(
    v_uid,v_char.id,'purchase_debit',-v_price,v_wallet.balance,'property_purchase',v_key,
    jsonb_build_object(
      'property_key',p_property_key,'base_price',v_prop.base_price_credits,
      'price_multiplier',v_price_multiplier,'virtual_currency',true,'real_money',false
    )
  );

  insert into public.tgg_world_character_properties(
    character_id,property_key,nickname,ownership_status,customization,acquired_at,updated_at
  )
  values(v_char.id,p_property_key,v_prop.display_name,'owned','{}'::jsonb,now(),now())
  returning id into v_owned;

  v_result:=jsonb_build_object(
    'ok',true,'property_id',v_owned,'property_key',p_property_key,
    'base_price',v_prop.base_price_credits,'price_multiplier',v_price_multiplier,
    'total_cost',v_price,'balance',v_wallet.balance,'currency','tgg_credits',
    'virtual_currency',true,'real_money',false
  );

  insert into public.tgg_world_property_purchase_requests(
    user_id,character_id,idempotency_key,property_key,total_cost,status,result
  )
  values(v_uid,v_char.id,v_key,p_property_key,v_price,'completed',v_result);

  return v_result||jsonb_build_object('replayed',false);
exception when unique_violation then
  select * into v_req from public.tgg_world_property_purchase_requests
  where user_id=v_uid and idempotency_key=v_key;
  if found then return v_req.result||jsonb_build_object('replayed',true); end if;
  raise;
end;
$function$


-- [40000000297] function private.tgg_world_can_read_crew(p_crew_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_can_read_crew(p_crew_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists(
    select 1 from public.tgg_world_crew_members m
    where m.crew_id=p_crew_id and m.user_id=auth.uid() and m.left_at is null
  )
$function$


-- [40000000298] function private.tgg_world_can_read_vehicle(p_vehicle_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_can_read_vehicle(p_vehicle_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists(
    select 1 from public.tgg_world_vehicles v
    where v.id=p_vehicle_id
      and (
        v.owner_user_id=auth.uid()
        or exists(
          select 1 from public.tgg_world_vehicle_passengers p
          where p.vehicle_id=v.id and p.user_id=auth.uid() and p.left_at is null
        )
      )
  )
$function$


-- [40000000299] function private.tgg_world_career_climb_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_career_climb_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_rep integer:=0;
  v_location text;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select * into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char.id is null then return '{}'::jsonb; end if;

  select coalesce(reputation,0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char.id and career_key=v_char.active_career;

  select l.location_key into v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=v_char.id;

  return jsonb_build_object(
    'character_id',v_char.id,
    'active_career',v_char.active_career,
    'career_reputation',v_rep,
    'current_location',v_location,
    'contracts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'contract_key',c.contract_key,
        'title',c.title,
        'career_key',c.career_key,
        'location_key',c.location_key,
        'contract_type',c.contract_type,
        'reputation_required',c.reputation_required,
        'objectives',c.objectives,
        'rewards',c.rewards,
        'repeatable',c.repeatable,
        'relationship_weight',private.tgg_world_relationship_opportunity_weight(v_char.id,c.contract_key),
        'state',case when cc.id is null then null else jsonb_build_object(
          'id',cc.id,'status',cc.status,'progress',cc.progress,
          'accepted_at',cc.accepted_at,'completed_at',cc.completed_at
        ) end,
        'career_ready',c.career_key=v_char.active_career,
        'reputation_ready',v_rep>=c.reputation_required,
        'chain_ready',not exists(
          select 1
          from public.tgg_world_contract_chain_steps s
          where s.contract_key=c.contract_key
            and (
              (
                s.unlock_condition ? 'previous_contract'
                and not exists(
                  select 1
                  from public.tgg_world_character_contracts pc
                  where pc.character_id=v_char.id
                    and pc.contract_key=s.unlock_condition->>'previous_contract'
                    and pc.status='completed'
                )
              )
              or (
                s.unlock_condition ? 'reputation'
                and v_rep<coalesce((s.unlock_condition->>'reputation')::integer,0)
              )
              or (
                s.unlock_condition ? 'relationship_contact'
                and coalesce((
                  select r.trust_score
                  from public.tgg_world_contact_relationships r
                  where r.character_id=v_char.id
                    and r.contact_key=s.unlock_condition->>'relationship_contact'
                ),0)<coalesce((s.unlock_condition->>'trust_score')::integer,0)
              )
            )
        )
      ) order by
        private.tgg_world_relationship_opportunity_weight(v_char.id,c.contract_key) desc,
        c.reputation_required,
        c.title)
      from public.tgg_world_career_contracts c
      left join public.tgg_world_character_contracts cc
        on cc.contract_key=c.contract_key and cc.character_id=v_char.id
      where c.enabled=true and c.career_key=v_char.active_career
    ),'[]'::jsonb),
    'missions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'mission_key',m.mission_key,
        'title',m.title,
        'description',m.description,
        'mission_type',m.mission_type,
        'location_key',m.location_key,
        'xp_reward',m.xp_reward,
        'repeatable',m.repeatable,
        'objectives',m.objectives,
        'rewards',m.rewards,
        'state',case when mp.id is null then null else jsonb_build_object(
          'id',mp.id,'status',mp.status,'progress',mp.progress,
          'started_at',mp.started_at,'completed_at',mp.completed_at
        ) end
      ) order by m.title)
      from public.tgg_world_career_missions m
      left join public.tgg_world_career_mission_progress mp
        on mp.mission_key=m.mission_key and mp.character_id=v_char.id
      where m.enabled=true and m.career_key=v_char.active_career
    ),'[]'::jsonb),
    'districts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'district_key',d.district_key,
        'display_name',d.display_name,
        'description',d.description,
        'unlock_reputation',d.unlock_reputation,
        'featured_locations',d.featured_locations,
        'activity_tags',d.activity_tags,
        'unlocked',v_rep>=d.unlock_reputation,
        'reputation',coalesce(dr.reputation,0),
        'tier',coalesce(dr.tier,1),
        'notoriety',coalesce(dr.notoriety,0)
      ) order by d.unlock_reputation,d.display_name)
      from public.tgg_world_districts d
      left join public.tgg_world_character_district_reputation dr
        on dr.district_key=d.district_key and dr.character_id=v_char.id
      where d.enabled=true
    ),'[]'::jsonb),
    'opportunity_matches',coalesce((
      select jsonb_agg(jsonb_build_object(
        'opportunity_id',o.opportunity_id,
        'title',o.title,
        'opportunity_type',o.opportunity_type,
        'city',o.city,
        'region',o.region,
        'remote_ok',o.remote_ok,
        'compensation_type',o.compensation_type,
        'match_score',o.match_score,
        'match_reason',o.match_reason,
        'application',(
          select jsonb_build_object(
            'id',a.id,'status',a.status,'message',a.message,
            'portfolio_url',a.portfolio_url,'created_at',a.created_at,'updated_at',a.updated_at
          )
          from public.tgg_opportunity_applications a
          where a.opportunity_id=o.opportunity_id and a.applicant_user_id=v_uid
          limit 1
        )
      ) order by o.match_score desc,o.title)
      from public.tgg_get_opportunity_matches(25) o
    ),'[]'::jsonb),
    'my_applications',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',a.id,'opportunity_id',a.opportunity_id,
        'title',o.title,'status',a.status,
        'created_at',a.created_at,'updated_at',a.updated_at
      ) order by a.updated_at desc)
      from public.tgg_opportunity_applications a
      join public.tgg_opportunities o on o.id=a.opportunity_id
      where a.applicant_user_id=v_uid
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000300] function private.tgg_world_career_track_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_career_track_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select * into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char.id is null then return '{}'::jsonb; end if;

  return jsonb_build_object(
    'character_id',v_char.id,
    'active_career',v_char.active_career,
    'tracks',coalesce((
      select jsonb_agg(jsonb_build_object(
        'career_key',t.career_key,
        'display_name',t.display_name,
        'description',t.description,
        'primary_location_key',t.primary_location_key,
        'level_cap',t.level_cap,
        'xp_per_level',t.xp_per_level,
        'rewards',t.rewards,
        'metadata',t.metadata,
        'active',t.career_key=v_char.active_career,
        'state',case when c.character_id is null then null else jsonb_build_object(
          'career_level',c.career_level,
          'career_xp',c.career_xp,
          'unlocked',c.unlocked,
          'xp_to_next',case
            when c.career_level>=t.level_cap then 0
            else greatest((c.career_level*t.xp_per_level)-c.career_xp,0)
          end
        ) end,
        'unlocks',coalesce((
          select jsonb_agg(jsonb_build_object(
            'unlock_key',u.unlock_key,
            'source_type',u.source_type,
            'source_key',u.source_key,
            'metadata',u.metadata,
            'unlocked_at',u.unlocked_at
          ) order by u.unlocked_at desc)
          from public.tgg_world_career_unlocks u
          where u.character_id=v_char.id
            and (
              u.metadata->>'career_key'=t.career_key
              or u.source_key=t.career_key
            )
        ),'[]'::jsonb)
      ) order by (t.career_key=v_char.active_career) desc,t.display_name)
      from public.tgg_world_career_tracks t
      left join public.world_character_careers c
        on c.character_id=v_char.id and c.career_key=t.career_key
      where t.enabled=true
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000301] function private.tgg_world_challenge_period(p_cadence text)
CREATE OR REPLACE FUNCTION private.tgg_world_challenge_period(p_cadence text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_clock jsonb;
  v_local timestamp;
  v_cadence text:=lower(btrim(coalesce(p_cadence,'')));
begin
  v_clock:=private.tgg_world_clock();
  v_local:=(v_clock->>'local_timestamp')::timestamp;

  if v_cadence='daily' then
    return to_char(v_local::date,'YYYY-MM-DD');
  elsif v_cadence='weekly' then
    return to_char(date_trunc('week',v_local)::date,'IYYY-"W"IW');
  else
    raise exception 'unsupported_challenge_cadence';
  end if;
end;
$function$


-- [40000000302] function private.tgg_world_character_creation_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_character_creation_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_uid uuid:=auth.uid();
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  return jsonb_build_object(
    'has_character',exists(select 1 from public.world_characters where user_id=v_uid and character_status='active'),
    'careers',coalesce((
      select jsonb_agg(jsonb_build_object(
        'career_key',c.career_key,
        'display_name',c.display_name,
        'description',c.description
      ) order by c.display_name)
      from public.tgg_world_career_tracks c
      where c.enabled=true
    ),'[]'::jsonb),
    'spawn',jsonb_build_object(
      'location_key','starter-apartment',
      'location_name',coalesce((select name from public.tgg_world_locations where location_key='starter-apartment' limit 1),'Starter Apartment')
    )
  );
end;
$function$


-- [40000000303] function private.tgg_world_city_activity_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_city_activity_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_char uuid;
      v_rep integer:=0;
    begin
      if v_uid is null then raise exception 'authentication required'; end if;

      select id into v_char
      from public.world_characters
      where user_id=v_uid and character_status='active'
      limit 1;

      if v_char is null then return '{}'::jsonb; end if;

      select coalesce(max(reputation),0) into v_rep
      from public.tgg_world_career_reputation
      where character_id=v_char;

      return jsonb_build_object(
        'character_id',v_char,
        'reputation',v_rep,
        'events',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',e.id,
            'event_key',e.event_key,
            'title',t.title,
            'description',nullif(t.metadata->>'description',''),
            'location_key',e.location_key,
            'status',e.status,
            'starts_at',e.starts_at,
            'ends_at',e.ends_at,
            'participant_roles',t.participant_roles,
            'outcomes',t.outcomes,
            'state',case when s.character_id is null then null else jsonb_build_object(
              'status',s.status,
              'role_key',s.role_key,
              'progress',s.progress,
              'outcome',s.outcome,
              'discovered_at',s.discovered_at,
              'joined_at',s.joined_at,
              'completed_at',s.completed_at
            ) end
          ) order by e.starts_at)
          from public.tgg_world_dynamic_events e
          join public.tgg_world_dynamic_event_templates t
            on t.event_key=e.event_key and t.enabled=true
          left join public.tgg_world_character_event_state s
            on s.dynamic_event_id=e.id and s.character_id=v_char
          where e.status in ('scheduled','active')
            and e.ends_at>now()
        ),'[]'::jsonb),
        'transit',coalesce((
          select jsonb_agg(jsonb_build_object(
            'transit_key',n.transit_key,
            'display_name',n.display_name,
            'location_key',n.location_key,
            'district_key',n.district_key,
            'unlock_reputation',n.unlock_reputation,
            'connections',n.connections,
            'unlocked',v_rep>=n.unlock_reputation
          ) order by n.unlock_reputation,n.display_name)
          from public.tgg_world_transit_nodes n
          where n.enabled=true
        ),'[]'::jsonb)
      );
    end;
    $function$


-- [40000000304] function private.tgg_world_city_power_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_city_power_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_location text;
  v_district text;
  v_rep integer:=0;
  v_career_level integer:=1;
  v_achievements integer:=0;
  v_crew uuid;
  v_crew_role text;
  v_crew_members integer:=0;
  v_crew_rank integer:=0;
  v_dominant integer:=0;
  v_business_prestige integer:=0;
  v_city_influence integer:=0;
  v_prestige integer:=0;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select * into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char.id is null then return '{}'::jsonb; end if;

  select l.location_key,l.district_key
  into v_location,v_district
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=v_char.id;

  select coalesce(reputation,0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char.id and career_key=v_char.active_career;

  select coalesce(career_level,1) into v_career_level
  from public.world_character_careers
  where character_id=v_char.id and career_key=v_char.active_career;

  select count(*) into v_achievements
  from public.tgg_world_character_achievements
  where character_id=v_char.id and unlocked_at is not null;

  select m.crew_id,m.crew_role into v_crew,v_crew_role
  from public.tgg_world_crew_members m
  where m.user_id=v_uid and m.character_id=v_char.id and m.left_at is null
  order by m.joined_at desc limit 1;

  if v_crew is not null then
    select count(*) into v_crew_members
    from public.tgg_world_crew_members where crew_id=v_crew and left_at is null;

    select coalesce(rank_level,1) into v_crew_rank
    from public.tgg_world_crew_progression where crew_id=v_crew;

    select count(*) into v_dominant
    from public.tgg_world_crew_territories
    where crew_id=v_crew and control_level='dominant';
  end if;

  select coalesce(max(p.prestige_level),0)
  into v_business_prestige
  from public.tgg_world_character_businesses b
  left join public.tgg_world_character_business_prestige p on p.business_id=b.id
  where b.character_id=v_char.id and b.status='active';

  select coalesce(total_influence,
    career_influence+crew_influence+business_influence+faction_influence+district_influence+social_influence,0)
  into v_city_influence
  from public.tgg_world_character_influence
  where character_id=v_char.id;

  select coalesce(prestige_level,0) into v_prestige
  from public.tgg_world_character_prestige
  where character_id=v_char.id;

  return jsonb_build_object(
    'character_id',v_char.id,
    'active_career',v_char.active_career,
    'career_reputation',v_rep,
    'career_level',v_career_level,
    'current_location',v_location,
    'current_district',v_district,
    'jobs',coalesce((
      select jsonb_agg(jsonb_build_object(
        'job_key',j.job_key,
        'display_name',j.display_name,
        'district_key',j.district_key,
        'career_affinity',j.career_affinity,
        'min_reputation',j.min_reputation,
        'shift_minutes',j.shift_minutes,
        'rewards',j.rewards,
        'crew_bonus',j.crew_bonus,
        'vehicle_bonus',j.vehicle_bonus,
        'career_ready',cardinality(j.career_affinity)=0 or v_char.active_career=any(j.career_affinity),
        'reputation_ready',v_rep>=j.min_reputation,
        'district_ready',v_district=j.district_key,
        'state',(
          select jsonb_build_object(
            'id',s.id,'status',s.status,'progress',s.progress,
            'accepted_at',s.accepted_at,'completed_at',s.completed_at,
            'ready_at',case when s.status='accepted'
              then s.accepted_at+make_interval(mins=>j.shift_minutes) else null end
          )
          from public.tgg_world_character_jobs s
          where s.character_id=v_char.id and s.job_key=j.job_key
          order by s.updated_at desc limit 1
        )
      ) order by j.min_reputation,j.display_name)
      from public.tgg_world_job_catalog j
      where j.enabled=true
    ),'[]'::jsonb),
    'crew',case when v_crew is null then '{}'::jsonb else jsonb_build_object(
      'crew_id',v_crew,
      'role',v_crew_role,
      'member_count',v_crew_members,
      'rank_level',v_crew_rank,
      'dominant_districts',v_dominant,
      'can_start_contract',v_crew_role in ('owner','admin')
        or exists(select 1 from public.tgg_world_crews c where c.id=v_crew and c.owner_user_id=v_uid),
      'contracts',coalesce((
        select jsonb_agg(jsonb_build_object(
          'contract_key',c.contract_key,
          'title',c.title,
          'required_crew_size',c.required_crew_size,
          'district_key',c.district_key,
          'objectives',c.objectives,
          'rewards',c.rewards,
          'crew_size_ready',v_crew_members>=c.required_crew_size,
          'district_ready',c.district_key is null or c.district_key=v_district,
          'run',(
            select jsonb_build_object(
              'id',r.id,'status',r.status,'progress',r.progress,
              'started_at',r.started_at,'completed_at',r.completed_at
            )
            from public.tgg_world_crew_contract_runs r
            where r.crew_id=v_crew and r.contract_key=c.contract_key
            order by r.updated_at desc limit 1
          )
        ) order by c.required_crew_size,c.title)
        from public.tgg_world_crew_contracts c
        where c.enabled=true
      ),'[]'::jsonb),
      'territories',coalesce((
        select jsonb_agg(jsonb_build_object(
          'district_key',t.district_key,
          'influence',t.influence,
          'control_level',t.control_level,
          'perks',t.perks
        ) order by t.influence desc,t.district_key)
        from public.tgg_world_crew_territories t
        where t.crew_id=v_crew
      ),'[]'::jsonb)
    ) end,
    'elite_events',coalesce((
      select jsonb_agg(jsonb_build_object(
        'elite_event_key',e.elite_event_key,
        'title',e.title,
        'event_type',e.event_type,
        'location_key',e.location_key,
        'entry_conditions',e.entry_conditions,
        'rewards',e.rewards,
        'prestige_tier',e.prestige_tier,
        'cooldown_minutes',e.cooldown_minutes,
        'requirements_ready',
          (not (e.entry_conditions ? 'reputation') or v_rep>=(e.entry_conditions->>'reputation')::integer)
          and (not (e.entry_conditions ? 'career_level') or v_career_level>=(e.entry_conditions->>'career_level')::integer)
          and (not (e.entry_conditions ? 'achievements') or v_achievements>=(e.entry_conditions->>'achievements')::integer)
          and (not (e.entry_conditions ? 'crew_rank') or v_crew_rank>=(e.entry_conditions->>'crew_rank')::integer)
          and (not (e.entry_conditions ? 'districts_dominant') or v_dominant>=(e.entry_conditions->>'districts_dominant')::integer)
          and (not (e.entry_conditions ? 'faction') or exists(
            select 1 from public.tgg_world_character_factions f
            where f.character_id=v_char.id
              and f.faction_key=e.entry_conditions->>'faction'
              and f.status<>'hostile'
          ))
          and (not (e.entry_conditions ? 'business_prestige') or v_business_prestige>=(e.entry_conditions->>'business_prestige')::integer)
          and (not (e.entry_conditions ? 'city_influence') or v_city_influence>=(e.entry_conditions->>'city_influence')::integer)
          and (not (e.entry_conditions ? 'prestige_level') or v_prestige>=(e.entry_conditions->>'prestige_level')::integer),
        'location_ready',v_location=e.location_key,
        'last_completed_at',(
          select max(s.completed_at)
          from public.tgg_world_character_elite_events s
          where s.character_id=v_char.id and s.elite_event_key=e.elite_event_key
        ),
        'ready_at',(
          select max(s.completed_at)+make_interval(mins=>e.cooldown_minutes)
          from public.tgg_world_character_elite_events s
          where s.character_id=v_char.id and s.elite_event_key=e.elite_event_key
        )
      ) order by e.prestige_tier,e.title)
      from public.tgg_world_elite_events e
      where e.enabled=true
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000305] function private.tgg_world_claim_business_prestige(p_business_id uuid, p_prestige_level integer)
CREATE OR REPLACE FUNCTION private.tgg_world_claim_business_prestige(p_business_id uuid, p_prestige_level integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_char uuid;
  v_b public.tgg_world_character_businesses%rowtype;
  v_p public.tgg_world_business_prestige_levels%rowtype;
  v_current integer:=0;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select id into v_char from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_b from public.tgg_world_character_businesses
  where id=p_business_id and character_id=v_char and status='active'
  for update;
  if v_b.id is null then raise exception 'owned_business_required'; end if;

  select * into v_p from public.tgg_world_business_prestige_levels
  where prestige_level=p_prestige_level and enabled=true;
  if v_p.prestige_level is null then raise exception 'prestige_level_unavailable'; end if;

  select coalesce(prestige_level,0) into v_current
  from public.tgg_world_character_business_prestige where business_id=v_b.id;

  if v_current>=p_prestige_level then return jsonb_build_object('ok',true,'replayed',true,'prestige_level',v_current); end if;
  if v_b.business_level<coalesce((v_p.requirements->>'business_level')::integer,0)
     or v_b.reputation<coalesce((v_p.requirements->>'reputation')::integer,0) then
    return jsonb_build_object('ok',false,'reason','requirements_not_met','business_level',v_b.business_level,'reputation',v_b.reputation);
  end if;

  insert into public.tgg_world_character_business_prestige(business_id,prestige_level,prestige_xp,unlocks,updated_at)
  values(v_b.id,p_prestige_level,p_prestige_level*100,v_p.perks,now())
  on conflict(business_id) do update
  set prestige_level=greatest(public.tgg_world_character_business_prestige.prestige_level,excluded.prestige_level),
      prestige_xp=public.tgg_world_character_business_prestige.prestige_xp+100,
      unlocks=public.tgg_world_character_business_prestige.unlocks||excluded.unlocks,
      updated_at=now();

  perform private.tgg_recompute_progression(v_char);
  return jsonb_build_object('ok',true,'prestige_level',p_prestige_level,'perks',v_p.perks,'real_money_changed',false);
end;
$function$


-- [40000000306] function private.tgg_world_claim_prestige_challenge(p_challenge_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_claim_prestige_challenge(p_challenge_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_ch public.tgg_world_prestige_challenges%rowtype;
  v_level public.tgg_world_prestige_levels%rowtype;
  v_props integer:=0;
  v_businesses integer:=0;
  v_rep integer:=0;
  v_ach integer:=0;
  v_tournaments integer:=0;
  v_favored boolean:=false;
  v_max_business_level integer:=0;
  v_good_districts integer:=0;
  v_ok boolean:=true;
  v_prestige_xp integer:=0;
  v_state public.tgg_world_character_prestige_challenges%rowtype;
  v_title_key text;
  v_bonus_unlocks jsonb:='{}'::jsonb;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char from public.world_characters
  where user_id=v_uid and character_status='active' limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_ch from public.tgg_world_prestige_challenges
  where challenge_key=p_challenge_key and enabled=true;
  if v_ch.challenge_key is null then raise exception 'prestige challenge unavailable'; end if;

  select * into v_level from public.tgg_world_prestige_levels
  where prestige_level=v_ch.prestige_level and enabled=true;
  if v_level.prestige_level is null then raise exception 'prestige level unavailable'; end if;

  select count(*) into v_props from public.tgg_world_character_properties
  where character_id=v_char and ownership_status='owned';
  select count(*) into v_businesses from public.tgg_world_character_businesses
  where character_id=v_char and status='active';
  select coalesce(sum(reputation),0) into v_rep from public.tgg_world_career_reputation where character_id=v_char;
  select count(*) into v_ach from public.tgg_world_character_achievements where character_id=v_char and unlocked_at is not null;
  select count(*) into v_tournaments from public.tgg_world_tournament_entries where character_id=v_char and status='completed';
  select exists(select 1 from public.tgg_world_character_factions where character_id=v_char and status='favored') into v_favored;
  select coalesce(max(business_level),0) into v_max_business_level from public.tgg_world_character_businesses where character_id=v_char and status='active';
  select count(*) into v_good_districts from public.tgg_world_character_district_reputation where character_id=v_char and tier>=3;

  if v_ch.requirements ? 'own_property' and coalesce((v_ch.requirements->>'own_property')::boolean,false) and v_props<1 then v_ok:=false; end if;
  if v_ch.requirements ? 'complete_tournaments' and v_tournaments<coalesce((v_ch.requirements->>'complete_tournaments')::integer,0) then v_ok:=false; end if;
  if v_ch.requirements ? 'faction_favored' and coalesce((v_ch.requirements->>'faction_favored')::boolean,false) and not v_favored then v_ok:=false; end if;
  if v_ch.requirements ? 'business_level_gte' and v_max_business_level<coalesce((v_ch.requirements->>'business_level_gte')::integer,0) then v_ok:=false; end if;
  if v_ch.requirements ? 'achievements' and v_ach<coalesce((v_ch.requirements->>'achievements')::integer,0) then v_ok:=false; end if;
  if v_ch.requirements ? 'districts_dominant_or_favored' and v_good_districts<coalesce((v_ch.requirements->>'districts_dominant_or_favored')::integer,0) then v_ok:=false; end if;

  if v_level.requirements ? 'properties' and v_props<coalesce((v_level.requirements->>'properties')::integer,0) then v_ok:=false; end if;
  if v_level.requirements ? 'businesses' and v_businesses<coalesce((v_level.requirements->>'businesses')::integer,0) then v_ok:=false; end if;
  if v_level.requirements ? 'reputation' and v_rep<coalesce((v_level.requirements->>'reputation')::integer,0) then v_ok:=false; end if;
  if v_level.requirements ? 'achievements' and v_ach<coalesce((v_level.requirements->>'achievements')::integer,0) then v_ok:=false; end if;

  insert into public.tgg_world_character_prestige_challenges(character_id,challenge_key,status,updated_at)
  values(v_char,p_challenge_key,'available',now())
  on conflict(character_id,challenge_key) do nothing;

  select * into v_state from public.tgg_world_character_prestige_challenges
  where character_id=v_char and challenge_key=p_challenge_key for update;

  if v_state.status='completed' then
    return jsonb_build_object('completed',true,'replayed',true,'prestige_level',v_ch.prestige_level);
  end if;

  if not v_ok then
    return jsonb_build_object(
      'completed',false,'reason','requirements_not_met',
      'properties',v_props,'businesses',v_businesses,'reputation',v_rep,
      'achievements',v_ach,'tournaments',v_tournaments,'faction_favored',v_favored,
      'max_business_level',v_max_business_level,'favored_districts',v_good_districts
    );
  end if;

  v_prestige_xp:=greatest(coalesce((v_ch.rewards->>'prestige_xp')::integer,0),0);
  v_bonus_unlocks:=coalesce(v_ch.rewards,'{}'::jsonb)-'prestige_xp';

  update public.tgg_world_character_prestige_challenges
  set status='completed',completed_at=now(),reward_snapshot=v_ch.rewards,updated_at=now()
  where character_id=v_char and challenge_key=p_challenge_key;

  insert into public.tgg_world_character_prestige(character_id,prestige_level,lifetime_prestige_xp,permanent_unlocks,updated_at)
  values(v_char,v_ch.prestige_level,v_prestige_xp,v_level.permanent_unlocks||v_bonus_unlocks,now())
  on conflict(character_id) do update
    set prestige_level=greatest(public.tgg_world_character_prestige.prestige_level,v_ch.prestige_level),
        lifetime_prestige_xp=public.tgg_world_character_prestige.lifetime_prestige_xp+v_prestige_xp,
        permanent_unlocks=public.tgg_world_character_prestige.permanent_unlocks||v_level.permanent_unlocks||v_bonus_unlocks,
        updated_at=now();

  select title_key into v_title_key
  from public.tgg_world_titles
  where enabled=true and lower(display_name)=lower(v_level.title)
  limit 1;

  if v_title_key is not null then
    insert into public.tgg_world_character_titles(character_id,title_key,unlocked_at)
    values(v_char,v_title_key,now()) on conflict do nothing;
  end if;

  perform private.tgg_recompute_progression(v_char);

  return jsonb_build_object(
    'completed',true,'challenge_key',p_challenge_key,'prestige_level',v_ch.prestige_level,
    'prestige_xp',v_prestige_xp,'permanent_unlocks',v_level.permanent_unlocks||v_bonus_unlocks,
    'season_reset_applied',false
  );
end;
$function$


-- [40000000307] function private.tgg_world_claim_season_reward(p_season_key text, p_reward_level integer)
CREATE OR REPLACE FUNCTION private.tgg_world_claim_season_reward(p_season_key text, p_reward_level integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_season public.tgg_world_seasons%rowtype;
  v_progress public.tgg_world_character_season_progress%rowtype;
  v_reward public.tgg_world_season_rewards%rowtype;
  v_title_key text;
  v_badge_key text;
  v_prestige_xp integer:=0;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_season
  from public.tgg_world_seasons
  where season_key=p_season_key and enabled=true
    and (starts_at is null or starts_at<=now())
    and (ends_at is null or ends_at>=now());
  if v_season.season_key is null then raise exception 'season_not_active'; end if;

  select * into v_reward
  from public.tgg_world_season_rewards
  where season_key=p_season_key and reward_level=p_reward_level;
  if v_reward.season_key is null then raise exception 'season_reward_not_found'; end if;

  insert into public.tgg_world_character_season_progress(
    character_id,season_key,season_level,season_xp,unlocked_rewards,updated_at
  )
  values(v_char,p_season_key,1,0,'[]'::jsonb,now())
  on conflict(character_id,season_key) do nothing;

  select * into v_progress
  from public.tgg_world_character_season_progress
  where character_id=v_char and season_key=p_season_key
  for update;

  if v_progress.unlocked_rewards @> jsonb_build_array(p_reward_level) then
    return jsonb_build_object(
      'claimed',true,'replayed',true,'season_key',p_season_key,'reward_level',p_reward_level
    );
  end if;

  if v_progress.season_xp<v_reward.required_xp then
    return jsonb_build_object(
      'claimed',false,'reason','xp_required',
      'season_xp',v_progress.season_xp,'required_xp',v_reward.required_xp
    );
  end if;

  update public.tgg_world_character_season_progress
  set unlocked_rewards=unlocked_rewards||jsonb_build_array(p_reward_level),
      season_level=greatest(season_level,p_reward_level),
      updated_at=now()
  where character_id=v_char and season_key=p_season_key;

  if v_reward.reward ? 'title' then
    select title_key into v_title_key
    from public.tgg_world_titles
    where enabled=true and lower(display_name)=lower(v_reward.reward->>'title')
    limit 1;
    if v_title_key is not null then
      insert into public.tgg_world_character_titles(character_id,title_key,unlocked_at)
      values(v_char,v_title_key,now())
      on conflict do nothing;
    end if;
  end if;

  if v_reward.reward ? 'season_badge' then
    select badge_key into v_badge_key
    from public.tgg_world_badges
    where enabled=true and badge_key=v_reward.reward->>'season_badge'
    limit 1;
    if v_badge_key is not null then
      insert into public.tgg_world_character_badges(character_id,badge_key,unlocked_at)
      values(v_char,v_badge_key,now())
      on conflict do nothing;
    end if;
  end if;

  v_prestige_xp:=greatest(coalesce((v_reward.reward->>'prestige_xp')::integer,0),0);
  if v_prestige_xp>0 then
    insert into public.tgg_world_character_prestige(
      character_id,prestige_level,lifetime_prestige_xp,permanent_unlocks,updated_at
    )
    values(v_char,0,v_prestige_xp,'{}'::jsonb,now())
    on conflict(character_id) do update
    set lifetime_prestige_xp=public.tgg_world_character_prestige.lifetime_prestige_xp+v_prestige_xp,
        updated_at=now();
  end if;

  perform private.tgg_recompute_progression(v_char);

  return jsonb_build_object(
    'claimed',true,'replayed',false,
    'season_key',p_season_key,'reward_level',p_reward_level,
    'reward',v_reward.reward
  );
end;
$function$


-- [40000000308] function private.tgg_world_claim_story_chapter(p_arc_key text, p_expected_chapter_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_claim_story_chapter(p_arc_key text, p_expected_chapter_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_state public.tgg_world_character_story_state%rowtype;
  v_ch public.tgg_world_story_chapters%rowtype;
  v_next public.tgg_world_story_chapters%rowtype;
  v_flag text;
  v_rivalry integer:=0;
  v_event uuid;
  v_completed_arc boolean:=false;
  v_target jsonb:='{}'::jsonb;
  v_target_contact text;
  v_target_npc text;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_state
  from public.tgg_world_character_story_state
  where character_id=v_char and arc_key=p_arc_key and status='active'
  for update;

  if v_state.character_id is null then
    raise exception 'active_story_arc_required';
  end if;

  if p_expected_chapter_key is null
     or p_expected_chapter_key<>v_state.current_chapter_key then
    return jsonb_build_object(
      'completed',false,
      'reason','stale_chapter_request',
      'expected_chapter_key',p_expected_chapter_key,
      'current_chapter_key',v_state.current_chapter_key
    );
  end if;

  select * into v_ch
  from public.tgg_world_story_chapters
  where chapter_key=v_state.current_chapter_key and enabled=true;

  if v_ch.chapter_key is null then raise exception 'story_chapter_unavailable'; end if;

  if not private.tgg_world_story_conditions_met(v_char,v_ch.completion_conditions) then
    return jsonb_build_object(
      'completed',false,'reason','completion_conditions_not_met',
      'chapter_key',v_ch.chapter_key,'conditions',v_ch.completion_conditions
    );
  end if;

  if v_ch.consequences ? 'set_flag' then
    v_flag:=v_ch.consequences->>'set_flag';
    update public.tgg_world_character_story_state
    set flags=flags||jsonb_build_object(v_flag,true)
    where character_id=v_char and arc_key=p_arc_key;
  end if;

  if coalesce((v_ch.consequences->>'relationship_shift')::boolean,false) then
    v_target:=private.tgg_world_story_consequence_target(v_char,v_ch.chapter_key);
    v_target_contact:=nullif(v_target->>'contact_key','');

    if v_target_contact is not null then
      update public.tgg_world_contact_relationships
      set trust_score=least(100,trust_score+5),
          relationship_xp=relationship_xp+10,
          relationship_level=greatest(relationship_level,1+((relationship_xp+10)/100)),
          last_interaction_at=now(),
          updated_at=now()
      where character_id=v_char
        and contact_key=v_target_contact;
    end if;
  end if;

  v_rivalry:=greatest(coalesce((v_ch.consequences->>'rivalry_seed')::integer,0),0);

  if v_rivalry>0 then
    v_target:=private.tgg_world_story_consequence_target(v_char,v_ch.chapter_key);
    v_target_npc:=nullif(v_target->>'npc_key','');

    if v_target_npc is not null then
      insert into public.tgg_world_character_npc_standing(
        character_id,npc_key,standing,rivalry,loyalty,
        blocked_opportunities,favored_opportunities,memory,updated_at
      )
      values(
        v_char,v_target_npc,0,least(100,v_rivalry),0,
        '[]'::jsonb,'[]'::jsonb,
        jsonb_build_object(
          'last_story_chapter',v_ch.chapter_key,
          'story_rivalry_seed',v_rivalry
        ),
        now()
      )
      on conflict(character_id,npc_key) do update
      set rivalry=greatest(
            public.tgg_world_character_npc_standing.rivalry,
            least(100,v_rivalry)
          ),
          memory=public.tgg_world_character_npc_standing.memory
            ||jsonb_build_object(
              'last_story_chapter',v_ch.chapter_key,
              'story_rivalry_seed',v_rivalry
            ),
          updated_at=now();
    end if;
  end if;

  update public.tgg_world_character_story_state
  set consequence_state=consequence_state||v_ch.consequences
        ||case
          when coalesce((v_target->>'resolved')::boolean,false)
          then jsonb_build_object('last_consequence_target',v_target)
          else jsonb_build_object(
            'last_consequence_target',
            jsonb_build_object(
              'resolved',false,
              'chapter_key',v_ch.chapter_key,
              'reason','no_grounded_story_target'
            )
          )
        end,
      flags=flags||jsonb_build_object('completed_'||v_ch.chapter_key,true),
      updated_at=now()
  where character_id=v_char and arc_key=p_arc_key;

  v_event:=private.tgg_apply_progression_event(
    v_char,'story_chapter_completed',v_ch.chapter_key,
    jsonb_build_object('season_xp',50)
  );

  select * into v_next
  from public.tgg_world_story_chapters
  where arc_key=p_arc_key and enabled=true and chapter_order>v_ch.chapter_order
  order by chapter_order
  limit 1;

  if v_next.chapter_key is null then
    update public.tgg_world_character_story_state
    set current_chapter_key=null,status='completed',completed_at=now(),updated_at=now()
    where character_id=v_char and arc_key=p_arc_key;
    v_completed_arc:=true;
  elsif private.tgg_world_story_conditions_met(v_char,v_next.start_conditions) then
    update public.tgg_world_character_story_state
    set current_chapter_key=v_next.chapter_key,
        consequence_state=consequence_state-'next_chapter_locked',
        updated_at=now()
    where character_id=v_char and arc_key=p_arc_key;
  else
    update public.tgg_world_character_story_state
    set current_chapter_key=v_next.chapter_key,
        consequence_state=consequence_state||jsonb_build_object('next_chapter_locked',true),
        updated_at=now()
    where character_id=v_char and arc_key=p_arc_key;
  end if;

  perform private.tgg_recompute_progression(v_char);

  return jsonb_build_object(
    'completed',true,
    'chapter_key',v_ch.chapter_key,
    'arc_completed',v_completed_arc,
    'next_chapter_key',v_next.chapter_key,
    'consequences',v_ch.consequences,
    'consequence_target',v_target,
    'progression_event_id',v_event
  );
end;
$function$


-- [40000000309] function private.tgg_world_clock()
CREATE OR REPLACE FUNCTION private.tgg_world_clock()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_tz text:='America/New_York';
  v_local timestamp;
begin
  select coalesce(value->>'timezone','America/New_York') into v_tz
  from public.tgg_world_runtime_config
  where config_key='world_timezone';

  begin
    perform now() at time zone v_tz;
  exception when invalid_parameter_value then
    v_tz:='America/New_York';
  end;

  v_local:=now() at time zone v_tz;
  return jsonb_build_object(
    'timezone',v_tz,
    'local_timestamp',v_local,
    'local_hour',extract(hour from v_local)::integer,
    'iso_dow',extract(isodow from v_local)::integer,
    'is_weekend',extract(isodow from v_local)::integer in (6,7)
  );
end;
$function$


-- [40000000310] function private.tgg_world_competitive_endgame_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_competitive_endgame_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_rep integer:=0;
  v_location text;
  v_prestige integer:=0;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select * into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char.id is null then return '{}'::jsonb; end if;

  select coalesce(sum(reputation),0) into v_rep
  from public.tgg_world_career_reputation where character_id=v_char.id;

  select l.location_key into v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=v_char.id;

  select coalesce(prestige_level,0) into v_prestige
  from public.tgg_world_character_prestige
  where character_id=v_char.id;

  return jsonb_build_object(
    'character_id',v_char.id,
    'career',v_char.active_career,
    'reputation',v_rep,
    'current_location',v_location,
    'factions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'faction_key',f.faction_key,
        'display_name',f.display_name,
        'faction_type',f.faction_type,
        'home_district_key',f.home_district_key,
        'perks',f.perks,
        'standing',coalesce(cf.standing,0),
        'rank_level',coalesce(cf.rank_level,1),
        'loyalty',coalesce(cf.loyalty,0),
        'status',coalesce(cf.status,'not_joined'),
        'joined',cf.character_id is not null,
        'missions',coalesce((
          select jsonb_agg(jsonb_build_object(
            'mission_key',m.mission_key,
            'title',m.title,
            'description',m.description,
            'requirements',m.requirements,
            'rewards',m.rewards,
            'repeatable',m.repeatable,
            'status',coalesce(ms.status,'available'),
            'progress',coalesce(ms.progress,'{}'::jsonb)
          ) order by m.title)
          from public.tgg_world_faction_missions m
          left join public.tgg_world_character_faction_missions ms
            on ms.mission_key=m.mission_key and ms.character_id=v_char.id
          where m.faction_key=f.faction_key and m.enabled=true
        ),'[]'::jsonb)
      ) order by f.display_name)
      from public.tgg_world_factions f
      left join public.tgg_world_character_factions cf
        on cf.faction_key=f.faction_key and cf.character_id=v_char.id
      where f.enabled=true
    ),'[]'::jsonb),
    'crew_options',coalesce((
      select jsonb_agg(jsonb_build_object(
        'crew_id',c.id,'crew_name',c.crew_name,'my_role',m.crew_role
      ) order by c.crew_name)
      from public.tgg_world_crew_members m
      join public.tgg_world_crews c on c.id=m.crew_id and c.crew_status='active'
      where m.character_id=v_char.id and m.left_at is null
    ),'[]'::jsonb),
    'tournaments',coalesce((
      select jsonb_agg(jsonb_build_object(
        'tournament_key',t.tournament_key,
        'title',t.title,
        'tournament_type',t.tournament_type,
        'location_key',t.location_key,
        'entry_conditions',t.entry_conditions,
        'format',t.format,
        'rewards',t.rewards,
        'eligible_career',not (t.entry_conditions ? 'career') or t.entry_conditions->>'career'=v_char.active_career,
        'eligible_reputation',not (t.entry_conditions ? 'reputation_gte') or v_rep>=coalesce((t.entry_conditions->>'reputation_gte')::integer,0),
        'crew_required',coalesce((t.entry_conditions->>'crew_required')::boolean,false),
        'entry',(
          select jsonb_build_object(
            'id',e.id,'status',e.status,'score',e.score,'placement',e.placement,
            'result',e.result,'registered_at',e.registered_at,'updated_at',e.updated_at,'crew_id',e.crew_id
          )
          from public.tgg_world_tournament_entries e
          where e.tournament_key=t.tournament_key and e.character_id=v_char.id
          limit 1
        )
      ) order by t.title)
      from public.tgg_world_tournaments t
      where t.enabled=true
    ),'[]'::jsonb),
    'ladders',coalesce((
      select jsonb_agg(jsonb_build_object(
        'ladder_key',l.ladder_key,
        'display_name',l.display_name,
        'tournament_type',l.tournament_type,
        'divisions',l.divisions,
        'state',(
          select jsonb_build_object(
            'points',s.ladder_points,'division_key',s.division_key,
            'wins',s.wins,'losses',s.losses,'streak',s.streak
          )
          from public.tgg_world_character_ladder_state s
          where s.character_id=v_char.id and s.ladder_key=l.ladder_key
        )
      ) order by l.display_name)
      from public.tgg_world_tournament_ladders l where l.enabled=true
    ),'[]'::jsonb),
    'prestige',jsonb_build_object(
      'level',v_prestige,
      'lifetime_xp',coalesce((select lifetime_prestige_xp from public.tgg_world_character_prestige where character_id=v_char.id),0),
      'permanent_unlocks',coalesce((select permanent_unlocks from public.tgg_world_character_prestige where character_id=v_char.id),'{}'::jsonb),
      'challenges',coalesce((
        select jsonb_agg(jsonb_build_object(
          'challenge_key',c.challenge_key,
          'prestige_level',c.prestige_level,
          'title',c.title,
          'requirements',c.requirements,
          'rewards',c.rewards,
          'status',coalesce(s.status,'available'),
          'completed_at',s.completed_at
        ) order by c.prestige_level,c.title)
        from public.tgg_world_prestige_challenges c
        left join public.tgg_world_character_prestige_challenges s
          on s.challenge_key=c.challenge_key and s.character_id=v_char.id
        where c.enabled=true
      ),'[]'::jsonb)
    ),
    'showcase',jsonb_build_object(
      'loadout',coalesce((
        select jsonb_build_object(
          'title_key',s.title_key,'badge_key',s.badge_key,'collectible_key',s.collectible_key
        ) from public.tgg_world_showcase_loadouts s where s.character_id=v_char.id
      ),'{}'::jsonb),
      'titles',coalesce((
        select jsonb_agg(jsonb_build_object(
          'title_key',t.title_key,'display_name',t.display_name,'category',t.category,'equipped',ct.equipped
        ) order by t.display_name)
        from public.tgg_world_character_titles ct
        join public.tgg_world_titles t on t.title_key=ct.title_key
        where ct.character_id=v_char.id
      ),'[]'::jsonb),
      'badges',coalesce((
        select jsonb_agg(jsonb_build_object(
          'badge_key',b.badge_key,'display_name',b.display_name,'category',b.category
        ) order by b.display_name)
        from public.tgg_world_character_badges cb
        join public.tgg_world_badges b on b.badge_key=cb.badge_key
        where cb.character_id=v_char.id
      ),'[]'::jsonb),
      'collectibles',coalesce((
        select jsonb_agg(jsonb_build_object(
          'collectible_key',c.collectible_key,'display_name',c.display_name,
          'rarity',c.rarity,'quantity',cc.quantity
        ) order by c.display_name)
        from public.tgg_world_character_collectibles cc
        join public.tgg_world_collectibles c on c.collectible_key=cc.collectible_key
        where cc.character_id=v_char.id
      ),'[]'::jsonb)
    )
  );
end;
$function$


-- [40000000311] function private.tgg_world_complete_business_competition(p_run_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_complete_business_competition(p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_char uuid;
  v_run public.tgg_world_character_business_competitions%rowtype;
  v_b public.tgg_world_character_businesses%rowtype;
  v_c public.tgg_world_business_competitions%rowtype;
  v_score integer; v_xp integer; v_rep integer;
  v_xp_base integer:=0;
  v_metric_bonus numeric:=0;
  v_fx jsonb:='{}'::jsonb;
  v_mod jsonb:='{}'::jsonb;
  v_business_multiplier numeric:=1;
  v_business_cap integer:=5;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select id into v_char from public.world_characters where user_id=v_uid and character_status='active' limit 1;

  select r.* into v_run
  from public.tgg_world_character_business_competitions r
  join public.tgg_world_character_businesses b on b.id=r.business_id
  where r.id=p_run_id and b.character_id=v_char and r.status='running'
  for update of r;
  if v_run.id is null then raise exception 'running_competition_required'; end if;

  select * into v_b from public.tgg_world_character_businesses where id=v_run.business_id for update;
  select * into v_c from public.tgg_world_business_competitions where competition_key=v_run.competition_key and enabled=true;

  if now()<v_run.started_at+make_interval(hours=>v_c.duration_hours) then raise exception 'competition_not_ready'; end if;

  v_fx:=private.tgg_world_property_effects(v_char);
  v_mod:=private.tgg_world_effective_modifiers(v_char);
  v_business_multiplier:=greatest(coalesce((v_mod->>'business_xp_multiplier')::numeric,1),1);

  v_metric_bonus:=case v_c.metric_key
    when 'brand_reputation' then coalesce((v_fx->>'brand_reputation')::numeric,0)
    when 'session_quality' then coalesce((v_fx->>'studio_quality')::numeric,0)
    when 'attendance' then
      coalesce((v_fx->>'event_hype')::numeric,0)
      + coalesce((v_fx->>'capacity_bonus')::numeric,0)
      + 100*coalesce((v_fx->>'vip_bonus')::numeric,0)
    when 'content_quality' then 100*coalesce((v_fx->>'creator_bonus')::numeric,0)
    else 0
  end;

  v_score:=v_b.business_level*100+v_b.reputation+v_b.business_xp/10+round(v_metric_bonus)::integer;
  v_xp_base:=greatest(coalesce((v_c.rewards->>'business_xp')::integer,0),0);
  v_xp:=greatest(round(v_xp_base*v_business_multiplier)::integer,0);
  select greatest(coalesce((progression->>'levels')::integer,5),1)
  into v_business_cap
  from public.tgg_world_business_types
  where business_type_key=v_b.business_type_key;
  v_business_cap:=coalesce(v_business_cap,5);
  v_rep:=coalesce((v_c.rewards->>'reputation')::integer,0);

  update public.tgg_world_character_businesses
  set business_xp=business_xp+v_xp,
      business_level=least(v_business_cap,greatest(business_level,1+((business_xp+v_xp)/250))),
      reputation=reputation+v_rep,updated_at=now()
  where id=v_b.id;

  update public.tgg_world_character_business_competitions
  set status='completed',score=v_score,
      result=jsonb_build_object('success',true,'rewards',v_c.rewards,'score',v_score,'metric_bonus',v_metric_bonus,'business_xp_applied',v_xp,'business_xp_multiplier',v_business_multiplier),
      completed_at=now(),updated_at=now()
  where id=v_run.id;

  insert into public.tgg_world_character_influence(character_id,business_influence,updated_at)
  values(v_char,greatest(v_rep,0),now())
  on conflict(character_id) do update
  set business_influence=public.tgg_world_character_influence.business_influence+greatest(v_rep,0),updated_at=now();

  perform private.tgg_recompute_progression(v_char);

  return jsonb_build_object('ok',true,'score',v_score,'metric_bonus',v_metric_bonus,'property_effects',v_fx,'business_xp_base',v_xp_base,'business_xp_awarded',v_xp,'business_xp_multiplier',v_business_multiplier,'business_reputation_awarded',v_rep,'real_money_changed',false);
end;
$function$


-- [40000000312] function private.tgg_world_complete_business_operation(p_operation_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_complete_business_operation(p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_run public.tgg_world_character_business_operations%rowtype;
  v_business public.tgg_world_character_businesses%rowtype;
  v_op public.tgg_world_business_operations%rowtype;
  v_business_xp integer:=0;
  v_business_rep integer:=0;
  v_business_xp_applied integer:=0;
  v_mod jsonb:='{}'::jsonb;
  v_business_multiplier numeric:=1;
  v_max_level integer:=5;
  v_new_xp integer;
  v_new_rep integer;
  v_event uuid;
  v_ch public.tgg_world_character_challenges%rowtype;
  v_ch_t public.tgg_world_challenge_templates%rowtype;
  v_progress jsonb;
  v_need integer;
  v_done integer;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select r.* into v_run
  from public.tgg_world_character_business_operations r
  join public.tgg_world_character_businesses b on b.id=r.business_id
  join public.world_characters wc on wc.id=b.character_id
  where r.id=p_operation_id and wc.user_id=v_uid and r.status='running'
  for update of r;
  if v_run.id is null then raise exception 'running_operation_not_found'; end if;

  select b.* into v_business
  from public.tgg_world_character_businesses b
  join public.world_characters wc on wc.id=b.character_id
  where b.id=v_run.business_id and wc.user_id=v_uid
  for update of b;
  if v_business.id is null then raise exception 'business_ownership_required'; end if;

  select * into v_op
  from public.tgg_world_business_operations
  where operation_key=v_run.operation_key and enabled=true;
  if v_op.operation_key is null then raise exception 'operation_template_unavailable'; end if;

  if now()<v_run.started_at+make_interval(mins=>v_op.duration_minutes) then
    raise exception 'operation_not_ready';
  end if;

  v_business_xp:=greatest(coalesce((v_op.rewards->>'business_xp')::integer,0),0);
  v_business_rep:=greatest(
    coalesce((v_op.rewards->>'reputation')::integer,0)+
    coalesce((v_op.rewards->>'brand_reputation')::integer,0),
    0
  );

  select greatest(coalesce((progression->>'levels')::integer,5),1)
  into v_max_level
  from public.tgg_world_business_types
  where business_type_key=v_business.business_type_key;

  v_mod:=private.tgg_world_effective_modifiers(v_business.character_id);
  v_business_multiplier:=greatest(coalesce((v_mod->>'business_xp_multiplier')::numeric,1),1);
  v_business_xp_applied:=greatest(round(v_business_xp*v_business_multiplier)::integer,0);
  v_new_rep:=v_business.reputation+v_business_rep;

  update public.tgg_world_character_businesses
  set reputation=v_new_rep,
      updated_at=now()
  where id=v_business.id;

  update public.tgg_world_character_business_operations
  set status='completed',
      completed_at=now(),
      result=jsonb_build_object('success',true,'rewards',v_op.rewards),
      updated_at=now()
  where id=v_run.id;

  v_event:=private.tgg_apply_progression_event(
    v_business.character_id,
    'business_operation_completed',
    v_op.operation_key,
    jsonb_build_object(
      'business_id',v_business.id,
      'business_xp',v_business_xp
    )
  );

  perform private.tgg_world_credit_challenge_event(
    v_business.character_id,'business_ops_completed','business_operation',v_run.id::text
  );

  return jsonb_build_object(
    'operation_id',v_run.id,
    'operation_key',v_op.operation_key,
    'completed',true,
    'business_id',v_business.id,
    'business_xp_awarded',v_business_xp_applied,
    'business_xp_base',v_business_xp,
    'business_xp_multiplier',v_business_multiplier,
    'business_reputation_awarded',v_business_rep,
    'progression_event_id',v_event,
    'virtual_currency_changed',false,
    'real_money_changed',false
  );
end;
$function$


-- [40000000313] function private.tgg_world_consequence_performance_trigger()
CREATE OR REPLACE FUNCTION private.tgg_world_consequence_performance_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_location text;
begin
  if new.performance_status='completed'
     and old.performance_status is distinct from 'completed' then
    select e.location_key into v_location
    from public.tgg_world_open_mic_events e
    where e.id=new.event_id;

    if v_location is not null then
      perform private.tgg_world_apply_consequence_rules(
        new.character_id,'performance_complete',v_location,
        'open_mic_performance',new.id::text
      );
    end if;
  end if;
  return new;
end;
$function$


-- [40000000314] function private.tgg_world_consequence_progression_trigger()
CREATE OR REPLACE FUNCTION private.tgg_world_consequence_progression_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_trigger_type text;
begin
  v_trigger_type:=case new.event_type
    when 'contract_completed' then 'contract_complete'
    when 'dialogue_choice' then 'dialogue_choice'
    else null
  end;

  if v_trigger_type is not null and new.source_key is not null then
    perform private.tgg_world_apply_consequence_rules(
      new.character_id,v_trigger_type,new.source_key,
      'progression_event',new.id::text
    );
  end if;

  return new;
end;
$function$


-- [40000000315] function private.tgg_world_create_character_impl(p_stage_name text, p_avatar_config jsonb, p_active_career text)
CREATE OR REPLACE FUNCTION private.tgg_world_create_character_impl(p_stage_name text, p_avatar_config jsonb DEFAULT '{}'::jsonb, p_active_career text DEFAULT 'artist'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_character public.world_characters%rowtype;
  v_location uuid;
  v_name text;
  v_career text;
begin
  if v_user is null then raise exception 'authentication required'; end if;

  v_name := nullif(trim(coalesce(p_stage_name,'')),'');
  if v_name is null or length(v_name) < 2 or length(v_name) > 40 then
    raise exception 'stage name must be between 2 and 40 characters';
  end if;

  v_career := lower(trim(coalesce(p_active_career,'artist')));
  if v_career not in (
    'artist','singer','producer','songwriter','dj','engineer','musician',
    'dancer','director','photographer','videographer','editor','actor','host',
    'comedian','manager','promoter','booking_agent','label_owner','venue_owner',
    'studio_owner','tour_manager','a_and_r','publicist','designer','jeweler',
    'stylist','barber','makeup_artist','tattoo_artist','model','fitness_coach',
    'chef','security','fan'
  ) then raise exception 'unsupported career'; end if;

  select l.id into v_location
  from public.tgg_world_locations l
  join public.tgg_world_blueprints b on b.id=l.blueprint_id
  where b.blueprint_key='tgg-world-alpha-city'
    and l.location_key='starter-apartment'
    and l.enabled=true
  limit 1;

  if v_location is null then raise exception 'starter apartment is unavailable'; end if;

  insert into public.world_characters(
    user_id,stage_name,avatar_config,active_career,current_location_id
  )
  values(v_user,v_name,coalesce(p_avatar_config,'{}'::jsonb),v_career,v_location)
  on conflict(user_id) do update
  set stage_name=excluded.stage_name,
      avatar_config=excluded.avatar_config,
      active_career=excluded.active_career,
      updated_at=now()
  returning * into v_character;

  insert into public.world_character_stats(character_id,stat_key,stat_value)
  values
    (v_character.id,'level',1),(v_character.id,'xp',0),(v_character.id,'fame',0),
    (v_character.id,'buzz',0),(v_character.id,'respect',0),(v_character.id,'influence',0),
    (v_character.id,'talent',1),(v_character.id,'creativity',1),(v_character.id,'charisma',1),
    (v_character.id,'discipline',1),(v_character.id,'confidence',1),(v_character.id,'stage_presence',1),
    (v_character.id,'business_sense',1),(v_character.id,'fashion',1),(v_character.id,'networking',1),
    (v_character.id,'musicianship',1),(v_character.id,'leadership',1),(v_character.id,'stamina',1)
  on conflict(character_id,stat_key) do nothing;

  insert into public.world_character_careers(character_id,career_key,career_level,career_xp,unlocked)
  values(v_character.id,v_career,1,0,true)
  on conflict(character_id,career_key) do update
  set unlocked=true,updated_at=now();

  return jsonb_build_object('character',to_jsonb(v_character),'created_or_updated',true);
end
$function$


-- [40000000316] function private.tgg_world_creative_credit_beat_trigger()
