-- [40000000317] function private.tgg_world_creative_credit_live_trigger()
CREATE OR REPLACE FUNCTION private.tgg_world_creative_credit_live_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  if new.status='ENDED' and old.status is distinct from 'ENDED'
     and new.actual_start is not null and new.actual_end is not null
     and extract(epoch from (new.actual_end-new.actual_start))>=60 then
    perform private.tgg_world_creative_mission_credit(new.creator_id,'live_ended',new.id::text);
  end if;
  return new;
end;
$function$


