-- [40000000321] function private.tgg_world_creative_mission_credit(p_user_id uuid, p_source_type text, p_source_id text)
CREATE OR REPLACE FUNCTION private.tgg_world_creative_mission_credit(p_user_id uuid, p_source_type text, p_source_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_char uuid;
  v_m record;
  v_state public.tgg_world_character_creative_missions%rowtype;
  v_inserted integer;
  v_progress integer;
  v_completed boolean;
  v_event uuid;
  v_count integer:=0;
  v_skipped_cooldown integer:=0;
begin
  select id into v_char
  from public.world_characters
  where user_id=p_user_id and character_status='active'
  limit 1;

  if v_char is null then
    return jsonb_build_object('credited',false,'reason','no_active_world_character');
  end if;

  for v_m in
    select *
    from public.tgg_world_creative_missions
    where enabled=true and source_type=p_source_type
  loop
    select * into v_state
    from public.tgg_world_character_creative_missions
    where character_id=v_char and mission_key=v_m.mission_key
    for update;

    if found
       and v_m.repeatable
       and v_state.last_completed_at is not null
       and v_state.last_completed_at+make_interval(hours=>v_m.cooldown_hours)>now()
    then
      v_skipped_cooldown:=v_skipped_cooldown+1;
      continue;
    end if;

    if found and not v_m.repeatable and v_state.status='completed' then
      continue;
    end if;

    insert into public.tgg_world_creative_mission_credits(
      character_id,mission_key,source_type,source_id,credited_at
    )
    values(v_char,v_m.mission_key,p_source_type,p_source_id,now())
    on conflict(character_id,mission_key,source_type,source_id) do nothing;

    get diagnostics v_inserted = row_count;
    if v_inserted=0 then continue; end if;

    insert into public.tgg_world_character_creative_missions(
      character_id,mission_key,status,progress,completions,updated_at
    )
    values(v_char,v_m.mission_key,'active',0,0,now())
    on conflict(character_id,mission_key) do nothing;

    update public.tgg_world_character_creative_missions
    set progress=progress+1,updated_at=now()
    where character_id=v_char and mission_key=v_m.mission_key
    returning progress into v_progress;

    v_completed:=v_progress>=v_m.required_count;

    if v_completed then
      v_event:=private.tgg_apply_progression_event(
        v_char,'creative_mission_completed',v_m.mission_key,
        jsonb_build_object(
          'career_xp',coalesce((v_m.rewards->>'career_xp')::integer,0),
          'reputation',coalesce((v_m.rewards->>'reputation')::integer,0),
          'season_xp',coalesce((v_m.rewards->>'season_xp')::integer,0)
        )
      );

      update public.tgg_world_character_creative_missions
      set completions=completions+1,
          last_completed_at=now(),
          progress=case when v_m.repeatable then 0 else v_progress end,
          status=case when v_m.repeatable then 'active' else 'completed' end,
          updated_at=now()
      where character_id=v_char and mission_key=v_m.mission_key;

      perform private.tgg_recompute_progression(v_char);
    end if;

    v_count:=v_count+1;
  end loop;

  return jsonb_build_object(
    'credited',v_count>0,
    'mission_rows',v_count,
    'skipped_cooldown',v_skipped_cooldown,
    'character_id',v_char
  );
end;
$function$


-- [40000000322] function private.tgg_world_creative_missions_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_creative_missions_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  return jsonb_build_object(
    'character_id',v_char,
    'missions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'mission_key',m.mission_key,
        'display_name',m.display_name,
        'source_type',m.source_type,
        'required_count',m.required_count,
        'rewards',m.rewards,
        'repeatable',m.repeatable,
        'cooldown_hours',m.cooldown_hours,
        'metadata',m.metadata,
        'tool_url',case m.mission_key
          when 'creative-beat-builder' then 'https://trugogettamixtapes.blogspot.com/p/beat-studio.html'
          when 'creative-recording-run' then 'https://trugogettamixtapes.blogspot.com/p/recording-studio.html'
          when 'creative-video-drop' then 'https://trugogettamixtapes.blogspot.com/p/video-studio.html'
          when 'creative-radio-submit' then 'https://trugogettamixtapes.blogspot.com/p/tgg-radio.html'
          when 'creative-go-live' then 'https://trugogettamixtapes.blogspot.com/p/live.html'
          else 'https://trugogettamixtapes.blogspot.com/p/create-hub.html'
        end,
        'state',jsonb_build_object(
          'status',coalesce(s.status,'active'),
          'progress',coalesce(s.progress,0),
          'completions',coalesce(s.completions,0),
          'last_completed_at',s.last_completed_at,
          'cooldown_ready_at',case
            when s.last_completed_at is null then null
            else s.last_completed_at+make_interval(hours=>m.cooldown_hours)
          end,
          'cooldown_active',coalesce(
            s.last_completed_at+make_interval(hours=>m.cooldown_hours)>now(),
            false
          )
        )
      ) order by m.display_name)
      from public.tgg_world_creative_missions m
      left join public.tgg_world_character_creative_missions s
        on s.character_id=v_char and s.mission_key=m.mission_key
      where m.enabled=true
    ),'[]'::jsonb)
  );
end;
$function$


