-- [40000000324] function private.tgg_world_credit_award(p_character_id uuid, p_amount integer, p_reference_type text, p_reference_key text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION private.tgg_world_credit_award(p_character_id uuid, p_amount integer, p_reference_type text, p_reference_key text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid;
  v_cap integer:=5000;
  v_today_minted integer:=0;
  v_award integer:=0;
  v_balance bigint:=0;
begin
  if p_amount is null or p_amount<1 then raise exception 'positive_credit_award_required'; end if;

  select user_id into v_uid
  from public.world_characters
  where id=p_character_id and character_status='active'
  limit 1;
  if v_uid is null then raise exception 'active_character_required'; end if;

  select greatest(coalesce((value->>'daily_virtual_credit_softcap')::integer,5000),0)
  into v_cap
  from public.tgg_world_economy_config
  where config_key='anti-inflation-softcap';
  v_cap:=coalesce(v_cap,5000);

  select coalesce(sum(amount),0)::integer
  into v_today_minted
  from public.tgg_world_wallet_ledger
  where character_id=p_character_id
    and amount>0
    and entry_type='reward_credit'
    and created_at>=date_trunc('day',now());

  v_award:=greatest(least(p_amount,greatest(v_cap-v_today_minted,0)),0);

  if v_award=0 then
    return jsonb_build_object(
      'ok',false,'reason','daily_virtual_credit_softcap_reached',
      'requested',p_amount,'awarded',0,'daily_softcap',v_cap,
      'today_minted',v_today_minted,'virtual_currency',true,'real_money',false
    );
  end if;

  insert into public.tgg_world_wallets(user_id,character_id,balance,currency_key,created_at,updated_at)
  values(v_uid,p_character_id,0,'tgg_credits',now(),now())
  on conflict(user_id) do nothing;

  update public.tgg_world_wallets
  set balance=balance+v_award,updated_at=now()
  where user_id=v_uid
  returning balance into v_balance;

  insert into public.tgg_world_wallet_ledger(
    user_id,character_id,entry_type,amount,balance_after,reference_type,reference_key,metadata,created_at
  )
  values(
    v_uid,p_character_id,'reward_credit',v_award,v_balance,
    left(coalesce(p_reference_type,'reward'),64),
    left(coalesce(p_reference_key,'reward'),120),
    coalesce(p_metadata,'{}'::jsonb)
      ||jsonb_build_object(
        'requested_amount',p_amount,
        'daily_softcap',v_cap,
        'today_minted_before',v_today_minted,
        'virtual_currency',true,
        'real_money',false
      ),
    now()
  );

  return jsonb_build_object(
    'ok',true,'requested',p_amount,'awarded',v_award,
    'daily_softcap',v_cap,'today_minted_before',v_today_minted,
    'balance',v_balance,'virtual_currency',true,'real_money',false
  );
end;
$function$


-- [40000000325] function private.tgg_world_credit_career_mission_event(p_character_id uuid, p_objective_key text, p_source_type text, p_source_id text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION private.tgg_world_credit_career_mission_event(p_character_id uuid, p_objective_key text, p_source_type text, p_source_id text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_char public.world_characters%rowtype;
  v_location_key text;
  v_mission record;
  v_state public.tgg_world_career_mission_progress%rowtype;
  v_required integer;
  v_progress jsonb;
  v_current integer;
  v_all_met boolean;
  v_inserted integer;
  v_event uuid;
  v_district jsonb;
  v_buzz integer:=0;
  v_unlock text;
  v_credited integer:=0;
  v_completed integer:=0;
  v_results jsonb:='[]'::jsonb;
  v_max_failed integer;
  v_failed_takes integer:=0;
begin
  if p_character_id is null
     or nullif(btrim(coalesce(p_objective_key,'')),'') is null
     or nullif(btrim(coalesce(p_source_id,'')),'') is null then
    return jsonb_build_object('credited',0,'completed',0,'reason','invalid_input');
  end if;

  select wc.* into v_char
  from public.world_characters wc
  where wc.id=p_character_id and wc.character_status='active';

  if v_char.id is null then
    return jsonb_build_object('credited',0,'completed',0,'reason','character_not_found');
  end if;

  if auth.uid() is not null and v_char.user_id<>auth.uid() then
    raise exception 'character_ownership_mismatch';
  end if;

  select l.location_key into v_location_key
  from public.tgg_world_locations l
  where l.id=v_char.current_location_id;

  for v_mission in
    select
      m.*,
      o as objective,
      coalesce(nullif(o->>'action_key',''),o->>'type') as progress_key
    from public.tgg_world_career_missions m
    cross join lateral jsonb_array_elements(m.objectives) o
    where m.enabled=true
      and m.career_key=v_char.active_career
      and (
        m.location_key=v_location_key
        or p_source_type in ('booking','recording_session','live_clip')
      )
      and coalesce(nullif(o->>'action_key',''),o->>'type')=p_objective_key
    order by m.mission_key
  loop
    v_required:=greatest(coalesce((v_mission.objective->>'count')::integer,1),1);
    v_max_failed:=case
      when v_mission.objective ? 'max_failed_takes'
      then greatest((v_mission.objective->>'max_failed_takes')::integer,0)
      else null
    end;
    v_failed_takes:=greatest(coalesce((p_metadata->>'failed_takes')::integer,0),0);

    if v_max_failed is not null and v_failed_takes>v_max_failed then
      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'mission_key',v_mission.mission_key,
        'credited',false,
        'reason','failed_take_limit_exceeded',
        'failed_takes',v_failed_takes,
        'max_failed_takes',v_max_failed
      ));
      continue;
    end if;

    insert into public.tgg_world_career_mission_progress(
      character_id,mission_key,status,progress,started_at,updated_at
    )
    values(v_char.id,v_mission.mission_key,'active','{}'::jsonb,now(),now())
    on conflict(character_id,mission_key) do nothing;

    select * into v_state
    from public.tgg_world_career_mission_progress
    where character_id=v_char.id and mission_key=v_mission.mission_key
    for update;

    if v_state.status='completed' and not v_mission.repeatable then
      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'mission_key',v_mission.mission_key,'completed',true,'replayed',true
      ));
      continue;
    end if;

    if v_state.status='completed' and v_mission.repeatable then
      if exists(
        select 1
        from public.tgg_world_career_mission_credits cr
        where cr.character_id=v_char.id
          and cr.mission_key=v_mission.mission_key
          and cr.objective_key=p_objective_key
          and cr.source_type=left(coalesce(p_source_type,'event'),64)
          and cr.source_id=left(p_source_id,180)
      ) then
        v_results:=v_results||jsonb_build_array(jsonb_build_object(
          'mission_key',v_mission.mission_key,
          'completed',true,
          'credited',false,
          'replayed',true
        ));
        continue;
      end if;

      update public.tgg_world_career_mission_progress
      set status='active',progress='{}'::jsonb,started_at=now(),completed_at=null,updated_at=now()
      where id=v_state.id;
      v_state.progress:='{}'::jsonb;
    end if;

    insert into public.tgg_world_career_mission_credits(
      character_id,mission_key,objective_key,source_type,source_id,metadata
    )
    values(
      v_char.id,v_mission.mission_key,p_objective_key,
      left(coalesce(p_source_type,'event'),64),
      left(p_source_id,180),
      coalesce(p_metadata,'{}'::jsonb)
    )
    on conflict do nothing;

    get diagnostics v_inserted=row_count;
    if v_inserted=0 then
      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'mission_key',v_mission.mission_key,'credited',false,'replayed',true
      ));
      continue;
    end if;

    v_progress:=coalesce(v_state.progress,'{}'::jsonb);
    v_current:=least(
      v_required,
      greatest(coalesce((v_progress->>p_objective_key)::integer,0),0)+1
    );
    v_progress:=jsonb_set(v_progress,array[p_objective_key],to_jsonb(v_current),true);

    select coalesce(bool_and(
      coalesce((v_progress->>coalesce(nullif(o->>'action_key',''),o->>'type'))::integer,0)
      >= greatest((o->>'count')::integer,1)
    ),false)
    into v_all_met
    from jsonb_array_elements(v_mission.objectives) o;

    update public.tgg_world_career_mission_progress
    set progress=v_progress,
        status=case when v_all_met then 'completed' else 'active' end,
        completed_at=case when v_all_met then coalesce(completed_at,now()) else completed_at end,
        updated_at=now()
    where id=v_state.id;

    v_credited:=v_credited+1;

    if v_all_met then
      v_buzz:=greatest(coalesce((v_mission.rewards->>'buzz')::integer,0),0);
      if v_buzz>0 then
        insert into public.world_character_stats(character_id,stat_key,stat_value)
        values(v_char.id,'buzz',v_buzz)
        on conflict(character_id,stat_key) do update
        set stat_value=public.world_character_stats.stat_value+excluded.stat_value;
      end if;

      v_unlock:=nullif(v_mission.rewards->>'career_unlock','');
      if v_unlock is not null then
        insert into public.tgg_world_career_unlocks(
          character_id,unlock_key,source_type,source_key,metadata,unlocked_at
        )
        values(
          v_char.id,v_unlock,'career_mission_reward',v_mission.mission_key,
          jsonb_build_object(
            'career_key',v_mission.career_key,
            'unlock_type','career_mission_marker',
            'source_title',v_mission.title
          ),
          now()
        )
        on conflict(character_id,unlock_key) do update
        set metadata=public.tgg_world_career_unlocks.metadata||excluded.metadata,
            source_type=excluded.source_type,
            source_key=excluded.source_key,
            unlocked_at=least(public.tgg_world_career_unlocks.unlocked_at,excluded.unlocked_at);
      end if;

      v_event:=private.tgg_apply_progression_event(
        v_char.id,
        'career_mission_completed',
        v_mission.mission_key,
        jsonb_strip_nulls(jsonb_build_object(
          'career_xp',greatest(v_mission.xp_reward,0),
          'reputation',coalesce((v_mission.rewards->>'reputation')::integer,0),
          'season_xp',coalesce((v_mission.rewards->>'season_xp')::integer,0)
        ))
      );

      v_district:=private.tgg_world_apply_district_progress(v_char.id,v_mission.location_key,10);
      perform private.tgg_recompute_progression(v_char.id);
      v_completed:=v_completed+1;
    end if;

    v_results:=v_results||jsonb_build_array(jsonb_build_object(
      'mission_key',v_mission.mission_key,
      'objective_key',p_objective_key,
      'current',v_current,
      'required',v_required,
      'completed',v_all_met,
      'progression_event_id',v_event,
      'district_progress',coalesce(v_district,'{}'::jsonb),
      'buzz_awarded',case when v_all_met then v_buzz else 0 end,
      'career_unlock',case when v_all_met then v_unlock else null end
    ));
  end loop;

  return jsonb_build_object(
    'credited',v_credited,
    'completed',v_completed,
    'objective_key',p_objective_key,
    'source_type',p_source_type,
    'source_id',p_source_id,
    'results',v_results
  );
end;
$function$


-- [40000000326] function private.tgg_world_credit_challenge_event(p_character_id uuid, p_action_key text, p_source_type text, p_source_id text)
CREATE OR REPLACE FUNCTION private.tgg_world_credit_challenge_event(p_character_id uuid, p_action_key text, p_source_type text, p_source_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_ch record;
  v_required integer;
  v_current integer;
  v_progress jsonb;
  v_all_met boolean;
  v_inserted integer;
  v_event uuid;
  v_business_id uuid;
  v_crew_id uuid;
  v_business_xp integer;
  v_crew_xp integer;
  v_crew_rep integer;
  v_credited integer:=0;
  v_completed integer:=0;
  v_results jsonb:='[]'::jsonb;
begin
  if p_character_id is null
     or not exists(select 1 from public.world_characters where id=p_character_id) then
    return jsonb_build_object('credited',0,'completed',0,'reason','character_not_found');
  end if;

  for v_ch in
    select c.character_id,c.challenge_key,c.period_key,c.progress,t.requirements,t.rewards
    from public.tgg_world_character_challenges c
    join public.tgg_world_challenge_templates t on t.challenge_key=c.challenge_key and t.enabled=true
    where c.character_id=p_character_id
      and c.status='active'
      and c.period_key=private.tgg_world_challenge_period(t.cadence)
      and t.requirements ? p_action_key
    order by c.updated_at,c.challenge_key
  loop
    insert into public.tgg_world_challenge_action_credits(
      character_id,challenge_key,period_key,action_key,source_type,source_id,metadata
    )
    values(
      p_character_id,v_ch.challenge_key,v_ch.period_key,p_action_key,
      left(coalesce(p_source_type,'event'),64),
      left(coalesce(p_source_id,'event'),160),
      '{}'::jsonb
    )
    on conflict do nothing;

    get diagnostics v_inserted=row_count;
    if v_inserted=0 then
      continue;
    end if;

    select c.progress into v_progress
    from public.tgg_world_character_challenges c
    where c.character_id=p_character_id
      and c.challenge_key=v_ch.challenge_key
      and c.period_key=v_ch.period_key
      and c.status='active'
    for update;

    if not found then
      continue;
    end if;

    v_required:=greatest(coalesce((v_ch.requirements->>p_action_key)::integer,0),1);
    v_current:=least(
      v_required,
      greatest(coalesce((v_progress->>p_action_key)::integer,0),0)+1
    );
    v_progress:=jsonb_set(v_progress,array[p_action_key],to_jsonb(v_current),true);

    update public.tgg_world_character_challenges
    set progress=v_progress,updated_at=now()
    where character_id=p_character_id
      and challenge_key=v_ch.challenge_key
      and period_key=v_ch.period_key;

    select coalesce(bool_and(
      coalesce((v_progress->>k)::integer,0)>=greatest((v_ch.requirements->>k)::integer,1)
    ),false)
    into v_all_met
    from jsonb_object_keys(v_ch.requirements) k;

    v_credited:=v_credited+1;

    if v_all_met then
      update public.tgg_world_character_challenges
      set status='completed',
          completed_at=coalesce(completed_at,now()),
          progress=v_progress,
          updated_at=now()
      where character_id=p_character_id
        and challenge_key=v_ch.challenge_key
        and period_key=v_ch.period_key
        and status='active';

      v_business_id:=null;
      v_crew_id:=null;
      v_business_xp:=greatest(coalesce((v_ch.rewards->>'business_xp')::integer,0),0);
      v_crew_xp:=greatest(coalesce((v_ch.rewards->>'crew_xp')::integer,0),0);
      v_crew_rep:=greatest(coalesce((v_ch.rewards->>'crew_rep')::integer,0),0);

      if v_business_xp>0 then
        select id into v_business_id
        from public.tgg_world_character_businesses
        where character_id=p_character_id and status='active'
        order by business_level desc,business_xp desc,updated_at desc
        limit 1;
      end if;

      if v_crew_xp>0 or v_crew_rep>0 then
        select crew_id into v_crew_id
        from public.tgg_world_crew_members
        where character_id=p_character_id and left_at is null
        order by joined_at desc
        limit 1;
      end if;

      if v_crew_id is not null and v_crew_rep>0 then
        insert into public.tgg_world_crew_progression(
          crew_id,crew_xp,rank_level,reputation,unlocks,updated_at
        )
        values(v_crew_id,0,1,v_crew_rep,'{}'::jsonb,now())
        on conflict(crew_id) do update
        set reputation=public.tgg_world_crew_progression.reputation+v_crew_rep,
            updated_at=now();
      end if;

      v_event:=private.tgg_apply_progression_event(
        p_character_id,'challenge_completed',v_ch.challenge_key,
        jsonb_strip_nulls(jsonb_build_object(
          'career_xp',coalesce((v_ch.rewards->>'career_xp')::integer,0),
          'reputation',coalesce((v_ch.rewards->>'reputation')::integer,0),
          'season_xp',coalesce((v_ch.rewards->>'season_xp')::integer,0),
          'crew_id',v_crew_id,
          'crew_xp',v_crew_xp,
          'business_id',v_business_id,
          'business_xp',v_business_xp,
          'influence',coalesce((v_ch.rewards->>'district_influence')::integer,0)
        ))
      );

      v_completed:=v_completed+1;
      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'challenge_key',v_ch.challenge_key,
        'completed',true,
        'progression_event_id',v_event
      ));
    else
      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'challenge_key',v_ch.challenge_key,
        'completed',false,
        'current',v_current,
        'required',v_required
      ));
    end if;
  end loop;

  return jsonb_build_object(
    'credited',v_credited,
    'completed',v_completed,
    'action_key',p_action_key,
    'source_type',p_source_type,
    'source_id',p_source_id,
    'results',v_results
  );
end;
$function$


-- [40000000327] function private.tgg_world_credit_contract_event(p_character_id uuid, p_objective_type text, p_source_type text, p_source_id text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION private.tgg_world_credit_contract_event(p_character_id uuid, p_objective_type text, p_source_type text, p_source_id text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_char public.world_characters%rowtype;
  v_state public.tgg_world_character_contracts%rowtype;
  v_contract public.tgg_world_career_contracts%rowtype;
  v_required integer;
  v_current integer;
  v_progress jsonb;
  v_all_met boolean;
  v_inserted integer;
  v_event uuid;
  v_district jsonb;
  v_unlock text;
  v_unlock_type text;
  v_npc_key text;
  v_credited integer:=0;
  v_completed integer:=0;
  v_results jsonb:='[]'::jsonb;
begin
  if p_character_id is null
     or nullif(btrim(coalesce(p_objective_type,'')),'') is null
     or nullif(btrim(coalesce(p_source_id,'')),'') is null then
    return jsonb_build_object('credited',0,'completed',0,'reason','invalid_input');
  end if;

  select * into v_char
  from public.world_characters
  where id=p_character_id and character_status='active';

  if v_char.id is null then
    return jsonb_build_object('credited',0,'completed',0,'reason','character_not_found');
  end if;

  if auth.uid() is not null and v_char.user_id<>auth.uid() then
    raise exception 'character_ownership_mismatch';
  end if;

  for v_state in
    select cc.*
    from public.tgg_world_character_contracts cc
    join public.tgg_world_career_contracts c
      on c.contract_key=cc.contract_key and c.enabled=true
    where cc.character_id=v_char.id
      and cc.status='active'
      and c.career_key=v_char.active_career
      and exists(
        select 1 from jsonb_array_elements(c.objectives) o
        where o->>'type'=p_objective_type
      )
    order by cc.accepted_at,cc.id
  loop
    select * into v_contract
    from public.tgg_world_career_contracts
    where contract_key=v_state.contract_key and enabled=true;

    select cc.* into v_state
    from public.tgg_world_character_contracts cc
    where cc.id=v_state.id and cc.status='active'
    for update;

    if v_state.id is null then
      continue;
    end if;

    select (o->>'count')::integer into v_required
    from jsonb_array_elements(v_contract.objectives) o
    where o->>'type'=p_objective_type
    limit 1;

    if v_required is null or v_required<1 then
      continue;
    end if;

    insert into public.tgg_world_contract_credits(
      character_id,contract_id,contract_key,objective_type,source_type,source_id,metadata
    )
    values(
      v_char.id,v_state.id,v_contract.contract_key,p_objective_type,
      left(coalesce(p_source_type,'event'),64),
      left(p_source_id,180),
      coalesce(p_metadata,'{}'::jsonb)
    )
    on conflict do nothing;

    get diagnostics v_inserted=row_count;
    if v_inserted=0 then
      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'contract_key',v_contract.contract_key,'credited',false,'replayed',true
      ));
      continue;
    end if;

    v_progress:=coalesce(v_state.progress,'{}'::jsonb);
    v_current:=least(
      v_required,
      greatest(coalesce((v_progress->>p_objective_type)::integer,0),0)+1
    );
    v_progress:=jsonb_set(v_progress,array[p_objective_type],to_jsonb(v_current),true);

    select coalesce(bool_and(
      coalesce((v_progress->>(o->>'type'))::integer,0)>=(o->>'count')::integer
    ),false)
    into v_all_met
    from jsonb_array_elements(v_contract.objectives) o;

    update public.tgg_world_character_contracts
    set progress=v_progress,
        status=case when v_all_met then 'completed' else 'active' end,
        completed_at=case when v_all_met then coalesce(completed_at,now()) else completed_at end,
        updated_at=now()
    where id=v_state.id;

    v_credited:=v_credited+1;

    if v_all_met then
      select n.npc_key into v_npc_key
      from public.tgg_world_industry_contacts i
      join public.tgg_world_npc_profiles n on lower(n.display_name)=lower(i.display_name)
      where i.contact_key=v_contract.contact_key
      limit 1;

      v_event:=private.tgg_apply_progression_event(
        v_char.id,
        'contract_completed',
        v_contract.contract_key,
        jsonb_strip_nulls(jsonb_build_object(
          'career_xp',coalesce((v_contract.rewards->>'career_xp')::integer,0),
          'reputation',coalesce((v_contract.rewards->>'reputation')::integer,0),
          'season_xp',coalesce((v_contract.rewards->>'season_xp')::integer,0),
          'npc_key',v_npc_key
        ))
      );

      v_unlock:=nullif(v_contract.rewards->>'unlock','');
      if v_unlock is not null then
        v_unlock_type:=case
          when exists(
            select 1 from public.tgg_world_career_contracts c
            where c.contract_key=v_unlock and c.enabled=true
          ) then 'career_contract'
          else 'career_path_marker'
        end;

        insert into public.tgg_world_career_unlocks(
          character_id,unlock_key,source_type,source_key,metadata,unlocked_at
        )
        values(
          v_char.id,v_unlock,'contract_reward',v_contract.contract_key,
          jsonb_build_object(
            'career_key',v_contract.career_key,
            'unlock_type',v_unlock_type,
            'source_title',v_contract.title
          ),
          now()
        )
        on conflict(character_id,unlock_key) do update
        set metadata=public.tgg_world_career_unlocks.metadata||excluded.metadata,
            source_type=excluded.source_type,
            source_key=excluded.source_key,
            unlocked_at=least(public.tgg_world_career_unlocks.unlocked_at,excluded.unlocked_at);
      end if;

      if v_contract.contact_key is not null then
        insert into public.tgg_world_contact_relationships(
          character_id,contact_key,relationship_xp,relationship_level,trust_score,
          meetings_completed,successful_contracts,last_interaction_at,memory,updated_at
        )
        values(
          v_char.id,v_contract.contact_key,10,1,5,0,1,now(),
          jsonb_build_object('last_contract',v_contract.contract_key),now()
        )
        on conflict(character_id,contact_key) do update
        set relationship_xp=public.tgg_world_contact_relationships.relationship_xp+10,
            relationship_level=greatest(
              public.tgg_world_contact_relationships.relationship_level,
              1+((public.tgg_world_contact_relationships.relationship_xp+10)/100)
            ),
            trust_score=least(100,public.tgg_world_contact_relationships.trust_score+5),
            successful_contracts=public.tgg_world_contact_relationships.successful_contracts+1,
            last_interaction_at=now(),
            memory=public.tgg_world_contact_relationships.memory||
              jsonb_build_object('last_contract',v_contract.contract_key),
            updated_at=now();
      end if;

      v_district:=private.tgg_world_apply_district_progress(v_char.id,v_contract.location_key,15);
      perform private.tgg_world_credit_faction_mission_event(
        v_char.id,
        'contracts_completed',
        'career_contract',
        v_state.id::text,
        jsonb_build_object('contract_key',v_contract.contract_key)
      );

      perform private.tgg_recompute_progression(v_char.id);
      v_completed:=v_completed+1;
    end if;

    v_results:=v_results||jsonb_build_array(jsonb_build_object(
      'contract_id',v_state.id,
      'contract_key',v_contract.contract_key,
      'objective_type',p_objective_type,
      'current',v_current,
      'required',v_required,
      'completed',v_all_met,
      'progression_event_id',v_event,
      'district_progress',coalesce(v_district,'{}'::jsonb),
      'unlock_key',case when v_all_met then v_unlock else null end,
      'unlock_type',case when v_all_met then v_unlock_type else null end
    ));
  end loop;

  return jsonb_build_object(
    'credited',v_credited,
    'completed',v_completed,
    'objective_type',p_objective_type,
    'source_type',p_source_type,
    'source_id',p_source_id,
    'results',v_results
  );
end;
$function$


-- [40000000328] function private.tgg_world_credit_faction_mission_event(p_character_id uuid, p_action_key text, p_source_type text, p_source_id text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION private.tgg_world_credit_faction_mission_event(p_character_id uuid, p_action_key text, p_source_type text, p_source_id text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_char public.world_characters%rowtype;
  v_mission public.tgg_world_faction_missions%rowtype;
  v_state public.tgg_world_character_faction_missions%rowtype;
  v_required integer;
  v_current integer;
  v_progress jsonb;
  v_all_met boolean;
  v_inserted integer;
  v_event uuid;
  v_crew_id uuid;
  v_crew_rep integer:=0;
  v_credited integer:=0;
  v_completed integer:=0;
  v_results jsonb:='[]'::jsonb;
begin
  if p_character_id is null
     or nullif(btrim(coalesce(p_action_key,'')),'') is null
     or nullif(btrim(coalesce(p_source_id,'')),'') is null then
    return jsonb_build_object('credited',0,'completed',0,'reason','invalid_input');
  end if;

  select * into v_char
  from public.world_characters
  where id=p_character_id and character_status='active';

  if v_char.id is null then
    return jsonb_build_object('credited',0,'completed',0,'reason','character_not_found');
  end if;

  if auth.uid() is not null and v_char.user_id<>auth.uid() then
    raise exception 'character_ownership_mismatch';
  end if;

  for v_mission in
    select m.*
    from public.tgg_world_faction_missions m
    join public.tgg_world_character_factions f
      on f.character_id=v_char.id
     and f.faction_key=m.faction_key
     and f.status in ('member','favored')
    where m.enabled=true
      and m.requirements ? p_action_key
    order by m.mission_key
  loop
    insert into public.tgg_world_character_faction_missions(
      character_id,mission_key,status,progress,updated_at
    )
    values(v_char.id,v_mission.mission_key,'active','{}'::jsonb,now())
    on conflict(character_id,mission_key) do nothing;

    select * into v_state
    from public.tgg_world_character_faction_missions
    where character_id=v_char.id and mission_key=v_mission.mission_key
    for update;

    if v_state.status='completed' and not v_mission.repeatable then
      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'mission_key',v_mission.mission_key,'completed',true,'replayed',true
      ));
      continue;
    end if;

    if v_state.status='completed' and v_mission.repeatable then
      if exists(
        select 1
        from public.tgg_world_faction_mission_credits cr
        where cr.character_id=v_char.id
          and cr.mission_key=v_mission.mission_key
          and cr.action_key=p_action_key
          and cr.source_type=left(coalesce(p_source_type,'event'),64)
          and cr.source_id=left(p_source_id,180)
      ) then
        v_results:=v_results||jsonb_build_array(jsonb_build_object(
          'mission_key',v_mission.mission_key,
          'completed',true,
          'credited',false,
          'replayed',true
        ));
        continue;
      end if;

      update public.tgg_world_character_faction_missions
      set status='active',progress='{}'::jsonb,completed_at=null,updated_at=now()
      where character_id=v_char.id and mission_key=v_mission.mission_key;
      v_state.progress:='{}'::jsonb;
    end if;

    insert into public.tgg_world_faction_mission_credits(
      character_id,mission_key,action_key,source_type,source_id,metadata
    )
    values(
      v_char.id,v_mission.mission_key,p_action_key,
      left(coalesce(p_source_type,'event'),64),
      left(p_source_id,180),
      coalesce(p_metadata,'{}'::jsonb)
    )
    on conflict do nothing;

    get diagnostics v_inserted=row_count;
    if v_inserted=0 then
      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'mission_key',v_mission.mission_key,'credited',false,'replayed',true
      ));
      continue;
    end if;

    v_required:=greatest(coalesce((v_mission.requirements->>p_action_key)::integer,1),1);
    v_progress:=coalesce(v_state.progress,'{}'::jsonb);
    v_current:=least(
      v_required,
      greatest(coalesce((v_progress->>p_action_key)::integer,0),0)+1
    );
    v_progress:=jsonb_set(v_progress,array[p_action_key],to_jsonb(v_current),true);

    select coalesce(bool_and(
      coalesce((v_progress->>k)::integer,0)>=greatest((v_mission.requirements->>k)::integer,1)
    ),false)
    into v_all_met
    from jsonb_object_keys(v_mission.requirements) k;

    update public.tgg_world_character_faction_missions
    set progress=v_progress,
        status=case when v_all_met then 'completed' else 'active' end,
        completed_at=case when v_all_met then coalesce(completed_at,now()) else completed_at end,
        updated_at=now()
    where character_id=v_char.id and mission_key=v_mission.mission_key;

    v_credited:=v_credited+1;

    if v_all_met then
      v_crew_rep:=greatest(coalesce((v_mission.rewards->>'crew_rep')::integer,0),0);

      if v_crew_rep>0 then
        select crew_id into v_crew_id
        from public.tgg_world_crew_members
        where character_id=v_char.id and left_at is null
        order by joined_at desc
        limit 1;

        if v_crew_id is not null then
          insert into public.tgg_world_crew_progression(
            crew_id,crew_xp,rank_level,reputation,unlocks,updated_at
          )
          values(v_crew_id,0,1,v_crew_rep,'{}'::jsonb,now())
          on conflict(crew_id) do update
          set reputation=public.tgg_world_crew_progression.reputation+v_crew_rep,
              updated_at=now();
        end if;
      end if;

      v_event:=private.tgg_apply_progression_event(
        v_char.id,'dynamic_event_completed',v_mission.mission_key,
        jsonb_strip_nulls(jsonb_build_object(
          'career_xp',coalesce((v_mission.rewards->>'career_xp')::integer,0),
          'reputation',coalesce((v_mission.rewards->>'reputation')::integer,0),
          'season_xp',coalesce((v_mission.rewards->>'season_xp')::integer,0),
          'faction_key',v_mission.faction_key,
          'faction_standing',coalesce((v_mission.rewards->>'faction_standing')::integer,0)
        ))
      );

      perform private.tgg_recompute_progression(v_char.id);
      v_completed:=v_completed+1;
    end if;

    v_results:=v_results||jsonb_build_array(jsonb_build_object(
      'mission_key',v_mission.mission_key,
      'action_key',p_action_key,
      'current',v_current,
      'required',v_required,
      'completed',v_all_met,
      'crew_id',v_crew_id,
      'crew_reputation_awarded',case when v_all_met then v_crew_rep else 0 end,
      'progression_event_id',v_event
    ));
  end loop;

  return jsonb_build_object(
    'credited',v_credited,
    'completed',v_completed,
    'action_key',p_action_key,
    'source_type',p_source_type,
    'source_id',p_source_id,
    'results',v_results
  );
end;
$function$


-- [40000000329] function private.tgg_world_credit_gig_event(p_character_id uuid, p_objective_type text, p_source_type text, p_source_id text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION private.tgg_world_credit_gig_event(p_character_id uuid, p_objective_type text, p_source_type text, p_source_id text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_char public.world_characters%rowtype;
  v_location text;
  v_gig public.tgg_world_character_gigs%rowtype;
  v_template public.tgg_world_gig_templates%rowtype;
  v_required integer;
  v_current integer;
  v_progress jsonb;
  v_all_met boolean;
  v_inserted integer;
  v_event uuid;
  v_rel_xp integer:=0;
  v_credited integer:=0;
  v_completed integer:=0;
  v_results jsonb:='[]'::jsonb;
begin
  if p_character_id is null
     or nullif(btrim(coalesce(p_objective_type,'')),'') is null
     or nullif(btrim(coalesce(p_source_id,'')),'') is null then
    return jsonb_build_object('credited',0,'completed',0,'reason','invalid_input');
  end if;

  select * into v_char
  from public.world_characters
  where id=p_character_id and character_status='active';

  if v_char.id is null then
    return jsonb_build_object('credited',0,'completed',0,'reason','character_not_found');
  end if;

  if auth.uid() is not null and v_char.user_id<>auth.uid() then
    raise exception 'character_ownership_mismatch';
  end if;

  select l.location_key into v_location
  from public.tgg_world_locations l
  where l.id=v_char.current_location_id;

  for v_gig in
    select g.*
    from public.tgg_world_character_gigs g
    join public.tgg_world_gig_templates t
      on t.gig_key=g.gig_key and t.enabled=true
    where g.character_id=v_char.id
      and g.status='accepted'
      and (g.expires_at is null or g.expires_at>now())
      and v_char.active_career=any(t.career_keys)
      and (
        t.location_key is null
        or t.location_key=v_location
        or p_source_type='booking'
      )
      and exists(
        select 1 from jsonb_array_elements(t.objectives) o
        where o->>'type'=p_objective_type
      )
    order by g.accepted_at,g.id
  loop
    select * into v_template
    from public.tgg_world_gig_templates
    where gig_key=v_gig.gig_key and enabled=true;

    select g.* into v_gig
    from public.tgg_world_character_gigs g
    where g.id=v_gig.id and g.status='accepted'
    for update;

    if v_gig.id is null then continue; end if;

    if v_gig.expires_at is not null and v_gig.expires_at<=now() then
      update public.tgg_world_character_gigs
      set status='expired',updated_at=now()
      where id=v_gig.id;
      continue;
    end if;

    select (o->>'count')::integer into v_required
    from jsonb_array_elements(v_template.objectives) o
    where o->>'type'=p_objective_type
    limit 1;

    if v_required is null or v_required<1 then continue; end if;

    insert into public.tgg_world_gig_credits(
      character_id,gig_id,gig_key,objective_type,source_type,source_id,metadata
    )
    values(
      v_char.id,v_gig.id,v_template.gig_key,p_objective_type,
      left(coalesce(p_source_type,'event'),64),
      left(p_source_id,180),
      coalesce(p_metadata,'{}'::jsonb)
    )
    on conflict do nothing;

    get diagnostics v_inserted=row_count;
    if v_inserted=0 then
      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'gig_id',v_gig.id,'gig_key',v_template.gig_key,'credited',false,'replayed',true
      ));
      continue;
    end if;

    v_progress:=coalesce(v_gig.progress,'{}'::jsonb);
    v_current:=least(
      v_required,
      greatest(coalesce((v_progress->>p_objective_type)::integer,0),0)+1
    );
    v_progress:=jsonb_set(v_progress,array[p_objective_type],to_jsonb(v_current),true);

    select coalesce(bool_and(
      coalesce((v_progress->>(o->>'type'))::integer,0)>=(o->>'count')::integer
    ),false)
    into v_all_met
    from jsonb_array_elements(v_template.objectives) o;

    update public.tgg_world_character_gigs
    set progress=v_progress,
        status=case when v_all_met then 'completed' else 'accepted' end,
        completed_at=case when v_all_met then coalesce(completed_at,now()) else completed_at end,
        updated_at=now()
    where id=v_gig.id;

    v_credited:=v_credited+1;

    if v_all_met then
      v_event:=private.tgg_apply_progression_event(
        v_char.id,
        'gig_completed',
        v_template.gig_key,
        jsonb_strip_nulls(jsonb_build_object(
          'career_xp',coalesce((v_template.rewards->>'career_xp')::integer,0),
          'reputation',coalesce((v_template.rewards->>'reputation')::integer,0),
          'season_xp',coalesce((v_template.rewards->>'season_xp')::integer,0)
        ))
      );

      v_rel_xp:=greatest(coalesce((v_template.rewards->>'relationship_xp')::integer,0),0);

      if v_rel_xp>0 and v_template.contact_key is not null then
        insert into public.tgg_world_contact_relationships(
          character_id,contact_key,relationship_xp,relationship_level,
          trust_score,meetings_completed,successful_contracts,last_interaction_at,memory,updated_at
        )
        values(
          v_char.id,v_template.contact_key,v_rel_xp,
          greatest(1,1+(v_rel_xp/100)),
          least(100,greatest(0,v_rel_xp/10)),
          0,1,now(),
          jsonb_build_object('last_reward_source',v_template.gig_key),
          now()
        )
        on conflict(character_id,contact_key) do update
        set relationship_xp=public.tgg_world_contact_relationships.relationship_xp+v_rel_xp,
            relationship_level=greatest(
              public.tgg_world_contact_relationships.relationship_level,
              1+((public.tgg_world_contact_relationships.relationship_xp+v_rel_xp)/100)
            ),
            trust_score=least(
              100,
              public.tgg_world_contact_relationships.trust_score+greatest(1,v_rel_xp/10)
            ),
            successful_contracts=public.tgg_world_contact_relationships.successful_contracts+1,
            last_interaction_at=now(),
            memory=public.tgg_world_contact_relationships.memory||
              jsonb_build_object('last_reward_source',v_template.gig_key),
            updated_at=now();
      end if;

      perform private.tgg_rotate_challenges(v_char.id);
      v_completed:=v_completed+1;
    end if;

    v_results:=v_results||jsonb_build_array(jsonb_build_object(
      'gig_id',v_gig.id,
      'gig_key',v_template.gig_key,
      'objective_type',p_objective_type,
      'current',v_current,
      'required',v_required,
      'completed',v_all_met,
      'progression_event_id',v_event
    ));
  end loop;

  return jsonb_build_object(
    'credited',v_credited,
    'completed',v_completed,
    'objective_type',p_objective_type,
    'source_type',p_source_type,
    'source_id',p_source_id,
    'results',v_results
  );
end;
$function$


-- [40000000330] function private.tgg_world_crew_activity_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_crew_activity_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_crew uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then return '{}'::jsonb; end if;

  select crew_id into v_crew
  from public.tgg_world_crew_members
  where user_id=v_uid and character_id=v_char and left_at is null
  order by joined_at desc limit 1;

  return jsonb_build_object(
    'character_id',v_char,
    'crew_id',v_crew,
    'crew',case when v_crew is null then null else (
      select jsonb_build_object(
        'crew_name',c.crew_name,
        'my_role',m.crew_role,
        'crew_xp',coalesce(p.crew_xp,0),
        'rank_level',coalesce(p.rank_level,1),
        'reputation',coalesce(p.reputation,0)
      )
      from public.tgg_world_crews c
      join public.tgg_world_crew_members m
        on m.crew_id=c.id and m.user_id=v_uid and m.left_at is null
      left join public.tgg_world_crew_progression p on p.crew_id=c.id
      where c.id=v_crew
      limit 1
    ) end,
    'rank_path',coalesce((
      select jsonb_agg(jsonb_build_object(
        'rank_level',r.rank_level,
        'title',r.title,
        'required_crew_xp',r.required_crew_xp,
        'perks',r.perks,
        'reached',coalesce((
          select p.crew_xp>=r.required_crew_xp
          from public.tgg_world_crew_progression p
          where p.crew_id=v_crew
        ),r.required_crew_xp=0)
      ) order by r.rank_level)
      from public.tgg_world_crew_ranks r
      where r.enabled=true
    ),'[]'::jsonb),
    'activity',case when v_crew is null then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',a.id,
        'activity_type',a.activity_type,
        'actor_user_id',case
          when exists(
            select 1 from public.tgg_world_crew_members me
            where me.crew_id=v_crew and me.user_id=v_uid
              and me.left_at is null and me.crew_role in ('owner','admin')
          ) then a.actor_user_id else null end,
        'actor_stage_name',coalesce(wc.stage_name,'Crew Member'),
        'detail',a.detail,
        'created_at',a.created_at
      ) order by a.created_at desc)
      from (
        select * from public.tgg_world_crew_activity
        where crew_id=v_crew
        order by created_at desc
        limit 30
      ) a
      left join public.world_characters wc on wc.user_id=a.actor_user_id
    ),'[]'::jsonb) end
  );
end;
$function$


-- [40000000331] function private.tgg_world_crew_contract_credit(p_character_id uuid, p_objective_type text, p_source_type text, p_source_id text)
CREATE OR REPLACE FUNCTION private.tgg_world_crew_contract_credit(p_character_id uuid, p_objective_type text, p_source_type text, p_source_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_crew uuid;
  v_location_district text;
  v_run record;
  v_required integer;
  v_current integer;
  v_progress jsonb;
  v_all_met boolean;
  v_inserted integer;
  v_crew_rep integer;
  v_district_influence integer;
  v_event uuid;
  v_completed integer:=0;
begin
  select m.crew_id into v_crew
  from public.tgg_world_crew_members m
  where m.character_id=p_character_id and m.left_at is null
  order by m.joined_at desc
  limit 1;

  if v_crew is null then
    return jsonb_build_object('credited',false,'reason','no_active_crew');
  end if;

  select l.district_key into v_location_district
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=p_character_id;

  for v_run in
    select r.id,r.contract_key,r.progress,c.objectives,c.rewards,c.district_key
    from public.tgg_world_crew_contract_runs r
    join public.tgg_world_crew_contracts c on c.contract_key=r.contract_key
    where r.crew_id=v_crew and r.status='active' and c.enabled=true
      and (c.district_key is null or c.district_key=v_location_district)
      and exists(
        select 1 from jsonb_array_elements(c.objectives) o
        where o->>'type'=p_objective_type
      )
    for update of r
  loop
    select (o->>'count')::integer into v_required
    from jsonb_array_elements(v_run.objectives) o
    where o->>'type'=p_objective_type
    limit 1;

    insert into public.tgg_world_crew_contract_credits(
      run_id,character_id,objective_type,source_type,source_id,credited_at
    )
    values(v_run.id,p_character_id,p_objective_type,p_source_type,p_source_id,now())
    on conflict(run_id,objective_type,source_type,source_id) do nothing;

    get diagnostics v_inserted = row_count;
    if v_inserted=0 then
      continue;
    end if;

    v_progress:=coalesce(v_run.progress,'{}'::jsonb);
    v_current:=least(
      v_required,
      greatest(coalesce((v_progress->>p_objective_type)::integer,0),0)+1
    );
    v_progress:=jsonb_set(v_progress,array[p_objective_type],to_jsonb(v_current),true);

    select coalesce(bool_and(
      coalesce((v_progress->>(o->>'type'))::integer,0)>=(o->>'count')::integer
    ),false)
    into v_all_met
    from jsonb_array_elements(v_run.objectives) o;

    update public.tgg_world_crew_contract_runs
    set progress=v_progress,
        status=case when v_all_met then 'completed' else 'active' end,
        completed_at=case when v_all_met then now() else null end,
        updated_at=now()
    where id=v_run.id;

    if v_all_met then
      v_crew_rep:=greatest(coalesce((v_run.rewards->>'crew_rep')::integer,0),0);
      v_district_influence:=greatest(coalesce((v_run.rewards->>'district_influence')::integer,0),0);

      insert into public.tgg_world_crew_progression(
        crew_id,crew_xp,rank_level,reputation,unlocks,updated_at
      )
      values(v_crew,0,1,v_crew_rep,'{}'::jsonb,now())
      on conflict(crew_id) do update
      set reputation=public.tgg_world_crew_progression.reputation+v_crew_rep,
          updated_at=now();

      if v_run.district_key is not null and v_district_influence>0 then
        insert into public.tgg_world_crew_territories(
          crew_id,district_key,influence,control_level,perks,updated_at
        )
        values(
          v_crew,v_run.district_key,least(100,v_district_influence),
          case when v_district_influence>=70 then 'dominant'
               when v_district_influence>=30 then 'contested'
               else 'presence' end,
          '{}'::jsonb,now()
        )
        on conflict(crew_id,district_key) do update
        set influence=least(100,public.tgg_world_crew_territories.influence+v_district_influence),
            control_level=case
              when least(100,public.tgg_world_crew_territories.influence+v_district_influence)>=70 then 'dominant'
              when least(100,public.tgg_world_crew_territories.influence+v_district_influence)>=30 then 'contested'
              else 'presence'
            end,
            updated_at=now();
      end if;

      v_event:=private.tgg_apply_progression_event(
        p_character_id,'crew_contract_completed',v_run.contract_key,
        jsonb_strip_nulls(jsonb_build_object(
          'crew_id',v_crew,
          'district_key',v_run.district_key
        ))
      );

      perform private.tgg_world_credit_challenge_event(
        p_character_id,'crew_contracts_completed','crew_contract_run',v_run.id::text
      );
      perform private.tgg_recompute_progression(p_character_id);
      v_completed:=v_completed+1;
    end if;
  end loop;

  return jsonb_build_object(
    'credited',true,'crew_id',v_crew,'objective_type',p_objective_type,
    'completed_contracts',v_completed
  );
end;
$function$


-- [40000000332] function private.tgg_world_crew_contract_start(p_contract_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_crew_contract_start(p_contract_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_crew uuid;
  v_role text;
  v_contract public.tgg_world_crew_contracts%rowtype;
  v_member_count integer:=0;
  v_district text;
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select wc.id,m.crew_id,m.crew_role
  into v_char,v_crew,v_role
  from public.world_characters wc
  join public.tgg_world_crew_members m
    on m.character_id=wc.id and m.user_id=v_uid and m.left_at is null
  where wc.user_id=v_uid and wc.character_status='active'
  order by m.joined_at desc
  limit 1;

  if v_crew is null then raise exception 'active_crew_required'; end if;

  if not (
    v_role in ('owner','admin')
    or exists(select 1 from public.tgg_world_crews c where c.id=v_crew and c.owner_user_id=v_uid)
  ) then
    raise exception 'crew_leader_or_admin_required';
  end if;

  select * into v_contract
  from public.tgg_world_crew_contracts
  where contract_key=p_contract_key and enabled=true;
  if v_contract.contract_key is null then raise exception 'crew_contract_unavailable'; end if;

  select count(*) into v_member_count
  from public.tgg_world_crew_members
  where crew_id=v_crew and left_at is null;

  if v_member_count<v_contract.required_crew_size then
    raise exception 'crew_size_requirement_not_met';
  end if;

  select l.district_key into v_district
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=v_char;

  if v_contract.district_key is not null and v_district is distinct from v_contract.district_key then
    raise exception 'travel_to_contract_district_first';
  end if;

  if exists(
    select 1 from public.tgg_world_crew_contract_runs
    where crew_id=v_crew and status='active'
  ) then
    raise exception 'finish_current_crew_contract_first';
  end if;

  insert into public.tgg_world_crew_contract_runs(
    crew_id,contract_key,status,progress,started_by_user_id,started_at,updated_at
  )
  values(v_crew,v_contract.contract_key,'active','{}'::jsonb,v_uid,now(),now())
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'run_id',v_id,'crew_id',v_crew,
    'contract_key',v_contract.contract_key,'title',v_contract.title,
    'objectives',v_contract.objectives,'rewards',v_contract.rewards
  );
end;
$function$


-- [40000000333] function private.tgg_world_crew_create(p_crew_name text)
CREATE OR REPLACE FUNCTION private.tgg_world_crew_create(p_crew_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_char public.world_characters%rowtype;
  v_name text := trim(coalesce(p_crew_name,''));
  v_key text;
  v_crew public.tgg_world_crews%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if length(v_name)<2 or length(v_name)>50 then raise exception 'crew_name_invalid'; end if;
  select * into v_char from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if not found then raise exception 'active_character_required'; end if;
  v_key := regexp_replace(lower(v_name),'[^a-z0-9]+','-','g')||'-'||substr(replace(gen_random_uuid()::text,'-',''),1,6);
  insert into public.tgg_world_crews(owner_user_id,owner_character_id,crew_name,crew_key)
  values(v_uid,v_char.id,v_name,v_key) returning * into v_crew;
  insert into public.tgg_world_crew_members(crew_id,user_id,character_id,crew_role)
  values(v_crew.id,v_uid,v_char.id,'owner');
  insert into public.tgg_world_crew_activity(crew_id,actor_user_id,activity_type,detail)
  values(v_crew.id,v_uid,'crew_created',jsonb_build_object('crew_name',v_name));
  return jsonb_build_object('ok',true,'crew_id',v_crew.id,'crew_key',v_crew.crew_key,'role','owner','real_money',false);
end $function$


-- [40000000334] function private.tgg_world_crew_credit_business_trigger()
CREATE OR REPLACE FUNCTION private.tgg_world_crew_credit_business_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_char uuid;
begin
  if new.status='completed' and old.status is distinct from 'completed' then
    select character_id into v_char
    from public.tgg_world_character_businesses
    where id=new.business_id;
    if v_char is not null then
      perform private.tgg_world_crew_contract_credit(
        v_char,'business_ops','business_operation',new.id::text
      );
    end if;
  end if;
  return new;
end;
$function$


-- [40000000335] function private.tgg_world_crew_credit_event_trigger()
CREATE OR REPLACE FUNCTION private.tgg_world_crew_credit_event_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_event_type text;
begin
  if new.status='completed' and old.status is distinct from 'completed' then
    select t.event_type into v_event_type
    from public.tgg_world_dynamic_events e
    join public.tgg_world_dynamic_event_templates t on t.event_key=e.event_key
    where e.id=new.dynamic_event_id;

    if v_event_type in ('nightlife','nightlife_event') then
      perform private.tgg_world_crew_contract_credit(
        new.character_id,'night_events','dynamic_event',new.dynamic_event_id::text
      );
    end if;
  end if;
  return new;
end;
$function$


