-- [40000000338] function private.tgg_world_crew_join(p_crew_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_crew_join(p_crew_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_char public.world_characters%rowtype;
  v_crew public.tgg_world_crews%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select * into v_char from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if not found then raise exception 'active_character_required'; end if;
  select * into v_crew from public.tgg_world_crews where id=p_crew_id and crew_status='active';
  if not found then raise exception 'crew_not_found'; end if;
  insert into public.tgg_world_crew_members(crew_id,user_id,character_id,crew_role,left_at)
  values(v_crew.id,v_uid,v_char.id,'member',null)
  on conflict(crew_id,user_id) do update
    set character_id=excluded.character_id,
        crew_role=case when tgg_world_crew_members.crew_role in ('owner','admin') then tgg_world_crew_members.crew_role else 'member' end,
        left_at=null;
  insert into public.tgg_world_crew_activity(crew_id,actor_user_id,activity_type,detail)
  values(v_crew.id,v_uid,'member_joined',jsonb_build_object('character_id',v_char.id));
  return jsonb_build_object('ok',true,'crew_id',v_crew.id,'role',(select crew_role from public.tgg_world_crew_members where crew_id=v_crew.id and user_id=v_uid),'real_money',false);
end $function$


-- [40000000339] function private.tgg_world_crew_rides_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_crew_rides_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_instance uuid;
  v_memberships jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select wc.id into v_char
  from public.world_characters wc
  where wc.user_id=v_uid and wc.character_status='active'
  limit 1;

  if v_char is null then
    return jsonb_build_object(
      'character_id',null,
      'crew_memberships','[]'::jsonb,
      'joinable_crews','[]'::jsonb,
      'owned_vehicles','[]'::jsonb,
      'nearby_vehicles','[]'::jsonb
    );
  end if;

  select p.instance_id into v_instance
  from public.tgg_world_presence p
  where p.user_id=v_uid
  order by p.last_seen_at desc
  limit 1;

  select coalesce(jsonb_agg(jsonb_build_object(
    'crew_id',c.id,
    'crew_name',c.crew_name,
    'crew_key',c.crew_key,
    'my_role',m.crew_role,
    'crew_xp',coalesce(cp.crew_xp,0),
    'rank_level',coalesce(cp.rank_level,1),
    'reputation',coalesce(cp.reputation,0),
    'members',coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id',case when m.crew_role in ('owner','admin') then mm.user_id else null end,
        'character_id',mm.character_id,
        'stage_name',wc.stage_name,
        'crew_role',mm.crew_role,
        'joined_at',mm.joined_at
      ) order by
        case mm.crew_role when 'owner' then 1 when 'admin' then 2 else 3 end,
        wc.stage_name
      )
      from public.tgg_world_crew_members mm
      join public.world_characters wc on wc.id=mm.character_id
      where mm.crew_id=c.id and mm.left_at is null
    ),'[]'::jsonb)
  ) order by c.created_at),'[]'::jsonb)
  into v_memberships
  from public.tgg_world_crew_members m
  join public.tgg_world_crews c on c.id=m.crew_id and c.crew_status='active'
  left join public.tgg_world_crew_progression cp on cp.crew_id=c.id
  where m.user_id=v_uid and m.left_at is null;

  return jsonb_build_object(
    'character_id',v_char,
    'current_instance_id',v_instance,
    'crew_memberships',v_memberships,
    'joinable_crews',coalesce((
      select jsonb_agg(jsonb_build_object(
        'crew_id',c.id,
        'crew_name',c.crew_name,
        'crew_key',c.crew_key,
        'member_count',(select count(*) from public.tgg_world_crew_members mm where mm.crew_id=c.id and mm.left_at is null),
        'rank_level',coalesce(cp.rank_level,1),
        'reputation',coalesce(cp.reputation,0)
      ) order by coalesce(cp.rank_level,1) desc,c.created_at)
      from public.tgg_world_crews c
      left join public.tgg_world_crew_progression cp on cp.crew_id=c.id
      where c.crew_status='active'
        and not exists(
          select 1 from public.tgg_world_crew_members m
          where m.crew_id=c.id and m.user_id=v_uid and m.left_at is null
        )
    ),'[]'::jsonb),
    'owned_vehicles',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',v.id,
        'vehicle_key',v.vehicle_key,
        'display_name',v.display_name,
        'vehicle_status',v.vehicle_status,
        'current_instance_id',v.current_instance_id,
        'music_state',v.music_state,
        'passengers',coalesce((
          select jsonb_agg(jsonb_build_object(
            'stage_name',wc.stage_name,
            'seat_key',vp.seat_key
          ) order by vp.seat_key,wc.stage_name)
          from public.tgg_world_vehicle_passengers vp
          join public.world_characters wc on wc.id=vp.character_id
          where vp.vehicle_id=v.id and vp.left_at is null
        ),'[]'::jsonb)
      ) order by v.created_at)
      from public.tgg_world_vehicles v
      where v.owner_user_id=v_uid and v.vehicle_status='active'
    ),'[]'::jsonb),
    'nearby_vehicles',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',v.id,
        'display_name',v.display_name,
        'vehicle_key',v.vehicle_key,
        'owner_stage_name',ow.stage_name,
        'music_state',v.music_state,
        'already_inside',exists(
          select 1 from public.tgg_world_vehicle_passengers vp
          where vp.vehicle_id=v.id and vp.user_id=v_uid and vp.left_at is null
        )
      ) order by v.display_name)
      from public.tgg_world_vehicles v
      join public.world_characters ow on ow.id=v.owner_character_id
      where v.vehicle_status='active'
        and v.current_instance_id is not distinct from v_instance
        and v.owner_user_id<>v_uid
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000340] function private.tgg_world_crew_set_role(p_crew_id uuid, p_member_user_id uuid, p_role text)
CREATE OR REPLACE FUNCTION private.tgg_world_crew_set_role(p_crew_id uuid, p_member_user_id uuid, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_actor_role text;
  v_target_role text := lower(trim(coalesce(p_role,'')));
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if v_target_role not in ('admin','member') then raise exception 'invalid_role'; end if;
  select crew_role into v_actor_role
  from public.tgg_world_crew_members
  where crew_id=p_crew_id and user_id=v_uid and left_at is null;
  if v_actor_role is null then raise exception 'crew_membership_required'; end if;
  if v_actor_role not in ('owner','admin') then raise exception 'crew_permission_denied'; end if;
  if exists(select 1 from public.tgg_world_crew_members where crew_id=p_crew_id and user_id=p_member_user_id and crew_role='owner') then
    raise exception 'owner_role_immutable';
  end if;
  if v_actor_role='admin' and v_target_role='admin' then
    raise exception 'owner_required_for_admin_promotion';
  end if;
  update public.tgg_world_crew_members
  set crew_role=v_target_role
  where crew_id=p_crew_id and user_id=p_member_user_id and left_at is null;
  if not found then raise exception 'crew_member_not_found'; end if;
  insert into public.tgg_world_crew_activity(crew_id,actor_user_id,activity_type,detail)
  values(p_crew_id,v_uid,'role_changed',jsonb_build_object('member_user_id',p_member_user_id,'role',v_target_role));
  return jsonb_build_object('ok',true,'crew_id',p_crew_id,'member_user_id',p_member_user_id,'role',v_target_role);
end $function$


-- [40000000341] function private.tgg_world_dashboard_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_dashboard_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_character uuid;
  v_payload jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select id into v_character from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if v_character is null then raise exception 'active world character not found'; end if;

  select jsonb_build_object(
    'character',(select jsonb_build_object(
      'id',wc.id,'stage_name',wc.stage_name,'active_career',wc.active_career,
      'current_location_id',wc.current_location_id,'status',wc.character_status
    ) from public.world_characters wc where wc.id=v_character),

    'career',coalesce((select jsonb_agg(jsonb_build_object(
      'career_key',c.career_key,'level',c.career_level,'xp',c.career_xp,'unlocked',c.unlocked
    ) order by c.career_level desc) from public.world_character_careers c where c.character_id=v_character),'[]'::jsonb),

    'reputation',coalesce((select jsonb_agg(jsonb_build_object(
      'career_key',r.career_key,'reputation',r.reputation,'tier',r.tier
    )) from public.tgg_world_career_reputation r where r.character_id=v_character),'[]'::jsonb),

    'influence',coalesce((select to_jsonb(i)-'character_id' from public.tgg_world_character_influence i where i.character_id=v_character),'{}'::jsonb),

    'season',coalesce((select jsonb_agg(jsonb_build_object(
      'season_key',sp.season_key,'level',sp.season_level,'xp',sp.season_xp,'rewards',sp.unlocked_rewards
    )) from public.tgg_world_character_season_progress sp where sp.character_id=v_character),'[]'::jsonb),

    'challenges',coalesce((select jsonb_agg(jsonb_build_object(
      'challenge_key',cc.challenge_key,'period_key',cc.period_key,'status',cc.status,'progress',cc.progress,'streak',cc.streak_count
    ) order by cc.updated_at desc) from public.tgg_world_character_challenges cc
    where cc.character_id=v_character and cc.status='active'),'[]'::jsonb),

    'gigs',coalesce((select jsonb_agg(jsonb_build_object(
      'id',g.id,'gig_key',g.gig_key,'status',g.status,'expires_at',g.expires_at,'progress',g.progress
    ) order by g.offered_at desc) from public.tgg_world_character_gigs g
    where g.character_id=v_character
      and g.status in ('available','accepted')
      and (g.expires_at is null or g.expires_at>now())),'[]'::jsonb),

    'contracts',coalesce((select jsonb_agg(jsonb_build_object(
      'id',c.id,'contract_key',c.contract_key,'status',c.status,'progress',c.progress
    ) order by c.updated_at desc) from public.tgg_world_character_contracts c
    where c.character_id=v_character and c.status='active'),'[]'::jsonb),

    'properties',coalesce((select jsonb_agg(jsonb_build_object(
      'id',p.id,'property_key',p.property_key,'nickname',p.nickname,'status',p.ownership_status
    )) from public.tgg_world_character_properties p where p.character_id=v_character and p.ownership_status='owned'),'[]'::jsonb),

    'businesses',coalesce((select jsonb_agg(jsonb_build_object(
      'id',b.id,'business_name',b.business_name,'type',b.business_type_key,'level',b.business_level,'xp',b.business_xp,'reputation',b.reputation
    )) from public.tgg_world_character_businesses b where b.character_id=v_character and b.status='active'),'[]'::jsonb),

    'achievements',coalesce((select jsonb_agg(a.achievement_key order by a.unlocked_at desc)
      from public.tgg_world_character_achievements a where a.character_id=v_character and a.unlocked_at is not null),'[]'::jsonb),

    'titles',coalesce((select jsonb_agg(jsonb_build_object('title_key',t.title_key,'equipped',t.equipped,'unlocked_at',t.unlocked_at))
      from public.tgg_world_character_titles t where t.character_id=v_character),'[]'::jsonb),

    'badges',coalesce((select jsonb_agg(b.badge_key order by b.unlocked_at desc)
      from public.tgg_world_character_badges b where b.character_id=v_character),'[]'::jsonb),

    'collectibles',coalesce((select jsonb_agg(jsonb_build_object('collectible_key',c.collectible_key,'quantity',c.quantity))
      from public.tgg_world_character_collectibles c where c.character_id=v_character),'[]'::jsonb),

    'runtime',coalesce((select jsonb_build_object('status',r.status,'detail',r.detail,'created_at',r.created_at)
      from public.tgg_world_runtime_snapshots r where r.snapshot_key='tgg-world-runtime'
      order by r.created_at desc limit 1),'{}'::jsonb)
  ) into v_payload;

  return v_payload;
end;
$function$


-- [40000000342] function private.tgg_world_discover_events()
CREATE OR REPLACE FUNCTION private.tgg_world_discover_events()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_count integer:=0;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  v_count:=private.tgg_discover_dynamic_events(v_char);
  return jsonb_build_object('discovered',v_count,'character_id',v_char);
end;
$function$


-- [40000000343] function private.tgg_world_dynamic_event_resolution(p_character_id uuid, p_dynamic_event_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_dynamic_event_resolution(p_character_id uuid, p_dynamic_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_event public.tgg_world_dynamic_events%rowtype;
  v_template public.tgg_world_dynamic_event_templates%rowtype;
  v_char public.world_characters%rowtype;
  v_rep integer:=0;
  v_roll numeric:=0;
  v_probability numeric:=1;
  v_outcome_key text:='success';
  v_reward jsonb:='{}'::jsonb;
  v_bonus jsonb:='{}'::jsonb;
  v_crew_id uuid;
  v_crew_rank integer:=1;
  v_crew_rep integer:=0;
  v_crew_rivalry integer:=0;
  v_npc_key text;
  v_npc_rivalry integer:=0;
  v_npc_loyalty integer:=0;
  v_rationale text:='default_success';
begin
  select * into v_event
  from public.tgg_world_dynamic_events
  where id=p_dynamic_event_id;

  if v_event.id is null then raise exception 'dynamic_event_not_found'; end if;

  select * into v_template
  from public.tgg_world_dynamic_event_templates
  where event_key=v_event.event_key and enabled=true;

  if v_template.event_key is null then raise exception 'event_template_unavailable'; end if;

  select * into v_char
  from public.world_characters
  where id=p_character_id and character_status='active';

  if v_char.id is null then raise exception 'active_character_required'; end if;

  select coalesce(reputation,0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=p_character_id and career_key=v_char.active_career;

  v_roll:=(
    (('x'||substr(md5(p_character_id::text||':'||p_dynamic_event_id::text||':resolution'),1,8))::bit(32)::bigint)
    % 1000000
  )::numeric/1000000;

  v_npc_key:=case when cardinality(v_template.npc_keys)>0 then v_template.npc_keys[1] else null end;

  if v_npc_key is not null then
    select coalesce(rivalry,0),coalesce(loyalty,0)
    into v_npc_rivalry,v_npc_loyalty
    from public.tgg_world_character_npc_standing
    where character_id=p_character_id and npc_key=v_npc_key;
  end if;

  select m.crew_id,coalesce(cp.rank_level,1),coalesce(cp.reputation,0)
  into v_crew_id,v_crew_rank,v_crew_rep
  from public.tgg_world_crew_members m
  left join public.tgg_world_crew_progression cp on cp.crew_id=m.crew_id
  where m.character_id=p_character_id and m.left_at is null
  order by m.joined_at desc
  limit 1;

  if v_crew_id is not null then
    select coalesce(max(r.rivalry),0) into v_crew_rivalry
    from public.tgg_world_crew_relations r
    where r.crew_a_id=v_crew_id or r.crew_b_id=v_crew_id;
  end if;

  if v_template.outcomes ? 'success' and v_template.outcomes ? 'fail' then
    v_probability:=least(0.90,greatest(0.35,0.55+least(greatest(v_rep,0),175)::numeric/500));
    if v_roll<=v_probability then
      v_outcome_key:='success';
      v_rationale:='reputation_weighted_showcase_roll';
    else
      v_outcome_key:='fail';
      v_rationale:='reputation_weighted_showcase_roll';
    end if;

  elsif v_template.outcomes ? 'win' and v_template.outcomes ? 'lose' then
    v_probability:=least(
      0.85,
      greatest(
        0.20,
        0.50
        + greatest(v_crew_rank-1,0)::numeric*0.05
        + least(greatest(v_crew_rep,0),250)::numeric/1000
        - least(greatest(v_crew_rivalry,0),100)::numeric/500
      )
    );
    if v_roll<=v_probability then
      v_outcome_key:='win';
    else
      v_outcome_key:='lose';
    end if;
    v_rationale:='crew_power_vs_rivalry_roll';

  elsif v_template.outcomes ? 'win' and v_template.outcomes ? 'deescalate' then
    if v_npc_loyalty>=v_npc_rivalry then
      v_outcome_key:='deescalate';
      v_probability:=1;
      v_rationale:='npc_loyalty_at_or_above_rivalry';
    else
      v_outcome_key:='win';
      v_probability:=1;
      v_rationale:='npc_rivalry_above_loyalty';
    end if;

  elsif v_template.outcomes ? 'success' then
    v_outcome_key:='success';
    v_probability:=1;
    v_rationale:='success_path';

  else
    select key into v_outcome_key
    from jsonb_object_keys(v_template.outcomes) key
    where key<>'bonus'
    order by key
    limit 1;
    v_rationale:='single_available_outcome';
  end if;

  v_reward:=coalesce(v_template.outcomes->v_outcome_key,'{}'::jsonb);

  if v_outcome_key='success' and v_template.outcomes ? 'bonus' then
    v_bonus:=coalesce(v_template.outcomes->'bonus','{}'::jsonb);
    v_reward:=v_reward||v_bonus;
  end if;

  return jsonb_build_object(
    'event_id',v_event.id,
    'event_key',v_template.event_key,
    'outcome_key',v_outcome_key,
    'reward',v_reward,
    'bonus',v_bonus,
    'roll',v_roll,
    'success_probability',v_probability,
    'rationale',v_rationale,
    'inputs',jsonb_build_object(
      'career_reputation',v_rep,
      'crew_id',v_crew_id,
      'crew_rank',v_crew_rank,
      'crew_reputation',v_crew_rep,
      'crew_rivalry',v_crew_rivalry,
      'npc_key',v_npc_key,
      'npc_rivalry',v_npc_rivalry,
      'npc_loyalty',v_npc_loyalty
    )
  );
end;
$function$


-- [40000000344] function private.tgg_world_effective_modifiers(p_character_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_effective_modifiers(p_character_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_season jsonb:='{}'::jsonb;
  v_season_rewards jsonb:='{}'::jsonb;
  v_prestige jsonb:='{}'::jsonb;
  v_story jsonb:='{}'::jsonb;
  v_earned jsonb:='{}'::jsonb;
  v_endgame jsonb:='{}'::jsonb;
  v_property_effects jsonb:='{}'::jsonb;
  v_faction_perks jsonb:='{}'::jsonb;
  v_career text;
  v_property_career_bonus numeric:=0;
  v_vehicle_service_bonus numeric:=0;
  v_xp_bonus numeric:=0;
  v_business_bonus numeric:=0;
  v_rare_event_bonus numeric:=0;
  v_event_weight numeric:=1;
  v_rare_gig_modifier numeric:=0;
  v_unlock_weight_bonus numeric:=0;
  v_elite boolean:=false;
  v_story_unlocks jsonb:='[]'::jsonb;
begin
  if not exists(select 1 from public.world_characters where id=p_character_id) then
    raise exception 'character_not_found';
  end if;

  select active_career into v_career
  from public.world_characters
  where id=p_character_id;

  v_property_effects:=private.tgg_world_property_effects(p_character_id);

  select coalesce(jsonb_object_agg(k.key,to_jsonb(k.total_value)),'{}'::jsonb)
  into v_faction_perks
  from (
    select e.key,
           sum(case when jsonb_typeof(e.value)='number'
                    then (e.value#>>'{}')::numeric else 0 end) total_value
    from public.tgg_world_character_factions cf
    join public.tgg_world_factions f on f.faction_key=cf.faction_key and f.enabled=true
    cross join lateral jsonb_each(f.perks) e
    where cf.character_id=p_character_id
      and cf.status='favored'
    group by e.key
  ) k;
  v_property_career_bonus :=
      case when v_career in ('artist','dj','engineer','producer','videographer')
        then coalesce((v_property_effects->>'creator_bonus')::numeric,0)
        else 0 end
    + case when v_career='manager'
        then coalesce((v_property_effects->>'manager_bonus')::numeric,0)
        else 0 end
    + case when v_career='producer'
        then coalesce((v_property_effects->>'producer_bonus')::numeric,0)
        else 0 end;

  v_vehicle_service_bonus:=greatest(
    coalesce((v_property_effects->>'vehicle_service_bonus')::numeric,0),0
  );

  select coalesce(s.modifiers,'{}'::jsonb)
  into v_season
  from public.tgg_world_seasons s
  where s.enabled=true
    and (s.starts_at is null or s.starts_at<=now())
    and (s.ends_at is null or s.ends_at>=now())
  order by s.starts_at desc nulls last
  limit 1;

  select coalesce(jsonb_build_object(
    'xp_bonus',coalesce(sum(coalesce((r.reward->>'xp_bonus')::numeric,0)),0),
    'rare_event_bonus',coalesce(sum(coalesce((r.reward->>'rare_event_bonus')::numeric,0)),0)
  ),'{}'::jsonb)
  into v_season_rewards
  from public.tgg_world_character_season_progress sp
  join public.tgg_world_season_rewards r
    on r.season_key=sp.season_key
   and sp.unlocked_rewards @> jsonb_build_array(r.reward_level)
  join public.tgg_world_seasons s on s.season_key=sp.season_key
  where sp.character_id=p_character_id
    and s.enabled=true
    and (s.starts_at is null or s.starts_at<=now())
    and (s.ends_at is null or s.ends_at>=now());

  select coalesce(permanent_unlocks,'{}'::jsonb)
  into v_prestige
  from public.tgg_world_character_prestige
  where character_id=p_character_id;

  select coalesce(jsonb_build_object(
    'rare_gig_modifier',coalesce(sum(coalesce((s.consequence_state->>'rare_gig_modifier')::numeric,0)),0),
    'unlock_weight_bonus',coalesce(sum(coalesce((s.consequence_state->>'unlock_weight_bonus')::numeric,0)),0),
    'story_unlocks',coalesce(jsonb_agg(distinct s.consequence_state->>'story_unlock')
      filter(where s.consequence_state ? 'story_unlock'),'[]'::jsonb)
  ),'{}'::jsonb)
  into v_story
  from public.tgg_world_character_story_state s
  where s.character_id=p_character_id;

  select coalesce(
    jsonb_object_agg(k.key,k.value),'{}'::jsonb
  )
  into v_endgame
  from public.tgg_world_character_endgame ce
  join public.tgg_world_endgame_milestones em on em.milestone_key=ce.milestone_key and em.enabled=true
  cross join lateral jsonb_each(em.unlocks) k
  where ce.character_id=p_character_id
    and ce.status='completed';

  select jsonb_build_object(
    'rare_gig_bonus',coalesce(sum(numeric_value) filter(where modifier_key='rare_gig_bonus'),0),
    'unlock_weight_bonus',coalesce(sum(numeric_value) filter(where modifier_key='unlock_weight_bonus'),0),
    'rare_event_bonus',coalesce(sum(numeric_value) filter(where modifier_key='rare_event_bonus'),0)
  )
  into v_earned
  from public.tgg_world_character_modifiers
  where character_id=p_character_id
    and (expires_at is null or expires_at>now());

  v_xp_bonus :=
      coalesce((v_season->>'career_xp_bonus')::numeric,0)
    + coalesce((v_season_rewards->>'xp_bonus')::numeric,0)
    + coalesce((v_prestige->>'xp_bonus')::numeric,0)
    + v_property_career_bonus;

  v_business_bonus :=
      coalesce((v_season->>'business_xp_bonus')::numeric,0)
    + coalesce((v_faction_perks->>'business_xp_bonus')::numeric,0)
    + coalesce((v_season_rewards->>'xp_bonus')::numeric,0)
    + coalesce((v_prestige->>'xp_bonus')::numeric,0);

  v_rare_event_bonus :=
      coalesce((v_season_rewards->>'rare_event_bonus')::numeric,0)
    + coalesce((v_prestige->>'rare_event_bonus')::numeric,0)
    + coalesce((v_earned->>'rare_event_bonus')::numeric,0);

  v_unlock_weight_bonus :=
      coalesce((v_story->>'unlock_weight_bonus')::numeric,0)
    + coalesce((v_earned->>'unlock_weight_bonus')::numeric,0);

  v_event_weight := greatest(
      0.1,
      coalesce((v_season->>'city_event_weight')::numeric,1)
      + least(greatest(v_unlock_weight_bonus,0),1)
      + least(greatest(coalesce((v_property_effects->>'event_hype')::numeric,0)/100,0),1)
  );

  v_rare_gig_modifier :=
      coalesce((v_story->>'rare_gig_modifier')::numeric,0)
    + coalesce((v_earned->>'rare_gig_bonus')::numeric,0);

  v_elite := coalesce((v_prestige->>'elite_events')::boolean,false)
          or coalesce((v_prestige->>'elite_event_unlock')::boolean,false)
          or coalesce((v_endgame->>'elite_events')::boolean,false);
  v_story_unlocks := coalesce(v_story->'story_unlocks','[]'::jsonb);

  return jsonb_build_object(
    'career_xp_multiplier',1+greatest(v_xp_bonus,0),
    'business_xp_multiplier',1+greatest(v_business_bonus,0),
    'rare_event_bonus',least(greatest(v_rare_event_bonus,0),1),
    'event_weight_multiplier',v_event_weight,
    'rare_gig_modifier',least(greatest(v_rare_gig_modifier,0),1),
    'unlock_weight_bonus',least(greatest(v_unlock_weight_bonus,0),1),
    'elite_events_unlocked',v_elite,
    'vehicle_xp_multiplier',1+least(v_vehicle_service_bonus,1),
    'contract_weight_bonus',least(greatest(
      coalesce((v_property_effects->>'contract_weight')::numeric,0)
      + coalesce((v_faction_perks->>'contract_weight')::numeric,0),0),1),
    'collab_event_bonus',least(greatest(coalesce((v_faction_perks->>'collab_bonus')::numeric,0),0),1),
    'street_event_weight',greatest(coalesce((v_faction_perks->>'street_event_weight')::numeric,1),0.1),
    'night_event_bonus',least(greatest(coalesce((v_faction_perks->>'night_event_bonus')::numeric,0),0),1),
    'vip_weight',greatest(coalesce((v_faction_perks->>'vip_weight')::numeric,1),0.1),
    'crew_rep_bonus',least(greatest(coalesce((v_faction_perks->>'crew_rep_bonus')::numeric,0),0),1),
    'territory_bonus',least(greatest(coalesce((v_faction_perks->>'territory_bonus')::numeric,0),0),1),
    'faction_perks',v_faction_perks,
    'property_effects',v_property_effects,
    'story_unlocks',v_story_unlocks,
    'endgame_unlocks',v_endgame,
    'elite_property_access',coalesce((v_endgame->>'elite_property_access')::boolean,false),
    'world_icon_status',coalesce((v_endgame->>'world_icon_status')::boolean,false),
    'legend_storyline_unlocked',coalesce((v_endgame->>'legend_storyline')::boolean,false),
    'sources',jsonb_build_object(
      'season',v_season,
      'claimed_season_rewards',v_season_rewards,
      'prestige',v_prestige,
      'story',v_story,
      'earned',v_earned,
      'endgame',v_endgame,
      'property_effects',v_property_effects,
      'faction',v_faction_perks
    )
  );
end;
$function$


-- [40000000345] function private.tgg_world_effective_modifiers_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_effective_modifiers_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  return private.tgg_world_effective_modifiers(v_char);
end;
$function$


-- [40000000346] function private.tgg_world_elite_event_play(p_elite_event_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_elite_event_play(p_elite_event_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_event public.tgg_world_elite_events%rowtype;
  v_location text;
  v_rep integer:=0;
  v_career_level integer:=1;
  v_achievements integer:=0;
  v_crew uuid;
  v_crew_rank integer:=0;
  v_dominant integer:=0;
  v_business_prestige integer:=0;
  v_business uuid;
  v_city_influence integer:=0;
  v_prestige integer:=0;
  v_last timestamptz;
  v_requirements_ok boolean:=true;
  v_progression_event uuid;
  v_prestige_xp integer:=0;
  v_crew_rep integer:=0;
  v_business_xp integer:=0;
  v_title text;
  v_title_key text;
  v_run_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select * into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char.id is null then raise exception 'active_character_required'; end if;

  select * into v_event
  from public.tgg_world_elite_events
  where elite_event_key=p_elite_event_key and enabled=true;
  if v_event.elite_event_key is null then raise exception 'elite_event_unavailable'; end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_char.id::text||':'||v_event.elite_event_key,0)
  );

  select l.location_key into v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=v_char.id;

  if v_location is distinct from v_event.location_key then
    return jsonb_build_object(
      'ok',false,'reason','travel_required','location_key',v_event.location_key
    );
  end if;

  select max(completed_at) into v_last
  from public.tgg_world_character_elite_events
  where character_id=v_char.id and elite_event_key=v_event.elite_event_key;

  if v_last is not null
     and v_last+make_interval(mins=>v_event.cooldown_minutes)>now() then
    return jsonb_build_object(
      'ok',false,'reason','cooldown',
      'ready_at',v_last+make_interval(mins=>v_event.cooldown_minutes)
    );
  end if;

  select coalesce(reputation,0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char.id and career_key=v_char.active_career;

  select coalesce(career_level,1) into v_career_level
  from public.world_character_careers
  where character_id=v_char.id and career_key=v_char.active_career;

  select count(*) into v_achievements
  from public.tgg_world_character_achievements
  where character_id=v_char.id and unlocked_at is not null;

  select m.crew_id into v_crew
  from public.tgg_world_crew_members m
  where m.character_id=v_char.id and m.user_id=v_uid and m.left_at is null
  order by m.joined_at desc limit 1;

  if v_crew is not null then
    select coalesce(rank_level,1) into v_crew_rank
    from public.tgg_world_crew_progression where crew_id=v_crew;

    select count(*) into v_dominant
    from public.tgg_world_crew_territories
    where crew_id=v_crew and control_level='dominant';
  end if;

  select
    coalesce(max(p.prestige_level),0),
    (
      select b2.id
      from public.tgg_world_character_businesses b2
      left join public.tgg_world_character_business_prestige p2 on p2.business_id=b2.id
      where b2.character_id=v_char.id and b2.status='active'
      order by coalesce(p2.prestige_level,0) desc,b2.business_level desc,b2.created_at
      limit 1
    )
  into v_business_prestige,v_business
  from public.tgg_world_character_businesses b
  left join public.tgg_world_character_business_prestige p on p.business_id=b.id
  where b.character_id=v_char.id and b.status='active';

  select coalesce(total_influence,
    career_influence+crew_influence+business_influence+faction_influence+district_influence+social_influence,0)
  into v_city_influence
  from public.tgg_world_character_influence
  where character_id=v_char.id;

  select coalesce(prestige_level,0) into v_prestige
  from public.tgg_world_character_prestige
  where character_id=v_char.id;

  if v_event.entry_conditions ? 'reputation'
     and v_rep<(v_event.entry_conditions->>'reputation')::integer then v_requirements_ok:=false; end if;
  if v_event.entry_conditions ? 'career_level'
     and v_career_level<(v_event.entry_conditions->>'career_level')::integer then v_requirements_ok:=false; end if;
  if v_event.entry_conditions ? 'achievements'
     and v_achievements<(v_event.entry_conditions->>'achievements')::integer then v_requirements_ok:=false; end if;
  if v_event.entry_conditions ? 'crew_rank'
     and v_crew_rank<(v_event.entry_conditions->>'crew_rank')::integer then v_requirements_ok:=false; end if;
  if v_event.entry_conditions ? 'districts_dominant'
     and v_dominant<(v_event.entry_conditions->>'districts_dominant')::integer then v_requirements_ok:=false; end if;
  if v_event.entry_conditions ? 'faction'
     and not exists(
       select 1 from public.tgg_world_character_factions f
       where f.character_id=v_char.id
         and f.faction_key=v_event.entry_conditions->>'faction'
         and f.status<>'hostile'
     ) then v_requirements_ok:=false; end if;
  if v_event.entry_conditions ? 'business_prestige'
     and v_business_prestige<(v_event.entry_conditions->>'business_prestige')::integer then v_requirements_ok:=false; end if;
  if v_event.entry_conditions ? 'city_influence'
     and v_city_influence<(v_event.entry_conditions->>'city_influence')::integer then v_requirements_ok:=false; end if;
  if v_event.entry_conditions ? 'prestige_level'
     and v_prestige<(v_event.entry_conditions->>'prestige_level')::integer then v_requirements_ok:=false; end if;

  if not v_requirements_ok then
    return jsonb_build_object(
      'ok',false,'reason','requirements_not_met',
      'requirements',v_event.entry_conditions,
      'current',jsonb_build_object(
        'reputation',v_rep,'career_level',v_career_level,'achievements',v_achievements,
        'crew_rank',v_crew_rank,'districts_dominant',v_dominant,
        'business_prestige',v_business_prestige,
        'city_influence',v_city_influence,'prestige_level',v_prestige
      )
    );
  end if;

  v_business_xp:=greatest(coalesce((v_event.rewards->>'business_xp')::integer,0),0);

  v_progression_event:=private.tgg_apply_progression_event(
    v_char.id,'dynamic_event_completed',v_event.elite_event_key,
    jsonb_strip_nulls(jsonb_build_object(
      'career_xp',coalesce((v_event.rewards->>'career_xp')::integer,0),
      'reputation',coalesce((v_event.rewards->>'reputation')::integer,0),
      'business_id',case when v_business_xp>0 then v_business else null end,
      'business_xp',v_business_xp
    ))
  );

  v_prestige_xp:=greatest(coalesce((v_event.rewards->>'prestige_xp')::integer,0),0);
  if v_prestige_xp>0 then
    insert into public.tgg_world_character_prestige(
      character_id,prestige_level,lifetime_prestige_xp,permanent_unlocks,updated_at
    )
    values(v_char.id,0,v_prestige_xp,'{}'::jsonb,now())
    on conflict(character_id) do update
    set lifetime_prestige_xp=public.tgg_world_character_prestige.lifetime_prestige_xp+v_prestige_xp,
        updated_at=now();
  end if;

  v_crew_rep:=greatest(coalesce((v_event.rewards->>'crew_reputation')::integer,0),0);
  if v_crew is not null and v_crew_rep>0 then
    insert into public.tgg_world_crew_progression(
      crew_id,crew_xp,rank_level,reputation,unlocks,updated_at
    )
    values(v_crew,0,1,v_crew_rep,'{}'::jsonb,now())
    on conflict(crew_id) do update
    set reputation=public.tgg_world_crew_progression.reputation+v_crew_rep,
        updated_at=now();
  end if;

  v_title:=nullif(v_event.rewards->>'title','');
  if v_title is not null then
    v_title_key:=case
      when lower(v_title)='award winner' then 'title-award-winner'
      when lower(v_title)='world icon' then 'title-world-icon'
      else null
    end;

    if v_title_key is not null then
      insert into public.tgg_world_character_titles(character_id,title_key,equipped,unlocked_at)
      values(v_char.id,v_title_key,false,now())
      on conflict(character_id,title_key) do nothing;
    end if;
  end if;

  insert into public.tgg_world_character_elite_events(
    character_id,elite_event_key,result,completed_at,created_at
  )
  values(
    v_char.id,v_event.elite_event_key,
    jsonb_build_object(
      'rewards',v_event.rewards,
      'progression_event_id',v_progression_event,
      'crew_id',v_crew,
      'business_id',v_business
    ),
    now(),now()
  )
  returning id into v_run_id;

  perform private.tgg_recompute_progression(v_char.id);

  return jsonb_build_object(
    'ok',true,'run_id',v_run_id,'elite_event_key',v_event.elite_event_key,
    'title',v_event.title,'rewards',v_event.rewards,
    'cooldown_ready_at',now()+make_interval(mins=>v_event.cooldown_minutes)
  );
end;
$function$


-- [40000000347] function private.tgg_world_empire_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_empire_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_char uuid; v_rep integer:=0;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select id into v_char from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if v_char is null then return '{}'::jsonb; end if;
  select coalesce(max(reputation),0) into v_rep from public.tgg_world_career_reputation where character_id=v_char;

  return jsonb_build_object(
    'character_id',v_char,
    'influence',coalesce((select to_jsonb(i) from public.tgg_world_character_influence i where i.character_id=v_char),'{}'::jsonb),
    'properties',coalesce((
      select jsonb_agg(jsonb_build_object(
        'property_id',cp.id,'display_name',pc.display_name,'property_type',pc.property_type,
        'upgrades',coalesce((
          select jsonb_agg(jsonb_build_object(
            'upgrade_key',u.upgrade_key,'display_name',u.display_name,'upgrade_level',u.upgrade_level,
            'required_reputation',u.required_reputation,'effects',u.effects,
            'installed',exists(select 1 from public.tgg_world_character_property_upgrades cu where cu.property_id=cp.id and cu.upgrade_key=u.upgrade_key),
            'ready',v_rep>=u.required_reputation
          ) order by u.upgrade_level,u.display_name)
          from public.tgg_world_property_upgrades u
          where u.enabled=true and pc.property_type=any(u.property_types)
        ),'[]'::jsonb)
      ) order by cp.acquired_at)
      from public.tgg_world_character_properties cp
      join public.tgg_world_property_catalog pc on pc.property_key=cp.property_key
      where cp.character_id=v_char and cp.ownership_status='owned'
    ),'[]'::jsonb),
    'businesses',coalesce((
      select jsonb_agg(jsonb_build_object(
        'business_id',b.id,'business_name',b.business_name,'business_type_key',b.business_type_key,
        'business_level',b.business_level,'business_xp',b.business_xp,'reputation',b.reputation,
        'prestige',coalesce((
          select jsonb_build_object('prestige_level',p.prestige_level,'prestige_xp',p.prestige_xp,'unlocks',p.unlocks)
          from public.tgg_world_character_business_prestige p where p.business_id=b.id
        ),'{}'::jsonb),
        'prestige_levels',coalesce((
          select jsonb_agg(jsonb_build_object(
            'prestige_level',p.prestige_level,'title',p.title,'requirements',p.requirements,'perks',p.perks,
            'ready',b.business_level>=coalesce((p.requirements->>'business_level')::integer,0)
               and b.reputation>=coalesce((p.requirements->>'reputation')::integer,0)
          ) order by p.prestige_level)
          from public.tgg_world_business_prestige_levels p where p.enabled=true
        ),'[]'::jsonb),
        'competitions',coalesce((
          select jsonb_agg(jsonb_build_object(
            'competition_key',c.competition_key,'title',c.title,'metric_key',c.metric_key,
            'duration_hours',c.duration_hours,'rewards',c.rewards,
            'run',(
              select jsonb_build_object(
                'id',r.id,'status',r.status,'score',r.score,'result',r.result,
                'started_at',r.started_at,'completed_at',r.completed_at,
                'ready_at',r.started_at+make_interval(hours=>c.duration_hours)
              )
              from public.tgg_world_character_business_competitions r
              where r.business_id=b.id and r.competition_key=c.competition_key
              limit 1
            )
          ) order by c.title)
          from public.tgg_world_business_competitions c
          where c.enabled=true and b.business_type_key=any(c.business_type_keys)
        ),'[]'::jsonb)
      ) order by b.created_at)
      from public.tgg_world_character_businesses b
      where b.character_id=v_char and b.status='active'
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000348] function private.tgg_world_endgame_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_endgame_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_prestige integer:=0;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then return '{}'::jsonb; end if;

  select coalesce(prestige_level,0) into v_prestige
  from public.tgg_world_character_prestige
  where character_id=v_char;

  return jsonb_build_object(
    'character_id',v_char,
    'prestige_level',v_prestige,
    'milestones',coalesce((
      select jsonb_agg(jsonb_build_object(
        'milestone_key',m.milestone_key,
        'title',m.title,
        'description',m.description,
        'tier',m.tier,
        'requirements',m.requirements,
        'unlocks',m.unlocks,
        'state',case when s.character_id is null then jsonb_build_object(
          'status','locked','progress','{}'::jsonb,'completed_at',null
        ) else jsonb_build_object(
          'status',s.status,'progress',s.progress,'completed_at',s.completed_at
        ) end
      ) order by m.tier,m.title)
      from public.tgg_world_endgame_milestones m
      left join public.tgg_world_character_endgame s
        on s.character_id=v_char and s.milestone_key=m.milestone_key
      where m.enabled=true
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000349] function private.tgg_world_evaluate_incidents(p_character_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_evaluate_incidents(p_character_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_char public.world_characters%rowtype;
  v_rep integer:=0;
  v_rule record;
  v_ok boolean;
  v_roll numeric;
  v_chance numeric;
  v_spawn text;
  v_template public.tgg_world_dynamic_event_templates%rowtype;
  v_event_id uuid;
  v_snapshot jsonb;
  v_count integer:=0;
  v_latest timestamptz;
  v_max_rivalry integer:=0;
  v_max_loyalty integer:=0;
  v_recent_performance boolean:=false;
  v_bucket text;
  v_clock jsonb:='{}'::jsonb;
  v_hour integer:=0;
  v_location text;
  v_max_rivalry_npc text;
  v_max_loyalty_npc text;
  v_target_npc text;
  v_target_keys jsonb:='[]'::jsonb;
  v_occurrence_id uuid;
  v_favor_weight numeric:=0;
  v_block_weight numeric:=0;
begin
  select * into v_char
  from public.world_characters
  where id=p_character_id and character_status='active';

  if v_char.id is null then
    return jsonb_build_object('triggered',0,'reason','character_not_found');
  end if;

  select coalesce(reputation,0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char.id and career_key=v_char.active_career;

  select coalesce(max(rivalry),0),coalesce(max(loyalty),0)
  into v_max_rivalry,v_max_loyalty
  from public.tgg_world_character_npc_standing
  where character_id=v_char.id;

  select npc_key into v_max_rivalry_npc
  from public.tgg_world_character_npc_standing
  where character_id=v_char.id
  order by rivalry desc,updated_at desc,npc_key
  limit 1;

  select npc_key into v_max_loyalty_npc
  from public.tgg_world_character_npc_standing
  where character_id=v_char.id
  order by loyalty desc,updated_at desc,npc_key
  limit 1;

  select exists(
    select 1 from public.tgg_world_open_mic_performances p
    where p.character_id=v_char.id
      and p.performance_status='completed'
      and p.ended_at>now()-interval '24 hours'
  ) into v_recent_performance;

  v_clock:=private.tgg_world_clock();
  v_hour:=coalesce((v_clock->>'local_hour')::integer,0);

  select l.location_key into v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=v_char.id;

  for v_rule in
    select *
    from public.tgg_world_incident_rules
    where enabled=true
    order by severity desc,incident_key
  loop
    v_bucket:=private.tgg_world_incident_bucket_key(greatest(v_rule.cooldown_minutes,1));

    if exists(
      select 1
      from public.tgg_world_incident_occurrences
      where character_id=v_char.id
        and incident_key=v_rule.incident_key
        and bucket_key=v_bucket
    ) then
      continue;
    end if;

    select max(triggered_at) into v_latest
    from public.tgg_world_incident_occurrences
    where character_id=v_char.id and incident_key=v_rule.incident_key;

    if v_latest is not null
       and v_latest+make_interval(mins=>v_rule.cooldown_minutes)>now()
    then
      continue;
    end if;

    v_ok:=false;

    if v_rule.trigger_source='npc_rivalry' then
      v_ok:=v_max_rivalry>=coalesce((v_rule.trigger_conditions->>'rivalry_gte')::integer,0);
    elsif v_rule.trigger_source='npc_loyalty' then
      v_ok:=v_max_loyalty>=coalesce((v_rule.trigger_conditions->>'loyalty_gte')::integer,0);
    elsif v_rule.trigger_source='career_reputation' then
      v_ok:=v_rep>=coalesce((v_rule.trigger_conditions->>'reputation_gte')::integer,0);
    elsif v_rule.trigger_source='performance' then
      v_ok:=v_recent_performance
        and v_rep>=coalesce((v_rule.trigger_conditions->>'reputation_gte')::integer,0);
    elsif v_rule.trigger_source='time_window' then
      v_ok:=(
        (
          not (v_rule.trigger_conditions ? 'location')
          or v_location=v_rule.trigger_conditions->>'location'
        )
        and (
          not (v_rule.trigger_conditions ? 'hour_start')
          or not (v_rule.trigger_conditions ? 'hour_end')
          or case
            when (v_rule.trigger_conditions->>'hour_start')::integer
               <= (v_rule.trigger_conditions->>'hour_end')::integer
            then v_hour >= (v_rule.trigger_conditions->>'hour_start')::integer
             and v_hour <  (v_rule.trigger_conditions->>'hour_end')::integer
            else v_hour >= (v_rule.trigger_conditions->>'hour_start')::integer
              or v_hour <  (v_rule.trigger_conditions->>'hour_end')::integer
          end
        )
      );
    end if;

    if not v_ok then continue; end if;

    v_chance:=coalesce((v_rule.trigger_conditions->>'chance')::numeric,1);
    if v_chance<1 then
      v_roll:=private.tgg_world_incident_bucket_roll(
        v_char.id,v_rule.incident_key,greatest(v_rule.cooldown_minutes,1)
      );
      if v_roll>=v_chance then continue; end if;
    else
      v_roll:=0;
    end if;

    v_spawn:=nullif(v_rule.effects->>'spawn_event','');
    if v_spawn is null then continue; end if;

    select * into v_template
    from public.tgg_world_dynamic_event_templates
    where event_key=v_spawn and enabled=true;
    if v_template.event_key is null then continue; end if;

    if exists(
      select 1 from public.tgg_world_dynamic_events e
      where e.event_key=v_spawn
        and e.status in ('scheduled','active')
        and e.ends_at>now()
    ) then
      select id into v_event_id
      from public.tgg_world_dynamic_events
      where event_key=v_spawn
        and status in ('scheduled','active')
        and ends_at>now()
      order by starts_at desc limit 1;
    else
      insert into public.tgg_world_dynamic_events(
        event_key,location_key,status,starts_at,ends_at,world_state,
        spawned_by,created_at,updated_at
      )
      values(
        v_template.event_key,v_template.location_key,'active',now(),
        now()+make_interval(mins=>v_template.duration_minutes),
        jsonb_build_object(
          'incident_key',v_rule.incident_key,
          'character_id',v_char.id,
          'source','incident_engine'
        ),
        'incident_engine',now(),now()
      )
      returning id into v_event_id;
    end if;

    v_target_npc:=case
      when v_rule.trigger_source='npc_rivalry' then v_max_rivalry_npc
      when v_rule.trigger_source='npc_loyalty' then v_max_loyalty_npc
      else null
    end;
    v_target_keys:=case
      when v_target_npc is null then '[]'::jsonb
      else private.tgg_world_npc_opportunity_keys(v_char.id,v_target_npc)
    end;
    v_favor_weight:=greatest(coalesce((v_rule.effects->>'favored_opportunity_weight')::numeric,0),0);
    v_block_weight:=greatest(coalesce((v_rule.effects->>'blocked_opportunity_weight')::numeric,0),0);

    v_snapshot:=jsonb_build_object(
      'reputation',v_rep,
      'max_rivalry',v_max_rivalry,
      'max_loyalty',v_max_loyalty,
      'recent_performance',v_recent_performance,
      'chance',v_chance,
      'roll',v_roll,
      'spawn_event',v_spawn,
      'bucket_key',v_bucket,
      'world_clock',v_clock,
      'location_key',v_location,
      'target_npc',v_target_npc,
      'target_opportunity_keys',v_target_keys,
      'favored_opportunity_weight',v_favor_weight,
      'blocked_opportunity_weight',v_block_weight
    );

    v_occurrence_id:=null;
    insert into public.tgg_world_incident_occurrences(
      character_id,incident_key,dynamic_event_id,eligibility_snapshot,
      triggered_at,cooldown_ready_at,bucket_key
    )
    values(
      v_char.id,v_rule.incident_key,v_event_id,v_snapshot,now(),
      now()+make_interval(mins=>v_rule.cooldown_minutes),v_bucket
    )
    on conflict do nothing
    returning id into v_occurrence_id;

    if v_occurrence_id is not null then
      if v_favor_weight>0 then
        insert into public.tgg_world_character_modifiers(
          character_id,modifier_key,numeric_value,source_type,source_key,
          expires_at,metadata
        )
        values(
          v_char.id,'favored_opportunity_weight',v_favor_weight,
          'incident',v_occurrence_id::text,
          now()+make_interval(mins=>v_rule.cooldown_minutes),
          jsonb_build_object(
            'incident_key',v_rule.incident_key,
            'target_npc',v_target_npc,
            'target_keys',v_target_keys
          )
        )
        on conflict(character_id,modifier_key,source_type,source_key) do nothing;
      end if;

      if v_block_weight>0 then
        insert into public.tgg_world_character_modifiers(
          character_id,modifier_key,numeric_value,source_type,source_key,
          expires_at,metadata
        )
        values(
          v_char.id,'blocked_opportunity_weight',v_block_weight,
          'incident',v_occurrence_id::text,
          now()+make_interval(mins=>v_rule.cooldown_minutes),
          jsonb_build_object(
            'incident_key',v_rule.incident_key,
            'target_npc',v_target_npc,
            'target_keys',v_target_keys
          )
        )
        on conflict(character_id,modifier_key,source_type,source_key) do nothing;
      end if;
      insert into public.tgg_world_character_event_state(
        character_id,dynamic_event_id,status,progress,outcome,discovered_at,updated_at
      )
      values(
        v_char.id,v_event_id,'discovered','{}'::jsonb,'{}'::jsonb,now(),now()
      )
      on conflict(character_id,dynamic_event_id) do nothing;

      v_count:=v_count+1;
    end if;
  end loop;

  return jsonb_build_object(
    'triggered',v_count,
    'time_window_rules_deferred',false,
    'world_clock',v_clock,
    'current_location',v_location,
    'deterministic_chance',true,
    'bucket_concurrency_guard',true
  );
end;
$function$


-- [40000000350] function private.tgg_world_fast_travel(p_transit_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_fast_travel(p_transit_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_node public.tgg_world_transit_nodes%rowtype;
  v_rep integer:=0;
  v_result jsonb;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_node
  from public.tgg_world_transit_nodes
  where transit_key=p_transit_key and enabled=true;
  if v_node.transit_key is null then raise exception 'transit_unavailable'; end if;

  select coalesce(max(reputation),0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char;

  if v_rep<v_node.unlock_reputation then
    return jsonb_build_object(
      'ok',false,'reason','reputation_required',
      'reputation',v_rep,'required',v_node.unlock_reputation
    );
  end if;

  select public.tgg_world_join_location(v_node.location_key) into v_result;
  return jsonb_build_object(
    'ok',true,'transit_key',v_node.transit_key,
    'location_key',v_node.location_key,'travel',v_result
  );
end;
$function$


-- [40000000351] function private.tgg_world_friend_request_send_artist_impl(p_artist_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_friend_request_send_artist_impl(p_artist_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_target uuid;
  v_result jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select a.user_id into v_target from public.artists a where a.id=p_artist_id limit 1;
  if v_target is null then raise exception 'ARTIST_NOT_FOUND'; end if;
  if v_target=v_uid then raise exception 'CANNOT_FRIEND_SELF'; end if;
  select public.tgg_world_friend_request_send(v_target) into v_result;
  return coalesce(v_result,'{}'::jsonb) - 'user_id' - 'requester_user_id' - 'recipient_user_id';
end$function$


-- [40000000352] function private.tgg_world_hire_business_staff(p_business_id uuid, p_role_key text, p_staff_name text)
CREATE OR REPLACE FUNCTION private.tgg_world_hire_business_staff(p_business_id uuid, p_role_key text, p_staff_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_business public.tgg_world_character_businesses%rowtype;
  v_role public.tgg_world_business_staff_roles%rowtype;
  v_name text:=btrim(coalesce(p_staff_name,''));
  v_count integer;
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if char_length(v_name)<2 or char_length(v_name)>50 then raise exception 'staff_name_invalid'; end if;

  select b.* into v_business
  from public.tgg_world_character_businesses b
  join public.world_characters wc on wc.id=b.character_id
  where b.id=p_business_id and wc.user_id=v_uid and b.status='active';
  if v_business.id is null then raise exception 'business_ownership_required'; end if;

  select * into v_role from public.tgg_world_business_staff_roles
  where role_key=p_role_key and enabled=true;
  if v_role.role_key is null then raise exception 'staff_role_unavailable'; end if;

  if not (v_business.business_type_key=any(v_role.business_type_keys)) then raise exception 'staff_role_not_compatible'; end if;

  select count(*) into v_count from public.tgg_world_business_staff
  where business_id=v_business.id and status='active';
  if v_count>=20 then raise exception 'staff_limit_reached'; end if;

  insert into public.tgg_world_business_staff(business_id,role_key,staff_name,skill,loyalty,status,metadata,hired_at,updated_at)
  values(v_business.id,p_role_key,v_name,1,50,'active',jsonb_build_object('source','player_hire'),now(),now())
  returning id into v_id;
  return v_id;
end;
$function$


-- [40000000353] function private.tgg_world_incident_bucket_key(p_cooldown_minutes integer)
CREATE OR REPLACE FUNCTION private.tgg_world_incident_bucket_key(p_cooldown_minutes integer)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
  select floor(
    extract(epoch from now()) / greatest(p_cooldown_minutes*60,60)
  )::bigint::text;
$function$


-- [40000000354] function private.tgg_world_incident_bucket_roll(p_character_id uuid, p_incident_key text, p_cooldown_minutes integer)
CREATE OR REPLACE FUNCTION private.tgg_world_incident_bucket_roll(p_character_id uuid, p_incident_key text, p_cooldown_minutes integer)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
  select (
    abs(hashtextextended(
      p_character_id::text || ':' || p_incident_key || ':' ||
      private.tgg_world_incident_bucket_key(p_cooldown_minutes),
      0
    )) % 1000000
  )::numeric / 1000000::numeric;
$function$


-- [40000000355] function private.tgg_world_incident_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_incident_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_eval jsonb;
  v_clock jsonb:='{}'::jsonb;
  v_hour integer:=0;
  v_location text;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then return '{}'::jsonb; end if;

  v_eval:=private.tgg_world_evaluate_incidents(v_char);
  v_clock:=coalesce(v_eval->'world_clock',private.tgg_world_clock());
  v_hour:=coalesce((v_clock->>'local_hour')::integer,0);

  select l.location_key into v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=v_char;

  return jsonb_build_object(
    'character_id',v_char,
    'evaluation',v_eval,
    'recent_incidents',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',o.id,
        'incident_key',o.incident_key,
        'incident_type',r.incident_type,
        'severity',r.severity,
        'effects',r.effects,
        'dynamic_event_id',o.dynamic_event_id,
        'triggered_at',o.triggered_at,
        'cooldown_ready_at',o.cooldown_ready_at,
        'eligibility_snapshot',o.eligibility_snapshot
      ) order by o.triggered_at desc)
      from (
        select * from public.tgg_world_incident_occurrences
        where character_id=v_char
        order by triggered_at desc
        limit 20
      ) o
      join public.tgg_world_incident_rules r on r.incident_key=o.incident_key
    ),'[]'::jsonb),
    'deferred_time_rules','[]'::jsonb,
    'time_window_rules',coalesce((
      select jsonb_agg(jsonb_build_object(
        'incident_key',r.incident_key,
        'incident_type',r.incident_type,
        'trigger_conditions',r.trigger_conditions,
        'effects',r.effects,
        'world_clock',v_clock,
        'current_location',v_location,
        'active_now',
          (
            (not (r.trigger_conditions ? 'location')
             or v_location=r.trigger_conditions->>'location')
            and
            (
              not (r.trigger_conditions ? 'hour_start')
              or not (r.trigger_conditions ? 'hour_end')
              or case
                when (r.trigger_conditions->>'hour_start')::integer
                   <= (r.trigger_conditions->>'hour_end')::integer
                then v_hour >= (r.trigger_conditions->>'hour_start')::integer
                 and v_hour <  (r.trigger_conditions->>'hour_end')::integer
                else v_hour >= (r.trigger_conditions->>'hour_start')::integer
                  or v_hour <  (r.trigger_conditions->>'hour_end')::integer
              end
            )
          )
      ) order by r.incident_key)
      from public.tgg_world_incident_rules r
      where r.enabled=true and r.trigger_source='time_window'
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000356] function private.tgg_world_install_property_upgrade(p_property_id uuid, p_upgrade_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_install_property_upgrade(p_property_id uuid, p_upgrade_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_char uuid;
  v_prop public.tgg_world_character_properties%rowtype;
  v_cat public.tgg_world_property_catalog%rowtype;
  v_up public.tgg_world_property_upgrades%rowtype;
  v_rep integer:=0;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select id into v_char from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_prop from public.tgg_world_character_properties
  where id=p_property_id and character_id=v_char and ownership_status='owned';
  if v_prop.id is null then raise exception 'owned_property_required'; end if;

  select * into v_cat from public.tgg_world_property_catalog where property_key=v_prop.property_key;
  select * into v_up from public.tgg_world_property_upgrades where upgrade_key=p_upgrade_key and enabled=true;
  if v_up.upgrade_key is null then raise exception 'upgrade_unavailable'; end if;
  if not (v_cat.property_type=any(v_up.property_types)) then raise exception 'upgrade_not_compatible'; end if;

  select coalesce(max(reputation),0) into v_rep from public.tgg_world_career_reputation where character_id=v_char;
  if v_rep<v_up.required_reputation then
    return jsonb_build_object('ok',false,'reason','reputation_required','required',v_up.required_reputation,'reputation',v_rep);
  end if;

  insert into public.tgg_world_character_property_upgrades(property_id,upgrade_key,installed_level,metadata,installed_at)
  values(v_prop.id,v_up.upgrade_key,v_up.upgrade_level,jsonb_build_object('effects',v_up.effects),now())
  on conflict(property_id,upgrade_key) do update
  set installed_level=greatest(public.tgg_world_character_property_upgrades.installed_level,excluded.installed_level),
      metadata=excluded.metadata,installed_at=now();

  return jsonb_build_object('ok',true,'property_id',v_prop.id,'upgrade_key',v_up.upgrade_key,'effects',v_up.effects,'real_money_changed',false);
end;
$function$


-- [40000000357] function private.tgg_world_interaction_activate_impl(p_action_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_interaction_activate_impl(p_action_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_point record;
  v_bucket text;
  v_credit jsonb;
  v_contract_credit jsonb;
  v_gig_credit jsonb;
  v_alias_contract_credit jsonb;
  v_alias_gig_credit jsonb;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select * into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char.id is null then raise exception 'active_character_required'; end if;

  select p.id,p.interaction_key,p.action_key,p.label,l.location_key
  into v_point
  from public.tgg_world_interaction_points p
  join public.tgg_world_locations l on l.id=p.location_id
  where p.location_id=v_char.current_location_id
    and p.action_key=p_action_key
    and p.enabled=true
  order by p.interaction_key
  limit 1;

  if v_point.id is null then raise exception 'interaction_not_available_here'; end if;

  v_bucket:=to_char(date_trunc('hour',now()),'YYYYMMDDHH24');

  v_credit:=private.tgg_world_credit_career_mission_event(
    v_char.id,
    p_action_key,
    'world_interaction',
    v_point.interaction_key||':'||v_bucket,
    jsonb_build_object(
      'interaction_key',v_point.interaction_key,
      'location_key',v_point.location_key,
      'anti_farm_bucket','hour'
    )
  );

  v_contract_credit:=private.tgg_world_credit_contract_event(
    v_char.id,
    p_action_key,
    'world_interaction',
    v_point.interaction_key||':'||v_bucket,
    jsonb_build_object(
      'interaction_key',v_point.interaction_key,
      'location_key',v_point.location_key,
      'anti_farm_bucket','hour'
    )
  );

  v_gig_credit:=private.tgg_world_credit_gig_event(
    v_char.id,
    p_action_key,
    'world_interaction',
    v_point.interaction_key||':'||v_bucket,
    jsonb_build_object(
      'interaction_key',v_point.interaction_key,
      'location_key',v_point.location_key,
      'anti_farm_bucket','hour'
    )
  );

  if v_point.location_key='nova-club' and p_action_key='dj' then
    v_alias_contract_credit:=private.tgg_world_credit_contract_event(
      v_char.id,
      'dj_set',
      'world_interaction_alias',
      v_point.interaction_key||':'||v_bucket||':dj_set',
      jsonb_build_object(
        'interaction_key',v_point.interaction_key,
        'location_key',v_point.location_key,
        'alias_from','dj',
        'alias_to','dj_set',
        'anti_farm_bucket','hour'
      )
    );

    v_alias_gig_credit:=private.tgg_world_credit_gig_event(
      v_char.id,
      'dj_set',
      'world_interaction_alias',
      v_point.interaction_key||':'||v_bucket||':dj_set',
      jsonb_build_object(
        'interaction_key',v_point.interaction_key,
        'location_key',v_point.location_key,
        'alias_from','dj',
        'alias_to','dj_set',
        'anti_farm_bucket','hour'
      )
    );
  end if;

  return jsonb_build_object(
    'ok',true,
    'action_key',p_action_key,
    'interaction_key',v_point.interaction_key,
    'location_key',v_point.location_key,
    'mission_credit',v_credit,
    'contract_credit',v_contract_credit,
    'gig_credit',v_gig_credit,
    'alias_contract_credit',coalesce(v_alias_contract_credit,'{}'::jsonb),
    'alias_gig_credit',coalesce(v_alias_gig_credit,'{}'::jsonb)
  );
end;
$function$


-- [40000000358] function private.tgg_world_inventory_equip_impl(p_item_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_inventory_equip_impl(p_item_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_item public.tgg_world_shop_catalog%rowtype;
  v_inv public.tgg_world_inventory%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select * into v_item from public.tgg_world_shop_catalog where item_key=p_item_key and enabled=true;
  if not found then raise exception 'item_not_found'; end if;
  if not v_item.equippable or v_item.slot_key is null then raise exception 'item_not_equippable'; end if;

  select * into v_inv from public.tgg_world_inventory
  where user_id=v_uid and item_key=p_item_key and quantity>0;
  if not found then raise exception 'item_not_owned'; end if;

  update public.tgg_world_inventory i
  set equipped=false,updated_at=now()
  from public.tgg_world_shop_catalog c
  where i.user_id=v_uid
    and i.item_key=c.item_key
    and c.slot_key=v_item.slot_key
    and i.equipped=true;

  update public.tgg_world_inventory
  set equipped=true,updated_at=now()
  where user_id=v_uid and item_key=p_item_key;

  return jsonb_build_object(
    'ok',true,'item_key',p_item_key,'slot_key',v_item.slot_key,
    'equipped',true,'virtual_item',true,'real_money',false
  );
end
$function$


-- [40000000359] function private.tgg_world_job_accept(p_job_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_job_accept(p_job_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_job public.tgg_world_job_catalog%rowtype;
  v_rep integer:=0;
  v_location_district text;
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select * into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char.id is null then raise exception 'active_character_required'; end if;

  select * into v_job
  from public.tgg_world_job_catalog
  where job_key=p_job_key and enabled=true;
  if v_job.job_key is null then raise exception 'job_unavailable'; end if;

  if cardinality(v_job.career_affinity)>0
     and not (v_char.active_career=any(v_job.career_affinity)) then
    raise exception 'career_not_eligible';
  end if;

  select coalesce(reputation,0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char.id and career_key=v_char.active_career;

  if v_rep<v_job.min_reputation then
    raise exception 'reputation_requirement_not_met';
  end if;

  select l.district_key into v_location_district
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=v_char.id;

  if v_location_district is distinct from v_job.district_key then
    raise exception 'travel_to_job_district_first';
  end if;

  if exists(
    select 1 from public.tgg_world_character_jobs
    where character_id=v_char.id and status='accepted'
  ) then
    raise exception 'finish_current_job_first';
  end if;

  insert into public.tgg_world_character_jobs(
    character_id,job_key,status,progress,accepted_at,completed_at,updated_at
  )
  values(
    v_char.id,v_job.job_key,'accepted',
    jsonb_build_object('ready_at',now()+make_interval(mins=>v_job.shift_minutes)),
    now(),null,now()
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'job_id',v_id,'job_key',v_job.job_key,
    'display_name',v_job.display_name,
    'ready_at',now()+make_interval(mins=>v_job.shift_minutes),
    'district_key',v_job.district_key
  );
end;
$function$


-- [40000000360] function private.tgg_world_job_complete(p_job_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_job_complete(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_state public.tgg_world_character_jobs%rowtype;
  v_job public.tgg_world_job_catalog%rowtype;
  v_char public.world_characters%rowtype;
  v_location_district text;
  v_event uuid;
  v_crew uuid;
  v_crew_xp integer:=0;
  v_vehicle_xp integer:=0;
  v_vehicle uuid;
  v_district jsonb;
  v_job_multiplier numeric:=1;
  v_vehicle_multiplier numeric:=1;
  v_property_vehicle_multiplier numeric:=1;
  v_mod jsonb:='{}'::jsonb;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select j.* into v_state
  from public.tgg_world_character_jobs j
  join public.world_characters wc on wc.id=j.character_id
  where j.id=p_job_id and wc.user_id=v_uid and j.status='accepted'
  for update of j;
  if v_state.id is null then raise exception 'accepted_job_required'; end if;

  select * into v_job
  from public.tgg_world_job_catalog
  where job_key=v_state.job_key and enabled=true;

  select * into v_char from public.world_characters where id=v_state.character_id;

  select greatest(coalesce((value->>'value')::numeric,1),0)
  into v_job_multiplier
  from public.tgg_world_economy_config
  where config_key='job_reward_multiplier';
  v_job_multiplier:=coalesce(v_job_multiplier,1);

  select greatest(coalesce((value->>'value')::numeric,1),0)
  into v_vehicle_multiplier
  from public.tgg_world_economy_config
  where config_key='vehicle_xp_multiplier';
  v_vehicle_multiplier:=coalesce(v_vehicle_multiplier,1);
  v_mod:=private.tgg_world_effective_modifiers(v_char.id);
  v_property_vehicle_multiplier:=greatest(coalesce((v_mod->>'vehicle_xp_multiplier')::numeric,1),1);
  v_vehicle_multiplier:=v_vehicle_multiplier*v_property_vehicle_multiplier;

  if cardinality(v_job.career_affinity)>0
     and not (v_char.active_career=any(v_job.career_affinity)) then
    raise exception 'career_not_eligible';
  end if;

  if now()<v_state.accepted_at+make_interval(mins=>v_job.shift_minutes) then
    return jsonb_build_object(
      'ok',false,'reason','shift_not_ready',
      'ready_at',v_state.accepted_at+make_interval(mins=>v_job.shift_minutes)
    );
  end if;

  select l.district_key into v_location_district
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=v_char.id;

  if v_location_district is distinct from v_job.district_key then
    raise exception 'return_to_job_district';
  end if;

  if coalesce((v_job.vehicle_bonus->>'vehicle_required')::boolean,false) then
    select p.vehicle_id into v_vehicle
    from public.tgg_world_vehicle_passengers p
    join public.tgg_world_vehicles v on v.id=p.vehicle_id
    where p.user_id=v_uid and p.character_id=v_char.id
      and p.seat_key='driver' and p.left_at is null
      and v.owner_user_id=v_uid and v.vehicle_status='active'
    limit 1;
    if v_vehicle is null then raise exception 'active_driver_vehicle_required'; end if;
  end if;

  update public.tgg_world_character_jobs
  set status='completed',completed_at=now(),updated_at=now()
  where id=v_state.id;

  v_event:=private.tgg_apply_progression_event(
    v_char.id,'job_completed',v_job.job_key,
    jsonb_build_object(
      'career_xp',round(coalesce((v_job.rewards->>'career_xp')::numeric,0)*v_job_multiplier)::integer,
      'reputation',round(coalesce((v_job.rewards->>'reputation')::numeric,0)*v_job_multiplier)::integer
    )
  );

  select m.crew_id into v_crew
  from public.tgg_world_crew_members m
  where m.user_id=v_uid and m.character_id=v_char.id and m.left_at is null
  order by m.joined_at desc limit 1;

  if v_crew is not null then
    v_crew_xp:=round(coalesce((v_job.crew_bonus->>'crew_xp')::numeric,0)*v_job_multiplier)::integer;
    if v_crew_xp>0 then
      insert into public.tgg_world_crew_progression(crew_id,crew_xp,rank_level,reputation,unlocks,updated_at)
      values(v_crew,v_crew_xp,1,0,'{}'::jsonb,now())
      on conflict(crew_id) do update
      set crew_xp=public.tgg_world_crew_progression.crew_xp+v_crew_xp,
          rank_level=greatest(
            public.tgg_world_crew_progression.rank_level,
            coalesce((
              select max(r.rank_level)
              from public.tgg_world_crew_ranks r
              where r.enabled=true
                and r.required_crew_xp<=public.tgg_world_crew_progression.crew_xp+v_crew_xp
            ),1)
          ),
          updated_at=now();
    end if;
  end if;

  if v_vehicle is not null then
    v_vehicle_xp:=round(coalesce((v_job.vehicle_bonus->>'vehicle_xp')::numeric,0)*v_vehicle_multiplier)::integer;
    if v_vehicle_xp>0 then
      insert into public.tgg_world_vehicle_progression(
        vehicle_id,vehicle_level,vehicle_xp,performance_rating,style_rating,reliability,unlocks,updated_at
      )
      values(v_vehicle,1,v_vehicle_xp,1,1,100,'{}'::jsonb,now())
      on conflict(vehicle_id) do update
      set vehicle_xp=public.tgg_world_vehicle_progression.vehicle_xp+v_vehicle_xp,
          vehicle_level=least(
            10,
            greatest(
              public.tgg_world_vehicle_progression.vehicle_level,
              1+((public.tgg_world_vehicle_progression.vehicle_xp+v_vehicle_xp)/100)
            )
          ),
          updated_at=now();
    end if;
  end if;

  v_district:=private.tgg_world_apply_district_progress(v_char.id,
    (select location_key from public.tgg_world_locations where district_key=v_job.district_key and enabled=true order by location_key limit 1),
    8
  );

  perform private.tgg_world_credit_challenge_event(
    v_char.id,'jobs_completed','job',v_state.id::text
  );

  perform private.tgg_recompute_progression(v_char.id);

  return jsonb_build_object(
    'ok',true,'job_id',v_state.id,'job_key',v_job.job_key,
    'rewards',v_job.rewards,'crew_xp',v_crew_xp,'vehicle_xp',v_vehicle_xp,
    'progression_event_id',v_event,'district_progress',coalesce(v_district,'{}'::jsonb),
    'job_reward_multiplier',v_job_multiplier,'vehicle_xp_multiplier',v_vehicle_multiplier,'property_vehicle_multiplier',v_property_vehicle_multiplier
  );
end;
$function$


-- [40000000361] function private.tgg_world_join_faction(p_faction_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_join_faction(p_faction_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_faction public.tgg_world_factions%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select id into v_char from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_faction from public.tgg_world_factions where faction_key=p_faction_key and enabled=true;
  if v_faction.faction_key is null then raise exception 'faction_unavailable'; end if;

  insert into public.tgg_world_character_factions(character_id,faction_key,standing,rank_level,loyalty,status,updated_at)
  values(v_char,p_faction_key,0,1,10,'member',now())
  on conflict(character_id,faction_key) do update
  set status=case when public.tgg_world_character_factions.status='hostile' then 'hostile' else 'member' end,
      loyalty=greatest(public.tgg_world_character_factions.loyalty,10),
      updated_at=now();

  insert into public.tgg_world_character_faction_missions(character_id,mission_key,status,progress,updated_at)
  select v_char,m.mission_key,'active','{}'::jsonb,now()
  from public.tgg_world_faction_missions m
  where m.faction_key=p_faction_key and m.enabled=true
  on conflict(character_id,mission_key) do nothing;

  return jsonb_build_object('ok',true,'faction_key',p_faction_key,'status','member');
end;
$function$


-- [40000000362] function private.tgg_world_life_phone_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_life_phone_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_location text;
  v_balance bigint:=0;
  v_phone jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select wc.id,l.location_key
  into v_char,v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.user_id=v_uid and wc.character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  perform private.tgg_world_wallet_ensure_impl();
  select balance into v_balance from public.tgg_world_wallets where user_id=v_uid;

  select public.tgg_world_phone_bundle() into v_phone;

  return jsonb_build_object(
    'character_id',v_char,
    'current_location',v_location,
    'wallet',jsonb_build_object('balance',coalesce(v_balance,0),'currency','tgg_credits'),
    'stats',coalesce((
      select jsonb_object_agg(stat_key,stat_value)
      from public.world_character_stats
      where character_id=v_char
    ),'{}'::jsonb),
    'available_actions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'action_key',a.action_key,
        'display_name',a.display_name,
        'location_key',a.location_key,
        'cooldown_minutes',a.cooldown_minutes,
        'stat_delta',a.stat_delta,
        'requirements',a.requirements,
        'ready_at',(
          select max(l.performed_at)+make_interval(mins=>a.cooldown_minutes)
          from public.tgg_world_character_life_action_log l
          where l.character_id=v_char and l.action_key=a.action_key
        )
      ) order by a.display_name)
      from public.tgg_world_life_actions a
      where a.enabled=true and a.location_key=v_location
    ),'[]'::jsonb),
    'travel_actions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'action_key',a.action_key,'display_name',a.display_name,'location_key',a.location_key,
        'location_name',l.name
      ) order by l.name,a.display_name)
      from public.tgg_world_life_actions a
      join public.tgg_world_locations l on l.location_key=a.location_key
      where a.enabled=true and a.location_key<>v_location
    ),'[]'::jsonb),
    'inventory',coalesce((
      select jsonb_agg(jsonb_build_object(
        'item_key',i.item_key,
        'display_name',c.display_name,
        'category',c.category,
        'quantity',i.quantity,
        'equipped',i.equipped,
        'equippable',c.equippable,
        'slot_key',c.slot_key
      ) order by c.category,c.display_name)
      from public.tgg_world_inventory i
      join public.tgg_world_shop_catalog c on c.item_key=i.item_key
      where i.user_id=v_uid and i.quantity>0
    ),'[]'::jsonb),
    'shop',coalesce((
      select jsonb_agg(jsonb_build_object(
        'item_key',c.item_key,'display_name',c.display_name,'category',c.category,
        'price',c.price,'equippable',c.equippable,'slot_key',c.slot_key,
        'owned',exists(select 1 from public.tgg_world_inventory i where i.user_id=v_uid and i.item_key=c.item_key and i.quantity>0),
        'can_afford',coalesce(v_balance,0)>=c.price
      ) order by c.category,c.price,c.display_name)
      from public.tgg_world_shop_catalog c
      where c.enabled=true
    ),'[]'::jsonb),
    'phone',coalesce(v_phone,'{}'::jsonb),
    'recent_actions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'action_key',l.action_key,'location_key',l.location_key,
        'stat_delta',l.stat_delta,'result_stats',l.result_stats,'performed_at',l.performed_at
      ) order by l.performed_at desc)
      from (
        select * from public.tgg_world_character_life_action_log
        where character_id=v_char order by performed_at desc limit 12
      ) l
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000363] function private.tgg_world_local_interactions_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_local_interactions_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_location_id uuid;
  v_location_key text;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select wc.id,wc.current_location_id,l.location_key
  into v_char,v_location_id,v_location_key
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.user_id=v_uid and wc.character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  return jsonb_build_object(
    'character_id',v_char,
    'current_location',v_location_key,
    'interactions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',p.id,'interaction_key',p.interaction_key,'object_type',p.object_type,
        'label',p.label,'action_key',p.action_key,'position',p.position,
        'radius',p.radius,'permissions',p.permissions,'metadata',p.metadata
      ) order by p.label)
      from public.tgg_world_interaction_points p
      where p.location_id=v_location_id and p.enabled=true
    ),'[]'::jsonb),
    'audio_zones',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',z.id,'zone_key',z.zone_key,'zone_type',z.zone_type,
        'bounds',z.bounds,'audio_rules',z.audio_rules,'priority',z.priority
      ) order by z.priority desc,z.zone_key)
      from public.tgg_world_audio_zones z
      where z.location_id=v_location_id and z.enabled=true
    ),'[]'::jsonb),
    'action_map',jsonb_build_object(
      'start_studio_session',jsonb_build_object('kind','rpc','rpc','tgg_world_studio_open'),
      'join_open_mic',jsonb_build_object('kind','rpc','rpc','tgg_world_open_mic_join_queue'),
      'open_garage',jsonb_build_object('kind','screen','screen','world-assets'),
      'open_career_board',jsonb_build_object('kind','screen','screen','world-career'),
      'distribution_desk',jsonb_build_object('kind','screen','screen','world-runtime'),
      'metadata_review',jsonb_build_object('kind','screen','screen','world-runtime'),
      'rights_review',jsonb_build_object('kind','screen','screen','world-runtime'),
      'dj_set',jsonb_build_object('kind','screen','screen','world-activity'),
      'performance_complete',jsonb_build_object('kind','screen','screen','world-activity'),
      'label_meeting',jsonb_build_object('kind','screen','screen','world-map'),
      'manager_meeting',jsonb_build_object('kind','screen','screen','world-map'),
      'network',jsonb_build_object('kind','life_action','action_key','music-row-network'),
      'producer_session',jsonb_build_object('kind','url','url','https://trugogettamixtapes.blogspot.com/p/beat-studio.html'),
      'radio_session',jsonb_build_object('kind','url','url','https://trugogettamixtapes.blogspot.com/p/tgg-radio.html'),
      'video_shoot',jsonb_build_object('kind','url','url','https://trugogettamixtapes.blogspot.com/p/video-studio.html'),
      'dj',jsonb_build_object('kind','screen','screen','world-activity'),
      'enter_club',jsonb_build_object('kind','screen','screen','world-activity'),
      'open_phone',jsonb_build_object('kind','screen','screen','world-home'),
      'browse_shop',jsonb_build_object('kind','screen','screen','world-home'),
      'start_workout',jsonb_build_object('kind','workout','workout_type','gym'),
      'open_job_board',jsonb_build_object('kind','screen','screen','world-career')
    )
  );
end;
$function$


-- [40000000364] function private.tgg_world_map_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_map_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_current text;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select wc.id,l.location_key
  into v_char,v_current
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.user_id=v_uid and wc.character_status='active'
  limit 1;

  return jsonb_build_object(
    'character_id',v_char,
    'current_location',v_current,
    'districts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'district_key',d.district_key,
        'display_name',d.display_name,
        'description',d.description,
        'unlock_reputation',d.unlock_reputation,
        'featured_locations',d.featured_locations,
        'activity_tags',d.activity_tags
      ) order by d.display_name)
      from public.tgg_world_districts d where d.enabled
    ),'[]'::jsonb),
    'locations',coalesce((
      select jsonb_agg(jsonb_build_object(
        'location_key',l.location_key,
        'name',l.name,
        'location_type',l.location_type,
        'district_key',l.district_key,
        'capacity',l.capacity,
        'privacy_mode',l.privacy_mode,
        'is_public',l.privacy_mode='public',
        'interaction_spec',l.interaction_spec,
        'layout_spec',l.layout_spec,
        'lighting_spec',l.lighting_spec,
        'is_current',l.location_key=v_current
      ) order by l.name)
      from public.tgg_world_locations l
      where l.enabled=true
    ),'[]'::jsonb),
    'npcs',coalesce((
      select jsonb_agg(jsonb_build_object(
        'npc_key',n.npc_key,
        'display_name',n.display_name,
        'archetype',n.archetype,
        'location_key',s.location_key,
        'activity_key',s.activity_key,
        'mood',s.mood,
        'next_transition_at',s.next_transition_at
      ) order by n.display_name)
      from public.tgg_world_npc_profiles n
      left join public.tgg_world_npc_runtime_state s on s.npc_key=n.npc_key
      where n.enabled
    ),'[]'::jsonb),
    'events',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',e.id,'event_key',e.event_key,'location_key',e.location_key,
        'status',e.status,'starts_at',e.starts_at,'ends_at',e.ends_at
      ) order by e.starts_at)
      from public.tgg_world_dynamic_events e
      where e.status in ('scheduled','active')
    ),'[]'::jsonb),
    'transit',coalesce((
      select jsonb_agg(to_jsonb(t) order by t.display_name)
      from public.tgg_world_transit_nodes t where t.enabled
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000365] function private.tgg_world_media_readiness_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_media_readiness_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_provider jsonb;
  v_call jsonb;
  v_invite jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select public.tgg_provider_final_health() into v_provider;
  select public.tgg_call_validation_final_health() into v_call;
  select public.tgg_call_validation_invite_status() into v_invite;

  return jsonb_build_object(
    'provider_version',v_provider->>'version',
    'call_validation',v_call,
    'validation_invite',v_invite,
    'media',jsonb_build_object(
      'camera_screen_capture_ready',true,
      'webrtc_signaling_ready',true,
      'realtime_signals_published',true,
      'realtime_rooms_published',true,
      'realtime_participants_published',true,
      'realtime_live_state_published',true,
      'realtime_viewers_published',true,
      'sfu_turn',coalesce((
        select jsonb_build_object(
          'provider_key',i->>'provider_key',
          'enabled',(i->>'enabled')::boolean,
          'endpoint_configured',(i->>'endpoint_configured')::boolean,
          'mode',i->>'mode',
          'disabled_reason',i->>'disabled_reason'
        )
        from jsonb_array_elements(coalesce(v_provider->'adapters','[]'::jsonb)) i
        where i->>'provider_key'='broadcast.sfu_turn'
        limit 1
      ),jsonb_build_object(
        'provider_key','broadcast.sfu_turn',
        'enabled',false,
        'endpoint_configured',true,
        'mode','endpoint_staged',
        'disabled_reason','activation_bridge_secret_required'
      )),
      'fallback',jsonb_build_object(
        'call_rooms',true,
        'webrtc_offer_answer',true,
        'realtime_signaling',true,
        'live_chat',true,
        'guest_requests',true,
        'project_presence',true,
        'camera_screen_local_recording',true,
        'scalable_audience_video',false
      )
    ),
    'realtime_tables',jsonb_build_array(
      'tgg_call_rooms','tgg_call_participants','tgg_call_signals',
      'live_streams','live_stream_viewers','tgg_live_chat_messages',
      'tgg_live_guest_requests','tgg_studio_project_presence'
    )
  );
end;
$function$


-- [40000000366] function private.tgg_world_memory_history_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_memory_history_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then return '{}'::jsonb; end if;

  return jsonb_build_object(
    'character_id',v_char,
    'npc_memories',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',m.id,
        'npc_key',m.npc_key,
        'display_name',coalesce(n.display_name,m.npc_key),
        'memory_type',m.memory_type,
        'memory_key',m.memory_key,
        'weight',m.weight,
        'sentiment',m.sentiment,
        'payload',m.payload,
        'occurred_at',m.occurred_at
      ) order by m.occurred_at desc)
      from (
        select * from public.tgg_world_npc_memory_events
        where character_id=v_char
        order by occurred_at desc
        limit 40
      ) m
      left join public.tgg_world_npc_profiles n on n.npc_key=m.npc_key
    ),'[]'::jsonb),
    'choice_history',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',c.id,
        'encounter_id',c.encounter_id,
        'node_key',c.node_key,
        'choice_key',c.choice_key,
        'effect_snapshot',c.effect_snapshot,
        'created_at',c.created_at
      ) order by c.created_at desc)
      from (
        select * from public.tgg_world_encounter_choice_log
        where character_id=v_char
        order by created_at desc
        limit 40
      ) c
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000367] function private.tgg_world_milestone_tier_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_milestone_tier_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_rep integer:=0;
  v_properties integer:=0;
  v_businesses integer:=0;
  v_vehicles integer:=0;
  v_crew_owner boolean:=false;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  select coalesce(sum(reputation),0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char;

  select count(*) into v_properties
  from public.tgg_world_character_properties
  where character_id=v_char and ownership_status='owned';

  select count(*) into v_businesses
  from public.tgg_world_character_businesses
  where character_id=v_char and status='active';

  select count(*) into v_vehicles
  from public.tgg_world_vehicles
  where owner_character_id=v_char and vehicle_status='active';

  select exists(
    select 1 from public.tgg_world_crews c
    where c.owner_character_id=v_char and c.crew_status='active'
  ) into v_crew_owner;

  return jsonb_build_object(
    'character_id',v_char,
    'summary',jsonb_build_object(
      'reputation',v_rep,
      'properties',v_properties,
      'businesses',v_businesses,
      'vehicles',v_vehicles,
      'crew_owner',v_crew_owner
    ),
    'city_reputation',coalesce((
      select jsonb_build_object(
        'tier_key',t.tier_key,
        'tier_order',t.tier_order,
        'display_name',t.display_name,
        'min_reputation',t.min_reputation,
        'perks',t.perks
      )
      from public.tgg_world_city_reputation_tiers t
      where t.enabled=true and v_rep>=t.min_reputation
      order by t.min_reputation desc
      limit 1
    ),'{}'::jsonb),
    'next_city_reputation',(
      select jsonb_build_object(
        'tier_key',t.tier_key,
        'tier_order',t.tier_order,
        'display_name',t.display_name,
        'min_reputation',t.min_reputation,
        'needed',greatest(t.min_reputation-v_rep,0),
        'perks',t.perks
      )
      from public.tgg_world_city_reputation_tiers t
      where t.enabled=true and t.min_reputation>v_rep
      order by t.min_reputation
      limit 1
    ),
    'milestones',coalesce((
      select jsonb_agg(jsonb_build_object(
        'milestone_key',m.milestone_key,
        'title',m.title,
        'category',m.category,
        'conditions',m.conditions,
        'unlocks',m.unlocks,
        'met',
          (not (m.conditions ? 'reputation') or v_rep>=(m.conditions->>'reputation')::integer)
          and (not (m.conditions ? 'property_count') or v_properties>=(m.conditions->>'property_count')::integer)
          and (not (m.conditions ? 'properties') or v_properties>=(m.conditions->>'properties')::integer)
          and (not (m.conditions ? 'business_count') or v_businesses>=(m.conditions->>'business_count')::integer)
          and (not (m.conditions ? 'businesses') or v_businesses>=(m.conditions->>'businesses')::integer)
          and (not (m.conditions ? 'vehicle_count') or v_vehicles>=(m.conditions->>'vehicle_count')::integer)
          and (not (m.conditions ? 'crew_owner') or v_crew_owner=(m.conditions->>'crew_owner')::boolean)
      ) order by m.category,m.title)
      from public.tgg_world_progression_milestones m
      where m.enabled=true
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000368] function private.tgg_world_music_session_claim()
CREATE OR REPLACE FUNCTION private.tgg_world_music_session_claim()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_presence public.tgg_world_presence%rowtype;
  v_session public.tgg_world_music_sessions%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select * into v_presence
  from public.tgg_world_presence
  where user_id=v_uid and presence_state='online'
  limit 1;

  if v_presence.user_id is null then raise exception 'active_world_presence_required'; end if;

  select * into v_session
  from public.tgg_world_music_sessions
  where instance_id=v_presence.instance_id
  for update;

  if v_session.id is null then
    insert into public.tgg_world_music_sessions(
      instance_id,controller_user_id,track_id,playback_state,position_seconds,
      playback_rate,started_at,updated_at,version
    )
    values(
      v_presence.instance_id,v_uid,null,'paused',0,1,null,now(),1
    )
    returning * into v_session;
  elsif v_session.controller_user_id=v_uid then
    null;
  elsif not exists(
    select 1 from public.tgg_world_presence p
    where p.instance_id=v_presence.instance_id
      and p.user_id=v_session.controller_user_id
      and p.presence_state='online'
      and p.last_seen_at>now()-interval '2 minutes'
  ) then
    update public.tgg_world_music_sessions
    set controller_user_id=v_uid,updated_at=now(),version=version+1
    where id=v_session.id
    returning * into v_session;
  else
    return jsonb_build_object(
      'ok',false,'reason','controller_active',
      'controller_user_id',v_session.controller_user_id,
      'session_id',v_session.id
    );
  end if;

  return jsonb_build_object(
    'ok',true,'session_id',v_session.id,
    'instance_id',v_session.instance_id,
    'controller_user_id',v_session.controller_user_id,
    'version',v_session.version
  );
end;
$function$


-- [40000000369] function private.tgg_world_music_session_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_music_session_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_presence public.tgg_world_presence%rowtype;
  v_session public.tgg_world_music_sessions%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select * into v_presence
  from public.tgg_world_presence
  where user_id=v_uid and presence_state='online'
  limit 1;

  if v_presence.user_id is null then
    return jsonb_build_object('active_presence',false);
  end if;

  select * into v_session
  from public.tgg_world_music_sessions
  where instance_id=v_presence.instance_id;

  return jsonb_build_object(
    'active_presence',true,
    'instance_id',v_presence.instance_id,
    'is_controller',v_session.controller_user_id=v_uid,
    'session',case when v_session.id is null then null else jsonb_build_object(
      'id',v_session.id,
      'controller_user_id',v_session.controller_user_id,
      'track_id',v_session.track_id,
      'playback_state',v_session.playback_state,
      'position_seconds',v_session.position_seconds,
      'playback_rate',v_session.playback_rate,
      'started_at',v_session.started_at,
      'updated_at',v_session.updated_at,
      'version',v_session.version,
      'track',(
        select jsonb_build_object(
          'id',t.id,
          'title',t.title,
          'featured_artist',t.featured_artist,
          'duration_seconds',t.duration_seconds,
          'artist_name',a.stage_name,
          'mixtape_title',m.title
        )
        from public.tracks t
        join public.mixtapes m on m.id=t.mixtape_id
        left join public.artists a on a.id=t.artist_id
        where t.id=v_session.track_id
      )
    ) end,
    'published_tracks',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',t.id,
        'title',t.title,
        'featured_artist',t.featured_artist,
        'duration_seconds',t.duration_seconds,
        'artist_name',a.stage_name,
        'mixtape_title',m.title
      ) order by m.release_date desc nulls last,m.title,t.track_number)
      from (
        select t.*
        from public.tracks t
        join public.mixtapes m2 on m2.id=t.mixtape_id
        where m2.status='published'
        order by m2.release_date desc nulls last,t.created_at desc
        limit 50
      ) t
      join public.mixtapes m on m.id=t.mixtape_id
      left join public.artists a on a.id=t.artist_id
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000370] function private.tgg_world_music_session_set(p_track_id uuid, p_playback_state text, p_position_seconds numeric, p_playback_rate numeric)
CREATE OR REPLACE FUNCTION private.tgg_world_music_session_set(p_track_id uuid DEFAULT NULL::uuid, p_playback_state text DEFAULT NULL::text, p_position_seconds numeric DEFAULT NULL::numeric, p_playback_rate numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_presence public.tgg_world_presence%rowtype;
  v_session public.tgg_world_music_sessions%rowtype;
  v_state text;
  v_pos numeric;
  v_rate numeric;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select * into v_presence
  from public.tgg_world_presence
  where user_id=v_uid and presence_state='online'
  limit 1;
  if v_presence.user_id is null then raise exception 'active_world_presence_required'; end if;

  select * into v_session
  from public.tgg_world_music_sessions
  where instance_id=v_presence.instance_id
    and controller_user_id=v_uid
  for update;
  if v_session.id is null then raise exception 'music_controller_required'; end if;

  if p_track_id is not null and not exists(
    select 1
    from public.tracks t
    join public.mixtapes m on m.id=t.mixtape_id
    where t.id=p_track_id and m.status='published'
  ) then
    raise exception 'published_track_required';
  end if;

  v_state:=coalesce(p_playback_state,v_session.playback_state);
  if v_state not in ('paused','playing','stopped') then
    raise exception 'invalid_playback_state';
  end if;

  v_pos:=coalesce(p_position_seconds,v_session.position_seconds);
  if v_pos<0 then raise exception 'invalid_position'; end if;

  v_rate:=coalesce(p_playback_rate,v_session.playback_rate);
  if v_rate<=0 or v_rate>2 then raise exception 'invalid_playback_rate'; end if;

  update public.tgg_world_music_sessions
  set track_id=coalesce(p_track_id,track_id),
      playback_state=v_state,
      position_seconds=case when v_state='stopped' then 0 else v_pos end,
      playback_rate=v_rate,
      started_at=case
        when v_state='playing' and playback_state<>'playing' then now()
        when v_state='stopped' then null
        else started_at
      end,
      updated_at=now(),
      version=version+1
  where id=v_session.id
  returning * into v_session;

  return jsonb_build_object(
    'ok',true,'session_id',v_session.id,'track_id',v_session.track_id,
    'playback_state',v_session.playback_state,
    'position_seconds',v_session.position_seconds,
    'playback_rate',v_session.playback_rate,
    'started_at',v_session.started_at,
    'version',v_session.version
  );
end;
$function$


-- [40000000371] function private.tgg_world_next_moves_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_next_moves_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_character uuid;
  v_career text;
  v_location text;
  v_power jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select wc.id,wc.active_career,l.location_key
  into v_character,v_career,v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.user_id=v_uid and wc.character_status='active'
  limit 1;

  if v_character is null then
    return jsonb_build_object('moves','[]'::jsonb,'events','[]'::jsonb);
  end if;

  perform private.tgg_schedule_dynamic_events();
  perform private.tgg_discover_dynamic_events(v_character);
  perform private.tgg_rotate_challenges(v_character);

  v_power:=private.tgg_world_city_power_payload();

  return jsonb_build_object(
    'moves',(
      select coalesce(jsonb_agg(x.move order by x.priority desc),'[]'::jsonb)
      from (
        select 110 as priority,jsonb_build_object(
          'type','job',
          'title',j.display_name,
          'subtitle','Finish your active shift',
          'location_key',j.district_key,
          'ref_id',s.id,
          'priority',110
        ) as move
        from public.tgg_world_character_jobs s
        join public.tgg_world_job_catalog j on j.job_key=s.job_key
        where s.character_id=v_character and s.status='accepted'

        union all

        select 105,jsonb_build_object(
          'type','crew_contract',
          'title',c.title,
          'subtitle','Advance your crew contract',
          'location_key',(
            select l.location_key
            from public.tgg_world_locations l
            where l.district_key=c.district_key and l.enabled=true
            order by l.location_key limit 1
          ),
          'ref_id',r.id,
          'priority',105
        )
        from public.tgg_world_crew_contract_runs r
        join public.tgg_world_crew_contracts c on c.contract_key=r.contract_key
        where r.status='active'
          and exists(
            select 1 from public.tgg_world_crew_members m
            where m.crew_id=r.crew_id and m.character_id=v_character and m.left_at is null
          )

        union all

        select 100,jsonb_build_object(
          'type','gig',
          'title',t.title,
          'subtitle','Continue your accepted gig',
          'location_key',t.location_key,
          'ref_id',g.id,
          'priority',100
        )
        from public.tgg_world_character_gigs g
        join public.tgg_world_gig_templates t on t.gig_key=g.gig_key
        where g.character_id=v_character and g.status='accepted'

        union all

        select 90,jsonb_build_object(
          'type','event',
          'title',t.title,
          'subtitle','Live city event',
          'location_key',e.location_key,
          'ref_id',e.id,
          'priority',90
        )
        from public.tgg_world_character_event_state s
        join public.tgg_world_dynamic_events e on e.id=s.dynamic_event_id
        join public.tgg_world_dynamic_event_templates t on t.event_key=e.event_key
        where s.character_id=v_character
          and s.status in ('discovered','joined')
          and e.status='active'
          and e.ends_at>now()

        union all

        select 80,jsonb_build_object(
          'type','challenge',
          'title',t.display_name,
          'subtitle',upper(t.cadence)||' challenge',
          'location_key',null,
          'ref_id',c.challenge_key,
          'priority',80
        )
        from public.tgg_world_character_challenges c
        join public.tgg_world_challenge_templates t on t.challenge_key=c.challenge_key
        where c.character_id=v_character and c.status='active'

        union all

        select 70,jsonb_build_object(
          'type','elite_event',
          'title',e->>'title',
          'subtitle','Elite event ready',
          'location_key',e->>'location_key',
          'ref_id',e->>'elite_event_key',
          'priority',70
        )
        from jsonb_array_elements(coalesce(v_power->'elite_events','[]'::jsonb)) e
        where coalesce((e->>'requirements_ready')::boolean,false)
          and (
            e->>'ready_at' is null
            or (e->>'ready_at')::timestamptz<=now()
          )

        union all

        select 60,jsonb_build_object(
          'type','contact',
          'title','Meet '||c.display_name,
          'subtitle',c.role_title||coalesce(' · '||c.organization,''),
          'location_key',c.location_key,
          'ref_id',c.contact_key,
          'priority',60
        )
        from public.tgg_world_industry_contacts c
        where c.enabled=true
          and (cardinality(c.career_affinity)=0 or v_career=any(c.career_affinity))

        order by priority desc
        limit 12
      ) x
    ),
    'events',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',e.id,
        'event_key',e.event_key,
        'title',t.title,
        'event_type',t.event_type,
        'location_key',e.location_key,
        'status',s.status,
        'starts_at',e.starts_at,
        'ends_at',e.ends_at,
        'joined_at',s.joined_at,
        'min_participation_seconds',coalesce(
          nullif((s.progress->>'min_participation_seconds')::integer,0),
          nullif((t.metadata->>'min_participation_seconds')::integer,0),
          least(120,greatest(30,t.duration_minutes*3))
        ),
        'ready_at',case when s.status='joined' then coalesce(
          nullif(s.progress->>'ready_at','')::timestamptz,
          s.joined_at+make_interval(secs=>coalesce(
            nullif((s.progress->>'min_participation_seconds')::integer,0),
            nullif((t.metadata->>'min_participation_seconds')::integer,0),
            least(120,greatest(30,t.duration_minutes*3))
          ))
        ) else null end,
        'ready_to_complete',case when s.status='joined' then now()>=coalesce(
          nullif(s.progress->>'ready_at','')::timestamptz,
          s.joined_at+make_interval(secs=>coalesce(
            nullif((s.progress->>'min_participation_seconds')::integer,0),
            nullif((t.metadata->>'min_participation_seconds')::integer,0),
            least(120,greatest(30,t.duration_minutes*3))
          ))
        ) else false end,
        'possible_outcomes',t.outcomes,
        'rewards',coalesce(t.outcomes->'success',t.outcomes->'win','{}'::jsonb)
      ) order by t.priority desc,e.ends_at)
      from public.tgg_world_character_event_state s
      join public.tgg_world_dynamic_events e on e.id=s.dynamic_event_id
      join public.tgg_world_dynamic_event_templates t on t.event_key=e.event_key
      where s.character_id=v_character
        and s.status in ('discovered','joined')
        and e.status='active'
        and e.ends_at>now()
    ),'[]'::jsonb),
    'current_location',v_location
  );
end;
$function$


-- [40000000372] function private.tgg_world_npc_encounters_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_npc_encounters_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_location text;
  v_rep integer:=0;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select wc.id,l.location_key
  into v_char,v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.user_id=v_uid and wc.character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  select coalesce(max(reputation),0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char;

  return jsonb_build_object(
    'character_id',v_char,
    'current_location',v_location,
    'reputation',v_rep,
    'npcs',coalesce((
      select jsonb_agg(jsonb_build_object(
        'npc_key',n.npc_key,
        'display_name',n.display_name,
        'archetype',n.archetype,
        'location_key',coalesce(rs.location_key,n.home_location_key),
        'activity_key',rs.activity_key,
        'mood',rs.mood,
        'encounters',coalesce((
          select jsonb_agg(jsonb_build_object(
            'encounter_key',e.encounter_key,
            'title',e.title,
            'location_key',e.location_key,
            'trigger_type',e.trigger_type,
            'trigger_conditions',e.trigger_conditions,
            'repeatable',e.repeatable,
            'cooldown_minutes',e.cooldown_minutes,
            'at_location',v_location=e.location_key,
            'reputation_ready',not (e.trigger_conditions ? 'min_reputation')
              or v_rep>=coalesce((e.trigger_conditions->>'min_reputation')::integer,0),
            'active_encounter_id',(
              select ce.id from public.tgg_world_character_encounters ce
              where ce.character_id=v_char and ce.encounter_key=e.encounter_key and ce.status='active'
              order by ce.started_at desc limit 1
            ),
            'cooldown_until',(
              select ce.completed_at+make_interval(mins=>e.cooldown_minutes)
              from public.tgg_world_character_encounters ce
              where ce.character_id=v_char and ce.encounter_key=e.encounter_key and ce.completed_at is not null
              order by ce.completed_at desc limit 1
            )
          ) order by e.priority desc,e.title)
          from public.tgg_world_encounter_templates e
          where e.npc_key=n.npc_key and e.enabled=true
        ),'[]'::jsonb)
      ) order by n.display_name)
      from public.tgg_world_npc_profiles n
      left join public.tgg_world_npc_runtime_state rs on rs.npc_key=n.npc_key
      where n.enabled=true
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000373] function private.tgg_world_npc_opportunity_keys(p_character_id uuid, p_npc_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_npc_opportunity_keys(p_character_id uuid, p_npc_key text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
  with npc_contact as (
    select i.contact_key
    from public.tgg_world_npc_profiles n
    join public.tgg_world_industry_contacts i
      on lower(i.display_name)=lower(n.display_name)
     and i.enabled=true
    where n.npc_key=p_npc_key and n.enabled=true
    limit 1
  ),
  keys as (
    select jsonb_array_elements_text(s.favored_opportunities) key
    from public.tgg_world_character_npc_standing s
    where s.character_id=p_character_id and s.npc_key=p_npc_key
    union
    select jsonb_array_elements_text(s.blocked_opportunities)
    from public.tgg_world_character_npc_standing s
    where s.character_id=p_character_id and s.npc_key=p_npc_key
    union
    select c.contract_key
    from public.tgg_world_career_contracts c
    join npc_contact nc on nc.contact_key=c.contact_key
    where c.enabled=true
    union
    select g.gig_key
    from public.tgg_world_gig_templates g
    join npc_contact nc on nc.contact_key=g.contact_key
    where g.enabled=true
  )
  select coalesce(jsonb_agg(key order by key),'[]'::jsonb)
  from keys;
$function$


-- [40000000374] function private.tgg_world_npc_relationship_network_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_npc_relationship_network_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;

  return jsonb_build_object(
    'nodes',coalesce((
      select jsonb_agg(jsonb_build_object(
        'npc_key',n.npc_key,
        'display_name',n.display_name,
        'archetype',n.archetype,
        'home_location_key',n.home_location_key,
        'primary_job',n.primary_job,
        'crew_affiliation',n.crew_affiliation
      ) order by n.display_name)
      from public.tgg_world_npc_profiles n
      where n.enabled=true
        and exists(
          select 1
          from public.tgg_world_npc_relationships r
          where r.npc_a_key=n.npc_key or r.npc_b_key=n.npc_key
        )
    ),'[]'::jsonb),
    'edges',coalesce((
      select jsonb_agg(jsonb_build_object(
        'npc_a_key',r.npc_a_key,
        'npc_a_name',coalesce(a.display_name,r.npc_a_key),
        'npc_b_key',r.npc_b_key,
        'npc_b_name',coalesce(b.display_name,r.npc_b_key),
        'relationship_type',r.relationship_type,
        'affinity',r.affinity,
        'rivalry',r.rivalry,
        'trust',r.trust,
        'metadata',r.metadata,
        'updated_at',r.updated_at
      ) order by r.rivalry desc,r.affinity desc,r.npc_a_key,r.npc_b_key)
      from public.tgg_world_npc_relationships r
      left join public.tgg_world_npc_profiles a on a.npc_key=r.npc_a_key
      left join public.tgg_world_npc_profiles b on b.npc_key=r.npc_b_key
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000375] function private.tgg_world_onboarding_event(p_character_id uuid, p_event_type text, p_source_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_onboarding_event(p_character_id uuid, p_event_type text, p_source_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_state public.tgg_world_character_onboarding%rowtype;
  v_step public.tgg_world_onboarding_steps%rowtype;
  v_match boolean := false;
  v_next integer;
begin
  insert into public.tgg_world_character_onboarding(character_id)
  values(p_character_id)
  on conflict(character_id) do nothing;

  select * into v_state
  from public.tgg_world_character_onboarding
  where character_id=p_character_id
  for update;

  if v_state.status<>'active' then
    return jsonb_build_object('status',v_state.status,'advanced',false);
  end if;

  select * into v_step
  from public.tgg_world_onboarding_steps
  where step_order=v_state.current_step_order and enabled=true;

  if not found then
    return jsonb_build_object('status','active','advanced',false,'reason','step_missing');
  end if;

  v_match :=
    coalesce(v_step.objective->>'event_type','') = p_event_type
    and (
      not (v_step.objective ? 'source_key')
      or coalesce(v_step.objective->>'source_key','') = coalesce(p_source_key,'')
    );

  if not v_match then
    return jsonb_build_object('status','active','advanced',false,'current_step',v_step.step_key);
  end if;

  if v_step.step_order=8 then
    update public.tgg_world_character_onboarding
    set completed_steps=array_append(completed_steps,v_step.step_key),
        status='completed',completed_at=now(),updated_at=now()
    where character_id=p_character_id;

    insert into public.tgg_world_character_titles(character_id,title_key,unlocked_at)
    select p_character_id,t.title_key,now()
    from public.tgg_world_titles t
    where t.title_key='title-rising-artist'
    on conflict do nothing;

    insert into public.tgg_world_character_collectibles(character_id,collectible_key,quantity,acquired_at,metadata)
    select p_character_id,c.collectible_key,1,now(),jsonb_build_object('source','onboarding')
    from public.tgg_world_collectibles c
    where c.collectible_key='collect-red-chain'
    on conflict(character_id,collectible_key) do nothing;

    return jsonb_build_object('status','completed','advanced',true,'completed_step',v_step.step_key);
  end if;

  v_next := v_step.step_order + 1;
  update public.tgg_world_character_onboarding
  set completed_steps=array_append(completed_steps,v_step.step_key),
      current_step_order=v_next,
      updated_at=now()
  where character_id=p_character_id;

  return jsonb_build_object(
    'status','active',
    'advanced',true,
    'completed_step',v_step.step_key,
    'next_step_order',v_next
  );
end;
$function$


-- [40000000376] function private.tgg_world_onboarding_from_progression()
CREATE OR REPLACE FUNCTION private.tgg_world_onboarding_from_progression()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  perform private.tgg_world_onboarding_event(new.character_id,new.event_type,new.source_key);
  return new;
end;
$function$


-- [40000000377] function private.tgg_world_onboarding_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_onboarding_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_uid uuid:=auth.uid(); v_character uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select id into v_character from public.world_characters
  where user_id=v_uid and character_status='active' limit 1;
  if v_character is null then return '{}'::jsonb; end if;

  return jsonb_build_object(
    'state',coalesce((
      select jsonb_build_object(
        'status',o.status,
        'current_step_order',o.current_step_order,
        'completed_steps',o.completed_steps,
        'started_at',o.started_at,
        'completed_at',o.completed_at
      )
      from public.tgg_world_character_onboarding o
      where o.character_id=v_character
    ),'{}'::jsonb),
    'steps',coalesce((
      select jsonb_agg(jsonb_build_object(
        'step_key',s.step_key,
        'step_order',s.step_order,
        'title',s.title,
        'description',s.description,
        'objective_type',s.objective_type,
        'objective',s.objective,
        'unlocks',s.unlocks
      ) order by s.step_order)
      from public.tgg_world_onboarding_steps s
      where s.enabled=true
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000378] function private.tgg_world_open_business(p_property_id uuid, p_business_type_key text, p_business_name text)
CREATE OR REPLACE FUNCTION private.tgg_world_open_business(p_property_id uuid, p_business_type_key text, p_business_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_prop public.tgg_world_character_properties%rowtype;
  v_catalog public.tgg_world_property_catalog%rowtype;
  v_type public.tgg_world_business_types%rowtype;
  v_rep integer:=0;
  v_slots integer:=0;
  v_id uuid;
  v_name text:=btrim(coalesce(p_business_name,''));
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if char_length(v_name)<2 or char_length(v_name)>60 then raise exception 'business_name_invalid'; end if;

  select id into v_char from public.world_characters
  where user_id=v_uid and character_status='active' limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_prop from public.tgg_world_character_properties
  where id=p_property_id and character_id=v_char and ownership_status='owned';
  if v_prop.id is null then raise exception 'property_ownership_required'; end if;

  select * into v_catalog from public.tgg_world_property_catalog
  where property_key=v_prop.property_key and enabled=true;

  select * into v_type from public.tgg_world_business_types
  where business_type_key=p_business_type_key and enabled=true;
  if v_type.business_type_key is null then raise exception 'business_type_unavailable'; end if;

  if not (v_catalog.property_type=any(v_type.allowed_property_types)) then raise exception 'business_not_compatible_with_property'; end if;

  select coalesce(max(reputation),0) into v_rep
  from public.tgg_world_career_reputation where character_id=v_char;
  if v_rep<v_type.required_reputation then raise exception 'business_reputation_requirement_not_met'; end if;

  select count(*) into v_slots from public.tgg_world_character_businesses
  where property_id=v_prop.id and status in ('active','paused');
  if v_slots>=v_catalog.business_slots then raise exception 'property_business_slots_full'; end if;

  insert into public.tgg_world_character_businesses(character_id,property_id,business_type_key,business_name,business_level,business_xp,reputation,status,settings,created_at,updated_at)
  values(v_char,v_prop.id,p_business_type_key,v_name,1,0,0,'active','{}'::jsonb,now(),now())
  returning id into v_id;
  return v_id;
end;
$function$


-- [40000000379] function private.tgg_world_open_mic_finish_impl(p_performance_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_open_mic_finish_impl(p_performance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_perf public.tgg_world_open_mic_performances%rowtype;
  v_reactions integer; v_xp integer; v_buzz integer;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select * into v_perf from public.tgg_world_open_mic_performances where id=p_performance_id for update;
  if not found then raise exception 'performance not found'; end if;
  if v_perf.user_id<>v_uid then raise exception 'only the performer can finish this Alpha performance'; end if;
  if v_perf.performance_status='complete' then
    return jsonb_build_object('performance_id',v_perf.id,'already_complete',true,'reward_applied',v_perf.reward_applied,'reward_detail',v_perf.reward_detail);
  end if;
  if v_perf.performance_status='canceled' then
    return jsonb_build_object(
      'performance_id',v_perf.id,
      'already_canceled',true,
      'reward_applied',false,
      'reward_detail',v_perf.reward_detail,
      'xp',0,
      'buzz',0,
      'virtual_reward_only',true,
      'real_money',false,
      'rights_effect',false
    );
  end if;

  select count(*) into v_reactions from public.tgg_world_open_mic_reactions where performance_id=v_perf.id;
  v_xp:=25 + least(v_reactions,10)*2; v_buzz:=5 + least(v_reactions,10);
  if not v_perf.reward_applied then
    insert into public.world_character_stats(character_id,stat_key,stat_value)
    values(v_perf.character_id,'xp',v_xp)
    on conflict(character_id,stat_key) do update set stat_value=public.world_character_stats.stat_value+excluded.stat_value;
    insert into public.world_character_stats(character_id,stat_key,stat_value)
    values(v_perf.character_id,'buzz',v_buzz)
    on conflict(character_id,stat_key) do update set stat_value=public.world_character_stats.stat_value+excluded.stat_value;
  end if;
  update public.tgg_world_open_mic_performances
  set performance_status='complete',ended_at=now(),reward_applied=true,
      reward_detail=jsonb_build_object('type','virtual_progression','xp',v_xp,'buzz',v_buzz,'reaction_count',v_reactions,'real_money',false,'rights_effect',false)
  where id=v_perf.id;
  update public.tgg_world_open_mic_queue set queue_status='done' where event_id=v_perf.event_id and user_id=v_perf.user_id;
  update public.tgg_world_open_mic_events set event_status='open',current_performance_id=null,updated_at=now() where id=v_perf.event_id;
  perform private.tgg_world_credit_career_mission_event(
    v_perf.character_id,'open_mic_performance','open_mic_performance',v_perf.id::text,jsonb_build_object('reaction_count',v_reactions)
  );
  perform private.tgg_world_credit_contract_event(
    v_perf.character_id,'open_mic_performance','open_mic_performance',v_perf.id::text,jsonb_build_object('reaction_count',v_reactions)
  );
  perform private.tgg_world_credit_contract_event(
    v_perf.character_id,'performance_complete','open_mic_performance',v_perf.id::text,jsonb_build_object('reaction_count',v_reactions,'performance_kind','open_mic')
  );
  perform private.tgg_world_credit_gig_event(
    v_perf.character_id,'performance_complete','open_mic_performance',v_perf.id::text,jsonb_build_object('reaction_count',v_reactions,'performance_kind','open_mic')
  );
  return jsonb_build_object('performance_id',v_perf.id,'reward_applied',true,'xp',v_xp,'buzz',v_buzz,'virtual_reward_only',true,'real_money',false,'rights_effect',false);
end
$function$


-- [40000000380] function private.tgg_world_open_mic_join_queue_impl()
CREATE OR REPLACE FUNCTION private.tgg_world_open_mic_join_queue_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_char public.world_characters%rowtype;
  v_location public.tgg_world_locations%rowtype;
  v_presence public.world_presence%rowtype;
  v_join jsonb;
  v_event uuid;
  v_pos integer;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  perform private.tgg_world_open_mic_recover_stale();

  select * into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if not found then raise exception 'active world character required'; end if;

  select * into v_location
  from public.tgg_world_locations
  where id=v_char.current_location_id and location_key='corner-stage' and enabled=true;
  if not found then raise exception 'character must be at Corner Stage'; end if;

  select * into v_presence
  from public.world_presence
  where user_id=v_uid and left_at is null and heartbeat_at > now()-interval '2 minutes'
  order by heartbeat_at desc
  limit 1;

  if v_presence.id is null or v_presence.instance_id is null then
    v_join := tgg_private.world_join_location('corner-stage');
    perform tgg_private.world_presence_heartbeat(
      jsonb_build_object('x',0,'y',0,'z',0),
      jsonb_build_object('location_key','corner-stage','source','open-mic-queue-v11.6.1')
    );
    select * into v_presence
    from public.world_presence
    where user_id=v_uid and left_at is null and heartbeat_at > now()-interval '2 minutes'
    order by heartbeat_at desc
    limit 1;
  end if;
  if v_presence.id is null or v_presence.instance_id is null then raise exception 'active Corner Stage presence required'; end if;

  if not exists(
    select 1 from public.world_instances i
    where i.id=v_presence.instance_id and i.location_id=v_location.id and i.status in ('active','draining')
  ) then raise exception 'Corner Stage instance required'; end if;

  select e.id into v_event
  from public.tgg_world_open_mic_events e
  where e.location_id=v_location.id
    and e.instance_id=v_presence.instance_id
    and e.event_status in ('open','performing')
  order by e.created_at desc limit 1;

  if v_event is null then
    insert into public.tgg_world_open_mic_events(location_id,instance_id)
    values(v_location.id,v_presence.instance_id)
    returning id into v_event;
  end if;

  select coalesce(max(queue_position),0)+1 into v_pos
  from public.tgg_world_open_mic_queue
  where event_id=v_event and queue_status in ('waiting','performing');

  insert into public.tgg_world_open_mic_queue(event_id,user_id,character_id,queue_position,queue_status)
  values(v_event,v_uid,v_char.id,v_pos,'waiting')
  on conflict(event_id,user_id) do update
  set character_id=excluded.character_id,
      queue_position=excluded.queue_position,
      queue_status='waiting',
      joined_at=now();

  return jsonb_build_object(
    'event_id',v_event,
    'instance_id',v_presence.instance_id,
    'queue_position',v_pos,
    'virtual_reward_only',true,
    'real_money',false
  );
end
$function$


-- [40000000381] function private.tgg_world_open_mic_react_impl(p_performance_id uuid, p_reaction text)
CREATE OR REPLACE FUNCTION private.tgg_world_open_mic_react_impl(p_performance_id uuid, p_reaction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if p_reaction not in ('fire','clap','heart','star') then raise exception 'invalid reaction'; end if;

  if not exists(
    select 1
    from public.tgg_world_open_mic_performances p
    join public.tgg_world_open_mic_events e on e.id=p.event_id
    join public.world_presence wp
      on wp.user_id=v_uid
     and wp.instance_id=e.instance_id
     and wp.left_at is null
     and wp.heartbeat_at > now()-interval '2 minutes'
    join public.world_characters c on c.id=wp.character_id and c.user_id=v_uid
    where p.id=p_performance_id
      and p.performance_status='live'
      and e.instance_id is not null
      and c.current_location_id=e.location_id
  ) then raise exception 'active same-instance audience presence required'; end if;

  insert into public.tgg_world_open_mic_reactions(performance_id,user_id,reaction)
  values(p_performance_id,v_uid,p_reaction)
  on conflict(performance_id,user_id) do update
  set reaction=excluded.reaction,reacted_at=now();

  return jsonb_build_object('performance_id',p_performance_id,'reaction',p_reaction,'instance_verified',true);
end
$function$


-- [40000000382] function private.tgg_world_open_mic_recover_stale()
CREATE OR REPLACE FUNCTION private.tgg_world_open_mic_recover_stale()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_waiting integer := 0;
  v_sets integer := 0;
  r record;
begin
  update public.tgg_world_open_mic_queue
  set queue_status='left'
  where queue_status='waiting'
    and joined_at < now() - interval '30 minutes';
  get diagnostics v_waiting = row_count;

  for r in
    select p.id,p.event_id,p.user_id
    from public.tgg_world_open_mic_performances p
    where p.performance_status='live'
      and p.started_at < now() - interval '45 minutes'
    for update skip locked
  loop
    update public.tgg_world_open_mic_performances
    set performance_status='canceled',
        ended_at=now(),
        reward_applied=false,
        reward_detail=jsonb_build_object(
          'type','stale_recovery',
          'reason','performance_timeout',
          'reward_applied',false,
          'xp',0,
          'buzz',0,
          'real_money',false,
          'rights_effect',false
        ),
        performance_metadata=coalesce(performance_metadata,'{}'::jsonb)
          || jsonb_build_object('stale_recovered_at',now(),'timeout_minutes',45)
    where id=r.id and performance_status='live';
    if found then
      v_sets := v_sets + 1;
      update public.tgg_world_open_mic_queue
      set queue_status='left'
      where event_id=r.event_id and user_id=r.user_id and queue_status='performing';
      update public.tgg_world_open_mic_events
      set event_status='open',current_performance_id=null,updated_at=now()
      where id=r.event_id and current_performance_id=r.id;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'expired_waiting_slots',v_waiting,
    'canceled_stale_sets',v_sets,
    'waiting_timeout_minutes',30,
    'performance_timeout_minutes',45,
    'rewards_on_timeout',false
  );
end
$function$


-- [40000000383] function private.tgg_world_open_mic_start_next_impl(p_event_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_open_mic_start_next_impl(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_event public.tgg_world_open_mic_events%rowtype;
  v_next public.tgg_world_open_mic_queue%rowtype;
  v_perf uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  perform private.tgg_world_open_mic_recover_stale();

  select * into v_event
  from public.tgg_world_open_mic_events
  where id=p_event_id
  for update;
  if not found then raise exception 'open mic event not found'; end if;
  if v_event.instance_id is null then raise exception 'instance-scoped open mic required'; end if;

  if not exists(
    select 1
    from public.world_presence wp
    join public.world_characters c on c.id=wp.character_id
    where wp.user_id=v_uid
      and wp.instance_id=v_event.instance_id
      and wp.left_at is null
      and wp.heartbeat_at > now()-interval '2 minutes'
      and c.user_id=v_uid
      and c.current_location_id=v_event.location_id
      and c.character_status='active'
  ) then raise exception 'active same-instance Corner Stage presence required'; end if;

  if v_event.current_performance_id is not null then raise exception 'a performance is already active'; end if;

  select q.* into v_next
  from public.tgg_world_open_mic_queue q
  join public.world_presence wp
    on wp.user_id=q.user_id
   and wp.instance_id=v_event.instance_id
   and wp.left_at is null
   and wp.heartbeat_at > now()-interval '2 minutes'
  where q.event_id=p_event_id and q.queue_status='waiting'
  order by q.queue_position,q.joined_at
  limit 1
  for update of q skip locked;
  if not found then raise exception 'open mic queue has no active performers'; end if;

  insert into public.tgg_world_open_mic_performances(event_id,user_id,character_id)
  values(p_event_id,v_next.user_id,v_next.character_id)
  returning id into v_perf;

  update public.tgg_world_open_mic_queue
  set queue_status='performing'
  where event_id=p_event_id and user_id=v_next.user_id;
  update public.tgg_world_open_mic_events
  set event_status='performing',current_performance_id=v_perf,updated_at=now()
  where id=p_event_id;

  return jsonb_build_object(
    'event_id',p_event_id,
    'instance_id',v_event.instance_id,
    'performance_id',v_perf,
    'performer_user_id',v_next.user_id,
    'virtual_reward_only',true
  );
end
$function$


-- [40000000384] function private.tgg_world_party_invite_artist_impl(p_party_id uuid, p_artist_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_party_invite_artist_impl(p_party_id uuid, p_artist_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_target uuid;
  v_result jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select a.user_id into v_target from public.artists a where a.id=p_artist_id limit 1;
  if v_target is null then raise exception 'ARTIST_NOT_FOUND'; end if;
  if v_target=v_uid then raise exception 'CANNOT_INVITE_SELF'; end if;
  select public.tgg_world_party_invite(p_party_id,v_target) into v_result;
  return coalesce(v_result,'{}'::jsonb) - 'user_id' - 'requester_user_id' - 'recipient_user_id';
end$function$


-- [40000000385] function private.tgg_world_perform_life_action(p_action_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_perform_life_action(p_action_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_action public.tgg_world_life_actions%rowtype;
  v_location text;
  v_last timestamptz;
  v_energy numeric:=0;
  v_k text;
  v_delta numeric;
  v_new numeric;
  v_stats jsonb:='{}'::jsonb;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select * into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char.id is null then raise exception 'active_character_required'; end if;

  select * into v_action
  from public.tgg_world_life_actions
  where action_key=p_action_key and enabled=true;
  if v_action.action_key is null then raise exception 'life_action_unavailable'; end if;

  select l.location_key into v_location
  from public.tgg_world_locations l
  where l.id=v_char.current_location_id;

  if v_location is distinct from v_action.location_key then
    raise exception 'travel to % first',v_action.location_key;
  end if;

  select max(performed_at) into v_last
  from public.tgg_world_character_life_action_log
  where character_id=v_char.id and action_key=p_action_key;

  if v_last is not null
     and v_last+make_interval(mins=>v_action.cooldown_minutes)>now() then
    return jsonb_build_object(
      'ok',false,'reason','cooldown',
      'ready_at',v_last+make_interval(mins=>v_action.cooldown_minutes)
    );
  end if;

  select coalesce(stat_value,0) into v_energy
  from public.world_character_stats
  where character_id=v_char.id and stat_key='energy';

  if v_action.requirements ? 'min_energy'
     and v_energy<coalesce((v_action.requirements->>'min_energy')::numeric,0) then
    return jsonb_build_object(
      'ok',false,'reason','energy_required',
      'energy',v_energy,
      'required',v_action.requirements->>'min_energy'
    );
  end if;

  for v_k in select jsonb_object_keys(v_action.stat_delta)
  loop
    v_delta:=coalesce((v_action.stat_delta->>v_k)::numeric,0);

    insert into public.world_character_stats(character_id,stat_key,stat_value,updated_at)
    values(v_char.id,v_k,greatest(0,least(100,50+v_delta)),now())
    on conflict(character_id,stat_key) do update
    set stat_value=greatest(0,least(100,public.world_character_stats.stat_value+v_delta)),
        updated_at=now();

    select stat_value into v_new
    from public.world_character_stats
    where character_id=v_char.id and stat_key=v_k;

    v_stats:=v_stats||jsonb_build_object(v_k,v_new);
  end loop;

  insert into public.tgg_world_character_life_action_log(
    character_id,action_key,location_key,stat_delta,result_stats,performed_at
  )
  values(v_char.id,v_action.action_key,v_location,v_action.stat_delta,v_stats,now());

  return jsonb_build_object(
    'ok',true,'action_key',v_action.action_key,'location_key',v_location,
    'stat_delta',v_action.stat_delta,'stats',v_stats,
    'cooldown_minutes',v_action.cooldown_minutes
  );
end;
$function$


-- [40000000386] function private.tgg_world_play_tournament(p_entry_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_play_tournament(p_entry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_entry public.tgg_world_tournament_entries%rowtype;
  v_t public.tgg_world_tournaments%rowtype;
  v_char public.world_characters%rowtype;
  v_location text;
  v_rep integer:=0;
  v_career_level integer:=1;
  v_season_level integer:=1;
  v_crew_rank integer:=0;
  v_score integer:=0;
  v_won boolean:=false;
  v_factor numeric:=0.35;
  v_ladder text;
  v_ladder_points integer:=0;
  v_event uuid;
  v_career_xp integer:=0;
  v_season_xp integer:=0;
  v_reward_rep integer:=0;
  v_crew_rep integer:=0;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select e.* into v_entry
  from public.tgg_world_tournament_entries e
  join public.world_characters wc on wc.id=e.character_id
  where e.id=p_entry_id and wc.user_id=v_uid and e.status='registered'
  for update of e;
  if v_entry.id is null then raise exception 'registered tournament entry required'; end if;

  select * into v_char from public.world_characters where id=v_entry.character_id;
  select * into v_t from public.tgg_world_tournaments where tournament_key=v_entry.tournament_key and enabled=true;
  if v_t.tournament_key is null then raise exception 'tournament unavailable'; end if;

  select l.location_key into v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.id=v_entry.character_id;

  if v_location is distinct from v_t.location_key then
    raise exception 'travel to % before competing',v_t.location_key;
  end if;

  select coalesce(max(reputation),0) into v_rep
  from public.tgg_world_career_reputation where character_id=v_entry.character_id;

  select coalesce(max(career_level),1) into v_career_level
  from public.world_character_careers
  where character_id=v_entry.character_id and career_key=v_char.active_career;

  select coalesce(max(season_level),1) into v_season_level
  from public.tgg_world_character_season_progress
  where character_id=v_entry.character_id;

  if v_entry.crew_id is not null then
    select coalesce(rank_level,1) into v_crew_rank
    from public.tgg_world_crew_progression where crew_id=v_entry.crew_id;
  end if;

  v_score:=greatest(0,v_career_level*50 + v_rep + v_season_level*20 + v_crew_rank*10);
  v_won:=v_score>=100;
  v_factor:=case when v_won then 1.0 else 0.35 end;

  select l.ladder_key into v_ladder
  from public.tgg_world_tournament_ladders l
  where l.tournament_type=v_t.tournament_type and l.enabled=true
  order by l.ladder_key limit 1;

  v_ladder_points:=case when v_ladder is null then 0 when v_won then 120 else 40 end;
  v_career_xp:=floor(coalesce((v_t.rewards->>'career_xp')::numeric,0)*v_factor)::integer;
  v_season_xp:=floor(coalesce((v_t.rewards->>'season_xp')::numeric,0)*v_factor)::integer;
  v_reward_rep:=floor(coalesce((v_t.rewards->>'reputation')::numeric,0)*v_factor)::integer;
  v_crew_rep:=floor(coalesce((v_t.rewards->>'crew_reputation')::numeric,0)*v_factor)::integer;

  v_event:=private.tgg_apply_progression_event(
    v_entry.character_id,'tournament_completed',v_t.tournament_key,
    jsonb_strip_nulls(jsonb_build_object(
      'career_xp',v_career_xp,
      'season_xp',v_season_xp,
      'reputation',v_reward_rep,
      'ladder_key',v_ladder,
      'ladder_points',v_ladder_points,
      'won',v_won
    ))
  );

  if v_entry.crew_id is not null and v_crew_rep>0
     and exists(select 1 from public.tgg_world_crew_members
       where crew_id=v_entry.crew_id and character_id=v_entry.character_id and left_at is null) then
    insert into public.tgg_world_crew_progression(crew_id,crew_xp,rank_level,reputation,unlocks,updated_at)
    values(v_entry.crew_id,0,1,v_crew_rep,'{}'::jsonb,now())
    on conflict(crew_id) do update
      set reputation=public.tgg_world_crew_progression.reputation+v_crew_rep,updated_at=now();
  end if;

  update public.tgg_world_tournament_entries
  set status='completed',
      score=v_score,
      placement=case when v_won then 1 else 2 end,
      result=jsonb_build_object(
        'won',v_won,'score',v_score,'reward_factor',v_factor,
        'ladder_key',v_ladder,'ladder_points',v_ladder_points
      ),
      updated_at=now()
  where id=v_entry.id;

  perform private.tgg_recompute_progression(v_entry.character_id);

  return jsonb_build_object(
    'entry_id',v_entry.id,'tournament_key',v_t.tournament_key,
    'score',v_score,'won',v_won,'placement',case when v_won then 1 else 2 end,
    'career_xp',v_career_xp,'season_xp',v_season_xp,'reputation',v_reward_rep,
    'crew_reputation',v_crew_rep,'ladder_key',v_ladder,'ladder_points',v_ladder_points,
    'progression_event_id',v_event
  );
end;
$function$


-- [40000000387] function private.tgg_world_prestige_roadmap_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_prestige_roadmap_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_rep integer:=0;
  v_properties integer:=0;
  v_businesses integer:=0;
  v_achievements integer:=0;
  v_current_level integer:=0;
  v_lifetime_xp integer:=0;
  v_permanent jsonb:='{}'::jsonb;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  select coalesce(sum(reputation),0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char;

  select count(*) into v_properties
  from public.tgg_world_character_properties
  where character_id=v_char and ownership_status='owned';

  select count(*) into v_businesses
  from public.tgg_world_character_businesses
  where character_id=v_char and status='active';

  select count(*) into v_achievements
  from public.tgg_world_character_achievements
  where character_id=v_char and unlocked_at is not null;

  select
    coalesce(prestige_level,0),
    coalesce(lifetime_prestige_xp,0),
    coalesce(permanent_unlocks,'{}'::jsonb)
  into v_current_level,v_lifetime_xp,v_permanent
  from public.tgg_world_character_prestige
  where character_id=v_char;

  return jsonb_build_object(
    'character_id',v_char,
    'current',jsonb_build_object(
      'prestige_level',v_current_level,
      'lifetime_prestige_xp',v_lifetime_xp,
      'permanent_unlocks',v_permanent
    ),
    'summary',jsonb_build_object(
      'reputation',v_rep,
      'properties',v_properties,
      'businesses',v_businesses,
      'achievements',v_achievements
    ),
    'levels',coalesce((
      select jsonb_agg(jsonb_build_object(
        'prestige_level',p.prestige_level,
        'title',p.title,
        'requirements',p.requirements,
        'permanent_unlocks',p.permanent_unlocks,
        'reset_scope',p.reset_scope,
        'reached',v_current_level>=p.prestige_level,
        'requirements_ready',
          v_rep>=coalesce((p.requirements->>'reputation')::integer,0)
          and v_properties>=coalesce((p.requirements->>'properties')::integer,0)
          and v_businesses>=coalesce((p.requirements->>'businesses')::integer,0)
          and v_achievements>=coalesce((p.requirements->>'achievements')::integer,0),
        'remaining',jsonb_strip_nulls(jsonb_build_object(
          'reputation',case
            when p.requirements ? 'reputation'
            then greatest((p.requirements->>'reputation')::integer-v_rep,0)
            else null end,
          'properties',case
            when p.requirements ? 'properties'
            then greatest((p.requirements->>'properties')::integer-v_properties,0)
            else null end,
          'businesses',case
            when p.requirements ? 'businesses'
            then greatest((p.requirements->>'businesses')::integer-v_businesses,0)
            else null end,
          'achievements',case
            when p.requirements ? 'achievements'
            then greatest((p.requirements->>'achievements')::integer-v_achievements,0)
            else null end
        ))
      ) order by p.prestige_level)
      from public.tgg_world_prestige_levels p
      where p.enabled=true
    ),'[]'::jsonb),
    'next_level',(
      select jsonb_build_object(
        'prestige_level',p.prestige_level,
        'title',p.title,
        'requirements',p.requirements,
        'permanent_unlocks',p.permanent_unlocks
      )
      from public.tgg_world_prestige_levels p
      where p.enabled=true and p.prestige_level>v_current_level
      order by p.prestige_level
      limit 1
    )
  );
end;
$function$


-- [40000000388] function private.tgg_world_progression_ops_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_progression_ops_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_season public.tgg_world_seasons%rowtype;
  v_progress public.tgg_world_character_season_progress%rowtype;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  select * into v_season
  from public.tgg_world_seasons
  where enabled=true
    and (starts_at is null or starts_at<=now())
    and (ends_at is null or ends_at>=now())
  order by starts_at desc nulls last
  limit 1;

  if v_season.season_key is not null then
    insert into public.tgg_world_character_season_progress(
      character_id,season_key,season_level,season_xp,unlocked_rewards,updated_at
    )
    values(v_char,v_season.season_key,1,0,'[]'::jsonb,now())
    on conflict(character_id,season_key) do nothing;

    select * into v_progress
    from public.tgg_world_character_season_progress
    where character_id=v_char and season_key=v_season.season_key;
  end if;

  return jsonb_build_object(
    'season',case when v_season.season_key is null then '{}'::jsonb else jsonb_build_object(
      'season_key',v_season.season_key,
      'title',v_season.title,
      'theme',v_season.theme,
      'starts_at',v_season.starts_at,
      'ends_at',v_season.ends_at,
      'modifiers',v_season.modifiers,
      'level',coalesce(v_progress.season_level,1),
      'xp',coalesce(v_progress.season_xp,0),
      'claimed_rewards',coalesce(v_progress.unlocked_rewards,'[]'::jsonb),
      'rewards',coalesce((
        select jsonb_agg(jsonb_build_object(
          'reward_level',r.reward_level,
          'required_xp',r.required_xp,
          'reward',r.reward,
          'claimed',coalesce(v_progress.unlocked_rewards,'[]'::jsonb) @> jsonb_build_array(r.reward_level),
          'eligible',coalesce(v_progress.season_xp,0)>=r.required_xp
        ) order by r.reward_level)
        from public.tgg_world_season_rewards r
        where r.season_key=v_season.season_key
      ),'[]'::jsonb)
    ) end,
    'achievements',coalesce((
      select jsonb_agg(jsonb_build_object(
        'achievement_key',a.achievement_key,
        'title',a.title,
        'description',a.description,
        'category',a.category,
        'conditions',a.conditions,
        'rewards',a.rewards,
        'unlocked',ca.unlocked_at is not null,
        'unlocked_at',ca.unlocked_at,
        'progress',coalesce(ca.progress,'{}'::jsonb)
      ) order by (ca.unlocked_at is not null) desc,a.category,a.title)
      from public.tgg_world_achievements a
      left join public.tgg_world_character_achievements ca
        on ca.achievement_key=a.achievement_key and ca.character_id=v_char
      where a.enabled=true
    ),'[]'::jsonb),
    'runtime',jsonb_build_object(
      'latest_snapshot',coalesce((
        select jsonb_build_object(
          'snapshot_key',r.snapshot_key,
          'status',r.status,
          'detail',r.detail,
          'created_at',r.created_at
        )
        from public.tgg_world_runtime_snapshots r
        order by r.created_at desc
        limit 1
      ),'{}'::jsonb),
      'workers',coalesce((
        select jsonb_agg(jsonb_build_object(
          'worker_key',w.worker_key,
          'worker_group',w.worker_group,
          'last_run_at',w.last_run_at,
          'last_status',w.last_status,
          'run_count',w.run_count,
          'error_count',w.error_count,
          'updated_at',w.updated_at
        ) order by w.worker_group,w.worker_key)
        from public.tgg_world_worker_health w
      ),'[]'::jsonb),
      'economy_metrics',coalesce((
        select jsonb_agg(jsonb_build_object(
          'metric_key',m.metric_key,
          'metric_value',m.metric_value,
          'target_min',m.target_min,
          'target_max',m.target_max,
          'status',m.status,
          'metadata',m.metadata,
          'updated_at',m.updated_at
        ) order by m.metric_key)
        from public.tgg_world_economy_metrics m
      ),'[]'::jsonb),
      'balance_recommendations',coalesce((
        select jsonb_agg(jsonb_build_object(
          'balance_key',b.balance_key,
          'metric_key',b.metric_key,
          'metric_value',b.metric_value,
          'recommendation',b.recommendation,
          'status',b.status,
          'generated_at',b.generated_at,
          'updated_at',b.updated_at
        ) order by b.generated_at desc)
        from public.tgg_world_balance_recommendations b
        where b.status='open'
        limit 25
      ),'[]'::jsonb),
      'read_only',true,
      'auto_apply_balance',false
    )
  );
end;
$function$


-- [40000000389] function private.tgg_world_property_effects(p_character_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_property_effects(p_character_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
  with installed as (
    select u.effects
    from public.tgg_world_character_properties p
    join public.tgg_world_character_property_upgrades cu on cu.property_id=p.id
    join public.tgg_world_property_upgrades u on u.upgrade_key=cu.upgrade_key and u.enabled=true
    where p.character_id=p_character_id
      and p.ownership_status='owned'
  ),
  kv as (
    select e.key,
           sum(case
             when jsonb_typeof(e.value)='number' then (e.value#>>'{}')::numeric
             else 0
           end) numeric_value
    from installed i
    cross join lateral jsonb_each(i.effects) e
    group by e.key
  )
  select coalesce(jsonb_object_agg(key,to_jsonb(numeric_value)),'{}'::jsonb)
  from kv;
$function$


-- [40000000390] function private.tgg_world_property_market_buy(p_listing_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_property_market_buy(p_listing_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_buyer uuid;
  v_listing public.tgg_world_property_listings%rowtype;
  v_prop public.tgg_world_character_properties%rowtype;
  v_cat public.tgg_world_property_catalog%rowtype;
  v_seller_user uuid;
  v_buyer_balance bigint;
  v_seller_balance bigint;
  v_rep integer:=0;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_buyer from public.world_characters
  where user_id=v_uid and character_status='active' limit 1;
  if v_buyer is null then raise exception 'active_character_required'; end if;

  perform private.tgg_world_wallet_ensure_impl();

  select * into v_listing
  from public.tgg_world_property_listings
  where id=p_listing_id and status='active'
  for update;
  if v_listing.id is null then raise exception 'listing_unavailable'; end if;

  if v_listing.expires_at is not null and v_listing.expires_at<=now() then
    update public.tgg_world_property_listings
    set status='expired',metadata=metadata||jsonb_build_object('expired_at',now())
    where id=v_listing.id;

    update public.tgg_world_character_properties
    set ownership_status='owned',updated_at=now()
    where id=v_listing.property_id and character_id=v_listing.seller_character_id;

    return jsonb_build_object('ok',false,'reason','listing_expired');
  end if;

  if v_listing.seller_character_id=v_buyer then raise exception 'cannot_buy_own_listing'; end if;

  select * into v_prop
  from public.tgg_world_character_properties
  where id=v_listing.property_id
    and character_id=v_listing.seller_character_id
    and ownership_status='listed'
  for update;
  if v_prop.id is null then raise exception 'listed_property_state_invalid'; end if;

  select * into v_cat
  from public.tgg_world_property_catalog
  where property_key=v_prop.property_key and enabled=true;

  if exists(
    select 1 from public.tgg_world_character_properties
    where character_id=v_buyer and property_key=v_prop.property_key
  ) then raise exception 'buyer_already_owns_property_type'; end if;

  select coalesce(max(reputation),0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_buyer;

  if v_rep<v_cat.required_reputation then
    return jsonb_build_object(
      'ok',false,'reason','reputation_required',
      'required',v_cat.required_reputation,'reputation',v_rep
    );
  end if;

  select user_id into v_seller_user
  from public.world_characters
  where id=v_listing.seller_character_id;

  insert into public.tgg_world_wallets(user_id,character_id,balance,currency_key,created_at,updated_at)
  values(v_seller_user,v_listing.seller_character_id,0,'tgg_credits',now(),now())
  on conflict(user_id) do nothing;

  select balance into v_buyer_balance
  from public.tgg_world_wallets
  where user_id=v_uid
  for update;

  select balance into v_seller_balance
  from public.tgg_world_wallets
  where user_id=v_seller_user
  for update;

  if coalesce(v_buyer_balance,0)<v_listing.asking_credits then
    return jsonb_build_object(
      'ok',false,'reason','insufficient_tgg_credits',
      'balance',coalesce(v_buyer_balance,0),'asking_credits',v_listing.asking_credits
    );
  end if;

  update public.tgg_world_wallets
  set balance=balance-v_listing.asking_credits,updated_at=now()
  where user_id=v_uid
  returning balance into v_buyer_balance;

  update public.tgg_world_wallets
  set balance=balance+v_listing.asking_credits,updated_at=now()
  where user_id=v_seller_user
  returning balance into v_seller_balance;

  insert into public.tgg_world_wallet_ledger(
    user_id,character_id,entry_type,amount,balance_after,reference_type,reference_key,metadata,created_at
  )
  values(
    v_uid,v_buyer,'purchase_debit',-v_listing.asking_credits,v_buyer_balance,
    'property_market',v_listing.id::text,
    jsonb_build_object('role','buyer','property_key',v_prop.property_key),now()
  );

  insert into public.tgg_world_wallet_ledger(
    user_id,character_id,entry_type,amount,balance_after,reference_type,reference_key,metadata,created_at
  )
  values(
    v_seller_user,v_listing.seller_character_id,'adjustment',v_listing.asking_credits,v_seller_balance,
    'property_market',v_listing.id::text,
    jsonb_build_object('role','seller','property_key',v_prop.property_key),now()
  );

  update public.tgg_world_character_properties
  set character_id=v_buyer,
      ownership_status='owned',
      acquired_at=now(),
      updated_at=now()
  where id=v_prop.id;

  update public.tgg_world_property_listings
  set status='sold',
      metadata=metadata||jsonb_build_object(
        'sold_at',now(),
        'buyer_character_id',v_buyer,
        'seller_character_id',v_listing.seller_character_id,
        'settled_credits',v_listing.asking_credits
      )
  where id=v_listing.id;

  perform private.tgg_recompute_progression(v_buyer);

  return jsonb_build_object(
    'ok',true,'listing_id',v_listing.id,'property_id',v_prop.id,
    'property_key',v_prop.property_key,'settled_credits',v_listing.asking_credits,
    'buyer_balance',v_buyer_balance,'seller_balance',v_seller_balance,
    'real_money',false
  );
end;
$function$


-- [40000000391] function private.tgg_world_property_market_cancel(p_listing_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_property_market_cancel(p_listing_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_listing public.tgg_world_property_listings%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char from public.world_characters
  where user_id=v_uid and character_status='active' limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_listing
  from public.tgg_world_property_listings
  where id=p_listing_id and seller_character_id=v_char and status='active'
  for update;
  if v_listing.id is null then raise exception 'active_owned_listing_required'; end if;

  update public.tgg_world_property_listings
  set status='canceled',
      metadata=metadata||jsonb_build_object('canceled_at',now())
  where id=v_listing.id;

  update public.tgg_world_character_properties
  set ownership_status='owned',updated_at=now()
  where id=v_listing.property_id and character_id=v_char;

  return jsonb_build_object('ok',true,'listing_id',v_listing.id,'status','canceled');
end;
$function$


-- [40000000392] function private.tgg_world_property_market_expire()
CREATE OR REPLACE FUNCTION private.tgg_world_property_market_expire()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_count integer:=0;
begin
  with expired as (
    update public.tgg_world_property_listings
    set status='expired',
        metadata=metadata||jsonb_build_object('expired_at',now())
    where status='active' and expires_at is not null and expires_at<=now()
    returning property_id
  ),
  restored as (
    update public.tgg_world_character_properties p
    set ownership_status='owned',updated_at=now()
    where p.id in (select property_id from expired)
      and p.ownership_status='listed'
    returning p.id
  )
  select count(*) into v_count from restored;

  return v_count;
end;
$function$


-- [40000000393] function private.tgg_world_property_market_list(p_property_id uuid, p_asking_credits integer)
CREATE OR REPLACE FUNCTION private.tgg_world_property_market_list(p_property_id uuid, p_asking_credits integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_prop public.tgg_world_character_properties%rowtype;
  v_cat public.tgg_world_property_catalog%rowtype;
  v_id uuid;
  v_price_multiplier numeric:=1;
  v_adjusted_base integer:=0;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if p_asking_credits is null or p_asking_credits<1 then raise exception 'asking_price_invalid'; end if;

  perform private.tgg_world_property_market_expire();

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_prop
  from public.tgg_world_character_properties
  where id=p_property_id and character_id=v_char and ownership_status='owned'
  for update;
  if v_prop.id is null then raise exception 'owned_property_required'; end if;

  select * into v_cat
  from public.tgg_world_property_catalog
  where property_key=v_prop.property_key and enabled=true;
  if v_cat.property_key is null then raise exception 'property_catalog_unavailable'; end if;

  select greatest(coalesce((value->>'value')::numeric,1),0)
  into v_price_multiplier
  from public.tgg_world_economy_config
  where config_key='property_price_multiplier';
  v_price_multiplier:=coalesce(v_price_multiplier,1);
  v_adjusted_base:=greatest(round(v_cat.base_price_credits*v_price_multiplier)::integer,0);

  if exists(
    select 1 from public.tgg_world_character_businesses b
    where b.property_id=v_prop.id and b.status='active'
  ) then
    raise exception 'active_business_blocks_sale';
  end if;

  if p_asking_credits < greatest(1,(v_adjusted_base/2))
     or p_asking_credits > v_adjusted_base*2 then
    return jsonb_build_object(
      'ok',false,'reason','asking_price_out_of_range',
      'minimum',greatest(1,v_adjusted_base/2),
      'maximum',v_adjusted_base*2,
      'base_price',v_adjusted_base,
      'catalog_base_price',v_cat.base_price_credits,
      'price_multiplier',v_price_multiplier
    );
  end if;

  if exists(
    select 1 from public.tgg_world_property_listings
    where property_id=v_prop.id and status='active'
  ) then
    raise exception 'property_already_listed';
  end if;

  update public.tgg_world_character_properties
  set ownership_status='listed',updated_at=now()
  where id=v_prop.id;

  insert into public.tgg_world_property_listings(
    property_id,seller_character_id,asking_credits,status,listed_at,expires_at,metadata
  )
  values(
    v_prop.id,v_char,p_asking_credits,'active',now(),now()+interval '7 days',
    jsonb_build_object('base_price',v_adjusted_base,'catalog_base_price',v_cat.base_price_credits,'price_multiplier',v_price_multiplier,'property_key',v_prop.property_key)
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'listing_id',v_id,'property_id',v_prop.id,
    'asking_credits',p_asking_credits,'base_price',v_adjusted_base,'price_multiplier',v_price_multiplier,'expires_at',now()+interval '7 days'
  );
end;
$function$


-- [40000000394] function private.tgg_world_property_market_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_property_market_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_balance bigint:=0;
  v_price_multiplier numeric:=1;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  perform private.tgg_world_property_market_expire();

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then return '{}'::jsonb; end if;

  perform private.tgg_world_wallet_ensure_impl();
  select balance into v_balance from public.tgg_world_wallets where user_id=v_uid;

  select greatest(coalesce((value->>'value')::numeric,1),0)
  into v_price_multiplier
  from public.tgg_world_economy_config
  where config_key='property_price_multiplier';
  v_price_multiplier:=coalesce(v_price_multiplier,1);

  return jsonb_build_object(
    'character_id',v_char,
    'wallet_balance',coalesce(v_balance,0),
    'property_price_multiplier',v_price_multiplier,
    'owned_properties',coalesce((
      select jsonb_agg(jsonb_build_object(
        'property_id',p.id,
        'property_key',p.property_key,
        'display_name',c.display_name,
        'property_type',c.property_type,
        'district_key',c.district_key,
        'catalog_base_price',c.base_price_credits,
        'base_price',round(c.base_price_credits*v_price_multiplier)::integer,
        'ownership_status',p.ownership_status,
        'active_businesses',(
          select count(*) from public.tgg_world_character_businesses b
          where b.property_id=p.id and b.status='active'
        ),
        'active_listing',(
          select jsonb_build_object(
            'id',l.id,'asking_credits',l.asking_credits,
            'listed_at',l.listed_at,'expires_at',l.expires_at
          )
          from public.tgg_world_property_listings l
          where l.property_id=p.id and l.status='active'
          order by l.listed_at desc limit 1
        ),
        'can_list',p.ownership_status='owned'
          and not exists(
            select 1 from public.tgg_world_character_businesses b
            where b.property_id=p.id and b.status='active'
          )
      ) order by p.acquired_at)
      from public.tgg_world_character_properties p
      join public.tgg_world_property_catalog c on c.property_key=p.property_key
      where p.character_id=v_char and p.ownership_status in ('owned','listed')
    ),'[]'::jsonb),
    'listings',coalesce((
      select jsonb_agg(jsonb_build_object(
        'listing_id',l.id,
        'property_id',l.property_id,
        'property_key',p.property_key,
        'display_name',c.display_name,
        'property_type',c.property_type,
        'district_key',c.district_key,
        'catalog_base_price',c.base_price_credits,
        'base_price',round(c.base_price_credits*v_price_multiplier)::integer,
        'asking_credits',l.asking_credits,
        'seller_character_id',l.seller_character_id,
        'seller_stage_name',coalesce(wc.stage_name,'Creator'),
        'is_mine',l.seller_character_id=v_char,
        'listed_at',l.listed_at,
        'expires_at',l.expires_at,
        'can_afford',coalesce(v_balance,0)>=l.asking_credits,
        'buyer_already_owns',exists(
          select 1 from public.tgg_world_character_properties bp
          where bp.character_id=v_char and bp.property_key=p.property_key
        )
      ) order by l.asking_credits,l.listed_at desc)
      from public.tgg_world_property_listings l
      join public.tgg_world_character_properties p on p.id=l.property_id
      join public.tgg_world_property_catalog c on c.property_key=p.property_key
      join public.world_characters wc on wc.id=l.seller_character_id
      where l.status='active' and (l.expires_at is null or l.expires_at>now())
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000395] function private.tgg_world_property_upgrades_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_property_upgrades_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_rep integer:=0;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  select coalesce(max(reputation),0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char;

  return jsonb_build_object(
    'character_id',v_char,
    'reputation',v_rep,
    'properties',coalesce((
      select jsonb_agg(jsonb_build_object(
        'property_id',p.id,
        'property_key',p.property_key,
        'display_name',c.display_name,
        'property_type',c.property_type,
        'district_key',c.district_key,
        'ownership_status',p.ownership_status,
        'upgrades',coalesce((
          select jsonb_agg(jsonb_build_object(
            'upgrade_key',u.upgrade_key,
            'display_name',u.display_name,
            'upgrade_level',u.upgrade_level,
            'required_reputation',u.required_reputation,
            'effects',u.effects,
            'reputation_ready',v_rep>=u.required_reputation,
            'installed',case when cu.upgrade_key is null then null else jsonb_build_object(
              'installed_level',cu.installed_level,
              'installed_at',cu.installed_at,
              'metadata',cu.metadata
            ) end
          ) order by u.upgrade_level,u.display_name)
          from public.tgg_world_property_upgrades u
          left join public.tgg_world_character_property_upgrades cu
            on cu.property_id=p.id and cu.upgrade_key=u.upgrade_key
          where u.enabled=true and c.property_type=any(u.property_types)
        ),'[]'::jsonb)
      ) order by p.acquired_at)
      from public.tgg_world_character_properties p
      join public.tgg_world_property_catalog c on c.property_key=p.property_key
      where p.character_id=v_char and p.ownership_status='owned'
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000396] function private.tgg_world_purchase_impl(p_item_key text, p_quantity integer, p_idempotency_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_purchase_impl(p_item_key text, p_quantity integer DEFAULT 1, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_char public.world_characters%rowtype;
  v_wallet public.tgg_world_wallets%rowtype;
  v_item public.tgg_world_shop_catalog%rowtype;
  v_existing public.tgg_world_purchase_requests%rowtype;
  v_key text := trim(coalesce(p_idempotency_key,''));
  v_qty integer := coalesce(p_quantity,1);
  v_cost bigint;
  v_result jsonb;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if v_qty < 1 or v_qty > 20 then raise exception 'invalid_quantity'; end if;
  if length(v_key) < 8 or length(v_key) > 120 then raise exception 'idempotency_key_required'; end if;

  select * into v_char from public.world_characters
  where user_id=v_uid and character_status='active' limit 1;
  if not found then raise exception 'active_character_required'; end if;

  select * into v_existing from public.tgg_world_purchase_requests
  where user_id=v_uid and idempotency_key=v_key;
  if found then
    if v_existing.item_key<>p_item_key or v_existing.quantity<>v_qty then
      raise exception 'idempotency_key_reuse_mismatch';
    end if;
    return v_existing.result || jsonb_build_object('replayed',true);
  end if;

  select * into v_item from public.tgg_world_shop_catalog
  where item_key=p_item_key and enabled=true;
  if not found then raise exception 'item_not_found'; end if;

  perform private.tgg_world_wallet_ensure_impl();

  select * into v_wallet from public.tgg_world_wallets
  where user_id=v_uid
  for update;

  v_cost := v_item.price * v_qty;
  if v_wallet.balance < v_cost then
    v_result := jsonb_build_object(
      'ok',false,'reason','insufficient_virtual_credits',
      'balance',v_wallet.balance,'total_cost',v_cost,
      'currency','tgg_credits','virtual_currency',true,'real_money',false
    );
    insert into public.tgg_world_purchase_requests(
      user_id,character_id,idempotency_key,item_key,quantity,total_cost,status,result
    )
    values(v_uid,v_char.id,v_key,p_item_key,v_qty,v_cost,'rejected',v_result);
    return v_result;
  end if;

  update public.tgg_world_wallets
  set balance=balance-v_cost,updated_at=now()
  where user_id=v_uid
  returning * into v_wallet;

  insert into public.tgg_world_wallet_ledger(
    user_id,character_id,entry_type,amount,balance_after,reference_type,reference_key,metadata
  )
  values(
    v_uid,v_char.id,'purchase_debit',-v_cost,v_wallet.balance,'purchase',v_key,
    jsonb_build_object('item_key',p_item_key,'quantity',v_qty,'unit_price',v_item.price,'virtual_currency',true,'real_money',false)
  );

  insert into public.tgg_world_inventory(user_id,character_id,item_key,quantity,equipped)
  values(v_uid,v_char.id,p_item_key,v_qty,false)
  on conflict(user_id,item_key) do update
  set quantity=public.tgg_world_inventory.quantity+excluded.quantity,
      updated_at=now();

  v_result := jsonb_build_object(
    'ok',true,'item_key',p_item_key,'quantity',v_qty,
    'total_cost',v_cost,'balance',v_wallet.balance,
    'currency','tgg_credits','virtual_currency',true,'real_money',false
  );

  insert into public.tgg_world_purchase_requests(
    user_id,character_id,idempotency_key,item_key,quantity,total_cost,status,result
  )
  values(v_uid,v_char.id,v_key,p_item_key,v_qty,v_cost,'completed',v_result);

  perform private.tgg_recompute_progression(v_char.id);

  return v_result || jsonb_build_object('replayed',false);
exception
  when unique_violation then
    select * into v_existing from public.tgg_world_purchase_requests
    where user_id=v_uid and idempotency_key=v_key;
    if found then return v_existing.result || jsonb_build_object('replayed',true); end if;
    raise;
end
$function$


-- [40000000397] function private.tgg_world_refresh_achievements()
CREATE OR REPLACE FUNCTION private.tgg_world_refresh_achievements()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;
  return private.tgg_recompute_progression(v_char);
end;
$function$


-- [40000000398] function private.tgg_world_relationship_consequences_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_relationship_consequences_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_career text;
  v_rep integer:=0;
  v_max_trust integer:=0;
  v_crew uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id,active_career into v_char,v_career
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  select coalesce(reputation,0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=v_char and career_key=v_career;

  select coalesce(max(trust_score),0) into v_max_trust
  from public.tgg_world_contact_relationships
  where character_id=v_char;

  select crew_id into v_crew
  from public.tgg_world_crew_members
  where character_id=v_char and user_id=v_uid and left_at is null
  order by joined_at desc limit 1;

  return jsonb_build_object(
    'character_id',v_char,
    'career_reputation',v_rep,
    'max_contact_trust',v_max_trust,
    'npc_reaction',coalesce((
      select jsonb_build_object(
        'reaction_key',r.reaction_key,
        'reaction_type',r.reaction_type,
        'dialogue_style',r.dialogue_style,
        'behavior_modifier',r.behavior_modifier,
        'min_reputation',r.min_reputation,
        'max_reputation',r.max_reputation,
        'contact_trust_min',r.contact_trust_min
      )
      from public.tgg_world_npc_player_reactions r
      where r.enabled=true
        and v_rep>=r.min_reputation
        and (r.max_reputation is null or v_rep<=r.max_reputation)
        and v_max_trust>=r.contact_trust_min
      order by r.min_reputation desc,r.contact_trust_min desc
      limit 1
    ),jsonb_build_object(
      'reaction_type','neutral','dialogue_style','brief-neutral',
      'behavior_modifier',jsonb_build_object('offer_weight',0.7)
    )),
    'npc_standing',coalesce((
      select jsonb_agg(jsonb_build_object(
        'npc_key',s.npc_key,
        'display_name',coalesce(n.display_name,s.npc_key),
        'standing',s.standing,
        'loyalty',s.loyalty,
        'rivalry',s.rivalry,
        'favored_opportunities',s.favored_opportunities,
        'blocked_opportunities',s.blocked_opportunities,
        'memory',s.memory,
        'updated_at',s.updated_at
      ) order by s.standing desc,s.loyalty desc,s.rivalry desc)
      from public.tgg_world_character_npc_standing s
      left join public.tgg_world_npc_profiles n on n.npc_key=s.npc_key
      where s.character_id=v_char
    ),'[]'::jsonb),
    'applied_consequences',coalesce((
      select jsonb_agg(jsonb_build_object(
        'rule_key',a.rule_key,
        'source_type',a.source_type,
        'source_id',a.source_id,
        'applied_effects',a.applied_effects,
        'applied_at',a.applied_at
      ) order by a.applied_at desc)
      from (
        select * from public.tgg_world_consequence_applications
        where character_id=v_char
        order by applied_at desc
        limit 30
      ) a
    ),'[]'::jsonb),
    'contacts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'contact_key',c.contact_key,
        'display_name',coalesce(i.display_name,c.contact_key),
        'role_title',i.role_title,
        'organization',i.organization,
        'relationship_xp',c.relationship_xp,
        'relationship_level',c.relationship_level,
        'trust_score',c.trust_score,
        'meetings_completed',c.meetings_completed,
        'successful_contracts',c.successful_contracts,
        'last_interaction_at',c.last_interaction_at,
        'memory',c.memory
      ) order by c.trust_score desc,c.relationship_xp desc)
      from public.tgg_world_contact_relationships c
      left join public.tgg_world_industry_contacts i on i.contact_key=c.contact_key
      where c.character_id=v_char
    ),'[]'::jsonb),
    'relationship_events',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',e.id,
        'contact_key',e.contact_key,
        'event_type',e.event_type,
        'delta_xp',e.delta_xp,
        'delta_trust',e.delta_trust,
        'source_type',e.source_type,
        'source_key',e.source_key,
        'memory_patch',e.memory_patch,
        'created_at',e.created_at
      ) order by e.created_at desc)
      from (
        select * from public.tgg_world_relationship_events
        where character_id=v_char
        order by created_at desc
        limit 40
      ) e
    ),'[]'::jsonb),
    'crew_relations',case when v_crew is null then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
        'other_crew_id',case when r.crew_a_id=v_crew then r.crew_b_id else r.crew_a_id end,
        'other_crew_name',coalesce(c.crew_name,'Unknown Crew'),
        'relation_type',r.relation_type,
        'affinity',r.affinity,
        'rivalry',r.rivalry,
        'shared_reputation',r.shared_reputation,
        'metadata',r.metadata,
        'updated_at',r.updated_at
      ) order by r.rivalry desc,r.affinity desc)
      from public.tgg_world_crew_relations r
      left join public.tgg_world_crews c
        on c.id=case when r.crew_a_id=v_crew then r.crew_b_id else r.crew_a_id end
      where v_crew=any(array[r.crew_a_id,r.crew_b_id])
    ),'[]'::jsonb) end
  );
end;
$function$


-- [40000000399] function private.tgg_world_relationship_opportunity_weight(p_character_id uuid, p_opportunity_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_relationship_opportunity_weight(p_character_id uuid, p_opportunity_key text)
 RETURNS numeric
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
  with base as (
    select
      coalesce(sum(case when s.favored_opportunities ? p_opportunity_key then 0.10 else 0 end),0)
      -
      coalesce(sum(case when s.blocked_opportunities ? p_opportunity_key then 0.10 else 0 end),0)
      as weight
    from public.tgg_world_character_npc_standing s
    where s.character_id=p_character_id
  ),
  mods as (
    select coalesce(sum(
      case
        when m.modifier_key='favored_opportunity_weight' then m.numeric_value
        when m.modifier_key='blocked_opportunity_weight' then -m.numeric_value
        else 0
      end
    ),0) as weight
    from public.tgg_world_character_modifiers m
    where m.character_id=p_character_id
      and m.modifier_key in ('favored_opportunity_weight','blocked_opportunity_weight')
      and (m.expires_at is null or m.expires_at>now())
      and (
        coalesce(jsonb_array_length(m.metadata->'target_keys'),0)=0
        or (m.metadata->'target_keys') ? p_opportunity_key
      )
  )
  select least(1::numeric,greatest(-1::numeric,base.weight+mods.weight))
  from base cross join mods;
$function$


-- [40000000400] function private.tgg_world_runtime_snapshot()
CREATE OR REPLACE FUNCTION private.tgg_world_runtime_snapshot()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_id uuid; v_detail jsonb; v_status text;
begin
  v_status := case when exists(select 1 from public.tgg_world_worker_health where last_status='error') then 'error'
                   when exists(select 1 from public.tgg_world_worker_health where last_status='warn') then 'warn'
                   else 'ok' end;
  v_detail := jsonb_build_object(
    'characters',(select count(*) from public.world_characters where character_status='active'),
    'active_dynamic_events',(select count(*) from public.tgg_world_dynamic_events where status='active'),
    'scheduled_dynamic_events',(select count(*) from public.tgg_world_dynamic_events where status='scheduled'),
    'available_gigs',(select count(*) from public.tgg_world_character_gigs where status='available'),
    'queued_stories',(select count(*) from public.tgg_world_story_generation_queue where status='queued'),
    'open_balance_recommendations',(select count(*) from public.tgg_world_balance_recommendations where status='open'),
    'worker_errors',(select count(*) from public.tgg_world_worker_health where last_status='error')
  );
  insert into public.tgg_world_runtime_snapshots(snapshot_key,status,detail)
  values('tgg-world-runtime',v_status,v_detail)
  returning id into v_id;
  perform private.tgg_worker_mark('runtime-snapshot','ok',v_detail);
  return v_id;
end;
$function$


-- [40000000401] function private.tgg_world_runtime_ui_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_runtime_ui_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  return jsonb_build_object(
    'latest',coalesce((
      select jsonb_build_object('status',r.status,'detail',r.detail,'created_at',r.created_at)
      from public.tgg_world_runtime_snapshots r
      where r.snapshot_key='tgg-world-runtime'
      order by r.created_at desc limit 1
    ),'{}'::jsonb),
    'workers',coalesce((
      select jsonb_agg(jsonb_build_object(
        'worker_key',w.worker_key,'group',w.worker_group,'last_run_at',w.last_run_at,
        'last_status',w.last_status,'last_detail',w.last_detail,'run_count',w.run_count,'error_count',w.error_count
      ) order by w.worker_key)
      from public.tgg_world_worker_health w
    ),'[]'::jsonb),
    'balance_recommendations',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',b.id,'balance_key',b.balance_key,'metric_key',b.metric_key,
        'metric_value',b.metric_value,'recommendation',b.recommendation,'status',b.status,'generated_at',b.generated_at
      ) order by b.generated_at desc)
      from public.tgg_world_balance_recommendations b
      where b.status='open'
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000402] function private.tgg_world_set_showcase(p_title_key text, p_badge_key text, p_collectible_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_set_showcase(p_title_key text DEFAULT NULL::text, p_badge_key text DEFAULT NULL::text, p_collectible_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_uid uuid:=auth.uid(); v_char uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select id into v_char from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  if p_title_key is not null and not exists(select 1 from public.tgg_world_character_titles where character_id=v_char and title_key=p_title_key) then raise exception 'title_not_unlocked'; end if;
  if p_badge_key is not null and not exists(select 1 from public.tgg_world_character_badges where character_id=v_char and badge_key=p_badge_key) then raise exception 'badge_not_unlocked'; end if;
  if p_collectible_key is not null and not exists(select 1 from public.tgg_world_character_collectibles where character_id=v_char and collectible_key=p_collectible_key) then raise exception 'collectible_not_owned'; end if;

  insert into public.tgg_world_showcase_loadouts(character_id,title_key,badge_key,collectible_key,updated_at)
  values(v_char,p_title_key,p_badge_key,p_collectible_key,now())
  on conflict(character_id) do update
    set title_key=excluded.title_key,badge_key=excluded.badge_key,collectible_key=excluded.collectible_key,updated_at=now();

  update public.tgg_world_character_titles set equipped=(title_key=p_title_key) where character_id=v_char;

  return jsonb_build_object('ok',true,'title_key',p_title_key,'badge_key',p_badge_key,'collectible_key',p_collectible_key);
end;
$function$


-- [40000000403] function private.tgg_world_settle_ended_ladder_seasons()
CREATE OR REPLACE FUNCTION private.tgg_world_settle_ended_ladder_seasons()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_row record;
  v_reward jsonb;
  v_min_division text;
  v_current_rank integer;
  v_min_rank integer;
  v_qualified boolean;
  v_title_key text;
  v_badge_key text;
  v_season_xp integer;
  v_result jsonb;
  v_inserted integer:=0;
  v_qualified_count integer:=0;
begin
  for v_row in
    select
      s.character_id,
      l.season_key,
      l.ladder_key,
      s.division_key,
      s.ladder_points,
      l.divisions,
      l.rewards->'season_end' as reward
    from public.tgg_world_character_ladder_state s
    join public.tgg_world_tournament_ladders l
      on l.ladder_key=s.ladder_key and l.enabled=true
    join public.tgg_world_seasons se
      on se.season_key=l.season_key
     and se.enabled=true
     and se.ends_at is not null
     and se.ends_at<=now()
    where l.rewards ? 'season_end'
      and not exists(
        select 1
        from public.tgg_world_ladder_season_settlements x
        where x.character_id=s.character_id
          and x.season_key=l.season_key
          and x.ladder_key=l.ladder_key
      )
    order by l.season_key,l.ladder_key,s.character_id
  loop
    v_reward:=coalesce(v_row.reward,'{}'::jsonb);
    v_min_division:=nullif(v_reward->>'min_division','');

    select ord::integer into v_current_rank
    from jsonb_array_elements(v_row.divisions) with ordinality d(item,ord)
    where item->>'key'=v_row.division_key
    limit 1;

    select ord::integer into v_min_rank
    from jsonb_array_elements(v_row.divisions) with ordinality d(item,ord)
    where item->>'key'=v_min_division
    limit 1;

    v_qualified:=v_min_division is not null
      and v_current_rank is not null
      and v_min_rank is not null
      and v_current_rank>=v_min_rank;

    v_result:=jsonb_build_object(
      'qualified',v_qualified,
      'division_key',v_row.division_key,
      'min_division',v_min_division,
      'ladder_points',v_row.ladder_points
    );

    if v_qualified then
      v_title_key:=null;
      v_badge_key:=null;
      v_season_xp:=greatest(coalesce((v_reward->>'season_xp')::integer,0),0);

      if v_reward ? 'title' then
        select title_key into v_title_key
        from public.tgg_world_titles
        where enabled=true and lower(display_name)=lower(v_reward->>'title')
        limit 1;

        if v_title_key is not null then
          insert into public.tgg_world_character_titles(character_id,title_key,equipped,unlocked_at)
          values(v_row.character_id,v_title_key,false,now())
          on conflict(character_id,title_key) do nothing;
        end if;
      end if;

      if v_reward ? 'badge' then
        select badge_key into v_badge_key
        from public.tgg_world_badges
        where enabled=true and badge_key=v_reward->>'badge'
        limit 1;

        if v_badge_key is not null then
          insert into public.tgg_world_character_badges(character_id,badge_key,unlocked_at)
          values(v_row.character_id,v_badge_key,now())
          on conflict(character_id,badge_key) do nothing;
        end if;
      end if;

      if v_season_xp>0 then
        insert into public.tgg_world_character_season_progress(
          character_id,season_key,season_level,season_xp,unlocked_rewards,updated_at
        )
        values(v_row.character_id,v_row.season_key,1,v_season_xp,'[]'::jsonb,now())
        on conflict(character_id,season_key) do update
        set season_xp=public.tgg_world_character_season_progress.season_xp+excluded.season_xp,
            updated_at=now();

        update public.tgg_world_character_season_progress sp
        set season_level=coalesce((
          select max(r.reward_level)
          from public.tgg_world_season_rewards r
          where r.season_key=sp.season_key
            and r.required_xp<=sp.season_xp
        ),1),
        updated_at=now()
        where sp.character_id=v_row.character_id
          and sp.season_key=v_row.season_key;
      end if;

      v_result:=v_result||jsonb_build_object(
        'title_key',v_title_key,
        'badge_key',v_badge_key,
        'season_xp_awarded',v_season_xp
      );
      v_qualified_count:=v_qualified_count+1;
    end if;

    insert into public.tgg_world_ladder_season_settlements(
      character_id,season_key,ladder_key,division_key,qualified,reward,result,settled_at
    )
    values(
      v_row.character_id,v_row.season_key,v_row.ladder_key,v_row.division_key,
      v_qualified,v_reward,v_result,now()
    )
    on conflict(character_id,season_key,ladder_key) do nothing;

    v_inserted:=v_inserted+1;
  end loop;

  return jsonb_build_object(
    'processed',v_inserted,
    'qualified',v_qualified_count,
    'checked_at',now()
  );
end;
$function$


-- [40000000404] function private.tgg_world_social_comment(p_post_id uuid, p_body text)
CREATE OR REPLACE FUNCTION private.tgg_world_social_comment(p_post_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_body text:=btrim(coalesce(p_body,''));
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if char_length(v_body)<1 or char_length(v_body)>500 then raise exception 'comment_invalid'; end if;
  if not exists(select 1 from public.tgg_world_social_posts where id=p_post_id) then raise exception 'post_not_found'; end if;

  insert into public.tgg_world_social_comments(post_id,user_id,body,created_at,updated_at)
  values(p_post_id,v_uid,v_body,now(),now())
  returning id into v_id;

  update public.tgg_world_social_posts p
  set engagement=jsonb_set(
      coalesce(p.engagement,'{}'::jsonb),
      '{comments}',
      to_jsonb((select count(*) from public.tgg_world_social_comments c where c.post_id=p.id)),
      true
    )
  where p.id=p_post_id;

  return jsonb_build_object('ok',true,'comment_id',v_id,'post_id',p_post_id);
end;
$function$


-- [40000000405] function private.tgg_world_social_engagement_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_social_engagement_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  return jsonb_build_object(
    'reactions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'post_id',r.post_id,'user_id',r.user_id,'reaction_key',r.reaction_key,'created_at',r.created_at
      ) order by r.updated_at desc)
      from public.tgg_world_social_reactions r
      join public.tgg_world_social_posts p on p.id=r.post_id
      join public.world_characters own on own.id=p.character_id
      where p.visibility='public'
         or own.user_id=v_uid
         or (
           p.visibility='friends' and exists(
             select 1 from public.world_friend_requests fr
             where fr.status='accepted'
               and ((fr.requester_user_id=v_uid and fr.recipient_user_id=own.user_id)
                 or (fr.recipient_user_id=v_uid and fr.requester_user_id=own.user_id))
           )
         )
         or (
           p.visibility='crew' and exists(
             select 1 from public.tgg_world_crew_members mine
             join public.tgg_world_crew_members theirs on theirs.crew_id=mine.crew_id
             where mine.user_id=v_uid and mine.left_at is null
               and theirs.character_id=p.character_id and theirs.left_at is null
           )
         )
    ),'[]'::jsonb),
    'comments',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',c.id,'post_id',c.post_id,'user_id',c.user_id,'body',c.body,
        'stage_name',coalesce(a.stage_name,wc.stage_name,'Creator'),
        'created_at',c.created_at
      ) order by c.created_at asc)
      from public.tgg_world_social_comments c
      join public.tgg_world_social_posts p on p.id=c.post_id
      join public.world_characters own on own.id=p.character_id
      left join public.artists a on a.user_id=c.user_id
      left join public.world_characters wc on wc.user_id=c.user_id and wc.character_status='active'
      where p.visibility='public'
         or own.user_id=v_uid
         or (
           p.visibility='friends' and exists(
             select 1 from public.world_friend_requests fr
             where fr.status='accepted'
               and ((fr.requester_user_id=v_uid and fr.recipient_user_id=own.user_id)
                 or (fr.recipient_user_id=v_uid and fr.requester_user_id=own.user_id))
           )
         )
         or (
           p.visibility='crew' and exists(
             select 1 from public.tgg_world_crew_members mine
             join public.tgg_world_crew_members theirs on theirs.crew_id=mine.crew_id
             where mine.user_id=v_uid and mine.left_at is null
               and theirs.character_id=p.character_id and theirs.left_at is null
           )
         )
    ),'[]'::jsonb),
    'my_user_id',v_uid
  );
end;
$function$


-- [40000000406] function private.tgg_world_social_hub_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_social_hub_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  return jsonb_build_object(
    'character_id',v_char,
    'people',coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id',a.user_id,
        'artist_id',a.id,
        'stage_name',a.stage_name,
        'avatar_url',a.avatar_url,
        'world_stage_name',wc.stage_name,
        'friend_status',coalesce((
          select case
            when fr.status='accepted' then 'friends'
            when fr.status='pending' and fr.requester_user_id=v_uid then 'outgoing'
            when fr.status='pending' and fr.recipient_user_id=v_uid then 'incoming'
            else fr.status
          end
          from public.world_friend_requests fr
          where ((fr.requester_user_id=v_uid and fr.recipient_user_id=a.user_id)
             or (fr.requester_user_id=a.user_id and fr.recipient_user_id=v_uid))
          order by fr.created_at desc
          limit 1
        ),'none')
      ) order by a.stage_name)
      from public.artists a
      left join public.world_characters wc on wc.user_id=a.user_id and wc.character_status='active'
      where a.user_id<>v_uid
      limit 100
    ),'[]'::jsonb),
    'incoming_requests',coalesce((
      select jsonb_agg(jsonb_build_object(
        'request_id',fr.id,
        'user_id',fr.requester_user_id,
        'stage_name',coalesce(a.stage_name,wc.stage_name,'Creator'),
        'created_at',fr.created_at
      ) order by fr.created_at desc)
      from public.world_friend_requests fr
      left join public.artists a on a.user_id=fr.requester_user_id
      left join public.world_characters wc on wc.user_id=fr.requester_user_id and wc.character_status='active'
      where fr.recipient_user_id=v_uid and fr.status='pending'
    ),'[]'::jsonb),
    'friends',coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id',x.friend_user_id,
        'stage_name',coalesce(a.stage_name,wc.stage_name,'Creator'),
        'avatar_url',a.avatar_url,
        'conversation_id',(
          select c.id
          from public.tgg_conversations c
          join public.tgg_conversation_members m1 on m1.conversation_id=c.id and m1.user_id=v_uid
          join public.tgg_conversation_members m2 on m2.conversation_id=c.id and m2.user_id=x.friend_user_id
          where c.project_type='dm'
            and (select count(*) from public.tgg_conversation_members cm where cm.conversation_id=c.id)=2
          order by c.created_at desc limit 1
        )
      ) order by coalesce(a.stage_name,wc.stage_name,'Creator'))
      from (
        select case when fr.requester_user_id=v_uid then fr.recipient_user_id else fr.requester_user_id end as friend_user_id
        from public.world_friend_requests fr
        where fr.status='accepted'
          and (fr.requester_user_id=v_uid or fr.recipient_user_id=v_uid)
      ) x
      left join public.artists a on a.user_id=x.friend_user_id
      left join public.world_characters wc on wc.user_id=x.friend_user_id and wc.character_status='active'
    ),'[]'::jsonb),
    'world_posts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',p.id,
        'stage_name',wc.stage_name,
        'post_type',p.post_type,
        'caption',p.caption,
        'visibility',p.visibility,
        'engagement',p.engagement,
        'created_at',p.created_at
      ) order by p.created_at desc)
      from (
        select p.*
        from public.tgg_world_social_posts p
        join public.world_characters own on own.id=p.character_id
        where p.visibility='public'
           or own.user_id=v_uid
           or (
             p.visibility='friends'
             and exists(
               select 1 from public.world_friend_requests fr
               where fr.status='accepted'
                 and ((fr.requester_user_id=v_uid and fr.recipient_user_id=own.user_id)
                   or (fr.recipient_user_id=v_uid and fr.requester_user_id=own.user_id))
             )
           )
           or (
             p.visibility='crew'
             and exists(
               select 1
               from public.tgg_world_crew_members mine
               join public.tgg_world_crew_members theirs on theirs.crew_id=mine.crew_id
               where mine.user_id=v_uid and mine.left_at is null
                 and theirs.character_id=p.character_id and theirs.left_at is null
             )
           )
        order by p.created_at desc limit 50
      ) p
      join public.world_characters wc on wc.id=p.character_id
    ),'[]'::jsonb),
    'city_news',coalesce((
      select jsonb_agg(jsonb_build_object(
        'news_key',n.news_key,'headline',n.headline,'body',n.body,
        'category',n.category,'district_key',n.district_key,
        'importance',n.importance,'published_at',n.published_at
      ) order by n.importance desc,n.published_at desc)
      from (
        select * from public.tgg_world_city_news
        where visibility='public' and (expires_at is null or expires_at>now())
        order by importance desc,published_at desc
        limit 30
      ) n
    ),'[]'::jsonb),
    'creator_stories',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',s.id,'story_type',s.story_type,'caption',s.caption,
        'media_url',s.media_url,'created_at',s.created_at,'expires_at',s.expires_at
      ) order by s.created_at desc)
      from public.tgg_stories s
      where s.user_id=v_uid and s.expires_at>now()
    ),'[]'::jsonb),
    'story_arcs',coalesce((
      select jsonb_agg(jsonb_build_object(
        'arc_key',a.arc_key,'title',a.title,'description',a.description,'category',a.category,
        'status',coalesce(st.status,'not_started'),
        'current_chapter_key',st.current_chapter_key,
        'current_chapter',case when st.current_chapter_key is null then null else (
          select jsonb_build_object(
            'chapter_key',ch.chapter_key,'title',ch.title,'description',ch.description,
            'completion_conditions',ch.completion_conditions
          )
          from public.tgg_world_story_chapters ch
          where ch.chapter_key=st.current_chapter_key
        ) end,
        'flags',coalesce(st.flags,'{}'::jsonb),
        'consequence_state',coalesce(st.consequence_state,'{}'::jsonb)
      ) order by a.title)
      from public.tgg_world_story_arcs a
      left join public.tgg_world_character_story_state st
        on st.arc_key=a.arc_key and st.character_id=v_char
      where a.enabled=true
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000407] function private.tgg_world_social_lobby_bundle_impl()
CREATE OR REPLACE FUNCTION private.tgg_world_social_lobby_bundle_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object(
    'incoming_friend_requests',coalesce((
      select jsonb_agg(jsonb_build_object(
        'request_id',r.id,'artist_id',a.id,'stage_name',a.stage_name,'avatar_url',a.avatar_url,'created_at',r.created_at
      ) order by r.created_at desc)
      from public.world_friend_requests r
      join public.artists a on a.user_id=r.requester_user_id
      where r.recipient_user_id=v_uid and r.status='pending'
    ),'[]'::jsonb),
    'outgoing_friend_requests',coalesce((
      select jsonb_agg(jsonb_build_object(
        'request_id',r.id,'artist_id',a.id,'stage_name',a.stage_name,'avatar_url',a.avatar_url,'status',r.status,'created_at',r.created_at
      ) order by r.created_at desc)
      from public.world_friend_requests r
      join public.artists a on a.user_id=r.recipient_user_id
      where r.requester_user_id=v_uid and r.status in ('pending','accepted')
    ),'[]'::jsonb),
    'friends',coalesce((
      select jsonb_agg(jsonb_build_object(
        'artist_id',a.id,'stage_name',a.stage_name,'avatar_url',a.avatar_url,'friends_since',r.responded_at
      ) order by a.stage_name)
      from public.world_friend_requests r
      join public.artists a on a.user_id=(case when r.requester_user_id=v_uid then r.recipient_user_id else r.requester_user_id end)
      where r.status='accepted' and (r.requester_user_id=v_uid or r.recipient_user_id=v_uid)
    ),'[]'::jsonb),
    'party_invites',coalesce((
      select jsonb_agg(jsonb_build_object(
        'party_id',pm.party_id,'leader_artist_id',a.id,'leader_stage_name',a.stage_name,'leader_avatar_url',a.avatar_url,
        'current_instance_id',p.current_instance_id,'created_at',p.created_at
      ) order by p.created_at desc)
      from public.world_party_members pm
      join public.world_parties p on p.id=pm.party_id and p.status='active'
      left join public.artists a on a.user_id=p.leader_user_id
      where pm.user_id=v_uid and pm.status='invited'
    ),'[]'::jsonb),
    'active_parties',coalesce((
      select jsonb_agg(jsonb_build_object(
        'party_id',pm.party_id,'member_role',pm.member_role,'current_instance_id',p.current_instance_id,
        'leader_artist_id',a.id,'leader_stage_name',a.stage_name,'updated_at',p.updated_at
      ) order by p.updated_at desc)
      from public.world_party_members pm
      join public.world_parties p on p.id=pm.party_id and p.status='active'
      left join public.artists a on a.user_id=p.leader_user_id
      where pm.user_id=v_uid and pm.status='active'
    ),'[]'::jsonb)
  );
end$function$


-- [40000000408] function private.tgg_world_social_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_social_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_uid uuid:=auth.uid(); v_character uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select id into v_character from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if v_character is null then raise exception 'active world character not found'; end if;

  return jsonb_build_object(
    'crew',coalesce((
      select jsonb_agg(jsonb_build_object(
        'crew_id',c.id,'crew_name',c.crew_name,'crew_key',c.crew_key,'role',m.crew_role,
        'status',c.crew_status,
        'progression',case when cp.crew_id is null then null else jsonb_build_object(
          'xp',cp.crew_xp,'rank_level',cp.rank_level,'reputation',cp.reputation,'unlocks',cp.unlocks
        ) end
      ))
      from public.tgg_world_crew_members m
      join public.tgg_world_crews c on c.id=m.crew_id
      left join public.tgg_world_crew_progression cp on cp.crew_id=c.id
      where m.character_id=v_character and m.left_at is null
    ),'[]'::jsonb),

    'factions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'faction_key',f.faction_key,'name',f.display_name,'standing',cf.standing,
        'rank_level',cf.rank_level,'loyalty',cf.loyalty,'status',cf.status
      ) order by cf.standing desc)
      from public.tgg_world_character_factions cf
      join public.tgg_world_factions f on f.faction_key=cf.faction_key
      where cf.character_id=v_character
    ),'[]'::jsonb),

    'ladders',coalesce((
      select jsonb_agg(jsonb_build_object(
        'ladder_key',l.ladder_key,'display_name',l.display_name,'points',s.ladder_points,
        'division',s.division_key,'wins',s.wins,'losses',s.losses,'streak',s.streak
      ))
      from public.tgg_world_character_ladder_state s
      join public.tgg_world_tournament_ladders l on l.ladder_key=s.ladder_key
      where s.character_id=v_character
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000409] function private.tgg_world_social_play_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_social_play_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_location text;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select wc.id,l.location_key into v_char,v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.user_id=v_uid and wc.character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  return jsonb_build_object(
    'character_id',v_char,
    'current_location',v_location,
    'party',jsonb_build_object(
      'my_parties',coalesce((
        select jsonb_agg(jsonb_build_object(
          'party_id',p.id,
          'leader_user_id',p.leader_user_id,
          'is_leader',p.leader_user_id=v_uid,
          'status',p.status,
          'current_instance_id',p.current_instance_id,
          'voice_room_id',p.voice_room_id,
          'location_key',p.metadata->>'location_key',
          'members',coalesce((
            select jsonb_agg(jsonb_build_object(
              'user_id',m.user_id,'member_role',m.member_role,'status',m.status,
              'stage_name',coalesce(a.stage_name,wc2.stage_name,'Creator')
            ) order by m.member_role desc,coalesce(a.stage_name,wc2.stage_name,'Creator'))
            from public.world_party_members m
            left join public.artists a on a.user_id=m.user_id
            left join public.world_characters wc2 on wc2.user_id=m.user_id and wc2.character_status='active'
            where m.party_id=p.id
          ),'[]'::jsonb)
        ) order by p.updated_at desc)
        from public.world_parties p
        where p.status='active'
          and exists(
            select 1 from public.world_party_members m
            where m.party_id=p.id and m.user_id=v_uid and m.status='active'
          )
      ),'[]'::jsonb),
      'invites',coalesce((
        select jsonb_agg(jsonb_build_object(
          'party_id',i.circle_id,
          'invite_id',i.id,
          'invited_by',i.invited_by,
          'inviter_name',coalesce(a.stage_name,wc2.stage_name,'Creator'),
          'status',i.status,'created_at',i.created_at
        ) order by i.created_at desc)
        from public.tgg_world_party_invites i
        left join public.artists a on a.user_id=i.invited_by
        left join public.world_characters wc2 on wc2.user_id=i.invited_by and wc2.character_status='active'
        where i.invited_user_id=v_uid and i.status='pending'
      ),'[]'::jsonb),
      'friends',coalesce((
        select jsonb_agg(jsonb_build_object(
          'user_id',x.friend_user_id,
          'stage_name',coalesce(a.stage_name,wc2.stage_name,'Creator')
        ) order by coalesce(a.stage_name,wc2.stage_name,'Creator'))
        from (
          select case when fr.requester_user_id=v_uid then fr.recipient_user_id else fr.requester_user_id end as friend_user_id
          from public.world_friend_requests fr
          where fr.status='accepted'
            and (fr.requester_user_id=v_uid or fr.recipient_user_id=v_uid)
        ) x
        left join public.artists a on a.user_id=x.friend_user_id
        left join public.world_characters wc2 on wc2.user_id=x.friend_user_id and wc2.character_status='active'
      ),'[]'::jsonb)
    ),
    'open_mic',jsonb_build_object(
      'at_corner_stage',v_location='corner-stage',
      'events',coalesce((
        select jsonb_agg(jsonb_build_object(
          'event_id',e.id,'event_status',e.event_status,'current_performance_id',e.current_performance_id,
          'queue',coalesce((
            select jsonb_agg(jsonb_build_object(
              'user_id',q.user_id,'queue_position',q.queue_position,'queue_status',q.queue_status,
              'stage_name',coalesce(a.stage_name,wc2.stage_name,'Creator')
            ) order by q.queue_position)
            from public.tgg_world_open_mic_queue q
            left join public.artists a on a.user_id=q.user_id
            left join public.world_characters wc2 on wc2.user_id=q.user_id and wc2.character_status='active'
            where q.event_id=e.id and q.queue_status in ('waiting','performing')
          ),'[]'::jsonb),
          'current_performance',case when e.current_performance_id is null then null else (
            select jsonb_build_object(
              'id',p.id,'user_id',p.user_id,'performance_status',p.performance_status,
              'stage_name',coalesce(a.stage_name,wc3.stage_name,'Creator'),
              'reaction_count',(select count(*) from public.tgg_world_open_mic_reactions r where r.performance_id=p.id),
              'is_me',p.user_id=v_uid
            )
            from public.tgg_world_open_mic_performances p
            left join public.artists a on a.user_id=p.user_id
            left join public.world_characters wc3 on wc3.user_id=p.user_id and wc3.character_status='active'
            where p.id=e.current_performance_id
          ) end
        ) order by e.updated_at desc)
        from public.tgg_world_open_mic_events e
        join public.tgg_world_locations l on l.id=e.location_id
        where l.location_key='corner-stage'
          and e.event_status in ('open','performing')
      ),'[]'::jsonb)
    ),
    'studio',jsonb_build_object(
      'at_basement_sound',v_location='basement-sound',
      'sessions',coalesce((
        select jsonb_agg(jsonb_build_object(
          'session_id',s.id,'host_user_id',s.host_user_id,'is_host',s.host_user_id=v_uid,
          'studio_project_id',s.studio_project_id,'session_status',s.session_status,
          'voice_context',s.voice_context,'created_at',s.created_at,
          'members',coalesce((
            select jsonb_agg(jsonb_build_object(
              'user_id',m.user_id,'session_role',m.session_role,'voice_enabled',m.voice_enabled,
              'stage_name',coalesce(a.stage_name,wc2.stage_name,'Creator')
            ) order by m.joined_at)
            from public.tgg_world_studio_session_members m
            left join public.artists a on a.user_id=m.user_id
            left join public.world_characters wc2 on wc2.user_id=m.user_id and wc2.character_status='active'
            where m.session_id=s.id and m.left_at is null
          ),'[]'::jsonb)
        ) order by s.created_at desc)
        from public.tgg_world_studio_sessions s
        where s.session_status='active'
          and (
            s.host_user_id=v_uid
            or exists(select 1 from public.tgg_world_studio_session_members m where m.session_id=s.id and m.user_id=v_uid and m.left_at is null)
            or (v_location='basement-sound')
          )
      ),'[]'::jsonb)
    )
  );
end;
$function$


-- [40000000410] function private.tgg_world_social_post(p_caption text, p_visibility text, p_post_type text, p_entity_type text, p_entity_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_social_post(p_caption text, p_visibility text DEFAULT 'public'::text, p_post_type text DEFAULT 'status'::text, p_entity_type text DEFAULT NULL::text, p_entity_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_caption text:=btrim(coalesce(p_caption,''));
  v_visibility text:=lower(btrim(coalesce(p_visibility,'public')));
  v_type text:=lower(btrim(coalesce(p_post_type,'status')));
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if char_length(v_caption)<1 or char_length(v_caption)>1000 then raise exception 'caption_invalid'; end if;
  if v_visibility not in ('public','friends','crew','private') then raise exception 'visibility_invalid'; end if;
  if v_type not in ('status','career','gig','event','crew','business','tournament','story') then raise exception 'post_type_invalid'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  insert into public.tgg_world_social_posts(
    character_id,post_type,caption,entity_type,entity_key,visibility,engagement,metadata,created_at
  ) values(
    v_char,v_type,v_caption,nullif(btrim(coalesce(p_entity_type,'')),''),
    nullif(btrim(coalesce(p_entity_key,'')),''),
    v_visibility,
    '{"likes":0,"shares":0,"comments":0}'::jsonb,
    jsonb_build_object('source','player'),
    now()
  )
  returning id into v_id;

  perform private.tgg_world_credit_challenge_event(
    v_char,'social_actions','social_post',v_id::text
  );

  return v_id;
end;
$function$


-- [40000000411] function private.tgg_world_social_react(p_post_id uuid, p_reaction_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_social_react(p_post_id uuid, p_reaction_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_key text:=lower(btrim(coalesce(p_reaction_key,'')));
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if v_key not in ('like','fire','clap','star') then raise exception 'invalid_reaction'; end if;
  if not exists(select 1 from public.tgg_world_social_posts where id=p_post_id) then raise exception 'post_not_found'; end if;

  insert into public.tgg_world_social_reactions(post_id,user_id,reaction_key,created_at,updated_at)
  values(p_post_id,v_uid,v_key,now(),now())
  on conflict(post_id,user_id) do update
  set reaction_key=excluded.reaction_key,updated_at=now();

  update public.tgg_world_social_posts p
  set engagement=jsonb_set(
      coalesce(p.engagement,'{}'::jsonb),
      '{likes}',
      to_jsonb((select count(*) from public.tgg_world_social_reactions r where r.post_id=p.id)),
      true
    )
  where p.id=p_post_id;

  return jsonb_build_object('ok',true,'post_id',p_post_id,'reaction_key',v_key);
end;
$function$


-- [40000000412] function private.tgg_world_start_business_competition(p_business_id uuid, p_competition_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_start_business_competition(p_business_id uuid, p_competition_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_char uuid;
  v_b public.tgg_world_character_businesses%rowtype;
  v_c public.tgg_world_business_competitions%rowtype;
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select id into v_char from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  select * into v_b from public.tgg_world_character_businesses where id=p_business_id and character_id=v_char and status='active';
  if v_b.id is null then raise exception 'owned_business_required'; end if;
  select * into v_c from public.tgg_world_business_competitions where competition_key=p_competition_key and enabled=true;
  if v_c.competition_key is null then raise exception 'competition_unavailable'; end if;
  if not (v_b.business_type_key=any(v_c.business_type_keys)) then raise exception 'business_not_eligible'; end if;

  insert into public.tgg_world_character_business_competitions(business_id,competition_key,status,score,result,started_at,updated_at)
  values(v_b.id,v_c.competition_key,'running',0,'{}'::jsonb,now(),now())
  on conflict(business_id,competition_key) do update
  set status='running',score=0,result='{}'::jsonb,started_at=now(),completed_at=null,updated_at=now()
  returning id into v_id;

  return jsonb_build_object('ok',true,'competition_run_id',v_id,'ready_at',now()+make_interval(hours=>v_c.duration_hours));
end;
$function$


-- [40000000413] function private.tgg_world_start_business_operation(p_business_id uuid, p_operation_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_start_business_operation(p_business_id uuid, p_operation_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_business public.tgg_world_character_businesses%rowtype;
  v_op public.tgg_world_business_operations%rowtype;
  v_required text[];
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select b.* into v_business
  from public.tgg_world_character_businesses b
  join public.world_characters wc on wc.id=b.character_id
  where b.id=p_business_id and wc.user_id=v_uid and b.status='active';
  if v_business.id is null then raise exception 'business_ownership_required'; end if;

  select * into v_op from public.tgg_world_business_operations
  where operation_key=p_operation_key and enabled=true;
  if v_op.operation_key is null then raise exception 'operation_unavailable'; end if;

  if cardinality(v_op.business_type_keys)>0 and not (v_business.business_type_key=any(v_op.business_type_keys)) then raise exception 'operation_not_compatible'; end if;

  if v_op.requirements ? 'staff_any' then
    select array_agg(x) into v_required from jsonb_array_elements_text(v_op.requirements->'staff_any') x;
    if not exists(
      select 1 from public.tgg_world_business_staff s
      where s.business_id=v_business.id and s.status='active' and s.role_key=any(v_required)
    ) then raise exception 'required_staff_missing'; end if;
  end if;

  if exists(
    select 1 from public.tgg_world_character_business_operations
    where business_id=v_business.id and operation_key=p_operation_key and status in ('queued','running')
  ) then raise exception 'operation_already_running'; end if;

  insert into public.tgg_world_character_business_operations(business_id,operation_key,status,started_at,result,updated_at)
  values(v_business.id,p_operation_key,'running',now(),jsonb_build_object('duration_minutes',v_op.duration_minutes),now())
  returning id into v_id;
  return v_id;
end;
$function$


-- [40000000414] function private.tgg_world_start_story_arc(p_arc_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_start_story_arc(p_arc_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_arc public.tgg_world_story_arcs%rowtype;
  v_first public.tgg_world_story_chapters%rowtype;
  v_existing public.tgg_world_character_story_state%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select id into v_char from public.world_characters
  where user_id=v_uid and character_status='active' limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_arc from public.tgg_world_story_arcs
  where arc_key=p_arc_key and enabled=true;
  if v_arc.arc_key is null then raise exception 'story_arc_unavailable'; end if;

  if not private.tgg_world_story_conditions_met(v_char,v_arc.entry_conditions) then
    return jsonb_build_object('started',false,'reason','entry_conditions_not_met');
  end if;

  select * into v_existing from public.tgg_world_character_story_state
  where character_id=v_char and arc_key=p_arc_key;
  if found then
    return jsonb_build_object(
      'started',true,'replayed',true,'arc_key',p_arc_key,
      'status',v_existing.status,'current_chapter_key',v_existing.current_chapter_key
    );
  end if;

  select * into v_first from public.tgg_world_story_chapters
  where arc_key=p_arc_key and enabled=true
  order by chapter_order limit 1;
  if v_first.chapter_key is null then raise exception 'story_arc_has_no_chapters'; end if;

  if not private.tgg_world_story_conditions_met(v_char,v_first.start_conditions) then
    return jsonb_build_object('started',false,'reason','first_chapter_conditions_not_met');
  end if;

  insert into public.tgg_world_character_story_state(
    character_id,arc_key,current_chapter_key,status,flags,consequence_state,started_at,updated_at
  ) values(v_char,p_arc_key,v_first.chapter_key,'active','{}'::jsonb,'{}'::jsonb,now(),now());

  return jsonb_build_object(
    'started',true,'replayed',false,'arc_key',p_arc_key,'current_chapter_key',v_first.chapter_key
  );
end;
$function$


-- [40000000415] function private.tgg_world_story_conditions_met(p_character_id uuid, p_conditions jsonb)
CREATE OR REPLACE FUNCTION private.tgg_world_story_conditions_met(p_character_id uuid, p_conditions jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_rep integer:=0;
  v_count integer:=0;
  v_flag text;
begin
  if coalesce(p_conditions,'{}'::jsonb)='{}'::jsonb then return true; end if;

  select coalesce(sum(reputation),0) into v_rep
  from public.tgg_world_career_reputation
  where character_id=p_character_id;

  if p_conditions ? 'min_reputation'
     and v_rep<coalesce((p_conditions->>'min_reputation')::integer,0)
  then return false; end if;

  if p_conditions ? 'flag' then
    v_flag:=p_conditions->>'flag';
    if not exists(
      select 1 from public.tgg_world_character_story_state
      where character_id=p_character_id and flags ? v_flag
    ) then return false; end if;
  end if;

  if p_conditions ? 'encounter' and not exists(
    select 1 from public.tgg_world_character_encounters
    where character_id=p_character_id
      and encounter_key=p_conditions->>'encounter'
  ) then return false; end if;

  if p_conditions ? 'encounter_any' and not exists(
    select 1
    from public.tgg_world_character_encounters e,
         jsonb_array_elements_text(p_conditions->'encounter_any') x
    where e.character_id=p_character_id and e.encounter_key=x
  ) then return false; end if;

  if p_conditions ? 'encounter_completed_any' and not exists(
    select 1
    from public.tgg_world_character_encounters e,
         jsonb_array_elements_text(p_conditions->'encounter_completed_any') x
    where e.character_id=p_character_id
      and e.encounter_key=x
      and e.status='completed'
  ) then return false; end if;

  if p_conditions ? 'choice_any' and not exists(
    select 1
    from public.tgg_world_encounter_choice_log l,
         jsonb_array_elements_text(p_conditions->'choice_any') x
    where l.character_id=p_character_id and l.choice_key=x
  ) then return false; end if;

  if p_conditions ? 'contract_any' and not exists(
    select 1
    from public.tgg_world_character_contracts c,
         jsonb_array_elements_text(p_conditions->'contract_any') x
    where c.character_id=p_character_id and c.contract_key=x
  ) then return false; end if;

  if p_conditions ? 'contract_completed_any' and not exists(
    select 1
    from public.tgg_world_character_contracts c,
         jsonb_array_elements_text(p_conditions->'contract_completed_any') x
    where c.character_id=p_character_id
      and c.contract_key=x
      and c.status='completed'
  ) then return false; end if;

  if p_conditions ? 'contract_completed_count' then
    select count(*) into v_count
    from public.tgg_world_character_contracts
    where character_id=p_character_id and status='completed';
    if v_count<coalesce((p_conditions->>'contract_completed_count')::integer,0)
    then return false; end if;
  end if;

  if p_conditions ? 'gig_completed_count' then
    select count(*) into v_count
    from public.tgg_world_character_gigs
    where character_id=p_character_id and status='completed';
    if v_count<coalesce((p_conditions->>'gig_completed_count')::integer,0)
    then return false; end if;
  end if;

  if p_conditions ? 'relationship_trust_min' and not exists(
    select 1 from public.tgg_world_contact_relationships
    where character_id=p_character_id
      and trust_score>=coalesce((p_conditions->>'relationship_trust_min')::integer,0)
  ) then return false; end if;

  if p_conditions ? 'npc_standing_changed'
     and coalesce((p_conditions->>'npc_standing_changed')::boolean,false)
     and not exists(
       select 1 from public.tgg_world_character_npc_standing
       where character_id=p_character_id
         and (standing<>0 or rivalry<>0 or loyalty<>0)
     )
  then return false; end if;

  return true;
end;
$function$


-- [40000000416] function private.tgg_world_story_consequence_target(p_character_id uuid, p_chapter_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_story_consequence_target(p_character_id uuid, p_chapter_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_ch public.tgg_world_story_chapters%rowtype;
  v_contact text;
  v_npc text;
  v_source_type text;
  v_source_key text;
begin
  select * into v_ch
  from public.tgg_world_story_chapters
  where chapter_key=p_chapter_key and enabled=true;

  if v_ch.chapter_key is null then
    return jsonb_build_object('resolved',false,'reason','chapter_not_found');
  end if;

  if coalesce((v_ch.consequences->>'relationship_shift')::boolean,false) then
    with encounter_candidates as (
      select jsonb_array_elements_text(sc.completion_conditions->'encounter_any') encounter_key
      from public.tgg_world_story_chapters sc
      where sc.arc_key=v_ch.arc_key
        and sc.chapter_order<v_ch.chapter_order
        and jsonb_typeof(sc.completion_conditions->'encounter_any')='array'
      union
      select sc.completion_conditions->>'encounter'
      from public.tgg_world_story_chapters sc
      where sc.arc_key=v_ch.arc_key
        and sc.chapter_order<v_ch.chapter_order
        and sc.completion_conditions ? 'encounter'
      union
      select sc.start_conditions->>'encounter'
      from public.tgg_world_story_chapters sc
      where sc.arc_key=v_ch.arc_key
        and sc.chapter_order<=v_ch.chapter_order
        and sc.start_conditions ? 'encounter'
    )
    select i.contact_key,e.npc_key,'encounter',ce.encounter_key
    into v_contact,v_npc,v_source_type,v_source_key
    from public.tgg_world_character_encounters ce
    join encounter_candidates c on c.encounter_key=ce.encounter_key
    join public.tgg_world_encounter_templates e on e.encounter_key=ce.encounter_key
    join public.tgg_world_npc_profiles n on n.npc_key=e.npc_key
    left join public.tgg_world_industry_contacts i
      on lower(i.display_name)=lower(n.display_name) and i.enabled=true
    where ce.character_id=p_character_id
      and ce.status='completed'
    order by ce.completed_at desc nulls last,ce.updated_at desc
    limit 1;

  elsif coalesce((v_ch.consequences->>'rivalry_seed')::integer,0)>0 then
    with contract_candidates as (
      select jsonb_array_elements_text(v_ch.start_conditions->'contract_any') contract_key
      where jsonb_typeof(v_ch.start_conditions->'contract_any')='array'
      union
      select jsonb_array_elements_text(v_ch.completion_conditions->'contract_any')
      where jsonb_typeof(v_ch.completion_conditions->'contract_any')='array'
      union
      select v_ch.start_conditions->>'contract'
      where v_ch.start_conditions ? 'contract'
      union
      select v_ch.completion_conditions->>'contract'
      where v_ch.completion_conditions ? 'contract'
    )
    select c.contact_key,n.npc_key,'contract',cc.contract_key
    into v_contact,v_npc,v_source_type,v_source_key
    from public.tgg_world_character_contracts cc
    join contract_candidates x on x.contract_key=cc.contract_key
    join public.tgg_world_career_contracts c on c.contract_key=cc.contract_key
    left join public.tgg_world_industry_contacts i on i.contact_key=c.contact_key
    left join public.tgg_world_npc_profiles n
      on i.contact_key is not null and lower(n.display_name)=lower(i.display_name) and n.enabled=true
    where cc.character_id=p_character_id
      and cc.status='completed'
    order by cc.completed_at desc nulls last,cc.updated_at desc
    limit 1;
  end if;

  return jsonb_build_object(
    'resolved',v_contact is not null or v_npc is not null,
    'contact_key',v_contact,
    'npc_key',v_npc,
    'source_type',v_source_type,
    'source_key',v_source_key,
    'chapter_key',v_ch.chapter_key,
    'arc_key',v_ch.arc_key
  );
end;
$function$


-- [40000000417] function private.tgg_world_story_control_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_story_control_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select id into v_char from public.world_characters
  where user_id=v_uid and character_status='active' limit 1;
  if v_char is null then return '{}'::jsonb; end if;

  return jsonb_build_object(
    'arcs',coalesce((
      select jsonb_agg(jsonb_build_object(
        'arc_key',a.arc_key,'title',a.title,'description',a.description,'category',a.category,
        'entry_conditions',a.entry_conditions,
        'entry_ready',private.tgg_world_story_conditions_met(v_char,a.entry_conditions),
        'state',case when s.character_id is null then null else jsonb_build_object(
          'status',s.status,'current_chapter_key',s.current_chapter_key,
          'flags',s.flags,'consequence_state',s.consequence_state,
          'started_at',s.started_at,'completed_at',s.completed_at
        ) end,
        'current_chapter',case when s.current_chapter_key is null then null else (
          select jsonb_build_object(
            'chapter_key',ch.chapter_key,'title',ch.title,'description',ch.description,
            'start_conditions',ch.start_conditions,
            'completion_conditions',ch.completion_conditions,
            'completion_ready',private.tgg_world_story_conditions_met(v_char,ch.completion_conditions),
            'consequences',ch.consequences
          ) from public.tgg_world_story_chapters ch where ch.chapter_key=s.current_chapter_key
        ) end
      ) order by a.title)
      from public.tgg_world_story_arcs a
      left join public.tgg_world_character_story_state s
        on s.arc_key=a.arc_key and s.character_id=v_char
      where a.enabled=true
    ),'[]'::jsonb),
    'relationships',coalesce((
      select jsonb_agg(jsonb_build_object(
        'contact_key',r.contact_key,
        'display_name',coalesce(c.display_name,r.contact_key),
        'relationship_xp',r.relationship_xp,
        'relationship_level',r.relationship_level,
        'trust_score',r.trust_score,
        'successful_contracts',r.successful_contracts,
        'last_interaction_at',r.last_interaction_at,
        'memory',r.memory
      ) order by r.trust_score desc,r.last_interaction_at desc nulls last)
      from public.tgg_world_contact_relationships r
      left join public.tgg_world_industry_contacts c on c.contact_key=r.contact_key
      where r.character_id=v_char
    ),'[]'::jsonb),
    'npc_standing',coalesce((
      select jsonb_agg(jsonb_build_object(
        'npc_key',s.npc_key,
        'display_name',coalesce(n.display_name,s.npc_key),
        'standing',s.standing,'rivalry',s.rivalry,'loyalty',s.loyalty,
        'blocked_opportunities',s.blocked_opportunities,
        'favored_opportunities',s.favored_opportunities,
        'memory',s.memory
      ) order by s.rivalry desc,s.standing desc)
      from public.tgg_world_character_npc_standing s
      left join public.tgg_world_npc_profiles n on n.npc_key=s.npc_key
      where s.character_id=v_char
    ),'[]'::jsonb),
    'generated_story_queue',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',q.id,'rule_key',q.rule_key,'status',q.status,'context',q.context,'queued_at',q.queued_at
      ) order by q.queued_at desc)
      from public.tgg_world_story_generation_queue q
      where q.character_id=v_char
      limit 20
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000418] function private.tgg_world_studio_close_impl(p_session_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_studio_close_impl(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_session public.tgg_world_studio_sessions%rowtype;
  v_member_count integer:=0;
  v_session_credit jsonb;
  v_collab_credit jsonb;
  v_duration_seconds integer:=0;
  v_qualified boolean:=false;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select * into v_session
  from public.tgg_world_studio_sessions
  where id=p_session_id
    and host_user_id=v_uid
    and session_status in ('active','paused')
  for update;

  if v_session.id is null then raise exception 'active_hosted_session_required'; end if;

  select count(distinct character_id) into v_member_count
  from public.tgg_world_studio_session_members
  where session_id=v_session.id;

  v_duration_seconds:=greatest(floor(extract(epoch from (now()-v_session.created_at)))::integer,0);
  v_qualified:=v_duration_seconds>=60;

  update public.tgg_world_studio_sessions
  set session_status='ended',
      ended_at=coalesce(ended_at,now()),
      updated_at=now()
  where id=v_session.id;

  update public.tgg_world_studio_session_members
  set left_at=coalesce(left_at,now()),
      last_seen_at=now()
  where session_id=v_session.id;

  if v_qualified then
    perform private.tgg_world_credit_challenge_event(
      v_session.host_character_id,
      'studio_sessions',
      'studio_session',
      v_session.id::text
    );

    v_session_credit:=private.tgg_world_credit_career_mission_event(
    v_session.host_character_id,
    'studio_session_complete',
    'world_studio_session',
    v_session.id::text,
    jsonb_build_object('member_count',v_member_count)
  );
  perform private.tgg_world_credit_contract_event(
    v_session.host_character_id,
    'studio_session_complete',
    'world_studio_session',
    v_session.id::text,
    jsonb_build_object('member_count',v_member_count)
  );
  perform private.tgg_world_credit_gig_event(
    v_session.host_character_id,
    'studio_session_complete',
    'world_studio_session',
    v_session.id::text,
    jsonb_build_object('member_count',v_member_count)
  );

  if v_member_count>=2 then
    v_collab_credit:=private.tgg_world_credit_career_mission_event(
      v_session.host_character_id,
      'studio_collab_complete',
      'world_studio_session',
      v_session.id::text,
      jsonb_build_object('member_count',v_member_count,'collaboration',true)
    );
    perform private.tgg_world_credit_contract_event(
      v_session.host_character_id,
      'studio_collab_complete',
      'world_studio_session',
      v_session.id::text,
      jsonb_build_object('member_count',v_member_count,'collaboration',true)
    );
    perform private.tgg_world_credit_faction_mission_event(
      v_session.host_character_id,
      'collabs',
      'world_studio_session',
      v_session.id::text,
      jsonb_build_object('member_count',v_member_count,'collaboration',true)
    );
    end if;
  end if;

  return jsonb_build_object(
    'ok',true,
    'session_id',v_session.id,
    'session_status','ended',
    'member_count',v_member_count,
    'duration_seconds',v_duration_seconds,
    'qualified_for_progression',v_qualified,
    'session_mission_credit',coalesce(v_session_credit,'{}'::jsonb),
    'collab_mission_credit',coalesce(v_collab_credit,'{}'::jsonb)
  );
end;
$function$


-- [40000000419] function private.tgg_world_studio_join_impl(p_session_id uuid, p_role text)
CREATE OR REPLACE FUNCTION private.tgg_world_studio_join_impl(p_session_id uuid, p_role text DEFAULT 'guest'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_char public.world_characters%rowtype;
  v_session public.tgg_world_studio_sessions%rowtype;
  v_effective_role text;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if p_role not in ('artist','producer','engineer','guest') then raise exception 'invalid studio role'; end if;
  select * into v_char from public.world_characters where user_id=v_uid and character_status='active';
  if not found then raise exception 'active world character required'; end if;
  select * into v_session from public.tgg_world_studio_sessions where id=p_session_id and session_status='active';
  if not found then raise exception 'active studio session not found'; end if;
  if v_char.current_location_id<>v_session.location_id then raise exception 'character must be at the studio location'; end if;
  select case when m.session_role='host' then 'host' else p_role end into v_effective_role
  from public.tgg_world_studio_session_members m where m.session_id=p_session_id and m.user_id=v_uid;
  v_effective_role:=coalesce(v_effective_role,p_role);
  insert into public.tgg_world_studio_session_members(session_id,user_id,character_id,session_role,voice_enabled,left_at,last_seen_at)
  values(p_session_id,v_uid,v_char.id,v_effective_role,true,null,now())
  on conflict(session_id,user_id) do update
  set character_id=excluded.character_id,
      session_role=case when public.tgg_world_studio_session_members.session_role='host' then 'host' else excluded.session_role end,
      voice_enabled=true,left_at=null,last_seen_at=now();
  return jsonb_build_object('session_id',p_session_id,'role',v_effective_role,'voice_context','studio','reconnected',true);
end $function$


-- [40000000420] function private.tgg_world_studio_open_impl(p_studio_project_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_studio_open_impl(p_studio_project_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_char public.world_characters%rowtype;
  v_location public.tgg_world_locations%rowtype;
  v_presence public.tgg_world_presence%rowtype;
  v_session uuid;
  v_existing public.tgg_world_studio_sessions%rowtype;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select * into v_char from public.world_characters where user_id=v_uid and character_status='active';
  if not found then raise exception 'active world character required'; end if;
  select * into v_location from public.tgg_world_locations where id=v_char.current_location_id and location_key='basement-sound' and enabled=true;
  if not found then raise exception 'character must be at Basement Sound'; end if;
  if p_studio_project_id is not null and not exists(
    select 1 from public.tgg_studio_projects p
    where p.id=p_studio_project_id and (
      p.user_id=v_uid or exists(
        select 1 from public.tgg_studio_project_members pm
        where pm.project_id=p.id and pm.user_id=v_uid and pm.left_at is null
      )
    )
  ) then raise exception 'studio project access denied'; end if;
  select * into v_presence from public.tgg_world_presence where user_id=v_uid;

  select * into v_existing
  from public.tgg_world_studio_sessions
  where host_user_id=v_uid and session_status in ('active','paused')
  order by created_at desc
  limit 1
  for update;

  if v_existing.id is not null then
    if p_studio_project_id is not null
       and v_existing.studio_project_id is distinct from p_studio_project_id then
      raise exception 'active hosted studio session exists; close it before opening another project';
    end if;

    update public.tgg_world_studio_session_members
    set left_at=null,last_seen_at=now()
    where session_id=v_existing.id and user_id=v_uid;

    return jsonb_build_object(
      'session_id',v_existing.id,
      'studio_project_id',v_existing.studio_project_id,
      'voice_context',v_existing.voice_context,
      'creator_os_bridge',v_existing.studio_project_id is not null,
      'rights_transfer',false,
      'real_money',false,
      'reused',true
    );
  end if;
  insert into public.tgg_world_studio_sessions(host_user_id,host_character_id,location_id,instance_id,studio_project_id,metadata)
  values(v_uid,v_char.id,v_location.id,v_presence.instance_id,p_studio_project_id,
    jsonb_build_object('creator_os_bridge',p_studio_project_id is not null,'rights_transfer',false,'real_money',false))
  returning id into v_session;
  insert into public.tgg_world_studio_session_members(session_id,user_id,character_id,session_role)
  values(v_session,v_uid,v_char.id,'host');
  return jsonb_build_object('session_id',v_session,'studio_project_id',p_studio_project_id,'voice_context','studio',
    'creator_os_bridge',p_studio_project_id is not null,'rights_transfer',false,'real_money',false);
end $function$


-- [40000000421] function private.tgg_world_ui_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_ui_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;

  return jsonb_build_object(
    'navigation',coalesce((
      select jsonb_agg(jsonb_build_object(
        'screen_key',s.screen_key,'display_name',s.display_name,'route_key',s.route_key,
        'icon',s.icon,'sort_order',s.sort_order
      ) order by s.sort_order)
      from public.tgg_world_ui_screens s where s.enabled=true
    ),'[]'::jsonb),
    'screens',coalesce((
      select jsonb_object_agg(s.screen_key,jsonb_build_object(
        'display_name',s.display_name,'route_key',s.route_key,'icon',s.icon,'layout',s.layout,
        'modules',coalesce((
          select jsonb_agg(jsonb_build_object(
            'module_key',m.module_key,'display_name',m.display_name,'module_type',m.module_type,
            'data_path',m.data_path,'sort_order',m.sort_order,'ui_config',m.ui_config
          ) order by m.sort_order)
          from public.tgg_world_ui_modules m
          where m.screen_key=s.screen_key and m.enabled=true
        ),'[]'::jsonb)
      ))
      from public.tgg_world_ui_screens s where s.enabled=true
    ),'{}'::jsonb),
    'character_creation',private.tgg_world_character_creation_payload(),
    'onboarding',private.tgg_world_onboarding_payload(),
    'next_moves',private.tgg_world_next_moves_payload(),
    'actions',private.tgg_world_actions_payload(),
    'business_loop',private.tgg_world_business_loop_payload(),
    'crew_rides',private.tgg_world_crew_rides_payload(),
    'competitive',private.tgg_world_competitive_endgame_payload(),
    'social_hub',private.tgg_world_social_hub_payload(),
    'career_climb',private.tgg_world_career_climb_payload(),
    'progression_ops',private.tgg_world_progression_ops_payload(),
    'story_control',private.tgg_world_story_control_payload(),
    'dashboard',case when exists(
      select 1 from public.world_characters where user_id=auth.uid() and character_status='active'
    ) then private.tgg_world_dashboard_payload() else '{}'::jsonb end,
    'map',private.tgg_world_map_payload(),
    'activity',case when exists(
      select 1 from public.world_characters where user_id=auth.uid() and character_status='active'
    ) then private.tgg_world_activity_payload() else '{}'::jsonb end,
    'social',case when exists(
      select 1 from public.world_characters where user_id=auth.uid() and character_status='active'
    ) then private.tgg_world_social_payload() else '{}'::jsonb end,
    'runtime',private.tgg_world_runtime_ui_payload(),
    'responsive',jsonb_build_object(
      'breakpoints',jsonb_build_object('mobile',0,'tablet',768,'desktop',1200),
      'navigation',jsonb_build_object('mobile','bottom_tabs','desktop','sidebar'),
      'cards',jsonb_build_object('mobile_columns',1,'tablet_columns',2,'desktop_columns',3),
      'reduce_motion_supported',true
    )
  );
end;
$function$


-- [40000000422] function private.tgg_world_update_character_profile_impl(p_stage_name text, p_avatar_config jsonb, p_active_career text)
CREATE OR REPLACE FUNCTION private.tgg_world_update_character_profile_impl(p_stage_name text DEFAULT NULL::text, p_avatar_config jsonb DEFAULT NULL::jsonb, p_active_career text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_character public.world_characters%rowtype;
  v_name text;
  v_career text;
begin
  if v_user is null then raise exception 'authentication required'; end if;

  select * into v_character from public.world_characters where user_id=v_user for update;
  if v_character.id is null then raise exception 'character not found'; end if;

  v_name := case when p_stage_name is null then v_character.stage_name else nullif(trim(p_stage_name),'') end;
  if v_name is null or length(v_name) < 2 or length(v_name) > 40 then
    raise exception 'stage name must be between 2 and 40 characters';
  end if;

  v_career := case when p_active_career is null then v_character.active_career else lower(trim(p_active_career)) end;
  if not exists(
    select 1 from public.world_character_careers c
    where c.character_id=v_character.id and c.career_key=v_career and c.unlocked=true
  ) then raise exception 'career is not unlocked'; end if;

  update public.world_characters
  set stage_name=v_name,
      avatar_config=coalesce(p_avatar_config,avatar_config),
      active_career=v_career,
      updated_at=now()
  where id=v_character.id
  returning * into v_character;

  return to_jsonb(v_character);
end
$function$


-- [40000000423] function private.tgg_world_v10_verify_crew_shared_session_impl(p_crew_mission_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_v10_verify_crew_shared_session_impl(p_crew_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_cm public.tgg_world_crew_missions%rowtype;
  v_mission public.tgg_world_missions%rowtype;
  v_session public.tgg_world_studio_sessions%rowtype;
  v_duration integer := 0;
  v_real_members integer := 0;
  v_verified integer := 0;
  v_completed boolean := false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;

  select * into v_cm
  from public.tgg_world_crew_missions
  where id=p_crew_mission_id
  for update;
  if v_cm.id is null then raise exception 'CREW_MISSION_NOT_FOUND'; end if;

  if v_cm.status='completed' then
    select count(distinct user_id) into v_verified
    from public.tgg_world_crew_mission_members
    where crew_mission_id=v_cm.id and verified=true;
    return jsonb_build_object('ok',true,'status','completed','crew_mission_id',v_cm.id,'verified_members',v_verified,'required_members',2,'completed',true,'replayed',true);
  end if;

  if v_cm.status not in ('in_progress','evidence_pending') then raise exception 'CREW_MISSION_NOT_ACTIVE'; end if;

  select * into v_mission from public.tgg_world_missions where id=v_cm.mission_id and active=true;
  if v_mission.id is null then raise exception 'MISSION_NOT_FOUND'; end if;
  if v_mission.objective_type <> 'shared_session' then raise exception 'SHARED_SESSION_MISSION_REQUIRED'; end if;

  if not exists(
    select 1 from public.tgg_world_crew_members_v10 m
    where m.crew_id=v_cm.crew_id and m.user_id=v_uid and m.status='active'
  ) then raise exception 'CREW_MEMBERSHIP_REQUIRED'; end if;

  if v_cm.session_id is null then raise exception 'CREW_SESSION_REQUIRED'; end if;
  select * into v_session
  from public.tgg_world_studio_sessions
  where id=v_cm.session_id and session_status='ended';
  if v_session.id is null then raise exception 'COMPLETED_STUDIO_SESSION_REQUIRED'; end if;

  if v_cm.project_id is not null and v_session.studio_project_id is distinct from v_cm.project_id then
    raise exception 'CREW_PROJECT_SESSION_MISMATCH';
  end if;

  v_duration := greatest(floor(extract(epoch from (coalesce(v_session.ended_at,now())-v_session.created_at)))::integer,0);
  if v_duration < 60 then raise exception 'QUALIFYING_SESSION_DURATION_REQUIRED'; end if;

  if not exists(
    select 1 from public.tgg_world_studio_session_members sm
    where sm.session_id=v_session.id and sm.user_id=v_uid
  ) then raise exception 'SESSION_PARTICIPATION_REQUIRED'; end if;

  select count(distinct sm.user_id) into v_real_members
  from public.tgg_world_studio_session_members sm
  join public.tgg_world_crew_members_v10 cmem
    on cmem.crew_id=v_cm.crew_id and cmem.user_id=sm.user_id and cmem.status='active'
  where sm.session_id=v_session.id;

  if v_real_members < 2 then raise exception 'TWO_REAL_COLLABORATORS_REQUIRED'; end if;

  insert into public.tgg_world_crew_mission_members(crew_mission_id,user_id,contribution,verified,verified_at)
  values (
    v_cm.id,v_uid,
    jsonb_build_object('source','world_studio_session','session_id',v_session.id,'studio_project_id',v_session.studio_project_id,'duration_seconds',v_duration,'real_crew_members',v_real_members,'provenance_verified',true),
    true,now()
  )
  on conflict(crew_mission_id,user_id) do update
    set contribution=coalesce(public.tgg_world_crew_mission_members.contribution,'{}'::jsonb)||excluded.contribution,
        verified=true,
        verified_at=coalesce(public.tgg_world_crew_mission_members.verified_at,excluded.verified_at);

  select count(distinct user_id) into v_verified
  from public.tgg_world_crew_mission_members
  where crew_mission_id=v_cm.id and verified=true;

  if v_verified >= 2 then
    update public.tgg_world_crew_missions
    set status='completed',progress=100,completed_at=coalesce(completed_at,now()),updated_at=now()
    where id=v_cm.id;
    v_completed:=true;
  else
    update public.tgg_world_crew_missions
    set status='evidence_pending',progress=least(99,greatest(progress,50)),updated_at=now()
    where id=v_cm.id;
  end if;

  return jsonb_build_object(
    'ok',true,'status',case when v_completed then 'completed' else 'evidence_pending' end,
    'crew_mission_id',v_cm.id,'session_id',v_session.id,'verified_user_id',v_uid,
    'duration_seconds',v_duration,'real_collaborators',v_real_members,
    'verified_members',v_verified,'required_members',2,'completed',v_completed
  );
end
$function$


-- [40000000424] function private.tgg_world_v11_5_open_mic_bundle_impl()
CREATE OR REPLACE FUNCTION private.tgg_world_v11_5_open_mic_bundle_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_character public.world_characters%rowtype;
  v_stage_id uuid;
  v_stage_key text := 'corner-stage';
  v_instance uuid;
  v_event public.tgg_world_open_mic_events%rowtype;
  v_suggested text;
  v_queue jsonb := '[]'::jsonb;
  v_my_queue jsonb;
  v_performance jsonb;
  v_top_instrument jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_character
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  select id into v_stage_id
  from public.tgg_world_locations
  where location_key=v_stage_key and enabled=true
  limit 1;
  if v_stage_id is null then raise exception 'CORNER_STAGE_UNAVAILABLE'; end if;

  select wp.instance_id into v_instance
  from public.world_presence wp
  join public.world_instances i on i.id=wp.instance_id
  where wp.user_id=v_uid
    and wp.left_at is null
    and wp.heartbeat_at > now()-interval '2 minutes'
    and i.location_id=v_stage_id
    and i.status in ('active','draining')
  order by wp.heartbeat_at desc
  limit 1;

  select * into v_event
  from public.tgg_world_open_mic_events e
  where e.location_id=v_stage_id
    and v_instance is not null
    and e.instance_id=v_instance
    and e.event_status in ('open','performing')
  order by e.created_at desc
  limit 1;

  if v_character.id is null then
    select coalesce(
      (select nullif(btrim(a.stage_name),'') from public.artists a where a.user_id=v_uid limit 1),
      (select nullif(btrim(cp.display_name),'') from public.tgg_creator_profiles cp where cp.user_id=v_uid limit 1),
      (select nullif(btrim(wp.display_name),'') from public.tgg_world_players wp where wp.user_id=v_uid limit 1),
      'Creator'
    ) into v_suggested;
  else
    v_suggested := v_character.stage_name;
  end if;

  if v_event.id is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'position',q.queue_position,
      'status',q.queue_status,
      'stage_name',coalesce(c.stage_name,'Creator'),
      'is_me',q.user_id=v_uid
    ) order by q.queue_position,q.joined_at),'[]'::jsonb)
    into v_queue
    from public.tgg_world_open_mic_queue q
    left join public.world_characters c on c.id=q.character_id
    where q.event_id=v_event.id and q.queue_status in ('waiting','performing');

    select jsonb_build_object('position',q.queue_position,'status',q.queue_status)
    into v_my_queue
    from public.tgg_world_open_mic_queue q
    where q.event_id=v_event.id and q.user_id=v_uid
    limit 1;

    if v_event.current_performance_id is not null then
      select jsonb_build_object(
        'id',p.id,
        'status',p.performance_status,
        'stage_name',coalesce(c.stage_name,'Creator'),
        'is_me',p.user_id=v_uid,
        'started_at',p.started_at,
        'instrument_key',p.instrument_key,
        'instrument_level',p.instrument_level,
        'instrument_xp',p.instrument_xp,
        'reaction_count',(select count(*) from public.tgg_world_open_mic_reactions r where r.performance_id=p.id),
        'my_reaction',(select r.reaction from public.tgg_world_open_mic_reactions r where r.performance_id=p.id and r.user_id=v_uid limit 1)
      ) into v_performance
      from public.tgg_world_open_mic_performances p
      left join public.world_characters c on c.id=p.character_id
      where p.id=v_event.current_performance_id;
    end if;
  end if;

  select jsonb_build_object('instrument_key',ip.instrument_key,'level',ip.level,'xp',ip.xp)
  into v_top_instrument
  from public.tgg_world_instrument_progress ip
  where ip.user_id=v_uid
  order by ip.level desc,ip.xp desc,ip.updated_at desc
  limit 1;

  return jsonb_build_object(
    'ok',true,
    'version','WORLD-V11.6.1-OPEN-MIC-INSTANCE-SCOPE',
    'character_ready',v_character.id is not null,
    'stage_name',coalesce(v_character.stage_name,v_suggested),
    'suggested_stage_name',v_suggested,
    'current_location_key',(select l.location_key from public.tgg_world_locations l where l.id=v_character.current_location_id),
    'at_corner_stage',coalesce(v_character.current_location_id=v_stage_id,false),
    'instance_present',v_instance is not null,
    'event',case when v_event.id is null then null else jsonb_build_object('id',v_event.id,'status',v_event.event_status) end,
    'queue',v_queue,
    'my_queue',v_my_queue,
    'performance',v_performance,
    'top_instrument',v_top_instrument,
    'capabilities',jsonb_build_object(
      'queue',true,'start_next',true,'audience_reactions',true,'performer_finish',true,
      'instrument_snapshot',true,'instance_scoped',true,'fresh_presence_required',true,
      'virtual_rewards_only',true,'real_money',false
    )
  );
end
$function$


-- [40000000425] function private.tgg_world_v11_5_set_open_mic_instrument_impl(p_performance_id uuid, p_instrument_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_5_set_open_mic_instrument_impl(p_performance_id uuid, p_instrument_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_perf public.tgg_world_open_mic_performances%rowtype;
  v_level integer := 1;
  v_xp bigint := 0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if not exists(select 1 from public.tgg_world_instrument_catalog where instrument_key=p_instrument_key and enabled=true) then
    raise exception 'INSTRUMENT_NOT_FOUND';
  end if;
  select * into v_perf from public.tgg_world_open_mic_performances where id=p_performance_id for update;
  if not found then raise exception 'PERFORMANCE_NOT_FOUND'; end if;
  if v_perf.user_id<>v_uid then raise exception 'PERFORMER_ONLY'; end if;
  if v_perf.performance_status<>'live' then raise exception 'PERFORMANCE_NOT_LIVE'; end if;

  select level,xp into v_level,v_xp
  from public.tgg_world_instrument_progress
  where user_id=v_uid and instrument_key=p_instrument_key;
  v_level := coalesce(v_level,1); v_xp := coalesce(v_xp,0);

  update public.tgg_world_open_mic_performances
  set instrument_key=p_instrument_key,
      instrument_level=v_level,
      instrument_xp=v_xp,
      performance_metadata=coalesce(performance_metadata,'{}'::jsonb)||jsonb_build_object('instrument_snapshot_at',now(),'source','world-v11.5')
  where id=p_performance_id;

  return jsonb_build_object('ok',true,'performance_id',p_performance_id,'instrument_key',p_instrument_key,'instrument_level',v_level,'instrument_xp',v_xp);
end
$function$


-- [40000000426] function private.tgg_world_v11_6_presence_bootstrap_impl()
CREATE OR REPLACE FUNCTION private.tgg_world_v11_6_presence_bootstrap_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_character public.world_characters%rowtype;
  v_location_key text;
  v_join jsonb;
  v_hb jsonb;
  v_presence_key text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_character
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_character.id is null then
    return jsonb_build_object('ok',true,'character_ready',false,'joined',false);
  end if;

  select location_key into v_location_key
  from public.tgg_world_locations
  where id=v_character.current_location_id and enabled=true;
  if v_location_key is null then raise exception 'CURRENT_LOCATION_UNAVAILABLE'; end if;

  v_join := tgg_private.world_join_location(v_location_key);
  v_hb := tgg_private.world_presence_heartbeat(
    jsonb_build_object('x',0,'y',0,'z',0),
    jsonb_build_object('location_key',v_location_key,'source','artist-world-v11.7')
  );

  select replace(p.id::text,'-','') into v_presence_key
  from public.world_presence p
  where p.user_id=v_uid
    and p.instance_id=(v_join->>'instance_id')::uuid
    and p.left_at is null
  order by p.heartbeat_at desc
  limit 1;

  return jsonb_build_object(
    'ok',true,
    'character_ready',true,
    'joined',true,
    'location_key',v_location_key,
    'instance_id',v_join->>'instance_id',
    'presence_key',v_presence_key,
    'population',v_join->'population',
    'capacity',v_join->'capacity',
    'heartbeat',v_hb,
    'realtime',jsonb_build_object(
      'movement_topic','world:' || (v_join->>'instance_id') || ':moves',
      'private',true,
      'authoritative',false
    )
  );
end
$function$


-- [40000000427] function private.tgg_world_v11_6_presence_bundle_impl()
CREATE OR REPLACE FUNCTION private.tgg_world_v11_6_presence_bundle_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_presence public.world_presence%rowtype;
  v_instance public.world_instances%rowtype;
  v_location_key text;
  v_players jsonb := '[]'::jsonb;
  v_proof jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select jsonb_build_object(
    'status',w.status,
    'passed',w.status='passed',
    'required_players',w.required_players,
    'peak_population',w.peak_population,
    'passed_at',w.first_passed_at,
    'last_observed_at',w.last_observed_at,
    'evidence_source','server_observed_world_presence'
  ) into v_proof
  from private.tgg_world_multiplayer_witness w
  where w.witness_key='same_instance_two_real_users';
  v_proof:=coalesce(v_proof,jsonb_build_object('status','pending','passed',false,'required_players',2,'peak_population',0,'evidence_source','server_observed_world_presence'));

  select * into v_presence
  from public.world_presence
  where user_id=v_uid and left_at is null and heartbeat_at > now()-interval '2 minutes'
  order by heartbeat_at desc
  limit 1;

  if v_presence.id is null then
    return jsonb_build_object(
      'ok',true,
      'version','WORLD-V11.7.1-REAL-MULTIPLAYER-WITNESS',
      'present',false,
      'players','[]'::jsonb,
      'population',0,
      'multiplayer_proof',v_proof,
      'privacy',jsonb_build_object('user_ids_exposed',false,'character_ids_exposed',false,'presence_key_pseudonymous',true)
    );
  end if;

  select * into v_instance from public.world_instances where id=v_presence.instance_id;
  select l.location_key into v_location_key from public.tgg_world_locations l where l.id=v_instance.location_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'presence_key',replace(p.id::text,'-',''),
    'stage_name',c.stage_name,
    'active_career',c.active_career,
    'avatar',jsonb_build_object(
      'accent',coalesce(ap.profile->>'accent',c.avatar_config->>'accent','#e50914'),
      'build',coalesce(ap.profile->>'build',c.avatar_config->>'build','balanced'),
      'vibe',coalesce(ap.profile->>'vibe',c.avatar_config->>'vibe','street')
    ),
    'position',coalesce(p.position,'{}'::jsonb),
    'activity',coalesce(p.activity,'{}'::jsonb),
    'presence_state',p.presence_state,
    'is_me',p.user_id=v_uid,
    'heartbeat_at',p.heartbeat_at
  ) order by p.joined_at),'[]'::jsonb)
  into v_players
  from public.world_presence p
  join public.world_characters c on c.id=p.character_id
  left join public.tgg_world_avatar_profiles ap on ap.user_id=p.user_id
  where p.instance_id=v_presence.instance_id
    and p.left_at is null
    and p.heartbeat_at > now()-interval '2 minutes';

  return jsonb_build_object(
    'ok',true,
    'version','WORLD-V11.7.1-REAL-MULTIPLAYER-WITNESS',
    'present',true,
    'presence_key',replace(v_presence.id::text,'-',''),
    'instance',jsonb_build_object(
      'key',v_instance.instance_key,
      'status',v_instance.status,
      'capacity',v_instance.capacity,
      'location_key',v_location_key
    ),
    'realtime',jsonb_build_object(
      'movement_topic','world:' || v_presence.instance_id::text || ':moves',
      'private',true,
      'authoritative',false
    ),
    'population',jsonb_array_length(v_players),
    'players',v_players,
    'multiplayer_proof',v_proof,
    'privacy',jsonb_build_object(
      'user_ids_exposed',false,
      'character_ids_exposed',false,
      'presence_key_pseudonymous',true
    )
  );
end
$function$


-- [40000000428] function private.tgg_world_v11_7_multiplayer_witness_eval()
CREATE OR REPLACE FUNCTION private.tgg_world_v11_7_multiplayer_witness_eval()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_instance uuid;
  v_population integer := 0;
  v_peak integer := 0;
  v_status text := 'pending';
  v_passed_at timestamptz;
  v_last_checked timestamptz;
  v_location_key text;
  v_instance_type text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select x.instance_id,x.population,x.location_key,x.instance_type
  into v_instance,v_population,v_location_key,v_instance_type
  from (
    select p.instance_id,
           count(distinct p.user_id)::integer as population,
           l.location_key,
           i.instance_type
    from public.world_presence p
    join auth.users u on u.id=p.user_id
    join public.world_characters c on c.id=p.character_id and c.user_id=p.user_id and c.character_status='active'
    join public.world_instances i on i.id=p.instance_id and i.status in ('active','draining')
    join public.tgg_world_locations l on l.id=i.location_id and l.enabled=true
    where p.left_at is null
      and p.presence_state <> 'offline'
      and p.heartbeat_at > now()-interval '2 minutes'
    group by p.instance_id,l.location_key,i.instance_type
    order by count(distinct p.user_id) desc,p.instance_id
    limit 1
  ) x;

  v_population := coalesce(v_population,0);

  insert into private.tgg_world_multiplayer_witness(
    witness_key,status,required_players,peak_population,last_current_population,
    observed_instance_id,first_passed_at,last_observed_at,last_checked_at,evidence,updated_at
  ) values (
    'same_instance_two_real_users',
    case when v_population>=2 then 'passed' else 'pending' end,
    2,
    v_population,
    v_population,
    case when v_population>=2 then v_instance else null end,
    case when v_population>=2 then now() else null end,
    case when v_population>=2 then now() else null end,
    now(),
    jsonb_build_object(
      'source','server_observed_world_presence',
      'freshness_seconds',120,
      'distinct_authenticated_users',v_population,
      'character_user_binding_required',true,
      'instance_status_required',jsonb_build_array('active','draining'),
      'location_enabled_required',true,
      'client_presence_mutation_allowed',false,
      'location_key',v_location_key,
      'instance_type',v_instance_type
    ),
    now()
  )
  on conflict(witness_key) do update
  set status=case when private.tgg_world_multiplayer_witness.status='passed' or excluded.status='passed' then 'passed' else 'pending' end,
      peak_population=greatest(private.tgg_world_multiplayer_witness.peak_population,excluded.peak_population),
      last_current_population=excluded.last_current_population,
      observed_instance_id=case when excluded.status='passed' then excluded.observed_instance_id else private.tgg_world_multiplayer_witness.observed_instance_id end,
      first_passed_at=coalesce(private.tgg_world_multiplayer_witness.first_passed_at,excluded.first_passed_at),
      last_observed_at=case when excluded.status='passed' then excluded.last_observed_at else private.tgg_world_multiplayer_witness.last_observed_at end,
      last_checked_at=excluded.last_checked_at,
      evidence=excluded.evidence,
      updated_at=now();

  select status,peak_population,first_passed_at,last_checked_at
  into v_status,v_peak,v_passed_at,v_last_checked
  from private.tgg_world_multiplayer_witness
  where witness_key='same_instance_two_real_users';

  return jsonb_build_object(
    'ok',true,
    'version','WORLD-V11.7.1-REAL-MULTIPLAYER-WITNESS',
    'status',v_status,
    'passed',v_status='passed',
    'required_players',2,
    'current_max_population',v_population,
    'peak_population',v_peak,
    'passed_at',v_passed_at,
    'last_checked_at',v_last_checked,
    'evidence_source','server_observed_world_presence',
    'freshness_seconds',120,
    'synthetic_client_presence_possible',false,
    'privacy',jsonb_build_object('user_ids_exposed',false,'character_ids_exposed',false,'instance_id_exposed',false)
  );
end
$function$


-- [40000000429] function private.tgg_world_v11_7_record_multiplayer_witness(p_instance_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_7_record_multiplayer_witness(p_instance_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_population integer := 0;
  v_location_key text;
  v_instance_type text;
  v_matrix_id uuid;
begin
  if p_instance_id is null then return; end if;

  select count(distinct p.user_id)::integer,l.location_key,i.instance_type
  into v_population,v_location_key,v_instance_type
  from public.world_presence p
  join auth.users u on u.id=p.user_id
  join public.world_characters c on c.id=p.character_id and c.user_id=p.user_id and c.character_status='active'
  join public.world_instances i on i.id=p.instance_id and i.status in ('active','draining')
  join public.tgg_world_locations l on l.id=i.location_id and l.enabled=true
  where p.instance_id=p_instance_id
    and p.left_at is null
    and p.presence_state <> 'offline'
    and p.heartbeat_at > now()-interval '2 minutes'
  group by l.location_key,i.instance_type;

  v_population:=coalesce(v_population,0);

  insert into private.tgg_world_multiplayer_witness(
    witness_key,status,required_players,peak_population,last_current_population,
    observed_instance_id,first_passed_at,last_observed_at,last_checked_at,evidence,updated_at
  ) values (
    'same_instance_two_real_users',
    case when v_population>=2 then 'passed' else 'pending' end,
    2,v_population,v_population,
    case when v_population>=2 then p_instance_id else null end,
    case when v_population>=2 then now() else null end,
    case when v_population>=2 then now() else null end,
    now(),
    jsonb_build_object(
      'source','authoritative_presence_heartbeat',
      'freshness_seconds',120,
      'distinct_authenticated_users',v_population,
      'character_user_binding_required',true,
      'client_presence_mutation_allowed',false,
      'location_key',v_location_key,
      'instance_type',v_instance_type
    ),now()
  )
  on conflict(witness_key) do update
  set status=case when private.tgg_world_multiplayer_witness.status='passed' or excluded.status='passed' then 'passed' else 'pending' end,
      peak_population=greatest(private.tgg_world_multiplayer_witness.peak_population,excluded.peak_population),
      last_current_population=excluded.last_current_population,
      observed_instance_id=case when excluded.status='passed' then excluded.observed_instance_id else private.tgg_world_multiplayer_witness.observed_instance_id end,
      first_passed_at=coalesce(private.tgg_world_multiplayer_witness.first_passed_at,excluded.first_passed_at),
      last_observed_at=case when excluded.status='passed' then excluded.last_observed_at else private.tgg_world_multiplayer_witness.last_observed_at end,
      last_checked_at=excluded.last_checked_at,
      evidence=excluded.evidence,
      updated_at=now();

  insert into public.tgg_runtime_qa_contract_matrix(
    contract_key,subsystem,flow,required_state,evidence_type,status,metadata,updated_at
  ) values (
    'world_multiplayer_same_instance_two_real_users_v11_7',
    'artist_world',
    'multiplayer_presence_and_realtime_movement',
    'two_distinct_real_authenticated_users_with_fresh_presence_in_same_live_instance',
    'server_observed_presence_witness',
    case when v_population>=2 then 'passed' else 'pending' end,
    jsonb_build_object(
      'version','WORLD-V11.7.1-REAL-MULTIPLAYER-WITNESS',
      'required_players',2,
      'current_population',v_population,
      'freshness_seconds',120,
      'synthetic_accounts_used',false,
      'client_can_mutate_world_presence',false,
      'broadcast_authoritative',false,
      'authoritative_source','public.world_presence'
    ),now()
  )
  on conflict(contract_key) do update
  set status=case when public.tgg_runtime_qa_contract_matrix.status='passed' or excluded.status='passed' then 'passed' else 'pending' end,
      metadata=public.tgg_runtime_qa_contract_matrix.metadata || excluded.metadata,
      updated_at=now()
  returning id into v_matrix_id;

  if v_population>=2 and not exists(
    select 1 from public.tgg_runtime_qa_contract_evidence e
    where e.matrix_id=v_matrix_id
      and e.status='passed'
      and e.evidence_source='world_presence_heartbeat_witness'
  ) then
    insert into public.tgg_runtime_qa_contract_evidence(
      matrix_id,evidence_source,evidence_type,status,source_ref,evidence,captured_at,expires_at
    ) values (
      v_matrix_id,
      'world_presence_heartbeat_witness',
      'server_observed_presence_witness',
      'passed',
      'WORLD-V11.7.1',
      jsonb_build_object(
        'distinct_authenticated_users',v_population,
        'freshness_seconds',120,
        'same_instance',true,
        'character_user_binding_required',true,
        'client_presence_mutation_allowed',false,
        'broadcast_authoritative',false,
        'authoritative_source','public.world_presence'
      ),
      now(),null
    );
  end if;
end
$function$


-- [40000000430] function private.tgg_world_v11_avatar_save_impl(p_profile jsonb)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_avatar_save_impl(p_profile jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_row public.tgg_world_avatar_profiles;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if jsonb_typeof(coalesce(p_profile,'{}'::jsonb)) <> 'object' then raise exception 'AVATAR_PROFILE_INVALID'; end if;
  if char_length(coalesce(p_profile,'{}'::jsonb)::text) > 12000 then raise exception 'AVATAR_PROFILE_TOO_LARGE'; end if;

  insert into public.tgg_world_avatar_profiles(user_id,profile,updated_at)
  values(v_uid,coalesce(p_profile,'{}'::jsonb),now())
  on conflict(user_id) do update set profile=excluded.profile,updated_at=now()
  returning * into v_row;

  update public.world_characters
  set avatar_config=coalesce(avatar_config,'{}'::jsonb)||jsonb_build_object('identity_v11',v_row.profile),updated_at=now()
  where user_id=v_uid and character_status='active';

  update public.tgg_world_players
  set avatar=coalesce(avatar,'{}'::jsonb)||jsonb_build_object('identity_v11',v_row.profile),updated_at=now()
  where user_id=v_uid;

  return jsonb_build_object('ok',true,'profile',v_row.profile,'updated_at',v_row.updated_at,'synced_legacy_avatar',true);
end
$function$


-- [40000000431] function private.tgg_world_v11_bundle_impl()
CREATE OR REPLACE FUNCTION private.tgg_world_v11_bundle_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'version','WORLD-V11-LIFESTYLE-IDENTITY-1.1',
    'avatar',(select jsonb_build_object('profile',a.profile,'updated_at',a.updated_at) from public.tgg_world_avatar_profiles a where a.user_id=v_uid),
    'loadouts',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'name',l.name,'slots',l.slots,'active',l.active,'updated_at',l.updated_at) order by l.active desc,l.updated_at desc) from public.tgg_world_style_loadouts l where l.user_id=v_uid),'[]'::jsonb),
    'custom_designs',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'design_type',d.design_type,'name',d.name,'slot_key',d.slot_key,'material',d.material,'finish',d.finish,'palette',d.palette,'engraving',d.engraving,'status',d.status,'craft_cost_credits',d.craft_cost_credits,'crafted_at',d.crafted_at) order by d.updated_at desc) from public.tgg_world_custom_designs d where d.user_id=v_uid),'[]'::jsonb),
    'custom_items',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'design_id',i.design_id,'slot_key',i.slot_key,'display_name',i.display_name,'metadata',i.metadata,'created_at',i.created_at) order by i.created_at desc) from public.tgg_world_custom_style_items i where i.user_id=v_uid),'[]'::jsonb),
    'purchasable_style',coalesce((select jsonb_agg(jsonb_build_object('item_key',c.item_key,'display_name',c.display_name,'category',c.category,'price',c.price,'equippable',c.equippable,'slot_key',c.slot_key,'metadata',c.metadata) order by c.category,c.price,c.item_key) from public.tgg_world_shop_catalog c where c.enabled=true and (c.metadata->>'v11')='true'),'[]'::jsonb),
    'households',coalesce((select jsonb_agg(
      jsonb_build_object(
        'id',h.id,'name',h.name,'home_property_id',h.home_property_id,'visibility',h.visibility,'is_owner',h.owner_user_id=v_uid,
        'members',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'display_name',m.display_name,'relationship_role',m.relationship_role,'status',m.status,'is_me',m.member_user_id=v_uid,'is_npc',m.member_user_id is null,'created_at',m.created_at) order by m.created_at) from public.tgg_world_household_members m where m.household_id=h.id),'[]'::jsonb)
      ) order by h.updated_at desc)
      from public.tgg_world_households h
      where h.owner_user_id=v_uid or exists(select 1 from public.tgg_world_household_members hm where hm.household_id=h.id and hm.member_user_id=v_uid and hm.status in ('invited','active','away'))),'[]'::jsonb),
    'instrument_catalog',coalesce((select jsonb_agg(jsonb_build_object('instrument_key',c.instrument_key,'display_name',c.display_name,'family',c.family,'difficulty',c.difficulty,'metadata',c.metadata) order by c.family,c.difficulty,c.display_name) from public.tgg_world_instrument_catalog c where c.enabled=true),'[]'::jsonb),
    'instrument_progress',coalesce((select jsonb_agg(jsonb_build_object('instrument_key',p.instrument_key,'xp',p.xp,'level',p.level,'practice_seconds',p.practice_seconds,'sessions_completed',p.sessions_completed,'performances_completed',p.performances_completed,'best_score',p.best_score,'updated_at',p.updated_at) order by p.level desc,p.xp desc) from public.tgg_world_instrument_progress p where p.user_id=v_uid),'[]'::jsonb),
    'recent_instrument_sessions',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'instrument_key',s.instrument_key,'session_type',s.session_type,'duration_seconds',s.duration_seconds,'bpm',s.bpm,'musical_key',s.musical_key,'score',s.score,'studio_project_id',s.studio_project_id,'created_at',s.created_at) order by s.created_at desc) from (select * from public.tgg_world_instrument_sessions where user_id=v_uid order by created_at desc limit 20) s),'[]'::jsonb),
    'capabilities',jsonb_build_object('avatar_editor',true,'fashion_maker',true,'jewelry_maker',true,'virtual_credit_crafting',true,'style_loadouts',true,'households',true,'creator_search_invites',true,'real_user_invites',true,'npc_household_members',true,'live_instrument_progression',true,'studio_project_linking',true,'real_money',false)
  );
end
$function$


-- [40000000432] function private.tgg_world_v11_creator_search_impl(p_query text)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_creator_search_impl(p_query text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_q text := lower(btrim(coalesce(p_query,'')));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(v_q)<2 or char_length(v_q)>60 then raise exception 'SEARCH_QUERY_INVALID'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('creator_id',p.id,'display_name',p.display_name,'handle',p.handle,'avatar_url',p.avatar_url) order by p.display_name,p.handle)
    from (
      select id,display_name,handle,avatar_url
      from public.tgg_creator_profiles
      where is_public=true
        and user_id<>v_uid
        and (strpos(lower(coalesce(display_name,'')),v_q)>0 or strpos(lower(coalesce(handle,'')),v_q)>0)
      order by updated_at desc
      limit 12
    ) p
  ),'[]'::jsonb);
end
$function$


-- [40000000433] function private.tgg_world_v11_design_craft_impl(p_design_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_design_craft_impl(p_design_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_design public.tgg_world_custom_designs%rowtype;
  v_char public.world_characters%rowtype;
  v_wallet public.tgg_world_wallets%rowtype;
  v_cost bigint;
  v_item_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_design
  from public.tgg_world_custom_designs
  where id=p_design_id and user_id=v_uid
  for update;
  if not found then raise exception 'DESIGN_NOT_FOUND'; end if;

  if v_design.status='crafted' then
    select id into v_item_id from public.tgg_world_custom_style_items where design_id=v_design.id;
    return jsonb_build_object('ok',true,'design_id',v_design.id,'item_id',v_item_id,'status','crafted','replayed',true,'virtual_currency',true,'real_money',false);
  end if;
  if v_design.status<>'draft' then raise exception 'DESIGN_NOT_CRAFTABLE'; end if;

  v_cost := case when v_design.design_type='jewelry' then 900 else 300 end
    + case v_design.material when 'silk' then 150 when 'leather' then 250 when 'silver' then 250 when 'gold' then 700 when 'platinum' then 1200 when 'diamond' then 2500 when 'gemstone' then 900 when 'mixed' then 400 else 0 end
    + case v_design.finish when 'iced' then 1000 when 'custom' then 300 else 0 end;
  v_cost := least(v_cost,6000);

  select * into v_char from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if not found then raise exception 'ACTIVE_CHARACTER_REQUIRED'; end if;

  perform private.tgg_world_wallet_ensure_impl();
  select * into v_wallet from public.tgg_world_wallets where user_id=v_uid for update;
  if v_wallet.balance<v_cost then
    return jsonb_build_object('ok',false,'reason','insufficient_virtual_credits','balance',v_wallet.balance,'craft_cost',v_cost,'virtual_currency',true,'real_money',false);
  end if;

  update public.tgg_world_wallets set balance=balance-v_cost,updated_at=now() where user_id=v_uid returning * into v_wallet;
  insert into public.tgg_world_wallet_ledger(user_id,character_id,entry_type,amount,balance_after,reference_type,reference_key,metadata)
  values(v_uid,v_char.id,'purchase_debit',-v_cost,v_wallet.balance,'custom_style',p_design_id::text,jsonb_build_object('design_type',v_design.design_type,'slot_key',v_design.slot_key,'virtual_currency',true,'real_money',false));

  update public.tgg_world_custom_designs
  set status='crafted',craft_cost_credits=v_cost,crafted_at=now(),updated_at=now()
  where id=v_design.id;

  insert into public.tgg_world_custom_style_items(user_id,design_id,slot_key,display_name,metadata)
  values(v_uid,v_design.id,v_design.slot_key,v_design.name,jsonb_build_object('material',v_design.material,'finish',v_design.finish,'palette',v_design.palette,'engraving',v_design.engraving,'maker',v_design.design_type))
  returning id into v_item_id;

  return jsonb_build_object('ok',true,'design_id',v_design.id,'item_id',v_item_id,'status','crafted','craft_cost',v_cost,'balance',v_wallet.balance,'virtual_currency',true,'real_money',false,'replayed',false);
end
$function$


-- [40000000434] function private.tgg_world_v11_design_create_impl(p_design_type text, p_name text, p_slot_key text, p_material text, p_finish text, p_palette jsonb, p_engraving text)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_design_create_impl(p_design_type text, p_name text, p_slot_key text, p_material text, p_finish text, p_palette jsonb DEFAULT '{}'::jsonb, p_engraving text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_design_type not in ('fashion','jewelry') then raise exception 'DESIGN_TYPE_INVALID'; end if;
  if char_length(btrim(coalesce(p_name,''))) not between 1 and 80 then raise exception 'DESIGN_NAME_INVALID'; end if;
  if p_slot_key not in ('outfit','top','bottom','shoes','outerwear','headwear','accessory','jewelry') then raise exception 'DESIGN_SLOT_INVALID'; end if;
  if p_design_type='jewelry' and p_slot_key not in ('jewelry','accessory') then raise exception 'JEWELRY_SLOT_INVALID'; end if;
  if p_design_type='fashion' and p_slot_key='jewelry' then raise exception 'FASHION_SLOT_INVALID'; end if;
  if lower(coalesce(p_material,'')) not in ('cotton','denim','leather','silk','canvas','silver','gold','platinum','diamond','gemstone','mixed') then raise exception 'MATERIAL_INVALID'; end if;
  if lower(coalesce(p_finish,'')) not in ('matte','gloss','polished','brushed','iced','vintage','custom') then raise exception 'FINISH_INVALID'; end if;
  if jsonb_typeof(coalesce(p_palette,'{}'::jsonb))<>'object' or char_length(coalesce(p_palette,'{}'::jsonb)::text)>2000 then raise exception 'PALETTE_INVALID'; end if;
  if char_length(coalesce(p_engraving,''))>120 then raise exception 'ENGRAVING_TOO_LONG'; end if;

  insert into public.tgg_world_custom_designs(user_id,design_type,name,slot_key,material,finish,palette,engraving)
  values(v_uid,p_design_type,btrim(p_name),p_slot_key,lower(p_material),lower(p_finish),coalesce(p_palette,'{}'::jsonb),nullif(btrim(coalesce(p_engraving,'')),''))
  returning id into v_id;

  return jsonb_build_object('ok',true,'design_id',v_id,'status','draft','virtual_currency',true,'real_money',false);
end
$function$


-- [40000000435] function private.tgg_world_v11_household_accept_impl(p_member_id uuid, p_accept boolean)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_household_accept_impl(p_member_id uuid, p_accept boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_status text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  update public.tgg_world_household_members
  set status=case when coalesce(p_accept,true) then 'active' else 'declined' end,updated_at=now()
  where id=p_member_id and member_user_id=v_uid and status='invited'
  returning status into v_status;
  if v_status is null then raise exception 'HOUSEHOLD_INVITE_NOT_FOUND'; end if;
  return jsonb_build_object('ok',true,'member_id',p_member_id,'status',v_status);
end
$function$


-- [40000000436] function private.tgg_world_v11_household_action_impl(p_member_id uuid, p_action_type text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_household_action_impl(p_member_id uuid, p_action_type text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_member public.tgg_world_household_members%rowtype;
  v_household public.tgg_world_households%rowtype;
  v_existing public.tgg_world_household_action_log%rowtype;
  v_rel public.tgg_world_household_relationships%rowtype;
  v_action text := lower(trim(coalesce(p_action_type,'')));
  v_key text := trim(coalesce(p_idempotency_key,''));
  v_xp integer;
  v_trust integer;
  v_result jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_member_id is null then raise exception 'MEMBER_REQUIRED'; end if;
  if length(v_key) < 8 or length(v_key) > 120 then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;

  select * into v_existing
  from public.tgg_world_household_action_log
  where user_id=v_uid and idempotency_key=v_key;
  if found then return v_existing.result || jsonb_build_object('replayed',true); end if;

  select m.* into v_member
  from public.tgg_world_household_members m
  join public.tgg_world_households h on h.id=m.household_id
  where m.id=p_member_id
    and m.status in ('active','away')
    and (
      h.owner_user_id=v_uid
      or exists (
        select 1 from public.tgg_world_household_members mine
        where mine.household_id=h.id
          and mine.member_user_id=v_uid
          and mine.status in ('active','away')
      )
    )
  limit 1;
  if not found then raise exception 'HOUSEHOLD_MEMBER_NOT_AVAILABLE'; end if;
  if v_member.member_user_id=v_uid then raise exception 'CANNOT_TARGET_SELF'; end if;

  select * into v_household from public.tgg_world_households where id=v_member.household_id;

  case v_action
    when 'hangout' then v_xp:=25; v_trust:=3;
    when 'meal' then v_xp:=18; v_trust:=2;
    when 'studio_session' then v_xp:=30; v_trust:=2;
    when 'workout' then v_xp:=22; v_trust:=2;
    when 'call' then v_xp:=15; v_trust:=2;
    when 'support' then v_xp:=35; v_trust:=5;
    when 'celebrate' then v_xp:=28; v_trust:=4;
    when 'chore' then v_xp:=20; v_trust:=2;
    else raise exception 'INVALID_HOUSEHOLD_ACTION';
  end case;

  if exists (
    select 1 from public.tgg_world_household_action_log l
    where l.user_id=v_uid and l.member_id=p_member_id and l.action_type=v_action
      and l.created_at > now() - interval '3 seconds'
  ) then raise exception 'ACTION_TOO_FAST'; end if;

  insert into public.tgg_world_household_relationships(user_id,member_id,bond_xp,bond_level,trust_score,interactions_completed,last_action_type,last_interaction_at)
  values(v_uid,p_member_id,v_xp,least(50,1+(v_xp/250)),least(100,50+v_trust),1,v_action,now())
  on conflict(user_id,member_id) do update
  set bond_xp=public.tgg_world_household_relationships.bond_xp+excluded.bond_xp,
      bond_level=least(50,1+((public.tgg_world_household_relationships.bond_xp+excluded.bond_xp)/250)),
      trust_score=greatest(0,least(100,public.tgg_world_household_relationships.trust_score+v_trust)),
      interactions_completed=public.tgg_world_household_relationships.interactions_completed+1,
      last_action_type=v_action,
      last_interaction_at=now(),
      updated_at=now()
  returning * into v_rel;

  v_result:=jsonb_build_object(
    'ok',true,
    'household_id',v_household.id,
    'household_name',v_household.name,
    'member_id',v_member.id,
    'display_name',coalesce(v_member.display_name,v_member.relationship_role),
    'relationship_role',v_member.relationship_role,
    'action_type',v_action,
    'bond_xp_delta',v_xp,
    'trust_delta',v_trust,
    'bond_xp',v_rel.bond_xp,
    'bond_level',v_rel.bond_level,
    'trust_score',v_rel.trust_score,
    'interactions_completed',v_rel.interactions_completed,
    'virtual_currency_reward',0,
    'real_money',false,
    'replayed',false
  );

  insert into public.tgg_world_household_action_log(user_id,household_id,member_id,action_type,bond_xp_delta,trust_delta,idempotency_key,result)
  values(v_uid,v_household.id,v_member.id,v_action,v_xp,v_trust,v_key,v_result);

  return v_result;
exception
  when unique_violation then
    select * into v_existing from public.tgg_world_household_action_log where user_id=v_uid and idempotency_key=v_key;
    if found then return v_existing.result || jsonb_build_object('replayed',true); end if;
    raise;
end
$function$


-- [40000000437] function private.tgg_world_v11_household_add_member_impl(p_household_id uuid, p_member_user_id uuid, p_npc_key text, p_display_name text, p_relationship_role text)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_household_add_member_impl(p_household_id uuid, p_member_user_id uuid DEFAULT NULL::uuid, p_npc_key text DEFAULT NULL::text, p_display_name text DEFAULT NULL::text, p_relationship_role text DEFAULT 'friend'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
  v_status text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if not exists(select 1 from public.tgg_world_households where id=p_household_id and owner_user_id=v_uid) then raise exception 'HOUSEHOLD_OWNER_REQUIRED' using errcode='42501'; end if;
  if p_relationship_role not in ('partner','child','parent','sibling','relative','roommate','friend','dependent') then raise exception 'RELATIONSHIP_ROLE_INVALID'; end if;
  if num_nonnulls(p_member_user_id,nullif(btrim(coalesce(p_npc_key,'')),''),nullif(btrim(coalesce(p_display_name,'')),''))=0 then raise exception 'HOUSEHOLD_MEMBER_IDENTITY_REQUIRED'; end if;

  v_status := case when p_member_user_id is not null and p_member_user_id<>v_uid then 'invited' else 'active' end;
  insert into public.tgg_world_household_members(household_id,added_by_user_id,member_user_id,npc_key,display_name,relationship_role,status)
  values(p_household_id,v_uid,p_member_user_id,nullif(btrim(coalesce(p_npc_key,'')),''),nullif(btrim(coalesce(p_display_name,'')),''),p_relationship_role,v_status)
  returning id into v_id;

  return jsonb_build_object('ok',true,'member_id',v_id,'status',v_status,'requires_acceptance',v_status='invited');
end
$function$


-- [40000000438] function private.tgg_world_v11_household_create_impl(p_name text, p_home_property_id uuid, p_visibility text)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_household_create_impl(p_name text, p_home_property_id uuid DEFAULT NULL::uuid, p_visibility text DEFAULT 'private'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
  v_stage text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_name,''))) not between 1 and 80 then raise exception 'HOUSEHOLD_NAME_INVALID'; end if;
  if coalesce(p_visibility,'private') not in ('private','friends','crew') then raise exception 'HOUSEHOLD_VISIBILITY_INVALID'; end if;
  if p_home_property_id is not null and not exists(select 1 from public.tgg_world_properties where id=p_home_property_id and owner_user_id=v_uid) then raise exception 'HOME_PROPERTY_NOT_OWNED'; end if;

  insert into public.tgg_world_households(owner_user_id,name,home_property_id,visibility)
  values(v_uid,btrim(p_name),p_home_property_id,coalesce(p_visibility,'private'))
  returning id into v_id;

  select stage_name into v_stage from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  insert into public.tgg_world_household_members(household_id,added_by_user_id,member_user_id,display_name,relationship_role,status)
  values(v_id,v_uid,v_uid,coalesce(v_stage,'Player'),'self','active');

  return jsonb_build_object('ok',true,'household_id',v_id,'name',btrim(p_name),'visibility',coalesce(p_visibility,'private'));
end
$function$


-- [40000000439] function private.tgg_world_v11_household_gameplay_bundle_impl()
CREATE OR REPLACE FUNCTION private.tgg_world_v11_household_gameplay_bundle_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'version','WORLD-V11.2-HOUSEHOLD-GAMEPLAY-1.0',
    'actions',jsonb_build_array(
      jsonb_build_object('key','hangout','label','Hang Out','bond_xp',25,'trust',3),
      jsonb_build_object('key','meal','label','Share a Meal','bond_xp',18,'trust',2),
      jsonb_build_object('key','studio_session','label','Studio Session','bond_xp',30,'trust',2),
      jsonb_build_object('key','workout','label','Work Out','bond_xp',22,'trust',2),
      jsonb_build_object('key','call','label','Call','bond_xp',15,'trust',2),
      jsonb_build_object('key','support','label','Show Support','bond_xp',35,'trust',5),
      jsonb_build_object('key','celebrate','label','Celebrate','bond_xp',28,'trust',4),
      jsonb_build_object('key','chore','label','Handle a Chore','bond_xp',20,'trust',2)
    ),
    'relationships',coalesce((
      select jsonb_agg(jsonb_build_object(
        'member_id',r.member_id,
        'display_name',coalesce(m.display_name,m.relationship_role),
        'relationship_role',m.relationship_role,
        'is_npc',m.member_user_id is null,
        'bond_xp',r.bond_xp,
        'bond_level',r.bond_level,
        'trust_score',r.trust_score,
        'interactions_completed',r.interactions_completed,
        'last_action_type',r.last_action_type,
        'last_interaction_at',r.last_interaction_at
      ) order by r.bond_level desc,r.bond_xp desc)
      from public.tgg_world_household_relationships r
      join public.tgg_world_household_members m on m.id=r.member_id
      where r.user_id=v_uid
    ),'[]'::jsonb),
    'recent_actions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',l.id,
        'member_id',l.member_id,
        'display_name',coalesce(m.display_name,m.relationship_role),
        'action_type',l.action_type,
        'bond_xp_delta',l.bond_xp_delta,
        'trust_delta',l.trust_delta,
        'created_at',l.created_at
      ) order by l.created_at desc)
      from (
        select * from public.tgg_world_household_action_log
        where user_id=v_uid order by created_at desc limit 25
      ) l join public.tgg_world_household_members m on m.id=l.member_id
    ),'[]'::jsonb),
    'real_money',false
  );
end
$function$


-- [40000000440] function private.tgg_world_v11_household_invite_creator_impl(p_household_id uuid, p_creator_id uuid, p_relationship_role text)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_household_invite_creator_impl(p_household_id uuid, p_creator_id uuid, p_relationship_role text DEFAULT 'friend'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_target_uid uuid;
  v_name text;
  v_existing public.tgg_world_household_members%rowtype;
  v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if not exists(select 1 from public.tgg_world_households where id=p_household_id and owner_user_id=v_uid) then raise exception 'HOUSEHOLD_OWNER_REQUIRED' using errcode='42501'; end if;
  if p_relationship_role not in ('partner','parent','sibling','relative','roommate','friend') then raise exception 'REAL_USER_RELATIONSHIP_ROLE_INVALID'; end if;

  select user_id,coalesce(display_name,handle,'Creator') into v_target_uid,v_name
  from public.tgg_creator_profiles
  where id=p_creator_id and is_public=true
  limit 1;
  if v_target_uid is null or v_target_uid=v_uid then raise exception 'CREATOR_NOT_AVAILABLE'; end if;

  select * into v_existing
  from public.tgg_world_household_members
  where household_id=p_household_id and member_user_id=v_target_uid and status<>'archived'
  limit 1;
  if found then
    return jsonb_build_object('ok',true,'member_id',v_existing.id,'status',v_existing.status,'replayed',true,'display_name',v_existing.display_name);
  end if;

  insert into public.tgg_world_household_members(household_id,added_by_user_id,member_user_id,display_name,relationship_role,status)
  values(p_household_id,v_uid,v_target_uid,v_name,p_relationship_role,'invited')
  returning id into v_id;

  return jsonb_build_object('ok',true,'member_id',v_id,'status','invited','requires_acceptance',true,'display_name',v_name,'replayed',false);
end
$function$


-- [40000000441] function private.tgg_world_v11_instrument_session_impl(p_instrument_key text, p_session_type text, p_duration_seconds integer, p_bpm numeric, p_musical_key text, p_score numeric, p_studio_project_id uuid, p_source_asset_id uuid, p_metadata jsonb, p_idempotency_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_instrument_session_impl(p_instrument_key text, p_session_type text, p_duration_seconds integer, p_bpm numeric DEFAULT NULL::numeric, p_musical_key text DEFAULT NULL::text, p_score numeric DEFAULT NULL::numeric, p_studio_project_id uuid DEFAULT NULL::uuid, p_source_asset_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_session uuid;
  v_xp bigint;
  v_credited_seconds integer;
  v_progress public.tgg_world_instrument_progress%rowtype;
  v_existing public.tgg_world_instrument_sessions%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_idempotency_key,''))) not between 8 and 120 then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;
  select * into v_existing from public.tgg_world_instrument_sessions where user_id=v_uid and idempotency_key=btrim(p_idempotency_key);
  if found then
    return jsonb_build_object('ok',true,'session_id',v_existing.id,'instrument_key',v_existing.instrument_key,'replayed',true);
  end if;
  if not exists(select 1 from public.tgg_world_instrument_catalog where instrument_key=p_instrument_key and enabled=true) then raise exception 'INSTRUMENT_NOT_FOUND'; end if;
  if p_session_type not in ('practice','recording','jam','live','performance') then raise exception 'SESSION_TYPE_INVALID'; end if;
  if p_duration_seconds not between 1 and 21600 then raise exception 'SESSION_DURATION_INVALID'; end if;
  if p_bpm is not null and (p_bpm<20 or p_bpm>300) then raise exception 'BPM_INVALID'; end if;
  if p_score is not null and (p_score<0 or p_score>100) then raise exception 'SCORE_INVALID'; end if;
  if jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))<>'object' or char_length(coalesce(p_metadata,'{}'::jsonb)::text)>8000 then raise exception 'SESSION_METADATA_INVALID'; end if;
  if p_studio_project_id is not null and not exists(select 1 from public.tgg_studio_projects where id=p_studio_project_id and user_id=v_uid) then raise exception 'STUDIO_PROJECT_NOT_OWNED'; end if;

  v_credited_seconds := least(p_duration_seconds,3600);
  v_xp := greatest(1,ceil(v_credited_seconds/60.0)::bigint)
    + coalesce(floor(p_score/10)::bigint,0)
    + case when p_session_type in ('live','performance') then 15 else 0 end;

  insert into public.tgg_world_instrument_sessions(user_id,instrument_key,studio_project_id,session_type,duration_seconds,bpm,musical_key,score,source_asset_id,metadata,idempotency_key)
  values(v_uid,p_instrument_key,p_studio_project_id,p_session_type,p_duration_seconds,p_bpm,nullif(btrim(coalesce(p_musical_key,'')),''),p_score,p_source_asset_id,coalesce(p_metadata,'{}'::jsonb),btrim(p_idempotency_key))
  returning id into v_session;

  insert into public.tgg_world_instrument_progress(user_id,instrument_key,xp,level,practice_seconds,sessions_completed,performances_completed,best_score,updated_at)
  values(v_uid,p_instrument_key,v_xp,greatest(1,floor(sqrt(v_xp::numeric/100.0))::int+1),case when p_session_type='practice' then v_credited_seconds else 0 end,1,case when p_session_type in ('live','performance') then 1 else 0 end,p_score,now())
  on conflict(user_id,instrument_key) do update set
    xp=public.tgg_world_instrument_progress.xp+excluded.xp,
    level=greatest(public.tgg_world_instrument_progress.level,floor(sqrt((public.tgg_world_instrument_progress.xp+excluded.xp)::numeric/100.0))::int+1),
    practice_seconds=public.tgg_world_instrument_progress.practice_seconds+excluded.practice_seconds,
    sessions_completed=public.tgg_world_instrument_progress.sessions_completed+1,
    performances_completed=public.tgg_world_instrument_progress.performances_completed+excluded.performances_completed,
    best_score=case when excluded.best_score is null then public.tgg_world_instrument_progress.best_score when public.tgg_world_instrument_progress.best_score is null then excluded.best_score else greatest(public.tgg_world_instrument_progress.best_score,excluded.best_score) end,
    updated_at=now()
  returning * into v_progress;

  return jsonb_build_object('ok',true,'session_id',v_session,'instrument_key',p_instrument_key,'xp_awarded',v_xp,'credited_seconds',v_credited_seconds,'progress',to_jsonb(v_progress),'virtual_progression',true,'real_money',false,'replayed',false);
exception
  when unique_violation then
    select * into v_existing from public.tgg_world_instrument_sessions where user_id=v_uid and idempotency_key=btrim(p_idempotency_key);
    if found then return jsonb_build_object('ok',true,'session_id',v_existing.id,'instrument_key',v_existing.instrument_key,'replayed',true); end if;
    raise;
end
$function$


-- [40000000442] function private.tgg_world_v11_loadout_save_impl(p_loadout_id uuid, p_name text, p_slots jsonb, p_activate boolean)
CREATE OR REPLACE FUNCTION private.tgg_world_v11_loadout_save_impl(p_loadout_id uuid, p_name text, p_slots jsonb, p_activate boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
  v_slot text;
  v_ref text;
  v_key text;
  v_custom uuid;
  v_catalog_slot text;
  v_custom_slot text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_name,''))) not between 1 and 60 then raise exception 'LOADOUT_NAME_INVALID'; end if;
  if jsonb_typeof(coalesce(p_slots,'{}'::jsonb))<>'object' or char_length(coalesce(p_slots,'{}'::jsonb)::text)>8000 then raise exception 'LOADOUT_SLOTS_INVALID'; end if;

  for v_slot,v_ref in select key,value from jsonb_each_text(coalesce(p_slots,'{}'::jsonb))
  loop
    if v_slot not in ('outfit','top','bottom','shoes','outerwear','headwear','accessory','jewelry','instrument') then raise exception 'LOADOUT_SLOT_INVALID'; end if;

    if v_ref like 'catalog:%' then
      v_key := substr(v_ref,9);
      select c.slot_key into v_catalog_slot
      from public.tgg_world_shop_catalog c
      join public.tgg_world_inventory i on i.item_key=c.item_key and i.user_id=v_uid and i.quantity>0
      where c.item_key=v_key and c.enabled=true
      limit 1;
      if v_catalog_slot is null or v_catalog_slot<>v_slot then raise exception 'CATALOG_ITEM_NOT_OWNED_OR_SLOT_MISMATCH'; end if;
    elsif v_ref like 'custom:%' then
      begin
        v_custom := substr(v_ref,8)::uuid;
      exception
        when invalid_text_representation then
          raise exception 'CUSTOM_ITEM_REFERENCE_INVALID';
      end;
      select slot_key into v_custom_slot from public.tgg_world_custom_style_items where id=v_custom and user_id=v_uid;
      if v_custom_slot is null or v_custom_slot<>v_slot then raise exception 'CUSTOM_ITEM_NOT_OWNED_OR_SLOT_MISMATCH'; end if;
    else
      raise exception 'LOADOUT_REFERENCE_INVALID';
    end if;
  end loop;

  if coalesce(p_activate,true) then
    update public.tgg_world_style_loadouts set active=false,updated_at=now() where user_id=v_uid and active=true;
  end if;

  if p_loadout_id is null then
    insert into public.tgg_world_style_loadouts(user_id,name,slots,active)
    values(v_uid,btrim(p_name),coalesce(p_slots,'{}'::jsonb),coalesce(p_activate,true))
    returning id into v_id;
  else
    update public.tgg_world_style_loadouts
    set name=btrim(p_name),slots=coalesce(p_slots,'{}'::jsonb),active=coalesce(p_activate,active),updated_at=now()
    where id=p_loadout_id and user_id=v_uid
    returning id into v_id;
    if v_id is null then raise exception 'LOADOUT_NOT_FOUND'; end if;
  end if;

  return jsonb_build_object('ok',true,'loadout_id',v_id,'active',coalesce(p_activate,true),'slots',coalesce(p_slots,'{}'::jsonb));
end
$function$


-- [40000000443] function private.tgg_world_v12_accept_career_contract_impl(p_contract_key text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v12_accept_career_contract_impl(p_contract_key text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_contract public.tgg_world_career_contracts%rowtype;
  v_state public.tgg_world_character_contracts%rowtype;
  v_rep integer:=0;
  v_unmet jsonb:='[]'::jsonb;
  v_action text;
  v_result jsonb;
  v_previous_runs integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_contract_key,'')),'') is null then raise exception 'CONTRACT_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;

  select result into v_result from private.tgg_world_v12_contract_actions where user_id=v_uid and idempotency_key=p_idempotency_key limit 1;
  if v_result is not null then return v_result||jsonb_build_object('idempotent',true); end if;

  select * into v_char from public.world_characters where user_id=v_uid and character_status='active' order by updated_at desc limit 1;
  if v_char.id is null then raise exception 'WORLD_CHARACTER_REQUIRED' using errcode='22023'; end if;
  if nullif(v_char.active_career,'') is null then raise exception 'ACTIVE_CAREER_REQUIRED' using errcode='22023'; end if;

  select * into v_contract from public.tgg_world_career_contracts where contract_key=p_contract_key and enabled=true;
  if v_contract.contract_key is null then raise exception 'CONTRACT_NOT_FOUND' using errcode='22023'; end if;
  if v_contract.career_key<>v_char.active_career then raise exception 'CONTRACT_CAREER_MISMATCH' using errcode='22023'; end if;

  v_rep:=coalesce((select reputation from public.tgg_world_career_reputation where character_id=v_char.id and career_key=v_char.active_career),0);
  if v_rep<v_contract.reputation_required then raise exception 'CAREER_REPUTATION_REQUIRED:%',v_contract.reputation_required using errcode='22023'; end if;

  select coalesce(jsonb_agg(jsonb_build_object('chain_key',s.chain_key,'step_order',s.step_order,'condition',s.unlock_condition)),'[]'::jsonb)
  into v_unmet
  from public.tgg_world_contract_chain_steps s
  where s.contract_key=v_contract.contract_key
    and (
      (s.unlock_condition ? 'previous_contract' and not exists(
        select 1 from public.tgg_world_character_contracts pc
        where pc.character_id=v_char.id and pc.contract_key=s.unlock_condition->>'previous_contract' and pc.status='completed'
      ))
      or (s.unlock_condition ? 'reputation' and v_rep<coalesce((s.unlock_condition->>'reputation')::integer,0))
      or (s.unlock_condition ? 'relationship_contact' and coalesce((
        select r.trust_score from public.tgg_world_contact_relationships r
        where r.character_id=v_char.id and r.contact_key=s.unlock_condition->>'relationship_contact'
      ),0)<coalesce((s.unlock_condition->>'trust_score')::integer,0))
    );
  if jsonb_array_length(v_unmet)>0 then raise exception 'CONTRACT_CHAIN_LOCKED' using errcode='22023'; end if;

  select * into v_state from public.tgg_world_character_contracts where character_id=v_char.id and contract_key=v_contract.contract_key for update;
  if v_state.id is null then
    insert into public.tgg_world_character_contracts(character_id,contract_key,status,progress,accepted_at,updated_at)
    values(v_char.id,v_contract.contract_key,'active','{}'::jsonb,now(),now()) returning * into v_state;
    v_action:='accept';
  elsif v_state.status='active' then
    v_action:='resume';
  elsif v_state.status='completed' and not v_contract.repeatable then
    v_action:='already_completed';
  elsif v_state.status='completed' and v_contract.repeatable then
    v_previous_runs:=coalesce((v_state.progress->>'_runs_completed')::integer,0)+1;
    update public.tgg_world_character_contracts
    set status='active',
        progress=jsonb_build_object('_runs_completed',v_previous_runs,'_last_completed_at',v_state.completed_at),
        accepted_at=now(),completed_at=null,updated_at=now()
    where id=v_state.id returning * into v_state;
    v_action:='restart';
  elsif v_state.status='abandoned' then
    update public.tgg_world_character_contracts
    set status='active',
        progress=jsonb_build_object('_resumed_from','abandoned','_resumed_at',now()),
        accepted_at=now(),completed_at=null,updated_at=now()
    where id=v_state.id returning * into v_state;
    v_action:='resume';
  else
    raise exception 'CONTRACT_STATE_INVALID' using errcode='22023';
  end if;

  v_result:=jsonb_build_object(
    'ok',true,'version','WORLD-V12.1-CAREER-BRIDGE','contract_id',v_state.id,'contract_key',v_contract.contract_key,
    'title',v_contract.title,'career_key',v_contract.career_key,'status',v_state.status,'action',v_action,
    'progress',v_state.progress,'objectives',v_contract.objectives,'rewards',v_contract.rewards,'repeatable',v_contract.repeatable,
    'career_reputation',v_rep,'idempotent',false
  );
  insert into private.tgg_world_v12_contract_actions(user_id,character_id,contract_key,action_type,idempotency_key,result)
  values(v_uid,v_char.id,v_contract.contract_key,v_action,p_idempotency_key,v_result);
  return v_result;
end
$function$


-- [40000000444] function private.tgg_world_v12_accept_contact_offer_impl(p_offer_id uuid, p_idempotency_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v12_accept_contact_offer_impl(p_offer_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid(); v_offer public.tgg_world_contact_offers%rowtype; v_contract_key text; v_contract jsonb; v_contact public.tgg_world_contacts%rowtype; v_result jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_offer_id is null then raise exception 'OFFER_ID_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  select * into v_offer from public.tgg_world_contact_offers where id=p_offer_id and user_id=v_uid for update;
  if v_offer.id is null then raise exception 'OFFER_NOT_FOUND' using errcode='22023'; end if;
  if v_offer.status='accepted' then return jsonb_build_object('ok',true,'version','WORLD-V12.2-RELATIONSHIP-OFFERS','offer_id',v_offer.id,'status','accepted','contract_key',v_offer.terms->>'contract_key','idempotent',true); end if;
  if v_offer.status<>'pending' then raise exception 'OFFER_NOT_PENDING' using errcode='22023'; end if;
  if v_offer.expires_at is not null and v_offer.expires_at<now() then update public.tgg_world_contact_offers set status='expired',responded_at=now() where id=v_offer.id; raise exception 'OFFER_EXPIRED' using errcode='22023'; end if;
  v_contract_key:=nullif(v_offer.terms->>'contract_key','');
  if v_contract_key is null then raise exception 'OFFER_CONTRACT_MISSING' using errcode='22023'; end if;
  v_contract:=private.tgg_world_v12_accept_career_contract_impl(v_contract_key,'offer:'||v_offer.id::text||':'||p_idempotency_key);
  update public.tgg_world_contact_offers set status='accepted',responded_at=now(),terms=terms||jsonb_build_object('accepted_via','WORLD-V12.2','accepted_at',now()) where id=v_offer.id;
  select * into v_contact from public.tgg_world_contacts where id=v_offer.contact_id;
  insert into public.tgg_world_contact_messages(user_id,contact_id,direction,message_type,body,payload)
  values(v_uid,v_offer.contact_id,'system','offer','Offer accepted: '||v_offer.title,jsonb_build_object('offer_id',v_offer.id,'contract_key',v_contract_key,'source','WORLD-V12.2'));
  insert into public.tgg_world_notifications(user_id,notification_type,title,body,action_type,action_payload,priority)
  values(v_uid,'contact','Offer accepted',v_offer.title,'open',jsonb_build_object('surface','artist-world','contract_key',v_contract_key,'contact_key',v_contact.contact_key),'normal');
  v_result:=jsonb_build_object('ok',true,'version','WORLD-V12.2-RELATIONSHIP-OFFERS','offer_id',v_offer.id,'status','accepted','contract_key',v_contract_key,'contract',v_contract,'idempotent',false);
  return v_result;
end
$function$


-- [40000000445] function private.tgg_world_v12_book_show(p_contact_key text, p_title text, p_starts_at timestamp with time zone, p_project_id uuid, p_session_id uuid, p_idempotency_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v12_book_show(p_contact_key text, p_title text, p_starts_at timestamp with time zone, p_project_id uuid, p_session_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_character_id uuid;
  v_player record;
  v_contact record;
  v_rel record;
  v_event_id uuid;
  v_booking_id uuid;
  v_existing private.tgg_world_v12_show_bookings%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_title,'')),'') is null or length(p_title)>120 then raise exception 'SHOW_TITLE_REQUIRED' using errcode='22023'; end if;
  if p_starts_at is null or p_starts_at<now()-interval '15 minutes' or p_starts_at>now()+interval '180 days' then raise exception 'INVALID_SHOW_TIME' using errcode='22023'; end if;

  select * into v_existing from private.tgg_world_v12_show_bookings where user_id=v_uid and idempotency_key=p_idempotency_key limit 1;
  if found then return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','booking_id',v_existing.id,'event_id',v_existing.event_id,'status',v_existing.status,'idempotent',true); end if;

  select id into v_character_id from public.world_characters where user_id=v_uid and character_status='active' order by updated_at desc limit 1;
  if v_character_id is null then raise exception 'WORLD_CHARACTER_REQUIRED' using errcode='22023'; end if;
  select * into v_player from public.tgg_world_players where user_id=v_uid limit 1;
  if not found then raise exception 'WORLD_PLAYER_REQUIRED' using errcode='22023'; end if;

  select * into v_contact from public.tgg_world_industry_contacts where contact_key=p_contact_key and enabled=true;
  if not found then raise exception 'CONTACT_NOT_FOUND' using errcode='22023'; end if;
  if lower(v_contact.role_title) not like '%promoter%' and lower(v_contact.role_title) not like '%booking%' and lower(v_contact.role_title) not like '%director%' and lower(v_contact.role_title) not like '%a&r%' then
    raise exception 'CONTACT_CANNOT_BOOK_SHOWS' using errcode='22023';
  end if;
  if v_player.reputation<v_contact.reputation_required then raise exception 'REPUTATION_REQUIRED:%',v_contact.reputation_required using errcode='22023'; end if;

  select * into v_rel from public.tgg_world_contact_relationships where character_id=v_character_id and contact_key=p_contact_key;
  if not found or v_rel.meetings_completed<1 then raise exception 'MEET_CONTACT_FIRST' using errcode='22023'; end if;

  insert into public.tgg_world_events(host_user_id,event_type,title,status,starts_at,project_id,session_id,visibility,metadata)
  values(v_uid,'concert',btrim(p_title),'scheduled',p_starts_at,p_project_id,p_session_id,'public',
    jsonb_build_object('world_layer','v12','booking_contact',p_contact_key,'booking_type','industry_show'))
  returning id into v_event_id;

  insert into public.tgg_world_event_participants(event_id,user_id,role,joined_at,metadata)
  values(v_event_id,v_uid,'performer',now(),jsonb_build_object('world_layer','v12'))
  on conflict do nothing;

  insert into private.tgg_world_v12_show_bookings(user_id,character_id,contact_key,event_id,title,starts_at,project_id,session_id,idempotency_key,metadata)
  values(v_uid,v_character_id,p_contact_key,v_event_id,btrim(p_title),p_starts_at,p_project_id,p_session_id,p_idempotency_key,
    jsonb_build_object('contact_trust_at_booking',v_rel.trust_score,'player_reputation_at_booking',v_player.reputation))
  returning id into v_booking_id;

  update public.tgg_world_contact_relationships set relationship_xp=relationship_xp+10,trust_score=least(100,trust_score+2),last_interaction_at=now(),updated_at=now()
  where character_id=v_character_id and contact_key=p_contact_key;

  return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','booking_id',v_booking_id,'event_id',v_event_id,'status','booked','starts_at',p_starts_at,'idempotent',false);
end $function$


-- [40000000446] function private.tgg_world_v12_career_industry_bundle_impl()
