-- [40000000447] function private.tgg_world_v12_close_offer_on_contract_completion()
CREATE OR REPLACE FUNCTION private.tgg_world_v12_close_offer_on_contract_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
begin
  if new.status='completed' and old.status is distinct from 'completed' then
    select wc.user_id into v_uid
    from public.world_characters wc
    where wc.id=new.character_id;

    if v_uid is not null then
      update public.tgg_world_contact_offers o
      set status='completed',
          terms=coalesce(o.terms,'{}'::jsonb)||jsonb_build_object(
            'contract_completed_via','WORLD-V12.3',
            'contract_completed_at',coalesce(new.completed_at,now()),
            'character_contract_id',new.id
          )
      where o.user_id=v_uid
        and o.status='accepted'
        and o.terms->>'source'='WORLD-V12.2-CONTACT-OFFER'
        and o.terms->>'contract_key'=new.contract_key;
    end if;
  end if;
  return new;
end
$function$


-- [40000000448] function private.tgg_world_v12_contact_offers_bundle()
CREATE OR REPLACE FUNCTION private.tgg_world_v12_contact_offers_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  update public.tgg_world_contact_offers set status='expired',responded_at=coalesce(responded_at,now()) where user_id=v_uid and status='pending' and expires_at is not null and expires_at<now();
  return jsonb_build_object('ok',true,'version','WORLD-V12.2-RELATIONSHIP-OFFERS','offers',coalesce((
    select jsonb_agg(jsonb_build_object('offer_id',o.id,'status',o.status,'offer_type',o.offer_type,'title',o.title,'body',o.body,'terms',o.terms,'expires_at',o.expires_at,'created_at',o.created_at,'responded_at',o.responded_at,'contact_key',c.contact_key,'contact_name',c.display_name) order by o.created_at desc)
    from (select * from public.tgg_world_contact_offers where user_id=v_uid order by created_at desc limit 20) o join public.tgg_world_contacts c on c.id=o.contact_id
  ),'[]'::jsonb));
end
$function$


