-- [40000000453] function private.tgg_world_v12_generate_contact_offer(p_contact_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v12_generate_contact_offer(p_contact_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_ind public.tgg_world_industry_contacts%rowtype;
  v_contact public.tgg_world_contacts%rowtype;
  v_rel public.tgg_world_contact_relationships%rowtype;
  v_contract public.tgg_world_career_contracts%rowtype;
  v_career_rep integer:=0;
  v_offer public.tgg_world_contact_offers%rowtype;
  v_offer_type text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_char from public.world_characters where user_id=v_uid and character_status='active' order by updated_at desc limit 1;
  if v_char.id is null or nullif(v_char.active_career,'') is null then return null; end if;
  select * into v_ind from public.tgg_world_industry_contacts where contact_key=p_contact_key and enabled=true;
  if v_ind.contact_key is null then return null; end if;
  select * into v_contact from public.tgg_world_contacts where contact_key=p_contact_key;
  if v_contact.id is null then return null; end if;
  select * into v_rel from public.tgg_world_contact_relationships where character_id=v_char.id and contact_key=p_contact_key;
  if v_rel.character_id is null or v_rel.meetings_completed<1 or v_rel.trust_score<8 then return null; end if;
  v_career_rep:=coalesce((select reputation from public.tgg_world_career_reputation where character_id=v_char.id and career_key=v_char.active_career),0);

  select c.* into v_contract
  from jsonb_array_elements_text(coalesce(v_ind.unlocks->'contracts','[]'::jsonb)) with ordinality u(contract_key,ord)
  join public.tgg_world_career_contracts c on c.contract_key=u.contract_key and c.enabled=true
  left join public.tgg_world_character_contracts cc on cc.character_id=v_char.id and cc.contract_key=c.contract_key
  where c.career_key=v_char.active_career
    and v_career_rep>=c.reputation_required
    and (cc.id is null or cc.status='abandoned' or (cc.status='completed' and c.repeatable))
    and not exists(
      select 1 from public.tgg_world_contract_chain_steps s
      where s.contract_key=c.contract_key and (
        (s.unlock_condition ? 'previous_contract' and not exists(
          select 1 from public.tgg_world_character_contracts pc
          where pc.character_id=v_char.id and pc.contract_key=s.unlock_condition->>'previous_contract' and pc.status='completed'))
        or (s.unlock_condition ? 'reputation' and v_career_rep<coalesce((s.unlock_condition->>'reputation')::integer,0))
        or (s.unlock_condition ? 'relationship_contact' and coalesce((select r.trust_score from public.tgg_world_contact_relationships r where r.character_id=v_char.id and r.contact_key=s.unlock_condition->>'relationship_contact'),0)<coalesce((s.unlock_condition->>'trust_score')::integer,0))
      )
    )
  order by u.ord
  limit 1;
  if v_contract.contract_key is null then return null; end if;

  select * into v_offer from public.tgg_world_contact_offers
  where user_id=v_uid and status='pending' and terms->>'contract_key'=v_contract.contract_key
  order by created_at desc limit 1;
  if v_offer.id is not null then
    return jsonb_build_object('offer_id',v_offer.id,'status',v_offer.status,'title',v_offer.title,'contact_key',p_contact_key,'contract_key',v_contract.contract_key,'offer_type',v_offer.offer_type,'expires_at',v_offer.expires_at,'existing',true);
  end if;

  v_offer_type:=case v_contract.contract_type
    when 'showcase' then 'show_booking'
    when 'booking' then 'show_booking'
    when 'visual' then 'video_shoot'
    when 'service' then 'mix_master'
    when 'placement' then 'studio_session'
    when 'media' then 'promotion'
    when 'development' then 'management'
    when 'business' then 'management'
    else 'mission' end;

  insert into public.tgg_world_contact_offers(user_id,contact_id,offer_type,title,body,status,terms,expires_at)
  values(v_uid,v_contact.id,v_offer_type,v_contract.title,
         v_ind.display_name||' has an opportunity for your '||v_char.active_career||' career.','pending',
         jsonb_build_object('source','WORLD-V12.2-CONTACT-OFFER','contact_key',p_contact_key,'contract_key',v_contract.contract_key,'contract_type',v_contract.contract_type,'objectives',v_contract.objectives,'rewards',v_contract.rewards,'career_key',v_contract.career_key),
         now()+interval '7 days')
  returning * into v_offer;

  insert into public.tgg_world_contact_messages(user_id,contact_id,direction,message_type,body,payload)
  values(v_uid,v_contact.id,'inbound','offer',v_ind.display_name||': '||v_contract.title,
         jsonb_build_object('offer_id',v_offer.id,'contract_key',v_contract.contract_key,'source','WORLD-V12.2-CONTACT-OFFER'));
  insert into public.tgg_world_notifications(user_id,notification_type,title,body,action_type,action_payload,priority)
  values(v_uid,'contact','New industry offer',v_ind.display_name||' sent: '||v_contract.title,'open',jsonb_build_object('surface','artist-world','offer_id',v_offer.id,'contact_key',p_contact_key),'normal');

  return jsonb_build_object('offer_id',v_offer.id,'status','pending','title',v_offer.title,'contact_key',p_contact_key,'contract_key',v_contract.contract_key,'offer_type',v_offer.offer_type,'expires_at',v_offer.expires_at,'existing',false);
end
$function$


-- [40000000454] function private.tgg_world_v12_guard_contact_meeting()
CREATE OR REPLACE FUNCTION private.tgg_world_v12_guard_contact_meeting()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1 from private.tgg_world_v12_contact_meetings m
    where m.user_id=new.user_id
      and m.contact_key=new.contact_key
      and m.created_at>now()-interval '30 minutes'
  ) then
    raise exception 'CONTACT_MEETING_COOLDOWN' using errcode='P0001';
  end if;
  return new;
end $function$


-- [40000000455] function private.tgg_world_v12_guard_rap_battle()
CREATE OR REPLACE FUNCTION private.tgg_world_v12_guard_rap_battle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1 from private.tgg_world_v12_rap_battles b
    where b.user_id=new.user_id and b.status='live'
  ) then
    raise exception 'ACTIVE_BATTLE_EXISTS' using errcode='P0001';
  end if;
  if (select count(*) from private.tgg_world_v12_rap_battles b where b.user_id=new.user_id and b.created_at>now()-interval '1 hour')>=6 then
    raise exception 'BATTLE_HOURLY_LIMIT' using errcode='P0001';
  end if;
  return new;
end $function$


-- [40000000456] function private.tgg_world_v12_guard_show_booking()
CREATE OR REPLACE FUNCTION private.tgg_world_v12_guard_show_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select count(*) from private.tgg_world_v12_show_bookings b where b.user_id=new.user_id and b.created_at>now()-interval '24 hours')>=10 then
    raise exception 'SHOW_BOOKING_DAILY_LIMIT' using errcode='P0001';
  end if;
  if exists (
    select 1 from private.tgg_world_v12_show_bookings b
    where b.user_id=new.user_id
      and b.status='booked'
      and abs(extract(epoch from (b.starts_at-new.starts_at)))<5400
  ) then
    raise exception 'SHOW_BOOKING_TIME_CONFLICT' using errcode='P0001';
  end if;
  return new;
end $function$


-- [40000000457] function private.tgg_world_v12_health()
CREATE OR REPLACE FUNCTION private.tgg_world_v12_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object('ok',
    to_regclass('private.tgg_world_v12_contact_meetings') is not null and
    to_regclass('private.tgg_world_v12_show_bookings') is not null and
    to_regclass('private.tgg_world_v12_rap_battles') is not null and
    to_regclass('private.tgg_world_v12_rap_battle_rounds') is not null,
    'version','WORLD-V12-PERFORMANCE-INDUSTRY',
    'contacts_seeded',(select count(*) from public.tgg_world_industry_contacts where contact_key in ('contact-zara-stone','contact-kilo-verse')),
    'features',jsonb_build_array('industry_contact_meetings','concert_booking','concert_performance','npc_rap_battles','player_rap_battles','server_scored_rounds','bounded_virtual_progression')
  );
end $function$


-- [40000000458] function private.tgg_world_v12_industry_performance_bundle()
CREATE OR REPLACE FUNCTION private.tgg_world_v12_industry_performance_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_character_id uuid;
  v_rep bigint:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select id into v_character_id from public.world_characters where user_id=v_uid and character_status='active' order by updated_at desc limit 1;
  v_rep:=coalesce((select reputation from public.tgg_world_players where user_id=v_uid limit 1),0);
  return jsonb_build_object(
    'ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','character_ready',v_character_id is not null,'reputation',v_rep,
    'contacts',coalesce((select jsonb_agg(jsonb_build_object('contact_key',c.contact_key,'display_name',c.display_name,'role_title',c.role_title,'organization',c.organization,'location_key',c.location_key,'reputation_required',c.reputation_required,'available',v_rep>=c.reputation_required,'unlocks',c.unlocks,'relationship',case when r.character_id is null then null else jsonb_build_object('xp',r.relationship_xp,'level',r.relationship_level,'trust',r.trust_score,'meetings',r.meetings_completed,'successful_contracts',r.successful_contracts) end) order by c.reputation_required,c.display_name) from public.tgg_world_industry_contacts c left join public.tgg_world_contact_relationships r on r.character_id=v_character_id and r.contact_key=c.contact_key where c.enabled=true),'[]'::jsonb),
    'shows',coalesce((select jsonb_agg(jsonb_build_object('booking_id',b.id,'event_id',b.event_id,'title',b.title,'contact_key',b.contact_key,'status',b.status,'starts_at',b.starts_at,'performance_score',b.performance_score,'audience_gain',b.audience_gain,'reputation_gain',b.reputation_gain,'xp_gain',b.xp_gain) order by b.created_at desc) from private.tgg_world_v12_show_bookings b where b.user_id=v_uid),'[]'::jsonb),
    'battles',coalesce((select jsonb_agg(jsonb_build_object('battle_id',b.id,'event_id',b.event_id,'opponent',b.opponent_label,'status',b.status,'rounds_total',b.rounds_total,'rounds_completed',b.rounds_completed,'player_score',b.player_score,'opponent_score',b.opponent_score,'crowd_energy',b.crowd_energy,'winner_side',b.winner_side) order by b.created_at desc) from private.tgg_world_v12_rap_battles b where b.user_id=v_uid),'[]'::jsonb)
  );
end $function$


-- [40000000459] function private.tgg_world_v12_meet_industry_contact(p_contact_key text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v12_meet_industry_contact(p_contact_key text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid(); v_character_id uuid; v_rep bigint:=0; v_required integer; v_meeting_id uuid; v_rel record; v_existing jsonb; v_offer jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  select result into v_existing from private.tgg_world_v12_contact_meetings where user_id=v_uid and idempotency_key=p_idempotency_key limit 1;
  if v_existing is not null then return v_existing||jsonb_build_object('idempotent',true); end if;
  select id into v_character_id from public.world_characters where user_id=v_uid and character_status='active' order by updated_at desc limit 1;
  if v_character_id is null then raise exception 'WORLD_CHARACTER_REQUIRED' using errcode='22023'; end if;
  v_rep:=coalesce((select reputation from public.tgg_world_players where user_id=v_uid limit 1),0);
  select reputation_required into v_required from public.tgg_world_industry_contacts where contact_key=p_contact_key and enabled=true;
  if v_required is null then raise exception 'CONTACT_NOT_FOUND' using errcode='22023'; end if;
  if v_rep<v_required then raise exception 'REPUTATION_REQUIRED:%',v_required using errcode='22023'; end if;
  if exists(select 1 from private.tgg_world_v12_contact_meetings where user_id=v_uid and contact_key=p_contact_key and created_at>now()-interval '30 minutes') then raise exception 'CONTACT_MEETING_COOLDOWN' using errcode='22023'; end if;
  insert into public.tgg_world_contact_relationships(character_id,contact_key,relationship_xp,relationship_level,trust_score,meetings_completed,last_interaction_at,memory,updated_at)
  values(v_character_id,p_contact_key,20,1,8,1,now(),jsonb_build_object('last_meeting','v12_intro'),now())
  on conflict(character_id,contact_key) do update set relationship_xp=public.tgg_world_contact_relationships.relationship_xp+20,
    relationship_level=greatest(public.tgg_world_contact_relationships.relationship_level,1+((public.tgg_world_contact_relationships.relationship_xp+20)/100)),
    trust_score=least(100,public.tgg_world_contact_relationships.trust_score+5),meetings_completed=public.tgg_world_contact_relationships.meetings_completed+1,
    last_interaction_at=now(),memory=coalesce(public.tgg_world_contact_relationships.memory,'{}'::jsonb)||jsonb_build_object('last_meeting','v12_intro','last_meeting_at',now()),updated_at=now()
  returning relationship_xp,relationship_level,trust_score,meetings_completed into v_rel;
  insert into private.tgg_world_v12_contact_meetings(user_id,character_id,contact_key,relationship_xp_delta,trust_delta,idempotency_key)
  values(v_uid,v_character_id,p_contact_key,20,5,p_idempotency_key) returning id into v_meeting_id;
  v_offer:=private.tgg_world_v12_generate_contact_offer(p_contact_key);
  v_existing:=jsonb_build_object('ok',true,'version','WORLD-V12.2-RELATIONSHIP-OFFERS','meeting_id',v_meeting_id,'contact_key',p_contact_key,
    'relationship',jsonb_build_object('xp',v_rel.relationship_xp,'level',v_rel.relationship_level,'trust',v_rel.trust_score,'meetings',v_rel.meetings_completed),'offer',v_offer,'idempotent',false);
  update private.tgg_world_v12_contact_meetings set result=v_existing where id=v_meeting_id;
  return v_existing;
end
$function$


-- [40000000460] function private.tgg_world_v12_perform_show(p_booking_id uuid, p_idempotency_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v12_perform_show(p_booking_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_booking private.tgg_world_v12_show_bookings%rowtype;
  v_rep bigint:=0;
  v_trust integer:=0;
  v_jitter integer;
  v_score numeric;
  v_energy numeric;
  v_audience bigint;
  v_rep_gain bigint;
  v_xp bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  select * into v_booking from private.tgg_world_v12_show_bookings where id=p_booking_id and user_id=v_uid for update;
  if not found then raise exception 'SHOW_BOOKING_NOT_FOUND' using errcode='22023'; end if;
  if v_booking.status='completed' then return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','booking_id',v_booking.id,'event_id',v_booking.event_id,'status','completed','performance_score',v_booking.performance_score,'audience_gain',v_booking.audience_gain,'reputation_gain',v_booking.reputation_gain,'xp_gain',v_booking.xp_gain,'idempotent',true); end if;
  if v_booking.status<>'booked' then raise exception 'SHOW_NOT_ACTIVE' using errcode='22023'; end if;
  if v_booking.starts_at>now()+interval '30 minutes' then raise exception 'SHOW_NOT_STARTED_YET' using errcode='22023'; end if;
  v_rep:=coalesce((select reputation from public.tgg_world_players where user_id=v_uid limit 1),0);
  v_trust:=coalesce((select trust_score from public.tgg_world_contact_relationships where character_id=v_booking.character_id and contact_key=v_booking.contact_key),0);
  v_jitter:=(((hashtextextended(v_booking.id::text||':show',0)%21)+21)%21)::integer-10;
  v_score:=greatest(20,least(100,55+least(20,(v_rep/25)::integer)+least(12,(v_trust/8)::integer)+v_jitter));
  v_energy:=greatest(20,least(100,round((v_score+60+v_trust/2.0)/2)));
  v_audience:=greatest(20,round(v_energy*2+least(200,v_rep/5.0))::bigint);
  v_rep_gain:=greatest(3,round(v_score/12)::bigint);
  v_xp:=greatest(50,round(v_score*1.5)::bigint);
  update public.tgg_world_events set status='completed',ends_at=now(),updated_at=now(),metadata=metadata||jsonb_build_object('performance_score',v_score,'crowd_energy',v_energy) where id=v_booking.event_id and host_user_id=v_uid;
  insert into public.tgg_world_event_results(event_id,peak_audience,total_reactions,total_votes,crowd_energy,winner_user_id,result_payload,finalized_at)
  values(v_booking.event_id,v_audience::integer,0,0,v_energy,v_uid,jsonb_build_object('world_layer','v12','kind','concert','performance_score',v_score),now())
  on conflict(event_id) do update set peak_audience=excluded.peak_audience,crowd_energy=excluded.crowd_energy,winner_user_id=excluded.winner_user_id,result_payload=excluded.result_payload,finalized_at=excluded.finalized_at;
  update public.tgg_world_event_participants set score=v_score,left_at=now(),metadata=metadata||jsonb_build_object('performance_complete',true) where event_id=v_booking.event_id and user_id=v_uid;
  update public.tgg_world_players set xp=xp+v_xp,reputation=reputation+v_rep_gain,audience=audience+v_audience,updated_at=now() where user_id=v_uid;
  update public.tgg_world_contact_relationships set relationship_xp=relationship_xp+20,trust_score=least(100,trust_score+4),successful_contracts=successful_contracts+1,last_interaction_at=now(),updated_at=now() where character_id=v_booking.character_id and contact_key=v_booking.contact_key;
  update private.tgg_world_v12_show_bookings set status='completed',performance_score=v_score,audience_gain=v_audience,reputation_gain=v_rep_gain,xp_gain=v_xp,completed_at=now(),updated_at=now(),metadata=metadata||jsonb_build_object('completion_key',p_idempotency_key,'crowd_energy',v_energy) where id=v_booking.id;
  return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','booking_id',v_booking.id,'event_id',v_booking.event_id,'status','completed','performance_score',v_score,'crowd_energy',v_energy,'audience_gain',v_audience,'reputation_gain',v_rep_gain,'xp_gain',v_xp,'idempotent',false);
end $function$


-- [40000000461] function private.tgg_world_v12_play_rap_battle_round(p_battle_id uuid, p_idempotency_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v12_play_rap_battle_round(p_battle_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_battle private.tgg_world_v12_rap_battles%rowtype;
  v_player_rep bigint:=0;
  v_opp_rep bigint:=0;
  v_round integer;
  v_player_jitter integer;
  v_opp_jitter integer;
  v_player numeric;
  v_opp numeric;
  v_energy numeric;
  v_total_player numeric;
  v_total_opp numeric;
  v_winner text;
  v_rep_gain bigint:=0;
  v_xp_gain bigint:=0;
  v_audience_gain bigint:=0;
  v_existing record;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  select * into v_existing from private.tgg_world_v12_rap_battle_rounds where battle_id=p_battle_id and user_id=v_uid and idempotency_key=p_idempotency_key limit 1;
  if found then return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','battle_id',p_battle_id,'round_number',v_existing.round_number,'player_score',v_existing.player_score,'opponent_score',v_existing.opponent_score,'crowd_energy',v_existing.crowd_energy,'idempotent',true); end if;
  select * into v_battle from private.tgg_world_v12_rap_battles where id=p_battle_id and user_id=v_uid for update;
  if not found then raise exception 'BATTLE_NOT_FOUND' using errcode='22023'; end if;
  if v_battle.status='completed' then return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','battle_id',v_battle.id,'status','completed','player_score',v_battle.player_score,'opponent_score',v_battle.opponent_score,'winner_side',v_battle.winner_side,'idempotent',true); end if;
  if v_battle.status<>'live' then raise exception 'BATTLE_NOT_ACTIVE' using errcode='22023'; end if;
  v_round:=v_battle.rounds_completed+1;
  if v_round>v_battle.rounds_total then raise exception 'BATTLE_ROUNDS_COMPLETE' using errcode='22023'; end if;
  v_player_rep:=coalesce((select reputation from public.tgg_world_players where user_id=v_uid limit 1),0);
  if v_battle.opponent_user_id is not null then v_opp_rep:=coalesce((select reputation from public.tgg_world_players where user_id=v_battle.opponent_user_id limit 1),0); else v_opp_rep:=coalesce((v_battle.metadata->>'opponent_reputation_basis')::bigint,30); end if;
  v_player_jitter:=(((hashtextextended(v_battle.id::text||':p:'||v_round::text,0)%21)+21)%21)::integer-10;
  v_opp_jitter:=(((hashtextextended(v_battle.id::text||':o:'||v_round::text,0)%21)+21)%21)::integer-10;
  v_player:=greatest(10,least(100,55+least(25,(v_player_rep/20)::integer)+v_player_jitter));
  v_opp:=greatest(10,least(100,52+least(25,(v_opp_rep/20)::integer)+v_opp_jitter));
  v_energy:=greatest(25,least(100,round((v_player+v_opp)/2+8)));
  insert into private.tgg_world_v12_rap_battle_rounds(battle_id,user_id,round_number,player_score,opponent_score,crowd_energy,idempotency_key)
  values(v_battle.id,v_uid,v_round,v_player,v_opp,v_energy,p_idempotency_key);
  v_total_player:=v_battle.player_score+v_player;
  v_total_opp:=v_battle.opponent_score+v_opp;
  if v_round=v_battle.rounds_total then
    v_winner:=case when v_total_player>v_total_opp then 'player' when v_total_player<v_total_opp then 'opponent' else 'draw' end;
    v_rep_gain:=case when v_winner='player' then 12 when v_winner='draw' then 7 else 4 end;
    v_xp_gain:=case when v_winner='player' then 140 when v_winner='draw' then 95 else 65 end;
    v_audience_gain:=case when v_winner='player' then 90 when v_winner='draw' then 55 else 30 end;
    update private.tgg_world_v12_rap_battles set rounds_completed=v_round,player_score=v_total_player,opponent_score=v_total_opp,crowd_energy=case when rounds_completed=0 then v_energy else (crowd_energy*rounds_completed+v_energy)/(rounds_completed+1) end,status='completed',winner_side=v_winner,completed_at=now(),updated_at=now() where id=v_battle.id;
    update public.tgg_world_events set status='completed',ends_at=now(),updated_at=now(),metadata=metadata||jsonb_build_object('winner_side',v_winner,'player_score',v_total_player,'opponent_score',v_total_opp) where id=v_battle.event_id and host_user_id=v_uid;
    insert into public.tgg_world_event_results(event_id,peak_audience,total_reactions,total_votes,crowd_energy,winner_user_id,result_payload,finalized_at)
    values(v_battle.event_id,v_audience_gain::integer,0,0,v_energy,case when v_winner='player' then v_uid when v_winner='opponent' then v_battle.opponent_user_id else null end,jsonb_build_object('world_layer','v12','kind','rap_battle','winner_side',v_winner,'player_score',v_total_player,'opponent_score',v_total_opp),now())
    on conflict(event_id) do update set peak_audience=excluded.peak_audience,crowd_energy=excluded.crowd_energy,winner_user_id=excluded.winner_user_id,result_payload=excluded.result_payload,finalized_at=excluded.finalized_at;
    update public.tgg_world_event_participants set score=case when user_id=v_uid then v_total_player else v_total_opp end,left_at=now() where event_id=v_battle.event_id;
    update public.tgg_world_players set xp=xp+v_xp_gain,reputation=reputation+v_rep_gain,audience=audience+v_audience_gain,updated_at=now() where user_id=v_uid;
  else
    update private.tgg_world_v12_rap_battles set rounds_completed=v_round,player_score=v_total_player,opponent_score=v_total_opp,crowd_energy=case when rounds_completed=0 then v_energy else (crowd_energy*rounds_completed+v_energy)/(rounds_completed+1) end,updated_at=now() where id=v_battle.id;
  end if;
  return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','battle_id',v_battle.id,'round_number',v_round,'rounds_total',v_battle.rounds_total,'player_score',v_player,'opponent_score',v_opp,'crowd_energy',v_energy,'battle_player_total',v_total_player,'battle_opponent_total',v_total_opp,'status',case when v_round=v_battle.rounds_total then 'completed' else 'live' end,'winner_side',case when v_round=v_battle.rounds_total then v_winner else null end,'reputation_gain',v_rep_gain,'xp_gain',v_xp_gain,'audience_gain',v_audience_gain,'idempotent',false);
end $function$


-- [40000000462] function private.tgg_world_v12_reconcile_persisted_contract_objectives()
CREATE OR REPLACE FUNCTION private.tgg_world_v12_reconcile_persisted_contract_objectives()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_char record;
  v_state record;
  v_event record;
  v_result jsonb;
  v_credited integer := 0;
  v_completed integer := 0;
  v_scanned integer := 0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select wc.id, wc.active_career
  into v_char
  from public.world_characters wc
  where wc.user_id=v_uid
    and wc.character_status='active'
  order by wc.updated_at desc
  limit 1;

  if v_char.id is null then
    return jsonb_build_object(
      'ok',true,
      'version','WORLD-V12.4-PERSISTED-OBJECTIVE-RECONCILIATION',
      'character_present',false,
      'scanned',0,
      'credited',0,
      'completed',0
    );
  end if;

  for v_state in
    select cc.id as contract_id,
           cc.contract_key,
           cc.accepted_at,
           c.objectives
    from public.tgg_world_character_contracts cc
    join public.tgg_world_career_contracts c
      on c.contract_key=cc.contract_key
     and c.enabled=true
    where cc.character_id=v_char.id
      and cc.status='active'
      and c.career_key=v_char.active_career
    order by cc.accepted_at,cc.id
  loop
    if exists (
      select 1 from jsonb_array_elements(v_state.objectives) o
      where o->>'type'='radio_session'
    ) then
      for v_event in
        select r.id,r.published_at,r.title,r.show_type
        from public.tgg_radio_shows r
        where r.user_id=v_uid
          and r.status='published'
          and r.published_at is not null
          and r.published_at>=v_state.accepted_at
        order by r.published_at,r.id
      loop
        v_scanned:=v_scanned+1;
        v_result:=private.tgg_world_credit_contract_event(
          v_char.id,
          'radio_session',
          'radio_show_published',
          v_event.id::text,
          jsonb_build_object(
            'show_id',v_event.id,
            'title',v_event.title,
            'show_type',v_event.show_type,
            'published_at',v_event.published_at,
            'world_layer','v12.4'
          )
        );
        v_credited:=v_credited+coalesce((v_result->>'credited')::integer,0);
        v_completed:=v_completed+coalesce((v_result->>'completed')::integer,0);
      end loop;
    end if;

    if exists (
      select 1 from jsonb_array_elements(v_state.objectives) o
      where o->>'type'='metadata_review'
    ) then
      for v_event in
        select d.release_id,d.updated_at,d.primary_language,d.territories
        from public.tgg_distribution_release_metadata d
        where d.owner_user_id=v_uid
          and d.updated_at>=v_state.accepted_at
          and nullif(btrim(coalesce(d.label_name,'')),'') is not null
          and nullif(btrim(coalesce(d.copyright_line,'')),'') is not null
          and nullif(btrim(coalesce(d.publishing_line,'')),'') is not null
          and nullif(btrim(coalesce(d.primary_language,'')),'') is not null
          and jsonb_typeof(d.territories)='array'
          and jsonb_array_length(d.territories)>0
        order by d.updated_at,d.release_id
      loop
        v_scanned:=v_scanned+1;
        v_result:=private.tgg_world_credit_contract_event(
          v_char.id,
          'metadata_review',
          'distribution_metadata_review',
          v_event.release_id::text,
          jsonb_build_object(
            'release_id',v_event.release_id,
            'metadata_updated_at',v_event.updated_at,
            'primary_language',v_event.primary_language,
            'territory_count',jsonb_array_length(v_event.territories),
            'world_layer','v12.4'
          )
        );
        v_credited:=v_credited+coalesce((v_result->>'credited')::integer,0);
        v_completed:=v_completed+coalesce((v_result->>'completed')::integer,0);
      end loop;
    end if;

    if exists (
      select 1 from jsonb_array_elements(v_state.objectives) o
      where o->>'type'='rights_review'
    ) then
      for v_event in
        select d.release_id,d.rights_confirmed_at,d.updated_at
        from public.tgg_distribution_release_metadata d
        where d.owner_user_id=v_uid
          and d.rights_confirmed=true
          and d.rights_confirmed_at is not null
          and d.rights_confirmed_at>=v_state.accepted_at
          and nullif(btrim(coalesce(d.label_name,'')),'') is not null
          and nullif(btrim(coalesce(d.copyright_line,'')),'') is not null
          and nullif(btrim(coalesce(d.publishing_line,'')),'') is not null
          and jsonb_typeof(d.territories)='array'
          and jsonb_array_length(d.territories)>0
          and not exists (
            select 1
            from public.tgg_clearance_items ci
            where ci.owner_user_id=v_uid
              and ci.release_id=d.release_id
              and lower(coalesce(ci.permission_status,'needs_review'))
                  not in ('cleared','approved','licensed','not_required')
          )
        order by d.rights_confirmed_at,d.release_id
      loop
        v_scanned:=v_scanned+1;
        v_result:=private.tgg_world_credit_contract_event(
          v_char.id,
          'rights_review',
          'distribution_rights_review',
          v_event.release_id::text,
          jsonb_build_object(
            'release_id',v_event.release_id,
            'rights_confirmed_at',v_event.rights_confirmed_at,
            'metadata_updated_at',v_event.updated_at,
            'clearances_resolved',true,
            'world_layer','v12.4'
          )
        );
        v_credited:=v_credited+coalesce((v_result->>'credited')::integer,0);
        v_completed:=v_completed+coalesce((v_result->>'completed')::integer,0);
      end loop;
    end if;

    if exists (
      select 1 from jsonb_array_elements(v_state.objectives) o
      where o->>'type'='producer_session'
    ) then
      for v_event in
        select sl.id as launch_id,
               sl.project_id,
               sl.session_id,
               sl.updated_at
        from public.tgg_world_session_launches sl
        join public.tgg_beat_patterns bp
          on bp.id=sl.session_id
         and bp.project_id=sl.project_id
         and bp.user_id=v_uid
        join public.tgg_studio_projects sp
          on sp.id=bp.project_id
         and sp.user_id=v_uid
        where sl.user_id=v_uid
          and sl.status='saved'
          and sl.session_id is not null
          and sl.project_id is not null
          and coalesce(sl.handoff_payload->>'tool',sl.requested_tool)='beat'
          and coalesce((sl.handoff_payload->>'creator_session_provenance_verified')::boolean,false)=true
          and sl.updated_at>=v_state.accepted_at
        order by sl.updated_at,sl.id
      loop
        v_scanned:=v_scanned+1;
        v_result:=private.tgg_world_credit_contract_event(
          v_char.id,
          'producer_session',
          'world_beat_provenance_save',
          v_event.session_id::text,
          jsonb_build_object(
            'launch_id',v_event.launch_id,
            'project_id',v_event.project_id,
            'beat_pattern_id',v_event.session_id,
            'saved_at',v_event.updated_at,
            'creator_session_provenance_verified',true,
            'world_layer','v12.4'
          )
        );
        v_credited:=v_credited+coalesce((v_result->>'credited')::integer,0);
        v_completed:=v_completed+coalesce((v_result->>'completed')::integer,0);
      end loop;
    end if;

    if exists (
      select 1 from jsonb_array_elements(v_state.objectives) o
      where o->>'type'='video_shoot'
    ) then
      for v_event in
        select j.id as render_job_id,
               j.project_id,
               j.finished_at,
               j.output_format,
               j.output_preset
        from public.tgg_video_studio_render_jobs j
        where j.user_id=v_uid
          and j.status='ready'
          and j.job_type='master'
          and j.finished_at is not null
          and j.finished_at>=v_state.accepted_at
          and exists (
            select 1
            from public.tgg_video_studio_render_outputs ro
            where ro.render_job_id=j.id
              and ro.user_id=v_uid
              and ro.status='ready'
              and nullif(btrim(coalesce(ro.storage_path,'')),'') is not null
          )
        order by j.finished_at,j.id
      loop
        v_scanned:=v_scanned+1;
        v_result:=private.tgg_world_credit_contract_event(
          v_char.id,
          'video_shoot',
          'video_master_render',
          v_event.project_id::text,
          jsonb_build_object(
            'project_id',v_event.project_id,
            'render_job_id',v_event.render_job_id,
            'finished_at',v_event.finished_at,
            'output_format',v_event.output_format,
            'output_preset',v_event.output_preset,
            'world_layer','v12.4'
          )
        );
        v_credited:=v_credited+coalesce((v_result->>'credited')::integer,0);
        v_completed:=v_completed+coalesce((v_result->>'completed')::integer,0);
      end loop;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'version','WORLD-V12.4-PERSISTED-OBJECTIVE-RECONCILIATION',
    'character_present',true,
    'character_id',v_char.id,
    'active_career',v_char.active_career,
    'scanned',v_scanned,
    'credited',v_credited,
    'completed',v_completed
  );
end;
$function$


-- [40000000463] function private.tgg_world_v12_start_rap_battle(p_opponent_user_id uuid, p_opponent_contact_key text, p_title text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v12_start_rap_battle(p_opponent_user_id uuid, p_opponent_contact_key text, p_title text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_character_id uuid;
  v_player_rep bigint:=0;
  v_opponent_character_id uuid;
  v_opponent_label text;
  v_opponent_rep bigint:=0;
  v_required integer:=0;
  v_event_id uuid;
  v_battle_id uuid;
  v_existing private.tgg_world_v12_rap_battles%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if (p_opponent_user_id is null and nullif(btrim(coalesce(p_opponent_contact_key,'')),'') is null) or (p_opponent_user_id is not null and nullif(btrim(coalesce(p_opponent_contact_key,'')),'') is not null) then raise exception 'ONE_OPPONENT_REQUIRED' using errcode='22023'; end if;
  if p_opponent_user_id=v_uid then raise exception 'SELF_BATTLE_NOT_ALLOWED' using errcode='22023'; end if;

  select * into v_existing from private.tgg_world_v12_rap_battles where user_id=v_uid and idempotency_key=p_idempotency_key limit 1;
  if found then return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','battle_id',v_existing.id,'event_id',v_existing.event_id,'status',v_existing.status,'opponent',v_existing.opponent_label,'idempotent',true); end if;

  select id into v_character_id from public.world_characters where user_id=v_uid and character_status='active' order by updated_at desc limit 1;
  if v_character_id is null then raise exception 'WORLD_CHARACTER_REQUIRED' using errcode='22023'; end if;
  select coalesce(reputation,0) into v_player_rep from public.tgg_world_players where user_id=v_uid limit 1;
  if not found then raise exception 'WORLD_PLAYER_REQUIRED' using errcode='22023'; end if;

  if p_opponent_user_id is not null then
    select id,stage_name into v_opponent_character_id,v_opponent_label from public.world_characters where user_id=p_opponent_user_id and character_status='active' order by updated_at desc limit 1;
    if v_opponent_character_id is null then raise exception 'OPPONENT_WORLD_CHARACTER_REQUIRED' using errcode='22023'; end if;
    select coalesce(reputation,0) into v_opponent_rep from public.tgg_world_players where user_id=p_opponent_user_id limit 1;
  else
    select display_name,reputation_required into v_opponent_label,v_required from public.tgg_world_industry_contacts where contact_key=p_opponent_contact_key and enabled=true and (lower(role_title) like '%battle%' or lower(role_title) like '%rapper%' or lower(role_title) like '%mc%');
    if v_opponent_label is null then raise exception 'BATTLE_OPPONENT_NOT_FOUND' using errcode='22023'; end if;
    if v_player_rep<v_required then raise exception 'REPUTATION_REQUIRED:%',v_required using errcode='22023'; end if;
    v_opponent_rep:=greatest(20,v_required*3);
  end if;

  insert into public.tgg_world_events(host_user_id,event_type,title,status,starts_at,visibility,metadata)
  values(v_uid,'rap_battle',coalesce(nullif(btrim(coalesce(p_title,'')),''),'TGG Rap Battle'),'live',now(),'public',jsonb_build_object('world_layer','v12','opponent_user_id',p_opponent_user_id,'opponent_contact_key',p_opponent_contact_key)) returning id into v_event_id;
  insert into public.tgg_world_event_participants(event_id,user_id,role,joined_at,metadata) values(v_event_id,v_uid,'performer',now(),jsonb_build_object('side','player')) on conflict do nothing;
  if p_opponent_user_id is not null then insert into public.tgg_world_event_participants(event_id,user_id,role,joined_at,metadata) values(v_event_id,p_opponent_user_id,'challenger',now(),jsonb_build_object('side','opponent')) on conflict do nothing; end if;

  insert into private.tgg_world_v12_rap_battles(user_id,character_id,event_id,opponent_user_id,opponent_character_id,opponent_contact_key,opponent_label,idempotency_key,metadata)
  values(v_uid,v_character_id,v_event_id,p_opponent_user_id,v_opponent_character_id,nullif(btrim(coalesce(p_opponent_contact_key,'')),''),v_opponent_label,p_idempotency_key,
    jsonb_build_object('player_reputation_at_start',v_player_rep,'opponent_reputation_basis',v_opponent_rep)) returning id into v_battle_id;

  return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','battle_id',v_battle_id,'event_id',v_event_id,'status','live','opponent',v_opponent_label,'rounds_total',3,'idempotent',false);
end $function$


-- [40000000464] function private.tgg_world_v3_travel_to_impl(p_location_key text)
CREATE OR REPLACE FUNCTION private.tgg_world_v3_travel_to_impl(p_location_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_location public.tgg_world_locations_v10%rowtype;
  v_player public.tgg_world_players%rowtype;
  v_canonical_key text;
  v_canonical_id uuid;
  v_character_synced boolean := false;
  v_join jsonb := '{}'::jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_location
  from public.tgg_world_locations_v10
  where location_key=p_location_key and active=true;
  if v_location.id is null then raise exception 'LOCATION_NOT_FOUND'; end if;

  select * into v_player from public.tgg_world_players where user_id=v_uid;
  if v_player.id is null then
    perform public.tgg_world_mvp_v1_bootstrap_player();
    select * into v_player from public.tgg_world_players where user_id=v_uid;
  end if;
  if v_player.reputation < v_location.unlock_reputation then raise exception 'LOCATION_LOCKED'; end if;

  v_canonical_key := case v_location.location_key
    when 'starter_studio' then 'basement-sound'
    when 'creator_shop' then 'style-shop'
    when 'local_venue' then 'corner-stage'
    when 'garage_one' then 'garage'
    when 'industry_row' then 'music-row'
    when 'spawn_district' then 'the-park'
    else v_location.location_key
  end;

  select id into v_canonical_id
  from public.tgg_world_locations
  where location_key=v_canonical_key and enabled=true
  limit 1;

  update public.tgg_world_players
  set current_location=v_location.location_key,last_seen_at=now(),updated_at=now()
  where user_id=v_uid;

  if v_canonical_id is not null and exists(
    select 1 from public.world_characters where user_id=v_uid and character_status='active'
  ) then
    v_join := tgg_private.world_join_location(v_canonical_key);
    v_character_synced := true;
  elsif v_canonical_id is not null then
    update public.world_characters
    set current_location_id=v_canonical_id,updated_at=now()
    where user_id=v_uid and character_status='active';
    v_character_synced := found;
  end if;

  return jsonb_build_object(
    'ok',true,
    'location_id',v_location.id,
    'location_key',v_location.location_key,
    'name',v_location.name,
    'canonical_location_id',v_canonical_id,
    'canonical_location_key',v_canonical_key,
    'character_synced',v_character_synced,
    'instance_id',v_join->>'instance_id',
    'population',v_join->'population',
    'capacity',v_join->'capacity'
  );
end
$function$


-- [40000000465] function private.tgg_world_vehicle_drive_session(p_vehicle_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_vehicle_drive_session(p_vehicle_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_vehicle public.tgg_world_vehicles%rowtype;
  v_presence public.tgg_world_presence%rowtype;
  v_prog public.tgg_world_vehicle_progression%rowtype;
  v_new_xp integer;
  v_new_level integer;
  v_vehicle_multiplier numeric:=1;
  v_drive_xp integer:=25;
  v_mod jsonb:='{}'::jsonb;
  v_property_vehicle_multiplier numeric:=1;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  select * into v_vehicle
  from public.tgg_world_vehicles
  where id=p_vehicle_id and owner_user_id=v_uid and owner_character_id=v_char and vehicle_status='active'
  for update;
  if v_vehicle.id is null then raise exception 'owned_active_vehicle_required'; end if;

  if not exists(
    select 1 from public.tgg_world_vehicle_passengers
    where vehicle_id=v_vehicle.id and user_id=v_uid and character_id=v_char
      and seat_key='driver' and left_at is null
  ) then raise exception 'driver_seat_required'; end if;

  select * into v_presence
  from public.tgg_world_presence
  where user_id=v_uid
  order by last_seen_at desc
  limit 1;

  if v_vehicle.current_instance_id is distinct from v_presence.instance_id then
    raise exception 'vehicle_not_in_current_instance';
  end if;

  insert into public.tgg_world_vehicle_progression(
    vehicle_id,vehicle_level,vehicle_xp,performance_rating,style_rating,reliability,unlocks,updated_at
  )
  values(v_vehicle.id,1,0,1,1,100,'{}'::jsonb,now())
  on conflict(vehicle_id) do nothing;

  select * into v_prog
  from public.tgg_world_vehicle_progression
  where vehicle_id=v_vehicle.id
  for update;

  select greatest(coalesce((value->>'value')::numeric,1),0)
  into v_vehicle_multiplier
  from public.tgg_world_economy_config
  where config_key='vehicle_xp_multiplier';
  v_vehicle_multiplier:=coalesce(v_vehicle_multiplier,1);
  v_mod:=private.tgg_world_effective_modifiers(v_char);
  v_property_vehicle_multiplier:=greatest(coalesce((v_mod->>'vehicle_xp_multiplier')::numeric,1),1);
  v_vehicle_multiplier:=v_vehicle_multiplier*v_property_vehicle_multiplier;
  v_drive_xp:=greatest(round(25*v_vehicle_multiplier)::integer,0);

  v_new_xp:=v_prog.vehicle_xp+v_drive_xp;
  v_new_level:=least(10,greatest(v_prog.vehicle_level,1+(v_new_xp/100)));

  update public.tgg_world_vehicle_progression
  set vehicle_xp=v_new_xp,
      vehicle_level=v_new_level,
      reliability=greatest(0,reliability-2),
      unlocks=unlocks||
        case
          when v_new_level>=5 then '{"road_ready":true}'::jsonb
          when v_new_level>=3 then '{"custom_tuning":true}'::jsonb
          else '{}'::jsonb
        end,
      updated_at=now()
  where vehicle_id=v_vehicle.id
  returning * into v_prog;

  perform private.tgg_recompute_progression(v_char);

  return jsonb_build_object(
    'ok',true,'vehicle_id',v_vehicle.id,'vehicle_level',v_prog.vehicle_level,
    'vehicle_xp',v_prog.vehicle_xp,'performance_rating',v_prog.performance_rating,
    'style_rating',v_prog.style_rating,'reliability',v_prog.reliability,
    'unlocks',v_prog.unlocks,'drive_xp_awarded',v_drive_xp,'vehicle_xp_multiplier',v_vehicle_multiplier,'property_vehicle_multiplier',v_property_vehicle_multiplier,'real_money',false
  );
end;
$function$


-- [40000000466] function private.tgg_world_vehicle_install_tune(p_vehicle_id uuid, p_upgrade_type text)
CREATE OR REPLACE FUNCTION private.tgg_world_vehicle_install_tune(p_vehicle_id uuid, p_upgrade_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_vehicle public.tgg_world_vehicles%rowtype;
  v_location text;
  v_item text;
  v_qty integer:=0;
  v_prog public.tgg_world_vehicle_progression%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  if p_upgrade_type not in ('performance','style') then
    raise exception 'invalid_upgrade_type';
  end if;

  select wc.id,l.location_key
  into v_char,v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.user_id=v_uid and wc.character_status='active'
  limit 1;
  if v_char is null then raise exception 'active_character_required'; end if;

  if v_location<>'garage' then raise exception 'travel_to_garage_first'; end if;

  select * into v_vehicle
  from public.tgg_world_vehicles
  where id=p_vehicle_id and owner_user_id=v_uid and owner_character_id=v_char
  for update;
  if v_vehicle.id is null then raise exception 'owned_vehicle_required'; end if;

  v_item:=case when p_upgrade_type='performance'
    then 'vehicle-performance-tune-kit'
    else 'vehicle-style-tune-kit' end;

  select quantity into v_qty
  from public.tgg_world_inventory
  where user_id=v_uid and character_id=v_char and item_key=v_item
  for update;

  if coalesce(v_qty,0)<1 then
    return jsonb_build_object(
      'ok',false,'reason','tune_kit_required','item_key',v_item,'real_money',false
    );
  end if;

  update public.tgg_world_inventory
  set quantity=quantity-1,updated_at=now()
  where user_id=v_uid and item_key=v_item;

  insert into public.tgg_world_vehicle_progression(
    vehicle_id,vehicle_level,vehicle_xp,performance_rating,style_rating,reliability,unlocks,updated_at
  )
  values(v_vehicle.id,1,0,1,1,100,'{}'::jsonb,now())
  on conflict(vehicle_id) do nothing;

  if p_upgrade_type='performance' then
    update public.tgg_world_vehicle_progression
    set performance_rating=least(10,performance_rating+1),
        reliability=least(100,reliability+5),
        updated_at=now()
    where vehicle_id=v_vehicle.id
    returning * into v_prog;
  else
    update public.tgg_world_vehicle_progression
    set style_rating=least(10,style_rating+1),
        updated_at=now()
    where vehicle_id=v_vehicle.id
    returning * into v_prog;
  end if;

  return jsonb_build_object(
    'ok',true,'vehicle_id',v_vehicle.id,'upgrade_type',p_upgrade_type,
    'vehicle_level',v_prog.vehicle_level,'vehicle_xp',v_prog.vehicle_xp,
    'performance_rating',v_prog.performance_rating,'style_rating',v_prog.style_rating,
    'reliability',v_prog.reliability,'kit_consumed',v_item,'real_money',false
  );
end;
$function$


-- [40000000467] function private.tgg_world_vehicle_join(p_vehicle_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_vehicle_join(p_vehicle_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_char public.world_characters%rowtype;
  v_presence public.tgg_world_presence%rowtype;
  v_vehicle public.tgg_world_vehicles%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select * into v_char from public.world_characters where user_id=v_uid and character_status='active' limit 1;
  if not found then raise exception 'active_character_required'; end if;
  select * into v_vehicle from public.tgg_world_vehicles where id=p_vehicle_id and vehicle_status='active';
  if not found then raise exception 'vehicle_not_active'; end if;
  select * into v_presence from public.tgg_world_presence where user_id=v_uid limit 1;
  if v_presence.instance_id is distinct from v_vehicle.current_instance_id then
    raise exception 'same_instance_required';
  end if;
  insert into public.tgg_world_vehicle_passengers(vehicle_id,user_id,character_id,seat_key,left_at,last_seen_at)
  values(v_vehicle.id,v_uid,v_char.id,'passenger',null,now())
  on conflict(vehicle_id,user_id) do update
    set character_id=excluded.character_id,seat_key=case when tgg_world_vehicle_passengers.seat_key='driver' then 'driver' else 'passenger' end,left_at=null,last_seen_at=now();
  return jsonb_build_object('ok',true,'vehicle_id',v_vehicle.id,'seat','passenger','shared_music',v_vehicle.music_state,'real_money',false);
end $function$


-- [40000000468] function private.tgg_world_vehicle_music(p_vehicle_id uuid, p_track jsonb)
CREATE OR REPLACE FUNCTION private.tgg_world_vehicle_music(p_vehicle_id uuid, p_track jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_role text;
  v_state jsonb;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select p.seat_key into v_role
  from public.tgg_world_vehicle_passengers p
  where p.vehicle_id=p_vehicle_id and p.user_id=v_uid and p.left_at is null;
  if v_role is null then raise exception 'vehicle_membership_required'; end if;
  if v_role <> 'driver' then raise exception 'driver_only'; end if;
  v_state := jsonb_build_object('mode','shared','track',coalesce(p_track,'{}'::jsonb),'position_ms',0,'updated_at',now());
  update public.tgg_world_vehicles set music_state=v_state,updated_at=now() where id=p_vehicle_id;
  return jsonb_build_object('ok',true,'vehicle_id',p_vehicle_id,'music_state',v_state);
end $function$


-- [40000000469] function private.tgg_world_vehicle_progression_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_vehicle_progression_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
  v_location text;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select wc.id,l.location_key into v_char,v_location
  from public.world_characters wc
  left join public.tgg_world_locations l on l.id=wc.current_location_id
  where wc.user_id=v_uid and wc.character_status='active'
  limit 1;
  if v_char is null then return '{}'::jsonb; end if;

  return jsonb_build_object(
    'character_id',v_char,
    'current_location',v_location,
    'garage_ready',v_location='garage',
    'performance_kits',coalesce((
      select quantity from public.tgg_world_inventory
      where user_id=v_uid and item_key='vehicle-performance-tune-kit'
    ),0),
    'style_kits',coalesce((
      select quantity from public.tgg_world_inventory
      where user_id=v_uid and item_key='vehicle-style-tune-kit'
    ),0),
    'vehicles',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',v.id,'display_name',v.display_name,'vehicle_key',v.vehicle_key,
        'vehicle_status',v.vehicle_status,
        'is_driver',exists(
          select 1 from public.tgg_world_vehicle_passengers p
          where p.vehicle_id=v.id and p.user_id=v_uid and p.seat_key='driver' and p.left_at is null
        ),
        'progression',jsonb_build_object(
          'vehicle_level',coalesce(p.vehicle_level,1),
          'vehicle_xp',coalesce(p.vehicle_xp,0),
          'performance_rating',coalesce(p.performance_rating,1),
          'style_rating',coalesce(p.style_rating,1),
          'reliability',coalesce(p.reliability,100),
          'unlocks',coalesce(p.unlocks,'{}'::jsonb)
        )
      ) order by v.created_at)
      from public.tgg_world_vehicles v
      left join public.tgg_world_vehicle_progression p on p.vehicle_id=v.id
      where v.owner_user_id=v_uid and v.owner_character_id=v_char
    ),'[]'::jsonb)
  );
end;
$function$


-- [40000000470] function private.tgg_world_vehicle_spawn(p_vehicle_key text, p_display_name text)
CREATE OR REPLACE FUNCTION private.tgg_world_vehicle_spawn(p_vehicle_key text DEFAULT 'starter-ride'::text, p_display_name text DEFAULT 'TGG Starter Ride'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_char public.world_characters%rowtype;
  v_presence public.tgg_world_presence%rowtype;
  v_vehicle public.tgg_world_vehicles%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select * into v_char from public.world_characters
   where user_id=v_uid and character_status='active' limit 1;
  if not found then raise exception 'active_character_required'; end if;
  select * into v_presence from public.tgg_world_presence where user_id=v_uid limit 1;

  insert into public.tgg_world_vehicles
    (owner_user_id,owner_character_id,vehicle_key,display_name,vehicle_status,current_instance_id)
  values
    (v_uid,v_char.id,coalesce(nullif(trim(p_vehicle_key),''),'starter-ride'),
     coalesce(nullif(trim(p_display_name),''),'TGG Starter Ride'),
     'active',v_presence.instance_id)
  on conflict(owner_character_id,vehicle_key) do update
    set vehicle_status='active',
        current_instance_id=excluded.current_instance_id,
        updated_at=now()
  returning * into v_vehicle;

  insert into public.tgg_world_vehicle_passengers(vehicle_id,user_id,character_id,seat_key,left_at,last_seen_at)
  values(v_vehicle.id,v_uid,v_char.id,'driver',null,now())
  on conflict(vehicle_id,user_id) do update
    set character_id=excluded.character_id,seat_key='driver',left_at=null,last_seen_at=now();

  return jsonb_build_object(
    'ok',true,'vehicle_id',v_vehicle.id,'vehicle_key',v_vehicle.vehicle_key,
    'display_name',v_vehicle.display_name,'seat','driver',
    'instance_id',v_vehicle.current_instance_id,'real_money',false
  );
end $function$


-- [40000000471] function private.tgg_world_wallet_ensure_impl()
CREATE OR REPLACE FUNCTION private.tgg_world_wallet_ensure_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_char public.world_characters%rowtype;
  v_wallet public.tgg_world_wallets%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select * into v_char from public.world_characters
  where user_id=v_uid and character_status='active' limit 1;
  if not found then raise exception 'active_character_required'; end if;

  insert into public.tgg_world_wallets(user_id,character_id,balance)
  values(v_uid,v_char.id,500)
  on conflict(user_id) do nothing;

  select * into v_wallet from public.tgg_world_wallets where user_id=v_uid;

  insert into public.tgg_world_wallet_ledger(
    user_id,character_id,entry_type,amount,balance_after,reference_type,reference_key,metadata
  )
  values(
    v_uid,v_char.id,'starter_grant',500,v_wallet.balance,'wallet_init','starter',
    jsonb_build_object('virtual_currency',true,'real_money',false)
  )
  on conflict do nothing;

  return jsonb_build_object(
    'ok',true,'balance',v_wallet.balance,'currency','tgg_credits',
    'virtual_currency',true,'real_money',false
  );
end
$function$


-- [40000000472] function private.tgg_world_watchdog()
CREATE OR REPLACE FUNCTION private.tgg_world_watchdog()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_stale integer; v_errors integer; v_status text; v_detail jsonb;
begin
  select count(*) into v_stale
  from public.tgg_world_worker_health
  where worker_key not in ('world-watchdog','runtime-snapshot')
    and (last_run_at is null or last_run_at < now()-interval '2 days');

  select count(*) into v_errors
  from public.tgg_world_worker_health
  where last_status='error';

  v_status := case when v_errors>0 then 'error' when v_stale>0 then 'warn' else 'ok' end;
  v_detail := jsonb_build_object('stale_workers',v_stale,'error_workers',v_errors);
  perform private.tgg_worker_mark('world-watchdog',v_status,v_detail);
  return v_detail;
end;
$function$


-- [40000000473] function private.tgg_world_workout_finish(p_workout_id uuid)
CREATE OR REPLACE FUNCTION private.tgg_world_workout_finish(p_workout_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_workout public.tgg_world_workouts%rowtype;
  v_xp integer;
  v_fitness integer;
  v_minutes integer;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select * into v_workout
  from public.tgg_world_workouts
  where id=p_workout_id and user_id=v_uid
  for update;

  if v_workout.id is null then raise exception 'workout_not_found'; end if;

  if v_workout.workout_status='complete' then
    return jsonb_build_object(
      'ok',true,'already_complete',true,'workout_id',v_workout.id,
      'reward',v_workout.reward_detail,'real_money',false
    );
  end if;

  if v_workout.workout_status<>'active' then
    raise exception 'workout_not_active';
  end if;

  v_minutes:=coalesce((v_workout.metadata->>'required_minutes')::integer,10);

  if now()<v_workout.started_at+make_interval(mins=>v_minutes) then
    return jsonb_build_object(
      'ok',false,'reason','workout_not_ready',
      'ready_at',v_workout.started_at+make_interval(mins=>v_minutes),
      'required_minutes',v_minutes
    );
  end if;

  v_xp:=case v_workout.workout_type
    when 'run_outside' then 18
    when 'strength' then 20
    else 15
  end;

  v_fitness:=case v_workout.workout_type
    when 'run_outside' then 3
    when 'strength' then 4
    else 2
  end;

  insert into public.world_character_stats(character_id,stat_key,stat_value,updated_at)
  values(v_workout.character_id,'xp',v_xp,now())
  on conflict(character_id,stat_key) do update
  set stat_value=public.world_character_stats.stat_value+excluded.stat_value,
      updated_at=now();

  insert into public.world_character_stats(character_id,stat_key,stat_value,updated_at)
  values(v_workout.character_id,'fitness',v_fitness,now())
  on conflict(character_id,stat_key) do update
  set stat_value=public.world_character_stats.stat_value+excluded.stat_value,
      updated_at=now();

  update public.tgg_world_workouts
  set workout_status='complete',
      completed_at=now(),
      reward_applied=true,
      reward_detail=jsonb_build_object(
        'type','virtual_progression','xp',v_xp,'fitness',v_fitness,
        'required_minutes',v_minutes,'real_money',false
      )
  where id=v_workout.id
  returning * into v_workout;

  return jsonb_build_object(
    'ok',true,'already_complete',false,'workout_id',v_workout.id,
    'reward',v_workout.reward_detail,'real_money',false
  );
end;
$function$


-- [40000000474] function private.tgg_world_workout_payload()
CREATE OR REPLACE FUNCTION private.tgg_world_workout_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;

  select id into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;

  if v_char is null then return '{}'::jsonb; end if;

  return jsonb_build_object(
    'character_id',v_char,
    'active',(
      select jsonb_build_object(
        'id',w.id,
        'workout_type',w.workout_type,
        'started_at',w.started_at,
        'required_minutes',coalesce((w.metadata->>'required_minutes')::integer,10),
        'ready_at',w.started_at+make_interval(
          mins=>coalesce((w.metadata->>'required_minutes')::integer,10)
        ),
        'ready_to_finish',now()>=w.started_at+make_interval(
          mins=>coalesce((w.metadata->>'required_minutes')::integer,10)
        )
      )
      from public.tgg_world_workouts w
      where w.user_id=v_uid and w.workout_status='active'
      order by w.started_at desc limit 1
    ),
    'recent',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',w.id,'workout_type',w.workout_type,
        'workout_status',w.workout_status,
        'started_at',w.started_at,'completed_at',w.completed_at,
        'reward_detail',w.reward_detail
      ) order by w.started_at desc)
      from (
        select * from public.tgg_world_workouts
        where user_id=v_uid
        order by started_at desc
        limit 10
      ) w
    ),'[]'::jsonb),
    'types',jsonb_build_array(
      jsonb_build_object('key','gym','label','Gym','minutes',10),
      jsonb_build_object('key','cardio','label','Cardio','minutes',10),
      jsonb_build_object('key','strength','label','Strength','minutes',15),
      jsonb_build_object('key','run_outside','label','Run Outside','minutes',15)
    )
  );
end;
$function$


-- [40000000475] function private.tgg_world_workout_start(p_workout_type text)
CREATE OR REPLACE FUNCTION private.tgg_world_workout_start(p_workout_type text DEFAULT 'gym'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_type text:=lower(trim(coalesce(p_workout_type,'')));
  v_minutes integer;
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if v_type not in ('gym','run_outside','cardio','strength') then
    raise exception 'invalid_workout_type';
  end if;

  select * into v_char
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_char.id is null then raise exception 'active_character_required'; end if;

  v_minutes:=case v_type
    when 'run_outside' then 15
    when 'strength' then 15
    when 'cardio' then 10
    else 10
  end;

  update public.tgg_world_workouts
  set workout_status='canceled'
  where user_id=v_uid and workout_status='active';

  insert into public.tgg_world_workouts(
    user_id,character_id,workout_type,workout_status,started_at,reward_applied,reward_detail,metadata
  )
  values(
    v_uid,v_char.id,v_type,'active',now(),false,'{}'::jsonb,
    jsonb_build_object('required_minutes',v_minutes)
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'workout_id',v_id,'workout_type',v_type,
    'required_minutes',v_minutes,
    'ready_at',now()+make_interval(mins=>v_minutes),
    'virtual_reward_only',true,'real_money',false
  );
end;
$function$


-- [40000000476] function public.ab005_advance_after_clean_pass(p_staging_release_id uuid)
CREATE OR REPLACE FUNCTION public.ab005_advance_after_clean_pass(p_staging_release_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ declare v_stage public.tgg_build_staging_releases%rowtype; v_after timestamptz; v_total bigint; v_pass bigint; v_bad bigint; v_checkpoint boolean; v_candidate_id uuid; begin select * into v_stage from public.tgg_build_staging_releases where id=p_staging_release_id for update; if not found then raise exception 'AB-005 staging release not found: %',p_staging_release_id; end if; if nullif(trim(v_stage.checkpoint_key),'') is null then raise exception 'AB-005 cannot advance without a checkpoint'; end if; select exists(select 1 from public.tgg_release_checkpoints c where c.checkpoint_key=v_stage.checkpoint_key) into v_checkpoint; if not v_checkpoint then raise exception 'AB-005 checkpoint key does not exist: %',v_stage.checkpoint_key; end if; v_after:=coalesce(nullif(v_stage.smoke_summary->>'rollback_cutoff','')::timestamptz,v_stage.created_at); select count(*),count(*) filter(where status='pass'),count(*) filter(where status in ('fail','blocked','manual')) into v_total,v_pass,v_bad from public.tgg_launch_smoke_results where check_key like 'ab005:'||v_stage.staging_key||':%' and checked_at > v_after; if v_total=0 or v_pass<>v_total or v_bad<>0 then raise exception 'AB-005 clean pass required: total=%, pass=%, bad=%',v_total,v_pass,v_bad; end if; update public.tgg_build_staging_releases set status='passed',verified_at=clock_timestamp(),smoke_summary=coalesce(smoke_summary,'{}'::jsonb)||jsonb_build_object('ab005_clean_pass',true,'smoke_count',v_total) where id=p_staging_release_id; update public.tgg_build_release_candidates set status=case when status in ('canary','draft','failed','rolled_back','blocked') then 'ready' else status end,updated_at=clock_timestamp() where staging_release_id=p_staging_release_id returning id into v_candidate_id; return jsonb_build_object('staging_release_id',p_staging_release_id,'status','passed','candidate_id',v_candidate_id,'production_gate_required',true,'production_promoted',false); end; $function$


-- [40000000477] function public.ab005_checkpoint(p_staging_release_id uuid, p_checkpoint_key text, p_title text, p_created_by uuid)
CREATE OR REPLACE FUNCTION public.ab005_checkpoint(p_staging_release_id uuid, p_checkpoint_key text, p_title text DEFAULT 'AB-005 Continuous Staging Checkpoint'::text, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ declare v_stage public.tgg_build_staging_releases%rowtype; begin if nullif(trim(p_checkpoint_key),'') is null then raise exception 'AB-005 checkpoint key is required'; end if; select * into v_stage from public.tgg_build_staging_releases where id=p_staging_release_id; if not found then raise exception 'AB-005 staging release not found: %',p_staging_release_id; end if; insert into public.tgg_release_checkpoints(checkpoint_key,title,system_state,runtime_manifest,launch_readiness,notes,created_by) values(p_checkpoint_key,coalesce(nullif(trim(p_title),''),'AB-005 Continuous Staging Checkpoint'),jsonb_build_object('environment','staging','staging_release_id',p_staging_release_id,'staging_key',v_stage.staging_key,'status',v_stage.status),coalesce(v_stage.deployment_manifest,'{}'::jsonb),jsonb_build_object('environment','staging','production_promoted',false,'production_gate_required',true),jsonb_build_object('rollback_reference',v_stage.previous_stable_key,'smoke_summary',coalesce(v_stage.smoke_summary,'{}'::jsonb)),p_created_by); update public.tgg_build_staging_releases set checkpoint_key=p_checkpoint_key where id=p_staging_release_id; return jsonb_build_object('staging_release_id',p_staging_release_id,'checkpoint_key',p_checkpoint_key); end; $function$


-- [40000000478] function public.ab005_prepare_staging(p_build_release_id uuid, p_run_id uuid, p_staging_key text, p_build_version text, p_previous_stable_key text)
CREATE OR REPLACE FUNCTION public.ab005_prepare_staging(p_build_release_id uuid, p_run_id uuid DEFAULT NULL::uuid, p_staging_key text DEFAULT NULL::text, p_build_version text DEFAULT NULL::text, p_previous_stable_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_build_release_id is null then raise exception 'AB-005 build release id is required'; end if;
  if nullif(trim(p_staging_key), '') is null then raise exception 'AB-005 staging key is required'; end if;
  if nullif(trim(p_build_version), '') is null then raise exception 'AB-005 build version is required'; end if;
  insert into public.tgg_build_staging_releases(build_release_id,run_id,staging_key,build_version,status,previous_stable_key)
  values(p_build_release_id,p_run_id,p_staging_key,p_build_version,'prepared',p_previous_stable_key)
  returning id into v_id;
  return v_id;
end;
$function$


-- [40000000479] function public.ab005_record_smoke(p_staging_release_id uuid, p_result text, p_detail jsonb, p_created_by uuid)
CREATE OR REPLACE FUNCTION public.ab005_record_smoke(p_staging_release_id uuid, p_result text, p_detail jsonb DEFAULT '{}'::jsonb, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ declare v_stage public.tgg_build_staging_releases%rowtype; v_check_key text; v_id bigint; begin if p_result not in ('pass','fail','blocked','manual') then raise exception 'AB-005 smoke result must be pass, fail, blocked, or manual'; end if; select * into v_stage from public.tgg_build_staging_releases where id=p_staging_release_id for update; if not found then raise exception 'AB-005 staging release not found: %',p_staging_release_id; end if; v_check_key:='ab005:'||v_stage.staging_key||':'||coalesce(nullif(trim(p_detail->>'check_key'),''),'smoke'); insert into public.tgg_launch_smoke_results(check_key,status,detail,checked_at) values(v_check_key,p_result,coalesce(p_detail,'{}'::jsonb)||jsonb_build_object('staging_release_id',p_staging_release_id,'created_by',p_created_by),clock_timestamp()) returning id into v_id; update public.tgg_build_staging_releases set status=case when p_result in ('fail','blocked') then 'failed' when p_result='pass' then 'smoke_testing' else status end, smoke_summary=coalesce(smoke_summary,'{}'::jsonb)||jsonb_build_object('last_result',p_result,'last_smoke_id',v_id) where id=p_staging_release_id; return jsonb_build_object('staging_release_id',p_staging_release_id,'smoke_id',v_id,'result',p_result); end; $function$


-- [40000000480] function public.ab005_rollback_staging(p_staging_release_id uuid, p_rollback_reference text)
CREATE OR REPLACE FUNCTION public.ab005_rollback_staging(p_staging_release_id uuid, p_rollback_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ declare v_cutoff timestamptz; begin if nullif(trim(p_rollback_reference),'') is null then raise exception 'AB-005 rollback reference is required'; end if; v_cutoff:=clock_timestamp(); update public.tgg_build_staging_releases set status='rolled_back',previous_stable_key=p_rollback_reference,rolled_back_at=v_cutoff,smoke_summary=coalesce(smoke_summary,'{}'::jsonb)||jsonb_build_object('rollback_reference',p_rollback_reference,'rollback_cutoff',v_cutoff) where id=p_staging_release_id; if not found then raise exception 'AB-005 staging release not found: %',p_staging_release_id; end if; return jsonb_build_object('staging_release_id',p_staging_release_id,'status','rolled_back','rollback_reference',p_rollback_reference,'rollback_cutoff',v_cutoff); end; $function$


-- [40000000481] function public.ab006_authorize_production(p_staging_release_id uuid, p_authorization_key text, p_note text)
CREATE OR REPLACE FUNCTION public.ab006_authorize_production(p_staging_release_id uuid, p_authorization_key text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_stage public.tgg_build_staging_releases%rowtype;
  v_checkpoint public.tgg_release_checkpoints%rowtype;
  v_id uuid;
begin
  if p_staging_release_id is null or nullif(btrim(p_authorization_key), '') is null then
    raise exception 'staging release and authorization key are required';
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.role = 'admin'
  ) then
    raise exception 'production authorization requires admin role';
  end if;

  select * into v_stage
  from public.tgg_build_staging_releases
  where id = p_staging_release_id;

  if not found then
    raise exception 'staging release not found';
  end if;

  if v_stage.status <> 'passed'
     or coalesce((v_stage.smoke_summary->>'ab005_clean_pass')::boolean, false) is not true
     or nullif(btrim(v_stage.checkpoint_key), '') is null then
    raise exception 'staging release is not eligible for production authorization';
  end if;

  select * into v_checkpoint
  from public.tgg_release_checkpoints
  where checkpoint_key = v_stage.checkpoint_key;

  if not found then
    raise exception 'required release checkpoint not found';
  end if;

  insert into public.tgg_production_authorizations (
    staging_release_id, checkpoint_key, authorization_key, status, authorized_by, authorization_note
  ) values (
    v_stage.id, v_stage.checkpoint_key, btrim(p_authorization_key), 'approved', auth.uid(), p_note
  ) returning id into v_id;

  return jsonb_build_object(
    'ok', true,
    'authorization_id', v_id,
    'authorization_key', btrim(p_authorization_key),
    'staging_release_id', v_stage.id,
    'checkpoint_key', v_stage.checkpoint_key,
    'production_authorized', true,
    'production_promoted', false,
    'production_deploy_performed', false,
    'explicit_admin_authorization', true
  );
end;
$function$


-- [40000000482] function public.artist_owns_mixtape(p_mixtape_id uuid)
CREATE OR REPLACE FUNCTION public.artist_owns_mixtape(p_mixtape_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.mixtapes m
    INNER JOIN public.artists a
      ON a.id = m.artist_id
    WHERE m.id = p_mixtape_id
      AND a.user_id = (SELECT auth.uid())
  );
$function$


-- [40000000483] function public.handle_new_user()
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN

  INSERT INTO public.profiles (
    id,
    role
  )

  VALUES (
    NEW.id,
    'artist'
  )

  ON CONFLICT (id) DO NOTHING;

  RETURN NEW;

END;
$function$


