-- [40000000486] function public.phase2_creator_analytics(p_creator_id uuid, p_days integer)
CREATE OR REPLACE FUNCTION public.phase2_creator_analytics(p_creator_id uuid, p_days integer DEFAULT 30)
 RETURNS TABLE(event_type text, event_count bigint)
 LANGUAGE sql
 SET search_path TO 'public', 'auth'
AS $function$
  select e.event_type,count(*)::bigint
  from public.creator_analytics_events e
  where e.creator_id=p_creator_id
    and e.occurred_at >= now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365)))
    and exists(
      select 1 from public.artists a
      where a.id=p_creator_id and a.user_id=auth.uid()
    )
  group by e.event_type
  order by count(*) desc;
$function$


-- [40000000487] function public.phase2_creator_analytics_dashboard(p_days integer)
CREATE OR REPLACE FUNCTION public.phase2_creator_analytics_dashboard(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'auth'
AS $function$
    declare
      v_user uuid := auth.uid();
      v_creator uuid;
      v_days integer := greatest(1, least(coalesce(p_days,30),365));
      v_result jsonb;
    begin
      if v_user is null then raise exception 'Authentication required'; end if;

      select a.id into v_creator
      from public.artists a
      where a.user_id=v_user
      order by a.created_at asc
      limit 1;

      if v_creator is null then raise exception 'Creator workspace not found'; end if;

      select jsonb_build_object(
        'creator_id', v_creator,
        'days', v_days,
        'events_total', (select count(*) from public.creator_analytics_events e where e.creator_id=v_creator and e.occurred_at>=now()-make_interval(days=>v_days)),
        'views', (select count(*) from public.creator_analytics_events e where e.creator_id=v_creator and e.event_type='view' and e.occurred_at>=now()-make_interval(days=>v_days)),
        'plays', (select count(*) from public.creator_analytics_events e where e.creator_id=v_creator and e.event_type='play' and e.occurred_at>=now()-make_interval(days=>v_days)),
        'downloads', (select count(*) from public.creator_analytics_events e where e.creator_id=v_creator and e.event_type='download' and e.occurred_at>=now()-make_interval(days=>v_days)),
        'shares', (select count(*) from public.creator_analytics_events e where e.creator_id=v_creator and e.event_type='share' and e.occurred_at>=now()-make_interval(days=>v_days)),
        'likes', (select count(*) from public.creator_analytics_events e where e.creator_id=v_creator and e.event_type='like' and e.occurred_at>=now()-make_interval(days=>v_days)),
        'mixtapes', coalesce((
          select jsonb_agg(to_jsonb(x) order by x.play_count desc,x.created_at desc)
          from (
            select mt.id,mt.title,mt.genre,mt.status,mt.featured,mt.play_count,mt.created_at
            from public.mixtapes mt
            where mt.artist_id=v_creator
            order by mt.play_count desc,mt.created_at desc
            limit 12
          ) x
        ),'[]'::jsonb),
        'event_breakdown', coalesce((
          select jsonb_agg(jsonb_build_object('event_type',z.event_type,'count',z.event_count) order by z.event_count desc)
          from (
            select e.event_type,count(*)::bigint event_count
            from public.creator_analytics_events e
            where e.creator_id=v_creator and e.occurred_at>=now()-make_interval(days=>v_days)
            group by e.event_type
          ) z
        ),'[]'::jsonb)
      ) into v_result;

      return v_result;
    end;
    $function$


-- [40000000488] function public.phase2_creator_analytics_summary(p_creator_id uuid, p_days integer)
CREATE OR REPLACE FUNCTION public.phase2_creator_analytics_summary(p_creator_id uuid, p_days integer DEFAULT 30)
 RETURNS TABLE(metric text, value bigint)
 LANGUAGE sql
 SET search_path TO 'public', 'auth'
AS $function$
  select *
  from (
    select 'views'::text,count(*)::bigint from public.creator_analytics_events e
      where e.creator_id=p_creator_id and e.event_type='view'
        and e.occurred_at>=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365)))
    union all
    select 'plays',count(*) from public.creator_analytics_events e
      where e.creator_id=p_creator_id and e.event_type='play'
        and e.occurred_at>=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365)))
    union all
    select 'downloads',count(*) from public.creator_analytics_events e
      where e.creator_id=p_creator_id and e.event_type='download'
        and e.occurred_at>=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365)))
    union all
    select 'shares',count(*) from public.creator_analytics_events e
      where e.creator_id=p_creator_id and e.event_type='share'
        and e.occurred_at>=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365)))
    union all
    select 'likes',count(*) from public.creator_analytics_events e
      where e.creator_id=p_creator_id and e.event_type='like'
        and e.occurred_at>=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365)))
    union all
    select 'follows',count(*) from public.creator_analytics_events e
      where e.creator_id=p_creator_id and e.event_type='follow'
        and e.occurred_at>=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365)))
  ) s
  where exists(
    select 1 from public.artists a
    where a.id=p_creator_id and a.user_id=auth.uid()
  );
$function$


-- [40000000489] function public.phase2_mixtape_performance(p_creator_id uuid, p_days integer)
CREATE OR REPLACE FUNCTION public.phase2_mixtape_performance(p_creator_id uuid, p_days integer DEFAULT 30)
 RETURNS TABLE(mixtape_id uuid, title text, genre text, cover_url text, play_count bigint, period_plays bigint, period_views bigint, period_downloads bigint)
 LANGUAGE sql
 SET search_path TO 'public', 'auth'
AS $function$
  select
    m.id,m.title,m.genre,m.cover_url,coalesce(m.play_count,0)::bigint,
    coalesce((select count(*) from public.creator_analytics_events e
      where e.mixtape_id=m.id and e.creator_id=p_creator_id and e.event_type='play'
        and e.occurred_at>=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365)))),0)::bigint,
    coalesce((select count(*) from public.creator_analytics_events e
      where e.mixtape_id=m.id and e.creator_id=p_creator_id and e.event_type='view'
        and e.occurred_at>=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365)))),0)::bigint,
    coalesce((select count(*) from public.creator_analytics_events e
      where e.mixtape_id=m.id and e.creator_id=p_creator_id and e.event_type='download'
        and e.occurred_at>=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365)))),0)::bigint
  from public.mixtapes m
  join public.artists a on a.id=m.artist_id
  where m.artist_id=p_creator_id
    and a.user_id=auth.uid()
  order by coalesce(m.play_count,0) desc,m.created_at desc;
$function$


