-- [40000000492] function public.tgg_ab005_launch_gate()
CREATE OR REPLACE FUNCTION public.tgg_ab005_launch_gate()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_stage record;
  v_ready boolean := false;
begin
  select
    s.id,
    s.staging_key,
    s.status,
    s.checkpoint_key,
    s.previous_stable_key,
    s.verified_at,
    s.smoke_summary,
    s.created_at
  into v_stage
  from public.tgg_build_staging_releases s
  where s.smoke_summary->>'ab005_clean_pass'='true'
  order by s.verified_at desc nulls last,s.created_at desc
  limit 1;

  if found then
    v_ready :=
      v_stage.status='passed'
      and nullif(v_stage.checkpoint_key,'') is not null
      and coalesce(v_stage.smoke_summary->>'ab005_clean_pass','false')='true';
  end if;

  return jsonb_build_object(
    'ok',true,
    'consumer','ab005-launch-gate',
    'read_only',true,
    'eligible',v_ready,
    'staging',
      case when found then jsonb_build_object(
        'id',v_stage.id,
        'staging_key',v_stage.staging_key,
        'status',v_stage.status,
        'checkpoint_key',v_stage.checkpoint_key,
        'clean_pass',true,
        'rollback_reference',v_stage.previous_stable_key,
        'rollback_cutoff',v_stage.smoke_summary->>'rollback_cutoff',
        'verified_at',v_stage.verified_at,
        'created_at',v_stage.created_at
      ) else null end,
    'production_gate_required',true,
    'production_promoted',false
  );
end;
$function$


-- [40000000493] function public.tgg_ab006_handoff_status()
CREATE OR REPLACE FUNCTION public.tgg_ab006_handoff_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_release jsonb;
  v_drift jsonb;
  v_controller jsonb;
  v_prod_auth bigint;
  v_approved bigint;
  v_promoted bigint;
  v_handoff jsonb;
begin
  select jsonb_build_object(
    'release_key',r.release_key,
    'status',r.status,
    'target_environment',r.target_environment,
    'metadata',r.metadata
  )
  into v_release
  from public.tgg_build_releases r
  where r.release_key='AB-006';

  select public.tgg_ab006_verify_runtime_contract() into v_drift;

  select jsonb_build_object(
    'enabled',c.enabled,
    'status',c.status,
    'mode',c.mode,
    'last_cycle_result',c.last_cycle_result
  )
  into v_controller
  from public.tgg_autobuilder_controller c
  where c.id=1;

  select count(*) into v_prod_auth
  from public.tgg_production_authorizations;

  select count(*) into v_approved
  from public.tgg_build_release_candidates
  where status='approved';

  select count(*) into v_promoted
  from public.tgg_build_release_candidates
  where status='promoted';

  select s.state into v_handoff
  from public.tgg_build_snapshots s
  where s.snapshot_key='AB006-V223-CANONICAL-HANDOFF'
  order by s.created_at desc
  limit 1;

  return jsonb_build_object(
    'ok',true,
    'read_only',true,
    'canonical_source_version','V223',
    'canonical_source_label','AB-006-updated V223',
    'canonical_boundary','AB-006',
    'release',v_release,
    'runtime_contract',v_drift,
    'controller',v_controller,
    'production_state',jsonb_build_object(
      'production_authorization_count',v_prod_auth,
      'approved_candidate_count',v_approved,
      'promoted_candidate_count',v_promoted,
      'production_state_changed',false
    ),
    'handoff_snapshot',v_handoff,
    'status_only',true,
    'production_action_exposed',false
  );
end;
$function$


-- [40000000494] function public.tgg_ab006_status()
CREATE OR REPLACE FUNCTION public.tgg_ab006_status()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(public.tgg_ab005_launch_gate(),'{}'::jsonb)
    || jsonb_build_object(
      'stage','AB-006',
      'canonical_source_version','V223',
      'canonical_source_label','AB-006-updated V223',
      'ui_mode','status_only',
      'ui_authorization_action_exposed',false,
      'production_authorization_required',true,
      'production_authorization_mode','explicit_admin_only',
      'production_deploy_performed',false,
      'production_promotion_performed',false,
      'next_stage_created',false
    );
$function$


-- [40000000495] function public.tgg_ab006_verify_runtime_contract()
CREATE OR REPLACE FUNCTION public.tgg_ab006_verify_runtime_contract()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manifest jsonb;
  v_grants jsonb;
  v_current text;
  v_expected text;
  v_match boolean;
begin
  select jsonb_agg(
    jsonb_build_object(
      'function_name',p.proname,
      'args',pg_get_function_identity_arguments(p.oid),
      'definition_md5',md5(pg_get_functiondef(p.oid)),
      'security_definer',p.prosecdef
    )
    order by p.proname
  )
  into v_manifest
  from pg_proc p
  join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public'
    and p.proname in (
      'ab005_prepare_staging',
      'ab005_record_smoke',
      'ab005_checkpoint',
      'ab005_rollback_staging',
      'ab005_advance_after_clean_pass',
      'tgg_ab005_launch_gate',
      'ab006_authorize_production',
      'tgg_ab006_status'
    );

  select jsonb_agg(
    jsonb_build_object(
      'routine_name',routine_name,
      'grantee',grantee,
      'privilege_type',privilege_type
    )
    order by routine_name,grantee
  )
  into v_grants
  from information_schema.routine_privileges
  where routine_schema='public'
    and routine_name in (
      'ab005_prepare_staging',
      'ab005_record_smoke',
      'ab005_checkpoint',
      'ab005_rollback_staging',
      'ab005_advance_after_clean_pass',
      'tgg_ab005_launch_gate',
      'ab006_authorize_production',
      'tgg_ab006_status'
    );

  v_current := md5(coalesce(v_manifest::text,'') || '|' || coalesce(v_grants::text,''));

  select checksum into v_expected
  from public.tgg_build_artifacts
  where artifact_type='handoff_manifest'
    and name='AB-006 V223 Canonical Handoff'
  order by created_at desc
  limit 1;

  v_match := v_expected is not null and v_current=v_expected;

  return jsonb_build_object(
    'ok',true,
    'canonical_source_version','V223',
    'canonical_boundary','AB-006',
    'read_only',true,
    'expected_checksum_md5',v_expected,
    'current_checksum_md5',v_current,
    'contract_matches',v_match,
    'production_state_changed',false
  );
end;
$function$


-- [40000000496] function public.tgg_academy_bundle()
CREATE OR REPLACE FUNCTION public.tgg_academy_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      return tgg_safe_api.academy_catalog() || jsonb_build_object(
        'ok',true,
        'version','ACADEMY-ONE-FINAL-1.0',
        'progress',coalesce((
          select jsonb_agg(jsonb_build_object(
            'course_code',p.course_code,'lesson_code',p.lesson_code,'status',p.status,
            'progress_percent',p.progress_percent,'completed_at',p.completed_at,'updated_at',p.updated_at
          ) order by p.updated_at desc)
          from public.tgg_academy_progress p where p.user_id=v_uid
        ),'[]'::jsonb),
        'mentorship',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',m.id,'topic',m.topic,'message',m.message,'session_type',m.session_type,
            'status',m.status,'requested_at',m.requested_at,'scheduled_at',m.scheduled_at,
            'direction',case when m.requester_user_id=v_uid then 'outgoing' else 'incoming' end,
            'other_artist',case
              when m.requester_user_id=v_uid then (
                select jsonb_build_object('artist_id',a.id,'stage_name',a.stage_name,'avatar_url',a.avatar_url)
                from public.artists a where a.user_id=m.mentor_user_id limit 1
              )
              else (
                select jsonb_build_object('artist_id',a.id,'stage_name',a.stage_name,'avatar_url',a.avatar_url)
                from public.artists a where a.user_id=m.requester_user_id limit 1
              )
            end
          ) order by m.updated_at desc)
          from public.tgg_mentorship_requests m
          where m.requester_user_id=v_uid or m.mentor_user_id=v_uid
        ),'[]'::jsonb),
        'generated_at',now()
      );
    end $function$


