-- [40000000500] function public.tgg_activation_bridge_bundle()
CREATE OR REPLACE FUNCTION public.tgg_activation_bridge_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_secrets jsonb;
  v_staging jsonb;
  v_runtime jsonb;
  v_membership jsonb;
  v_verification jsonb;
  v_root jsonb;
begin
  v_secrets:=public.tgg_provider_secret_status();
  v_staging:=public.tgg_provider_activation_staging_status();
  v_membership:=public.tgg_membership_activation_bundle();
  v_verification:=public.tgg_provider_activation_verification_status();
  v_root:=public.tgg_one_final_root_actions();

  select coalesce(jsonb_agg(jsonb_build_object(
    'provider_key',provider_key,
    'display_name',display_name,
    'capability',capability,
    'mode',mode,
    'enabled',enabled,
    'endpoint_configured',endpoint_configured,
    'disabled_reason',disabled_reason,
    'updated_at',updated_at
  ) order by provider_key),'[]'::jsonb)
  into v_runtime
  from public.tgg_provider_runtime_config
  where provider_key in ('stripe.webhook','email.resend','distribution.provider','broadcast.sfu_turn');

  return jsonb_build_object(
    'ok',true,
    'version','ACTIVATION-BRIDGE-ONE-FINAL-1.1',
    'secrets',v_secrets->'providers',
    'staging',v_staging,
    'verification',v_verification,
    'runtime',v_runtime,
    'membership',v_membership,
    'root_actions',v_root,
    'safe_actions',jsonb_build_object(
      'store_secret_rpc','tgg_store_provider_secret',
      'stage_provider_rpc','tgg_provider_activation_stage',
      'membership_finalize_rpc','tgg_membership_activate_if_ready',
      'membership_tier_id','280efcec-1bb1-41e2-a048-945b4b742f3b',
      'call_invite_claim_rpc','tgg_call_validation_invite_claim'
    ),
    'generated_at',now()
  );
end
$function$


