-- [40000000502] function public.tgg_activation_packets_final()
CREATE OR REPLACE FUNCTION public.tgg_activation_packets_final()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_scope jsonb;
  v_invite jsonb;
  v_membership jsonb;
  v_staging jsonb;
  v_secrets jsonb;
  v_bowser jsonb;
  v_lets jsonb;
  v_preflight jsonb;
  v_revelator_secret_present boolean:=false;
  v_livekit_secret_present boolean:=false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  v_scope:=public.tgg_launch_scope_final();
  v_invite:=public.tgg_call_validation_invite_status();
  v_membership:=public.tgg_membership_activation_bundle();
  v_staging:=public.tgg_provider_activation_staging_status();
  v_secrets:=public.tgg_provider_secret_status();
  v_bowser:=public.tgg_creator_distribution_readiness('b95ffce9-a4a1-42ea-9dcb-c3cb7375600f');
  v_lets:=public.tgg_creator_distribution_readiness('0c6e3ff9-186a-4df2-ac3f-3ae917ba44a8');
  v_preflight:=public.tgg_distribution_preflight_bundle();

  select exists(
    select 1
    from jsonb_array_elements(coalesce(v_secrets->'providers','[]'::jsonb)) x
    where x->>'provider_key'='distribution.provider'
      and x->>'status' in ('stored','verified')
  )
  into v_revelator_secret_present;

  select exists(
    select 1
    from jsonb_array_elements(coalesce(v_secrets->'providers','[]'::jsonb)) x
    where x->>'provider_key'='broadcast.sfu_turn'
      and x->>'status' in ('stored','verified','runtime_verified')
  )
  into v_livekit_secret_present;

  return jsonb_build_object(
    'ok',true,
    'version','ACTIVATION-PACKETS-ONE-FINAL-1.3',
    'core_launch_ready',coalesce((v_scope->>'core_launch_ready')::boolean,false),
    'canonical_handoff_rpc','tgg_final_activation_handoff',
    'canonical_handoff_version','FINAL-ACTIVATION-HANDOFF-1.2',
    'distribution_fallback',jsonb_build_object(
      'available',true,
      'rpc','tgg_distribution_preflight_bundle',
      'version','DISTRIBUTION-PREFLIGHT-BUNDLE-ONE-FINAL-1.0',
      'submission_ready',false,
      'purpose','Provider-neutral technical preflight package while legal metadata/provider credentials remain incomplete.'
    ),
    'handoff_contract',jsonb_build_object(
      'partial_inputs_supported',true,
      'secrets_echoed',false,
      'sections_isolated',true,
      'supported_payload_keys',jsonb_build_array(
        'stripe_webhook_signing_secret',
        'bowser_on_it',
        'lets_get_it',
        'revelator_production_api_credential',
        'livekit_url',
        'livekit_api_key',
        'livekit_api_secret'
      ),
      'pending_payload_keys',
        (case
          when coalesce((v_membership->>'webhook_ready')::boolean,false)
               and coalesce((v_membership#>>'{tiers,0,is_active}')::boolean,false)
            then '[]'::jsonb
          else jsonb_build_array('stripe_webhook_signing_secret')
        end)
        ||
        (case when coalesce((v_bowser->>'package_ready')::boolean,false)
          then '[]'::jsonb else jsonb_build_array('bowser_on_it') end)
        ||
        (case when coalesce((v_lets->>'package_ready')::boolean,false)
          then '[]'::jsonb else jsonb_build_array('lets_get_it') end)
        ||
        (case when v_revelator_secret_present
          then '[]'::jsonb else jsonb_build_array('revelator_production_api_credential') end)
        ||
        (case when v_livekit_secret_present
          then '[]'::jsonb else jsonb_build_array('livekit_url','livekit_api_key','livekit_api_secret') end)
    ),
    'packets',jsonb_build_array(
      jsonb_build_object(
        'key','stripe_webhook',
        'title','Stripe webhook + Backstage Supporter',
        'status',case
          when coalesce((v_membership->>'webhook_ready')::boolean,false)
               and coalesce((v_membership#>>'{tiers,0,is_active}')::boolean,false)
            then 'complete'
          when coalesce((v_membership->>'webhook_ready')::boolean,false)
            then 'ready_to_finalize'
          else 'input_required'
        end,
        'handoff_payload_key','stripe_webhook_signing_secret',
        'required_inputs',case
          when coalesce((v_membership->>'webhook_ready')::boolean,false)
               and coalesce((v_membership#>>'{tiers,0,is_active}')::boolean,false)
            then '[]'::jsonb
          else jsonb_build_array(
            jsonb_build_object(
              'field','stripe_webhook_signing_secret',
              'secret',true,
              'source','Stripe live webhook endpoint',
              'destination','Final Activation Handoff',
              'vault_slot','tgg_stripe_webhook_secret'
            )
          )
        end,
        'verification',jsonb_build_object(
          'payment_link_verified',coalesce((v_membership#>>'{tiers,0,payment_link_verified}')::boolean,false),
          'payout_ready',coalesce((v_membership->>'payout_ready')::boolean,false),
          'webhook_ready',coalesce((v_membership->>'webhook_ready')::boolean,false)
        )
      ),
      jsonb_build_object(
        'key','bowser_legal',
        'title','Bowser On It distribution legal metadata',
        'release_id','b95ffce9-a4a1-42ea-9dcb-c3cb7375600f',
        'status',case when coalesce((v_bowser->>'package_ready')::boolean,false) then 'complete' else 'input_required' end,
        'handoff_payload_key','bowser_on_it',
        'technical_preflight_ready',coalesce((v_preflight#>>'{bowser_on_it,ok}')::boolean,false),
        'preflight_rpc','tgg_creator_distribution_preflight_package',
        'required_inputs',jsonb_build_array(
          jsonb_build_object('field','label_name','secret',false),
          jsonb_build_object('field','copyright_line','secret',false),
          jsonb_build_object('field','publishing_line','secret',false),
          jsonb_build_object('field','territories','secret',false),
          jsonb_build_object('field','rights_confirmed','secret',false)
        ),
        'current_blockers',coalesce(v_bowser->'blockers','[]'::jsonb)
      ),
      jsonb_build_object(
        'key','lets_get_it_legal',
        'title','Lets Get It distribution legal metadata',
        'release_id','0c6e3ff9-186a-4df2-ac3f-3ae917ba44a8',
        'status',case when coalesce((v_lets->>'package_ready')::boolean,false) then 'complete' else 'input_required' end,
        'handoff_payload_key','lets_get_it',
        'technical_preflight_ready',coalesce((v_preflight#>>'{lets_get_it,ok}')::boolean,false),
        'preflight_rpc','tgg_creator_distribution_preflight_package',
        'required_inputs',jsonb_build_array(
          jsonb_build_object('field','label_name','secret',false),
          jsonb_build_object('field','copyright_line','secret',false),
          jsonb_build_object('field','publishing_line','secret',false),
          jsonb_build_object('field','territories','secret',false),
          jsonb_build_object('field','rights_confirmed','secret',false)
        ),
        'current_blockers',coalesce(v_lets->'blockers','[]'::jsonb)
      ),
      jsonb_build_object(
        'key','revelator_dsp',
        'title','Revelator production DSP connection',
        'status',case
          when v_revelator_secret_present then 'credential_stored_verification_pending'
          when exists(
            select 1
            from jsonb_array_elements(coalesce(v_staging->'items','[]'::jsonb)) x
            where x->>'provider_key'='distribution.provider'
              and x->>'status'='verified'
          ) then 'endpoint_verified_credential_required'
          else 'endpoint_or_credential_required'
        end,
        'endpoint','https://api.revelator.com',
        'endpoint_reachable',exists(
          select 1
          from jsonb_array_elements(coalesce(v_staging->'items','[]'::jsonb)) x
          where x->>'provider_key'='distribution.provider'
            and x->>'status'='verified'
        ),
        'credential_present',v_revelator_secret_present,
        'handoff_payload_key','revelator_production_api_credential',
        'required_inputs',case
          when v_revelator_secret_present then '[]'::jsonb
          else jsonb_build_array(
            jsonb_build_object(
              'field','revelator_production_api_credential',
              'secret',true,
              'destination','Final Activation Handoff'
            )
          )
        end,
        'notes','Endpoint reachability is not credential verification. Production runtime remains disabled until the real credential is stored and validated.'
      ),
      jsonb_build_object(
        'key','livekit',
        'title','LiveKit Cloud scalable broadcast',
        'status','project_required',
        'handoff_payload_keys',jsonb_build_array('livekit_url','livekit_api_key','livekit_api_secret'),
        'required_inputs',jsonb_build_array(
          jsonb_build_object('field','livekit_url','secret',false,'format','wss://<project>.livekit.cloud'),
          jsonb_build_object('field','livekit_api_key','secret',true),
          jsonb_build_object('field','livekit_api_secret','secret',true)
        )
      ),
      jsonb_build_object(
        'key','two_user_call',
        'title','Two-user call validation',
        'status',case
          when coalesce((v_invite->>'completed_at'),'')<>'' then 'complete'
          when coalesce((v_invite->>'has_invite')::boolean,false) then 'ready'
          else 'invite_required'
        end,
        'claim_url',v_invite->>'claim_url',
        'expires_at',v_invite->>'expires_at',
        'required_inputs',jsonb_build_array(
          jsonb_build_object(
            'field','second_authenticated_device',
            'secret',false,
            'instruction','Open the claim URL while signed into the second legitimate account, then complete one offer/answer exchange.'
          )
        )
      )
    ),
    'generated_at',now()
  );
end
$function$


