-- [40000000507] function public.tgg_admin_artist_profile_bundle(p_artist_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_admin_artist_profile_bundle(p_artist_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();
