          select jsonb_agg(jsonb_build_object(
            'id',a.id,'user_id',a.user_id,'stage_name',a.stage_name,'bio',a.bio,'avatar_url',a.avatar_url,
            'instagram',a.instagram,'website',a.website,'youtube',a.youtube,'soundcloud',a.soundcloud,'spotify',a.spotify,
            'stripe_onboarding_complete',a.stripe_onboarding_complete,'payouts_enabled',a.payouts_enabled,'created_at',a.created_at
          ) order by a.stage_name)
          from public.artists a where p_artist_id is null or a.id=p_artist_id
        ),'[]'::jsonb)
      );
    end $function$


-- [40000000508] function public.tgg_admin_artist_profile_update(p_artist_id uuid, p_stage_name text, p_bio text, p_avatar_url text, p_instagram text, p_website text, p_youtube text, p_soundcloud text, p_spotify text)
CREATE OR REPLACE FUNCTION public.tgg_admin_artist_profile_update(p_artist_id uuid, p_stage_name text, p_bio text, p_avatar_url text, p_instagram text, p_website text, p_youtube text, p_soundcloud text, p_spotify text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_id uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if not exists(select 1 from public.profiles p where p.id=v_uid and p.role='admin') then
        raise exception 'ADMIN_REQUIRED' using errcode='42501';
      end if;
      update public.artists set
        stage_name=left(btrim(coalesce(p_stage_name,'')),120),
        bio=coalesce(p_bio,''),
