        instagram=nullif(btrim(coalesce(p_instagram,'')),''),
        website=nullif(btrim(coalesce(p_website,'')),''),
        youtube=nullif(btrim(coalesce(p_youtube,'')),''),
        soundcloud=nullif(btrim(coalesce(p_soundcloud,'')),''),
