      where id=p_artist_id returning id into v_id;
      if v_id is null then raise exception 'ARTIST_NOT_FOUND'; end if;
      return jsonb_build_object('ok',true,'artist_id',v_id);
    end $function$


-- [40000000509] function public.tgg_admin_content_bundle()
CREATE OR REPLACE FUNCTION public.tgg_admin_content_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();
