    $function$


-- [40000000510] function public.tgg_admin_media_action(p_type text, p_id uuid, p_action text)
CREATE OR REPLACE FUNCTION public.tgg_admin_media_action(p_type text, p_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_type text:=lower(btrim(coalesce(p_type,'')));
      v_action text:=lower(btrim(coalesce(p_action,'')));
      v_flag boolean;
      v_deleted integer;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if not exists(select 1 from public.profiles where id=v_uid and role='admin') then
        raise exception 'ADMIN_REQUIRED' using errcode='42501';
      end if;
      if v_type not in ('videos','interviews') then raise exception 'MEDIA_TYPE_INVALID'; end if;
      if v_action not in ('toggle_publish','toggle_featured','delete') then raise exception 'ACTION_INVALID'; end if;
      if v_action='toggle_featured' and v_type<>'videos' then raise exception 'ACTION_NOT_SUPPORTED'; end if;

      if v_action='delete' then
        if v_type='videos' then
          delete from public.site_videos where id=p_id;
        else
          delete from public.artist_interviews where id=p_id;
        end if;
        get diagnostics v_deleted = row_count;
        if v_deleted=0 then raise exception 'MEDIA_NOT_FOUND'; end if;
        return jsonb_build_object('ok',true,'type',v_type,'id',p_id,'deleted',true);
      end if;

      if v_action='toggle_featured' then
        update public.site_videos
        set featured=not coalesce(featured,false)
        where id=p_id
        returning featured into v_flag;
      elsif v_type='videos' then
        update public.site_videos
        set published=not coalesce(published,false),
            status=case when not coalesce(published,false) then 'published' else 'draft' end
        where id=p_id
        returning published into v_flag;
      else
        update public.artist_interviews
        set published=not coalesce(published,false),
            status=case when not coalesce(published,false) then 'published' else 'draft' end
        where id=p_id
        returning published into v_flag;
      end if;

      if v_flag is null then raise exception 'MEDIA_NOT_FOUND'; end if;
      return jsonb_build_object('ok',true,'type',v_type,'id',p_id,'action',v_action,'value',v_flag);
    end;
    $function$


-- [40000000511] function public.tgg_admin_media_bundle()
CREATE OR REPLACE FUNCTION public.tgg_admin_media_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if not exists(select 1 from public.profiles where id=v_uid and role='admin') then
        raise exception 'ADMIN_REQUIRED' using errcode='42501';
      end if;

      return jsonb_build_object(
        'ok',true,
        'version','ADMIN-MEDIA-ONE-FINAL-1.0',
        'counts',jsonb_build_object(
          'videos',(select count(*) from public.site_videos),
          'published_videos',(select count(*) from public.site_videos where published=true),
          'featured_videos',(select count(*) from public.site_videos where featured=true),
          'interviews',(select count(*) from public.artist_interviews),
          'published_interviews',(select count(*) from public.artist_interviews where published=true)
        ),
        'videos',coalesce((
          select jsonb_agg(to_jsonb(x) order by x.publish_date desc nulls last,x.created_at desc)
          from (
            select id,title,description,category,video_url,thumbnail_url,artist_name,
                   publish_date,featured,published,status,created_at
            from public.site_videos
            order by publish_date desc nulls last,created_at desc
            limit 300
          ) x
        ),'[]'::jsonb),
        'interviews',coalesce((
          select jsonb_agg(to_jsonb(x) order by x.publish_date desc nulls last,x.created_at desc)
          from (
            select id,title,artist_name,video_url,image_url,publish_date,published,status,created_at
            from public.artist_interviews
            order by publish_date desc nulls last,created_at desc
            limit 300
          ) x
        ),'[]'::jsonb),
        'generated_at',now()
      );
    end;
    $function$


-- [40000000512] function public.tgg_admin_media_save(p_type text, p_id uuid, p_title text, p_artist_name text, p_video_url text, p_image_url text, p_publish_date timestamp with time zone, p_published boolean, p_description text, p_category text, p_featured boolean)
CREATE OR REPLACE FUNCTION public.tgg_admin_media_save(p_type text, p_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_artist_name text DEFAULT NULL::text, p_video_url text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text, p_publish_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_published boolean DEFAULT false, p_description text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_featured boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_type text:=lower(btrim(coalesce(p_type,'')));
      v_title text:=btrim(coalesce(p_title,''));
      v_video_url text:=btrim(coalesce(p_video_url,''));
      v_image_url text:=nullif(btrim(coalesce(p_image_url,'')),'');
      v_id uuid:=p_id;
      v_status text:=case when coalesce(p_published,false) then 'published' else 'draft' end;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if not exists(select 1 from public.profiles where id=v_uid and role='admin') then
        raise exception 'ADMIN_REQUIRED' using errcode='42501';
      end if;
      if v_type not in ('videos','interviews') then raise exception 'MEDIA_TYPE_INVALID'; end if;
      if char_length(v_title)<1 or char_length(v_title)>180 then raise exception 'TITLE_INVALID'; end if;
      if v_video_url !~* '^https?://' then raise exception 'VIDEO_URL_INVALID'; end if;
      if v_image_url is not null and v_image_url !~* '^https?://' then raise exception 'IMAGE_URL_INVALID'; end if;

      if v_type='videos' then
        if v_id is null then
          insert into public.site_videos(
            title,description,category,video_url,thumbnail_url,artist_name,publish_date,
            featured,published,user_id,status
          ) values(
            v_title,nullif(btrim(coalesce(p_description,'')),''),
            nullif(btrim(coalesce(p_category,'')),''),
            v_video_url,v_image_url,nullif(btrim(coalesce(p_artist_name,'')),''),
            coalesce(p_publish_date,now()),coalesce(p_featured,false),
            coalesce(p_published,false),v_uid,v_status
          ) returning id into v_id;
        else
          update public.site_videos
          set title=v_title,
              description=nullif(btrim(coalesce(p_description,'')),''),
              category=nullif(btrim(coalesce(p_category,'')),''),
              video_url=v_video_url,
              thumbnail_url=v_image_url,
              artist_name=nullif(btrim(coalesce(p_artist_name,'')),''),
              publish_date=coalesce(p_publish_date,publish_date,now()),
              featured=coalesce(p_featured,false),
              published=coalesce(p_published,false),
              status=v_status
          where id=v_id;
          if not found then raise exception 'MEDIA_NOT_FOUND'; end if;
        end if;
      else
        if v_id is null then
          insert into public.artist_interviews(
            title,artist_name,video_url,image_url,publish_date,published,user_id,status
          ) values(
            v_title,nullif(btrim(coalesce(p_artist_name,'')),''),
            v_video_url,v_image_url,coalesce(p_publish_date,now()),
            coalesce(p_published,false),v_uid,v_status
          ) returning id into v_id;
        else
          update public.artist_interviews
          set title=v_title,
              artist_name=nullif(btrim(coalesce(p_artist_name,'')),''),
              video_url=v_video_url,
              image_url=v_image_url,
              publish_date=coalesce(p_publish_date,publish_date,now()),
              published=coalesce(p_published,false),
              status=v_status
          where id=v_id;
          if not found then raise exception 'MEDIA_NOT_FOUND'; end if;
        end if;
      end if;

      return jsonb_build_object('ok',true,'type',v_type,'id',v_id,'published',coalesce(p_published,false),'status',v_status);
    end;
    $function$


-- [40000000513] function public.tgg_admin_os_final_bundle()
CREATE OR REPLACE FUNCTION public.tgg_admin_os_final_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_content jsonb;v_media jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if not exists(select 1 from public.profiles p where p.id=v_uid and p.role='admin') then
    raise exception 'ADMIN_REQUIRED' using errcode='42501';
  end if;
  v_content:=public.tgg_admin_content_bundle();
  v_media:=public.tgg_admin_media_bundle();
  return jsonb_build_object(
    'ok',true,'version','ADMIN-ONE-FINAL-1.5','user_id',v_uid,
    'counts',jsonb_build_object(
      'pending_mixtapes',(select count(*) from public.mixtapes where status='pending'),
      'pending_videos',(select count(*) from public.videos where status='pending'),
      'pending_audiobooks',(select count(*) from public.tgg_audiobooks where status='pending'),
      'pending_merch',(select count(*) from public.merch_products where status='pending'),
      'pending_promotions',(select count(*) from public.promotion_campaigns where status='pending'),
      'pending_radio',(select count(*) from public.tgg_radio_shows where status='pending'),
      'pending_tv_episodes',(select count(*) from public.tgg_tv_episodes where status='pending'),
      'published_releases',(select count(*) from public.mixtapes where status='published'),
      'published_videos',(select count(*) from public.videos where status='published' and visibility='public'),
      'published_audiobooks',(select count(*) from public.tgg_audiobooks where status='published' and visibility='public'),
      'published_merch',(select count(*) from public.merch_products where status='published'),
      'published_tv_episodes',(select count(*) from public.tgg_tv_episodes where status='published' and visibility='public')
    ),
    'content',v_content,'media',v_media,
    'capabilities',jsonb_build_object(
      'review_mixtape',true,'review_video',true,'review_audiobook',true,
      'review_merch',true,'review_promotion',true,'review_radio',true,'review_tv_episode',true,
      'project_status_update',true,'project_delete',true,'unified_dashboard',true,
      'media_crud',true,'media_publish_toggle',true,'media_feature_toggle',true,'media_crop_upload',true
    ),
    'operations',public.tgg_operations_final_health(),'generated_at',now()
  );
end $function$


-- [40000000514] function public.tgg_admin_project_delete(p_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_admin_project_delete(p_project_id uuid)
 RETURNS jsonb
