-- [40000000515] function public.tgg_admin_project_set_status(p_project_id uuid, p_status text, p_note text)
CREATE OR REPLACE FUNCTION public.tgg_admin_project_set_status(p_project_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid(); v_status text:=lower(btrim(coalesce(p_status,'')));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if not exists(select 1 from public.profiles where id=v_uid and role='admin') then
        raise exception 'ADMIN_REQUIRED' using errcode='42501';
      end if;
      if v_status not in ('draft','pending','published','changes_requested','rejected') then raise exception 'STATUS_INVALID'; end if;
      update public.mixtapes
      set status=v_status::public.mixtape_status,admin_note=nullif(btrim(coalesce(p_note,'')),'')
      where id=p_project_id;
      if not found then raise exception 'PROJECT_NOT_FOUND'; end if;
      return jsonb_build_object('ok',true,'project_id',p_project_id,'status',v_status);
    end;
    $function$


