-- [40000000520] function public.tgg_admin_review_tv_episode(p_episode_id uuid, p_action text, p_note text)
CREATE OR REPLACE FUNCTION public.tgg_admin_review_tv_episode(p_episode_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_action text:=lower(btrim(coalesce(p_action,'')));v_id uuid;v_status text;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from public.profiles where id=v_uid and role='admin') then raise exception 'ADMIN_REQUIRED' using errcode='42501'; end if;
 if v_action='approve' then v_status:='published';
 elsif v_action in ('reject','changes') then v_status:='rejected';
 else raise exception 'ACTION_INVALID'; end if;
 update public.tgg_tv_episodes
 set status=v_status,admin_note=nullif(btrim(coalesce(p_note,'')),''),published_at=case when v_status='published' then coalesce(published_at,now()) else null end,updated_at=now()
 where id=p_episode_id and status='pending'
 returning id into v_id;
 if v_id is null then raise exception 'EPISODE_NOT_PENDING'; end if;
 return jsonb_build_object('ok',true,'episode_id',v_id,'status',v_status);
end $function$


