-- [40000000522] function public.tgg_artist_follow_state(p_artist_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_artist_follow_state(p_artist_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_owner uuid;v_count bigint:=0;
begin
  select a.user_id into v_owner from public.artists a where a.id=p_artist_id;
  if v_owner is null then return jsonb_build_object('ok',false,'error','artist_not_found'); end if;
  select count(*) into v_count from public.artist_follows f where f.artist_id=p_artist_id;
  return jsonb_build_object(
    'ok',true,
    'signed_in',v_uid is not null,
    'is_owner',v_uid is not null and v_uid=v_owner,
    'can_follow',v_uid is not null and v_uid<>v_owner,
    'following',case when v_uid is null then false else exists(
      select 1 from public.artist_follows f where f.user_id=v_uid and f.artist_id=p_artist_id
    ) end,
    'follower_count',v_count
  );
end $function$


-- [40000000523] function public.tgg_asset_validate_brief(p_asset_key text)
CREATE OR REPLACE FUNCTION public.tgg_asset_validate_brief(p_asset_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_asset public.tgg_asset_briefs%rowtype;
  v_opt_ok boolean;
  v_rights_ok boolean;
  v_tech_ok boolean;
begin
  select * into v_asset
  from public.tgg_asset_briefs
  where asset_key=p_asset_key;

  if v_asset.id is null then
    raise exception 'asset brief not found: %',p_asset_key;
  end if;

  v_opt_ok := jsonb_typeof(v_asset.optimization_targets)='object'
              and v_asset.optimization_targets <> '{}'::jsonb;
  v_rights_ok := jsonb_typeof(v_asset.rights_requirements)='object'
                 and v_asset.rights_requirements <> '{}'::jsonb;
  v_tech_ok := jsonb_typeof(v_asset.technical_requirements)='object'
               and v_asset.technical_requirements <> '{}'::jsonb;

  if not v_opt_ok then
    return jsonb_build_object('status','blocked','reason','missing_optimization_targets');
  end if;

  if not v_rights_ok then
    return jsonb_build_object('status','blocked','reason','missing_rights_requirements');
  end if;

  if not v_tech_ok then
    return jsonb_build_object('status','blocked','reason','missing_technical_requirements');
  end if;

  return jsonb_build_object(
    'status','ready_for_generation',
    'asset_key',p_asset_key,
    'optimization_targets',true,
    'rights_requirements',true,
    'technical_requirements',true
  );
end;
$function$


-- [40000000524] function public.tgg_attach_vault_media(p_vault_item_id uuid, p_media_asset_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_attach_vault_media(p_vault_item_id uuid, p_media_asset_id uuid)
 RETURNS public.tgg_vault_items
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_asset public.tgg_media_vault_assets;
  v_row public.tgg_vault_items;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select * into v_asset
  from public.tgg_media_vault_assets
  where id = p_media_asset_id and user_id = v_uid;
  if not found then raise exception 'media asset not found'; end if;

  update public.tgg_vault_items vi
     set media_asset_id = v_asset.id,
         storage_path = v_asset.storage_path,
         mime_type = v_asset.mime_type,
         file_size_bytes = v_asset.file_size_bytes,
         media_url = null,
         metadata = coalesce(vi.metadata,'{}'::jsonb) || jsonb_build_object('secure_media',true)
   where vi.id = p_vault_item_id
     and exists (select 1 from public.artists a where a.id = vi.artist_id and a.user_id = v_uid)
  returning * into v_row;

  if not found then raise exception 'vault item not found or not owned by current user'; end if;
  return v_row;
end;
$function$


-- [40000000525] function public.tgg_audiobook_add_chapter_from_storage(p_audiobook_id uuid, p_chapter_number integer, p_title text, p_storage_path text, p_duration_seconds numeric, p_allow_download boolean)
CREATE OR REPLACE FUNCTION public.tgg_audiobook_add_chapter_from_storage(p_audiobook_id uuid, p_chapter_number integer, p_title text, p_storage_path text, p_duration_seconds numeric DEFAULT NULL::numeric, p_allow_download boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_path text:=btrim(coalesce(p_storage_path,''));
      v_chapter public.tgg_audiobook_chapters;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if p_chapter_number is null or p_chapter_number<1 then raise exception 'CHAPTER_NUMBER_INVALID'; end if;
      if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'CHAPTER_TITLE_INVALID'; end if;
      if v_path='' or split_part(v_path,'/',1)<>v_uid::text then raise exception 'STORAGE_PATH_NOT_OWNED'; end if;

      if not exists(
        select 1
        from public.tgg_audiobooks b
        join public.artists a on a.id=b.artist_id
        where b.id=p_audiobook_id
          and a.user_id=v_uid
          and b.status in ('draft','changes_requested')
      ) then raise exception 'AUDIOBOOK_NOT_EDITABLE'; end if;

      if not exists(
        select 1 from storage.objects o
        where o.bucket_id='creator-media'
          and o.name=v_path
          and (storage.foldername(o.name))[1]=v_uid::text
      ) then raise exception 'UPLOADED_AUDIO_NOT_FOUND'; end if;

      insert into public.tgg_audiobook_chapters(
        audiobook_id,user_id,chapter_number,title,storage_bucket,storage_path,
        duration_seconds,allow_download
      )
      values(
        p_audiobook_id,v_uid,p_chapter_number,btrim(p_title),
        'creator-media',v_path,p_duration_seconds,p_allow_download
      )
      on conflict(audiobook_id,chapter_number)
      do update set
        title=excluded.title,
        storage_bucket=excluded.storage_bucket,
        storage_path=excluded.storage_path,
        duration_seconds=excluded.duration_seconds,
        allow_download=excluded.allow_download,
        updated_at=now()
      returning * into v_chapter;

      return jsonb_build_object(
        'ok',true,
        'chapter_id',v_chapter.id,
        'audiobook_id',v_chapter.audiobook_id,
        'chapter_number',v_chapter.chapter_number,
        'title',v_chapter.title
      );
    end;
    $function$


-- [40000000526] function public.tgg_audiobook_create_draft(p_title text, p_author_name text, p_narrator_name text, p_description text, p_cover_url text, p_genre text, p_language text, p_explicit_content boolean, p_allow_downloads boolean)
CREATE OR REPLACE FUNCTION public.tgg_audiobook_create_draft(p_title text, p_author_name text DEFAULT NULL::text, p_narrator_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_cover_url text DEFAULT NULL::text, p_genre text DEFAULT NULL::text, p_language text DEFAULT 'en'::text, p_explicit_content boolean DEFAULT false, p_allow_downloads boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist_id uuid;
      v_project public.tgg_studio_projects;
      v_book public.tgg_audiobooks;
      v_title text:=btrim(coalesce(p_title,''));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if char_length(v_title)<1 or char_length(v_title)>180 then raise exception 'TITLE_INVALID'; end if;

      select id into v_artist_id
      from public.artists
      where user_id=v_uid
      order by created_at
      limit 1;

      if v_artist_id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

      v_project:=public.tgg_studio_create_project(
        v_title,'audiobook',null,null,
        nullif(btrim(coalesce(p_description,'')),'')
      );

      insert into public.tgg_audiobooks(
        artist_id,project_id,title,author_name,narrator_name,description,
        cover_url,genre,language,explicit_content,allow_downloads,status,visibility
      )
      values(
        v_artist_id,v_project.id,v_title,
        nullif(btrim(coalesce(p_author_name,'')),''),
        nullif(btrim(coalesce(p_narrator_name,'')),''),
        nullif(btrim(coalesce(p_description,'')),''),
        nullif(btrim(coalesce(p_cover_url,'')),''),
        nullif(btrim(coalesce(p_genre,'')),''),
        coalesce(nullif(btrim(coalesce(p_language,'')),''),'en'),
        p_explicit_content,p_allow_downloads,'draft','private'
      )
      returning * into v_book;

      return jsonb_build_object(
        'ok',true,
        'audiobook_id',v_book.id,
        'project_id',v_book.project_id,
        'status',v_book.status,
        'title',v_book.title
      );
    end;
    $function$


