-- [40000000528] function public.tgg_auth_authorization_readiness()
CREATE OR REPLACE FUNCTION public.tgg_auth_authorization_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
with owner_functions(name) as (
  values
  ('tgg_master_owner_dashboard'),
  ('tgg_master_owner_queue_change'),
  ('tgg_master_owner_set_site'),
  ('tgg_master_owner_upsert_content'),
  ('tgg_master_owner_upsert_shared_setting'),
  ('tgg_owner_provider_completion_checklist'),
  ('tgg_owner_provider_handoff')
),
owner_fn_state as (
  select
    o.name,
    exists(
      select 1
      from pg_proc p
      join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='public'
        and p.prokind='f'
        and p.proname=o.name
        and p.prosecdef=false
        and has_function_privilege('authenticated',p.oid,'EXECUTE')
        and not has_function_privilege('anon',p.oid,'EXECUTE')
        and (
          (
            pg_get_functiondef(p.oid) ilike '%app_metadata%'
            and pg_get_functiondef(p.oid) ilike '%tgg_role%'
            and pg_get_functiondef(p.oid) ilike '%owner%'
          )
          or pg_get_functiondef(p.oid) ilike '%private.tgg_is_owner_fresh()%'
        )
    ) ready
  from owner_functions o
),
unsafe_function_metadata as (
  select n.nspname schema_name,p.proname,pg_get_function_identity_arguments(p.oid) args
  from pg_proc p
  join pg_namespace n on n.oid=p.pronamespace
  where n.nspname in ('public','private')
    and p.prokind='f'
    and not (n.nspname='public' and p.proname='tgg_auth_authorization_readiness')
    and (
      pg_get_functiondef(p.oid) ilike '%raw_user_meta_data%'
      or pg_get_functiondef(p.oid) ilike '%user_metadata%'
    )
),
unsafe_policy_metadata as (
  select c.relname table_name,pol.polname policy_name
  from pg_policy pol
  join pg_class c on c.oid=pol.polrelid
  join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='public'
    and (
      coalesce(pg_get_expr(pol.polqual,pol.polrelid),'') ilike '%raw_user_meta_data%'
      or coalesce(pg_get_expr(pol.polqual,pol.polrelid),'') ilike '%user_metadata%'
      or coalesce(pg_get_expr(pol.polwithcheck,pol.polrelid),'') ilike '%raw_user_meta_data%'
      or coalesce(pg_get_expr(pol.polwithcheck,pol.polrelid),'') ilike '%user_metadata%'
    )
),
owner_policies as (
  select count(*) filter(
    where c.relname in (
      'tgg_master_sites','tgg_master_content','tgg_master_shared_settings',
      'tgg_master_change_queue','tgg_provider_handoff'
    )
    and (
      coalesce(pg_get_expr(pol.polqual,pol.polrelid),'') ilike '%app_metadata%'
      or coalesce(pg_get_expr(pol.polwithcheck,pol.polrelid),'') ilike '%app_metadata%'
    )
    and (
      coalesce(pg_get_expr(pol.polqual,pol.polrelid),'') ilike '%tgg_role%'
      or coalesce(pg_get_expr(pol.polwithcheck,pol.polrelid),'') ilike '%tgg_role%'
    )
    and (
      coalesce(pg_get_expr(pol.polqual,pol.polrelid),'') ilike '%owner%'
      or coalesce(pg_get_expr(pol.polwithcheck,pol.polrelid),'') ilike '%owner%'
    )
  ) owner_policy_count
  from pg_policy pol
  join pg_class c on c.oid=pol.polrelid
  join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='public'
),
agg as (
  select
    (select count(*) from owner_fn_state) owner_fn_total,
    (select count(*) from owner_fn_state where ready) owner_fn_ready,
    (select coalesce(jsonb_agg(name),'[]'::jsonb) from owner_fn_state where not ready) owner_fn_failed,
    (select count(*) from unsafe_function_metadata) unsafe_function_count,
    (select coalesce(jsonb_agg(jsonb_build_object('schema',schema_name,'name',proname,'args',args)),'[]'::jsonb) from unsafe_function_metadata) unsafe_functions,
    (select count(*) from unsafe_policy_metadata) unsafe_policy_count,
    (select coalesce(jsonb_agg(jsonb_build_object('table',table_name,'policy',policy_name)),'[]'::jsonb) from unsafe_policy_metadata) unsafe_policies,
    (select owner_policy_count from owner_policies) owner_policy_count
)
select jsonb_build_object(
  'ok',
    owner_fn_ready=owner_fn_total
    and unsafe_function_count=0
    and unsafe_policy_count=0
    and owner_policy_count>=5,
  'version','AUTH-AUTHORIZATION-1.2',
  'owner_rpcs',jsonb_build_object(
    'ready',owner_fn_ready,'total',owner_fn_total,'failed',owner_fn_failed,
    'security_mode','security_invoker',
    'accepted_owner_checks',jsonb_build_array('direct_app_metadata','private.tgg_is_owner_fresh'),
    'role_source','app_metadata.tgg_role'
  ),
  'owner_rls',jsonb_build_object(
    'role_guarded_policy_count',owner_policy_count,
    'role_source','app_metadata.tgg_role'
  ),
  'unsafe_user_metadata',jsonb_build_object(
    'function_count',unsafe_function_count,
    'policy_count',unsafe_policy_count,
    'functions',unsafe_functions,
    'policies',unsafe_policies
  ),
  'session_security',jsonb_build_object(
    'jwt_session_id_available',true,
    'strict_auth_sessions_lookup_required_for_current_core',false,
    'fresh_owner_helper','private.tgg_is_owner_fresh',
    'note','Owner authorization accepts direct signed app_metadata checks or the vetted fresh-owner lookup against auth.users.raw_app_meta_data.'
  ),
  'generated_at',now()
)
from agg;
$function$


