-- [40000000530] function public.tgg_authenticated_user_e2e_refresh()
CREATE OR REPLACE FUNCTION public.tgg_authenticated_user_e2e_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_sessions int:=0;
  v_refreshed int:=0;
  v_covers int:=0;
  v_audio int:=0;
  v_projects int:=0;
  v_actions int:=0;
  v_completed int:=0;
  v_portal_return boolean:=false;
  v_status text:='active';
  v_acceptance jsonb;
begin
  with recent_users as (
    select distinct user_id
    from auth.sessions
    where created_at>=now()-interval '24 hours'
  ),
  recent_artists as (
    select a.id,a.user_id
    from public.artists a
    join recent_users ru on ru.user_id=a.user_id
  )
  select
    (select count(*) from auth.sessions where created_at>=now()-interval '24 hours'),
    (select count(*) from auth.sessions where refreshed_at>=now()-interval '24 hours'),
    (select count(*) from storage.objects o
      where o.bucket_id='covers'
        and o.owner_id in (select user_id::text from recent_users)),
    (select count(*) from storage.objects o
      where o.bucket_id='mixtape-audio'
        and o.owner_id in (select user_id::text from recent_users)),
    (select count(*) from public.mixtapes m
      where m.artist_id in (select id from recent_artists)),
    (select count(*) from public.tgg_creator_action_queue q
      where q.artist_id in (select id from recent_artists)),
    (select count(*) from public.tgg_creator_action_queue q
      where q.artist_id in (select id from recent_artists)
        and q.status='completed'
        and q.updated_at>=now()-interval '7 days')
  into v_sessions,v_refreshed,v_covers,v_audio,v_projects,v_actions,v_completed;

  select exists(
    select 1
    from private.tgg_veil_audit_ledger enter_evt
    where enter_evt.allowed=true
      and enter_evt.route_key='artist_world'
      and exists(
        select 1
        from private.tgg_veil_audit_ledger exit_evt
        where exit_evt.allowed=true
          and exit_evt.actor_user_id=enter_evt.actor_user_id
          and exit_evt.route_key='artist_creator_os'
          and exit_evt.decided_at>=enter_evt.decided_at
      )
  ) into v_portal_return;

  if v_sessions>0
     and v_covers>0
     and v_audio>0
     and v_projects>0
     and v_actions>0
     and v_completed>0
     and v_portal_return then
    v_status:='complete';
  end if;

  v_acceptance:=jsonb_build_array(
    format('PASS: real sign-in/session evidence exists — %s session(s) in 24h, %s refreshed',v_sessions,v_refreshed),
    'READY / REAL SESSION PRESENT: Creator OS runtime validates bearer JWT and returns READY bundle after onboarding; direct dashboard-view audit evidence is not recorded',
    format('PASS: upload/project evidence — %s authenticated-owned cover object(s), %s authenticated-owned mixtape-audio object(s), %s project(s) owned by recent-session user(s)',v_covers,v_audio,v_projects),
    format('PASS: creator action evidence — %s action(s) tied to recent-session user(s), including %s completed this week',v_actions,v_completed),
    case when v_portal_return
      then 'PASS: portal/return — real authenticated VEIL audit contains artist_world entry followed by artist_creator_os return'
      else 'EVIDENCE-GATED: portal/return — waiting for one real authenticated Matrix/Lewis entry plus return to Creator OS; ledger remains un-fabricated'
    end,
    'CODE-VERIFIED ONLY: live Creator OS signOut uses sb.auth.signOut() then reload; no durable logout audit event exists, so real logout is not falsely claimed',
    'DEFERRED EXTERNAL: LiveKit production credentials',
    'DEFERRED EXTERNAL: real second-device WebRTC validation',
    'DEFERRED EXTERNAL: DSP production credential',
    'DEFERRED EXTERNAL: Supabase leaked-password-protection setting',
    'PROTECTED: CodeSync remains review-only and untouched'
  );

  update public.tgg_build_milestones
  set status=v_status,
      acceptance=v_acceptance,
      updated_at=now()
  where release_id='433251c2-3ca3-4d95-a535-8b438f0e094c'
    and milestone_key='authenticated-user-e2e';

  return jsonb_build_object(
    'ok',true,
    'status',v_status,
    'sessions_24h',v_sessions,
    'refreshed_24h',v_refreshed,
    'owned_covers',v_covers,
    'owned_mixtape_audio',v_audio,
    'owned_projects',v_projects,
    'creator_actions',v_actions,
    'creator_actions_completed_7d',v_completed,
    'portal_return_verified',v_portal_return
  );
end $function$


-- [40000000531] function public.tgg_autobuilder_detect_state()
CREATE OR REPLACE FUNCTION public.tgg_autobuilder_detect_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_ready integer;
  v_running integer;
  v_approval integer;
  v_blocked integer;
  v_unfinished integer;
  v_status text;
begin
  perform public.tgg_build_refresh_ready_tasks();

  with eligible as (
    select t.*
    from public.tgg_build_tasks t
    join public.tgg_build_milestones m on m.id=t.milestone_id
    join public.tgg_build_releases r on r.id=m.release_id
    where coalesce(r.target_environment,'staging') <> 'production'
      and coalesce((r.metadata->>'production_promotion_performed')::boolean,false) is not true
      and coalesce((r.metadata->>'production_deploy_performed')::boolean,false) is not true
      and (
        coalesce((r.metadata->>'canonical')::boolean,true) is not false
        or (
          coalesce((r.metadata->>'development_scope_approved')::boolean,false) is true
          and coalesce((r.metadata->>'development_only')::boolean,false) is true
        )
      )
      and coalesce((r.metadata->>'auto_builder_claim_allowed')::boolean,true) is not false
      and coalesce((r.metadata->>'historical_only')::boolean,false) is not true
      and (
        coalesce((r.metadata->>'historical_backlog')::boolean,false) is not true
        or coalesce((r.metadata->>'development_scope_approved')::boolean,false) is true
      )
  )
  select
    count(*) filter(where status='ready'),
    count(*) filter(where status in ('designing','building','testing','repairing','staging')),
    count(*) filter(where status='approval_required'),
    count(*) filter(where status='blocked'),
    count(*) filter(where status not in ('complete','passed','skipped'))
  into v_ready,v_running,v_approval,v_blocked,v_unfinished
  from eligible;

  v_status := case
    when v_unfinished=0 then 'complete'
    when v_ready>0 or v_running>0 then 'running'
    when v_approval>0 then 'waiting_approval'
    when v_blocked>0 then 'blocked'
    else 'blocked'
  end;

  return jsonb_build_object(
    'status',v_status,
    'ready',v_ready,
    'running',v_running,
    'approval_required',v_approval,
    'blocked',v_blocked,
    'unfinished',v_unfinished,
    'historical_noncanonical_excluded',true,
    'production_auto_claim_blocked',true,
    'high_risk_auto_claim_blocked',true,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end;
$function$


-- [40000000532] function public.tgg_autobuilder_finish_job(p_job_id uuid, p_outcome text, p_result jsonb)
CREATE OR REPLACE FUNCTION public.tgg_autobuilder_finish_job(p_job_id uuid, p_outcome text, p_result jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_job public.tgg_autobuilder_agent_jobs%rowtype;
  v_task public.tgg_build_tasks%rowtype;
  v_failure_id uuid;
begin
  if p_outcome not in ('passed','failed','blocked') then
    raise exception 'invalid job outcome: %',p_outcome;
  end if;

  select * into v_job
  from public.tgg_autobuilder_agent_jobs
  where id=p_job_id
  for update;

  if v_job.id is null then
    raise exception 'job not found: %',p_job_id;
  end if;

  select * into v_task
  from public.tgg_build_tasks
  where id=v_job.task_id
  for update;

  if p_outcome='passed' then
    update public.tgg_autobuilder_agent_jobs
    set status='passed',
        result=coalesce(p_result,'{}'::jsonb),
        attempts=attempts+1,
        finished_at=now()
    where id=p_job_id;

    perform public.tgg_build_finish_task(
      v_task.task_key,
      'complete',
      coalesce(p_result,'{}'::jsonb) || jsonb_build_object('agent_job_id',p_job_id)
    );

    return jsonb_build_object('status','passed','task_key',v_task.task_key);
  end if;

  insert into public.tgg_build_failures(
    task_id,failure_key,category,severity,status,message,detail
  )
  values(
    v_task.id,
    'autobuilder-job:' || p_job_id::text,
    'agent_job',
    case when p_outcome='blocked' then 'critical' else 'error' end,
    case when p_outcome='blocked' then 'blocked' else 'open' end,
    'Auto Builder agent job did not pass',
    coalesce(p_result,'{}'::jsonb)
  )
  returning id into v_failure_id;

  update public.tgg_autobuilder_agent_jobs
  set status=p_outcome,
      result=coalesce(p_result,'{}'::jsonb),
      attempts=attempts+1,
      finished_at=now()
  where id=p_job_id;

  if p_outcome='blocked' or v_task.retry_count + 1 >= v_task.max_retries then
    update public.tgg_build_tasks
    set status='blocked',
        retry_count=retry_count+1,
        locked_by=null,
        locked_at=null,
        updated_at=now(),
        last_result=coalesce(last_result,'{}'::jsonb) ||
          jsonb_build_object('failure_id',v_failure_id,'retry_exhausted',true)
    where id=v_task.id;

    return jsonb_build_object(
      'status','blocked',
      'task_key',v_task.task_key,
      'failure_id',v_failure_id
    );
  end if;

  update public.tgg_build_tasks
  set status='ready',
      retry_count=retry_count+1,
      locked_by=null,
      locked_at=null,
      updated_at=now(),
      last_result=coalesce(last_result,'{}'::jsonb) ||
        jsonb_build_object('failure_id',v_failure_id,'retry_scheduled',true)
  where id=v_task.id;

  return jsonb_build_object(
    'status','retry_ready',
    'task_key',v_task.task_key,
    'failure_id',v_failure_id,
    'retry_count',v_task.retry_count+1
  );
end;
$function$


