-- [40000000534] function public.tgg_autobuilder_run_cycle()
CREATE OR REPLACE FUNCTION public.tgg_autobuilder_run_cycle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_ctrl public.tgg_autobuilder_controller%rowtype;
  v_cycle uuid;
  v_claimed_count integer := 0;
  v_approval_count integer := 0;
  v_unfinished integer := 0;
  v_blocked integer := 0;
  v_cycle_status text;
  v_claimed jsonb := '[]'::jsonb;
  v_approvals jsonb := '[]'::jsonb;
  v_speed jsonb;
  v_batch_size integer := 5;
begin
  select * into v_ctrl
  from public.tgg_autobuilder_controller
  where id=1
  for update;

  if not v_ctrl.enabled then
    return jsonb_build_object(
      'status','paused',
      'reason','controller_disabled',
      'canonical_boundary','AB-006',
      'canonical_source_version','V223'
    );
  end if;

  v_speed := public.tgg_speed_booster_state();
  v_batch_size := greatest(
    1,
    least(
      25,
      coalesce((v_speed->>'effective_batch_size')::integer,v_ctrl.max_batch_size,5)
    )
  );

  perform public.tgg_build_refresh_ready_tasks();

  with eligible as (
    select t.*
    from public.tgg_build_tasks t
    join public.tgg_build_milestones m on m.id=t.milestone_id
    join public.tgg_build_releases r on r.id=m.release_id
    where (
        coalesce((r.metadata->>'canonical')::boolean,true) is not false
        or (
          coalesce((r.metadata->>'development_scope_approved')::boolean,false) is true
          and coalesce((r.metadata->>'development_only')::boolean,false) is true
        )
      )
      and coalesce((r.metadata->>'auto_builder_claim_allowed')::boolean,true) is not false
      and coalesce((r.metadata->>'historical_only')::boolean,false) is not true
      and (
        coalesce((r.metadata->>'historical_backlog')::boolean,false) is not true
        or coalesce((r.metadata->>'development_scope_approved')::boolean,false) is true
      )
  )
  select
    count(*) filter(where status='approval_required'),
    count(*) filter(where status not in ('complete','passed','skipped')),
    count(*) filter(where status='blocked')
  into v_approval_count,v_unfinished,v_blocked
  from eligible;

  with eligible as (
    select t.*
    from public.tgg_build_tasks t
    join public.tgg_build_milestones m on m.id=t.milestone_id
    join public.tgg_build_releases r on r.id=m.release_id
    where (
        coalesce((r.metadata->>'canonical')::boolean,true) is not false
        or (
          coalesce((r.metadata->>'development_scope_approved')::boolean,false) is true
          and coalesce((r.metadata->>'development_only')::boolean,false) is true
        )
      )
      and coalesce((r.metadata->>'auto_builder_claim_allowed')::boolean,true) is not false
      and coalesce((r.metadata->>'historical_only')::boolean,false) is not true
      and (
        coalesce((r.metadata->>'historical_backlog')::boolean,false) is not true
        or coalesce((r.metadata->>'development_scope_approved')::boolean,false) is true
      )
      and t.status='approval_required'
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'task_key',task_key,
        'title',title,
        'risk_level',risk_level
      )
      order by priority
    ),
    '[]'::jsonb
  )
  into v_approvals
  from eligible;

  insert into public.tgg_autobuilder_cycles(controller_id,status,approval_tasks)
  values(1,'running',v_approvals)
  returning id into v_cycle;

  insert into public.tgg_autobuilder_agent_jobs(
    cycle_id,task_id,agent_type,status,payload
  )
  select
    v_cycle,
    c.task_id,
    c.agent_type,
    'queued',
    jsonb_build_object(
      'task_key',c.task_key,
      'title',c.title,
      'task_type',c.task_type,
      'priority',c.priority,
      'risk_level',c.risk_level,
      'speed_mode',v_speed->>'mode',
      'effective_batch_size',v_batch_size
    )
  from public.tgg_build_claim_ready_batch(
    'full-auto-controller',
    v_batch_size
  ) c;

  get diagnostics v_claimed_count=row_count;

  select coalesce(jsonb_agg(payload order by created_at),'[]'::jsonb)
  into v_claimed
  from public.tgg_autobuilder_agent_jobs
  where cycle_id=v_cycle;

  v_cycle_status := case
    when v_claimed_count>0 then 'queued_work'
    when v_unfinished=0 then 'complete'
    when v_approval_count>0 then 'waiting_approval'
    when v_blocked>0 then 'blocked'
    else 'blocked'
  end;

  update public.tgg_autobuilder_cycles
  set status=v_cycle_status,
      claimed_tasks=v_claimed,
      summary=jsonb_build_object(
        'claimed_count',v_claimed_count,
        'approval_count',v_approval_count,
        'unfinished_count',v_unfinished,
        'blocked_count',v_blocked,
        'speed_booster',v_speed,
        'effective_batch_size',v_batch_size,
        'historical_noncanonical_excluded',true,
        'canonical_boundary','AB-006',
        'canonical_source_version','V223'
      ),
      finished_at=case when v_cycle_status<>'queued_work' then now() else null end
  where id=v_cycle;

  update public.tgg_autobuilder_controller
  set status=case v_cycle_status
      when 'queued_work' then 'running'
      when 'waiting_approval' then 'waiting_approval'
      when 'complete' then 'complete'
      when 'blocked' then 'blocked'
      else 'running'
    end,
    last_cycle_at=now(),
    last_cycle_result=jsonb_build_object(
      'cycle_id',v_cycle,
      'status',v_cycle_status,
      'claimed',v_claimed,
      'approvals',v_approvals,
      'speed_booster',v_speed,
      'effective_batch_size',v_batch_size,
      'historical_noncanonical_excluded',true,
      'canonical_boundary','AB-006',
      'canonical_source_version','V223'
    ),
    updated_at=now()
  where id=1;

  return jsonb_build_object(
    'cycle_id',v_cycle,
    'status',v_cycle_status,
    'claimed',v_claimed,
    'approvals',v_approvals,
    'speed_booster',v_speed,
    'effective_batch_size',v_batch_size,
    'historical_noncanonical_excluded',true,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end $function$


