-- [40000000538] function public.tgg_autonomic_completeness()
CREATE OR REPLACE FUNCTION public.tgg_autonomic_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_required_functions text[] := array[
    'tgg_brain_state','tgg_brain_reflect','tgg_brain_next_actions',
    'tgg_brain_goal_next_steps','tgg_brain_next_buildable_steps',
    'tgg_brain_simulate_goal','tgg_brain_trial_prepare','tgg_brain_trial_ready_for_staging',
    'tgg_brain_latest_scorecard','tgg_brain_checkpoint_create','tgg_brain_auto_recover_if_unsafe',
    'tgg_brain_architecture_scan','tgg_brain_lineage_refresh','tgg_brain_predict_change_set',
    'tgg_brain_prediction_accuracy','tgg_brain_execution_trace_state','tgg_brain_conflict_state',
    'tgg_brain_memory_hygiene_state','tgg_brain_spec_state','tgg_brain_spec_coverage',
    'tgg_brain_next_critical_unlocks','tgg_speed_booster_state','tgg_speed_booster_layer_plan',
    'tgg_autobuilder_watchdog','tgg_autonomic_scan','tgg_autonomic_run_cycle','tgg_autonomic_state',
    'tgg_provider_health_refresh','tgg_provider_health_state','tgg_autonomic_provider_sync',
    'tgg_release_train_plan','tgg_release_train_state','tgg_observability_state',
    'tgg_one_senses_refresh','tgg_one_senses_state',
    'tgg_one_heart_refresh','tgg_one_heart_state',
    'tgg_one_hair_refresh','tgg_one_hair_state',
    'tgg_one_layer_state','tgg_one_state','tgg_one_cycle','tgg_one_latest'
  ];
  v_required_tables text[] := array[
    'tgg_brain_memory','tgg_brain_decisions','tgg_brain_priorities',
    'tgg_brain_learning_events','tgg_brain_goals','tgg_brain_goal_steps',
    'tgg_brain_goal_dependencies','tgg_brain_simulations','tgg_brain_trials',
    'tgg_brain_trial_checks','tgg_brain_versions','tgg_brain_evaluations',
    'tgg_brain_checkpoints','tgg_brain_components','tgg_brain_component_links',
    'tgg_brain_lineage_evidence','tgg_brain_change_predictions',
    'tgg_brain_prediction_calibrations','tgg_brain_execution_traces',
    'tgg_brain_guardrails','tgg_brain_conflicts','tgg_brain_specs',
    'tgg_brain_spec_requirements','tgg_speed_booster_config','tgg_speed_booster_layers',
    'tgg_autonomic_events','tgg_autonomic_gaps','tgg_autonomic_cycles',
    'tgg_provider_health_snapshots','tgg_release_trains','tgg_observability_snapshots',
    'tgg_one_layers','tgg_one_cycles',
    'tgg_one_senses_snapshots','tgg_one_heart_snapshots','tgg_one_hair_snapshots'
  ];
  v_missing_functions jsonb;
  v_missing_tables jsonb;
  v_missing_crons jsonb;
  v_missing_triggers jsonb;
  v_layer_count integer:=0;
  v_ok boolean;
begin
  select coalesce(jsonb_agg(x order by x),'[]'::jsonb)
  into v_missing_functions
  from unnest(v_required_functions) x
  where not exists(
    select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname=x
  );

  select coalesce(jsonb_agg(x order by x),'[]'::jsonb)
  into v_missing_tables
  from unnest(v_required_tables) x
  where to_regclass('public.'||x) is null;

  with required(jobname) as (
    values
      ('tgg-autonomic-os-minute-loop'),
      ('tgg-autobuilder-continuous-watchdog'),
      ('tgg-brain-architecture-refresh'),
      ('tgg-brain-periodic-evaluation')
  )
  select coalesce(jsonb_agg(r.jobname order by r.jobname),'[]'::jsonb)
  into v_missing_crons
  from required r
  where not exists(select 1 from cron.job j where j.jobname=r.jobname and j.active=true);

  with required(trigger_name) as (
    values
      ('trg_tgg_autonomic_game_idea'),
      ('trg_tgg_autonomic_content'),
      ('trg_tgg_autonomic_master_content')
  )
  select coalesce(jsonb_agg(r.trigger_name order by r.trigger_name),'[]'::jsonb)
  into v_missing_triggers
  from required r
  where not exists(
    select 1 from pg_trigger t
    where t.tgname=r.trigger_name and not t.tgisinternal
  );

  select count(*) into v_layer_count
  from public.tgg_one_layers
  where active=true
    and layer_key in ('senses','shadow','head','mind','heart','body','spirit','soul','hair','the_one');

  v_ok :=
    jsonb_array_length(v_missing_functions)=0
    and jsonb_array_length(v_missing_tables)=0
    and jsonb_array_length(v_missing_crons)=0
    and jsonb_array_length(v_missing_triggers)=0
    and v_layer_count=10;

  return jsonb_build_object(
    'ok',v_ok,
    'required_function_count',cardinality(v_required_functions),
    'required_table_count',cardinality(v_required_tables),
    'required_one_layer_count',10,
    'active_required_one_layers',v_layer_count,
    'missing_functions',v_missing_functions,'missing_tables',v_missing_tables,
    'missing_crons',v_missing_crons,'missing_triggers',v_missing_triggers,
    'one_hierarchy_required',true,
    'one_hierarchy_order',jsonb_build_array(
      'senses','shadow','head','mind','heart','body','spirit','soul','hair','the_one'
    ),
    'canonical_boundary','AB-006','canonical_source_version','V223',
    'production_auto_publish',false,'high_risk_auto_execute',false
  );
end $function$


-- [40000000539] function public.tgg_autonomic_final_cycle()
CREATE OR REPLACE FUNCTION public.tgg_autonomic_final_cycle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_complete jsonb;
  v_provider jsonb;
  v_train jsonb;
  v_result jsonb;
  v_observe jsonb;
begin
  v_complete:=public.tgg_autonomic_completeness();

  if coalesce((v_complete->>'ok')::boolean,false) is not true then
    insert into public.tgg_autonomic_gaps(
      gap_key,gap_type,severity,source_ref,auto_fix_allowed,status,details,last_seen_at
    )
    values(
      'gap:autonomic-completeness','architecture','critical',
      'tgg_autonomic_completeness',true,'open',v_complete,now()
    )
    on conflict(gap_key) do update
      set status='open',severity='critical',auto_fix_allowed=true,
          details=excluded.details,last_seen_at=now(),resolved_at=null;

    return jsonb_build_object(
      'status','restricted','reason','missing_required_system_piece',
      'completeness',v_complete,'new_builds_allowed',false,'safe_repair_first',true,
      'canonical_boundary','AB-006','canonical_source_version','V223'
    );
  end if;

  update public.tgg_autonomic_gaps
  set status='resolved',resolved_at=now(),last_seen_at=now()
  where gap_key='gap:autonomic-completeness' and status<>'resolved';

  v_provider:=public.tgg_autonomic_provider_sync();
  v_result:=public.tgg_autonomic_run_cycle();

  if coalesce((v_result->>'status'),'complete')='complete'
     and coalesce((v_result->'state'->>'restricted')::boolean,false)=false then
    v_train:=public.tgg_release_train_plan(
      greatest(1,least(25,coalesce((public.tgg_speed_booster_state()->>'effective_batch_size')::integer,5)))
    );
  else
    v_train:=jsonb_build_object('ok',true,'status','skipped_restricted');
  end if;

  v_observe:=public.tgg_observability_state();

  return jsonb_build_object(
    'status',coalesce(v_result->>'status','complete'),
    'completeness',v_complete,'provider_sync',v_provider,'release_train',v_train,
    'observability',v_observe,'cycle',v_result,'new_builds_allowed',true,
    'missing_piece_scan_first',true,'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end $function$


-- [40000000540] function public.tgg_autonomic_provider_sync()
CREATE OR REPLACE FUNCTION public.tgg_autonomic_provider_sync()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_refresh jsonb;
  v_state jsonb;
  v_external integer:=0;
  v_degraded integer:=0;
  v_blocked integer:=0;
begin
  v_refresh:=public.tgg_provider_health_refresh();
  v_state:=public.tgg_provider_health_state();

  v_external:=coalesce((v_state->>'external_action_required')::integer,0);
  v_degraded:=coalesce((v_state->>'degraded')::integer,0);
  v_blocked:=coalesce((v_state->>'blocked')::integer,0);

  if v_degraded>0 or v_blocked>0 then
    insert into public.tgg_autonomic_gaps(
      gap_key,gap_type,severity,source_ref,auto_fix_allowed,status,details,last_seen_at
    )
    values(
      'gap:provider-health','approval_gate',
      case when v_blocked>0 then 'high' else 'medium' end,
      'tgg_provider_health_state',
      false,
      case when v_blocked>0 then 'approval_required' else 'external_required' end,
      v_state,now()
    )
    on conflict(gap_key) do update
      set severity=excluded.severity,status=excluded.status,details=excluded.details,
          last_seen_at=now(),resolved_at=null;
  else
    update public.tgg_autonomic_gaps
    set status='resolved',resolved_at=now(),last_seen_at=now()
    where gap_key='gap:provider-health' and status<>'resolved';
  end if;

  if v_external>0 and v_degraded=0 and v_blocked=0 then
    insert into public.tgg_autonomic_gaps(
      gap_key,gap_type,severity,source_ref,auto_fix_allowed,status,details,last_seen_at
    )
    values(
      'gap:provider-external-actions','approval_gate','low','tgg_provider_health_state',
      false,'external_required',v_state,now()
    )
    on conflict(gap_key) do update
      set status='external_required',details=excluded.details,last_seen_at=now(),resolved_at=null;
  elsif v_external=0 then
    update public.tgg_autonomic_gaps
    set status='resolved',resolved_at=now(),last_seen_at=now()
    where gap_key='gap:provider-external-actions' and status<>'resolved';
  end if;

  return jsonb_build_object(
    'ok',true,'refresh',v_refresh,'state',v_state,
    'production_change_performed',false
  );
end $function$


-- [40000000541] function public.tgg_autonomic_run_cycle()
CREATE OR REPLACE FUNCTION public.tgg_autonomic_run_cycle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cycle uuid;
  v_scan jsonb;
  v_scan_after jsonb;
  v_actions jsonb := '[]'::jsonb;
  v_watchdog jsonb;
  v_arch jsonb;
  v_compact jsonb;
  v_reflect jsonb;
  v_event_count integer := 0;
  v_restricted boolean := false;
  v_status text := 'complete';
begin
  v_scan := public.tgg_autonomic_scan();
  v_restricted := coalesce((v_scan->>'restricted')::boolean,false);

  insert into public.tgg_autonomic_cycles(status,speed_state,scan)
  values(
    case when v_restricted then 'restricted' else 'running' end,
    coalesce(v_scan->'speed','{}'::jsonb),
    v_scan
  )
  returning id into v_cycle;

  -- Always allow safe memory hygiene.
  if coalesce(((v_scan->'memory')->>'exact_duplicate_candidates')::integer,0)>0 then
    v_compact := public.tgg_brain_memory_compact();
    v_actions := v_actions || jsonb_build_array(
      jsonb_build_object('action','memory_compact','result',v_compact)
    );
  end if;

  -- Refresh architecture immediately when the map is unhealthy or new events arrived.
  select count(*) into v_event_count
  from public.tgg_autonomic_events
  where status='new';

  if coalesce((v_scan->'architecture'->>'drift_status'),'warning')='warning'
     or coalesce((v_scan->'architecture'->>'stale_components')::integer,0)>0
     or coalesce((v_scan->'architecture'->>'missing_since_previous')::integer,0)>0
     or v_event_count>0 then
    v_arch := public.tgg_brain_architecture_scan();
    v_actions := v_actions || jsonb_build_array(
      jsonb_build_object('action','architecture_scan','result',v_arch)
    );
  end if;

  -- Route newly captured events without performing production/content publication.
  update public.tgg_autonomic_events e
  set status='routed',
      processed_at=now()
  where e.status='new'
    and e.source_table='tgg_game_idea_inbox';

  get diagnostics v_event_count=row_count;
  if v_event_count>0 then
    v_actions := v_actions || jsonb_build_array(
      jsonb_build_object('action','route_game_ideas','count',v_event_count,'destination','game_idea_pipeline')
    );
  end if;

  update public.tgg_autonomic_events e
  set status='routed',
      processed_at=now()
  where e.status='new'
    and e.source_table in ('content_items','tgg_master_content');

  get diagnostics v_event_count=row_count;
  if v_event_count>0 then
    v_actions := v_actions || jsonb_build_array(
      jsonb_build_object(
        'action','observe_new_content',
        'count',v_event_count,
        'destination','content_health_and_sync_review',
        'production_publish_performed',false
      )
    );
  end if;

  -- Re-scan after safe preflight repairs/event routing.
  v_scan_after := public.tgg_autonomic_scan();
  v_restricted := coalesce((v_scan_after->>'restricted')::boolean,false);

  if v_restricted then
    -- Safety recovery may restore heuristics only; it never changes safety contract/production.
    if coalesce((v_scan_after->>'safety_score')::numeric,0)<100 then
      v_actions := v_actions || jsonb_build_array(
        jsonb_build_object(
          'action','brain_safe_recovery',
          'result',public.tgg_brain_auto_recover_if_unsafe('TGG-BRAIN-1.0-BASELINE')
        )
      );
    end if;

    v_status := 'restricted';
  else
    -- Existing watchdog owns safe repair/build claiming and respects the speed booster/controller gates.
    v_watchdog := public.tgg_autobuilder_watchdog();
    v_actions := v_actions || jsonb_build_array(
      jsonb_build_object('action','autobuilder_watchdog','result',v_watchdog)
    );

    -- Deduped reflection keeps learning current without manufacturing tasks.
    v_reflect := public.tgg_brain_reflect();
    v_actions := v_actions || jsonb_build_array(
      jsonb_build_object('action','brain_reflect','result',v_reflect)
    );

    v_status := 'complete';
  end if;

  v_scan_after := public.tgg_autonomic_scan();

  update public.tgg_autonomic_cycles
  set finished_at=now(),
      status=v_status,
      actions=v_actions,
      summary=jsonb_build_object(
        'restricted',coalesce((v_scan_after->>'restricted')::boolean,false),
        'safety_score',v_scan_after->'safety_score',
        'effective_batch_size',v_scan_after->'speed'->'effective_batch_size',
        'open_build_failures',v_scan_after->'open_build_failures',
        'active_game_ideas',v_scan_after->'active_game_ideas',
        'new_events',v_scan_after->'new_events',
        'open_creator_actions',v_scan_after->'open_creator_actions',
        'open_master_changes',v_scan_after->'open_master_changes',
        'canonical_boundary','AB-006',
        'canonical_source_version','V223',
        'production_auto_publish',false,
        'high_risk_auto_execute',false
      )
  where id=v_cycle;

  return jsonb_build_object(
    'cycle_id',v_cycle,
    'status',v_status,
    'actions',v_actions,
    'state',v_scan_after
  );
exception when others then
  if v_cycle is not null then
    update public.tgg_autonomic_cycles
    set finished_at=now(),
        status='failed',
        summary=jsonb_build_object(
          'error',sqlerrm,
          'canonical_boundary','AB-006',
          'canonical_source_version','V223',
          'production_auto_publish',false
        )
    where id=v_cycle;
  end if;
  raise;
end $function$


-- [40000000542] function public.tgg_autonomic_scan()
CREATE OR REPLACE FUNCTION public.tgg_autonomic_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_score jsonb;
  v_arch jsonb;
  v_conf jsonb;
  v_trace jsonb;
  v_speed jsonb;
  v_memory jsonb;
  v_spec jsonb;
  v_failures integer:=0;
  v_new_events integer:=0;
  v_new_ideas integer:=0;
  v_open_creator_actions integer:=0;
  v_open_master_changes integer:=0;
  v_restricted boolean:=false;
begin
  v_score:=public.tgg_brain_latest_scorecard();
  v_arch:=public.tgg_brain_architecture_latest();
  v_conf:=public.tgg_brain_conflict_state();
  v_trace:=public.tgg_brain_execution_trace_state();
  v_speed:=public.tgg_speed_booster_state();
  v_memory:=public.tgg_brain_memory_hygiene_state();
  v_spec:=public.tgg_brain_spec_state();

  select count(*) into v_failures
  from public.tgg_build_failures
  where resolved_at is null;

  select count(*) into v_new_events
  from public.tgg_autonomic_events
  where status='new';

  select count(*) into v_new_ideas
  from public.tgg_game_idea_inbox
  where status in ('new','planning','queued','building','testing','staged');

  select count(*) into v_open_creator_actions
  from public.tgg_creator_action_queue
  where status='open';

  select count(*) into v_open_master_changes
  from public.tgg_master_change_queue
  where status in ('pending','ready');

  -- Refresh machine-detectable gaps.
  insert into public.tgg_autonomic_gaps(gap_key,gap_type,severity,source_ref,auto_fix_allowed,status,details,last_seen_at)
  select 'gap:safety-score','safety','critical','brain_scorecard',true,'open',
    jsonb_build_object('safety_score',coalesce((v_score->>'safety_score')::numeric,0)),now()
  where coalesce((v_score->>'safety_score')::numeric,0)<100
  on conflict(gap_key) do update set status='open',details=excluded.details,last_seen_at=now(),resolved_at=null;

  if coalesce((v_score->>'safety_score')::numeric,0)>=100 then
    update public.tgg_autonomic_gaps set status='resolved',resolved_at=now(),last_seen_at=now()
    where gap_key='gap:safety-score' and status<>'resolved';
  end if;

  insert into public.tgg_autonomic_gaps(gap_key,gap_type,severity,source_ref,auto_fix_allowed,status,details,last_seen_at)
  select 'gap:architecture','architecture','high','brain_architecture',true,'open',v_arch,now()
  where coalesce(v_arch->>'drift_status','warning')='warning'
     or coalesce((v_arch->>'stale_components')::integer,0)>0
     or coalesce((v_arch->>'missing_since_previous')::integer,0)>0
  on conflict(gap_key) do update set status='open',details=excluded.details,last_seen_at=now(),resolved_at=null;

  if coalesce(v_arch->>'drift_status','warning')<>'warning'
     and coalesce((v_arch->>'stale_components')::integer,0)=0
     and coalesce((v_arch->>'missing_since_previous')::integer,0)=0 then
    update public.tgg_autonomic_gaps set status='resolved',resolved_at=now(),last_seen_at=now()
    where gap_key='gap:architecture' and status<>'resolved';
  end if;

  insert into public.tgg_autonomic_gaps(gap_key,gap_type,severity,source_ref,auto_fix_allowed,status,details,last_seen_at)
  select 'gap:conflicts','conflict','critical','brain_conflicts',false,'approval_required',v_conf,now()
  where coalesce((v_conf->>'critical_open')::integer,0)>0
     or coalesce((v_conf->>'blocked_open')::integer,0)>0
  on conflict(gap_key) do update set status='approval_required',details=excluded.details,last_seen_at=now(),resolved_at=null;

  if coalesce((v_conf->>'critical_open')::integer,0)=0
     and coalesce((v_conf->>'blocked_open')::integer,0)=0 then
    update public.tgg_autonomic_gaps set status='resolved',resolved_at=now(),last_seen_at=now()
    where gap_key='gap:conflicts' and status<>'resolved';
  end if;

  insert into public.tgg_autonomic_gaps(gap_key,gap_type,severity,source_ref,auto_fix_allowed,status,details,last_seen_at)
  select 'gap:trace-boundary','trace','critical','brain_execution_trace',false,'approval_required',v_trace,now()
  where coalesce((v_trace->>'production_touched')::integer,0)>0
     or coalesce((v_trace->>'high_risk_executed')::integer,0)>0
     or coalesce((v_trace->>'boundary_violations')::integer,0)>0
  on conflict(gap_key) do update set status='approval_required',details=excluded.details,last_seen_at=now(),resolved_at=null;

  if coalesce((v_trace->>'production_touched')::integer,0)=0
     and coalesce((v_trace->>'high_risk_executed')::integer,0)=0
     and coalesce((v_trace->>'boundary_violations')::integer,0)=0 then
    update public.tgg_autonomic_gaps set status='resolved',resolved_at=now(),last_seen_at=now()
    where gap_key='gap:trace-boundary' and status<>'resolved';
  end if;

  insert into public.tgg_autonomic_gaps(gap_key,gap_type,severity,source_ref,auto_fix_allowed,status,details,last_seen_at)
  select 'gap:build-failures','build_failure','high','tgg_build_failures',true,'open',
    jsonb_build_object('open_failures',v_failures),now()
  where v_failures>0
  on conflict(gap_key) do update set status='open',details=excluded.details,last_seen_at=now(),resolved_at=null;

  if v_failures=0 then
    update public.tgg_autonomic_gaps set status='resolved',resolved_at=now(),last_seen_at=now()
    where gap_key='gap:build-failures' and status<>'resolved';
  end if;

  -- Human/external growth outcomes are tracked but never auto-faked.
  if v_open_creator_actions>0 then
    insert into public.tgg_autonomic_gaps(gap_key,gap_type,severity,source_ref,auto_fix_allowed,status,details,last_seen_at)
    values('gap:creator-growth-actions','human_action','low','tgg_creator_action_queue',false,'external_required',
      jsonb_build_object('open_actions',v_open_creator_actions),now())
    on conflict(gap_key) do update set status='external_required',details=excluded.details,last_seen_at=now(),resolved_at=null;
  else
    update public.tgg_autonomic_gaps set status='resolved',resolved_at=now(),last_seen_at=now()
    where gap_key='gap:creator-growth-actions' and status<>'resolved';
  end if;

  if v_open_master_changes>0 then
    insert into public.tgg_autonomic_gaps(gap_key,gap_type,severity,source_ref,auto_fix_allowed,status,details,last_seen_at)
    values('gap:master-change-queue','approval_gate','high','tgg_master_change_queue',false,'approval_required',
      jsonb_build_object('pending_or_ready',v_open_master_changes),now())
    on conflict(gap_key) do update set status='approval_required',details=excluded.details,last_seen_at=now(),resolved_at=null;
  else
    update public.tgg_autonomic_gaps set status='resolved',resolved_at=now(),last_seen_at=now()
    where gap_key='gap:master-change-queue' and status<>'resolved';
  end if;

  v_restricted :=
    coalesce((v_score->>'safety_score')::numeric,0)<100
    or coalesce(v_arch->>'drift_status','warning')='warning'
    or coalesce((v_conf->>'critical_open')::integer,0)>0
    or coalesce((v_conf->>'blocked_open')::integer,0)>0
    or coalesce((v_trace->>'boundary_violations')::integer,0)>0;

  return jsonb_build_object(
    'restricted',v_restricted,
    'speed',v_speed,
    'safety_score',coalesce((v_score->>'safety_score')::numeric,0),
    'architecture',v_arch,
    'conflicts',v_conf,
    'trace',v_trace,
    'memory',v_memory,
    'specs',v_spec,
    'open_build_failures',v_failures,
    'new_events',v_new_events,
    'active_game_ideas',v_new_ideas,
    'open_creator_actions',v_open_creator_actions,
    'open_master_changes',v_open_master_changes,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223',
    'production_auto_publish',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000000543] function public.tgg_autonomic_state()
CREATE OR REPLACE FUNCTION public.tgg_autonomic_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'latest_cycle',(
      select jsonb_build_object(
        'id',id,'started_at',started_at,'finished_at',finished_at,'status',status,
        'summary',summary
      )
      from public.tgg_autonomic_cycles
      order by started_at desc
      limit 1
    ),
    'gaps',jsonb_build_object(
      'open',(select count(*) from public.tgg_autonomic_gaps where status='open'),
      'repairing',(select count(*) from public.tgg_autonomic_gaps where status='repairing'),
      'approval_required',(select count(*) from public.tgg_autonomic_gaps where status='approval_required'),
      'external_required',(select count(*) from public.tgg_autonomic_gaps where status='external_required')
    ),
    'events',jsonb_build_object(
      'new',(select count(*) from public.tgg_autonomic_events where status='new'),
      'routed',(select count(*) from public.tgg_autonomic_events where status='routed'),
      'blocked',(select count(*) from public.tgg_autonomic_events where status='blocked')
    ),
    'scan',public.tgg_autonomic_scan()
  )
$function$


-- [40000000544] function public.tgg_beat_pattern_save(p_project_id uuid, p_name text, p_bpm numeric, p_steps integer, p_pattern_data jsonb, p_pattern_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_beat_pattern_save(p_project_id uuid, p_name text, p_bpm numeric, p_steps integer, p_pattern_data jsonb, p_pattern_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_row public.tgg_beat_patterns;
  v_name text:=btrim(coalesce(p_name,''));
  v_can_edit boolean:=false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(v_name)<1 or char_length(v_name)>100 then raise exception 'PATTERN_NAME_INVALID'; end if;
  if p_bpm<30 or p_bpm>300 then raise exception 'BPM_INVALID'; end if;
  if p_steps not in (8,16,32,64) then raise exception 'STEPS_INVALID'; end if;
  if jsonb_typeof(coalesce(p_pattern_data,'{}'::jsonb)) not in ('object','array') then
    raise exception 'PATTERN_DATA_INVALID';
  end if;

  select exists(
    select 1
    from public.tgg_studio_projects p
    where p.id=p_project_id
      and p.project_type='beat'
      and (
        p.user_id=v_uid
        or exists(
          select 1
          from public.tgg_studio_project_members m
          where m.project_id=p.id
            and m.user_id=v_uid
            and m.left_at is null
            and m.can_edit
        )
      )
  ) into v_can_edit;

  if not v_can_edit then raise exception 'BEAT_PROJECT_NOT_EDITABLE'; end if;

  if p_pattern_id is null then
    insert into public.tgg_beat_patterns(project_id,user_id,name,bpm,steps,pattern_data,pattern,updated_at)
    values(p_project_id,v_uid,v_name,p_bpm,p_steps,p_pattern_data,p_pattern_data,now())
    returning * into v_row;
  else
    update public.tgg_beat_patterns
    set name=v_name,bpm=p_bpm,steps=p_steps,pattern_data=p_pattern_data,pattern=p_pattern_data,updated_at=now()
    where id=p_pattern_id and project_id=p_project_id
    returning * into v_row;
    if v_row.id is null then raise exception 'PATTERN_NOT_FOUND_OR_NOT_EDITABLE'; end if;
  end if;

  return jsonb_build_object(
    'ok',true,
    'pattern_id',v_row.id,
    'project_id',v_row.project_id,
    'created_by',v_row.user_id,
    'name',v_row.name,
    'bpm',v_row.bpm,
    'steps',v_row.steps,
    'updated_at',v_row.updated_at
  );
end;
$function$


