-- [40000000546] function public.tgg_brain_architecture_latest()
CREATE OR REPLACE FUNCTION public.tgg_brain_architecture_latest()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'scan_id',id,
    'scanned_at',scanned_at,
    'active_components',active_components,
    'active_tables',active_tables,
    'active_functions',active_functions,
    'stale_components',stale_components,
    'new_since_previous',new_since_previous,
    'missing_since_previous',missing_since_previous,
    'drift_status',drift_status,
    'summary',summary
  )
  from public.tgg_brain_architecture_scans
  order by scanned_at desc
  limit 1
$function$


-- [40000000547] function public.tgg_brain_architecture_refresh()
CREATE OR REPLACE FUNCTION public.tgg_brain_architecture_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tables integer := 0;
  v_functions integer := 0;
  v_verified integer := 0;
  v_now timestamptz := now();
begin
  -- Relevant public TGG tables.
  with src as (
    select
      'dbtable:'||c.table_name as component_key,
      c.table_name as name,
      case
        when c.table_name like 'tgg_world_%' then 'game'
        when c.table_name like 'tgg_brain_%' then 'brain'
        when c.table_name like 'tgg_build_%' or c.table_name like 'tgg_autobuilder_%' then 'build'
        when c.table_name like 'tgg_creator_%' then 'creator_platform'
        else 'platform'
      end as owner_domain,
      case
        when c.table_name like 'tgg_brain_%' then 'medium'
        when c.table_name like 'tgg_world_%' then 'medium'
        when c.table_name like 'tgg_build_%' or c.table_name like 'tgg_autobuilder_%' then 'high'
        else 'medium'
      end as risk_level
    from information_schema.tables c
    where c.table_schema='public'
      and (
        c.table_name like 'tgg_world_%'
        or c.table_name like 'tgg_brain_%'
        or c.table_name like 'tgg_build_%'
        or c.table_name like 'tgg_autobuilder_%'
        or c.table_name like 'tgg_creator_%'
      )
  ),
  upserted as (
    insert into public.tgg_brain_components(
      component_key,component_type,name,environment,source_ref,canonical,active,
      risk_level,owner_domain,capabilities,constraints,metadata,health_status,last_verified_at,updated_at
    )
    select
      s.component_key,'database_table',s.name,'shared',
      'table:public.'||s.name,false,true,s.risk_level,s.owner_domain,
      jsonb_build_array('database_storage'),
      jsonb_build_array('internal_component'),
      jsonb_build_object('auto_discovered',true,'schema','public'),
      'healthy',v_now,v_now
    from src s
    on conflict(component_key) do update
      set component_type='database_table',
          name=excluded.name,
          source_ref=excluded.source_ref,
          active=true,
          risk_level=excluded.risk_level,
          owner_domain=excluded.owner_domain,
          metadata=public.tgg_brain_components.metadata || excluded.metadata,
          health_status='healthy',
          last_verified_at=v_now,
          updated_at=v_now
    returning 1
  )
  select count(*) into v_tables from upserted;

  -- Relevant public/private TGG functions, excluding pg/internal extensions.
  with src as (
    select
      'dbfn:'||n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' as component_key,
      p.proname as name,
      n.nspname as schema_name,
      case
        when p.proname like 'tgg_world_%' then 'game'
        when p.proname like 'tgg_brain_%' then 'brain'
        when p.proname like 'tgg_build_%' or p.proname like 'tgg_autobuilder_%' then 'build'
        when p.proname like 'tgg_creator_%' then 'creator_platform'
        else 'platform'
      end as owner_domain,
      case
        when p.prosecdef then 'high'
        when p.proname like 'tgg_build_%' or p.proname like 'tgg_autobuilder_%' then 'high'
        else 'medium'
      end as risk_level,
      p.prosecdef as security_definer
    from pg_proc p
    join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in ('public','private')
      and (
        p.proname like 'tgg_world_%'
        or p.proname like 'tgg_brain_%'
        or p.proname like 'tgg_build_%'
        or p.proname like 'tgg_autobuilder_%'
        or p.proname like 'tgg_creator_%'
      )
  ),
  upserted as (
    insert into public.tgg_brain_components(
      component_key,component_type,name,environment,source_ref,canonical,active,
      risk_level,owner_domain,capabilities,constraints,metadata,health_status,last_verified_at,updated_at
    )
    select
      s.component_key,'database_function',s.name,'shared',
      'function:'||s.schema_name||'.'||s.name,false,true,s.risk_level,s.owner_domain,
      jsonb_build_array('database_rpc'),
      case when s.security_definer
        then jsonb_build_array('security_definer','internal_review_required')
        else jsonb_build_array('internal_component')
      end,
      jsonb_build_object('auto_discovered',true,'schema',s.schema_name,'security_definer',s.security_definer),
      'healthy',v_now,v_now
    from src s
    on conflict(component_key) do update
      set component_type='database_function',
          name=excluded.name,
          source_ref=excluded.source_ref,
          active=true,
          risk_level=excluded.risk_level,
          owner_domain=excluded.owner_domain,
          constraints=excluded.constraints,
          metadata=public.tgg_brain_components.metadata || excluded.metadata,
          health_status='healthy',
          last_verified_at=v_now,
          updated_at=v_now
    returning 1
  )
  select count(*) into v_functions from upserted;

  -- Mark only previously auto-discovered DB objects stale if they have not been
  -- seen in this complete catalog refresh. Do not retire manually curated components.
  update public.tgg_brain_components c
  set health_status='warning',
      active=false,
      updated_at=v_now,
      metadata=c.metadata || jsonb_build_object('stale_detected_at',v_now)
  where coalesce((c.metadata->>'auto_discovered')::boolean,false)=true
    and c.component_type in ('database_table','database_function')
    and c.last_verified_at < v_now
    and not exists (
      select 1
      from information_schema.tables t
      where c.component_type='database_table'
        and c.component_key='dbtable:'||t.table_name
        and t.table_schema='public'
    )
    and not exists (
      select 1
      from pg_proc p
      join pg_namespace n on n.oid=p.pronamespace
      where c.component_type='database_function'
        and c.component_key='dbfn:'||n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')'
        and n.nspname in ('public','private')
    );

  select count(*) into v_verified
  from public.tgg_brain_components
  where active=true and last_verified_at=v_now;

  return jsonb_build_object(
    'ok',true,
    'refreshed_at',v_now,
    'tables_seen',v_tables,
    'functions_seen',v_functions,
    'components_verified',v_verified,
    'auto_retire_manual_components',false
  );
end $function$


-- [40000000548] function public.tgg_brain_architecture_scan()
CREATE OR REPLACE FUNCTION public.tgg_brain_architecture_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_refresh jsonb;
  v_lineage jsonb;
  v_now timestamptz := now();
  v_active integer := 0;
  v_tables integer := 0;
  v_functions integer := 0;
  v_stale integer := 0;
  v_prev public.tgg_brain_architecture_scans%rowtype;
  v_new integer := 0;
  v_missing integer := 0;
  v_status text := 'clean';
  v_key text;
  v_id uuid;
begin
  v_refresh := public.tgg_brain_architecture_refresh();
  v_lineage := public.tgg_brain_lineage_refresh();

  select count(*) filter(where active=true),
         count(*) filter(where active=true and component_type='database_table'),
         count(*) filter(where active=true and component_type='database_function'),
         count(*) filter(where active=false and coalesce((metadata->>'auto_discovered')::boolean,false)=true)
  into v_active,v_tables,v_functions,v_stale
  from public.tgg_brain_components;

  select * into v_prev
  from public.tgg_brain_architecture_scans
  order by scanned_at desc
  limit 1;

  if found then
    v_new := greatest(v_active-v_prev.active_components,0);
    v_missing := greatest(v_prev.active_components-v_active,0);
  end if;

  if v_missing>0 or v_stale>0 then
    v_status := 'warning';
  elsif v_new>0 then
    v_status := 'changed';
  else
    v_status := 'clean';
  end if;

  v_key := 'archscan:'||replace(gen_random_uuid()::text,'-','');

  insert into public.tgg_brain_architecture_scans(
    scan_key,scanned_at,active_components,active_tables,active_functions,
    stale_components,new_since_previous,missing_since_previous,drift_status,summary
  )
  values(
    v_key,v_now,v_active,v_tables,v_functions,v_stale,v_new,v_missing,v_status,
    jsonb_build_object(
      'refresh',v_refresh,
      'lineage',v_lineage,
      'production_auto_publish',false,
      'high_risk_auto_execute',false,
      'canonical_boundary','AB-006',
      'canonical_source_version','V223'
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,
    'scan_id',v_id,
    'drift_status',v_status,
    'active_components',v_active,
    'active_tables',v_tables,
    'active_functions',v_functions,
    'stale_components',v_stale,
    'new_since_previous',v_new,
    'missing_since_previous',v_missing,
    'lineage',v_lineage
  );
end $function$


-- [40000000549] function public.tgg_brain_auto_recover_if_unsafe(p_checkpoint_key text)
CREATE OR REPLACE FUNCTION public.tgg_brain_auto_recover_if_unsafe(p_checkpoint_key text DEFAULT 'TGG-BRAIN-1.0-BASELINE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_score jsonb;
  v_safety numeric;
  v_preview jsonb;
  v_restore jsonb;
begin
  v_score := public.tgg_brain_latest_scorecard();

  if v_score is null then
    return jsonb_build_object('ok',true,'action','none','reason','no_scorecard');
  end if;

  v_safety := coalesce((v_score->>'safety_score')::numeric,100);

  if v_safety >= 100 then
    return jsonb_build_object(
      'ok',true,'action','none','reason','safety_healthy',
      'safety_score',v_safety
    );
  end if;

  v_preview := public.tgg_brain_checkpoint_preview_restore(p_checkpoint_key);

  if coalesce((v_preview->>'restore_allowed')::boolean,false) is not true then
    return jsonb_build_object(
      'ok',false,'action','blocked',
      'reason','checkpoint_safety_contract_mismatch',
      'safety_score',v_safety,
      'preview',v_preview
    );
  end if;

  v_restore := public.tgg_brain_checkpoint_restore(p_checkpoint_key);

  return jsonb_build_object(
    'ok',true,
    'action','heuristics_restored',
    'reason','safety_score_below_100',
    'safety_score',v_safety,
    'restore',v_restore,
    'safety_contract_changed',false,
    'production_touched',false
  );
end $function$


-- [40000000550] function public.tgg_brain_calibrate_prediction(p_prediction_id uuid, p_trial_id uuid, p_actual_component_keys jsonb, p_actual_test_types jsonb)
CREATE OR REPLACE FUNCTION public.tgg_brain_calibrate_prediction(p_prediction_id uuid, p_trial_id uuid DEFAULT NULL::uuid, p_actual_component_keys jsonb DEFAULT '[]'::jsonb, p_actual_test_types jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_pred public.tgg_brain_change_predictions%rowtype;
  v_pred_components text[];
  v_actual_components text[];
  v_pred_tests text[];
  v_actual_tests text[];
  v_pred_count integer := 0;
  v_actual_count integer := 0;
  v_match integer := 0;
  v_missed integer := 0;
  v_over integer := 0;
  v_pred_test_count integer := 0;
  v_actual_test_count integer := 0;
  v_test_match integer := 0;
  v_precision numeric := 100;
  v_recall numeric := 100;
  v_test_match_score numeric := 100;
  v_score numeric := 100;
  v_status text := 'complete';
  v_id uuid;
begin
  select * into v_pred
  from public.tgg_brain_change_predictions
  where id=p_prediction_id;

  if not found then raise exception 'prediction_not_found'; end if;

  select coalesce(array_agg(distinct x->>'component_key'),array[]::text[])
  into v_pred_components
  from jsonb_array_elements(v_pred.predicted_edits) x
  where x ? 'component_key';

  select coalesce(array_agg(distinct value),array[]::text[])
  into v_actual_components
  from jsonb_array_elements_text(coalesce(p_actual_component_keys,'[]'::jsonb));

  select coalesce(array_agg(distinct value),array[]::text[])
  into v_pred_tests
  from jsonb_array_elements_text(v_pred.predicted_tests);

  select coalesce(array_agg(distinct value),array[]::text[])
  into v_actual_tests
  from jsonb_array_elements_text(coalesce(p_actual_test_types,'[]'::jsonb));

  v_pred_count := cardinality(v_pred_components);
  v_actual_count := cardinality(v_actual_components);
  v_pred_test_count := cardinality(v_pred_tests);
  v_actual_test_count := cardinality(v_actual_tests);

  select count(*) into v_match
  from unnest(v_pred_components) p
  where p=any(v_actual_components);

  v_missed := greatest(v_actual_count-v_match,0);
  v_over := greatest(v_pred_count-v_match,0);

  select count(*) into v_test_match
  from unnest(v_pred_tests) p
  where p=any(v_actual_tests);

  if v_pred_count>0 then
    v_precision := round((v_match::numeric/v_pred_count)*100,2);
  end if;
  if v_actual_count>0 then
    v_recall := round((v_match::numeric/v_actual_count)*100,2);
  end if;
  if v_pred_test_count>0 then
    v_test_match_score := round((v_test_match::numeric/v_pred_test_count)*100,2);
  end if;

  if v_actual_count=0 and v_actual_test_count=0 then
    v_status := 'insufficient_evidence';
    v_score := 0;
  else
    v_score := round(v_precision*0.35 + v_recall*0.40 + v_test_match_score*0.25,2);
    if v_score<80 then v_status:='warning'; end if;
  end if;

  insert into public.tgg_brain_prediction_calibrations(
    prediction_id,trial_id,
    predicted_component_count,actual_component_count,matched_component_count,
    missed_component_count,overpredicted_component_count,
    predicted_test_count,actual_test_count,matched_test_count,
    component_precision,component_recall,test_coverage_match,
    calibration_score,status,summary
  )
  values(
    p_prediction_id,p_trial_id,
    v_pred_count,v_actual_count,v_match,v_missed,v_over,
    v_pred_test_count,v_actual_test_count,v_test_match,
    v_precision,v_recall,v_test_match_score,
    v_score,v_status,
    jsonb_build_object(
      'source_component_key',v_pred.source_component_key,
      'predicted_risk',v_pred.predicted_risk,
      'approval_required',v_pred.approval_required,
      'actual_component_keys',coalesce(p_actual_component_keys,'[]'::jsonb),
      'actual_test_types',coalesce(p_actual_test_types,'[]'::jsonb)
    )
  )
  on conflict(prediction_id,trial_id) do update
  set predicted_component_count=excluded.predicted_component_count,
      actual_component_count=excluded.actual_component_count,
      matched_component_count=excluded.matched_component_count,
      missed_component_count=excluded.missed_component_count,
      overpredicted_component_count=excluded.overpredicted_component_count,
      predicted_test_count=excluded.predicted_test_count,
      actual_test_count=excluded.actual_test_count,
      matched_test_count=excluded.matched_test_count,
      component_precision=excluded.component_precision,
      component_recall=excluded.component_recall,
      test_coverage_match=excluded.test_coverage_match,
      calibration_score=excluded.calibration_score,
      status=excluded.status,
      summary=excluded.summary,
      created_at=now()
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,
    'calibration_id',v_id,
    'status',v_status,
    'component_precision',v_precision,
    'component_recall',v_recall,
    'test_coverage_match',v_test_match_score,
    'calibration_score',v_score,
    'missed_components',v_missed,
    'overpredicted_components',v_over
  );
end $function$


-- [40000000551] function public.tgg_brain_checkpoint_create(p_checkpoint_key text, p_label text)
CREATE OR REPLACE FUNCTION public.tgg_brain_checkpoint_create(p_checkpoint_key text, p_label text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tgg_brain_versions%rowtype;
  v_score jsonb;
  v_eval_id uuid;
  v_id uuid;
begin
  select * into v_version
  from public.tgg_brain_versions
  where status='active'
  order by version_no desc
  limit 1;

  if not found then raise exception 'active_brain_version_required'; end if;

  v_score := public.tgg_brain_latest_scorecard();
  v_eval_id := nullif(v_score->>'evaluation_id','')::uuid;

  insert into public.tgg_brain_checkpoints(
    checkpoint_key,brain_version_id,label,heuristics,safety_contract,scorecard,source_evaluation_id,state
  )
  values(
    trim(p_checkpoint_key),v_version.id,trim(p_label),
    v_version.heuristics,v_version.safety_contract,coalesce(v_score,'{}'::jsonb),v_eval_id,'ready'
  )
  on conflict(checkpoint_key) do update
    set label=excluded.label,
        heuristics=excluded.heuristics,
        safety_contract=excluded.safety_contract,
        scorecard=excluded.scorecard,
        source_evaluation_id=excluded.source_evaluation_id,
        state='ready'
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'checkpoint_id',v_id,'checkpoint_key',p_checkpoint_key,
    'brain_version',v_version.version_key,
    'safety_contract',v_version.safety_contract
  );
end $function$


-- [40000000552] function public.tgg_brain_checkpoint_preview_restore(p_checkpoint_key text)
CREATE OR REPLACE FUNCTION public.tgg_brain_checkpoint_preview_restore(p_checkpoint_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cp public.tgg_brain_checkpoints%rowtype;
  v_active public.tgg_brain_versions%rowtype;
begin
  select * into v_cp
  from public.tgg_brain_checkpoints
  where checkpoint_key=p_checkpoint_key and state in ('ready','restored');

  if not found then raise exception 'checkpoint_not_found'; end if;

  select * into v_active
  from public.tgg_brain_versions
  where status='active'
  order by version_no desc limit 1;

  return jsonb_build_object(
    'checkpoint_key',v_cp.checkpoint_key,
    'checkpoint_version_id',v_cp.brain_version_id,
    'current_version',v_active.version_key,
    'heuristics_change',v_active.heuristics is distinct from v_cp.heuristics,
    'safety_contract_change',v_active.safety_contract is distinct from v_cp.safety_contract,
    'checkpoint_scorecard',v_cp.scorecard,
    'restore_allowed',
      v_active.safety_contract = v_cp.safety_contract,
    'requires_manual_restore',true
  );
end $function$


-- [40000000553] function public.tgg_brain_checkpoint_restore(p_checkpoint_key text)
CREATE OR REPLACE FUNCTION public.tgg_brain_checkpoint_restore(p_checkpoint_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cp public.tgg_brain_checkpoints%rowtype;
  v_active public.tgg_brain_versions%rowtype;
begin
  if current_user <> 'postgres' then raise exception 'internal_worker_only'; end if;

  select * into v_cp
  from public.tgg_brain_checkpoints
  where checkpoint_key=p_checkpoint_key and state in ('ready','restored');

  if not found then raise exception 'checkpoint_not_found'; end if;

  select * into v_active
  from public.tgg_brain_versions
  where status='active'
  order by version_no desc limit 1;

  if v_active.safety_contract is distinct from v_cp.safety_contract then
    raise exception 'safety_contract_mismatch_restore_blocked';
  end if;

  update public.tgg_brain_versions
  set heuristics=v_cp.heuristics,
      updated_at=now()
  where id=v_active.id;

  update public.tgg_brain_checkpoints
  set state='restored',restored_at=now()
  where id=v_cp.id;

  return jsonb_build_object(
    'ok',true,
    'checkpoint_key',p_checkpoint_key,
    'restored_heuristics',true,
    'safety_contract_changed',false,
    'production_touched',false
  );
end $function$


-- [40000000554] function public.tgg_brain_component_find(p_query text, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_brain_component_find(p_query text, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'component_key',component_key,
    'component_type',component_type,
    'name',name,
    'environment',environment,
    'risk_level',risk_level,
    'canonical',canonical,
    'owner_domain',owner_domain,
    'capabilities',capabilities,
    'source_ref',source_ref,
    'health_status',health_status
  ) order by canonical desc,name),'[]'::jsonb)
  from (
    select *
    from public.tgg_brain_components
    where active=true
      and (
        component_key ilike '%'||trim(p_query)||'%'
        or name ilike '%'||trim(p_query)||'%'
        or coalesce(owner_domain,'') ilike '%'||trim(p_query)||'%'
        or capabilities::text ilike '%'||trim(p_query)||'%'
      )
    limit greatest(1,least(50,p_limit))
  ) q
$function$


-- [40000000555] function public.tgg_brain_component_impact(p_component_key text, p_depth integer)
CREATE OR REPLACE FUNCTION public.tgg_brain_component_impact(p_component_key text, p_depth integer DEFAULT 2)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with recursive seed as (
    select id,component_key,component_type,name,environment,risk_level,canonical,0 as depth
    from public.tgg_brain_components
    where component_key=p_component_key and active=true
  ),
  walk as (
    select * from seed
    union
    select c.id,c.component_key,c.component_type,c.name,c.environment,c.risk_level,c.canonical,w.depth+1
    from walk w
    join public.tgg_brain_component_links l on l.to_component_id=w.id
    join public.tgg_brain_components c on c.id=l.from_component_id and c.active=true
    where w.depth < greatest(0,least(5,p_depth))
  )
  select jsonb_build_object(
    'component_key',p_component_key,
    'affected_count',(select count(distinct id) from walk)-1,
    'affected_components',coalesce((
      select jsonb_agg(jsonb_build_object(
        'component_key',component_key,
        'component_type',component_type,
        'name',name,
        'environment',environment,
        'risk_level',risk_level,
        'canonical',canonical,
        'depth',depth
      ) order by depth,component_key)
      from (
        select distinct on(id) id,component_key,component_type,name,environment,risk_level,canonical,depth
        from walk
        where depth>0
        order by id,depth
      ) q
    ),'[]'::jsonb),
    'production_affected',exists(select 1 from walk where depth>0 and environment='production'),
    'high_risk_affected',exists(select 1 from walk where depth>0 and risk_level='high')
  )
$function$


-- [40000000556] function public.tgg_brain_component_link(p_from_key text, p_to_key text, p_relationship text, p_strength integer, p_required boolean, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_brain_component_link(p_from_key text, p_to_key text, p_relationship text, p_strength integer DEFAULT 50, p_required boolean DEFAULT true, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_from uuid; v_to uuid;
begin
  if p_relationship not in ('depends_on','reads','writes','calls','renders','routes_to','authenticates_via','deploys_to','tests','monitors','backs_up','syncs_with','extends') then
    raise exception 'invalid_relationship';
  end if;

  select id into v_from from public.tgg_brain_components where component_key=p_from_key and active=true;
  select id into v_to from public.tgg_brain_components where component_key=p_to_key and active=true;

  if v_from is null or v_to is null then raise exception 'component_not_found'; end if;
  if v_from=v_to then raise exception 'self_link_forbidden'; end if;

  insert into public.tgg_brain_component_links(
    from_component_id,to_component_id,relationship,strength,required,metadata
  )
  values(v_from,v_to,p_relationship,greatest(1,least(100,p_strength)),coalesce(p_required,true),coalesce(p_metadata,'{}'::jsonb))
  on conflict(from_component_id,to_component_id,relationship) do update
  set strength=excluded.strength,required=excluded.required,metadata=excluded.metadata;

  return jsonb_build_object('ok',true,'from',p_from_key,'to',p_to_key,'relationship',p_relationship);
end $function$


-- [40000000557] function public.tgg_brain_component_upsert(p_component_key text, p_component_type text, p_name text, p_environment text, p_source_ref text, p_canonical boolean, p_risk_level text, p_owner_domain text, p_capabilities jsonb, p_constraints jsonb, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_brain_component_upsert(p_component_key text, p_component_type text, p_name text, p_environment text DEFAULT 'shared'::text, p_source_ref text DEFAULT NULL::text, p_canonical boolean DEFAULT false, p_risk_level text DEFAULT 'medium'::text, p_owner_domain text DEFAULT NULL::text, p_capabilities jsonb DEFAULT '[]'::jsonb, p_constraints jsonb DEFAULT '[]'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if p_component_type not in ('database_table','database_function','edge_function','page','api','worker','cron','ui_module','game_system','integration','repository_path') then
    raise exception 'invalid_component_type';
  end if;
  if p_environment not in ('shared','development','staging','production') then
    raise exception 'invalid_environment';
  end if;
  if p_risk_level not in ('low','medium','high') then
    raise exception 'invalid_risk_level';
  end if;

  insert into public.tgg_brain_components(
    component_key,component_type,name,environment,source_ref,canonical,active,risk_level,
    owner_domain,capabilities,constraints,metadata,updated_at
  )
  values(
    trim(p_component_key),p_component_type,trim(p_name),p_environment,p_source_ref,
    coalesce(p_canonical,false),true,p_risk_level,p_owner_domain,
    coalesce(p_capabilities,'[]'::jsonb),coalesce(p_constraints,'[]'::jsonb),
    coalesce(p_metadata,'{}'::jsonb),now()
  )
  on conflict(component_key) do update
  set component_type=excluded.component_type,
      name=excluded.name,
      environment=excluded.environment,
      source_ref=coalesce(excluded.source_ref,public.tgg_brain_components.source_ref),
      canonical=excluded.canonical,
      active=true,
      risk_level=excluded.risk_level,
      owner_domain=excluded.owner_domain,
      capabilities=excluded.capabilities,
      constraints=excluded.constraints,
      metadata=excluded.metadata,
      updated_at=now()
  returning id into v_id;

  return jsonb_build_object('ok',true,'component_id',v_id,'component_key',p_component_key);
end $function$


-- [40000000558] function public.tgg_brain_conflict_state()
CREATE OR REPLACE FUNCTION public.tgg_brain_conflict_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'active_guardrails',(select count(*) from public.tgg_brain_guardrails where active=true),
    'open_conflicts',count(*) filter(where c.status='open'),
    'critical_open',count(*) filter(where c.status='open' and c.severity='critical'),
    'high_open',count(*) filter(where c.status='open' and c.severity='high'),
    'approval_required_open',count(*) filter(where c.status='open' and c.required_action='approval_required'),
    'blocked_open',count(*) filter(where c.status='open' and c.required_action='block')
  )
  from public.tgg_brain_conflicts c
$function$


-- [40000000559] function public.tgg_brain_context_pack(p_query text, p_memory_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_brain_context_pack(p_query text, p_memory_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_memory jsonb;
  v_components jsonb;
  v_decisions jsonb;
  v_guardrails jsonb;
begin
  v_memory := public.tgg_brain_recall(p_query,p_memory_limit);

  with tokens as (
    select distinct tok
    from regexp_split_to_table(lower(trim(coalesce(p_query,''))), E'[^a-z0-9_:-]+') tok
    where length(tok)>=3
  ),
  scored as (
    select
      c.*,
      (
        case when lower(c.name)=lower(trim(p_query)) then 60 else 0 end
        + case when lower(c.name) like '%'||lower(trim(p_query))||'%' and trim(p_query)<>'' then 40 else 0 end
        + case when c.canonical then 20 else 0 end
        + (
          select coalesce(count(*),0)*12
          from tokens t
          where lower(c.name) like '%'||t.tok||'%'
             or lower(c.component_key) like '%'||t.tok||'%'
             or lower(coalesce(c.owner_domain,'')) like '%'||t.tok||'%'
             or lower(c.capabilities::text) like '%'||t.tok||'%'
        )
      ) as relevance_score
    from public.tgg_brain_components c
    where c.active=true
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'component_key',component_key,
    'component_type',component_type,
    'name',name,
    'environment',environment,
    'risk_level',risk_level,
    'canonical',canonical,
    'owner_domain',owner_domain,
    'capabilities',capabilities,
    'source_ref',source_ref,
    'health_status',health_status,
    'relevance_score',relevance_score
  ) order by relevance_score desc,canonical desc,name),'[]'::jsonb)
  into v_components
  from (
    select *
    from scored
    where relevance_score>0
    order by relevance_score desc,canonical desc,name
    limit 10
  ) q;

  with tokens as (
    select distinct tok
    from regexp_split_to_table(lower(trim(coalesce(p_query,''))), E'[^a-z0-9_:-]+') tok
    where length(tok)>=3
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'decision_key',d.decision_key,
    'subject',d.subject,
    'decision',d.decision,
    'constraints',d.constraints,
    'reversible',d.reversible
  ) order by d.updated_at desc),'[]'::jsonb)
  into v_decisions
  from public.tgg_brain_decisions d
  where d.status='active'
    and (
      p_query=''
      or exists(
        select 1 from tokens t
        where lower(d.subject) like '%'||t.tok||'%'
           or lower(d.decision) like '%'||t.tok||'%'
           or lower(d.constraints::text) like '%'||t.tok||'%'
      )
    );

  select coalesce(jsonb_agg(jsonb_build_object(
    'guardrail_key',guardrail_key,
    'category',category,
    'severity',severity,
    'action',action,
    'rule',rule
  ) order by
      case severity when 'critical' then 1 when 'high' then 2 else 3 end,
      guardrail_key
  ),'[]'::jsonb)
  into v_guardrails
  from public.tgg_brain_guardrails
  where active=true;

  return jsonb_build_object(
    'query',p_query,
    'memory',v_memory,
    'matching_components',v_components,
    'matching_decisions',v_decisions,
    'active_guardrails',v_guardrails,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223',
    'production_auto_publish',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000000560] function public.tgg_brain_critical_path(p_goal_id uuid, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_brain_critical_path(p_goal_id uuid, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
with recursive edges as (
  select
    s.id as step_id,
    d.goal_step_id as dependent_id
  from public.tgg_brain_goal_steps s
  join public.tgg_brain_goal_dependencies d
    on d.depends_on_step_id=s.id
  where s.goal_id=p_goal_id
),
closure as (
  select e.step_id,e.dependent_id,1 as depth
  from edges e
  union all
  select c.step_id,e.dependent_id,c.depth+1
  from closure c
  join edges e on e.step_id=c.dependent_id
  where c.depth<50
),
unlock_counts as (
  select step_id,count(distinct dependent_id) as downstream_unlocks
  from closure
  group by step_id
),
dep_state as (
  select
    s.id,
    count(d.depends_on_step_id) as dependency_count,
    count(d.depends_on_step_id) filter(where dep.status='complete') as complete_dependencies
  from public.tgg_brain_goal_steps s
  left join public.tgg_brain_goal_dependencies d on d.goal_step_id=s.id
  left join public.tgg_brain_goal_steps dep on dep.id=d.depends_on_step_id
  where s.goal_id=p_goal_id
  group by s.id
),
ranked as (
  select
    s.id,
    s.step_key,
    s.title,
    s.step_type,
    s.status,
    s.sequence_no,
    s.risk_level,
    s.acceptance,
    coalesce(u.downstream_unlocks,0) as downstream_unlocks,
    ds.dependency_count,
    ds.complete_dependencies,
    (ds.dependency_count=ds.complete_dependencies) as dependencies_satisfied,
    case
      when s.risk_level='high' then false
      when s.status in ('complete','skipped','approval_required','blocked') then false
      when ds.dependency_count<>ds.complete_dependencies then false
      else true
    end as autonomous_candidate,
    (
      coalesce(u.downstream_unlocks,0)*20
      + case s.status when 'ready' then 30 when 'queued' then 20 when 'repairing' then 25 else 10 end
      + greatest(0,20-s.sequence_no)
      - case s.risk_level when 'medium' then 10 else 0 end
    )::numeric as unlock_score
  from public.tgg_brain_goal_steps s
  join dep_state ds on ds.id=s.id
  left join unlock_counts u on u.step_id=s.id
  where s.goal_id=p_goal_id
    and s.status not in ('complete','skipped')
)
select jsonb_build_object(
  'goal_id',p_goal_id,
  'critical_path',coalesce((
    select jsonb_agg(jsonb_build_object(
      'step_id',id,
      'step_key',step_key,
      'title',title,
      'step_type',step_type,
      'status',status,
      'sequence_no',sequence_no,
      'risk_level',risk_level,
      'downstream_unlocks',downstream_unlocks,
      'dependency_count',dependency_count,
      'complete_dependencies',complete_dependencies,
      'dependencies_satisfied',dependencies_satisfied,
      'autonomous_candidate',autonomous_candidate,
      'unlock_score',unlock_score,
      'acceptance',acceptance
    ) order by unlock_score desc,sequence_no)
    from (
      select *
      from ranked
      order by unlock_score desc,sequence_no
      limit greatest(1,least(50,p_limit))
    ) q
  ),'[]'::jsonb),
  'next_safe_unlock',(
    select jsonb_build_object(
      'step_id',id,
      'step_key',step_key,
      'title',title,
      'unlock_score',unlock_score,
      'downstream_unlocks',downstream_unlocks
    )
    from ranked
    where autonomous_candidate=true
    order by unlock_score desc,sequence_no
    limit 1
  ),
  'blocked_or_approval_count',(
    select count(*) from ranked
    where status in ('blocked','approval_required') or risk_level='high'
  ),
  'safe_ready_count',(
    select count(*) from ranked where autonomous_candidate=true
  )
)
$function$


-- [40000000561] function public.tgg_brain_decide(p_decision_key text, p_subject text, p_decision text, p_rationale jsonb, p_constraints jsonb, p_reversible boolean)
CREATE OR REPLACE FUNCTION public.tgg_brain_decide(p_decision_key text, p_subject text, p_decision text, p_rationale jsonb DEFAULT '{}'::jsonb, p_constraints jsonb DEFAULT '[]'::jsonb, p_reversible boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  insert into public.tgg_brain_decisions(decision_key,subject,decision,rationale,constraints,reversible)
  values(trim(p_decision_key),trim(p_subject),trim(p_decision),coalesce(p_rationale,'{}'::jsonb),coalesce(p_constraints,'[]'::jsonb),coalesce(p_reversible,true))
  on conflict(decision_key) do update
    set subject=excluded.subject,
        decision=excluded.decision,
        rationale=excluded.rationale,
        constraints=excluded.constraints,
        reversible=excluded.reversible,
        status='active',
        superseded_by=null,
        updated_at=now()
  returning id into v_id;
  return jsonb_build_object('ok',true,'decision_id',v_id,'decision_key',p_decision_key);
end $function$


-- [40000000562] function public.tgg_brain_evaluate(p_window interval)
CREATE OR REPLACE FUNCTION public.tgg_brain_evaluate(p_window interval DEFAULT '24:00:00'::interval)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tgg_brain_versions%rowtype;
  v_start timestamptz := now()-p_window;
  v_end timestamptz := now();
  v_completed integer := 0;
  v_failed integer := 0;
  v_recovered integer := 0;
  v_qa_total integer := 0;
  v_qa_passed integer := 0;
  v_play_total integer := 0;
  v_play_passed integer := 0;
  v_stale integer := 0;
  v_dupes integer := 0;
  v_prod_drift integer := 0;
  v_highrisk integer := 0;
  v_completion numeric := 100;
  v_qa numeric := 100;
  v_resilience numeric := 100;
  v_safety numeric := 100;
  v_overall numeric := 100;
  v_rec text := 'hold_current_heuristics';
  v_key text;
  v_id uuid;
begin
  select * into v_version
  from public.tgg_brain_versions
  where status='active'
  order by version_no desc
  limit 1;

  if not found then raise exception 'active_brain_version_required'; end if;

  select count(*) into v_completed
  from public.tgg_build_tasks
  where status='complete'
    and coalesce(completed_at,updated_at,created_at)>=v_start;

  select
    count(*) filter(where status<>'resolved'),
    count(*) filter(where status='resolved')
  into v_failed,v_recovered
  from public.tgg_build_failures
  where coalesce(resolved_at,first_seen_at)>=v_start;

  select
    (select count(*) from public.tgg_browser_qa_results where checked_at>=v_start)
    +(select count(*) from public.tgg_visual_qa_results where checked_at>=v_start),
    (select count(*) from public.tgg_browser_qa_results where checked_at>=v_start and status='passed')
    +(select count(*) from public.tgg_visual_qa_results where checked_at>=v_start and status='passed')
  into v_qa_total,v_qa_passed;

  select count(*),count(*) filter(where status='passed')
  into v_play_total,v_play_passed
  from public.tgg_playtest_runs
  where coalesce(finished_at,started_at)>=v_start;

  select count(*) into v_stale
  from public.tgg_game_idea_inbox
  where updated_at>=v_start
    and last_error='auto_recovered_stale_worker';

  select coalesce(sum(duplicate_count),0) into v_dupes
  from public.tgg_game_idea_inbox
  where updated_at>=v_start;

  select count(*) into v_prod_drift
  from public.tgg_operational_audit_log
  where occurred_at>=v_start
    and (
      payload->>'production_state_changed'='true'
      or payload->>'production_touched'='true'
    );

  select count(*) into v_highrisk
  from public.tgg_build_tasks t
  where t.updated_at>=v_start
    and t.risk_level='high'
    and t.status in ('building','testing','complete')
    and coalesce(t.locked_by,'') ilike '%auto%';

  if (v_completed+v_failed)>0 then
    v_completion := round((v_completed::numeric/(v_completed+v_failed))*100,2);
  end if;

  if v_qa_total>0 then
    v_qa := round((v_qa_passed::numeric/v_qa_total)*100,2);
  end if;

  v_resilience := greatest(0,least(100,
    100 - least(v_failed*8,40) + least(v_recovered*4,20) - least(v_stale*3,15)
  ));

  v_safety := greatest(0,least(100,
    100 - least(v_prod_drift*50,100) - least(v_highrisk*50,100)
  ));

  v_overall := round(
    v_completion*0.30 + v_qa*0.25 + v_resilience*0.20 + v_safety*0.25
  ,2);

  if v_safety<100 then
    v_rec := 'freeze_heuristic_changes_and_review_safety';
  elsif v_overall<70 then
    v_rec := 'tighten_qa_and_reduce_batch_size';
  elsif v_qa<85 then
    v_rec := 'increase_qa_depth';
  elsif v_completion<85 then
    v_rec := 'improve_dependency_planning';
  elsif v_resilience<85 then
    v_rec := 'improve_retry_and_repair_strategy';
  else
    v_rec := 'hold_current_heuristics';
  end if;

  v_key := 'eval:'||v_version.version_key||':'||replace(gen_random_uuid()::text,'-','');

  insert into public.tgg_brain_evaluations(
    evaluation_key,brain_version_id,window_start,window_end,
    completed_tasks,failed_tasks,recovered_failures,
    qa_total,qa_passed,playtests_total,playtests_passed,
    stale_recoveries,duplicate_preventions,
    production_drift_count,high_risk_auto_executions,
    completion_score,qa_score,resilience_score,safety_score,overall_score,
    recommendation,metrics
  )
  values(
    v_key,v_version.id,v_start,v_end,
    v_completed,v_failed,v_recovered,
    v_qa_total,v_qa_passed,v_play_total,v_play_passed,
    v_stale,v_dupes,v_prod_drift,v_highrisk,
    v_completion,v_qa,v_resilience,v_safety,v_overall,
    v_rec,
    jsonb_build_object(
      'window',p_window::text,
      'brain_version',v_version.version_key,
      'duplicate_preventions',v_dupes,
      'playtest_pass_rate',case when v_play_total=0 then null else round((v_play_passed::numeric/v_play_total)*100,2) end
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'evaluation_id',v_id,'brain_version',v_version.version_key,
    'completion_score',v_completion,'qa_score',v_qa,
    'resilience_score',v_resilience,'safety_score',v_safety,
    'overall_score',v_overall,'recommendation',v_rec
  );
end $function$


-- [40000000563] function public.tgg_brain_execution_trace_record(p_trace_key text, p_goal_id uuid, p_step_id uuid, p_prediction_id uuid, p_build_task_id uuid, p_trial_id uuid, p_calibration_id uuid, p_source_control jsonb, p_actual_components jsonb, p_actual_tests jsonb, p_acceptance_evidence jsonb, p_production_touched boolean, p_high_risk_executed boolean)
CREATE OR REPLACE FUNCTION public.tgg_brain_execution_trace_record(p_trace_key text, p_goal_id uuid DEFAULT NULL::uuid, p_step_id uuid DEFAULT NULL::uuid, p_prediction_id uuid DEFAULT NULL::uuid, p_build_task_id uuid DEFAULT NULL::uuid, p_trial_id uuid DEFAULT NULL::uuid, p_calibration_id uuid DEFAULT NULL::uuid, p_source_control jsonb DEFAULT '{}'::jsonb, p_actual_components jsonb DEFAULT '[]'::jsonb, p_actual_tests jsonb DEFAULT '[]'::jsonb, p_acceptance_evidence jsonb DEFAULT '[]'::jsonb, p_production_touched boolean DEFAULT false, p_high_risk_executed boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_step public.tgg_brain_goal_steps%rowtype;
  v_pred public.tgg_brain_change_predictions%rowtype;
  v_trial public.tgg_brain_trials%rowtype;
  v_plan_match boolean := false;
  v_prediction_match boolean := false;
  v_trial_passed boolean := false;
  v_acceptance_passed boolean := false;
  v_boundary boolean := true;
  v_status text := 'incomplete';
  v_id uuid;
  v_pred_components text[];
  v_actual_components text[];
  v_pred_tests text[];
  v_actual_tests text[];
  v_acceptance_count integer := 0;
  v_acceptance_pass_count integer := 0;
begin
  if p_step_id is not null then
    select * into v_step from public.tgg_brain_goal_steps where id=p_step_id;
  end if;

  if p_prediction_id is not null then
    select * into v_pred from public.tgg_brain_change_predictions where id=p_prediction_id;
  end if;

  if p_trial_id is not null then
    select * into v_trial from public.tgg_brain_trials where id=p_trial_id;
  end if;

  v_plan_match :=
    p_step_id is not null
    and v_step.id is not null
    and (p_goal_id is null or v_step.goal_id=p_goal_id);

  if v_pred.id is not null then
    select coalesce(array_agg(distinct x->>'component_key'),array[]::text[])
    into v_pred_components
    from jsonb_array_elements(v_pred.predicted_edits) x
    where x ? 'component_key';

    select coalesce(array_agg(distinct value),array[]::text[])
    into v_actual_components
    from jsonb_array_elements_text(coalesce(p_actual_components,'[]'::jsonb));

    select coalesce(array_agg(distinct value),array[]::text[])
    into v_pred_tests
    from jsonb_array_elements_text(v_pred.predicted_tests);

    select coalesce(array_agg(distinct value),array[]::text[])
    into v_actual_tests
    from jsonb_array_elements_text(coalesce(p_actual_tests,'[]'::jsonb));

    v_prediction_match :=
      (cardinality(v_pred_components)=0 or v_pred_components <@ v_actual_components)
      and (cardinality(v_pred_tests)=0 or v_pred_tests <@ v_actual_tests);
  end if;

  v_trial_passed :=
    v_trial.id is not null
    and v_trial.status='passed'
    and v_trial.verdict in ('safe_for_staging','advance_with_expanded_qa')
    and v_trial.production_touched=false;

  select count(*),
         count(*) filter(
           where coalesce((x->>'passed')::boolean,false)=true
         )
  into v_acceptance_count,v_acceptance_pass_count
  from jsonb_array_elements(coalesce(p_acceptance_evidence,'[]'::jsonb)) x;

  if v_step.id is not null and jsonb_array_length(coalesce(v_step.acceptance,'[]'::jsonb))=0 then
    v_acceptance_passed := true;
  elsif v_acceptance_count>0 and v_acceptance_count=v_acceptance_pass_count then
    v_acceptance_passed := true;
  else
    v_acceptance_passed := false;
  end if;

  v_boundary :=
    coalesce(p_production_touched,false)=false
    and coalesce(p_high_risk_executed,false)=false
    and coalesce(v_pred.canonical_affected,false)=false;

  if coalesce(p_production_touched,false) or coalesce(p_high_risk_executed,false) then
    v_status := 'blocked';
  elsif v_plan_match and v_prediction_match and v_trial_passed and v_acceptance_passed and v_boundary then
    v_status := 'verified';
  elsif v_trial.id is not null and v_trial.status in ('failed','blocked') then
    v_status := 'blocked';
  elsif v_plan_match or v_trial.id is not null or v_pred.id is not null then
    v_status := 'warning';
  else
    v_status := 'incomplete';
  end if;

  insert into public.tgg_brain_execution_traces(
    trace_key,goal_id,step_id,prediction_id,build_task_id,trial_id,calibration_id,
    source_control,actual_components,actual_tests,acceptance_evidence,
    plan_match,prediction_match,trial_passed,acceptance_passed,
    production_touched,high_risk_executed,canonical_boundary_preserved,
    trace_status,summary,updated_at
  )
  values(
    trim(p_trace_key),p_goal_id,p_step_id,p_prediction_id,p_build_task_id,p_trial_id,p_calibration_id,
    coalesce(p_source_control,'{}'::jsonb),coalesce(p_actual_components,'[]'::jsonb),
    coalesce(p_actual_tests,'[]'::jsonb),coalesce(p_acceptance_evidence,'[]'::jsonb),
    v_plan_match,v_prediction_match,v_trial_passed,v_acceptance_passed,
    coalesce(p_production_touched,false),coalesce(p_high_risk_executed,false),v_boundary,
    v_status,
    jsonb_build_object(
      'brain_version','TGG-BRAIN-1.0',
      'canonical_boundary','AB-006',
      'canonical_source_version','V223',
      'predicted_component_count',coalesce(cardinality(v_pred_components),0),
      'actual_component_count',coalesce(cardinality(v_actual_components),0),
      'predicted_test_count',coalesce(cardinality(v_pred_tests),0),
      'actual_test_count',coalesce(cardinality(v_actual_tests),0)
    ),
    now()
  )
  on conflict(trace_key) do update
  set goal_id=excluded.goal_id,
      step_id=excluded.step_id,
      prediction_id=excluded.prediction_id,
      build_task_id=excluded.build_task_id,
      trial_id=excluded.trial_id,
      calibration_id=excluded.calibration_id,
      source_control=excluded.source_control,
      actual_components=excluded.actual_components,
      actual_tests=excluded.actual_tests,
      acceptance_evidence=excluded.acceptance_evidence,
      plan_match=excluded.plan_match,
      prediction_match=excluded.prediction_match,
      trial_passed=excluded.trial_passed,
      acceptance_passed=excluded.acceptance_passed,
      production_touched=excluded.production_touched,
      high_risk_executed=excluded.high_risk_executed,
      canonical_boundary_preserved=excluded.canonical_boundary_preserved,
      trace_status=excluded.trace_status,
      summary=excluded.summary,
      updated_at=now()
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,
    'trace_id',v_id,
    'trace_key',p_trace_key,
    'trace_status',v_status,
    'plan_match',v_plan_match,
    'prediction_match',v_prediction_match,
    'trial_passed',v_trial_passed,
    'acceptance_passed',v_acceptance_passed,
    'canonical_boundary_preserved',v_boundary,
    'production_touched',coalesce(p_production_touched,false),
    'high_risk_executed',coalesce(p_high_risk_executed,false)
  );
end $function$


-- [40000000564] function public.tgg_brain_execution_trace_state()
CREATE OR REPLACE FUNCTION public.tgg_brain_execution_trace_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'total',count(*),
    'verified',count(*) filter(where trace_status='verified'),
    'warnings',count(*) filter(where trace_status='warning'),
    'blocked',count(*) filter(where trace_status='blocked'),
    'incomplete',count(*) filter(where trace_status='incomplete'),
    'production_touched',count(*) filter(where production_touched=true),
    'high_risk_executed',count(*) filter(where high_risk_executed=true),
    'boundary_violations',count(*) filter(where canonical_boundary_preserved=false)
  )
  from public.tgg_brain_execution_traces
$function$


-- [40000000565] function public.tgg_brain_goal_add_dependency(p_step_id uuid, p_depends_on_step_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_brain_goal_add_dependency(p_step_id uuid, p_depends_on_step_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_step_id=p_depends_on_step_id then raise exception 'self_dependency_forbidden'; end if;

  if exists(
    with recursive walk(step_id) as (
      select p_depends_on_step_id
      union
      select d.depends_on_step_id
      from public.tgg_brain_goal_dependencies d
      join walk w on d.goal_step_id=w.step_id
    )
    select 1 from walk where step_id=p_step_id
  ) then
    raise exception 'cyclic_dependency_forbidden';
  end if;

  insert into public.tgg_brain_goal_dependencies(goal_step_id,depends_on_step_id)
  values(p_step_id,p_depends_on_step_id)
  on conflict do nothing;

  return jsonb_build_object('ok',true,'step_id',p_step_id,'depends_on_step_id',p_depends_on_step_id);
end $function$


-- [40000000566] function public.tgg_brain_goal_add_step(p_goal_id uuid, p_step_key text, p_title text, p_step_type text, p_sequence_no integer, p_risk_level text, p_acceptance jsonb)
CREATE OR REPLACE FUNCTION public.tgg_brain_goal_add_step(p_goal_id uuid, p_step_key text, p_title text, p_step_type text, p_sequence_no integer, p_risk_level text DEFAULT 'medium'::text, p_acceptance jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if p_step_type not in ('research','design','schema','backend','frontend','integration','qa','playtest','repair','staging','source_control') then
    raise exception 'invalid_step_type';
  end if;
  if p_risk_level not in ('low','medium','high') then raise exception 'invalid_risk_level'; end if;

  insert into public.tgg_brain_goal_steps(
    goal_id,step_key,title,step_type,status,sequence_no,risk_level,acceptance
  )
  values(
    p_goal_id,trim(p_step_key),trim(p_title),p_step_type,'queued',p_sequence_no,p_risk_level,
    coalesce(p_acceptance,'[]'::jsonb)
  )
  on conflict(goal_id,step_key) do update
    set title=excluded.title,step_type=excluded.step_type,sequence_no=excluded.sequence_no,
        risk_level=excluded.risk_level,acceptance=excluded.acceptance,updated_at=now()
  returning id into v_id;

  return jsonb_build_object('ok',true,'step_id',v_id,'step_key',p_step_key);
end $function$


-- [40000000567] function public.tgg_brain_goal_create(p_goal_key text, p_title text, p_objective text, p_source_idea_id uuid, p_priority_score numeric, p_risk_level text, p_plan_summary jsonb)
CREATE OR REPLACE FUNCTION public.tgg_brain_goal_create(p_goal_key text, p_title text, p_objective text, p_source_idea_id uuid DEFAULT NULL::uuid, p_priority_score numeric DEFAULT 50, p_risk_level text DEFAULT 'medium'::text, p_plan_summary jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if p_risk_level not in ('low','medium','high') then raise exception 'invalid_risk_level'; end if;

  insert into public.tgg_brain_goals(
    goal_key,source_idea_id,title,objective,status,priority_score,risk_level,
    development_only,production_allowed,plan_summary
  )
  values(
    trim(p_goal_key),p_source_idea_id,trim(p_title),trim(p_objective),'planning',
    greatest(0,least(100,p_priority_score)),p_risk_level,true,false,coalesce(p_plan_summary,'{}'::jsonb)
  )
  on conflict(goal_key) do update
    set source_idea_id=coalesce(excluded.source_idea_id,public.tgg_brain_goals.source_idea_id),
        title=excluded.title,objective=excluded.objective,priority_score=excluded.priority_score,
        risk_level=excluded.risk_level,plan_summary=excluded.plan_summary,updated_at=now()
  returning id into v_id;

  return jsonb_build_object('ok',true,'goal_id',v_id,'goal_key',p_goal_key);
end $function$


-- [40000000568] function public.tgg_brain_goal_next_steps(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_brain_goal_next_steps(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'goal_id',g.id,
      'goal_key',g.goal_key,
      'goal_title',g.title,
      'goal_priority',g.priority_score,
      'step_id',s.id,
      'step_key',s.step_key,
      'step_title',s.title,
      'step_type',s.step_type,
      'step_risk',s.risk_level,
      'acceptance',s.acceptance
    )
    order by g.priority_score desc,s.sequence_no
  ),'[]'::jsonb)
  from (
    select s.*
    from public.tgg_brain_goal_steps s
    where s.status='ready'
      and s.risk_level<>'high'
    order by s.sequence_no
    limit greatest(1,least(25,p_limit))
  ) s
  join public.tgg_brain_goals g on g.id=s.goal_id
  where g.development_only=true
    and g.production_allowed=false
    and g.risk_level<>'high'
$function$


-- [40000000569] function public.tgg_brain_goal_refresh_ready()
CREATE OR REPLACE FUNCTION public.tgg_brain_goal_refresh_ready()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_ready integer := 0; v_waiting integer := 0; v_completed_goals integer := 0;
begin
  update public.tgg_brain_goal_steps s
  set status='ready',updated_at=now()
  where s.status='queued'
    and s.risk_level<>'high'
    and not exists(
      select 1
      from public.tgg_brain_goal_dependencies d
      join public.tgg_brain_goal_steps dep on dep.id=d.depends_on_step_id
      where d.goal_step_id=s.id and dep.status<>'complete'
    );
  get diagnostics v_ready = row_count;

  select count(*) into v_waiting
  from public.tgg_brain_goal_steps s
  where s.status='queued';

  update public.tgg_brain_goals g
  set status='complete',completed_at=coalesce(completed_at,now()),updated_at=now()
  where g.status not in ('complete','canceled')
    and exists(select 1 from public.tgg_brain_goal_steps s where s.goal_id=g.id)
    and not exists(
      select 1 from public.tgg_brain_goal_steps s
      where s.goal_id=g.id and s.status not in ('complete','skipped')
    );
  get diagnostics v_completed_goals = row_count;

  update public.tgg_brain_goals g
  set status=case
    when exists(select 1 from public.tgg_brain_goal_steps s where s.goal_id=g.id and s.status='approval_required') then 'approval_required'
    when exists(select 1 from public.tgg_brain_goal_steps s where s.goal_id=g.id and s.status in ('building','testing')) then 'building'
    when exists(select 1 from public.tgg_brain_goal_steps s where s.goal_id=g.id and s.status='ready') then 'ready'
    when exists(select 1 from public.tgg_brain_goal_steps s where s.goal_id=g.id and s.status='blocked') then 'blocked'
    else g.status
  end,
  updated_at=now()
  where g.status not in ('complete','canceled');

  return jsonb_build_object(
    'ok',true,'newly_ready',v_ready,'waiting_on_dependencies',v_waiting,
    'goals_completed',v_completed_goals
  );
end $function$


-- [40000000570] function public.tgg_brain_guardrail_check(p_subject_type text, p_subject_key text, p_action jsonb)
CREATE OR REPLACE FUNCTION public.tgg_brain_guardrail_check(p_subject_type text, p_subject_key text, p_action jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  v_field text;
  v_forbidden jsonb;
  v_actual jsonb;
  v_conflicts jsonb := '[]'::jsonb;
  v_count integer := 0;
  v_key text;
begin
  if p_subject_type not in ('idea','goal','step','prediction','action','decision','system') then
    raise exception 'invalid_subject_type';
  end if;

  for r in
    select * from public.tgg_brain_guardrails
    where active=true
    order by
      case severity when 'critical' then 1 when 'high' then 2 else 3 end,
      guardrail_key
  loop
    v_field := r.rule->>'field';
    v_forbidden := r.rule->'forbidden_value';
    v_actual := coalesce(p_action,'{}'::jsonb)->v_field;

    if v_actual is not null and v_actual=v_forbidden then
      v_key := 'conflict:'||md5(
        p_subject_type||':'||p_subject_key||':'||r.guardrail_key||':'||coalesce(p_action,'{}'::jsonb)::text
      );

      insert into public.tgg_brain_conflicts(
        conflict_key,guardrail_id,subject_type,subject_key,proposed_action,
        severity,required_action,status,evidence
      )
      values(
        v_key,r.id,p_subject_type,p_subject_key,coalesce(p_action,'{}'::jsonb),
        r.severity,r.action,'open',
        jsonb_build_object(
          'guardrail_key',r.guardrail_key,
          'field',v_field,
          'forbidden_value',v_forbidden,
          'actual_value',v_actual,
          'source_ref',r.source_ref
        )
      )
      on conflict(conflict_key) do update
      set status='open',
          evidence=excluded.evidence;

      v_conflicts := v_conflicts || jsonb_build_array(
        jsonb_build_object(
          'guardrail_key',r.guardrail_key,
          'category',r.category,
          'severity',r.severity,
          'required_action',r.action,
          'field',v_field
        )
      );
      v_count := v_count+1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',v_count=0,
    'subject_type',p_subject_type,
    'subject_key',p_subject_key,
    'conflict_count',v_count,
    'conflicts',v_conflicts,
    'allow_autonomous_execution',v_count=0
  );
end $function$


-- [40000000571] function public.tgg_brain_latest_scorecard()
CREATE OR REPLACE FUNCTION public.tgg_brain_latest_scorecard()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'evaluation_id',e.id,
    'brain_version',v.version_key,
    'window_start',e.window_start,
    'window_end',e.window_end,
    'completion_score',e.completion_score,
    'qa_score',e.qa_score,
    'resilience_score',e.resilience_score,
    'safety_score',e.safety_score,
    'overall_score',e.overall_score,
    'recommendation',e.recommendation,
    'proposed_adjustments',coalesce((
      select jsonb_agg(jsonb_build_object(
        'heuristic_key',a.heuristic_key,
        'proposed_value',a.proposed_value,
        'reason',a.reason,
        'status',a.status
      ) order by a.created_at)
      from public.tgg_brain_heuristic_adjustments a
      where a.evaluation_id=e.id
    ),'[]'::jsonb),
    'safety_contract',v.safety_contract
  )
  from public.tgg_brain_evaluations e
  join public.tgg_brain_versions v on v.id=e.brain_version_id
  order by e.created_at desc
  limit 1
$function$


-- [40000000572] function public.tgg_brain_lineage_refresh()
CREATE OR REPLACE FUNCTION public.tgg_brain_lineage_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_now timestamptz := now();
  v_fk integer := 0;
  v_reads integer := 0;
  v_writes integer := 0;
  v_links integer := 0;
begin
  update public.tgg_brain_lineage_evidence
  set active=false
  where evidence_type in ('foreign_key','function_sql');

  with fk as (
    select
      c_from.id as from_id,
      c_to.id as to_id,
      con.oid::text as evidence_ref
    from pg_constraint con
    join pg_class src on src.oid=con.conrelid
    join pg_namespace srcn on srcn.oid=src.relnamespace
    join pg_class dst on dst.oid=con.confrelid
    join pg_namespace dstn on dstn.oid=dst.relnamespace
    join public.tgg_brain_components c_from
      on c_from.component_key='dbtable:'||src.relname and c_from.active=true
    join public.tgg_brain_components c_to
      on c_to.component_key='dbtable:'||dst.relname and c_to.active=true
    where con.contype='f'
      and srcn.nspname='public'
      and dstn.nspname='public'
      and src.relname like 'tgg_%'
      and dst.relname like 'tgg_%'
  ),
  upserted as (
    insert into public.tgg_brain_lineage_evidence(
      from_component_id,to_component_id,relationship,evidence_type,evidence_ref,
      confidence,first_seen_at,last_seen_at,active
    )
    select from_id,to_id,'depends_on','foreign_key',evidence_ref,100,v_now,v_now,true
    from fk
    on conflict(from_component_id,to_component_id,relationship,evidence_type,evidence_ref) do update
      set confidence=excluded.confidence,last_seen_at=v_now,active=true
    returning 1
  )
  select count(*) into v_fk from upserted;

  with defs as (
    select
      c_fn.id as fn_id,
      lower(pg_get_functiondef(p.oid)) as def,
      p.oid::text as fn_oid
    from pg_proc p
    join pg_namespace n on n.oid=p.pronamespace
    join public.tgg_brain_components c_fn
      on c_fn.component_key=
         'dbfn:'||n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')'
      and c_fn.active=true
    where n.nspname in ('public','private')
      and p.proname like 'tgg_%'
  ),
  refs as (
    select d.fn_id,c_tbl.id as tbl_id,d.fn_oid||':read:'||c_tbl.component_key as evidence_ref
    from defs d
    join public.tgg_brain_components c_tbl
      on c_tbl.component_type='database_table'
     and c_tbl.active=true
     and c_tbl.component_key like 'dbtable:tgg_%'
    where d.def like '%from public.'||replace(c_tbl.component_key,'dbtable:','')||'%'
       or d.def like '%join public.'||replace(c_tbl.component_key,'dbtable:','')||'%'
  ),
  upserted as (
    insert into public.tgg_brain_lineage_evidence(
      from_component_id,to_component_id,relationship,evidence_type,evidence_ref,
      confidence,first_seen_at,last_seen_at,active
    )
    select fn_id,tbl_id,'reads','function_sql',evidence_ref,95,v_now,v_now,true
    from refs
    on conflict(from_component_id,to_component_id,relationship,evidence_type,evidence_ref) do update
      set confidence=excluded.confidence,last_seen_at=v_now,active=true
    returning 1
  )
  select count(*) into v_reads from upserted;

  with defs as (
    select
      c_fn.id as fn_id,
      lower(pg_get_functiondef(p.oid)) as def,
      p.oid::text as fn_oid
    from pg_proc p
    join pg_namespace n on n.oid=p.pronamespace
    join public.tgg_brain_components c_fn
      on c_fn.component_key=
         'dbfn:'||n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')'
      and c_fn.active=true
    where n.nspname in ('public','private')
      and p.proname like 'tgg_%'
  ),
  refs as (
    select d.fn_id,c_tbl.id as tbl_id,d.fn_oid||':write:'||c_tbl.component_key as evidence_ref
    from defs d
    join public.tgg_brain_components c_tbl
      on c_tbl.component_type='database_table'
     and c_tbl.active=true
     and c_tbl.component_key like 'dbtable:tgg_%'
    where d.def like '%insert into public.'||replace(c_tbl.component_key,'dbtable:','')||'%'
       or d.def like '%update public.'||replace(c_tbl.component_key,'dbtable:','')||'%'
       or d.def like '%delete from public.'||replace(c_tbl.component_key,'dbtable:','')||'%'
  ),
  upserted as (
    insert into public.tgg_brain_lineage_evidence(
      from_component_id,to_component_id,relationship,evidence_type,evidence_ref,
      confidence,first_seen_at,last_seen_at,active
    )
    select fn_id,tbl_id,'writes','function_sql',evidence_ref,98,v_now,v_now,true
    from refs
    on conflict(from_component_id,to_component_id,relationship,evidence_type,evidence_ref) do update
      set confidence=excluded.confidence,last_seen_at=v_now,active=true
    returning 1
  )
  select count(*) into v_writes from upserted;

  with grouped as (
    select
      from_component_id,
      to_component_id,
      relationship,
      max(confidence) as strength,
      jsonb_agg(jsonb_build_object(
        'evidence_type',evidence_type,
        'evidence_ref',evidence_ref,
        'confidence',confidence
      ) order by confidence desc,evidence_ref) as evidence
    from public.tgg_brain_lineage_evidence
    where active=true
    group by from_component_id,to_component_id,relationship
  ),
  upserted as (
    insert into public.tgg_brain_component_links(
      from_component_id,to_component_id,relationship,strength,required,metadata
    )
    select
      from_component_id,to_component_id,relationship,strength,true,
      jsonb_build_object('auto_discovered',true,'evidence',evidence)
    from grouped
    on conflict(from_component_id,to_component_id,relationship) do update
      set strength=greatest(public.tgg_brain_component_links.strength,excluded.strength),
          metadata=public.tgg_brain_component_links.metadata || excluded.metadata
    returning 1
  )
  select count(*) into v_links from upserted;

  return jsonb_build_object(
    'ok',true,
    'refreshed_at',v_now,
    'foreign_key_dependencies',v_fk,
    'function_reads',v_reads,
    'function_writes',v_writes,
    'links_materialized',v_links,
    'confidence_policy','foreign_keys=100, writes=98, reads=95'
  );
end $function$


-- [40000000573] function public.tgg_brain_memory_compact()
CREATE OR REPLACE FUNCTION public.tgg_brain_memory_compact()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_archived integer := 0;
  v_before integer := 0;
  v_after integer := 0;
begin
  select count(*) into v_before
  from public.tgg_brain_memory
  where active=true;

  with ranked as (
    select
      m.*,
      row_number() over(
        partition by m.memory_type,md5(m.content::text)
        order by m.importance desc,m.updated_at desc,m.id
      ) as rn,
      first_value(m.id) over(
        partition by m.memory_type,md5(m.content::text)
        order by m.importance desc,m.updated_at desc,m.id
      ) as keep_id
    from public.tgg_brain_memory m
    where m.active=true
      and m.memory_type in ('lesson','qa')
  ),
  losers as (
    select * from ranked where rn>1
  ),
  archived as (
    insert into public.tgg_brain_memory_archive(
      original_memory_id,memory_key,memory_type,title,content,importance,source_ref,
      archive_reason,retained_memory_id
    )
    select
      id,memory_key,memory_type,title,content,importance,source_ref,
      'exact_duplicate',keep_id
    from losers
    on conflict(original_memory_id,archive_reason) do nothing
    returning original_memory_id
  ),
  deactivated as (
    update public.tgg_brain_memory m
    set active=false,updated_at=now()
    where m.id in (select original_memory_id from archived)
    returning 1
  )
  select count(*) into v_archived from deactivated;

  select count(*) into v_after
  from public.tgg_brain_memory
  where active=true;

  return jsonb_build_object(
    'ok',true,
    'active_before',v_before,
    'archived_exact_duplicates',v_archived,
    'active_after',v_after,
    'protected_types',jsonb_build_array('system','decision','constraint','architecture','dependency','idea'),
    'destructive_delete_performed',false
  );
end $function$


-- [40000000574] function public.tgg_brain_memory_hygiene_state()
CREATE OR REPLACE FUNCTION public.tgg_brain_memory_hygiene_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with dupes as (
    select count(*) as groups,
           coalesce(sum(n-1),0) as candidates
    from (
      select memory_type,md5(content::text),count(*) n
      from public.tgg_brain_memory
      where active=true and memory_type in ('lesson','qa')
      group by memory_type,md5(content::text)
      having count(*)>1
    ) q
  )
  select jsonb_build_object(
    'active_memories',(select count(*) from public.tgg_brain_memory where active=true),
    'archived_memories',(select count(*) from public.tgg_brain_memory_archive),
    'exact_duplicate_groups',dupes.groups,
    'exact_duplicate_candidates',dupes.candidates,
    'protected_active_memories',(
      select count(*) from public.tgg_brain_memory
      where active=true and memory_type in ('system','decision','constraint','architecture','dependency','idea')
    )
  )
  from dupes
$function$


-- [40000000575] function public.tgg_brain_next_actions(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_brain_next_actions(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with candidates as (
    select
      'idea'::text as item_type,
      i.id::text as item_key,
      coalesce(i.idea_title,left(i.idea_text,80)) as title,
      case i.status
        when 'new' then 100
        when 'planning' then 90
        when 'building' then 85
        when 'testing' then 80
        when 'blocked' then 20
        else 10
      end::numeric as base_score,
      jsonb_build_object('status',i.status,'retry_count',i.retry_count,'max_retries',i.max_retries) as detail
    from public.tgg_game_idea_inbox i
    where i.status not in ('complete','canceled','approval_required')

    union all

    select
      'task',
      t.task_key,
      t.title,
      case t.status
        when 'ready' then 100
        when 'building' then 90
        when 'testing' then 80
        when 'repairing' then 95
        when 'blocked' then 25
        else 50
      end::numeric,
      jsonb_build_object('status',t.status,'risk_level',t.risk_level,'task_type',t.task_type)
    from public.tgg_build_tasks t
    join public.tgg_build_milestones m on m.id=t.milestone_id
    join public.tgg_build_releases r on r.id=m.release_id
    where t.status not in ('complete','skipped')
      and t.risk_level<>'high'
      and coalesce(r.target_environment,'staging')<>'production'
      and coalesce((r.metadata->>'auto_builder_claim_allowed')::boolean,true)=true
  ),
  ranked as (
    select
      c.*,
      coalesce(p.score,c.base_score) as final_score
    from candidates c
    left join public.tgg_brain_priorities p
      on p.item_type=c.item_type and p.item_key=c.item_key
    order by coalesce(p.score,c.base_score) desc
    limit greatest(1,least(25,p_limit))
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'item_type',item_type,
      'item_key',item_key,
      'title',title,
      'score',final_score,
      'detail',detail
    )
    order by final_score desc
  ),'[]'::jsonb)
  from ranked
$function$


-- [40000000576] function public.tgg_brain_next_buildable_steps(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_brain_next_buildable_steps(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'goal_id',g.id,
      'goal_key',g.goal_key,
      'step_id',s.id,
      'step_key',s.step_key,
      'title',s.title,
      'step_type',s.step_type,
      'risk_level',s.risk_level,
      'simulation',jsonb_build_object(
        'status',sim.status,
        'risk_score',sim.risk_score,
        'confidence',sim.confidence,
        'qa_coverage_need',sim.qa_coverage_need,
        'recommendation',sim.recommendation
      ),
      'acceptance',s.acceptance
    )
    order by g.priority_score desc,s.sequence_no
  ),'[]'::jsonb)
  from (
    select s.*
    from public.tgg_brain_goal_steps s
    join public.tgg_brain_simulations sim0 on sim0.step_id=s.id
    where s.status='ready'
      and s.risk_level<>'high'
      and sim0.status in ('complete','warning')
      and sim0.dependency_readiness=100
      and sim0.recommendation<>'approval_required_high_risk'
    order by sim0.risk_score asc,s.sequence_no
    limit greatest(1,least(25,p_limit))
  ) s
  join public.tgg_brain_goals g on g.id=s.goal_id
  join public.tgg_brain_simulations sim on sim.step_id=s.id
  where g.development_only=true
    and g.production_allowed=false
    and g.risk_level<>'high'
$function$


-- [40000000577] function public.tgg_brain_next_critical_unlocks(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_brain_next_critical_unlocks(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
with goals as (
  select id,goal_key,title,priority_score
  from public.tgg_brain_goals
  where status not in ('complete','canceled')
    and development_only=true
    and production_allowed=false
    and risk_level<>'high'
),
candidates as (
  select
    g.id as goal_id,
    g.goal_key,
    g.title as goal_title,
    g.priority_score,
    s.id as step_id,
    s.step_key,
    s.title as step_title,
    s.step_type,
    s.sequence_no,
    s.risk_level,
    coalesce(u.downstream_unlocks,0) as downstream_unlocks,
    (
      g.priority_score
      + coalesce(u.downstream_unlocks,0)*20
      + greatest(0,20-s.sequence_no)
      - case s.risk_level when 'medium' then 10 else 0 end
    )::numeric as score
  from goals g
  join public.tgg_brain_goal_steps s on s.goal_id=g.id
  left join (
    with recursive e as (
      select
        d.depends_on_step_id as step_id,
        d.goal_step_id as dependent_id
      from public.tgg_brain_goal_dependencies d
    ),
    c as (
      select step_id,dependent_id,1 depth from e
      union all
      select c.step_id,e.dependent_id,c.depth+1
      from c join e on e.step_id=c.dependent_id
      where c.depth<50
    )
    select step_id,count(distinct dependent_id) downstream_unlocks
    from c group by step_id
  ) u on u.step_id=s.id
  where s.status in ('queued','ready','repairing','testing')
    and s.risk_level<>'high'
    and not exists(
      select 1
      from public.tgg_brain_goal_dependencies d
      join public.tgg_brain_goal_steps dep on dep.id=d.depends_on_step_id
      where d.goal_step_id=s.id
        and dep.status<>'complete'
    )
)
select coalesce(jsonb_agg(jsonb_build_object(
  'goal_id',goal_id,
  'goal_key',goal_key,
  'goal_title',goal_title,
  'step_id',step_id,
  'step_key',step_key,
  'step_title',step_title,
  'step_type',step_type,
  'risk_level',risk_level,
  'downstream_unlocks',downstream_unlocks,
  'score',score
) order by score desc),'[]'::jsonb)
from (
  select *
  from candidates
  order by score desc
  limit greatest(1,least(25,p_limit))
) q
$function$


-- [40000000578] function public.tgg_brain_periodic_evaluation()
CREATE OR REPLACE FUNCTION public.tgg_brain_periodic_evaluation()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_eval jsonb;
  v_props jsonb;
  v_recovery jsonb;
begin
  v_eval := public.tgg_brain_evaluate(interval '24 hours');
  v_props := public.tgg_brain_propose_adjustments((v_eval->>'evaluation_id')::uuid);
  v_recovery := public.tgg_brain_auto_recover_if_unsafe('TGG-BRAIN-1.0-BASELINE');

  return jsonb_build_object(
    'ok',true,
    'evaluation',v_eval,
    'proposals',v_props,
    'recovery',v_recovery,
    'auto_apply_proposals',false
  );
end $function$


-- [40000000579] function public.tgg_brain_predict_change_set(p_source_component_key text, p_goal_id uuid, p_step_id uuid, p_depth integer)
CREATE OR REPLACE FUNCTION public.tgg_brain_predict_change_set(p_source_component_key text, p_goal_id uuid DEFAULT NULL::uuid, p_step_id uuid DEFAULT NULL::uuid, p_depth integer DEFAULT 2)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source public.tgg_brain_components%rowtype;
  v_prediction_key text;
  v_edits jsonb := '[]'::jsonb;
  v_tests jsonb := '[]'::jsonb;
  v_prod boolean := false;
  v_high boolean := false;
  v_canonical boolean := false;
  v_risk integer := 0;
  v_confidence integer := 90;
  v_approval boolean := false;
  v_id uuid;
begin
  select * into v_source
  from public.tgg_brain_components
  where component_key=p_source_component_key and active=true;

  if not found then raise exception 'source_component_not_found'; end if;

  with recursive walk as (
    select
      c.id,c.component_key,c.component_type,c.name,c.environment,c.risk_level,c.canonical,
      0 as depth,
      100::integer as path_confidence
    from public.tgg_brain_components c
    where c.id=v_source.id

    union all

    select
      c.id,c.component_key,c.component_type,c.name,c.environment,c.risk_level,c.canonical,
      w.depth+1,
      least(w.path_confidence,l.strength)
    from walk w
    join public.tgg_brain_component_links l
      on l.to_component_id=w.id
    join public.tgg_brain_components c
      on c.id=l.from_component_id and c.active=true
    where w.depth < greatest(0,least(4,p_depth))
  ),
  distinct_walk as (
    select distinct on(id)
      id,component_key,component_type,name,environment,risk_level,canonical,depth,path_confidence
    from walk
    order by id,depth,path_confidence desc
  )
  select
    coalesce(jsonb_agg(
      jsonb_build_object(
        'component_key',component_key,
        'component_type',component_type,
        'name',name,
        'depth',depth,
        'confidence',path_confidence,
        'environment',environment,
        'risk_level',risk_level,
        'canonical',canonical
      )
      order by depth,component_key
    ),'[]'::jsonb),
    exists(select 1 from distinct_walk where environment='production'),
    exists(select 1 from distinct_walk where risk_level='high'),
    exists(select 1 from distinct_walk where canonical=true)
  into v_edits,v_prod,v_high,v_canonical
  from distinct_walk;

  -- Test recommendations from affected component types.
  with affected as (
    select *
    from jsonb_to_recordset(v_edits)
      as x(component_key text,component_type text,name text,depth integer,confidence integer,environment text,risk_level text,canonical boolean)
  ),
  tests as (
    select distinct test_type
    from affected a
    cross join lateral (
      values
        (case when a.component_type='database_table' then 'schema' end),
        (case when a.component_type='database_function' then 'integration' end),
        (case when a.component_type in ('page','ui_module') then 'browser' end),
        (case when a.component_type in ('page','ui_module') then 'visual' end),
        (case when a.component_type='game_system' then 'playtest' end),
        ('regression')
    ) t(test_type)
    where test_type is not null
  )
  select coalesce(jsonb_agg(test_type order by test_type),'[]'::jsonb)
  into v_tests
  from tests;

  v_risk := least(100,
    (case when v_prod then 45 else 0 end)
    +(case when v_high then 35 else 0 end)
    +(case when v_canonical then 25 else 0 end)
    +(case v_source.risk_level when 'high' then 30 when 'medium' then 10 else 0 end)
  );

  v_approval := v_prod or v_high or v_canonical or v_source.risk_level='high';

  select coalesce(min((x->>'confidence')::integer),90)
  into v_confidence
  from jsonb_array_elements(v_edits) x;

  v_prediction_key := 'changepred:'||coalesce(p_step_id::text,p_goal_id::text,p_source_component_key)||':'||md5(p_source_component_key||coalesce(p_step_id::text,'')||coalesce(p_goal_id::text,''));

  insert into public.tgg_brain_change_predictions(
    prediction_key,goal_id,step_id,source_component_key,predicted_edits,predicted_tests,
    predicted_risk,production_affected,high_risk_affected,canonical_affected,
    approval_required,confidence,rationale
  )
  values(
    v_prediction_key,p_goal_id,p_step_id,p_source_component_key,v_edits,v_tests,
    v_risk,v_prod,v_high,v_canonical,v_approval,v_confidence,
    jsonb_build_object(
      'depth',greatest(0,least(4,p_depth)),
      'source_risk',v_source.risk_level,
      'source_environment',v_source.environment,
      'lineage_based',true
    )
  )
  on conflict(prediction_key) do update
  set predicted_edits=excluded.predicted_edits,
      predicted_tests=excluded.predicted_tests,
      predicted_risk=excluded.predicted_risk,
      production_affected=excluded.production_affected,
      high_risk_affected=excluded.high_risk_affected,
      canonical_affected=excluded.canonical_affected,
      approval_required=excluded.approval_required,
      confidence=excluded.confidence,
      rationale=excluded.rationale,
      updated_at=now()
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,
    'prediction_id',v_id,
    'source_component_key',p_source_component_key,
    'predicted_edits',v_edits,
    'predicted_tests',v_tests,
    'predicted_risk',v_risk,
    'production_affected',v_prod,
    'high_risk_affected',v_high,
    'canonical_affected',v_canonical,
    'approval_required',v_approval,
    'confidence',v_confidence
  );
end $function$


-- [40000000580] function public.tgg_brain_prediction_accuracy()
CREATE OR REPLACE FUNCTION public.tgg_brain_prediction_accuracy()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'calibrations',count(*),
    'usable_calibrations',count(*) filter(where status<>'insufficient_evidence'),
    'average_component_precision',coalesce(round(avg(component_precision) filter(where status<>'insufficient_evidence'),2),0),
    'average_component_recall',coalesce(round(avg(component_recall) filter(where status<>'insufficient_evidence'),2),0),
    'average_test_coverage_match',coalesce(round(avg(test_coverage_match) filter(where status<>'insufficient_evidence'),2),0),
    'average_calibration_score',coalesce(round(avg(calibration_score) filter(where status<>'insufficient_evidence'),2),0),
    'warning_count',count(*) filter(where status='warning')
  )
  from public.tgg_brain_prediction_calibrations
$function$


-- [40000000581] function public.tgg_brain_prediction_latest(p_source_component_key text)
CREATE OR REPLACE FUNCTION public.tgg_brain_prediction_latest(p_source_component_key text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'prediction_id',id,
    'source_component_key',source_component_key,
    'predicted_edits',predicted_edits,
    'predicted_tests',predicted_tests,
    'predicted_risk',predicted_risk,
    'production_affected',production_affected,
    'high_risk_affected',high_risk_affected,
    'canonical_affected',canonical_affected,
    'approval_required',approval_required,
    'confidence',confidence,
    'rationale',rationale,
    'updated_at',updated_at
  )
  from public.tgg_brain_change_predictions
  where source_component_key=p_source_component_key
  order by updated_at desc
  limit 1
$function$


-- [40000000582] function public.tgg_brain_propose_adjustments(p_evaluation_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_brain_propose_adjustments(p_evaluation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_eval public.tgg_brain_evaluations%rowtype;
  v_version public.tgg_brain_versions%rowtype;
  v_count integer := 0;
begin
  select * into v_eval from public.tgg_brain_evaluations where id=p_evaluation_id;
  if not found then raise exception 'evaluation_not_found'; end if;

  select * into v_version from public.tgg_brain_versions where id=v_eval.brain_version_id;
  if not found then raise exception 'brain_version_not_found'; end if;

  if v_eval.safety_score<100 then
    insert into public.tgg_brain_heuristic_adjustments(
      brain_version_id,evaluation_id,heuristic_key,old_value,proposed_value,reason
    )
    values(
      v_version.id,v_eval.id,'autonomy_mode',
      to_jsonb('normal'::text),to_jsonb('restricted'::text),
      jsonb_build_object('reason','safety_score_below_100','score',v_eval.safety_score)
    )
    on conflict do nothing;
  elsif v_eval.qa_score<85 then
    insert into public.tgg_brain_heuristic_adjustments(
      brain_version_id,evaluation_id,heuristic_key,old_value,proposed_value,reason
    )
    values(
      v_version.id,v_eval.id,'qa_depth',
      to_jsonb('standard'::text),to_jsonb('expanded'::text),
      jsonb_build_object('reason','qa_score_below_85','score',v_eval.qa_score)
    )
    on conflict do nothing;
  elsif v_eval.completion_score<85 then
    insert into public.tgg_brain_heuristic_adjustments(
      brain_version_id,evaluation_id,heuristic_key,old_value,proposed_value,reason
    )
    values(
      v_version.id,v_eval.id,'planning_mode',
      to_jsonb('normal'::text),to_jsonb('dependency_first'::text),
      jsonb_build_object('reason','completion_score_below_85','score',v_eval.completion_score)
    )
    on conflict do nothing;
  elsif v_eval.resilience_score<85 then
    insert into public.tgg_brain_heuristic_adjustments(
      brain_version_id,evaluation_id,heuristic_key,old_value,proposed_value,reason
    )
    values(
      v_version.id,v_eval.id,'repair_mode',
      to_jsonb('standard'::text),to_jsonb('conservative'::text),
      jsonb_build_object('reason','resilience_score_below_85','score',v_eval.resilience_score)
    )
    on conflict do nothing;
  end if;

  select count(*) into v_count
  from public.tgg_brain_heuristic_adjustments
  where evaluation_id=p_evaluation_id and status='proposed';

  return jsonb_build_object(
    'ok',true,'evaluation_id',p_evaluation_id,'proposals',v_count,'auto_apply',false
  );
end $function$


-- [40000000583] function public.tgg_brain_recall(p_query text, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_brain_recall(p_query text, p_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with tokens as (
    select distinct tok
    from regexp_split_to_table(lower(trim(coalesce(p_query,''))), E'[^a-z0-9_:-]+') tok
    where length(tok)>=3
  ),
  scored as (
    select
      m.id,m.memory_key,m.memory_type,m.title,m.content,m.importance,m.source_ref,m.updated_at,
      (
        m.importance::numeric * 0.45
        + case m.memory_type
            when 'constraint' then 30
            when 'system' then 25
            when 'architecture' then 22
            when 'decision' then 20
            when 'dependency' then 15
            when 'qa' then 10
            when 'lesson' then 8
            else 5
          end
        + case when lower(m.title) like '%'||lower(trim(p_query))||'%' and trim(p_query)<>'' then 35 else 0 end
        + case when lower(m.content::text) like '%'||lower(trim(p_query))||'%' and trim(p_query)<>'' then 20 else 0 end
        + (
          select coalesce(count(*),0)*6
          from tokens t
          where lower(m.title) like '%'||t.tok||'%'
             or lower(m.content::text) like '%'||t.tok||'%'
             or lower(coalesce(m.source_ref,'')) like '%'||t.tok||'%'
        )
      ) as relevance_score
    from public.tgg_brain_memory m
    where m.active=true
  ),
  ranked as (
    select *
    from scored
    where relevance_score>0
    order by relevance_score desc,importance desc,updated_at desc
    limit greatest(1,least(30,p_limit))
  )
  select jsonb_build_object(
    'query',p_query,
    'active_memory_count',(select count(*) from public.tgg_brain_memory where active=true),
    'returned_count',(select count(*) from ranked),
    'memories',coalesce((
      select jsonb_agg(jsonb_build_object(
        'memory_key',memory_key,
        'memory_type',memory_type,
        'title',title,
        'importance',importance,
        'relevance_score',round(relevance_score,2),
        'content',content,
        'source_ref',source_ref
      ) order by relevance_score desc,importance desc)
      from ranked
    ),'[]'::jsonb)
  )
$function$


-- [40000000584] function public.tgg_brain_reflect()
CREATE OR REPLACE FUNCTION public.tgg_brain_reflect()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tasks integer := 0;
  v_failures integer := 0;
  v_browser integer := 0;
  v_visual integer := 0;
  v_playtests integer := 0;
  v_recoveries integer := 0;
  v_memories integer := 0;
begin
  -- Completed task outcomes.
  with ins as (
    insert into public.tgg_brain_learning_events(
      source_type,source_key,event_type,outcome,lesson_key,lesson
    )
    select
      'task',
      t.id::text,
      'task_complete',
      'success',
      'lesson:task:'||t.id::text,
      jsonb_build_object(
        'task_key',t.task_key,
        'title',t.title,
        'task_type',t.task_type,
        'risk_level',t.risk_level,
        'result',t.last_result,
        'lesson','Reuse verified completed work; do not rebuild unless live evidence shows regression.'
      )
    from public.tgg_build_tasks t
    where t.status='complete'
    on conflict do nothing
    returning 1
  )
  select count(*) into v_tasks from ins;

  -- Failure outcomes, including resolved failures as lessons.
  with ins as (
    insert into public.tgg_brain_learning_events(
      source_type,source_key,event_type,outcome,lesson_key,lesson
    )
    select
      'failure',
      f.id::text,
      'build_failure',
      case when f.status='resolved' then 'recovered' else 'failure' end,
      'lesson:failure:'||f.id::text,
      jsonb_build_object(
        'failure_key',f.failure_key,
        'category',f.category,
        'severity',f.severity,
        'status',f.status,
        'message',f.message,
        'detail',f.detail,
        'lesson',case
          when f.status='resolved' then 'Preserve the resolution evidence and prefer the superseding verified path.'
          else 'Avoid repeating this failure path until its root cause is addressed.'
        end
      )
    from public.tgg_build_failures f
    on conflict do nothing
    returning 1
  )
  select count(*) into v_failures from ins;

  -- Browser QA evidence.
  with ins as (
    insert into public.tgg_brain_learning_events(
      source_type,source_key,event_type,outcome,lesson_key,lesson
    )
    select
      'browser_qa',
      q.id::text,
      'browser_qa',
      case when q.status='passed' then 'success' else 'warning' end,
      'lesson:browser_qa:'||q.id::text,
      jsonb_build_object(
        'route_key',q.route_key,
        'viewport_key',q.viewport_key,
        'status',q.status,
        'console_error_count',q.console_error_count,
        'network_error_count',q.network_error_count,
        'stuck_loading',q.stuck_loading,
        'duplicate_shell',q.duplicate_shell,
        'overlap_count',q.overlap_count,
        'clipped_text_count',q.clipped_text_count,
        'findings',q.findings,
        'lesson','Keep the exact QA evidence attached to the surface and reuse passing layout patterns.'
      )
    from public.tgg_browser_qa_results q
    on conflict do nothing
    returning 1
  )
  select count(*) into v_browser from ins;

  -- Visual QA evidence.
  with ins as (
    insert into public.tgg_brain_learning_events(
      source_type,source_key,event_type,outcome,lesson_key,lesson
    )
    select
      'visual_qa',
      q.id::text,
      'visual_qa',
      case when q.status='passed' then 'success' else 'warning' end,
      'lesson:visual_qa:'||q.id::text,
      jsonb_build_object(
        'viewport_key',q.viewport_key,
        'status',q.status,
        'overlap_count',q.overlap_count,
        'clipped_text_count',q.clipped_text_count,
        'duplicate_shell_count',q.duplicate_shell_count,
        'stuck_loading_count',q.stuck_loading_count,
        'accessibility_findings',q.accessibility_findings,
        'findings',q.findings,
        'lesson','Prefer layouts that have already passed overlap, clipping, shell-duplication, and loading checks.'
      )
    from public.tgg_visual_qa_results q
    on conflict do nothing
    returning 1
  )
  select count(*) into v_visual from ins;

  -- Playtest run outcomes.
  with ins as (
    insert into public.tgg_brain_learning_events(
      source_type,source_key,event_type,outcome,lesson_key,lesson
    )
    select
      'playtest',
      r.id::text,
      'playtest_run',
      case when r.status='passed' then 'success'
           when r.status='blocked' then 'blocked'
           else 'warning' end,
      'lesson:playtest:'||r.id::text,
      jsonb_build_object(
        'environment',r.environment,
        'status',r.status,
        'executor',r.executor,
        'summary',r.summary,
        'lesson','Use passed journeys as regression contracts; blocked journeys remain gates, not failures to fake around.'
      )
    from public.tgg_playtest_runs r
    on conflict do nothing
    returning 1
  )
  select count(*) into v_playtests from ins;

  -- Idea recovery lessons.
  with ins as (
    insert into public.tgg_brain_learning_events(
      source_type,source_key,event_type,outcome,lesson_key,lesson
    )
    select
      'idea_recovery',
      i.id::text,
      'idea_recovery',
      case
        when i.last_error='auto_recovered_stale_worker' then 'recovered'
        when i.last_error='auto_recovery_retries_exhausted' then 'blocked'
        else 'warning'
      end,
      'lesson:idea_recovery:'||i.id::text,
      jsonb_build_object(
        'idea_title',i.idea_title,
        'status',i.status,
        'retry_count',i.retry_count,
        'max_retries',i.max_retries,
        'last_error',i.last_error,
        'lesson','Use heartbeats for active work; requeue abandoned work; stop after bounded retries instead of looping forever.'
      )
    from public.tgg_game_idea_inbox i
    where i.last_error in ('auto_recovered_stale_worker','auto_recovery_retries_exhausted')
    on conflict do nothing
    returning 1
  )
  select count(*) into v_recoveries from ins;

  -- Promote learning events into durable brain memory once.
  with pending as (
    select e.id,e.lesson_key,e.source_type,e.outcome,e.lesson
    from public.tgg_brain_learning_events e
    where e.incorporated_into_memory=false
    order by e.created_at
    limit 500
  ),
  upserted as (
    insert into public.tgg_brain_memory(
      memory_key,memory_type,title,content,importance,source_ref
    )
    select
      p.lesson_key,
      'lesson',
      'Learned from '||p.source_type||' · '||p.outcome,
      p.lesson,
      case p.outcome
        when 'failure' then 90
        when 'blocked' then 90
        when 'recovered' then 85
        when 'warning' then 75
        else 60
      end,
      p.source_type||':'||p.id::text
    from pending p
    on conflict(memory_key) do update
      set content=excluded.content,
          importance=excluded.importance,
          active=true,
          updated_at=now()
    returning memory_key
  )
  select count(*) into v_memories from upserted;

  update public.tgg_brain_learning_events e
  set incorporated_into_memory=true
  where e.incorporated_into_memory=false
    and exists(
      select 1 from public.tgg_brain_memory m where m.memory_key=e.lesson_key
    );

  return jsonb_build_object(
    'ok',true,
    'new_task_lessons',v_tasks,
    'new_failure_lessons',v_failures,
    'new_browser_qa_lessons',v_browser,
    'new_visual_qa_lessons',v_visual,
    'new_playtest_lessons',v_playtests,
    'new_recovery_lessons',v_recoveries,
    'memories_written',v_memories,
    'total_learning_events',(select count(*) from public.tgg_brain_learning_events),
    'active_brain_memories',(select count(*) from public.tgg_brain_memory where active=true)
  );
end $function$


-- [40000000585] function public.tgg_brain_remember(p_memory_key text, p_memory_type text, p_title text, p_content jsonb, p_importance integer, p_source_ref text)
CREATE OR REPLACE FUNCTION public.tgg_brain_remember(p_memory_key text, p_memory_type text, p_title text, p_content jsonb DEFAULT '{}'::jsonb, p_importance integer DEFAULT 50, p_source_ref text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if p_memory_type not in ('system','idea','decision','lesson','constraint','architecture','qa','dependency') then
    raise exception 'invalid_memory_type';
  end if;
  insert into public.tgg_brain_memory(memory_key,memory_type,title,content,importance,source_ref)
  values(trim(p_memory_key),p_memory_type,trim(p_title),coalesce(p_content,'{}'::jsonb),greatest(0,least(100,p_importance)),p_source_ref)
  on conflict(memory_key) do update
    set memory_type=excluded.memory_type,
        title=excluded.title,
        content=excluded.content,
        importance=excluded.importance,
        source_ref=coalesce(excluded.source_ref,public.tgg_brain_memory.source_ref),
        active=true,
        updated_at=now()
  returning id into v_id;
  return jsonb_build_object('ok',true,'memory_id',v_id,'memory_key',p_memory_key);
end $function$


-- [40000000586] function public.tgg_brain_requirement_link(p_requirement_id uuid, p_link_type text, p_goal_step_id uuid, p_build_task_id uuid, p_execution_trace_id uuid, p_evidence jsonb)
CREATE OR REPLACE FUNCTION public.tgg_brain_requirement_link(p_requirement_id uuid, p_link_type text, p_goal_step_id uuid DEFAULT NULL::uuid, p_build_task_id uuid DEFAULT NULL::uuid, p_execution_trace_id uuid DEFAULT NULL::uuid, p_evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if p_link_type not in ('implements','tests','verifies','depends_on') then
    raise exception 'invalid_link_type';
  end if;

  if p_goal_step_id is null and p_build_task_id is null and p_execution_trace_id is null then
    raise exception 'at_least_one_link_target_required';
  end if;

  insert into public.tgg_brain_requirement_links(
    requirement_id,goal_step_id,build_task_id,execution_trace_id,link_type,evidence
  )
  values(
    p_requirement_id,p_goal_step_id,p_build_task_id,p_execution_trace_id,p_link_type,
    coalesce(p_evidence,'{}'::jsonb)
  )
  on conflict(requirement_id,goal_step_id,build_task_id,execution_trace_id,link_type) do update
  set evidence=excluded.evidence
  returning id into v_id;

  return jsonb_build_object('ok',true,'requirement_link_id',v_id,'link_type',p_link_type);
end $function$


-- [40000000587] function public.tgg_brain_set_priority(p_item_type text, p_item_key text, p_impact integer, p_urgency integer, p_dependency_readiness integer, p_confidence integer, p_risk_penalty integer, p_reason jsonb)
CREATE OR REPLACE FUNCTION public.tgg_brain_set_priority(p_item_type text, p_item_key text, p_impact integer, p_urgency integer, p_dependency_readiness integer, p_confidence integer, p_risk_penalty integer DEFAULT 0, p_reason jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_score numeric;
begin
  insert into public.tgg_brain_priorities(item_type,item_key,impact,urgency,dependency_readiness,confidence,risk_penalty,reason)
  values(
    p_item_type,trim(p_item_key),
    greatest(0,least(100,p_impact)),
    greatest(0,least(100,p_urgency)),
    greatest(0,least(100,p_dependency_readiness)),
    greatest(0,least(100,p_confidence)),
    greatest(0,least(100,p_risk_penalty)),
    coalesce(p_reason,'{}'::jsonb)
  )
  on conflict(item_type,item_key) do update
    set impact=excluded.impact,
        urgency=excluded.urgency,
        dependency_readiness=excluded.dependency_readiness,
        confidence=excluded.confidence,
        risk_penalty=excluded.risk_penalty,
        reason=excluded.reason,
        updated_at=now();

  select score into v_score from public.tgg_brain_priorities
  where item_type=p_item_type and item_key=trim(p_item_key);

  return jsonb_build_object('ok',true,'item_type',p_item_type,'item_key',p_item_key,'score',v_score);
end $function$


-- [40000000588] function public.tgg_brain_simulate_goal(p_goal_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_brain_simulate_goal(p_goal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  v_results jsonb := '[]'::jsonb;
  v_blocked integer := 0;
  v_warning integer := 0;
begin
  perform public.tgg_brain_goal_refresh_ready();

  for r in
    select id from public.tgg_brain_goal_steps
    where goal_id=p_goal_id
    order by sequence_no
  loop
    v_results := v_results || jsonb_build_array(public.tgg_brain_simulate_step(r.id));
  end loop;

  select count(*) filter(where status='blocked'),
         count(*) filter(where status='warning')
  into v_blocked,v_warning
  from public.tgg_brain_simulations
  where goal_id=p_goal_id;

  update public.tgg_brain_goals
  set plan_summary=coalesce(plan_summary,'{}'::jsonb) || jsonb_build_object(
    'simulation_status',case when v_blocked>0 then 'blocked' when v_warning>0 then 'warning' else 'clear' end,
    'blocked_steps',v_blocked,
    'warning_steps',v_warning,
    'simulated_at',now()
  ),
  updated_at=now()
  where id=p_goal_id;

  return jsonb_build_object(
    'ok',true,'goal_id',p_goal_id,'blocked_steps',v_blocked,
    'warning_steps',v_warning,'results',v_results
  );
end $function$


-- [40000000589] function public.tgg_brain_simulate_step(p_step_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_brain_simulate_step(p_step_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_step public.tgg_brain_goal_steps%rowtype;
  v_goal public.tgg_brain_goals%rowtype;
  v_dep_total integer := 0;
  v_dep_complete integer := 0;
  v_dependency integer := 100;
  v_regression integer := 20;
  v_qa integer := 40;
  v_confidence integer := 70;
  v_risk integer := 0;
  v_status text := 'complete';
  v_recommendation text := 'safe_to_plan';
  v_key text;
  v_id uuid;
  v_failure_count integer := 0;
  v_related_lessons integer := 0;
begin
  select * into v_step from public.tgg_brain_goal_steps where id=p_step_id;
  if not found then raise exception 'goal_step_not_found'; end if;

  select * into v_goal from public.tgg_brain_goals where id=v_step.goal_id;
  if not found then raise exception 'goal_not_found'; end if;

  select count(*),
         count(*) filter(where dep.status='complete')
  into v_dep_total,v_dep_complete
  from public.tgg_brain_goal_dependencies d
  join public.tgg_brain_goal_steps dep on dep.id=d.depends_on_step_id
  where d.goal_step_id=v_step.id;

  if v_dep_total>0 then
    v_dependency := round((v_dep_complete::numeric/v_dep_total::numeric)*100)::integer;
  end if;

  select count(*) into v_failure_count
  from public.tgg_build_failures f
  where f.status<>'resolved'
     or coalesce(f.detail::text,'') ilike '%'||v_step.step_type||'%';

  select count(*) into v_related_lessons
  from public.tgg_brain_memory m
  where m.active=true
    and m.memory_type in ('lesson','qa','architecture')
    and (
      m.title ilike '%'||v_step.step_type||'%'
      or m.content::text ilike '%'||v_step.step_type||'%'
    );

  v_regression := least(100,
    case v_step.step_type
      when 'schema' then 55
      when 'backend' then 45
      when 'integration' then 60
      when 'frontend' then 35
      when 'repair' then 40
      when 'staging' then 50
      else 25
    end + least(v_failure_count*5,25)
  );

  v_qa := least(100,
    case v_step.step_type
      when 'schema' then 70
      when 'backend' then 75
      when 'integration' then 90
      when 'frontend' then 85
      when 'qa' then 100
      when 'playtest' then 100
      when 'staging' then 95
      else 60
    end
  );

  v_confidence := greatest(0,least(100,
    55
    + least(v_related_lessons*3,30)
    + case when v_dependency=100 then 10 else 0 end
    - least(v_failure_count*4,20)
  ));

  v_risk := greatest(0,least(100,
    round(
      (100-v_dependency)*0.35
      + v_regression*0.35
      + (100-v_confidence)*0.20
      + case v_step.risk_level when 'high' then 30 when 'medium' then 10 else 0 end
    )::integer
  ));

  if v_step.risk_level='high' or v_goal.risk_level='high' then
    v_status := 'blocked';
    v_recommendation := 'approval_required_high_risk';
  elsif v_dependency<100 then
    v_status := 'blocked';
    v_recommendation := 'wait_for_dependencies';
  elsif v_risk>=70 then
    v_status := 'warning';
    v_recommendation := 'add_qa_and_review_before_build';
  elsif v_risk>=45 then
    v_status := 'warning';
    v_recommendation := 'build_with_expanded_qa';
  else
    v_status := 'complete';
    v_recommendation := 'safe_to_build';
  end if;

  v_key := 'sim:'||v_step.id::text;

  insert into public.tgg_brain_simulations(
    goal_id,step_id,simulation_key,status,dependency_readiness,regression_exposure,
    qa_coverage_need,confidence,risk_score,recommendation,evidence
  )
  values(
    v_goal.id,v_step.id,v_key,v_status,v_dependency,v_regression,
    v_qa,v_confidence,v_risk,v_recommendation,
    jsonb_build_object(
      'step_key',v_step.step_key,
      'step_type',v_step.step_type,
      'step_risk_level',v_step.risk_level,
      'goal_risk_level',v_goal.risk_level,
      'dependency_total',v_dep_total,
      'dependency_complete',v_dep_complete,
      'related_learning_memories',v_related_lessons,
      'relevant_failure_signals',v_failure_count,
      'production_allowed',v_goal.production_allowed,
      'development_only',v_goal.development_only
    )
  )
  on conflict(simulation_key) do update
    set status=excluded.status,
        dependency_readiness=excluded.dependency_readiness,
        regression_exposure=excluded.regression_exposure,
        qa_coverage_need=excluded.qa_coverage_need,
        confidence=excluded.confidence,
        risk_score=excluded.risk_score,
        recommendation=excluded.recommendation,
        evidence=excluded.evidence,
        updated_at=now()
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'simulation_id',v_id,'step_id',v_step.id,
    'status',v_status,'dependency_readiness',v_dependency,
    'regression_exposure',v_regression,'qa_coverage_need',v_qa,
    'confidence',v_confidence,'risk_score',v_risk,
    'recommendation',v_recommendation
  );
end $function$


-- [40000000590] function public.tgg_brain_spec_add_requirement(p_spec_id uuid, p_requirement_key text, p_requirement_type text, p_priority text, p_statement text, p_acceptance jsonb, p_owner_domain text, p_risk_level text, p_scope_status text, p_source_ref text)
CREATE OR REPLACE FUNCTION public.tgg_brain_spec_add_requirement(p_spec_id uuid, p_requirement_key text, p_requirement_type text, p_priority text, p_statement text, p_acceptance jsonb, p_owner_domain text DEFAULT NULL::text, p_risk_level text DEFAULT 'medium'::text, p_scope_status text DEFAULT 'in_scope'::text, p_source_ref text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if p_requirement_type not in ('functional','nonfunctional','security','performance','ux','data','integration','qa') then
    raise exception 'invalid_requirement_type';
  end if;
  if p_priority not in ('must','should','could') then raise exception 'invalid_priority'; end if;
  if p_risk_level not in ('low','medium','high') then raise exception 'invalid_risk_level'; end if;
  if p_scope_status not in ('in_scope','out_of_scope','approval_required') then
    raise exception 'invalid_scope_status';
  end if;

  insert into public.tgg_brain_spec_requirements(
    spec_id,requirement_key,requirement_type,priority,statement,acceptance,
    owner_domain,risk_level,scope_status,source_ref,status
  )
  values(
    p_spec_id,trim(p_requirement_key),p_requirement_type,p_priority,trim(p_statement),
    coalesce(p_acceptance,'[]'::jsonb),p_owner_domain,p_risk_level,p_scope_status,p_source_ref,'planned'
  )
  on conflict(spec_id,requirement_key) do update
  set requirement_type=excluded.requirement_type,
      priority=excluded.priority,
      statement=excluded.statement,
      acceptance=excluded.acceptance,
      owner_domain=excluded.owner_domain,
      risk_level=excluded.risk_level,
      scope_status=excluded.scope_status,
      source_ref=excluded.source_ref,
      updated_at=now()
  returning id into v_id;

  return jsonb_build_object('ok',true,'requirement_id',v_id,'requirement_key',p_requirement_key);
end $function$


-- [40000000591] function public.tgg_brain_spec_add_scope(p_spec_id uuid, p_scope_key text, p_scope_type text, p_description text, p_immutable boolean)
CREATE OR REPLACE FUNCTION public.tgg_brain_spec_add_scope(p_spec_id uuid, p_scope_key text, p_scope_type text, p_description text, p_immutable boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_scope_type not in ('in_scope','out_of_scope','constraint','assumption') then
    raise exception 'invalid_scope_type';
  end if;

  insert into public.tgg_brain_spec_scope(spec_id,scope_key,scope_type,description,immutable)
  values(p_spec_id,trim(p_scope_key),p_scope_type,trim(p_description),coalesce(p_immutable,false))
  on conflict(spec_id,scope_key) do update
  set scope_type=excluded.scope_type,
      description=excluded.description,
      immutable=excluded.immutable;

  return jsonb_build_object('ok',true,'scope_key',p_scope_key);
end $function$


-- [40000000592] function public.tgg_brain_spec_coverage(p_spec_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_brain_spec_coverage(p_spec_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_must integer := 0;
  v_impl integer := 0;
  v_test integer := 0;
  v_verify integer := 0;
  v_uncovered jsonb := '[]'::jsonb;
  v_complete boolean := false;
begin
  select count(*) into v_must
  from public.tgg_brain_spec_requirements
  where spec_id=p_spec_id
    and priority='must'
    and scope_status='in_scope';

  select count(*) into v_impl
  from public.tgg_brain_spec_requirements r
  where r.spec_id=p_spec_id
    and r.priority='must'
    and r.scope_status='in_scope'
    and exists(
      select 1 from public.tgg_brain_requirement_links l
      where l.requirement_id=r.id and l.link_type='implements'
        and (l.goal_step_id is not null or l.build_task_id is not null)
    );

  select count(*) into v_test
  from public.tgg_brain_spec_requirements r
  where r.spec_id=p_spec_id
    and r.priority='must'
    and r.scope_status='in_scope'
    and exists(
      select 1 from public.tgg_brain_requirement_links l
      where l.requirement_id=r.id and l.link_type='tests'
    );

  select count(*) into v_verify
  from public.tgg_brain_spec_requirements r
  where r.spec_id=p_spec_id
    and r.priority='must'
    and r.scope_status='in_scope'
    and exists(
      select 1
      from public.tgg_brain_requirement_links l
      join public.tgg_brain_execution_traces t on t.id=l.execution_trace_id
      where l.requirement_id=r.id
        and l.link_type='verifies'
        and t.trace_status='verified'
    );

  select coalesce(jsonb_agg(jsonb_build_object(
    'requirement_id',r.id,
    'requirement_key',r.requirement_key,
    'statement',r.statement,
    'implemented',exists(
      select 1 from public.tgg_brain_requirement_links l
      where l.requirement_id=r.id and l.link_type='implements'
    ),
    'tested',exists(
      select 1 from public.tgg_brain_requirement_links l
      where l.requirement_id=r.id and l.link_type='tests'
    ),
    'verified',exists(
      select 1
      from public.tgg_brain_requirement_links l
      join public.tgg_brain_execution_traces t on t.id=l.execution_trace_id
      where l.requirement_id=r.id and l.link_type='verifies' and t.trace_status='verified'
    )
  ) order by r.requirement_key),'[]'::jsonb)
  into v_uncovered
  from public.tgg_brain_spec_requirements r
  where r.spec_id=p_spec_id
    and r.priority='must'
    and r.scope_status='in_scope'
    and not (
      exists(select 1 from public.tgg_brain_requirement_links l where l.requirement_id=r.id and l.link_type='implements')
      and exists(select 1 from public.tgg_brain_requirement_links l where l.requirement_id=r.id and l.link_type='tests')
      and exists(
        select 1
        from public.tgg_brain_requirement_links l
        join public.tgg_brain_execution_traces t on t.id=l.execution_trace_id
        where l.requirement_id=r.id and l.link_type='verifies' and t.trace_status='verified'
      )
    );

  v_complete := v_must>0 and v_impl=v_must and v_test=v_must and v_verify=v_must;

  return jsonb_build_object(
    'ok',true,
    'spec_id',p_spec_id,
    'must_requirements',v_must,
    'implemented',v_impl,
    'tested',v_test,
    'verified',v_verify,
    'coverage_complete',v_complete,
    'uncovered_requirements',v_uncovered
  );
end $function$


-- [40000000593] function public.tgg_brain_spec_create(p_spec_key text, p_title text, p_objective text, p_idea_id uuid, p_goal_id uuid, p_risk_level text, p_summary jsonb)
CREATE OR REPLACE FUNCTION public.tgg_brain_spec_create(p_spec_key text, p_title text, p_objective text, p_idea_id uuid DEFAULT NULL::uuid, p_goal_id uuid DEFAULT NULL::uuid, p_risk_level text DEFAULT 'medium'::text, p_summary jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if p_risk_level not in ('low','medium','high') then
    raise exception 'invalid_risk_level';
  end if;

  insert into public.tgg_brain_specs(
    spec_key,idea_id,goal_id,title,objective,summary,status,risk_level,
    development_only,production_allowed
  )
  values(
    trim(p_spec_key),p_idea_id,p_goal_id,trim(p_title),trim(p_objective),
    coalesce(p_summary,'{}'::jsonb),'draft',p_risk_level,true,false
  )
  on conflict(spec_key) do update
  set idea_id=coalesce(excluded.idea_id,public.tgg_brain_specs.idea_id),
      goal_id=coalesce(excluded.goal_id,public.tgg_brain_specs.goal_id),
      title=excluded.title,
      objective=excluded.objective,
      summary=excluded.summary,
      risk_level=excluded.risk_level,
      development_only=true,
      production_allowed=false,
      updated_at=now()
  returning id into v_id;

  return jsonb_build_object('ok',true,'spec_id',v_id,'spec_key',p_spec_key);
end $function$


-- [40000000594] function public.tgg_brain_spec_mark_complete(p_spec_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_brain_spec_mark_complete(p_spec_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_validation jsonb;
  v_coverage jsonb;
begin
  v_validation := public.tgg_brain_spec_validate(p_spec_id);
  v_coverage := public.tgg_brain_spec_coverage(p_spec_id);

  if coalesce((v_validation->>'ready')::boolean,false) is not true then
    raise exception 'spec_not_ready';
  end if;

  if coalesce((v_coverage->>'coverage_complete')::boolean,false) is not true then
    raise exception 'spec_coverage_incomplete';
  end if;

  update public.tgg_brain_specs
  set status='complete',updated_at=now()
  where id=p_spec_id;

  return jsonb_build_object(
    'ok',true,
    'spec_id',p_spec_id,
    'status','complete',
    'validation',v_validation,
    'coverage',v_coverage
  );
end $function$


-- [40000000595] function public.tgg_brain_spec_state()
CREATE OR REPLACE FUNCTION public.tgg_brain_spec_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'total',count(*),
    'draft',count(*) filter(where status='draft'),
    'ready',count(*) filter(where status='ready'),
    'blocked',count(*) filter(where status='blocked'),
    'complete',count(*) filter(where status='complete'),
    'production_allowed',count(*) filter(where production_allowed=true),
    'high_risk_specs',count(*) filter(where risk_level='high')
  )
  from public.tgg_brain_specs
$function$


-- [40000000596] function public.tgg_brain_spec_validate(p_spec_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_brain_spec_validate(p_spec_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_spec public.tgg_brain_specs%rowtype;
  v_must integer := 0;
  v_missing_acceptance integer := 0;
  v_missing_owner integer := 0;
  v_high integer := 0;
  v_approval integer := 0;
  v_scope integer := 0;
  v_ready boolean := false;
  v_status text := 'draft';
begin
  select * into v_spec from public.tgg_brain_specs where id=p_spec_id;
  if not found then raise exception 'spec_not_found'; end if;

  select
    count(*) filter(where priority='must' and scope_status='in_scope'),
    count(*) filter(
      where priority='must'
        and scope_status='in_scope'
        and jsonb_array_length(coalesce(acceptance,'[]'::jsonb))=0
    ),
    count(*) filter(
      where priority='must'
        and scope_status='in_scope'
        and nullif(trim(coalesce(owner_domain,'')),'') is null
    ),
    count(*) filter(where risk_level='high' and scope_status='in_scope'),
    count(*) filter(where scope_status='approval_required')
  into v_must,v_missing_acceptance,v_missing_owner,v_high,v_approval
  from public.tgg_brain_spec_requirements
  where spec_id=p_spec_id;

  select count(*) into v_scope
  from public.tgg_brain_spec_scope
  where spec_id=p_spec_id;

  v_ready :=
    v_must>0
    and v_missing_acceptance=0
    and v_missing_owner=0
    and v_high=0
    and v_approval=0
    and v_scope>0
    and v_spec.development_only=true
    and v_spec.production_allowed=false;

  if v_high>0 or v_approval>0 then v_status:='blocked';
  elsif v_ready then v_status:='ready';
  else v_status:='draft'; end if;

  update public.tgg_brain_specs
  set status=v_status,
      updated_at=now(),
      summary=coalesce(summary,'{}'::jsonb) || jsonb_build_object(
        'validation',jsonb_build_object(
          'must_requirements',v_must,
          'missing_acceptance',v_missing_acceptance,
          'missing_owner_domain',v_missing_owner,
          'high_risk_in_scope',v_high,
          'approval_required',v_approval,
          'scope_items',v_scope,
          'ready',v_ready,
          'validated_at',now()
        )
      )
  where id=p_spec_id;

  return jsonb_build_object(
    'ok',true,
    'spec_id',p_spec_id,
    'status',v_status,
    'ready',v_ready,
    'must_requirements',v_must,
    'missing_acceptance',v_missing_acceptance,
    'missing_owner_domain',v_missing_owner,
    'high_risk_in_scope',v_high,
    'approval_required',v_approval,
    'scope_items',v_scope
  );
end $function$


-- [40000000597] function public.tgg_brain_state()
CREATE OR REPLACE FUNCTION public.tgg_brain_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_idea jsonb;
  v_build jsonb;
  v_dependency jsonb;
begin
  v_idea := public.tgg_game_idea_pipeline_state();
  v_build := public.tgg_autobuilder_detect_state();
  v_dependency := private.tgg_latest_operational_dependency_state();

  return jsonb_build_object(
    'brain_version','TGG-BRAIN-1.0',
    'memory_count',(select count(*) from public.tgg_brain_memory where active=true),
    'active_decisions',(select count(*) from public.tgg_brain_decisions where status='active'),
    'top_priorities',coalesce((
      select jsonb_agg(x)
      from (
        select jsonb_build_object(
          'item_type',item_type,'item_key',item_key,'score',score,'reason',reason
        ) as x
        from public.tgg_brain_priorities
        order by score desc,updated_at desc
        limit 10
      ) q
    ),'[]'::jsonb),
    'game_ideas',v_idea,
    'builder',v_build,
    'dependencies',coalesce(v_dependency,'{}'::jsonb),
    'production_auto_publish',false,
    'high_risk_auto_execute',false,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end $function$


-- [40000000598] function public.tgg_brain_trial_finalize(p_trial_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_brain_trial_finalize(p_trial_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_high_fail integer := 0;
  v_fail integer := 0;
  v_blocked integer := 0;
  v_warning integer := 0;
  v_pass integer := 0;
  v_total integer := 0;
  v_status text;
  v_verdict text;
begin
  if current_user <> 'postgres' then raise exception 'internal_worker_only'; end if;

  select
    count(*),
    count(*) filter(where status='pass'),
    count(*) filter(where status='warning'),
    count(*) filter(where status='fail'),
    count(*) filter(where status='blocked'),
    count(*) filter(where status='fail' and severity='high')
  into v_total,v_pass,v_warning,v_fail,v_blocked,v_high_fail
  from public.tgg_brain_trial_checks
  where trial_id=p_trial_id;

  if v_total=0 then
    raise exception 'trial_has_no_checks';
  elsif v_blocked>0 or v_high_fail>0 then
    v_status:='blocked';
    v_verdict:='do_not_advance';
  elsif v_fail>0 then
    v_status:='failed';
    v_verdict:='repair_and_retry';
  elsif v_warning>0 then
    v_status:='passed';
    v_verdict:='advance_with_expanded_qa';
  else
    v_status:='passed';
    v_verdict:='safe_for_staging';
  end if;

  update public.tgg_brain_trials
  set status=v_status,
      verdict=v_verdict,
      result=jsonb_build_object(
        'checks_total',v_total,
        'checks_passed',v_pass,
        'warnings',v_warning,
        'failures',v_fail,
        'blocked',v_blocked,
        'high_severity_failures',v_high_fail
      ),
      completed_at=now(),
      updated_at=now(),
      production_touched=false
  where id=p_trial_id;

  if not found then raise exception 'trial_not_found'; end if;

  return jsonb_build_object(
    'ok',true,'trial_id',p_trial_id,'status',v_status,'verdict',v_verdict,
    'production_touched',false
  );
end $function$


-- [40000000599] function public.tgg_brain_trial_prepare(p_trial_key text, p_goal_id uuid, p_step_id uuid, p_source_ref text, p_artifact_ref text, p_baseline jsonb)
CREATE OR REPLACE FUNCTION public.tgg_brain_trial_prepare(p_trial_key text, p_goal_id uuid, p_step_id uuid, p_source_ref text DEFAULT NULL::text, p_artifact_ref text DEFAULT NULL::text, p_baseline jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_goal public.tgg_brain_goals%rowtype;
  v_step public.tgg_brain_goal_steps%rowtype;
  v_id uuid;
begin
  if current_user <> 'postgres' then raise exception 'internal_worker_only'; end if;

  select * into v_goal from public.tgg_brain_goals where id=p_goal_id;
  if not found then raise exception 'goal_not_found'; end if;

  select * into v_step from public.tgg_brain_goal_steps where id=p_step_id and goal_id=p_goal_id;
  if not found then raise exception 'goal_step_not_found'; end if;

  if v_goal.production_allowed or not v_goal.development_only then
    raise exception 'sandbox_trial_requires_development_only_goal';
  end if;

  if v_goal.risk_level='high' or v_step.risk_level='high' then
    raise exception 'high_risk_requires_approval';
  end if;

  insert into public.tgg_brain_trials(
    trial_key,goal_id,step_id,status,environment,source_ref,artifact_ref,baseline,production_touched
  )
  values(
    trim(p_trial_key),p_goal_id,p_step_id,'prepared','sandbox',
    p_source_ref,p_artifact_ref,coalesce(p_baseline,'{}'::jsonb),false
  )
  on conflict(trial_key) do update
    set source_ref=coalesce(excluded.source_ref,public.tgg_brain_trials.source_ref),
        artifact_ref=coalesce(excluded.artifact_ref,public.tgg_brain_trials.artifact_ref),
        baseline=excluded.baseline,
        production_touched=false,
        updated_at=now()
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'trial_id',v_id,'trial_key',p_trial_key,
    'environment','sandbox','production_touched',false
  );
end $function$


-- [40000000600] function public.tgg_brain_trial_ready_for_staging(p_trial_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_brain_trial_ready_for_staging(p_trial_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'trial_id',t.id,
    'trial_key',t.trial_key,
    'status',t.status,
    'verdict',t.verdict,
    'ready_for_staging',
      t.status='passed'
      and t.verdict in ('safe_for_staging','advance_with_expanded_qa')
      and t.production_touched=false,
    'production_touched',t.production_touched,
    'result',t.result
  )
  from public.tgg_brain_trials t
  where t.id=p_trial_id
$function$


-- [40000000601] function public.tgg_brain_trial_record_check(p_trial_id uuid, p_check_key text, p_check_type text, p_status text, p_severity text, p_evidence jsonb)
CREATE OR REPLACE FUNCTION public.tgg_brain_trial_record_check(p_trial_id uuid, p_check_key text, p_check_type text, p_status text, p_severity text DEFAULT 'medium'::text, p_evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user <> 'postgres' then raise exception 'internal_worker_only'; end if;
  if p_check_type not in ('schema','security','unit','integration','browser','visual','playtest','performance','regression','dependency') then
    raise exception 'invalid_check_type';
  end if;
  if p_status not in ('pass','fail','warning','blocked') then raise exception 'invalid_check_status'; end if;
  if p_severity not in ('low','medium','high') then raise exception 'invalid_severity'; end if;

  insert into public.tgg_brain_trial_checks(trial_id,check_key,check_type,status,severity,evidence)
  values(p_trial_id,trim(p_check_key),p_check_type,p_status,p_severity,coalesce(p_evidence,'{}'::jsonb))
  on conflict(trial_id,check_key) do update
    set check_type=excluded.check_type,status=excluded.status,severity=excluded.severity,
        evidence=excluded.evidence,checked_at=now();

  update public.tgg_brain_trials set updated_at=now() where id=p_trial_id;

  return jsonb_build_object('ok',true,'trial_id',p_trial_id,'check_key',p_check_key,'status',p_status);
end $function$


-- [40000000602] function public.tgg_brain_trial_start(p_trial_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_brain_trial_start(p_trial_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user <> 'postgres' then raise exception 'internal_worker_only'; end if;

  update public.tgg_brain_trials
  set status='running',started_at=coalesce(started_at,now()),updated_at=now()
  where id=p_trial_id and status in ('prepared','running');

  if not found then raise exception 'trial_not_startable'; end if;

  return jsonb_build_object('ok',true,'trial_id',p_trial_id,'status','running');
end $function$


-- [40000000603] function public.tgg_brain_uncertainty_gate(p_source_component_key text, p_prediction_id uuid, p_step_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_brain_uncertainty_gate(p_source_component_key text, p_prediction_id uuid DEFAULT NULL::uuid, p_step_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_arch jsonb;
  v_pred public.tgg_brain_change_predictions%rowtype;
  v_sim public.tgg_brain_simulations%rowtype;
  v_component public.tgg_brain_components%rowtype;
  v_lineage_count integer := 0;
  v_arch_score integer := 100;
  v_lineage_score integer := 0;
  v_pred_score integer := 50;
  v_cal_score integer := 50;
  v_sim_score integer := 50;
  v_quality integer := 0;
  v_action text := 'proceed';
  v_blockers jsonb := '[]'::jsonb;
  v_accuracy jsonb;
  v_usable integer := 0;
  v_key text;
  v_id uuid;
begin
  select * into v_component
  from public.tgg_brain_components
  where component_key=p_source_component_key and active=true;
  if not found then raise exception 'source_component_not_found'; end if;

  v_arch := public.tgg_brain_architecture_latest();

  if v_arch is null then
    v_arch_score := 20;
    v_blockers := v_blockers || jsonb_build_array('architecture_state_missing');
  elsif coalesce(v_arch->>'drift_status','warning')='warning'
     or coalesce((v_arch->>'stale_components')::integer,0)>0
     or coalesce((v_arch->>'missing_since_previous')::integer,0)>0 then
    v_arch_score := 40;
    v_blockers := v_blockers || jsonb_build_array('architecture_not_clean');
  elsif coalesce(v_arch->>'drift_status','clean')='changed' then
    v_arch_score := 85;
  else
    v_arch_score := 100;
  end if;

  select count(*) into v_lineage_count
  from public.tgg_brain_lineage_evidence e
  join public.tgg_brain_components c1 on c1.id=e.from_component_id
  join public.tgg_brain_components c2 on c2.id=e.to_component_id
  where e.active=true
    and (c1.component_key=p_source_component_key or c2.component_key=p_source_component_key);

  v_lineage_score := least(100,20 + v_lineage_count*10);

  if p_prediction_id is not null then
    select * into v_pred from public.tgg_brain_change_predictions where id=p_prediction_id;
    if found then
      v_pred_score := v_pred.confidence;
      if v_pred.approval_required then
        v_blockers := v_blockers || jsonb_build_array('prediction_requires_approval');
      end if;
      if v_pred.production_affected then
        v_blockers := v_blockers || jsonb_build_array('production_affected');
      end if;
      if v_pred.high_risk_affected then
        v_blockers := v_blockers || jsonb_build_array('high_risk_affected');
      end if;
      if v_pred.canonical_affected then
        v_blockers := v_blockers || jsonb_build_array('canonical_affected');
      end if;
    else
      v_pred_score := 20;
      v_blockers := v_blockers || jsonb_build_array('prediction_missing');
    end if;
  else
    v_pred_score := 35;
  end if;

  v_accuracy := public.tgg_brain_prediction_accuracy();
  v_usable := coalesce((v_accuracy->>'usable_calibrations')::integer,0);

  if v_usable=0 then
    v_cal_score := 50;
  else
    v_cal_score := least(100,greatest(0,round((v_accuracy->>'average_calibration_score')::numeric)::integer));
  end if;

  if p_step_id is not null then
    select * into v_sim
    from public.tgg_brain_simulations
    where step_id=p_step_id
    order by updated_at desc
    limit 1;

    if found then
      v_sim_score := v_sim.confidence;
      if v_sim.status='blocked' then
        v_blockers := v_blockers || jsonb_build_array('simulation_blocked');
      end if;
    else
      v_sim_score := 30;
      v_blockers := v_blockers || jsonb_build_array('simulation_missing');
    end if;
  end if;

  v_quality := round(
    v_arch_score*0.25
    + v_lineage_score*0.20
    + v_pred_score*0.25
    + v_cal_score*0.15
    + v_sim_score*0.15
  )::integer;

  if v_component.risk_level='high'
     or v_component.canonical
     or (found and coalesce(v_pred.approval_required,false)) then
    v_action := 'approval_required';
  elsif v_arch_score<60 then
    v_action := 'research_required';
  elsif v_quality<55 then
    v_action := 'research_required';
  elsif v_quality<70 then
    v_action := 'narrow_scope';
  elsif v_quality<85 then
    v_action := 'expanded_qa';
  else
    v_action := 'proceed';
  end if;

  v_key := 'uncertainty:'||p_source_component_key||':'||coalesce(p_prediction_id::text,'none')||':'||coalesce(p_step_id::text,'none');

  insert into public.tgg_brain_uncertainty_checks(
    check_key,source_component_key,prediction_id,step_id,
    architecture_score,lineage_score,prediction_score,calibration_score,simulation_score,
    evidence_quality,action,blockers,rationale
  )
  values(
    v_key,p_source_component_key,p_prediction_id,p_step_id,
    v_arch_score,v_lineage_score,v_pred_score,v_cal_score,v_sim_score,
    v_quality,v_action,v_blockers,
    jsonb_build_object(
      'lineage_evidence_count',v_lineage_count,
      'usable_prediction_calibrations',v_usable,
      'component_risk_level',v_component.risk_level,
      'component_canonical',v_component.canonical,
      'production_auto_publish',false,
      'high_risk_auto_execute',false
    )
  )
  on conflict(check_key) do update
  set architecture_score=excluded.architecture_score,
      lineage_score=excluded.lineage_score,
      prediction_score=excluded.prediction_score,
      calibration_score=excluded.calibration_score,
      simulation_score=excluded.simulation_score,
      evidence_quality=excluded.evidence_quality,
      action=excluded.action,
      blockers=excluded.blockers,
      rationale=excluded.rationale,
      updated_at=now()
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,
    'check_id',v_id,
    'source_component_key',p_source_component_key,
    'evidence_quality',v_quality,
    'action',v_action,
    'scores',jsonb_build_object(
      'architecture',v_arch_score,
      'lineage',v_lineage_score,
      'prediction',v_pred_score,
      'calibration',v_cal_score,
      'simulation',v_sim_score
    ),
    'blockers',v_blockers
  );
end $function$


-- [40000000604] function public.tgg_broadcast_engine_health()
CREATE OR REPLACE FUNCTION public.tgg_broadcast_engine_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with r as (
    select
      coalesce(enabled,false) as enabled,
      coalesce(mode,'disabled') as mode,
      coalesce(endpoint_configured,false) as endpoint_configured,
      disabled_reason
    from public.tgg_provider_runtime_config
    where provider_key='broadcast.sfu_turn'
  )
  select jsonb_build_object(
    'ok',true,
    'version','BROADCAST-ENGINE-ONE-FINAL-1.1',
    'control_plane_ready',true,
    'room_authorization_ready',true,
    'public_viewer_tokens_ready',true,
    'host_guest_collab_tokens_ready',true,
    'livekit_gateway_package_ready',true,
    'adapter_contract_ready',true,
    'sfu_connected',coalesce((select enabled and mode='production' and endpoint_configured from r),false),
    'turn_connected',coalesce((select enabled and mode='production' and endpoint_configured from r),false),
    'egress_connected',false,
    'ingress_connected',false,
    'external_deployment_required',
      not coalesce((select enabled and mode='production' and endpoint_configured from r),false),
    'provider','livekit_compatible_sfu_turn',
    'disabled_reason',(select disabled_reason from r),
    'generated_at',now()
  );
$function$


-- [40000000605] function public.tgg_broadcast_room_access(p_stream_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_broadcast_room_access(p_stream_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$ select tgg_private.broadcast_room_access($1); $function$


-- [40000000606] function public.tgg_browser_qa_gate(p_task_key text, p_required_passes integer)
CREATE OR REPLACE FUNCTION public.tgg_browser_qa_gate(p_task_key text, p_required_passes integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_task_id uuid;
  v_passes integer;
  v_open_failures integer;
begin
  select id into v_task_id from public.tgg_build_tasks where task_key=p_task_key;
  if v_task_id is null then
    raise exception 'task not found: %',p_task_key;
  end if;

  select count(*) into v_passes
  from public.tgg_browser_qa_results
  where task_id=v_task_id and status='passed';

  select count(*) into v_open_failures
  from public.tgg_build_failures
  where task_id=v_task_id
    and category='browser_qa'
    and status in ('open','repairing','blocked');

  if v_open_failures > 0 then
    return jsonb_build_object('status','blocked','open_failures',v_open_failures,'passes',v_passes);
  end if;

  if v_passes < greatest(p_required_passes,1) then
    return jsonb_build_object('status','testing','reason','insufficient_clean_browser_evidence','passes',v_passes);
  end if;

  return jsonb_build_object('status','passed','passes',v_passes);
end;
$function$


-- [40000000607] function public.tgg_browser_qa_protected_audio_candidate_v1()
CREATE OR REPLACE FUNCTION public.tgg_browser_qa_protected_audio_candidate_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_track_id uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select t.id
  into v_track_id
  from public.tracks t
  join public.mixtapes m on m.id=t.mixtape_id
  where m.status='published'::public.mixtape_status
    and nullif(btrim(coalesce(t.audio_path,'')),'') is not null
  order by m.created_at desc nulls last, t.track_number asc nulls last, t.id
  limit 1;

  return jsonb_build_object(
    'ok', v_track_id is not null,
    'track_id', v_track_id,
    'source', 'published_protected_audio_candidate'
  );
end
$function$


-- [40000000608] function public.tgg_browser_qa_record(p_run_id uuid, p_task_key text, p_route_key text, p_url text, p_viewport_key text, p_http_status integer, p_load_ms integer, p_console_error_count integer, p_network_error_count integer, p_stuck_loading boolean, p_duplicate_shell boolean, p_overlap_count integer, p_clipped_text_count integer, p_auth_loop boolean, p_findings jsonb, p_screenshot_uri text)
CREATE OR REPLACE FUNCTION public.tgg_browser_qa_record(p_run_id uuid, p_task_key text, p_route_key text, p_url text, p_viewport_key text, p_http_status integer, p_load_ms integer, p_console_error_count integer DEFAULT 0, p_network_error_count integer DEFAULT 0, p_stuck_loading boolean DEFAULT false, p_duplicate_shell boolean DEFAULT false, p_overlap_count integer DEFAULT 0, p_clipped_text_count integer DEFAULT 0, p_auth_loop boolean DEFAULT false, p_findings jsonb DEFAULT '[]'::jsonb, p_screenshot_uri text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_task_id uuid;
  v_status text;
  v_id uuid;
  v_failure_count integer := 0;
begin
  select id into v_task_id
  from public.tgg_build_tasks
  where task_key=p_task_key;

  if v_task_id is null then
    raise exception 'task not found: %', p_task_key;
  end if;

  if coalesce(p_http_status,0) < 200 or coalesce(p_http_status,0) >= 400
     or coalesce(p_console_error_count,0) > 0
     or coalesce(p_network_error_count,0) > 0
     or coalesce(p_stuck_loading,false)
     or coalesce(p_duplicate_shell,false)
     or coalesce(p_overlap_count,0) > 0
     or coalesce(p_clipped_text_count,0) > 0
     or coalesce(p_auth_loop,false) then
    v_status := 'failed';
  else
    v_status := 'passed';
  end if;

  insert into public.tgg_browser_qa_results(
    run_id,task_id,route_key,url,viewport_key,status,http_status,load_ms,
    console_error_count,network_error_count,stuck_loading,duplicate_shell,
    overlap_count,clipped_text_count,auth_loop,findings,screenshot_uri
  )
  values(
    p_run_id,v_task_id,p_route_key,p_url,p_viewport_key,v_status,p_http_status,p_load_ms,
    greatest(coalesce(p_console_error_count,0),0),
    greatest(coalesce(p_network_error_count,0),0),
    coalesce(p_stuck_loading,false),
    coalesce(p_duplicate_shell,false),
    greatest(coalesce(p_overlap_count,0),0),
    greatest(coalesce(p_clipped_text_count,0),0),
    coalesce(p_auth_loop,false),
    coalesce(p_findings,'[]'::jsonb),
    p_screenshot_uri
  )
  returning id into v_id;

  if v_status='failed' then
    insert into public.tgg_build_failures(
      run_id,task_id,failure_key,category,severity,status,message,detail
    )
    values(
      p_run_id,
      v_task_id,
      'browser:' || coalesce(p_route_key,'unknown') || ':' || coalesce(p_viewport_key,'unknown') || ':' || v_id::text,
      'browser_qa',
      'error',
      'open',
      'Browser QA failed for ' || coalesce(p_route_key,p_url,'unknown route'),
      jsonb_build_object(
        'qa_id',v_id,
        'http_status',p_http_status,
        'console_error_count',greatest(coalesce(p_console_error_count,0),0),
        'network_error_count',greatest(coalesce(p_network_error_count,0),0),
        'stuck_loading',coalesce(p_stuck_loading,false),
        'duplicate_shell',coalesce(p_duplicate_shell,false),
        'overlap_count',greatest(coalesce(p_overlap_count,0),0),
        'clipped_text_count',greatest(coalesce(p_clipped_text_count,0),0),
        'auth_loop',coalesce(p_auth_loop,false),
        'findings',coalesce(p_findings,'[]'::jsonb)
      )
    );
    v_failure_count := 1;
  end if;

  return jsonb_build_object('qa_id',v_id,'status',v_status,'failure_created',v_failure_count=1);
end;
$function$


-- [40000000609] function public.tgg_browser_qa_resolve_failures(p_task_key text, p_resolution jsonb)
CREATE OR REPLACE FUNCTION public.tgg_browser_qa_resolve_failures(p_task_key text, p_resolution jsonb DEFAULT '{}'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_task_id uuid;
  v_count integer := 0;
begin
  select id into v_task_id from public.tgg_build_tasks where task_key=p_task_key;

  update public.tgg_build_failures
  set status='resolved',
      resolved_at=now(),
      detail=detail || jsonb_build_object('resolution',coalesce(p_resolution,'{}'::jsonb))
  where task_id=v_task_id
    and category='browser_qa'
    and status in ('open','repairing');

  get diagnostics v_count=row_count;
  return v_count;
end;
$function$


-- [40000000610] function public.tgg_build_approve_production_candidate(p_candidate_key text, p_admin_user uuid)
CREATE OR REPLACE FUNCTION public.tgg_build_approve_production_candidate(p_candidate_key text, p_admin_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not exists(
    select 1
    from public.profiles
    where id=p_admin_user and role::text='admin'
  ) then
    raise exception 'valid admin approval required';
  end if;

  update public.tgg_build_release_candidates
  set status='approved',
      approved_by=p_admin_user,
      approved_at=now(),
      updated_at=now()
  where candidate_key=p_candidate_key
    and status in ('ready','canary');

  if not found then
    raise exception 'candidate is not eligible for approval: %',p_candidate_key;
  end if;

  return jsonb_build_object(
    'candidate_key',p_candidate_key,
    'status','approved',
    'approved_at',now()
  );
end;
$function$


-- [40000000611] function public.tgg_build_claim_ready_batch(p_worker text, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_build_claim_ready_batch(p_worker text, p_limit integer DEFAULT 5)
 RETURNS TABLE(task_id uuid, task_key text, title text, task_type text, priority integer, risk_level text, agent_type text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_worker is null or length(trim(p_worker))=0 then
    raise exception 'worker is required';
  end if;

  if p_limit < 1 or p_limit > 25 then
    raise exception 'p_limit must be between 1 and 25';
  end if;

  return query
  with picked as (
    select t.id
    from public.tgg_build_tasks t
    join public.tgg_build_milestones m on m.id=t.milestone_id
    join public.tgg_build_releases r on r.id=m.release_id
    where t.status='ready'
      and t.risk_level <> 'high'
      and coalesce(r.target_environment,'staging') <> 'production'
      and coalesce((r.metadata->>'production_promotion_performed')::boolean,false) is not true
      and coalesce((r.metadata->>'production_deploy_performed')::boolean,false) is not true
      and (
        coalesce((r.metadata->>'canonical')::boolean,true) is not false
        or (
          coalesce((r.metadata->>'development_scope_approved')::boolean,false) is true
          and coalesce((r.metadata->>'development_only')::boolean,false) is true
        )
      )
      and coalesce((r.metadata->>'auto_builder_claim_allowed')::boolean,true) is not false
      and coalesce((r.metadata->>'historical_only')::boolean,false) is not true
      and (
        coalesce((r.metadata->>'historical_backlog')::boolean,false) is not true
        or coalesce((r.metadata->>'development_scope_approved')::boolean,false) is true
      )
      and (t.locked_at is null or t.locked_at < now() - interval '15 minutes')
    order by t.priority,t.created_at
    for update of t skip locked
    limit p_limit
  ),
  claimed as (
    update public.tgg_build_tasks t
    set status='building',
        locked_by=p_worker,
        locked_at=now(),
        started_at=coalesce(t.started_at,now()),
        updated_at=now()
    from picked
    where t.id=picked.id
    returning t.*
  )
  select c.id,c.task_key,c.title,c.task_type,c.priority,c.risk_level,c.agent_type
  from claimed c
  order by c.priority,c.created_at;
end;
$function$


-- [40000000612] function public.tgg_build_create_staging_checkpoint(p_staging_key text, p_title text)
CREATE OR REPLACE FUNCTION public.tgg_build_create_staging_checkpoint(p_staging_key text, p_title text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_stage public.tgg_build_staging_releases%rowtype;
  v_checkpoint_key text;
  v_checkpoint_id uuid;
begin
  select * into v_stage
  from public.tgg_build_staging_releases
  where staging_key=p_staging_key;

  if v_stage.id is null then
    raise exception 'staging candidate not found: %',p_staging_key;
  end if;

  v_checkpoint_key := 'autobuilder:' || p_staging_key;

  insert into public.tgg_release_checkpoints(
    checkpoint_key,title,system_state,runtime_manifest,launch_readiness,notes,created_by,created_at
  )
  values(
    v_checkpoint_key,
    p_title,
    jsonb_build_object('staging_key',p_staging_key,'build_version',v_stage.build_version,'status',v_stage.status),
    v_stage.deployment_manifest,
    jsonb_build_object('environment','staging','production_promoted',false),
    jsonb_build_object('feature_flags',v_stage.feature_flags,'previous_stable_key',v_stage.previous_stable_key),
    null,
    now()
  )
  on conflict(checkpoint_key) do update
  set title=excluded.title,
      system_state=excluded.system_state,
      runtime_manifest=excluded.runtime_manifest,
      launch_readiness=excluded.launch_readiness,
      notes=excluded.notes
  returning id into v_checkpoint_id;

  update public.tgg_build_staging_releases
  set checkpoint_key=v_checkpoint_key
  where id=v_stage.id;

  return v_checkpoint_id;
end;
$function$


-- [40000000613] function public.tgg_build_enqueue_change(p_task_key text, p_target_site_key text, p_change_type text, p_payload jsonb)
CREATE OR REPLACE FUNCTION public.tgg_build_enqueue_change(p_task_key text, p_target_site_key text, p_change_type text, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_task public.tgg_build_tasks%rowtype;
  v_change_id uuid;
  v_requested_by uuid;
begin
  select * into v_task
  from public.tgg_build_tasks
  where task_key=p_task_key
  for update;

  if v_task.id is null then
    raise exception 'task not found: %', p_task_key;
  end if;

  if v_task.risk_level='high' or v_task.status='approval_required' then
    raise exception 'approval required for high-risk task: %', p_task_key;
  end if;

  if not exists(
    select 1 from public.tgg_master_sites
    where site_key=p_target_site_key and status='online'
  ) then
    raise exception 'target site is not registered online: %', p_target_site_key;
  end if;

  select id into v_requested_by
  from public.profiles
  where role::text='admin'
  order by created_at nulls last, id
  limit 1;

  if v_requested_by is null then
    raise exception 'no admin operator profile is available for build attribution';
  end if;

  if exists(select 1 from public.tgg_build_change_links where task_id=v_task.id) then
    select change_id into v_change_id
    from public.tgg_build_change_links
    where task_id=v_task.id;
    return v_change_id;
  end if;

  insert into public.tgg_master_change_queue(
    target_site_key, change_type, payload, status, requested_by, requested_at
  )
  values(
    p_target_site_key,
    p_change_type,
    coalesce(p_payload,'{}'::jsonb) || jsonb_build_object('auto_builder_task_key',p_task_key),
    'pending',
    v_requested_by,
    now()
  )
  returning id into v_change_id;

  insert into public.tgg_build_change_links(task_id,change_id)
  values(v_task.id,v_change_id);

  update public.tgg_build_tasks
  set status='building',
      locked_by='codesync-bridge',
      locked_at=now(),
      started_at=coalesce(started_at,now()),
      updated_at=now(),
      last_result=jsonb_build_object('change_id',v_change_id,'queue','tgg_master_change_queue')
  where id=v_task.id;

  return v_change_id;
end;
$function$


-- [40000000614] function public.tgg_build_finish_task(p_task_key text, p_outcome text, p_result jsonb)
CREATE OR REPLACE FUNCTION public.tgg_build_finish_task(p_task_key text, p_outcome text, p_result jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_task public.tgg_build_tasks%rowtype;
  v_unlocked integer := 0;
begin
  if p_outcome not in ('complete','passed','blocked','approval_required','skipped') then
    raise exception 'invalid outcome';
  end if;

  update public.tgg_build_tasks
  set status=p_outcome,
      last_result=coalesce(p_result,'{}'::jsonb),
      completed_at=case when p_outcome in ('complete','passed','skipped') then now() else completed_at end,
      locked_by=null,
      locked_at=null,
      updated_at=now()
  where task_key=p_task_key
  returning * into v_task;

  if v_task.id is null then
    raise exception 'task not found: %', p_task_key;
  end if;

  if p_outcome in ('complete','passed','skipped') then
    select public.tgg_build_refresh_ready_tasks() into v_unlocked;
  end if;

  return jsonb_build_object(
    'task_key', v_task.task_key,
    'status', p_outcome,
    'newly_unlocked', v_unlocked
  );
end;
$function$


-- [40000000615] function public.tgg_build_gate_staging(p_staging_key text, p_required_passes integer)
CREATE OR REPLACE FUNCTION public.tgg_build_gate_staging(p_staging_key text, p_required_passes integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_stage public.tgg_build_staging_releases%rowtype;
  v_passes integer;
  v_bad integer;
begin
  select * into v_stage
  from public.tgg_build_staging_releases
  where staging_key=p_staging_key;

  if v_stage.id is null then
    raise exception 'staging candidate not found: %',p_staging_key;
  end if;

  select
    count(*) filter(where status='pass'),
    count(*) filter(where status in ('fail','blocked'))
  into v_passes,v_bad
  from public.tgg_launch_smoke_results
  where check_key like 'autobuilder:' || p_staging_key || ':%';

  if v_stage.checkpoint_key is null then
    return jsonb_build_object('status','blocked','reason','missing_checkpoint','passes',v_passes,'bad',v_bad);
  end if;

  if v_bad > 0 then
    update public.tgg_build_staging_releases
    set status='failed'
    where id=v_stage.id;
    return jsonb_build_object('status','blocked','reason','failed_smoke','passes',v_passes,'bad',v_bad);
  end if;

  if v_passes < greatest(p_required_passes,1) then
    return jsonb_build_object('status','testing','reason','insufficient_passes','passes',v_passes);
  end if;

  update public.tgg_build_staging_releases
  set status='passed',verified_at=now()
  where id=v_stage.id;

  return jsonb_build_object('status','passed','passes',v_passes,'checkpoint_key',v_stage.checkpoint_key);
end;
$function$


-- [40000000616] function public.tgg_build_generate_repair(p_task_key text)
CREATE OR REPLACE FUNCTION public.tgg_build_generate_repair(p_task_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_task public.tgg_build_tasks%rowtype;
  v_change_id uuid;
  v_error text;
  v_failure_id uuid;
begin
  select * into v_task
  from public.tgg_build_tasks
  where task_key=p_task_key
  for update;

  if v_task.id is null then
    raise exception 'task not found: %', p_task_key;
  end if;

  select l.change_id, q.error_text
  into v_change_id, v_error
  from public.tgg_build_change_links l
  join public.tgg_master_change_queue q on q.id=l.change_id
  where l.task_id=v_task.id;

  if v_change_id is null then
    raise exception 'task has no linked change: %', p_task_key;
  end if;

  if v_task.retry_count >= v_task.max_retries then
    update public.tgg_build_tasks
    set status='blocked',
        updated_at=now(),
        last_result=coalesce(last_result,'{}'::jsonb) ||
          jsonb_build_object('blocked_reason','retry_limit_reached')
    where id=v_task.id;

    return jsonb_build_object(
      'task_key',p_task_key,
      'status','blocked',
      'reason','retry_limit_reached',
      'retry_count',v_task.retry_count,
      'max_retries',v_task.max_retries
    );
  end if;

  insert into public.tgg_build_failures(
    task_id, failure_key, category, severity, status, message, detail
  )
  values(
    v_task.id,
    'build:' || v_change_id::text || ':retry:' || (v_task.retry_count+1)::text,
    'build_change',
    'error',
    'repairing',
    coalesce(v_error,'Build change failed'),
    jsonb_build_object('change_id',v_change_id,'retry_no',v_task.retry_count+1)
  )
  returning id into v_failure_id;

  update public.tgg_build_tasks
  set retry_count=retry_count+1,
      status='repairing',
      updated_at=now(),
      last_result=coalesce(last_result,'{}'::jsonb) ||
        jsonb_build_object('repair_failure_id',v_failure_id,'retry_count',retry_count+1)
  where id=v_task.id;

  return jsonb_build_object(
    'task_key',p_task_key,
    'status','repairing',
    'failure_id',v_failure_id,
    'retry_count',v_task.retry_count+1
  );
end;
$function$


-- [40000000617] function public.tgg_build_get_rollback_candidate(p_candidate_key text)
CREATE OR REPLACE FUNCTION public.tgg_build_get_rollback_candidate(p_candidate_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_rollback text;
begin
  select rollback_candidate_key into v_rollback
  from public.tgg_build_release_candidates
  where candidate_key=p_candidate_key;

  if not found then
    raise exception 'candidate not found: %',p_candidate_key;
  end if;

  return jsonb_build_object(
    'candidate_key',p_candidate_key,
    'rollback_candidate_key',v_rollback,
    'available',v_rollback is not null
  );
end;
$function$


-- [40000000618] function public.tgg_build_mark_staging_rollback(p_staging_key text, p_reason text)
CREATE OR REPLACE FUNCTION public.tgg_build_mark_staging_rollback(p_staging_key text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_previous text;
begin
  select previous_stable_key into v_previous
  from public.tgg_build_staging_releases
  where staging_key=p_staging_key;

  if not found then
    raise exception 'staging candidate not found: %',p_staging_key;
  end if;

  update public.tgg_build_staging_releases
  set status='rolled_back',
      rolled_back_at=now(),
      smoke_summary=coalesce(smoke_summary,'{}'::jsonb) ||
        jsonb_build_object('rollback_reason',p_reason)
  where staging_key=p_staging_key;

  return jsonb_build_object('status','rolled_back','previous_stable_key',v_previous,'reason',p_reason);
end;
$function$


-- [40000000619] function public.tgg_build_prepare_release_candidate(p_staging_key text, p_candidate_key text, p_version text, p_channel text, p_rollback_candidate_key text, p_notes jsonb)
CREATE OR REPLACE FUNCTION public.tgg_build_prepare_release_candidate(p_staging_key text, p_candidate_key text, p_version text, p_channel text DEFAULT 'internal'::text, p_rollback_candidate_key text DEFAULT NULL::text, p_notes jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_stage public.tgg_build_staging_releases%rowtype;
  v_id uuid;
begin
  if p_channel not in ('internal','private_alpha','creator_alpha','community_alpha','beta','public') then
    raise exception 'invalid release channel: %',p_channel;
  end if;

  select * into v_stage
  from public.tgg_build_staging_releases
  where staging_key=p_staging_key;

  if v_stage.id is null then
    raise exception 'staging candidate not found: %',p_staging_key;
  end if;

  if v_stage.status <> 'passed' then
    raise exception 'staging candidate must be passed before RC preparation';
  end if;

  insert into public.tgg_build_release_candidates(
    build_release_id,staging_release_id,candidate_key,version,channel,status,
    canary_percent,production_approval_required,rollback_candidate_key,release_notes
  )
  values(
    v_stage.build_release_id,v_stage.id,p_candidate_key,p_version,p_channel,'ready',
    0,true,p_rollback_candidate_key,coalesce(p_notes,'{}'::jsonb)
  )
  on conflict(candidate_key) do update
  set version=excluded.version,
      channel=excluded.channel,
      rollback_candidate_key=excluded.rollback_candidate_key,
      release_notes=excluded.release_notes,
      updated_at=now()
  returning id into v_id;

  return v_id;
end;
$function$


-- [40000000620] function public.tgg_build_prepare_staging(p_release_key text, p_staging_key text, p_build_version text, p_previous_stable_key text, p_feature_flags jsonb, p_manifest jsonb)
CREATE OR REPLACE FUNCTION public.tgg_build_prepare_staging(p_release_key text, p_staging_key text, p_build_version text, p_previous_stable_key text DEFAULT NULL::text, p_feature_flags jsonb DEFAULT '{}'::jsonb, p_manifest jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_release_id uuid;
  v_id uuid;
begin
  select r.id into v_release_id
  from public.tgg_build_releases r
  join public.tgg_build_projects p on p.id=r.project_id
  where p.project_key='tru-go-getta-master'
    and r.release_key=p_release_key;

  if v_release_id is null then
    raise exception 'release not found: %',p_release_key;
  end if;

  insert into public.tgg_build_staging_releases(
    build_release_id,staging_key,build_version,status,previous_stable_key,feature_flags,deployment_manifest
  )
  values(
    v_release_id,p_staging_key,p_build_version,'prepared',p_previous_stable_key,
    coalesce(p_feature_flags,'{}'::jsonb),coalesce(p_manifest,'{}'::jsonb)
  )
  on conflict(staging_key) do update
  set build_version=excluded.build_version,
      previous_stable_key=excluded.previous_stable_key,
      feature_flags=excluded.feature_flags,
      deployment_manifest=excluded.deployment_manifest
  returning id into v_id;

  return v_id;
end;
$function$


-- [40000000621] function public.tgg_build_record_staging_smoke(p_staging_key text, p_check_key text, p_status text, p_detail jsonb)
CREATE OR REPLACE FUNCTION public.tgg_build_record_staging_smoke(p_staging_key text, p_check_key text, p_status text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_id bigint;
begin
  if p_status not in ('pass','fail','blocked','manual') then
    raise exception 'invalid smoke status: %',p_status;
  end if;

  if not exists(select 1 from public.tgg_build_staging_releases where staging_key=p_staging_key) then
    raise exception 'staging candidate not found: %',p_staging_key;
  end if;

  insert into public.tgg_launch_smoke_results(check_key,status,detail,checked_at)
  values(
    'autobuilder:' || p_staging_key || ':' || p_check_key,
    p_status,
    coalesce(p_detail,'{}'::jsonb) || jsonb_build_object('staging_key',p_staging_key),
    now()
  )
  returning id into v_id;

  update public.tgg_build_staging_releases
  set status='smoke_testing',
      smoke_summary=coalesce(smoke_summary,'{}'::jsonb) ||
        jsonb_build_object(p_check_key,p_status)
  where staging_key=p_staging_key;

  return v_id;
end;
$function$


-- [40000000622] function public.tgg_build_refresh_ready_tasks()
CREATE OR REPLACE FUNCTION public.tgg_build_refresh_ready_tasks()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  changed integer := 0;
begin
  update public.tgg_build_tasks t
  set status = case
      when t.risk_level = 'high' then 'approval_required'
      else 'ready'
    end,
    updated_at = now()
  where t.status = 'queued'
    and not exists (
      select 1
      from public.tgg_build_dependencies d
      join public.tgg_build_tasks dep on dep.id = d.depends_on_task_id
      where d.task_id = t.id
        and d.dependency_type = 'hard'
        and dep.status not in ('complete','passed','skipped')
    );

  get diagnostics changed = row_count;
  return changed;
end;
$function$


-- [40000000623] function public.tgg_build_start_canary(p_candidate_key text, p_percent integer)
CREATE OR REPLACE FUNCTION public.tgg_build_start_canary(p_candidate_key text, p_percent integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_percent < 1 or p_percent > 25 then
    raise exception 'canary percent must be between 1 and 25';
  end if;

  update public.tgg_build_release_candidates
  set status='canary',
      canary_percent=p_percent,
      updated_at=now()
  where candidate_key=p_candidate_key
    and status in ('ready','canary');

  if not found then
    raise exception 'release candidate not ready for canary: %',p_candidate_key;
  end if;

  return jsonb_build_object('candidate_key',p_candidate_key,'status','canary','canary_percent',p_percent);
end;
$function$


-- [40000000624] function public.tgg_build_sync_change_state(p_task_key text)
CREATE OR REPLACE FUNCTION public.tgg_build_sync_change_state(p_task_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_task_id uuid;
  v_change_id uuid;
  v_change_status text;
  v_error text;
  v_next_status text;
begin
  select t.id, l.change_id
  into v_task_id, v_change_id
  from public.tgg_build_tasks t
  join public.tgg_build_change_links l on l.task_id=t.id
  where t.task_key=p_task_key;

  if v_task_id is null then
    raise exception 'linked task not found: %', p_task_key;
  end if;

  select status, error_text
  into v_change_status, v_error
  from public.tgg_master_change_queue
  where id=v_change_id;

  v_next_status := case v_change_status
    when 'pending' then 'building'
    when 'ready' then 'staging'
    when 'applied' then 'testing'
    when 'failed' then 'repairing'
    when 'cancelled' then 'blocked'
    else 'building'
  end;

  update public.tgg_build_tasks
  set status=v_next_status,
      updated_at=now(),
      last_result=coalesce(last_result,'{}'::jsonb) ||
        jsonb_build_object(
          'change_id',v_change_id,
          'change_status',v_change_status,
          'change_error',v_error
        )
  where id=v_task_id;

  return jsonb_build_object(
    'task_key',p_task_key,
    'change_id',v_change_id,
    'change_status',v_change_status,
    'task_status',v_next_status
  );
end;
$function$


-- [40000000625] function public.tgg_build_verify_promotion(p_candidate_key text)
CREATE OR REPLACE FUNCTION public.tgg_build_verify_promotion(p_candidate_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_rc public.tgg_build_release_candidates%rowtype;
  v_stage_status text;
  v_bad_smokes integer;
begin
  select * into v_rc
  from public.tgg_build_release_candidates
  where candidate_key=p_candidate_key;

  if v_rc.id is null then
    raise exception 'release candidate not found: %',p_candidate_key;
  end if;

  select status into v_stage_status
  from public.tgg_build_staging_releases
  where id=v_rc.staging_release_id;

  select count(*) into v_bad_smokes
  from public.tgg_launch_smoke_results s
  join public.tgg_build_staging_releases st
    on s.check_key like 'autobuilder:' || st.staging_key || ':%'
  where st.id=v_rc.staging_release_id
    and s.status in ('fail','blocked');

  if v_stage_status <> 'passed' then
    return jsonb_build_object('status','blocked','reason','staging_not_passed');
  end if;

  if v_bad_smokes > 0 then
    return jsonb_build_object('status','blocked','reason','bad_smoke_evidence','count',v_bad_smokes);
  end if;

  if v_rc.production_approval_required
     and (v_rc.approved_by is null or v_rc.approved_at is null) then
    return jsonb_build_object('status','approval_required','reason','owner_admin_approval_missing');
  end if;

  return jsonb_build_object(
    'status','promotion_ready',
    'candidate_key',p_candidate_key,
    'channel',v_rc.channel,
    'canary_percent',v_rc.canary_percent,
    'rollback_candidate_key',v_rc.rollback_candidate_key
  );
end;
$function$


-- [40000000626] function public.tgg_build_verify_task_evidence(p_task_key text)
CREATE OR REPLACE FUNCTION public.tgg_build_verify_task_evidence(p_task_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_task_id uuid;
  v_passed_tests integer;
  v_open_failures integer;
begin
  select id into v_task_id
  from public.tgg_build_tasks
  where task_key=p_task_key;

  if v_task_id is null then
    raise exception 'task not found: %', p_task_key;
  end if;

  select count(*) into v_passed_tests
  from public.tgg_build_test_results
  where task_id=v_task_id
    and status='passed';

  select count(*) into v_open_failures
  from public.tgg_build_failures
  where task_id=v_task_id
    and status in ('open','repairing','blocked');

  if v_passed_tests < 1 then
    return jsonb_build_object('status','testing','reason','no_passing_test_evidence');
  end if;

  if v_open_failures > 0 then
    return jsonb_build_object('status','blocked','reason','open_failures','count',v_open_failures);
  end if;

  update public.tgg_build_tasks
  set status='complete',
      completed_at=now(),
      locked_by=null,
      locked_at=null,
      updated_at=now()
  where id=v_task_id;

  perform public.tgg_build_refresh_ready_tasks();

  return jsonb_build_object('status','complete','passed_tests',v_passed_tests);
end;
$function$


-- [40000000627] function public.tgg_call_room_bundle(p_room_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_call_room_bundle(p_room_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from public.tgg_call_participants where room_id=p_room_id and user_id=v_uid and left_at is null) then raise exception 'ROOM_ACCESS_DENIED'; end if;
 return jsonb_build_object(
  'ok',true,
  'room',(select jsonb_build_object('id',r.id,'title',r.title,'room_type',r.room_type,'status',r.status,'is_group',r.is_group,'created_by',r.created_by,'created_at',r.created_at,'studio_project_id',r.studio_project_id) from public.tgg_call_rooms r where r.id=p_room_id),
  'participants',coalesce((select jsonb_agg(jsonb_build_object('user_id',p.user_id,'mic_enabled',p.mic_enabled,'camera_enabled',p.camera_enabled,'joined_at',p.joined_at,'left_at',p.left_at)) from public.tgg_call_participants p where p.room_id=p_room_id and p.left_at is null),'[]'::jsonb),
  'generated_at',now()
 );
end$function$


-- [40000000628] function public.tgg_call_signal_send(p_room_id uuid, p_signal_type text, p_payload jsonb, p_recipient_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_call_signal_send(p_room_id uuid, p_signal_type text, p_payload jsonb, p_recipient_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_id uuid;
      v_type text:=lower(btrim(coalesce(p_signal_type,'')));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if v_type not in ('offer','answer','ice','mute','unmute','camera_on','camera_off','screen_on','screen_off','hangup') then
        raise exception 'SIGNAL_TYPE_INVALID';
      end if;
      if not exists(
        select 1 from public.tgg_call_participants
        where room_id=p_room_id and user_id=v_uid and left_at is null
      ) then raise exception 'ROOM_ACCESS_DENIED'; end if;
      if p_recipient_id is not null and not exists(
        select 1 from public.tgg_call_participants
        where room_id=p_room_id and user_id=p_recipient_id and left_at is null
      ) then raise exception 'RECIPIENT_NOT_IN_ROOM'; end if;

      insert into public.tgg_call_signals(room_id,sender_id,recipient_id,signal_type,payload)
      values(p_room_id,v_uid,p_recipient_id,v_type,coalesce(p_payload,'{}'::jsonb))
      returning id into v_id;

      return jsonb_build_object('ok',true,'signal_id',v_id,'room_id',p_room_id,'signal_type',v_type);
    end;
    $function$


-- [40000000629] function public.tgg_call_validation_final_health()
CREATE OR REPLACE FUNCTION public.tgg_call_validation_final_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with verified as (
  select r.id
  from public.tgg_call_rooms r
  where
    (
      select count(distinct p.user_id)
      from public.tgg_call_participants p
      where p.room_id=r.id
    ) >= 2
    and exists(
      select 1
      from public.tgg_call_signals o
      join public.tgg_call_signals a
        on a.room_id=o.room_id
       and a.signal_type='answer'
       and a.sender_id<>o.sender_id
      where o.room_id=r.id
        and o.signal_type='offer'
        and exists(
          select 1 from public.tgg_call_participants po
          where po.room_id=r.id and po.user_id=o.sender_id
        )
        and exists(
          select 1 from public.tgg_call_participants pa
          where pa.room_id=r.id and pa.user_id=a.sender_id
        )
    )
  order by r.created_at desc
  limit 1
)
select jsonb_build_object(
  'ok',true,
  'version','CALL-VALIDATION-ONE-FINAL-1.3',
  'validated',exists(select 1 from verified),
  'verified_room_id',(select id from verified),
  'requirements',jsonb_build_object(
    'distinct_users',2,
    'offer_signal',true,
    'answer_signal',true,
    'distinct_offer_answer_senders',true
  ),
  'prerequisites',jsonb_build_object(
    'second_distinct_user_available',exists(select 1 from verified),
    'invite_workflow_ready',true,
    'invite_create_rpc','tgg_call_validation_invite_create',
    'invite_claim_rpc','tgg_call_validation_invite_claim',
    'status',case
      when exists(select 1 from verified) then 'validated'
      else 'second_legitimate_user_required'
    end
  ),
  'privacy',jsonb_build_object(
    'auth_users_enumerated',false,
    'private_invites_enumerated',false
  ),
  'generated_at',now()
);
$function$


