-- [40000000641] function public.tgg_collab_artist_search(p_query text, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_collab_artist_search(p_query text DEFAULT NULL::text, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_limit integer:=greatest(1,least(coalesce(p_limit,20),50));v_q text:=nullif(btrim(coalesce(p_query,'')),'');
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object(
    'artists',coalesce((
      select jsonb_agg(jsonb_build_object('artist_id',a.id,'stage_name',a.stage_name,'avatar_url',a.avatar_url) order by a.stage_name)
      from (
        select id,stage_name,avatar_url
        from public.artists
        where user_id<>v_uid and (v_q is null or stage_name ilike '%'||v_q||'%')
        order by stage_name
        limit v_limit
      ) a
    ),'[]'::jsonb)
  );
end $function$


