-- [40000000644] function public.tgg_content_readiness_final_health()
CREATE OR REPLACE FUNCTION public.tgg_content_readiness_final_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_releases jsonb;
  v_summary jsonb;
  v_primary_credits integer:=0;
begin
  if v_uid is null then
    with release_rows as (
      select
        r.mixtape_id as id,
        r.title,
        r.track_count,
        coalesce((
          select count(*)
          from public.public_release_tracks_v1 t
          where t.mixtape_id=r.mixtape_id
            and (
              nullif(btrim(coalesce(t.audio_url,'')),'') is null
              or not (
                t.playback_mode='protected'
                or (
                  coalesce(t.audio_url,'') ~* '^https://'
                  and regexp_replace(split_part(t.audio_url,'?',1),'#.*$','') ~* '\.(mp3|wav|flac|m4a|aac|ogg)$'
                )
              )
            )
        ),0) as nondistributable_tracks
      from public.public_release_detail_v1 r
      join public.mixtapes m on m.id=r.mixtape_id
      where m.status='published'::public.mixtape_status
    )
    select
      jsonb_build_object(
        'published_releases',(select count(*) from release_rows),
        'distribution_candidates',(select count(*) from release_rows where track_count>0 and nondistributable_tracks=0),
        'public_only_or_incomplete_releases',(select count(*) from release_rows where track_count=0 or nondistributable_tracks>0),
        'releases_missing_distribution_metadata',null,
        'primary_artist_credits',null
      ),
      coalesce((
        select jsonb_agg(jsonb_build_object(
          'release_id',id,
          'title',title,
          'track_count',track_count,
          'distribution_candidate',track_count>0 and nondistributable_tracks=0,
          'content_state',case
            when track_count=0 then 'incomplete'
            when nondistributable_tracks>0 then 'public_playback_only'
            else 'distribution_candidate'
          end
        ) order by title,id)
        from release_rows
      ),'[]'::jsonb)
    into v_summary,v_releases;

    return jsonb_build_object(
      'ok',true,
      'version','CONTENT-READINESS-ONE-FINAL-1.7',
      'scope','public',
      'summary',v_summary,
      'releases',v_releases,
      'platform_blocking',false,
      'generated_at',now()
    );
  end if;

  select count(*)
  into v_primary_credits
  from public.tgg_release_credits c
  where c.owner_user_id=v_uid
    and c.role='primary_artist';

  with owned as (
    select
      m.id,
      m.title,
      public.tgg_creator_distribution_readiness(m.id) as readiness
    from public.mixtapes m
    join public.artists a on a.id=m.artist_id
    where a.user_id=v_uid
      and m.status='published'::public.mixtape_status
  ),
  release_rows as (
    select
      id,
      title,
      readiness,
      coalesce((readiness->'counts'->>'tracks')::integer,0) as track_count,
      coalesce((readiness->'counts'->>'missing_duration')::integer,0) as missing_duration,
      coalesce((readiness->'counts'->>'duplicate_master_tracks')::integer,0) as unresolved_duplicate_master_tracks,
      coalesce((readiness->>'distribution_candidate')::boolean,false) as distribution_candidate,
      coalesce((readiness->>'package_ready')::boolean,false) as package_ready,
      coalesce((readiness->>'submit_ready')::boolean,false) as submit_ready,
      coalesce((readiness->'metadata'->>'rights_confirmed')::boolean,false)
        and nullif(btrim(coalesce(readiness->'metadata'->>'label_name','')),'') is not null
        and nullif(btrim(coalesce(readiness->'metadata'->>'copyright_line','')),'') is not null
        and nullif(btrim(coalesce(readiness->'metadata'->>'publishing_line','')),'') is not null
        and coalesce(jsonb_array_length(coalesce(readiness->'metadata'->'territories','[]'::jsonb)),0)>0
        as distribution_metadata_complete,
      readiness->'metadata' is not null as distribution_metadata_shell_present
    from owned
  )
  select
    jsonb_build_object(
      'published_releases',(select count(*) from release_rows),
      'distribution_candidates',(select count(*) from release_rows where distribution_candidate),
      'master_reuse_review_releases',(select count(*) from release_rows where unresolved_duplicate_master_tracks>0),
      'public_only_or_incomplete_releases',(select count(*) from release_rows where not distribution_candidate),
      'candidate_tracks_missing_duration',(
        select coalesce(sum(missing_duration) filter(where distribution_candidate),0)
        from release_rows
      ),
      'candidate_releases_missing_distribution_metadata',(
        select count(*) from release_rows
        where distribution_candidate and not distribution_metadata_complete
      ),
      'candidate_releases_with_metadata_shell_only',(
        select count(*) from release_rows
        where distribution_candidate
          and distribution_metadata_shell_present
          and not distribution_metadata_complete
      ),
      'primary_artist_credits',v_primary_credits
    ),
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'release_id',id,
        'title',title,
        'track_count',track_count,
        'duplicate_master_tracks',unresolved_duplicate_master_tracks,
        'duplicate_master_reference',unresolved_duplicate_master_tracks>0,
        'distribution_candidate',distribution_candidate,
        'distribution_metadata_present',distribution_metadata_shell_present,
        'distribution_metadata_complete',distribution_metadata_complete,
        'candidate_tracks_missing_duration',missing_duration,
        'content_state',case
          when not distribution_candidate then
            case
              when track_count=0 then 'incomplete'
              when unresolved_duplicate_master_tracks>0 then 'master_reuse_review'
              else 'public_playback_only'
            end
          else 'distribution_candidate'
        end,
        'distribution_ready',package_ready,
        'submit_ready',submit_ready
      ) order by title,id)
      from release_rows
    ),'[]'::jsonb)
  into v_summary,v_releases;

  return jsonb_build_object(
    'ok',true,
    'version','CONTENT-READINESS-ONE-FINAL-1.7',
    'scope','creator',
    'summary',v_summary,
    'releases',v_releases,
    'platform_blocking',false,
    'distribution_feature_requires_creator_metadata',true,
    'generated_at',now()
  );
end
$function$


-- [40000000645] function public.tgg_conversation_thread_bundle(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_conversation_thread_bundle(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if not exists(select 1 from public.tgg_conversation_members where conversation_id=p_conversation_id and user_id=v_uid) then
        raise exception 'CONVERSATION_ACCESS_DENIED';
      end if;
      return jsonb_build_object(
        'ok',true,
        'conversation',(select jsonb_build_object('id',c.id,'title',c.title,'status',c.status,'project_type',c.project_type,'updated_at',c.updated_at) from public.tgg_conversations c where c.id=p_conversation_id),
        'members',coalesce((
          select jsonb_agg(jsonb_build_object(
            'user_id',m.user_id,'role',m.role,'stage_name',a.stage_name,'avatar_url',a.avatar_url
          ))
          from public.tgg_conversation_members m left join public.artists a on a.user_id=m.user_id
          where m.conversation_id=p_conversation_id
        ),'[]'::jsonb),
        'messages',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',x.id,'sender_id',x.sender_id,'body',x.body,'message_type',x.message_type,
            'reply_to_message_id',x.reply_to_message_id,'edited_at',x.edited_at,'metadata',x.metadata,'created_at',x.created_at,
            'stage_name',a.stage_name,'avatar_url',a.avatar_url
          ) order by x.created_at)
          from (
            select * from public.tgg_messages where conversation_id=p_conversation_id order by created_at desc limit 200
          ) x left join public.artists a on a.user_id=x.sender_id
        ),'[]'::jsonb)
      );
    end $function$


-- [40000000646] function public.tgg_create_collaboration_request(p_recipient_id uuid, p_project_title text, p_project_type text, p_note text)
CREATE OR REPLACE FUNCTION public.tgg_create_collaboration_request(p_recipient_id uuid, p_project_title text, p_project_type text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user uuid:=auth.uid();
  v_recipient_user uuid;
  v_id uuid;
  v_title text:=btrim(coalesce(p_project_title,''));
  v_type text:=btrim(coalesce(p_project_type,''));
  v_note text:=nullif(btrim(coalesce(p_note,'')),'');
begin
  if v_user is null then raise exception 'authentication required'; end if;

  select a.user_id
    into v_recipient_user
  from public.public_artist_directory_v1 a
  where a.artist_id=p_recipient_id
     or a.user_id=p_recipient_id
  limit 1;

  if v_recipient_user is null or v_recipient_user=v_user then
    raise exception 'invalid recipient';
  end if;

  if char_length(v_title)<1 or char_length(v_title)>160 then
    raise exception 'project title must be 1 to 160 characters';
  end if;

  if char_length(v_type)<1 or char_length(v_type)>80 then
    raise exception 'project type must be 1 to 80 characters';
  end if;

  if v_note is not null and char_length(v_note)>2000 then
    raise exception 'note too long';
  end if;

  if exists(
    select 1
    from public.tgg_collaboration_requests r
    where r.sender_id=v_user
      and r.recipient_id=v_recipient_user
      and r.project_title=v_title
      and r.status='pending'
  ) then
    raise exception 'matching request already pending';
  end if;

  insert into public.tgg_collaboration_requests(
    sender_id,recipient_id,project_title,project_type,note,status
  )
  values(
    v_user,v_recipient_user,v_title,v_type,v_note,'pending'
  )
  returning id into v_id;

  return v_id;
end
$function$


-- [40000000647] function public.tgg_create_conversation(p_user_id uuid, p_title text)
CREATE OR REPLACE FUNCTION public.tgg_create_conversation(p_user_id uuid, p_title text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_recipient uuid;
  v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select a.user_id into v_recipient
  from public.artists a
  where a.id=p_user_id or a.user_id=p_user_id
  limit 1;

  if v_recipient is null or v_recipient=v_uid then
    raise exception 'INVALID_RECIPIENT';
  end if;

  select c.id into v_id
  from public.tgg_conversations c
  join public.tgg_conversation_members a
    on a.conversation_id=c.id and a.user_id=v_uid
  join public.tgg_conversation_members b
    on b.conversation_id=c.id and b.user_id=v_recipient
  where c.project_type='dm'
    and (
      select count(*)
      from public.tgg_conversation_members m
      where m.conversation_id=c.id
    )=2
  order by c.created_at desc
  limit 1;

  if v_id is not null then return v_id; end if;

  insert into public.tgg_conversations(
    created_by,title,project_type,status,last_message_at
  )
  values(
    v_uid,
    coalesce(nullif(left(btrim(coalesce(p_title,'')),200),''),'Creator Chat'),
    'dm','active',null
  )
  returning id into v_id;

  insert into public.tgg_conversation_members(conversation_id,user_id,role)
  values(v_id,v_uid,'member'),(v_id,v_recipient,'member');

  return v_id;
end
$function$


-- [40000000648] function public.tgg_create_fan_collection(p_name text, p_description text, p_is_public boolean)
CREATE OR REPLACE FUNCTION public.tgg_create_fan_collection(p_name text, p_description text DEFAULT NULL::text, p_is_public boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare v_user uuid:=auth.uid(); v_id uuid; v_name text:=btrim(coalesce(p_name,'')); begin if v_user is null then raise exception 'authentication required'; end if; if char_length(v_name)<1 or char_length(v_name)>80 then raise exception 'collection name must be 1 to 80 characters'; end if; if p_description is not null and char_length(p_description)>500 then raise exception 'description too long'; end if; insert into public.fan_collections(user_id,name,description,is_public) values(v_user,v_name,nullif(btrim(p_description),''),coalesce(p_is_public,false)) returning id into v_id; return v_id; end $function$


-- [40000000649] function public.tgg_create_world_character(p_stage_name text, p_career_key text, p_avatar_config jsonb)
CREATE OR REPLACE FUNCTION public.tgg_create_world_character(p_stage_name text, p_career_key text DEFAULT 'artist'::text, p_avatar_config jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE sql
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
  select private.tgg_create_world_character(p_stage_name,p_career_key,p_avatar_config);
$function$


-- [40000000650] function public.tgg_creator_abuse_control_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_abuse_control_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
with rate_checks(name,ok) as (
  values
    ('messages_insert_rate', exists(
      select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid
      where c.relname='tgg_messages' and t.tgname='tgg_rate_messages_insert' and not t.tgisinternal
    )),
    ('membership_create_rate', exists(
      select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid
      where c.relname='tgg_membership_tiers' and t.tgname='tgg_rate_membership_tier_insert' and not t.tgisinternal
    )),
    ('distribution_insert_rate', exists(
      select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid
      where c.relname='tgg_distribution_requests' and t.tgname='tgg_rate_distribution_request_insert' and not t.tgisinternal
    )),
    ('call_signal_rate', exists(
      select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid
      where c.relname='tgg_call_signals' and t.tgname='tgg_rate_call_signal_insert' and not t.tgisinternal
    )),
    ('call_room_insert_rate', exists(
      select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid
      where c.relname='tgg_call_rooms' and t.tgname='tgg_rate_call_room_insert' and not t.tgisinternal
    )),
    ('distribution_rpc_rate', exists(
      select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='public' and p.proname='tgg_distribution_submit_request'
        and pg_get_functiondef(p.oid) ilike '%distribution.submit.rpc%'
        and pg_get_functiondef(p.oid) ilike '%tgg_creator_rate_limit_gate%'
    )),
    ('call_room_rpc_rate', exists(
      select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='public' and p.proname='tgg_start_call_room'
        and pg_get_functiondef(p.oid) ilike '%calls.room_start.rpc%'
        and pg_get_functiondef(p.oid) ilike '%tgg_creator_rate_limit_gate%'
    )),
    ('call_validation_invite_rate', exists(
      select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='private' and p.proname='tgg_call_validation_invite_create'
        and pg_get_functiondef(p.oid) ilike '%calls.validation_invite%'
        and pg_get_functiondef(p.oid) ilike '%tgg_creator_rate_limit_gate%'
    ))
),
audit_checks(name,ok) as (
  values
    ('membership_mutation_audit', exists(
      select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid
      where c.relname='tgg_membership_tiers' and t.tgname='tgg_audit_membership_tier_mutation' and not t.tgisinternal
    )),
    ('distribution_submit_audit', exists(
      select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='public' and p.proname='tgg_distribution_submit_request'
        and pg_get_functiondef(p.oid) ilike '%tgg_creator_mutation_audit_log%'
    )),
    ('call_room_audit', exists(
      select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='public' and p.proname='tgg_start_call_room'
        and pg_get_functiondef(p.oid) ilike '%tgg_creator_mutation_audit_log%'
    )),
    ('call_validation_invite_audit', exists(
      select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='private' and p.proname='tgg_call_validation_invite_create'
        and pg_get_functiondef(p.oid) ilike '%tgg_creator_mutation_audit_log%'
    ))
),
storage_checks as (
  select
    to_regclass('private.tgg_creator_rate_counters') is not null as rate_table,
    to_regclass('private.tgg_creator_mutation_audit') is not null as audit_table,
    not has_table_privilege('anon','private.tgg_creator_rate_counters','SELECT') as rate_anon_blocked,
    not has_table_privilege('authenticated','private.tgg_creator_rate_counters','SELECT') as rate_auth_select_blocked,
    not has_table_privilege('authenticated','private.tgg_creator_rate_counters','INSERT') as rate_auth_insert_blocked,
    not has_table_privilege('anon','private.tgg_creator_mutation_audit','SELECT') as audit_anon_blocked,
    not has_table_privilege('authenticated','private.tgg_creator_mutation_audit','SELECT') as audit_auth_select_blocked,
    not has_table_privilege('authenticated','private.tgg_creator_mutation_audit','INSERT') as audit_auth_insert_blocked
),
privacy_retention as (
  select
    exists(
      select 1 from cron.job
      where jobname='tgg-operational-cron-history-retention'
        and active=true
        and command='select private.tgg_operational_cron_history_retention();'
    ) as retention_job_active,
    pg_get_functiondef('private.tgg_operational_cron_history_retention()'::regprocedure) ilike '%tgg_creator_rate_counters%'
      and pg_get_functiondef('private.tgg_operational_cron_history_retention()'::regprocedure) ilike '%2 days%'
      and pg_get_functiondef('private.tgg_operational_cron_history_retention()'::regprocedure) ilike '%tgg_creator_mutation_audit%'
      and pg_get_functiondef('private.tgg_operational_cron_history_retention()'::regprocedure) ilike '%180 days%' as retention_contract,
    pg_get_functiondef('private.tgg_creator_rate_limit_gate(text,integer,integer)'::regprocedure)
      ilike '%RATE_LIMIT_ACTION_NOT_ALLOWED%' as rate_action_whitelist,
    pg_get_functiondef('private.tgg_creator_mutation_audit_log(text,text,jsonb)'::regprocedure)
      ilike '%AUDIT_ACTION_NOT_ALLOWED%' as audit_action_whitelist,
    pg_get_functiondef('private.tgg_creator_mutation_audit_log(text,text,jsonb)'::regprocedure)
      ilike '%AUDIT_SENSITIVE_METADATA_REJECTED%' as sensitive_metadata_reject,
    pg_get_functiondef('private.tgg_creator_mutation_audit_trigger()'::regprocedure)
      ilike '%AUDIT_TRIGGER_ACTION_NOT_ALLOWED%' as trigger_action_whitelist,
    (select count(*)=0 from private.tgg_creator_mutation_audit
      where metadata::text ~* '"(body|payload|package_snapshot|[^"]*token[^"]*|[^"]*secret[^"]*|password)"[[:space:]]*:'
    ) as no_sensitive_audit_rows,
    (select count(*)=0 from private.tgg_creator_rate_counters where bucket_start<now()-interval '2 days') as no_stale_rate_rows,
    (select count(*)=0 from private.tgg_creator_mutation_audit where occurred_at<now()-interval '180 days') as no_expired_audit_rows
),
r as (
  select count(*) total,count(*) filter(where ok) ready,
         coalesce(jsonb_agg(name order by name) filter(where not ok),'[]'::jsonb) failed
  from rate_checks
),
a as (
  select count(*) total,count(*) filter(where ok) ready,
         coalesce(jsonb_agg(name order by name) filter(where not ok),'[]'::jsonb) failed
  from audit_checks
)
select jsonb_build_object(
  'ok',
    r.ready=r.total
    and a.ready=a.total
    and s.rate_table and s.audit_table
    and s.rate_anon_blocked and s.rate_auth_select_blocked and s.rate_auth_insert_blocked
    and s.audit_anon_blocked and s.audit_auth_select_blocked and s.audit_auth_insert_blocked
    and p.retention_job_active and p.retention_contract
    and p.rate_action_whitelist and p.audit_action_whitelist
    and p.sensitive_metadata_reject and p.trigger_action_whitelist
    and p.no_sensitive_audit_rows and p.no_stale_rate_rows and p.no_expired_audit_rows,
  'version','CREATOR-ABUSE-CONTROL-1.1',
  'rate_controls',jsonb_build_object('ready',r.ready,'total',r.total,'failed',r.failed),
  'audit_controls',jsonb_build_object('ready',a.ready,'total',a.total,'failed',a.failed),
  'private_storage',jsonb_build_object(
    'rate_table',s.rate_table,
    'audit_table',s.audit_table,
    'direct_client_access_blocked',
      s.rate_anon_blocked and s.rate_auth_select_blocked and s.rate_auth_insert_blocked
      and s.audit_anon_blocked and s.audit_auth_select_blocked and s.audit_auth_insert_blocked
  ),
  'privacy',jsonb_build_object(
    'rate_action_whitelist',p.rate_action_whitelist,
    'audit_action_whitelist',p.audit_action_whitelist,
    'sensitive_metadata_rejected',p.sensitive_metadata_reject,
    'trigger_action_whitelist',p.trigger_action_whitelist,
    'sensitive_rows',case when p.no_sensitive_audit_rows then 0 else 1 end
  ),
  'retention',jsonb_build_object(
    'job_active',p.retention_job_active,
    'contract_ready',p.retention_contract,
    'rate_days',2,
    'audit_days',180,
    'stale_rate_rows',case when p.no_stale_rate_rows then 0 else 1 end,
    'expired_audit_rows',case when p.no_expired_audit_rows then 0 else 1 end
  ),
  'limits',jsonb_build_object(
    'messages_per_minute',120,
    'membership_tiers_per_hour',20,
    'distribution_rows_per_hour',20,
    'distribution_rpc_per_hour',60,
    'call_signals_per_minute',600,
    'call_rooms_per_10_minutes',30,
    'call_room_rpc_per_10_minutes',60,
    'call_validation_invites_per_hour',10
  ),
  'generated_at',now()
)
from r cross join a cross join storage_checks s cross join privacy_retention p;
$function$


-- [40000000651] function public.tgg_creator_access_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_access_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with write_functions as (
  select p.oid,p.proname
  from pg_proc p
  join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public'
    and p.proname in (
      'tgg_studio_create_project','tgg_finalize_studio_upload','tgg_studio_save_version',
      'tgg_beat_pattern_save','tgg_studio_project_collab_invite','tgg_studio_project_collab_respond',
      'tgg_studio_project_presence_upsert','tgg_studio_project_apply_patch',
      'tgg_finalize_video_upload','tgg_video_submit_from_storage','tgg_video_publish',
      'tgg_live_studio_create','tgg_live_start','tgg_live_end','tgg_live_studio_finalize_replay',
      'tgg_send_message','tgg_finalize_message_upload','tgg_start_call_room','tgg_call_signal_send',
      'tgg_finalize_vault_upload','tgg_vault_item_create','tgg_attach_vault_media',
      'tgg_store_product_create','tgg_store_product_set_payment_link',
      'tgg_audiobook_create_draft','tgg_audiobook_add_chapter_from_storage','tgg_audiobook_submit',
      'tgg_game_create_draft','tgg_game_session_create','tgg_game_session_join',
      'tgg_game_session_start','tgg_game_session_end'
    )
),
function_checks as (
  select count(*) total,
         count(*) filter(where not p.prosecdef) invoker_count,
         count(*) filter(where has_function_privilege('authenticated',p.oid,'EXECUTE')) auth_exec_count,
         count(*) filter(where not has_function_privilege('anon',p.oid,'EXECUTE')) anon_blocked_count,
         count(*) filter(where not has_function_privilege('public',p.oid,'EXECUTE')) public_blocked_count
  from write_functions w join pg_proc p on p.oid=w.oid
),
core_tables(name) as (
  values
    ('tgg_studio_projects'),('tgg_studio_assets'),('tgg_studio_project_members'),
    ('tgg_beat_patterns'),('tgg_media_vault_assets'),('tgg_creative_projects'),
    ('live_streams'),('tgg_live_replays'),('tgg_conversation_members'),('tgg_messages'),
    ('merch_products'),('tgg_audiobooks'),('tgg_audiobook_chapters'),
    ('tgg_games'),('tgg_game_sessions'),('tgg_vault_items')
),
table_checks as (
  select count(*) total,count(*) filter(where c.relrowsecurity) rls_enabled_count
  from core_tables t
  join pg_class c on c.relname=t.name
  join pg_namespace n on n.oid=c.relnamespace and n.nspname='public'
),
collab as (
  select jsonb_build_object(
    'studio_assets_shared_select',exists(select 1 from pg_policy pol join pg_class c on c.oid=pol.polrelid where c.relname='tgg_studio_assets' and pol.polname='tgg_studio_assets_member_select'),
    'studio_assets_creator_write',exists(select 1 from pg_policy pol join pg_class c on c.oid=pol.polrelid where c.relname='tgg_studio_assets' and pol.polname='tgg_studio_assets_member_insert'),
    'beat_patterns_shared_select',exists(select 1 from pg_policy pol join pg_class c on c.oid=pol.polrelid where c.relname='tgg_beat_patterns' and pol.polname='tgg_beat_patterns_project_select'),
    'beat_patterns_shared_edit',exists(select 1 from pg_policy pol join pg_class c on c.oid=pol.polrelid where c.relname='tgg_beat_patterns' and pol.polname='tgg_beat_patterns_project_update'),
    'beat_identity_lock',exists(select 1 from pg_trigger tg join pg_class c on c.oid=tg.tgrelid where c.relname='tgg_beat_patterns' and tg.tgname='tgg_lock_beat_pattern_identity' and not tg.tgisinternal)
  ) j
),
summary as (
  select f.total function_total,f.invoker_count,f.auth_exec_count,f.anon_blocked_count,f.public_blocked_count,
         t.total table_total,t.rls_enabled_count,c.j collab
  from function_checks f cross join table_checks t cross join collab c
)
select jsonb_build_object(
  'ok',
    invoker_count=function_total
    and auth_exec_count=function_total
    and anon_blocked_count=function_total
    and public_blocked_count=function_total
    and rls_enabled_count=table_total
    and not exists(select 1 from jsonb_each(collab) where coalesce((value#>>'{}')::boolean,false)=false),
  'version','ACCESS-QA-1.1',
  'write_functions',jsonb_build_object(
    'total',function_total,'security_invoker',invoker_count,'authenticated_execute',auth_exec_count,
    'anon_blocked',anon_blocked_count,'public_blocked',public_blocked_count
  ),
  'rls',jsonb_build_object('core_tables',table_total,'enabled',rls_enabled_count),
  'collaboration',collab,
  'generated_at',now()
)
from summary;
$function$


