-- [40000000655] function public.tgg_creator_archive_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_archive_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist uuid;
  v_active_live bigint:=0;
  v_active_memberships bigint:=0;
  v_active_tiers bigint:=0;
  v_distribution_inflight bigint:=0;
  v_pending_collabs bigint:=0;
  v_blockers jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select id into v_artist from public.artists where user_id=v_uid order by created_at limit 1;
  select count(*) into v_active_live from public.live_streams where creator_id=v_uid and status='live';
  select count(*) into v_active_memberships from public.tgg_memberships where (artist_id=v_artist or fan_user_id=v_uid) and status='active';
  select count(*) into v_active_tiers from public.tgg_membership_tiers where artist_id=v_artist and is_active=true;
  select count(*) into v_distribution_inflight from public.tgg_distribution_requests
    where (owner_user_id=v_uid or artist_id=v_artist) and status in ('prepared','queued','processing','submitted');
  select count(*) into v_pending_collabs from public.tgg_collaboration_requests
    where (sender_id=v_uid or recipient_id=v_uid) and status='pending';

  v_blockers:=jsonb_strip_nulls(jsonb_build_object(
    'active_live_streams',case when v_active_live>0 then v_active_live end,
    'active_memberships',case when v_active_memberships>0 then v_active_memberships end,
    'active_membership_tiers',case when v_active_tiers>0 then v_active_tiers end,
    'distribution_inflight',case when v_distribution_inflight>0 then v_distribution_inflight end,
    'pending_collaborations',case when v_pending_collabs>0 then v_pending_collabs end
  ));

  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-ARCHIVE-READINESS-1.1',
    'archive_action_enabled',true,
    'delete_request_enabled',true,
    'ready',v_blockers='{}'::jsonb,
    'blockers',v_blockers,
    'archive_grace_hours',24,
    'delete_grace_days',7,
    'immediate_destructive_execution',false,
    'recommended_order',jsonb_build_array(
      'export_creator_data',
      'end_live_sessions',
      'resolve_memberships_and_tiers',
      'finish_or_cancel_distribution_requests',
      'resolve_pending_collaborations',
      'review_deletion_impact',
      'request_archive_or_delete_with_explicit_confirmation'
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000656] function public.tgg_creator_audiobooks_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_audiobooks_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist_id uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

      select id into v_artist_id
      from public.artists
      where user_id=v_uid
      order by created_at
      limit 1;

      if v_artist_id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

      return jsonb_build_object(
        'ok',true,
        'version','AUDIOBOOKS-ONE-FINAL-1.0',
        'counts',jsonb_build_object(
          'total',(select count(*) from public.tgg_audiobooks where artist_id=v_artist_id),
          'draft',(select count(*) from public.tgg_audiobooks where artist_id=v_artist_id and status='draft'),
          'pending',(select count(*) from public.tgg_audiobooks where artist_id=v_artist_id and status='pending'),
          'published',(select count(*) from public.tgg_audiobooks where artist_id=v_artist_id and status='published'),
          'chapters',(select count(*) from public.tgg_audiobook_chapters c join public.tgg_audiobooks b on b.id=c.audiobook_id where b.artist_id=v_artist_id)
        ),
        'books',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',b.id,
            'project_id',b.project_id,
            'title',b.title,
            'author_name',b.author_name,
            'narrator_name',b.narrator_name,
            'description',b.description,
            'cover_url',b.cover_url,
            'genre',b.genre,
            'language',b.language,
            'explicit_content',b.explicit_content,
            'allow_downloads',b.allow_downloads,
            'status',b.status,
            'visibility',b.visibility,
            'admin_note',b.admin_note,
            'published_at',b.published_at,
            'created_at',b.created_at,
            'updated_at',b.updated_at,
            'chapter_count',(select count(*) from public.tgg_audiobook_chapters c where c.audiobook_id=b.id)
          ) order by b.updated_at desc)
          from public.tgg_audiobooks b
          where b.artist_id=v_artist_id
        ),'[]'::jsonb),
        'capabilities',jsonb_build_object(
          'create_draft',true,
          'upload_chapters',true,
          'submit_review',true,
          'secure_public_playback',true
        ),
        'generated_at',now()
      );
    end;
    $function$


-- [40000000657] function public.tgg_creator_beatmaker_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_beatmaker_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_library jsonb;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

      v_library:=public.tgg_sound_library_search(
        null,null,null,null,null,null,null,false,true,false,false,50
      );

      return jsonb_build_object(
        'ok',true,
        'version','BEATMAKER-ONE-FINAL-1.1',
        'counts',jsonb_build_object(
          'beat_projects',(select count(*) from public.tgg_studio_projects where user_id=v_uid and project_type='beat'),
          'patterns',(select count(*) from public.tgg_beat_patterns where user_id=v_uid),
          'owned_sounds',(select count(*) from public.tgg_sound_library_items where owner_user_id=v_uid and is_active=true),
          'global_sounds',(select count(*) from public.tgg_sound_library_items where owner_user_id is null and is_active=true),
          'favorites',(select count(*) from public.tgg_sound_library_favorites where user_id=v_uid),
          'imports',(select count(*) from public.tgg_sound_library_imports where user_id=v_uid)
        ),
        'projects',coalesce((
          select jsonb_agg(to_jsonb(x) order by x.updated_at desc)
          from (
            select id,title,bpm,musical_key,status,updated_at
            from public.tgg_studio_projects
            where user_id=v_uid and project_type='beat'
            order by updated_at desc
            limit 50
          ) x
        ),'[]'::jsonb),
        'patterns',coalesce((
          select jsonb_agg(to_jsonb(x) order by x.updated_at desc)
          from (
            select id,project_id,name,bpm,steps,pattern_data,updated_at
            from public.tgg_beat_patterns
            where user_id=v_uid
            order by updated_at desc
            limit 100
          ) x
        ),'[]'::jsonb),
        'library',v_library,
        'favorites',coalesce((
          select jsonb_agg(jsonb_build_object(
            'sound_id',s.id,'title',s.title,'asset_type',s.asset_type,'bpm',s.bpm,
            'musical_key',s.musical_key,'tags',s.tags,'preview_url',s.preview_url,
            'source_provider',s.source_provider,'license_name',s.license_name,
            'license_kind',s.license_kind,'commercial_use_allowed',s.commercial_use_allowed,
            'attribution_required',s.attribution_required,'attribution_text',s.attribution_text,
            'import_allowed',s.import_allowed
          ) order by f.created_at desc)
          from public.tgg_sound_library_favorites f
          join public.tgg_sound_library_items s on s.id=f.sound_id
          where f.user_id=v_uid and s.is_active=true
            and (s.owner_user_id is null or s.owner_user_id=v_uid)
        ),'[]'::jsonb),
        'recent_imports',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',i.id,'sound_id',i.sound_id,'project_id',i.project_id,
            'studio_asset_id',i.studio_asset_id,'attribution',i.attribution_snapshot,
            'license_snapshot',i.license_snapshot,'created_at',i.created_at
          ) order by i.created_at desc)
          from public.tgg_sound_library_imports i
          where i.user_id=v_uid
          limit 100
        ),'[]'::jsonb),
        'capabilities',jsonb_build_object(
          'search_library',true,'advanced_library_filters',true,
          'favorite_sounds',true,'upload_owned_sounds',true,
          'register_owned_asset',true,'import_licensed_sound',true,
          'private_owned_preview',true,'save_pattern',true,
          'external_catalog_auto_import',false
        ),
        'licensing_policy',jsonb_build_object(
          'allowed_kinds',jsonb_build_array('user_owned','public_domain','cc0','creative_commons','royalty_free','custom_reusable'),
          'requires_import_allowed',true,'stores_license_snapshot',true,
          'copyrighted_scraping',false,'unverified_external_imports',false
        ),
        'generated_at',now()
      );
    end;
    $function$


-- [40000000658] function public.tgg_creator_career_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_career_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

      select id into v_artist
      from public.artists
      where user_id=v_uid
      order by created_at
      limit 1;

      if v_artist is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

      return jsonb_build_object(
        'ok',true,
        'version','CAREER-ONE-FINAL-1.1',
        'career',public.tgg_get_creator_career_workspace_bundle(v_artist),
        'opportunities',public.tgg_get_creator_opportunity_bundle(v_artist),
        'events',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',e.id,'title',e.title,'description',e.description,'venue_name',e.venue_name,
            'city',e.city,'region',e.region,'country',e.country,'starts_at',e.starts_at,'ends_at',e.ends_at,
            'event_type',e.event_type,'ticket_url',e.ticket_url,'status',e.status,
            'rsvp_counts',jsonb_build_object(
              'interested',(select count(*) from public.tgg_event_rsvps r where r.event_id=e.id and r.status='interested'),
              'going',(select count(*) from public.tgg_event_rsvps r where r.event_id=e.id and r.status='going')
            )
          ) order by e.created_at desc)
          from public.tgg_events e
          where e.created_by=v_uid
        ),'[]'::jsonb),
        'incoming_applications',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',a.id,'opportunity_id',a.opportunity_id,'opportunity_title',o.title,
            'message',a.message,'portfolio_url',a.portfolio_url,'status',a.status,'created_at',a.created_at,
            'applicant',jsonb_build_object(
              'artist_id',ar.id,'stage_name',coalesce(ar.stage_name,'Applicant'),'avatar_url',ar.avatar_url,
              'profile_url',case when ar.id is null then null else '/p/public-artist-profile.html?artist_id='||ar.id::text end
            )
          ) order by a.created_at desc)
          from public.tgg_opportunity_applications a
          join public.tgg_opportunities o on o.id=a.opportunity_id
          left join public.artists ar on ar.user_id=a.applicant_user_id
          where o.created_by=v_uid
        ),'[]'::jsonb),
        'my_rsvps',coalesce((
          select jsonb_agg(jsonb_build_object(
            'event_id',r.event_id,'status',r.status,'updated_at',r.updated_at,'title',e.title,'starts_at',e.starts_at
          ) order by e.starts_at)
          from public.tgg_event_rsvps r
          join public.tgg_events e on e.id=r.event_id
          where r.user_id=v_uid
        ),'[]'::jsonb),
        'live_booking',public.tgg_get_creator_live_booking_bundle(v_artist),
        'counts',jsonb_build_object(
          'applications',(select count(*) from public.tgg_opportunity_applications where applicant_user_id=v_uid),
          'incoming_applications',(
            select count(*) from public.tgg_opportunity_applications a
            join public.tgg_opportunities o on o.id=a.opportunity_id
            where o.created_by=v_uid
          ),
          'created_opportunities',(select count(*) from public.tgg_opportunities where created_by=v_uid),
          'open_opportunities',(select count(*) from public.tgg_opportunities where created_by=v_uid and status='open'),
          'booking_incoming',(select count(*) from public.tgg_booking_requests where provider_user_id=v_uid),
          'booking_outgoing',(select count(*) from public.tgg_booking_requests where requester_user_id=v_uid),
          'events',(select count(*) from public.tgg_events where created_by=v_uid),
          'published_events',(select count(*) from public.tgg_events where created_by=v_uid and status='published'),
          'live_events',(select count(*) from public.tgg_live_events where host_user_id=v_uid)
        ),
        'generated_at',now()
      );
    end $function$


-- [40000000659] function public.tgg_creator_collab_bundle()
