  from b;
$function$


-- [40000000660] function public.tgg_creator_communications_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_communications_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'user_id',v_uid,
    'counts',jsonb_build_object(
      'conversations',(
        select count(*)
        from public.tgg_conversations c
        where c.created_by=v_uid
           or exists(
             select 1 from public.tgg_conversation_members m
             where m.conversation_id=c.id and m.user_id=v_uid
           )
      ),
      'unread_messages',(
        select count(*)
        from public.tgg_messages m
        join public.tgg_conversation_members cm
          on cm.conversation_id=m.conversation_id
         and cm.user_id=v_uid
        where m.sender_id<>v_uid
          and m.created_at > coalesce(cm.last_read_at,'epoch'::timestamptz)
      ),
      'collab_incoming_pending',(
        select count(*) from public.tgg_collaboration_requests
        where recipient_id=v_uid and status='pending'
      ),
      'collab_outgoing_pending',(
        select count(*) from public.tgg_collaboration_requests
        where sender_id=v_uid and status='pending'
      ),
      'active_calls',(
        select count(distinct r.id)
        from public.tgg_call_rooms r
        left join public.tgg_call_participants p on p.room_id=r.id
        where r.status='active'
          and (r.created_by=v_uid or p.user_id=v_uid)
      )
    ),
    'recent_conversations',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.last_activity desc)
      from (
        select c.id,c.title,c.project_type,c.status,
               coalesce(c.last_message_at,c.updated_at,c.created_at) as last_activity
        from public.tgg_conversations c
        where c.created_by=v_uid
           or exists(
             select 1 from public.tgg_conversation_members cm
             where cm.conversation_id=c.id and cm.user_id=v_uid
           )
        order by coalesce(c.last_message_at,c.updated_at,c.created_at) desc
        limit 20
      ) x
    ),'[]'::jsonb),
    'collaboration_requests',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.updated_at desc)
      from (
        select id,sender_id,recipient_id,project_title,project_type,note,status,
               conversation_id,created_at,updated_at,
               case when recipient_id=v_uid then 'incoming' else 'outgoing' end as direction
        from public.tgg_collaboration_requests
        where sender_id=v_uid or recipient_id=v_uid
        order by updated_at desc
        limit 50
      ) x
    ),'[]'::jsonb),
    'active_calls',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select distinct r.id,r.conversation_id,r.title,r.room_type,r.status,r.is_group,r.created_at
        from public.tgg_call_rooms r
        left join public.tgg_call_participants p on p.room_id=r.id
        where r.status='active'
          and (r.created_by=v_uid or p.user_id=v_uid)
        order by r.created_at desc
        limit 20
      ) x
    ),'[]'::jsonb),
    'capabilities',jsonb_build_object(
      'create_conversation',has_function_privilege('authenticated','public.tgg_create_conversation(uuid,text)','EXECUTE'),
      'send_message',has_function_privilege('authenticated','public.tgg_send_message(uuid,text,text,uuid)','EXECUTE'),
      'mark_read',has_function_privilege('authenticated','public.tgg_mark_conversation_read(uuid)','EXECUTE'),
      'create_collab',has_function_privilege('authenticated','public.tgg_create_collaboration_request(uuid,text,text,text)','EXECUTE'),
      'respond_collab',has_function_privilege('authenticated','public.tgg_respond_collaboration_request(uuid,boolean)','EXECUTE'),
      'start_call',has_function_privilege('authenticated','public.tgg_start_call_room(uuid,text)','EXECUTE'),
      'end_call',has_function_privilege('authenticated','public.tgg_end_call_room(uuid)','EXECUTE')
    ),
    'generated_at',now()
  );
end;
$function$


-- [40000000661] function public.tgg_creator_copilot()
CREATE OR REPLACE FUNCTION public.tgg_creator_copilot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist public.artists;
  v_release public.mixtapes;
  v_growth jsonb;
  v_stage text;
  v_title text;
  v_genre text;
  v_release_url text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist.id is null then
    return jsonb_build_object(
      'ok',true,'version','CREATOR-COPILOT-1.1','has_artist_profile',false,
      'captions','[]'::jsonb,'cover_briefs','[]'::jsonb,'clip_ideas','[]'::jsonb,
      'promo_scripts','[]'::jsonb,'collab_prompts','[]'::jsonb,'generated_at',now()
    );
  end if;

  select * into v_release
  from public.mixtapes
  where artist_id=v_artist.id and status='published'
  order by coalesce(featured,false) desc,
           (coalesce(play_count,0)+(coalesce(download_count,0)*3)) desc,
           created_at desc
  limit 1;

  v_growth:=public.tgg_creator_growth_status();
  v_stage:=coalesce(nullif(btrim(v_artist.stage_name),''),'TRU GO GETTA Creator');
  v_title:=coalesce(nullif(btrim(v_release.title),''),'your latest release');
  v_genre:=coalesce(nullif(btrim(v_release.genre),''),'music');
  if v_release.id is not null and nullif(btrim(coalesce(v_release.slug,'')),'') is not null then
    v_release_url:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-shell?view=release&slug='||v_release.slug;
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-COPILOT-1.1',
    'mode','data_driven_template_assistant',
    'note','Suggestions are generated from your live creator/release data and are editable.',
    'focus_release',case when v_release.id is null then null else jsonb_build_object(
      'release_id',v_release.id,'title',v_release.title,'genre',v_release.genre,'url',v_release_url
    ) end,
    'captions',jsonb_build_array(
      jsonb_build_object('style','direct','text',v_stage||' just dropped "'||v_title||'". Tap in, run it up, and tell me which track stays in rotation. '||coalesce(v_release_url,'')),
      jsonb_build_object('style','story','text','Built this one for the people who really listen. "'||v_title||'" is out now from '||v_stage||'. If it hits, save it and send it to somebody who needs to hear it. '||coalesce(v_release_url,'')),
      jsonb_build_object('style','engagement','text','First listen to "'||v_title||'": what are you rating it 1–10? Drop your score, save the release, and share it with one person. '||coalesce(v_release_url,''))
    ),
    'cover_briefs',jsonb_build_array(
      jsonb_build_object('direction','cinematic','brief','Create a cinematic square cover for "'||v_title||'" by '||v_stage||'. Mood: bold, premium, modern. Genre cue: '||v_genre||'. Strong focal subject, dramatic lighting, minimal typography, readable at thumbnail size.'),
      jsonb_build_object('direction','minimal','brief','Design a minimal high-contrast cover for "'||v_title||'". Use one memorable visual symbol, clean spacing, restrained typography, and a premium editorial feel. Avoid clutter.'),
      jsonb_build_object('direction','street-luxury','brief','Design a polished street-luxury cover for "'||v_title||'" by '||v_stage||'. Blend raw urban texture with premium fashion/editorial presentation. Keep the title dominant and mobile-readable.')
    ),
    'clip_ideas',jsonb_build_array(
      jsonb_build_object('format','hook','idea','15–20 second vertical clip: start on the strongest lyric/beat moment from "'||v_title||'", add a hard visual cut in the first second, then end with the release cover and Listen Now CTA.'),
      jsonb_build_object('format','studio','idea','Behind-the-scenes vertical clip showing how "'||v_title||'" was made. Open with the finished sound, cut to the studio process, then return to the finished moment.'),
      jsonb_build_object('format','reaction','idea','Create a reaction prompt: play the strongest 10–15 seconds from "'||v_title||'" and ask viewers to rate it, choose a favorite bar, or tag someone who would replay it.')
    ),
    'promo_scripts',jsonb_build_array(
      jsonb_build_object(
        'format','15-second',
        'script','[0–2s] Hook: "Stop scrolling — this one is for the people who like real '||v_genre||'." '||
                 '[2–10s] Play the strongest moment from "'||v_title||'". '||
                 '[10–15s] "'||v_title||'" by '||v_stage||' is out now. Tap in, save it, and tell me your favorite part. '||coalesce(v_release_url,'')
      ),
      jsonb_build_object(
        'format','30-second',
        'script','[0–4s] Open on camera: "I want your real opinion on this one." '||
                 '[4–18s] Cut to the strongest section of "'||v_title||'" with quick studio or performance visuals. '||
                 '[18–25s] Voiceover: "This is '||v_stage||' — I built this for the people who actually listen." '||
                 '[25–30s] CTA: "Run "'||v_title||'", save it if it hits, and send it to one person." '||coalesce(v_release_url,'')
      ),
      jsonb_build_object(
        'format','story-sequence',
        'script','Story 1: Face camera — "New drop. I need your honest reaction." '||
                 'Story 2: Play 8–12 seconds from "'||v_title||'" with the cover on screen. '||
                 'Story 3: Poll — "Would you replay this?" YES / RUN IT BACK. '||
                 'Story 4: Link sticker CTA — "Listen to "'||v_title||'" now." '||coalesce(v_release_url,'')
      )
    ),
    'collab_prompts',jsonb_build_array(
      jsonb_build_object('type','feature','text','Looking for a serious feature on a '||v_genre||' record. Send your strongest verse/hook and what you bring to the record. Quality + fit over follower count.'),
      jsonb_build_object('type','producer','text','Looking for producers who can match the energy around "'||v_title||'". Send 2–3 of your strongest beats, BPM/key if available, and your turnaround time.'),
      jsonb_build_object('type','visual','text','Looking for a visual collaborator for upcoming music content—short-form clips, cover concepts, and performance visuals. Send your best recent work and availability.')
    ),
    'growth_context',jsonb_build_object(
      'followers',v_growth->'followers',
      'published_releases',v_growth->'published_releases',
      'referrals',v_growth->'successful_referrals',
      'profile_score',v_growth->'profile_score'
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000662] function public.tgg_creator_create_mixtape_draft(p_title text, p_genre text, p_description text, p_cover_url text, p_cover_path text, p_explicit text)
CREATE OR REPLACE FUNCTION public.tgg_creator_create_mixtape_draft(p_title text, p_genre text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_cover_url text DEFAULT NULL::text, p_cover_path text DEFAULT NULL::text, p_explicit text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist_id uuid;
      v_id uuid;
      v_title text:=btrim(coalesce(p_title,''));
      v_cover_path text:=nullif(btrim(coalesce(p_cover_path,'')),'');
      v_cover_url text:=nullif(btrim(coalesce(p_cover_url,'')),'');
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist_id from public.artists where user_id=v_uid limit 1;
      if v_artist_id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;
      if char_length(v_title)<1 or char_length(v_title)>200 then raise exception 'TITLE_INVALID'; end if;

      if v_cover_path is not null and split_part(v_cover_path,'/',1)<>v_uid::text then
        raise exception 'COVER_PATH_NOT_OWNED';
      end if;
      if v_cover_url is not null and v_cover_url !~* '^https?://' then
        raise exception 'COVER_URL_INVALID';
      end if;

      insert into public.mixtapes(
        artist_id,user_id,title,genre,description,cover_url,cover_path,explicit,status
      )
      values(
        v_artist_id,v_uid,v_title,
        nullif(btrim(coalesce(p_genre,'')),''),
        nullif(btrim(coalesce(p_description,'')),''),
        v_cover_url,v_cover_path,
        nullif(btrim(coalesce(p_explicit,'')),''),
        'draft'::public.mixtape_status
      )
      returning id into v_id;

      return jsonb_build_object('ok',true,'id',v_id,'title',v_title,'status','draft');
    end;
    $function$


-- [40000000663] function public.tgg_creator_create_profile(p_stage_name text, p_bio text, p_avatar_url text)
CREATE OR REPLACE FUNCTION public.tgg_creator_create_profile(p_stage_name text, p_bio text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist public.artists;
      v_name text:=btrim(coalesce(p_stage_name,''));
    begin
      if v_uid is null then
        raise exception 'AUTH_REQUIRED' using errcode='42501';
      end if;

      if char_length(v_name)<2 or char_length(v_name)>80 then
        raise exception 'STAGE_NAME_INVALID';
      end if;

      if exists(select 1 from public.artists where user_id=v_uid) then
        raise exception 'ARTIST_PROFILE_EXISTS';
      end if;

      if exists(select 1 from public.artists where lower(stage_name)=lower(v_name)) then
        raise exception 'STAGE_NAME_TAKEN';
      end if;

      insert into public.artists(user_id,stage_name,bio,avatar_url)
      values(
        v_uid,
        v_name,
        nullif(btrim(coalesce(p_bio,'')),''),
        nullif(btrim(coalesce(p_avatar_url,'')),'')
      )
      returning * into v_artist;

      return jsonb_build_object(
        'ok',true,
        'artist_id',v_artist.id,
        'stage_name',v_artist.stage_name,
        'next_step','creator_os'
      );
    end;
    $function$


