-- [40000000666] function public.tgg_creator_data_integrity_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_data_integrity_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
with orphan_checks as (
  select 'tracks_without_mixtape' key, count(*)::bigint n
  from public.tracks t left join public.mixtapes m on m.id=t.mixtape_id
  where t.mixtape_id is not null and m.id is null

  union all
  select 'studio_assets_without_project', count(*)::bigint
  from public.tgg_studio_assets a left join public.tgg_studio_projects p on p.id=a.project_id
  where a.project_id is not null and p.id is null

  union all
  select 'studio_members_without_project', count(*)::bigint
  from public.tgg_studio_project_members m left join public.tgg_studio_projects p on p.id=m.project_id
  where m.project_id is not null and p.id is null

  union all
  select 'messages_without_conversation', count(*)::bigint
  from public.tgg_messages m left join public.tgg_conversations c on c.id=m.conversation_id
  where m.conversation_id is not null and c.id is null

  union all
  select 'conversation_members_without_conversation', count(*)::bigint
  from public.tgg_conversation_members cm left join public.tgg_conversations c on c.id=cm.conversation_id
  where cm.conversation_id is not null and c.id is null

  union all
  select 'live_replays_without_stream', count(*)::bigint
  from public.tgg_live_replays r left join public.live_streams l on l.id=r.stream_id
  where r.stream_id is not null and l.id is null

  union all
  select 'audiobook_chapters_without_book', count(*)::bigint
  from public.tgg_audiobook_chapters c left join public.tgg_audiobooks b on b.id=c.audiobook_id
  where c.audiobook_id is not null and b.id is null

  union all
  select 'game_sessions_without_game', count(*)::bigint
  from public.tgg_game_sessions s left join public.tgg_games g on g.id=s.game_id
  where s.game_id is not null and g.id is null

  union all
  select 'membership_rows_without_tier', count(*)::bigint
  from public.tgg_memberships m left join public.tgg_membership_tiers t on t.id=m.tier_id
  where m.tier_id is not null and t.id is null

  union all
  select 'vault_assets_without_creative_project', count(*)::bigint
  from public.tgg_media_vault_assets v left join public.tgg_creative_projects p on p.id=v.project_id
  where v.project_id is not null and p.id is null
),
mismatch_checks as (
  select 'tracks_user_mismatch_mixtape' key, count(*)::bigint n
  from public.tracks t join public.mixtapes m on m.id=t.mixtape_id
  where t.user_id is not null and m.user_id is not null and t.user_id<>m.user_id

  union all
  select 'studio_assets_user_mismatch_project', count(*)::bigint
  from public.tgg_studio_assets a join public.tgg_studio_projects p on p.id=a.project_id
  where a.user_id is not null and p.user_id is not null and a.user_id<>p.user_id

  union all
  select 'studio_member_missing_user', count(*)::bigint
  from public.tgg_studio_project_members m left join auth.users u on u.id=m.user_id
  where u.id is null

  union all
  select 'conversation_member_missing_user', count(*)::bigint
  from public.tgg_conversation_members cm left join auth.users u on u.id=cm.user_id
  where u.id is null

  union all
  select 'message_sender_missing_user', count(*)::bigint
  from public.tgg_messages m left join auth.users u on u.id=m.sender_id
  where m.sender_id is not null and u.id is null

  union all
  select 'audiobook_chapter_user_mismatch', count(*)::bigint
  from public.tgg_audiobook_chapters c
  join public.tgg_audiobooks b on b.id=c.audiobook_id
  join public.artists a on a.id=b.artist_id
  where c.user_id is not null and a.user_id is not null and c.user_id<>a.user_id

  union all
  select 'membership_artist_tier_mismatch', count(*)::bigint
  from public.tgg_memberships m join public.tgg_membership_tiers t on t.id=m.tier_id
  where m.artist_id is not null and t.artist_id is not null and m.artist_id<>t.artist_id

  union all
  select 'vault_asset_user_mismatch_creative_project', count(*)::bigint
  from public.tgg_media_vault_assets v join public.tgg_creative_projects p on p.id=v.project_id
  where v.user_id is not null and p.user_id is not null and v.user_id<>p.user_id

  union all
  select 'live_replay_creator_mismatch_stream', count(*)::bigint
  from public.tgg_live_replays r join public.live_streams l on l.id=r.stream_id
  where r.creator_id is not null and l.creator_id is not null and r.creator_id<>l.creator_id
),
fk_targets(child_table,child_col,parent_table,parent_col) as (
  values
  ('tracks','mixtape_id','mixtapes','id'),
  ('tgg_studio_assets','project_id','tgg_studio_projects','id'),
  ('tgg_studio_project_members','project_id','tgg_studio_projects','id'),
  ('tgg_messages','conversation_id','tgg_conversations','id'),
  ('tgg_conversation_members','conversation_id','tgg_conversations','id'),
  ('tgg_live_replays','stream_id','live_streams','id'),
  ('tgg_audiobook_chapters','audiobook_id','tgg_audiobooks','id'),
  ('tgg_game_sessions','game_id','tgg_games','id'),
  ('tgg_memberships','tier_id','tgg_membership_tiers','id'),
  ('tgg_media_vault_assets','project_id','tgg_creative_projects','id')
),
fk_state as (
  select
    t.*,
    exists(
      select 1
      from pg_constraint con
      join pg_class c on c.oid=con.conrelid
      join pg_namespace n on n.oid=c.relnamespace
      join pg_class pc on pc.oid=con.confrelid
      join pg_namespace pn on pn.oid=pc.relnamespace
      join unnest(con.conkey) with ordinality ck(attnum,ord) on true
      join unnest(con.confkey) with ordinality fk(attnum,ord) on fk.ord=ck.ord
      join pg_attribute a on a.attrelid=c.oid and a.attnum=ck.attnum
      join pg_attribute pa on pa.attrelid=pc.oid and pa.attnum=fk.attnum
      where con.contype='f'
        and con.convalidated
        and n.nspname='public'
        and pn.nspname='public'
        and c.relname=t.child_table
        and a.attname=t.child_col
        and pc.relname=t.parent_table
        and pa.attname=t.parent_col
    ) ready
  from fk_targets t
),
o as (
  select sum(n) total, jsonb_object_agg(key,n order by key) counts from orphan_checks
),
m as (
  select sum(n) total, jsonb_object_agg(key,n order by key) counts from mismatch_checks
),
f as (
  select
    count(*) total,
    count(*) filter(where ready) ready,
    coalesce(jsonb_agg(jsonb_build_object(
      'child',child_table||'.'||child_col,
      'parent',parent_table||'.'||parent_col
    ) order by child_table) filter(where not ready),'[]'::jsonb) missing
  from fk_state
)
select jsonb_build_object(
  'ok',coalesce(o.total,0)=0 and coalesce(m.total,0)=0 and f.ready=f.total,
  'version','CREATOR-DATA-INTEGRITY-1.1',
  'orphans',jsonb_build_object('total',coalesce(o.total,0),'checks',10,'counts',o.counts),
  'ownership_mismatches',jsonb_build_object('total',coalesce(m.total,0),'checks',9,'counts',m.counts),
  'foreign_keys',jsonb_build_object('ready',f.ready,'total',f.total,'missing',f.missing),
  'generated_at',now()
)
from o cross join m cross join f;
$function$


