-- [40000000671] function public.tgg_creator_digest_preferences_get()
CREATE OR REPLACE FUNCTION public.tgg_creator_digest_preferences_get()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_row public.tgg_creator_digest_preferences;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  insert into public.tgg_creator_digest_preferences(user_id)
  values(v_uid)
  on conflict(user_id) do nothing;

  select * into v_row
  from public.tgg_creator_digest_preferences
  where user_id=v_uid;

  return jsonb_build_object(
    'ok',true,
    'digest_enabled',v_row.digest_enabled,
    'action_alerts_enabled',v_row.action_alerts_enabled,
    'opportunity_alerts_enabled',v_row.opportunity_alerts_enabled,
    'minimum_priority',v_row.minimum_priority,
    'digest_hour_utc',v_row.digest_hour_utc,
    'updated_at',v_row.updated_at
  );
end
$function$


-- [40000000672] function public.tgg_creator_digest_preferences_update(p_digest_enabled boolean, p_action_alerts_enabled boolean, p_opportunity_alerts_enabled boolean, p_minimum_priority integer)
CREATE OR REPLACE FUNCTION public.tgg_creator_digest_preferences_update(p_digest_enabled boolean, p_action_alerts_enabled boolean, p_opportunity_alerts_enabled boolean, p_minimum_priority integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_priority integer:=greatest(0,least(coalesce(p_minimum_priority,70),100));
  v_row public.tgg_creator_digest_preferences;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  insert into public.tgg_creator_digest_preferences(
    user_id,digest_enabled,action_alerts_enabled,opportunity_alerts_enabled,minimum_priority,updated_at
  )
  values(
    v_uid,coalesce(p_digest_enabled,true),coalesce(p_action_alerts_enabled,true),
    coalesce(p_opportunity_alerts_enabled,true),v_priority,now()
  )
  on conflict(user_id) do update
  set digest_enabled=excluded.digest_enabled,
      action_alerts_enabled=excluded.action_alerts_enabled,
      opportunity_alerts_enabled=excluded.opportunity_alerts_enabled,
      minimum_priority=excluded.minimum_priority,
      updated_at=now()
  returning * into v_row;

  return jsonb_build_object(
    'ok',true,
    'digest_enabled',v_row.digest_enabled,
    'action_alerts_enabled',v_row.action_alerts_enabled,
    'opportunity_alerts_enabled',v_row.opportunity_alerts_enabled,
    'minimum_priority',v_row.minimum_priority,
    'updated_at',v_row.updated_at
  );
end
$function$


-- [40000000673] function public.tgg_creator_digest_schedule_update(p_digest_hour_utc integer)
CREATE OR REPLACE FUNCTION public.tgg_creator_digest_schedule_update(p_digest_hour_utc integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_hour integer:=greatest(0,least(coalesce(p_digest_hour_utc,14),23));
  v_row public.tgg_creator_digest_preferences;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  insert into public.tgg_creator_digest_preferences(user_id,digest_hour_utc,updated_at)
  values(v_uid,v_hour,now())
  on conflict(user_id) do update
  set digest_hour_utc=excluded.digest_hour_utc,
      updated_at=now()
  returning * into v_row;

  return jsonb_build_object(
    'ok',true,
    'digest_hour_utc',v_row.digest_hour_utc,
    'digest_enabled',v_row.digest_enabled,
    'minimum_priority',v_row.minimum_priority,
    'updated_at',v_row.updated_at
  );
end
$function$


-- [40000000674] function public.tgg_creator_distribution_activation_summary()
CREATE OR REPLACE FUNCTION public.tgg_creator_distribution_activation_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_items jsonb;
  v_candidates integer:=0;
  v_package_ready integer:=0;
  v_submit_ready integer:=0;
  v_runtime_ready boolean:=false;
  v_credential_present boolean:=false;
  v_endpoint_reachable boolean:=false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select
    coalesce(c.enabled,false)
    and coalesce(c.endpoint_configured,false)
    and c.mode='production'
  into v_runtime_ready
  from public.tgg_provider_runtime_config c
  where c.provider_key='distribution.provider';

  select exists(
    select 1
    from jsonb_array_elements(coalesce(public.tgg_provider_secret_status()->'providers','[]'::jsonb)) x
    where x->>'provider_key'='distribution.provider'
      and x->>'status' in ('stored','verified')
  ) into v_credential_present;

  select exists(
    select 1
    from jsonb_array_elements(coalesce(public.tgg_provider_activation_staging_status()->'items','[]'::jsonb)) x
    where x->>'provider_key'='distribution.provider'
      and x->>'status'='verified'
  ) into v_endpoint_reachable;

  with owned as (
    select m.id,m.title,m.status,m.release_date,
           public.tgg_creator_distribution_readiness(m.id) as readiness
    from public.mixtapes m
    join public.artists a on a.id=m.artist_id
    where a.user_id=v_uid
  )
  select
    coalesce(jsonb_agg(
      jsonb_build_object(
        'release_id',id,
        'title',title,
        'status',status,
        'release_date',release_date,
        'distribution_candidate',coalesce((readiness->>'distribution_candidate')::boolean,false),
        'technical_preflight_ready',coalesce((readiness->>'distribution_candidate')::boolean,false),
        'package_ready',coalesce((readiness->>'package_ready')::boolean,false),
        'submit_ready',coalesce((readiness->>'submit_ready')::boolean,false),
        'provider_ready',coalesce((readiness->>'provider_ready')::boolean,false),
        'candidate_reason',readiness->>'candidate_reason',
        'provider_blocker',readiness->>'provider_blocker',
        'blockers',coalesce(readiness->'blockers','[]'::jsonb),
        'warnings',coalesce(readiness->'warnings','[]'::jsonb),
        'counts',coalesce(readiness->'counts','{}'::jsonb),
        'metadata',coalesce(readiness->'metadata','{}'::jsonb)
      )
      order by coalesce(release_date,'epoch'::timestamptz) desc
    ),'[]'::jsonb),
    count(*) filter(where coalesce((readiness->>'distribution_candidate')::boolean,false)),
    count(*) filter(where coalesce((readiness->>'package_ready')::boolean,false)),
    count(*) filter(where coalesce((readiness->>'submit_ready')::boolean,false))
  into v_items,v_candidates,v_package_ready,v_submit_ready
  from owned;

  return jsonb_build_object(
    'ok',true,
    'version','DISTRIBUTION-ACTIVATION-SUMMARY-1.2',
    'candidate_releases',v_candidates,
    'package_ready_releases',v_package_ready,
    'submit_ready_releases',v_submit_ready,
    'technical_preflight_available',true,
    'technical_preflight_rpc','tgg_distribution_preflight_bundle',
    'provider_endpoint_reachable',v_endpoint_reachable,
    'provider_credential_present',v_credential_present,
    'provider_connection_ready',
      v_runtime_ready and v_credential_present,
    'items',v_items,
    'generated_at',now()
  );
end
$function$


-- [40000000675] function public.tgg_creator_distribution_bundle(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_creator_distribution_bundle(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_limit integer:=greatest(1,least(coalesce(p_limit,50),100));
  v_provider jsonb;
  v_credential_present boolean:=false;
  v_endpoint_reachable boolean:=false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select jsonb_build_object(
    'provider_key',provider_key,
    'enabled',enabled,
    'mode',mode,
    'endpoint_configured',endpoint_configured,
    'disabled_reason',disabled_reason
  )
  into v_provider
  from public.tgg_provider_runtime_config
  where provider_key='distribution.provider';

  select exists(
    select 1
    from jsonb_array_elements(coalesce(public.tgg_provider_secret_status()->'providers','[]'::jsonb)) x
    where x->>'provider_key'='distribution.provider'
      and x->>'status' in ('stored','verified')
  ) into v_credential_present;

  select exists(
    select 1
    from jsonb_array_elements(coalesce(public.tgg_provider_activation_staging_status()->'items','[]'::jsonb)) x
    where x->>'provider_key'='distribution.provider'
      and x->>'status'='verified'
  ) into v_endpoint_reachable;

  return jsonb_build_object(
    'ok',true,
    'version','DISTRIBUTION-ONE-FINAL-1.2',
    'package_pipeline_ready',true,
    'prepare_without_provider',true,
    'technical_preflight_available',true,
    'technical_preflight_rpc','tgg_distribution_preflight_bundle',
    'provider_endpoint_reachable',v_endpoint_reachable,
    'provider_credential_present',v_credential_present,
    'delivery_provider_ready',
      coalesce((v_provider->>'enabled')::boolean,false)
      and coalesce((v_provider->>'endpoint_configured')::boolean,false)
      and coalesce(v_provider->>'mode','')='production'
      and v_credential_present,
    'provider',
      coalesce(
        v_provider,
        jsonb_build_object(
          'enabled',false,
          'endpoint_configured',false,
          'disabled_reason','provider_endpoint_missing'
        )
      ),
    'releases',coalesce((
      select jsonb_agg(public.tgg_creator_distribution_readiness(x.id) order by x.created_at desc)
      from (
        select m.id,m.created_at
        from public.mixtapes m
        join public.artists a on a.id=m.artist_id
        where a.user_id=v_uid
        order by m.created_at desc
        limit v_limit
      ) x
    ),'[]'::jsonb),
    'requests',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',r.id,
        'release_id',r.release_id,
        'provider_key',r.provider_key,
        'status',r.status,
        'external_reference',r.external_reference,
        'last_error',r.last_error,
        'created_at',r.created_at,
        'updated_at',r.updated_at
      ) order by r.created_at desc)
      from (
        select *
        from public.tgg_distribution_requests
        where owner_user_id=v_uid
        order by created_at desc
        limit 50
      ) r
    ),'[]'::jsonb),
    'generated_at',now()
  );
end
$function$


-- [40000000676] function public.tgg_creator_distribution_package(p_release_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_creator_distribution_package(p_release_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();r jsonb;m public.mixtapes;a public.artists;d public.tgg_distribution_release_metadata;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  r:=public.tgg_creator_distribution_readiness(p_release_id);
  if not coalesce((r->>'package_ready')::boolean,false) then
    return jsonb_build_object('ok',false,'error','distribution_package_not_ready','readiness',r);
  end if;
  select m0.* into m from public.mixtapes m0 join public.artists a0 on a0.id=m0.artist_id where m0.id=p_release_id and a0.user_id=v_uid;
  select * into a from public.artists where id=m.artist_id;
  select * into d from public.tgg_distribution_release_metadata where release_id=m.id and owner_user_id=v_uid;

  return jsonb_build_object(
    'ok',true,
    'version','DISTRIBUTION-PACKAGE-ONE-FINAL-1.0',
    'package',jsonb_build_object(
      'release',jsonb_build_object(
        'id',m.id,'title',m.title,'artist',a.stage_name,'artist_id',a.id,'genre',m.genre,
        'description',m.description,'release_date',m.release_date,'explicit',coalesce(m.explicit,'Not Explicit'),
        'cover_url',m.cover_url,'cover_path',m.cover_path,'slug',m.slug
      ),
      'rights',jsonb_build_object(
        'label_name',d.label_name,'copyright_line',d.copyright_line,'publishing_line',d.publishing_line,
        'primary_language',d.primary_language,'territories',d.territories,'rights_confirmed',d.rights_confirmed,
        'rights_confirmed_at',d.rights_confirmed_at
      ),
      'tracks',coalesce((
        select jsonb_agg(jsonb_build_object(
          'id',t.id,'track_number',t.track_number,'title',t.title,'featured_artist',t.featured_artist,
          'duration_seconds',t.duration_seconds,'audio_path',t.audio_path,'audio_url',t.audio_url
        ) order by t.track_number)
        from public.tracks t where t.mixtape_id=m.id
      ),'[]'::jsonb),
      'credits',coalesce((
        select jsonb_agg(jsonb_build_object(
          'track_id',c.track_id,'person_name',c.person_name,'role',c.role,'tgg_user_id',c.tgg_user_id,'notes',c.notes
        ) order by c.created_at)
        from public.tgg_release_credits c where c.release_id=m.id and c.owner_user_id=v_uid
      ),'[]'::jsonb),
      'clearances',coalesce((
        select jsonb_agg(jsonb_build_object(
          'item_type',c.item_type,'description',c.description,'source_name',c.source_name,
          'permission_status',c.permission_status,'proof_url',c.proof_url,'notes',c.notes
        ) order by c.created_at)
        from public.tgg_clearance_items c where c.release_id=m.id and c.owner_user_id=v_uid
      ),'[]'::jsonb),
      'source',jsonb_build_object('platform','Tru Go Getta','generated_at',now())
    ),
    'readiness',r
  );
end $function$


-- [40000000677] function public.tgg_creator_distribution_preflight_package(p_release_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_creator_distribution_preflight_package(p_release_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  r jsonb;
  m public.mixtapes;
  a public.artists;
  d public.tgg_distribution_release_metadata;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select m0.*
  into m
  from public.mixtapes m0
  join public.artists a0 on a0.id=m0.artist_id
  where m0.id=p_release_id
    and a0.user_id=v_uid;

  if m.id is null then
    raise exception 'RELEASE_NOT_FOUND_OR_NOT_OWNED' using errcode='42501';
  end if;

  select * into a from public.artists where id=m.artist_id;
  select * into d
  from public.tgg_distribution_release_metadata
  where release_id=m.id
    and owner_user_id=v_uid;

  r:=public.tgg_creator_distribution_readiness(p_release_id);

  return jsonb_build_object(
    'ok',true,
    'version','DISTRIBUTION-PREFLIGHT-ONE-FINAL-1.0',
    'submission_ready',coalesce((r->>'package_ready')::boolean,false),
    'legal_metadata_complete',
      coalesce(d.label_name,'')<>''
      and coalesce(d.copyright_line,'')<>''
      and coalesce(d.publishing_line,'')<>''
      and jsonb_array_length(coalesce(d.territories,'[]'::jsonb))>0
      and coalesce(d.rights_confirmed,false),
    'preflight',jsonb_build_object(
      'release',jsonb_build_object(
        'id',m.id,
        'title',m.title,
        'artist',a.stage_name,
        'artist_id',a.id,
        'genre',m.genre,
        'description',m.description,
        'release_date',m.release_date,
        'explicit',coalesce(m.explicit,'Not Explicit'),
        'cover_url',m.cover_url,
        'cover_path',m.cover_path,
        'slug',m.slug
      ),
      'rights',jsonb_build_object(
        'label_name',d.label_name,
        'copyright_line',d.copyright_line,
        'publishing_line',d.publishing_line,
        'primary_language',coalesce(d.primary_language,'en'),
        'territories',coalesce(d.territories,'[]'::jsonb),
        'rights_confirmed',coalesce(d.rights_confirmed,false),
        'rights_confirmed_at',d.rights_confirmed_at,
        'owner_input_required',true
      ),
      'tracks',coalesce((
        select jsonb_agg(jsonb_build_object(
          'id',t.id,
          'track_number',t.track_number,
          'title',t.title,
          'featured_artist',t.featured_artist,
          'duration_seconds',t.duration_seconds,
          'audio_path',t.audio_path,
          'audio_url',t.audio_url,
          'technical_audio_ready',
            nullif(btrim(coalesce(t.audio_path,'')),'') is not null
            and coalesce(t.duration_seconds,0)>0
        ) order by t.track_number)
        from public.tracks t
        where t.mixtape_id=m.id
      ),'[]'::jsonb),
      'credits',coalesce((
        select jsonb_agg(jsonb_build_object(
          'track_id',c.track_id,
          'person_name',c.person_name,
          'role',c.role,
          'tgg_user_id',c.tgg_user_id,
          'notes',c.notes
        ) order by c.created_at)
        from public.tgg_release_credits c
        where c.release_id=m.id
          and c.owner_user_id=v_uid
      ),'[]'::jsonb),
      'clearances',coalesce((
        select jsonb_agg(jsonb_build_object(
          'item_type',c.item_type,
          'description',c.description,
          'source_name',c.source_name,
          'permission_status',c.permission_status,
          'proof_url',c.proof_url,
          'notes',c.notes
        ) order by c.created_at)
        from public.tgg_clearance_items c
        where c.release_id=m.id
          and c.owner_user_id=v_uid
      ),'[]'::jsonb),
      'source',jsonb_build_object(
        'platform','Tru Go Getta',
        'generated_at',now(),
        'preflight_only',not coalesce((r->>'package_ready')::boolean,false)
      )
    ),
    'readiness',r,
    'next_action',
      case
        when coalesce((r->>'package_ready')::boolean,false)
          then 'Use tgg_creator_distribution_package for the final submission-ready package.'
        else 'Complete only the listed readiness blockers; technical media package is already prepared.'
      end
  );
end
$function$


-- [40000000678] function public.tgg_creator_distribution_readiness(p_release_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_creator_distribution_readiness(p_release_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  m public.mixtapes;
  a public.artists;
  d public.tgg_distribution_release_metadata;
  v_tracks integer:=0;
  v_deliverable_tracks integer:=0;
  v_missing_audio integer:=0;
  v_undeliverable_audio integer:=0;
  v_missing_duration integer:=0;
  v_duplicate_numbers integer:=0;
  v_duplicate_master_tracks integer:=0;
  v_credits integer:=0;
  v_unresolved integer:=0;
  v_blockers jsonb:='[]'::jsonb;
  v_warnings jsonb:='[]'::jsonb;
  v_provider_ready boolean:=false;
  v_provider_endpoint_ready boolean:=false;
  v_provider_credential_present boolean:=false;
  v_distribution_candidate boolean:=false;
  v_reuse_status jsonb:='{}'::jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select m0.* into m
  from public.mixtapes m0
  join public.artists a0 on a0.id=m0.artist_id
  where m0.id=p_release_id and a0.user_id=v_uid;

  if m.id is null then
    raise exception 'RELEASE_NOT_FOUND_OR_NOT_OWNED';
  end if;

  select * into a from public.artists where id=m.artist_id;

  select * into d
  from public.tgg_distribution_release_metadata
  where release_id=m.id and owner_user_id=v_uid;

  v_reuse_status:=public.tgg_distribution_master_reuse_status();

  select
    count(*),
    count(*) filter(
      where nullif(btrim(coalesce(t.audio_path,'')),'') is not null
         or (
           coalesce(t.audio_url,'') ~* '^https://'
           and regexp_replace(split_part(t.audio_url,'?',1),'#.*$','') ~* '\.(mp3|wav|flac|m4a|aac|ogg)$'
         )
    ),
    count(*) filter(
      where nullif(btrim(coalesce(t.audio_path,t.audio_url,'')),'') is null
    ),
    count(*) filter(
      where nullif(btrim(coalesce(t.audio_path,t.audio_url,'')),'') is not null
        and not (
          nullif(btrim(coalesce(t.audio_path,'')),'') is not null
          or (
            coalesce(t.audio_url,'') ~* '^https://'
            and regexp_replace(split_part(t.audio_url,'?',1),'#.*$','') ~* '\.(mp3|wav|flac|m4a|aac|ogg)$'
          )
        )
    ),
    count(*) filter(
      where (
        nullif(btrim(coalesce(t.audio_path,'')),'') is not null
        or (
          coalesce(t.audio_url,'') ~* '^https://'
          and regexp_replace(split_part(t.audio_url,'?',1),'#.*$','') ~* '\.(mp3|wav|flac|m4a|aac|ogg)$'
        )
      )
      and coalesce(t.duration_seconds,0)<=0
    )
  into
    v_tracks,v_deliverable_tracks,v_missing_audio,v_undeliverable_audio,v_missing_duration
  from public.tracks t
  where t.mixtape_id=m.id;

  -- Only unconfirmed cross-release master reuse is a blocker.
  select count(*)
  into v_duplicate_master_tracks
  from public.tracks t
  where t.mixtape_id=m.id
    and nullif(btrim(coalesce(t.audio_path,'')),'') is not null
    and exists(
      select 1
      from public.tracks t2
      join public.mixtapes m2 on m2.id=t2.mixtape_id
      where t2.mixtape_id<>m.id
        and m2.status='published'::public.mixtape_status
        and nullif(btrim(coalesce(t2.audio_path,'')),'')=nullif(btrim(coalesce(t.audio_path,'')),'')
    )
    and not exists(
      select 1
      from jsonb_array_elements(coalesce(v_reuse_status->'groups','[]'::jsonb)) g
      where g->>'audio_path'=t.audio_path
        and coalesce((g->>'confirmed_intentional')::boolean,false)
    );

  v_distribution_candidate:=
    v_tracks>0
    and v_deliverable_tracks=v_tracks
    and v_duplicate_master_tracks=0;

  select count(*) into v_duplicate_numbers
  from (
    select track_number
    from public.tracks
    where mixtape_id=m.id
    group by track_number
    having count(*)>1
  ) q;

  select count(*) into v_credits
  from public.tgg_release_credits c
  where c.release_id=m.id and c.owner_user_id=v_uid;

  select count(*) into v_unresolved
  from public.tgg_clearance_items c
  where c.release_id=m.id and c.owner_user_id=v_uid
    and lower(coalesce(c.permission_status,'needs_review'))
      not in ('cleared','approved','licensed','not_required');

  if m.status::text<>'published' then v_blockers:=v_blockers||jsonb_build_array('release_not_published'); end if;
  if nullif(btrim(coalesce(m.title,'')),'') is null then v_blockers:=v_blockers||jsonb_build_array('title_missing'); end if;
  if nullif(btrim(coalesce(a.stage_name,'')),'') is null then v_blockers:=v_blockers||jsonb_build_array('artist_name_missing'); end if;
  if nullif(btrim(coalesce(m.genre,'')),'') is null then v_blockers:=v_blockers||jsonb_build_array('genre_missing'); end if;
  if nullif(btrim(coalesce(m.cover_url,m.cover_path,'')),'') is null then v_blockers:=v_blockers||jsonb_build_array('cover_missing'); end if;
  if m.release_date is null then v_blockers:=v_blockers||jsonb_build_array('release_date_missing'); end if;
  if v_tracks<1 then v_blockers:=v_blockers||jsonb_build_array('tracks_missing'); end if;
  if v_missing_audio>0 then v_blockers:=v_blockers||jsonb_build_array('track_audio_missing'); end if;
  if v_undeliverable_audio>0 then v_blockers:=v_blockers||jsonb_build_array('track_audio_not_distribution_master'); end if;
  if v_duplicate_numbers>0 then v_blockers:=v_blockers||jsonb_build_array('duplicate_track_numbers'); end if;
  if v_duplicate_master_tracks>0 then
    v_blockers:=v_blockers||jsonb_build_array('master_audio_reused_across_published_releases');
  end if;

  if v_distribution_candidate then
    if d.release_id is null then v_blockers:=v_blockers||jsonb_build_array('distribution_metadata_missing'); end if;
    if d.release_id is not null and nullif(btrim(coalesce(d.label_name,'')),'') is null then v_blockers:=v_blockers||jsonb_build_array('label_name_missing'); end if;
    if d.release_id is not null and not d.rights_confirmed then v_blockers:=v_blockers||jsonb_build_array('distribution_rights_not_confirmed'); end if;
    if d.release_id is not null and nullif(btrim(coalesce(d.copyright_line,'')),'') is null then v_blockers:=v_blockers||jsonb_build_array('copyright_line_missing'); end if;
    if d.release_id is not null and nullif(btrim(coalesce(d.publishing_line,'')),'') is null then v_blockers:=v_blockers||jsonb_build_array('publishing_line_missing'); end if;
    if d.release_id is not null and coalesce(jsonb_array_length(d.territories),0)=0 then v_blockers:=v_blockers||jsonb_build_array('territories_missing'); end if;
    if v_unresolved>0 then v_blockers:=v_blockers||jsonb_build_array('clearance_items_unresolved'); end if;
    if v_missing_duration>0 then v_warnings:=v_warnings||jsonb_build_array('track_duration_missing'); end if;
  end if;

  if v_credits=0 then v_warnings:=v_warnings||jsonb_build_array('release_credits_empty'); end if;
  if nullif(btrim(coalesce(m.description,'')),'') is null then v_warnings:=v_warnings||jsonb_build_array('description_missing'); end if;

  select coalesce(enabled,false) and coalesce(endpoint_configured,false) and mode='production'
  into v_provider_ready
  from public.tgg_provider_runtime_config
  where provider_key='distribution.provider';

  select exists(
    select 1
    from jsonb_array_elements(
      coalesce(public.tgg_provider_activation_staging_status()->'items','[]'::jsonb)
    ) x
    where x->>'provider_key'='distribution.provider'
      and x->>'status'='verified'
  )
  into v_provider_endpoint_ready;

  select exists(
    select 1
    from jsonb_array_elements(
      coalesce(public.tgg_provider_secret_status()->'providers','[]'::jsonb)
    ) x
    where x->>'provider_key'='distribution.provider'
      and x->>'status' in ('stored','verified','runtime_verified')
  )
  into v_provider_credential_present;

  v_provider_ready:=coalesce(v_provider_ready,false)
    and v_provider_credential_present;

  return jsonb_build_object(
    'ok',true,
    'version','DISTRIBUTION-READINESS-ONE-FINAL-1.5',
    'release',jsonb_build_object(
      'id',m.id,'title',m.title,'status',m.status,'genre',m.genre,'cover_url',m.cover_url,
      'release_date',m.release_date,'explicit',m.explicit,'artist_id',a.id,'stage_name',a.stage_name
    ),
    'distribution_candidate',v_distribution_candidate,
    'candidate_reason',case
      when v_tracks<1 then 'tracks_missing'
      when v_deliverable_tracks<>v_tracks then 'distribution_master_audio_required'
      when v_duplicate_master_tracks>0 then 'duplicate_master_reference_requires_review'
      else 'deliverable_audio_ready'
    end,
    'metadata',case when d.release_id is null then null else jsonb_build_object(
      'label_name',d.label_name,'copyright_line',d.copyright_line,'publishing_line',d.publishing_line,
      'primary_language',d.primary_language,'territories',d.territories,'rights_confirmed',d.rights_confirmed,
      'rights_confirmed_at',d.rights_confirmed_at,'notes',d.notes
    ) end,
    'counts',jsonb_build_object(
      'tracks',v_tracks,
      'deliverable_tracks',v_deliverable_tracks,
      'missing_audio',v_missing_audio,
      'undeliverable_audio',v_undeliverable_audio,
      'missing_duration',v_missing_duration,
      'duplicate_master_tracks',v_duplicate_master_tracks,
      'credits',v_credits,
      'unresolved_clearances',v_unresolved
    ),
    'blockers',v_blockers,
    'warnings',v_warnings,
    'package_ready',v_distribution_candidate and jsonb_array_length(v_blockers)=0,
    'provider_ready',coalesce(v_provider_ready,false),
    'provider_endpoint_reachable',v_provider_endpoint_ready,
    'provider_credential_present',v_provider_credential_present,
    'submit_ready',
      v_distribution_candidate
      and jsonb_array_length(v_blockers)=0
      and coalesce(v_provider_ready,false),
    'provider_blocker',
      case
        when coalesce(v_provider_ready,false) then null
        when not v_provider_endpoint_ready then 'provider_endpoint_missing'
        when not v_provider_credential_present then 'provider_credential_required'
        else 'provider_runtime_not_enabled'
      end,
    'generated_at',now()
  );
end
$function$


-- [40000000679] function public.tgg_creator_epk_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_epk_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist public.artists;
  v_settings public.tgg_epk_settings;
  v_press jsonb;
  v_releases jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist.id is null then
    return jsonb_build_object('ok',true,'version','CREATOR-EPK-1.0','has_artist_profile',false,'generated_at',now());
  end if;

  select * into v_settings
  from public.tgg_epk_settings
  where owner_user_id=v_uid
  limit 1;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',p.id,'item_type',p.item_type,'title',p.title,'publication',p.publication,
    'url',p.url,'published_at',p.published_at,'quote',p.quote,'is_featured',p.is_featured
  ) order by p.is_featured desc,p.published_at desc nulls last,p.created_at desc),'[]'::jsonb)
  into v_press
  from public.tgg_press_items p
  where p.owner_user_id=v_uid and p.artist_id=v_artist.id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'release_id',m.id,'title',m.title,'slug',m.slug,'cover_url',m.cover_url,
    'genre',m.genre,'release_date',m.release_date,
    'url',case when m.slug is null then null else
      'https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-shell?view=release&slug='||m.slug end
  ) order by coalesce(m.release_date,m.created_at) desc),'[]'::jsonb)
  into v_releases
  from public.mixtapes m
  where m.artist_id=v_artist.id and m.status='published';

  return jsonb_build_object(
    'ok',true,'version','CREATOR-EPK-1.0','has_artist_profile',true,
    'artist',jsonb_build_object(
      'artist_id',v_artist.id,'stage_name',v_artist.stage_name,'bio',v_artist.bio,
      'avatar_url',v_artist.avatar_url,'website',v_artist.website,
      'instagram',v_artist.instagram,'youtube',v_artist.youtube,'spotify',v_artist.spotify
    ),
    'settings',case when v_settings.owner_user_id is null then null else jsonb_build_object(
      'headline',v_settings.headline,'short_bio',v_settings.short_bio,'location',v_settings.location,
      'highlights',v_settings.highlights,'public_slug',v_settings.public_slug,
      'is_public',v_settings.is_public,'updated_at',v_settings.updated_at
    ) end,
    'press_items',v_press,'releases',v_releases,'generated_at',now()
  );
end
$function$


-- [40000000680] function public.tgg_creator_epk_save(p_headline text, p_short_bio text, p_location text, p_highlights jsonb, p_public_slug text, p_is_public boolean)
CREATE OR REPLACE FUNCTION public.tgg_creator_epk_save(p_headline text, p_short_bio text, p_location text, p_highlights jsonb, p_public_slug text, p_is_public boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_slug text:=lower(btrim(coalesce(p_public_slug,'')));
  v_headline text:=nullif(btrim(coalesce(p_headline,'')),'');
  v_bio text:=nullif(btrim(coalesce(p_short_bio,'')),'');
  v_location text:=nullif(btrim(coalesce(p_location,'')),'');
  v_highlights jsonb:=coalesce(p_highlights,'[]'::jsonb);
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then raise exception 'ARTIST_PROFILE_REQUIRED' using errcode='P0002'; end if;
  if v_headline is not null and length(v_headline)>120 then raise exception 'HEADLINE_TOO_LONG' using errcode='22023'; end if;
  if v_bio is not null and length(v_bio)>1200 then raise exception 'SHORT_BIO_TOO_LONG' using errcode='22023'; end if;
  if v_location is not null and length(v_location)>120 then raise exception 'LOCATION_TOO_LONG' using errcode='22023'; end if;
  if jsonb_typeof(v_highlights)<>'array' then raise exception 'HIGHLIGHTS_MUST_BE_ARRAY' using errcode='22023'; end if;
  if jsonb_array_length(v_highlights)>12 then raise exception 'TOO_MANY_HIGHLIGHTS' using errcode='22023'; end if;

  if v_slug='' then
    v_slug:=null;
  elsif v_slug !~ '^[a-z0-9][a-z0-9-]{2,63}$' then
    raise exception 'EPK_SLUG_INVALID' using errcode='22023';
  end if;

  insert into public.tgg_epk_settings(
    owner_user_id,artist_id,headline,short_bio,location,highlights,public_slug,is_public,updated_at
  )
  values(v_uid,v_artist_id,v_headline,v_bio,v_location,v_highlights,v_slug,coalesce(p_is_public,false),now())
  on conflict(owner_user_id) do update
  set artist_id=excluded.artist_id,
      headline=excluded.headline,
      short_bio=excluded.short_bio,
      location=excluded.location,
      highlights=excluded.highlights,
      public_slug=excluded.public_slug,
      is_public=excluded.is_public,
      updated_at=now();

  return public.tgg_creator_epk_bundle();
end
$function$


-- [40000000681] function public.tgg_creator_expansion_control_center()
CREATE OR REPLACE FUNCTION public.tgg_creator_expansion_control_center()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_activation jsonb:=public.tgg_optional_upgrade_activation_health();
  v_optional jsonb:=public.tgg_external_optional_upgrades_final();
  v_external jsonb:=public.tgg_external_infrastructure_final_health();
  v_invite jsonb:=public.tgg_call_validation_invite_status();
  v_distribution jsonb:=public.tgg_creator_distribution_activation_summary();
  v_staging jsonb:=public.tgg_provider_activation_stage_status();
  v_master_reuse jsonb:=public.tgg_distribution_master_reuse_status();
  v_queue jsonb:=public.tgg_one_final_activation_queue();
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-EXPANSION-CONTROL-1.5',
    'status','activation_ready',
    'launch_blockers',public.tgg_external_blockers_final(),
    'optional_upgrades',v_optional,
    'activation_health',v_activation,
    'activation_queue',v_queue,
    'provider_staging',v_staging,
    'master_reuse',v_master_reuse,
    'providers',jsonb_build_object(
      'stripe',v_external->'stripe',
      'distribution',jsonb_build_object(
        'adapter_key','distribution.provider',
        'runtime_key','distribution.provider',
        'adapter_ready',coalesce((v_activation->'distribution'->>'adapter_ready')::boolean,false),
        'provider_connected',coalesce((v_external->'dsp_distribution'->>'ready')::boolean,false),
        'activation_state',case when coalesce((v_external->'dsp_distribution'->>'ready')::boolean,false) then 'active' else 'provider_connection_pending' end,
        'activation_summary',v_distribution,
        'package_preview_rpc','tgg_creator_distribution_package',
        'stage_rpc','tgg_provider_activation_stage'
      ),
      'broadcast',jsonb_build_object(
        'adapter_key','broadcast.sfu_turn',
        'runtime_key','broadcast.sfu_turn',
        'adapter_ready',coalesce((v_activation->'broadcast'->>'adapter_ready')::boolean,false),
        'control_plane_ready',coalesce((v_activation->'broadcast'->>'control_plane_ready')::boolean,false),
        'provider_connected',coalesce((v_external->'broadcast_engine'->>'ready')::boolean,false),
        'activation_state',case when coalesce((v_external->'broadcast_engine'->>'ready')::boolean,false) then 'active' else 'provider_connection_pending' end,
        'stage_rpc','tgg_provider_activation_stage'
      ),
      'call_validation',jsonb_build_object(
        'harness_ready',coalesce((v_activation->'call_validation'->>'harness_ready')::boolean,false),
        'room_creation_ready',coalesce((v_activation->'call_validation'->>'room_creation_ready')::boolean,false),
        'signal_exchange_ready',coalesce((v_activation->'call_validation'->>'signal_exchange_ready')::boolean,false),
        'validated',coalesce((v_external->'two_user_call'->>'validated')::boolean,false),
        'activation_state',case when coalesce((v_external->'two_user_call'->>'validated')::boolean,false) then 'validated' else 'second_device_pending' end,
        'invite',v_invite
      ),
      'account_hardening',jsonb_build_object(
        'leaked_password_protection_ready',coalesce((v_external->'leaked_password_protection'->>'ready')::boolean,false),
        'activation_state',case when coalesce((v_external->'leaked_password_protection'->>'ready')::boolean,false) then 'active' else 'account_setting_pending' end
      )
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000682] function public.tgg_creator_fan_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_fan_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select id into v_artist from public.artists where user_id=v_uid limit 1;
  if v_artist is null then raise exception 'ARTIST_PROFILE_REQUIRED'; end if;

  return jsonb_build_object(
    'ok',true,
    'version','FAN-CRM-ONE-FINAL-1.0',
    'artist_id',v_artist,
    'counts',jsonb_build_object(
      'followers',(select count(*) from public.artist_follows where artist_id=v_artist),
      'new_7d',(select count(*) from public.artist_follows where artist_id=v_artist and created_at>=now()-interval '7 days'),
      'new_30d',(select count(*) from public.artist_follows where artist_id=v_artist and created_at>=now()-interval '30 days')
    ),
    'recent_followers',coalesce((
      select jsonb_agg(jsonb_build_object(
        'followed_at',f.created_at,
        'creator_profile',case when a.id is null then null else jsonb_build_object(
          'artist_id',a.id,
          'stage_name',a.stage_name,
          'avatar_url',a.avatar_url,
          'profile_url','/p/public-artist-profile.html?artist_id='||a.id::text
        ) end
      ) order by f.created_at desc)
      from (
        select * from public.artist_follows
        where artist_id=v_artist
        order by created_at desc
        limit 100
      ) f
      left join public.artists a on a.user_id=f.user_id
    ),'[]'::jsonb),
    'generated_at',now()
  );
end $function$


-- [40000000683] function public.tgg_creator_fan_crm_bundle(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_creator_fan_crm_bundle(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_artist uuid;v_limit integer:=greatest(1,least(coalesce(p_limit,50),100));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select id into v_artist from public.artists where user_id=v_uid limit 1;
  if v_artist is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

  return jsonb_build_object(
    'ok',true,
    'version','FAN-CRM-ONE-FINAL-1.0',
    'artist_id',v_artist,
    'counts',jsonb_build_object(
      'followers',(select count(*) from public.artist_follows where artist_id=v_artist),
      'new_7d',(select count(*) from public.artist_follows where artist_id=v_artist and created_at>=now()-interval '7 days'),
      'new_30d',(select count(*) from public.artist_follows where artist_id=v_artist and created_at>=now()-interval '30 days')
    ),
    'recent_followers',coalesce((
      select jsonb_agg(jsonb_build_object(
        'followed_at',f.created_at,
        'display_name',coalesce(fa.stage_name,'TGG Fan'),
        'avatar_url',fa.avatar_url,
        'is_creator',fa.id is not null
      ) order by f.created_at desc)
      from (
        select * from public.artist_follows where artist_id=v_artist order by created_at desc limit v_limit
      ) f
      left join public.artists fa on fa.user_id=f.user_id
    ),'[]'::jsonb),
    'privacy',jsonb_build_object(
      'emails_exposed',false,
      'raw_fan_ids_exposed',false,
      'creator_names_only_when_public_artist_profile_exists',true
    ),
    'generated_at',now()
  );
end $function$


-- [40000000684] function public.tgg_creator_fan_crm_dashboard(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_creator_fan_crm_dashboard(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_artist uuid;v_limit integer:=greatest(1,least(coalesce(p_limit,100),200));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select id into v_artist from public.artists where user_id=v_uid order by created_at limit 1;
  if v_artist is null then raise exception 'ARTIST_PROFILE_REQUIRED'; end if;

  return jsonb_build_object(
    'ok',true,'version','FAN-CRM-ONE-FINAL-1.2','artist_id',v_artist,
    'summary',coalesce((
      select to_jsonb(s)-'creator_user_id'
      from public.tgg_creator_fan_intelligence_summary s
      where s.creator_user_id=v_uid and s.artist_id=v_artist limit 1
    ),'{}'::jsonb),
    'counts',jsonb_build_object(
      'followers',(select count(*) from public.artist_follows f where f.artist_id=v_artist),
      'crm_fans',(select count(*) from public.tgg_fan_crm c where c.creator_user_id=v_uid and c.artist_id=v_artist and c.segment<>'unfollowed'),
      'active_members',(select count(*) from public.tgg_memberships m where m.artist_id=v_artist and m.status='active'),
      'paid_supporters',(select count(distinct s.fan_user_id) from public.tgg_support_transactions s where s.artist_id=v_artist and s.status='paid'),
      'new_followers_7d',(select count(*) from public.artist_follows f where f.artist_id=v_artist and f.created_at>=now()-interval '7 days'),
      'new_followers_30d',(select count(*) from public.artist_follows f where f.artist_id=v_artist and f.created_at>=now()-interval '30 days')
    ),
    'revenue',jsonb_build_object(
      'lifetime_paid_cents',coalesce((select sum(s.amount_cents) from public.tgg_support_transactions s where s.artist_id=v_artist and s.status='paid'),0),
      'platform_fee_cents',coalesce((select sum(s.platform_fee_cents) from public.tgg_support_transactions s where s.artist_id=v_artist and s.status='paid'),0),
      'creator_net_cents',coalesce((select sum(s.amount_cents-s.platform_fee_cents) from public.tgg_support_transactions s where s.artist_id=v_artist and s.status='paid'),0)
    ),
    'fans',coalesce((
      select jsonb_agg(jsonb_build_object(
        'crm_id',c.id,'fan_user_id',c.fan_user_id,
        'fan_artist_id',(select a.id from public.artists a where a.user_id=c.fan_user_id limit 1),
        'display_name',coalesce((select a.stage_name from public.artists a where a.user_id=c.fan_user_id limit 1),'TGG Fan'),
        'avatar_url',(select a.avatar_url from public.artists a where a.user_id=c.fan_user_id limit 1),
        'can_message',exists(select 1 from public.artists a where a.user_id=c.fan_user_id),
        'following',exists(select 1 from public.artist_follows f where f.artist_id=v_artist and f.user_id=c.fan_user_id),
        'active_member',exists(select 1 from public.tgg_memberships m where m.artist_id=v_artist and m.fan_user_id=c.fan_user_id and m.status='active'),
        'membership_status',(select m.status from public.tgg_memberships m where m.artist_id=v_artist and m.fan_user_id=c.fan_user_id order by m.updated_at desc limit 1),
        'lifetime_paid_cents',coalesce((select sum(s.amount_cents) from public.tgg_support_transactions s where s.artist_id=v_artist and s.fan_user_id=c.fan_user_id and s.status='paid'),0),
        'segment',c.segment,'tags',c.tags,
        'private_notes',c.private_notes,'last_contacted_at',c.last_contacted_at,
        'engagement_score',coalesce(i.engagement_score,0),
        'recency_score',coalesce(i.recency_score,0),
        'loyalty_score',coalesce(i.loyalty_score,0),
        'fan_state',coalesce(i.fan_state,c.segment),
        'recommended_action',i.recommended_action,'last_seen_at',i.last_seen_at,
        'supporter',coalesce(j.supporter,false),'journey_stage',j.journey_stage,
        'streams_count',coalesce(j.streams_count,0),'saves_count',coalesce(j.saves_count,0),
        'comments_count',coalesce(j.comments_count,0),'events_count',coalesce(j.events_count,0),
        'rooms_count',coalesce(j.rooms_count,0),
        'profile_url',case when exists(select 1 from public.artists a where a.user_id=c.fan_user_id)
          then '/p/public-artist-profile.html?artist_id='||(select a.id from public.artists a where a.user_id=c.fan_user_id limit 1)::text
          else null end
      ) order by
        coalesce((select sum(s.amount_cents) from public.tgg_support_transactions s where s.artist_id=v_artist and s.fan_user_id=c.fan_user_id and s.status='paid'),0) desc,
        coalesce(i.engagement_score,0) desc,
        c.updated_at desc)
      from (
        select * from public.tgg_fan_crm
        where creator_user_id=v_uid and artist_id=v_artist
        order by updated_at desc limit v_limit
      ) c
      left join public.tgg_fan_intelligence_snapshots i
        on i.creator_user_id=c.creator_user_id and i.artist_id=c.artist_id and i.fan_user_id=c.fan_user_id
      left join public.tgg_fan_journey j
        on j.user_id=c.fan_user_id and j.artist_id=c.artist_id
    ),'[]'::jsonb),
    'actions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',q.id,'fan_user_id',q.source_id,'action_type',q.action_type,'title',q.title,
        'rationale',q.rationale,'priority',q.priority,'status',q.status,'due_at',q.due_at,
        'metadata',q.metadata,'created_at',q.created_at
      ) order by q.priority desc,q.created_at)
      from public.tgg_creator_action_queue q
      where q.owner_user_id=v_uid and q.artist_id=v_artist and q.source_type='fan_intelligence' and q.status='open'
    ),'[]'::jsonb),
    'generated_at',now()
  );
end $function$


-- [40000000685] function public.tgg_creator_fan_loyalty_tiers(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_creator_fan_loyalty_tiers(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist uuid;
  v_limit integer:=greatest(1,least(coalesce(p_limit,50),100));
  v_fans jsonb:='[]'::jsonb;
  v_fan bigint:=0;
  v_engaged bigint:=0;
  v_loyal bigint:=0;
  v_superfan bigint:=0;
  v_ambassador bigint:=0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist is null then
    raise exception 'ARTIST_PROFILE_REQUIRED';
  end if;

  with fan_base as (
    select
      c.fan_user_id,
      coalesce(i.engagement_score,0) as engagement_score,
      coalesce(i.recency_score,0) as recency_score,
      coalesce(i.loyalty_score,0) as loyalty_score,
      coalesce(i.fan_state,c.segment) as fan_state,
      i.recommended_action,
      i.last_seen_at,
      exists(
        select 1 from public.tgg_memberships m
        where m.artist_id=v_artist and m.fan_user_id=c.fan_user_id and m.status='active'
      ) as active_member,
      coalesce((
        select sum(s.amount_cents)
        from public.tgg_support_transactions s
        where s.artist_id=v_artist and s.fan_user_id=c.fan_user_id and s.status='paid'
      ),0) as lifetime_paid_cents,
      coalesce(j.streams_count,0) as streams_count,
      coalesce(j.saves_count,0) as saves_count,
      coalesce(j.comments_count,0) as comments_count,
      coalesce(j.events_count,0) as events_count,
      coalesce(j.rooms_count,0) as rooms_count,
      coalesce(j.supporter,false) as supporter,
      coalesce((select a.stage_name from public.artists a where a.user_id=c.fan_user_id limit 1),'TGG Fan') as display_name,
      (select a.avatar_url from public.artists a where a.user_id=c.fan_user_id limit 1) as avatar_url
    from public.tgg_fan_crm c
    left join public.tgg_fan_intelligence_snapshots i
      on i.creator_user_id=c.creator_user_id
     and i.artist_id=c.artist_id
     and i.fan_user_id=c.fan_user_id
    left join public.tgg_fan_journey j
      on j.user_id=c.fan_user_id and j.artist_id=c.artist_id
    where c.creator_user_id=v_uid
      and c.artist_id=v_artist
      and c.segment<>'unfollowed'
  ),
  classified as (
    select *,
      case
        when active_member or supporter or lifetime_paid_cents>0 or loyalty_score>=85 then 'ambassador'
        when loyalty_score>=70 or (engagement_score>=75 and recency_score>=60) then 'superfan'
        when loyalty_score>=50 or engagement_score>=55 then 'loyal'
        when loyalty_score>=25 or engagement_score>=25 then 'engaged'
        else 'fan'
      end as loyalty_tier,
      case
        when active_member or supporter or lifetime_paid_cents>0 or loyalty_score>=85 then 5
        when loyalty_score>=70 or (engagement_score>=75 and recency_score>=60) then 4
        when loyalty_score>=50 or engagement_score>=55 then 3
        when loyalty_score>=25 or engagement_score>=25 then 2
        else 1
      end as tier_rank
    from fan_base
  ),
  ranked as (
    select * from classified
    order by tier_rank desc,loyalty_score desc,engagement_score desc
  )
  select
    coalesce(count(*) filter(where loyalty_tier='fan'),0),
    coalesce(count(*) filter(where loyalty_tier='engaged'),0),
    coalesce(count(*) filter(where loyalty_tier='loyal'),0),
    coalesce(count(*) filter(where loyalty_tier='superfan'),0),
    coalesce(count(*) filter(where loyalty_tier='ambassador'),0),
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'display_name',r2.display_name,
        'avatar_url',r2.avatar_url,
        'tier',r2.loyalty_tier,
        'tier_rank',r2.tier_rank,
        'engagement_score',r2.engagement_score,
        'recency_score',r2.recency_score,
        'loyalty_score',r2.loyalty_score,
        'fan_state',r2.fan_state,
        'recommended_action',r2.recommended_action,
        'last_seen_at',r2.last_seen_at,
        'active_member',r2.active_member,
        'supporter',r2.supporter,
        'lifetime_paid_cents',r2.lifetime_paid_cents,
        'streams_count',r2.streams_count,
        'saves_count',r2.saves_count,
        'comments_count',r2.comments_count,
        'events_count',r2.events_count,
        'rooms_count',r2.rooms_count
      ) order by r2.tier_rank desc,r2.loyalty_score desc,r2.engagement_score desc)
      from (select * from ranked limit v_limit) r2
    ),'[]'::jsonb)
  into v_fan,v_engaged,v_loyal,v_superfan,v_ambassador,v_fans
  from ranked;

  return jsonb_build_object(
    'ok',true,
    'version','FAN-LOYALTY-TIERS-1.1',
    'artist_id',v_artist,
    'counts',jsonb_build_object(
      'fan',v_fan,
      'engaged',v_engaged,
      'loyal',v_loyal,
      'superfan',v_superfan,
      'ambassador',v_ambassador
    ),
    'fans',v_fans,
    'privacy',jsonb_build_object(
      'emails_exposed',false,
      'raw_fan_ids_exposed',false,
      'creator_owned_relationship_data_only',true
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000686] function public.tgg_creator_fan_summary()
CREATE OR REPLACE FUNCTION public.tgg_creator_fan_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist from public.artists where user_id=v_uid limit 1;
      if v_artist is null then raise exception 'ARTIST_PROFILE_REQUIRED'; end if;

      return jsonb_build_object(
        'ok',true,
        'version','FANS-ONE-FINAL-1.1',
        'artist_id',v_artist,
        'followers_total',(select count(*) from public.artist_follows f where f.artist_id=v_artist),
        'followers_7d',(select count(*) from public.artist_follows f where f.artist_id=v_artist and f.created_at>=now()-interval '7 days'),
        'followers_30d',(select count(*) from public.artist_follows f where f.artist_id=v_artist and f.created_at>=now()-interval '30 days'),
        'latest_follow_at',(select max(f.created_at) from public.artist_follows f where f.artist_id=v_artist),
        'profile_url','/p/public-artist-profile.html?artist_id='||v_artist::text||'&id='||v_artist::text,
        'directory_url','/p/artists.html',
        'generated_at',now()
      );
    end $function$


-- [40000000687] function public.tgg_creator_first_use_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_first_use_bundle()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with me as (
  select auth.uid() user_id
),
artist as (
  select id
  from public.artists
  where user_id=(select user_id from me)
  order by created_at
  limit 1
),
counts as (
  select
    (select count(*) from public.merch_products
      where user_id=(select user_id from me)
         or creator_id=(select id from artist)) as products,
    (select count(*) from public.tgg_membership_tiers
      where artist_id=(select id from artist)) as membership_tiers,
    (select count(*) from public.tgg_membership_tiers
      where artist_id=(select id from artist) and is_active=true) as active_membership_tiers,
    (select count(*) from public.tgg_audiobooks
      where artist_id=(select id from artist)) as audiobooks,
    (select count(*) from public.tgg_games
      where artist_id=(select id from artist)) as games,
    (select count(*) from public.mixtapes
      where user_id=(select user_id from me)
         or artist_id=(select id from artist)) as releases,
    (select count(*) from public.mixtapes
      where (user_id=(select user_id from me) or artist_id=(select id from artist))
        and status='published') as published_releases,
    (select count(*) from public.mixtapes
      where (user_id=(select user_id from me) or artist_id=(select id from artist))
        and status in ('draft','pending','changes_requested')) as unpublished_releases,
    (select count(*) from public.fan_library
      where fan_user_id=(select user_id from me)) as saved_releases,
    (select count(*) from public.tgg_creator_growth_activity
      where owner_user_id=(select user_id from me)
        and action_type in ('share_artist','share_release','share_referral')) as growth_shares
)
select jsonb_build_object(
  'ok',(select user_id from me) is not null,
  'version','CREATOR-FIRST-USE-1.2',
  'artist_id',(select id from artist),
  'counts',jsonb_build_object(
    'products',products,
    'membership_tiers',membership_tiers,
    'active_membership_tiers',active_membership_tiers,
    'audiobooks',audiobooks,
    'games',games,
    'releases',releases,
    'published_releases',published_releases,
    'unpublished_releases',unpublished_releases,
    'saved_releases',saved_releases,
    'growth_shares',growth_shares
  ),
  'needs',jsonb_build_object(
    'first_product',products=0,
    'first_membership_tier',membership_tiers=0,
    'membership_activation',membership_tiers>0 and active_membership_tiers=0,
    'first_audiobook',audiobooks=0,
    'first_game',games=0,
    'first_release',releases=0,
    'publish_release',releases>0 and published_releases=0,
    'first_share',published_releases>0 and growth_shares=0,
    'first_saved_release',saved_releases=0
  ),
  'creator_launch_progress',jsonb_build_object(
    'profile_ready',(select id from artist) is not null,
    'release_created',releases>0,
    'release_published',published_releases>0,
    'release_shared',growth_shares>0,
    'completed_steps',
      ((select id from artist) is not null)::int
      +(releases>0)::int
      +(published_releases>0)::int
      +(growth_shares>0)::int,
    'total_steps',4
  ),
  'generated_at',now()
)
from counts;
$function$


-- [40000000688] function public.tgg_creator_games_bundle(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_creator_games_bundle(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_limit integer:=greatest(1,least(coalesce(p_limit,100),200));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-GAMES-ONE-FINAL-1.0',
    'counts',jsonb_build_object(
      'games',(select count(*) from public.tgg_games where created_by=v_uid),
      'draft',(select count(*) from public.tgg_games where created_by=v_uid and status='draft'),
      'open',(select count(*) from public.tgg_games where created_by=v_uid and status='open'),
      'live',(select count(*) from public.tgg_games where created_by=v_uid and status='live'),
      'sessions',(select count(*) from public.tgg_game_sessions where host_user_id=v_uid)
    ),
    'games',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',g.id,'title',g.title,'game_type',g.game_type,'status',g.status,
        'settings',g.settings,'starts_at',g.starts_at,'created_at',g.created_at,
        'player_count',(select count(*) from public.tgg_game_players p where p.game_id=g.id),
        'sessions',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',s.id,'status',s.status,'created_at',s.created_at,'started_at',s.started_at,'ended_at',s.ended_at,
            'player_count',(select count(*) from public.tgg_game_scores gs where gs.session_id=s.id),
            'leaderboard_endpoint','tgg_public_game_leaderboard'
          ) order by s.created_at desc)
          from public.tgg_game_sessions s where s.game_id=g.id
        ),'[]'::jsonb)
      ) order by g.created_at desc)
      from (
        select * from public.tgg_games where created_by=v_uid order by created_at desc limit v_limit
      ) g
    ),'[]'::jsonb),
    'capabilities',jsonb_build_object(
      'music_bingo',true,'trivia',true,'name_that_track',true,'finish_the_lyric',true,
      'beat_battle',true,'song_battle',true,'karaoke',true,'beat_roulette',true,'freestyle_roulette',true,
      'host_controlled_scoring',true,'public_leaderboards',true,'realtime_ready',true
    ),
    'generated_at',now()
  );
end $function$


-- [40000000689] function public.tgg_creator_growth_share_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_growth_share_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist public.artists;
  v_ref jsonb;
  v_releases jsonb;
  v_code text;
  v_invite_url text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select * into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist.id is null then
    raise exception 'ARTIST_PROFILE_REQUIRED' using errcode='P0002';
  end if;

  v_ref:=public.tgg_referral_code();
  v_code:=coalesce(v_ref->>'code','');
  v_invite_url:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-creator-os-app-v17?app=1&ref='||v_code||'#growth';

  select coalesce(jsonb_agg(jsonb_build_object(
    'release_id',m.id,
    'title',m.title,
    'slug',m.slug,
    'url','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-shell?view=release&slug='||m.slug
  ) order by coalesce(m.release_date,m.created_at) desc),'[]'::jsonb)
  into v_releases
  from public.mixtapes m
  where m.artist_id=v_artist.id
    and m.status='published'
    and nullif(btrim(coalesce(m.slug,'')),'') is not null;

  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-GROWTH-SHARE-1.1',
    'artist',jsonb_build_object(
      'artist_id',v_artist.id,
      'stage_name',v_artist.stage_name,
      'url','https://trugogettamixtapes.blogspot.com/p/public-artist-profile.html?artist_id='||v_artist.id
    ),
    'referral',jsonb_build_object(
      'code',v_code,
      'url',v_invite_url,
      'claim_mode','automatic_after_sign_in_with_manual_fallback',
      'claim_instructions','Open the invite link and sign in. Creator OS will capture the referral automatically.'
    ),
    'releases',v_releases,
    'generated_at',now()
  );
end
$function$


-- [40000000690] function public.tgg_creator_growth_status()
CREATE OR REPLACE FUNCTION public.tgg_creator_growth_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist public.artists;
  v_published integer:=0;
  v_followers integer:=0;
  v_following integer:=0;
  v_unread integer:=0;
  v_referrals integer:=0;
  v_profile_score integer:=0;
  v_actions jsonb:='[]'::jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_artist from public.artists where user_id=v_uid order by created_at limit 1;

  if v_artist.id is null then
    return jsonb_build_object(
      'ok',true,'version','CREATOR-GROWTH-STATUS-1.1',
      'has_artist_profile',false,
      'profile_score',0,
      'next_actions',jsonb_build_array(
        jsonb_build_object('key','create_profile','priority',1,'label','Create your artist profile')
      ),
      'generated_at',now()
    );
  end if;

  v_profile_score :=
    (case when nullif(btrim(coalesce(v_artist.stage_name,'')),'') is not null then 20 else 0 end)
    +(case when nullif(btrim(coalesce(v_artist.bio,'')),'') is not null then 20 else 0 end)
    +(case when nullif(btrim(coalesce(v_artist.avatar_url,'')),'') is not null then 20 else 0 end)
    +(case when nullif(btrim(coalesce(v_artist.website,'')),'') is not null
             or nullif(btrim(coalesce(v_artist.instagram,'')),'') is not null
             or nullif(btrim(coalesce(v_artist.youtube,'')),'') is not null
             or nullif(btrim(coalesce(v_artist.spotify,'')),'') is not null then 20 else 0 end)
    +(case when coalesce(v_artist.stripe_onboarding_complete,false) or v_artist.membership_payout_mode='platform' then 20 else 0 end);

  select count(*) into v_published from public.mixtapes where artist_id=v_artist.id and status='published';
  select count(*) into v_followers from public.artist_follows where artist_id=v_artist.id;
  select count(*) into v_following from public.artist_follows where user_id=v_uid;
  select count(*) into v_unread from public.notifications where recipient_id=v_uid and read_at is null;
  select count(*) into v_referrals from public.tgg_referral_claims where referrer_user_id=v_uid;

  if v_profile_score<80 then
    v_actions:=v_actions||jsonb_build_array(jsonb_build_object('key','complete_profile','priority',1,'label','Complete your public creator profile'));
  end if;
  if v_published=0 then
    v_actions:=v_actions||jsonb_build_array(jsonb_build_object('key','publish_release','priority',2,'label','Publish your first release'));
  end if;
  if v_referrals=0 then
    v_actions:=v_actions||jsonb_build_array(jsonb_build_object('key','invite_people','priority',3,'label','Share your referral code and invite your first fan or creator'));
  end if;
  if v_followers=0 then
    v_actions:=v_actions||jsonb_build_array(jsonb_build_object('key','grow_followers','priority',4,'label','Share your public artist profile to earn your first follower'));
  end if;
  if jsonb_array_length(v_actions)=0 then
    v_actions:=jsonb_build_array(jsonb_build_object('key','keep_growing','priority',5,'label','Keep publishing and engaging your audience'));
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','CREATOR-GROWTH-STATUS-1.1',
    'has_artist_profile',true,
    'artist_id',v_artist.id,
    'stage_name',v_artist.stage_name,
    'profile_score',v_profile_score,
    'published_releases',v_published,
    'followers',v_followers,
    'following',v_following,
    'unread_notifications',v_unread,
    'successful_referrals',v_referrals,
    'next_actions',v_actions,
    'generated_at',now()
  );
end
$function$


-- [40000000691] function public.tgg_creator_hot_path_index_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_hot_path_index_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
with checks(name,ok) as (
  values
    ('artists_user_lookup', to_regclass('public.artists_user_id_key') is not null),
    ('notifications_unread', to_regclass('public.idx_notifications_unread') is not null or to_regclass('public.notifications_recipient_unread_idx') is not null),
    ('action_queue_owner_status', to_regclass('public.tgg_creator_action_queue_owner_status_idx') is not null or to_regclass('public.tgg_creator_action_queue_owner_status_priority_idx') is not null),
    ('booking_provider_status', to_regclass('public.tgg_booking_provider_idx') is not null or to_regclass('public.tgg_booking_requests_provider_status_idx') is not null),
    ('products_user_lookup', to_regclass('public.merch_products_user_id_idx') is not null),
    ('products_creator_lookup', to_regclass('public.merch_products_creator_idx') is not null),
    ('membership_artist_active', to_regclass('public.tgg_membership_tiers_artist_idx') is not null),
    ('audiobook_artist_status', to_regclass('public.tgg_audiobooks_artist_status_updated_idx') is not null),
    ('games_artist_lookup', to_regclass('public.tgg_games_artist_idx') is not null),
    ('release_user_lookup', to_regclass('public.mixtapes_user_id_idx') is not null),
    ('release_artist_lookup', to_regclass('public.mixtapes_artist_id_fkey_idx') is not null),
    ('fan_library_user_lookup', to_regclass('public.release_saves_user_created_idx') is not null or to_regclass('public.release_saves_user_id_mixtape_id_key') is not null),
    ('conversation_member_user_lookup', to_regclass('public.tgg_conversation_members_user_idx') is not null),
    ('messages_conversation_time', to_regclass('public.tgg_messages_conversation_created_idx') is not null),
    ('collaboration_incoming_pending', to_regclass('public.tgg_collab_recipient_status_idx') is not null),
    ('collaboration_sender_lookup', to_regclass('public.tgg_collaboration_requests_sender_id_idx') is not null)
),
agg as (
  select
    count(*) total,
    count(*) filter(where ok) ready,
    coalesce(jsonb_agg(name order by name) filter(where not ok),'[]'::jsonb) failed
  from checks
)
select jsonb_build_object(
  'ok',ready=total,
  'version','CREATOR-HOT-PATH-INDEX-1.0',
  'ready',ready,
  'total',total,
  'failed',failed,
  'checks',(select jsonb_object_agg(name,ok order by name) from checks),
  'scope',jsonb_build_array(
    'creator_navigation',
    'first_use_boot',
    'fan_library',
    'messenger_inbox',
    'collaboration_inbox'
  ),
  'new_indexes_added',0,
  'reason','existing indexes already cover current hot predicates; avoid redundant write/index overhead',
  'generated_at',now()
)
from agg;
$function$


-- [40000000692] function public.tgg_creator_idempotency_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_idempotency_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
with checks(name,ok,detail) as (
  values
    (
      'distribution_submit_retry_safe',
      exists(
        select 1 from pg_indexes
        where schemaname='public'
          and tablename='tgg_distribution_requests'
          and indexname='tgg_distribution_requests_active_package_uidx'
          and indexdef ilike '%UNIQUE INDEX%'
      )
      and exists(
        select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
        where n.nspname='public'
          and p.proname='tgg_distribution_submit_request'
          and pg_get_functiondef(p.oid) ilike '%idempotent_reuse%'
          and pg_get_functiondef(p.oid) ilike '%unique_violation%'
      ),
      'same release/provider/package reuses in-flight request'
    ),
    (
      'studio_finalize_retry_safe',
      exists(
        select 1 from pg_indexes
        where schemaname='public'
          and tablename='tgg_studio_assets'
          and indexname='tgg_studio_assets_project_storage_uidx'
          and indexdef ilike '%UNIQUE INDEX%'
      )
      and exists(
        select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
        where n.nspname='public'
          and p.proname='tgg_register_studio_asset'
          and pg_get_functiondef(p.oid) ilike '%unique_violation%'
      ),
      'same project/storage path reuses existing studio asset'
    ),
    (
      'live_replay_finalize_retry_safe',
      exists(
        select 1 from pg_indexes
        where schemaname='public'
          and tablename='tgg_live_replays'
          and indexname='tgg_live_replays_stream_id_key'
          and indexdef ilike '%UNIQUE INDEX%'
      )
      and exists(
        select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
        where n.nspname='public'
          and p.proname='tgg_live_studio_finalize_replay'
          and pg_get_functiondef(p.oid) ilike '%on conflict%'
      ),
      'one replay per stream with conflict-safe finalize'
    ),
    (
      'call_room_start_retry_safe',
      exists(
        select 1 from pg_indexes
        where schemaname='public'
          and tablename='tgg_call_rooms'
          and indexname='tgg_call_rooms_active_conversation_type_uidx'
          and indexdef ilike '%UNIQUE INDEX%'
      )
      and exists(
        select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
        where n.nspname='public'
          and p.proname='tgg_start_call_room'
          and pg_get_functiondef(p.oid) ilike '%pg_advisory_xact_lock%'
          and pg_get_functiondef(p.oid) ilike '%r.status=''active''%'
          and pg_get_functiondef(p.oid) ilike '%if v_room is null then%'
          and pg_get_functiondef(p.oid) ilike '%on conflict(room_id,user_id) do update%'
      ),
      'one active room per conversation/type with unique index, transaction lock, retry reuse, and participant upsert'
    ),
    (
      'distribution_metadata_upsert_retry_safe',
      exists(
        select 1 from pg_indexes
        where schemaname='public'
          and tablename='tgg_distribution_release_metadata'
          and indexname='tgg_distribution_release_metadata_pkey'
          and indexdef ilike '%UNIQUE INDEX%'
      )
      and exists(
        select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
        where n.nspname='public'
          and p.proname='tgg_distribution_metadata_upsert'
          and pg_get_functiondef(p.oid) ilike '%on conflict%'
      ),
      'one metadata row per release with upsert'
    ),
    (
      'membership_activation_retry_safe',
      exists(
        select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
        where n.nspname='public'
          and p.proname='tgg_membership_tier_set_active'
          and pg_get_functiondef(p.oid) ilike '%update %'
          and pg_get_functiondef(p.oid) ilike '%exists(%'
      ),
      'setting same active state is an idempotent update'
    ),
    (
      'call_validation_invite_retry_safe',
      exists(
        select 1 from pg_indexes
        where schemaname='private'
          and tablename='tgg_call_validation_invites'
          and indexname='tgg_call_validation_invites_one_pending_inviter_uidx'
          and indexdef ilike '%UNIQUE INDEX%'
      )
      and exists(
        select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
        where n.nspname='private'
          and p.proname='tgg_call_validation_invite_create'
          and pg_get_functiondef(p.oid) ilike '%idempotent_reuse%'
          and pg_get_functiondef(p.oid) ilike '%unique_violation%'
      ),
      'one pending validation invite per inviter with retry reuse'
    )
),
agg as (
  select
    count(*) total,
    count(*) filter(where ok) ready,
    coalesce(jsonb_agg(name order by name) filter(where not ok),'[]'::jsonb) failed,
    jsonb_object_agg(name,jsonb_build_object('ok',ok,'detail',detail) order by name) details
  from checks
),
dups as (
  select jsonb_build_object(
    'distribution_active_duplicate_groups',(
      select count(*) from (
        select release_id,provider_key,package_hash
        from public.tgg_distribution_requests
        where status in ('prepared','queued','processing','submitted')
        group by 1,2,3 having count(*)>1
      ) x
    ),
    'studio_asset_duplicate_groups',(
      select count(*) from (
        select project_id,storage_path
        from public.tgg_studio_assets
        where storage_path is not null
        group by 1,2 having count(*)>1
      ) x
    ),
    'call_active_duplicate_groups',(
      select count(*) from (
        select conversation_id,room_type
        from public.tgg_call_rooms
        where status='active'
        group by 1,2 having count(*)>1
      ) x
    ),
    'call_validation_pending_duplicate_groups',(
      select count(*) from (
        select inviter_user_id
        from private.tgg_call_validation_invites
        where status='pending'
        group by 1 having count(*)>1
      ) x
    )
  ) d
)
select jsonb_build_object(
  'ok',
    a.ready=a.total
    and coalesce((d.d->>'distribution_active_duplicate_groups')::bigint,0)=0
    and coalesce((d.d->>'studio_asset_duplicate_groups')::bigint,0)=0
    and coalesce((d.d->>'call_active_duplicate_groups')::bigint,0)=0
    and coalesce((d.d->>'call_validation_pending_duplicate_groups')::bigint,0)=0,
  'version','CREATOR-IDEMPOTENCY-1.2',
  'contracts',jsonb_build_object('ready',a.ready,'total',a.total,'failed',a.failed,'details',a.details),
  'duplicate_state',d.d,
  'intentional_non_idempotent_actions',jsonb_build_array(
    'tgg_toggle_release_save: explicit toggle semantics',
    'tgg_membership_tier_create: intentional creation of distinct tiers',
    'tgg_send_message: identical message bodies may be intentional'
  ),
  'generated_at',now()
)
from agg a cross join dups d;
$function$


-- [40000000693] function public.tgg_creator_interviews_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_interviews_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'counts',jsonb_build_object(
      'draft',(select count(*) from public.artist_interviews where user_id=v_uid and status='draft'),
      'published',(select count(*) from public.artist_interviews where user_id=v_uid and status='published')
    ),
    'interviews',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',i.id,'title',i.title,'artist_name',i.artist_name,'video_url',i.video_url,
        'image_url',i.image_url,'publish_date',i.publish_date,'published',i.published,'status',i.status
      ) order by i.created_at desc)
      from public.artist_interviews i where i.user_id=v_uid
    ),'[]'::jsonb)
  );
end $function$


-- [40000000694] function public.tgg_creator_legacy_issue_health()
CREATE OR REPLACE FUNCTION public.tgg_creator_legacy_issue_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
select jsonb_build_object(
  'ok',
    to_regclass('public.v159_creator_events') is null
    and to_regclass('public.creator_analytics_events') is not null
    and has_table_privilege('authenticated','public.creator_analytics_events','SELECT')
    and has_table_privilege('authenticated','public.creator_analytics_events','INSERT')
    and to_regprocedure('public.tgg_record_creator_event(text,uuid,text,text,jsonb)') is not null,
  'version','LEGACY-COMPAT-CANONICAL',
  'analytics',jsonb_build_object(
    'current_table','creator_analytics_events',
    'current_rpc','tgg_record_creator_event',
    'legacy_v159_present',to_regclass('public.v159_creator_events') is not null,
    'authenticated_select',has_table_privilege('authenticated','public.creator_analytics_events','SELECT'),
    'authenticated_insert',has_table_privilege('authenticated','public.creator_analytics_events','INSERT')
  ),
  'payments',jsonb_build_object(
    'current_health_rpc','tgg_get_provider_pipeline_health',
    'current_config_table','tgg_provider_runtime_config',
    'legacy_v58_tables_present',exists(
      select 1 from information_schema.tables
      where table_schema='public' and table_name like 'v58_%'
    )
  ),
  'media',jsonb_build_object(
    'mixtapes_audio_url',exists(
      select 1 from information_schema.columns
      where table_schema='public' and table_name='mixtapes' and column_name='audio_url'
    ),
    'creator_media_health_function',
      to_regprocedure('public.tgg_creator_media_health()') is not null
  ),
  'routing',jsonb_build_object(
    'canonical_creator_os',(
      select path from public.tgg_site_routes
      where route_key='artist_creator_os' and is_active
      limit 1
    ),
    'legacy_dashboard_hidden_from_manifest',
      not exists(
        select 1 from public.tgg_site_routes
        where route_key='artist_dashboard' and is_active
      ),
    'canonical_home',(
      select path from public.tgg_site_routes
      where route_key='home' and is_active
      limit 1
    )
  ),
  'generated_at',now()
);
$function$


-- [40000000695] function public.tgg_creator_lifecycle_integrity_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_lifecycle_integrity_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
with status_checks as (
  select count(*) filter(where ok) ready, count(*) total,
         coalesce(jsonb_agg(name order by name) filter(where not ok),'[]'::jsonb) failed
  from (
    values
      ('mixtapes.status_enum', exists(
        select 1
        from pg_type t
        join pg_enum e on e.enumtypid=t.oid
        where t.typname='mixtape_status'
        group by t.oid
        having array_agg(e.enumlabel::text order by e.enumsortorder) @>
          array['draft','pending','changes_requested','published','rejected']::text[]
      )),
      ('live_streams.status_check', exists(
        select 1 from pg_constraint con join pg_class c on c.oid=con.conrelid
        where c.relname='live_streams' and con.conname='live_streams_status_check' and con.convalidated
      )),
      ('memberships.status_check', exists(
        select 1 from pg_constraint con join pg_class c on c.oid=con.conrelid
        where c.relname='tgg_memberships' and con.conname='tgg_memberships_status_check' and con.convalidated
      )),
      ('game_sessions.status_check', exists(
        select 1 from pg_constraint con join pg_class c on c.oid=con.conrelid
        where c.relname='tgg_game_sessions' and con.conname='tgg_game_sessions_status_check' and con.convalidated
      )),
      ('games.status_check', exists(
        select 1 from pg_constraint con join pg_class c on c.oid=con.conrelid
        where c.relname='tgg_games' and con.conname='tgg_games_status_check' and con.convalidated
      )),
      ('studio_projects.status_check', exists(
        select 1 from pg_constraint con join pg_class c on c.oid=con.conrelid
        where c.relname='tgg_studio_projects' and con.conname='tgg_studio_projects_status_check' and con.convalidated
      )),
      ('audiobooks.status_check', exists(
        select 1 from pg_constraint con join pg_class c on c.oid=con.conrelid
        where c.relname='tgg_audiobooks' and con.conname='tgg_audiobooks_status_check' and con.convalidated
      )),
      ('call_rooms.status_check', exists(
        select 1 from pg_constraint con join pg_class c on c.oid=con.conrelid
        where c.relname='tgg_call_rooms' and con.conname='tgg_call_rooms_status_check' and con.convalidated
      ))
  ) s(name,ok)
),
uniqueness as (
  select count(*) filter(where ok) ready, count(*) total,
         coalesce(jsonb_agg(name order by name) filter(where not ok),'[]'::jsonb) failed
  from (
    values
      ('conversation_member_unique', exists(
        select 1 from pg_constraint con join pg_class c on c.oid=con.conrelid
        where c.relname='tgg_conversation_members'
          and con.contype='p'
          and pg_get_constraintdef(con.oid,true)='PRIMARY KEY (conversation_id, user_id)'
      )),
      ('studio_member_unique', exists(
        select 1 from pg_constraint con join pg_class c on c.oid=con.conrelid
        where c.relname='tgg_studio_project_members'
          and con.contype='p'
          and pg_get_constraintdef(con.oid,true)='PRIMARY KEY (project_id, user_id)'
      )),
      ('track_number_unique', exists(
        select 1 from pg_indexes
        where schemaname='public'
          and tablename='tracks'
          and indexname='tracks_mixtape_track_number_uidx'
          and indexdef ilike '%UNIQUE INDEX%'
      )),
      ('audiobook_chapter_unique', exists(
        select 1 from pg_constraint con join pg_class c on c.oid=con.conrelid
        where c.relname='tgg_audiobook_chapters'
          and con.conname='tgg_audiobook_chapters_audiobook_id_chapter_number_key'
          and con.convalidated
      )),
      ('membership_artist_fan_unique', exists(
        select 1 from pg_constraint con join pg_class c on c.oid=con.conrelid
        where c.relname='tgg_memberships'
          and con.conname='tgg_memberships_artist_id_fan_user_id_key'
          and con.convalidated
      ))
  ) u(name,ok)
),
timelines as (
  select count(*) filter(where ok) ready, count(*) total,
         coalesce(jsonb_agg(name order by name) filter(where not ok),'[]'::jsonb) failed
  from (
    values
      ('live_stream_time_order', exists(
        select 1 from pg_constraint con where con.conname='live_streams_actual_time_order_check' and con.convalidated
      )),
      ('game_session_time_order', exists(
        select 1 from pg_constraint con where con.conname='tgg_game_sessions_time_order_check' and con.convalidated
      )),
      ('call_room_time_order', exists(
        select 1 from pg_constraint con where con.conname='tgg_call_rooms_time_order_check' and con.convalidated
      )),
      ('membership_period_order', exists(
        select 1 from pg_constraint con where con.conname='tgg_memberships_period_order_check' and con.convalidated
      ))
  ) t(name,ok)
),
violations as (
  select jsonb_build_object(
    'duplicate_groups',
      (select sum(v) from (values
        ((select count(*) from (
          select conversation_id,user_id from public.tgg_conversation_members group by 1,2 having count(*)>1
        )x)),
        ((select count(*) from (
          select project_id,user_id from public.tgg_studio_project_members group by 1,2 having count(*)>1
        )x)),
        ((select count(*) from (
          select mixtape_id,track_number from public.tracks group by 1,2 having count(*)>1
        )x)),
        ((select count(*) from (
          select audiobook_id,chapter_number from public.tgg_audiobook_chapters group by 1,2 having count(*)>1
        )x))
      ) q(v)),
    'timeline_violations',
      (select
        (select count(*) from public.live_streams where actual_start is not null and actual_end is not null and actual_end<actual_start)
        +(select count(*) from public.tgg_game_sessions where started_at is not null and ended_at is not null and ended_at<started_at)
        +(select count(*) from public.tgg_call_rooms where ended_at is not null and created_at is not null and ended_at<created_at)
        +(select count(*) from public.tgg_memberships where started_at is not null and current_period_end is not null and current_period_end<started_at)
      )
  ) v
)
select jsonb_build_object(
  'ok',
    s.ready=s.total
    and u.ready=u.total
    and t.ready=t.total
    and coalesce((v.v->>'duplicate_groups')::bigint,0)=0
    and coalesce((v.v->>'timeline_violations')::bigint,0)=0,
  'version','CREATOR-LIFECYCLE-INTEGRITY-1.0',
  'status_contracts',jsonb_build_object('ready',s.ready,'total',s.total,'failed',s.failed),
  'uniqueness_contracts',jsonb_build_object('ready',u.ready,'total',u.total,'failed',u.failed),
  'timeline_contracts',jsonb_build_object('ready',t.ready,'total',t.total,'failed',t.failed),
  'violations',v.v,
  'generated_at',now()
)
from status_checks s cross join uniqueness u cross join timelines t cross join violations v;
$function$


-- [40000000696] function public.tgg_creator_live_studio_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_live_studio_bundle()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with b as (
    select public.tgg_broadcast_engine_health() as h
  )
  select
    tgg_private.creator_live_studio_bundle()
    || jsonb_build_object(
      'broadcast_readiness',
        jsonb_build_object(
          'control_plane_ready',coalesce((b.h->>'control_plane_ready')::boolean,false),
          'camera_screen_capture_ready',true,
          'local_process_recording_ready',true,
          'guest_webrtc_signaling_ready',true,
          'replay_pipeline_ready',true,
          'dedicated_sfu_turn_connected',coalesce((b.h->>'sfu_connected')::boolean,false) and coalesce((b.h->>'turn_connected')::boolean,false),
          'scalable_audience_video_ready',coalesce((b.h->>'sfu_connected')::boolean,false),
          'provider',b.h->>'provider',
          'disabled_reason',b.h->>'disabled_reason',
          'status',case when coalesce((b.h->>'sfu_connected')::boolean,false) then 'production_ready' else 'adapter_required' end
        )
    )
  from b;
$function$


-- [40000000697] function public.tgg_creator_media_health()
CREATE OR REPLACE FUNCTION public.tgg_creator_media_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist from public.artists where user_id=v_uid order by created_at limit 1;
      if v_artist is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

      return jsonb_build_object(
        'ok',true,
        'artist_id',v_artist,
        'catalog',jsonb_build_object(
          'releases',(select count(*) from public.mixtapes where artist_id=v_artist),
          'tracks',(select count(*) from public.tracks where artist_id=v_artist),
          'secure_tracks',(select count(*) from public.tracks where artist_id=v_artist and audio_path is not null),
          'videos',(select count(*) from public.videos where artist_id=v_artist)
        ),
        'storage',jsonb_build_object(
          'owned_audio_objects',(
            select count(*) from storage.objects o
            where o.bucket_id='mixtape-audio'
              and (storage.foldername(o.name))[1]=v_uid::text
          )
        ),
        'generated_at',now()
      );
    end;
    $function$


-- [40000000698] function public.tgg_creator_notifications_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_notifications_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_preferences jsonb;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

      select to_jsonb(p) - 'user_id'
      into v_preferences
      from public.notification_preferences p
      where p.user_id=v_uid;

      return jsonb_build_object(
        'ok',true,
        'version','NOTIFICATIONS-ONE-FINAL-1.0',
        'counts',jsonb_build_object(
          'total',(select count(*) from public.notifications where recipient_id=v_uid),
          'unread',(select count(*) from public.notifications where recipient_id=v_uid and read_at is null),
          'review_events',(select count(*) from public.notifications where recipient_id=v_uid and notification_type like '%review%'),
          'collaboration',(select count(*) from public.notifications where recipient_id=v_uid and notification_type ilike '%collab%'),
          'messages',(select count(*) from public.notifications where recipient_id=v_uid and notification_type ilike '%message%')
        ),
        'notifications',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',n.id,
            'notification_type',n.notification_type,
            'entity_type',n.entity_type,
            'entity_id',n.entity_id,
            'title',n.title,
            'body',n.body,
            'read_at',n.read_at,
            'created_at',n.created_at,
            'is_unread',n.read_at is null
          ) order by n.created_at desc)
          from (
            select *
            from public.notifications
            where recipient_id=v_uid
            order by created_at desc
            limit 100
          ) n
        ),'[]'::jsonb),
        'preferences',coalesce(v_preferences,jsonb_build_object(
          'follows_enabled',true,
          'saves_enabled',true,
          'reactions_enabled',true,
          'comments_enabled',true,
          'collaboration_enabled',true
        )),
        'capabilities',jsonb_build_object(
          'mark_read',true,
          'mark_all_read',true,
          'preferences',true,
          'realtime',true
        ),
        'generated_at',now()
      );
    end;
    $function$


-- [40000000699] function public.tgg_creator_onboarding_status()
CREATE OR REPLACE FUNCTION public.tgg_creator_onboarding_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist public.artists;
    begin
      if v_uid is null then
        raise exception 'AUTH_REQUIRED' using errcode='42501';
      end if;

      select * into v_artist
      from public.artists
      where user_id=v_uid
      order by created_at
      limit 1;

      return jsonb_build_object(
        'ok',true,
        'authenticated',true,
        'has_artist_profile',(v_artist.id is not null),
        'artist',case when v_artist.id is null then null else jsonb_build_object(
          'id',v_artist.id,
          'stage_name',v_artist.stage_name,
          'bio',v_artist.bio,
          'avatar_url',v_artist.avatar_url,
          'instagram',v_artist.instagram,
          'website',v_artist.website,
          'youtube',v_artist.youtube,
          'soundcloud',v_artist.soundcloud,
          'spotify',v_artist.spotify,
          'stripe_onboarding_complete',v_artist.stripe_onboarding_complete,
          'payouts_enabled',v_artist.payouts_enabled
        ) end,
        'next_step',case when v_artist.id is null then 'create_artist_profile' else 'creator_os' end,
        'generated_at',now()
      );
    end;
    $function$


-- [40000000700] function public.tgg_creator_one_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_one_bundle()
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select private.tgg_creator_one_bundle();
