$function$


-- [40000000711] function public.tgg_creator_os_v5000_health()
CREATE OR REPLACE FUNCTION public.tgg_creator_os_v5000_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_route jsonb:=public.tgg_route_registry_final_health();
  v_ops jsonb:=public.tgg_operations_final_health();
  v_media jsonb:=public.tgg_creator_media_health();
  v_integrity jsonb:=public.tgg_v5000_runtime_integrity();
begin
  return jsonb_build_object(
    'ok',
      coalesce((v_route->>'ok')::boolean,false)
      and coalesce((v_media->>'ok')::boolean,false)
      and coalesce((v_integrity->>'ok')::boolean,false)
      and coalesce((v_ops#>>'{drift,storage_buckets_checked}')::integer,0)>=8,
    'version','V5000-ONE-LOAD',
    'build','V5000-ONE-LOAD',
    'runtime_edge_version',v_integrity->'edge_version',
    'routes',v_route,'media',v_media,'runtime_integrity',v_integrity,
    'storage',jsonb_build_object(
      'buckets_checked',coalesce((v_ops#>>'{drift,storage_buckets_checked}')::integer,0),
      'contract_ok',coalesce((v_ops#>>'{drift,storage_buckets_checked}')::integer,0)>=8
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000712] function public.tgg_creator_payout_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_payout_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();a public.artists;v_runtime boolean:=false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into a from public.artists where user_id=v_uid order by created_at limit 1;
  if a.id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;
  select coalesce(enabled,false) and coalesce(endpoint_configured,false) and mode='production'
  into v_runtime
  from public.tgg_provider_runtime_config
  where provider_key='stripe';

  return jsonb_build_object(
    'ok',true,
    'artist_id',a.id,
    'stripe_server_runtime_configured',coalesce(v_runtime,false),
    'stripe_account_connected',a.stripe_account_id is not null,
    'stripe_onboarding_complete',a.stripe_onboarding_complete,
    'payouts_enabled',a.payouts_enabled,
    'can_accept_paid_memberships',
      coalesce(v_runtime,false) and a.stripe_account_id is not null and a.stripe_onboarding_complete and a.payouts_enabled,
    'next_action',case
      when not coalesce(v_runtime,false) then 'configure_stripe_server'
      when a.stripe_account_id is null then 'connect_stripe'
      when not a.stripe_onboarding_complete then 'continue_onboarding'
      when not a.payouts_enabled then 'refresh_status'
      else 'ready'
    end
  );
end $function$


-- [40000000713] function public.tgg_creator_phone_bundle(p_query text, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_creator_phone_bundle(p_query text DEFAULT NULL::text, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_profile jsonb;
  v_comms jsonb;
  v_notifications jsonb;
  v_collab jsonb;
  v_live jsonb;
  v_directory jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  v_profile:=public.tgg_creator_profile_bundle();
  v_comms:=public.tgg_creator_communications_bundle();
  v_notifications:=public.tgg_creator_notifications_bundle();
  v_collab:=public.tgg_creator_collab_bundle();
  v_live:=public.tgg_creator_live_studio_bundle();
  v_directory:=public.tgg_public_artist_discovery_one_final(p_query,greatest(1,least(coalesce(p_limit,20),50)));

  return jsonb_build_object(
    'ok',true,
    'version','PHONE-ONE-FINAL-1.0',
    'creator',v_profile->'artist',
    'status',jsonb_build_object(
      'unread_notifications',coalesce((v_notifications->'counts'->>'unread')::int,0),
      'unread_messages',coalesce((v_comms->'counts'->>'unread_messages')::int,0),
      'pending_collabs',coalesce((v_comms->'counts'->>'collab_incoming_pending')::int,0),
      'active_calls',coalesce((v_comms->'counts'->>'active_calls')::int,0),
      'live_now',coalesce((v_live->'counts'->>'live')::int,0)
    ),
    'favorites',coalesce((
      select jsonb_agg(jsonb_build_object(
        'artist_id',a.id,'stage_name',a.stage_name,'avatar_url',a.avatar_url,
        'profile_url','/p/public-artist-profile.html?id='||a.id::text,
        'message_action','/p/messages.html?artist_id='||a.id::text,
        'call_action','/p/live.html#calls'
      ) order by f.created_at desc)
      from public.tgg_phone_favorites f
      join public.artists a on a.id=f.artist_id
      where f.user_id=v_uid
    ),'[]'::jsonb),
    'directory',coalesce(v_directory->'artists','[]'::jsonb),
    'communications',v_comms,
    'notifications',v_notifications,
    'collab',v_collab,
    'live',v_live,
    'launcher',jsonb_build_array(
      jsonb_build_object('key','messages','label','Messages','icon','message-circle','url','/p/messages.html'),
      jsonb_build_object('key','calls','label','Calls','icon','phone','url','/p/live.html#calls'),
      jsonb_build_object('key','live','label','Go Live','icon','radio','url','/p/live.html#studio'),
      jsonb_build_object('key','collab','label','Collab','icon','users','url','/p/live.html#collab'),
      jsonb_build_object('key','beat','label','Beat Studio','icon','music','url','/p/beat-studio.html'),
      jsonb_build_object('key','recording','label','Recording','icon','mic','url','/p/recording-studio.html'),
      jsonb_build_object('key','video','label','Video Studio','icon','video','url','/p/video-studio.html'),
      jsonb_build_object('key','upload','label','Upload','icon','upload','url','/p/upload-mixtape.html'),
      jsonb_build_object('key','vault','label','Vault','icon','lock','url','/p/vault.html'),
      jsonb_build_object('key','store','label','Store','icon','shopping-bag','url','/p/creator-store.html'),
      jsonb_build_object('key','career','label','Career OS','icon','briefcase','url','/p/career-os.html'),
      jsonb_build_object('key','notifications','label','Notifications','icon','bell','url','/p/notifications.html')
    ),
    'generated_at',now()
  );
end $function$


-- [40000000714] function public.tgg_creator_podcast_interview_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_podcast_interview_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'version','PODCAST-INTERVIEW-ONE-FINAL-1.0',
    'counts',jsonb_build_object(
      'interviews',(select count(*) from public.artist_interviews where user_id=v_uid),
      'interviews_published',(select count(*) from public.artist_interviews where user_id=v_uid and published=true),
      'audio_podcasts',(select count(*) from public.tgg_radio_shows where user_id=v_uid and show_type='podcast'),
      'audio_podcasts_published',(select count(*) from public.tgg_radio_shows where user_id=v_uid and show_type='podcast' and status='published'),
      'video_podcasts',(select count(*) from public.tgg_tv_episodes where owner_user_id=v_uid and episode_type='podcast_video'),
      'video_podcasts_published',(select count(*) from public.tgg_tv_episodes where owner_user_id=v_uid and episode_type='podcast_video' and status='published')
    ),
    'interviews',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',i.id,'title',i.title,'artist_name',i.artist_name,'video_url',i.video_url,
        'image_url',i.image_url,'publish_date',i.publish_date,'status',i.status,'published',i.published
      ) order by i.created_at desc)
      from public.artist_interviews i where i.user_id=v_uid
    ),'[]'::jsonb),
    'audio_podcasts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',r.id,'title',r.title,'description',r.description,'audio_url',r.audio_url,
        'artwork_url',r.artwork_url,'scheduled_for',r.scheduled_for,'duration_seconds',r.duration_seconds,
        'status',r.status,'admin_note',r.admin_note,'published_at',r.published_at
      ) order by r.created_at desc)
      from public.tgg_radio_shows r where r.user_id=v_uid and r.show_type='podcast'
    ),'[]'::jsonb),
    'video_podcasts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',e.id,'channel_id',e.channel_id,'title',e.title,'description',e.description,
        'video_url',e.video_url,'thumbnail_url',e.thumbnail_url,'duration_seconds',e.duration_seconds,
        'season_number',e.season_number,'episode_number',e.episode_number,'status',e.status,
        'admin_note',e.admin_note,'published_at',e.published_at
      ) order by e.created_at desc)
      from public.tgg_tv_episodes e where e.owner_user_id=v_uid and e.episode_type='podcast_video'
    ),'[]'::jsonb),
    'capabilities',jsonb_build_object(
      'recording_studio_source',true,
      'audio_podcast_radio_review',true,
      'video_podcast_tv_review',true,
      'interview_direct_publish',true,
      'live_replay_to_video_podcast',true,
      'collab_recording_ready',true
    ),
    'generated_at',now()
  );
end $function$


-- [40000000715] function public.tgg_creator_profile_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_profile_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_artist public.artists;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select * into v_artist from public.artists where user_id=v_uid limit 1;
      if v_artist.id is null then raise exception 'ARTIST_PROFILE_REQUIRED'; end if;
      return jsonb_build_object(
        'ok',true,
        'artist',jsonb_build_object(
          'id',v_artist.id,'stage_name',v_artist.stage_name,'bio',v_artist.bio,
          'avatar_url',v_artist.avatar_url,'instagram',v_artist.instagram,'website',v_artist.website,
          'youtube',v_artist.youtube,'soundcloud',v_artist.soundcloud,'spotify',v_artist.spotify,
          'stripe_onboarding_complete',v_artist.stripe_onboarding_complete,'payouts_enabled',v_artist.payouts_enabled
        )
      );
    end $function$


-- [40000000716] function public.tgg_creator_profile_update(p_stage_name text, p_bio text, p_avatar_url text, p_instagram text, p_website text, p_youtube text, p_soundcloud text, p_spotify text)
CREATE OR REPLACE FUNCTION public.tgg_creator_profile_update(p_stage_name text, p_bio text, p_avatar_url text, p_instagram text, p_website text, p_youtube text, p_soundcloud text, p_spotify text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_stage_name,'')))<1 or char_length(btrim(coalesce(p_stage_name,'')))>120 then
    raise exception 'STAGE_NAME_INVALID';
  end if;

  update public.artists
  set stage_name=left(btrim(p_stage_name),120),
      bio=coalesce(p_bio,''),
      avatar_url=nullif(btrim(coalesce(p_avatar_url,'')),''),
      instagram=nullif(btrim(coalesce(p_instagram,'')),''),
      website=nullif(btrim(coalesce(p_website,'')),''),
      youtube=nullif(btrim(coalesce(p_youtube,'')),''),
      soundcloud=nullif(btrim(coalesce(p_soundcloud,'')),''),
      spotify=nullif(btrim(coalesce(p_spotify,'')),'')
  where user_id=v_uid
  returning id into v_id;

  if v_id is null then raise exception 'ARTIST_PROFILE_REQUIRED'; end if;

  perform tgg_private.sync_public_artist_directory(v_id);

  return jsonb_build_object('ok',true,'artist_id',v_id);
end $function$


-- [40000000717] function public.tgg_creator_project_update_resubmit(p_project_id uuid, p_title text, p_genre text, p_release_date timestamp with time zone, p_explicit text, p_description text, p_cover_url text, p_tracks jsonb)
CREATE OR REPLACE FUNCTION public.tgg_creator_project_update_resubmit(p_project_id uuid, p_title text, p_genre text DEFAULT NULL::text, p_release_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_explicit text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_cover_url text DEFAULT NULL::text, p_tracks jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist_id uuid;
      v_status public.mixtape_status;
      v_title text:=btrim(coalesce(p_title,''));
      v_track jsonb;
      v_track_id uuid;
      v_audio_url text;
      v_cover_url text:=nullif(btrim(coalesce(p_cover_url,'')),'');
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist_id from public.artists where user_id=v_uid limit 1;
      if v_artist_id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;
      if char_length(v_title)<1 or char_length(v_title)>160 then raise exception 'TITLE_INVALID'; end if;

      select status into v_status
      from public.mixtapes
      where id=p_project_id and artist_id=v_artist_id
      for update;

      if v_status is null then raise exception 'PROJECT_NOT_FOUND'; end if;
      if v_status not in ('draft','pending','changes_requested','rejected') then
        raise exception 'PROJECT_NOT_EDITABLE';
      end if;

      if v_cover_url is not null and v_cover_url not like 'https://xsofowzvwetamhyuvlpj.supabase.co/storage/v1/object/public/covers/%' then
        raise exception 'COVER_URL_INVALID';
      end if;

      update public.mixtapes
      set title=v_title,
          genre=nullif(btrim(coalesce(p_genre,'')),''),
          release_date=p_release_date,
          explicit=nullif(btrim(coalesce(p_explicit,'')),''),
          description=coalesce(p_description,''),
          cover_url=coalesce(v_cover_url,cover_url),
          status='pending'::public.mixtape_status
      where id=p_project_id and artist_id=v_artist_id;

      if jsonb_typeof(coalesce(p_tracks,'[]'::jsonb))<>'array' then raise exception 'TRACKS_INVALID'; end if;

      for v_track in select value from jsonb_array_elements(coalesce(p_tracks,'[]'::jsonb))
      loop
        v_track_id:=nullif(v_track->>'id','')::uuid;
        if v_track_id is null then continue; end if;
        if not exists(
          select 1 from public.tracks
          where id=v_track_id and mixtape_id=p_project_id and artist_id=v_artist_id
        ) then
          raise exception 'TRACK_NOT_FOUND_OR_NOT_OWNED';
        end if;

        v_audio_url:=nullif(btrim(coalesce(v_track->>'audio_url','')),'');
        if v_audio_url is not null and v_audio_url not like 'https://xsofowzvwetamhyuvlpj.supabase.co/storage/v1/object/public/audio/%' then
          raise exception 'AUDIO_URL_INVALID';
        end if;

        update public.tracks
        set track_number=greatest(1,coalesce(nullif(v_track->>'track_number','')::integer,track_number)),
            title=coalesce(nullif(btrim(coalesce(v_track->>'title','')),''),title),
            featured_artist=nullif(btrim(coalesce(v_track->>'featured_artist','')),''),
            audio_url=coalesce(v_audio_url,audio_url)
        where id=v_track_id and mixtape_id=p_project_id and artist_id=v_artist_id;
      end loop;

      return jsonb_build_object('ok',true,'project_id',p_project_id,'status','pending');
    end;
    $function$


-- [40000000718] function public.tgg_creator_projects_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_projects_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist_id uuid;
      v_stage_name text;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id,stage_name into v_artist_id,v_stage_name from public.artists where user_id=v_uid limit 1;
      if v_artist_id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

      return jsonb_build_object(
        'ok',true,
        'version','PROJECTS-ONE-FINAL-1.0',
        'artist',jsonb_build_object('artist_id',v_artist_id,'stage_name',v_stage_name),
        'counts',jsonb_build_object(
          'total',(select count(*) from public.mixtapes where artist_id=v_artist_id),
          'draft',(select count(*) from public.mixtapes where artist_id=v_artist_id and status='draft'),
          'pending',(select count(*) from public.mixtapes where artist_id=v_artist_id and status='pending'),
          'published',(select count(*) from public.mixtapes where artist_id=v_artist_id and status='published'),
          'changes_requested',(select count(*) from public.mixtapes where artist_id=v_artist_id and status='changes_requested')
        ),
        'projects',coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'id',m.id,'title',m.title,'genre',m.genre,'description',m.description,
              'cover_url',m.cover_url,'status',m.status,'release_date',m.release_date,
              'explicit',m.explicit,'admin_note',m.admin_note,'created_at',m.created_at,
              'tracks',coalesce((
                select jsonb_agg(
                  jsonb_build_object(
                    'id',t.id,'track_number',t.track_number,'title',t.title,
                    'featured_artist',t.featured_artist,'audio_url',t.audio_url,
                    'has_secure_audio',coalesce(t.has_secure_audio,t.audio_path is not null)
                  ) order by t.track_number
                )
                from public.tracks t where t.mixtape_id=m.id
              ),'[]'::jsonb)
            ) order by m.created_at desc
          )
          from public.mixtapes m
          where m.artist_id=v_artist_id
        ),'[]'::jsonb),
        'generated_at',now()
      );
    end;
    $function$


-- [40000000719] function public.tgg_creator_promotion_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_promotion_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist_id uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist_id from public.artists where user_id=v_uid limit 1;
      if v_artist_id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

      return jsonb_build_object(
        'ok',true,
        'version','PROMOTION-ONE-FINAL-1.0',
        'counts',jsonb_build_object(
          'draft',(select count(*) from public.promotion_campaigns where creator_id=v_artist_id and status='draft'),
          'pending',(select count(*) from public.promotion_campaigns where creator_id=v_artist_id and status='pending'),
          'approved',(select count(*) from public.promotion_campaigns where creator_id=v_artist_id and status='approved'),
          'active',(select count(*) from public.promotion_campaigns where creator_id=v_artist_id and status='active'),
          'rejected',(select count(*) from public.promotion_campaigns where creator_id=v_artist_id and status='rejected')
        ),
        'campaigns',coalesce((
          select jsonb_agg(to_jsonb(x) order by x.created_at desc)
          from (
            select id,title,description,campaign_type,target_url,image_url,budget_cents,status,admin_note,starts_at,ends_at,created_at,updated_at
            from public.promotion_campaigns
            where creator_id=v_artist_id
            order by created_at desc
            limit 100
          ) x
        ),'[]'::jsonb),
        'generated_at',now()
      );
    end;
    $function$


-- [40000000720] function public.tgg_creator_promotion_create(p_title text, p_description text, p_campaign_type text, p_target_url text, p_image_url text, p_budget_cents bigint, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_submit boolean)
CREATE OR REPLACE FUNCTION public.tgg_creator_promotion_create(p_title text, p_description text DEFAULT NULL::text, p_campaign_type text DEFAULT 'general'::text, p_target_url text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text, p_budget_cents bigint DEFAULT 0, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_submit boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist_id uuid;
      v_id uuid;
      v_title text:=btrim(coalesce(p_title,''));
      v_type text:=lower(btrim(coalesce(p_campaign_type,'general')));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist_id from public.artists where user_id=v_uid limit 1;
      if v_artist_id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;
      if char_length(v_title)<2 or char_length(v_title)>120 then raise exception 'TITLE_INVALID'; end if;
      if p_budget_cents is null or p_budget_cents<0 or p_budget_cents>100000000 then raise exception 'BUDGET_INVALID'; end if;
      if p_starts_at is not null and p_ends_at is not null and p_ends_at<=p_starts_at then raise exception 'DATE_RANGE_INVALID'; end if;
      if v_type not in ('general','release','video','event','merch','profile','radio','short') then v_type:='general'; end if;

      insert into public.promotion_campaigns(
        creator_id,title,description,campaign_type,target_url,image_url,budget_cents,status,starts_at,ends_at
      ) values(
        v_artist_id,v_title,nullif(btrim(coalesce(p_description,'')),''),
        v_type,nullif(btrim(coalesce(p_target_url,'')),''),
        nullif(btrim(coalesce(p_image_url,'')),''),
        p_budget_cents,'draft',p_starts_at,p_ends_at
      )
      returning id into v_id;

      if coalesce(p_submit,false) then
        perform public.tgg_submit_promotion(v_id);
      end if;

      return jsonb_build_object('ok',true,'campaign_id',v_id,'status',case when p_submit then 'pending' else 'draft' end);
    end;
    $function$


-- [40000000721] function public.tgg_creator_public_profile_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_public_profile_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_profile jsonb;
