-- [40000000722] function public.tgg_creator_public_profile_update(p_stage_name text, p_bio text, p_avatar_url text, p_instagram text, p_website text, p_youtube text, p_soundcloud text, p_spotify text)
CREATE OR REPLACE FUNCTION public.tgg_creator_public_profile_update(p_stage_name text, p_bio text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text, p_instagram text DEFAULT NULL::text, p_website text DEFAULT NULL::text, p_youtube text DEFAULT NULL::text, p_soundcloud text DEFAULT NULL::text, p_spotify text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_id uuid;
      v_name text:=btrim(coalesce(p_stage_name,''));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if char_length(v_name)<2 or char_length(v_name)>120 then raise exception 'STAGE_NAME_INVALID'; end if;

      if exists(
        select 1 from public.artists a
        where lower(a.stage_name)=lower(v_name)
          and a.user_id<>v_uid
      ) then raise exception 'STAGE_NAME_TAKEN'; end if;

      update public.artists
      set stage_name=v_name,
          bio=coalesce(p_bio,''),
          avatar_url=nullif(btrim(coalesce(p_avatar_url,'')),''),
          instagram=nullif(btrim(coalesce(p_instagram,'')),''),
          website=nullif(btrim(coalesce(p_website,'')),''),
          youtube=nullif(btrim(coalesce(p_youtube,'')),''),
          soundcloud=nullif(btrim(coalesce(p_soundcloud,'')),''),
          spotify=nullif(btrim(coalesce(p_spotify,'')),'')
      where user_id=v_uid
      returning id into v_id;

      if v_id is null then raise exception 'ARTIST_PROFILE_REQUIRED'; end if;

      return jsonb_build_object(
        'ok',true,
        'artist_id',v_id,
        'profile_url','/p/public-artist-profile.html?artist_id='||v_id::text
      );
    end $function$


-- [40000000723] function public.tgg_creator_recording_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_recording_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  return jsonb_build_object(
    'ok',true,
    'version','RECORDING-ONE-FINAL-1.2',
    'counts',jsonb_build_object(
      'recording_projects',(
        select count(*) from public.tgg_studio_projects p
        where p.project_type='recording'
          and (
            p.user_id=v_uid
            or exists(
              select 1 from public.tgg_studio_project_members m
              where m.project_id=p.id
                and m.user_id=v_uid
                and m.left_at is null
                and (m.can_edit or m.can_record)
            )
          )
      ),
      'owned_recording_projects',(
        select count(*) from public.tgg_studio_projects
        where user_id=v_uid and project_type='recording'
      ),
      'shared_recording_projects',(
        select count(*)
        from public.tgg_studio_projects p
        where p.project_type='recording'
          and p.user_id<>v_uid
          and exists(
            select 1 from public.tgg_studio_project_members m
            where m.project_id=p.id
              and m.user_id=v_uid
              and m.left_at is null
              and (m.can_edit or m.can_record)
          )
      ),
      'sessions',(select count(*) from public.tgg_recording_sessions where user_id=v_uid),
      'open_sessions',(select count(*) from public.tgg_recording_sessions where user_id=v_uid and status in ('open','paused')),
      'takes',(select count(*) from public.tgg_recording_takes where user_id=v_uid),
      'selected_takes',(select count(*) from public.tgg_recording_takes where user_id=v_uid and is_selected=true)
    ),
    'projects',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.updated_at desc)
      from (
        select
          p.id,p.title,p.bpm,p.musical_key,p.status,p.description,p.created_at,p.updated_at,
          (p.user_id=v_uid) as is_owner,
          case
            when p.user_id=v_uid then 'owner'
            else coalesce((
              select m.role
              from public.tgg_studio_project_members m
              where m.project_id=p.id
                and m.user_id=v_uid
                and m.left_at is null
              limit 1
            ),'viewer')
          end as collaboration_role,
          case
            when p.user_id=v_uid then true
            else coalesce((
              select m.can_record
              from public.tgg_studio_project_members m
              where m.project_id=p.id
                and m.user_id=v_uid
                and m.left_at is null
              limit 1
            ),false)
          end as can_record
        from public.tgg_studio_projects p
        where p.project_type='recording'
          and (
            p.user_id=v_uid
            or exists(
              select 1 from public.tgg_studio_project_members m
              where m.project_id=p.id
                and m.user_id=v_uid
                and m.left_at is null
                and (m.can_edit or m.can_record)
            )
          )
        order by p.updated_at desc
        limit 50
      ) x
    ),'[]'::jsonb),
    'sessions',coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id',s.id,'project_id',s.project_id,'title',s.title,'status',s.status,
          'sample_rate',s.sample_rate,'bit_depth',s.bit_depth,'notes',s.notes,
          'started_at',s.started_at,'ended_at',s.ended_at,'updated_at',s.updated_at,
          'takes',coalesce((
            select jsonb_agg(jsonb_build_object(
              'id',t.id,'take_number',t.take_number,'name',t.name,
              'duration_seconds',t.duration_seconds,'is_selected',t.is_selected,
              'notes',t.notes,'created_at',t.created_at
            ) order by t.take_number)
            from public.tgg_recording_takes t
            where t.session_id=s.id and t.user_id=v_uid
          ),'[]'::jsonb)
        ) order by s.updated_at desc
      )
      from public.tgg_recording_sessions s
      where s.user_id=v_uid
    ),'[]'::jsonb),
    'capabilities',jsonb_build_object(
      'create_recording_project',true,
      'start_session',true,
      'pause_session',true,
      'resume_session',true,
      'complete_session',true,
