-- [40000000726] function public.tgg_creator_revenue_summary(p_days integer)
CREATE OR REPLACE FUNCTION public.tgg_creator_revenue_summary(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist uuid;
  v_days integer:=greatest(1,least(coalesce(p_days,30),365));
  v_start timestamptz:=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365)));
  v_total_cents bigint:=0;
  v_paid bigint:=0;
  v_pending bigint:=0;
  v_currency text:='USD';
  v_avg_cents numeric:=0;
  v_daily jsonb:='[]'::jsonb;
  v_recent jsonb:='[]'::jsonb;
  v_test_count bigint:=0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select a.id into v_artist
  from public.artists a
  where a.user_id=v_uid
  order by a.created_at asc
  limit 1;

  if v_artist is null then
    return jsonb_build_object(
      'days',v_days,'currency','USD','revenue',0,'paid_transactions',0,
      'pending_transactions',0,'average_order',0,'daily','[]'::jsonb,'recent','[]'::jsonb,
      'test_verification_transactions_excluded',0,'production_only',true,'generated_at',now()
    );
  end if;

  select
    coalesce(sum(amount_cents),0),
    count(*),
    coalesce(max(currency),'USD')
  into v_total_cents,v_paid,v_currency
  from public.tgg_revenue_events
  where artist_id=v_artist
    and test_mode=false
    and lower(status) in ('completed','paid','succeeded','active')
    and occurred_at>=v_start;

  select count(*) into v_pending
  from public.tgg_revenue_events
  where artist_id=v_artist
    and test_mode=false
    and lower(status) in ('pending','processing','requires_action');

  select count(*) into v_test_count
  from public.tgg_revenue_events
  where artist_id=v_artist and test_mode=true;

  if v_paid>0 then
    v_avg_cents:=v_total_cents::numeric/v_paid;
  end if;

  select coalesce(jsonb_agg(x order by x.day),'[]'::jsonb)
  into v_daily
  from (
    select
      to_char(d.day,'YYYY-MM-DD') as day,
      round(coalesce(sum(r.amount_cents),0)::numeric/100,2) as revenue,
      count(r.id) as transactions
    from generate_series(current_date-(v_days-1),current_date,interval '1 day') d(day)
    left join public.tgg_revenue_events r
      on r.artist_id=v_artist
     and r.test_mode=false
     and lower(r.status) in ('completed','paid','succeeded','active')
     and r.occurred_at::date=d.day::date
    group by d.day
  ) x;

  select coalesce(jsonb_agg(x order by x.updated_at desc),'[]'::jsonb)
  into v_recent
  from (
    select
      id,
      source_kind,
      source_id,
      status,
      round(amount_cents::numeric/100,2) as amount,
      currency,
      external_id,
      occurred_at as created_at,
      updated_at
    from public.tgg_revenue_events
    where artist_id=v_artist
      and test_mode=false
    order by updated_at desc
    limit 10
  ) x;

  return jsonb_build_object(
    'days',v_days,
    'currency',upper(v_currency),
    'revenue',round(v_total_cents::numeric/100,2),
    'paid_transactions',v_paid,
    'pending_transactions',v_pending,
    'average_order',round(v_avg_cents/100,2),
    'daily',v_daily,
    'recent',v_recent,
    'test_verification_transactions_excluded',v_test_count,
    'production_only',true,
    'ledger','tgg_revenue_events',
    'generated_at',now()
  );
end;
$function$


