-- [40000000729] function public.tgg_creator_settings_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_settings_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist public.artists;
      v_prefs jsonb;
      v_checkout jsonb;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

      select * into v_artist
      from public.artists
      where user_id=v_uid
      order by created_at
      limit 1;

      if v_artist.id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

      select to_jsonb(p)-'user_id'
      into v_prefs
      from public.notification_preferences p
      where p.user_id=v_uid;

      v_checkout:=public.tgg_membership_checkout_final_health();

      return jsonb_build_object(
        'ok',true,
        'version','SETTINGS-ONE-FINAL-1.0',
        'profile',jsonb_build_object(
          'artist_id',v_artist.id,
          'stage_name',v_artist.stage_name,
          'bio',v_artist.bio,
          'avatar_url',v_artist.avatar_url,
          'instagram',v_artist.instagram,
          'website',v_artist.website,
          'youtube',v_artist.youtube,
          'soundcloud',v_artist.soundcloud,
          'spotify',v_artist.spotify
        ),
        'notifications',coalesce(v_prefs,jsonb_build_object(
          'follows_enabled',true,
          'saves_enabled',true,
          'reactions_enabled',true,
          'comments_enabled',true,
          'collaboration_enabled',true
        )),
        'payments',jsonb_build_object(
          'checkout_runtime_configured',coalesce((v_checkout->>'checkout_runtime_configured')::boolean,false),
          'creator_payout_connected',coalesce((v_checkout->>'creator_payout_connected')::boolean,false),
          'stripe_onboarding_complete',v_artist.stripe_onboarding_complete,
          'payouts_enabled',v_artist.payouts_enabled
        ),
        'capabilities',jsonb_build_object(
          'update_profile',true,
          'update_notifications',true,
          'reset_password',true,
          'sign_out',true
        ),
        'generated_at',now()
      );
    end;
    $function$


