-- [40000000731] function public.tgg_creator_smart_link_template(p_release_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_creator_smart_link_template(p_release_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_release public.mixtapes;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

      if p_release_id is not null then
        select * into v_release
        from public.mixtapes
        where id=p_release_id
          and user_id=v_uid;
        if v_release.id is null then raise exception 'RELEASE_NOT_FOUND_OR_NOT_OWNED'; end if;
      end if;

      return jsonb_build_object(
        'ok',true,
        'release',case when v_release.id is null then null else jsonb_build_object(
          'id',v_release.id,'title',v_release.title,'cover_url',v_release.cover_url,'genre',v_release.genre
        ) end,
        'destinations',jsonb_build_array(
          jsonb_build_object('provider','spotify','label','Spotify','url',''),
          jsonb_build_object('provider','apple_music','label','Apple Music','url',''),
          jsonb_build_object('provider','youtube_music','label','YouTube Music','url',''),
          jsonb_build_object('provider','youtube','label','YouTube','url',''),
          jsonb_build_object('provider','soundcloud','label','SoundCloud','url',''),
          jsonb_build_object('provider','tidal','label','TIDAL','url',''),
          jsonb_build_object('provider','audiomack','label','Audiomack','url',''),
          jsonb_build_object('provider','bandcamp','label','Bandcamp','url',''),
          jsonb_build_object('provider','deezer','label','Deezer','url',''),
          jsonb_build_object('provider','amazon_music','label','Amazon Music','url','')
        ),
        'tgg_destination',case when v_release.id is null then null else
          'https://trugogettamixtapes.blogspot.com/p/mixtape.html?id='||v_release.id::text end
      );
    end $function$


-- [40000000732] function public.tgg_creator_smart_links_bundle(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_creator_smart_links_bundle(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_limit integer:=greatest(1,least(coalesce(p_limit,100),200));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'version','SMART-LINKS-ONE-FINAL-1.2',
    'counts',jsonb_build_object(
      'links',(select count(*) from public.tgg_smart_links where owner_user_id=v_uid),
      'active',(select count(*) from public.tgg_smart_links where owner_user_id=v_uid and is_active),
      'destination_clicks',(select coalesce(sum(click_count),0) from public.tgg_smart_links where owner_user_id=v_uid),
      'events_30d',(
        select count(*) from public.tgg_smart_link_events e
        join public.tgg_smart_links l on l.id=e.link_id
        where l.owner_user_id=v_uid and e.occurred_at>=now()-interval '30 days'
      )
    ),
    'links',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',l.id,'title',l.title,'slug',l.slug,'release_id',l.release_id,'destination_type',l.destination_type,
        'destinations',l.destinations,'click_count',l.click_count,'is_active',l.is_active,
        'public_url','/p/smart-link.html?slug='||l.slug,'created_at',l.created_at,'updated_at',l.updated_at,
        'events_30d',(
          select count(*) from public.tgg_smart_link_events e
          where e.link_id=l.id and e.occurred_at>=now()-interval '30 days'
        ),
        'provider_clicks_30d',coalesce((
          select jsonb_object_agg(x.destination,x.cnt)
          from (
            select coalesce(e.destination,'unknown') destination,count(*) cnt
            from public.tgg_smart_link_events e
            where e.link_id=l.id and e.event_type='destination_click'
              and e.occurred_at>=now()-interval '30 days'
            group by coalesce(e.destination,'unknown')
          ) x
        ),'{}'::jsonb)
      ) order by l.created_at desc)
      from (
        select * from public.tgg_smart_links
        where owner_user_id=v_uid
        order by created_at desc
        limit v_limit
      ) l
    ),'[]'::jsonb),
    'providers',jsonb_build_array(
      'spotify','apple_music','youtube','youtube_music','soundcloud','tidal',
      'audiomack','bandcamp','deezer','amazon_music','tgg'
    ),
    'generated_at',now()
  );
end $function$


