    $function$


-- [40000000736] function public.tgg_creator_supporters_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_supporters_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_base jsonb;
  v_checkout jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select a.id into v_artist_id
  from public.artists a
  where a.user_id=v_uid
  order by a.created_at
  limit 1;

  if v_artist_id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

  v_base:=public.tgg_get_creator_supporters_revenue_bundle(v_artist_id);
  v_checkout:=public.tgg_membership_checkout_final_health();

  return jsonb_build_object(
    'ok',true,
    'artist_id',v_artist_id,
    'supporters',v_base,
    'counts',jsonb_build_object(
      'tiers',(select count(*) from public.tgg_membership_tiers where artist_id=v_artist_id),
      'active_tiers',(select count(*) from public.tgg_membership_tiers where artist_id=v_artist_id and is_active=true),
      'memberships',(select count(*) from public.tgg_memberships where artist_id=v_artist_id),
      'active_memberships',(select count(*) from public.tgg_memberships where artist_id=v_artist_id and status='active'),
      'vault_items',(select count(*) from public.tgg_vault_items where artist_id=v_artist_id)
    ),
    'tiers',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',t.id,
        'name',t.name,
        'description',t.description,
        'price_cents',t.price_cents,
        'benefits',t.benefits,
        'is_active',t.is_active,
        'payment_link_configured',t.stripe_payment_link_url is not null,
        'payment_link_verified',coalesce(t.stripe_payment_link_verified,false),
        'stripe_payment_link_url',t.stripe_payment_link_url,
        'stripe_product_id',t.stripe_product_id,
        'stripe_price_id',t.stripe_price_id,
        'created_at',t.created_at,
        'updated_at',t.updated_at
      ) order by t.created_at desc)
      from public.tgg_membership_tiers t
      where t.artist_id=v_artist_id
    ),'[]'::jsonb),
    'checkout',v_checkout,
    'vault',jsonb_build_object(
      'count',(select count(*) from public.tgg_vault_items where artist_id=v_artist_id),
      'published_count',(select count(*) from public.tgg_vault_items where artist_id=v_artist_id and published_at is not null),
      'items',coalesce((
        select jsonb_agg(jsonb_build_object(
          'id',v.id,
          'title',v.title,
          'item_type',v.item_type,
          'description',v.description,
          'min_tier_id',v.min_tier_id,
          'published_at',v.published_at,
          'created_at',v.created_at
        ) order by v.created_at desc)
        from public.tgg_vault_items v
        where v.artist_id=v_artist_id
      ),'[]'::jsonb)
    ),
    'capabilities',jsonb_build_object(
      'create_tier',true,
      'attach_payment_link',true,
      'activate_tier',true,
      'finalize_vault_upload',true,
      'membership_checkout',coalesce((v_checkout->>'can_accept_memberships')::boolean,false)
    )
  );
end
$function$


-- [40000000737] function public.tgg_creator_transaction_atomicity_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_transaction_atomicity_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
with checks(name,ok) as (
  values
    (
      'call_room_plus_participants',
      pg_get_functiondef('public.tgg_start_call_room(uuid,text)'::regprocedure)
        ilike '%insert into public.tgg_call_rooms%'
      and pg_get_functiondef('public.tgg_start_call_room(uuid,text)'::regprocedure)
        ilike '%insert into public.tgg_call_participants%'
      and pg_get_functiondef('public.tgg_start_call_room(uuid,text)'::regprocedure)
        ilike '%tgg_creator_mutation_audit_log%'
    ),
    (
      'studio_finalize_plus_vault',
      pg_get_functiondef('public.tgg_finalize_studio_upload(uuid,text,text,text,text,bigint,jsonb)'::regprocedure)
        ilike '%tgg_register_studio_asset%'
      and pg_get_functiondef('public.tgg_finalize_studio_upload(uuid,text,text,text,text,bigint,jsonb)'::regprocedure)
        ilike '%tgg_register_media_vault_asset%'
      and pg_get_functiondef('public.tgg_finalize_studio_upload(uuid,text,text,text,text,bigint,jsonb)'::regprocedure)
        ilike '%tgg_mark_media_upload_finalized%'
    ),
    (
      'live_replay_plus_vault',
      pg_get_functiondef('public.tgg_live_studio_finalize_replay(uuid,text,numeric,text,jsonb)'::regprocedure)
        ilike '%insert into public.tgg_live_replays%'
      and pg_get_functiondef('public.tgg_live_studio_finalize_replay(uuid,text,numeric,text,jsonb)'::regprocedure)
        ilike '%tgg_register_media_vault_asset%'
      and pg_get_functiondef('public.tgg_live_studio_finalize_replay(uuid,text,numeric,text,jsonb)'::regprocedure)
        ilike '%tgg_mark_media_upload_finalized%'
    ),
    (
      'membership_activation_business_write_isolated_from_monitoring',
      pg_get_functiondef('public.tgg_membership_tier_set_active(uuid,boolean)'::regprocedure)
        ilike '%update public.tgg_membership_tiers%'
      and pg_get_functiondef('public.tgg_membership_tier_set_active(uuid,boolean)'::regprocedure)
        ilike '%exception when others%'
      and pg_get_functiondef('public.tgg_membership_tier_set_active(uuid,boolean)'::regprocedure)
        ilike '%operational_sync%'
    )
),
agg as (
  select
    count(*) total,
    count(*) filter(where ok) ready,
    coalesce(jsonb_agg(name order by name) filter(where not ok),'[]'::jsonb) failed
  from checks
)
select jsonb_build_object(
  'ok',ready=total,
  'version','CREATOR-TRANSACTION-ATOMICITY-1.0',
  'ready',ready,
  'total',total,
  'failed',failed,
  'checks',(select jsonb_object_agg(name,ok order by name) from checks),
  'generated_at',now()
)
from agg;
$function$


-- [40000000738] function public.tgg_creator_tv_bundle()
CREATE OR REPLACE FUNCTION public.tgg_creator_tv_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 return jsonb_build_object(
  'ok',true,'version','CREATOR-TV-ONE-FINAL-1.0',
  'counts',jsonb_build_object(
   'channels',(select count(*) from public.tgg_tv_channels where owner_user_id=v_uid),
   'episodes',(select count(*) from public.tgg_tv_episodes where owner_user_id=v_uid),
   'pending',(select count(*) from public.tgg_tv_episodes where owner_user_id=v_uid and status='pending'),
   'published',(select count(*) from public.tgg_tv_episodes where owner_user_id=v_uid and status='published')
  ),
  'channels',coalesce((select jsonb_agg(jsonb_build_object(
    'id',c.id,'title',c.title,'slug',c.slug,'status',c.status,'artwork_url',c.artwork_url,'banner_url',c.banner_url,
    'episode_count',(select count(*) from public.tgg_tv_episodes e where e.channel_id=c.id),
    'published_count',(select count(*) from public.tgg_tv_episodes e where e.channel_id=c.id and e.status='published')
  ) order by c.created_at desc) from public.tgg_tv_channels c where c.owner_user_id=v_uid),'[]'::jsonb),
  'episodes',coalesce((select jsonb_agg(jsonb_build_object(
    'id',e.id,'channel_id',e.channel_id,'title',e.title,'episode_type',e.episode_type,'status',e.status,'visibility',e.visibility,
    'thumbnail_url',e.thumbnail_url,'duration_seconds',e.duration_seconds,'season_number',e.season_number,'episode_number',e.episode_number,'admin_note',e.admin_note
  ) order by e.created_at desc) from public.tgg_tv_episodes e where e.owner_user_id=v_uid),'[]'::jsonb),
  'capabilities',jsonb_build_object('channels',true,'series',true,'live_replays',true,'music_videos',true,'watchlists',true,'history',true,'admin_review',true),
  'generated_at',now()
 );
end $function$


-- [40000000739] function public.tgg_creator_ui_action_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_ui_action_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with rpc_names(name) as (
  values
  ('tgg_activation_bridge_bundle'),
  ('tgg_activation_consistency_alerts'),
  ('tgg_activation_queue_consistency_audit'),
  ('tgg_activation_state_history'),
  ('tgg_auth_final_health'),
  ('tgg_blogger_reconnect_link_create'),
  ('tgg_call_validation_invite_claim'),
  ('tgg_call_validation_invite_create'),
  ('tgg_cancel_collaboration_request'),
  ('tgg_code_sync_workspace'),
  ('tgg_creator_access_readiness'),
  ('tgg_creator_distribution_package'),
  ('tgg_creator_first_use_bundle'),
  ('tgg_creator_ui_action_readiness'),
  ('tgg_creator_workflow_readiness'),
  ('tgg_distribution_master_candidates'),
  ('tgg_distribution_master_detach'),
  ('tgg_distribution_master_reuse_bundle'),
  ('tgg_distribution_master_reuse_confirm'),
  ('tgg_distribution_master_select'),
  ('tgg_distribution_metadata_upsert'),
  ('tgg_distribution_resolution_bundle'),
  ('tgg_distribution_track_duration_set'),
  ('tgg_external_completion_state'),
  ('tgg_get_creator_app_startup_bundle'),
  ('tgg_get_creator_dashboard_bundle'),
  ('tgg_get_creator_navigation_state'),
  ('tgg_get_creator_release_workspace_bundle'),
  ('tgg_get_creator_workspace_schema'),
  ('tgg_launch_closeout_summary'),
  ('tgg_launch_readiness'),
  ('tgg_launch_readiness_final'),
  ('tgg_master_owner_dashboard'),
  ('tgg_master_owner_queue_change'),
  ('tgg_master_owner_set_site'),
  ('tgg_master_owner_upsert_shared_setting'),
  ('tgg_membership_tier_create'),
  ('tgg_membership_tier_set_active'),
  ('tgg_one_final_activation_queue'),
  ('tgg_one_final_activation_queue_refresh'),
  ('tgg_one_final_system_health'),
  ('tgg_owner_provider_completion_checklist'),
  ('tgg_owner_provider_handoff'),
  ('tgg_provider_acceptance_matrix'),
  ('tgg_provider_activation_stage'),
  ('tgg_provider_activation_staging_status'),
  ('tgg_provider_activation_verify'),
  ('tgg_respond_collaboration_request'),
  ('tgg_runtime_drift_guard'),
  ('tgg_save_listening_progress'),
  ('tgg_send_message'),
  ('tgg_set_creator_action_status'),
  ('tgg_set_creator_ui_preferences'),
  ('tgg_start_call_room'),
  ('tgg_store_provider_secret'),
  ('tgg_toggle_release_save')
),
rpc_state as (
  select
    r.name,
    count(p.oid) filter(where n.nspname='public')>0 as present,
    coalesce(bool_or(has_function_privilege('authenticated',p.oid,'EXECUTE')) filter(where n.nspname='public'),false) as auth_exec
  from rpc_names r
  left join pg_proc p on p.proname=r.name
  left join pg_namespace n on n.oid=p.pronamespace
  group by r.name
),
workspace_rpc(key,rpc_name) as (
  values
  ('dashboard','tgg_get_creator_dashboard_bundle'),
  ('releases','tgg_get_creator_release_workspace_bundle'),
  ('fans','tgg_get_creator_fan_crm_bundle'),
  ('growth','tgg_get_creator_growth_workspace_bundle'),
  ('messages','tgg_get_creator_communications_bundle'),
  ('live','tgg_get_creator_live_booking_bundle'),
  ('opportunities','tgg_get_creator_opportunity_bundle'),
  ('supporters','tgg_get_creator_supporters_revenue_bundle'),
  ('career','tgg_get_creator_career_workspace_bundle'),
  ('library','tgg_get_user_music_library_bundle'),
  ('expansion','tgg_creator_expansion_control_center')
),
workspace_state as (
  select w.key,
         exists(
           select 1
           from pg_proc p
           join pg_namespace n on n.oid=p.pronamespace
           where n.nspname='public'
             and p.proname=w.rpc_name
             and has_function_privilege('authenticated',p.oid,'EXECUTE')
         ) as ready
  from workspace_rpc w
),
external_paths(path) as (
  values
  ('/p/create-hub.html'),('/p/recording-studio.html'),('/p/beat-studio.html'),
  ('/p/video-studio.html'),('/p/music-hub.html'),('/p/artist-world.html'),
  ('/p/creator-store.html'),('/p/backstage.html'),('/p/vault.html'),('/p/games-tv.html')
),
external_state as (
  select e.path,
         exists(select 1 from public.tgg_site_routes r where r.path=e.path and r.is_active) as active
  from external_paths e
),
agg as (
  select
    (select count(*) from rpc_state) rpc_total,
    (select count(*) from rpc_state where present and auth_exec) rpc_ready,
    (select coalesce(jsonb_agg(name order by name),'[]'::jsonb) from rpc_state where not present or not auth_exec) rpc_failed,
    (select count(*) from workspace_state) workspace_total,
    (select count(*) from workspace_state where ready) workspace_ready,
    (select coalesce(jsonb_agg(key order by key),'[]'::jsonb) from workspace_state where not ready) workspace_failed,
    (select count(*) from external_state) external_total,
    (select count(*) from external_state where active) external_ready,
    (select coalesce(jsonb_agg(path order by path),'[]'::jsonb) from external_state where not active) external_failed
)
select jsonb_build_object(
  'ok',
    rpc_ready=rpc_total
    and workspace_ready=workspace_total
    and external_ready=external_total,
  'version','UI-ACTION-QA-1.3',
  'rpc_references',jsonb_build_object(
    'ready',rpc_ready,'total',rpc_total,'failed',rpc_failed
  ),
  'internal_workspaces',jsonb_build_object(
    'ready',workspace_ready,'total',workspace_total,'failed',workspace_failed
  ),
  'external_destinations',jsonb_build_object(
    'ready',external_ready,'total',external_total,'failed',external_failed
  ),
  'consolidated_internal_tiles',jsonb_build_array(
    'Collaboration → messages',
    'Live → live',
    'Career OS → career'
  ),
  'generated_at',now()
)
from agg;
$function$


-- [40000000740] function public.tgg_creator_upload_bootstrap(p_suggested_stage_name text)
CREATE OR REPLACE FUNCTION public.tgg_creator_upload_bootstrap(p_suggested_stage_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_artist public.artists;
      v_name text:=btrim(coalesce(p_suggested_stage_name,''));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

      select * into v_artist
      from public.artists
      where user_id=v_uid
      order by created_at
      limit 1;

      if v_artist.id is null then
        if char_length(v_name)<2 then v_name:='Artist'; end if;
        v_name:=left(v_name,80);

        if exists(select 1 from public.artists where lower(stage_name)=lower(v_name)) then
          v_name:=left(v_name,68)||'-'||left(replace(v_uid::text,'-',''),8);
        end if;

        insert into public.artists(user_id,stage_name)
        values(v_uid,v_name)
        returning * into v_artist;
      end if;

      return jsonb_build_object(
        'ok',true,
        'version','UPLOAD-BOOTSTRAP-ONE-FINAL-1.0',
        'artist_id',v_artist.id,
        'stage_name',v_artist.stage_name,
        'user_id',v_uid
      );
    end;
    $function$


-- [40000000741] function public.tgg_creator_workflow_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_workflow_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with launch as (select public.tgg_launch_readiness() j),
checks as (
  select * from (values
    ('studio_pipeline','READY',
      has_function_privilege('authenticated','public.tgg_studio_create_project(text,text,numeric,text,text)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_finalize_studio_upload(uuid,text,text,text,text,bigint,jsonb)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_studio_save_version(uuid,text)','EXECUTE')
      and position('tgg_media_vault_assets' in pg_get_functiondef('public.tgg_finalize_studio_upload(uuid,text,text,text,text,bigint,jsonb)'::regprocedure))>0,
      'Studio create → secure upload → version → Vault registration'),
    ('beat_to_studio','READY',
      has_function_privilege('authenticated','public.tgg_studio_create_project(text,text,numeric,text,text)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_beat_pattern_save(uuid,text,numeric,integer,jsonb,uuid)','EXECUTE')
      and to_regclass('public.tgg_studio_projects') is not null
      and to_regclass('public.tgg_beat_patterns') is not null,
      'Beat projects use the shared Studio project backbone'),
    ('studio_collaboration','READY',
      has_function_privilege('authenticated','public.tgg_studio_project_collab_invite(uuid,uuid,text,text)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_studio_project_collab_respond(uuid,boolean)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_studio_project_presence_upsert(uuid,text,text,text,jsonb,jsonb)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_studio_project_apply_patch(uuid,text,text,text,jsonb,bigint)','EXECUTE'),
      'Invite → shared presence/control state → revisioned project patches'),
    ('video_pipeline','READY',
      has_function_privilege('authenticated','public.tgg_finalize_video_upload(uuid,text,text,text,bigint,numeric,integer,integer,jsonb)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_video_submit_from_storage(text,text,text,text,date,boolean,text,boolean)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_video_publish(uuid)','EXECUTE')
      and coalesce((public.tgg_video_pipeline_final_health()->>'ok')::boolean,false),
      'Video upload → Vault registration → submit/publish'),
    ('live_to_replay',
      case when coalesce(((select j->'live'->>'sfu_turn_connected' from launch))::boolean,false) then 'READY' else 'READY_WITH_FALLBACK' end,
      has_function_privilege('authenticated','public.tgg_live_studio_create(text,text,text,text,text,boolean,boolean,boolean,boolean,boolean,boolean,boolean,text)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_live_start(uuid)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_live_end(uuid)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_live_studio_finalize_replay(uuid,text,numeric,text,jsonb)','EXECUTE')
      and position('vault_registered' in pg_get_functiondef('public.tgg_live_studio_finalize_replay(uuid,text,numeric,text,jsonb)'::regprocedure))>0,
      'Live control plane → recording → replay → Vault + Video Studio handoff'),
    ('messages_attachments','READY',
      has_function_privilege('authenticated','public.tgg_send_message(uuid,text,text,uuid)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_finalize_message_upload(uuid,text,text,bigint,text,jsonb)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_get_message_attachment_manifest(uuid)','EXECUTE'),
      'Message → secure attachment upload → attachment manifest'),
    ('calls',
      case when coalesce(((select j->'calls'->>'two_user_validated' from launch))::boolean,false) then 'READY' else 'VALIDATION_REQUIRED' end,
      has_function_privilege('authenticated','public.tgg_start_call_room(uuid,text)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_call_signal_send(uuid,text,jsonb,uuid)','EXECUTE'),
      'Core room/signaling ready; real two-user proof tracked separately'),
    ('vault','READY',
      has_function_privilege('authenticated','public.tgg_finalize_vault_upload(text,text,text,text,bigint,numeric,integer,integer,jsonb)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_vault_item_create(text,text,text,uuid)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_attach_vault_media(uuid,uuid)','EXECUTE'),
      'Secure media Vault upload → Vault item → attach media'),
    ('store_checkout',
      case when (select j->'payments'->>'safe_mode' from launch)='native_stripe' then 'READY' else 'READY_WITH_FALLBACK' end,
      has_function_privilege('authenticated','public.tgg_store_product_create(text,text,text,integer,text,text,integer,text)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_store_product_set_payment_link(uuid,text)','EXECUTE')
      and ((select j->'payments'->>'safe_mode' from launch) in ('native_stripe','payment_link_fallback')),
      'Product create/update plus production-safe Stripe checkout mode'),
    ('audiobook_publish','READY',
      has_function_privilege('authenticated','public.tgg_audiobook_create_draft(text,text,text,text,text,text,text,boolean,boolean)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_audiobook_add_chapter_from_storage(uuid,integer,text,text,numeric,boolean)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_audiobook_submit(uuid)','EXECUTE')
      and to_regprocedure('public.tgg_public_audiobooks_feed(integer)') is not null,
      'Audiobook draft → storage chapters → submit → public feed'),
    ('game_sessions','READY',
      has_function_privilege('authenticated','public.tgg_game_create_draft(text,text,jsonb,timestamp with time zone)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_game_session_create(uuid)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_game_session_join(uuid)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_game_session_start(uuid)','EXECUTE')
      and has_function_privilege('authenticated','public.tgg_game_session_end(uuid)','EXECUTE')
      and to_regprocedure('public.tgg_public_game_leaderboard(uuid)') is not null,
      'Create game → create/join/start/end session → public leaderboard'),
    ('public_publish','READY',
      to_regprocedure('public.tgg_public_video_feed(integer)') is not null
      and to_regprocedure('public.tgg_public_audiobooks_feed(integer)') is not null
      and to_regprocedure('public.tgg_public_games_bundle(integer)') is not null
      and to_regprocedure('public.tgg_public_live_bundle(uuid)') is not null
      and jsonb_array_length(coalesce(public.tgg_public_one_final_bundle()->'releases','[]'::jsonb))>0,
      'Public release/video/audiobook/game/live read paths are present')
  ) v(workflow_key,status,ready,detail)
),
agg as (
  select count(*) total,
         count(*) filter(where ready) ready_count,
         count(*) filter(where status='READY') full_ready,
         count(*) filter(where status='READY_WITH_FALLBACK') fallback_ready,
         count(*) filter(where status='VALIDATION_REQUIRED') validation_required,
         jsonb_object_agg(workflow_key,jsonb_build_object('status',status,'ready',ready,'detail',detail)) workflows
  from checks
)
select jsonb_build_object(
  'ok',ready_count=total,
  'version','WORKFLOW-READINESS-1.1',
  'ready_count',ready_count,
  'total',total,
  'full_ready',full_ready,
  'fallback_ready',fallback_ready,
  'validation_required',validation_required,
  'workflows',workflows,
  'generated_at',now()
)
from agg;
$function$


-- [40000000742] function public.tgg_creator_world_bundle(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_creator_world_bundle(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_limit integer:=greatest(1,least(coalesce(p_limit,50),100));
    begin
      return jsonb_build_object(
        'ok',true,
        'me',case when v_uid is null then null else (
          select jsonb_build_object('artist_id',id,'stage_name',stage_name,'avatar_url',avatar_url)
          from public.artists where user_id=v_uid limit 1
        ) end,
        'stories',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',s.id,'user_id',s.user_id,'story_type',s.story_type,'caption',s.caption,
            'media_url',s.media_url,'linked_release_id',s.linked_release_id,'created_at',s.created_at,'expires_at',s.expires_at,
            'artist',jsonb_build_object('artist_id',a.id,'stage_name',a.stage_name,'avatar_url',a.avatar_url),
            'following',case when v_uid is null then false else exists(select 1 from public.artist_follows f where f.user_id=v_uid and f.artist_id=a.id) end
          ) order by s.created_at desc)
          from (
            select * from public.tgg_stories where expires_at>now() order by created_at desc limit v_limit
          ) s
          left join public.artists a on a.user_id=s.user_id
        ),'[]'::jsonb),
        'artists',coalesce((
          select jsonb_agg(jsonb_build_object(
            'artist_id',a.id,'stage_name',a.stage_name,'avatar_url',a.avatar_url,'bio',a.bio,
            'following',case when v_uid is null then false else exists(select 1 from public.artist_follows f where f.user_id=v_uid and f.artist_id=a.id) end
          ) order by a.stage_name)
          from (select * from public.artists order by stage_name limit v_limit) a
        ),'[]'::jsonb)
      );
    end $function$


-- [40000000743] function public.tgg_creator_write_validation_readiness()
CREATE OR REPLACE FUNCTION public.tgg_creator_write_validation_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
with checks(name,ok) as (
  values
    ('messages_body', exists(select 1 from pg_constraint where conname='tgg_messages_body_check' and convalidated)),
    ('mixtape_title', exists(select 1 from pg_constraint where conname='mixtapes_title_len_check' and convalidated)),
    ('mixtape_description', exists(select 1 from pg_constraint where conname='mixtapes_description_len_check' and convalidated)),
    ('track_title', exists(select 1 from pg_constraint where conname='tracks_title_len_check' and convalidated)),
    ('track_number_positive', exists(select 1 from pg_constraint where conname='tracks_track_number_positive_check' and convalidated)),
    ('studio_project_title', exists(select 1 from pg_constraint where conname='tgg_studio_projects_title_len' and convalidated)),
    ('studio_project_bpm', exists(select 1 from pg_constraint where conname='tgg_studio_projects_bpm_range' and convalidated)),
    ('studio_asset_name', exists(select 1 from pg_constraint where conname='tgg_studio_assets_name_len' and convalidated)),
    ('membership_name', exists(select 1 from pg_constraint where conname='tgg_membership_tiers_name_check' and convalidated)),
    ('membership_description', exists(select 1 from pg_constraint where conname='tgg_membership_tiers_description_len_check' and convalidated)),
    ('membership_benefits_shape', exists(select 1 from pg_constraint where conname='tgg_membership_tiers_benefits_shape_check' and convalidated)),
    ('membership_benefits_size', exists(select 1 from pg_constraint where conname='tgg_membership_tiers_benefits_size_check' and convalidated)),
    ('distribution_label', exists(select 1 from pg_constraint where conname='tgg_distribution_label_len_check' and convalidated)),
    ('distribution_copyright', exists(select 1 from pg_constraint where conname='tgg_distribution_copyright_len_check' and convalidated)),
    ('distribution_publishing', exists(select 1 from pg_constraint where conname='tgg_distribution_publishing_len_check' and convalidated)),
    ('distribution_language', exists(select 1 from pg_constraint where conname='tgg_distribution_language_len_check' and convalidated)),
    ('distribution_notes', exists(select 1 from pg_constraint where conname='tgg_distribution_notes_len_check' and convalidated)),
    ('distribution_territories_array', exists(select 1 from pg_constraint where conname='tgg_distribution_territories_array' and convalidated)),
    ('distribution_territories_size', exists(select 1 from pg_constraint where conname='tgg_distribution_territories_size_check' and convalidated)),
    ('membership_rpc_aligned', exists(
      select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='public' and p.proname='tgg_membership_tier_create'
        and pg_get_functiondef(p.oid) ilike '%>80%'
        and pg_get_functiondef(p.oid) ilike '%DESCRIPTION_TOO_LONG%'
        and pg_get_functiondef(p.oid) ilike '%BENEFITS_TOO_LARGE%'
    )),
    ('distribution_rpc_guarded', exists(
      select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='public' and p.proname='tgg_distribution_metadata_upsert'
        and pg_get_functiondef(p.oid) ilike '%TERRITORIES_TOO_LARGE%'
        and pg_get_functiondef(p.oid) ilike '%LABEL_NAME_TOO_LONG%'
        and pg_get_functiondef(p.oid) ilike '%NOTES_TOO_LONG%'
    ))
),
agg as (
  select
    count(*) total,
    count(*) filter(where ok) ready,
    coalesce(jsonb_agg(name order by name) filter(where not ok),'[]'::jsonb) failed
  from checks
),
violations as (
  select
    (select count(*) from public.mixtapes where char_length(title)<1 or char_length(title)>180 or (description is not null and char_length(description)>5000))
    +(select count(*) from public.tracks where char_length(title)<1 or char_length(title)>180 or (track_number is not null and track_number<=0))
    +(select count(*) from public.tgg_membership_tiers where (description is not null and char_length(description)>2000) or octet_length(benefits::text)>16384 or jsonb_typeof(benefits) not in ('array','object'))
    +(select count(*) from public.tgg_distribution_release_metadata where
       (label_name is not null and char_length(label_name)>500)
       or (copyright_line is not null and char_length(copyright_line)>500)
       or (publishing_line is not null and char_length(publishing_line)>500)
       or char_length(primary_language)<2 or char_length(primary_language)>20
       or (notes is not null and char_length(notes)>5000)
       or octet_length(territories::text)>16384
       or jsonb_typeof(territories)<>'array')
    as n
)
select jsonb_build_object(
  'ok',a.ready=a.total and v.n=0,
  'version','CREATOR-WRITE-VALIDATION-1.0',
  'contracts',jsonb_build_object('ready',a.ready,'total',a.total,'failed',a.failed),
  'violations',v.n,
  'generated_at',now()
)
from agg a cross join violations v;
$function$


-- [40000000744] function public.tgg_dashboard_growth_pulse()
CREATE OR REPLACE FUNCTION public.tgg_dashboard_growth_pulse()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_coach jsonb;
  v_weekly jsonb;
  v_retention jsonb;
  v_wins jsonb;
  v_brain jsonb;
  v_top_action jsonb;
  v_week_done integer:=0;
  v_week_total integer:=0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  v_coach:=public.tgg_growth_coach_refresh();
  v_weekly:=public.tgg_growth_weekly_refresh();
  v_retention:=public.tgg_creator_retention_pulse();
  v_wins:=public.tgg_growth_wins_summary();
  v_brain:=public.tgg_growth_brain_refresh();

  select to_jsonb(x) into v_top_action
  from (
    select id,title,rationale,priority,due_at,action_type
    from public.tgg_creator_action_queue
    where owner_user_id=v_uid and source_type='growth' and status='open'
    order by priority desc,created_at asc
    limit 1
  ) x;

  v_week_total:=jsonb_array_length(coalesce(v_weekly->'missions','[]'::jsonb));
  select count(*) into v_week_done
  from jsonb_array_elements(coalesce(v_weekly->'missions','[]'::jsonb)) j
  where j->>'status'='completed';

  return jsonb_build_object(
    'ok',true,
    'version','DASHBOARD-GROWTH-PULSE-1.0',
    'top_action',v_top_action,
    'weekly',jsonb_build_object(
      'completed',v_week_done,
      'total',v_week_total,
      'streak',coalesce((v_weekly->'streak'->>'current_streak')::int,0),
      'missions',coalesce(v_weekly->'missions','[]'::jsonb)
    ),
    'since_last_visit',coalesce(v_retention->'since_last_visit','{}'::jsonb),
    'current',coalesce(v_retention->'current','{}'::jsonb),
    'momentum',jsonb_build_object(
      'trend',coalesce(v_wins->>'trend','starting'),
      'score_7d',coalesce((v_wins->'last_7_days'->>'momentum_score')::bigint,0),
      'score_30d',coalesce((v_wins->'last_30_days'->>'momentum_score')::bigint,0)
    ),
    'brain',v_brain,
    'generated_at',now()
  );
end
$function$


-- [40000000745] function public.tgg_database_final_health()
CREATE OR REPLACE FUNCTION public.tgg_database_final_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
      select jsonb_build_object(
        'ok',true,
        'version','DB-ONE-FINAL-1.0',
        'security',jsonb_build_object(
          'exposed_tables_without_rls',(
            select count(*)
            from pg_class c
            join pg_namespace n on n.oid=c.relnamespace
            where n.nspname='public' and c.relkind='r'
              and c.relrowsecurity=false
              and (
                has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE')
                or has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE')
              )
          ),
          'client_views_without_security_invoker',(
            select count(*)
            from pg_class c
            join pg_namespace n on n.oid=c.relnamespace
            where n.nspname='public' and c.relkind='v'
              and (has_table_privilege('anon',c.oid,'SELECT') or has_table_privilege('authenticated',c.oid,'SELECT'))
              and not coalesce(c.reloptions,'{}') @> array['security_invoker=true']
          ),
          'public_security_definer_client_callable',(
            select count(*)
            from pg_proc p
            join pg_namespace n on n.oid=p.pronamespace
            where n.nspname='public' and p.prosecdef=true
              and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE'))
          )
        ),
        'hot_path_indexes',jsonb_build_object(
          'mixtapes_public_home',to_regclass('public.mixtapes_public_home_idx') is not null,
          'tracks_release_order',to_regclass('public.tracks_mixtape_track_number_idx') is not null,
          'videos_public_listing',to_regclass('public.videos_public_listing_idx') is not null,
          'merch_public_feed',to_regclass('public.merch_products_public_feed_idx') is not null,
          'messages_conversation_time',to_regclass('public.tgg_messages_conversation_created_idx') is not null,
          'memberships_artist_status',to_regclass('public.tgg_memberships_artist_status_period_idx') is not null,
          'studio_project_user_time',to_regclass('public.tgg_studio_projects_user_updated_idx') is not null,
          'recording_session_user_status',to_regclass('public.tgg_recording_sessions_user_status_updated_idx') is not null,
          'recording_takes_project_time',to_regclass('public.tgg_recording_takes_project_created_idx') is not null
        ),
        'generated_at',now()
      );
    $function$


