-- [40000000750] function public.tgg_design_create_spec(p_task_key text, p_spec_key text, p_surface_type text, p_title text, p_purpose text, p_hierarchy jsonb, p_layout_spec jsonb, p_responsive_rules jsonb, p_interaction_states jsonb, p_accessibility jsonb, p_asset_requirements jsonb)
CREATE OR REPLACE FUNCTION public.tgg_design_create_spec(p_task_key text, p_spec_key text, p_surface_type text, p_title text, p_purpose text, p_hierarchy jsonb, p_layout_spec jsonb, p_responsive_rules jsonb, p_interaction_states jsonb, p_accessibility jsonb, p_asset_requirements jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_task_id uuid;
  v_design_system_id uuid;
  v_spec_id uuid;
begin
  select id into v_task_id
  from public.tgg_build_tasks
  where task_key=p_task_key;

  if v_task_id is null then
    raise exception 'task not found: %', p_task_key;
  end if;

  select ds.id into v_design_system_id
  from public.tgg_design_systems ds
  join public.tgg_build_projects p on p.id=ds.project_id
  where p.project_key='tru-go-getta-master'
    and ds.design_key='tgg-core'
    and ds.status='active'
  order by ds.version desc
  limit 1;

  insert into public.tgg_design_specs(
    task_id, design_system_id, spec_key, surface_type, title, purpose,
    hierarchy, layout_spec, responsive_rules, interaction_states,
    accessibility, asset_requirements, status
  )
  values(
    v_task_id, v_design_system_id, p_spec_key, p_surface_type, p_title, p_purpose,
    coalesce(p_hierarchy,'[]'::jsonb),
    coalesce(p_layout_spec,'{}'::jsonb),
    coalesce(p_responsive_rules,'{}'::jsonb),
    coalesce(p_interaction_states,'{}'::jsonb),
    coalesce(p_accessibility,'{}'::jsonb),
    coalesce(p_asset_requirements,'[]'::jsonb),
    'ready'
  )
  on conflict (spec_key) do update
  set task_id=excluded.task_id,
      design_system_id=excluded.design_system_id,
      surface_type=excluded.surface_type,
      title=excluded.title,
      purpose=excluded.purpose,
      hierarchy=excluded.hierarchy,
      layout_spec=excluded.layout_spec,
      responsive_rules=excluded.responsive_rules,
      interaction_states=excluded.interaction_states,
      accessibility=excluded.accessibility,
      asset_requirements=excluded.asset_requirements,
      status='ready',
      revision=public.tgg_design_specs.revision+1,
      updated_at=now()
  returning id into v_spec_id;

  return v_spec_id;
end;
$function$


-- [40000000751] function public.tgg_design_gate_spec(p_spec_key text)
CREATE OR REPLACE FUNCTION public.tgg_design_gate_spec(p_spec_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_spec public.tgg_design_specs%rowtype;
  v_fail_count integer;
  v_pass_count integer;
begin
  select * into v_spec
  from public.tgg_design_specs
  where spec_key=p_spec_key;

  if v_spec.id is null then
    raise exception 'design spec not found: %', p_spec_key;
  end if;

  select count(*) into v_fail_count
  from public.tgg_build_failures
  where task_id=v_spec.task_id
    and category='visual_qa'
    and status in ('open','repairing');

  select count(*) into v_pass_count
  from public.tgg_visual_qa_results
  where design_spec_id=v_spec.id
    and status='passed';

  if v_fail_count > 0 then
    update public.tgg_design_specs
    set status='blocked', updated_at=now()
    where id=v_spec.id;

    return jsonb_build_object('status','blocked','open_visual_failures',v_fail_count,'passed_checks',v_pass_count);
  end if;

  if v_pass_count < 3 then
    return jsonb_build_object('status','qa','reason','desktop/tablet/mobile pass set required','passed_checks',v_pass_count);
  end if;

  update public.tgg_design_specs
  set status='passed', updated_at=now()
  where id=v_spec.id;

  return jsonb_build_object('status','passed','passed_checks',v_pass_count);
end;
$function$


-- [40000000752] function public.tgg_design_resolve_visual_failures(p_task_key text, p_spec_key text, p_resolution jsonb)
CREATE OR REPLACE FUNCTION public.tgg_design_resolve_visual_failures(p_task_key text, p_spec_key text, p_resolution jsonb DEFAULT '{}'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_task_id uuid;
  v_count integer := 0;
begin
  select id into v_task_id from public.tgg_build_tasks where task_key=p_task_key;

  update public.tgg_build_failures
  set status='resolved',
      resolved_at=now(),
      detail=detail || jsonb_build_object('resolution',coalesce(p_resolution,'{}'::jsonb))
  where task_id=v_task_id
    and category='visual_qa'
    and status in ('open','repairing')
    and failure_key like 'visual:' || p_spec_key || ':%';

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$


