-- [40000000754] function public.tgg_distribution_master_detach(p_track_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_distribution_master_detach(p_track_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_track public.tracks%rowtype;
  v_release_title text;
  v_old_path text;
  v_direct_url boolean:=false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select t.*
  into v_track
  from public.tracks t
  join public.mixtapes m on m.id=t.mixtape_id
  join public.artists a on a.id=m.artist_id
  where t.id=p_track_id
    and a.user_id=v_uid
  limit 1;

  if v_track.id is null then
    raise exception 'TRACK_NOT_FOUND_OR_NOT_OWNED';
  end if;

  select m.title
  into v_release_title
  from public.mixtapes m
  where m.id=v_track.mixtape_id;

  v_old_path:=nullif(btrim(coalesce(v_track.audio_path,'')),'');
  if v_old_path is null then
    raise exception 'TRACK_HAS_NO_MASTER_REFERENCE';
  end if;

  if private.tgg_master_reuse_confirmed_for_owner(v_old_path) then
    raise exception 'MASTER_REUSE_CONFIRMED_INTENTIONAL_CLEAR_CONFIRMATION_FIRST'
      using errcode='22023';
  end if;

  if not exists(
    select 1
    from public.tracks t2
    join public.mixtapes m2 on m2.id=t2.mixtape_id
    where t2.id<>v_track.id
      and m2.status='published'::public.mixtape_status
      and nullif(btrim(coalesce(t2.audio_path,'')),'')=v_old_path
  ) then
    raise exception 'MASTER_REFERENCE_IS_NOT_DUPLICATED';
  end if;

  v_direct_url :=
    coalesce(v_track.audio_url,'') ~* '^https://'
    and regexp_replace(split_part(v_track.audio_url,'?',1),'#.*$','') ~* '\.(mp3|wav|flac|m4a|aac|ogg)$';

  update public.tracks
  set
    audio_path=null,
    duration_seconds=case when v_direct_url then duration_seconds else null end
  where id=v_track.id;

  perform private.tgg_reconcile_distribution_master_reuse_activation_item();
  perform private.tgg_reconcile_distribution_metadata_activation_item();
  perform private.tgg_activation_consistency_monitor();

  return jsonb_build_object(
    'ok',true,
    'version','DISTRIBUTION-MASTER-DETACH-ONE-FINAL-1.2',
    'track_id',v_track.id,
    'release_id',v_track.mixtape_id,
    'release_title',v_release_title,
    'detached_audio_path',v_old_path,
    'stored_object_deleted',false,
    'remaining_audio_url',v_track.audio_url,
    'duration_preserved',v_direct_url,
    'next_step','Refresh distribution readiness and confirm the correct master assignment.'
  );
end
$function$


-- [40000000755] function public.tgg_distribution_master_provenance()
CREATE OR REPLACE FUNCTION public.tgg_distribution_master_provenance()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','DISTRIBUTION-MASTER-PROVENANCE-ONE-FINAL-1.0',
    'groups',coalesce((
      with refs as (
        select
          t.audio_path,
          t.id as track_id,
          t.created_at as track_created_at,
          t.audio_url,
          t.duration_seconds,
          m.id as release_id,
          m.title as release_title,
          m.created_at as release_created_at,
          a.user_id
        from public.tracks t
        join public.mixtapes m on m.id=t.mixtape_id
        join public.artists a on a.id=m.artist_id
        where a.user_id=v_uid
          and m.status='published'::public.mixtape_status
          and nullif(btrim(coalesce(t.audio_path,'')),'') is not null
      ),
      dup as (
        select audio_path
        from refs
        group by audio_path
        having count(distinct release_id)>1
      ),
      obj as (
        select
          o.name as audio_path,
          o.bucket_id,
          o.created_at as object_created_at,
          o.updated_at as object_updated_at,
          o.owner_id,
          o.metadata
        from storage.objects o
        where exists(select 1 from dup d where d.audio_path=o.name)
      ),
      scored as (
        select
          r.*,
          o.bucket_id,
          o.object_created_at,
          abs(extract(epoch from (r.track_created_at-o.object_created_at))) as seconds_from_object_create,
          case when r.audio_url is null then 1 else 0 end as no_legacy_url_bonus
        from refs r
        left join obj o on o.audio_path=r.audio_path
        where exists(select 1 from dup d where d.audio_path=r.audio_path)
      )
      select jsonb_agg(jsonb_build_object(
        'audio_path',d.audio_path,
        'object',(
          select jsonb_build_object(
            'bucket_id',o.bucket_id,
            'created_at',o.object_created_at,
            'updated_at',o.object_updated_at,
            'owner_id',o.owner_id,
            'size_bytes',nullif(o.metadata->>'size','')::bigint,
            'mimetype',o.metadata->>'mimetype'
          )
          from obj o
          where o.audio_path=d.audio_path
          limit 1
        ),
        'references',(
          select jsonb_agg(jsonb_build_object(
            'release_id',s.release_id,
            'release_title',s.release_title,
            'track_id',s.track_id,
            'track_created_at',s.track_created_at,
            'release_created_at',s.release_created_at,
            'audio_url',s.audio_url,
            'duration_seconds',s.duration_seconds,
            'seconds_from_object_create',s.seconds_from_object_create
          ) order by s.track_created_at)
          from scored s
          where s.audio_path=d.audio_path
        ),
        'recommended_owner',(
          select jsonb_build_object(
            'release_id',s.release_id,
            'release_title',s.release_title,
            'track_id',s.track_id,
            'reason','closest_track_creation_to_storage_object_creation',
            'seconds_from_object_create',s.seconds_from_object_create,
            'confidence',case
              when s.seconds_from_object_create is not null and s.seconds_from_object_create<=2 then 'high'
              when s.seconds_from_object_create is not null and s.seconds_from_object_create<=60 then 'medium'
              else 'low'
            end
          )
          from scored s
          where s.audio_path=d.audio_path
          order by s.seconds_from_object_create asc nulls last,s.no_legacy_url_bonus desc,s.track_created_at desc
          limit 1
        ),
        'recommendation_is_advisory',true,
        'automatic_detach_performed',false
      ) order by d.audio_path)
      from dup d
    ),'[]'::jsonb),
    'generated_at',now()
  );
end
$function$


-- [40000000756] function public.tgg_distribution_master_reuse_bundle()
CREATE OR REPLACE FUNCTION public.tgg_distribution_master_reuse_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','DISTRIBUTION-MASTER-REUSE-ONE-FINAL-1.0',
    'groups',coalesce((
      with owned_tracks as (
        select
          t.id as track_id,
          t.mixtape_id as release_id,
          m.title as release_title,
          t.title as track_title,
          t.audio_path,
          t.audio_url,
          t.duration_seconds,
          coalesce(t.has_secure_audio,false) as has_secure_audio
        from public.tracks t
        join public.mixtapes m on m.id=t.mixtape_id
        join public.artists a on a.id=m.artist_id
        where a.user_id=v_uid
          and m.status='published'::public.mixtape_status
          and nullif(btrim(coalesce(t.audio_path,'')),'') is not null
      ),
      duplicate_paths as (
        select audio_path
        from owned_tracks
        group by audio_path
        having count(distinct release_id)>1
      )
      select jsonb_agg(jsonb_build_object(
        'audio_path',d.audio_path,
        'published_release_count',(
          select count(distinct o.release_id)
          from owned_tracks o
          where o.audio_path=d.audio_path
        ),
        'references',(
          select jsonb_agg(jsonb_build_object(
            'release_id',o.release_id,
            'release_title',o.release_title,
            'track_id',o.track_id,
            'track_title',o.track_title,
            'audio_url',o.audio_url,
            'duration_seconds',o.duration_seconds,
            'has_secure_audio',o.has_secure_audio
          ) order by o.release_title,o.track_title,o.track_id)
          from owned_tracks o
          where o.audio_path=d.audio_path
        )
      ) order by d.audio_path)
      from duplicate_paths d
    ),'[]'::jsonb),
    'safe_actions',jsonb_build_object(
      'detach_master_reference_rpc','tgg_distribution_master_detach',
      'stored_object_deleted',false,
      'requires_owner_confirmation',true
    ),
    'generated_at',now()
  );
end
$function$


