-- [40000000760] function public.tgg_distribution_metadata_upsert(p_release_id uuid, p_label_name text, p_copyright_line text, p_publishing_line text, p_primary_language text, p_territories jsonb, p_rights_confirmed boolean, p_notes text)
CREATE OR REPLACE FUNCTION public.tgg_distribution_metadata_upsert(p_release_id uuid, p_label_name text DEFAULT NULL::text, p_copyright_line text DEFAULT NULL::text, p_publishing_line text DEFAULT NULL::text, p_primary_language text DEFAULT 'en'::text, p_territories jsonb DEFAULT '[]'::jsonb, p_rights_confirmed boolean DEFAULT false, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text:=coalesce(auth.jwt()->'app_metadata'->>'tgg_role','');
  v_artist uuid;
  v_row public.tgg_distribution_release_metadata;
  v_sync_ok boolean:=true;
  v_sync_skipped boolean:=false;
  v_sync_error text:=null;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select m.artist_id into v_artist
  from public.mixtapes m
  join public.artists a on a.id=m.artist_id
  where m.id=p_release_id and a.user_id=v_uid;

  if v_artist is null then raise exception 'RELEASE_NOT_FOUND_OR_NOT_OWNED'; end if;
  if jsonb_typeof(coalesce(p_territories,'[]'::jsonb))<>'array' then raise exception 'TERRITORIES_MUST_BE_ARRAY'; end if;
  if octet_length(coalesce(p_territories,'[]'::jsonb)::text)>16384 then raise exception 'TERRITORIES_TOO_LARGE'; end if;

  if char_length(btrim(coalesce(p_primary_language,'')))<2 or char_length(btrim(coalesce(p_primary_language,'')))>20 then
    raise exception 'PRIMARY_LANGUAGE_INVALID';
  end if;
  if p_label_name is not null and char_length(p_label_name)>500 then raise exception 'LABEL_NAME_TOO_LONG'; end if;
  if p_copyright_line is not null and char_length(p_copyright_line)>500 then raise exception 'COPYRIGHT_LINE_TOO_LONG'; end if;
  if p_publishing_line is not null and char_length(p_publishing_line)>500 then raise exception 'PUBLISHING_LINE_TOO_LONG'; end if;
  if p_notes is not null and char_length(p_notes)>5000 then raise exception 'NOTES_TOO_LONG'; end if;

  if coalesce(p_rights_confirmed,false) then
    if nullif(btrim(coalesce(p_label_name,'')),'') is null then raise exception 'LABEL_NAME_REQUIRED_FOR_RIGHTS_CONFIRMATION'; end if;
    if nullif(btrim(coalesce(p_copyright_line,'')),'') is null then raise exception 'COPYRIGHT_LINE_REQUIRED_FOR_RIGHTS_CONFIRMATION'; end if;
    if nullif(btrim(coalesce(p_publishing_line,'')),'') is null then raise exception 'PUBLISHING_LINE_REQUIRED_FOR_RIGHTS_CONFIRMATION'; end if;
    if coalesce(jsonb_array_length(coalesce(p_territories,'[]'::jsonb)),0)=0 then raise exception 'TERRITORIES_REQUIRED_FOR_RIGHTS_CONFIRMATION'; end if;
  end if;

  insert into public.tgg_distribution_release_metadata(
    release_id,owner_user_id,artist_id,label_name,copyright_line,publishing_line,
    primary_language,territories,rights_confirmed,rights_confirmed_at,notes,updated_at
  )
  values(
    p_release_id,v_uid,v_artist,
    nullif(btrim(coalesce(p_label_name,'')),''),
    nullif(btrim(coalesce(p_copyright_line,'')),''),
    nullif(btrim(coalesce(p_publishing_line,'')),''),
    lower(btrim(p_primary_language)),
    coalesce(p_territories,'[]'::jsonb),
    coalesce(p_rights_confirmed,false),
    case when coalesce(p_rights_confirmed,false) then now() else null end,
    nullif(btrim(coalesce(p_notes,'')),''),
    now()
  )
  on conflict(release_id) do update set
    label_name=excluded.label_name,
    copyright_line=excluded.copyright_line,
    publishing_line=excluded.publishing_line,
    primary_language=excluded.primary_language,
    territories=excluded.territories,
    rights_confirmed=excluded.rights_confirmed,
    rights_confirmed_at=case
      when excluded.rights_confirmed and not tgg_distribution_release_metadata.rights_confirmed then now()
      when excluded.rights_confirmed then coalesce(tgg_distribution_release_metadata.rights_confirmed_at,now())
      else null
    end,
    notes=excluded.notes,
    updated_at=now()
  where tgg_distribution_release_metadata.owner_user_id=v_uid
  returning * into v_row;

  if v_row.release_id is null then
    raise exception 'RELEASE_METADATA_NOT_OWNED';
  end if;

  if v_role='owner' then
    begin
      perform private.tgg_reconcile_distribution_metadata_activation_item();
      perform private.tgg_activation_consistency_monitor();
    exception when others then
      v_sync_ok:=false;
      v_sync_error:=sqlerrm;
    end;
  else
    v_sync_skipped:=true;
  end if;

  return jsonb_build_object(
    'ok',true,
    'release_id',v_row.release_id,
    'rights_confirmed',v_row.rights_confirmed,
    'territories',v_row.territories,
    'updated_at',v_row.updated_at,
    'operational_sync',jsonb_build_object(
      'ok',v_sync_ok,
      'skipped',v_sync_skipped,
      'retryable',not v_sync_ok,
      'error',v_sync_error,
      'source',case when v_sync_skipped
        then 'creator_metadata_write_no_owner_queue_reconcile'
        else 'owner_distribution_metadata_post_write_reconcile'
      end
    )
  );
end
$function$


