-- [40000000762] function public.tgg_distribution_resolution_bundle()
CREATE OR REPLACE FUNCTION public.tgg_distribution_resolution_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_master jsonb;
  v_provenance jsonb;
  v_releases jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  v_master:=public.tgg_distribution_master_reuse_bundle();
  v_provenance:=public.tgg_distribution_master_provenance();

  select coalesce(jsonb_agg(jsonb_build_object(
    'release_id',m.id,
    'title',m.title,
    'status',m.status,
    'label_name',d.label_name,
    'copyright_line',d.copyright_line,
    'publishing_line',d.publishing_line,
    'primary_language',coalesce(d.primary_language,'en'),
    'territories',coalesce(d.territories,'[]'::jsonb),
    'rights_confirmed',coalesce(d.rights_confirmed,false),
    'notes',d.notes,
    'missing',jsonb_strip_nulls(jsonb_build_object(
      'label_name',case when nullif(btrim(coalesce(d.label_name,'')),'') is null then true end,
      'copyright_line',case when nullif(btrim(coalesce(d.copyright_line,'')),'') is null then true end,
      'publishing_line',case when nullif(btrim(coalesce(d.publishing_line,'')),'') is null then true end,
      'territories',case when coalesce(jsonb_array_length(coalesce(d.territories,'[]'::jsonb)),0)=0 then true end,
      'rights_confirmed',case when not coalesce(d.rights_confirmed,false) then true end
    ))
  ) order by m.title),'[]'::jsonb)
  into v_releases
  from public.mixtapes m
  join public.artists a on a.id=m.artist_id
  left join public.tgg_distribution_release_metadata d
    on d.release_id=m.id and d.owner_user_id=v_uid
  where a.user_id=v_uid
    and m.status='published'
    and exists(
      select 1 from public.tracks t
      where t.mixtape_id=m.id
        and (
          nullif(btrim(coalesce(t.audio_path,'')),'') is not null
          or nullif(btrim(coalesce(t.audio_url,'')),'') is not null
        )
    );

  return jsonb_build_object(
    'ok',true,
    'master_reuse',v_master,
    'master_provenance',v_provenance,
    'releases',v_releases,
    'master_conflict_count',jsonb_array_length(coalesce(v_master->'groups','[]'::jsonb)),
    'releases_missing_metadata',(
      select count(*)
      from jsonb_array_elements(v_releases) x
      where exists (
        select 1 from jsonb_object_keys(coalesce(x->'missing','{}'::jsonb))
      )
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000763] function public.tgg_distribution_submit_request(p_release_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_distribution_submit_request(p_release_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_ready jsonb;
  v_pkg jsonb;
  v_artist uuid;
  v_provider_ready boolean:=false;
  v_id uuid;
  v_hash text;
  v_status text;
  v_existing public.tgg_distribution_requests%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  perform private.tgg_creator_rate_limit_gate('distribution.submit.rpc',60,3600);

  v_ready:=public.tgg_creator_distribution_readiness(p_release_id);

  if not coalesce((v_ready->>'package_ready')::boolean,false) then
    return jsonb_build_object(
      'ok',false,'blocked',true,'reason','release_not_ready','readiness',v_ready
    );
  end if;

  select coalesce(enabled,false)
         and coalesce(endpoint_configured,false)
         and mode='production'
  into v_provider_ready
  from public.tgg_provider_runtime_config
  where provider_key='distribution.provider';

  v_pkg:=public.tgg_creator_distribution_package(p_release_id)->'package';

  select m.artist_id into v_artist
  from public.mixtapes m
  join public.artists a on a.id=m.artist_id
  where m.id=p_release_id and a.user_id=v_uid;

  if v_artist is null then raise exception 'RELEASE_NOT_FOUND_OR_NOT_OWNED'; end if;

  v_hash:=encode(digest(convert_to(v_pkg::text,'UTF8'),'sha256'),'hex');
  v_status:=case when coalesce(v_provider_ready,false) then 'queued' else 'prepared' end;

  select * into v_existing
  from public.tgg_distribution_requests
  where owner_user_id=v_uid
    and release_id=p_release_id
    and provider_key='distribution.provider'
    and package_hash=v_hash
    and status in ('prepared','queued','processing','submitted')
  order by created_at desc
  limit 1;

  if v_existing.id is not null then
    perform private.tgg_creator_mutation_audit_log(
      'distribution.submit_reuse',
      v_existing.id::text,
      jsonb_build_object('release_id',p_release_id,'status',v_existing.status,'package_hash',v_hash)
    );

    return jsonb_build_object(
      'ok',true,'idempotent_reuse',true,'request_id',v_existing.id,
      'status',v_existing.status,'package_hash',v_existing.package_hash,
      'provider_ready',coalesce(v_provider_ready,false),
      'delivery_pending',v_existing.status<>'delivered',
      'message','Existing in-flight distribution request reused.'
    );
  end if;

  begin
    insert into public.tgg_distribution_requests(
      owner_user_id,artist_id,release_id,provider_key,package_snapshot,package_hash,status
    )
    values(
      v_uid,v_artist,p_release_id,'distribution.provider',v_pkg,v_hash,v_status
    )
    returning id into v_id;
  exception when unique_violation then
    select * into v_existing
    from public.tgg_distribution_requests
    where owner_user_id=v_uid
      and release_id=p_release_id
      and provider_key='distribution.provider'
      and package_hash=v_hash
      and status in ('prepared','queued','processing','submitted')
    order by created_at desc
    limit 1;

    if v_existing.id is null then raise; end if;

    perform private.tgg_creator_mutation_audit_log(
      'distribution.submit_reuse',
      v_existing.id::text,
      jsonb_build_object('release_id',p_release_id,'status',v_existing.status,'package_hash',v_hash,'concurrent_retry',true)
    );

    return jsonb_build_object(
      'ok',true,'idempotent_reuse',true,'request_id',v_existing.id,
      'status',v_existing.status,'package_hash',v_existing.package_hash,
      'provider_ready',coalesce(v_provider_ready,false),
      'delivery_pending',v_existing.status<>'delivered',
      'message','Concurrent distribution retry reused the existing request.'
    );
  end;

  perform private.tgg_creator_mutation_audit_log(
    'distribution.submit',
    v_id::text,
    jsonb_build_object('release_id',p_release_id,'status',v_status,'package_hash',v_hash)
  );

  return jsonb_build_object(
    'ok',true,'idempotent_reuse',false,'request_id',v_id,'status',v_status,
    'package_hash',v_hash,'provider_ready',coalesce(v_provider_ready,false),
    'delivery_pending',not coalesce(v_provider_ready,false),
    'message',case
      when coalesce(v_provider_ready,false) then 'Package queued for provider delivery.'
      else 'Package prepared and frozen; provider delivery can be enabled later without rebuilding metadata.'
    end
  );
end;
$function$


