-- [40000000765] function public.tgg_edit_message(p_message_id uuid, p_body text)
CREATE OR REPLACE FUNCTION public.tgg_edit_message(p_message_id uuid, p_body text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid(); v_body text:=btrim(coalesce(p_body,''));
begin
 if v_user is null then raise exception 'authentication required'; end if;
 if char_length(v_body)<1 or char_length(v_body)>10000 then raise exception 'message must be 1 to 10000 characters'; end if;
 update public.tgg_messages set body=v_body,edited_at=now() where id=p_message_id and sender_id=v_user; if not found then raise exception 'message unavailable'; end if; return true;
end $function$


-- [40000000766] function public.tgg_effective_blogger_page_hashes()
CREATE OR REPLACE FUNCTION public.tgg_effective_blogger_page_hashes()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with b as (
    select version,coalesce(notes->'page_hashes','{}'::jsonb) as page_hashes
    from public.tgg_production_baselines
    where status='locked'
    order by locked_at desc
    limit 1
  ), o as (
    select coalesce(jsonb_object_agg(a.object_key,a.approved_contract->>'hash' order by a.object_key),'{}'::jsonb) as overrides
    from private.tgg_baseline_additive_allowances a
    join b on b.version=a.baseline_version
    where a.object_kind='blogger_page_hash'
      and a.active=true
      and a.approved_contract ? 'hash'
      and (a.approved_contract->>'hash') ~ '^[0-9a-f]{64}$'
  )
  select coalesce(b.page_hashes,'{}'::jsonb) || coalesce(o.overrides,'{}'::jsonb)
  from b cross join o;
$function$


-- [40000000767] function public.tgg_end_call_room(p_room_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_end_call_room(p_room_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  update public.tgg_call_rooms set status='ended',ended_at=now() where id=p_room_id and created_by=auth.uid() and status<>'ended';
  return found;
end;$function$


-- [40000000768] function public.tgg_enforce_game_score_integrity()
CREATE OR REPLACE FUNCTION public.tgg_enforce_game_score_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF NEW.score < 0 OR NEW.wins < 0 THEN
    RAISE EXCEPTION 'INVALID_SCORE_STATE';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.session_id <> OLD.session_id OR NEW.user_id <> OLD.user_id THEN
      RAISE EXCEPTION 'SCORE_IDENTITY_IMMUTABLE';
    END IF;
    IF NEW.score < OLD.score THEN
      RAISE EXCEPTION 'SCORE_CANNOT_DECREASE';
    END IF;
    IF NEW.wins < OLD.wins THEN
      RAISE EXCEPTION 'WINS_CANNOT_DECREASE';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$


-- [40000000769] function public.tgg_enforce_game_session_status_transition()
CREATE OR REPLACE FUNCTION public.tgg_enforce_game_session_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF NEW.status = OLD.status THEN RETURN NEW; END IF;
  IF NOT ((OLD.status='open' AND NEW.status='active') OR (OLD.status='active' AND NEW.status='ended')) THEN
    RAISE EXCEPTION 'INVALID_SESSION_STATUS_TRANSITION' USING DETAIL=concat('Cannot transition session from ',OLD.status,' to ',NEW.status);
  END IF;
  RETURN NEW;
END;
$function$


-- [40000000770] function public.tgg_enforce_game_status_transition()
CREATE OR REPLACE FUNCTION public.tgg_enforce_game_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if new.status = old.status then
    return new;
  end if;
  if not (
    (old.status='draft' and new.status='open') or
    (old.status='open' and new.status='live') or
    (old.status='live' and new.status='ended')
  ) then
    raise exception 'INVALID_STATUS_TRANSITION' using detail=concat('Cannot transition game from ',old.status,' to ',new.status);
  end if;
  return new;
end;
$function$


-- [40000000771] function public.tgg_event_create(p_title text, p_description text, p_venue_name text, p_city text, p_region text, p_country text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_event_type text, p_ticket_url text)
CREATE OR REPLACE FUNCTION public.tgg_event_create(p_title text, p_description text DEFAULT NULL::text, p_venue_name text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_region text DEFAULT NULL::text, p_country text DEFAULT 'US'::text, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_event_type text DEFAULT 'show'::text, p_ticket_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_artist uuid;v_id uuid;v_type text:=lower(coalesce(nullif(btrim(coalesce(p_event_type,'')),''),'show'));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'TITLE_REQUIRED'; end if;
  if v_type not in ('show','festival','release_party','game_night','open_mic','battle','meetup','virtual') then raise exception 'EVENT_TYPE_INVALID'; end if;
  if p_starts_at is not null and p_ends_at is not null and p_ends_at<=p_starts_at then raise exception 'EVENT_TIME_INVALID'; end if;
  select id into v_artist from public.artists where user_id=v_uid order by created_at limit 1;
  insert into public.tgg_events(created_by,artist_id,title,description,venue_name,city,region,country,starts_at,ends_at,event_type,ticket_url,status)
  values(v_uid,v_artist,left(btrim(p_title),180),nullif(btrim(coalesce(p_description,'')),''),
    nullif(btrim(coalesce(p_venue_name,'')),''),nullif(btrim(coalesce(p_city,'')),''),nullif(btrim(coalesce(p_region,'')),''),
    coalesce(nullif(btrim(coalesce(p_country,'')),''),'US'),p_starts_at,p_ends_at,v_type,nullif(btrim(coalesce(p_ticket_url,'')),''),'draft')
  returning id into v_id;
  return jsonb_build_object('ok',true,'event_id',v_id,'status','draft');
end $function$


-- [40000000772] function public.tgg_event_delete(p_event_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_event_delete(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  delete from public.tgg_events where id=p_event_id and created_by=v_uid and status in ('draft','canceled')
  returning id into v_id;
  if v_id is null then raise exception 'EVENT_NOT_DELETABLE'; end if;
  return jsonb_build_object('ok',true,'event_id',v_id,'deleted',true);
end $function$


-- [40000000773] function public.tgg_event_rsvp_remove(p_event_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_event_rsvp_remove(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_event uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      delete from public.tgg_event_rsvps where event_id=p_event_id and user_id=v_uid returning event_id into v_event;
      if v_event is null then raise exception 'RSVP_NOT_FOUND'; end if;
      return jsonb_build_object('ok',true,'event_id',v_event,'removed',true);
    end $function$


-- [40000000774] function public.tgg_event_rsvp_set(p_event_id uuid, p_status text)
CREATE OR REPLACE FUNCTION public.tgg_event_rsvp_set(p_event_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_status text:=lower(btrim(coalesce(p_status,'')));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if v_status not in ('interested','going') then raise exception 'RSVP_STATUS_INVALID'; end if;
      if not exists(select 1 from public.tgg_events e where e.id=p_event_id and e.status='published') then
        raise exception 'EVENT_NOT_AVAILABLE';
      end if;

      insert into public.tgg_event_rsvps(event_id,user_id,status)
      values(p_event_id,v_uid,v_status)
      on conflict(event_id,user_id) do update set status=excluded.status,updated_at=now();

      return jsonb_build_object('ok',true,'event_id',p_event_id,'status',v_status);
    end $function$


-- [40000000775] function public.tgg_event_set_published(p_event_id uuid, p_published boolean)
CREATE OR REPLACE FUNCTION public.tgg_event_set_published(p_event_id uuid, p_published boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_status text:=case when coalesce(p_published,false) then 'published' else 'draft' end;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  update public.tgg_events set status=v_status
  where id=p_event_id and created_by=v_uid and status<>'ended'
  returning id into v_id;
  if v_id is null then raise exception 'EVENT_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'event_id',v_id,'status',v_status);
end $function$


-- [40000000776] function public.tgg_event_update(p_event_id uuid, p_title text, p_description text, p_venue_name text, p_city text, p_region text, p_country text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_event_type text, p_ticket_url text)
CREATE OR REPLACE FUNCTION public.tgg_event_update(p_event_id uuid, p_title text, p_description text, p_venue_name text, p_city text, p_region text, p_country text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_event_type text, p_ticket_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_type text:=lower(coalesce(nullif(btrim(coalesce(p_event_type,'')),''),'show'));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_type not in ('show','festival','release_party','game_night','open_mic','battle','meetup','virtual') then raise exception 'EVENT_TYPE_INVALID'; end if;
  if p_starts_at is not null and p_ends_at is not null and p_ends_at<=p_starts_at then raise exception 'EVENT_TIME_INVALID'; end if;
  update public.tgg_events
  set title=left(btrim(coalesce(p_title,'')),180),description=nullif(btrim(coalesce(p_description,'')),''),
      venue_name=nullif(btrim(coalesce(p_venue_name,'')),''),city=nullif(btrim(coalesce(p_city,'')),''),
      region=nullif(btrim(coalesce(p_region,'')),''),country=coalesce(nullif(btrim(coalesce(p_country,'')),''),'US'),
      starts_at=p_starts_at,ends_at=p_ends_at,event_type=v_type,ticket_url=nullif(btrim(coalesce(p_ticket_url,'')),'')
  where id=p_event_id and created_by=v_uid and status in ('draft','published','canceled')
  returning id into v_id;
  if v_id is null then raise exception 'EVENT_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'event_id',v_id);
end $function$


-- [40000000777] function public.tgg_external_action_contract_readiness()
CREATE OR REPLACE FUNCTION public.tgg_external_action_contract_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with expected(provider_key,expects_fallback,expects_action) as (
  values
    ('blogger.oauth',true,false),
    ('stripe.native',true,true),
    ('distribution.provider',true,true),
    ('broadcast.sfu_turn',true,true),
    ('calls.two_user_validation',true,true),
    ('auth.leaked_password_protection',false,true)
),
state as (
  select
    e.provider_key,
    h.status,
    nullif(btrim(coalesce(h.required_action,'')),'') is not null as action_text_ready,
    nullif(btrim(coalesce(h.verification_check,'')),'') is not null as verification_ready,
    case when e.expects_fallback then nullif(btrim(coalesce(h.safe_fallback,'')),'') is not null else true end as fallback_ready,
    case when e.expects_action then
      nullif(btrim(coalesce(h.notes->>'action_label','')),'') is not null
      and nullif(btrim(coalesce(h.notes->>'action_url','')),'') is not null
      else true end as action_path_ready,
    nullif(btrim(coalesce(h.notes->>'acceptance_contract','')),'') is not null
      or e.provider_key in ('blogger.oauth','stripe.native') as acceptance_contract_ready
  from expected e
  left join public.tgg_provider_handoff h using(provider_key)
),
agg as (
  select
    count(*) total,
    count(*) filter(
      where status is not null
        and action_text_ready
        and verification_ready
        and fallback_ready
        and action_path_ready
        and acceptance_contract_ready
    ) ready,
    coalesce(jsonb_agg(provider_key order by provider_key) filter(
      where status is null
         or not action_text_ready
         or not verification_ready
         or not fallback_ready
         or not action_path_ready
         or not acceptance_contract_ready
    ),'[]'::jsonb) failed
  from state
)
select jsonb_build_object(
  'ok',ready=total,
  'version','EXTERNAL-ACTION-CONTRACT-1.1',
  'ready',ready,
  'total',total,
  'failed',failed,
  'state',(
    select jsonb_object_agg(provider_key,jsonb_build_object(
      'status',status,
      'action_text_ready',action_text_ready,
      'verification_ready',verification_ready,
      'fallback_ready',fallback_ready,
      'action_path_ready',action_path_ready,
      'acceptance_contract_ready',acceptance_contract_ready
    ) order by provider_key)
    from state
  ),
  'generated_at',now()
)
from agg;
$function$


