-- [40000000782] function public.tgg_external_infrastructure_center()
CREATE OR REPLACE FUNCTION public.tgg_external_infrastructure_center()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_launch jsonb;
  v_provider jsonb;
  v_broadcast jsonb;
  v_distribution jsonb;
  v_ext jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_launch:=public.tgg_launch_readiness_final();
  v_provider:=public.tgg_provider_final_health();
  v_broadcast:=public.tgg_broadcast_engine_health();
  v_distribution:=public.tgg_creator_distribution_bundle(25);
  v_ext:=public.tgg_external_infrastructure_final_health();

  return jsonb_build_object(
    'ok',true,
    'version','EXTERNAL-CENTER-ONE-FINAL-1.1',
    'code_complete',v_launch->'code_complete',
    'internal_ready',v_launch->'internal_ready',
    'status',v_launch->>'status',
    'blockers',v_launch->'external_blockers',
    'providers',v_provider->'adapters',
    'broadcast',v_broadcast,
    'distribution',v_distribution,
    'actions',jsonb_build_array(
      jsonb_build_object(
        'key','stripe_server_runtime',
        'title','Stripe Server Runtime',
        'code_ready',true,
        'external_required',false,
        'state',case when coalesce((v_ext#>>'{stripe,webhook_runtime_ready}')::boolean,false) then 'ready' else 'setup_required' end,
        'requirement','Production Stripe Payment Links and webhook runtime are active. Native checkout remains optional.',
        'target','/p/vault.html#supporters'
      ),
      jsonb_build_object(
        'key','dsp_distribution_provider',
        'title','DSP Distribution Provider',
        'code_ready',true,
        'external_required',true,
        'state',case
          when coalesce((v_ext#>>'{dsp_distribution,ready}')::boolean,false) then 'ready'
          when coalesce((v_ext#>>'{dsp_distribution,endpoint_configured}')::boolean,false) then 'credentials_required'
          else 'endpoint_required'
        end,
        'requirement','The DSP endpoint is staged. Real production provider credentials are the remaining connection requirement.',
        'target','/p/music-hub.html'
      ),
      jsonb_build_object(
        'key','scalable_broadcast_sfu_turn',
        'title','TGG Broadcast Engine SFU/TURN',
        'code_ready',true,
        'external_required',true,
        'state',case
          when coalesce((v_ext#>>'{broadcast_engine,ready}')::boolean,false) then 'ready'
          when coalesce((v_ext#>>'{broadcast_engine,endpoint_configured}')::boolean,false) then 'credentials_required'
          else 'deployment_required'
        end,
        'requirement','The LiveKit WSS endpoint, control plane, room authorization, and token systems are ready. LiveKit credentials are the remaining connection requirement.',
        'target','/p/live.html'
      ),
      jsonb_build_object(
        'key','two_user_call_validation',
        'title','Two-User Call Validation',
        'code_ready',true,
        'external_required',true,
        'state',case when coalesce((v_launch->'checks'->>'two_user_call_validated')::boolean,false) then 'validated' else 'second_user_required' end,
        'requirement','A second legitimate signed-in creator/device is required for the final WebRTC offer/answer validation.',
        'target','/p/live.html#calls'
      ),
      jsonb_build_object(
        'key','leaked_password_protection',
        'title','Leaked Password Protection',
        'code_ready',true,
        'external_required',true,
        'state',case when coalesce((v_launch->'checks'->>'leaked_password_protection_enabled')::boolean,false) then 'enabled' else 'account_setting_required' end,
        'requirement','Enable the hosted Supabase Auth leaked-password protection setting.',
        'target','https://supabase.com/dashboard/project/xsofowzvwetamhyuvlpj/auth/providers?provider=Email'
      )
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000783] function public.tgg_external_infrastructure_final_health()
CREATE OR REPLACE FUNCTION public.tgg_external_infrastructure_final_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with cfg as (
  select
    coalesce((select enabled and endpoint_configured and mode='production'
              from public.tgg_provider_runtime_config where provider_key='stripe'),false) as stripe_native_ready,
    coalesce((select endpoint_configured
              from public.tgg_provider_runtime_config where provider_key='stripe.webhook'),false) as stripe_webhook_endpoint_ready,
    coalesce((select enabled and endpoint_configured and mode='production'
              from public.tgg_provider_runtime_config where provider_key='stripe.webhook'),false) as stripe_webhook_runtime_ready,
    coalesce((select disabled_reason
              from public.tgg_provider_runtime_config where provider_key='stripe.webhook'),'') as stripe_webhook_reason,
    coalesce((select enabled and endpoint_configured and mode='production'
              from public.tgg_provider_runtime_config where provider_key='stripe.payment_link'),false) as stripe_payment_link_ready,
    coalesce((select enabled and endpoint_configured and mode='production'
              from public.tgg_provider_runtime_config where provider_key='membership.payment_link'),false) as membership_payment_link_ready,
    coalesce((select enabled and endpoint_configured and mode='production'
              from public.tgg_provider_runtime_config where provider_key='distribution.provider'),false) as distribution_ready,
    coalesce((select endpoint_configured
              from public.tgg_provider_runtime_config where provider_key='distribution.provider'),false) as distribution_endpoint_configured,
    coalesce((select disabled_reason
              from public.tgg_provider_runtime_config where provider_key='distribution.provider'),'') as distribution_disabled_reason,
    coalesce((select enabled and endpoint_configured and mode='production'
              from public.tgg_provider_runtime_config where provider_key='broadcast.sfu_turn'),false) as broadcast_ready,
    coalesce((select endpoint_configured
              from public.tgg_provider_runtime_config where provider_key='broadcast.sfu_turn'),false) as broadcast_endpoint_configured,
    coalesce((select disabled_reason
              from public.tgg_provider_runtime_config where provider_key='broadcast.sfu_turn'),'') as broadcast_disabled_reason
)
select jsonb_build_object(
  'ok',true,
  'version','EXTERNAL-INFRA-ONE-FINAL-1.4',
  'stripe',jsonb_build_object(
    'ready',cfg.stripe_native_ready or cfg.stripe_payment_link_ready,
    'commerce_ready',cfg.stripe_native_ready or cfg.stripe_payment_link_ready,
    'native_checkout_ready',cfg.stripe_native_ready,
    'webhook_endpoint_ready',cfg.stripe_webhook_endpoint_ready,
    'webhook_runtime_ready',cfg.stripe_webhook_runtime_ready,
    'webhook_ready',cfg.stripe_webhook_runtime_ready,
    'webhook_pending_reason',case
      when cfg.stripe_webhook_runtime_ready then null
      when cfg.stripe_webhook_endpoint_ready then nullif(cfg.stripe_webhook_reason,'')
      else 'stripe_webhook_endpoint_missing'
    end,
    'payment_link_ready',cfg.stripe_payment_link_ready,
    'membership_payment_link_ready',cfg.membership_payment_link_ready,
    'mode',case
      when cfg.stripe_native_ready then 'native_checkout'
      when cfg.stripe_payment_link_ready then 'payment_link'
      else 'disabled'
    end,
    'native_upgrade_pending',not cfg.stripe_native_ready,
    'reason',case
      when cfg.stripe_native_ready then null
      when cfg.stripe_payment_link_ready then 'production_payment_link_active_native_checkout_optional'
      when cfg.stripe_webhook_runtime_ready then 'stripe_native_checkout_secret_missing_webhook_ready'
      else 'stripe_server_runtime_not_ready'
    end
  ),
  'dsp_distribution',jsonb_build_object(
    'ready',cfg.distribution_ready,
    'endpoint_configured',cfg.distribution_endpoint_configured,
    'reason',case
      when cfg.distribution_ready then null
      when cfg.distribution_endpoint_configured and cfg.distribution_disabled_reason='activation_bridge_secret_required'
        then 'production_credentials_required'
      when cfg.distribution_endpoint_configured then 'provider_activation_required'
      else 'production_endpoint_required'
    end
  ),
  'broadcast_engine',jsonb_build_object(
    'ready',cfg.broadcast_ready,
    'endpoint_configured',cfg.broadcast_endpoint_configured,
    'reason',case
      when cfg.broadcast_ready then null
      when cfg.broadcast_endpoint_configured and cfg.broadcast_disabled_reason='activation_bridge_secret_required'
        then 'livekit_credentials_required'
      when cfg.broadcast_endpoint_configured then 'provider_activation_required'
      else 'sfu_turn_infrastructure_required'
    end
  ),
  'two_user_call',public.tgg_call_validation_final_health(),
  'leaked_password_protection',jsonb_build_object(
    'ready',false,
    'reason','supabase_auth_dashboard_setting_required'
  ),
  'generated_at',now()
)
from cfg;
$function$


-- [40000000784] function public.tgg_external_optional_upgrades_final()
CREATE OR REPLACE FUNCTION public.tgg_external_optional_upgrades_final()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_h jsonb:=public.tgg_external_infrastructure_final_health();
  v_a jsonb:=public.tgg_optional_upgrade_activation_health();
  v_out jsonb:='[]'::jsonb;
begin
  if not coalesce((v_h->'dsp_distribution'->>'ready')::boolean,false) then
    v_out:=v_out||jsonb_build_array(jsonb_build_object(
      'key','dsp_distribution_provider',
      'ready',false,
      'optional',true,
      'category','feature_expansion',
      'candidate',null,
      'provider_selection','external_dsp_delivery_provider_required',
      'adapter_ready',coalesce((v_a->'distribution'->>'adapter_ready')::boolean,false),
      'activation_state','provider_connection_pending',
      'fallback','distribution_package_export',
      'reason',coalesce(v_h->'dsp_distribution'->>'reason','production_endpoint_required')
    ));
  end if;

  if not coalesce((v_h->'broadcast_engine'->>'ready')::boolean,false) then
    v_out:=v_out||jsonb_build_array(jsonb_build_object(
      'key','scalable_broadcast_sfu_turn',
      'ready',false,
      'optional',true,
      'category','feature_expansion',
      'adapter_ready',coalesce((v_a->'broadcast'->>'adapter_ready')::boolean,false),
      'control_plane_ready',coalesce((v_a->'broadcast'->>'control_plane_ready')::boolean,false),
      'activation_state','provider_connection_pending',
      'current_mode','webrtc_control_plane_and_local_capture',
      'reason',coalesce(v_h->'broadcast_engine'->>'reason','sfu_turn_infrastructure_required')
    ));
  end if;

  if not coalesce((v_h->'two_user_call'->>'validated')::boolean,false) then
    v_out:=v_out||jsonb_build_array(jsonb_build_object(
      'key','two_user_call_validation',
      'ready',false,
      'optional',true,
      'category','validation',
      'harness_ready',coalesce((v_a->'call_validation'->>'harness_ready')::boolean,false),
      'room_creation_ready',coalesce((v_a->'call_validation'->>'room_creation_ready')::boolean,false),
      'signal_exchange_ready',coalesce((v_a->'call_validation'->>'signal_exchange_ready')::boolean,false),
      'activation_state','second_device_pending',
      'reason','second_legitimate_creator_device_required'
    ));
  end if;

  return v_out;
end
$function$


-- [40000000785] function public.tgg_fan_crm_update(p_crm_id uuid, p_segment text, p_tags jsonb, p_private_notes text, p_mark_contacted boolean)
CREATE OR REPLACE FUNCTION public.tgg_fan_crm_update(p_crm_id uuid, p_segment text, p_tags jsonb, p_private_notes text, p_mark_contacted boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_seg text:=lower(coalesce(nullif(btrim(coalesce(p_segment,'')),''),'fan'));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_seg not in ('new','fan','active','superfan','supporter','slipping','dormant','vip') then raise exception 'SEGMENT_INVALID'; end if;
  if jsonb_typeof(coalesce(p_tags,'[]'::jsonb))<>'array' then raise exception 'TAGS_MUST_BE_ARRAY'; end if;
  update public.tgg_fan_crm
  set segment=v_seg,
      tags=coalesce(p_tags,'[]'::jsonb),
      private_notes=nullif(btrim(coalesce(p_private_notes,'')),''),
      last_contacted_at=case when coalesce(p_mark_contacted,false) then now() else last_contacted_at end,
      updated_at=now()
  where id=p_crm_id and creator_user_id=v_uid
  returning id into v_id;
  if v_id is null then raise exception 'FAN_CRM_RECORD_NOT_FOUND'; end if;
  return jsonb_build_object('ok',true,'crm_id',v_id,'segment',v_seg);
end $function$


-- [40000000786] function public.tgg_fan_following_feed(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_fan_following_feed(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_limit integer:=greatest(1,least(coalesce(p_limit,50),100));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'version','FAN-FEED-ONE-FINAL-1.0',
    'following_count',(select count(*) from public.artist_follows f where f.user_id=v_uid),
    'artists',coalesce((
      select jsonb_agg(jsonb_build_object(
        'artist_id',a.artist_id,'stage_name',a.stage_name,'avatar_url',a.avatar_url,'bio',a.bio,
        'profile_url','/p/public-artist-profile.html?artist_id='||a.artist_id::text
      ) order by f.created_at desc)
      from public.artist_follows f
      join public.public_artist_directory_v1 a on a.artist_id=f.artist_id
      where f.user_id=v_uid
    ),'[]'::jsonb),
    'feed',coalesce((
      select jsonb_agg(x.item order by x.sort_at desc)
      from (
        select jsonb_build_object(
          'kind','release','id',m.id,'artist_id',a.id,'artist_name',a.stage_name,'artist_avatar',a.avatar_url,
          'title',m.title,'subtitle',m.genre,'image_url',m.cover_url,'created_at',coalesce(m.release_date,m.created_at),
          'url','/p/mixtape.html?id='||m.id::text
        ) item,coalesce(m.release_date,m.created_at) sort_at
        from public.artist_follows f
        join public.artists a on a.id=f.artist_id
        join public.mixtapes m on m.artist_id=a.id and m.status='published'
        where f.user_id=v_uid

        union all

        select jsonb_build_object(
          'kind','short','id',s.id,'artist_id',a.id,'artist_name',a.stage_name,'artist_avatar',a.avatar_url,
          'title',coalesce(s.caption,'Short'),'subtitle','Short','image_url',s.thumbnail_url,'media_url',s.media_url,
          'created_at',s.created_at,'url','/p/shorts.html'
        ),s.created_at
        from public.artist_follows f
        join public.artists a on a.id=f.artist_id
        join public.tgg_shorts s on s.user_id=a.user_id and s.status='published' and s.visibility='public'
        where f.user_id=v_uid

        union all

        select jsonb_build_object(
          'kind','radio','id',r.id,'artist_id',a.id,'artist_name',a.stage_name,'artist_avatar',a.avatar_url,
          'title',r.title,'subtitle',r.show_type,'image_url',r.artwork_url,'audio_url',r.audio_url,
          'created_at',coalesce(r.published_at,r.created_at),'url','/p/tgg-radio.html'
        ),coalesce(r.published_at,r.created_at)
        from public.artist_follows f
        join public.artists a on a.id=f.artist_id
        join public.tgg_radio_shows r on r.user_id=a.user_id and r.status='published'
        where f.user_id=v_uid

        union all

        select jsonb_build_object(
          'kind','live','id',l.id,'artist_id',a.id,'artist_name',a.stage_name,'artist_avatar',a.avatar_url,
          'title',l.title,'subtitle','LIVE','created_at',coalesce(l.actual_start,l.created_at),
          'url','/p/live.html?stream='||l.id::text
        ),coalesce(l.actual_start,l.created_at)
        from public.artist_follows f
        join public.artists a on a.id=f.artist_id
        join public.live_streams l on l.creator_id=a.user_id and l.status='LIVE' and l.audience='everyone'
        where f.user_id=v_uid
        order by 2 desc
        limit v_limit
      ) x
    ),'[]'::jsonb),
    'generated_at',now()
  );
end $function$


