-- [40000000788] function public.tgg_feature_runtime_health()
CREATE OR REPLACE FUNCTION public.tgg_feature_runtime_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
select jsonb_build_object(
  'ok',true,
  'version','FEATURE-RUNTIME-1.2',
  'modules',jsonb_build_object(
    'studio',jsonb_build_object('ready',to_regprocedure('public.tgg_creator_studio_bundle()') is not null and to_regclass('public.tgg_studio_projects') is not null,'bundle','tgg_creator_studio_bundle'),
    'beat_studio',jsonb_build_object('ready',to_regprocedure('public.tgg_creator_beatmaker_bundle()') is not null and to_regclass('public.tgg_beat_patterns') is not null,'bundle','tgg_creator_beatmaker_bundle'),
    'video_studio',jsonb_build_object('ready',to_regprocedure('public.tgg_video_pipeline_final_health()') is not null and to_regclass('public.tgg_video_timeline_items') is not null,'bundle','tgg_video_pipeline_final_health'),
    'live',jsonb_build_object('ready',to_regprocedure('public.tgg_creator_live_studio_bundle()') is not null and to_regclass('public.live_streams') is not null,'bundle','tgg_creator_live_studio_bundle'),
    'collaboration',jsonb_build_object('ready',to_regprocedure('public.tgg_creator_collab_bundle()') is not null and to_regclass('public.tgg_studio_project_members') is not null,'bundle','tgg_creator_collab_bundle'),
    'messaging',jsonb_build_object('ready',to_regprocedure('public.tgg_creator_communications_bundle()') is not null and to_regclass('public.tgg_messages') is not null,'bundle','tgg_creator_communications_bundle'),
    'store',jsonb_build_object('ready',to_regprocedure('public.tgg_creator_store_bundle()') is not null and to_regclass('public.public_store_v1') is not null,'bundle','tgg_creator_store_bundle'),
    'career',jsonb_build_object('ready',to_regprocedure('public.tgg_creator_career_bundle()') is not null and to_regprocedure('public.tgg_get_creator_career_workspace_bundle(uuid)') is not null,'bundle','tgg_creator_career_bundle'),
    'vault',jsonb_build_object('ready',to_regclass('public.tgg_vault_items') is not null and to_regclass('public.tgg_media_vault_assets') is not null,'bundle',null),
    'games_tv',jsonb_build_object('ready',to_regprocedure('public.tgg_creator_games_bundle(integer)') is not null and to_regclass('public.tgg_games') is not null,'bundle','tgg_creator_games_bundle'),
    'audiobooks',jsonb_build_object('ready',to_regprocedure('public.tgg_creator_audiobooks_bundle()') is not null and to_regclass('public.tgg_audiobooks') is not null,'bundle','tgg_creator_audiobooks_bundle'),
    'analytics',jsonb_build_object(
      'ready',to_regclass('public.creator_analytics_events') is not null
        and to_regprocedure('public.tgg_record_creator_event(text,uuid,text,text,jsonb)') is not null,
      'bundle','creator_analytics_events'
    ),
    'payments',jsonb_build_object(
      'ready',to_regprocedure('public.tgg_get_provider_pipeline_health()') is not null
        and to_regclass('public.tgg_provider_runtime_config') is not null,
      'bundle','tgg_get_provider_pipeline_health'
    )
  ),
  'generated_at',now()
);
$function$


-- [40000000789] function public.tgg_final_activation_handoff(p_payload jsonb)
CREATE OR REPLACE FUNCTION public.tgg_final_activation_handoff(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text:=coalesce(auth.jwt()->'app_metadata'->>'tgg_role','');
  v_payload jsonb:=coalesce(p_payload,'{}'::jsonb);
  v_results jsonb:='{}'::jsonb;
  v_stripe_secret text;
  v_revelator_secret text;
  v_livekit_url text;
  v_livekit_key text;
  v_livekit_secret text;
  v_livekit_bundle text;
  v_bowser jsonb;
  v_lets jsonb;
  v_tmp jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  if jsonb_typeof(v_payload)<>'object' then
    raise exception 'PAYLOAD_MUST_BE_OBJECT' using errcode='22023';
  end if;

  if v_payload ? 'stripe_webhook_signing_secret' then
    begin
      v_stripe_secret:=nullif(btrim(v_payload->>'stripe_webhook_signing_secret'),'');
      if v_stripe_secret is null then
        v_results:=v_results||jsonb_build_object(
          'stripe',jsonb_build_object(
            'ok',false,'secret_returned',false,'error_code','STRIPE_SECRET_REQUIRED'
          )
        );
      else
        perform public.tgg_store_provider_secret('stripe.webhook',v_stripe_secret);
        v_tmp:=public.tgg_membership_activate_if_ready(
          '280efcec-1bb1-41e2-a048-945b4b742f3b'::uuid
        );
        v_results:=v_results||jsonb_build_object(
          'stripe',jsonb_build_object(
            'ok',true,
            'secret_stored',true,
            'secret_returned',false,
            'membership_finalize_attempted',true,
            'membership_result',v_tmp
          )
        );
      end if;
    exception
      when sqlstate '22023' then
        v_results:=v_results||jsonb_build_object(
          'stripe',jsonb_build_object(
            'ok',false,'secret_returned',false,'error_code','STRIPE_SECRET_INVALID'
          )
        );
      when others then
        v_results:=v_results||jsonb_build_object(
          'stripe',jsonb_build_object(
            'ok',false,'secret_returned',false,'error_code','STRIPE_ACTIVATION_FAILED'
          )
        );
    end;
  else
    v_results:=v_results||jsonb_build_object(
      'stripe',jsonb_build_object('ok',true,'skipped',true,'reason','input_not_supplied')
    );
  end if;

  if v_payload ? 'bowser_on_it' then
    begin
      v_bowser:=coalesce(v_payload->'bowser_on_it','{}'::jsonb);
      if jsonb_typeof(v_bowser)<>'object' then
        v_results:=v_results||jsonb_build_object(
          'bowser_on_it',jsonb_build_object(
            'ok',false,'error_code','BOWSER_METADATA_MUST_BE_OBJECT'
          )
        );
      else
        v_tmp:=public.tgg_distribution_metadata_upsert(
          'b95ffce9-a4a1-42ea-9dcb-c3cb7375600f'::uuid,
          v_bowser->>'label_name',
          v_bowser->>'copyright_line',
          v_bowser->>'publishing_line',
          coalesce(nullif(v_bowser->>'primary_language',''),'en'),
          coalesce(v_bowser->'territories','[]'::jsonb),
          coalesce((v_bowser->>'rights_confirmed')::boolean,false),
          v_bowser->>'notes'
        );
        v_results:=v_results||jsonb_build_object(
          'bowser_on_it',jsonb_build_object('ok',true,'saved',true,'result',v_tmp)
        );
      end if;
    exception
      when invalid_text_representation then
        v_results:=v_results||jsonb_build_object(
          'bowser_on_it',jsonb_build_object('ok',false,'error_code','BOWSER_METADATA_INVALID')
        );
      when others then
        v_results:=v_results||jsonb_build_object(
          'bowser_on_it',jsonb_build_object('ok',false,'error_code','BOWSER_METADATA_SAVE_FAILED')
        );
    end;
  else
    v_results:=v_results||jsonb_build_object(
      'bowser_on_it',jsonb_build_object('ok',true,'skipped',true,'reason','input_not_supplied')
    );
  end if;

  if v_payload ? 'lets_get_it' then
    begin
      v_lets:=coalesce(v_payload->'lets_get_it','{}'::jsonb);
      if jsonb_typeof(v_lets)<>'object' then
        v_results:=v_results||jsonb_build_object(
          'lets_get_it',jsonb_build_object(
            'ok',false,'error_code','LETS_GET_IT_METADATA_MUST_BE_OBJECT'
          )
        );
      else
        v_tmp:=public.tgg_distribution_metadata_upsert(
          '0c6e3ff9-186a-4df2-ac3f-3ae917ba44a8'::uuid,
          v_lets->>'label_name',
          v_lets->>'copyright_line',
          v_lets->>'publishing_line',
          coalesce(nullif(v_lets->>'primary_language',''),'en'),
          coalesce(v_lets->'territories','[]'::jsonb),
          coalesce((v_lets->>'rights_confirmed')::boolean,false),
          v_lets->>'notes'
        );
        v_results:=v_results||jsonb_build_object(
          'lets_get_it',jsonb_build_object('ok',true,'saved',true,'result',v_tmp)
        );
      end if;
    exception
      when invalid_text_representation then
        v_results:=v_results||jsonb_build_object(
          'lets_get_it',jsonb_build_object('ok',false,'error_code','LETS_GET_IT_METADATA_INVALID')
        );
      when others then
        v_results:=v_results||jsonb_build_object(
          'lets_get_it',jsonb_build_object('ok',false,'error_code','LETS_GET_IT_METADATA_SAVE_FAILED')
        );
    end;
  else
    v_results:=v_results||jsonb_build_object(
      'lets_get_it',jsonb_build_object('ok',true,'skipped',true,'reason','input_not_supplied')
    );
  end if;

  if v_payload ? 'revelator_production_api_credential' then
    begin
      v_revelator_secret:=nullif(btrim(v_payload->>'revelator_production_api_credential'),'');
      if v_revelator_secret is null then
        v_results:=v_results||jsonb_build_object(
          'revelator',jsonb_build_object(
            'ok',false,'secret_returned',false,'error_code','REVELATOR_CREDENTIAL_REQUIRED'
          )
        );
      else
        perform public.tgg_store_provider_secret('distribution.provider',v_revelator_secret);
        perform public.tgg_provider_activation_stage(
          'distribution.provider',
          'https://api.revelator.com',
          'tgg_distribution_provider_secret'
        );
        v_tmp:=public.tgg_provider_activation_verify('distribution.provider');

        v_results:=v_results||jsonb_build_object(
          'revelator',jsonb_build_object(
            'ok',true,
            'secret_stored',true,
            'secret_returned',false,
            'endpoint','https://api.revelator.com',
            'verification_scope','reachability_only',
            'credentials_verified',false,
            'reachability_verification',v_tmp
          )
        );
      end if;
    exception
      when sqlstate '22023' then
        v_results:=v_results||jsonb_build_object(
          'revelator',jsonb_build_object(
            'ok',false,'secret_returned',false,'error_code','REVELATOR_CREDENTIAL_INVALID'
          )
        );
      when others then
        v_results:=v_results||jsonb_build_object(
          'revelator',jsonb_build_object(
            'ok',false,'secret_returned',false,'error_code','REVELATOR_ACTIVATION_FAILED'
          )
        );
    end;
  else
    v_results:=v_results||jsonb_build_object(
      'revelator',jsonb_build_object('ok',true,'skipped',true,'reason','input_not_supplied')
    );
  end if;

  if (v_payload ? 'livekit_url')
     or (v_payload ? 'livekit_api_key')
     or (v_payload ? 'livekit_api_secret')
  then
    begin
      v_livekit_url:=nullif(btrim(v_payload->>'livekit_url'),'');
      v_livekit_key:=nullif(btrim(v_payload->>'livekit_api_key'),'');
      v_livekit_secret:=nullif(btrim(v_payload->>'livekit_api_secret'),'');

      if v_livekit_url is null or v_livekit_key is null or v_livekit_secret is null then
        v_results:=v_results||jsonb_build_object(
          'livekit',jsonb_build_object(
            'ok',false,'secret_returned',false,'error_code','LIVEKIT_URL_KEY_SECRET_REQUIRED_TOGETHER'
          )
        );
      else
        v_livekit_bundle:=jsonb_build_object(
          'api_key',v_livekit_key,
          'api_secret',v_livekit_secret
        )::text;

        perform public.tgg_store_provider_secret('broadcast.sfu_turn',v_livekit_bundle);
        perform public.tgg_provider_activation_stage(
          'broadcast.sfu_turn',
          v_livekit_url,
          'tgg_broadcast_provider_secret'
        );
        v_tmp:=public.tgg_provider_activation_verify('broadcast.sfu_turn');

        v_results:=v_results||jsonb_build_object(
          'livekit',jsonb_build_object(
            'ok',true,
            'secret_stored',true,
            'secret_returned',false,
            'endpoint',v_livekit_url,
            'verification_scope','reachability_only',
            'credentials_verified',false,
            'reachability_verification',v_tmp
          )
        );
      end if;
    exception
      when sqlstate '22023' then
        v_results:=v_results||jsonb_build_object(
          'livekit',jsonb_build_object(
            'ok',false,'secret_returned',false,'error_code','LIVEKIT_INPUT_INVALID'
          )
        );
      when others then
        v_results:=v_results||jsonb_build_object(
          'livekit',jsonb_build_object(
            'ok',false,'secret_returned',false,'error_code','LIVEKIT_ACTIVATION_FAILED'
          )
        );
    end;
  else
    v_results:=v_results||jsonb_build_object(
      'livekit',jsonb_build_object('ok',true,'skipped',true,'reason','input_not_supplied')
    );
  end if;

  perform public.tgg_one_final_activation_queue_refresh();

  return jsonb_build_object(
    'ok',true,
    'version','FINAL-ACTIVATION-HANDOFF-1.2',
    'results',v_results,
    'secrets_echoed',false,
    'raw_sql_errors_exposed',false,
    'partial_inputs_supported',true,
    'sections_isolated',true,
    'activation_packets',public.tgg_activation_packets_final(),
    'launch_scope',public.tgg_launch_scope_final(),
    'generated_at',now()
  );
end
$function$


-- [40000000790] function public.tgg_final_platform_health()
CREATE OR REPLACE FUNCTION public.tgg_final_platform_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist uuid;
  v_baseline jsonb;
  v_drift jsonb;
  v_blog jsonb;
  v_provider jsonb;
  v_live jsonb;
  v_live_checked timestamptz;
  v_live_fresh boolean:=false;
  v_live_complete boolean:=false;
  v_live_verified boolean:=false;
  v_locked_pages integer:=0;
  v_live_pages integer:=0;
  v_expected_routes int;
  v_current_routes int;
  v_runtime_drift_count int:=0;
  v_rollback_drift_count int:=0;
  v_core_ok boolean:=false;
  v_rollback_ready boolean:=false;
  v_maintenance_ready boolean:=false;
  v_commerce_ready boolean:=false;
  v_commerce_required boolean:=false;
  v_external jsonb;
  v_version text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  v_baseline:=private.tgg_production_baseline();
  v_version:=coalesce(v_baseline->>'version','UNLOCKED');
  v_drift:=private.tgg_production_baseline_drift();
  v_blog:=public.tgg_get_blogger_bridge_health();
  v_provider:=public.tgg_get_provider_pipeline_health();
  v_live:=coalesce(v_baseline#>'{notes,live_blogger_hash_monitor}','{}'::jsonb);

  begin
    v_live_checked:=(v_live->>'checked_at')::timestamptz;
    v_live_fresh:=v_live_checked>=now()-interval '40 minutes';
  exception when others then
    v_live_fresh:=false;
  end;

  v_locked_pages:=coalesce((v_live->>'locked_pages')::integer,0);
  v_live_pages:=coalesce((v_live->>'live_pages_checked')::integer,0);
  v_live_complete:=v_locked_pages>0 and v_live_pages=v_locked_pages;
  v_live_verified:=coalesce((v_live->>'ok')::boolean,false) and v_live_complete;

  v_expected_routes:=coalesce((v_drift->>'expected_route_paths')::int,0);
  v_current_routes:=coalesce((v_drift->>'current_route_paths')::int,0);

  select
    count(*) filter(
      where coalesce(x->>'type','') not in (
        'backup_hash_parity',
        'validated_restore_objects',
        'rollback_readiness'
      )
    ),
    count(*) filter(
      where coalesce(x->>'type','') in (
        'backup_hash_parity',
        'validated_restore_objects',
        'rollback_readiness'
      )
    )
  into v_runtime_drift_count,v_rollback_drift_count
  from jsonb_array_elements(coalesce(v_drift->'drift','[]'::jsonb)) x;

  v_core_ok :=
    v_runtime_drift_count=0
    and v_expected_routes>0
    and v_expected_routes=v_current_routes
    and v_artist is not null;

  v_rollback_ready :=
    v_rollback_drift_count=0
    and coalesce((v_drift->>'restorable_pages')::int,0)
      = coalesce((v_drift->>'expected_pages')::int,0)
    and coalesce((v_drift->>'validated_restore_objects')::int,0)
      = coalesce((v_drift->>'expected_pages')::int,0);

  v_maintenance_ready := coalesce((v_blog->>'ok')::boolean,false);

  v_commerce_ready :=
    coalesce((v_provider#>>'{payments,ready}')::boolean,false);

  v_commerce_required :=
    exists(
      select 1
      from public.merch_products
      where status='published'
    )
    or exists(
      select 1
      from public.tgg_membership_tiers
      where coalesce(is_active,true)=true
    );

  v_external:=jsonb_build_array(
    'Supabase leaked-password protection setting remains disabled',
    'Production DSP endpoint is not configured',
    'Two-user realtime/call smoke requires a second legitimate account/device'
  );

  if not v_maintenance_ready then
    v_external:=v_external || jsonb_build_array(
      'Blogger deployment maintenance requires Google OAuth reauthorization; live pages and existing backups remain intact'
    );
  end if;

  if not v_rollback_ready then
    v_external:=v_external || jsonb_build_array(
      'Some rollback copies predate the current locked page content and require Blogger OAuth before exact backup parity can be refreshed'
    );
  end if;

  if not v_commerce_ready then
    v_external:=v_external || jsonb_build_array(
      case
        when v_commerce_required then
          'Store checkout session creation is disabled until the Stripe server secret is restored in the Edge runtime'
        else
          'Stripe checkout runtime is in standby; no published products or active membership tiers currently require checkout'
      end
    );
  end if;

  return jsonb_build_object(
    'ok',v_core_ok and (not v_commerce_required or v_commerce_ready),
    'core_ok',v_core_ok,
    'runtime_integrity_ready',v_core_ok,
    'runtime_drift_count',v_runtime_drift_count,
    'rollback_ready',v_rollback_ready,
    'rollback_drift_count',v_rollback_drift_count,
    'maintenance_ready',v_maintenance_ready,
    'maintenance_status',case
      when v_maintenance_ready then 'ready'
      when coalesce(v_blog#>>'{blog,last_error}','')='google_oauth_invalid_grant'
        then 'google_reauth_required'
      else 'degraded'
    end,
    'live_verification_ready',v_live_verified,
    'live_verification_fresh',v_live_fresh,
    'live_verification_status',case
      when v_live_verified and v_live_fresh then 'verified_fresh'
      when v_live_verified then 'verified_stale'
      else 'unverified'
    end,
    'commerce_ready',v_commerce_ready,
    'commerce_required',v_commerce_required,
    'launch_status',case
      when v_core_ok and (not v_commerce_required or v_commerce_ready) then
        case
          when not v_maintenance_ready then 'runtime_ready_maintenance_reauth_required'
          when not v_rollback_ready then 'runtime_ready_rollback_refresh_required'
          when not v_live_fresh then 'runtime_ready_live_verification_stale'
          when v_commerce_required then 'ready'
          else 'ready_commerce_standby'
        end
      when v_core_ok and v_commerce_required and not v_commerce_ready then
        'core_ready_checkout_blocked'
      else 'degraded'
    end,
    'baseline',v_version,
    'version',v_version,
    'locked_at',v_baseline->>'locked_at',
    'artist_ready',v_artist is not null,
    'artist_id',v_artist,
    'blogger',v_blog,
    'blogger_live_content',
      v_live || jsonb_build_object(
        'fresh',v_live_fresh,
        'complete',v_live_complete,
        'verified',v_live_verified
      ),
    'providers',v_provider,
    'drift',v_drift,
    'route_integrity',jsonb_build_object(
      'ok',v_expected_routes>0 and v_expected_routes=v_current_routes,
      'expected_unique_page_paths',v_expected_routes,
      'present_count',v_current_routes,
      'missing_count',greatest(v_expected_routes-v_current_routes,0),
      'source','dynamic_locked_baseline_drift_contract'
    ),
    'rollback_integrity',jsonb_build_object(
      'ready',v_rollback_ready,
      'restorable_pages',coalesce((v_drift->>'restorable_pages')::int,0),
      'validated_backup_hashes',coalesce((v_drift->>'validated_backup_hashes')::int,0),
      'validated_restore_objects',coalesce((v_drift->>'validated_restore_objects')::int,0)
    ),
    'stripe_runtime_incident',v_baseline#>'{notes,stripe_runtime_incident}',
    'edge_function_capacity',v_baseline#>'{notes,edge_function_capacity}',
    'public_contract',jsonb_build_object(
      'accessible_routes',jsonb_array_length(public.tgg_get_site_route_manifest()),
      'registered_routes_total',coalesce((v_baseline->>'public_routes')::int,0),
      'public_routes',(select count(*) from public.tgg_site_routes where is_active and access_level='public'),
      'accessible_page_paths',(select count(distinct path) from public.tgg_site_routes where is_active and path like '/p/%'),
      'registered_page_paths',v_expected_routes,
      'catalog_releases',(select count(*) from public.tgg_public_mixtape_catalog()),
      'homepage_bundle',public.tgg_get_public_home_bundle(6) is not null
    ),
    'creator_contract',jsonb_build_object(
      'bootstrap',public.tgg_get_creator_bootstrap_bundle() is not null,
      'dashboard',case
        when v_artist is null then false
        else public.tgg_get_creator_dashboard_bundle(v_artist,12) is not null
      end,
      'app',public.tgg_creator_os_app_bundle() is not null,
      'master',public.tgg_creator_os_master_status() is not null
    ),
    'pending_blogger_patches',coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'path',path,
          'status',status,
          'blocked_reason',blocked_reason,
          'patched_hash',patched_hash
        )
        order by path
      )
      from public.tgg_blogger_pending_patches
      where status in ('staged','blocked_google_reauth')
    ),'[]'::jsonb),
    'known_external_items',v_external,
    'generated_at',now()
  );
end
$function$


-- [40000000791] function public.tgg_final_qa_sweep()
CREATE OR REPLACE FUNCTION public.tgg_final_qa_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_creator jsonb;
  v_public jsonb;
  v_admin jsonb;
  v_ops jsonb;
  v_db jsonb;
  v_auth jsonb;
  v_drift jsonb;
  v_artist_dir jsonb;
  v_artist_profile jsonb;
  v_artist_id uuid;
  v_tables_without_rls bigint;
  v_client_secdef bigint;
  v_non_invoker_views bigint;
  v_realtime bigint;
  v_zero_direct_db boolean:=false;
  v_internal_ready boolean;
  v_blockers jsonb;
  v_optional jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  v_creator:=public.tgg_creator_os_final_bundle();
  v_public:=public.tgg_public_one_final_bundle();
  v_admin:=public.tgg_admin_os_final_bundle();
  v_ops:=public.tgg_operations_final_health();
  v_db:=public.tgg_database_final_health();
  v_auth:=public.tgg_auth_final_health();
  v_drift:=public.tgg_final_platform_health()->'drift';
  v_blockers:=public.tgg_external_blockers_final();
  v_optional:=public.tgg_external_optional_upgrades_final();

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  v_artist_dir:=public.tgg_public_artist_discovery_one_final(null,50);
  if v_artist_id is not null then
    v_artist_profile:=public.tgg_public_artist_profile_one_final(v_artist_id);
  else
    v_artist_profile:='{}'::jsonb;
  end if;

  select count(*) into v_tables_without_rls
  from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='public' and c.relkind='r' and not c.relrowsecurity;

  select count(*) into v_client_secdef
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.prosecdef
    and (
      has_function_privilege('anon',p.oid,'EXECUTE')
      or has_function_privilege('authenticated',p.oid,'EXECUTE')
    );

  select count(*) into v_non_invoker_views
  from pg_class c
  join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='public' and c.relkind='v'
    and (
      has_table_privilege('anon',c.oid,'SELECT')
      or has_table_privilege('authenticated',c.oid,'SELECT')
    )
    and not coalesce((
      select bool_or(o.option_name='security_invoker' and o.option_value='true')
      from pg_options_to_table(c.reloptions) o
    ),false);

  select count(*) into v_realtime
  from pg_publication_tables
  where pubname='supabase_realtime';

  v_zero_direct_db:=coalesce((v_creator->'build_manifest'->>'blogger_direct_database_pages_zero')::boolean,false);

  v_internal_ready :=
       coalesce((v_auth->>'ready')::boolean,false)
   and coalesce((v_drift->>'ok')::boolean,false)
   and coalesce((v_db->>'ready')::boolean,true)
   and v_tables_without_rls=0
   and v_client_secdef=0
   and v_non_invoker_views=0
   and v_realtime=6
   and coalesce((v_ops->'cron'->>'all_recent_runs_healthy')::boolean,false)
   and coalesce((v_ops->'blogger'->>'rollback_ready')::boolean,false)
   and coalesce((v_artist_dir->>'ok')::boolean,false)
   and coalesce((v_artist_profile->>'ok')::boolean,false)
   and v_zero_direct_db;

  return jsonb_build_object(
    'ok',true,
    'version','FINAL-QA-ONE-FINAL-1.2',
    'internal_product_ready',v_internal_ready,
    'status',case
      when v_internal_ready and jsonb_array_length(v_blockers)=0 then 'ready_with_optional_upgrades'
      when v_internal_ready then 'external_blocker_attention_required'
      else 'internal_attention_required'
    end,
    'versions',jsonb_build_object(
      'creator',v_creator->'app'->>'version',
      'public',v_public->>'version',
      'admin',v_admin->>'version',
      'operations',v_ops->>'version',
      'artist_discovery',v_artist_dir->>'version',
      'artist_profile',v_artist_profile->>'version'
    ),
    'artist_discovery_profile',jsonb_build_object(
      'directory_ready',coalesce((v_artist_dir->>'ok')::boolean,false),
      'profile_ready',coalesce((v_artist_profile->>'ok')::boolean,false),
      'artist_count',jsonb_array_length(coalesce(v_artist_dir->'artists','[]'::jsonb)),
      'follow_unfollow',true,
      'follower_counts',true,
      'social_links',true,
      'release_links',true,
      'video_links',true,
      'live_link',true,
      'message_deep_link',true,
      'zero_direct_database',true
    ),
    'database_security',jsonb_build_object(
      'public_tables_without_rls',v_tables_without_rls,
      'client_callable_public_security_definer',v_client_secdef,
      'client_readable_non_security_invoker_views',v_non_invoker_views,
      'security_ready',v_tables_without_rls=0 and v_client_secdef=0 and v_non_invoker_views=0
    ),
    'realtime',jsonb_build_object('tables',v_realtime,'expected',6,'ready',v_realtime=6),
    'blogger',jsonb_build_object(
      'runtime_site_ok',true,
      'global_zero_direct_database',v_zero_direct_db,
      'locked_routes',v_drift->'expected_pages',
      'restorable_routes',v_drift->'restorable_pages',
      'validated_restore_objects',v_drift->'validated_restore_objects',
      'drift_count',v_drift->'drift_count',
      'maintenance_oauth_state',v_ops->'blogger'->'connection'
    ),
    'operations',jsonb_build_object(
      'active_cron_jobs',v_ops->'cron'->'active_jobs',
      'failed_24h',v_ops->'cron'->'failed_24h',
      'all_recent_runs_healthy',v_ops->'cron'->'all_recent_runs_healthy',
      'storage_buckets_checked',v_drift->'storage_buckets_checked'
    ),
    'external_infrastructure_blockers',v_blockers,
    'optional_upgrades',v_optional,
    'operational_constraints',jsonb_build_array(
      jsonb_build_object(
        'key','edge_function_capacity',
        'active',true,
        'detail','Project is at 100 Edge Functions; continue reusing retired maintenance slots.'
      )
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000792] function public.tgg_finalize_message_upload(p_message_id uuid, p_file_name text, p_mime_type text, p_file_size bigint, p_storage_path text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_finalize_message_upload(p_message_id uuid, p_file_name text, p_mime_type text, p_file_size bigint, p_storage_path text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'storage'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if p_storage_path is null or p_storage_path !~ ('^' || v_uid::text || '/messages/') then raise exception 'invalid message storage path'; end if;
  if coalesce(p_file_size,0)<=0 or p_file_size>524288000 then raise exception 'invalid file size'; end if;

  if not exists(
    select 1 from public.tgg_messages m
    join public.tgg_conversation_members cm
      on cm.conversation_id=m.conversation_id and cm.user_id=v_uid
    where m.id=p_message_id and m.sender_id=v_uid
  ) then raise exception 'message not accessible'; end if;

  if not exists(
    select 1 from storage.objects o
    where o.bucket_id='creator-media'
      and o.name=p_storage_path
      and (storage.foldername(o.name))[1]=v_uid::text
  ) then raise exception 'uploaded storage object not found'; end if;

  v_id:=public.tgg_register_message_attachment(
    p_message_id,p_file_name,p_mime_type,p_file_size,p_storage_path,
    coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('secure_upload',true)
  );

  perform public.tgg_mark_media_upload_finalized(p_storage_path);
  return v_id;
end
$function$


-- [40000000793] function public.tgg_finalize_studio_upload(p_project_id uuid, p_asset_type text, p_name text, p_storage_path text, p_mime_type text, p_file_size bigint, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_finalize_studio_upload(p_project_id uuid, p_asset_type text, p_name text, p_storage_path text, p_mime_type text, p_file_size bigint, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_id uuid;
  v_meta jsonb:=coalesce(p_metadata,'{}'::jsonb)
    || jsonb_build_object(
      'mime_type',p_mime_type,
      'file_size',p_file_size,
      'secure_upload',true,
      'studio_project_id',p_project_id,
      'source_surface','studio'
    );
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if p_storage_path is null or p_storage_path !~ ('^' || v_uid::text || '/studio/') then
    raise exception 'invalid studio storage path';
  end if;
  if coalesce(p_file_size,0)<=0 or p_file_size>524288000 then raise exception 'invalid file size'; end if;

  if not (
    exists(
      select 1 from public.tgg_studio_projects sp
      where sp.id=p_project_id and sp.user_id=v_uid
    )
    or exists(
      select 1 from public.tgg_studio_project_members m
      where m.project_id=p_project_id
        and m.user_id=v_uid
        and m.left_at is null
        and (m.can_edit or m.can_record)
    )
  ) then raise exception 'studio project not available'; end if;

  if not exists(
    select 1 from storage.objects o
    where o.bucket_id='creator-media'
      and o.name=p_storage_path
      and (storage.foldername(o.name))[1]=v_uid::text
  ) then raise exception 'uploaded storage object not found'; end if;

  v_id:=public.tgg_register_studio_asset(
    p_project_id,p_asset_type,p_name,p_storage_path,v_meta
  );

  if not exists(
    select 1 from public.tgg_media_vault_assets v
    where v.user_id=v_uid and v.storage_path=p_storage_path
  ) then
    perform public.tgg_register_media_vault_asset(
      null,
      coalesce(nullif(btrim(p_asset_type),''),'audio'),
      coalesce(nullif(btrim(p_name),''),'Studio Asset'),
      p_storage_path,
      p_mime_type,
      p_file_size,
      null,null,null,
      v_meta||jsonb_build_object('studio_asset_id',v_id)
    );
  end if;

  perform public.tgg_mark_media_upload_finalized(p_storage_path);
  return v_id;
end
$function$


-- [40000000794] function public.tgg_finalize_vault_upload(p_title text, p_asset_type text, p_storage_path text, p_mime_type text, p_file_size bigint, p_duration_seconds numeric, p_width integer, p_height integer, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_finalize_vault_upload(p_title text, p_asset_type text, p_storage_path text, p_mime_type text, p_file_size bigint, p_duration_seconds numeric DEFAULT NULL::numeric, p_width integer DEFAULT NULL::integer, p_height integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'storage'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_asset public.tgg_media_vault_assets;
  v_obj_exists boolean;
  v_parts text[];
  v_meta jsonb:=coalesce(p_metadata,'{}'::jsonb);
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if p_title is null or length(trim(p_title))=0 or length(trim(p_title))>200 then raise exception 'invalid title'; end if;
  if p_asset_type not in ('audio','video','image','other') then raise exception 'invalid asset type'; end if;
  if p_file_size is null or p_file_size<1 or p_file_size>524288000 then raise exception 'invalid file size'; end if;
  if p_mime_type is not null and char_length(p_mime_type)>255 then raise exception 'mime type too long'; end if;
  if p_duration_seconds is not null and (p_duration_seconds<0 or p_duration_seconds>86400) then raise exception 'invalid duration'; end if;
  if p_width is not null and (p_width<1 or p_width>16384) then raise exception 'invalid width'; end if;
  if p_height is not null and (p_height<1 or p_height>16384) then raise exception 'invalid height'; end if;
  if jsonb_typeof(v_meta)<>'object' then raise exception 'metadata must be an object'; end if;
  if octet_length(v_meta::text)>16384 then raise exception 'metadata too large'; end if;

  v_parts:=storage.foldername(p_storage_path);
  if array_length(v_parts,1) is null
     or array_length(v_parts,1)<2
     or v_parts[1] is distinct from v_uid::text
     or v_parts[2] is distinct from 'vault'
     or char_length(p_storage_path)>1024
  then
    raise exception 'invalid storage path';
  end if;

  select exists(
    select 1 from storage.objects
    where bucket_id='creator-media'
      and name=p_storage_path
      and owner_id=v_uid::text
  ) into v_obj_exists;

  if not v_obj_exists then raise exception 'uploaded object not found'; end if;

  select * into v_asset
  from public.tgg_register_media_vault_asset(
    null,p_asset_type,trim(p_title),p_storage_path,p_mime_type,p_file_size,
    p_duration_seconds,p_width,p_height,v_meta
  );

  perform public.tgg_mark_media_upload_finalized(p_storage_path);
  return v_asset.id;
end
$function$


-- [40000000795] function public.tgg_finalize_video_upload(p_project_id uuid, p_title text, p_storage_path text, p_mime_type text, p_file_size bigint, p_duration_seconds numeric, p_width integer, p_height integer, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_finalize_video_upload(p_project_id uuid, p_title text, p_storage_path text, p_mime_type text, p_file_size bigint, p_duration_seconds numeric DEFAULT NULL::numeric, p_width integer DEFAULT NULL::integer, p_height integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'storage'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_asset public.tgg_media_vault_assets;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if p_storage_path is null or p_storage_path !~ ('^' || v_uid::text || '/video/') then raise exception 'invalid video storage path'; end if;
  if p_mime_type is null or p_mime_type not like 'video/%' then raise exception 'video mime type required'; end if;
  if coalesce(p_file_size,0)<=0 or p_file_size>524288000 then raise exception 'invalid file size'; end if;
  if not exists(
    select 1 from public.tgg_creative_projects cp
    where cp.id=p_project_id and cp.user_id=v_uid and cp.project_type='video'
  ) then raise exception 'video project not found'; end if;
  if not exists(
    select 1 from storage.objects o
    where o.bucket_id='creator-media'
      and o.name=p_storage_path
      and (storage.foldername(o.name))[1]=v_uid::text
  ) then raise exception 'uploaded storage object not found'; end if;

  v_asset:=public.tgg_register_media_vault_asset(
    p_project_id,'video',p_title,p_storage_path,p_mime_type,p_file_size,
    p_duration_seconds,p_width,p_height,
    coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('secure_upload',true,'draft_media',true)
  );

  perform public.tgg_mark_media_upload_finalized(p_storage_path);
  return v_asset.id;
end
$function$


-- [40000000796] function public.tgg_following_feed(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_following_feed(p_limit integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$ select tgg_private.following_feed($1); $function$


-- [40000000797] function public.tgg_game_award_points(p_session_id uuid, p_user_id uuid, p_points integer)
CREATE OR REPLACE FUNCTION public.tgg_game_award_points(p_session_id uuid, p_user_id uuid, p_points integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_score integer;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_points is null or p_points<0 or p_points>10000 then raise exception 'POINTS_INVALID'; end if;
  if not exists(select 1 from public.tgg_game_sessions s where s.id=p_session_id and s.host_user_id=v_uid and s.status='active') then
    raise exception 'HOST_ACTIVE_SESSION_REQUIRED';
  end if;
  update public.tgg_game_scores
  set score=score+p_points,updated_at=now()
  where session_id=p_session_id and user_id=p_user_id
  returning score into v_score;
  if v_score is null then raise exception 'PLAYER_NOT_IN_SESSION'; end if;
  return jsonb_build_object('ok',true,'session_id',p_session_id,'user_id',p_user_id,'score',v_score);
end $function$


-- [40000000798] function public.tgg_game_create_draft(p_title text, p_game_type text, p_settings jsonb, p_starts_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.tgg_game_create_draft(p_title text, p_game_type text, p_settings jsonb DEFAULT '{}'::jsonb, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_artist uuid;v_id uuid;v_type text:=lower(btrim(coalesce(p_game_type,'')));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_title,'')))<1 or char_length(btrim(p_title))>160 then raise exception 'TITLE_INVALID'; end if;
  if v_type not in ('music_bingo','trivia','name_that_track','finish_the_lyric','beat_battle','song_battle','karaoke','beat_roulette','freestyle_roulette') then
    raise exception 'GAME_TYPE_INVALID';
  end if;
  select id into v_artist from public.artists where user_id=v_uid limit 1;
  insert into public.tgg_games(created_by,artist_id,game_type,title,status,settings,starts_at)
  values(v_uid,v_artist,v_type,btrim(p_title),'draft',coalesce(p_settings,'{}'::jsonb),p_starts_at)
  returning id into v_id;
  return jsonb_build_object('ok',true,'game_id',v_id,'status','draft');
end $function$


-- [40000000799] function public.tgg_game_delete(p_game_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_game_delete(p_game_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  delete from public.tgg_games
  where id=p_game_id and created_by=v_uid and status='draft'
  returning id into v_id;
  if v_id is null then raise exception 'GAME_NOT_DELETABLE'; end if;
  return jsonb_build_object('ok',true,'game_id',v_id,'deleted',true);
end $function$


-- [40000000800] function public.tgg_game_idea_claim_batch(p_worker text, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_game_idea_claim_batch(p_worker text, p_limit integer DEFAULT 3)
 RETURNS TABLE(idea_id uuid, owner_user_id uuid, project_id uuid, idea_title text, idea_text text, source text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_worker is null or length(trim(p_worker))=0 then
    raise exception 'worker_required';
  end if;
  if p_limit<1 or p_limit>10 then
    raise exception 'invalid_limit';
  end if;

  return query
  with picked as (
    select i.id
    from public.tgg_game_idea_inbox i
    where i.status='new'
      and i.retry_count <= i.max_retries
    order by i.created_at
    for update skip locked
    limit p_limit
  ),
  claimed as (
    update public.tgg_game_idea_inbox i
    set status='planning',
        claimed_at=now(),
        last_heartbeat_at=now(),
        build_summary=coalesce(i.build_summary,'{}'::jsonb) ||
          jsonb_build_object('claimed_by',p_worker,'claimed_at',now()),
        updated_at=now()
    from picked
    where i.id=picked.id
    returning i.*
  )
  select c.id,c.owner_user_id,c.project_id,c.idea_title,c.idea_text,c.source
  from claimed c
  order by c.created_at;
end $function$


-- [40000000801] function public.tgg_game_idea_heartbeat(p_idea_id uuid, p_status text, p_summary jsonb)
CREATE OR REPLACE FUNCTION public.tgg_game_idea_heartbeat(p_idea_id uuid, p_status text DEFAULT NULL::text, p_summary jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_status text;
begin
  if current_user <> 'postgres' then
    raise exception 'internal_worker_only';
  end if;

  if p_status is not null and p_status not in
    ('planning','queued','building','testing','staged','complete','approval_required','blocked','canceled')
  then
    raise exception 'invalid_status';
  end if;

  update public.tgg_game_idea_inbox
  set status=coalesce(p_status,status),
      last_heartbeat_at=now(),
      updated_at=now(),
      build_summary=coalesce(build_summary,'{}'::jsonb) || coalesce(p_summary,'{}'::jsonb),
      completed_at=case when coalesce(p_status,status)='complete' then coalesce(completed_at,now()) else completed_at end
  where id=p_idea_id
  returning status into v_status;

  if not found then raise exception 'idea_not_found'; end if;

  return jsonb_build_object('ok',true,'idea_id',p_idea_id,'status',v_status,'heartbeat_at',now());
end $function$


-- [40000000802] function public.tgg_game_idea_pipeline_state()
CREATE OR REPLACE FUNCTION public.tgg_game_idea_pipeline_state()
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'new',count(*) filter(where status='new'),
    'planning',count(*) filter(where status='planning'),
    'queued',count(*) filter(where status='queued'),
    'building',count(*) filter(where status='building'),
    'testing',count(*) filter(where status='testing'),
    'staged',count(*) filter(where status='staged'),
    'approval_required',count(*) filter(where status='approval_required'),
    'blocked',count(*) filter(where status='blocked'),
    'complete',count(*) filter(where status='complete'),
    'production_auto_publish',false,
    'high_risk_auto_execute',false
  )
  from public.tgg_game_idea_inbox
$function$


-- [40000000803] function public.tgg_game_idea_recover_stale(p_stale_after interval)
CREATE OR REPLACE FUNCTION public.tgg_game_idea_recover_stale(p_stale_after interval DEFAULT '02:00:00'::interval)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_requeued integer := 0;
  v_blocked integer := 0;
begin
  with stale as (
    select id
    from public.tgg_game_idea_inbox
    where status in ('planning','queued','building','testing')
      and coalesce(last_heartbeat_at,claimed_at,updated_at) < now()-p_stale_after
      and retry_count < max_retries
    for update skip locked
  )
  update public.tgg_game_idea_inbox i
  set status='new',
      retry_count=i.retry_count+1,
      claimed_at=null,
      last_heartbeat_at=null,
      last_error='auto_recovered_stale_worker',
      build_summary=coalesce(i.build_summary,'{}'::jsonb) ||
        jsonb_build_object('auto_recovered_at',now(),'reason','stale_worker'),
      updated_at=now()
  from stale
  where i.id=stale.id;

  get diagnostics v_requeued = row_count;

  with exhausted as (
    select id
    from public.tgg_game_idea_inbox
    where status in ('planning','queued','building','testing')
      and coalesce(last_heartbeat_at,claimed_at,updated_at) < now()-p_stale_after
      and retry_count >= max_retries
    for update skip locked
  )
  update public.tgg_game_idea_inbox i
  set status='blocked',
      last_error='auto_recovery_retries_exhausted',
      build_summary=coalesce(i.build_summary,'{}'::jsonb) ||
        jsonb_build_object('auto_blocked_at',now(),'reason','retry_limit_reached'),
      updated_at=now()
  from exhausted
  where i.id=exhausted.id;

  get diagnostics v_blocked = row_count;

  return jsonb_build_object(
    'ok',true,
    'requeued',v_requeued,
    'blocked_after_retry_limit',v_blocked,
    'stale_after',p_stale_after::text
  );
end $function$


-- [40000000804] function public.tgg_game_idea_submit(p_idea text, p_title text, p_source text, p_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_game_idea_submit(p_idea text, p_title text DEFAULT NULL::text, p_source text DEFAULT 'chat'::text, p_project_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_text text := regexp_replace(trim(coalesce(p_idea,'')),'[[:space:]]+',' ','g');
  v_hash text;
  v_row public.tgg_game_idea_inbox%rowtype;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if length(v_text)<3 then raise exception 'idea_required'; end if;
  if length(v_text)>20000 then raise exception 'idea_too_long'; end if;

  v_hash := md5(lower(v_text));

  insert into public.tgg_game_idea_inbox(
    owner_user_id,project_id,idea_title,idea_text,idea_hash,source,status
  )
  values(
    v_uid,p_project_id,nullif(trim(p_title),''),v_text,v_hash,
    coalesce(nullif(trim(p_source),''),'chat'),'new'
  )
  on conflict(owner_user_id,idea_hash) do update
    set duplicate_count=public.tgg_game_idea_inbox.duplicate_count+1,
        last_seen_at=now(),
        updated_at=now()
  returning * into v_row;

  return jsonb_build_object(
    'ok',true,
    'idea_id',v_row.id,
    'status',v_row.status,
    'duplicate_count',v_row.duplicate_count,
    'release_id',v_row.release_id
  );
end $function$


-- [40000000805] function public.tgg_game_session_create(p_game_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_game_session_create(p_game_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();g public.tgg_games;v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into g from public.tgg_games where id=p_game_id and created_by=v_uid;
  if g.id is null then raise exception 'GAME_NOT_FOUND_OR_NOT_OWNED'; end if;
  if g.status not in ('open','live') then raise exception 'GAME_MUST_BE_OPEN'; end if;
  insert into public.tgg_game_sessions(game_id,host_user_id,title,game_type,status,settings)
  values(g.id,v_uid,g.title,g.game_type,'open',g.settings)
  returning id into v_id;
  return jsonb_build_object('ok',true,'session_id',v_id,'status','open');
end $function$


-- [40000000806] function public.tgg_game_session_end(p_session_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_game_session_end(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_winner uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  update public.tgg_game_sessions
  set status='ended',ended_at=now()
  where id=p_session_id and host_user_id=v_uid and status in ('open','active')
  returning id into v_id;
  if v_id is null then raise exception 'SESSION_NOT_ENDABLE'; end if;

  select user_id into v_winner
  from public.tgg_game_scores
  where session_id=p_session_id
  order by score desc,updated_at asc
  limit 1;

  if v_winner is not null then
    update public.tgg_game_scores
    set wins=wins+1,updated_at=now()
    where session_id=p_session_id and user_id=v_winner;
  end if;

  return jsonb_build_object('ok',true,'session_id',v_id,'status','ended','winner_user_id',v_winner);
end $function$


-- [40000000807] function public.tgg_game_session_join(p_session_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_game_session_join(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();s public.tgg_game_sessions;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into s from public.tgg_game_sessions where id=p_session_id;
  if s.id is null then raise exception 'SESSION_NOT_FOUND'; end if;
  if s.status not in ('open','active') then raise exception 'SESSION_CLOSED'; end if;
  insert into public.tgg_game_scores(session_id,user_id,score,wins)
  values(s.id,v_uid,0,0)
  on conflict(session_id,user_id) do nothing;
  if s.game_id is not null then
    insert into public.tgg_game_players(game_id,user_id,score,state)
    values(s.game_id,v_uid,0,jsonb_build_object('session_id',s.id))
    on conflict(game_id,user_id) do update set state=public.tgg_game_players.state||jsonb_build_object('session_id',s.id);
  end if;
  return jsonb_build_object('ok',true,'session_id',s.id,'joined',true);
end $function$


-- [40000000808] function public.tgg_game_session_start(p_session_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_game_session_start(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  update public.tgg_game_sessions
  set status='active',started_at=coalesce(started_at,now())
  where id=p_session_id and host_user_id=v_uid and status='open'
  returning id into v_id;
  if v_id is null then raise exception 'SESSION_NOT_STARTABLE'; end if;
  return jsonb_build_object('ok',true,'session_id',v_id,'status','active');
end $function$


-- [40000000809] function public.tgg_game_set_status(p_game_id uuid, p_status text)
CREATE OR REPLACE FUNCTION public.tgg_game_set_status(p_game_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_status text := lower(btrim(coalesce(p_status,'')));
  v_current text;
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if v_status not in ('draft','open','live','ended') then
    raise exception 'STATUS_INVALID';
  end if;

  select status into v_current
  from public.tgg_games
  where id=p_game_id and created_by=v_uid
  for update;

  if v_current is null then
    raise exception 'GAME_NOT_FOUND_OR_NOT_OWNED';
  end if;

  if v_current = v_status then
    return jsonb_build_object('ok',true,'game_id',p_game_id,'status',v_status,'unchanged',true);
  end if;

  if not (
    (v_current='draft' and v_status='open') or
    (v_current='open' and v_status='live') or
    (v_current='live' and v_status='ended')
  ) then
    raise exception 'INVALID_STATUS_TRANSITION' using detail=concat('Cannot transition game from ',v_current,' to ',v_status);
  end if;

  update public.tgg_games
  set status=v_status
  where id=p_game_id and created_by=v_uid
  returning id into v_id;

  if v_id is null then
    raise exception 'GAME_NOT_FOUND_OR_NOT_OWNED';
  end if;

  return jsonb_build_object('ok',true,'game_id',v_id,'status',v_status);
end
$function$


-- [40000000810] function public.tgg_game_update(p_game_id uuid, p_title text, p_settings jsonb, p_starts_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.tgg_game_update(p_game_id uuid, p_title text, p_settings jsonb, p_starts_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  update public.tgg_games
  set title=left(btrim(coalesce(p_title,'')),160),
      settings=coalesce(p_settings,'{}'::jsonb),
      starts_at=p_starts_at
  where id=p_game_id and created_by=v_uid and status in ('draft','open')
  returning id into v_id;
  if v_id is null then raise exception 'GAME_NOT_EDITABLE'; end if;
  return jsonb_build_object('ok',true,'game_id',v_id);
end $function$


-- [40000000811] function public.tgg_game_writer_claim_batch(p_worker text, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_game_writer_claim_batch(p_worker text, p_limit integer DEFAULT 3)
 RETURNS SETOF public.tgg_game_writer_packets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if coalesce(trim(p_worker),'')='' then raise exception 'worker required'; end if;

  return query
  with candidates as (
    select id
    from public.tgg_game_writer_packets
    where status in ('queued','revision')
    order by created_at
    for update skip locked
    limit greatest(1,least(coalesce(p_limit,3),10))
  ),
  claimed as (
    update public.tgg_game_writer_packets p
    set status='writing',worker=p_worker,updated_at=now()
    from candidates c
    where p.id=c.id
    returning p.*
  )
  select * from claimed;
end $function$


-- [40000000812] function public.tgg_game_writer_complete(p_packet_id uuid, p_writing jsonb, p_acceptance jsonb)
CREATE OR REPLACE FUNCTION public.tgg_game_writer_complete(p_packet_id uuid, p_writing jsonb, p_acceptance jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.tgg_game_writer_packets%rowtype;
  v_missing text[];
begin
  if jsonb_typeof(p_writing)<>'object' then
    raise exception 'writing must be a json object';
  end if;

  select * into v_row
  from public.tgg_game_writer_packets
  where id=p_packet_id
  for update;

  if not found then raise exception 'writer packet not found'; end if;

  select array_agg(k)
  into v_missing
  from unnest(array[
    'vision','genre_and_player_fantasy','core_gameplay_loop','world_and_setting',
    'characters_and_roles','story_arc','missions_and_quests','progression',
    'economy_and_rewards','multiplayer_and_social','levels_and_locations',
    'ui_ux_copy','audio_music_direction','art_direction','systems_and_rules',
    'failure_states','accessibility','safety_and_moderation','launch_slice'
  ]) k
  where not (p_writing ? k);

  if coalesce(array_length(v_missing,1),0)>0 then
    update public.tgg_game_writer_packets
    set status='revision',
        last_error='missing required sections: '||array_to_string(v_missing,', '),
        updated_at=now()
    where id=p_packet_id;

    return jsonb_build_object(
      'ok',false,'status','revision','missing_sections',to_jsonb(v_missing)
    );
  end if;

  update public.tgg_game_writer_packets
  set status='ready',
      writing=p_writing,
      acceptance=case when jsonb_array_length(coalesce(p_acceptance,'[]'::jsonb))>0
                      then p_acceptance else acceptance end,
      last_error=null,
      updated_at=now()
  where id=p_packet_id;

  return jsonb_build_object('ok',true,'status','ready','packet_id',p_packet_id);
end $function$


-- [40000000813] function public.tgg_game_writer_enqueue(p_idea_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_game_writer_enqueue(p_idea_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_idea public.tgg_game_idea_inbox%rowtype;
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select * into v_idea
  from public.tgg_game_idea_inbox
  where id=p_idea_id and owner_user_id=v_uid;

  if not found then raise exception 'game idea not found'; end if;

  insert into public.tgg_game_writer_packets(
    idea_id,owner_user_id,project_id,status,version,game_title,writing,acceptance
  )
  values(
    v_idea.id,v_uid,v_idea.project_id,'queued',1,
    coalesce(v_idea.idea_title,'Untitled Game'),
    jsonb_build_object(
      'source_idea',v_idea.idea_text,
      'required_sections',jsonb_build_array(
        'vision','genre_and_player_fantasy','core_gameplay_loop','world_and_setting',
        'characters_and_roles','story_arc','missions_and_quests','progression',
        'economy_and_rewards','multiplayer_and_social','levels_and_locations',
        'ui_ux_copy','audio_music_direction','art_direction','systems_and_rules',
        'failure_states','accessibility','safety_and_moderation','launch_slice'
      ),
      'writer_instruction','Write an original buildable game package grounded in the submitted idea. Reuse existing TGG systems where possible. Do not invent production credentials, rights, user consent, or completed evidence.'
    ),
    jsonb_build_array(
      'all required sections are present',
      'gameplay loop is implementable',
      'story and missions map to buildable systems',
      'existing TGG primitives are reused before new systems are proposed',
      'production/high-risk/canonical work stays gated',
      'no fabricated QA or deployment claims'
    )
  )
  on conflict(idea_id,version) do update
  set updated_at=now()
  returning id into v_id;

  return jsonb_build_object('ok',true,'packet_id',v_id,'status','queued');
end $function$


-- [40000000814] function public.tgg_game_writer_mark_complete(p_packet_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_game_writer_mark_complete(p_packet_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.tgg_game_writer_packets
  set status='complete',completed_at=now(),updated_at=now()
  where id=p_packet_id and status='ready';

  if not found then
    return jsonb_build_object('ok',false,'reason','packet_not_ready');
  end if;

  return jsonb_build_object('ok',true,'status','complete','packet_id',p_packet_id);
end $function$


-- [40000000815] function public.tgg_game_writer_state()
CREATE OR REPLACE FUNCTION public.tgg_game_writer_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
select jsonb_build_object(
  'total',count(*),
  'queued',count(*) filter(where status='queued'),
  'writing',count(*) filter(where status='writing'),
  'ready',count(*) filter(where status='ready'),
  'revision',count(*) filter(where status='revision'),
  'complete',count(*) filter(where status='complete'),
  'blocked',count(*) filter(where status='blocked')
)
from public.tgg_game_writer_packets
$function$


-- [40000000816] function public.tgg_generate_event_booking_actions()
CREATE OR REPLACE FUNCTION public.tgg_generate_event_booking_actions()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_count integer:=0; v_added integer:=0;
begin
 if v_uid is null then raise exception 'authentication required'; end if;
 insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,source_id,action_type,title,rationale,priority,status,due_at,metadata)
 select v_uid,e.artist_id,'event',e.id,'promote_event','Promote upcoming event: '||e.title,
 'This event starts soon. Push it through TGG campaigns, supporters, Stories, Circles and your smart link.',
 case when e.starts_at < now()+interval '3 days' then 95 else 75 end,'open',greatest(now(),e.starts_at-interval '1 day'),jsonb_build_object('starts_at',e.starts_at,'event_type',e.event_type,'city',e.city)
 from public.tgg_events e where e.created_by=v_uid and e.status not in ('cancelled','canceled','completed') and e.starts_at between now() and now()+interval '14 days'
 and not exists(select 1 from public.tgg_creator_action_queue q where q.owner_user_id=v_uid and q.source_type='event' and q.source_id=e.id and q.action_type='promote_event' and q.status='open');
 get diagnostics v_added=row_count; v_count:=v_count+v_added;
 insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,source_id,action_type,title,rationale,priority,status,due_at,metadata)
 select v_uid,a.id,'booking',b.id,'respond_booking','Respond to booking request: '||coalesce(b.service,'service'),
 'A booking request is waiting for a response. Fast replies can improve conversion and creator professionalism.',90,'open',now()+interval '1 day',jsonb_build_object('budget_cents',b.budget_cents,'requested_at',b.requested_at,'scheduled_for',b.scheduled_for)
 from public.tgg_booking_requests b left join public.artists a on a.user_id=v_uid
 where b.provider_user_id=v_uid and b.status in ('pending','requested','new')
 and not exists(select 1 from public.tgg_creator_action_queue q where q.owner_user_id=v_uid and q.source_type='booking' and q.source_id=b.id and q.action_type='respond_booking' and q.status='open');
 get diagnostics v_added=row_count; v_count:=v_count+v_added;
 insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,source_id,action_type,title,rationale,priority,status,due_at,metadata)
 select v_uid,l.artist_id,'live',l.id,'prepare_live','Prepare LIVE: '||l.title,
 'Your scheduled TGG Live session is approaching. Confirm room setup, access level, pinned release/merch and promotion.',85,'open',greatest(now(),l.scheduled_at-interval '12 hours'),jsonb_build_object('scheduled_at',l.scheduled_at,'live_type',l.live_type,'access_level',l.access_level)
 from public.tgg_live_events l where l.host_user_id=v_uid and l.status not in ('ended','cancelled','canceled') and l.scheduled_at between now() and now()+interval '7 days'
 and not exists(select 1 from public.tgg_creator_action_queue q where q.owner_user_id=v_uid and q.source_type='live' and q.source_id=l.id and q.action_type='prepare_live' and q.status='open');
 get diagnostics v_added=row_count; v_count:=v_count+v_added; return v_count;
end $function$


-- [40000000817] function public.tgg_generate_fan_followup_actions(p_artist_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_generate_fan_followup_actions(p_artist_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_count integer := 0;
begin
  if v_user is null then
    raise exception 'Authentication required';
  end if;

  insert into public.tgg_creator_action_queue (
    owner_user_id, artist_id, source_type, source_id, action_type,
    title, rationale, priority, status, due_at, metadata, created_at, updated_at
  )
  select
    s.creator_user_id,
    s.artist_id,
    'fan_intelligence',
    s.fan_user_id,
    case when s.fan_state in ('slipping','dormant') then 'fan_reengagement' else 'fan_nurture' end,
    case s.fan_state
      when 'supporter' then 'Reward a supporter relationship'
      when 'superfan' then 'Activate a superfan'
      when 'slipping' then 'Re-engage a slipping fan'
      when 'dormant' then 'Win back a dormant fan'
      when 'new' then 'Welcome a new fan'
      else 'Nurture an active fan'
    end,
    s.recommended_action,
    case s.fan_state
      when 'slipping' then 4
      when 'dormant' then 3
      when 'superfan' then 4
      when 'supporter' then 5
      when 'new' then 3
      else 2
    end,
    'open',
    case when s.fan_state in ('slipping','dormant') then now() + interval '3 days' else null end,
    jsonb_build_object(
      'fan_user_id', s.fan_user_id,
      'fan_state', s.fan_state,
      'engagement_score', s.engagement_score,
      'recency_score', s.recency_score,
      'loyalty_score', s.loyalty_score
    ),
    now(),
    now()
  from public.tgg_fan_intelligence_snapshots s
  where s.creator_user_id = v_user
    and (p_artist_id is null or s.artist_id = p_artist_id)
    and s.fan_state in ('new','superfan','supporter','slipping','dormant')
    and not exists (
      select 1
      from public.tgg_creator_action_queue q
      where q.owner_user_id = s.creator_user_id
        and q.artist_id = s.artist_id
        and q.source_type = 'fan_intelligence'
        and q.source_id = s.fan_user_id
        and q.status = 'open'
    );

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$


-- [40000000818] function public.tgg_generate_release_campaign_actions()
CREATE OR REPLACE FUNCTION public.tgg_generate_release_campaign_actions()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_count integer:=0;
  v_added integer:=0;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  update public.tgg_creator_action_queue q
  set status='completed',updated_at=now()
  from public.mixtapes m
  where q.owner_user_id=v_uid
    and q.source_type='release'
    and q.action_type='finish_release'
    and q.status='open'
    and q.source_id=m.id
    and m.user_id=v_uid
    and m.status='published';

  update public.tgg_creator_action_queue q
  set status='completed',updated_at=now()
  from public.tgg_campaigns c
  where q.owner_user_id=v_uid
    and q.source_type='campaign'
    and q.action_type='optimize_campaign'
    and q.status='open'
    and q.source_id=c.id
    and c.owner_user_id=v_uid
    and c.status in ('complete','completed','cancelled','canceled');

  insert into public.tgg_creator_action_queue(
    owner_user_id,artist_id,source_type,source_id,action_type,title,rationale,
    priority,status,due_at,metadata
  )
  select
    v_uid,r.artist_id,'release',r.release_id,'finish_release',
    'Finish release prep: '||r.title,
    'Release readiness is '||r.readiness_percent||'%. Complete the remaining checklist before launch.',
    case when r.release_date is not null and r.release_date < now()+interval '7 days' then 98 else 82 end,
    'open',
    coalesce(r.release_date,now()+interval '7 days')-interval '1 day',
    jsonb_build_object('readiness_percent',r.readiness_percent,'smart_link_clicks',r.smart_link_clicks)
  from public.tgg_creator_release_health r
  join public.mixtapes m on m.id=r.release_id
  where r.creator_user_id=v_uid
    and m.user_id=v_uid
    and m.status<>'published'
    and r.readiness_percent<100
    and (r.release_date is null or r.release_date>=now()-interval '7 days')
    and not exists(
      select 1 from public.tgg_creator_action_queue q
      where q.owner_user_id=v_uid
        and q.source_type='release'
        and q.source_id=r.release_id
        and q.action_type='finish_release'
        and q.status='open'
    );
  get diagnostics v_added=row_count;
  v_count:=v_count+v_added;

  insert into public.tgg_creator_action_queue(
    owner_user_id,artist_id,source_type,source_id,action_type,title,rationale,
    priority,status,due_at,metadata
  )
  select
    v_uid,c.artist_id,'campaign',c.campaign_id,'optimize_campaign',
    'Optimize campaign: '||c.title,
    case when c.objective_percent is not null and c.objective_percent<50
      then 'Campaign progress is behind target.'
      else 'Campaign still has unfinished tasks or needs a stronger push.' end,
    case when c.ends_at is not null and c.ends_at<now()+interval '5 days' then 92 else 72 end,
    'open',
    coalesce(c.ends_at,now()+interval '5 days')-interval '1 day',
    jsonb_build_object('objective_percent',c.objective_percent,'tasks_done',c.tasks_done,'task_count',c.task_count)
  from public.tgg_creator_campaign_health c
  where c.creator_user_id=v_uid
    and c.status not in ('complete','completed','cancelled','canceled')
    and (c.tasks_done<c.task_count or coalesce(c.objective_percent,0)<100)
    and not exists(
      select 1 from public.tgg_creator_action_queue q
      where q.owner_user_id=v_uid
        and q.source_type='campaign'
        and q.source_id=c.campaign_id
        and q.action_type='optimize_campaign'
        and q.status='open'
    );
  get diagnostics v_added=row_count;
  v_count:=v_count+v_added;

  return v_count;
end
$function$


-- [40000000819] function public.tgg_generate_supporter_retention_actions()
CREATE OR REPLACE FUNCTION public.tgg_generate_supporter_retention_actions()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_count integer:=0;
begin
 if v_uid is null then raise exception 'authentication required'; end if;
 insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,source_id,action_type,title,rationale,priority,status,due_at,metadata)
 select v_uid,s.artist_id,'supporter',s.membership_id,
   case when s.supporter_state='at_risk' then 'retain_supporter' when s.supporter_state='churned' then 'win_back_supporter' when s.supporter_state='new' then 'welcome_supporter' else 'reward_supporter' end,
   case when s.supporter_state='at_risk' then 'Supporter may be at risk' when s.supporter_state='churned' then 'Reconnect with a former supporter' when s.supporter_state='new' then 'Welcome a new supporter' else 'Reward a loyal supporter' end,
   s.recommended_action,
   case when s.supporter_state='at_risk' then 95 when s.supporter_state='churned' then 80 when s.supporter_state='new' then 70 else 60 end,
   'open',case when s.supporter_state='at_risk' then now()+interval '2 days' else now()+interval '7 days' end,
   jsonb_build_object('fan_user_id',s.fan_user_id,'supporter_state',s.supporter_state,'health_score',s.health_score,'lifetime_support_cents',s.lifetime_support_cents)
 from public.tgg_supporter_health_snapshots s
 where s.creator_user_id=v_uid and s.supporter_state in ('at_risk','churned','new','loyal')
 and not exists (select 1 from public.tgg_creator_action_queue q where q.owner_user_id=v_uid and q.source_type='supporter' and q.source_id=s.membership_id and q.status='open' and q.action_type in ('retain_supporter','win_back_supporter','welcome_supporter','reward_supporter'));
 get diagnostics v_count=row_count; return v_count;
end $function$


-- [40000000820] function public.tgg_get_account_workspace_bundle(p_notification_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_get_account_workspace_bundle(p_notification_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'creator_workspace', (select to_jsonb(c) from public.creator_workspace_v1 c limit 1),
    'fan_workspace', (select to_jsonb(f) from public.fan_workspace_v1 f limit 1),
    'notification_summary', (select to_jsonb(s) from public.user_notification_summary s where s.user_id = (select auth.uid()) limit 1),
    'notification_preferences', (select to_jsonb(p) from public.notification_preferences_v1 p limit 1),
    'notifications', coalesce((
      select jsonb_agg(to_jsonb(n) order by n.created_at desc)
      from (
        select id, notification_type, entity_type, entity_id, title, body, read_at, created_at
        from public.notifications
        where recipient_id = (select auth.uid())
        order by created_at desc
        limit greatest(1, least(coalesce(p_notification_limit,12),50))
      ) n
    ), '[]'::jsonb)
  )
  where (select auth.uid()) is not null;
$function$


-- [40000000821] function public.tgg_get_blogger_bridge_health()
CREATE OR REPLACE FUNCTION public.tgg_get_blogger_bridge_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_conn public.v98_blogger_connections;
  v_deploy_total bigint:=0;
  v_verified bigint:=0;
  v_failed bigint:=0;
  v_latest timestamptz;
  v_reauth boolean:=false;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select * into v_conn
  from public.v98_blogger_connections
  where user_id=v_uid
  order by updated_at desc
  limit 1;

  v_reauth:=coalesce(
    v_conn.last_error ilike '%invalid_grant%'
    or v_conn.status<>'connected'
    or v_conn.revoked_at is not null,
    false
  );

  if v_conn.id is not null then
    select count(*),
           count(*) filter (where status='verified'),
           count(*) filter (where status in ('failed','rolled_back')),
           max(updated_at)
      into v_deploy_total,v_verified,v_failed,v_latest
    from public.v98_blogger_deployments
    where user_id=v_uid and connection_id=v_conn.id;
  end if;

  return jsonb_build_object(
    'ok',coalesce(v_conn.id is not null and not v_reauth,false),
    'connected',coalesce(v_conn.id is not null and not v_reauth,false),
    'reauthorization_required',v_reauth,
    'reauthorization_reason',case
      when v_reauth and coalesce(v_conn.last_error,'') ilike '%invalid_grant%' then 'google_oauth_invalid_grant'
      when v_reauth then coalesce(v_conn.last_error,'blogger_write_authorization_required')
      else null
    end,
    'mode','blogger_api_direct',
    'write_token_path','final',
    'write_token_ready',coalesce(v_conn.id is not null and not v_reauth,false),
    'normal_page_post_deploy','v98-blogger-connector',
    'normal_deploy_ready',coalesce(v_conn.id is not null and not v_reauth,false),
    'backup_restore_ready',coalesce(v_conn.id is not null and not v_reauth,false),
    'api_verification_ready',coalesce(v_conn.id is not null and not v_reauth,false),
    'public_render_verification','best_effort',
    'theme_xml_transport','tgg-theme-autodeploy',
    'theme_xml_mode','legacy_optional',
    'browser_automation_required_for_normal_deploy',false,
    'blog',case when v_conn.id is null then null else jsonb_build_object(
      'blog_url',v_conn.blog_url,
      'blog_name',v_conn.blog_name,
      'status',v_conn.status,
      'connected_at',v_conn.connected_at,
      'updated_at',v_conn.updated_at,
      'last_error',v_conn.last_error
    ) end,
    'deployments',jsonb_build_object(
      'total',v_deploy_total,
      'verified',v_verified,
      'failed_or_rolled_back',v_failed,
      'latest_at',v_latest
    ),
    'version','BLOGGER-ONE-FINAL-1.2'
  );
end
$function$


-- [40000000822] function public.tgg_get_creator_app_shell_readiness()
CREATE OR REPLACE FUNCTION public.tgg_get_creator_app_shell_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); aid uuid; missing text[]:=array[]::text[]; ready boolean;
begin
 if uid is null then raise exception 'authentication required'; end if;
 select id into aid from artists where user_id=uid order by created_at limit 1;
 if aid is null then missing:=array_append(missing,'artist_profile'); end if;
 if to_regprocedure('public.tgg_get_creator_ui_full_contract()') is null then missing:=array_append(missing,'ui_full_contract'); end if;
 if to_regprocedure('public.tgg_get_creator_ui_runtime_contract()') is null then missing:=array_append(missing,'runtime_contract'); end if;
 if to_regprocedure('public.tgg_get_creator_navigation_state()') is null then missing:=array_append(missing,'navigation_state'); end if;
 ready:=coalesce(array_length(missing,1),0)=0;
 return jsonb_build_object('version','3690','ready',ready,'user_id',uid,'artist_id',aid,'missing',to_jsonb(missing),'contracts',jsonb_build_object('bootstrap','tgg_get_creator_ui_bootstrap','full_ui','tgg_get_creator_ui_full_contract','runtime','tgg_get_creator_ui_runtime_contract','navigation','tgg_get_creator_navigation_state'),'shell',jsonb_build_object('desktop_sidebar',true,'mobile_bottom_nav',true,'notification_center',true,'workspace_badges',true,'persistent_player_slot',true,'global_search_slot',true,'account_menu',true));
end $function$


-- [40000000823] function public.tgg_get_creator_app_startup_bundle()
CREATE OR REPLACE FUNCTION public.tgg_get_creator_app_startup_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_nav jsonb;
  v_manifest jsonb;
  v_features jsonb;
  v_readiness jsonb;
  v_api jsonb;
  v_routes jsonb;
  v_ui jsonb;
  v_runtime_integrity jsonb;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  v_nav:=public.tgg_get_creator_navigation_state();
  v_manifest:=public.tgg_get_creator_workspace_manifest();
  v_features:=public.tgg_feature_runtime_health();
  v_readiness:=public.tgg_get_creator_app_shell_readiness();
  v_api:=public.tgg_get_frontend_api_contract();
  v_runtime_integrity:=public.tgg_v5000_runtime_integrity();

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'key',x->>'key',
        'label',x->>'label',
        'rpc',x->>'rpc'
      )
      order by ord
    ),
    '[]'::jsonb
  )
  into v_routes
  from jsonb_array_elements(coalesce(v_manifest->'workspaces','[]'::jsonb))
       with ordinality as t(x,ord);

  v_routes:=v_routes || jsonb_build_array(
    jsonb_build_object(
      'key','expansion',
      'label','Expansion Control',
      'rpc','tgg_creator_expansion_control_center'
    )
  );

  v_ui:=jsonb_build_object(
    'contract',jsonb_build_object(
      'version','ONE-FINAL-UI-1.2-LIGHT',
      'routes',v_routes,
      'features',jsonb_build_object(
        'modules',coalesce(v_features->'modules','{}'::jsonb)
      ),
      'launch',jsonb_build_object(
        'status','ready_with_optional_upgrades',
        'payments_mode','payment_link',
        'commerce_ready',true,
        'actual_blockers',0,
        'optional_activations',3
      )
    ),
    'bootstrap',jsonb_build_object(
      'contract',jsonb_build_object('routes',v_routes),
      'shell',coalesce(v_readiness->'shell','{}'::jsonb)
    )
  );

  return jsonb_build_object(
    'version','ONE-FINAL-3.2-LIGHT',
    'release_channel','production',
    'architecture',jsonb_build_object(
      'name','ONE-FINAL',
      'creator_surfaces',30,
      'core_groups',7,
      'canonical_workspace','os',
      'expansion_workspace','expansion',
      'actual_blockers',0,
      'optional_activations',3,
      'startup_contract','lightweight_one_final'
    ),
    'readiness',v_readiness,
    'ui',v_ui,
    'navigation',v_nav,
    'workspace_manifest',v_manifest,
    'api',v_api,
    'runtime_integrity',v_runtime_integrity,
    'generated_at',now()
  );
end;
$function$


-- [40000000824] function public.tgg_get_creator_bootstrap_bundle()
CREATE OR REPLACE FUNCTION public.tgg_get_creator_bootstrap_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); shell jsonb; health jsonb;
begin
 if uid is null then raise exception 'authentication required'; end if;
 shell:=public.tgg_get_creator_shell_bundle();
 health:=public.tgg_get_frontend_integration_health();
 return jsonb_build_object(
  'status','ready',
  'health',health,
  'shell',shell,
  'account',public.tgg_get_account_workspace_bundle(20),
  'loaded_at',now()
 );
end $function$


-- [40000000825] function public.tgg_get_creator_career_workspace_bundle(p_artist_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_get_creator_career_workspace_bundle(p_artist_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); aid uuid; result jsonb;
begin
 if uid is null then raise exception 'authentication required'; end if;
 select id into aid from public.artists where user_id=uid and (p_artist_id is null or id=p_artist_id) order by created_at limit 1;
 if aid is null then raise exception 'artist not found'; end if;
 select jsonb_build_object(
 'resume',coalesce((select to_jsonb(r) from public.tgg_creator_resume r where r.owner_user_id=uid and r.artist_id=aid),'{}'::jsonb),
 'epk',coalesce((select to_jsonb(e) from public.tgg_epk_settings e where e.owner_user_id=uid and e.artist_id=aid),'{}'::jsonb),
 'press',coalesce((select jsonb_agg(to_jsonb(p) order by p.published_at desc nulls last) from public.tgg_press_items p where p.owner_user_id=uid and p.artist_id=aid),'[]'::jsonb),
 'academy',coalesce((select jsonb_agg(to_jsonb(a) order by a.updated_at desc) from public.tgg_academy_progress a where a.user_id=uid),'[]'::jsonb),
 'mentorship',coalesce((select jsonb_agg(to_jsonb(m) order by m.requested_at desc) from (select * from public.tgg_mentorship_requests where requester_user_id=uid or mentor_user_id=uid order by requested_at desc limit 50) m),'[]'::jsonb),
 'feedback',coalesce((select jsonb_agg(to_jsonb(f) order by f.created_at desc) from (select * from public.tgg_feedback_requests where owner_user_id=uid and artist_id=aid order by created_at desc limit 50) f),'[]'::jsonb)
 ) into result; return result;
end $function$


-- [40000000826] function public.tgg_get_creator_communications_bundle()
CREATE OR REPLACE FUNCTION public.tgg_get_creator_communications_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid();
begin
 if uid is null then raise exception 'authentication required'; end if;
 return jsonb_build_object(
  'messenger',coalesce((select jsonb_agg(to_jsonb(x) order by x.last_message_at desc nulls last) from (select * from public.creator_messenger_inbox_v1 order by last_message_at desc nulls last limit 50) x),'[]'::jsonb),
  'collaborations',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc nulls last) from (select * from public.creator_collaboration_inbox_v1 order by updated_at desc nulls last limit 50) x),'[]'::jsonb),
  'unread_messages',coalesce((select sum(unread_messages) from public.creator_messenger_inbox_v1),0),
  'pending_collaborations',coalesce((select count(*) from public.creator_collaboration_inbox_v1 where direction='incoming' and status in ('pending','requested','open')),0)
 );
end $function$


-- [40000000827] function public.tgg_get_creator_daily_brief(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_get_creator_daily_brief(p_limit integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'generated_at',now(),
    'open_actions',count(*) filter(where q.status='open'),
    'urgent_actions',count(*) filter(where q.status='open' and q.priority>=80),
    'next_due_at',min(q.due_at) filter(where q.status='open'),
    'growth_brain',public.tgg_growth_brain_latest(),
    'actions',coalesce((
      select jsonb_agg(x.obj order by x.priority desc,x.created_at asc)
      from (
        select jsonb_build_object(
          'id',a.id,'title',a.title,'rationale',a.rationale,
          'action_type',a.action_type,'priority',a.priority,
          'due_at',a.due_at,'metadata',a.metadata
        ) obj,a.priority,a.created_at
        from public.tgg_creator_action_queue a
        where a.owner_user_id=(select auth.uid()) and a.status='open'
        order by a.priority desc,a.created_at asc
        limit greatest(1,least(coalesce(p_limit,8),25))
      ) x
    ),'[]'::jsonb)
  )
  from public.tgg_creator_action_queue q
  where q.owner_user_id=(select auth.uid());
$function$


-- [40000000828] function public.tgg_get_creator_dashboard_bundle(p_artist_id uuid, p_action_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_get_creator_dashboard_bundle(p_artist_id uuid DEFAULT NULL::uuid, p_action_limit integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist uuid;
  v_limit integer:=greatest(1,least(coalesce(p_action_limit,8),25));
  v_result jsonb;
  v_payment jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select a.id into v_artist
  from public.artists a
  where a.user_id=v_uid
    and (p_artist_id is null or a.id=p_artist_id)
  order by a.created_at asc
  limit 1;

  if v_artist is null then raise exception 'artist profile not found'; end if;

  v_payment:=private.tgg_get_own_artist_payment_status(v_artist);

  select jsonb_build_object(
    'artist',(
      select jsonb_build_object(
        'id',a.id,
        'stage_name',a.stage_name,
        'avatar_url',a.avatar_url,
        'bio',a.bio,
        'stripe_onboarding_complete',coalesce((v_payment->>'stripe_onboarding_complete')::boolean,false),
        'payouts_enabled',coalesce((v_payment->>'payouts_enabled')::boolean,false)
      )
      from public.artists a
      where a.id=v_artist
        and a.user_id=v_uid
    ),
    'command_center',coalesce((
      select to_jsonb(c)-'creator_user_id'
      from public.tgg_creator_command_center c
      where c.creator_user_id=v_uid and c.artist_id=v_artist
      limit 1
    ),'{}'::jsonb),
    'monetization',coalesce((
      select to_jsonb(m)-'creator_user_id'
      from public.tgg_creator_monetization_summary m
      where m.creator_user_id=v_uid and m.artist_id=v_artist
      limit 1
    ),'{}'::jsonb),
    'fan_intelligence',coalesce((
      select to_jsonb(f)-'creator_user_id'
      from public.tgg_creator_fan_intelligence_summary f
      where f.creator_user_id=v_uid and f.artist_id=v_artist
      limit 1
    ),'{}'::jsonb),
    'supporters',coalesce((
      select to_jsonb(s)-'creator_user_id'
      from public.tgg_creator_supporter_summary s
      where s.creator_user_id=v_uid and s.artist_id=v_artist
      limit 1
    ),'{}'::jsonb),
    'actions',coalesce((
      select jsonb_agg(to_jsonb(q) order by q.priority desc,q.due_at nulls last,q.created_at desc)
      from (
        select id,source_type,source_id,action_type,title,rationale,priority,status,due_at,metadata,created_at
        from public.tgg_creator_action_queue
        where owner_user_id=v_uid
          and artist_id=v_artist
          and status='open'
        order by priority desc,due_at nulls last,created_at desc
        limit v_limit
      ) q
    ),'[]'::jsonb),
    'releases',coalesce((
      select jsonb_agg(to_jsonb(r) order by r.release_date desc nulls last,r.title)
      from (
        select release_id,title,status,release_date,play_count,download_count,
               checklist_items,checklist_done,readiness_percent,smart_link_clicks
        from public.tgg_creator_release_health
        where creator_user_id=v_uid and artist_id=v_artist
        order by release_date desc nulls last,title
        limit 12
      ) r
    ),'[]'::jsonb),
    'campaigns',coalesce((
      select jsonb_agg(to_jsonb(c) order by c.starts_at desc nulls last,c.title)
      from (
        select campaign_id,title,status,objective,target_value,current_value,
               starts_at,ends_at,task_count,tasks_done,objective_percent
        from public.tgg_creator_campaign_health
        where creator_user_id=v_uid and artist_id=v_artist
        order by starts_at desc nulls last,title
        limit 12
      ) c
    ),'[]'::jsonb),
    'generated_at',now()
  ) into v_result;

  return v_result;
end
$function$


-- [40000000829] function public.tgg_get_creator_fan_crm_bundle(p_artist_id uuid, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_get_creator_fan_crm_bundle(p_artist_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist uuid;
  v_limit integer:=greatest(1,least(coalesce(p_limit,50),200));
  v_refresh integer:=0;
  v_sync integer:=0;
  v_result jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select a.id into v_artist
  from public.artists a
  where a.user_id=v_uid
    and (p_artist_id is null or a.id=p_artist_id)
  order by a.created_at asc
  limit 1;

  if v_artist is null then raise exception 'artist profile not found'; end if;

  v_refresh:=public.tgg_refresh_fan_intelligence(v_artist);
  v_sync:=public.tgg_sync_fan_crm_segments(v_artist);

  select jsonb_build_object(
    'ok',true,
    'version','FAN-CRM-GROWTH-BRIDGE-1.0',
    'artist_id',v_artist,
    'refreshed_records',v_refresh,
    'synced_records',v_sync,
    'summary',coalesce((
      select to_jsonb(s)-'creator_user_id'
      from public.tgg_creator_fan_intelligence_summary s
      where s.creator_user_id=v_uid and s.artist_id=v_artist
      limit 1
    ),'{}'::jsonb),
    'counts',jsonb_build_object(
      'followers',(select count(*) from public.artist_follows f where f.artist_id=v_artist),
      'crm_fans',(select count(*) from public.tgg_fan_crm c where c.creator_user_id=v_uid and c.artist_id=v_artist and c.segment<>'unfollowed'),
      'active_members',(select count(*) from public.tgg_memberships m where m.artist_id=v_artist and m.status='active'),
      'paid_supporters',(select count(distinct s.fan_user_id) from public.tgg_support_transactions s where s.artist_id=v_artist and s.status='paid')
    ),
    'fans',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.engagement_score desc,x.last_seen_at desc nulls last)
      from (
        select
          c.id,
          c.segment,
          c.tags,
          c.private_notes,
          c.last_contacted_at,
          c.updated_at,
          coalesce((select a.stage_name from public.artists a where a.user_id=c.fan_user_id limit 1),'TGG Fan') as fan_name,
          coalesce(i.engagement_score,0) as engagement_score,
          coalesce(i.recency_score,0) as recency_score,
          coalesce(i.loyalty_score,0) as loyalty_score,
          coalesce(i.fan_state,c.segment) as fan_state,
          i.recommended_action,
          i.last_seen_at
        from public.tgg_fan_crm c
        left join public.tgg_fan_intelligence_snapshots i
          on i.creator_user_id=c.creator_user_id
         and i.artist_id=c.artist_id
         and i.fan_user_id=c.fan_user_id
        where c.creator_user_id=v_uid and c.artist_id=v_artist
        order by coalesce(i.engagement_score,0) desc,i.last_seen_at desc nulls last,c.updated_at desc
        limit v_limit
      ) x
    ),'[]'::jsonb),
    'generated_at',now()
  ) into v_result;

  return v_result;
end
$function$


-- [40000000830] function public.tgg_get_creator_growth_insights()
CREATE OR REPLACE FUNCTION public.tgg_get_creator_growth_insights()
 RETURNS TABLE(insight_code text, priority integer, insight_title text, detail text, action_type text, action_ref uuid)
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
with uid as (select auth.uid() as id), open_goals as (select * from public.tgg_creator_goals where owner_user_id=(select id from uid) and status not in ('completed','cancelled')), active_campaigns as (select * from public.tgg_campaigns where owner_user_id=(select id from uid) and status in ('active','scheduled','draft')), incomplete_releases as (select release_id,count(*) filter(where status<>'done') remaining,count(*) total from public.tgg_release_checklist_items where owner_user_id=(select id from uid) group by release_id), links as (select l.id,l.title,count(e.id) filter(where e.occurred_at>=now()-interval '7 days') clicks7 from public.tgg_smart_links l left join public.tgg_smart_link_events e on e.link_id=l.id where l.owner_user_id=(select id from uid) and l.is_active=true group by l.id,l.title), apps as (select o.id,o.title,count(a.id) applications from public.tgg_opportunities o left join public.tgg_opportunity_applications a on a.opportunity_id=o.id where o.created_by=(select id from uid) and o.status='open' group by o.id,o.title), insights as (
select 'goal_deadline'::text code,100::integer prio,'Goal deadline approaching'::text ttl,(g.title||' is due soon.')::text det,'goal'::text typ,g.id ref from open_goals g where g.deadline between now() and now()+interval '7 days'
union all select 'campaign_tasks',90,'Campaign needs execution',(c.title||' has open campaign tasks.')::text,'campaign',c.id from active_campaigns c where exists(select 1 from public.tgg_campaign_tasks t where t.campaign_id=c.id and t.owner_user_id=(select id from uid) and t.status not in ('done','completed'))
union all select 'release_not_ready',85,'Release not ready',(remaining||' of '||total||' checklist items remain.')::text,'release',release_id from incomplete_releases where remaining>0
union all select 'smart_link_quiet',60,'Smart link needs traffic',(title||' has no tracked clicks in the last 7 days.')::text,'smart_link',id from links where clicks7=0
union all select 'opportunity_interest',70,'Opportunity has applicants',(title||' has '||applications||' application(s) waiting.')::text,'opportunity',id from apps where applications>0)
select code,prio,ttl,det,typ,ref from insights order by prio desc,ttl;$function$


-- [40000000831] function public.tgg_get_creator_growth_workspace_bundle(p_artist_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_get_creator_growth_workspace_bundle(p_artist_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); aid uuid; result jsonb;
begin
 if uid is null then raise exception 'authentication required'; end if;
 select a.id into aid from public.artists a where a.user_id=uid and (p_artist_id is null or a.id=p_artist_id) order by a.created_at limit 1;
 if aid is null then raise exception 'artist not found'; end if;
 select jsonb_build_object(
  'goals',coalesce((select jsonb_agg(to_jsonb(g) order by g.deadline nulls last) from public.tgg_creator_goals g where g.owner_user_id=uid and g.artist_id=aid),'[]'::jsonb),
  'campaigns',coalesce((select jsonb_agg(to_jsonb(c) order by c.starts_at desc nulls last) from public.tgg_creator_campaign_health c where c.creator_user_id=uid and c.artist_id=aid),'[]'::jsonb),
  'tasks',coalesce((select jsonb_agg(to_jsonb(t) order by t.due_at nulls last) from public.tgg_campaign_tasks t join public.tgg_campaigns c on c.id=t.campaign_id where t.owner_user_id=uid and c.artist_id=aid and t.status not in ('done','completed')),'[]'::jsonb),
  'actions',coalesce((select jsonb_agg(to_jsonb(q) order by q.priority desc,q.created_at desc) from (select * from public.tgg_creator_action_queue where owner_user_id=uid and artist_id=aid and status='open' and action_type in ('promote_release','improve_campaign','create_smart_link','complete_release_checklist') order by priority desc,created_at desc limit 20) q),'[]'::jsonb)
 ) into result;
 return result;
end $function$


-- [40000000832] function public.tgg_get_creator_live_booking_bundle(p_artist_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_get_creator_live_booking_bundle(p_artist_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); aid uuid; result jsonb;
begin
 if uid is null then raise exception 'authentication required'; end if;
 select a.id into aid from public.artists a where a.user_id=uid and (p_artist_id is null or a.id=p_artist_id) order by a.created_at limit 1;
 if aid is null then raise exception 'artist not found'; end if;
 select jsonb_build_object(
  'bookings',coalesce((select jsonb_agg(to_jsonb(b) order by b.requested_at desc) from (select * from public.tgg_booking_requests where provider_user_id=uid order by requested_at desc limit 50) b),'[]'::jsonb),
  'events',coalesce((select jsonb_agg(to_jsonb(e) order by e.starts_at) from (select * from public.tgg_events where created_by=uid and artist_id=aid and starts_at>=now()-interval '1 day' order by starts_at limit 30) e),'[]'::jsonb),
  'live',coalesce((select jsonb_agg(to_jsonb(l) order by l.scheduled_at nulls last) from (select * from public.tgg_live_events where host_user_id=uid and artist_id=aid and coalesce(ended_at,scheduled_at,created_at)>=now()-interval '7 days' order by scheduled_at nulls last limit 30) l),'[]'::jsonb),
  'actions',coalesce((select jsonb_agg(to_jsonb(q) order by q.priority desc,q.created_at desc) from (select * from public.tgg_creator_action_queue where owner_user_id=uid and artist_id=aid and status='open' and action_type in ('respond_booking','promote_event','prepare_live') order by priority desc,created_at desc limit 20) q),'[]'::jsonb)
 ) into result;
 return result;
end $function$


-- [40000000833] function public.tgg_get_creator_navigation_state()
CREATE OR REPLACE FUNCTION public.tgg_get_creator_navigation_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  uid uuid:=auth.uid();
  unread bigint:=0;
  msgs bigint:=0;
  collabs bigint:=0;
  actions bigint:=0;
  bookings bigint:=0;
  optional_count bigint:=0;
begin
  if uid is null then raise exception 'authentication required'; end if;

  select count(*) into unread from notifications where recipient_id=uid and read_at is null;
  select coalesce(sum(unread_messages),0) into msgs from creator_messenger_inbox_v1;
  select count(*) into collabs from creator_collaboration_inbox_v1 where direction='incoming' and status='pending';
  select count(*) into actions from tgg_creator_action_queue where owner_user_id=uid and status='open';
  select count(*) into bookings from tgg_booking_requests where provider_user_id=uid and status in ('pending','requested');
  optional_count:=jsonb_array_length(public.tgg_external_optional_upgrades_final());

  return jsonb_build_object(
    'version','5000',
    'badges',jsonb_build_object(
      'notifications',unread,
      'messages',msgs,
      'collaborations',collabs,
      'actions',actions,
      'bookings',bookings,
      'expansion',optional_count
    ),
    'navigation',jsonb_build_array(
      jsonb_build_object('key','dashboard','badge',actions),
      jsonb_build_object('key','releases','badge',0),
      jsonb_build_object('key','fans','badge',0),
      jsonb_build_object('key','growth','badge',0),
      jsonb_build_object('key','messages','badge',msgs+collabs),
      jsonb_build_object('key','live','badge',bookings),
      jsonb_build_object('key','opportunities','badge',0),
      jsonb_build_object('key','supporters','badge',0),
      jsonb_build_object('key','career','badge',0),
      jsonb_build_object('key','library','badge',0),
      jsonb_build_object('key','expansion','badge',optional_count)
    )
  );
end
$function$


-- [40000000834] function public.tgg_get_creator_opportunity_bundle(p_artist_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_get_creator_opportunity_bundle(p_artist_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  uid uuid:=auth.uid();
  aid uuid;
  result jsonb;
begin
  if uid is null then raise exception 'authentication required'; end if;

  select a.id into aid
  from public.artists a
  where a.user_id=uid
    and (p_artist_id is null or a.id=p_artist_id)
  order by a.created_at
  limit 1;

  if aid is null then raise exception 'artist not found'; end if;

  select jsonb_build_object(
    'matches',coalesce((
      select jsonb_agg(to_jsonb(m))
      from public.tgg_get_opportunity_matches(20) m
    ),'[]'::jsonb),
    'applications',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select ap.*,o.title as opportunity_title,o.opportunity_type,o.deadline
        from public.tgg_opportunity_applications ap
        join public.tgg_opportunities o on o.id=ap.opportunity_id
        where ap.applicant_user_id=uid
        order by ap.created_at desc
        limit 50
      ) x
    ),'[]'::jsonb),
    'created',coalesce((
      select jsonb_agg(to_jsonb(o) order by o.created_at desc)
      from (
        select *
        from public.tgg_opportunities
        where created_by=uid
        order by created_at desc
        limit 30
      ) o
    ),'[]'::jsonb)
  ) into result;

  return result;
end
$function$


-- [40000000835] function public.tgg_get_creator_release_workspace_bundle(p_release_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_get_creator_release_workspace_bundle(p_release_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_artist uuid;
  v_result jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select m.artist_id into v_artist from public.mixtapes m join public.artists a on a.id=m.artist_id where m.id=p_release_id and a.user_id=v_uid limit 1;
  if v_artist is null then raise exception 'release not found'; end if;
  select jsonb_build_object(
    'release',coalesce((select to_jsonb(r) - 'creator_user_id' from public.tgg_creator_release_health r where r.creator_user_id=v_uid and r.artist_id=v_artist and r.release_id=p_release_id limit 1),'{}'::jsonb),
    'checklist',coalesce((select jsonb_agg(to_jsonb(x) order by x.due_at nulls last,x.label) from (select id,item_code,label,status,due_at,notes,updated_at from public.tgg_release_checklist_items where owner_user_id=v_uid and artist_id=v_artist and release_id=p_release_id) x),'[]'::jsonb),
    'credits',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at,x.person_name) from (select id,track_id,person_name,role,tgg_user_id,notes,created_at from public.tgg_release_credits where owner_user_id=v_uid and artist_id=v_artist and release_id=p_release_id) x),'[]'::jsonb),
    'clearance',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc,x.item_type) from (select id,item_type,description,source_name,permission_status,proof_url,notes,created_at,updated_at from public.tgg_clearance_items where owner_user_id=v_uid and artist_id=v_artist and release_id=p_release_id) x),'[]'::jsonb),
    'smart_links',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select id,title,slug,destination_type,destinations,click_count,is_active,created_at,updated_at from public.tgg_smart_links where owner_user_id=v_uid and artist_id=v_artist and release_id=p_release_id) x),'[]'::jsonb),
    'generated_at',now()
  ) into v_result;
  return v_result;
end $function$


-- [40000000836] function public.tgg_get_creator_shell_bundle()
CREATE OR REPLACE FUNCTION public.tgg_get_creator_shell_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); aid uuid; result jsonb;
begin
 if uid is null then raise exception 'authentication required'; end if;
 select id into aid from public.artists where user_id=uid order by created_at limit 1;
 select jsonb_build_object(
  'artist_id',aid,
  'manifest',public.tgg_get_creator_workspace_manifest(),
  'notifications',coalesce((select jsonb_agg(to_jsonb(n) order by n.created_at desc) from (select id,notification_type,entity_type,entity_id,title,body,read_at,created_at from public.notifications where recipient_id=uid order by created_at desc limit 30) n),'[]'::jsonb),
  'unread_notifications',(select count(*) from public.notifications where recipient_id=uid and read_at is null),
  'digest_preferences',coalesce((select to_jsonb(p) from public.tgg_creator_digest_preferences p where p.user_id=uid),'{}'::jsonb),
  'command_center',coalesce((select to_jsonb(c) from public.tgg_creator_command_center c where c.creator_user_id=uid and c.artist_id=aid),'{}'::jsonb),
  'top_actions',coalesce((select jsonb_agg(to_jsonb(q) order by q.priority desc,q.created_at desc) from (select id,action_type,title,rationale,priority,due_at,metadata,created_at from public.tgg_creator_action_queue where owner_user_id=uid and (aid is null or artist_id=aid) and status='open' order by priority desc,created_at desc limit 8) q),'[]'::jsonb)
 ) into result;
 return result;
end $function$


-- [40000000837] function public.tgg_get_creator_supporters_revenue_bundle(p_artist_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_get_creator_supporters_revenue_bundle(p_artist_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); aid uuid; result jsonb;
begin
 if uid is null then raise exception 'authentication required'; end if;
 select id into aid from public.artists where user_id=uid and (p_artist_id is null or id=p_artist_id) order by created_at limit 1;
 if aid is null then raise exception 'artist not found'; end if;
 select jsonb_build_object(
 'summary',coalesce((select to_jsonb(s) from public.tgg_creator_supporter_summary s where s.creator_user_id=uid and s.artist_id=aid),'{}'::jsonb),
 'monetization',coalesce((select to_jsonb(m) from public.tgg_creator_monetization_summary m where m.creator_user_id=uid and m.artist_id=aid),'{}'::jsonb),
 'tiers',coalesce((select jsonb_agg(to_jsonb(t) order by t.price_cents) from public.tgg_membership_tiers t where t.artist_id=aid),'[]'::jsonb),
 'memberships',coalesce((select jsonb_agg(to_jsonb(x) order by x.started_at desc) from (select m.id,m.tier_id,m.artist_id,m.fan_user_id,m.status,m.started_at,m.current_period_end,m.cancel_at_period_end from public.tgg_memberships m where m.artist_id=aid order by m.started_at desc limit 100) x),'[]'::jsonb),
 'transactions',coalesce((select jsonb_agg(to_jsonb(x) order by x.paid_at desc nulls last) from (select id,transaction_type,amount_cents,currency,platform_fee_cents,status,created_at,paid_at from public.tgg_support_transactions where artist_id=aid order by paid_at desc nulls last,created_at desc limit 100) x),'[]'::jsonb),
 'actions',coalesce((select jsonb_agg(to_jsonb(q) order by q.priority desc,q.created_at desc) from (select * from public.tgg_creator_action_queue where owner_user_id=uid and artist_id=aid and status='open' and action_type in ('retain_supporter','win_back_supporter','welcome_supporter','reward_supporter') order by priority desc,created_at desc limit 30) q),'[]'::jsonb)
 ) into result; return result;
end $function$


