-- [40000000846] function public.tgg_get_creator_ui_workspace_states()
CREATE OR REPLACE FUNCTION public.tgg_get_creator_ui_workspace_states()
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO 'public'
