 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$ select jsonb_build_object('artist',to_jsonb(a),'releases',coalesce((select jsonb_agg(to_jsonb(r) order by r.release_date desc nulls last) from public.public_home_feed_v1 r where r.artist_id=a.artist_id),'[]'::jsonb)) from public.public_artist_profile_v1 a where a.artist_id=p_artist_id limit 1 $function$


-- [40000000858] function public.tgg_get_public_collection(p_collection_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_get_public_collection(p_collection_id uuid)
 RETURNS TABLE(collection_id uuid, collection_name text, collection_description text, updated_at timestamp with time zone, item_id uuid, mixtape_id uuid, mixtape_title text, artist_name text, cover_url text, slug text, added_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select
    c.id,
    c.name,
    c.description,
    c.updated_at,
    i.id,
    i.mixtape_id,
    m.title,
    a.stage_name,
    m.cover_url,
    m.slug,
    i.added_at
  from public.fan_collections c
  join public.fan_collection_items i
    on i.collection_id=c.id
  join public.mixtapes m
    on m.id=i.mixtape_id
   and m.status='published'::public.mixtape_status
  left join public.public_artist_directory_v1 a
    on a.artist_id=m.artist_id
  where c.id=p_collection_id
    and c.is_public=true
  order by i.added_at desc;
$function$


-- [40000000859] function public.tgg_get_public_home_bundle(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_get_public_home_bundle(p_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
      select jsonb_build_object(
        'bootstrap',(select to_jsonb(b) from public.public_frontend_bootstrap_v1 b limit 1),
        'releases',coalesce((
          select jsonb_agg(to_jsonb(x))
          from (
            select * from public.public_home_feed_v1
            order by featured desc,release_date desc nulls last
            limit greatest(1,least(coalesce(p_limit,12),50))
          ) x
        ),'[]'::jsonb),
        'videos',coalesce((
          select jsonb_agg(to_jsonb(x))
          from (
            select * from public.public_videos_v1
            order by featured desc,publish_date desc nulls last
            limit 12
          ) x
        ),'[]'::jsonb),
        'interviews',coalesce(tgg_safe_api.public_interviews_feed(12)->'interviews','[]'::jsonb),
        'merch',coalesce((
          select jsonb_agg(to_jsonb(x))
          from (
            select * from public.public_merch_v1
            order by published_at desc nulls last
            limit 12
          ) x
        ),'[]'::jsonb)
      );
    $function$


-- [40000000860] function public.tgg_get_public_release_bundle(p_release_id uuid, p_slug text)
