AS $function$ select jsonb_build_object('release',to_jsonb(d),'tracks',coalesce((select jsonb_agg(to_jsonb(t) order by t.track_number) from public.public_release_tracks_v1 t where t.mixtape_id=d.mixtape_id),'[]'::jsonb),'engagement',coalesce((select to_jsonb(e) from public.public_release_engagement_v2 e where e.mixtape_id=d.mixtape_id),'{}'::jsonb)) from public.public_release_detail_v1 d where (p_release_id is not null and d.mixtape_id=p_release_id) or (p_release_id is null and p_slug is not null and d.slug=p_slug) limit 1 $function$


-- [40000000861] function public.tgg_get_site_route_manifest()
CREATE OR REPLACE FUNCTION public.tgg_get_site_route_manifest()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(
    jsonb_agg(to_jsonb(r) order by r.area,r.nav_group,r.nav_order,r.title),
    '[]'::jsonb
  )
  from public.tgg_site_routes r
  where r.is_active=true
    and r.route_key <> 'artist_dashboard'
    and r.access_level <> 'admin'
    and (
      r.access_level='public'
      or (
        r.access_level='authenticated'
        and (select auth.uid()) is not null
      )
      or (
        r.access_level='artist'
        and exists (
          select 1
          from public.public_artist_directory_v1 a
          where a.user_id=(select auth.uid())
        )
      )
    );
$function$


