-- [40000000863] function public.tgg_get_user_music_library_bundle()
CREATE OR REPLACE FUNCTION public.tgg_get_user_music_library_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid();
begin
 if uid is null then raise exception 'authentication required'; end if;
 return jsonb_build_object(
  'library',coalesce((select jsonb_agg(to_jsonb(x) order by x.saved_at desc) from (select * from public.fan_library where fan_user_id=uid order by saved_at desc limit 100) x),'[]'::jsonb),
  'following_feed',coalesce((select jsonb_agg(to_jsonb(x) order by x.release_date desc nulls last) from (select * from public.fan_following_feed where fan_user_id=uid order by release_date desc nulls last limit 50) x),'[]'::jsonb),
  'collections',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from (select * from public.fan_collection_summary where user_id=uid order by updated_at desc limit 50) x),'[]'::jsonb),
  'playlists',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'description',p.description,'is_public',p.is_public,'created_at',p.created_at,'updated_at',p.updated_at,'item_count',(select count(*) from public.tgg_playlist_items i where i.playlist_id=p.id)) order by p.updated_at desc) from public.tgg_playlists p where p.user_id=uid),'[]'::jsonb)
 );
end $function$


-- [40000000864] function public.tgg_get_video_asset_manifest(p_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_get_video_asset_manifest(p_project_id uuid)
 RETURNS TABLE(id uuid, asset_type text, title text, storage_path text, mime_type text, duration_seconds numeric, width integer, height integer, file_size_bytes bigint, metadata jsonb, created_at timestamp with time zone)
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  select a.id,a.asset_type,a.title,a.storage_path,a.mime_type,a.duration_seconds,a.width,a.height,a.file_size_bytes,a.metadata,a.created_at
  from public.tgg_media_vault_assets a
  join public.tgg_creative_projects p on p.id=a.project_id
  where a.project_id=p_project_id and p.user_id=(select auth.uid()) and p.project_type='video'
  order by a.created_at desc;
$function$


-- [40000000865] function public.tgg_growth_achievement_share_kit()
CREATE OR REPLACE FUNCTION public.tgg_growth_achievement_share_kit()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist public.artists;
  v_profile_url text;
  v_items jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select * into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist.id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-ACHIEVEMENT-SHARE-1.0',
      'has_artist_profile',false,'items','[]'::jsonb,'generated_at',now()
    );
  end if;

  v_profile_url:='https://trugogettamixtapes.blogspot.com/p/public-artist-profile.html?artist_id='||v_artist.id;

  select coalesce(jsonb_agg(x.item order by x.earned_at desc),'[]'::jsonb)
  into v_items
  from (
    select
      b.earned_at,
      jsonb_build_object(
        'kind','badge',
        'key',b.badge_key,
        'title',b.badge_title,
        'description',b.badge_description,
        'level',b.badge_level,
        'earned_at',b.earned_at,
        'share_text','I just unlocked "'||b.badge_title||'" on TRU GO GETTA. Growth level '||b.badge_level||'.',
        'share_url',v_profile_url
      ) as item
    from public.tgg_creator_growth_badges b
    where b.owner_user_id=v_uid

    union all

    select
      m.achieved_at,
      jsonb_build_object(
        'kind','milestone',
        'key',m.milestone_key,
        'title',m.milestone_title,
        'description','Creator growth milestone',
        'earned_at',m.achieved_at,
        'share_text','I just hit "'||m.milestone_title||'" on TRU GO GETTA.',
        'share_url',v_profile_url
      ) as item
    from public.tgg_creator_growth_milestones m
    where m.owner_user_id=v_uid
  ) x;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-ACHIEVEMENT-SHARE-1.0',
    'artist',jsonb_build_object('artist_id',v_artist.id,'stage_name',v_artist.stage_name),
    'profile_url',v_profile_url,
    'items',v_items,
    'count',jsonb_array_length(v_items),
    'privacy','public-safe achievement text only; private analytics excluded',
    'generated_at',now()
  );
end
$function$


-- [40000000866] function public.tgg_growth_acquisition_metrics()
CREATE OR REPLACE FUNCTION public.tgg_growth_acquisition_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_published integer:=0;
  v_followers integer:=0;
  v_referrals integer:=0;
  v_plays bigint:=0;
  v_downloads bigint:=0;
  v_smart_links integer:=0;
  v_link_clicks bigint:=0;
  v_clicks_30d bigint:=0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object(
      'ok',true,
      'version','GROWTH-ACQUISITION-METRICS-1.0',
      'has_artist_profile',false,
      'generated_at',now()
    );
  end if;

  select
    count(*),
    coalesce(sum(play_count),0),
    coalesce(sum(download_count),0)
  into v_published,v_plays,v_downloads
  from public.mixtapes
  where artist_id=v_artist_id and status='published';

  select count(*) into v_followers
  from public.artist_follows
  where artist_id=v_artist_id;

  select count(*) into v_referrals
  from public.tgg_referral_claims
  where referrer_user_id=v_uid;

  select count(*),coalesce(sum(click_count),0)
  into v_smart_links,v_link_clicks
  from public.tgg_smart_links
  where owner_user_id=v_uid and is_active=true;

  select count(*) into v_clicks_30d
  from public.tgg_smart_link_events e
  where e.link_id in (
    select l.id from public.tgg_smart_links l where l.owner_user_id=v_uid
  )
    and e.event_type='click'
    and e.occurred_at>=now()-interval '30 days';

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-ACQUISITION-METRICS-1.0',
    'has_artist_profile',true,
    'artist_id',v_artist_id,
    'published_releases',v_published,
    'followers',v_followers,
    'referral_conversions',v_referrals,
    'release_plays',v_plays,
    'release_downloads',v_downloads,
    'active_smart_links',v_smart_links,
    'smart_link_clicks',v_link_clicks,
    'smart_link_clicks_30d',v_clicks_30d,
    'generated_at',now()
  );
end
$function$


-- [40000000867] function public.tgg_growth_attribution_funnel()
CREATE OR REPLACE FUNCTION public.tgg_growth_attribution_funnel()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_shares bigint:=0;
  v_clicks bigint:=0;
  v_followers bigint:=0;
  v_saves bigint:=0;
  v_referrals bigint:=0;
  v_reactions bigint:=0;
  v_comments bigint:=0;
  v_sources jsonb:='[]'::jsonb;
  v_campaigns jsonb:='[]'::jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-ATTRIBUTION-1.0',
      'has_artist_profile',false,
      'generated_at',now()
    );
  end if;

  select count(*) into v_shares
  from public.tgg_creator_growth_activity
  where owner_user_id=v_uid
    and action_type in ('share_artist','share_release','share_referral');

  select count(*) into v_clicks
  from public.tgg_smart_link_events e
  join public.tgg_smart_links l on l.id=e.link_id
  where l.owner_user_id=v_uid
    and e.event_type='click';

  select count(*) into v_followers
  from public.artist_follows
  where artist_id=v_artist_id;

  select count(*) into v_saves
  from public.release_saves rs
  join public.mixtapes m on m.id=rs.mixtape_id
  where m.artist_id=v_artist_id and m.status='published';

  select count(*) into v_referrals
  from public.tgg_referral_claims
  where referrer_user_id=v_uid;

  select count(*) into v_reactions
  from public.release_reactions rr
  join public.mixtapes m on m.id=rr.mixtape_id
  where m.artist_id=v_artist_id and m.status='published';

  select count(*) into v_comments
  from public.release_comments rc
  join public.mixtapes m on m.id=rc.mixtape_id
  where m.artist_id=v_artist_id
    and m.status='published'
    and coalesce(rc.hidden_by_creator,false)=false;

  select coalesce(jsonb_agg(jsonb_build_object(
    'source',source,
    'clicks',clicks
  ) order by clicks desc,source),'[]'::jsonb)
  into v_sources
  from (
    select coalesce(nullif(btrim(e.utm_source),''),nullif(btrim(e.referrer),''),'direct_or_unknown') as source,
           count(*)::bigint as clicks
    from public.tgg_smart_link_events e
    join public.tgg_smart_links l on l.id=e.link_id
    where l.owner_user_id=v_uid
      and e.event_type='click'
    group by 1
    order by 2 desc,1
    limit 12
  ) s;

  select coalesce(jsonb_agg(jsonb_build_object(
    'campaign',campaign,
    'clicks',clicks
  ) order by clicks desc,campaign),'[]'::jsonb)
  into v_campaigns
  from (
    select coalesce(nullif(btrim(e.utm_campaign),''),'uncategorized') as campaign,
           count(*)::bigint as clicks
    from public.tgg_smart_link_events e
    join public.tgg_smart_links l on l.id=e.link_id
    where l.owner_user_id=v_uid
      and e.event_type='click'
    group by 1
    order by 2 desc,1
    limit 12
  ) c;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-ATTRIBUTION-1.0',
    'funnel',jsonb_build_object(
      'tracked_shares',v_shares,
      'smart_link_clicks',v_clicks,
      'followers',v_followers,
      'release_saves',v_saves,
      'referral_conversions',v_referrals,
      'reactions',v_reactions,
      'comments',v_comments
    ),
    'rates',jsonb_build_object(
      'clicks_per_tracked_share',case when v_shares>0 then round(v_clicks::numeric/v_shares,3) else null end,
      'fan_signals_per_click',case when v_clicks>0 then round((v_followers+v_saves+v_referrals+v_reactions+v_comments)::numeric/v_clicks,3) else null end
    ),
    'click_attribution',jsonb_build_object(
      'by_source',v_sources,
      'by_campaign',v_campaigns,
      'note','Source/campaign attribution applies to smart-link clicks only. Downstream fan signals remain platform totals until a conversion can be tied to a specific click/session.'
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000868] function public.tgg_growth_attribution_share_kit()
CREATE OR REPLACE FUNCTION public.tgg_growth_attribution_share_kit()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_week text:=to_char(date_trunc('week',now()),'YYYYMMDD');
  v_links jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'link_id',l.id,
    'title',l.title,
    'slug',l.slug,
    'release_id',l.release_id,
    'base_url','https://trugogettamixtapes.blogspot.com/p/smart-link.html?slug='||l.slug,
    'channels',jsonb_build_array(
      jsonb_build_object(
        'key','growth',
        'label','Creator OS Growth',
        'source','creator_os',
        'medium','growth',
        'campaign','weekly_growth_'||v_week,
        'url','https://trugogettamixtapes.blogspot.com/p/smart-link.html?slug='||l.slug||
          '&utm_source=creator_os&utm_medium=growth&utm_campaign=weekly_growth_'||v_week
      ),
      jsonb_build_object(
        'key','story',
        'label','Story',
        'source','tgg_story',
        'medium','social',
        'campaign','release_push_'||v_week,
        'url','https://trugogettamixtapes.blogspot.com/p/smart-link.html?slug='||l.slug||
          '&utm_source=tgg_story&utm_medium=social&utm_campaign=release_push_'||v_week
      ),
      jsonb_build_object(
        'key','short',
        'label','Short',
        'source','tgg_short',
        'medium','social',
        'campaign','release_push_'||v_week,
        'url','https://trugogettamixtapes.blogspot.com/p/smart-link.html?slug='||l.slug||
          '&utm_source=tgg_short&utm_medium=social&utm_campaign=release_push_'||v_week
      ),
      jsonb_build_object(
        'key','dm',
        'label','Direct Message',
        'source','direct_message',
        'medium','dm',
        'campaign','release_push_'||v_week,
        'url','https://trugogettamixtapes.blogspot.com/p/smart-link.html?slug='||l.slug||
          '&utm_source=direct_message&utm_medium=dm&utm_campaign=release_push_'||v_week
      ),
      jsonb_build_object(
        'key','referral',
        'label','Referral Push',
        'source','referral_push',
        'medium','invite',
        'campaign','creator_invite_'||v_week,
        'url','https://trugogettamixtapes.blogspot.com/p/smart-link.html?slug='||l.slug||
          '&utm_source=referral_push&utm_medium=invite&utm_campaign=creator_invite_'||v_week
      )
    )
  ) order by l.created_at desc),'[]'::jsonb)
  into v_links
  from public.tgg_smart_links l
  where l.owner_user_id=v_uid and l.is_active=true;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-ATTRIBUTION-SHARE-KIT-1.0',
    'week_key',v_week,
    'links',v_links,
    'generated_at',now()
  );
end
$function$


-- [40000000869] function public.tgg_growth_audience_intelligence()
CREATE OR REPLACE FUNCTION public.tgg_growth_audience_intelligence()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_total bigint:=0;
  v_followers bigint:=0;
  v_savers bigint:=0;
  v_referrals bigint:=0;
  v_segments jsonb:='[]'::jsonb;
  v_journey jsonb:='[]'::jsonb;
  v_actions jsonb:='[]'::jsonb;
  v_avg_eng numeric:=0;
  v_avg_rec numeric:=0;
  v_avg_loy numeric:=0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-AUDIENCE-INTELLIGENCE-1.0',
      'has_artist_profile',false,'generated_at',now()
    );
  end if;

  select count(*) into v_followers
  from public.artist_follows
  where artist_id=v_artist_id;

  select count(distinct rs.user_id) into v_savers
  from public.release_saves rs
  join public.mixtapes m on m.id=rs.mixtape_id
  where m.artist_id=v_artist_id and m.status='published';

  select count(*) into v_referrals
  from public.tgg_referral_claims
  where referrer_user_id=v_uid;

  select count(*),
         coalesce(avg(engagement_score),0),
         coalesce(avg(recency_score),0),
         coalesce(avg(loyalty_score),0)
  into v_total,v_avg_eng,v_avg_rec,v_avg_loy
  from public.tgg_fan_intelligence_snapshots
  where creator_user_id=v_uid and artist_id=v_artist_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'segment',fan_state,
    'count',fan_count
  ) order by fan_count desc,fan_state),'[]'::jsonb)
  into v_segments
  from (
    select fan_state,count(*)::bigint fan_count
    from public.tgg_fan_intelligence_snapshots
    where creator_user_id=v_uid and artist_id=v_artist_id
    group by fan_state
  ) s;

  select coalesce(jsonb_agg(jsonb_build_object(
    'journey_stage',journey_stage,
    'count',fan_count
  ) order by fan_count desc,journey_stage),'[]'::jsonb)
  into v_journey
  from (
    select coalesce(journey_stage,'unknown') journey_stage,count(*)::bigint fan_count
    from public.tgg_fan_journey
    where artist_id=v_artist_id
    group by coalesce(journey_stage,'unknown')
  ) j;

  select coalesce(jsonb_agg(jsonb_build_object(
    'action',recommended_action,
    'count',fan_count
  ) order by fan_count desc,recommended_action),'[]'::jsonb)
  into v_actions
  from (
    select recommended_action,count(*)::bigint fan_count
    from public.tgg_fan_intelligence_snapshots
    where creator_user_id=v_uid
      and artist_id=v_artist_id
      and nullif(btrim(coalesce(recommended_action,'')),'') is not null
    group by recommended_action
  ) a;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-AUDIENCE-INTELLIGENCE-1.0',
    'artist_id',v_artist_id,
    'audience_size',jsonb_build_object(
      'intelligence_profiles',v_total,
      'followers',v_followers,
      'unique_savers',v_savers,
      'referral_conversions',v_referrals
    ),
    'average_scores',jsonb_build_object(
      'engagement',round(v_avg_eng,1),
      'recency',round(v_avg_rec,1),
      'loyalty',round(v_avg_loy,1)
    ),
    'segments',v_segments,
    'journey_stages',v_journey,
    'recommended_actions',v_actions,
    'privacy',jsonb_build_object(
      'aggregate_only',true,
      'fan_identifiers_exposed',false
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000870] function public.tgg_growth_autopilot()
CREATE OR REPLACE FUNCTION public.tgg_growth_autopilot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist public.artists;
  v_release public.mixtapes;
  v_ref jsonb;
  v_coach jsonb;
  v_weekly jsonb;
  v_artist_url text;
  v_release_url text;
  v_ref_code text;
  v_plan jsonb;
  v_smart_links integer:=0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select * into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist.id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-AUTOPILOT-1.1',
      'has_artist_profile',false,
      'plan','[]'::jsonb,
      'generated_at',now()
    );
  end if;

  select * into v_release
  from public.mixtapes
  where artist_id=v_artist.id and status='published'
  order by coalesce(featured,false) desc,
           (coalesce(play_count,0)+(coalesce(download_count,0)*3)) desc,
           created_at desc
  limit 1;

  select count(*) into v_smart_links
  from public.tgg_smart_links
  where owner_user_id=v_uid and is_active=true;

  v_ref:=public.tgg_referral_code();
  v_coach:=public.tgg_growth_coach_refresh();
  v_weekly:=public.tgg_growth_weekly_refresh();

  v_artist_url:='https://trugogettamixtapes.blogspot.com/p/public-artist-profile.html?artist_id='||v_artist.id;
  v_ref_code:=coalesce(v_ref->>'code','');
  if v_release.id is not null and nullif(btrim(coalesce(v_release.slug,'')),'') is not null then
    v_release_url:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-shell?view=release&slug='||v_release.slug;
  end if;

  v_plan:=jsonb_build_array(
    jsonb_build_object(
      'day',1,'key','profile_push','title','Push your artist profile',
      'goal','Earn your first follower',
      'action','Share your public artist profile with people who already know your music.',
      'cta','Follow the artist profile',
      'share_url',v_artist_url,
      'coach_priority',96
    ),
    jsonb_build_object(
      'day',2,'key','release_push','title','Push your strongest release',
      'goal','Drive tracked plays',
      'action',case when v_release.id is null
        then 'Publish a release so Growth has something to promote.'
        else 'Share "'||v_release.title||'" in a Story, Short, post, or direct message.' end,
      'cta','Listen now',
      'share_url',v_release_url,
      'release_id',v_release.id,
      'release_title',v_release.title,
      'coach_priority',84
    ),
    jsonb_build_object(
      'day',3,'key','referral_push','title','Invite one real person',
      'goal','Get your first referral conversion',
      'action','Send your TRU GO GETTA referral code to one fan, artist, producer, or collaborator who would actually use the platform.',
      'cta','Join TRU GO GETTA',
      'referral_code',v_ref_code,
      'coach_priority',88
    ),
    jsonb_build_object(
      'day',4,'key','save_push','title','Ask for a save',
      'goal','Earn your first release save',
      'action',case when v_release.id is null
        then 'Publish a release before running a save campaign.'
        else 'Re-share "'||v_release.title||'" and explicitly ask listeners to save it if they want to come back.' end,
      'cta','Save this release',
      'share_url',v_release_url,
      'release_id',v_release.id,
      'coach_priority',78
    ),
    jsonb_build_object(
      'day',5,
      'key',case when v_smart_links>0 then 'measure_smart_link' else 'smart_link' end,
      'title',case when v_smart_links>0 then 'Work your smart link' else 'Set up one measured destination' end,
      'goal',case when v_smart_links>0 then 'Generate measurable click traffic' else 'Create your first smart link' end,
      'action',case when v_smart_links>0
        then 'Your smart link is live. Share it in a channel you have not used yet, then watch smart-link clicks in Acquisition Metrics.'
        else 'Create one smart link for your strongest release so future shares produce click data.' end,
      'cta',case when v_smart_links>0 then 'Drive smart-link clicks' else 'Create smart link' end,
      'coach_priority',92
    ),
    jsonb_build_object(
      'day',6,'key','repeat_winner','title','Repeat the best-performing push',
      'goal','Build momentum',
      'action','Check Growth Wins and Acquisition Metrics, then repeat whichever share produced the strongest response.',
      'cta','Open Growth metrics',
      'coach_priority',70
    ),
    jsonb_build_object(
      'day',7,'key','weekly_close','title','Close the week',
      'goal','Complete weekly missions and advance your streak',
      'action','Open Growth, finish any remaining weekly mission, then review your new milestones, badges, and next coach action.',
      'cta','Finish the week',
      'coach_priority',65
    )
  );

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-AUTOPILOT-1.1',
    'artist',jsonb_build_object('artist_id',v_artist.id,'stage_name',v_artist.stage_name),
    'focus_release',case when v_release.id is null then null else jsonb_build_object(
      'release_id',v_release.id,'title',v_release.title,'slug',v_release.slug,'url',v_release_url
    ) end,
    'active_smart_links',v_smart_links,
    'coach',v_coach,
    'weekly',v_weekly,
    'plan',v_plan,
    'generated_at',now()
  );
end
$function$


