-- [40000000872] function public.tgg_growth_autopilot_progress()
CREATE OR REPLACE FUNCTION public.tgg_growth_autopilot_progress()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_week date:=(date_trunc('week',now()))::date;
  v_items jsonb;
  v_count integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'step_key',step_key,'day',day_no,'status',status,'completed_at',completed_at
  ) order by day_no),'[]'::jsonb),count(*)
  into v_items,v_count
  from public.tgg_growth_autopilot_progress
  where owner_user_id=v_uid and week_start=v_week;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-AUTOPILOT-PROGRESS-1.0',
    'week_start',v_week,
    'completed_count',v_count,
    'total_steps',7,
    'completion_percent',round((v_count::numeric/7)*100),
    'items',v_items,
    'generated_at',now()
  );
end
$function$


