-- [40000000875] function public.tgg_growth_campaign_refresh()
CREATE OR REPLACE FUNCTION public.tgg_growth_campaign_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_week date:=(date_trunc('week',now()))::date;
  v_campaign_id uuid;
  v_plan jsonb;
  v_item jsonb;
  v_key text;
  v_completed integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object('ok',true,'version','GROWTH-CAMPAIGN-1.0','has_artist_profile',false);
  end if;

  select id into v_campaign_id
  from public.tgg_campaigns
  where owner_user_id=v_uid
    and campaign_type='growth_sprint'
    and (starts_at at time zone 'UTC')::date=v_week
  limit 1;

  if v_campaign_id is null then
    insert into public.tgg_campaigns(
      owner_user_id,artist_id,title,campaign_type,status,starts_at,ends_at,objective,target_value,current_value
    ) values(
      v_uid,v_artist_id,'7-Day Growth Sprint · '||to_char(v_week,'Mon DD'),
      'growth_sprint','active',v_week::timestamptz,(v_week+7)::timestamptz,
      'Complete the weekly Autopilot plan and generate measurable audience growth.',7,0
    ) returning id into v_campaign_id;
  end if;

  v_plan:=public.tgg_growth_autopilot()->'plan';

  for v_item in select value from jsonb_array_elements(coalesce(v_plan,'[]'::jsonb))
  loop
    v_key:=v_item->>'key';
    if not exists(
      select 1 from public.tgg_campaign_tasks
      where campaign_id=v_campaign_id and owner_user_id=v_uid and metadata->>'autopilot_key'=v_key
    ) then
      insert into public.tgg_campaign_tasks(
        campaign_id,owner_user_id,task_type,title,due_at,status,metadata
      ) values(
        v_campaign_id,v_uid,'growth_autopilot',
        coalesce(v_item->>'title','Growth action'),
        v_week::timestamptz + make_interval(days=>greatest(coalesce((v_item->>'day')::integer,1)-1,0)),
        'todo',
        jsonb_build_object(
          'autopilot_key',v_key,
          'day',v_item->'day',
          'goal',v_item->'goal',
          'action',v_item->'action',
          'cta',v_item->'cta',
          'share_url',v_item->'share_url',
          'referral_code',v_item->'referral_code',
          'release_id',v_item->'release_id'
        )
      );
    end if;
  end loop;

  update public.tgg_campaign_tasks t
  set status='completed',updated_at=now()
  where t.campaign_id=v_campaign_id
    and t.owner_user_id=v_uid
    and t.status<>'completed'
    and (
      (t.metadata->>'autopilot_key'='profile_push' and exists(select 1 from public.tgg_creator_growth_milestones m where m.owner_user_id=v_uid and m.milestone_key='first_follower'))
      or (t.metadata->>'autopilot_key'='release_push' and (
        exists(select 1 from public.tgg_creator_growth_milestones m where m.owner_user_id=v_uid and m.milestone_key='first_play')
        or exists(select 1 from public.tgg_creator_growth_activity a where a.owner_user_id=v_uid and a.action_type='share_release' and a.created_at>=v_week::timestamptz)
      ))
      or (t.metadata->>'autopilot_key'='referral_push' and exists(select 1 from public.tgg_creator_growth_milestones m where m.owner_user_id=v_uid and m.milestone_key='first_referral'))
      or (t.metadata->>'autopilot_key'='save_push' and exists(select 1 from public.tgg_creator_growth_milestones m where m.owner_user_id=v_uid and m.milestone_key='first_save'))
      or (t.metadata->>'autopilot_key'='smart_link' and exists(select 1 from public.tgg_creator_growth_milestones m where m.owner_user_id=v_uid and m.milestone_key='first_smart_link'))
      or (t.metadata->>'autopilot_key'='repeat_winner' and (select count(*) from public.tgg_creator_growth_activity a where a.owner_user_id=v_uid and a.action_type like 'share_%' and a.created_at>=v_week::timestamptz)>=2)
      or (t.metadata->>'autopilot_key'='weekly_close' and exists(
        select 1 from public.tgg_creator_weekly_missions wm
        where wm.owner_user_id=v_uid and wm.week_start=v_week
        group by wm.week_start
        having count(*)=3 and count(*) filter(where wm.status='completed')=3
      ))
    );

  select count(*) into v_completed
  from public.tgg_campaign_tasks
  where campaign_id=v_campaign_id and owner_user_id=v_uid and status='completed';

  update public.tgg_campaigns
  set current_value=v_completed,
      status=case when v_completed>=target_value then 'completed' else 'active' end,
      updated_at=now()
  where id=v_campaign_id and owner_user_id=v_uid;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-CAMPAIGN-1.0',
    'campaign',(select jsonb_build_object(
      'id',c.id,'title',c.title,'status',c.status,'starts_at',c.starts_at,'ends_at',c.ends_at,
      'objective',c.objective,'current_value',c.current_value,'target_value',c.target_value
    ) from public.tgg_campaigns c where c.id=v_campaign_id),
    'tasks',(select coalesce(jsonb_agg(jsonb_build_object(
      'id',t.id,'title',t.title,'status',t.status,'due_at',t.due_at,'metadata',t.metadata
    ) order by t.due_at,t.created_at),'[]'::jsonb)
      from public.tgg_campaign_tasks t
      where t.campaign_id=v_campaign_id and t.owner_user_id=v_uid),
    'generated_at',now()
  );
end;
$function$


-- [40000000876] function public.tgg_growth_coach_execute(p_action_type text)
CREATE OR REPLACE FUNCTION public.tgg_growth_coach_execute(p_action_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_action text:=lower(trim(coalesce(p_action_type,'')));
  v_artist_id uuid;
  v_release public.mixtapes;
  v_existing public.tgg_smart_links;
  v_result jsonb;
  v_release_url text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  if v_action not in ('create_smart_link') then
    raise exception 'COACH_ACTION_NOT_EXECUTABLE' using errcode='22023';
  end if;

  select id into v_artist_id from public.artists where user_id=v_uid order by created_at limit 1;
  if v_artist_id is null then raise exception 'ARTIST_PROFILE_REQUIRED' using errcode='P0002'; end if;

  select * into v_release
  from public.mixtapes
  where artist_id=v_artist_id and user_id=v_uid and status='published'
  order by coalesce(featured,false) desc,coalesce(play_count,0) desc,coalesce(download_count,0) desc,coalesce(release_date,created_at) desc
  limit 1;

  if v_release.id is null then raise exception 'PUBLISHED_RELEASE_REQUIRED' using errcode='P0002'; end if;

  select * into v_existing
  from public.tgg_smart_links
  where owner_user_id=v_uid and release_id=v_release.id and is_active=true
  order by created_at asc
  limit 1;

  if v_existing.id is not null then
    return jsonb_build_object(
      'ok',true,'action_type',v_action,'created',false,
      'link_id',v_existing.id,'slug',v_existing.slug,
      'public_url','/p/smart-link.html?slug='||v_existing.slug,
      'release_id',v_release.id,'release_title',v_release.title
    );
  end if;

  v_release_url:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-shell?view=release&slug='||v_release.slug;

  v_result:=public.tgg_smart_link_create(
    v_release.title||' · Smart Link',
    v_release.id,
    v_release.slug||'-smart',
    jsonb_build_array(jsonb_build_object(
      'provider','tgg',
      'label','TRU GO GETTA',
      'url',v_release_url
    )),
    true
  );

  perform private.tgg_growth_milestone_sync();

  return jsonb_build_object(
    'ok',true,
    'action_type',v_action,
    'created',true,
    'release_id',v_release.id,
    'release_title',v_release.title,
    'result',v_result
  );
end
$function$


-- [40000000877] function public.tgg_growth_coach_refresh()
CREATE OR REPLACE FUNCTION public.tgg_growth_coach_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_release_count integer:=0;
  v_followers integer:=0;
  v_referrals integer:=0;
  v_saves integer:=0;
  v_smart_links integer:=0;
  v_plays bigint:=0;
  v_added integer:=0;
  v_actions jsonb;
  v_milestones jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select id into v_artist_id from public.artists where user_id=v_uid order by created_at limit 1;
  if v_artist_id is null then
    return jsonb_build_object('ok',true,'version','GROWTH-COACH-1.1','has_artist_profile',false,'added_actions',0,'actions','[]'::jsonb,'generated_at',now());
  end if;

  v_milestones:=private.tgg_growth_milestone_sync();

  select count(*),coalesce(sum(play_count),0) into v_release_count,v_plays from public.mixtapes where artist_id=v_artist_id and status='published';
  select count(*) into v_followers from public.artist_follows where artist_id=v_artist_id;
  select count(*) into v_referrals from public.tgg_referral_claims where referrer_user_id=v_uid;
  select count(*) into v_saves from public.release_saves rs join public.mixtapes m on m.id=rs.mixtape_id where m.artist_id=v_artist_id and m.status='published';
  select count(*) into v_smart_links from public.tgg_smart_links where owner_user_id=v_uid and is_active=true;

  if v_release_count>0 and v_followers=0 and not exists(select 1 from public.tgg_creator_action_queue where owner_user_id=v_uid and source_type='growth' and source_id=v_artist_id and action_type='earn_first_follower' and status='open') then
    insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,source_id,action_type,title,rationale,priority,status,due_at,metadata)
    values(v_uid,v_artist_id,'growth',v_artist_id,'earn_first_follower','Earn your first follower','Your releases are live, but your artist profile has no followers yet. Share your artist profile and strongest release.',96,'open',now()+interval '2 days',jsonb_build_object('followers',v_followers,'published_releases',v_release_count)); v_added:=v_added+1;
  end if;
  if v_release_count>0 and v_smart_links=0 and not exists(select 1 from public.tgg_creator_action_queue where owner_user_id=v_uid and source_type='growth' and source_id=v_artist_id and action_type='create_smart_link' and status='open') then
    insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,source_id,action_type,title,rationale,priority,status,due_at,metadata)
    values(v_uid,v_artist_id,'growth',v_artist_id,'create_smart_link','Create a smart link for your music','Smart links give you one shareable destination and let Growth measure click-through traffic.',92,'open',now()+interval '2 days',jsonb_build_object('active_smart_links',v_smart_links)); v_added:=v_added+1;
  end if;
  if v_referrals=0 and not exists(select 1 from public.tgg_creator_action_queue where owner_user_id=v_uid and source_type='growth' and source_id=v_artist_id and action_type='get_first_referral' and status='open') then
    insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,source_id,action_type,title,rationale,priority,status,due_at,metadata)
    values(v_uid,v_artist_id,'growth',v_artist_id,'get_first_referral','Invite your first fan or creator','Your referral system is active. One successful invite starts the acquisition loop and gives Growth a measurable conversion.',88,'open',now()+interval '3 days',jsonb_build_object('referrals',v_referrals)); v_added:=v_added+1;
  end if;
  if v_release_count>0 and v_plays=0 and not exists(select 1 from public.tgg_creator_action_queue where owner_user_id=v_uid and source_type='growth' and source_id=v_artist_id and action_type='drive_first_plays' and status='open') then
    insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,source_id,action_type,title,rationale,priority,status,due_at,metadata)
    values(v_uid,v_artist_id,'growth',v_artist_id,'drive_first_plays','Drive your first tracked plays','You have published music but no tracked plays yet. Share a release link in Stories, Shorts, social posts, and direct messages.',84,'open',now()+interval '3 days',jsonb_build_object('plays',v_plays,'published_releases',v_release_count)); v_added:=v_added+1;
  end if;
  if v_release_count>0 and v_saves=0 and not exists(select 1 from public.tgg_creator_action_queue where owner_user_id=v_uid and source_type='growth' and source_id=v_artist_id and action_type='earn_first_save' and status='open') then
    insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,source_id,action_type,title,rationale,priority,status,due_at,metadata)
    values(v_uid,v_artist_id,'growth',v_artist_id,'earn_first_save','Earn your first release save','A save is a stronger retention signal than a click. Push your strongest release and ask listeners to save it.',78,'open',now()+interval '5 days',jsonb_build_object('release_saves',v_saves)); v_added:=v_added+1;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,'action_type',action_type,'title',title,'rationale',rationale,'priority',priority,'due_at',due_at,'metadata',metadata
  ) order by priority desc,created_at asc),'[]'::jsonb)
  into v_actions from public.tgg_creator_action_queue
  where owner_user_id=v_uid and source_type='growth' and status='open';

  return jsonb_build_object(
    'ok',true,'version','GROWTH-COACH-1.1','has_artist_profile',true,
    'added_actions',v_added,'open_action_count',jsonb_array_length(v_actions),
    'actions',v_actions,'milestones',v_milestones,'generated_at',now()
  );
end
$function$


-- [40000000878] function public.tgg_growth_collab_network()
CREATE OR REPLACE FUNCTION public.tgg_growth_collab_network()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist public.artists;
  v_candidate_count integer:=0;
  v_sent integer:=0;
  v_received integer:=0;
  v_accepted integer:=0;
  v_candidates jsonb:='[]'::jsonb;
  v_ref jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select * into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist.id is null then
    return jsonb_build_object(
      'ok',true,
      'version','GROWTH-COLLAB-NETWORK-1.0',
      'has_artist_profile',false,
      'network_ready',false,
      'candidate_count',0,
      'candidates','[]'::jsonb,
      'generated_at',now()
    );
  end if;

  select count(*) into v_candidate_count
  from public.artists a
  where a.user_id<>v_uid;

  select count(*) into v_sent
  from public.tgg_collaboration_requests
  where sender_id=v_uid;

  select count(*) into v_received
  from public.tgg_collaboration_requests
  where recipient_id=v_uid;

  select count(*) into v_accepted
  from public.tgg_collaboration_requests
  where (sender_id=v_uid or recipient_id=v_uid)
    and status='accepted';

  select coalesce(jsonb_agg(jsonb_build_object(
    'artist_id',a.id,
    'stage_name',a.stage_name,
    'bio',a.bio,
    'avatar_url',a.avatar_url,
    'has_music',exists(select 1 from public.mixtapes m where m.artist_id=a.id and m.status='published'),
    'published_release_count',(select count(*) from public.mixtapes m where m.artist_id=a.id and m.status='published')
  ) order by a.created_at desc),'[]'::jsonb)
  into v_candidates
  from (
    select *
    from public.artists a
    where a.user_id<>v_uid
    order by a.created_at desc
    limit 12
  ) a;

  v_ref:=public.tgg_referral_code();

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-COLLAB-NETWORK-1.0',
    'has_artist_profile',true,
    'network_ready',v_candidate_count>0,
    'candidate_count',v_candidate_count,
    'request_stats',jsonb_build_object(
      'sent',v_sent,
      'received',v_received,
      'accepted',v_accepted
    ),
    'candidates',v_candidates,
    'recruit_creator',jsonb_build_object(
      'recommended',v_candidate_count=0,
      'referral_code',v_ref->>'code',
      'message','Invite another artist, producer, songwriter, engineer, DJ, or creator to TRU GO GETTA, then use Collab search to start a project together.'
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000879] function public.tgg_growth_experiment_decision()
CREATE OR REPLACE FUNCTION public.tgg_growth_experiment_decision()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_exp public.tgg_growth_experiments;
  v_a public.tgg_growth_experiment_variants;
  v_b public.tgg_growth_experiment_variants;
  v_a_ctr numeric:=0;
  v_b_ctr numeric:=0;
  v_best text;
  v_best_ctr numeric:=0;
  v_other_ctr numeric:=0;
  v_abs_diff numeric:=0;
  v_rel_uplift numeric:=0;
  v_decision text:='keep_testing';
  v_reason text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_exp
  from public.tgg_growth_experiments
  where owner_user_id=v_uid and status='active'
  order by updated_at desc
  limit 1;

  if v_exp.id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-EXPERIMENT-DECISION-1.0',
      'experiment_available',false,'decision','no_experiment',
      'generated_at',now()
    );
  end if;

  select * into v_a from public.tgg_growth_experiment_variants
  where experiment_id=v_exp.id and variant_key='A' limit 1;
  select * into v_b from public.tgg_growth_experiment_variants
  where experiment_id=v_exp.id and variant_key='B' limit 1;

  v_a_ctr:=case when coalesce(v_a.share_count,0)>0 then v_a.click_count::numeric/v_a.share_count::numeric else 0 end;
  v_b_ctr:=case when coalesce(v_b.share_count,0)>0 then v_b.click_count::numeric/v_b.share_count::numeric else 0 end;

  if v_a_ctr>=v_b_ctr then
    v_best:='A'; v_best_ctr:=v_a_ctr; v_other_ctr:=v_b_ctr;
  else
    v_best:='B'; v_best_ctr:=v_b_ctr; v_other_ctr:=v_a_ctr;
  end if;

  v_abs_diff:=abs(v_a_ctr-v_b_ctr);
  v_rel_uplift:=case when v_other_ctr>0 then (v_best_ctr-v_other_ctr)/v_other_ctr else case when v_best_ctr>0 then 1 else 0 end end;

  if coalesce(v_a.share_count,0)<5 or coalesce(v_b.share_count,0)<5 then
    v_decision:='keep_testing';
    v_reason:='Each variant needs at least 5 recorded shares before Growth will compare them.';
  elsif coalesce(v_a.click_count,0)+coalesce(v_b.click_count,0)<3 then
    v_decision:='keep_testing';
    v_reason:='The test needs at least 3 attributed clicks before Growth will recommend a direction.';
  elsif v_abs_diff>=0.02 and v_rel_uplift>=0.20 then
    v_decision:='directional_winner';
    v_reason:='One variant is ahead by at least 2 percentage points of CTR and 20% relative uplift. Treat this as directional, not statistically conclusive.';
  else
    v_decision:='inconclusive';
    v_reason:='Both variants have enough activity to compare, but neither has a strong enough directional edge yet.';
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-EXPERIMENT-DECISION-1.0',
    'experiment_available',true,
    'experiment_id',v_exp.id,
    'decision',v_decision,
    'recommended_variant',case when v_decision='directional_winner' then v_best else null end,
    'reason',v_reason,
    'guardrails',jsonb_build_object(
      'min_shares_per_variant',5,
      'min_total_clicks',3,
      'min_absolute_ctr_gap_pct_points',2,
      'min_relative_uplift_pct',20,
      'confidence_claim','directional_only'
    ),
    'variant_a',jsonb_build_object(
      'shares',coalesce(v_a.share_count,0),
      'clicks',coalesce(v_a.click_count,0),
      'ctr_pct',round(v_a_ctr*100,2)
    ),
    'variant_b',jsonb_build_object(
      'shares',coalesce(v_b.share_count,0),
      'clicks',coalesce(v_b.click_count,0),
      'ctr_pct',round(v_b_ctr*100,2)
    ),
    'generated_at',now()
  );
end
$function$


