-- [40000000882] function public.tgg_growth_forecast()
CREATE OR REPLACE FUNCTION public.tgg_growth_forecast()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_week date:=(date_trunc('week',now()))::date;
  v_day integer:=extract(isodow from now())::integer;
  v_days_left integer:=greatest(7-extract(isodow from now())::integer,0);
  v_missions jsonb;
  v_total integer:=0;
  v_completed integer:=0;
  v_progress numeric:=0;
  v_expected numeric:=least(extract(isodow from now())::numeric/7.0,1.0);
  v_pace text;
  v_risk text;
  v_next jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-FORECAST-1.0','has_artist_profile',false,'generated_at',now()
    );
  end if;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'mission_key',mission_key,
      'title',title,
      'current_value',current_value,
      'target_value',target_value,
      'status',status,
      'remaining',greatest(target_value-current_value,0),
      'required_per_day',case
        when status='completed' then 0
        when v_days_left=0 then greatest(target_value-current_value,0)
        else round(greatest(target_value-current_value,0)::numeric/v_days_left,2)
      end,
      'progress_pct',round(least(current_value::numeric/nullif(target_value,0)*100,100),1)
    ) order by created_at),'[]'::jsonb),
    count(*),
    count(*) filter(where status='completed'),
    coalesce(avg(least(current_value::numeric/nullif(target_value,0),1)),0)
  into v_missions,v_total,v_completed,v_progress
  from public.tgg_creator_weekly_missions
  where owner_user_id=v_uid and week_start=v_week;

  if v_total=0 then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-FORECAST-1.0','has_artist_profile',true,
      'week_start',v_week,'days_left',v_days_left,'missions','[]'::jsonb,
      'pace','not_started','risk','unknown','generated_at',now()
    );
  end if;

  v_pace:=case
    when v_completed=v_total then 'complete'
    when v_progress>=v_expected+0.15 then 'ahead'
    when v_progress>=greatest(v_expected-0.15,0) then 'on_track'
    else 'behind'
  end;

  v_risk:=case
    when v_completed=v_total then 'none'
    when v_days_left=0 then 'high'
    when v_pace='behind' and v_days_left<=2 then 'high'
    when v_pace='behind' then 'medium'
    when v_days_left<=1 and v_completed<v_total then 'medium'
    else 'low'
  end;

  select jsonb_build_object(
    'action_type',action_type,'title',title,'priority',priority,'rationale',rationale
  )
  into v_next
  from public.tgg_creator_action_queue
  where owner_user_id=v_uid and source_type='growth' and status='open'
  order by priority desc,created_at asc
  limit 1;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-FORECAST-1.0',
    'has_artist_profile',true,
    'week_start',v_week,
    'day_of_week',v_day,
    'days_left',v_days_left,
    'completed_missions',v_completed,
    'total_missions',v_total,
    'overall_progress_pct',round(v_progress*100,1),
    'expected_progress_pct',round(v_expected*100,1),
    'pace',v_pace,
    'risk',v_risk,
    'missions',v_missions,
    'next_best_action',v_next,
    'method','transparent_weekly_pacing_v1',
    'generated_at',now()
  );
end
$function$


-- [40000000883] function public.tgg_growth_goal_sync()
CREATE OR REPLACE FUNCTION public.tgg_growth_goal_sync()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_followers bigint:=0;
  v_plays bigint:=0;
  v_saves bigint:=0;
  v_referrals bigint:=0;
  v_clicks bigint:=0;
  v_completed_now integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object('ok',true,'version','GROWTH-GOALS-1.0','has_artist_profile',false,'goals','[]'::jsonb);
  end if;

  select count(*) into v_followers from public.artist_follows where artist_id=v_artist_id;
  select coalesce(sum(play_count),0) into v_plays from public.mixtapes where artist_id=v_artist_id and status='published';
  select count(*) into v_saves
  from public.release_saves rs join public.mixtapes m on m.id=rs.mixtape_id
  where m.artist_id=v_artist_id and m.status='published';
  select count(*) into v_referrals from public.tgg_referral_claims where referrer_user_id=v_uid;
  select count(*) into v_clicks
  from public.tgg_smart_link_events e
  join public.tgg_smart_links l on l.id=e.link_id
  where l.owner_user_id=v_uid and e.event_type='click';

  insert into public.tgg_creator_goals(owner_user_id,artist_id,goal_type,title,target_value,current_value,unit,deadline,status)
  values
    (v_uid,v_artist_id,'system_followers_10','Reach 10 followers',10,v_followers,'followers',now()+interval '30 days',case when v_followers>=10 then 'completed' else 'active' end),
    (v_uid,v_artist_id,'system_plays_100','Reach 100 tracked plays',100,v_plays,'plays',now()+interval '30 days',case when v_plays>=100 then 'completed' else 'active' end),
    (v_uid,v_artist_id,'system_saves_10','Earn 10 release saves',10,v_saves,'saves',now()+interval '30 days',case when v_saves>=10 then 'completed' else 'active' end),
    (v_uid,v_artist_id,'system_referrals_5','Convert 5 referrals',5,v_referrals,'referrals',now()+interval '30 days',case when v_referrals>=5 then 'completed' else 'active' end),
    (v_uid,v_artist_id,'system_clicks_25','Get 25 smart-link clicks',25,v_clicks,'clicks',now()+interval '30 days',case when v_clicks>=25 then 'completed' else 'active' end)
  on conflict(owner_user_id,goal_type) where goal_type like 'system_%'
  do update set
    artist_id=excluded.artist_id,
    current_value=excluded.current_value,
    status=case when excluded.current_value>=public.tgg_creator_goals.target_value then 'completed' else public.tgg_creator_goals.status end,
    updated_at=now();

  select count(*) into v_completed_now
  from public.tgg_creator_goals
  where owner_user_id=v_uid and goal_type like 'system_%' and status='completed';

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-GOALS-1.0',
    'completed_count',v_completed_now,
    'goals',(select coalesce(jsonb_agg(jsonb_build_object(
      'id',id,'goal_type',goal_type,'title',title,'target_value',target_value,
      'current_value',current_value,'unit',unit,'deadline',deadline,'status',status
    ) order by created_at),'[]'::jsonb)
      from public.tgg_creator_goals
      where owner_user_id=v_uid and goal_type like 'system_%'),
    'generated_at',now()
  );
end
$function$


-- [40000000884] function public.tgg_growth_launch_feed(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_growth_launch_feed(p_limit integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_limit integer:=greatest(1,least(coalesce(p_limit,24),50));
  v_items jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(x) order by x.rank_score desc,x.release_date desc nulls last,x.created_at desc),'[]'::jsonb)
  into v_items
  from (
    select
      m.id as release_id,
      m.artist_id,
      a.stage_name,
      m.title,
      m.genre,
      m.description,
      m.cover_url,
      m.slug,
      m.release_date,
      m.created_at,
      coalesce(m.featured,false) as featured,
      coalesce(m.play_count,0) as play_count,
      coalesce(m.download_count,0) as download_count,
      (
        (case when coalesce(m.featured,false) then 1000 else 0 end)
        + least(coalesce(m.play_count,0),100000)
        + (least(coalesce(m.download_count,0),10000)*3)
        + greatest(0,120 - floor(extract(epoch from (now()-coalesce(m.release_date,m.created_at)))/86400))::bigint
      )::bigint as rank_score
    from public.mixtapes m
    join public.artists a on a.id=m.artist_id
    where m.status='published'
    order by
      (case when coalesce(m.featured,false) then 1000 else 0 end)
      + least(coalesce(m.play_count,0),100000)
      + (least(coalesce(m.download_count,0),10000)*3)
      + greatest(0,120 - floor(extract(epoch from (now()-coalesce(m.release_date,m.created_at)))/86400)) desc,
      m.release_date desc nulls last,
      m.created_at desc
    limit v_limit
  ) x;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-LAUNCH-FEED-1.0',
    'items',v_items,
    'count',jsonb_array_length(v_items),
    'generated_at',now()
  );
end
$function$


