-- [40000000886] function public.tgg_growth_opportunity_inbox()
CREATE OR REPLACE FUNCTION public.tgg_growth_opportunity_inbox()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_brain jsonb;
  v_forecast jsonb;
  v_revenue jsonb;
  v_collab jsonb;
  v_reactivation jsonb;
  v_items jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  v_brain:=public.tgg_growth_brain_latest();
  v_forecast:=public.tgg_growth_forecast();
  v_revenue:=public.tgg_growth_revenue_bridge();
  v_collab:=public.tgg_growth_collab_network();
  v_reactivation:=public.tgg_growth_reactivation_summary();

  with candidates as (
    select *
    from (values
      (
        'brain_top_action',
        coalesce(v_brain->'top_action'->>'title',''),
        coalesce(v_brain->'top_action'->>'rationale',''),
        coalesce((v_brain->'top_action'->>'confidence')::int,90),
        'growth',
        coalesce(v_brain->'top_action'->>'key','')
      ),
      (
        'weekly_pacing',
        case when v_forecast->>'pace'='behind' then 'Get this week back on pace' else 'Protect this week’s momentum' end,
        case when v_forecast->>'pace'='behind'
          then 'Weekly mission progress is behind the expected pace. Complete the next measurable mission before adding more work.'
          else 'Weekly mission pacing is healthy. Finish the next incomplete mission and preserve the streak.'
        end,
        case when v_forecast->>'pace'='behind' then 93 else 70 end,
        'weekly',
        coalesce(v_forecast->'next_best_action'->>'action_type','weekly_mission')
      ),
      (
        'revenue_next_action',
        coalesce(v_revenue->'next_actions'->0->>'title',''),
        coalesce(v_revenue->'next_actions'->0->>'rationale',''),
        coalesce((v_revenue->'next_actions'->0->>'priority')::int,0),
        'revenue',
        coalesce(v_revenue->'next_actions'->0->>'key','')
      ),
      (
        'collab_network',
        case when coalesce((v_collab->>'candidate_count')::int,0)=0
          then 'Recruit your first collaboration partner'
          else 'Act on a collaboration match'
        end,
        case when coalesce((v_collab->>'candidate_count')::int,0)=0
          then coalesce(v_collab->'recruit_creator'->>'message','Invite another creator into your network.')
          else 'Review your collaboration candidates and start a project with the strongest fit.'
        end,
        case when coalesce((v_collab->>'candidate_count')::int,0)=0 then 82 else 89 end,
        'collaboration',
        case when coalesce((v_collab->>'candidate_count')::int,0)=0 then 'recruit_creator' else 'review_collab_matches' end
      ),
      (
        'reactivation',
        coalesce(v_reactivation->>'recommended_play',''),
        coalesce(v_reactivation->>'reason',''),
        case coalesce(v_reactivation->>'priority','')
          when 'audience_building' then 80
          when 'urgent_reactivation' then 95
          when 'reactivation' then 90
          else 72
        end,
        'audience',
        coalesce(v_reactivation->>'priority','audience')
      )
    ) as x(source_key,title,rationale,priority,category,action_key)
    where nullif(btrim(title),'') is not null
  ),
  deduped as (
    select distinct on (action_key)
      source_key,title,rationale,priority,category,action_key
    from candidates
    where nullif(btrim(action_key),'') is not null
    order by action_key,priority desc
  ),
  ranked as (
    select *,row_number() over(order by priority desc,title) as rank
    from deduped
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'rank',rank,
    'source_key',source_key,
    'category',category,
    'action_key',action_key,
    'title',title,
    'rationale',rationale,
    'priority',priority
  ) order by rank),'[]'::jsonb)
  into v_items
  from ranked
  where rank<=5;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-OPPORTUNITY-INBOX-1.0',
    'items',v_items,
    'count',jsonb_array_length(v_items),
    'generated_at',now()
  );
end
$function$


-- [40000000887] function public.tgg_growth_promo_kit()
CREATE OR REPLACE FUNCTION public.tgg_growth_promo_kit()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist public.artists;
  v_release public.mixtapes;
  v_ref jsonb;
  v_url text;
  v_ref_code text;
  v_hashtag text;
  v_items jsonb;
  v_saves bigint:=0;
  v_reactions bigint:=0;
  v_comments bigint:=0;
  v_followers bigint:=0;
  v_plays bigint:=0;
  v_downloads bigint:=0;
  v_proof_parts text[]:=array[]::text[];
  v_proof text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select * into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist.id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-PROMO-KIT-1.1',
      'has_artist_profile',false,'items','[]'::jsonb,'generated_at',now()
    );
  end if;

  select * into v_release
  from public.mixtapes
  where artist_id=v_artist.id and status='published'
  order by coalesce(featured,false) desc,
           (coalesce(play_count,0)+(coalesce(download_count,0)*3)) desc,
           created_at desc
  limit 1;

  if v_release.id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-PROMO-KIT-1.1',
      'has_artist_profile',true,'has_release',false,
      'items','[]'::jsonb,'generated_at',now()
    );
  end if;

  v_ref:=public.tgg_referral_code();
  v_ref_code:=coalesce(v_ref->>'code','');
  v_url:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-shell?view=release&slug='||v_release.slug;
  v_hashtag:='#'||regexp_replace(coalesce(v_artist.stage_name,'Artist'),'[^A-Za-z0-9]','','g');

  v_plays:=coalesce(v_release.play_count,0);
  v_downloads:=coalesce(v_release.download_count,0);

  select count(*) into v_saves from public.release_saves where mixtape_id=v_release.id;
  select count(*) into v_reactions from public.release_reactions where mixtape_id=v_release.id;
  select count(*) into v_comments from public.release_comments where mixtape_id=v_release.id and coalesce(hidden_by_creator,false)=false;
  select count(*) into v_followers from public.artist_follows where artist_id=v_artist.id;

  if v_plays>0 then v_proof_parts:=array_append(v_proof_parts,v_plays||' play'||case when v_plays=1 then '' else 's' end); end if;
  if v_saves>0 then v_proof_parts:=array_append(v_proof_parts,v_saves||' save'||case when v_saves=1 then '' else 's' end); end if;
  if v_reactions>0 then v_proof_parts:=array_append(v_proof_parts,v_reactions||' reaction'||case when v_reactions=1 then '' else 's' end); end if;
  if v_comments>0 then v_proof_parts:=array_append(v_proof_parts,v_comments||' comment'||case when v_comments=1 then '' else 's' end); end if;
  if v_downloads>0 then v_proof_parts:=array_append(v_proof_parts,v_downloads||' download'||case when v_downloads=1 then '' else 's' end); end if;
  if v_followers>0 then v_proof_parts:=array_append(v_proof_parts,v_followers||' follower'||case when v_followers=1 then '' else 's' end); end if;

  v_items:=jsonb_build_array(
    jsonb_build_object(
      'key','social_post','label','Social Post',
      'copy','New drop: "'||v_release.title||'" by '||v_artist.stage_name||'. Tap in, run it up, and tell me your favorite track. '||v_url||' '||v_hashtag||' #NewMusic #TruGoGetta'
    ),
    jsonb_build_object(
      'key','story','label','Story',
      'copy','"'||v_release.title||'" is out now. Tap in and listen: '||v_url
    ),
    jsonb_build_object(
      'key','short','label','Short / Reel',
      'copy','POV: you just found your next rotation. "'||v_release.title||'" — '||v_artist.stage_name||'. Listen now: '||v_url
    ),
    jsonb_build_object(
      'key','dm','label','DM',
      'copy','Yo, I just dropped "'||v_release.title||'". Check it when you get a minute and let me know what you think: '||v_url
    ),
    jsonb_build_object(
      'key','save_cta','label','Save CTA',
      'copy','If "'||v_release.title||'" is hitting, save it so you can come back to it. '||v_url
    ),
    jsonb_build_object(
      'key','referral_cross_promo','label','Referral Cross-Promo',
      'copy','Listen to "'||v_release.title||'" here: '||v_url||'. If you make music or support independent artists, join TRU GO GETTA with code '||v_ref_code||'.'
    )
  );

  if coalesce(array_length(v_proof_parts,1),0)>0 then
    v_proof:=array_to_string(v_proof_parts,', ');
    v_items:=v_items||jsonb_build_array(
      jsonb_build_object(
        'key','social_proof',
        'label','Real Social Proof',
        'copy','"'||v_release.title||'" is building real momentum: '||v_proof||'. Tap in and see what people are checking out: '||v_url,
        'source','live_platform_counts',
        'fabricated',false
      )
    );
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-PROMO-KIT-1.1',
    'artist',jsonb_build_object('artist_id',v_artist.id,'stage_name',v_artist.stage_name),
    'release',jsonb_build_object(
      'release_id',v_release.id,'title',v_release.title,'genre',v_release.genre,
      'slug',v_release.slug,'cover_url',v_release.cover_url,'url',v_url
    ),
    'social_proof',jsonb_build_object(
      'available',coalesce(array_length(v_proof_parts,1),0)>0,
      'plays',v_plays,
      'saves',v_saves,
      'reactions',v_reactions,
      'comments',v_comments,
      'downloads',v_downloads,
      'followers',v_followers,
      'fabricated',false
    ),
    'items',v_items,
    'generated_at',now()
  );
end
$function$


-- [40000000888] function public.tgg_growth_reactivation_summary()
CREATE OR REPLACE FUNCTION public.tgg_growth_reactivation_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_total bigint:=0;
  v_new bigint:=0;
  v_active bigint:=0;
  v_superfans bigint:=0;
  v_supporters bigint:=0;
  v_slipping bigint:=0;
  v_dormant bigint:=0;
  v_avg_eng numeric:=0;
  v_avg_rec numeric:=0;
  v_avg_loyalty numeric:=0;
  v_priority text;
  v_play text;
  v_reason text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-REACTIVATION-1.1',
      'has_artist_profile',false,'generated_at',now()
    );
  end if;

  select
    coalesce(total_fans,0),coalesce(new_fans,0),coalesce(active_fans,0),
    coalesce(superfans,0),coalesce(supporters,0),coalesce(slipping_fans,0),
    coalesce(dormant_fans,0),coalesce(avg_engagement_score,0),
    coalesce(avg_recency_score,0),coalesce(avg_loyalty_score,0)
  into
    v_total,v_new,v_active,v_superfans,v_supporters,v_slipping,
    v_dormant,v_avg_eng,v_avg_rec,v_avg_loyalty
  from public.tgg_creator_fan_intelligence_summary
  where creator_user_id=v_uid and artist_id=v_artist_id
  limit 1;

  if not found then
    v_new:=0;v_active:=0;v_superfans:=0;v_supporters:=0;
    v_slipping:=0;v_dormant:=0;v_avg_eng:=0;v_avg_rec:=0;v_avg_loyalty:=0;
    select count(*) into v_total
    from public.tgg_fan_crm
    where creator_user_id=v_uid and artist_id=v_artist_id and segment<>'unfollowed';
  end if;

  if v_total=0 then
    v_priority:='audience_building';
    v_play:='Acquire your first engaged fans';
    v_reason:='There is no audience history to reactivate yet. Focus on follows, saves, referrals, and measured shares first.';
  elsif (v_slipping+v_dormant)>0 then
    v_priority:='win_back';
    v_play:='Run a win-back push';
    v_reason:=(v_slipping+v_dormant)::text||' fan'||case when (v_slipping+v_dormant)=1 then '' else 's' end||' are slipping or dormant.';
  elsif v_active>0 or v_superfans>0 or v_supporters>0 then
    v_priority:='retain';
    v_play:='Protect active momentum';
    v_reason:='Your audience is currently active. Reward engaged fans before they cool off.';
  else
    v_priority:='nurture';
    v_play:='Nurture recent fans';
    v_reason:='You have audience records but not enough recent engagement to classify a win-back segment.';
  end if;

  return jsonb_build_object(
    'ok',true,'version','GROWTH-REACTIVATION-1.1','has_artist_profile',true,
    'artist_id',v_artist_id,
    'audience',jsonb_build_object(
      'total_fans',v_total,'new_fans',v_new,'active_fans',v_active,
      'superfans',v_superfans,'supporters',v_supporters,
      'slipping_fans',v_slipping,'dormant_fans',v_dormant,
      'at_risk_fans',v_slipping+v_dormant
    ),
    'scores',jsonb_build_object(
      'avg_engagement',v_avg_eng,'avg_recency',v_avg_rec,'avg_loyalty',v_avg_loyalty
    ),
    'priority',v_priority,'recommended_play',v_play,'reason',v_reason,
    'privacy',jsonb_build_object('aggregate_only',true,'fan_ids_exposed',false,'emails_exposed',false),
    'generated_at',now()
  );
end
$function$


-- [40000000889] function public.tgg_growth_record_activity(p_action text, p_context jsonb)
