-- [40000000890] function public.tgg_growth_release_launch_overview()
CREATE OR REPLACE FUNCTION public.tgg_growth_release_launch_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-RELEASE-LAUNCH-OVERVIEW-1.0',
    'campaigns',(
      select coalesce(jsonb_agg(jsonb_build_object(
        'campaign_id',c.id,
        'title',c.title,
        'status',c.status,
        'starts_at',c.starts_at,
        'ends_at',c.ends_at,
        'release_id',c.metadata->>'release_id',
        'release_title',c.metadata->>'release_title',
        'release_date',c.metadata->>'release_date',
        'task_count',(select count(*) from public.tgg_campaign_tasks t where t.campaign_id=c.id and t.owner_user_id=v_uid),
        'completed_count',(select count(*) from public.tgg_campaign_tasks t where t.campaign_id=c.id and t.owner_user_id=v_uid and t.status='completed'),
        'open_count',(select count(*) from public.tgg_campaign_tasks t where t.campaign_id=c.id and t.owner_user_id=v_uid and t.status<>'completed')
      ) order by c.starts_at desc),'[]'::jsonb)
      from public.tgg_campaigns c
      where c.owner_user_id=v_uid
        and c.campaign_type='release_launch_sequence'
    ),
    'tasks',(
      select coalesce(jsonb_agg(jsonb_build_object(
        'id',t.id,
        'campaign_id',t.campaign_id,
        'title',t.title,
        'due_at',t.due_at,
        'status',t.status,
        'task_key',t.metadata->>'launch_task_key',
        'description',t.metadata->>'description',
        'release_id',t.metadata->>'release_id',
        'release_title',t.metadata->>'release_title',
        'calendar_source','release_launch'
      ) order by t.due_at,t.created_at),'[]'::jsonb)
      from public.tgg_campaign_tasks t
      join public.tgg_campaigns c on c.id=t.campaign_id
      where t.owner_user_id=v_uid
        and c.owner_user_id=v_uid
        and c.campaign_type='release_launch_sequence'
        and t.due_at>=now()-interval '30 days'
        and t.due_at<=now()+interval '45 days'
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000891] function public.tgg_growth_release_launch_sequence(p_release_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_growth_release_launch_sequence(p_release_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_release public.mixtapes;
  v_campaign_id uuid;
  v_anchor timestamptz;
  v_task record;
  v_created integer:=0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select m.* into v_release
  from public.mixtapes m
  join public.artists a on a.id=m.artist_id
  where m.id=p_release_id
    and a.user_id=v_uid
  limit 1;

  if v_release.id is null then
    raise exception 'RELEASE_NOT_FOUND_OR_NOT_OWNED' using errcode='P0002';
  end if;

  if v_release.release_date is null then
    return jsonb_build_object(
      'ok',false,
      'version','GROWTH-RELEASE-LAUNCH-SEQUENCE-1.0',
      'reason','release_date_required',
      'release_id',v_release.id,
      'release_title',v_release.title
    );
  end if;

  v_anchor:=v_release.release_date;

  select id into v_campaign_id
  from public.tgg_campaigns
  where owner_user_id=v_uid
    and campaign_type='release_launch_sequence'
    and metadata->>'release_id'=v_release.id::text
  order by created_at
  limit 1;

  if v_campaign_id is null then
    insert into public.tgg_campaigns(
      owner_user_id,artist_id,title,campaign_type,status,
      starts_at,ends_at,objective,target_value,current_value,metadata
    )
    values(
      v_uid,
      v_release.artist_id,
      'Release Launch · '||v_release.title,
      'release_launch_sequence',
      case when v_anchor+interval '8 days'<now() then 'completed_window' else 'active' end,
      v_anchor-interval '14 days',
      v_anchor+interval '8 days',
      'Run the pre-launch, launch-day, and post-launch sequence for "'||v_release.title||'".',
      8,
      0,
      jsonb_build_object(
        'release_id',v_release.id,
        'release_title',v_release.title,
        'release_date',v_release.release_date,
        'sequence_version','GROWTH-RELEASE-LAUNCH-SEQUENCE-1.0'
      )
    )
    returning id into v_campaign_id;
  end if;

  for v_task in
    select * from (values
      ('prep_assets','Prep launch assets','Finalize cover, release copy, share links, and launch CTA.',-14),
      ('announce_release','Announce the release','Publish the first release announcement and point fans to the artist/release link.',-7),
      ('teaser_push','Run the teaser push','Share a teaser, Story, Short, or behind-the-scenes preview.',-3),
      ('countdown_push','Start the countdown','Post the final countdown and send direct outreach to likely listeners.',-1),
      ('launch_day','Launch day push','Publish the release-day post, share the release link, and ask for a follow/save.',0),
      ('day_one_followup','Day-one follow-up','Re-share the release with a different angle and respond to early engagement.',1),
      ('social_proof_push','Use early social proof','Highlight any real plays, saves, comments, reactions, or follower growth.',3),
      ('week_one_review','Review week-one performance','Review Growth Wins, attribution, and audience signals, then repeat the strongest channel.',7)
    ) as x(task_key,title,description,day_offset)
  loop
    if not exists(
      select 1
      from public.tgg_campaign_tasks
      where campaign_id=v_campaign_id
        and owner_user_id=v_uid
        and metadata->>'launch_task_key'=v_task.task_key
    ) then
      insert into public.tgg_campaign_tasks(
        campaign_id,owner_user_id,task_type,title,due_at,status,metadata
      )
      values(
        v_campaign_id,
        v_uid,
        'release_launch_sequence',
        v_task.title,
        v_anchor + make_interval(days=>v_task.day_offset),
        case when v_anchor + make_interval(days=>v_task.day_offset) < now()-interval '24 hours' then 'overdue' else 'todo' end,
        jsonb_build_object(
          'launch_task_key',v_task.task_key,
          'description',v_task.description,
          'release_id',v_release.id,
          'release_title',v_release.title,
          'day_offset',v_task.day_offset
        )
      );
      v_created:=v_created+1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-RELEASE-LAUNCH-SEQUENCE-1.0',
    'campaign_id',v_campaign_id,
    'release',jsonb_build_object(
      'release_id',v_release.id,
      'title',v_release.title,
      'release_date',v_release.release_date
    ),
    'created_tasks',v_created,
    'task_count',(select count(*) from public.tgg_campaign_tasks where campaign_id=v_campaign_id and owner_user_id=v_uid),
    'tasks',(select coalesce(jsonb_agg(jsonb_build_object(
      'id',t.id,
      'title',t.title,
      'due_at',t.due_at,
      'status',t.status,
      'description',t.metadata->>'description',
      'task_key',t.metadata->>'launch_task_key'
    ) order by t.due_at,t.created_at),'[]'::jsonb)
      from public.tgg_campaign_tasks t
      where t.campaign_id=v_campaign_id and t.owner_user_id=v_uid),
    'generated_at',now()
  );
end
$function$


-- [40000000892] function public.tgg_growth_revenue_bridge()
CREATE OR REPLACE FUNCTION public.tgg_growth_revenue_bridge()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_growth jsonb;
  v_rev jsonb;
  v_supporters jsonb;
  v_followers bigint:=0;
  v_referrals bigint:=0;
  v_saves bigint:=0;
  v_clicks bigint:=0;
  v_active_members bigint:=0;
  v_paid_tx bigint:=0;
  v_revenue_cents bigint:=0;
  v_active_tiers integer:=0;
  v_joinable boolean:=false;
  v_stage text;
  v_actions jsonb:='[]'::jsonb;
  v_next_threshold bigint:=1;
  v_next_label text:='First revenue';
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object('ok',true,'version','GROWTH-REVENUE-BRIDGE-1.1','has_artist_profile',false,'generated_at',now());
  end if;

  v_growth:=public.tgg_growth_acquisition_metrics();
  v_rev:=public.tgg_creator_revenue_summary(30);
  v_supporters:=public.tgg_creator_supporters_bundle();

  v_followers:=coalesce((v_growth->>'followers')::bigint,0);
  v_referrals:=coalesce((v_growth->>'referral_conversions')::bigint,0);
  select count(*) into v_saves
  from public.release_saves rs
  join public.mixtapes m on m.id=rs.mixtape_id
  where m.artist_id=v_artist_id and m.status='published';
  v_clicks:=coalesce((v_growth->>'smart_link_clicks')::bigint,0);

  v_active_members:=coalesce((v_supporters#>>'{counts,active_memberships}')::bigint,0);
  v_active_tiers:=coalesce((v_supporters#>>'{counts,active_tiers}')::integer,0);
  v_joinable:=coalesce((v_supporters#>>'{checkout,can_accept_memberships}')::boolean,false);
  v_paid_tx:=coalesce((v_rev->>'paid_transactions')::bigint,0);
  v_revenue_cents:=round(coalesce((v_rev->>'revenue')::numeric,0)*100)::bigint;

  if v_revenue_cents<1 then v_next_threshold:=1; v_next_label:='First revenue';
  elsif v_revenue_cents<10000 then v_next_threshold:=10000; v_next_label:='100 revenue';
  elsif v_revenue_cents<100000 then v_next_threshold:=100000; v_next_label:='1000 revenue';
  else v_next_threshold:=1000000; v_next_label:='10000 revenue';
  end if;

  v_stage:=case
    when not v_joinable then 'monetization_setup'
    when v_followers=0 and v_referrals=0 and v_saves=0 and v_clicks=0 then 'build_audience'
    when v_paid_tx=0 and v_active_members=0 then 'convert_audience'
    when v_revenue_cents=0 then 'first_revenue'
    else 'optimize_revenue'
  end;

  if not v_joinable then
    v_actions:=v_actions||jsonb_build_array(jsonb_build_object('key','finish_membership_checkout','priority',100,'title','Finish membership checkout','rationale','Monetization cannot convert until at least one membership offer is joinable.'));
  end if;
  if v_joinable and v_active_members=0 then
    v_actions:=v_actions||jsonb_build_array(jsonb_build_object('key','promote_membership','priority',92,'title','Promote your Backstage membership','rationale','Membership checkout is ready but there are no active supporters yet. Add the membership CTA to your strongest release and artist-profile shares.'));
  end if;
  if v_joinable and v_clicks=0 then
    v_actions:=v_actions||jsonb_build_array(jsonb_build_object('key','drive_measured_clicks','priority',88,'title','Drive measured clicks before optimizing offers','rationale','Use smart links so Growth can compare audience traffic with monetization outcomes.'));
  end if;
  if v_joinable and v_followers=0 then
    v_actions:=v_actions||jsonb_build_array(jsonb_build_object('key','grow_followers_before_upsell','priority',84,'title','Build your follower base','rationale','A larger warm audience gives memberships and merch more people to convert.'));
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-REVENUE-BRIDGE-1.1',
    'artist_id',v_artist_id,
    'stage',v_stage,
    'monetization_ready',v_joinable,
    'active_membership_tiers',v_active_tiers,
    'active_supporters',v_active_members,
    'paid_transactions_30d',v_paid_tx,
    'revenue_30d_cents',v_revenue_cents,
    'currency',coalesce(v_rev->>'currency','USD'),
    'audience_signals',jsonb_build_object('followers',v_followers,'referral_conversions',v_referrals,'release_saves',v_saves,'smart_link_clicks',v_clicks),
    'conversion_rates',jsonb_build_object(
      'supporters_per_follower_pct',case when v_followers>0 then round((v_active_members::numeric/v_followers::numeric)*100,2) else null end,
      'paid_tx_per_click_pct',case when v_clicks>0 then round((v_paid_tx::numeric/v_clicks::numeric)*100,2) else null end
    ),
    'milestone_progress',jsonb_build_object(
      'first_supporter_unlocked',v_active_members>0,
      'first_revenue_unlocked',v_revenue_cents>0,
      'revenue_100_unlocked',v_revenue_cents>=10000,
      'revenue_1000_unlocked',v_revenue_cents>=100000,
      'next_threshold_cents',v_next_threshold,
      'next_label',v_next_label,
      'progress_pct',case when v_next_threshold>0 then least(100,round((v_revenue_cents::numeric/v_next_threshold::numeric)*100,1)) else 0 end
    ),
    'interpretation','Directional conversion ratios only; campaign attribution is required before claiming a specific growth action caused revenue.',
    'next_actions',v_actions,
    'generated_at',now()
  );
end
$function$


-- [40000000893] function public.tgg_growth_scorecard()
CREATE OR REPLACE FUNCTION public.tgg_growth_scorecard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_wins jsonb;
  v_metrics jsonb;
  v_weekly jsonb;
  v_forecast jsonb;
  v_audience jsonb;
  v_w7 jsonb;
  v_w30 jsonb;
  v_missions jsonb;
  v_followers bigint:=0;
  v_referrals bigint:=0;
  v_clicks30 bigint:=0;
  v_plays bigint:=0;
  v_downloads bigint:=0;
  v_weekly_progress numeric:=0;
  v_momentum7 bigint:=0;
  v_momentum30 bigint:=0;
  v_score integer:=0;
  v_stage text;
  v_grade text;
  v_dimensions jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-SCORECARD-1.0',
      'has_artist_profile',false,'generated_at',now()
    );
  end if;

  v_wins:=public.tgg_growth_wins_summary();
  v_metrics:=public.tgg_growth_acquisition_metrics();
  v_weekly:=public.tgg_growth_weekly_refresh();
  v_forecast:=public.tgg_growth_forecast();
  v_audience:=public.tgg_growth_audience_intelligence();

  v_w7:=coalesce(v_wins->'last_7_days','{}'::jsonb);
  v_w30:=coalesce(v_wins->'last_30_days','{}'::jsonb);
  v_missions:=coalesce(v_weekly->'missions','[]'::jsonb);

  v_followers:=coalesce((v_metrics->>'followers')::bigint,0);
  v_referrals:=coalesce((v_metrics->>'referral_conversions')::bigint,0);
  v_clicks30:=coalesce((v_metrics->>'smart_link_clicks_30d')::bigint,0);
  v_plays:=coalesce((v_metrics->>'release_plays')::bigint,0);
  v_downloads:=coalesce((v_metrics->>'release_downloads')::bigint,0);
  v_momentum7:=coalesce((v_w7->>'momentum_score')::bigint,0);
  v_momentum30:=coalesce((v_w30->>'momentum_score')::bigint,0);
  v_weekly_progress:=coalesce((v_forecast->>'overall_progress_pct')::numeric,0);

  v_score :=
    least(25,round(v_weekly_progress/4.0)::int)
    + least(20,case when v_followers=0 then 0 else 8+least(v_followers,12)::int end)
    + least(15,case when v_referrals=0 then 0 else 8+least(v_referrals,7)::int end)
    + least(15,case when v_clicks30=0 then 0 else 5+least(v_clicks30,10)::int end)
    + least(15,case when v_plays+v_downloads=0 then 0 else 5+least(v_plays+v_downloads,10)::int end)
    + least(10,case when v_momentum30=0 then 0 else greatest(1,least(10,ceil(v_momentum7::numeric/nullif(v_momentum30,0)*40)::int)) end);

  v_stage:=case
    when v_score>=80 then 'scaling'
    when v_score>=60 then 'growing'
    when v_score>=35 then 'building'
    else 'starting'
  end;

  v_grade:=case
    when v_score>=90 then 'A'
    when v_score>=80 then 'A-'
    when v_score>=70 then 'B'
    when v_score>=60 then 'B-'
    when v_score>=50 then 'C'
    when v_score>=35 then 'C-'
    else 'D'
  end;

  v_dimensions:=jsonb_build_array(
    jsonb_build_object(
      'key','execution','label','Weekly Execution','score',least(100,round(v_weekly_progress)::int),
      'status',coalesce(v_forecast->>'pace','not_started')
    ),
    jsonb_build_object(
      'key','audience','label','Audience','score',least(100,(v_followers*8+v_referrals*12)::int),
      'status',case when v_followers+v_referrals=0 then 'needs_first_conversion' else 'active' end
    ),
    jsonb_build_object(
      'key','traffic','label','Traffic','score',least(100,(v_clicks30*10)::int),
      'status',case when v_clicks30=0 then 'needs_clicks' else 'active' end
    ),
    jsonb_build_object(
      'key','content_response','label','Content Response','score',least(100,((v_plays+v_downloads)*8)::int),
      'status',case when v_plays+v_downloads=0 then 'needs_response' else 'active' end
    ),
    jsonb_build_object(
      'key','momentum','label','Momentum','score',
        case when v_momentum30=0 then 0 else least(100,round(v_momentum7::numeric/nullif(v_momentum30,0)*400)::int) end,
      'status',coalesce(v_wins->>'trend','starting')
    )
  );

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-SCORECARD-1.0',
    'artist_id',v_artist_id,
    'score',v_score,
    'grade',v_grade,
    'stage',v_stage,
    'dimensions',v_dimensions,
    'benchmarks',jsonb_build_object(
      'weekly_progress_pct',v_weekly_progress,
      'followers',v_followers,
      'referrals',v_referrals,
      'smart_link_clicks_30d',v_clicks30,
      'release_plays',v_plays,
      'release_downloads',v_downloads,
      'momentum_7d',v_momentum7,
      'momentum_30d',v_momentum30
    ),
    'privacy',jsonb_build_object(
      'personal_baseline_only',true,
      'peer_creator_data_used',false
    ),
    'generated_at',now()
  );
end
$function$


-- [40000000894] function public.tgg_growth_shadow_state()
CREATE OR REPLACE FUNCTION public.tgg_growth_shadow_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_ready_map jsonb:='{}'::jsonb;
  v_ready_keys jsonb:='[]'::jsonb;
  v_open_actions jsonb:='[]'::jsonb;
  v_weekly jsonb:='[]'::jsonb;
  v_next_action jsonb;
  v_next_mission jsonb;
  v_next_focus jsonb;
  v_ready_count integer:=0;
  v_open_count integer:=0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  v_ready_map:=private.tgg_growth_shadow_ready_flags();

  select
    coalesce(jsonb_agg(key order by key),'[]'::jsonb),
    count(*)
  into v_ready_keys,v_ready_count
  from jsonb_each(v_ready_map);

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id',q.id,
      'action_type',q.action_type,
      'title',q.title,
      'rationale',q.rationale,
      'priority',q.priority,
      'due_at',q.due_at
    ) order by q.priority desc,q.due_at nulls last,q.created_at),'[]'::jsonb),
    count(*)
  into v_open_actions,v_open_count
  from public.tgg_creator_action_queue q
  where q.owner_user_id=v_uid
    and q.source_type='growth'
    and q.status='open';

  select coalesce(jsonb_agg(jsonb_build_object(
    'mission_key',m.mission_key,
    'title',m.title,
    'current_value',m.current_value,
    'target_value',m.target_value,
    'status',m.status
  ) order by
    case when m.status='active' then 0 else 1 end,
    (m.target_value-m.current_value) asc,
    m.created_at),'[]'::jsonb)
  into v_weekly
  from public.tgg_creator_weekly_missions m
  where m.owner_user_id=v_uid
    and m.week_start=date_trunc('week',now())::date;

  select jsonb_build_object(
    'kind','coach_action',
    'key',q.action_type,
    'title',q.title,
    'reason',q.rationale,
    'priority',q.priority,
    'due_at',q.due_at
  )
  into v_next_action
  from public.tgg_creator_action_queue q
  where q.owner_user_id=v_uid
    and q.source_type='growth'
    and q.status='open'
  order by q.priority desc,q.due_at nulls last,q.created_at
  limit 1;

  select jsonb_build_object(
    'kind','weekly_mission',
    'key',m.mission_key,
    'title',m.title,
    'reason','Weekly mission still needs progress.',
    'current_value',m.current_value,
    'target_value',m.target_value
  )
  into v_next_mission
  from public.tgg_creator_weekly_missions m
  where m.owner_user_id=v_uid
    and m.week_start=date_trunc('week',now())::date
    and m.status='active'
  order by
    (m.target_value-m.current_value) asc,
    m.created_at
  limit 1;

  v_next_focus:=coalesce(
    v_next_action,
    v_next_mission,
    jsonb_build_object(
      'kind','maintain_growth',
      'key','keep_momentum',
      'title','Keep momentum moving',
      'reason','All current Growth Coach actions and weekly missions are complete.'
    )
  );

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-SHADOW-1.1',
    'mode','follow_live_state_skip_completed',
    'artist_id',v_artist_id,
    'completed_growth_layer_count',v_ready_count,
    'completed_growth_layers',v_ready_keys,
    'open_growth_action_count',v_open_count,
    'open_growth_actions',v_open_actions,
    'weekly_missions',v_weekly,
    'next_focus',v_next_focus,
    'rule','Never rebuild a Growth layer already marked ready; follow the highest-priority live unfinished action, then weekly mission progress.',
    'generated_at',now()
  );
end
$function$


-- [40000000895] function public.tgg_growth_social_schedule_refresh(p_timezone text)
CREATE OR REPLACE FUNCTION public.tgg_growth_social_schedule_refresh(p_timezone text DEFAULT 'UTC'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_tz text:=coalesce(nullif(btrim(p_timezone),''),'UTC');
  v_campaign public.tgg_campaigns;
  v_timing jsonb;
  v_promo jsonb;
  v_items jsonb;
  v_item jsonb;
  v_idx integer:=0;
  v_created integer:=0;
  v_date date;
  v_hour integer;
  v_due timestamptz;
  v_key text;
  v_channel text;
  v_copy text;
  v_title text;
  v_schedule jsonb:='[]'::jsonb;
  v_best_hour integer;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if not exists(select 1 from pg_catalog.pg_timezone_names where name=v_tz) then
    v_tz:='UTC';
  end if;

  select * into v_campaign
  from public.tgg_campaigns
  where owner_user_id=v_uid
    and status='active'
    and title like '7-Day Growth Sprint ·%'
  order by created_at desc
  limit 1;

  if v_campaign.id is null then
    perform public.tgg_growth_campaign_refresh();
    select * into v_campaign
    from public.tgg_campaigns
    where owner_user_id=v_uid
      and status='active'
      and title like '7-Day Growth Sprint ·%'
    order by created_at desc
    limit 1;
  end if;

  if v_campaign.id is null then
    return jsonb_build_object(
      'ok',false,'version','GROWTH-SOCIAL-SCHEDULE-1.0',
      'reason','growth_campaign_unavailable',
      'created_tasks',0,'schedule','[]'::jsonb
    );
  end if;

  v_timing:=public.tgg_growth_timing_intelligence(v_tz);
  v_promo:=public.tgg_growth_promo_kit();
  v_items:=coalesce(v_promo->'items','[]'::jsonb);

  if (v_timing->>'status')='ready' and (v_timing->'best_slot'->>'hour') is not null then
    v_best_hour:=(v_timing->'best_slot'->>'hour')::integer;
  end if;

  for v_item in
    select value from jsonb_array_elements(v_items)
    where value->>'key' in ('social_post','story','short','save_cta','referral_cross_promo')
    order by case value->>'key'
      when 'social_post' then 1
      when 'story' then 2
      when 'short' then 3
      when 'save_cta' then 4
      when 'referral_cross_promo' then 5
      else 99 end
  loop
    v_idx:=v_idx+1;
    v_date:=(timezone(v_tz,now())::date + v_idx);

    if v_best_hour is not null then
      v_hour:=v_best_hour;
    else
      v_hour:=case ((v_idx-1)%3)
        when 0 then 11
        when 1 then 15
        else 19
      end;
    end if;

    v_due:=make_timestamptz(
      extract(year from v_date)::int,
      extract(month from v_date)::int,
      extract(day from v_date)::int,
      v_hour,0,0,v_tz
    );

    if v_campaign.ends_at is not null and v_due>v_campaign.ends_at then
      v_due:=v_campaign.ends_at-interval '2 hours';
    end if;

    v_key:=to_char(v_date,'YYYY-MM-DD')||':'||(v_item->>'key');
    v_channel:=case v_item->>'key'
      when 'story' then 'story'
      when 'short' then 'short_reel'
      when 'social_post' then 'social_post'
      when 'save_cta' then 'social_post'
      when 'referral_cross_promo' then 'social_post'
      else 'social_post'
    end;
    v_copy:=coalesce(v_item->>'copy','');
    v_title:='Schedule · '||coalesce(v_item->>'label',initcap(replace(v_item->>'key','_',' ')));

    if not exists(
      select 1 from public.tgg_campaign_tasks t
      where t.owner_user_id=v_uid
        and t.campaign_id=v_campaign.id
        and t.task_type='growth_social_schedule'
        and t.metadata->>'schedule_key'=v_key
    ) then
      insert into public.tgg_campaign_tasks(
        campaign_id,owner_user_id,task_type,title,due_at,status,metadata
      )
      values(
        v_campaign.id,v_uid,'growth_social_schedule',v_title,v_due,'todo',
        jsonb_build_object(
          'schedule_key',v_key,
          'promo_key',v_item->>'key',
          'channel',v_channel,
          'copy',v_copy,
          'timezone',v_tz,
          'delivery_mode','manual_queue',
          'auto_publish_connected',false,
          'timing_status',v_timing->>'status',
          'timing_confidence',v_timing->>'confidence',
          'timing_event_count',coalesce((v_timing->>'event_count')::integer,0),
          'timing_source',case when v_best_hour is null then 'fallback_slots' else 'growth_timing_intelligence' end,
          'release_id',v_promo->'release'->>'release_id',
          'release_title',v_promo->'release'->>'title',
          'share_url',v_promo->'release'->>'url'
        )
      );
      v_created:=v_created+1;
    end if;

    v_schedule:=v_schedule||jsonb_build_array(jsonb_build_object(
      'schedule_key',v_key,
      'promo_key',v_item->>'key',
      'label',v_item->>'label',
      'channel',v_channel,
      'copy',v_copy,
      'due_at',v_due,
      'timezone',v_tz,
      'delivery_mode','manual_queue'
    ));
  end loop;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-SOCIAL-SCHEDULE-1.0',
    'campaign_id',v_campaign.id,
    'campaign_title',v_campaign.title,
    'timezone',v_tz,
    'timing',v_timing,
    'created_tasks',v_created,
    'schedule',v_schedule,
    'auto_publish_connected',false,
    'delivery_mode','manual_queue',
    'generated_at',now()
  );
end
$function$


-- [40000000896] function public.tgg_growth_timing_intelligence(p_timezone text)
CREATE OR REPLACE FUNCTION public.tgg_growth_timing_intelligence(p_timezone text DEFAULT 'UTC'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_tz text:=coalesce(nullif(btrim(p_timezone),''),'UTC');
  v_event_count bigint:=0;
  v_top_slots jsonb:='[]'::jsonb;
  v_best jsonb:=null;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if not exists(select 1 from pg_catalog.pg_timezone_names where name=v_tz) then
    v_tz:='UTC';
  end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object(
      'ok',true,
      'version','GROWTH-TIMING-1.0',
      'has_artist_profile',false,
      'timezone',v_tz,
      'status','profile_required',
      'event_count',0,
      'top_slots','[]'::jsonb,
      'generated_at',now()
    );
  end if;

  with events as (
    select af.created_at as occurred_at, 5::int as weight, 'follow'::text as event_type
    from public.artist_follows af
    where af.artist_id=v_artist_id

    union all
    select rs.created_at,4,'save'
    from public.release_saves rs
    join public.mixtapes m on m.id=rs.mixtape_id
    where m.artist_id=v_artist_id and m.status='published'

    union all
    select rr.created_at,2,'reaction'
    from public.release_reactions rr
    join public.mixtapes m on m.id=rr.mixtape_id
    where m.artist_id=v_artist_id and m.status='published'

    union all
    select rc.created_at,4,'comment'
    from public.release_comments rc
    join public.mixtapes m on m.id=rc.mixtape_id
    where m.artist_id=v_artist_id
      and m.status='published'
      and coalesce(rc.hidden_by_creator,false)=false

    union all
    select r.claimed_at,5,'referral'
    from public.tgg_referral_claims r
    where r.referrer_user_id=v_uid

    union all
    select e.occurred_at,1,'smart_link_click'
    from public.tgg_smart_link_events e
    join public.tgg_smart_links l on l.id=e.link_id
    where l.owner_user_id=v_uid
      and e.event_type='click'
  ),
  scored as (
    select
      extract(isodow from timezone(v_tz,occurred_at))::int as iso_day,
      extract(hour from timezone(v_tz,occurred_at))::int as hour_of_day,
      count(*)::bigint as events,
      sum(weight)::bigint as score
    from events
    where occurred_at>=now()-interval '90 days'
    group by 1,2
  ),
  ranked as (
    select iso_day,hour_of_day,events,score,
      row_number() over(order by score desc,events desc,iso_day,hour_of_day) as rn
    from scored
  )
  select
    (select count(*) from events where occurred_at>=now()-interval '90 days'),
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'iso_day',iso_day,
        'day_name',case iso_day
          when 1 then 'Monday' when 2 then 'Tuesday' when 3 then 'Wednesday'
          when 4 then 'Thursday' when 5 then 'Friday' when 6 then 'Saturday'
          when 7 then 'Sunday' end,
        'hour',hour_of_day,
        'label',to_char(make_time(hour_of_day,0,0),'HH12:MI AM'),
        'events',events,
        'score',score
      ) order by rn)
      from ranked where rn<=3
    ),'[]'::jsonb)
  into v_event_count,v_top_slots;

  if jsonb_array_length(v_top_slots)>0 then
    v_best:=v_top_slots->0;
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-TIMING-1.0',
    'has_artist_profile',true,
    'timezone',v_tz,
    'lookback_days',90,
    'event_count',v_event_count,
    'minimum_events_for_recommendation',5,
    'status',case when v_event_count>=5 then 'ready' else 'learning' end,
    'confidence',case
      when v_event_count>=50 then 'high'
      when v_event_count>=20 then 'medium'
      when v_event_count>=5 then 'low'
      else 'insufficient'
    end,
    'best_slot',case when v_event_count>=5 then v_best else null end,
    'top_slots',case when v_event_count>=5 then v_top_slots else '[]'::jsonb end,
    'data_note',case
      when v_event_count>=5 then 'Recommendations use only your real engagement activity from the last 90 days.'
      else 'More real engagement is needed before recommending a posting time.'
    end,
    'generated_at',now()
  );
end
$function$


