-- [40000000899] function public.tgg_growth_wins_summary()
CREATE OR REPLACE FUNCTION public.tgg_growth_wins_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  f7 bigint:=0; f30 bigint:=0;
  s7 bigint:=0; s30 bigint:=0;
  r7 bigint:=0; r30 bigint:=0;
  c7 bigint:=0; c30 bigint:=0;
  ref7 bigint:=0; ref30 bigint:=0;
  clk7 bigint:=0; clk30 bigint:=0;
  score7 bigint:=0; score30 bigint:=0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    return jsonb_build_object(
      'ok',true,'version','GROWTH-WINS-1.0','has_artist_profile',false,'generated_at',now()
    );
  end if;

  select
    count(*) filter(where af.created_at>=now()-interval '7 days'),
    count(*) filter(where af.created_at>=now()-interval '30 days')
  into f7,f30
  from public.artist_follows af
  where af.artist_id=v_artist_id;

  select
    count(*) filter(where rs.created_at>=now()-interval '7 days'),
    count(*) filter(where rs.created_at>=now()-interval '30 days')
  into s7,s30
  from public.release_saves rs
  join public.mixtapes m on m.id=rs.mixtape_id
  where m.artist_id=v_artist_id and m.status='published';

  select
    count(*) filter(where rr.created_at>=now()-interval '7 days'),
    count(*) filter(where rr.created_at>=now()-interval '30 days')
  into r7,r30
  from public.release_reactions rr
  join public.mixtapes m on m.id=rr.mixtape_id
  where m.artist_id=v_artist_id and m.status='published';

  select
    count(*) filter(where rc.created_at>=now()-interval '7 days'),
    count(*) filter(where rc.created_at>=now()-interval '30 days')
  into c7,c30
  from public.release_comments rc
  join public.mixtapes m on m.id=rc.mixtape_id
  where m.artist_id=v_artist_id and m.status='published'
    and coalesce(rc.hidden_by_creator,false)=false;

  select
    count(*) filter(where claimed_at>=now()-interval '7 days'),
    count(*) filter(where claimed_at>=now()-interval '30 days')
  into ref7,ref30
  from public.tgg_referral_claims
  where referrer_user_id=v_uid;

  select
    count(*) filter(where e.occurred_at>=now()-interval '7 days'),
    count(*) filter(where e.occurred_at>=now()-interval '30 days')
  into clk7,clk30
  from public.tgg_smart_link_events e
  join public.tgg_smart_links l on l.id=e.link_id
  where l.owner_user_id=v_uid and e.event_type='click';

  score7:=f7*8+s7*5+r7*3+c7*6+ref7*10+clk7;
  score30:=f30*8+s30*5+r30*3+c30*6+ref30*10+clk30;

  return jsonb_build_object(
    'ok',true,
    'version','GROWTH-WINS-1.0',
    'has_artist_profile',true,
    'last_7_days',jsonb_build_object(
      'new_followers',f7,
      'release_saves',s7,
      'reactions',r7,
      'comments',c7,
      'referrals',ref7,
      'smart_link_clicks',clk7,
      'momentum_score',score7
    ),
    'last_30_days',jsonb_build_object(
      'new_followers',f30,
      'release_saves',s30,
      'reactions',r30,
      'comments',c30,
      'referrals',ref30,
      'smart_link_clicks',clk30,
      'momentum_score',score30
    ),
    'trend',case
      when score30=0 then 'starting'
      when score7*4>score30 then 'accelerating'
      when score7*4=score30 then 'steady'
      else 'cooling'
    end,
    'generated_at',now()
  );
end
$function$


-- [40000000900] function public.tgg_insert_track(p_artist_id uuid, p_audio_url text, p_mixtape_id uuid, p_title text, p_track_number integer, p_youtube_url text, p_youtube_video_id text)
CREATE OR REPLACE FUNCTION public.tgg_insert_track(p_artist_id uuid, p_audio_url text, p_mixtape_id uuid, p_title text, p_track_number integer, p_youtube_url text DEFAULT NULL::text, p_youtube_video_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select private.tgg_insert_track(p_artist_id,p_audio_url,p_mixtape_id,p_title,p_track_number,p_youtube_url,p_youtube_video_id); $function$


-- [40000000901] function public.tgg_interview_create_draft(p_title text, p_artist_name text, p_video_url text, p_image_url text, p_publish_date timestamp with time zone)
CREATE OR REPLACE FUNCTION public.tgg_interview_create_draft(p_title text, p_artist_name text, p_video_url text, p_image_url text DEFAULT NULL::text, p_publish_date timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_artist_name text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'TITLE_REQUIRED'; end if;
  if char_length(btrim(coalesce(p_video_url,'')))<1 then raise exception 'VIDEO_URL_REQUIRED'; end if;
  select stage_name into v_artist_name from public.artists where user_id=v_uid order by created_at limit 1;
  insert into public.artist_interviews(title,artist_name,video_url,image_url,publish_date,published,user_id,status)
  values(left(btrim(p_title),180),coalesce(nullif(btrim(coalesce(p_artist_name,'')),''),v_artist_name),
    btrim(p_video_url),nullif(btrim(coalesce(p_image_url,'')),''),coalesce(p_publish_date,now()),false,v_uid,'draft')
  returning id into v_id;
  return jsonb_build_object('ok',true,'interview_id',v_id,'status','draft');
end $function$


-- [40000000902] function public.tgg_interview_delete(p_interview_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_interview_delete(p_interview_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  delete from public.artist_interviews where id=p_interview_id and user_id=v_uid
  returning id into v_id;
  if v_id is null then raise exception 'INTERVIEW_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'interview_id',v_id,'deleted',true);
end $function$


-- [40000000903] function public.tgg_interview_set_published(p_interview_id uuid, p_published boolean)
CREATE OR REPLACE FUNCTION public.tgg_interview_set_published(p_interview_id uuid, p_published boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_pub boolean:=coalesce(p_published,false);
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  update public.artist_interviews
  set published=v_pub,status=case when v_pub then 'published' else 'draft' end,
      publish_date=case when v_pub and publish_date is null then now() else publish_date end
  where id=p_interview_id and user_id=v_uid
  returning id into v_id;
  if v_id is null then raise exception 'INTERVIEW_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'interview_id',v_id,'status',case when v_pub then 'published' else 'draft' end);
end $function$


-- [40000000904] function public.tgg_interview_update(p_interview_id uuid, p_title text, p_artist_name text, p_video_url text, p_image_url text, p_publish_date timestamp with time zone)
CREATE OR REPLACE FUNCTION public.tgg_interview_update(p_interview_id uuid, p_title text, p_artist_name text, p_video_url text, p_image_url text, p_publish_date timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'TITLE_REQUIRED'; end if;
  if char_length(btrim(coalesce(p_video_url,'')))<1 then raise exception 'VIDEO_URL_REQUIRED'; end if;
  update public.artist_interviews
  set title=left(btrim(p_title),180),artist_name=nullif(btrim(coalesce(p_artist_name,'')),''),
      video_url=btrim(p_video_url),image_url=nullif(btrim(coalesce(p_image_url,'')),''),
      publish_date=coalesce(p_publish_date,publish_date)
  where id=p_interview_id and user_id=v_uid
  returning id into v_id;
  if v_id is null then raise exception 'INTERVIEW_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'interview_id',v_id);
end $function$


-- [40000000905] function public.tgg_join_dynamic_event(p_character_id uuid, p_dynamic_event_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_join_dynamic_event(p_character_id uuid, p_dynamic_event_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$ select private.tgg_join_dynamic_event(p_character_id,p_dynamic_event_id); $function$


-- [40000000906] function public.tgg_launch_closeout_summary()
CREATE OR REPLACE FUNCTION public.tgg_launch_closeout_summary()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with
sys as (select public.tgg_one_final_system_health() j),
drift as (select public.tgg_runtime_drift_guard() j),
launch as (select public.tgg_launch_readiness() j),
wf as (select public.tgg_creator_workflow_readiness() j),
access as (select public.tgg_creator_access_readiness() j),
ext as (select public.tgg_external_completion_state() j),
ops as (select private.tgg_launch_closeout_ops_snapshot() j),
summary as (
  select
    (select j->>'state' from sys) system_state,
    (select j->>'launch_stage' from sys) launch_stage,
    coalesce(((select j->>'ok' from drift))::boolean,false) drift_ok,
    coalesce(((select j->>'platform_complete' from launch))::boolean,false) platform_complete,
    coalesce(((select j->>'ok' from wf))::boolean,false) workflows_ok,
    coalesce(((select j->>'ok' from access))::boolean,false) access_ok,
    coalesce(((select j->>'core_complete' from ext))::boolean,false) core_complete,
    coalesce(((select j->>'fully_connected' from ext))::boolean,false) fully_connected,
    coalesce(((select j->>'complete_actions' from ext))::int,0) ext_complete,
    coalesce(((select j->>'total_actions' from ext))::int,0) ext_total,
    (select j->>'dependency_state' from ops) dependency_state,
    coalesce(((select j->>'dependency_failures' from ops))::int,0) dependency_failures,
    coalesce(((select j->>'blocking_alerts' from ops))::int,0) blocking_alerts,
    coalesce(((select j->>'advisory_alerts' from ops))::int,0) advisory_alerts,
    coalesce(((select j->>'open_incidents' from ops))::int,0) open_incidents
)
select jsonb_build_object(
  'ok',
    system_state='READY' and drift_ok and platform_complete and workflows_ok and access_ok
    and core_complete and dependency_state='pass' and dependency_failures=0
    and blocking_alerts=0 and open_incidents=0,
  'version','LAUNCH-CLOSEOUT-1.2',
  'status',case
    when system_state='READY' and drift_ok and platform_complete and workflows_ok and access_ok
      and core_complete and dependency_state='pass' and dependency_failures=0
      and blocking_alerts=0 and open_incidents=0 and fully_connected
    then 'FULLY_CONNECTED'
    when system_state='READY' and drift_ok and platform_complete and workflows_ok and access_ok
      and core_complete and dependency_state='pass' and dependency_failures=0
      and blocking_alerts=0 and open_incidents=0
    then 'CORE_LAUNCH_READY'
    else 'ATTENTION'
  end,
  'system_state',system_state,
  'launch_stage',launch_stage,
  'core_launch_ready',
    system_state='READY' and drift_ok and platform_complete and workflows_ok and access_ok
    and core_complete and dependency_state='pass' and dependency_failures=0
    and blocking_alerts=0 and open_incidents=0,
  'fully_connected',fully_connected,
  'external_completion',jsonb_build_object(
    'complete',ext_complete,'total',ext_total,'pending',greatest(ext_total-ext_complete,0),
    'items',(select j->'items' from ext)
  ),
  'workflows',jsonb_build_object(
    'ready',(select j->'ready_count' from wf),'total',(select j->'total' from wf),
    'full_ready',(select j->'full_ready' from wf),'fallback_ready',(select j->'fallback_ready' from wf),
    'validation_required',(select j->'validation_required' from wf)
  ),
  'access_qa',jsonb_build_object(
    'ok',access_ok,'write_functions',(select j->'write_functions' from access),
    'rls',(select j->'rls' from access),'collaboration',(select j->'collaboration' from access)
  ),
  'fallbacks',jsonb_build_object(
    'payments',(select j->'payments'->>'safe_mode' from launch),
    'memberships',(select j->'memberships'->>'safe_mode' from launch),
    'distribution',(select j->'distribution'->>'safe_mode' from launch),
    'live',(select j->'live'->>'safe_mode' from launch),
    'calls',(select j->'calls'->>'safe_mode' from launch)
  ),
  'operations',(select j from ops),
  'canonical_urls',jsonb_build_object(
    'creator_os','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-creator-os-app-v17?app=1',
    'master_admin','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-creator-os-app-v17?app=1#master-admin',
    'public_site','https://trugogettamixtapes.blogspot.com/'
  ),
  'generated_at',now()
)
from summary;
$function$


