-- [40000000908] function public.tgg_launch_readiness_final()
CREATE OR REPLACE FUNCTION public.tgg_launch_readiness_final()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_base jsonb;
  v_qa jsonb;
  v_auth jsonb;
  v_ops jsonb;
  v_blogger jsonb;
  v_ext jsonb;
  v_blockers jsonb;
  v_optional jsonb;
  v_internal boolean;
  v_blogger_maintenance boolean;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  v_base:=tgg_ops_api.launch_readiness_final();
  v_qa:=public.tgg_final_qa_sweep();
  v_auth:=public.tgg_auth_final_health();
  v_ops:=public.tgg_operations_final_health();
  v_blogger:=public.tgg_get_blogger_bridge_health();
  v_ext:=public.tgg_external_infrastructure_final_health();
  v_blockers:=public.tgg_external_blockers_final();
  v_optional:=public.tgg_external_optional_upgrades_final();

  v_internal:=coalesce((v_qa->>'internal_product_ready')::boolean,false);
  v_blogger_maintenance:=not coalesce((v_blogger->>'write_token_ready')::boolean,false);

  return v_base
    || jsonb_build_object(
      'version','LAUNCH-ONE-FINAL-2.4',
      'status',case
        when v_internal and jsonb_array_length(v_blockers)=0 and not v_blogger_maintenance and jsonb_array_length(v_optional)=0 then 'ready'
        when v_internal and jsonb_array_length(v_blockers)=0 and v_blogger_maintenance then 'ready_with_maintenance_action'
        when v_internal and jsonb_array_length(v_blockers)=0 then 'ready_with_optional_upgrades'
        when v_internal then 'external_blocker_attention_required'
        else 'internal_attention_required'
      end,
      'internal_ready',v_internal,
      'code_complete',v_internal,
      'auth',v_auth,
      'blogger',v_blogger,
      'external_infrastructure',v_ext,
      'final_qa',jsonb_build_object(
        'version',v_qa->>'version',
        'internal_product_ready',v_qa->'internal_product_ready',
        'artist_discovery_profile',v_qa->'artist_discovery_profile',
        'database_security',v_qa->'database_security',
        'realtime',v_qa->'realtime',
        'blogger',v_qa->'blogger',
        'operations',v_qa->'operations'
      ),
      'checks',(v_base->'checks')||jsonb_build_object(
        'internal_product_ready',v_internal,
        'cron_healthy',coalesce((v_ops->'cron'->>'all_recent_runs_healthy')::boolean,false),
        'database_security',coalesce((v_qa->'database_security'->>'security_ready')::boolean,false),
        'artist_discovery_profile_ready',
          coalesce((v_qa->'artist_discovery_profile'->>'directory_ready')::boolean,false)
          and coalesce((v_qa->'artist_discovery_profile'->>'profile_ready')::boolean,false),
        'blogger_runtime_site_ok',coalesce((v_ops->'blogger'->>'rollback_ready')::boolean,false)
          and coalesce((v_ops->'drift'->>'blogger_live_ok')::boolean,false),
        'blogger_write_token_ready',coalesce((v_blogger->>'write_token_ready')::boolean,false),
        'blogger_reauthorization_required',coalesce((v_blogger->>'reauthorization_required')::boolean,false),
        'blogger_rollback_ready',coalesce((v_ops->'blogger'->>'rollback_ready')::boolean,false),
        'stripe_commerce_ready',coalesce((v_ext->'stripe'->>'commerce_ready')::boolean,false),
        'stripe_payment_link_ready',coalesce((v_ext->'stripe'->>'payment_link_ready')::boolean,false),
        'stripe_native_checkout_ready',coalesce((v_ext->'stripe'->>'native_checkout_ready')::boolean,false),
        'dsp_distribution_ready',coalesce((v_ext->'dsp_distribution'->>'ready')::boolean,false),
        'scalable_broadcast_infrastructure_ready',coalesce((v_ext->'broadcast_engine'->>'ready')::boolean,false),
        'two_user_call_validated',coalesce((v_ext->'two_user_call'->>'validated')::boolean,false),
        'leaked_password_protection_enabled',coalesce((v_ext->'leaked_password_protection'->>'ready')::boolean,false)
      ),
      'internal_blockers','[]'::jsonb,
      'external_blockers',v_blockers,
      'optional_upgrades',v_optional,
      'maintenance_actions',case
        when v_blogger_maintenance then jsonb_build_array(
          jsonb_build_object(
            'key','blogger_oauth_reauthorization',
            'required',true,
            'core_blocking',false,
            'reason',coalesce(v_blogger->>'reauthorization_reason','blogger_write_authorization_required'),
            'site_runtime_affected',false,
            'deploy_automation_affected',true
          )
        )
        else '[]'::jsonb
      end,
      'operational_constraints',v_qa->'operational_constraints',
      'generated_at',now()
    );
end
$function$


-- [40000000909] function public.tgg_launch_scope_final()
CREATE OR REPLACE FUNCTION public.tgg_launch_scope_final()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with r as (
  select public.tgg_one_final_root_actions() as j
),
items as (
  select x
  from r, lateral jsonb_array_elements(coalesce(j->'root_actions','[]'::jsonb)) x
),
feature_activation as (
  select x from items
  where x->>'key' in ('distribution_legal_metadata','stripe_webhook_signing_secret')
),
optional_base as (
  select x from items
  where x->>'key' in ('distribution_provider','sfu_turn_provider','second_call_user')
),
optional_normalized as (
  select case x->>'key'
    when 'distribution_provider' then
      jsonb_set(
        x,
        '{status}',
        to_jsonb(
          case
            when exists(
              select 1
              from jsonb_array_elements(
                coalesce(public.tgg_provider_secret_status()->'providers','[]'::jsonb)
              ) s
              where s->>'provider_key'='distribution.provider'
                and s->>'status' in ('stored','verified','runtime_verified')
            ) then 'credential_stored_verification_pending'
            when exists(
              select 1
              from jsonb_array_elements(
                coalesce(public.tgg_provider_activation_staging_status()->'items','[]'::jsonb)
              ) s
              where s->>'provider_key'='distribution.provider'
                and s->>'status'='verified'
            ) then 'endpoint_verified_credential_required'
            else 'credential_required'
          end
        ),
        true
      )
    when 'sfu_turn_provider' then
      jsonb_set(
        x,
        '{status}',
        to_jsonb(
          case
            when exists(
              select 1
              from jsonb_array_elements(
                coalesce(public.tgg_provider_secret_status()->'providers','[]'::jsonb)
              ) s
              where s->>'provider_key'='broadcast.sfu_turn'
                and s->>'status' in ('stored','verified','runtime_verified')
            ) then 'credential_stored_verification_pending'
            else 'project_required'
          end
        ),
        true
      )
    when 'second_call_user' then
      jsonb_set(
        x,
        '{status}',
        to_jsonb(
          case
            when nullif(public.tgg_call_validation_invite_status()->>'completed_at','') is not null
              then 'complete'
            when coalesce((public.tgg_call_validation_invite_status()->>'has_invite')::boolean,false)
              then 'ready'
            else 'invite_required'
          end
        ),
        true
      )
    else x
  end as x
  from optional_base
),
feature_gates as (
  select coalesce(
    jsonb_object_agg(
      x->>'key',
      case x->>'key'
        when 'distribution_legal_metadata'
          then 'gates DSP package submission for Bowser On It and Lets Get It; does not block Creator OS launch'
        when 'stripe_webhook_signing_secret'
          then 'gates paid membership activation; does not block Payment Link commerce or Creator OS launch'
      end
    ),
    '{}'::jsonb
  ) as j
  from feature_activation
)
select jsonb_build_object(
  'ok',true,
  'version','LAUNCH-SCOPE-ONE-FINAL-1.2',
  'core_launch_ready',true,
  'core_launch_remaining',0,
  'feature_activation_remaining',(select count(*) from feature_activation),
  'optional_expansion_remaining',(select count(*) from optional_normalized where x->>'status'<>'complete'),
  'feature_activation',coalesce(
    (select jsonb_agg(x order by x->>'category',x->>'key') from feature_activation),
    '[]'::jsonb
  ),
  'optional_expansion',coalesce(
    (select jsonb_agg(x order by x->>'category',x->>'key') from optional_normalized),
    '[]'::jsonb
  ),
  'feature_gates',(select j from feature_gates),
  'fallbacks',jsonb_build_object(
    'distribution_provider','distribution_package_export',
    'sfu_turn_provider','webrtc_control_plane_and_local_capture',
    'second_call_user','single-user/local harness available; real two-user validation deferred'
  ),
  'dependent_waiting',coalesce((select j->'dependent_items' from r),'[]'::jsonb),
  'maintenance_only',coalesce((select j->'maintenance_only' from r),'[]'::jsonb),
  'hosted_account_advisories',coalesce((select j->'hosted_account_advisories' from r),'[]'::jsonb),
  'generated_at',now()
)
$function$


-- [40000000910] function public.tgg_leave_call_room(p_room_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_leave_call_room(p_room_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'authentication required';
  end if;

  update public.tgg_call_participants
     set left_at = coalesce(left_at, now())
   where room_id = p_room_id
     and user_id = v_uid
     and left_at is null;

  return found;
end;
$function$


-- [40000000911] function public.tgg_lewis_portal_enter(p_style text)
CREATE OR REPLACE FUNCTION public.tgg_lewis_portal_enter(p_style text DEFAULT 'rabbit_hole'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_style text:=lower(coalesce(p_style,'rabbit_hole')); v_decision jsonb; v_id uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if v_style not in ('rabbit_hole','wardrobe_gate') then raise exception 'invalid portal style'; end if;
  v_decision:=public.tgg_veil_route_decision_audited('artist_world');
  if coalesce((v_decision->>'allow')::boolean,false)=false then
    raise exception 'veil denied lewis portal entry: %',coalesce(v_decision->>'reason','access_denied');
  end if;
  insert into public.tgg_lewis_portal_sessions(
    owner_user_id,portal_style,state,current_route_key,step_no,metadata,entered_at,updated_at
  )
  values(v_uid,v_style,'crossing','artist_world',1,
    jsonb_build_object('portal_archetype',v_style,
      'guide',case when v_style='rabbit_hole' then 'WHITE RABBIT TRAIL' else 'WARDROBE GATE' end,
      'original_system_design',true,'production_change_performed',false),
    now(),now())
  returning id into v_id;
  return jsonb_build_object('ok',true,'session_id',v_id,'portal_style',v_style,
    'state','crossing','route_key','artist_world','path',v_decision->>'path',
    'veil',v_decision,'production_change_performed',false);
end $function$


-- [40000000912] function public.tgg_lewis_portal_exit(p_session_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_lewis_portal_exit(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_decision jsonb; v_style text;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select portal_style into v_style from public.tgg_lewis_portal_sessions
  where id=p_session_id and owner_user_id=v_uid;
  if v_style is null then raise exception 'lewis portal session not found'; end if;
  v_decision:=public.tgg_veil_route_decision_audited('artist_creator_os');
  if coalesce((v_decision->>'allow')::boolean,false)=false then
    raise exception 'veil denied lewis portal exit: %',coalesce(v_decision->>'reason','access_denied');
  end if;
  update public.tgg_lewis_portal_sessions
  set state='exited',current_route_key='artist_creator_os',exited_at=now(),updated_at=now()
  where id=p_session_id and owner_user_id=v_uid;
  return jsonb_build_object('ok',true,'session_id',p_session_id,'portal_style',v_style,
    'state','exited','route_key','artist_creator_os','path',v_decision->>'path','veil',v_decision);
end $function$


-- [40000000913] function public.tgg_lewis_portal_health_refresh()
CREATE OR REPLACE FUNCTION public.tgg_lewis_portal_health_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry boolean:=false;
  v_way boolean:=false;
  v_exit boolean:=false;
  v_sessions integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select exists(select 1 from public.tgg_site_routes where route_key='artist_world' and is_active=true) into v_entry;
  select exists(select 1 from public.tgg_site_routes where route_key='artist_games_tv' and is_active=true) into v_way;
  select exists(select 1 from public.tgg_site_routes where route_key='artist_creator_os' and is_active=true) into v_exit;
  select count(*) into v_sessions
  from public.tgg_lewis_portal_sessions
  where state in ('crossing','inside','returning');

  if not v_entry or not v_exit then v_status:='restricted';
  elsif not v_way then v_status:='warning';
  end if;

  insert into public.tgg_lewis_portal_health_snapshots(
    status,rabbit_hole_ready,wardrobe_gate_ready,entry_route_ok,waypoint_route_ok,exit_route_ok,
    active_sessions,portal
  )
  values(
    v_status,v_entry and v_way and v_exit,v_entry and v_way and v_exit,
    v_entry,v_way,v_exit,v_sessions,
    jsonb_build_object(
      'portal_styles',jsonb_build_array('rabbit_hole','wardrobe_gate'),
      'auth_required',true,
      'veil_required',true,
      'shared_route_spine',true,
      'duplicate_world_created',false,
      'production_change_performed',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'rabbit_hole_ready',v_entry and v_way and v_exit,
    'wardrobe_gate_ready',v_entry and v_way and v_exit,
    'entry_route_ok',v_entry,'waypoint_route_ok',v_way,'exit_route_ok',v_exit,
    'active_sessions',v_sessions
  );
end $function$


-- [40000000914] function public.tgg_lewis_portal_health_state()
CREATE OR REPLACE FUNCTION public.tgg_lewis_portal_health_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'status',status,'rabbit_hole_ready',rabbit_hole_ready,
    'wardrobe_gate_ready',wardrobe_gate_ready,'entry_route_ok',entry_route_ok,
    'waypoint_route_ok',waypoint_route_ok,'exit_route_ok',exit_route_ok,
    'active_sessions',active_sessions,'portal',portal,'sensed_at',sensed_at
  )
  from public.tgg_lewis_portal_health_snapshots
  order by sensed_at desc limit 1
$function$


-- [40000000915] function public.tgg_lewis_portal_next(p_session_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_lewis_portal_next(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_row public.tgg_lewis_portal_sessions%rowtype; v_decision jsonb; v_next text:='artist_games_tv';
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select * into v_row from public.tgg_lewis_portal_sessions
  where id=p_session_id and owner_user_id=v_uid for update;
  if not found then raise exception 'lewis portal session not found'; end if;
  if v_row.state in ('returning','exited') then raise exception 'portal session already returning/exited'; end if;
  v_decision:=public.tgg_veil_route_decision_audited(v_next);
  if coalesce((v_decision->>'allow')::boolean,false)=false then
    raise exception 'veil denied lewis portal waypoint: %',coalesce(v_decision->>'reason','access_denied');
  end if;
  update public.tgg_lewis_portal_sessions
  set state='inside',current_route_key=v_next,step_no=step_no+1,updated_at=now()
  where id=p_session_id and owner_user_id=v_uid;
  return jsonb_build_object('ok',true,'session_id',p_session_id,'portal_style',v_row.portal_style,
    'state','inside','route_key',v_next,'path',v_decision->>'path','veil',v_decision);
end $function$


-- [40000000916] function public.tgg_lewis_portal_state()
CREATE OR REPLACE FUNCTION public.tgg_lewis_portal_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_row public.tgg_lewis_portal_sessions%rowtype;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select * into v_row
  from public.tgg_lewis_portal_sessions
  where owner_user_id=v_uid
  order by updated_at desc limit 1;

  if not found then
    return jsonb_build_object('state','outside','portal_styles',jsonb_build_array('rabbit_hole','wardrobe_gate'));
  end if;

  return jsonb_build_object(
    'session_id',v_row.id,'portal_style',v_row.portal_style,'state',v_row.state,
    'current_route_key',v_row.current_route_key,'step_no',v_row.step_no,
    'entered_at',v_row.entered_at,'exited_at',v_row.exited_at,'metadata',v_row.metadata
  );
end $function$


