-- [40000000918] function public.tgg_live_guest_request(p_stream_id uuid, p_join_mode text, p_note text)
CREATE OR REPLACE FUNCTION public.tgg_live_guest_request(p_stream_id uuid, p_join_mode text DEFAULT 'video'::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_id uuid;
      v_mode text:=lower(btrim(coalesce(p_join_mode,'video')));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if v_mode not in ('video','audio','collab') then raise exception 'JOIN_MODE_INVALID'; end if;
      if not exists(select 1 from public.live_streams where id=p_stream_id and status='LIVE') then
        raise exception 'STREAM_NOT_LIVE';
      end if;
      if exists(select 1 from public.live_streams where id=p_stream_id and creator_id=v_uid) then
        raise exception 'HOST_CANNOT_REQUEST';
      end if;

      insert into public.tgg_live_guest_requests(stream_id,requester_id,join_mode,note,status)
      values(p_stream_id,v_uid,v_mode,left(nullif(btrim(coalesce(p_note,'')),''),500),'pending')
      returning id into v_id;

      return jsonb_build_object('ok',true,'request_id',v_id,'join_mode',v_mode,'status','pending');
    end;
    $function$


-- [40000000919] function public.tgg_live_guest_respond(p_request_id uuid, p_accept boolean, p_studio_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_live_guest_respond(p_request_id uuid, p_accept boolean, p_studio_project_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_req public.tgg_live_guest_requests;
  v_room uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select r.* into v_req
  from public.tgg_live_guest_requests r
  join public.live_streams s on s.id=r.stream_id
  where r.id=p_request_id and s.creator_id=v_uid and r.status='pending'
  for update;

  if v_req.id is null then raise exception 'REQUEST_UNAVAILABLE'; end if;

  if not coalesce(p_accept,false) then
    update public.tgg_live_guest_requests
    set status='declined',responded_at=now()
    where id=v_req.id;

    return jsonb_build_object('ok',true,'accepted',false,'request_id',v_req.id);
  end if;

  insert into public.tgg_call_rooms(created_by,title,room_type,status,is_group)
  values(
    v_uid,'Live Guest Room',
    case when v_req.join_mode='audio' then 'audio' else 'video' end,
    'active',true
  )
  returning id into v_room;

  insert into public.tgg_call_participants(room_id,user_id,mic_enabled,camera_enabled)
  values
    (v_room,v_uid,true,true),
    (v_room,v_req.requester_id,true,v_req.join_mode<>'audio')
  on conflict(room_id,user_id) do update set left_at=null;

  if v_req.join_mode='collab' then
    if p_studio_project_id is null then raise exception 'PROJECT_REQUIRED_FOR_COLLAB'; end if;

    if not exists(
      select 1 from public.tgg_studio_projects
      where id=p_studio_project_id and user_id=v_uid
    ) then
      raise exception 'PROJECT_NOT_FOUND_OR_NOT_OWNED';
    end if;

    insert into public.tgg_studio_project_members(
      project_id,user_id,role,can_edit,can_record,can_publish,left_at
    )
    values(
      p_studio_project_id,v_req.requester_id,'editor',true,true,false,null
    )
    on conflict(project_id,user_id) do update
      set role='editor',
          can_edit=true,
          can_record=true,
          can_publish=false,
          left_at=null;

    update public.tgg_studio_projects
    set collaboration_enabled=true,updated_at=now()
    where id=p_studio_project_id;
  end if;

  update public.tgg_live_guest_requests
  set status='accepted',
      responded_at=now(),
      call_room_id=v_room,
      studio_project_id=p_studio_project_id
  where id=v_req.id;

  return jsonb_build_object(
    'ok',true,
    'accepted',true,
    'request_id',v_req.id,
    'call_room_id',v_room,
    'join_mode',v_req.join_mode,
    'studio_project_id',p_studio_project_id,
    'collab_can_publish',false
  );
end
$function$


