-- [40000000922] function public.tgg_live_my_guest_requests()
CREATE OR REPLACE FUNCTION public.tgg_live_my_guest_requests()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      return jsonb_build_object(
        'requests',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',r.id,'stream_id',r.stream_id,'join_mode',r.join_mode,'status',r.status,
            'call_room_id',r.call_room_id,'studio_project_id',r.studio_project_id,
            'requested_at',r.requested_at,'responded_at',r.responded_at
          ) order by r.requested_at desc)
          from public.tgg_live_guest_requests r
          where r.requester_id=v_uid and r.status in ('pending','accepted')
        ),'[]'::jsonb)
      );
    end $function$


-- [40000000923] function public.tgg_live_react(p_stream_id uuid, p_reaction_type text)
CREATE OR REPLACE FUNCTION public.tgg_live_react(p_stream_id uuid, p_reaction_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_type text:=lower(btrim(coalesce(p_reaction_type,'')));
  v_id uuid;
begin
  if v_type not in ('fire','heart','clap','100') then
    raise exception 'REACTION_INVALID';
  end if;

  if not exists(
    select 1
    from public.live_streams s
    join public.content_items c on c.id=s.content_id
    where s.id=p_stream_id
      and s.status='LIVE'
      and s.reactions_enabled=true
      and c.status='PUBLISHED'
      and c.visibility='PUBLIC'
  ) then
    raise exception 'REACTIONS_UNAVAILABLE';
  end if;

  insert into public.live_reactions(stream_id,user_id,reaction_type)
  values(p_stream_id,v_uid,v_type)
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,
    'reaction_id',v_id,
    'reaction_type',v_type
  );
end
$function$


