-- [40000000927] function public.tgg_live_studio_create(p_title text, p_description text, p_category text, p_broadcast_mode text, p_audience text, p_recording_enabled boolean, p_camera_enabled boolean, p_screen_enabled boolean, p_mic_enabled boolean, p_system_audio_enabled boolean, p_chat_enabled boolean, p_reactions_enabled boolean, p_pip_position text)
CREATE OR REPLACE FUNCTION public.tgg_live_studio_create(p_title text, p_description text DEFAULT NULL::text, p_category text DEFAULT 'studio'::text, p_broadcast_mode text DEFAULT 'camera_screen'::text, p_audience text DEFAULT 'everyone'::text, p_recording_enabled boolean DEFAULT true, p_camera_enabled boolean DEFAULT true, p_screen_enabled boolean DEFAULT true, p_mic_enabled boolean DEFAULT true, p_system_audio_enabled boolean DEFAULT true, p_chat_enabled boolean DEFAULT true, p_reactions_enabled boolean DEFAULT true, p_pip_position text DEFAULT 'bottom_right'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_content_id uuid;
      v_stream_id uuid;
      v_visibility text;
      v_title text:=btrim(coalesce(p_title,''));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if char_length(v_title)<2 or char_length(v_title)>160 then raise exception 'TITLE_INVALID'; end if;
      if p_broadcast_mode not in ('camera_screen','screen_only','camera_only','studio_process') then raise exception 'BROADCAST_MODE_INVALID'; end if;
      if p_audience not in ('everyone','followers','supporters','private') then raise exception 'AUDIENCE_INVALID'; end if;
      if p_pip_position not in ('top_left','top_right','bottom_left','bottom_right') then raise exception 'PIP_POSITION_INVALID'; end if;

      v_visibility:=case when p_audience='everyone' then 'PUBLIC' else 'PRIVATE' end;

      insert into public.content_items(creator_id,content_type,status,visibility,published_at)
      values(v_uid,'LIVE','PUBLISHED',v_visibility,now())
      returning id into v_content_id;

      insert into public.live_streams(
        content_id,creator_id,title,description,category,status,recording_enabled,
        broadcast_mode,audience,camera_enabled,screen_enabled,mic_enabled,
        system_audio_enabled,chat_enabled,reactions_enabled,pip_position,replay_status
      )
      values(
        v_content_id,v_uid,v_title,nullif(btrim(coalesce(p_description,'')),''),
        nullif(btrim(coalesce(p_category,'')),'studio'),'SCHEDULED',coalesce(p_recording_enabled,true),
        p_broadcast_mode,p_audience,coalesce(p_camera_enabled,true),coalesce(p_screen_enabled,true),
        coalesce(p_mic_enabled,true),coalesce(p_system_audio_enabled,true),
        coalesce(p_chat_enabled,true),coalesce(p_reactions_enabled,true),p_pip_position,
        case when coalesce(p_recording_enabled,true) then 'recording' else 'none' end
      )
      returning id into v_stream_id;

      return jsonb_build_object(
        'ok',true,'stream_id',v_stream_id,'content_id',v_content_id,
        'status','SCHEDULED','broadcast_mode',p_broadcast_mode,'audience',p_audience
      );
    end;
    $function$


-- [40000000928] function public.tgg_live_studio_finalize_replay(p_stream_id uuid, p_storage_path text, p_duration_seconds numeric, p_aspect_ratio text, p_source_modes jsonb)
CREATE OR REPLACE FUNCTION public.tgg_live_studio_finalize_replay(p_stream_id uuid, p_storage_path text, p_duration_seconds numeric DEFAULT NULL::numeric, p_aspect_ratio text DEFAULT '16:9'::text, p_source_modes jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_stream public.live_streams;
  v_replay_id uuid;
  v_path text:=btrim(coalesce(p_storage_path,''));
  v_meta jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_stream
  from public.live_streams
  where id=p_stream_id and creator_id=v_uid;

  if v_stream.id is null then raise exception 'STREAM_NOT_FOUND_OR_NOT_OWNED'; end if;
  if v_path !~ ('^' || v_uid::text || '/studio/') then raise exception 'REPLAY_PATH_NOT_OWNED'; end if;
  if p_duration_seconds is not null and (p_duration_seconds<0 or p_duration_seconds>86400) then raise exception 'DURATION_INVALID'; end if;

  if not exists(
    select 1 from storage.objects o
    where o.bucket_id='creator-media'
      and o.name=v_path
      and (storage.foldername(o.name))[1]=v_uid::text
  ) then raise exception 'REPLAY_OBJECT_NOT_FOUND'; end if;

  insert into public.tgg_live_replays(
    stream_id,creator_id,storage_path,title,duration_seconds,aspect_ratio,status,edit_status,source_modes
  )
  values(
    v_stream.id,v_uid,v_path,v_stream.title,p_duration_seconds,
    coalesce(nullif(btrim(p_aspect_ratio),''),'16:9'),'ready','not_started',coalesce(p_source_modes,'{}'::jsonb)
  )
  on conflict(stream_id) do update
    set storage_path=excluded.storage_path,
        title=excluded.title,
        duration_seconds=excluded.duration_seconds,
        aspect_ratio=excluded.aspect_ratio,
        status='ready',
        source_modes=excluded.source_modes,
        updated_at=now()
  returning id into v_replay_id;

  update public.live_streams
  set recording_path=v_path,
      replay_status='ready',
      replay_duration_seconds=p_duration_seconds,
      updated_at=now()
  where id=v_stream.id;

  v_meta:=jsonb_build_object(
    'source_surface','live',
    'live_stream_id',v_stream.id,
    'live_replay_id',v_replay_id,
    'aspect_ratio',coalesce(nullif(btrim(p_aspect_ratio),''),'16:9'),
    'source_modes',coalesce(p_source_modes,'{}'::jsonb),
    'video_studio_url','/p/video-studio.html?live_replay_id='||v_replay_id::text
  );

  if not exists(
    select 1 from public.tgg_media_vault_assets v
    where v.user_id=v_uid and v.storage_path=v_path
  ) then
    perform public.tgg_register_media_vault_asset(
      null,'video',coalesce(nullif(btrim(v_stream.title),''),'Live Replay'),
      v_path,'video/webm',null,p_duration_seconds,null,null,v_meta
    );
  end if;

  perform public.tgg_mark_media_upload_finalized(v_path);

  return jsonb_build_object(
    'ok',true,
    'replay_id',v_replay_id,
    'stream_id',v_stream.id,
    'vault_registered',true,
    'video_studio_url','/p/video-studio.html?live_replay_id='||v_replay_id::text,
    'status','ready'
  );
end
$function$


-- [40000000929] function public.tgg_live_studio_mark_clip(p_stream_id uuid, p_title text, p_start_seconds numeric, p_end_seconds numeric, p_clip_kind text)
CREATE OR REPLACE FUNCTION public.tgg_live_studio_mark_clip(p_stream_id uuid, p_title text DEFAULT 'Clip Moment'::text, p_start_seconds numeric DEFAULT 0, p_end_seconds numeric DEFAULT NULL::numeric, p_clip_kind text DEFAULT 'moment'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_id uuid;
      v_replay_id uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if not exists(select 1 from public.live_streams where id=p_stream_id and creator_id=v_uid) then
        raise exception 'STREAM_NOT_FOUND_OR_NOT_OWNED';
      end if;
      select id into v_replay_id from public.tgg_live_replays where stream_id=p_stream_id and creator_id=v_uid limit 1;

      insert into public.tgg_live_clips(
        stream_id,replay_id,creator_id,title,start_seconds,end_seconds,clip_kind,status
      )
      values(
        p_stream_id,v_replay_id,v_uid,left(btrim(coalesce(p_title,'Clip Moment')),120),
        greatest(coalesce(p_start_seconds,0),0),
        case when p_end_seconds is null then null else greatest(p_end_seconds,coalesce(p_start_seconds,0)) end,
        case when p_clip_kind in ('moment','short','story','highlight') then p_clip_kind else 'moment' end,
        'marker'
      )
      returning id into v_id;

      return jsonb_build_object('ok',true,'clip_id',v_id,'stream_id',p_stream_id);
    end;
    $function$


-- [40000000930] function public.tgg_live_studio_send_chat(p_stream_id uuid, p_body text, p_display_name text)
CREATE OR REPLACE FUNCTION public.tgg_live_studio_send_chat(p_stream_id uuid, p_body text, p_display_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_id uuid;
      v_body text:=btrim(coalesce(p_body,''));
    begin
      if char_length(v_body)<1 or char_length(v_body)>500 then raise exception 'MESSAGE_INVALID'; end if;
      if not exists(select 1 from public.live_streams where id=p_stream_id and status='LIVE' and chat_enabled=true) then
        raise exception 'CHAT_UNAVAILABLE';
      end if;
      insert into public.tgg_live_chat_messages(stream_id,user_id,display_name,body)
      values(p_stream_id,v_uid,left(nullif(btrim(coalesce(p_display_name,'')),''),80),v_body)
      returning id into v_id;
      return jsonb_build_object('ok',true,'message_id',v_id);
    end;
    $function$


-- [40000000931] function public.tgg_livekit_credentials_save(p_endpoint_url text, p_api_key text, p_api_secret text)
CREATE OR REPLACE FUNCTION public.tgg_livekit_credentials_save(p_endpoint_url text, p_api_key text, p_api_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_endpoint text := nullif(btrim(coalesce(p_endpoint_url,'')),'');
  v_key text := nullif(btrim(coalesce(p_api_key,'')),'');
  v_secret text := nullif(btrim(coalesce(p_api_secret,'')),'');
  v_packed text;
  v_stage jsonb;
  v_store jsonb;
  v_verify jsonb;
  v_refresh jsonb;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if v_endpoint is null or v_endpoint !~ '^wss://[^[:space:]]+$' then
    raise exception 'LIVEKIT_WSS_URL_REQUIRED' using errcode='22023';
  end if;

  if v_key is null or length(v_key) < 8 then
    raise exception 'LIVEKIT_API_KEY_REQUIRED' using errcode='22023';
  end if;

  if v_secret is null or length(v_secret) < 16 then
    raise exception 'LIVEKIT_API_SECRET_REQUIRED' using errcode='22023';
  end if;

  v_packed := jsonb_build_object(
    'api_key', v_key,
    'api_secret', v_secret
  )::text;

  v_stage := public.tgg_provider_activation_stage(
    'broadcast.sfu_turn',
    v_endpoint,
    'tgg_broadcast_provider_secret'
  );

  v_store := public.tgg_store_provider_secret(
    'broadcast.sfu_turn',
    v_packed
  );

  v_verify := public.tgg_provider_activation_verify('broadcast.sfu_turn');
  v_refresh := public.tgg_one_final_activation_queue_refresh();

  return jsonb_build_object(
    'ok', true,
    'provider_key', 'broadcast.sfu_turn',
    'endpoint_url', v_endpoint,
    'secret_stored', coalesce((v_store->>'ok')::boolean,false),
    'verification_queued', coalesce((v_verify->>'ok')::boolean,false),
    'secret_value_returned', false,
    'stage', v_stage,
    'activation_refreshed', coalesce((v_refresh->>'ok')::boolean,false)
  );
end;
$function$


