-- [40000000937] function public.tgg_master_owner_dashboard()
CREATE OR REPLACE FUNCTION public.tgg_master_owner_dashboard()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
select case
  when auth.uid() is null or coalesce(auth.jwt()->'app_metadata'->>'tgg_role','') <> 'owner'
    then jsonb_build_object('ok',false,'error','OWNER_REQUIRED')
  else jsonb_build_object(
    'ok',true,
    'counts',jsonb_build_object(
      'sites',(select count(*) from public.tgg_master_sites),
      'shared_settings',(select count(*) from public.tgg_master_shared_settings),
      'content',(select count(*) from public.tgg_master_content),
      'pending_changes',(select count(*) from public.tgg_master_change_queue where status in ('pending','ready')),
      'open_alerts',(select count(*) from public.tgg_operational_alerts where status not in ('resolved','closed','dismissed'))
    ),
    'sites',coalesce((
      select jsonb_agg(jsonb_build_object(
        'site_key',site_key,
        'display_name',display_name,
        'platform',platform,
        'status',status,
        'base_url',base_url,
        'updated_at',updated_at
      ) order by display_name)
      from public.tgg_master_sites
    ),'[]'::jsonb),
    'recent_changes',coalesce((
      select jsonb_agg(x)
      from (
        select jsonb_build_object(
          'id',id,
          'site_key',target_site_key,
          'change_type',change_type,
          'status',status,
          'requested_at',requested_at,
          'applied_at',applied_at,
          'error_text',error_text
        ) x
        from public.tgg_master_change_queue
        order by requested_at desc
        limit 20
      ) q
    ),'[]'::jsonb),
    'recent_audit',coalesce((
      select jsonb_agg(x)
      from (
        select jsonb_build_object(
          'id',id,
          'action_key',action_key,
          'site_key',site_key,
          'target_key',target_key,
          'created_at',created_at
        ) x
        from public.tgg_master_audit_log
        order by created_at desc
        limit 20
      ) q
    ),'[]'::jsonb),
    'blogger',jsonb_build_object(
      'connected',coalesce((
        select status='connected'
        from public.v98_blogger_connections
        where revoked_at is null
        order by updated_at desc
        limit 1
      ),false),
      'deployments',(select count(*) from public.v98_blogger_deployments)
    ),
    'generated_at',now()
  )
end;
$function$


-- [40000000938] function public.tgg_master_owner_queue_change(p_site_key text, p_change_type text, p_payload jsonb)
CREATE OR REPLACE FUNCTION public.tgg_master_owner_queue_change(p_site_key text, p_change_type text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_row public.tgg_master_change_queue;
begin
  if auth.uid() is null or not coalesce(private.tgg_is_owner_fresh(),false) then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  if not exists (select 1 from public.tgg_master_sites where site_key=p_site_key) then
    raise exception 'SITE_NOT_FOUND' using errcode='P0002';
  end if;

  insert into public.tgg_master_change_queue
    (target_site_key,change_type,payload,status,requested_by)
  values
    (p_site_key,p_change_type,coalesce(p_payload,'{}'::jsonb),'pending',auth.uid())
  returning * into v_row;

  update public.tgg_master_sites
  set status='needs_sync',updated_by=auth.uid(),updated_at=now()
  where site_key=p_site_key;

  insert into public.tgg_master_audit_log
    (action_key,site_key,target_key,after_state,actor_id)
  values
    ('change.queue',p_site_key,v_row.id::text,to_jsonb(v_row),auth.uid());

  return jsonb_build_object('ok',true,'change',to_jsonb(v_row));
end
$function$


-- [40000000939] function public.tgg_master_owner_set_site(p_site_key text, p_status text, p_public_config jsonb)
CREATE OR REPLACE FUNCTION public.tgg_master_owner_set_site(p_site_key text, p_status text, p_public_config jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_before public.tgg_master_sites;
  v_after public.tgg_master_sites;
begin
  if auth.uid() is null or not coalesce(private.tgg_is_owner_fresh(),false) then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  if p_status not in ('online','maintenance','needs_sync','error','disabled') then
    raise exception 'INVALID_STATUS' using errcode='22023';
  end if;

  select * into v_before from public.tgg_master_sites where site_key=p_site_key;
  if v_before.id is null then raise exception 'SITE_NOT_FOUND' using errcode='P0002'; end if;

  update public.tgg_master_sites
  set status=p_status,
      public_config=coalesce(p_public_config,public_config),
      updated_by=auth.uid(),
      updated_at=now()
  where site_key=p_site_key
  returning * into v_after;

  insert into public.tgg_master_audit_log
    (action_key,site_key,target_key,before_state,after_state,actor_id)
  values
    ('site.update',p_site_key,p_site_key,to_jsonb(v_before),to_jsonb(v_after),auth.uid());

  return jsonb_build_object('ok',true,'site',to_jsonb(v_after)-'owner_config'-'updated_by');
end
$function$


-- [40000000940] function public.tgg_master_owner_upsert_content(p_site_key text, p_content_key text, p_section text, p_title text, p_config jsonb, p_is_published boolean)
CREATE OR REPLACE FUNCTION public.tgg_master_owner_upsert_content(p_site_key text, p_content_key text, p_section text, p_title text, p_config jsonb, p_is_published boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_before jsonb;
  v_after public.tgg_master_content;
begin
  if auth.uid() is null or not coalesce(private.tgg_is_owner_fresh(),false) then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  select to_jsonb(c) into v_before
  from public.tgg_master_content c
  where site_key=p_site_key and content_key=p_content_key;

  insert into public.tgg_master_content
    (site_key,content_key,section,title,config,is_published,updated_by,updated_at)
  values
    (p_site_key,p_content_key,coalesce(nullif(p_section,''),'general'),p_title,p_config,p_is_published,auth.uid(),now())
  on conflict(site_key,content_key) do update
  set section=excluded.section,
      title=excluded.title,
      config=excluded.config,
      is_published=excluded.is_published,
      updated_by=auth.uid(),
      updated_at=now()
  returning * into v_after;

  insert into public.tgg_master_audit_log
    (action_key,site_key,target_key,before_state,after_state,actor_id)
  values
    ('content.upsert',p_site_key,p_content_key,v_before,to_jsonb(v_after),auth.uid());

  return jsonb_build_object('ok',true,'content',to_jsonb(v_after)-'updated_by');
end
$function$


-- [40000000941] function public.tgg_master_owner_upsert_shared_setting(p_setting_key text, p_title text, p_config jsonb, p_is_published boolean)
CREATE OR REPLACE FUNCTION public.tgg_master_owner_upsert_shared_setting(p_setting_key text, p_title text, p_config jsonb, p_is_published boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_before jsonb;
  v_after public.tgg_master_shared_settings;
begin
  if auth.uid() is null or not coalesce(private.tgg_is_owner_fresh(),false) then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  select to_jsonb(s) into v_before
  from public.tgg_master_shared_settings s
  where setting_key=p_setting_key;

