-- [40000000942] function public.tgg_master_public_bundle(p_site_key text)
CREATE OR REPLACE FUNCTION public.tgg_master_public_bundle(p_site_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
select jsonb_build_object(
  'ok', true,
  'sites', coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'site_key',s.site_key,
        'display_name',s.display_name,
        'platform',s.platform,
        'base_url',s.base_url,
        'status',s.status,
        'public_config',s.public_config,
        'updated_at',s.updated_at
      ) order by s.display_name
    )
    from public.tgg_master_sites s
    where s.status <> 'disabled'
      and (p_site_key is null or s.site_key=p_site_key)
  ),'[]'::jsonb),
  'shared',coalesce((
    select jsonb_object_agg(setting_key,config)
    from public.tgg_master_shared_settings
    where is_published=true
  ),'{}'::jsonb),
  'features',public.tgg_feature_runtime_health(),
  'launch',public.tgg_launch_readiness(),
  'content',coalesce((
    select jsonb_object_agg(
      content_key,
      jsonb_build_object(
        'section',section,
        'title',title,
        'config',config,
        'updated_at',updated_at
      )
    )
    from public.tgg_master_content
    where is_published=true
      and (p_site_key is null or site_key=p_site_key)
  ),'{}'::jsonb),
  'generated_at',now()
);
$function$


-- [40000000943] function public.tgg_matrix_gateway_enter()
CREATE OR REPLACE FUNCTION public.tgg_matrix_gateway_enter()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_id uuid; v_decision jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  v_decision:=public.tgg_veil_route_decision_audited('artist_world');
  if coalesce((v_decision->>'allow')::boolean,false)=false then
    raise exception 'veil denied entry: %',coalesce(v_decision->>'reason','access_denied');
  end if;
  insert into public.tgg_matrix_gateway_sessions(
    owner_user_id,state,current_route_key,entry_route_key,exit_route_key,
    rabbit_step,entered_at,metadata,updated_at
  )
  values(
    v_uid,'following_rabbit','artist_world','artist_world','artist_creator_os',1,now(),
    jsonb_build_object('theme','matrix_gateway','guide','WHITE RABBIT','persona','NEO_MODE',
      'veil','open','production_change_performed',false),now()
  ) returning id into v_id;
  return jsonb_build_object('ok',true,'session_id',v_id,'state','following_rabbit',
    'route_key','artist_world','path',v_decision->>'path',
    'message','FOLLOW THE WHITE RABBIT','veil',v_decision,'production_change_performed',false);
end $function$


-- [40000000944] function public.tgg_matrix_gateway_exit(p_session_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_matrix_gateway_exit(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_decision jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if not exists(select 1 from public.tgg_matrix_gateway_sessions
    where id=p_session_id and owner_user_id=v_uid) then
    raise exception 'gateway session not found';
  end if;
  v_decision:=public.tgg_veil_route_decision_audited('artist_creator_os');
  if coalesce((v_decision->>'allow')::boolean,false)=false then
    raise exception 'veil denied exit route: %',coalesce(v_decision->>'reason','access_denied');
  end if;
  update public.tgg_matrix_gateway_sessions
  set state='exited',current_route_key='artist_creator_os',exited_at=now(),updated_at=now()
  where id=p_session_id and owner_user_id=v_uid;
  return jsonb_build_object('ok',true,'session_id',p_session_id,'state','exited',
    'route_key','artist_creator_os','path',v_decision->>'path',
    'message','WAKE UP / EXIT THE MATRIX','veil',v_decision,'production_change_performed',false);
end $function$


-- [40000000945] function public.tgg_matrix_gateway_health_refresh()
CREATE OR REPLACE FUNCTION public.tgg_matrix_gateway_health_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry boolean:=false;
  v_rabbit boolean:=false;
  v_exit boolean:=false;
  v_sessions integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select exists(
    select 1 from public.tgg_site_routes
    where route_key='artist_world' and is_active=true
  ) into v_entry;

  select exists(
    select 1 from public.tgg_site_routes
    where route_key='artist_games_tv' and is_active=true
  ) into v_rabbit;

  select exists(
    select 1 from public.tgg_site_routes
    where route_key='artist_creator_os' and is_active=true
  ) into v_exit;

  select count(*) into v_sessions
  from public.tgg_matrix_gateway_sessions
  where state in ('following_rabbit','inside','exiting');

  if not v_entry or not v_exit then
    v_status:='restricted';
  elsif not v_rabbit then
    v_status:='warning';
  end if;

  insert into public.tgg_matrix_gateway_health_snapshots(
    status,entry_route_ok,rabbit_route_ok,exit_route_ok,active_sessions,gateway
  )
  values(
    v_status,v_entry,v_rabbit,v_exit,v_sessions,
    jsonb_build_object(
      'entry','artist_world',
      'rabbit_trail','artist_games_tv',
      'exit','artist_creator_os',
      'auth_required',true,
      'anon_execute_allowed',false,
      'production_change_performed',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'entry_route_ok',v_entry,'rabbit_route_ok',v_rabbit,
    'exit_route_ok',v_exit,'active_sessions',v_sessions
  );
end $function$


-- [40000000946] function public.tgg_matrix_gateway_health_state()
CREATE OR REPLACE FUNCTION public.tgg_matrix_gateway_health_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'status',status,'entry_route_ok',entry_route_ok,
    'rabbit_route_ok',rabbit_route_ok,'exit_route_ok',exit_route_ok,
    'active_sessions',active_sessions,'gateway',gateway,'sensed_at',sensed_at
  )
  from public.tgg_matrix_gateway_health_snapshots
  order by sensed_at desc
  limit 1
$function$


-- [40000000947] function public.tgg_matrix_gateway_next(p_session_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_matrix_gateway_next(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_session public.tgg_matrix_gateway_sessions%rowtype;
  v_next_key text; v_next_step integer; v_decision jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select * into v_session from public.tgg_matrix_gateway_sessions
  where id=p_session_id and owner_user_id=v_uid for update;
  if not found then raise exception 'gateway session not found'; end if;
  if v_session.state in ('exiting','exited') then raise exception 'gateway session already exiting/exited'; end if;
  v_next_step:=v_session.rabbit_step+1;
  v_next_key:=case when v_next_step=2 then 'artist_games_tv' else 'artist_world' end;
  v_decision:=public.tgg_veil_route_decision_audited(v_next_key);
  if coalesce((v_decision->>'allow')::boolean,false)=false then
    raise exception 'veil denied next route: %',coalesce(v_decision->>'reason','access_denied');
  end if;
  update public.tgg_matrix_gateway_sessions
  set state='inside',current_route_key=v_next_key,rabbit_step=v_next_step,updated_at=now()
  where id=p_session_id and owner_user_id=v_uid;
  return jsonb_build_object('ok',true,'session_id',p_session_id,'state','inside',
    'rabbit_step',v_next_step,'route_key',v_next_key,'path',v_decision->>'path',
    'veil',v_decision,'message',case when v_next_step=2 then 'THE RABBIT GOES DEEPER' else 'YOU ARE INSIDE TGG WORLD' end);
end $function$


