-- [40000000950] function public.tgg_membership_activate_if_ready(p_tier_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_membership_activate_if_ready(p_tier_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_bundle jsonb;
  v_tier jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  v_bundle:=public.tgg_membership_activation_bundle();

  select x
  into v_tier
  from jsonb_array_elements(coalesce(v_bundle->'tiers','[]'::jsonb)) x
  where x->>'id'=p_tier_id::text
  limit 1;

  if v_tier is null then
    raise exception 'TIER_NOT_FOUND';
  end if;

  if not coalesce((v_tier->>'can_activate')::boolean,false) then
    return jsonb_build_object(
      'ok',false,
      'activated',false,
      'reason','membership_not_ready',
      'tier',v_tier,
      'webhook_ready',v_bundle->'webhook_ready',
      'payout_ready',v_bundle->'payout_ready'
    );
  end if;

  return public.tgg_membership_tier_set_active(p_tier_id,true)
         || jsonb_build_object('activated',true);
end
$function$


-- [40000000951] function public.tgg_membership_activation_bundle()
CREATE OR REPLACE FUNCTION public.tgg_membership_activation_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist_id uuid;
  v_health jsonb;
  v_webhook_ready boolean:=false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select id into v_artist_id
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist_id is null then
    raise exception 'CREATOR_PROFILE_REQUIRED';
  end if;

  v_health:=public.tgg_membership_checkout_final_health();

  select coalesce(enabled,false)
         and mode='production'
         and coalesce(endpoint_configured,false)
  into v_webhook_ready
  from public.tgg_provider_runtime_config
  where provider_key='stripe.webhook';

  return jsonb_build_object(
    'ok',true,
    'version','MEMBERSHIP-ACTIVATION-ONE-FINAL-1.2',
    'artist_id',v_artist_id,
    'payout_mode',v_health->>'creator_payout_mode',
    'payout_ready',coalesce((v_health->>'creator_payout_ready')::boolean,false),
    'webhook_ready',coalesce(v_webhook_ready,false),
    'tiers',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',t.id,
        'name',t.name,
        'description',t.description,
        'price_cents',t.price_cents,
        'benefits',t.benefits,
        'is_active',t.is_active,
        'payment_link_configured',t.stripe_payment_link_url is not null,
        'payment_link_verified',coalesce(t.stripe_payment_link_verified,false),
        'stripe_product_id',t.stripe_product_id,
        'stripe_price_id',t.stripe_price_id,
        'can_activate',
          coalesce(t.stripe_payment_link_verified,false)
          and coalesce((v_health->>'creator_payout_ready')::boolean,false)
          and coalesce(v_webhook_ready,false),
        'next_action',case
          when t.is_active then null
          when t.stripe_payment_link_url is null then 'Attach a recurring Stripe Payment Link.'
          when not coalesce(t.stripe_payment_link_verified,false) then 'Server-verify the recurring Stripe Payment Link.'
          when not coalesce(v_webhook_ready,false) then 'Store and verify the Stripe webhook signing secret in Creator OS → Activation Bridge.'
          when not coalesce((v_health->>'creator_payout_ready')::boolean,false) then 'Complete payout readiness.'
          else 'Activate the tier.'
        end
      ) order by t.created_at desc)
      from public.tgg_membership_tiers t
      where t.artist_id=v_artist_id
    ),'[]'::jsonb),
    'counts',jsonb_build_object(
      'total_tiers',(select count(*) from public.tgg_membership_tiers where artist_id=v_artist_id),
      'active_tiers',(select count(*) from public.tgg_membership_tiers where artist_id=v_artist_id and is_active),
      'verified_link_tiers',(select count(*) from public.tgg_membership_tiers where artist_id=v_artist_id and stripe_payment_link_verified),
      'activatable_tiers',(
        select count(*)
        from public.tgg_membership_tiers
        where artist_id=v_artist_id
          and not is_active
          and stripe_payment_link_verified
          and coalesce(v_webhook_ready,false)
      )
    ),
    'safe_actions',jsonb_build_object(
      'create_draft_rpc','tgg_membership_tier_create',
      'attach_link_rpc','tgg_membership_tier_set_payment_link',
      'activate_rpc','tgg_membership_tier_set_active',
      'queue_refresh_rpc','tgg_one_final_activation_queue_refresh'
    ),
    'generated_at',now()
  );
end
$function$


