-- [40000000953] function public.tgg_membership_tier_create(p_name text, p_price_cents integer, p_description text, p_benefits jsonb)
CREATE OR REPLACE FUNCTION public.tgg_membership_tier_create(p_name text, p_price_cents integer, p_description text DEFAULT NULL::text, p_benefits jsonb DEFAULT '[]'::jsonb)
 RETURNS public.tgg_membership_tiers
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist uuid;
  v public.tgg_membership_tiers;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_name,'')))<1 or char_length(btrim(coalesce(p_name,'')))>80 then
    raise exception 'NAME_INVALID';
  end if;
  if p_price_cents is null or p_price_cents<0 then raise exception 'PRICE_INVALID'; end if;
  if p_description is not null and char_length(p_description)>2000 then
    raise exception 'DESCRIPTION_TOO_LONG';
  end if;
  if jsonb_typeof(coalesce(p_benefits,'[]'::jsonb)) not in ('array','object') then
    raise exception 'BENEFITS_INVALID';
  end if;
  if octet_length(coalesce(p_benefits,'[]'::jsonb)::text)>16384 then
    raise exception 'BENEFITS_TOO_LARGE';
  end if;

  select id into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;
  if v_artist is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

  insert into public.tgg_membership_tiers(
    artist_id,name,description,price_cents,benefits,is_active
  )
  values(
    v_artist,btrim(p_name),
    nullif(btrim(coalesce(p_description,'')),''),
    p_price_cents,coalesce(p_benefits,'[]'::jsonb),false
  )
  returning * into v;

  return v;
end;
$function$


-- [40000000954] function public.tgg_membership_tier_delete(p_tier_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_membership_tier_delete(p_tier_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if exists(select 1 from public.tgg_memberships m where m.tier_id=p_tier_id and m.status in ('active','pending','paused')) then
    raise exception 'TIER_HAS_MEMBERSHIPS';
  end if;
  delete from public.tgg_membership_tiers t
  where t.id=p_tier_id
    and exists(select 1 from public.artists a where a.id=t.artist_id and a.user_id=v_uid)
  returning id into v_id;
  if v_id is null then raise exception 'TIER_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'tier_id',v_id,'deleted',true);
end $function$


-- [40000000955] function public.tgg_membership_tier_set_active(p_tier_id uuid, p_is_active boolean)
CREATE OR REPLACE FUNCTION public.tgg_membership_tier_set_active(p_tier_id uuid, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text:=coalesce(auth.jwt()->'app_metadata'->>'tgg_role','');
  v_count integer;
  v_link_verified boolean:=false;
  v_webhook_ready boolean:=false;
  v_payout_ready boolean:=false;
  v_health jsonb;
  v_sync_ok boolean:=true;
  v_sync_error text:=null;
  v_sync_skipped boolean:=false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if coalesce(p_is_active,false) then
    select coalesce(t.stripe_payment_link_verified,false)
    into v_link_verified
    from public.tgg_membership_tiers t
    join public.artists a on a.id=t.artist_id
    where t.id=p_tier_id
      and a.user_id=v_uid;

    if not coalesce(v_link_verified,false) then
      raise exception 'MEMBERSHIP_PAYMENT_LINK_NOT_VERIFIED' using errcode='22023';
    end if;

    select coalesce(enabled,false)
           and mode='production'
           and coalesce(endpoint_configured,false)
    into v_webhook_ready
    from public.tgg_provider_runtime_config
    where provider_key='stripe.webhook';

    if not coalesce(v_webhook_ready,false) then
      raise exception 'STRIPE_WEBHOOK_RUNTIME_NOT_READY' using errcode='22023';
    end if;

    v_health:=public.tgg_membership_checkout_final_health();
    v_payout_ready:=coalesce((v_health->>'creator_payout_ready')::boolean,false);

    if not v_payout_ready then
      raise exception 'MEMBERSHIP_PAYOUT_NOT_READY' using errcode='22023';
    end if;
  end if;

  update public.tgg_membership_tiers t
  set is_active=coalesce(p_is_active,false),
      updated_at=now()
  where t.id=p_tier_id
    and exists(
      select 1
      from public.artists a
      where a.id=t.artist_id
        and a.user_id=v_uid
    );

  get diagnostics v_count=row_count;

  if v_count=0 then
    raise exception 'TIER_NOT_FOUND';
  end if;

  if v_role='owner' then
    begin
      perform private.tgg_reconcile_membership_activation_item();
      perform private.tgg_activation_consistency_monitor();
    exception when others then
      v_sync_ok:=false;
      v_sync_error:=sqlerrm;
    end;
  else
    v_sync_skipped:=true;
  end if;

  return jsonb_build_object(
    'ok',true,
    'tier_id',p_tier_id,
    'is_active',coalesce(p_is_active,false),
    'guards',jsonb_build_object(
      'payment_link_verified',case when p_is_active then v_link_verified else null end,
      'webhook_runtime_ready',case when p_is_active then v_webhook_ready else null end,
      'payout_ready',case when p_is_active then v_payout_ready else null end
    ),
    'operational_sync',jsonb_build_object(
      'ok',v_sync_ok,
      'skipped',v_sync_skipped,
      'retryable',not v_sync_ok,
      'error',v_sync_error,
      'source',case when v_sync_skipped
        then 'creator_tier_write_no_owner_queue_reconcile'
        else 'membership_activation_post_write_reconcile'
      end
    )
  );
end
$function$


-- [40000000956] function public.tgg_membership_tier_set_payment_link(p_tier_id uuid, p_payment_link_url text, p_stripe_product_id text, p_stripe_price_id text)
CREATE OR REPLACE FUNCTION public.tgg_membership_tier_set_payment_link(p_tier_id uuid, p_payment_link_url text, p_stripe_product_id text DEFAULT NULL::text, p_stripe_price_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_url text:=nullif(btrim(coalesce(p_payment_link_url,'')),'');
  v_row public.tgg_membership_tiers%rowtype;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if v_url is not null and v_url !~ '^https://buy\.stripe\.com/' then
    raise exception 'PAYMENT_LINK_URL_INVALID' using errcode='22023';
  end if;

  update public.tgg_membership_tiers t
  set
    stripe_payment_link_url=v_url,
    stripe_product_id=nullif(btrim(coalesce(p_stripe_product_id,'')),''),
    stripe_price_id=nullif(btrim(coalesce(p_stripe_price_id,'')),''),
    stripe_payment_link_verified=false,
    stripe_payment_link_verified_at=null,
    is_active=case when v_url is distinct from t.stripe_payment_link_url then false else t.is_active end,
    updated_at=now()
  from public.artists a
  where t.id=p_tier_id
    and a.id=t.artist_id
    and a.user_id=v_uid
  returning t.* into v_row;

  if not found then
    raise exception 'TIER_NOT_FOUND_OR_NOT_OWNED' using errcode='42501';
  end if;

  return jsonb_build_object(
    'ok',true,
    'tier_id',v_row.id,
    'payment_link_configured',v_row.stripe_payment_link_url is not null,
    'payment_link_verified',false,
    'requires_server_verification',v_row.stripe_payment_link_url is not null,
    'stripe_product_id',v_row.stripe_product_id,
    'stripe_price_id',v_row.stripe_price_id
  );
end
$function$


-- [40000000957] function public.tgg_membership_tier_update(p_tier_id uuid, p_name text, p_price_cents integer, p_description text, p_benefits jsonb)
CREATE OR REPLACE FUNCTION public.tgg_membership_tier_update(p_tier_id uuid, p_name text, p_price_cents integer, p_description text, p_benefits jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_name,'')))<1 or char_length(btrim(coalesce(p_name,'')))>100 then raise exception 'NAME_INVALID'; end if;
  if p_price_cents is null or p_price_cents<50 then raise exception 'PRICE_INVALID_MIN_50'; end if;
  if jsonb_typeof(coalesce(p_benefits,'[]'::jsonb))<>'array' then raise exception 'BENEFITS_MUST_BE_ARRAY'; end if;
  update public.tgg_membership_tiers t
  set name=btrim(p_name),
      price_cents=p_price_cents,
      description=nullif(btrim(coalesce(p_description,'')),''),
      benefits=coalesce(p_benefits,'[]'::jsonb),
      updated_at=now()
  where t.id=p_tier_id
    and exists(select 1 from public.artists a where a.id=t.artist_id and a.user_id=v_uid)
  returning id into v_id;
  if v_id is null then raise exception 'TIER_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'tier_id',v_id);
end $function$


-- [40000000958] function public.tgg_mentorship_request_cancel(p_request_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_mentorship_request_cancel(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_id uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      update public.tgg_mentorship_requests
      set status='canceled',updated_at=now()
      where id=p_request_id and requester_user_id=v_uid and status in ('requested','accepted')
      returning id into v_id;
      if v_id is null then raise exception 'MENTORSHIP_REQUEST_NOT_CANCELABLE'; end if;
      return jsonb_build_object('ok',true,'request_id',v_id,'status','canceled');
    end $function$


-- [40000000959] function public.tgg_mentorship_request_create(p_mentor_artist_id uuid, p_topic text, p_message text, p_session_type text)
CREATE OR REPLACE FUNCTION public.tgg_mentorship_request_create(p_mentor_artist_id uuid, p_topic text, p_message text DEFAULT NULL::text, p_session_type text DEFAULT 'room'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_mentor uuid;v_id uuid;v_type text:=lower(btrim(coalesce(p_session_type,'room')));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select user_id into v_mentor from public.artists where id=p_mentor_artist_id;
      if v_mentor is null or v_mentor=v_uid then raise exception 'MENTOR_INVALID'; end if;
      if char_length(btrim(coalesce(p_topic,'')))<2 then raise exception 'TOPIC_REQUIRED'; end if;
      if v_type not in ('room','audio','video','project_review') then raise exception 'SESSION_TYPE_INVALID'; end if;
      insert into public.tgg_mentorship_requests(requester_user_id,mentor_user_id,topic,message,session_type,status)
      values(v_uid,v_mentor,left(btrim(p_topic),160),nullif(btrim(coalesce(p_message,'')),''),v_type,'requested')
      returning id into v_id;
      return jsonb_build_object('ok',true,'request_id',v_id,'status','requested');
    end $function$


-- [40000000960] function public.tgg_mentorship_request_respond(p_request_id uuid, p_accept boolean, p_scheduled_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.tgg_mentorship_request_respond(p_request_id uuid, p_accept boolean, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_id uuid;v_status text:=case when coalesce(p_accept,false) then 'accepted' else 'declined' end;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      update public.tgg_mentorship_requests
      set status=v_status,
          scheduled_at=case when v_status='accepted' then p_scheduled_at else null end,
          updated_at=now()
      where id=p_request_id and mentor_user_id=v_uid and status='requested'
      returning id into v_id;
      if v_id is null then raise exception 'MENTORSHIP_REQUEST_NOT_RESPONDABLE'; end if;
      return jsonb_build_object('ok',true,'request_id',v_id,'status',v_status,'scheduled_at',p_scheduled_at);
    end $function$


-- [40000000961] function public.tgg_migration_archive_export_chunk(p_after_version text, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_migration_archive_export_chunk(p_after_version text DEFAULT NULL::text, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit,25),50));
  v_rows jsonb := '[]'::jsonb;
  v_count integer := 0;
  v_next text := null;
  v_has_more boolean := false;
begin
  with selected as (
    select version,name,statements,created_by,idempotency_key,rollback
    from supabase_migrations.schema_migrations
    where p_after_version is null or version > p_after_version
    order by version
    limit v_limit + 1
  ), numbered as (
    select *, row_number() over(order by version) as rn
    from selected
  ), page as (
    select version,name,statements,created_by,idempotency_key,rollback
    from numbered
    where rn <= v_limit
    order by version
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'version',version,
      'name',name,
      'statements',to_jsonb(statements),
      'created_by',created_by,
      'idempotency_key',idempotency_key,
      'rollback',to_jsonb(rollback)
    ) order by version),'[]'::jsonb),
    count(*)::integer,
    max(version),
    exists(select 1 from numbered where rn > v_limit)
  into v_rows,v_count,v_next,v_has_more
  from page;

  return jsonb_build_object(
    'ok',true,
    'count',v_count,
    'next_after',v_next,
    'has_more',v_has_more,
    'rows',v_rows
  );
end;
$function$


-- [40000000962] function public.tgg_monetization_autopilot()
CREATE OR REPLACE FUNCTION public.tgg_monetization_autopilot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist public.artists;
  v_bridge jsonb;
  v_revenue jsonb;
  v_membership jsonb;
  v_tier jsonb;
  v_active_supporters integer:=0;
  v_merch_products integer:=0;
  v_revenue_cents bigint:=0;
  v_clicks bigint:=0;
  v_followers bigint:=0;
  v_focus_stage text;
  v_plan jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select * into v_artist
  from public.artists
  where user_id=v_uid
  order by created_at
  limit 1;

  if v_artist.id is null then
    return jsonb_build_object(
      'ok',true,
      'version','MONETIZATION-AUTOPILOT-1.0',
      'has_artist_profile',false,
      'plan','[]'::jsonb,
      'generated_at',now()
    );
  end if;

  v_bridge:=public.tgg_growth_revenue_bridge();
  v_revenue:=public.tgg_creator_revenue_summary(30);
  v_membership:=public.tgg_membership_activation_bundle();

  select coalesce(count(*),0) into v_active_supporters
  from public.tgg_memberships
  where artist_id=v_artist.id and status='active';

  select coalesce(count(*),0) into v_merch_products
  from public.merch_products
  where creator_id=v_artist.id;

  v_revenue_cents:=coalesce(round(((v_revenue->>'revenue')::numeric)*100)::bigint,0);
  v_clicks:=coalesce((v_bridge->'audience_signals'->>'smart_link_clicks')::bigint,0);
  v_followers:=coalesce((v_bridge->'audience_signals'->>'followers')::bigint,0);
  v_tier:=coalesce((v_membership->'tiers'->0),'{}'::jsonb);

  v_focus_stage:=case
    when v_active_supporters=0 then 'first_supporter'
    when v_revenue_cents<10000 then 'first_100_dollars'
    when v_merch_products=0 then 'add_second_offer'
    else 'optimize_conversion'
  end;

  v_plan:=jsonb_build_array(
    jsonb_build_object(
      'day',1,'key','membership_cta',
      'title',case when v_active_supporters=0 then 'Push Backstage Supporter' else 'Promote your membership again' end,
      'goal',case when v_active_supporters=0 then 'Get your first paying supporter' else 'Grow recurring supporters' end,
      'action','Add a clear Backstage membership CTA to your strongest artist-profile and release shares.',
      'cta','Open Backstage',
      'route','https://trugogettamixtapes.blogspot.com/p/backstage.html',
      'priority',98
    ),
    jsonb_build_object(
      'day',2,'key','measured_traffic',
      'title','Drive measured traffic',
      'goal','Create monetization data you can trust',
      'action',case when v_clicks=0
        then 'Share your strongest smart link so Growth can connect traffic with supporter outcomes.'
        else 'Repeat the smart-link share that is bringing the strongest measured traffic.' end,
      'cta','Open Growth',
      'workspace','growth',
      'priority',94
    ),
    jsonb_build_object(
      'day',3,'key','backstage_value',
      'title','Give fans a reason to join',
      'goal','Increase membership value',
      'action','Post or prepare one member-only update, early release note, backstage clip, or community drop that makes the membership feel active.',
      'cta','Open Backstage',
      'route','https://trugogettamixtapes.blogspot.com/p/backstage.html',
      'priority',90
    ),
    jsonb_build_object(
      'day',4,'key','first_product',
      'title',case when v_merch_products=0 then 'Create your first product' else 'Promote your strongest product' end,
      'goal',case when v_merch_products=0 then 'Add a second revenue path' else 'Grow commerce revenue' end,
      'action',case when v_merch_products=0
        then 'Create one simple merch or digital product that fits the artist brand. Keep the first offer easy to understand.'
        else 'Feature one product next to your strongest release and membership CTA.' end,
      'cta','Open Creator Store',
      'route','https://trugogettamixtapes.blogspot.com/p/creator-store.html',
      'priority',86
    ),
    jsonb_build_object(
      'day',5,'key','warm_audience',
      'title','Work the warm audience',
      'goal','Convert attention before chasing cold traffic',
      'action',case when v_followers=0
        then 'Focus on earning the first follower and save before pushing harder monetization.'
        else 'Prioritize followers, savers, repeat visitors, and engaged fans for membership or merch promotion.' end,
      'cta','Open Fan CRM',
      'workspace','fans',
      'priority',82
    ),
    jsonb_build_object(
      'day',6,'key','review_conversion',
      'title','Review conversion signals',
      'goal','Find what is actually moving people toward revenue',
      'action','Compare smart-link clicks, followers, saves, active supporters, and paid transactions. Treat ratios as directional until attribution volume grows.',
      'cta','Open Supporters + Revenue',
      'workspace','supporters',
      'priority',76
    ),
    jsonb_build_object(
      'day',7,'key','double_down',
      'title','Double down on the best offer',
      'goal','Repeat what worked',
      'action','Keep the strongest CTA, remove weak messaging, and repeat the best-performing traffic source next week.',
      'cta','Review Growth + Revenue',
      'workspace','supporters',
      'priority',70
    )
  );

  return jsonb_build_object(
    'ok',true,
    'version','MONETIZATION-AUTOPILOT-1.0',
    'artist_id',v_artist.id,
    'focus_stage',v_focus_stage,
    'membership',jsonb_build_object(
      'tier_name',v_tier->>'name',
      'price_cents',coalesce((v_tier->>'price_cents')::integer,0),
      'active',coalesce((v_tier->>'is_active')::boolean,false),
      'checkout_ready',coalesce((v_tier->>'payment_link_verified')::boolean,false)
    ),
    'metrics',jsonb_build_object(
      'active_supporters',v_active_supporters,
      'merch_products',v_merch_products,
      'revenue_30d_cents',v_revenue_cents,
      'smart_link_clicks',v_clicks,
      'followers',v_followers
    ),
    'milestone_progress',v_bridge->'milestone_progress',
    'next_actions',v_bridge->'next_actions',
    'plan',v_plan,
    'generated_at',now()
  );
end
$function$


