-- [40000000964] function public.tgg_observability_refresh()
CREATE OR REPLACE FUNCTION public.tgg_observability_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auto jsonb;
  v_provider jsonb;
  v_train jsonb;
  v_complete jsonb;
  v_speed jsonb;
  v_status text:='healthy';
  v_snapshot jsonb;
  v_id uuid;
begin
  perform public.tgg_provider_health_refresh();

  v_auto:=public.tgg_autonomic_state();
  v_provider:=public.tgg_provider_health_state();
  v_train:=public.tgg_release_train_state();
  v_complete:=public.tgg_autonomic_completeness();
  v_speed:=public.tgg_speed_booster_state();

  if coalesce((v_complete->>'ok')::boolean,false)=false
     or coalesce((v_auto->'scan'->>'restricted')::boolean,false)=true then
    v_status:='restricted';
  elsif coalesce((v_provider->>'degraded')::integer,0)>0
     or coalesce((v_provider->>'blocked')::integer,0)>0
     or coalesce((v_auto->'gaps'->>'open')::integer,0)>0 then
    v_status:='warning';
  end if;

  v_snapshot:=jsonb_build_object(
    'status',v_status,
    'autonomic',v_auto,
    'providers',v_provider,
    'release_train',v_train,
    'completeness',v_complete,
    'speed',v_speed,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223',
    'production_auto_publish',false,
    'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );

  insert into public.tgg_observability_snapshots(status,snapshot)
  values(v_status,v_snapshot)
  returning id into v_id;

  return jsonb_build_object('ok',true,'snapshot_id',v_id,'state',v_snapshot);
end $function$


