-- [40000000966] function public.tgg_one_all_d_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_all_d_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_registry jsonb;
  v_layers integer:=0;
  v_ok boolean;
begin
  v_base:=public.tgg_one_magic_portal_completeness();
  v_registry:=public.tgg_one_dimension_registry_state();

  select count(*) into v_layers
  from public.tgg_one_layers
  where active=true;

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and coalesce((v_registry->>'coverage_ok')::boolean,false)
    and coalesce((v_registry->>'frequency_enabled_count')::integer,1)=0
    and coalesce((v_registry->>'production_authority_count')::integer,1)=0
    and coalesce((v_registry->>'high_risk_authority_count')::integer,1)=0
    and v_layers>=40;

  return jsonb_build_object(
    'ok',v_ok,'base',v_base,'dimension_registry',v_registry,
    'minimum_required_layers',40,'active_total_layers',v_layers,
    'all_d_required',true,'dimensions_registered',65,'max_dimension',64,
    'frequency_model',false,'supernatural_claims',false,
    'canonical_boundary','AB-006','canonical_source_version','V223',
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000000967] function public.tgg_one_animal_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_animal_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_v jsonb:=public.tgg_one_vision_state(); v_e jsonb:=public.tgg_one_ears_state();
v_c jsonb:=public.tgg_one_curse_state(); v_b jsonb:=public.tgg_one_bear_state();
v_l jsonb:=public.tgg_one_lungs_state(); v_score int:=100; v_status text:='calm'; v_id uuid;
begin
  v_score:=greatest(0,least(100,
    100
    -least(30,(coalesce((v_v->>'browser_failures')::int,0)+coalesce((v_v->>'visual_failures')::int,0))*10)
    -least(20,coalesce((v_e->>'open_alerts')::int,0)*10)
    -least(30,coalesce((v_c->>'curse_score')::int,0)/2)
    -least(20,coalesce((v_l->>'pressure_score')::int,0)/2)
    -case when coalesce((v_b->>'guard_score')::int,100)<100 then least(25,100-coalesce((v_b->>'guard_score')::int,100)) else 0 end
  ));
  if coalesce(v_c->>'status','clear')='restricted' or coalesce(v_b->>'status','strong')='restricted' then v_status:='restricted';
  elsif v_score<50 then v_status:='retreat';
  elsif v_score<85 then v_status:='alert'; end if;
  insert into public.tgg_one_animal_snapshots(status,instinct_score,instinct)
  values(v_status,v_score,jsonb_build_object('role','evidence_based_instinct','attack_authority',false,'invent_danger',false,'retreat_when_evidence_bad',true))
  returning id into v_id;
  return jsonb_build_object('ok',true,'snapshot_id',v_id,'status',v_status,'instinct_score',v_score);
end $function$


