-- [40000000969] function public.tgg_one_balance_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_balance_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_lungs jsonb;
  v_curse jsonb;
  v_bear jsonb;
  v_vision jsonb;
  v_train jsonb;
  v_pressure int:=0;
  v_curse_score int:=0;
  v_guard int:=0;
  v_qa int:=0;
  v_active int:=0;
  v_score int:=100;
  v_stride int:=5;
  v_status text:='stable';
  v_id uuid;
begin
  v_lungs:=public.tgg_one_lungs_state();
  v_curse:=public.tgg_one_curse_state();
  v_bear:=public.tgg_one_bear_state();
  v_vision:=public.tgg_one_vision_state();
  v_train:=public.tgg_one_freight_train_state();

  v_pressure:=coalesce((v_lungs->>'pressure_score')::int,0);
  v_curse_score:=coalesce((v_curse->>'curse_score')::int,0);
  v_guard:=coalesce((v_bear->>'guard_score')::int,0);
  v_qa:=coalesce((v_vision->>'browser_failures')::int,0)
       +coalesce((v_vision->>'visual_failures')::int,0)
       +coalesce((v_vision->>'stuck_loading')::int,0)
       +coalesce((v_vision->>'duplicate_shell')::int,0);
  v_active:=coalesce((v_train->>'active_jobs')::int,0);

  v_score:=greatest(0,least(100,
    100
    -least(40,v_pressure/2)
    -least(30,v_curse_score/2)
    -least(20,v_qa*5)
    -case when v_guard<100 then least(30,100-v_guard) else 0 end
  ));

  v_stride:=case
    when v_score>=90 then 20
    when v_score>=75 then 15
    when v_score>=60 then 10
    else 5
  end;

  if v_score<50 or coalesce(v_curse->>'status','clear')='restricted'
     or coalesce(v_bear->>'status','strong')='restricted' then
    v_status:='restricted';
    v_stride:=5;
  elsif v_score<70 then
    v_status:='warning';
  elsif v_score<90 then
    v_status:='watch';
  end if;

  insert into public.tgg_one_balance_snapshots(
    status,pressure_score,curse_score,bear_guard_score,qa_findings,
    active_jobs,balance_score,recommended_stride,equilibrium
  )
  values(
    v_status,v_pressure,v_curse_score,v_guard,v_qa,v_active,v_score,v_stride,
    jsonb_build_object(
      'role','stability_and_brake_control',
      'can_throttle_down',true,
      'can_raise_ceiling',false,
      'fall_prevention','restrict_before_body',
      'production_authority',false,
      'high_risk_authority',false
    )
  ) returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'pressure_score',v_pressure,'curse_score',v_curse_score,
    'bear_guard_score',v_guard,'qa_findings',v_qa,'active_jobs',v_active,
    'balance_score',v_score,'recommended_stride',v_stride
  );
end $function$


