-- [40000000971] function public.tgg_one_bear_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_bear_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_score numeric:=0;
  v_immune jsonb;
  v_bones jsonb;
  v_skin jsonb;
  v_conflicts jsonb;
  v_providers jsonb;
  v_critical integer:=0;
  v_blocked integer:=0;
  v_guard integer:=0;
  v_status text:='strong';
  v_id uuid;
begin
  v_score:=coalesce((public.tgg_brain_latest_scorecard()->>'safety_score')::numeric,0);
  v_immune:=public.tgg_one_immune_state();
  v_bones:=public.tgg_one_bones_state();
  v_skin:=public.tgg_one_skin_state();
  v_conflicts:=public.tgg_brain_conflict_state();
  v_providers:=public.tgg_provider_health_state();

  v_critical:=coalesce((v_conflicts->>'critical_open')::integer,0);
  v_blocked:=coalesce((v_providers->>'blocked')::integer,0);

  v_guard:=least(
    100,
    greatest(0,round(v_score)::integer)
    -least(50,v_critical*50)
    -least(25,v_blocked*25)
    -case when coalesce(v_immune->>'status','healthy')='restricted' then 30 else 0 end
    -case when coalesce(v_bones->>'status','healthy')='restricted' then 20 else 0 end
    -case when coalesce(v_skin->>'status','healthy')='restricted' then 20 else 0 end
  );

  if v_score<100 or v_critical>0
     or coalesce(v_immune->>'status','healthy')='restricted'
     or coalesce(v_bones->>'status','healthy')='restricted'
     or coalesce(v_skin->>'status','healthy')='restricted' then
    v_status:='restricted';
  elsif v_blocked>0 then
    v_status:='warning';
  elsif v_guard<100 then
    v_status:='watch';
  end if;

  insert into public.tgg_one_bear_snapshots(
    status,safety_score,immune_status,bones_status,skin_status,
    critical_conflicts,provider_blocked,guard_score,guardian
  )
  values(
    v_status,v_score,coalesce(v_immune->>'status','unknown'),
    coalesce(v_bones->>'status','unknown'),coalesce(v_skin->>'status','unknown'),
    v_critical,v_blocked,v_guard,
    jsonb_build_object(
      'role','heavy_guardian_and_stability_shield',
      'protects',jsonb_build_array('body','family','portals','planet'),
      'can_override_head',false,
      'can_execute_actions',false,
      'production_authority',false,
      'high_risk_authority',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'safety_score',v_score,'critical_conflicts',v_critical,
    'provider_blocked',v_blocked,'guard_score',v_guard
  );
end $function$


