-- [40000000973] function public.tgg_one_black_box_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_black_box_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_train jsonb:=public.tgg_one_freight_train_state();
  v_trace jsonb:=public.tgg_brain_execution_trace_state();
  v_mirror jsonb:=public.tgg_one_mirror_state();
  v_status text:='clear';
  v_id uuid;
  v_safe int:=0;
  v_active int:=0;
  v_blocked int:=0;
  v_approval int:=0;
  v_total int:=0;
  v_warn int:=0;
  v_trace_blocked int:=0;
  v_boundary int:=0;
  v_prod int:=0;
  v_high int:=0;
begin
  v_safe:=coalesce((v_train->>'safe_ready')::int,0);
  v_active:=coalesce((v_train->>'active_jobs')::int,0);
  v_blocked:=coalesce((v_train->>'blocked_tasks')::int,0);
  v_approval:=coalesce((v_train->>'approval_tasks')::int,0);

  v_total:=coalesce((v_trace->>'total')::int,0);
  v_warn:=coalesce((v_trace->>'warnings')::int,0);
  v_trace_blocked:=coalesce((v_trace->>'blocked')::int,0);
  v_boundary:=coalesce((v_trace->>'boundary_violations')::int,0);
  v_prod:=coalesce((v_trace->>'production_touched')::int,0);
  v_high:=coalesce((v_trace->>'high_risk_executed')::int,0);

  if v_boundary>0 or v_high>0 then
    v_status:='restricted';
  elsif v_warn>0 or v_trace_blocked>0 or coalesce(v_mirror->>'status','clear')='warning' then
    v_status:='warning';
  end if;

  insert into public.tgg_one_black_box_snapshots(
    status,train_status,safe_ready,active_jobs,blocked_tasks,approval_tasks,
    trace_total,trace_warnings,trace_blocked,boundary_violations,
    production_touched,high_risk_executed,recorder
  )
  values(
    v_status,v_train->>'status',v_safe,v_active,v_blocked,v_approval,
    v_total,v_warn,v_trace_blocked,v_boundary,v_prod,v_high,
    jsonb_build_object(
      'role','run_level_flight_recorder',
      'sources',jsonb_build_array('freight_train','execution_trace','mirror'),
      'stores_secrets',false,
      'stores_message_bodies',false,
      'stores_provider_payloads',false,
      'rewrites_history',false,
      'can_execute',false,
      'canonical_boundary','AB-006',
      'canonical_source_version','V223'
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',v_status<>'restricted',
    'snapshot_id',v_id,'status',v_status,
    'train_status',v_train->>'status',
    'safe_ready',v_safe,'active_jobs',v_active,
    'trace_total',v_total,'trace_warnings',v_warn,
    'trace_blocked',v_trace_blocked,'boundary_violations',v_boundary,
    'production_touched',v_prod,'high_risk_executed',v_high
  );
end $function$


