-- [40000000975] function public.tgg_one_bones_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_bones_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_components integer:=0;
  v_required_links integer:=0;
  v_broken integer:=0;
  v_stale integer:=0;
  v_unhealthy integer:=0;
  v_unknown integer:=0;
  v_canonical integer:=0;
  v_status text:='healthy';
  v_arch jsonb;
  v_id uuid;
begin
  v_arch:=public.tgg_brain_architecture_latest();

  select
    count(*) filter(where active=true),
    count(*) filter(where active=true and canonical=true),
    count(*) filter(where active=true and lower(coalesce(health_status,'')) in ('failed','degraded','blocked','unhealthy','error')),
    count(*) filter(where active=true and lower(coalesce(health_status,''))='unknown')
  into v_components,v_canonical,v_unhealthy,v_unknown
  from public.tgg_brain_components;

  v_stale:=coalesce((v_arch->>'stale_components')::integer,0);

  select count(*) into v_required_links
  from public.tgg_brain_component_links l
  join public.tgg_brain_components f on f.id=l.from_component_id
  join public.tgg_brain_components t on t.id=l.to_component_id
  where coalesce(l.required,false)=true
    and f.active=true and t.active=true;

  select count(*) into v_broken
  from public.tgg_brain_component_links l
  left join public.tgg_brain_components f on f.id=l.from_component_id
  left join public.tgg_brain_components t on t.id=l.to_component_id
  where coalesce(l.required,false)=true
    and (
      f.id is null or t.id is null
      or coalesce(f.active,false)=false
      or coalesce(t.active,false)=false
    );

  if v_broken>0 or coalesce((v_arch->>'missing_since_previous')::integer,0)>0 then
    v_status:='restricted';
  elsif v_stale>0 or v_unhealthy>0 then
    v_status:='warning';
  end if;

  insert into public.tgg_one_bones_snapshots(
    status,active_components,active_required_links,broken_required_links,
    stale_components,unhealthy_components,canonical_components,structure
  )
  values(
    v_status,v_components,v_required_links,v_broken,v_stale,v_unhealthy,v_canonical,
    jsonb_build_object(
      'architecture_source','tgg_brain_architecture_latest',
      'unknown_health_components',v_unknown,
      'unknown_is_not_structural_failure',true,
      'required_links_must_land_on_active_components',true,
      'canonical_boundary','AB-006',
      'canonical_source_version','V223'
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'active_components',v_components,'active_required_links',v_required_links,
    'broken_required_links',v_broken,'stale_components',v_stale,
    'unhealthy_components',v_unhealthy,'unknown_health_components',v_unknown,
    'canonical_components',v_canonical
  );
end $function$


