-- [40000000977] function public.tgg_one_breathing_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_breathing_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_missing jsonb:='[]'::jsonb;
  v_layers integer:=0;
  v_lungs jsonb;
  v_metabolism jsonb;
  v_ok boolean;
begin
  v_base:=public.tgg_one_veiled_matrix_completeness();
  v_lungs:=public.tgg_one_lungs_state();
  v_metabolism:=public.tgg_one_metabolism_state();

  if to_regclass('public.tgg_one_lungs_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_one_lungs_snapshots');
  end if;
  if to_regclass('public.tgg_one_metabolism_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_one_metabolism_snapshots');
  end if;

  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname='tgg_one_lungs_refresh') then
    v_missing:=v_missing||jsonb_build_array('function:tgg_one_lungs_refresh');
  end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname='tgg_one_metabolism_refresh') then
    v_missing:=v_missing||jsonb_build_array('function:tgg_one_metabolism_refresh');
  end if;

  select count(*) into v_layers
  from public.tgg_one_layers
  where active=true
    and layer_key in (
      'senses','reflexes','scout','shadow','head','mind','heart','genome','bones','circulation',
      'nervous','immune','lungs','metabolism','muscle','stamina','body','skin','spirit','soul','hair',
      'partner','children','family','veil','matrix_gateway','planet','universe','the_one'
    );

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and jsonb_array_length(v_missing)=0
    and v_layers=29
    and coalesce(v_lungs->>'status','restricted')<>'restricted'
    and coalesce(v_metabolism->>'status','restricted')<>'restricted';

  return jsonb_build_object(
    'ok',v_ok,
    'base',v_base,
    'lungs',v_lungs,
    'metabolism',v_metabolism,
    'required_total_layers',29,
    'active_total_layers',v_layers,
    'lungs_required',true,
    'metabolism_required',true,
    'missing',v_missing,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223',
    'production_auto_publish',false,
    'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000000978] function public.tgg_one_breathing_cycle()
CREATE OR REPLACE FUNCTION public.tgg_one_breathing_cycle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_lungs jsonb;
  v_metabolism jsonb;
  v_core jsonb;
  v_status text:='complete';
begin
  v_lungs:=public.tgg_one_lungs_refresh();
  v_metabolism:=public.tgg_one_metabolism_refresh();

  if v_lungs->>'status'='restricted' or v_metabolism->>'status'='restricted' then
    return jsonb_build_object(
      'name','THE ONE BREATHING MATRIX',
      'status','restricted',
      'lungs',v_lungs,
      'metabolism',v_metabolism,
      'core_cycle_executed',false,
      'reason','breathing_or_energy_gate_restricted',
      'production_change_performed',false
    );
  end if;

  v_core:=public.tgg_one_veiled_matrix_cycle();

  if coalesce(v_core->>'status','complete')='restricted' then
    v_status:='restricted';
  elsif coalesce(v_core->>'status','complete') not in ('complete','healthy') then
    v_status:='warning';
  elsif v_lungs->>'status' in ('warning','loaded')
     or v_metabolism->>'status' in ('warning','loaded') then
    v_status:='warning';
  end if;

  return jsonb_build_object(
    'name','THE ONE BREATHING MATRIX',
    'status',v_status,
    'lungs',v_lungs,
    'metabolism',v_metabolism,
    'core',v_core,
    'flow',jsonb_build_array(
      'IMMUNE SYSTEM',
      'LUNGS / BREATH',
      'ENERGY / METABOLISM',
      'MUSCLE',
      'STAMINA',
      'BODY'
    ),
    'production_auto_publish',false,
    'production_promotion_allowed',false,
    'high_risk_auto_execute',false,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end $function$


-- [40000000979] function public.tgg_one_chester_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_chester_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix jsonb;
  v_lewis jsonb;
  v_veil jsonb;
  v_routes integer:=0;
  v_matrix_ok boolean:=false;
  v_lewis_ok boolean:=false;
  v_veil_ok boolean:=false;
  v_status text:='idle';
  v_id uuid;
begin
  v_matrix:=public.tgg_matrix_gateway_health_state();
  v_lewis:=public.tgg_lewis_portal_health_state();
  v_veil:=public.tgg_veil_health_state();

  v_matrix_ok:=coalesce(v_matrix->>'status','restricted')<>'restricted';
  v_lewis_ok:=coalesce(v_lewis->>'status','restricted')<>'restricted';
  v_veil_ok:=coalesce(v_veil->>'status','restricted')<>'restricted';

  select count(*) into v_routes
  from public.tgg_site_routes
  where is_active=true;

  if not v_veil_ok or not v_matrix_ok or not v_lewis_ok then
    v_status:='restricted';
  elsif v_routes>0 then
    v_status:='guiding';
  end if;

  insert into public.tgg_one_chester_snapshots(
    status,matrix_ready,lewis_ready,veil_ready,route_count,guide
  )
  values(
    v_status,v_matrix_ok,v_lewis_ok,v_veil_ok,v_routes,
    jsonb_build_object(
      'role','original_grinning_portal_guide',
      'copies_branded_character',false,
      'moves_user_automatically',false,
      'offers_route_hints_only',true,
      'route_styles',jsonb_build_array('rabbit_hole','wardrobe_gate','matrix_exit'),
      'veil_required',true
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'matrix_ready',v_matrix_ok,'lewis_ready',v_lewis_ok,
    'veil_ready',v_veil_ok,'route_count',v_routes
  );
end $function$


-- [40000000980] function public.tgg_one_chester_state()
