-- [40000000981] function public.tgg_one_chicken_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_chicken_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_j jsonb:=public.tgg_one_jack_state(); v_b jsonb:=public.tgg_one_balance_state(); v_o jsonb:=public.tgg_one_oracle_state();
v_t jsonb:=public.tgg_one_freight_train_state(); v_conf int:=0; v_status text:='wait'; v_id uuid;
begin
  v_conf:=greatest(0,least(100,
    coalesce((v_b->>'balance_score')::int,0)
    -case when coalesce((v_j->>'review_only')::boolean,false) then 40 else 0 end
    -case when coalesce(v_o->>'status','clear') in ('uncertain','warning') then 20 else 0 end
  ));
  if coalesce(v_b->>'status','stable')='restricted' or coalesce(v_o->>'status','clear')='restricted' then v_status:='restricted';
  elsif coalesce((v_j->>'review_only')::boolean,false) then v_status:='reroute';
  elsif coalesce((v_t->>'safe_ready')::int,0)>0 and v_conf>=80 then v_status:='cross';
  else v_status:='wait'; end if;
  insert into public.tgg_one_chicken_snapshots(status,confidence_score,decision)
  values(v_status,v_conf,jsonb_build_object('role','caution_before_crossing','cross_blindly',false,'wait_when_uncertain',true,'oracle_consulted',true))
  returning id into v_id;
  return jsonb_build_object('ok',true,'snapshot_id',v_id,'status',v_status,'confidence_score',v_conf);
end $function$


