AS $function$ select jsonb_build_object('status',status,'confidence_score',confidence_score,'decision',decision,'sensed_at',sensed_at)
from public.tgg_one_chicken_snapshots order by sensed_at desc limit 1 $function$


-- [40000000983] function public.tgg_one_children_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_children_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_queued integer:=0;
  v_running integer:=0;
  v_finished integer:=0;
  v_failed integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select
    count(*) filter(where status='queued'),
    count(*) filter(where status='running'),
    count(*) filter(where status in ('complete','completed','success','succeeded')),
    count(*) filter(where status in ('failed','error'))
  into v_queued,v_running,v_finished,v_failed
  from public.tgg_autobuilder_agent_jobs;

  if v_failed>0 then
    v_status:='warning';
  elsif v_queued+v_running>0 then
    v_status:='busy';
  end if;

  insert into public.tgg_one_children_snapshots(
    status,queued_children,running_children,finished_children,failed_children,sandbox_only,child_state
  )
  values(
    v_status,v_queued,v_running,v_finished,v_failed,true,
    jsonb_build_object(
      'role','sandbox_child_agents',
      'allowed_environments',jsonb_build_array('development','staging'),
      'production_authority',false,
      'high_risk_authority',false,
      'must_use_parent_guardrails',true,
      'must_report_back',true
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'queued_children',v_queued,'running_children',v_running,
    'finished_children',v_finished,'failed_children',v_failed,'sandbox_only',true
  );
end $function$


