-- [40000000985] function public.tgg_one_choice_exit_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_choice_exit_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb:=public.tgg_one_guarded_motion_completeness();
  v_choice jsonb:=public.tgg_one_choice_health_state();
  v_exit jsonb:=public.tgg_one_exit_state();
  v_layers integer:=0;
  v_guard boolean:=false;
  v_ok boolean;
begin
  select count(*) into v_layers from public.tgg_one_layers where active=true;
  select exists(select 1 from public.tgg_brain_guardrails
    where guardrail_key='guardrail:user-transition-consent'
      and active and immutable and severity='critical' and action='block')
  into v_guard;

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and v_layers>=54
    and v_guard
    and coalesce(v_choice->>'status','restricted')<>'restricted'
    and coalesce(v_exit->>'status','restricted')<>'restricted';

  return jsonb_build_object(
    'ok',v_ok,'base',v_base,'choice',v_choice,'exit',v_exit,
    'user_transition_consent_guardrail',v_guard,
    'minimum_required_layers',54,'active_total_layers',v_layers,
    'user_facing_transition_default_granted',false,
    'safe_backend_automation_can_continue',true,
    'no_forced_transition',true,
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false,
    'canonical_boundary','AB-006','canonical_source_version','V223'
  );
end $function$


