-- [40000000987] function public.tgg_one_choice_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_choice_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_active int:=0; v_granted int:=0; v_denied int:=0; v_status text:='healthy'; v_id uuid;
begin
  select count(*),count(*) filter(where granted),count(*) filter(where not granted)
  into v_active,v_granted,v_denied
  from public.tgg_one_choices
  where updated_at>=now()-interval '30 days';

  if v_active>0 and v_granted=0 then v_status:='waiting'; end if;

  insert into public.tgg_one_choice_snapshots(status,active_choices,granted_choices,denied_choices,choice)
  values(v_status,v_active,v_granted,v_denied,
    jsonb_build_object(
      'role','user_choice_and_consent_boundary',
      'default_granted',false,
      'can_force_user_transition',false,
      'can_override_head',false,
      'no_forcing_evil_guardrail_required',true
    ))
  returning id into v_id;

  return jsonb_build_object('ok',true,'snapshot_id',v_id,'status',v_status,
    'active_choices',v_active,'granted_choices',v_granted,'denied_choices',v_denied);
end $function$


-- [40000000988] function public.tgg_one_choice_set(p_choice_key text, p_granted boolean, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_one_choice_set(p_choice_key text, p_granted boolean, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid();
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if nullif(trim(p_choice_key),'') is null then raise exception 'choice key required'; end if;

  insert into public.tgg_one_choices(owner_user_id,choice_key,granted,metadata,decided_at,updated_at)
  values(v_uid,trim(p_choice_key),coalesce(p_granted,false),coalesce(p_metadata,'{}'::jsonb),now(),now())
  on conflict(owner_user_id,choice_key) do update
  set granted=excluded.granted,metadata=excluded.metadata,decided_at=now(),updated_at=now();

  return jsonb_build_object('ok',true,'choice_key',trim(p_choice_key),'granted',coalesce(p_granted,false));
end $function$


-- [40000000989] function public.tgg_one_choice_state(p_choice_key text)
CREATE OR REPLACE FUNCTION public.tgg_one_choice_state(p_choice_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_row public.tgg_one_choices%rowtype;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select * into v_row
  from public.tgg_one_choices
  where owner_user_id=v_uid and choice_key=trim(p_choice_key);

  if not found then
    return jsonb_build_object('choice_key',trim(p_choice_key),'granted',false,'status','not_decided');
  end if;

  return jsonb_build_object(
    'choice_key',v_row.choice_key,'granted',v_row.granted,'status','decided',
    'decided_at',v_row.decided_at,'metadata',v_row.metadata
  );
end $function$


-- [40000000990] function public.tgg_one_circulation_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_circulation_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_new_events integer:=0;
  v_routed_events integer:=0;
  v_provider_inflight integer:=0;
  v_provider_failed integer:=0;
  v_stale_provider integer:=0;
  v_agent_queued integer:=0;
  v_agent_running integer:=0;
  v_stale_agent integer:=0;
  v_master integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select
    count(*) filter(where status='new'),
    count(*) filter(where status='routed')
  into v_new_events,v_routed_events
  from public.tgg_autonomic_events;

  select
    count(*) filter(where state not in ('succeeded','completed','complete','failed','canceled','cancelled')),
    count(*) filter(where state in ('failed','error','dead_letter')),
    count(*) filter(where state not in ('succeeded','completed','complete','failed','canceled','cancelled')
      and updated_at < now()-interval '15 minutes')
  into v_provider_inflight,v_provider_failed,v_stale_provider
  from public.provider_operations;

  select
    count(*) filter(where status='queued'),
    count(*) filter(where status='running'),
    count(*) filter(where status in ('queued','running')
      and coalesce(started_at,created_at) < now()-interval '15 minutes')
  into v_agent_queued,v_agent_running,v_stale_agent
  from public.tgg_autobuilder_agent_jobs;

  select count(*) into v_master
  from public.tgg_master_change_queue
  where status in ('pending','ready');

  if v_provider_failed>0 then
    v_status:='warning';
  elsif v_stale_provider>0 or v_stale_agent>0 then
    v_status:='warning';
  elsif v_new_events+v_provider_inflight+v_agent_queued+v_agent_running > 50 then
    v_status:='loaded';
  end if;

  insert into public.tgg_one_circulation_snapshots(
    status,new_events,routed_events,provider_inflight,provider_failed,stale_provider_ops,
    agent_queued,agent_running,stale_agent_jobs,pending_master_changes,flow
  )
  values(
    v_status,v_new_events,v_routed_events,v_provider_inflight,v_provider_failed,v_stale_provider,
    v_agent_queued,v_agent_running,v_stale_agent,v_master,
    jsonb_build_object(
      'event_flow','tgg_autonomic_events',
      'provider_flow','provider_operations',
      'builder_flow','tgg_autobuilder_agent_jobs',
      'master_changes_are_approval_gated',true,
      'production_change_performed',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'new_events',v_new_events,'routed_events',v_routed_events,
    'provider_inflight',v_provider_inflight,'provider_failed',v_provider_failed,
    'stale_provider_ops',v_stale_provider,'agent_queued',v_agent_queued,
    'agent_running',v_agent_running,'stale_agent_jobs',v_stale_agent,
    'pending_master_changes',v_master
  );
end $function$


