-- [40000000992] function public.tgg_one_clock_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_clock_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_active int:=0; v_running int:=0; v_failed int:=0; v_minute int:=0;
  v_status text:='healthy'; v_id uuid;
begin
  select count(*) filter(where active=true),
         count(*) filter(where active=true and schedule='* * * * *')
    into v_active,v_minute
  from cron.job;

  select count(*) filter(where status='running'),
         count(*) filter(where status not in ('succeeded','running'))
    into v_running,v_failed
  from cron.job_run_details
  where start_time>=now()-interval '1 hour';

  if v_failed>0 then v_status:='warning';
  elsif v_running>8 then v_status:='busy';
  end if;

  insert into public.tgg_one_clock_snapshots(
    status,active_crons,running_recent,failed_recent,minute_jobs,cadence
  ) values (
    v_status,v_active,v_running,v_failed,v_minute,
    jsonb_build_object(
      'role','cadence_and_schedule_coordination',
      'recommended_concurrent_job_ceiling',8,
      'minute_heartbeat','tgg-autonomic-os-minute-loop',
      'dream_cycle','47 */6 * * *',
      'prevent_schedule_pileups',true,
      'auto_reschedule_existing_jobs',false
    )
  ) returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'active_crons',v_active,'running_recent',v_running,
    'failed_recent',v_failed,'minute_jobs',v_minute
  );
end $function$


