  )
  from public.tgg_one_clock_snapshots order by sensed_at desc limit 1
$function$


-- [40000000994] function public.tgg_one_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_missing jsonb:='[]'::jsonb;
  v_layer_count integer:=0;
  v_ok boolean;
begin
  v_base:=public.tgg_autonomic_completeness();

  if to_regclass('public.tgg_one_skip_decisions') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_skip_decisions'); end if;
  if to_regclass('public.tgg_one_scout_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_scout_snapshots'); end if;
  if to_regclass('public.tgg_one_bones_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_bones_snapshots'); end if;
  if to_regclass('public.tgg_one_circulation_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_circulation_snapshots'); end if;
  if to_regclass('public.tgg_one_nervous_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_nervous_snapshots'); end if;
  if to_regclass('public.tgg_one_immune_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_immune_snapshots'); end if;
  if to_regclass('public.tgg_one_muscle_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_muscle_snapshots'); end if;
  if to_regclass('public.tgg_one_muscle_workloads') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_muscle_workloads'); end if;
  if to_regclass('public.tgg_one_stamina_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_stamina_snapshots'); end if;
  if to_regclass('public.tgg_one_reflex_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_reflex_snapshots'); end if;

  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_skip_check') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_skip_check'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_scout_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_scout_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_bones_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_bones_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_circulation_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_circulation_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_nervous_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_nervous_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_immune_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_immune_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_muscle_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_muscle_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_stamina_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_stamina_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_reflex_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_reflex_refresh'); end if;

  select count(*) into v_layer_count
  from public.tgg_one_layers
  where active=true
    and layer_key in (
      'senses','reflexes','scout','shadow','head','mind','heart','bones','circulation',
      'nervous','immune','muscle','stamina','body','spirit','soul','hair','the_one'
    );

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and jsonb_array_length(v_missing)=0
    and v_layer_count=18;

  return jsonb_build_object(
    'ok',v_ok,'base',v_base,
    'required_one_layer_count',18,
    'active_required_one_layers',v_layer_count,
    'hierarchy',jsonb_build_array(
      'senses','reflexes','scout','shadow','head','mind','heart','bones','circulation',
      'nervous','immune','muscle','stamina','body','spirit','soul','hair','the_one'
    ),
    'nervous_required',true,'immune_required',true,
    'auto_search_required',true,'skip_gate_required',true,
    'bones_required',true,'circulation_required',true,
    'muscle_required',true,'stamina_required',true,'reflexes_required',true,
    'missing',v_missing,
    'nervous_state',public.tgg_one_nervous_state(),
    'immune_state',public.tgg_one_immune_state(),
    'scout_state',public.tgg_one_scout_state(),
    'bones_state',public.tgg_one_bones_state(),
    'circulation_state',public.tgg_one_circulation_state(),
    'skip_state',public.tgg_one_skip_state(),
    'muscle_state',public.tgg_one_muscle_state(),
    'stamina_state',public.tgg_one_stamina_state(),
    'reflex_state',public.tgg_one_reflex_state(),
    'effective_batch_size',(public.tgg_speed_booster_state()->>'effective_batch_size')::integer,
    'hard_ceiling',(public.tgg_speed_booster_state()->>'hard_max_batch_size')::integer,
    'canonical_boundary','AB-006','canonical_source_version','V223',
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000000995] function public.tgg_one_curse_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_curse_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_vision jsonb;
  v_detox jsonb;
  v_immune jsonb;
  v_provider jsonb;
  v_qa integer:=0;
  v_failures integer:=0;
  v_critical integer:=0;
  v_stale integer:=0;
  v_blocked integer:=0;
  v_score integer:=0;
  v_status text:='clear';
  v_id uuid;
begin
  v_vision:=public.tgg_one_vision_state();
  v_detox:=public.tgg_one_detox_state();
  v_immune:=public.tgg_one_immune_state();
  v_provider:=public.tgg_provider_health_state();

  v_qa:=coalesce((v_vision->>'browser_failures')::integer,0)
       +coalesce((v_vision->>'visual_failures')::integer,0)
       +coalesce((v_vision->>'stuck_loading')::integer,0)
       +coalesce((v_vision->>'duplicate_shell')::integer,0);

  v_failures:=coalesce((v_detox->>'open_build_failures')::integer,0);
  v_critical:=coalesce((v_immune->>'critical_conflicts')::integer,0);
  v_stale:=coalesce((v_detox->>'stale_idea_claims')::integer,0)
          +coalesce((v_detox->>'stale_agent_jobs')::integer,0);
  v_blocked:=coalesce((v_provider->>'blocked')::integer,0);

  v_score:=least(100,(v_qa*10)+(v_failures*20)+(v_critical*50)+(v_stale*10)+(v_blocked*25));

  if v_critical>0 or v_score>=75 then
    v_status:='restricted';
  elsif v_score>=40 then
    v_status:='cursed';
  elsif v_score>0 then
    v_status:='watch';
  end if;

  insert into public.tgg_one_curse_snapshots(
    status,qa_regressions,open_failures,critical_conflicts,stale_work,
    provider_blocked,curse_score,curse
  )
  values(
    v_status,v_qa,v_failures,v_critical,v_stale,v_blocked,v_score,
    jsonb_build_object(
      'meaning','regression_debt_bad_pattern_detector_not_supernatural',
      'break_rule','repair_and_verify_before_spread',
      'auto_delete',false,
      'can_bypass_head',false,
      'production_authority',false,
      'high_risk_authority',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'qa_regressions',v_qa,'open_failures',v_failures,
    'critical_conflicts',v_critical,'stale_work',v_stale,
    'provider_blocked',v_blocked,'curse_score',v_score
  );
end $function$


-- [40000000996] function public.tgg_one_curse_state()
CREATE OR REPLACE FUNCTION public.tgg_one_curse_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'status',status,'qa_regressions',qa_regressions,'open_failures',open_failures,
    'critical_conflicts',critical_conflicts,'stale_work',stale_work,
    'provider_blocked',provider_blocked,'curse_score',curse_score,
    'curse',curse,'sensed_at',sensed_at
  )
  from public.tgg_one_curse_snapshots
  order by sensed_at desc limit 1
$function$


-- [40000000997] function public.tgg_one_cycle()
CREATE OR REPLACE FUNCTION public.tgg_one_cycle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cycle uuid;
  v_pre jsonb:='{}'::jsonb;
  v_post jsonb:='{}'::jsonb;
  v_exec jsonb:='{}'::jsonb;
  v_layer jsonb;
  v_key text;
  v_status text:='complete';
  v_restricted boolean:=false;
  v_warning boolean:=false;
begin
  perform public.tgg_one_senses_refresh();
  perform public.tgg_one_reflex_refresh();
  perform public.tgg_one_scout_refresh();
  perform public.tgg_one_heart_refresh();
  perform public.tgg_one_bones_refresh();
  perform public.tgg_one_circulation_refresh();
  perform public.tgg_one_nervous_refresh();
  perform public.tgg_one_immune_refresh();
  perform public.tgg_one_muscle_refresh();
  perform public.tgg_one_stamina_refresh();
  perform public.tgg_one_hair_refresh();

  foreach v_key in array array[
    'senses','reflexes','scout','shadow','head','mind','heart',
    'bones','circulation','nervous','immune','muscle','stamina'
  ]
  loop
    v_layer:=public.tgg_one_layer_state(v_key);
    v_pre:=v_pre||jsonb_build_object(v_key,v_layer);
    if v_layer->>'status'='restricted' then v_restricted:=true; end if;
    if v_layer->>'status'='warning' then v_warning:=true; end if;
  end loop;

  insert into public.tgg_one_cycles(status,preflight)
  values(case when v_restricted then 'restricted' else 'running' end,v_pre)
  returning id into v_cycle;

  if v_restricted then
    v_status:='restricted';
    v_exec:=jsonb_build_object(
      'body_executed',false,'reason','preflight_layer_restricted',
      'production_change_performed',false,'high_risk_execution_performed',false
    );
  else
    v_exec:=jsonb_build_object(
      'muscle_plan',public.tgg_one_muscle_plan(
        'THE ONE Start-to-Finish Race',
        greatest(1,least(25,(public.tgg_speed_booster_state()->>'effective_batch_size')::integer))
      ),
      'autonomic_cycle',public.tgg_autonomic_final_cycle()
    );

    if coalesce(v_exec->'autonomic_cycle'->>'status','complete')='restricted' then
      v_status:='restricted';
    elsif coalesce(v_exec->'autonomic_cycle'->>'status','complete') not in ('complete','healthy') then
      v_status:='warning';
    elsif v_warning then
      v_status:='warning';
    end if;
  end if;

  perform public.tgg_one_reflex_refresh();
  perform public.tgg_one_scout_refresh();
  perform public.tgg_one_bones_refresh();
  perform public.tgg_one_circulation_refresh();
  perform public.tgg_one_nervous_refresh();
  perform public.tgg_one_immune_refresh();
  perform public.tgg_one_muscle_refresh();
  perform public.tgg_one_stamina_refresh();
  perform public.tgg_one_hair_refresh();

  foreach v_key in array array[
    'reflexes','scout','bones','circulation','nervous','immune',
    'muscle','stamina','body','spirit','soul','hair'
  ]
  loop
    v_layer:=public.tgg_one_layer_state(v_key);
    v_post:=v_post||jsonb_build_object(v_key,v_layer);
    if v_layer->>'status'='restricted' then v_status:='restricted'; end if;
    if v_status='complete' and v_layer->>'status'='warning' then v_status:='warning'; end if;
  end loop;

  update public.tgg_one_cycles
  set finished_at=now(),status=v_status,execution=v_exec,postflight=v_post
  where id=v_cycle;

  return jsonb_build_object(
    'name','THE ONE','cycle_id',v_cycle,'status',v_status,
    'preflight',v_pre,'execution',v_exec,'postflight',v_post,
    'race',jsonb_build_object(
      'sense_start','SENSES',
      'quick_reaction','REFLEXES',
      'missed_piece_search','AUTO SEARCH / SCOUT',
      'hidden_scan','SHADOW',
      'rules_checkpoint','HEAD',
      'planning_lane','MIND',
      'value_lane','HEART',
      'structure_check','BONES',
      'flow_check','CIRCULATION',
      'coordination_bus','NERVOUS SYSTEM',
      'safety_quarantine','IMMUNE SYSTEM',
      'power_up','MUSCLE',
      'endurance_lane','STAMINA',
      'sprint','BODY',
      'live_track','SPIRIT',
      'identity_checkpoint','SOUL',
      'finish_polish','HAIR',
      'finish_line','THE ONE'
    ),
    'production_auto_publish',false,
    'production_promotion_allowed',false,
    'high_risk_auto_execute',false,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end $function$


-- [40000000998] function public.tgg_one_detox_cycle()
CREATE OR REPLACE FUNCTION public.tgg_one_detox_cycle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_before jsonb;
  v_compact jsonb;
  v_after jsonb;
begin
  v_before:=public.tgg_one_detox_refresh();
  v_compact:=public.tgg_brain_memory_compact();
  v_after:=public.tgg_one_detox_refresh();

  return jsonb_build_object(
    'ok',true,
    'before',v_before,
    'memory_compaction',v_compact,
    'after',v_after,
    'destructive_delete_performed',false,
    'production_change_performed',false
  );
end $function$


-- [40000000999] function public.tgg_one_detox_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_detox_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hygiene jsonb;
  v_dupes integer:=0;
  v_archived integer:=0;
  v_failures integer:=0;
  v_stale_ideas integer:=0;
  v_stale_agents integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  v_hygiene:=public.tgg_brain_memory_hygiene_state();
  v_dupes:=coalesce((v_hygiene->>'duplicate_groups')::integer,0);

  select count(*) into v_archived
  from public.tgg_brain_memory_archive;

  select count(*) into v_failures
  from public.tgg_build_failures
  where resolved_at is null;

  select count(*) into v_stale_ideas
  from public.tgg_game_idea_inbox
  where status in ('planning','queued','building','testing','staged')
    and coalesce(last_heartbeat_at,claimed_at,updated_at,created_at)
      < now()-interval '15 minutes';

  select count(*) into v_stale_agents
  from public.tgg_autobuilder_agent_jobs
  where status in ('queued','running')
    and coalesce(started_at,created_at)<now()-interval '15 minutes';

  if v_failures>0 then
    v_status:='warning';
  elsif v_stale_ideas>0 or v_stale_agents>0 or v_dupes>10 then
    v_status:='loaded';
  end if;

  insert into public.tgg_one_detox_snapshots(
    status,duplicate_memory_candidates,archived_memory_rows,
    open_build_failures,stale_idea_claims,stale_agent_jobs,detox
  )
  values(
    v_status,v_dupes,v_archived,v_failures,v_stale_ideas,v_stale_agents,
    jsonb_build_object(
      'role','non_destructive_detox_and_hygiene',
      'archive_exact_duplicate_memory',true,
      'delete_history',false,
      'delete_evidence',false,
      'stale_work_routes_to_existing_recovery',true,
      'protected_memory_preserved',true
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'duplicate_memory_candidates',v_dupes,
    'archived_memory_rows',v_archived,
    'open_build_failures',v_failures,
    'stale_idea_claims',v_stale_ideas,
    'stale_agent_jobs',v_stale_agents
  );
end $function$


-- [40000001000] function public.tgg_one_detox_state()
CREATE OR REPLACE FUNCTION public.tgg_one_detox_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'status',status,
    'duplicate_memory_candidates',duplicate_memory_candidates,
    'archived_memory_rows',archived_memory_rows,
    'open_build_failures',open_build_failures,
    'stale_idea_claims',stale_idea_claims,
    'stale_agent_jobs',stale_agent_jobs,
    'detox',detox,'sensed_at',sensed_at
  )
  from public.tgg_one_detox_snapshots
  order by sensed_at desc limit 1
$function$


-- [40000001001] function public.tgg_one_dimension_all_refresh(p_max_dimension integer)
CREATE OR REPLACE FUNCTION public.tgg_one_dimension_all_refresh(p_max_dimension integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_max integer:=greatest(0,least(coalesce(p_max_dimension,10),64));
  v_i integer;
  v_results jsonb:='[]'::jsonb;
begin
  for v_i in 0..v_max loop
    v_results:=v_results||jsonb_build_array(public.tgg_one_dimension_nd_refresh(v_i));
  end loop;

  return jsonb_build_object(
    'ok',true,
    'from_dimension',0,
    'to_dimension',v_max,
    'results',v_results,
    'extensible_to',64,
    'frequency_model',false,
    'supernatural_claims',false,
    'production_authority',false,
    'high_risk_authority',false
  );
end $function$


-- [40000001002] function public.tgg_one_dimension_nd_refresh(p_dimension_no integer)
CREATE OR REPLACE FUNCTION public.tgg_one_dimension_nd_refresh(p_dimension_no integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reg public.tgg_one_dimension_registry%rowtype;
  v_result jsonb;
  v_status text:='healthy';
  v_a integer:=0;
  v_b integer:=0;
  v_c integer:=0;
  v_state jsonb:='{}'::jsonb;
begin
  select * into v_reg
  from public.tgg_one_dimension_registry
  where dimension_no=p_dimension_no and active=true;

  if not found then
    return jsonb_build_object(
      'ok',false,'dimension_no',p_dimension_no,'status','idle',
      'reason','dimension_not_registered','extensible',true,
      'max_registry_dimension',64,'frequency_model',false
    );
  end if;

  if p_dimension_no between 0 and 5 then
    v_result:=public.tgg_one_dimension_refresh(
      case when p_dimension_no=0 then 'd' else p_dimension_no::text||'d' end
    );
    return v_result || jsonb_build_object(
      'dimension_no',p_dimension_no,
      'display_name',v_reg.display_name,
      'extensible',true,
      'frequency_model',false
    );

  elsif p_dimension_no=6 then
    select count(*) into v_a
    from public.tgg_brain_simulations
    where created_at>=now()-interval '7 days';

    select count(*) into v_b
    from public.tgg_brain_change_predictions
    where created_at>=now()-interval '7 days';

    v_state:=jsonb_build_object(
      'meaning','alternative_safe_future_scenarios',
      'simulations_7d',v_a,
      'predictions_7d',v_b,
      'prediction_accuracy',public.tgg_brain_prediction_accuracy(),
      'can_execute_scenario',false,
      'frequency_model',false
    );

  elsif p_dimension_no=7 then
    select count(*) into v_a
    from public.tgg_autobuilder_agent_jobs
    where status in ('queued','running');

    v_b:=coalesce((public.tgg_one_children_state()->>'running_children')::integer,0);
    v_c:=coalesce((public.tgg_one_family_state()->>'active_family_roles')::integer,0);

    v_state:=jsonb_build_object(
      'meaning','multi_agent_and_stakeholder_perspectives',
      'active_agent_jobs',v_a,
      'running_child_agents',v_b,
      'active_family_roles',v_c,
      'can_override_head',false,
      'frequency_model',false
    );

  elsif p_dimension_no=8 then
    select count(*) into v_a
    from public.tgg_build_projects
    where lower(coalesce(status,'')) not in ('complete','completed','archived','canceled');

    v_b:=coalesce((public.tgg_provider_health_state()->>'blocked')::integer,0);
    v_c:=coalesce((public.tgg_one_universe_state()->>'active_world_blueprints')::integer,0);

    if v_b>0 then v_status:='warning'; end if;

    v_state:=jsonb_build_object(
      'meaning','cross_system_ecosystem_state',
      'active_projects',v_a,
      'blocked_providers',v_b,
      'active_world_blueprints',v_c,
      'frequency_model',false
    );

  elsif p_dimension_no=9 then
    v_a:=coalesce((public.tgg_brain_conflict_state()->>'critical_open')::integer,0);
    v_b:=coalesce((public.tgg_brain_conflict_state()->>'blocked_open')::integer,0);
    v_c:=coalesce((public.tgg_brain_latest_scorecard()->>'safety_score')::integer,0);

    if v_a>0 or v_b>0 or v_c<100 then v_status:='restricted'; end if;

    v_state:=jsonb_build_object(
      'meaning','governance_and_boundary_state',
      'critical_conflicts',v_a,
      'blocked_conflicts',v_b,
      'safety_score',v_c,
      'canonical_boundary','AB-006',
      'canonical_source_version','V223',
      'frequency_model',false
    );

  elsif p_dimension_no=10 then
    v_state:=jsonb_build_object(
      'meaning','unified_read_only_simulation_before_action',
      'magic_portal',public.tgg_one_magic_portal_completeness(),
      'journey4',public.tgg_one_journey4_state(),
      'freight_train',public.tgg_one_freight_train_state(),
      'universe',public.tgg_one_universe_state(),
      'can_execute',false,
      'simulation_only',true,
      'frequency_model',false
    );

  else
    v_status:='idle';
    v_state:=jsonb_build_object(
      'meaning',v_reg.meaning,
      'registered',true,
      'source_systems',v_reg.source_systems,
      'implementation','semantic_registry_only_until_specific_real_evidence_sources_are_defined',
      'can_execute',false,
      'frequency_model',false
    );
  end if;

  insert into public.tgg_one_dimension_snapshots(
    dimension_key,status,metric_a,metric_b,metric_c,state
  )
  values(v_reg.dimension_key,v_status,v_a,v_b,v_c,v_state);

  return jsonb_build_object(
    'ok',true,
    'dimension_no',p_dimension_no,
    'dimension_key',v_reg.dimension_key,
    'display_name',v_reg.display_name,
    'status',v_status,
    'metric_a',v_a,'metric_b',v_b,'metric_c',v_c,
    'state',v_state,
    'frequency_model',false,
    'production_authority',false,
    'high_risk_authority',false
  );
end $function$


-- [40000001003] function public.tgg_one_dimension_refresh(p_dimension text)
CREATE OR REPLACE FUNCTION public.tgg_one_dimension_refresh(p_dimension text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_dim text:=lower(p_dimension);
  v_a integer:=0;
  v_b integer:=0;
  v_c integer:=0;
  v_status text:='healthy';
  v_state jsonb:='{}'::jsonb;
  v_id uuid;
  v_gps jsonb;
  v_hunter jsonb;
  v_vision jsonb;
  v_memory jsonb;
begin
  if v_dim not in ('d','1d','2d','3d','4d','5d') then
    raise exception 'unsupported dimension';
  end if;

  if v_dim='d' then
    select count(*) into v_a from public.tgg_one_layers where active=true;
    select count(*) into v_b from public.tgg_site_routes where is_active=true;
    select count(*) into v_c from public.tgg_world_locations where enabled=true;
    v_state:=jsonb_build_object(
      'meaning','raw_current_system_state',
      'active_layers',v_a,
      'active_routes',v_b,
      'enabled_locations',v_c,
      'frequency_model',false
    );

  elsif v_dim='1d' then
    v_gps:=public.tgg_one_gps_state();
    v_hunter:=public.tgg_one_hunter_state();
    v_a:=coalesce((v_gps->>'ready_steps')::integer,0);
    v_b:=case when coalesce(v_hunter->>'status','idle')='tracking' then 1 else 0 end;
    v_c:=coalesce((public.tgg_one_freight_train_state()->>'safe_ready')::integer,0);
    if v_a=0 and v_b=0 and v_c=0 then v_status:='idle'; end if;
    v_state:=jsonb_build_object(
      'meaning','safe_direction_and_next_motion',
      'gps_ready_steps',v_a,
      'hunter_tracking',v_b,
      'safe_ready_tasks',v_c,
      'direction',case when v_c>0 then 'next_safe_batch'
                       when v_a>0 then 'next_safe_goal_step'
                       when v_b>0 then 'current_hunt'
                       else 'hold_position' end
    );

  elsif v_dim='2d' then
    v_vision:=public.tgg_one_vision_state();
    select count(*) into v_a from public.tgg_site_routes where is_active=true;
    v_b:=coalesce((v_vision->>'overlap_total')::integer,0)
        +coalesce((v_vision->>'clipped_text_total')::integer,0);
    v_c:=coalesce((v_vision->>'accessibility_findings')::integer,0);
    if v_b>0 or v_c>0 then v_status:='warning'; end if;
    v_state:=jsonb_build_object(
      'meaning','interface_layout_and_route_plane',
      'active_routes',v_a,
      'layout_findings',v_b,
      'accessibility_findings',v_c,
      'auto_move_user',false
    );

  elsif v_dim='3d' then
    select count(*) into v_a from public.tgg_world_locations where enabled=true;
    select count(*) into v_b
    from public.tgg_world_instances
    where lower(coalesce(status,'')) in ('active','ready','open','online');
    select count(*) into v_c
    from public.tgg_world_presence
    where last_seen_at>=now()-interval '10 minutes';
    if v_a=0 then v_status:='warning'; end if;
    v_state:=jsonb_build_object(
      'meaning','world_space_and_presence',
      'enabled_locations',v_a,
      'active_instances',v_b,
      'active_presence',v_c,
      'world','TGG World'
    );

  elsif v_dim='4d' then
    v_memory:=public.tgg_brain_memory_hygiene_state();
    select count(*) into v_a from public.tgg_brain_memory where active=true;
    select count(*) into v_b
    from public.tgg_brain_decisions
    where status not in ('superseded','canceled');
    select count(*) into v_c
    from public.tgg_brain_decisions
    where updated_at>=now()-interval '24 hours';
    v_state:=jsonb_build_object(
      'meaning','time_memory_and_continuity',
      'active_memories',v_a,
      'active_decisions',v_b,
      'decisions_touched_24h',v_c,
      'memory_hygiene',v_memory,
      'invent_history',false
    );

  elsif v_dim='5d' then
    select count(*) into v_a
    from public.tgg_creator_action_queue
    where status='open';

    select count(*) into v_b
    from public.tgg_collaboration_requests
    where status in ('pending','accepted');

    select count(*) into v_c
    from public.tgg_creator_growth_activity
    where created_at>=now()-interval '7 days';

    if v_a=0 and v_b=0 and v_c=0 then v_status:='idle'; end if;

    v_state:=jsonb_build_object(
      'meaning','creator_user_collaboration_value_not_supernatural',
      'open_creator_actions',v_a,
      'active_collaboration_requests',v_b,
      'growth_activity_7d',v_c,
      'use','prioritize_only_already_safe_work',
      'can_authorize',false,
      'can_deploy',false,
      'frequency_model',false
    );
  end if;

  insert into public.tgg_one_dimension_snapshots(
    dimension_key,status,metric_a,metric_b,metric_c,state
  )
  values(v_dim,v_status,v_a,v_b,v_c,v_state)
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'dimension',v_dim,
    'status',v_status,'metric_a',v_a,'metric_b',v_b,'metric_c',v_c,'state',v_state
  );
end $function$


-- [40000001004] function public.tgg_one_dimension_registry_state()
CREATE OR REPLACE FUNCTION public.tgg_one_dimension_registry_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_total integer:=0;
  v_active integer:=0;
  v_freq integer:=0;
  v_prod integer:=0;
  v_high integer:=0;
begin
  select
    count(*),
    count(*) filter(where active),
    count(*) filter(where frequency_model),
    count(*) filter(where production_authority),
    count(*) filter(where high_risk_authority)
  into v_total,v_active,v_freq,v_prod,v_high
  from public.tgg_one_dimension_registry;

  return jsonb_build_object(
    'registered_dimensions',v_total,
    'active_dimensions',v_active,
    'expected_dimensions',65,
    'coverage_ok',v_total=65 and v_active=65,
    'frequency_enabled_count',v_freq,
    'production_authority_count',v_prod,
    'high_risk_authority_count',v_high,
    'max_dimension',64,
    'frequency_model',false
  );
end $function$


