  'excessive_matrix_steps',excessive_matrix_steps,
  'excessive_lewis_steps',excessive_lewis_steps,
  'duplicate_active_sessions',duplicate_active_sessions,
  'breaker',breaker,
  'sensed_at',sensed_at
)
from public.tgg_one_double_matrix_snapshots
order by sensed_at desc limit 1
$function$


-- [40000001010] function public.tgg_one_dream_cycle()
