-- [40000001012] function public.tgg_one_ears_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_ears_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_messages integer:=0;
  v_live integer:=0;
  v_events integer:=0;
  v_provider integer:=0;
  v_open integer:=0;
  v_critical integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select count(*) into v_messages
  from public.tgg_messages
  where created_at>=now()-interval '15 minutes';

  select count(*) into v_live
  from public.tgg_live_chat_messages
  where created_at>=now()-interval '15 minutes';

  select count(*) into v_events
  from public.tgg_autonomic_events
  where created_at>=now()-interval '15 minutes';

  select count(*) into v_provider
  from public.provider_operations
  where updated_at>=now()-interval '15 minutes';

  select
    count(*) filter(where status='open'),
    count(*) filter(where status='open' and severity='critical')
  into v_open,v_critical
  from public.tgg_operational_alerts;

  if v_critical>0 then
    v_status:='restricted';
  elsif v_open>0 then
    v_status:='warning';
  elsif v_messages+v_live+v_events+v_provider>50 then
    v_status:='busy';
  end if;

  insert into public.tgg_one_ears_snapshots(
    status,messages_15m,live_chat_15m,autonomic_events_15m,
    provider_updates_15m,open_alerts,critical_alerts,listening
  )
  values(
    v_status,v_messages,v_live,v_events,v_provider,v_open,v_critical,
    jsonb_build_object(
      'role','privacy_safe_signal_listening',
      'counts_only',true,
      'message_bodies_read',false,
      'live_chat_bodies_read',false,
      'provider_payloads_read',false,
      'listen_sources',jsonb_build_array(
        'messages','live_chat','autonomic_events','provider_operations','operational_alerts'
      ),
      'can_execute_actions',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'messages_15m',v_messages,'live_chat_15m',v_live,
    'autonomic_events_15m',v_events,'provider_updates_15m',v_provider,
    'open_alerts',v_open,'critical_alerts',v_critical
  );
end $function$


