-- [40000001014] function public.tgg_one_elevator_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_elevator_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_j jsonb:=public.tgg_one_journey4_state(); v_c jsonb:=public.tgg_one_chicken_state(); v_v jsonb:=public.tgg_veil_health_state();
v_target text; v_auth boolean:=false; v_clear boolean:=false; v_status text:='idle'; v_id uuid;
begin
  v_target:=case coalesce((v_j->>'stage_no')::int,4) when 1 then 'discover' when 2 then 'prepare' when 3 then 'traverse' else 'verify_return' end;
  v_auth:=coalesce(v_v->>'status','restricted')<>'restricted';
  v_clear:=coalesce(v_c->>'status','wait')<>'restricted';
  if not v_auth then v_status:='restricted';
  elsif coalesce(v_c->>'status','wait')='cross' then v_status:='moving';
  elsif coalesce(v_j->>'status','complete')='complete' then v_status:='ready'; end if;
  insert into public.tgg_one_elevator_snapshots(status,current_level,target_level,target_authorized,path_clear,elevator)
  values(v_status,'creator_os',v_target,v_auth,v_clear,jsonb_build_object('role','authorized_level_transition','moves_user_automatically',false,'requires_veil',true,'requires_chicken_caution',true))
  returning id into v_id;
  return jsonb_build_object('ok',true,'snapshot_id',v_id,'status',v_status,'target_level',v_target,'target_authorized',v_auth,'path_clear',v_clear);
end $function$


