from public.tgg_one_elevator_snapshots order by sensed_at desc limit 1 $function$


-- [40000001016] function public.tgg_one_exit_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_exit_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix boolean:=false;
  v_lewis boolean:=false;
  v_creator boolean:=false;
  v_status text:='ready';
  v_id uuid;
begin
  select exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname='tgg_matrix_gateway_exit') into v_matrix;
  select exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname='tgg_lewis_portal_exit') into v_lewis;
  select exists(select 1 from public.tgg_site_routes where route_key='artist_creator_os' and is_active=true) into v_creator;

  if not v_creator then v_status:='restricted';
  elsif not v_matrix or not v_lewis then v_status:='warning'; end if;

  insert into public.tgg_one_exit_snapshots(status,matrix_exit_ready,lewis_exit_ready,creator_os_route_ready,exit_state)
  values(v_status,v_matrix,v_lewis,v_creator,
    jsonb_build_object(
      'role','safe_return_and_emergency_exit',
      'preferred_return_route','artist_creator_os',
      'user_choice_required',true,
      'auto_force_exit',false,
      'can_bypass_veil',false,
      'can_destroy_session_history',false
    ))
  returning id into v_id;

  return jsonb_build_object('ok',true,'snapshot_id',v_id,'status',v_status,
    'matrix_exit_ready',v_matrix,'lewis_exit_ready',v_lewis,'creator_os_route_ready',v_creator);
end $function$


