-- [40000001018] function public.tgg_one_family_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_family_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_roles integer:=0;
  v_goals integer:=0;
  v_children integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select count(*) into v_roles
  from public.tgg_one_layers
  where active=true;

  select count(*) into v_goals
  from public.tgg_brain_goals
  where status not in ('complete','completed','canceled');

  select count(*) into v_children
  from public.tgg_autobuilder_agent_jobs
  where status in ('queued','running');

  if v_children>0 then
    v_status:='busy';
  end if;

  insert into public.tgg_one_family_snapshots(
    status,active_family_roles,open_shared_goals,child_agents_active,family_state
  )
  values(
    v_status,v_roles,v_goals,v_children,
    jsonb_build_object(
      'shared_rules',jsonb_build_array(
        'everyone_uses_same_guardrails','no_duplicate_systems','report_back_to_the_one',
        'safe_dev_staging_only_for_children','shared_memory_and_goals'
      ),
      'family_members',jsonb_build_array('the_one','partner','children','all_core_layers'),
      'production_authority',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'active_family_roles',v_roles,'open_shared_goals',v_goals,'child_agents_active',v_children
  );
end $function$


