    'open_shared_goals',open_shared_goals,'child_agents_active',child_agents_active,
    'family_state',family_state,'sensed_at',sensed_at
  )
  from public.tgg_one_family_snapshots
  order by sensed_at desc limit 1
$function$


-- [40000001020] function public.tgg_one_family_universe_cycle()
CREATE OR REPLACE FUNCTION public.tgg_one_family_universe_cycle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_before jsonb;
  v_core jsonb;
  v_after jsonb;
  v_partner jsonb;
  v_children jsonb;
  v_family jsonb;
  v_planet jsonb;
  v_universe jsonb;
  v_genome jsonb;
  v_skin jsonb;
  v_status text:='complete';
begin
  v_genome:=public.tgg_one_genome_refresh();
  v_skin:=public.tgg_one_skin_refresh();
  v_partner:=public.tgg_one_partner_refresh();
  v_children:=public.tgg_one_children_refresh();
  v_family:=public.tgg_one_family_refresh();
  v_planet:=public.tgg_one_planet_refresh();
  v_universe:=public.tgg_one_universe_refresh();

  v_before:=jsonb_build_object(
    'genome',v_genome,'skin',v_skin,'partner',v_partner,'children',v_children,
    'family',v_family,'planet',v_planet,'universe',v_universe
  );

  if v_genome->>'status'='restricted' or v_skin->>'status'='restricted' then
    v_status:='restricted';
    v_core:=jsonb_build_object(
      'status','restricted',
      'reason','outer_ring_preflight_restricted',
      'core_cycle_executed',false
    );
  else
    v_core:=public.tgg_one_cycle();
    if coalesce(v_core->>'status','complete')='restricted' then v_status:='restricted';
    elsif coalesce(v_core->>'status','complete') not in ('complete','healthy') then v_status:='warning';
    end if;
  end if;

  v_genome:=public.tgg_one_genome_refresh();
  v_skin:=public.tgg_one_skin_refresh();
  v_partner:=public.tgg_one_partner_refresh();
  v_children:=public.tgg_one_children_refresh();
  v_family:=public.tgg_one_family_refresh();
  v_planet:=public.tgg_one_planet_refresh();
  v_universe:=public.tgg_one_universe_refresh();

  v_after:=jsonb_build_object(
    'genome',v_genome,'skin',v_skin,'partner',v_partner,'children',v_children,
    'family',v_family,'planet',v_planet,'universe',v_universe
  );

  if v_genome->>'status'='restricted' or v_skin->>'status'='restricted' then
    v_status:='restricted';
  elsif v_status='complete' and (
    v_partner->>'status'='warning'
    or v_children->>'status'='warning'
    or v_family->>'status'='warning'
    or v_planet->>'status'='warning'
    or v_universe->>'status'='warning'
  ) then
    v_status:='warning';
  end if;

  return jsonb_build_object(
    'name','THE ONE FAMILY UNIVERSE',
    'status',v_status,
    'outer_preflight',v_before,
    'core_cycle',v_core,
    'outer_postflight',v_after,
    'family',jsonb_build_object(
      'partner','PARTNER / WIFE',
      'children','KIDS / CHILD AGENTS',
      'home','PLANET / TGG WORLD',
      'cosmos','UNIVERSE',
      'works_together',true
    ),
    'production_auto_publish',false,
    'production_promotion_allowed',false,
    'high_risk_auto_execute',false,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end $function$


