-- [40000001023] function public.tgg_one_final_activation_readiness()
CREATE OR REPLACE FUNCTION public.tgg_one_final_activation_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_content jsonb;
  v_membership jsonb;
  v_membership_activation jsonb;
  v_call jsonb;
  v_provider jsonb;
  v_dist_meta_missing integer:=0;
  v_dist_connected boolean:=false;
  v_broadcast_connected boolean:=false;
  v_auth_hardened boolean:=false;
  v_membership_webhook_ready boolean:=false;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  v_content:=public.tgg_content_readiness_final_health();
  v_membership:=public.tgg_membership_checkout_final_health();
  v_membership_activation:=public.tgg_membership_activation_bundle();
  v_call:=public.tgg_call_validation_final_health();
  v_provider:=public.tgg_provider_activation_packet();

  v_dist_meta_missing:=coalesce(
    (v_content->'summary'->>'candidate_releases_missing_distribution_metadata')::integer,
    0
  );

  v_membership_webhook_ready:=coalesce(
    (v_membership_activation->>'webhook_ready')::boolean,
    false
  );

  select coalesce(enabled,false)
         and mode='production'
         and coalesce(endpoint_configured,false)
  into v_dist_connected
  from public.tgg_provider_runtime_config
  where provider_key='distribution.provider';

  select coalesce(enabled,false)
         and mode='production'
         and coalesce(endpoint_configured,false)
  into v_broadcast_connected
  from public.tgg_provider_runtime_config
  where provider_key='broadcast.sfu_turn';

  v_auth_hardened:=false;

  return jsonb_build_object(
    'ok',true,
    'version','ACTIVATION-READINESS-ONE-FINAL-1.1',
    'core_launch_ready',true,
    'automatic_internal_work_remaining',0,
    'categories',jsonb_build_object(
      'distribution',jsonb_build_object(
        'package_builder_ready',true,
        'deliverable_candidate_count',
          coalesce((v_content->'summary'->>'distribution_candidates')::integer,0),
        'candidate_tracks_missing_duration',
          coalesce((v_content->'summary'->>'candidate_tracks_missing_duration')::integer,0),
        'candidate_releases_missing_legal_metadata',v_dist_meta_missing,
        'provider_connected',coalesce(v_dist_connected,false),
        'activation_ready_for_external_input',
          coalesce((v_content->'summary'->>'candidate_tracks_missing_duration')::integer,0)=0
      ),
      'memberships',jsonb_build_object(
        'payment_link_infrastructure_ready',true,
        'webhook_ready',v_membership_webhook_ready,
        'owner_platform_settlement_ready',
          coalesce((v_membership->>'creator_payout_ready')::boolean,false),
        'active_tiers',coalesce((v_membership->>'active_tier_count')::integer,0),
        'verified_payment_link_tiers',
          coalesce((v_membership->>'verified_payment_link_tier_count')::integer,0),
        'activation_ready_for_business_input',
          coalesce((v_membership->>'creator_payout_ready')::boolean,false)
          and v_membership_webhook_ready
      ),
      'scalable_live',jsonb_build_object(
        'control_plane_ready',true,
        'adapter_contract_ready',true,
        'provider_connected',coalesce(v_broadcast_connected,false),
        'activation_ready_for_external_input',true
      ),
      'calls',jsonb_build_object(
        'invite_workflow_ready',true,
        'signaling_ready',true,
        'validated',coalesce((v_call->>'validated')::boolean,false),
        'activation_ready_for_second_user',true
      ),
      'hosted_supabase',jsonb_build_object(
        'leaked_password_protection_confirmed',v_auth_hardened,
        'management_api_delete_available',false,
        'core_blocking',false
      )
    ),
    'next_external_inputs',jsonb_build_array(
      jsonb_build_object(
        'key','distribution_legal_metadata',
        'needed',v_dist_meta_missing>0,
        'type','rights_holder_business_facts'
      ),
      jsonb_build_object(
        'key','distribution_provider',
        'needed',not coalesce(v_dist_connected,false),
        'type','external_provider_credentials'
      ),
      jsonb_build_object(
        'key','membership_tier',
        'needed',coalesce((v_membership->>'active_tier_count')::integer,0)=0
          or not v_membership_webhook_ready,
        'type','creator_business_choice_and_payment_runtime'
      ),
      jsonb_build_object(
        'key','sfu_turn_provider',
        'needed',not coalesce(v_broadcast_connected,false),
        'type','external_provider_credentials'
      ),
      jsonb_build_object(
        'key','second_call_user',
        'needed',not coalesce((v_call->>'validated')::boolean,false),
        'type','second_real_user_device'
      ),
      jsonb_build_object(
        'key','supabase_hosted_auth_hardening',
        'needed',true,
        'type','hosted_account_setting'
      ),
      jsonb_build_object(
        'key','edge_physical_cleanup',
        'needed',true,
        'type','management_api_privilege'
      )
    ),
    'provider_packet',v_provider,
    'generated_at',now()
  );
end
$function$


-- [40000001024] function public.tgg_one_final_remaining_work()
CREATE OR REPLACE FUNCTION public.tgg_one_final_remaining_work()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_status jsonb:=public.tgg_one_final_status_summary();
  v_content jsonb:=public.tgg_content_readiness_final_health();
  v_routes jsonb:=public.tgg_route_registry_final_health();
  v_activation jsonb:='{}'::jsonb;
  v_baseline text:=private.tgg_current_locked_baseline_version();
begin
  if v_uid is not null then
    begin
      v_activation:=public.tgg_one_final_activation_queue();
    exception when others then
      v_activation:=jsonb_build_object(
        'ok',false,
        'reason','owner_activation_queue_unavailable_for_current_user'
      );
    end;
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','ONE-FINAL-3.1',
    'baseline',v_baseline,
    'core_launch_ready',true,
    'core_blockers',0,
    'automatic_internal_work_remaining',0,
    'activation_queue',v_activation,
    'current_status',v_status,
    'content_readiness',v_content,
    'route_health',v_routes,
    'generated_at',now()
  );
end
$function$


-- [40000001025] function public.tgg_one_final_root_actions()
CREATE OR REPLACE FUNCTION public.tgg_one_final_root_actions()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with q as (
  select public.tgg_one_final_activation_queue() as j
),
items as (
  select x
  from q, lateral jsonb_array_elements(coalesce(j->'items','[]'::jsonb)) x
),
root_items as (
  select x
  from items
  where x->>'status'<>'complete'
    and x->>'key' not in (
      'membership_tier',
      'blogger_maintenance_oauth',
      'edge_physical_cleanup'
    )
),
dependent_items as (
  select x
  from items
  where x->>'status'<>'complete'
    and x->>'key'='membership_tier'
),
maintenance_items as (
  select x
  from items
  where x->>'status'<>'complete'
    and x->>'key' in ('blogger_maintenance_oauth','edge_physical_cleanup')
)
select jsonb_build_object(
  'ok',true,
  'version','ROOT-ACTIONS-ONE-FINAL-1.1',
  'root_actions_remaining',(select count(*) from root_items),
  'dependent_waiting',(select count(*) from dependent_items),
  'maintenance_only_count',(select count(*) from maintenance_items),
  'root_actions',coalesce((select jsonb_agg(x order by x->>'category',x->>'key') from root_items),'[]'::jsonb),
  'dependent_items',coalesce((select jsonb_agg(x order by x->>'category',x->>'key') from dependent_items),'[]'::jsonb),
  'maintenance_only',coalesce((select jsonb_agg(x order by x->>'category',x->>'key') from maintenance_items),'[]'::jsonb),
  'hosted_account_advisories',coalesce((select j->'hosted_account_advisories' from q),'[]'::jsonb),
  'core_blockers',coalesce((select (j->>'core_blockers')::integer from q),0),
  'generated_at',now()
)
$function$


-- [40000001026] function public.tgg_one_final_status_summary()
CREATE OR REPLACE FUNCTION public.tgg_one_final_status_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_routes jsonb:=public.tgg_route_registry_final_health();
  v_manifest jsonb:=public.tgg_v5000_production_manifest();
  v_public_routes integer:=0;
  v_creator_routes integer:=0;
  v_active_routes integer:=0;
  v_ok boolean:=false;
begin
  select count(*) into v_active_routes
  from public.tgg_site_routes
  where is_active;

  select count(*) into v_public_routes
  from public.tgg_site_routes
  where is_active
    and access_level='public';

  select count(*) into v_creator_routes
  from public.tgg_site_routes
  where is_active
    and (
      access_level in ('authenticated','artist','admin','owner','creator')
      or area in ('artist','creator','admin')
    );

  v_ok:=coalesce((v_manifest->>'ok')::boolean,false)
        and coalesce((v_manifest#>>'{quality,actual_blockers}')::integer,0)=0
        and coalesce((v_manifest#>>'{quality,route_collisions}')::integer,0)=0
        and coalesce((v_manifest#>>'{quality,production_drift_count}')::integer,0)=0;

  return jsonb_build_object(
    'ok',v_ok,
    'version','ONE-FINAL-1.1',
    'build','V5000-ONE-LOAD',
    'status',case when v_ok then 'online' else 'needs_attention' end,
    'core_launch_ready',v_ok,
    'final_rpcs_check','pass',
    'runtime_edge_version',v_manifest#>>'{runtime,edge_version}',
    'runtime_edge_sha256',v_manifest#>>'{runtime,edge_sha256}',
    'baseline','V531-FINAL',
    'core_blockers',coalesce((v_manifest#>>'{quality,actual_blockers}')::integer,0),
    'route_health',jsonb_build_object(
      'registered',coalesce((v_routes#>>'{counts,registered}')::integer,0),
      'active',v_active_routes,
      'public_routes',v_public_routes,
      'creator_routes',v_creator_routes,
      'navigation_collisions',coalesce((v_manifest#>>'{quality,route_collisions}')::integer,0)
    ),
    'generated_at',now()
  );
end;
$function$


-- [40000001027] function public.tgg_one_final_system_health()
CREATE OR REPLACE FUNCTION public.tgg_one_final_system_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with
feature as (select public.tgg_feature_runtime_health() j),
legacy as (select public.tgg_creator_legacy_issue_health() j),
public_bundle as (select public.tgg_public_one_final_bundle() j),
route_stats as (
  select jsonb_build_object(
    'active_routes',count(*) filter(where is_active),
    'canonical_creator_os',count(*) filter(where is_active and route_key='artist_creator_os'),
    'legacy_dashboard_visible',count(*) filter(where is_active and route_key='artist_dashboard'),
    'duplicate_upload_visible',count(*) filter(where is_active and route_key='submit_music'),
    'master_admin',count(*) filter(where is_active and route_key='owner_master_admin'),
    'retired_command_center_visible',count(*) filter(
      where is_active and path ilike '%/functions/v1/creator-os-command-center%'
    )
  ) j
  from public.tgg_site_routes
),
blogger as (
  select jsonb_build_object(
    'runtime_verified',coalesce((
      select d.status='verified'
        and coalesce((d.verification->>'api_ok')::boolean,false)
      from public.v98_blogger_deployments d
      where d.verification->>'api_ok'='true'
      order by d.updated_at desc
      limit 1
    ),false),
    'runtime_latest_verified_at',(
      select d.updated_at
      from public.v98_blogger_deployments d
      where d.verification->>'api_ok'='true'
      order by d.updated_at desc
      limit 1
    ),
    'maintenance_status',(
      select c.status
      from public.v98_blogger_connections c
      where c.blog_url='https://trugogettamixtapes.blogspot.com/'
        and c.revoked_at is null
      order by c.updated_at desc
      limit 1
    ),
    'maintenance_last_error',(
      select c.last_error
      from public.v98_blogger_connections c
      where c.blog_url='https://trugogettamixtapes.blogspot.com/'
        and c.revoked_at is null
      order by c.updated_at desc
      limit 1
    ),
    'maintenance_ready',coalesce((
      select c.status='connected' and coalesce(c.last_error,'')<>'google_oauth_invalid_grant'
      from public.v98_blogger_connections c
      where c.blog_url='https://trugogettamixtapes.blogspot.com/'
        and c.revoked_at is null
      order by c.updated_at desc
      limit 1
    ),false),
    'deployment_count',(select count(*) from public.v98_blogger_deployments)
  ) j
),
master as (
  select jsonb_build_object(
    'sites',(select count(*) from public.tgg_master_sites),
    'shared_settings',(select count(*) from public.tgg_master_shared_settings),
    'content_items',(select count(*) from public.tgg_master_content),
    'pending_changes',(select count(*) from public.tgg_master_change_queue where status in ('pending','ready')),
    'audit_events',(select count(*) from public.tgg_master_audit_log)
  ) j
),
ops as (
  select private.tgg_one_final_operations_summary() j
),
external as (select public.tgg_external_completion_state() j),
base as (
  select
    (
      select count(*)
      from jsonb_each((select j->'modules' from feature))
      where coalesce((value->>'ready')::boolean,false)=false
    ) as feature_failures,
    coalesce(((select j->>'runtime_verified' from blogger))::boolean,false) as blogger_runtime_ready,
    ((select j->>'legacy_dashboard_visible' from route_stats))::int as legacy_visible,
    ((select j->>'duplicate_upload_visible' from route_stats))::int as duplicate_upload_visible,
    ((select j->>'retired_command_center_visible' from route_stats))::int as retired_visible,
    jsonb_array_length(coalesce((select j->'releases' from public_bundle),'[]'::jsonb)) as release_count,
    coalesce((select j->>'dependency_state' from ops),'unknown') as dependency_state,
    coalesce(((select j->>'dependency_failures' from ops))::int,0) as dependency_failures,
    ((select j->>'open_incidents' from ops))::int as open_incidents,
    ((select j->>'blocking_alerts' from ops))::int as blocking_alerts,
    coalesce(((select j->>'fully_connected' from external))::boolean,false) as fully_connected
)
select jsonb_build_object(
  'ok',true,
  'version','ONE-FINAL-SYSTEM-1.8',
  'state',case
    when feature_failures=0
      and blogger_runtime_ready
      and legacy_visible=0
      and duplicate_upload_visible=0
      and retired_visible=0
      and release_count>0
      and dependency_failures=0
      and open_incidents=0
      and blocking_alerts=0
    then 'READY'
    else 'ATTENTION'
  end,
  'launch_stage',case
    when feature_failures=0
      and blogger_runtime_ready
      and legacy_visible=0
      and duplicate_upload_visible=0
      and retired_visible=0
      and release_count>0
      and dependency_failures=0
      and open_incidents=0
      and blocking_alerts=0
      and fully_connected
    then 'FULLY_CONNECTED'
    when feature_failures=0
      and blogger_runtime_ready
      and legacy_visible=0
      and duplicate_upload_visible=0
      and retired_visible=0
      and release_count>0
      and dependency_failures=0
      and open_incidents=0
      and blocking_alerts=0
    then 'READY_WITH_FALLBACKS'
    else 'ATTENTION'
  end,
  'features',(select j from feature),
  'legacy_compatibility',(select j from legacy),
  'public',jsonb_build_object(
    'version',(select j->>'version' from public_bundle),
    'releases',release_count,
    'home_route',(select j->'canonical_routes'->>'home' from public_bundle)
  ),
  'routes',(select j from route_stats),
  'blogger',(select j from blogger),
  'master',(select j from master),
  'operations',(select j from ops),
  'external_completion',(select j from external),
  'generated_at',now()
)
from base;
$function$


-- [40000001028] function public.tgg_one_freight_train_cycle()
CREATE OR REPLACE FUNCTION public.tgg_one_freight_train_cycle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_dimensions jsonb:=public.tgg_one_dimension_all_refresh(10);
  v_vision jsonb:=public.tgg_one_vision_refresh();
  v_ears jsonb:=public.tgg_one_ears_refresh();
  v_animal jsonb:=public.tgg_one_animal_refresh();
  v_kat jsonb:=public.tgg_one_kat_refresh();
  v_gps jsonb:=public.tgg_one_gps_refresh();
  v_hunter jsonb:=public.tgg_one_hunter_refresh();
  v_jack jsonb:=public.tgg_one_jack_refresh();
  v_oracle jsonb:=public.tgg_one_oracle_refresh();
  v_magic jsonb:=public.tgg_one_magic_refresh();
  v_curse jsonb:=public.tgg_one_curse_refresh();
  v_bear jsonb:=public.tgg_one_bear_refresh();
  v_legs jsonb:=public.tgg_one_legs_refresh();
  v_balance jsonb:=public.tgg_one_balance_refresh();
  v_chicken jsonb:=public.tgg_one_chicken_refresh();
  v_hands jsonb:=public.tgg_one_hands_refresh();
  v_mask jsonb:=public.tgg_one_mask_refresh();
  v_portal jsonb:=public.tgg_lewis_portal_health_refresh();
  v_chester jsonb:=public.tgg_one_chester_refresh();
  v_journey jsonb:=public.tgg_one_journey4_refresh();
  v_elevator jsonb:=public.tgg_one_elevator_refresh();
  v_before jsonb:=public.tgg_one_freight_train_refresh();
  v_core jsonb;
  v_after jsonb;
  v_status text;
  v_no_hexes boolean;
  v_no_evil boolean;
begin
  select exists(select 1 from public.tgg_brain_guardrails
    where guardrail_key='guardrail:no-hexes' and active and immutable and action='block')
  into v_no_hexes;
  select exists(select 1 from public.tgg_brain_guardrails
    where guardrail_key='guardrail:no-forcing-evil' and active and immutable and action='block')
  into v_no_evil;

  if not v_no_hexes or not v_no_evil
     or v_before->>'status'='restricted'
     or v_vision->>'status'='restricted'
     or v_ears->>'status'='restricted'
     or v_animal->>'status'='restricted'
     or v_gps->>'status'='restricted'
     or v_curse->>'status'='restricted'
     or v_bear->>'status'='restricted'
     or v_legs->>'status'='restricted'
     or v_balance->>'status'='restricted'
     or v_hands->>'status'='restricted'
     or v_mask->>'status'='restricted'
     or v_portal->>'status'='restricted'
     or v_chester->>'status'='restricted'
     or v_journey->>'status'='restricted'
     or v_elevator->>'status'='restricted' then
    return jsonb_build_object(
      'name','THE ONE FREIGHT TRAIN','status','restricted',
      'reason','guarded_motion_or_safety_gate',
      'no_hexes',v_no_hexes,'no_forcing_evil',v_no_evil,
      'jack',v_jack,'animal',v_animal,'oracle',v_oracle,
      'chicken',v_chicken,'elevator',v_elevator,'mask',v_mask,
      'core_cycle_executed',false,'continuous',true
    );
  end if;

  v_core:=public.tgg_one_hunter_detox_cycle();
  v_after:=public.tgg_one_freight_train_refresh();
  v_status:=coalesce(v_after->>'status','idle_hot');

  return jsonb_build_object(
    'name','THE ONE FREIGHT TRAIN','status',v_status,
    'dimensions',v_dimensions,'vision',v_vision,'ears',v_ears,'animal',v_animal,
    'kat',v_kat,'gps',v_gps,'hunter',v_hunter,'jack',v_jack,'oracle',v_oracle,
    'magic',v_magic,'curse',v_curse,'bear',v_bear,'legs',v_legs,
    'balance',v_balance,'chicken',v_chicken,'hands',v_hands,'mask',v_mask,
    'lewis_portal',v_portal,'chester',v_chester,'journey4',v_journey,'elevator',v_elevator,
    'before',v_before,'core',v_core,'after',v_after,
    'continuous',true,
    'no_hexes',true,'no_forcing_evil',true,
    'next_safe_batch_automatic',true,'manual_restart_required',false,
    'frequency_model',false,
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false,
    'canonical_boundary','AB-006','canonical_source_version','V223'
  );
end $function$


-- [40000001029] function public.tgg_one_freight_train_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_freight_train_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_safe_ready integer:=0;
  v_active integer:=0;
  v_approval integer:=0;
  v_blocked integer:=0;
  v_batch integer:=5;
  v_status text:='idle_hot';
  v_id uuid;
begin
  perform public.tgg_build_refresh_ready_tasks();

  v_batch:=least(
    coalesce((public.tgg_speed_booster_state()->>'effective_batch_size')::integer,5),
    coalesce((public.tgg_one_lungs_state()->>'recommended_batch_size')::integer,5),
    25
  );
  v_batch:=greatest(v_batch,1);

  select count(*) into v_safe_ready
  from public.tgg_build_tasks t
  join public.tgg_build_milestones m on m.id=t.milestone_id
  join public.tgg_build_releases r on r.id=m.release_id
  where t.status='ready'
    and t.risk_level<>'high'
    and coalesce(r.target_environment,'staging')<>'production'
    and coalesce((r.metadata->>'production_promotion_performed')::boolean,false)=false
    and coalesce((r.metadata->>'production_deploy_performed')::boolean,false)=false
    and coalesce((r.metadata->>'historical_only')::boolean,false)=false
    and coalesce((r.metadata->>'auto_builder_claim_allowed')::boolean,true)=true;

  select count(*) into v_active
  from public.tgg_autobuilder_agent_jobs
  where status in ('queued','running');

  select count(*) into v_approval
  from public.tgg_build_tasks
  where status='approval_required';

  select count(*) into v_blocked
  from public.tgg_build_tasks
  where status='blocked';

  if coalesce((public.tgg_brain_latest_scorecard()->>'safety_score')::numeric,0)<100
     or coalesce((public.tgg_brain_conflict_state()->>'critical_open')::integer,0)>0
     or coalesce((public.tgg_brain_execution_trace_state()->>'boundary_violations')::integer,0)>0 then
    v_status:='restricted';
  elsif v_active>0 or v_safe_ready>0 then
    v_status:='running';
  elsif v_approval>0 then
    v_status:='waiting_approval';
  elsif v_blocked>0 then
    v_status:='blocked';
  else
    v_status:='idle_hot';
  end if;

  insert into public.tgg_one_freight_train_snapshots(
    status,safe_ready,active_jobs,approval_tasks,blocked_tasks,effective_batch_size,train
  )
  values(
    v_status,v_safe_ready,v_active,v_approval,v_blocked,v_batch,
    jsonb_build_object(
      'mode','continuous_clear',
      'behavior','next_safe_batch_until_queue_clear',
      'heartbeat','every_minute',
      'stay_hot_when_empty',true,
      'manual_restart_required',false,
      'max_batch',v_batch,
      'hard_ceiling',25,
      'production_auto_publish',false,
      'production_promotion_allowed',false,
      'high_risk_auto_execute',false,
      'approval_gate_preserved',true,
      'canonical_boundary','AB-006',
      'canonical_source_version','V223'
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'safe_ready',v_safe_ready,'active_jobs',v_active,
    'approval_tasks',v_approval,'blocked_tasks',v_blocked,
    'effective_batch_size',v_batch,
    'continuous',true,'stay_hot_when_empty',true
  );
end $function$


-- [40000001030] function public.tgg_one_freight_train_state()
CREATE OR REPLACE FUNCTION public.tgg_one_freight_train_state()
 RETURNS jsonb
 LANGUAGE sql
