  order by sensed_at desc limit 1
$function$


-- [40000001031] function public.tgg_one_genome_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_genome_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_versions integer:=0;
  v_contracts integer:=0;
  v_design integer:=0;
  v_safety boolean:=false;
  v_identity boolean:=false;
  v_status text:='healthy';
  v_id uuid;
  v_active jsonb;
begin
  select count(*) into v_versions
  from public.tgg_brain_versions
  where status='active';

  select count(*) into v_contracts
  from public.tgg_api_contract_registry;

  select count(*) into v_design
  from public.tgg_design_systems
  where lower(coalesce(status,'')) in ('active','ready','approved','complete','completed');

  select jsonb_build_object(
    'version_key',version_key,'version_no',version_no,'safety_contract',safety_contract
  )
  into v_active
  from public.tgg_brain_versions
  where status='active'
  order by activated_at desc nulls last,created_at desc
  limit 1;

  v_safety :=
    coalesce((v_active->'safety_contract'->>'production_auto_publish')::boolean,false)=false
    and coalesce((v_active->'safety_contract'->>'high_risk_auto_execute')::boolean,false)=false
    and coalesce(v_active->'safety_contract'->>'canonical_boundary','AB-006')='AB-006'
    and coalesce(v_active->'safety_contract'->>'canonical_source_version','V223')='V223';

  v_identity := v_versions=1 and v_contracts>0 and v_design>0;

  if not v_safety then
    v_status:='restricted';
  elsif not v_identity then
    v_status:='warning';
  end if;

  insert into public.tgg_one_genome_snapshots(
    status,active_brain_versions,api_contracts,active_design_systems,
    safety_contract_ok,canonical_identity_ok,genome
  )
  values(
    v_status,v_versions,v_contracts,v_design,v_safety,v_identity,
    jsonb_build_object(
      'brain',v_active,
      'canonical_boundary','AB-006',
      'canonical_source_version','V223',
      'evolution_rule','additive_safe_evolution_only',
      'production_auto_publish',false,
      'high_risk_auto_execute',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'active_brain_versions',v_versions,'api_contracts',v_contracts,
    'active_design_systems',v_design,'safety_contract_ok',v_safety,
    'canonical_identity_ok',v_identity
  );
end $function$


