-- [40000001033] function public.tgg_one_gps_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_gps_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_routes integer:=0;
  v_locations integer:=0;
  v_goals integer:=0;
  v_ready integer:=0;
  v_blocked integer:=0;
  v_goal_key text;
  v_step_key text;
  v_status text:='idle';
  v_path jsonb:='{}'::jsonb;
  v_id uuid;
begin
  select count(*) into v_routes from public.tgg_site_routes where is_active=true;
  select count(*) into v_locations from public.tgg_world_locations where enabled=true;
  select count(*) into v_goals
  from public.tgg_brain_goals
  where status not in ('complete','completed','canceled');

  select
    count(*) filter(where s.status in ('ready','planned','queued')),
    count(*) filter(where s.status='blocked')
  into v_ready,v_blocked
  from public.tgg_brain_goal_steps s
  join public.tgg_brain_goals g on g.id=s.goal_id
  where g.status not in ('complete','completed','canceled');

  select g.goal_key,s.step_key
  into v_goal_key,v_step_key
  from public.tgg_brain_goal_steps s
  join public.tgg_brain_goals g on g.id=s.goal_id
  where g.status not in ('complete','completed','canceled')
    and s.status in ('ready','planned','queued')
    and s.risk_level<>'high'
    and coalesce(g.production_allowed,false)=false
  order by g.priority_score desc,s.sequence_no asc,s.created_at asc
  limit 1;

  if found then
    v_status:='healthy';
    v_path:=jsonb_build_object(
      'goal_key',v_goal_key,'step_key',v_step_key,
      'mode','shortest_safe_dependency_path',
      'production_allowed',false,'high_risk_allowed',false
    );
  elsif v_blocked>0 then
    v_status:='warning';
    v_path:=jsonb_build_object('reason','no_safe_ready_step','blocked_steps',v_blocked);
  else
    v_status:='idle';
    v_path:=jsonb_build_object(
      'reason','no_unfinished_safe_path',
      'active_routes',v_routes,
      'enabled_world_locations',v_locations
    );
  end if;

  insert into public.tgg_one_gps_snapshots(
    status,active_routes,enabled_world_locations,unfinished_goals,
    ready_steps,blocked_steps,next_goal_key,next_step_key,path
  )
  values(
    v_status,v_routes,v_locations,v_goals,v_ready,v_blocked,v_goal_key,v_step_key,v_path
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'active_routes',v_routes,'enabled_world_locations',v_locations,
    'unfinished_goals',v_goals,'ready_steps',v_ready,'blocked_steps',v_blocked,
    'next_goal_key',v_goal_key,'next_step_key',v_step_key,'path',v_path
  );
end $function$


