-- [40000001035] function public.tgg_one_guarded_motion_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_guarded_motion_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb:=public.tgg_one_journey_motion_completeness();
  v_jack jsonb:=public.tgg_one_jack_state();
  v_animal jsonb:=public.tgg_one_animal_state();
  v_oracle jsonb:=public.tgg_one_oracle_state();
  v_chicken jsonb:=public.tgg_one_chicken_state();
  v_elevator jsonb:=public.tgg_one_elevator_state();
  v_mask jsonb:=public.tgg_one_mask_state();
  v_layers integer:=0;
  v_hex boolean:=false;
  v_evil boolean:=false;
  v_ok boolean;
begin
  select count(*) into v_layers from public.tgg_one_layers where active=true;

  select exists(
    select 1 from public.tgg_brain_guardrails
    where guardrail_key='guardrail:no-hexes'
      and active and immutable and severity='critical' and action='block'
  ) into v_hex;

  select exists(
    select 1 from public.tgg_brain_guardrails
    where guardrail_key='guardrail:no-forcing-evil'
      and active and immutable and severity='critical' and action='block'
  ) into v_evil;

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and v_layers>=52
    and v_hex and v_evil
    and coalesce(v_animal->>'status','restricted')<>'restricted'
    and coalesce(v_mask->>'status','restricted')<>'restricted'
    and coalesce(v_elevator->>'status','restricted')<>'restricted';

  return jsonb_build_object(
    'ok',v_ok,'base',v_base,
    'jack',v_jack,'animal',v_animal,'oracle',v_oracle,
    'chicken',v_chicken,'elevator',v_elevator,'mask',v_mask,
    'no_hexes_guardrail',v_hex,
    'no_forcing_evil_guardrail',v_evil,
    'minimum_required_layers',52,'active_total_layers',v_layers,
    'frequency_model',false,'supernatural_claims',false,
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false,
    'canonical_boundary','AB-006','canonical_source_version','V223'
  );
end $function$


-- [40000001036] function public.tgg_one_hair_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_hair_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_design_systems integer:=0;
  v_ready_specs integer:=0;
  v_blocked_specs integer:=0;
  v_visual_fail integer:=0;
  v_overlap integer:=0;
  v_clipped integer:=0;
  v_stale_theme integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select count(*) into v_design_systems
  from public.tgg_design_systems
  where lower(coalesce(status,'')) in ('active','ready','complete','completed','approved','healthy');

  select
    count(*) filter(where lower(coalesce(status,'')) in ('ready','complete','completed','approved','passed')),
    count(*) filter(where lower(coalesce(status,'')) in ('blocked','failed','rejected'))
  into v_ready_specs,v_blocked_specs
  from public.tgg_design_specs;

  with latest as (
    select distinct on(task_id,viewport_key)
      *
    from public.tgg_visual_qa_results
    where checked_at>=now()-interval '24 hours'
    order by task_id,viewport_key,checked_at desc,
      case when lower(coalesce(status,'')) in ('pass','passed','complete','completed','ok','healthy') then 0 else 1 end,
      id desc
  )
  select
    count(*) filter(where lower(coalesce(status,'')) not in ('pass','passed','complete','completed','ok','healthy')),
    coalesce(sum(overlap_count),0),
    coalesce(sum(clipped_text_count),0)
  into v_visual_fail,v_overlap,v_clipped
  from latest;

  select count(*) into v_stale_theme
  from public.tgg_theme_deploy_jobs
  where status not in ('complete','completed','success','succeeded','failed','canceled','cancelled')
    and created_at < now()-interval '15 minutes';

  if v_stale_theme>0 then
    v_status:='warning';
  elsif v_blocked_specs>0 or v_visual_fail>0 or v_overlap>0 or v_clipped>0 then
    v_status:='warning';
  end if;

  insert into public.tgg_one_hair_snapshots(
    status,active_design_systems,ready_design_specs,blocked_design_specs,
    latest_visual_failures,latest_overlap_findings,latest_clipped_text_findings,
    stale_theme_jobs,style_state
  )
  values(
    v_status,v_design_systems,v_ready_specs,v_blocked_specs,
    v_visual_fail,v_overlap,v_clipped,v_stale_theme,
    jsonb_build_object(
      'role','outer_expression',
      'owns',jsonb_build_array('branding','themes','layout_polish','visual_consistency','surface_expression'),
      'does_not_own',jsonb_build_array('production_authority','canonical_boundary','high_risk_execution','secrets'),
      'visual_evidence_policy','latest_per_task_viewport'
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'active_design_systems',v_design_systems,'ready_design_specs',v_ready_specs,
    'blocked_design_specs',v_blocked_specs,'latest_visual_failures',v_visual_fail,
    'latest_overlap_findings',v_overlap,'latest_clipped_text_findings',v_clipped,
    'stale_theme_jobs',v_stale_theme
  );
end $function$


