-- [40000001038] function public.tgg_one_hands_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_hands_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ui jsonb;
  v_external jsonb;
  v_rpc_ready integer:=0;
  v_rpc_total integer:=0;
  v_ws_ready integer:=0;
  v_ws_total integer:=0;
  v_dest_ready integer:=0;
  v_dest_total integer:=0;
  v_open_actions integer:=0;
  v_ext_ready integer:=0;
  v_ext_total integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  v_ui:=public.tgg_creator_ui_action_readiness();
  v_external:=public.tgg_external_action_contract_readiness();

  v_rpc_ready:=coalesce((v_ui->'rpc_references'->>'ready')::integer,0);
  v_rpc_total:=coalesce((v_ui->'rpc_references'->>'total')::integer,0);
  v_ws_ready:=coalesce((v_ui->'internal_workspaces'->>'ready')::integer,0);
  v_ws_total:=coalesce((v_ui->'internal_workspaces'->>'total')::integer,0);
  v_dest_ready:=coalesce((v_ui->'external_destinations'->>'ready')::integer,0);
  v_dest_total:=coalesce((v_ui->'external_destinations'->>'total')::integer,0);
  v_ext_ready:=coalesce((v_external->>'ready')::integer,0);
  v_ext_total:=coalesce((v_external->>'total')::integer,0);

  select count(*) into v_open_actions
  from public.tgg_creator_action_queue
  where status='open';

  if v_rpc_ready<v_rpc_total or v_ws_ready<v_ws_total then
    v_status:='restricted';
  elsif v_dest_ready<v_dest_total then
    v_status:='warning';
  elsif v_open_actions>20 then
    v_status:='busy';
  end if;

  insert into public.tgg_one_hands_snapshots(
    status,ui_rpc_ready,ui_rpc_total,workspace_ready,workspace_total,
    destination_ready,destination_total,open_creator_actions,
    external_contract_ready,external_contract_total,hands
  )
  values(
    v_status,v_rpc_ready,v_rpc_total,v_ws_ready,v_ws_total,
    v_dest_ready,v_dest_total,v_open_actions,v_ext_ready,v_ext_total,
    jsonb_build_object(
      'role','controlled_action_capability_map',
      'arbitrary_rpc_execution',false,
      'executes_actions_itself',false,
      'uses_existing_guarded_actions',true,
      'requires_head_veil_immune_clearance',true,
      'creator_actions_require_real_user_session',true,
      'external_contract_incomplete_is_not_internal_blocker',true,
      'external_contract_failed',coalesce(v_external->'failed','[]'::jsonb),
      'production_authority',false,
      'high_risk_authority',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'ui_rpc_ready',v_rpc_ready,'ui_rpc_total',v_rpc_total,
    'workspace_ready',v_ws_ready,'workspace_total',v_ws_total,
    'destination_ready',v_dest_ready,'destination_total',v_dest_total,
    'open_creator_actions',v_open_actions,
    'external_contract_ready',v_ext_ready,'external_contract_total',v_ext_total,
    'external_contract_failed',coalesce(v_external->'failed','[]'::jsonb)
  );
end $function$


