-- [40000001040] function public.tgg_one_heart_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_heart_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_open integer:=0;
  v_overdue integer:=0;
  v_priorities integer:=0;
  v_focus jsonb:='[]'::jsonb;
  v_needs jsonb:='[]'::jsonb;
  v_status text:='healthy';
  v_id uuid;
begin
  select
    count(*) filter(where status='open'),
    count(*) filter(where status='open' and due_at is not null and due_at<now())
  into v_open,v_overdue
  from public.tgg_creator_action_queue;

  select count(*) into v_priorities
  from public.tgg_brain_priorities;

  select coalesce(jsonb_agg(jsonb_build_object(
    'item_type',item_type,'item_key',item_key,'score',score,
    'impact',impact,'urgency',urgency,'dependency_readiness',dependency_readiness,
    'confidence',confidence,'risk_penalty',risk_penalty,'reason',reason
  ) order by score desc),'[]'::jsonb)
  into v_focus
  from (
    select *
    from public.tgg_brain_priorities
    order by score desc
    limit 10
  ) q;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,'action_type',action_type,'title',title,'priority',priority,
    'due_at',due_at,'rationale',rationale,'status',status
  ) order by priority asc,created_at asc),'[]'::jsonb)
  into v_needs
  from (
    select *
    from public.tgg_creator_action_queue
    where status='open'
    order by priority asc,created_at asc
    limit 10
  ) q;

  if v_overdue>0 then
    v_status:='warning';
  elsif v_open>0 then
    v_status:='waiting';
  end if;

  insert into public.tgg_one_heart_snapshots(
    status,open_creator_actions,overdue_creator_actions,active_brain_priorities,
    top_focus,creator_needs,values_state
  )
  values(
    v_status,v_open,v_overdue,v_priorities,v_focus,v_needs,
    jsonb_build_object(
      'creator_value_first',true,
      'repair_before_expansion',true,
      'user_experience_matters',true,
      'evidence_before_completion',true,
      'safety_before_speed',true,
      'production_requires_explicit_approval',true
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'open_creator_actions',v_open,'overdue_creator_actions',v_overdue,
    'active_brain_priorities',v_priorities,'top_focus',v_focus,'creator_needs',v_needs
  );
end $function$


