  order by sensed_at desc
  limit 1
$function$


-- [40000001042] function public.tgg_one_hunter_detox_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_hunter_detox_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_missing jsonb:='[]'::jsonb;
  v_layers integer:=0;
  v_hunter jsonb;
  v_detox jsonb;
  v_dream jsonb;
  v_ok boolean;
begin
  v_base:=public.tgg_one_breathing_completeness();
  v_hunter:=public.tgg_one_hunter_state();
  v_detox:=public.tgg_one_detox_state();
  v_dream:=public.tgg_one_dream_state();

  if to_regclass('public.tgg_one_hunter_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_hunter_snapshots'); end if;
  if to_regclass('public.tgg_one_hunts') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_hunts'); end if;
  if to_regclass('public.tgg_one_detox_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_detox_snapshots'); end if;
  if to_regclass('public.tgg_one_dream_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_dream_snapshots'); end if;

  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_hunter_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_hunter_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_detox_cycle') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_detox_cycle'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_dream_cycle') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_dream_cycle'); end if;

  select count(*) into v_layers
  from public.tgg_one_layers
  where active=true
    and layer_key in (
      'senses','reflexes','scout','hunter','shadow','head','mind','heart','genome','bones','circulation',
      'nervous','immune','lungs','metabolism','detox','muscle','stamina','body','skin','spirit','soul','dream','hair',
      'partner','children','family','veil','matrix_gateway','planet','universe','the_one'
    );

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and jsonb_array_length(v_missing)=0
    and v_layers=32
    and coalesce(v_hunter->>'status','restricted')<>'restricted'
    and coalesce(v_detox->>'status','restricted')<>'restricted'
    and coalesce(v_dream->>'status','restricted')<>'restricted';

  return jsonb_build_object(
    'ok',v_ok,'base',v_base,
    'hunter',v_hunter,'detox',v_detox,'dream',v_dream,
    'required_total_layers',32,'active_total_layers',v_layers,
    'hunter_required',true,'detox_required',true,'dream_required',true,
    'missing',v_missing,
    'canonical_boundary','AB-006','canonical_source_version','V223',
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000001043] function public.tgg_one_hunter_detox_cycle()
CREATE OR REPLACE FUNCTION public.tgg_one_hunter_detox_cycle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hunter jsonb;
  v_detox jsonb;
  v_core jsonb;
  v_status text:='complete';
begin
  v_hunter:=public.tgg_one_hunter_refresh();
  v_detox:=public.tgg_one_detox_cycle();

  if v_hunter->>'status'='restricted' or coalesce(v_detox->'after'->>'status','healthy')='restricted' then
    return jsonb_build_object(
      'name','THE ONE HUNTER DETOX MATRIX',
      'status','restricted',
      'hunter',v_hunter,'detox',v_detox,
      'core_cycle_executed',false,
      'reason','hunter_or_detox_gate_restricted',
      'production_change_performed',false
    );
  end if;

  v_core:=public.tgg_one_breathing_cycle();

  if coalesce(v_core->>'status','complete')='restricted' then
    v_status:='restricted';
  elsif coalesce(v_core->>'status','complete') not in ('complete','healthy') then
    v_status:='warning';
  elsif coalesce(v_detox->'after'->>'status','healthy') in ('warning','loaded') then
    v_status:='warning';
  end if;

  return jsonb_build_object(
    'name','THE ONE HUNTER DETOX MATRIX',
    'status',v_status,'hunter',v_hunter,'detox',v_detox,'core',v_core,
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false,'canonical_boundary','AB-006','canonical_source_version','V223'
  );
end $function$


-- [40000001044] function public.tgg_one_hunter_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_hunter_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_scout jsonb;
  v_candidates integer:=0;
  v_safe integer:=0;
  v_review integer:=0;
  v_target_type text;
  v_target_key text;
  v_target_score numeric;
  v_target jsonb:='{}'::jsonb;
  v_status text:='idle';
  v_id uuid;
  v_task record;
begin
  v_scout:=public.tgg_one_scout_state();

  select
    count(*),
    count(*) filter(where coalesce((x->>'auto_fix_allowed')::boolean,false)=true),
    count(*) filter(where coalesce((x->>'auto_fix_allowed')::boolean,false)=false)
  into v_candidates,v_safe,v_review
  from jsonb_array_elements(coalesce(v_scout->'findings','[]'::jsonb)) x;

  -- Highest-value hunt is an already-safe ready build task.
  select
    t.task_key,
    t.title,
    t.task_type,
    t.priority,
    t.risk_level,
    r.release_key,
    r.target_environment
  into v_task
  from public.tgg_build_tasks t
  join public.tgg_build_milestones m on m.id=t.milestone_id
  join public.tgg_build_releases r on r.id=m.release_id
  where t.status='ready'
    and t.risk_level<>'high'
    and coalesce(r.target_environment,'staging')<>'production'
    and coalesce((r.metadata->>'production_promotion_performed')::boolean,false)=false
    and coalesce((r.metadata->>'production_deploy_performed')::boolean,false)=false
    and coalesce((r.metadata->>'historical_only')::boolean,false)=false
    and coalesce((r.metadata->>'auto_builder_claim_allowed')::boolean,true)=true
    and coalesce((public.tgg_one_skip_check('build_task',t.task_key,'process')->>'skip')::boolean,false)=false
  order by t.priority asc,t.created_at asc
  limit 1;

  if found then
    v_candidates:=v_candidates+1;
    v_safe:=v_safe+1;
    v_target_type:='build_task';
    v_target_key:=v_task.task_key;
    v_target_score:=100-greatest(0,least(100,coalesce(v_task.priority,50)));
    v_target:=jsonb_build_object(
      'target_type','build_task',
      'task_key',v_task.task_key,
      'title',v_task.title,
      'task_type',v_task.task_type,
      'priority',v_task.priority,
      'risk_level',v_task.risk_level,
      'release_key',v_task.release_key,
      'target_environment',v_task.target_environment,
      'auto_fix_allowed',true
    );
    v_status:='tracking';

    insert into public.tgg_one_hunts(
      hunt_key,target_type,target_key,status,score,reason,
      production_allowed,high_risk_allowed
    )
    values(
      'hunt:'||v_task.task_key,
      'build_task',v_task.task_key,'tracking',v_target_score,
      jsonb_build_object(
        'source','safe_ready_task',
        'skip_checked',true,
        'dependency_and_release_gates_preserved',true
      ),
      false,false
    )
    on conflict(hunt_key) do update
    set status=case
          when public.tgg_one_hunts.status in ('caught','verified','gated','abandoned')
            then public.tgg_one_hunts.status
          else 'tracking'
        end,
        score=excluded.score,
        reason=excluded.reason,
        updated_at=now();
  elsif v_safe>0 then
    -- Safe SCOUT finding exists, but HUNTER does not execute it directly.
    select
      x->>'type',
      coalesce(x->>'type','scout_finding'),
      50::numeric,
      x
    into v_target_type,v_target_key,v_target_score,v_target
    from jsonb_array_elements(coalesce(v_scout->'findings','[]'::jsonb)) x
    where coalesce((x->>'auto_fix_allowed')::boolean,false)=true
    limit 1;

    v_status:='tracking';
  elsif v_review>0 then
    v_status:='idle';
    v_target:=jsonb_build_object(
      'reason','no_safe_target',
      'review_only_findings',v_review,
      'protected_or_approval_gated_targets_are_not_hunted',true
    );
  end if;

  insert into public.tgg_one_hunter_snapshots(
    status,candidate_count,safe_candidate_count,review_only_count,
    target_type,target_key,target_score,target
  )
  values(
    v_status,v_candidates,v_safe,v_review,
    v_target_type,v_target_key,v_target_score,v_target
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'candidate_count',v_candidates,
    'safe_candidate_count',v_safe,
    'review_only_count',v_review,
    'target_type',v_target_type,
    'target_key',v_target_key,
    'target_score',v_target_score,
    'target',v_target,
    'production_allowed',false,
    'high_risk_allowed',false
  );
end $function$


-- [40000001045] function public.tgg_one_hunter_state()
CREATE OR REPLACE FUNCTION public.tgg_one_hunter_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'status',status,
    'candidate_count',candidate_count,
    'safe_candidate_count',safe_candidate_count,
    'review_only_count',review_only_count,
    'target_type',target_type,
    'target_key',target_key,
    'target_score',target_score,
    'target',target,
    'sensed_at',sensed_at
  )
  from public.tgg_one_hunter_snapshots
  order by sensed_at desc limit 1
$function$


-- [40000001046] function public.tgg_one_immune_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_immune_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_critical integer:=0;
  v_blocked integer:=0;
  v_high_failures integer:=0;
  v_qa integer:=0;
  v_provider jsonb;
  v_provider_blocked integer:=0;
  v_quarantine integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select
    count(*) filter(where status='open' and severity='critical'),
    count(*) filter(where status='open' and required_action='block')
  into v_critical,v_blocked
  from public.tgg_brain_conflicts;

  select count(*) into v_high_failures
  from public.tgg_build_failures
  where resolved_at is null
    and lower(coalesce(severity,'')) in ('high','critical');

  with latest_browser as (
    select distinct on(task_id,viewport_key) *
    from public.tgg_browser_qa_results
    where checked_at>=now()-interval '24 hours'
    order by task_id,viewport_key,checked_at desc,
      case when lower(coalesce(status,'')) in ('pass','passed','complete','completed','ok','healthy') then 0 else 1 end,
      id desc
  ),
  latest_visual as (
    select distinct on(task_id,viewport_key) *
    from public.tgg_visual_qa_results
    where checked_at>=now()-interval '24 hours'
    order by task_id,viewport_key,checked_at desc,
      case when lower(coalesce(status,'')) in ('pass','passed','complete','completed','ok','healthy') then 0 else 1 end,
      id desc
  )
  select
    (select count(*) from latest_browser
      where lower(coalesce(status,'')) not in ('pass','passed','complete','completed','ok','healthy'))
    +
    (select count(*) from latest_visual
      where lower(coalesce(status,'')) not in ('pass','passed','complete','completed','ok','healthy'))
  into v_qa;

  v_provider:=public.tgg_provider_health_state();
  v_provider_blocked:=coalesce((v_provider->>'blocked')::integer,0);

  v_quarantine:=v_critical+v_blocked+v_high_failures+v_provider_blocked;

  if v_quarantine>0 then
    v_status:='restricted';
  elsif v_qa>0 then
    v_status:='alert';
  end if;

  insert into public.tgg_one_immune_snapshots(
    status,critical_conflicts,blocked_conflicts,high_open_failures,
    current_qa_regressions,provider_blocked,quarantine_candidates,immunity
  )
  values(
    v_status,v_critical,v_blocked,v_high_failures,v_qa,
    v_provider_blocked,v_quarantine,
    jsonb_build_object(
      'quarantine_policy','block_before_body',
      'quarantine_is_logical_only',true,
      'auto_delete_or_destructive_action',false,
      'can_override_head',false,
      'protected_boundary','AB-006/V223'
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'critical_conflicts',v_critical,'blocked_conflicts',v_blocked,
    'high_open_failures',v_high_failures,'current_qa_regressions',v_qa,
    'provider_blocked',v_provider_blocked,'quarantine_candidates',v_quarantine
  );
end $function$


