  order by sensed_at desc limit 1
$function$


-- [40000001048] function public.tgg_one_jack_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_jack_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_h jsonb:=public.tgg_one_hunter_state();
  v_s jsonb:=public.tgg_one_scout_state();
  v_type text;
  v_key text;
  v_status text:='idle';
  v_review boolean:=false;
  v_id uuid;
begin
  if coalesce(v_h->>'status','idle')='tracking' and nullif(v_h->>'target_key','') is not null then
    v_type:=v_h->>'target_type'; v_key:=v_h->>'target_key'; v_status:='watching'; v_review:=false;
  else
    select x->>'type', coalesce(x->>'key',x->>'type','scout_finding'), coalesce((x->>'auto_fix_allowed')::boolean,false)=false
    into v_type,v_key,v_review
    from jsonb_array_elements(coalesce(v_s->'findings','[]'::jsonb)) x limit 1;
    v_review:=coalesce(v_review,false);
    if found then v_status:=case when v_review then 'gated' else 'watching' end; end if;
  end if;
  insert into public.tgg_one_jack_snapshots(status,target_type,target_key,target_status,evidence_count,review_only,watch)
  values(v_status,v_type,v_key,case when v_review then 'review_only' when v_status='watching' then 'tracking' else null end,case when v_key is null then 0 else 1 end,coalesce(v_review,false),jsonb_build_object('role','single_target_deep_watch','can_execute',false,'one_target_only',true)) returning id into v_id;
  return jsonb_build_object('ok',true,'snapshot_id',v_id,'status',v_status,'target_type',v_type,'target_key',v_key,'review_only',coalesce(v_review,false));
end
$function$


-- [40000001049] function public.tgg_one_jack_state()
CREATE OR REPLACE FUNCTION public.tgg_one_jack_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ select jsonb_build_object('status',status,'target_type',target_type,'target_key',target_key,'target_status',target_status,'evidence_count',evidence_count,'review_only',review_only,'watch',watch,'sensed_at',sensed_at)
from public.tgg_one_jack_snapshots order by sensed_at desc limit 1 $function$


-- [40000001050] function public.tgg_one_journey4_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_journey4_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_train jsonb;
  v_vision jsonb;
  v_gps jsonb;
  v_hunter jsonb;
  v_hands jsonb;
  v_curse jsonb;
  v_bear jsonb;
  v_safe integer:=0;
  v_active integer:=0;
  v_blockers integer:=0;
  v_stage integer:=1;
  v_key text:='discover';
  v_status text:='ready';
  v_id uuid;
begin
  v_train:=public.tgg_one_freight_train_state();
  v_vision:=public.tgg_one_vision_state();
  v_gps:=public.tgg_one_gps_state();
  v_hunter:=public.tgg_one_hunter_state();
  v_hands:=public.tgg_one_hands_state();
  v_curse:=public.tgg_one_curse_state();
  v_bear:=public.tgg_one_bear_state();

  v_safe:=coalesce((v_train->>'safe_ready')::integer,0);
  v_active:=coalesce((v_train->>'active_jobs')::integer,0);

  v_blockers :=
    case when coalesce(v_curse->>'status','clear')='restricted' then 1 else 0 end
    +case when coalesce(v_bear->>'status','strong')='restricted' then 1 else 0 end
    +case when coalesce(v_hands->>'status','healthy')='restricted' then 1 else 0 end;

  if v_blockers>0 then
    v_status:='restricted';
    v_stage:=2;
    v_key:='prepare';
  elsif v_active>0 then
    v_status:='running';
    v_stage:=3;
    v_key:='traverse';
  elsif v_safe>0 or coalesce(v_hunter->>'status','idle')='tracking' then
    v_status:='running';
    v_stage:=2;
    v_key:='prepare';
  elsif coalesce(v_vision->>'status','healthy')='healthy'
     and coalesce(v_gps->>'status','idle')='idle'
     and v_safe=0 and v_active=0 then
    v_status:='complete';
    v_stage:=4;
    v_key:='verify_return';
  else
    v_status:='ready';
    v_stage:=1;
    v_key:='discover';
  end if;

  insert into public.tgg_one_journey4_snapshots(
    status,stage_no,stage_key,safe_ready,active_jobs,blocker_count,journey
  )
  values(
    v_status,v_stage,v_key,v_safe,v_active,v_blockers,
    jsonb_build_object(
      'name','JOURNEY 4',
      'stages',jsonb_build_array(
        jsonb_build_object('stage',1,'key','discover','systems',jsonb_build_array('vision','ears','scout','kat','gps','hunter')),
        jsonb_build_object('stage',2,'key','prepare','systems',jsonb_build_array('head','mind','magic','curse','immune','bear','lungs','metabolism')),
        jsonb_build_object('stage',3,'key','traverse','systems',jsonb_build_array('muscle','stamina','hands','body','veil','matrix','lewis','chester')),
        jsonb_build_object('stage',4,'key','verify_return','systems',jsonb_build_array('qa','detox','evidence','dream','creator_os_return'))
      ),
      'automatic_next_stage',true,
      'manual_restart_required',false,
      'production_auto_publish',false,
      'high_risk_auto_execute',false,
      'canonical_boundary','AB-006',
      'canonical_source_version','V223'
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'stage_no',v_stage,'stage_key',v_key,
    'safe_ready',v_safe,'active_jobs',v_active,'blocker_count',v_blockers
  );
end $function$


