  order by sensed_at desc limit 1
$function$


-- [40000001052] function public.tgg_one_journey_motion_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_journey_motion_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_kat jsonb;
  v_bear jsonb;
  v_chester jsonb;
  v_journey jsonb;
  v_legs jsonb;
  v_balance jsonb;
  v_layers integer:=0;
  v_missing jsonb:='[]'::jsonb;
  v_ok boolean;
begin
  v_base:=public.tgg_one_all_d_completeness();
  v_kat:=public.tgg_one_kat_state();
  v_bear:=public.tgg_one_bear_state();
  v_chester:=public.tgg_one_chester_state();
  v_journey:=public.tgg_one_journey4_state();
  v_legs:=public.tgg_one_legs_state();
  v_balance:=public.tgg_one_balance_state();

  if to_regclass('public.tgg_one_legs_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_one_legs_snapshots');
  end if;
  if to_regclass('public.tgg_one_balance_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_one_balance_snapshots');
  end if;

  select count(*) into v_layers from public.tgg_one_layers where active=true;

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and jsonb_array_length(v_missing)=0
    and v_layers>=46
    and coalesce(v_bear->>'status','restricted')<>'restricted'
    and coalesce(v_chester->>'status','restricted')<>'restricted'
    and coalesce(v_legs->>'status','restricted')<>'restricted'
    and coalesce(v_balance->>'status','restricted')<>'restricted';

  return jsonb_build_object(
    'ok',v_ok,'base',v_base,
    'kat',v_kat,'bear',v_bear,'chester',v_chester,
    'journey4',v_journey,'legs',v_legs,'balance',v_balance,
    'minimum_required_layers',46,'active_total_layers',v_layers,
    'missing',v_missing,
    'canonical_boundary','AB-006','canonical_source_version','V223',
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000001053] function public.tgg_one_kat_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_kat_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_scout jsonb;
  v_findings integer:=0;
  v_safe integer:=0;
  v_routes integer:=0;
  v_locations integer:=0;
  v_goals integer:=0;
  v_status text:='idle';
  v_id uuid;
begin
  v_scout:=public.tgg_one_scout_state();

  select count(*),
         count(*) filter(where coalesce((x->>'auto_fix_allowed')::boolean,false)=true)
  into v_findings,v_safe
  from jsonb_array_elements(coalesce(v_scout->'findings','[]'::jsonb)) x;

  select count(*) into v_routes
  from public.tgg_site_routes
  where is_active=true;

  select count(*) into v_locations
  from public.tgg_world_locations
  where enabled=true;

  select count(*) into v_goals
  from public.tgg_brain_goals
  where status not in ('complete','completed','canceled');

  if v_safe>0 or v_goals>0 then
    v_status:='curious';
  elsif v_findings>0 then
    v_status:='idle';
  end if;

  insert into public.tgg_one_kat_snapshots(
    status,scout_findings,safe_scout_findings,active_routes,
    enabled_locations,unfinished_goals,curiosity
  )
  values(
    v_status,v_findings,v_safe,v_routes,v_locations,v_goals,
    jsonb_build_object(
      'role','safe_curiosity_and_exploration',
      'asks','what_safe_path_is_unexplored',
      'creates_work',false,
      'ignores_review_only_as_actionable',true,
      'production_authority',false,
      'high_risk_authority',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'scout_findings',v_findings,'safe_scout_findings',v_safe,
    'active_routes',v_routes,'enabled_locations',v_locations,'unfinished_goals',v_goals
  );
end $function$


