-- [40000001056] function public.tgg_one_layer_state(p_layer_key text)
CREATE OR REPLACE FUNCTION public.tgg_one_layer_state(p_layer_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_layer public.tgg_one_layers%rowtype;
  v_state jsonb:='{}'::jsonb;
  v_status text:='healthy';
begin
  select * into v_layer from public.tgg_one_layers
  where layer_key=p_layer_key and active=true;
  if not found then raise exception 'unknown_one_layer'; end if;

  case p_layer_key
    when 'senses' then
      v_state:=coalesce(public.tgg_one_senses_state(),'{}'::jsonb);
      v_status:=coalesce(v_state->>'status','healthy');
    when 'reflexes' then
      v_state:=coalesce(public.tgg_one_reflex_state(),'{}'::jsonb);
      v_status:=case coalesce(v_state->>'status','healthy')
        when 'alert' then 'warning' else coalesce(v_state->>'status','healthy') end;
    when 'scout' then
      v_state:=coalesce(public.tgg_one_scout_state(),'{}'::jsonb);
      v_status:=case coalesce(v_state->>'status','clean')
        when 'clean' then 'healthy'
        when 'findings' then 'healthy'
        else coalesce(v_state->>'status','healthy') end;
    when 'shadow' then
      v_state:=jsonb_build_object(
        'completeness',public.tgg_autonomic_completeness(),
        'autonomic',public.tgg_autonomic_state(),
        'architecture',public.tgg_brain_architecture_latest(),
        'conflicts',public.tgg_brain_conflict_state(),
        'providers',public.tgg_provider_health_state()
      );
      if coalesce((v_state->'completeness'->>'ok')::boolean,false)=false
         or coalesce((v_state->'autonomic'->'gaps'->>'open')::integer,0)>0 then
        v_status:='warning';
      end if;
    when 'head' then
      v_state:=jsonb_build_object(
        'scorecard',public.tgg_brain_latest_scorecard(),
        'conflicts',public.tgg_brain_conflict_state(),
        'boundary',jsonb_build_object(
          'canonical_boundary','AB-006','canonical_source_version','V223',
          'production_auto_publish',false,'production_promotion_allowed',false,
          'high_risk_auto_execute',false
        )
      );
      if coalesce((v_state->'scorecard'->>'safety_score')::numeric,0)<100
         or coalesce((v_state->'conflicts'->>'critical_open')::integer,0)>0
         or coalesce((v_state->'conflicts'->>'blocked_open')::integer,0)>0 then
        v_status:='restricted';
      end if;
    when 'mind' then
      v_state:=jsonb_build_object(
        'brain',public.tgg_brain_state(),
        'specs',public.tgg_brain_spec_state(),
        'prediction_accuracy',public.tgg_brain_prediction_accuracy(),
        'next_actions',public.tgg_brain_next_actions(10),
        'critical_unlocks',public.tgg_brain_next_critical_unlocks(10)
      );
    when 'heart' then
      v_state:=coalesce(public.tgg_one_heart_state(),'{}'::jsonb);
      v_status:=coalesce(v_state->>'status','healthy');
    when 'bones' then
      v_state:=coalesce(public.tgg_one_bones_state(),'{}'::jsonb);
      v_status:=coalesce(v_state->>'status','healthy');
    when 'circulation' then
      v_state:=coalesce(public.tgg_one_circulation_state(),'{}'::jsonb);
      v_status:=coalesce(v_state->>'status','healthy');
    when 'nervous' then
      v_state:=coalesce(public.tgg_one_nervous_state(),'{}'::jsonb);
      v_status:=coalesce(v_state->>'status','healthy');
    when 'immune' then
      v_state:=coalesce(public.tgg_one_immune_state(),'{}'::jsonb);
      v_status:=case coalesce(v_state->>'status','healthy')
        when 'alert' then 'warning'
        else coalesce(v_state->>'status','healthy') end;
    when 'muscle' then
      v_state:=coalesce(public.tgg_one_muscle_state(),'{}'::jsonb);
      v_status:=coalesce(v_state->>'status','healthy');
    when 'stamina' then
      v_state:=coalesce(public.tgg_one_stamina_state(),'{}'::jsonb);
      v_status:=coalesce(v_state->>'status','healthy');
    when 'body' then
      v_state:=jsonb_build_object(
        'autobuilder',public.tgg_autobuilder_detect_state(),
        'trace',public.tgg_brain_execution_trace_state(),
        'release_train',public.tgg_release_train_state()
      );
      if coalesce((v_state->'trace'->>'production_touched')::integer,0)>0
         or coalesce((v_state->'trace'->>'high_risk_executed')::integer,0)>0
         or coalesce((v_state->'trace'->>'boundary_violations')::integer,0)>0 then
        v_status:='restricted';
      end if;
    when 'spirit' then
      v_state:=jsonb_build_object(
        'observability',public.tgg_observability_state(),
        'speed',public.tgg_speed_booster_state(),
        'providers',public.tgg_provider_health_state()
      );
      if coalesce(v_state->'observability'->>'status','healthy')='restricted' then
        v_status:='restricted';
      elsif coalesce(v_state->'observability'->>'status','healthy')='warning' then
        v_status:='warning';
      end if;
    when 'soul' then
      v_state:=jsonb_build_object(
        'brain_version','TGG-BRAIN-1.0',
        'canonical_boundary','AB-006','canonical_source_version','V223',
        'memory_hygiene',public.tgg_brain_memory_hygiene_state(),
        'architecture',public.tgg_brain_architecture_latest()
      );
    when 'hair' then
      v_state:=coalesce(public.tgg_one_hair_state(),'{}'::jsonb);
      v_status:=coalesce(v_state->>'status','healthy');
    when 'the_one' then
      v_state:=public.tgg_observability_state();
      v_status:=coalesce(v_state->>'status','healthy');
  end case;

  return jsonb_build_object(
    'layer_key',v_layer.layer_key,'display_name',v_layer.display_name,
    'order',v_layer.layer_order,'purpose',v_layer.purpose,'status',v_status,
    'can_execute',v_layer.can_execute,'can_block',v_layer.can_block,
    'production_authority',v_layer.production_authority,
    'high_risk_authority',v_layer.high_risk_authority,
    'canonical_authority',v_layer.canonical_authority,
    'responsibility',v_layer.responsibility,'state',v_state
  );
end $function$


-- [40000001057] function public.tgg_one_legs_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_legs_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_train jsonb;
  v_gps jsonb;
  v_journey jsonb;
  v_safe int:=0;
  v_active int:=0;
  v_ready int:=0;
  v_stage int:=1;
  v_stride int:=5;
  v_status text:='idle';
  v_id uuid;
begin
  v_train:=public.tgg_one_freight_train_state();
  v_gps:=public.tgg_one_gps_state();
  v_journey:=public.tgg_one_journey4_state();

  v_safe:=coalesce((v_train->>'safe_ready')::int,0);
  v_active:=coalesce((v_train->>'active_jobs')::int,0);
  v_ready:=coalesce((v_gps->>'ready_steps')::int,0);
  v_stage:=coalesce((v_journey->>'stage_no')::int,1);
  v_stride:=greatest(1,least(
    coalesce((public.tgg_one_lungs_state()->>'recommended_batch_size')::int,5),
    coalesce((public.tgg_speed_booster_state()->>'effective_batch_size')::int,5),
    20
  ));

  if coalesce((public.tgg_one_curse_state()->>'status'),'clear')='restricted' then
    v_status:='restricted';
  elsif v_active>0 then
    v_status:='moving';
  elsif v_safe>0 or v_ready>0 then
    v_status:='ready';
  else
    v_status:='idle';
  end if;

  insert into public.tgg_one_legs_snapshots(
    status,safe_ready,active_jobs,gps_ready_steps,journey_stage,stride_size,locomotion
  )
  values(
    v_status,v_safe,v_active,v_ready,v_stage,v_stride,
    jsonb_build_object(
      'role','safe_forward_motion',
      'movement_policy','only_along_gps_and_head_approved_path',
      'auto_move_user',false,
      'production_authority',false,
      'high_risk_authority',false,
      'max_stride',20
    )
  ) returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'safe_ready',v_safe,'active_jobs',v_active,'gps_ready_steps',v_ready,
    'journey_stage',v_stage,'stride_size',v_stride
  );
end $function$


