-- [40000001059] function public.tgg_one_lungs_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_lungs_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_queued integer:=0;
  v_running integer:=0;
  v_stale integer:=0;
  v_failures integer:=0;
  v_avg numeric:=0;
  v_pressure integer:=0;
  v_speed jsonb;
  v_current integer:=5;
  v_recommended integer:=5;
  v_status text:='healthy';
  v_id uuid;
begin
  select
    count(*) filter(where status='queued'),
    count(*) filter(where status='running'),
    count(*) filter(
      where status in ('queued','running')
      and coalesce(started_at,created_at)<now()-interval '15 minutes'
    )
  into v_queued,v_running,v_stale
  from public.tgg_autobuilder_agent_jobs;

  select count(*) into v_failures
  from public.tgg_build_failures
  where first_seen_at>=now()-interval '1 hour'
    and resolved_at is null;

  select coalesce(avg(extract(epoch from (finished_at-started_at))),0)
  into v_avg
  from public.tgg_autobuilder_cycles
  where finished_at is not null
    and started_at>=now()-interval '24 hours';

  v_pressure:=least(
    100,
    (v_queued*3)+(v_running*5)+(v_stale*20)+(v_failures*25)
      +case when v_avg>120 then 15 when v_avg>60 then 8 else 0 end
  );

  v_speed:=public.tgg_speed_booster_state();
  v_current:=greatest(1,least(25,coalesce((v_speed->>'effective_batch_size')::integer,5)));

  v_recommended:=case
    when v_pressure>=75 then 5
    when v_pressure>=50 then least(10,v_current)
    when v_pressure>=25 then least(15,v_current)
    else v_current
  end;

  if v_stale>0 or v_failures>0 or v_pressure>=75 then
    v_status:='warning';
  elsif v_pressure>=25 then
    v_status:='loaded';
  end if;

  insert into public.tgg_one_lungs_snapshots(
    status,queued_jobs,running_jobs,stale_jobs,recent_failures,
    avg_cycle_seconds,pressure_score,recommended_batch_size,breathing
  )
  values(
    v_status,v_queued,v_running,v_stale,v_failures,
    round(v_avg,2),v_pressure,v_recommended,
    jsonb_build_object(
      'role','system_pacing_and_pressure_governor',
      'inhale','accept_safe_work',
      'exhale','flush_completed_evidence_and_release_locks',
      'can_throttle_down',true,
      'can_raise_hard_ceiling',false,
      'hard_ceiling',25,
      'fallback_batch',5
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'queued_jobs',v_queued,'running_jobs',v_running,'stale_jobs',v_stale,
    'recent_failures',v_failures,'avg_cycle_seconds',round(v_avg,2),
    'pressure_score',v_pressure,'recommended_batch_size',v_recommended
  );
end $function$


