  )
  from public.tgg_one_lungs_snapshots
  order by sensed_at desc limit 1
$function$


-- [40000001061] function public.tgg_one_magic_portal_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_magic_portal_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_magic jsonb;
  v_curse jsonb;
  v_portal jsonb;
  v_missing jsonb:='[]'::jsonb;
  v_layers integer:=0;
  v_ok boolean;
begin
  v_base:=public.tgg_one_sensory_action_completeness();
  v_magic:=public.tgg_one_magic_state();
  v_curse:=public.tgg_one_curse_state();
  v_portal:=public.tgg_lewis_portal_health_state();

  if to_regclass('public.tgg_one_magic_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_one_magic_snapshots');
  end if;
  if to_regclass('public.tgg_one_curse_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_one_curse_snapshots');
  end if;
  if to_regclass('public.tgg_lewis_portal_sessions') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_lewis_portal_sessions');
  end if;
  if to_regclass('public.tgg_lewis_portal_health_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_lewis_portal_health_snapshots');
  end if;

  select count(*) into v_layers
  from public.tgg_one_layers
  where active=true
    and layer_key in (
      'senses','vision','ears','reflexes','scout','gps','hunter','shadow','head','mind','heart','magic',
      'genome','bones','circulation','nervous','curse','immune','lungs','metabolism','detox','muscle',
      'stamina','hands','body','skin','spirit','soul','dream','hair','partner','children','family',
      'veil','matrix_gateway','lewis_portal','planet','universe','the_one'
    );

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and jsonb_array_length(v_missing)=0
    and v_layers=39
    and coalesce(v_magic->>'status','restricted')<>'restricted'
    and coalesce(v_curse->>'status','restricted')<>'restricted'
    and coalesce(v_portal->>'status','restricted')<>'restricted';

  return jsonb_build_object(
    'ok',v_ok,'base',v_base,'magic',v_magic,'curse',v_curse,'lewis_portal',v_portal,
    'required_total_layers',39,'active_total_layers',v_layers,
    'magic_required',true,'curse_breaker_required',true,'lewis_portal_required',true,
    'missing',v_missing,
    'canonical_boundary','AB-006','canonical_source_version','V223',
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000001062] function public.tgg_one_magic_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_magic_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_score numeric:=0;
  v_pressure integer:=0;
  v_batch integer:=5;
  v_vision jsonb;
  v_conflicts jsonb;
  v_qa_clean boolean:=false;
  v_conflicts_clean boolean:=false;
  v_synergy integer:=0;
  v_status text:='dormant';
  v_id uuid;
begin
  v_score:=coalesce((public.tgg_brain_latest_scorecard()->>'safety_score')::numeric,0);
  v_pressure:=coalesce((public.tgg_one_lungs_state()->>'pressure_score')::integer,0);
  v_batch:=coalesce((public.tgg_speed_booster_state()->>'effective_batch_size')::integer,5);
  v_vision:=public.tgg_one_vision_state();
  v_conflicts:=public.tgg_brain_conflict_state();

  v_qa_clean :=
    coalesce((v_vision->>'browser_failures')::integer,0)=0
    and coalesce((v_vision->>'visual_failures')::integer,0)=0
    and coalesce((v_vision->>'stuck_loading')::integer,0)=0
    and coalesce((v_vision->>'duplicate_shell')::integer,0)=0;

  v_conflicts_clean :=
    coalesce((v_conflicts->>'critical_open')::integer,0)=0
    and coalesce((v_conflicts->>'blocked_open')::integer,0)=0;

  v_synergy:=least(
    100,
    greatest(0,round(v_score)::integer)
    -least(30,v_pressure)
    +case when v_qa_clean then 10 else 0 end
    +case when v_conflicts_clean then 10 else 0 end
  );

  if v_score<100 or not v_conflicts_clean then
    v_status:='restricted';
  elsif v_synergy>=100 and v_batch>=20 then
    v_status:='charged';
  elsif v_synergy>=85 then
    v_status:='ready';
  else
    v_status:='dormant';
  end if;

  insert into public.tgg_one_magic_snapshots(
    status,safety_score,pressure_score,effective_batch_size,
    qa_clean,conflicts_clean,synergy_score,magic
  )
  values(
    v_status,v_score,v_pressure,v_batch,v_qa_clean,v_conflicts_clean,v_synergy,
    jsonb_build_object(
      'meaning','verified_positive_synergy_not_supernatural',
      'boost_only_when_safe',true,
      'can_raise_hard_ceiling',false,
      'can_bypass_head',false,
      'production_authority',false,
      'high_risk_authority',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'safety_score',v_score,'pressure_score',v_pressure,
    'effective_batch_size',v_batch,'qa_clean',v_qa_clean,
    'conflicts_clean',v_conflicts_clean,'synergy_score',v_synergy
  );
end $function$


