$function$


-- [40000001064] function public.tgg_one_mask_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_mask_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_art boolean:=false; v_prof boolean:=false; v_status text:='healthy'; v_id uuid;
begin
  select c.relrowsecurity into v_art from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='artists';
  select c.relrowsecurity into v_prof from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='profiles';
  if not coalesce(v_art,false) or not coalesce(v_prof,false) then v_status:='restricted'; end if;
  insert into public.tgg_one_mask_snapshots(status,artists_rls,profiles_rls,safe_public_fields,forbidden_private_fields,mask)
  values(v_status,coalesce(v_art,false),coalesce(v_prof,false),6,5,
    jsonb_build_object(
      'role','identity_and_presentation_boundary',
      'safe_fields',jsonb_build_array('stage_name','bio','avatar_url','instagram','website','youtube'),
      'forbidden_fields',jsonb_build_array('user_id','stripe_account_id','stripe_onboarding_complete','payouts_enabled','profile_role'),
      'impersonation_allowed',false,'auth_bypass_allowed',false,'secret_reveal_allowed',false
    ))
  returning id into v_id;
  return jsonb_build_object('ok',true,'snapshot_id',v_id,'status',v_status,'artists_rls',v_art,'profiles_rls',v_prof,'safe_public_fields',6,'forbidden_private_fields',5);
end $function$


