-- [40000001067] function public.tgg_one_matrix_total_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_matrix_total_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_missing jsonb:='[]'::jsonb;
  v_layers integer:=0;
  v_gateway jsonb;
  v_ok boolean;
begin
  v_base:=public.tgg_one_total_completeness();
  v_gateway:=public.tgg_matrix_gateway_health_state();

  if to_regclass('public.tgg_matrix_gateway_sessions') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_matrix_gateway_sessions');
  end if;
  if to_regclass('public.tgg_matrix_gateway_health_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_matrix_gateway_health_snapshots');
  end if;

  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_matrix_gateway_enter') then
    v_missing:=v_missing||jsonb_build_array('function:tgg_matrix_gateway_enter');
  end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_matrix_gateway_next') then
    v_missing:=v_missing||jsonb_build_array('function:tgg_matrix_gateway_next');
  end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_matrix_gateway_exit') then
    v_missing:=v_missing||jsonb_build_array('function:tgg_matrix_gateway_exit');
  end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_matrix_gateway_state') then
    v_missing:=v_missing||jsonb_build_array('function:tgg_matrix_gateway_state');
  end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_matrix_gateway_health_refresh') then
    v_missing:=v_missing||jsonb_build_array('function:tgg_matrix_gateway_health_refresh');
  end if;

  select count(*) into v_layers
  from public.tgg_one_layers
  where active=true
    and layer_key in (
      'senses','reflexes','scout','shadow','head','mind','heart','genome','bones','circulation',
      'nervous','immune','muscle','stamina','body','skin','spirit','soul','hair',
      'partner','children','family','matrix_gateway','planet','universe','the_one'
    );

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and jsonb_array_length(v_missing)=0
    and v_layers=26
    and coalesce(v_gateway->>'status','restricted')<>'restricted';

  return jsonb_build_object(
    'ok',v_ok,
    'base',v_base,
    'gateway',v_gateway,
    'required_total_layers',26,
    'active_total_layers',v_layers,
    'matrix_gateway_required',true,
    'missing',v_missing,
    'entry_route','artist_world',
    'rabbit_route','artist_games_tv',
    'exit_route','artist_creator_os',
    'auth_required',true,
    'anon_execute_allowed',false,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223',
    'production_auto_publish',false,
    'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000001068] function public.tgg_one_metabolism_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_metabolism_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_lungs jsonb;
  v_speed jsonb;
  v_batch integer:=5;
  v_active integer:=0;
  v_build integer:=0;
  v_qa integer:=0;
  v_recovery integer:=0;
  v_evidence integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  v_lungs:=public.tgg_one_lungs_state();
  v_speed:=public.tgg_speed_booster_state();

  v_batch:=least(
    coalesce((v_speed->>'effective_batch_size')::integer,5),
    coalesce((v_lungs->>'recommended_batch_size')::integer,5),
    25
  );
  v_batch:=greatest(v_batch,1);

  select count(*) into v_active
  from public.tgg_autobuilder_agent_jobs
  where status in ('queued','running');

  v_build:=greatest(1,floor(v_batch*0.50)::integer);
  v_qa:=greatest(1,floor(v_batch*0.25)::integer);
  v_recovery:=greatest(1,floor(v_batch*0.10)::integer);
  v_evidence:=greatest(1,v_batch-v_build-v_qa-v_recovery);

  if coalesce((v_lungs->>'pressure_score')::integer,0)>=75 then
    v_status:='warning';
  elsif v_active>=v_batch then
    v_status:='loaded';
  end if;

  insert into public.tgg_one_metabolism_snapshots(
    status,effective_batch_size,build_budget,qa_reserve,recovery_reserve,
    evidence_reserve,active_load,budget
  )
  values(
    v_status,v_batch,v_build,v_qa,v_recovery,v_evidence,v_active,
    jsonb_build_object(
      'role','workload_energy_budget',
      'build_share',v_build,
      'qa_reserve',v_qa,
      'recovery_reserve',v_recovery,
      'evidence_reserve',v_evidence,
      'never_starve_qa',true,
      'never_starve_recovery',true,
      'never_starve_evidence',true,
      'can_increase_hard_ceiling',false,
      'hard_ceiling',25
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'effective_batch_size',v_batch,'build_budget',v_build,
    'qa_reserve',v_qa,'recovery_reserve',v_recovery,
    'evidence_reserve',v_evidence,'active_load',v_active
  );
end $function$


