-- [40000001071] function public.tgg_one_mirror_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_mirror_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_prod jsonb:=public.tgg_get_production_drift();
  v_runtime jsonb:=public.tgg_runtime_drift_guard();
  v_arch jsonb:=public.tgg_brain_architecture_latest();
  v_prod_count int:=0;
  v_runtime_failed int:=0;
  v_missing int:=0;
  v_stale int:=0;
  v_new int:=0;
  v_intentional boolean:=false;
  v_status text:='clear';
  v_id uuid;
begin
  v_prod_count:=coalesce((v_prod->>'drift_count')::int,0);
  v_runtime_failed:=jsonb_array_length(coalesce(v_runtime->'failed','[]'::jsonb));
  v_missing:=coalesce((v_arch->>'missing_since_previous')::int,0);
  v_stale:=coalesce((v_arch->>'stale_components')::int,0);
  v_new:=coalesce((v_arch->>'new_since_previous')::int,0);

  v_intentional:=
    v_new>0
    and v_missing=0
    and v_stale=0
    and v_prod_count=0
    and v_runtime_failed=0;

  if v_prod_count>0 or v_runtime_failed>0 or v_missing>0 or v_stale>0 then
    v_status:='warning';
  elsif v_intentional then
    v_status:='changed';
  end if;

  if coalesce(v_arch->'summary'->>'canonical_boundary','')<>'AB-006'
     or coalesce(v_arch->'summary'->>'canonical_source_version','')<>'V223' then
    v_status:='restricted';
  end if;

  insert into public.tgg_one_mirror_snapshots(
    status,production_drift_count,runtime_failed_checks,
    architecture_missing,architecture_stale,architecture_new,
    intentional_change,reflection
  )
  values(
    v_status,v_prod_count,v_runtime_failed,v_missing,v_stale,v_new,v_intentional,
    jsonb_build_object(
      'role','self_reflection_and_truth_comparison',
      'compare',jsonb_build_array('intended_state','live_state','evidence'),
      'rewrites_history',false,
      'executes_changes',false,
      'intentional_change_is_not_drift',true,
      'production_baseline',v_prod->>'baseline',
      'runtime_version',v_runtime->>'version',
      'canonical_boundary','AB-006',
      'canonical_source_version','V223'
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',v_status<>'restricted',
    'snapshot_id',v_id,
    'status',v_status,
    'production_drift_count',v_prod_count,
    'runtime_failed_checks',v_runtime_failed,
    'architecture_missing',v_missing,
    'architecture_stale',v_stale,
    'architecture_new',v_new,
    'intentional_change',v_intentional
  );
end $function$


-- [40000001072] function public.tgg_one_mirror_state()
