  'sensed_at',sensed_at
)
from public.tgg_one_mirror_snapshots
order by sensed_at desc limit 1
$function$


-- [40000001073] function public.tgg_one_muscle_plan(p_title text, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_one_muscle_plan(p_title text DEFAULT 'THE ONE Heavy Load'::text, p_limit integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_speed jsonb;
  v_limit integer;
  v_manifest jsonb:='[]'::jsonb;
  v_count integer:=0;
  v_waves integer:=0;
  v_class text:='light';
  v_key text;
  v_id uuid;
begin
  v_speed:=public.tgg_speed_booster_state();
  v_limit:=least(
    coalesce(p_limit,(v_speed->>'effective_batch_size')::integer),
    coalesce((v_speed->>'hard_max_batch_size')::integer,25)
  );
  if v_limit<1 or v_limit>25 then raise exception 'limit_must_be_1_25'; end if;

  with eligible as (
    select t.id,t.task_key,t.title,t.task_type,t.priority,t.risk_level,
           r.release_key,r.target_environment
    from public.tgg_build_tasks t
    join public.tgg_build_milestones m on m.id=t.milestone_id
    join public.tgg_build_releases r on r.id=m.release_id
    where t.status='ready'
      and t.risk_level<>'high'
      and coalesce(r.target_environment,'staging')<>'production'
      and coalesce((r.metadata->>'production_promotion_performed')::boolean,false)=false
      and coalesce((r.metadata->>'production_deploy_performed')::boolean,false)=false
      and coalesce((r.metadata->>'historical_only')::boolean,false)=false
      and coalesce((r.metadata->>'auto_builder_claim_allowed')::boolean,true)=true
    order by t.priority,t.created_at
    limit v_limit
  ),
  checked as (
    select e.*,
      public.tgg_one_skip_check('build_task',e.task_key,'process') as skip_result
    from eligible e
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'task_id',id,'task_key',task_key,'title',title,'task_type',task_type,
      'priority',priority,'risk_level',risk_level,'release_key',release_key,
      'target_environment',target_environment,'lane','start_line'
    ) order by priority,task_key) filter(where coalesce((skip_result->>'skip')::boolean,false)=false),'[]'::jsonb),
    count(*) filter(where coalesce((skip_result->>'skip')::boolean,false)=false)
  into v_manifest,v_count
  from checked;

  if v_count=0 then
    return jsonb_build_object(
      'ok',true,'status','no_work','candidate_count',0,
      'skip_gate_first',true,'production_allowed',false,'high_risk_allowed',false
    );
  end if;

  v_waves:=ceil(v_count::numeric/greatest(1,v_limit))::integer;
  v_class:=case
    when v_count<=5 then 'light'
    when v_count<=10 then 'medium'
    when v_count<=20 then 'heavy'
    else 'xheavy'
  end;
  v_key:='muscle:'||to_char(now(),'YYYYMMDDHH24MISS')||':'||replace(gen_random_uuid()::text,'-','');

  insert into public.tgg_one_muscle_workloads(
    workload_key,title,status,load_class,batch_size,wave_count,source_type,manifest,race,
    production_allowed,high_risk_allowed
  )
  values(
    v_key,coalesce(nullif(trim(p_title),''),'THE ONE Heavy Load'),'planned',v_class,v_limit,v_waves,
    'build_tasks',v_manifest,
    jsonb_build_object(
      'start','skip_it_then_pack',
      'lanes',jsonb_build_array('start_line','sprint','qa_obstacle','evidence_stretch','finish_line'),
      'finish_rule','verified_complete_only'
    ),
    false,false
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'workload_id',v_id,'workload_key',v_key,'status','planned',
    'load_class',v_class,'batch_size',v_limit,'wave_count',v_waves,
    'candidate_count',v_count,'manifest',v_manifest,
    'production_allowed',false,'high_risk_allowed',false
  );
end $function$


-- [40000001074] function public.tgg_one_muscle_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_muscle_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_speed jsonb;
  v_batch integer:=5;
  v_ceiling integer:=25;
  v_ready integer:=0;
  v_building integer:=0;
  v_testing integer:=0;
  v_blocked integer:=0;
  v_approval integer:=0;
  v_finished integer:=0;
  v_skipped integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  v_speed:=public.tgg_speed_booster_state();
  v_batch:=coalesce((v_speed->>'effective_batch_size')::integer,5);
  v_ceiling:=coalesce((v_speed->>'hard_max_batch_size')::integer,25);

  select
    count(*) filter(where status='ready'),
    count(*) filter(where status='building'),
    count(*) filter(where status='testing'),
    count(*) filter(where status='blocked'),
    count(*) filter(where status='approval_required'),
    count(*) filter(where status in ('complete','completed','passed','skipped'))
  into v_ready,v_building,v_testing,v_blocked,v_approval,v_finished
  from public.tgg_build_tasks;

  select count(*) into v_skipped
  from public.tgg_one_skip_decisions
  where skip=true and checked_at>=now()-interval '24 hours';

  if coalesce((v_speed->>'boost_allowed')::boolean,false)=false then
    v_status:='warning';
  elsif v_ready+v_building+v_testing > v_ceiling*3 then
    v_status:='loaded';
  end if;

  insert into public.tgg_one_muscle_snapshots(
    status,effective_batch_size,hard_ceiling,ready_tasks,building_tasks,testing_tasks,
    blocked_tasks,approval_tasks,finished_tasks,skipped_recent,race_state
  )
  values(
    v_status,v_batch,v_ceiling,v_ready,v_building,v_testing,v_blocked,v_approval,v_finished,v_skipped,
    jsonb_build_object(
      'start_line',jsonb_build_object('ready',v_ready),
      'sprint_lane',jsonb_build_object('building',v_building),
      'obstacle_lane',jsonb_build_object('testing',v_testing,'blocked',v_blocked,'approval_required',v_approval),
      'finish_line',jsonb_build_object('finished',v_finished,'skip_it_saved',v_skipped),
      'batch_size',v_batch,'hard_ceiling',v_ceiling
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'effective_batch_size',v_batch,'hard_ceiling',v_ceiling,
    'race',jsonb_build_object(
      'start_line',v_ready,
      'sprint_lane',v_building,
      'testing_lane',v_testing,
      'blocked_pit',v_blocked,
      'approval_pit',v_approval,
      'finish_line',v_finished,
      'skip_it_saved',v_skipped
    )
  );
end $function$


