$function$


-- [40000001076] function public.tgg_one_navigation_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_navigation_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_missing jsonb:='[]'::jsonb;
  v_layers integer:=0;
  v_vision jsonb;
  v_gps jsonb;
  v_ok boolean;
begin
  v_base:=public.tgg_one_hunter_detox_completeness();
  v_vision:=public.tgg_one_vision_state();
  v_gps:=public.tgg_one_gps_state();

  if to_regclass('public.tgg_one_vision_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_one_vision_snapshots');
  end if;
  if to_regclass('public.tgg_one_gps_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_one_gps_snapshots');
  end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_vision_refresh') then
    v_missing:=v_missing||jsonb_build_array('function:tgg_one_vision_refresh');
  end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_gps_refresh') then
    v_missing:=v_missing||jsonb_build_array('function:tgg_one_gps_refresh');
  end if;

  select count(*) into v_layers
  from public.tgg_one_layers
  where active=true
    and layer_key in (
      'senses','vision','reflexes','scout','gps','hunter','shadow','head','mind','heart',
      'genome','bones','circulation','nervous','immune','lungs','metabolism','detox',
      'muscle','stamina','body','skin','spirit','soul','dream','hair','partner','children',
      'family','veil','matrix_gateway','planet','universe','the_one'
    );

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and jsonb_array_length(v_missing)=0
    and v_layers=34
    and coalesce(v_vision->>'status','restricted')<>'restricted'
    and coalesce(v_gps->>'status','restricted')<>'restricted';

  return jsonb_build_object(
    'ok',v_ok,'base',v_base,'vision',v_vision,'gps',v_gps,
    'required_total_layers',34,'active_total_layers',v_layers,
    'vision_required',true,'gps_required',true,'missing',v_missing,
    'canonical_boundary','AB-006','canonical_source_version','V223',
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000001077] function public.tgg_one_nervous_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_nervous_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_new integer:=0;
  v_routed integer:=0;
  v_unprocessed integer:=0;
  v_conflicts integer:=0;
  v_failures integer:=0;
  v_load integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select
    count(*) filter(where status='new'),
    count(*) filter(where status='routed'),
    count(*) filter(where status in ('new','blocked'))
  into v_new,v_routed,v_unprocessed
  from public.tgg_autonomic_events;

  select count(*) into v_conflicts
  from public.tgg_brain_conflicts
  where status='open';

  select count(*) into v_failures
  from public.tgg_build_failures
  where resolved_at is null;

  v_load:=v_new+v_unprocessed+v_conflicts+v_failures;

  if exists(
    select 1 from public.tgg_brain_conflicts
    where status='open' and severity='critical'
  ) then
    v_status:='restricted';
  elsif v_unprocessed>0 or v_conflicts>0 or v_failures>0 then
    v_status:='warning';
  elsif v_load>50 then
    v_status:='busy';
  end if;

  insert into public.tgg_one_nervous_snapshots(
    status,fresh_events,routed_events,unprocessed_events,open_conflicts,
    open_build_failures,signal_load,coordination
  )
  values(
    v_status,v_new,v_routed,v_unprocessed,v_conflicts,v_failures,v_load,
    jsonb_build_object(
      'role','coordination_bus',
      'connects',jsonb_build_array(
        'senses','reflexes','scout','shadow','head','mind','heart','bones',
        'circulation','immune','muscle','stamina','body','spirit','soul','hair','the_one'
      ),
      'can_bypass_head',false,
      'can_execute_production',false,
      'signal_policy','route_and_coordinate_only'
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'fresh_events',v_new,'routed_events',v_routed,
    'unprocessed_events',v_unprocessed,'open_conflicts',v_conflicts,
    'open_build_failures',v_failures,'signal_load',v_load
  );
end $function$


