  order by sensed_at desc limit 1
$function$


-- [40000001079] function public.tgg_one_oracle_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_oracle_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count int:=0; v_conf numeric:=0; v_risk numeric:=0;
  v_cal int:=0; v_calavg numeric:=0;
  v_prod int:=0; v_high int:=0; v_canon int:=0; v_approval int:=0;
  v_status text:='clear'; v_id uuid;
begin
  select count(*),coalesce(avg(confidence),0),coalesce(avg(predicted_risk),0),
         count(*) filter(where production_affected),
         count(*) filter(where high_risk_affected),
         count(*) filter(where canonical_affected),
         count(*) filter(where approval_required)
  into v_count,v_conf,v_risk,v_prod,v_high,v_canon,v_approval
  from public.tgg_brain_change_predictions
  where created_at>=now()-interval '7 days';

  select count(*),coalesce(avg(calibration_score),0)
  into v_cal,v_calavg
  from public.tgg_brain_prediction_calibrations;

  -- Global forecast is advisory. It only becomes a hard stop when the selected target
  -- itself is production/high-risk/canonical/approval gated through HEAD/JACK/HUNTER.
  if v_prod>0 or v_high>0 or v_canon>0 or v_approval>0 or v_risk>=60 then
    v_status:='warning';
  elsif v_count>0 and v_conf<70 then
    v_status:='uncertain';
  end if;

  insert into public.tgg_one_oracle_snapshots(
    status,prediction_count,avg_confidence,avg_risk,calibration_count,avg_calibration,forecast
  )
  values(
    v_status,v_count,round(v_conf,2),round(v_risk,2),v_cal,round(v_calavg,4),
    jsonb_build_object(
      'role','probabilistic_forecast_and_uncertainty',
      'prophecy',false,
      'psychic_claim',false,
      'certainty_claim',false,
      'global_forecast_is_advisory',true,
      'selected_target_still_gated_by_head_jack_hunter',true,
      'production_affected_predictions',v_prod,
      'high_risk_affected_predictions',v_high,
      'canonical_affected_predictions',v_canon,
      'approval_required_predictions',v_approval
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'prediction_count',v_count,'avg_confidence',round(v_conf,2),
    'avg_risk',round(v_risk,2),'calibration_count',v_cal,
    'avg_calibration',round(v_calavg,4),
    'gated_prediction_count',v_prod+v_high+v_canon+v_approval
  );
end $function$


