-- [40000001087] function public.tgg_one_reflex_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_reflex_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_events integer:=0;
  v_failures integer:=0;
  v_qa integer:=0;
  v_provider jsonb;
  v_degraded integer:=0;
  v_blocked integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select count(*) into v_events
  from public.tgg_autonomic_events
  where status='new';

  select count(*) into v_failures
  from public.tgg_build_failures
  where resolved_at is null;

  with latest_browser as (
    select distinct on(task_id,viewport_key) *
    from public.tgg_browser_qa_results
    where checked_at>=now()-interval '24 hours'
    order by task_id,viewport_key,checked_at desc,
      case when lower(coalesce(status,'')) in ('pass','passed','complete','completed','ok','healthy') then 0 else 1 end,
      id desc
  ),
  latest_visual as (
    select distinct on(task_id,viewport_key) *
    from public.tgg_visual_qa_results
    where checked_at>=now()-interval '24 hours'
    order by task_id,viewport_key,checked_at desc,
      case when lower(coalesce(status,'')) in ('pass','passed','complete','completed','ok','healthy') then 0 else 1 end,
      id desc
  )
  select
    (select count(*) from latest_browser where lower(coalesce(status,'')) not in ('pass','passed','complete','completed','ok','healthy'))
    +(select count(*) from latest_visual where lower(coalesce(status,'')) not in ('pass','passed','complete','completed','ok','healthy'))
  into v_qa;

  v_provider:=public.tgg_provider_health_state();
  v_degraded:=coalesce((v_provider->>'degraded')::integer,0);
  v_blocked:=coalesce((v_provider->>'blocked')::integer,0);

  if v_blocked>0 then
    v_status:='restricted';
  elsif v_events>0 or v_failures>0 or v_qa>0 or v_degraded>0 then
    v_status:='alert';
  end if;

  insert into public.tgg_one_reflex_snapshots(
    status,new_events,open_build_failures,current_qa_warnings,provider_degraded,provider_blocked,reaction
  )
  values(
    v_status,v_events,v_failures,v_qa,v_degraded,v_blocked,
    jsonb_build_object(
      'reaction_policy','detect_and_route_only',
      'can_bypass_head',false,
      'can_execute_production',false,
      'safe_immediate_actions',jsonb_build_array('refresh_health','route_event','flag_gap','trigger_safe_watchdog')
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'new_events',v_events,'open_build_failures',v_failures,'current_qa_warnings',v_qa,
    'provider_degraded',v_degraded,'provider_blocked',v_blocked
  );
end $function$


