-- [40000001089] function public.tgg_one_scout_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_scout_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_complete jsonb;
  v_arch jsonb;
  v_provider jsonb;
  v_missing_required integer:=0;
  v_orphan_tasks integer:=0;
  v_orphan_requirements integer:=0;
  v_codesync integer:=0;
  v_stale integer:=0;
  v_missing_arch integer:=0;
  v_failures integer:=0;
  v_events integer:=0;
  v_degraded integer:=0;
  v_blocked integer:=0;
  v_status text:='clean';
  v_findings jsonb:='[]'::jsonb;
  v_id uuid;
begin
  v_complete:=public.tgg_one_completeness();
  v_arch:=public.tgg_brain_architecture_latest();
  v_provider:=public.tgg_provider_health_state();

  v_missing_required:=jsonb_array_length(coalesce(v_complete->'missing','[]'::jsonb))
    + jsonb_array_length(coalesce(v_complete->'base'->'missing_functions','[]'::jsonb))
    + jsonb_array_length(coalesce(v_complete->'base'->'missing_tables','[]'::jsonb))
    + jsonb_array_length(coalesce(v_complete->'base'->'missing_crons','[]'::jsonb))
    + jsonb_array_length(coalesce(v_complete->'base'->'missing_triggers','[]'::jsonb));

  select count(*) into v_orphan_tasks
  from public.tgg_build_tasks t
  left join public.tgg_build_milestones m on m.id=t.milestone_id
  where m.id is null;

  select count(*) into v_orphan_requirements
  from public.tgg_brain_spec_requirements r
  left join public.tgg_brain_specs s on s.id=r.spec_id
  where s.id is null;

  select coalesce(open_issues,0) into v_codesync
  from public.tgg_code_sync_dashboard_state
  where id=1;

  v_stale:=coalesce((v_arch->>'stale_components')::integer,0);
  v_missing_arch:=coalesce((v_arch->>'missing_since_previous')::integer,0);

  select count(*) into v_failures
  from public.tgg_build_failures
  where resolved_at is null;

  select count(*) into v_events
  from public.tgg_autonomic_events
  where status='new';

  v_degraded:=coalesce((v_provider->>'degraded')::integer,0);
  v_blocked:=coalesce((v_provider->>'blocked')::integer,0);

  if v_missing_required>0 then
    v_findings:=v_findings||jsonb_build_array(jsonb_build_object(
      'type','missing_required_piece','count',v_missing_required,'auto_fix_allowed',true
    ));
  end if;

  if v_orphan_tasks>0 then
    v_findings:=v_findings||jsonb_build_array(jsonb_build_object(
      'type','orphan_build_task','count',v_orphan_tasks,'auto_fix_allowed',false
    ));
  end if;

  if v_orphan_requirements>0 then
    v_findings:=v_findings||jsonb_build_array(jsonb_build_object(
      'type','orphan_spec_requirement','count',v_orphan_requirements,'auto_fix_allowed',false
    ));
  end if;

  if v_codesync>0 then
    v_findings:=v_findings||jsonb_build_array(jsonb_build_object(
      'type','codesync_open_issue','count',v_codesync,
      'auto_fix_allowed',false,
      'note','review_only_when_protected_or_canonical_runtime_may_be_involved'
    ));
  end if;

  if v_stale>0 or v_missing_arch>0 then
    v_findings:=v_findings||jsonb_build_array(jsonb_build_object(
      'type','architecture_gap','stale',v_stale,'missing',v_missing_arch,'auto_fix_allowed',true
    ));
  end if;

  if v_failures>0 then
    v_findings:=v_findings||jsonb_build_array(jsonb_build_object(
      'type','open_build_failure','count',v_failures,'auto_fix_allowed',true
    ));
  end if;

  if v_events>0 then
    v_findings:=v_findings||jsonb_build_array(jsonb_build_object(
      'type','unrouted_event','count',v_events,'auto_fix_allowed',true
    ));
  end if;

  if v_degraded>0 or v_blocked>0 then
    v_findings:=v_findings||jsonb_build_array(jsonb_build_object(
      'type','provider_health_issue','degraded',v_degraded,'blocked',v_blocked,
      'auto_fix_allowed',false
    ));
  end if;

  if v_missing_required>0 or v_missing_arch>0 or v_blocked>0 then
    v_status:='restricted';
  elsif v_orphan_tasks>0 or v_orphan_requirements>0 or v_failures>0
     or v_stale>0 or v_degraded>0 then
    v_status:='warning';
  elsif jsonb_array_length(v_findings)>0 then
    v_status:='findings';
  end if;

  insert into public.tgg_one_scout_snapshots(
    status,missing_required_pieces,orphan_build_tasks,orphan_spec_requirements,
    open_codesync_issues,architecture_stale,architecture_missing,open_build_failures,
    pending_events,provider_degraded,provider_blocked,findings
  )
  values(
    v_status,v_missing_required,v_orphan_tasks,v_orphan_requirements,
    v_codesync,v_stale,v_missing_arch,v_failures,v_events,v_degraded,v_blocked,v_findings
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,
    'snapshot_id',v_id,
    'status',v_status,
    'missing_required_pieces',v_missing_required,
    'orphan_build_tasks',v_orphan_tasks,
    'orphan_spec_requirements',v_orphan_requirements,
    'open_codesync_issues',v_codesync,
    'architecture_stale',v_stale,
    'architecture_missing',v_missing_arch,
    'open_build_failures',v_failures,
    'pending_events',v_events,
    'provider_degraded',v_degraded,
    'provider_blocked',v_blocked,
    'findings',v_findings
  );
end $function$


