  limit 1
$function$


-- [40000001091] function public.tgg_one_senses_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_senses_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_browser_fail integer:=0;
  v_console integer:=0;
  v_network integer:=0;
  v_slow integer:=0;
  v_visual_fail integer:=0;
  v_accessibility integer:=0;
  v_overlap integer:=0;
  v_provider jsonb;
  v_provider_degraded integer:=0;
  v_provider_blocked integer:=0;
  v_events integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  with latest as (
    select distinct on(task_id,viewport_key)
      *
    from public.tgg_browser_qa_results
    where checked_at>=now()-interval '24 hours'
    order by task_id,viewport_key,checked_at desc,
      case when lower(coalesce(status,'')) in ('pass','passed','complete','completed','ok','healthy') then 0 else 1 end,
      id desc
  )
  select
    count(*) filter(where lower(coalesce(status,'')) not in ('pass','passed','complete','completed','ok','healthy')),
    coalesce(sum(console_error_count),0),
    coalesce(sum(network_error_count),0),
    count(*) filter(where coalesce(load_ms,0)>3000)
  into v_browser_fail,v_console,v_network,v_slow
  from latest;

  with latest as (
    select distinct on(task_id,viewport_key)
      *
    from public.tgg_visual_qa_results
    where checked_at>=now()-interval '24 hours'
    order by task_id,viewport_key,checked_at desc,
      case when lower(coalesce(status,'')) in ('pass','passed','complete','completed','ok','healthy') then 0 else 1 end,
      id desc
  )
  select
    count(*) filter(where lower(coalesce(status,'')) not in ('pass','passed','complete','completed','ok','healthy')),
    coalesce(sum(accessibility_findings),0),
    coalesce(sum(overlap_count),0)
  into v_visual_fail,v_accessibility,v_overlap
  from latest;

  v_provider:=public.tgg_provider_health_state();
  v_provider_degraded:=coalesce((v_provider->>'degraded')::integer,0);
  v_provider_blocked:=coalesce((v_provider->>'blocked')::integer,0);

  select count(*) into v_events
  from public.tgg_autonomic_events
  where status='new';

  if v_provider_blocked>0 then
    v_status:='restricted';
  elsif v_browser_fail>0 or v_visual_fail>0 or v_provider_degraded>0
     or v_console>0 or v_network>0 or v_accessibility>0 or v_overlap>0 or v_slow>0 then
    v_status:='warning';
  end if;

  insert into public.tgg_one_senses_snapshots(
    status,browser_failures,browser_console_errors,browser_network_errors,slow_routes,
    visual_failures,visual_accessibility_findings,visual_overlap_findings,
    provider_degraded,provider_blocked,new_events,signals
  )
  values(
    v_status,v_browser_fail,v_console,v_network,v_slow,
    v_visual_fail,v_accessibility,v_overlap,
    v_provider_degraded,v_provider_blocked,v_events,
    jsonb_build_object(
      'evidence_policy','latest_per_task_viewport',
      'browser_window','24 hours',
      'visual_window','24 hours',
      'providers',v_provider,
      'real_time_events',v_events
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'browser_failures',v_browser_fail,'browser_console_errors',v_console,
    'browser_network_errors',v_network,'slow_routes',v_slow,
    'visual_failures',v_visual_fail,'visual_accessibility_findings',v_accessibility,
    'visual_overlap_findings',v_overlap,
    'provider_degraded',v_provider_degraded,'provider_blocked',v_provider_blocked,
    'new_events',v_events
  );
end $function$


