-- [40000001093] function public.tgg_one_sensory_action_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_sensory_action_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_ears jsonb;
  v_hands jsonb;
  v_missing jsonb:='[]'::jsonb;
  v_layers integer:=0;
  v_ok boolean;
begin
  v_base:=public.tgg_one_navigation_completeness();
  v_ears:=public.tgg_one_ears_state();
  v_hands:=public.tgg_one_hands_state();

  if to_regclass('public.tgg_one_ears_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_one_ears_snapshots');
  end if;
  if to_regclass('public.tgg_one_hands_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_one_hands_snapshots');
  end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname='tgg_one_ears_refresh') then
    v_missing:=v_missing||jsonb_build_array('function:tgg_one_ears_refresh');
  end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname='tgg_one_hands_refresh') then
    v_missing:=v_missing||jsonb_build_array('function:tgg_one_hands_refresh');
  end if;

  select count(*) into v_layers
  from public.tgg_one_layers
  where active=true
    and layer_key in (
      'senses','vision','ears','reflexes','scout','gps','hunter','shadow','head','mind','heart',
      'genome','bones','circulation','nervous','immune','lungs','metabolism','detox','muscle',
      'stamina','hands','body','skin','spirit','soul','dream','hair','partner','children','family',
      'veil','matrix_gateway','planet','universe','the_one'
    );

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and jsonb_array_length(v_missing)=0
    and v_layers=36
    and coalesce(v_ears->>'status','restricted')<>'restricted'
    and coalesce(v_hands->>'status','restricted')<>'restricted';

  return jsonb_build_object(
    'ok',v_ok,'base',v_base,'ears',v_ears,'hands',v_hands,
    'required_total_layers',36,'active_total_layers',v_layers,
    'ears_required',true,'hands_required',true,'missing',v_missing,
    'canonical_boundary','AB-006','canonical_source_version','V223',
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000001094] function public.tgg_one_skin_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_skin_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_exposures integer:=0;
  v_public_readonly integer:=0;
  v_provider jsonb;
  v_blocked integer:=0;
  v_visual integer:=0;
  v_access integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select count(*) into v_exposures
  from pg_proc p
  join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public'
    and p.proname like 'tgg_one_%'
    and p.prosecdef=true
    and (
      has_function_privilege('anon',p.oid,'EXECUTE')
      or has_function_privilege('authenticated',p.oid,'EXECUTE')
    );

  select count(*) into v_public_readonly
  from pg_proc p
  join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public'
    and p.proname like 'tgg_one_%'
    and p.prosecdef=false
    and (
      has_function_privilege('anon',p.oid,'EXECUTE')
      or has_function_privilege('authenticated',p.oid,'EXECUTE')
    );

  v_provider:=public.tgg_provider_health_state();
  v_blocked:=coalesce((v_provider->>'blocked')::integer,0);

  with latest as (
    select distinct on(task_id,viewport_key) *
    from public.tgg_visual_qa_results
    where checked_at>=now()-interval '24 hours'
    order by task_id,viewport_key,checked_at desc,
      case when lower(coalesce(status,'')) in ('pass','passed','complete','completed','ok','healthy') then 0 else 1 end,
      id desc
  )
  select
    count(*) filter(where lower(coalesce(status,'')) not in ('pass','passed','complete','completed','ok','healthy')),
    coalesce(sum(accessibility_findings),0)
  into v_visual,v_access
  from latest;

  if v_exposures>0 or v_blocked>0 then
    v_status:='restricted';
  elsif v_visual>0 or v_access>0 then
    v_status:='warning';
  end if;

  insert into public.tgg_one_skin_snapshots(
    status,unsafe_one_function_exposures,provider_blocked,
    current_visual_regressions,current_accessibility_findings,armor
  )
  values(
    v_status,v_exposures,v_blocked,v_visual,v_access,
    jsonb_build_object(
      'boundary_role','external_surface_and_armor',
      'unsafe_privileged_exposures',v_exposures,
      'intentional_invoker_read_surfaces',v_public_readonly,
      'provider_boundary_clean',v_blocked=0,
      'surface_visual_clean',v_visual=0,
      'surface_accessibility_clean',v_access=0,
      'destructive_auto_action',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'unsafe_privileged_exposures',v_exposures,
    'intentional_invoker_read_surfaces',v_public_readonly,
    'provider_blocked',v_blocked,
    'current_visual_regressions',v_visual,
    'current_accessibility_findings',v_access
  );
end $function$


