$function$


-- [40000001096] function public.tgg_one_skip_batch(p_items jsonb)
CREATE OR REPLACE FUNCTION public.tgg_one_skip_batch(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_results jsonb:='[]'::jsonb;
  v_item jsonb;
  v_result jsonb;
  v_skip_count integer:=0;
  v_process_count integer:=0;
begin
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' then
    raise exception 'items_must_be_array';
  end if;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_result:=public.tgg_one_skip_check(
      v_item->>'item_type',
      v_item->>'item_key',
      coalesce(v_item->>'requested_action','process')
    );
    v_results:=v_results||jsonb_build_array(v_result);
    if coalesce((v_result->>'skip')::boolean,false) then
      v_skip_count:=v_skip_count+1;
    else
      v_process_count:=v_process_count+1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'skip_count',v_skip_count,
    'process_count',v_process_count,
    'results',v_results
  );
end $function$


-- [40000001097] function public.tgg_one_skip_check(p_item_type text, p_item_key text, p_requested_action text)
CREATE OR REPLACE FUNCTION public.tgg_one_skip_check(p_item_type text, p_item_key text, p_requested_action text DEFAULT 'process'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_type text:=lower(trim(coalesce(p_item_type,'')));
  v_key text:=trim(coalesce(p_item_key,''));
  v_action text:=lower(trim(coalesce(p_requested_action,'process')));
  v_skip boolean:=false;
  v_reason text:='not_terminal';
  v_evidence jsonb:='{}'::jsonb;
  v_status text;
  v_approved_at timestamptz;
  v_promoted_at timestamptz;
  v_applied_at timestamptz;
  v_decision_key text;
begin
  if v_key='' then raise exception 'item_key_required'; end if;

  case v_type
    when 'build_task' then
      select status into v_status
      from public.tgg_build_tasks
      where task_key=v_key
      order by updated_at desc limit 1;

      if found and lower(coalesce(v_status,'')) in ('complete','completed','passed','skipped') then
        v_skip:=true; v_reason:='already_complete';
      elsif found and lower(coalesce(v_status,''))='approval_required' and v_action in ('approve','approval') then
        v_skip:=false; v_reason:='approval_still_required';
      end if;

      v_evidence:=jsonb_build_object('status',v_status);

    when 'game_idea' then
      select status into v_status
      from public.tgg_game_idea_inbox
      where id::text=v_key or idea_hash=v_key
      order by updated_at desc limit 1;

      if found and lower(coalesce(v_status,'')) in ('complete','completed','canceled') then
        v_skip:=true; v_reason:='idea_already_terminal';
      end if;

      v_evidence:=jsonb_build_object('status',v_status);

    when 'spec' then
      select status into v_status
      from public.tgg_brain_specs
      where spec_key=v_key or id::text=v_key
      order by updated_at desc limit 1;

      if found and lower(coalesce(v_status,'')) in ('complete','completed','superseded') then
        v_skip:=true; v_reason:='spec_already_terminal';
      end if;

      v_evidence:=jsonb_build_object('status',v_status);

    when 'release_candidate' then
      select status,approved_at,promoted_at
      into v_status,v_approved_at,v_promoted_at
      from public.tgg_build_release_candidates
      where candidate_key=v_key or id::text=v_key
      order by updated_at desc limit 1;

      if found and v_action in ('approve','approval') and v_approved_at is not null then
        v_skip:=true; v_reason:='already_approved';
      elsif found and v_action in ('promote','promotion','deploy') and v_promoted_at is not null then
        v_skip:=true; v_reason:='already_promoted';
      elsif found and lower(coalesce(v_status,'')) in ('complete','completed','canceled') then
        v_skip:=true; v_reason:='candidate_already_terminal';
      end if;

      v_evidence:=jsonb_build_object(
        'status',v_status,'approved_at',v_approved_at,'promoted_at',v_promoted_at
      );

    when 'master_change' then
      select status,applied_at
      into v_status,v_applied_at
      from public.tgg_master_change_queue
      where id::text=v_key
      order by requested_at desc limit 1;

      if found and (v_applied_at is not null or lower(coalesce(v_status,'')) in ('applied','complete','completed')) then
        v_skip:=true; v_reason:='master_change_already_applied';
      end if;

      v_evidence:=jsonb_build_object('status',v_status,'applied_at',v_applied_at);

    else
      v_skip:=false;
      v_reason:='unsupported_item_type_no_skip';
      v_evidence:=jsonb_build_object('supported',false);
  end case;

  v_decision_key:='skip:'||md5(v_type||':'||v_key||':'||v_action||':'||coalesce(v_evidence::text,'{}'));

  insert into public.tgg_one_skip_decisions(
    decision_key,item_type,item_key,requested_action,skip,reason,evidence,checked_at
  )
  values(v_decision_key,v_type,v_key,v_action,v_skip,v_reason,v_evidence,now())
  on conflict(decision_key) do update
  set skip=excluded.skip,reason=excluded.reason,evidence=excluded.evidence,checked_at=now();

  return jsonb_build_object(
    'ok',true,
    'item_type',v_type,
    'item_key',v_key,
    'requested_action',v_action,
    'skip',v_skip,
    'reason',v_reason,
    'evidence',v_evidence
  );
end $function$


-- [40000001098] function public.tgg_one_skip_state()
CREATE OR REPLACE FUNCTION public.tgg_one_skip_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'checks_24h',count(*) filter(where checked_at>=now()-interval '24 hours'),
    'skipped_24h',count(*) filter(where checked_at>=now()-interval '24 hours' and skip=true),
    'processed_24h',count(*) filter(where checked_at>=now()-interval '24 hours' and skip=false),
    'top_skip_reasons',coalesce((
      select jsonb_agg(jsonb_build_object('reason',reason,'count',cnt) order by cnt desc)
      from (
        select reason,count(*) cnt
        from public.tgg_one_skip_decisions
        where checked_at>=now()-interval '24 hours' and skip=true
        group by reason
        order by cnt desc
        limit 10
      ) q
    ),'[]'::jsonb)
  )
  from public.tgg_one_skip_decisions
$function$


-- [40000001099] function public.tgg_one_stamina_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_stamina_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_retryable integer:=0;
  v_exhausted integer:=0;
  v_stale_ideas integer:=0;
  v_recoveries integer:=0;
  v_failures integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  select
    count(*) filter(where status not in ('complete','completed','passed','skipped')
      and retry_count < max_retries),
    count(*) filter(where status not in ('complete','completed','passed','skipped')
      and retry_count >= max_retries)
  into v_retryable,v_exhausted
  from public.tgg_build_tasks;

  select count(*) into v_stale_ideas
  from public.tgg_game_idea_inbox
  where status in ('planning','queued','building','testing','staged')
    and coalesce(last_heartbeat_at,claimed_at,updated_at,created_at) < now()-interval '15 minutes';

  select count(*) into v_recoveries
  from public.tgg_game_idea_inbox
  where retry_count>0 and updated_at>=now()-interval '24 hours';

  select count(*) into v_failures
  from public.tgg_build_failures
  where resolved_at is null;

  if v_exhausted>0 then
    v_status:='restricted';
  elsif v_stale_ideas>0 or v_failures>0 then
    v_status:='warning';
  elsif v_retryable>20 then
    v_status:='loaded';
  end if;

  insert into public.tgg_one_stamina_snapshots(
    status,retryable_tasks,exhausted_tasks,stale_game_ideas,recent_recoveries,open_failures,endurance
  )
  values(
    v_status,v_retryable,v_exhausted,v_stale_ideas,v_recoveries,v_failures,
    jsonb_build_object(
      'wave_continuation',true,
      'retry_budget_respected',true,
      'stale_recovery','tgg_game_idea_recover_stale',
      'watchdog','tgg_autobuilder_watchdog',
      'checkpointing','operational_and_brain_checkpoints',
      'never_exceed_retry_budget',true
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'retryable_tasks',v_retryable,'exhausted_tasks',v_exhausted,
    'stale_game_ideas',v_stale_ideas,'recent_recoveries',v_recoveries,'open_failures',v_failures
  );
end $function$


-- [40000001100] function public.tgg_one_stamina_state()
CREATE OR REPLACE FUNCTION public.tgg_one_stamina_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'status',status,'retryable_tasks',retryable_tasks,'exhausted_tasks',exhausted_tasks,
    'stale_game_ideas',stale_game_ideas,'recent_recoveries',recent_recoveries,
    'open_failures',open_failures,'endurance',endurance,'sensed_at',sensed_at
  )
  from public.tgg_one_stamina_snapshots
  order by sensed_at desc limit 1
$function$


-- [40000001101] function public.tgg_one_state()
CREATE OR REPLACE FUNCTION public.tgg_one_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_layers jsonb:='[]'::jsonb;
  v_status text:='healthy';
  r record;
  v_layer jsonb;
begin
  for r in
    select layer_key from public.tgg_one_layers
    where active=true and layer_key<>'the_one'
    order by layer_order
  loop
    v_layer:=public.tgg_one_layer_state(r.layer_key);
    v_layers:=v_layers||jsonb_build_array(v_layer);
  end loop;

  if exists(select 1 from jsonb_array_elements(v_layers) x where x->>'status'='restricted') then
    v_status:='restricted';
  elsif exists(select 1 from jsonb_array_elements(v_layers) x where x->>'status'='warning') then
    v_status:='warning';
  end if;

  return jsonb_build_object(
    'name','THE ONE','status',v_status,'layers',v_layers,
    'law',jsonb_build_object(
      'senses_perceive',true,'shadow_sees_hidden',true,'head_governs',true,
      'mind_understands',true,'heart_prioritizes_value',true,'body_executes',true,
      'spirit_keeps_motion',true,'soul_preserves_identity',true,
      'hair_expresses_identity',true,'the_one_unifies',true
    ),
    'production_auto_publish',false,'production_promotion_allowed',false,
    'high_risk_auto_execute',false,'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end $function$


-- [40000001102] function public.tgg_one_total_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_total_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_core jsonb;
  v_missing jsonb:='[]'::jsonb;
  v_layers integer:=0;
  v_ok boolean;
begin
  v_core:=public.tgg_one_completeness();

  if to_regclass('public.tgg_one_partner_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_partner_snapshots'); end if;
  if to_regclass('public.tgg_one_children_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_children_snapshots'); end if;
  if to_regclass('public.tgg_one_family_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_family_snapshots'); end if;
  if to_regclass('public.tgg_one_planet_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_planet_snapshots'); end if;
  if to_regclass('public.tgg_one_universe_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_universe_snapshots'); end if;
  if to_regclass('public.tgg_one_genome_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_genome_snapshots'); end if;
  if to_regclass('public.tgg_one_skin_snapshots') is null then v_missing:=v_missing||jsonb_build_array('table:tgg_one_skin_snapshots'); end if;

  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_partner_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_partner_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_children_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_children_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_family_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_family_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_planet_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_planet_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_universe_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_universe_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_genome_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_genome_refresh'); end if;
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_one_skin_refresh') then v_missing:=v_missing||jsonb_build_array('function:tgg_one_skin_refresh'); end if;

  select count(*) into v_layers
  from public.tgg_one_layers
  where active=true
    and layer_key in (
      'senses','reflexes','scout','shadow','head','mind','heart','genome','bones','circulation',
      'nervous','immune','muscle','stamina','body','skin','spirit','soul','hair',
      'partner','children','family','planet','universe','the_one'
    );

  v_ok:=coalesce((v_core->>'ok')::boolean,false)
    and jsonb_array_length(v_missing)=0
    and v_layers=25;

  return jsonb_build_object(
    'ok',v_ok,
    'core',v_core,
    'required_total_layers',25,
    'active_total_layers',v_layers,
    'missing',v_missing,
    'family_ring_required',true,
    'planet_required',true,
    'universe_required',true,
    'genome_required',true,
    'skin_required',true,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223',
    'production_auto_publish',false,
    'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000001103] function public.tgg_one_transition_allowed(p_choice_key text)
CREATE OR REPLACE FUNCTION public.tgg_one_transition_allowed(p_choice_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
