-- [40000001104] function public.tgg_one_universe_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_universe_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_projects integer:=0; v_goals integer:=0; v_worlds integer:=0;
  v_status text:='healthy'; v_id uuid;
begin
  select count(*) into v_projects
  from public.tgg_build_projects
  where lower(coalesce(status,'')) not in ('complete','completed','archived','canceled');

  select count(*) into v_goals
  from public.tgg_brain_goals
  where status not in ('complete','completed','canceled');

  select count(*) into v_worlds
  from public.tgg_world_blueprints
  where lower(coalesce(status,'')) in ('active','ready','passed','complete','completed','approved');

  if v_worlds=0 then v_status:='warning';
  elsif v_projects+v_goals>25 then v_status:='busy';
  end if;

  insert into public.tgg_one_universe_snapshots(
    status,active_projects,active_goals,active_world_blueprints,universe_state
  )
  values(
    v_status,v_projects,v_goals,v_worlds,
    jsonb_build_object(
      'scope','all_projects_and_worlds','planet','TGG World',
      'family_works_together',true,'the_one_is_final_unifier',true,
      'production_auto_publish',false,'high_risk_auto_execute',false,
      'canonical_boundary','AB-006','canonical_source_version','V223'
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'active_projects',v_projects,'active_goals',v_goals,'active_world_blueprints',v_worlds
  );
end $function$


