  order by sensed_at desc limit 1
$function$


-- [40000001106] function public.tgg_one_veiled_matrix_completeness()
CREATE OR REPLACE FUNCTION public.tgg_one_veiled_matrix_completeness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_veil jsonb;
  v_missing jsonb:='[]'::jsonb;
  v_layers integer:=0;
  v_ok boolean;
begin
  v_base:=public.tgg_one_matrix_total_completeness();
  v_veil:=public.tgg_veil_health_state();

  if to_regclass('public.tgg_veil_health_snapshots') is null then
    v_missing:=v_missing||jsonb_build_array('table:tgg_veil_health_snapshots');
  end if;

  if not exists(
    select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname='tgg_veil_route_decision'
  ) then
    v_missing:=v_missing||jsonb_build_array('function:tgg_veil_route_decision');
  end if;

  if not exists(
    select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname='tgg_veil_health_refresh'
  ) then
    v_missing:=v_missing||jsonb_build_array('function:tgg_veil_health_refresh');
  end if;

  if not exists(
    select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname='tgg_veil_health_state'
  ) then
    v_missing:=v_missing||jsonb_build_array('function:tgg_veil_health_state');
  end if;

  select count(*) into v_layers
  from public.tgg_one_layers
  where active=true
    and layer_key in (
      'senses','reflexes','scout','shadow','head','mind','heart','genome','bones','circulation',
      'nervous','immune','muscle','stamina','body','skin','spirit','soul','hair',
      'partner','children','family','veil','matrix_gateway','planet','universe','the_one'
    );

  v_ok:=coalesce((v_base->>'ok')::boolean,false)
    and jsonb_array_length(v_missing)=0
    and v_layers=27
    and coalesce(v_veil->>'status','restricted')<>'restricted';

  return jsonb_build_object(
    'ok',v_ok,
    'base',v_base,
    'veil',v_veil,
    'required_total_layers',27,
    'active_total_layers',v_layers,
    'veil_required',true,
    'matrix_gateway_required',true,
    'missing',v_missing,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223',
    'production_auto_publish',false,
    'production_promotion_allowed',false,
    'high_risk_auto_execute',false
  );
end $function$


-- [40000001107] function public.tgg_one_veiled_matrix_cycle()
CREATE OR REPLACE FUNCTION public.tgg_one_veiled_matrix_cycle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
