    'production_promotion_allowed',false,
    'high_risk_auto_execute',false,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end $function$


-- [40000001108] function public.tgg_one_vision_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_vision_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_browser_fail integer:=0;
  v_visual_fail integer:=0;
  v_overlap integer:=0;
  v_clip integer:=0;
  v_stuck integer:=0;
  v_dup integer:=0;
  v_access integer:=0;
  v_slow integer:=0;
  v_status text:='healthy';
  v_id uuid;
begin
  with latest_browser as (
    select distinct on(task_id,viewport_key) *
    from public.tgg_browser_qa_results
    where checked_at>=now()-interval '24 hours'
    order by task_id,viewport_key,checked_at desc,
      case when lower(coalesce(status,'')) in ('pass','passed','complete','completed','ok','healthy') then 0 else 1 end,
      id desc
  ),
  latest_visual as (
    select distinct on(task_id,viewport_key) *
    from public.tgg_visual_qa_results
    where checked_at>=now()-interval '24 hours'
    order by task_id,viewport_key,checked_at desc,
      case when lower(coalesce(status,'')) in ('pass','passed','complete','completed','ok','healthy') then 0 else 1 end,
      id desc
  )
  select
    (select count(*) from latest_browser where lower(coalesce(status,'')) not in ('pass','passed','complete','completed','ok','healthy')),
    (select count(*) from latest_visual where lower(coalesce(status,'')) not in ('pass','passed','complete','completed','ok','healthy')),
    coalesce((select sum(overlap_count) from latest_browser),0)+coalesce((select sum(overlap_count) from latest_visual),0),
    coalesce((select sum(clipped_text_count) from latest_browser),0)+coalesce((select sum(clipped_text_count) from latest_visual),0),
    coalesce((select count(*) from latest_browser where stuck_loading),0)+coalesce((select sum(stuck_loading_count) from latest_visual),0),
    coalesce((select count(*) from latest_browser where duplicate_shell),0)+coalesce((select sum(duplicate_shell_count) from latest_visual),0),
    coalesce((select sum(accessibility_findings) from latest_visual),0),
    coalesce((select count(*) from latest_browser where load_ms>3000),0)
  into v_browser_fail,v_visual_fail,v_overlap,v_clip,v_stuck,v_dup,v_access,v_slow;

  if v_browser_fail>0 or v_visual_fail>0 or v_stuck>0 or v_dup>0 then
    v_status:='warning';
  end if;

  insert into public.tgg_one_vision_snapshots(
    status,browser_failures,visual_failures,overlap_total,clipped_text_total,
    stuck_loading,duplicate_shell,accessibility_findings,slow_routes,vision
  )
  values(
    v_status,v_browser_fail,v_visual_fail,v_overlap,v_clip,
    v_stuck,v_dup,v_access,v_slow,
    jsonb_build_object(
      'role','latest_evidence_visual_and_browser_perception',
      'latest_per_task_viewport',true,
      'prefer_pass_on_timestamp_tie',true,
      'stale_failure_reuse',false,
      'auto_fix_without_evidence',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'browser_failures',v_browser_fail,'visual_failures',v_visual_fail,
    'overlap_total',v_overlap,'clipped_text_total',v_clip,'stuck_loading',v_stuck,
    'duplicate_shell',v_dup,'accessibility_findings',v_access,'slow_routes',v_slow
  );
end $function$


-- [40000001109] function public.tgg_one_vision_state()
