    'vision',vision,'sensed_at',sensed_at
  )
  from public.tgg_one_vision_snapshots
  order by sensed_at desc limit 1
$function$


-- [40000001110] function public.tgg_one_voice_refresh()
CREATE OR REPLACE FUNCTION public.tgg_one_voice_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_open int:=0; v_critical int:=0; v_queued int:=0; v_failed int:=0;
  v_status text:='healthy'; v_id uuid;
begin
  select count(*) filter(where status='open'),
         count(*) filter(where status='open' and severity='critical')
    into v_open,v_critical
  from public.tgg_operational_alerts;

  select count(*) filter(where status in ('queued','pending')),
         count(*) filter(where status in ('failed','error'))
    into v_queued,v_failed
  from public.tgg_operational_notification_outbox;

  if v_critical>0 then v_status:='restricted';
  elsif v_failed>0 then v_status:='warning';
  elsif v_open>0 or v_queued>20 then v_status:='busy';
  end if;

  insert into public.tgg_one_voice_snapshots(
    status,open_alerts,critical_alerts,queued_notifications,failed_notifications,voice
  ) values (
    v_status,v_open,v_critical,v_queued,v_failed,
    jsonb_build_object(
      'role','meaningful_status_and_alert_language',
      'speak_only_when_meaningful',true,
      'no_fabricated_messages',true,
      'uses_existing_notification_pipeline',true,
      'can_send_without_existing_authorized_pipeline',false
    )
  ) returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'open_alerts',v_open,'critical_alerts',v_critical,
    'queued_notifications',v_queued,'failed_notifications',v_failed
  );
end $function$


