-- [40000001113] function public.tgg_opportunity_application_review(p_application_id uuid, p_status text)
CREATE OR REPLACE FUNCTION public.tgg_opportunity_application_review(p_application_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_status text:=lower(btrim(coalesce(p_status,'')));v_id uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if v_status not in ('submitted','shortlisted','accepted','rejected') then raise exception 'APPLICATION_STATUS_INVALID'; end if;

      update public.tgg_opportunity_applications a
      set status=v_status,updated_at=now()
      where a.id=p_application_id
        and exists(
          select 1 from public.tgg_opportunities o
          where o.id=a.opportunity_id and o.created_by=v_uid
        )
      returning id into v_id;

      if v_id is null then raise exception 'APPLICATION_NOT_FOUND_OR_NOT_OWNED'; end if;
      return jsonb_build_object('ok',true,'application_id',v_id,'status',v_status);
    end $function$


-- [40000001114] function public.tgg_opportunity_apply(p_opportunity_id uuid, p_message text, p_portfolio_url text)
CREATE OR REPLACE FUNCTION public.tgg_opportunity_apply(p_opportunity_id uuid, p_message text DEFAULT NULL::text, p_portfolio_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_id uuid;v_owner uuid;v_deadline timestamptz;v_status text;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select created_by,deadline,status into v_owner,v_deadline,v_status
      from public.tgg_opportunities where id=p_opportunity_id;
      if v_owner is null then raise exception 'OPPORTUNITY_NOT_FOUND'; end if;
      if v_owner=v_uid then raise exception 'CANNOT_APPLY_TO_OWN_OPPORTUNITY'; end if;
      if v_status<>'open' then raise exception 'OPPORTUNITY_NOT_OPEN'; end if;
      if v_deadline is not null and v_deadline<now() then raise exception 'OPPORTUNITY_DEADLINE_PASSED'; end if;

      insert into public.tgg_opportunity_applications(opportunity_id,applicant_user_id,message,portfolio_url,status)
      values(
        p_opportunity_id,v_uid,
        nullif(btrim(coalesce(p_message,'')),''),
        nullif(btrim(coalesce(p_portfolio_url,'')),''),
        'submitted'
      )
      on conflict(opportunity_id,applicant_user_id) do update set
        message=excluded.message,
        portfolio_url=excluded.portfolio_url,
        status='submitted',
        updated_at=now()
      returning id into v_id;

      return jsonb_build_object('ok',true,'application_id',v_id,'status','submitted');
    end $function$


-- [40000001115] function public.tgg_opportunity_create(p_title text, p_description text, p_opportunity_type text, p_city text, p_region text, p_remote_ok boolean, p_compensation_type text, p_deadline timestamp with time zone)
CREATE OR REPLACE FUNCTION public.tgg_opportunity_create(p_title text, p_description text DEFAULT NULL::text, p_opportunity_type text DEFAULT 'collab'::text, p_city text DEFAULT NULL::text, p_region text DEFAULT NULL::text, p_remote_ok boolean DEFAULT true, p_compensation_type text DEFAULT 'unspecified'::text, p_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_artist uuid;v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'TITLE_REQUIRED'; end if;
  select id into v_artist from public.artists where user_id=v_uid order by created_at limit 1;
  insert into public.tgg_opportunities(created_by,artist_id,opportunity_type,title,description,city,region,remote_ok,compensation_type,deadline,status)
  values(v_uid,v_artist,coalesce(nullif(btrim(coalesce(p_opportunity_type,'')),''),'collab'),left(btrim(p_title),180),nullif(btrim(coalesce(p_description,'')),''),
    nullif(btrim(coalesce(p_city,'')),''),nullif(btrim(coalesce(p_region,'')),''),coalesce(p_remote_ok,true),
    coalesce(nullif(btrim(coalesce(p_compensation_type,'')),''),'unspecified'),p_deadline,'open')
  returning id into v_id;
  return jsonb_build_object('ok',true,'opportunity_id',v_id,'status','open');
end $function$


-- [40000001116] function public.tgg_opportunity_delete(p_opportunity_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_opportunity_delete(p_opportunity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  delete from public.tgg_opportunities where id=p_opportunity_id and created_by=v_uid returning id into v_id;
  if v_id is null then raise exception 'OPPORTUNITY_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'opportunity_id',v_id,'deleted',true);
end $function$


-- [40000001117] function public.tgg_opportunity_set_open(p_opportunity_id uuid, p_open boolean)
CREATE OR REPLACE FUNCTION public.tgg_opportunity_set_open(p_opportunity_id uuid, p_open boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_status text:=case when coalesce(p_open,false) then 'open' else 'closed' end;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  update public.tgg_opportunities set status=v_status
  where id=p_opportunity_id and created_by=v_uid returning id into v_id;
  if v_id is null then raise exception 'OPPORTUNITY_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'opportunity_id',v_id,'status',v_status);
end $function$


-- [40000001118] function public.tgg_opportunity_update(p_opportunity_id uuid, p_title text, p_description text, p_opportunity_type text, p_city text, p_region text, p_remote_ok boolean, p_compensation_type text, p_deadline timestamp with time zone)
CREATE OR REPLACE FUNCTION public.tgg_opportunity_update(p_opportunity_id uuid, p_title text, p_description text, p_opportunity_type text, p_city text, p_region text, p_remote_ok boolean, p_compensation_type text, p_deadline timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'TITLE_REQUIRED'; end if;
  update public.tgg_opportunities
  set title=left(btrim(p_title),180),description=nullif(btrim(coalesce(p_description,'')),''),
      opportunity_type=coalesce(nullif(btrim(coalesce(p_opportunity_type,'')),''),opportunity_type),
      city=nullif(btrim(coalesce(p_city,'')),''),region=nullif(btrim(coalesce(p_region,'')),''),
      remote_ok=coalesce(p_remote_ok,true),compensation_type=coalesce(nullif(btrim(coalesce(p_compensation_type,'')),''),'unspecified'),
      deadline=p_deadline
  where id=p_opportunity_id and created_by=v_uid
  returning id into v_id;
  if v_id is null then raise exception 'OPPORTUNITY_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'opportunity_id',v_id);
end $function$


-- [40000001119] function public.tgg_opportunity_withdraw(p_opportunity_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_opportunity_withdraw(p_opportunity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
