-- [40000001121] function public.tgg_owner_provider_completion_checklist()
CREATE OR REPLACE FUNCTION public.tgg_owner_provider_completion_checklist()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_role text:=coalesce(auth.jwt()->'app_metadata'->>'tgg_role','');
  v_external jsonb;
  v_handoff jsonb;
begin
  if auth.uid() is null or v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  v_external:=public.tgg_external_completion_state();
  v_handoff:=public.tgg_owner_provider_handoff();

  return jsonb_build_object(
    'ok',true,
    'version','OWNER-PROVIDER-CHECKLIST-1.2',
    'launch_stage',public.tgg_one_final_system_health()->>'launch_stage',
    'acceptance',public.tgg_provider_acceptance_matrix(),
    'completion',v_external,
    'pending_items',v_handoff->'pending_items',
    'pending_count',v_handoff->'pending_count',
    'external_action_contract',v_handoff->'contract',
    'next_transition','FULLY_CONNECTED',
    'transition_condition','all six external acceptance groups complete',
    'generated_at',now()
  );
end;
$function$


-- [40000001122] function public.tgg_owner_provider_handoff()
CREATE OR REPLACE FUNCTION public.tgg_owner_provider_handoff()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_role text:=coalesce(auth.jwt()->'app_metadata'->>'tgg_role','');
  v_all jsonb;
  v_pending jsonb;
  v_complete jsonb;
  v_contract jsonb;
begin
  if auth.uid() is null or v_role<>'owner' then
    raise exception 'OWNER_REQUIRED' using errcode='42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'provider_key',provider_key,
    'category',category,
    'status',status,
    'required_action',required_action,
    'safe_fallback',safe_fallback,
    'target_runtime',target_runtime,
    'verification_check',verification_check,
    'notes',notes,
    'updated_at',updated_at
  ) order by category,provider_key),'[]'::jsonb)
  into v_all
  from public.tgg_provider_handoff;

  select coalesce(jsonb_agg(jsonb_build_object(
    'provider_key',provider_key,
    'category',category,
    'status',status,
    'required_action',required_action,
    'safe_fallback',safe_fallback,
    'target_runtime',target_runtime,
    'verification_check',verification_check,
    'notes',notes,
    'updated_at',updated_at
  ) order by category,provider_key),'[]'::jsonb)
  into v_pending
  from public.tgg_provider_handoff
  where status<>'complete';

  select coalesce(jsonb_agg(jsonb_build_object(
    'provider_key',provider_key,
    'category',category,
    'status',status,
    'updated_at',updated_at
  ) order by category,provider_key),'[]'::jsonb)
  into v_complete
  from public.tgg_provider_handoff
  where status='complete';

  v_contract:=public.tgg_external_action_contract_readiness();

  return jsonb_build_object(
    'ok',true,
    'version','OWNER-PROVIDER-HANDOFF-1.1',
    'items',v_pending,
    'pending_items',v_pending,
    'all_items',v_all,
    'complete_items',v_complete,
    'pending_count',jsonb_array_length(v_pending),
    'complete_count',jsonb_array_length(v_complete),
    'contract',v_contract,
    'generated_at',now()
  );
end;
$function$


-- [40000001123] function public.tgg_phone_call_history_v1(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_phone_call_history_v1(p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_limit integer := greatest(1,least(coalesce(p_limit,30),100));
  v_result jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  with visible_rooms as (
    select r.*
    from public.tgg_call_rooms r
    where r.created_by=v_uid
       or exists (
         select 1
         from public.tgg_call_participants cp
         where cp.room_id=r.id and cp.user_id=v_uid
       )
    order by r.created_at desc
    limit v_limit
  ), facts as (
    select
      r.*,
      (select min(s.created_at)
       from public.tgg_call_signals s
       where s.room_id=r.id and s.signal_type='answer') as answered_at,
      exists(
        select 1 from public.tgg_call_signals s
        where s.room_id=r.id
          and s.signal_type='hangup'
          and lower(coalesce(s.payload->>'reason',''))='declined'
      ) as declined,
      exists(
        select 1 from public.tgg_call_signals s
        where s.room_id=r.id and s.signal_type='hangup'
      ) as has_hangup
    from visible_rooms r
  ), decorated as (
    select
      f.*,
      case when f.created_by=v_uid then 'outgoing' else 'incoming' end as direction,
      p.artist_id,
      p.stage_name,
      p.avatar_url,
      case
        when f.status='active' and f.answered_at is not null then 'active'
        when f.status='active' and f.answered_at is null then 'ringing'
        when f.declined then 'declined'
        when f.answered_at is not null then 'ended'
        when f.created_by<>v_uid then 'missed'
        else 'no_answer'
      end as call_state,
      case when f.answered_at is null then 0
           else greatest(0,extract(epoch from (coalesce(f.ended_at,case when f.status='active' then now() else f.created_at end)-f.answered_at))::integer)
      end as duration_seconds
    from facts f
    left join lateral (
      select a.id as artist_id,a.stage_name,a.avatar_url
      from public.tgg_conversation_members cm
      join public.artists a on a.user_id=cm.user_id
      where cm.conversation_id=f.conversation_id
        and cm.user_id<>v_uid
      order by cm.joined_at,a.created_at
      limit 1
    ) p on true
  )
  select jsonb_build_object(
    'ok',true,
    'version','PHONE-CALL-HISTORY-1.0',
    'calls',coalesce(jsonb_agg(
      jsonb_build_object(
        'room_id',id,
        'conversation_id',conversation_id,
        'room_type',room_type,
        'is_group',is_group,
        'direction',direction,
        'state',call_state,
        'created_at',created_at,
        'answered_at',answered_at,
        'ended_at',ended_at,
        'duration_seconds',duration_seconds,
        'artist_id',artist_id,
        'stage_name',coalesce(stage_name,title,'Creator'),
        'avatar_url',avatar_url,
        'can_redial',(artist_id is not null and coalesce(is_group,false)=false)
      ) order by created_at desc
    ),'[]'::jsonb),
    'generated_at',now()
  ) into v_result
  from decorated;

  return coalesce(v_result,jsonb_build_object('ok',true,'version','PHONE-CALL-HISTORY-1.0','calls','[]'::jsonb,'generated_at',now()));
end;
$function$


-- [40000001124] function public.tgg_phone_pin_artist(p_artist_id uuid, p_pinned boolean)
CREATE OR REPLACE FUNCTION public.tgg_phone_pin_artist(p_artist_id uuid, p_pinned boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if not exists(select 1 from public.artists a where a.id=p_artist_id) then raise exception 'ARTIST_NOT_FOUND'; end if;
  if coalesce(p_pinned,true) then
    insert into public.tgg_phone_favorites(user_id,artist_id)
    values(v_uid,p_artist_id)
    on conflict(user_id,artist_id) do nothing;
  else
    delete from public.tgg_phone_favorites where user_id=v_uid and artist_id=p_artist_id;
  end if;
  return jsonb_build_object('ok',true,'artist_id',p_artist_id,'pinned',coalesce(p_pinned,true));
end $function$


