-- [40000001126] function public.tgg_playtest_finalize_run(p_run_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_playtest_finalize_run(p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_scenario_id uuid;
  v_total integer;
  v_required integer;
  v_passed integer;
  v_failed integer;
  v_status text;
begin
  select scenario_id into v_scenario_id
  from public.tgg_playtest_runs
  where id=p_run_id;

  if v_scenario_id is null then
    raise exception 'playtest run not found: %',p_run_id;
  end if;

  select
    count(*),
    count(*) filter(where failure_severity in ('error','critical'))
  into v_total,v_required
  from public.tgg_playtest_steps
  where scenario_id=v_scenario_id;

  select
    count(*) filter(where r.status='passed'),
    count(*) filter(where r.status in ('failed','blocked'))
  into v_passed,v_failed
  from public.tgg_playtest_step_results r
  join public.tgg_playtest_steps s on s.id=r.step_id
  where r.playtest_run_id=p_run_id
    and s.failure_severity in ('error','critical');

  v_status := case
    when v_failed > 0 then 'failed'
    when v_passed >= v_required then 'passed'
    else 'blocked'
  end;

  update public.tgg_playtest_runs
  set status=v_status,
      finished_at=case when v_status in ('passed','failed') then now() else finished_at end,
      summary=jsonb_build_object(
        'total_steps',v_total,
        'required_steps',v_required,
        'required_passed',v_passed,
        'required_failed',v_failed
      )
  where id=p_run_id;

  return jsonb_build_object(
    'status',v_status,
    'total_steps',v_total,
    'required_steps',v_required,
    'required_passed',v_passed,
    'required_failed',v_failed
  );
end;
$function$


-- [40000001127] function public.tgg_playtest_record_step(p_run_id uuid, p_step_no integer, p_status text, p_detail jsonb, p_evidence_uri text, p_build_task_key text)
CREATE OR REPLACE FUNCTION public.tgg_playtest_record_step(p_run_id uuid, p_step_no integer, p_status text, p_detail jsonb DEFAULT '{}'::jsonb, p_evidence_uri text DEFAULT NULL::text, p_build_task_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_step public.tgg_playtest_steps%rowtype;
  v_scenario_id uuid;
  v_task_id uuid;
  v_result_id uuid;
  v_failure_id uuid;
begin
  if p_status not in ('passed','failed','skipped','blocked') then
    raise exception 'invalid step status: %',p_status;
  end if;

  select scenario_id into v_scenario_id
  from public.tgg_playtest_runs
  where id=p_run_id;

  if v_scenario_id is null then
    raise exception 'playtest run not found: %',p_run_id;
  end if;

  select * into v_step
  from public.tgg_playtest_steps
  where scenario_id=v_scenario_id and step_no=p_step_no;

  if v_step.id is null then
    raise exception 'step % not found for playtest run %',p_step_no,p_run_id;
  end if;

  insert into public.tgg_playtest_step_results(
    playtest_run_id,step_id,status,detail,evidence_uri
  )
  values(
    p_run_id,v_step.id,p_status,coalesce(p_detail,'{}'::jsonb),p_evidence_uri
  )
  on conflict(playtest_run_id,step_id) do update
  set status=excluded.status,
      detail=excluded.detail,
      evidence_uri=excluded.evidence_uri,
      checked_at=now()
  returning id into v_result_id;

  if p_build_task_key is not null then
    select id into v_task_id
    from public.tgg_build_tasks
    where task_key=p_build_task_key;
  end if;

  if p_status in ('failed','blocked')
     and v_step.failure_severity in ('error','critical')
     and v_task_id is not null then
    insert into public.tgg_build_failures(
      task_id,failure_key,category,severity,status,message,detail
    )
    values(
      v_task_id,
      'playtest:' || p_run_id::text || ':step:' || p_step_no::text,
      'playtest',
      v_step.failure_severity,
      'open',
      'Playtest step failed: ' || v_step.instruction,
      jsonb_build_object(
        'playtest_run_id',p_run_id,
        'step_no',p_step_no,
        'action_key',v_step.action_key,
        'detail',coalesce(p_detail,'{}'::jsonb),
        'evidence_uri',p_evidence_uri
      )
    )
    returning id into v_failure_id;
  end if;

  return jsonb_build_object(
    'result_id',v_result_id,
    'failure_id',v_failure_id,
    'step_status',p_status,
    'failure_severity',v_step.failure_severity
  );
end;
$function$


-- [40000001128] function public.tgg_playtest_start_run(p_scenario_key text, p_build_run_id uuid, p_environment text, p_executor text)
CREATE OR REPLACE FUNCTION public.tgg_playtest_start_run(p_scenario_key text, p_build_run_id uuid DEFAULT NULL::uuid, p_environment text DEFAULT 'staging'::text, p_executor text DEFAULT 'external_worker'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_scenario_id uuid;
  v_run_id uuid;
begin
  if p_environment not in ('development','staging','production') then
    raise exception 'invalid environment: %',p_environment;
  end if;

  select id into v_scenario_id
  from public.tgg_playtest_scenarios
  where scenario_key=p_scenario_key and enabled=true;

  if v_scenario_id is null then
    raise exception 'scenario not found/enabled: %',p_scenario_key;
  end if;

  insert into public.tgg_playtest_runs(
    scenario_id,build_run_id,environment,executor,status,started_at
  )
  values(
    v_scenario_id,p_build_run_id,p_environment,p_executor,'running',now()
  )
  returning id into v_run_id;

  return v_run_id;
end;
$function$


