-- [40000001133] function public.tgg_provider_acceptance_matrix()
CREATE OR REPLACE FUNCTION public.tgg_provider_acceptance_matrix()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with
stripe as (
  select
    coalesce(enabled,false) and coalesce(endpoint_configured,false) and mode='production' as native_ready,
    disabled_reason
  from public.tgg_provider_runtime_config
  where provider_key='stripe'
),
stripe_webhook as (
  select coalesce(enabled,false) enabled,
         coalesce(endpoint_configured,false) endpoint_configured,
         disabled_reason
  from public.tgg_provider_runtime_config
  where provider_key='stripe.webhook'
),
stripe_link as (
  select coalesce(enabled,false) enabled,
         coalesce(endpoint_configured,false) endpoint_configured
  from public.tgg_provider_runtime_config
  where provider_key='stripe.payment_link'
),
dsp as (
  select coalesce(bool_or(coalesce(enabled,false) and coalesce(endpoint_configured,false)),false) as ready
  from public.tgg_provider_runtime_config
  where provider_key='distribution.provider'
),
broadcast as (select public.tgg_broadcast_engine_health() j),
calls as (select public.tgg_call_validation_final_health() j),
blogger as (
  select coalesce(status='connected' and revoked_at is null and coalesce(last_error,'')<>'google_oauth_invalid_grant',false) ready,
         status,last_error
  from public.v98_blogger_connections
  where blog_url='https://trugogettamixtapes.blogspot.com/'
  order by updated_at desc
  limit 1
)
select jsonb_build_object(
  'ok',true,
  'version','PROVIDER-ACCEPTANCE-1.3',
  'stripe',jsonb_build_object(
    'complete',coalesce((select native_ready from stripe),false),
    'webhook_endpoint_configured',coalesce((select endpoint_configured from stripe_webhook),false),
    'webhook_runtime_ready',coalesce((select enabled and endpoint_configured from stripe_webhook),false),
    'webhook_blocker',(select disabled_reason from stripe_webhook),
    'payment_link_ready',coalesce((select enabled and endpoint_configured from stripe_link),false),
    'required_checks',jsonb_build_array(
      'server_secret_available_to_edge_runtime',
      'webhook_signing_secret_available_to_webhook_runtime',
      'stripe_runtime_config_enabled',
      'stripe_runtime_config_endpoint_configured',
      'stripe_runtime_config_mode_production'
    ),
    'fallback','stripe.payment_link',
    'current_reason',(select disabled_reason from stripe)
  ),
  'distribution',jsonb_build_object(
    'complete',(select ready from dsp),
    'required_checks',jsonb_build_array(
      'production_distribution_endpoint_configured',
      'provider_runtime_enabled'
    ),
    'fallback','distribution_package_export'
  ),
  'live_transport',jsonb_build_object(
    'complete',coalesce(((select j->>'sfu_connected' from broadcast))::boolean,false)
               and coalesce(((select j->>'turn_connected' from broadcast))::boolean,false),
    'required_checks',jsonb_build_array(
      'sfu_connected','turn_connected','provider_runtime_mode_production'
    ),
    'already_ready',jsonb_build_object(
      'control_plane',coalesce(((select j->>'control_plane_ready' from broadcast))::boolean,false),
      'room_authorization',coalesce(((select j->>'room_authorization_ready' from broadcast))::boolean,false),
      'viewer_tokens',coalesce(((select j->>'public_viewer_tokens_ready' from broadcast))::boolean,false),
      'guest_tokens',coalesce(((select j->>'host_guest_collab_tokens_ready' from broadcast))::boolean,false)
    ),
    'fallback','control_plane_and_token_layer'
  ),
  'calls',jsonb_build_object(
    'complete',coalesce(((select j->>'validated' from calls))::boolean,false),
    'required_checks',jsonb_build_array(
      'two_distinct_authenticated_users',
      'offer_signal_recorded',
      'answer_signal_recorded'
    ),
    'verified_room_id',(select j->'verified_room_id' from calls),
    'fallback','core_call_room_and_signaling'
  ),
  'blogger',jsonb_build_object(
    'complete',coalesce((select ready from blogger),false),
    'required_checks',jsonb_build_array(
      'owner_google_consent_completed',
      'refresh_token_stored',
      'connection_status_connected',
      'google_oauth_invalid_grant_absent'
    ),
    'current_status',(select status from blogger),
    'current_error',(select last_error from blogger),
    'reconnect_endpoint','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/v98-blogger-connector/start',
    'fallback','public_runtime_continues_without_maintenance_writes'
  ),
  'generated_at',now()
);
$function$


-- [40000001134] function public.tgg_provider_activation_packet()
CREATE OR REPLACE FUNCTION public.tgg_provider_activation_packet()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_dist public.tgg_provider_runtime_config;
  v_broadcast public.tgg_provider_runtime_config;
  v_membership public.tgg_provider_runtime_config;
  v_webhook public.tgg_provider_runtime_config;
  v_tier_count integer:=0;
  v_active_tier_count integer:=0;
  v_verified_link_tier_count integer:=0;
  v_membership_remaining jsonb:='[]'::jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select * into v_dist
  from public.tgg_provider_runtime_config
  where provider_key='distribution.provider';

  select * into v_broadcast
  from public.tgg_provider_runtime_config
  where provider_key='broadcast.sfu_turn';

  select * into v_membership
  from public.tgg_provider_runtime_config
  where provider_key='membership.payment_link';

  select * into v_webhook
  from public.tgg_provider_runtime_config
  where provider_key='stripe.webhook';

  select
    count(*),
    count(*) filter(where t.is_active),
    count(*) filter(where t.stripe_payment_link_verified)
  into v_tier_count,v_active_tier_count,v_verified_link_tier_count
  from public.tgg_membership_tiers t
  join public.artists a on a.id=t.artist_id
  where a.user_id=v_uid;

  if v_tier_count=0 then
    v_membership_remaining:=v_membership_remaining||jsonb_build_array('Create a real recurring membership tier');
  end if;

  if v_verified_link_tier_count=0 then
    v_membership_remaining:=v_membership_remaining||jsonb_build_array('Create and server-verify the recurring Stripe Payment Link');
  end if;

  if not (
    coalesce(v_webhook.enabled,false)
    and v_webhook.mode='production'
    and coalesce(v_webhook.endpoint_configured,false)
  ) then
    v_membership_remaining:=v_membership_remaining||jsonb_build_array('Restore the Stripe webhook signing secret/runtime');
  end if;

  if v_tier_count>0
     and v_verified_link_tier_count>0
     and v_active_tier_count=0
  then
    v_membership_remaining:=v_membership_remaining||jsonb_build_array('Activate the verified membership tier after webhook readiness passes');
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','PROVIDER-ACTIVATION-ONE-FINAL-1.2',
    'distribution',jsonb_build_object(
      'runtime_key','distribution.provider',
      'connected',coalesce(v_dist.enabled,false)
        and v_dist.mode='production'
        and coalesce(v_dist.endpoint_configured,false),
      'package_builder_ready',
        to_regprocedure('public.tgg_creator_distribution_package(uuid)') is not null,
      'readiness_rpc','tgg_creator_distribution_readiness',
      'package_rpc','tgg_creator_distribution_package',
      'metadata_rpc','tgg_distribution_metadata_upsert',
      'required_external_inputs',jsonb_build_array(
        'Production HTTPS delivery endpoint',
        'Server-to-server authentication/signature secret',
        'Provider-specific acceptance/status contract'
      ),
      'legal_metadata_rules',jsonb_build_object(
        'territories_default_to_worldwide',false,
        'rights_confirmation_requires_label',true,
        'rights_confirmation_requires_copyright',true,
        'rights_confirmation_requires_publishing',true,
        'rights_confirmation_requires_territories',true
      ),
      'secret_storage_rule','Secrets must be stored as server/Edge secrets, never in Blogger or public tables.'
    ),
    'broadcast',jsonb_build_object(
      'runtime_key','broadcast.sfu_turn',
      'connected',coalesce(v_broadcast.enabled,false)
        and v_broadcast.mode='production'
        and coalesce(v_broadcast.endpoint_configured,false),
      'adapter_contract_ready',true,
      'required_external_inputs',jsonb_build_array(
        'SFU/TURN service URL',
        'Server-side API key',
        'Server-side API secret',
        'Room/token issuance contract'
      ),
      'required_capabilities',jsonb_build_array('SFU','TURN','room tokens','guest tokens'),
      'optional_capabilities',jsonb_build_array('egress recording','ingress'),
      'secret_storage_rule','API secrets must remain server-side only.'
    ),
    'memberships',jsonb_build_object(
      'payment_link_fallback_infrastructure_ready',
        coalesce(v_membership.enabled,false)
        and v_membership.mode='production'
        and coalesce(v_membership.endpoint_configured,false),
      'stripe_webhook_ready',
        coalesce(v_webhook.enabled,false)
        and v_webhook.mode='production'
        and coalesce(v_webhook.endpoint_configured,false),
      'owner_platform_settlement_supported',true,
      'tier_count',v_tier_count,
      'active_tier_count',v_active_tier_count,
      'verified_payment_link_tier_count',v_verified_link_tier_count,
      'tier_setup_complete',v_tier_count>0,
      'payment_link_setup_complete',v_verified_link_tier_count>0,
      'remaining_setup',v_membership_remaining
    ),
    'calls',public.tgg_call_validation_final_health(),
    'blogger_maintenance',jsonb_build_object(
      'live_runtime_verified',true,
      'reconnect_rpc','tgg_blogger_reconnect_link_create',
      'reconnect_rpc_owner_only',true,
      'one_time_link',true,
      'oauth_user_consent_required',true
    ),
    'hosted_controls',jsonb_build_object(
      'leaked_password_protection','Enable in hosted Supabase Auth / Management API.',
      'physical_edge_cleanup','Requires Supabase Management API delete privilege.'
    ),
    'generated_at',now()
  );
end
$function$


