-- [40000001141] function public.tgg_provider_health_refresh()
CREATE OR REPLACE FUNCTION public.tgg_provider_health_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count integer:=0;
  v_degraded integer:=0;
  v_blocked integer:=0;
  v_external integer:=0;
begin
  with providers as (
    select distinct provider_key from public.tgg_provider_runtime_config
    union
    select distinct provider_key from public.tgg_provider_handoff
    union
    select distinct provider from public.provider_operations
    union
    select distinct provider from public.provider_reconciliation_runs
  ),
  stats as (
    select
      p.provider_key,
      cfg.enabled,
      cfg.endpoint_configured,
      cfg.mode,
      cfg.disabled_reason,
      h.status as handoff_status,
      h.required_action,
      h.safe_fallback,
      h.target_runtime,
      coalesce(op.open_ops,0) open_ops,
      coalesce(op.failed_ops,0) failed_ops,
      coalesce(rec.exceptions,0) rec_exceptions
    from providers p
    left join lateral (
      select enabled,endpoint_configured,mode,disabled_reason
      from public.tgg_provider_runtime_config c
      where c.provider_key=p.provider_key
      order by updated_at desc limit 1
    ) cfg on true
    left join lateral (
      select status,required_action,safe_fallback,target_runtime
      from public.tgg_provider_handoff h0
      where h0.provider_key=p.provider_key
      order by updated_at desc limit 1
    ) h on true
    left join lateral (
      select
        count(*) filter(where state not in ('succeeded','completed','complete','failed','canceled','cancelled')) open_ops,
        count(*) filter(where state in ('failed','error','dead_letter')) failed_ops
      from public.provider_operations o
      where o.provider=p.provider_key
        and o.updated_at >= now()-interval '24 hours'
    ) op on true
    left join lateral (
      select coalesce(sum(exception_count),0) exceptions
      from public.provider_reconciliation_runs r
      where r.provider=p.provider_key
        and coalesce(r.completed_at,r.started_at) >= now()-interval '24 hours'
    ) rec on true
  ),
  normalized as (
    select *,
      lower(trim(coalesce(required_action,''))) as action_text,
      lower(trim(coalesce(handoff_status,''))) as handoff_text
    from stats
  ),
  classified as (
    select *,
      case
        when enabled=false then 'disabled'
        when failed_ops>0 or rec_exceptions>0 then 'degraded'
        when handoff_text in ('blocked','action_required','credentials_required','scale_provider_required',
                              'validation_required','provider_delivery_required','account_setting_required','domain_verification_pending')
          then case when handoff_text='account_setting_required' then 'ready' else 'blocked' end
        when enabled=true and coalesce(endpoint_configured,false)=true then 'healthy'
        when handoff_text in ('complete','connected','healthy','verified') then 'healthy'
        when enabled=true then 'ready'
        else 'unknown'
      end as health_status,
      coalesce((
        (
          handoff_text in ('blocked','action_required','credentials_required','scale_provider_required',
                           'validation_required','provider_delivery_required','account_setting_required','domain_verification_pending')
          and action_text not like 'no action required%'
          and action_text not like '%no reauthorization action is required%'
        )
        or (
          coalesce(enabled,false)=true
          and coalesce(endpoint_configured,false)=false
          and nullif(action_text,'') is not null
          and action_text not like 'no action required%'
        )
      ),false) as external_action_required
    from normalized
  ),
  inserted as (
    insert into public.tgg_provider_health_snapshots(
      provider_key,health_status,enabled,endpoint_configured,handoff_status,
      open_operations,failed_operations,reconciliation_exceptions,
      external_action_required,auto_repair_allowed,details,checked_at
    )
    select
      provider_key,health_status,enabled,endpoint_configured,handoff_status,
      open_ops,failed_ops,rec_exceptions,external_action_required,
      case when failed_ops>0 and external_action_required=false then true else false end,
      jsonb_build_object(
        'mode',mode,'disabled_reason',disabled_reason,'required_action',required_action,
        'safe_fallback',safe_fallback,'target_runtime',target_runtime
      ),
      now()
    from classified
    returning health_status,external_action_required
  )
  select count(*),
         count(*) filter(where health_status='degraded'),
         count(*) filter(where health_status='blocked'),
         count(*) filter(where external_action_required)
  into v_count,v_degraded,v_blocked,v_external
  from inserted;

  return jsonb_build_object(
    'ok',true,'providers_checked',v_count,'degraded',v_degraded,'blocked',v_blocked,
    'external_action_required',v_external,'production_change_performed',false
  );
end $function$


-- [40000001142] function public.tgg_provider_health_state()
CREATE OR REPLACE FUNCTION public.tgg_provider_health_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with latest as (
    select distinct on(provider_key) *
    from public.tgg_provider_health_snapshots
    order by provider_key,checked_at desc
  )
  select jsonb_build_object(
    'providers',count(*),
    'healthy',count(*) filter(where health_status='healthy'),
    'ready',count(*) filter(where health_status='ready'),
    'disabled',count(*) filter(where health_status='disabled'),
    'degraded',count(*) filter(where health_status='degraded'),
    'blocked',count(*) filter(where health_status='blocked'),
    'unknown',count(*) filter(where health_status='unknown'),
    'external_action_required',count(*) filter(where external_action_required),
    'auto_repairable',count(*) filter(where auto_repair_allowed),
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'provider_key',provider_key,'health_status',health_status,'enabled',enabled,
      'endpoint_configured',endpoint_configured,'handoff_status',handoff_status,
      'open_operations',open_operations,'failed_operations',failed_operations,
      'reconciliation_exceptions',reconciliation_exceptions,
      'external_action_required',external_action_required,
      'auto_repair_allowed',auto_repair_allowed,'details',details,'checked_at',checked_at
    ) order by provider_key),'[]'::jsonb),
    'production_change_performed',false
  )
  from latest
$function$


