-- [40000001155] function public.tgg_public_checkout_capabilities()
CREATE OR REPLACE FUNCTION public.tgg_public_checkout_capabilities()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with runtime as (
  select coalesce(
    (
      select enabled
        and mode='production'
        and endpoint_configured
      from public.tgg_provider_runtime_config
      where provider_key='stripe'
      limit 1
    ),
    false
  ) as native_ready
),
catalog as (
  select
    count(*)::bigint as published_products,
    count(*) filter(
      where nullif(btrim(coalesce(stripe_payment_link_url,'')),'') is not null
    )::bigint as payment_link_products
  from public.merch_products
  where status='published'
),
memberships as (
  select
    count(*)::bigint as active_tiers,
    count(*) filter(
      where nullif(btrim(coalesce(checkout_url,'')),'') is not null
    )::bigint as checkout_ready_tiers
  from public.public_membership_tiers_v1
)
select jsonb_build_object(
  'store_checkout',
    runtime.native_ready
    or (
      catalog.published_products>0
      and catalog.payment_link_products=catalog.published_products
    ),
  'catalog_ready',
    runtime.native_ready
    or catalog.published_products=0
    or catalog.payment_link_products=catalog.published_products,
  'native_store_checkout',runtime.native_ready,
  'payment_link_fallback',true,
  'payment_link_supported',true,
  'payment_link_catalog_ready',
    catalog.published_products=0
    or catalog.payment_link_products=catalog.published_products,
  'published_products',catalog.published_products,
  'published_products_with_payment_link',catalog.payment_link_products,
  'published_products_without_checkout',
    case
      when runtime.native_ready then 0
      else greatest(catalog.published_products-catalog.payment_link_products,0)
    end,
  'publish_guard_enabled',true,
  'membership_checkout',
    memberships.active_tiers>0
    and memberships.checkout_ready_tiers=memberships.active_tiers,
  'membership_payment_link_ready',
    memberships.active_tiers>0
    and memberships.checkout_ready_tiers=memberships.active_tiers,
  'active_membership_tiers',memberships.active_tiers,
  'active_membership_tiers_with_checkout',memberships.checkout_ready_tiers
)
from runtime,catalog,memberships
$function$


-- [40000001156] function public.tgg_public_content_cancel(p_queue_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_public_content_cancel(p_queue_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_row public.tgg_public_content_queue;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  update public.tgg_public_content_queue
  set status='cancelled',updated_at=now()
  where id=p_queue_id and owner_user_id=v_uid and status='queued'
  returning * into v_row;

  if v_row.id is null then raise exception 'QUEUE_ITEM_NOT_FOUND' using errcode='P0002'; end if;

  return jsonb_build_object('ok',true,'queue_id',v_row.id,'status',v_row.status);
end
$function$


-- [40000001157] function public.tgg_public_content_feed(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_public_content_feed(p_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'ok',true,
    'version','PUBLIC-CONTENT-FEED-1.1',
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'id',c.id,'content_type',c.content_type,'title',c.title,'summary',c.summary,
      'target_url',c.target_url,'source_type',c.source_type,'source_id',c.source_id,'published_at',c.published_at
    ) order by c.published_at desc nulls last,c.created_at desc),'[]'::jsonb)
  )
  from (
    select *
    from public.content_items
    where status='PUBLISHED'
      and visibility='PUBLIC'
      and (published_at is null or published_at<=now())
    order by published_at desc nulls last,created_at desc
    limit greatest(1,least(coalesce(p_limit,12),50))
  ) c;
$function$


