-- [40000001159] function public.tgg_public_content_rotation(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_public_content_rotation(p_limit integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with eligible as (
    select c.*,
           mod(abs(hashtext(c.id::text||current_date::text)),1000000) rotation_rank
    from public.content_items c
    where c.status='PUBLISHED'
      and c.visibility='PUBLIC'
      and (c.published_at is null or c.published_at<=now())
  ),
  chosen as (
    select *
    from eligible
    order by
      case when coalesce(published_at,created_at)>=now()-interval '14 days' then 0 else 1 end,
      rotation_rank,
      published_at desc nulls last,
      created_at desc
    limit greatest(1,least(coalesce(p_limit,8),24))
  )
  select jsonb_build_object(
    'ok',true,
    'version','PUBLIC-CONTENT-ROTATION-1.0',
    'rotation_date',current_date,
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'id',id,'content_type',content_type,'title',title,'summary',summary,
      'target_url',target_url,'source_type',source_type,'source_id',source_id,'published_at',published_at
    ) order by rotation_rank),'[]'::jsonb)
  )
  from chosen;
$function$


-- [40000001160] function public.tgg_public_content_schedule(p_content_item_id uuid, p_scheduled_at timestamp with time zone, p_channel text)
CREATE OR REPLACE FUNCTION public.tgg_public_content_schedule(p_content_item_id uuid, p_scheduled_at timestamp with time zone, p_channel text DEFAULT 'public_site'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_item public.content_items;
  v_row public.tgg_public_content_queue;
  v_channel text:=lower(trim(coalesce(p_channel,'public_site')));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_scheduled_at is null or p_scheduled_at < now()-interval '5 minutes' then
    raise exception 'SCHEDULE_TIME_INVALID' using errcode='22023';
  end if;
  if v_channel not in ('public_site','discover','artist_profile') then
    raise exception 'CHANNEL_INVALID' using errcode='22023';
  end if;

  select * into v_item
  from public.content_items
  where id=p_content_item_id and creator_id=v_uid;

  if v_item.id is null then raise exception 'CONTENT_NOT_FOUND_OR_NOT_OWNED' using errcode='P0002'; end if;
  if upper(v_item.status) <> 'APPROVED' then
    raise exception 'CONTENT_MUST_BE_APPROVED_BEFORE_SCHEDULING' using errcode='22023';
  end if;
  if upper(v_item.visibility) <> 'PUBLIC' then
    raise exception 'CONTENT_MUST_BE_PUBLIC_BEFORE_SCHEDULING' using errcode='22023';
  end if;

  insert into public.tgg_public_content_queue(content_item_id,owner_user_id,channel,scheduled_at)
  values(v_item.id,v_uid,v_channel,p_scheduled_at)
  on conflict(content_item_id) where status='queued'
  do update set scheduled_at=excluded.scheduled_at,channel=excluded.channel,updated_at=now(),last_error=null
  returning * into v_row;

  return jsonb_build_object(
    'ok',true,'version','PUBLIC-CONTENT-ENGINE-1.0',
    'queue_id',v_row.id,'content_item_id',v_row.content_item_id,
    'scheduled_at',v_row.scheduled_at,'channel',v_row.channel,'status',v_row.status
  );
end
$function$


