-- [40000001168] function public.tgg_public_launch_content_mix()
CREATE OR REPLACE FUNCTION public.tgg_public_launch_content_mix()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_music bigint:=0;
  v_videos bigint:=0;
  v_books bigint:=0;
  v_merch bigint:=0;
  v_shorts bigint:=0;
  v_seeded integer:=0;
  v_next jsonb:='[]'::jsonb;
begin
  select count(*) into v_music from public.mixtapes where status='published';
  select count(*) into v_videos from public.videos where status='published';
  select count(*) into v_books from public.tgg_audiobooks where status='published';
  select count(*) into v_merch from public.merch_products where status='published';
  select count(*) into v_shorts from public.tgg_shorts where status='published';

  v_seeded :=
    (case when v_music>0 then 1 else 0 end)+
    (case when v_videos>0 then 1 else 0 end)+
    (case when v_books>0 then 1 else 0 end)+
    (case when v_merch>0 then 1 else 0 end)+
    (case when v_shorts>0 then 1 else 0 end);

  if v_videos=0 then
    v_next:=v_next||jsonb_build_array(jsonb_build_object(
      'key','seed_video','title','Publish the first public video','category','videos','priority',95
    ));
  end if;
  if v_shorts=0 then
    v_next:=v_next||jsonb_build_array(jsonb_build_object(
      'key','seed_short','title','Publish the first Short','category','shorts','priority',92
    ));
  end if;
  if v_books=0 then
    v_next:=v_next||jsonb_build_array(jsonb_build_object(
      'key','seed_audiobook','title','Publish the first audiobook','category','audiobooks','priority',86
    ));
  end if;
  if v_merch=0 then
    v_next:=v_next||jsonb_build_array(jsonb_build_object(
      'key','seed_merch','title','Publish the first merch item','category','merch','priority',82
    ));
  end if;
  if v_music=0 then
    v_next:=v_next||jsonb_build_array(jsonb_build_object(
      'key','seed_music','title','Publish the first music release','category','music','priority',100
    ));
  end if;

  return jsonb_build_object(
    'ok',true,
    'version','PUBLIC-LAUNCH-CONTENT-MIX-1.0',
    'seeded_categories',v_seeded,
    'total_categories',5,
    'coverage_pct',round((v_seeded::numeric/5)*100,0),
    'categories',jsonb_build_array(
      jsonb_build_object('key','music','title','Music','published_count',v_music,'seeded',v_music>0),
      jsonb_build_object('key','videos','title','Videos','published_count',v_videos,'seeded',v_videos>0),
      jsonb_build_object('key','audiobooks','title','Audiobooks','published_count',v_books,'seeded',v_books>0),
      jsonb_build_object('key','merch','title','Merch','published_count',v_merch,'seeded',v_merch>0),
      jsonb_build_object('key','shorts','title','Shorts','published_count',v_shorts,'seeded',v_shorts>0)
    ),
    'next_actions',v_next,
    'launch_blocking',false,
    'generated_at',now()
  );
end
$function$


-- [40000001169] function public.tgg_public_launch_mix(p_release_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_public_launch_mix(p_release_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_limit integer:=greatest(4,least(coalesce(p_release_limit,12),24));
  v_day integer:=extract(doy from current_date)::integer;
  v_releases jsonb:='[]'::jsonb; v_trending jsonb:='[]'::jsonb; v_latest jsonb:='[]'::jsonb;
  v_artists jsonb:='[]'::jsonb; v_content jsonb:='[]'::jsonb; v_videos jsonb:='[]'::jsonb; v_hero jsonb;
begin
  with ranked as (
    select m.id release_id,m.slug,m.title,m.genre,m.description,m.cover_url,m.release_date,m.created_at,
           a.id artist_id,a.stage_name,a.avatar_url,coalesce(m.featured,false) featured,
           coalesce(m.play_count,0) play_count,coalesce(m.download_count,0) download_count,
           coalesce(fd.saves,0) saves,coalesce(fd.reactions,0) reactions,coalesce(fd.comments,0) comments,
           (case when coalesce(m.featured,false) then 1200 else 0 end
            +coalesce(m.play_count,0)+coalesce(m.download_count,0)*3
            +coalesce(fd.saves,0)*10+coalesce(fd.reactions,0)*4+coalesce(fd.comments,0)*8
            +greatest(0,180-floor(extract(epoch from (now()-coalesce(m.release_date,m.created_at)))/86400))::bigint)::bigint rank_score
    from public.mixtapes m
    join public.artists a on a.id=m.artist_id
    left join public.fan_release_discovery fd on fd.mixtape_id=m.id
    where m.status='published' and nullif(btrim(coalesce(m.slug,'')),'') is not null
  )
  select coalesce(jsonb_agg(to_jsonb(x) order by rank_score desc,release_date desc nulls last),'[]'::jsonb)
  into v_releases from (select * from ranked order by rank_score desc,coalesce(release_date,created_at) desc limit v_limit) x;

  select to_jsonb(x) into v_hero from (
    select m.id release_id,m.slug,m.title,m.genre,m.description,m.cover_url,m.release_date,
           a.id artist_id,a.stage_name,a.avatar_url,coalesce(m.featured,false) featured,
           (case when coalesce(m.featured,false) then 1200 else 0 end
            +coalesce(m.play_count,0)+coalesce(m.download_count,0)*3
            +greatest(0,180-floor(extract(epoch from (now()-coalesce(m.release_date,m.created_at)))/86400))::bigint
            +case when mod(abs(hashtext(m.id::text)),7)=mod(v_day,7) then 40 else 0 end)::bigint rank_score
    from public.mixtapes m join public.artists a on a.id=m.artist_id
    where m.status='published' and nullif(btrim(coalesce(m.slug,'')),'') is not null
    order by rank_score desc,coalesce(m.release_date,m.created_at) desc limit 1
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x) order by rank_score desc,release_date desc nulls last),'[]'::jsonb)
  into v_trending from (
    select m.id release_id,m.slug,m.title,m.genre,m.cover_url,m.release_date,a.id artist_id,a.stage_name,
           coalesce(m.play_count,0) play_count,coalesce(m.download_count,0) download_count,
           coalesce(fd.saves,0) saves,coalesce(fd.reactions,0) reactions,coalesce(fd.comments,0) comments,
           (coalesce(m.play_count,0)+coalesce(m.download_count,0)*3+coalesce(fd.saves,0)*10+
            coalesce(fd.reactions,0)*4+coalesce(fd.comments,0)*8+
            greatest(0,90-floor(extract(epoch from (now()-coalesce(m.release_date,m.created_at)))/86400))::bigint)::bigint rank_score
    from public.mixtapes m join public.artists a on a.id=m.artist_id
    left join public.fan_release_discovery fd on fd.mixtape_id=m.id
    where m.status='published' and nullif(btrim(coalesce(m.slug,'')),'') is not null
    order by rank_score desc,coalesce(m.release_date,m.created_at) desc limit 8
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x) order by release_date desc nulls last,created_at desc),'[]'::jsonb)
  into v_latest from (
    select m.id release_id,m.slug,m.title,m.genre,m.cover_url,m.release_date,m.created_at,a.id artist_id,a.stage_name
    from public.mixtapes m join public.artists a on a.id=m.artist_id
    where m.status='published' and nullif(btrim(coalesce(m.slug,'')),'') is not null
    order by coalesce(m.release_date,m.created_at) desc,m.created_at desc limit 8
  ) x;

  v_artists:=coalesce(public.tgg_public_artist_directory(null,12)->'artists','[]'::jsonb);
  v_content:=coalesce(public.tgg_public_content_feed(12)->'items','[]'::jsonb);

  select coalesce(jsonb_agg(to_jsonb(x) order by featured desc,release_date desc nulls last,created_at desc),'[]'::jsonb)
  into v_videos from (
    select * from public.public_video_discovery_v1
    order by coalesce(featured,false) desc,release_date desc nulls last,created_at desc limit 8
  ) x;

  if jsonb_array_length(v_videos)=0 then
    v_videos:=coalesce(public.tgg_public_shell_bundle()->'videos','[]'::jsonb);
  end if;

  return jsonb_build_object(
    'ok',true,'version','PUBLIC-LAUNCH-MIX-1.1',
    'rotation_key',to_char(current_date,'IYYY-IW')||'-'||mod(v_day,7),
    'hero',v_hero,'trending',v_trending,'latest',v_latest,'releases',v_releases,
    'artists',v_artists,'videos',v_videos,'fresh_content',v_content,
    'signed_out',jsonb_build_object(
      'headline','Discover music. Follow creators. Build your world.',
      'primary_cta','Explore releases','secondary_cta','Sign in for follows + saves',
      'creator_cta','Open Creator OS',
      'fan_benefits',jsonb_build_array('Follow artists','Save releases','Personalized discovery','Weekly fan missions')
    ),
    'catalog_state',jsonb_build_object(
      'release_count',jsonb_array_length(v_releases),'artist_count',jsonb_array_length(v_artists),
      'video_count',jsonb_array_length(v_videos),'content_count',jsonb_array_length(v_content)
    ),
    'generated_at',now()
  );
end
$function$


-- [40000001170] function public.tgg_public_live_bundle(p_stream_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_public_live_bundle(p_stream_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'ok',true,
    'version','PUBLIC-LIVE-V519',
    'streams',coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id',s.id,
          'title',s.title,
          'description',s.description,
          'category',s.category,
          'status',s.status,
          'broadcast_mode',s.broadcast_mode,
          'audience',s.audience,
          'camera_enabled',s.camera_enabled,
          'screen_enabled',s.screen_enabled,
          'mic_enabled',s.mic_enabled,
          'system_audio_enabled',s.system_audio_enabled,
          'chat_enabled',s.chat_enabled,
          'reactions_enabled',s.reactions_enabled,
          'pip_position',s.pip_position,
          'viewer_count',s.viewer_count,
          'peak_viewers',s.peak_viewers,
          'actual_start',s.actual_start,
          'scheduled_start',s.scheduled_start,
          'media_provider',s.media_provider,
          'media_playback_id',s.media_playback_id,
          'creator',jsonb_build_object(
            'user_id',a.user_id,
            'artist_id',a.artist_id,
            'stage_name',a.stage_name,
            'avatar_url',a.avatar_url,'profile_url',case when a.artist_id is null then null else '/p/public-artist-profile.html?id='||a.artist_id::text end
          ),
          'reaction_counts',jsonb_build_object(
            'fire',coalesce(rc.fire,0),
            'heart',coalesce(rc.heart,0),
            'clap',coalesce(rc.clap,0),
            '100',coalesce(rc.hundred,0)
          ),
          'chat',
            case when s.chat_enabled then coalesce((
              select jsonb_agg(
                jsonb_build_object(
                  'id',m.id,
                  'user_id',m.user_id,
                  'display_name',m.display_name,
                  'body',m.body,
                  'created_at',m.created_at
                )
                order by m.created_at
              )
              from (
                select *
                from public.tgg_live_chat_messages
                where stream_id=s.id
                order by created_at desc
                limit 100
              ) m
            ),'[]'::jsonb)
            else '[]'::jsonb end
        )
        order by case when s.status='LIVE' then 0 else 1 end,s.created_at desc
      )
      from public.live_streams s
      join public.content_items c on c.id=s.content_id
      left join public.public_artist_directory_v1 a on a.user_id=s.creator_id
      left join public.public_live_reaction_counts_v1 rc on rc.stream_id=s.id
      where c.status='PUBLISHED'
        and c.visibility='PUBLIC'
        and s.audience='everyone'
        and (p_stream_id is null or s.id=p_stream_id)
        and s.status in ('LIVE','SCHEDULED','ENDED')
    ),'[]'::jsonb),
    'generated_at',now()
  );
$function$


