-- [40000001172] function public.tgg_public_mixtape_catalog()
CREATE OR REPLACE FUNCTION public.tgg_public_mixtape_catalog()
 RETURNS TABLE(id uuid, title text, genre text, description text, cover_url text, release_date timestamp with time zone, artist_id uuid, artist_name text, track_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select
    m.id,
    m.title,
    m.genre,
    m.description,
    m.cover_url,
    m.release_date,
    a.artist_id,
    a.stage_name,
    count(t.id)::bigint
  from public.mixtapes m
  left join public.public_artist_directory_v1 a
    on a.artist_id=m.artist_id
  left join public.tracks t
    on t.mixtape_id=m.id
  where m.status='published'::public.mixtape_status
  group by m.id,a.artist_id,a.stage_name
  order by m.release_date desc nulls last,m.created_at desc;
$function$


-- [40000001173] function public.tgg_public_mixtape_detail(p_mixtape_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_public_mixtape_detail(p_mixtape_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'id',m.id,
    'title',m.title,
    'genre',m.genre,
    'description',m.description,
    'cover_url',m.cover_url,
    'release_date',m.release_date,
    'download_access',m.download_access,
    'allow_full_download',m.allow_full_download,
    'allow_track_downloads',m.allow_track_downloads,
    'show_download_count',m.show_download_count,
    'show_play_count',m.show_play_count,
    'download_message',m.download_message,
    'play_count',case when m.show_play_count then m.play_count else null end,
    'download_count',case when m.show_download_count then m.download_count else null end,
    'artists',jsonb_build_object(
      'id',a.artist_id,
      'stage_name',a.stage_name
    ),
    'media_contract',public.tgg_public_release_media_contract(m.id),
    'tracks',coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id',t.id,
          'track_number',t.track_number,
          'title',t.title,
          'featured_artist',t.featured_artist,
          'duration_seconds',t.duration_seconds,
          'download_policy',t.download_policy
        )
        order by t.track_number
      )
      from public.tracks t
      where t.mixtape_id=m.id
    ),'[]'::jsonb)
  )
  from public.mixtapes m
  left join public.public_artist_directory_v1 a
    on a.artist_id=m.artist_id
  where m.id=p_mixtape_id
    and m.status='published'::public.mixtape_status;
$function$


-- [40000001174] function public.tgg_public_one_final_bundle()
CREATE OR REPLACE FUNCTION public.tgg_public_one_final_bundle()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with shell as (
  select public.tgg_public_shell_bundle() data
),
home as (
  select public.tgg_get_public_home_bundle(24) data
),
checkout as (
  select public.tgg_public_checkout_capabilities() data
),
launch as (
  select public.tgg_public_launch_mix(12) data
)
select
  (select data from shell)
  || jsonb_build_object(
    'version','ONE-FINAL-CANONICAL-1.2',
    'release_channel','production',
    'baseline','TRU_GO_GETTA_ONE_FINAL',
    'releases',coalesce((select data->'releases' from home),'[]'::jsonb),
    'home_feed',coalesce((select data->'releases' from home),'[]'::jsonb),
    'launch_mix',(select data from launch),
    'featured_release',(select data->'hero' from launch),
    'trending_releases',coalesce((select data->'trending' from launch),'[]'::jsonb),
    'latest_releases',coalesce((select data->'latest' from launch),'[]'::jsonb),
    'rotating_public_content',coalesce(public.tgg_public_content_rotation(8)->'items','[]'::jsonb),
    'checkout_capabilities',(select data from checkout),
    'audiobooks',public.tgg_public_audiobooks_feed(50),
    'artist_directory',public.tgg_public_artist_directory(null,100),
    'social',public.tgg_public_social_feed(50,50,50),
    'career',public.tgg_public_career_feed(),
    'memberships',public.tgg_public_memberships_feed(),
    'interviews',public.tgg_public_interviews_feed(50),
    'live',public.tgg_public_live_bundle(null)||jsonb_build_object('version','PUBLIC-LIVE-ONE-FINAL-1.0'),
    'canonical_routes',jsonb_build_object(
      'home','/','artists','/p/artists.html','artist_profile','/p/public-artist-profile.html',
      'mixtape_detail','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-shell?view=release',
      'audiobooks','/p/audiobooks.html','shorts','/p/shorts.html','radio','/p/tgg-radio.html',
      'events','/p/events.html','opportunities','/p/opportunities.html','memberships','/p/memberships.html',
      'interviews','/p/interviews.html','live','/p/live.html','discover','/p/homepage.html',
      'public_discover_runtime','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-shell?view=discover',
      'creator_home','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-creator-os-app-v17?app=1'
    ),
    'generated_at',now()
  );
$function$


