-- [40000001182] function public.tgg_radio_create_draft(p_title text, p_description text, p_show_type text, p_audio_url text, p_artwork_url text, p_scheduled_for timestamp with time zone, p_duration_seconds integer)
CREATE OR REPLACE FUNCTION public.tgg_radio_create_draft(p_title text, p_description text DEFAULT NULL::text, p_show_type text DEFAULT 'mix'::text, p_audio_url text DEFAULT NULL::text, p_artwork_url text DEFAULT NULL::text, p_scheduled_for timestamp with time zone DEFAULT NULL::timestamp with time zone, p_duration_seconds integer DEFAULT NULL::integer)
 RETURNS public.tgg_radio_shows
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v public.tgg_radio_shows;
  v_type text := lower(btrim(coalesce(p_show_type,'mix')));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_title,''))) < 1 or char_length(btrim(coalesce(p_title,''))) > 160 then
    raise exception 'TITLE_INVALID';
  end if;
  if v_type not in ('mix','interview','talk','premiere','live','podcast') then
    raise exception 'INVALID_SHOW_TYPE';
  end if;
  if p_duration_seconds is not null and p_duration_seconds < 0 then
    raise exception 'INVALID_DURATION';
  end if;

  insert into public.tgg_radio_shows(
    user_id,title,description,show_type,audio_url,artwork_url,
    scheduled_for,duration_seconds,status
  )
  values(
    v_uid,btrim(p_title),nullif(btrim(coalesce(p_description,'')),''),
    v_type,nullif(btrim(coalesce(p_audio_url,'')),''),
    nullif(btrim(coalesce(p_artwork_url,'')),''),
    p_scheduled_for,p_duration_seconds,'draft'
  )
  returning * into v;
  return v;
end $function$


-- [40000001183] function public.tgg_radio_delete(p_show_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_radio_delete(p_show_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  delete from public.tgg_radio_shows
  where id=p_show_id and user_id=v_uid and status in ('draft','rejected')
  returning id into v_id;
  if v_id is null then raise exception 'RADIO_SHOW_NOT_DELETABLE'; end if;
  return jsonb_build_object('ok',true,'show_id',v_id,'deleted',true);
end $function$


