-- [40000001185] function public.tgg_radio_submit(p_show_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_radio_submit(p_show_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid := auth.uid();
      v_count integer;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

      update public.tgg_radio_shows
      set status='pending',admin_note=null,updated_at=now()
      where id=p_show_id
        and user_id=v_uid
        and status in ('draft','rejected');

      get diagnostics v_count = row_count;
      if v_count=0 then raise exception 'SHOW_NOT_FOUND_OR_NOT_SUBMITTABLE'; end if;

      return jsonb_build_object('ok',true,'show_id',p_show_id,'status','pending');
    end;
    $function$


-- [40000001186] function public.tgg_radio_update_draft(p_show_id uuid, p_title text, p_description text, p_show_type text, p_audio_url text, p_artwork_url text, p_scheduled_for timestamp with time zone, p_duration_seconds integer)
CREATE OR REPLACE FUNCTION public.tgg_radio_update_draft(p_show_id uuid, p_title text, p_description text, p_show_type text, p_audio_url text, p_artwork_url text, p_scheduled_for timestamp with time zone, p_duration_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'TITLE_REQUIRED'; end if;
  update public.tgg_radio_shows
  set title=left(btrim(p_title),160),
      description=nullif(btrim(coalesce(p_description,'')),''),
      show_type=coalesce(nullif(btrim(coalesce(p_show_type,'')),''),'mix'),
      audio_url=nullif(btrim(coalesce(p_audio_url,'')),''),
      artwork_url=nullif(btrim(coalesce(p_artwork_url,'')),''),
      scheduled_for=p_scheduled_for,
      duration_seconds=p_duration_seconds,
      status=case when status='rejected' then 'draft' else status end,
      admin_note=case when status='rejected' then null else admin_note end,
      updated_at=now()
  where id=p_show_id and user_id=v_uid and status in ('draft','rejected')
  returning id into v_id;
  if v_id is null then raise exception 'RADIO_SHOW_NOT_EDITABLE'; end if;
  return jsonb_build_object('ok',true,'show_id',v_id);
end $function$


-- [40000001187] function public.tgg_realtime_security_readiness()
CREATE OR REPLACE FUNCTION public.tgg_realtime_security_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
with target(name,anon_expected) as (
  values
  ('tgg_call_signals',false),
  ('tgg_live_chat_messages',true),
  ('tgg_live_guest_requests',false),
  ('tgg_messages',false),
  ('tgg_studio_project_events',false),
  ('tgg_studio_project_presence',false)
),
state as (
  select
    t.name,
    t.anon_expected,
    exists(
      select 1 from pg_publication_tables pt
      where pt.pubname='supabase_realtime'
        and pt.schemaname='public'
        and pt.tablename=t.name
    ) published,
    c.relrowsecurity rls_enabled,
    has_table_privilege('anon','public.'||quote_ident(t.name),'SELECT') anon_select,
    has_table_privilege('authenticated','public.'||quote_ident(t.name),'SELECT') auth_select
  from target t
  join pg_class c on c.relname=t.name
  join pg_namespace n on n.oid=c.relnamespace and n.nspname='public'
),
policy_checks as (
  select jsonb_build_object(
    'call_participant_select',exists(
      select 1 from pg_policy p join pg_class c on c.oid=p.polrelid
      where c.relname='tgg_call_signals' and p.polname='tgg_call_signals_members_select'
    ),
    'message_member_select',exists(
      select 1 from pg_policy p join pg_class c on c.oid=p.polrelid
      where c.relname='tgg_messages' and p.polname='tgg messages select members'
    ),
    'guest_request_visibility',exists(
      select 1 from pg_policy p join pg_class c on c.oid=p.polrelid
      where c.relname='tgg_live_guest_requests' and p.polname='tgg_live_guest_request_visible'
    ),
    'studio_event_member_select',exists(
      select 1 from pg_policy p join pg_class c on c.oid=p.polrelid
      where c.relname='tgg_studio_project_events' and p.polname='tgg_studio_events_members'
    ),
    'studio_presence_member_select',exists(
      select 1 from pg_policy p join pg_class c on c.oid=p.polrelid
      where c.relname='tgg_studio_project_presence' and p.polname='tgg_studio_presence_members'
    ),
    'public_live_chat_read_guard',exists(
      select 1
      from pg_policy p
      join pg_class c on c.oid=p.polrelid
      where c.relname='tgg_live_chat_messages'
        and p.polname='tgg_live_chat_read'
        and pg_get_expr(p.polqual,p.polrelid) ilike '%chat_enabled = true%'
        and pg_get_expr(p.polqual,p.polrelid) ilike '%status = ''PUBLISHED''%'
        and pg_get_expr(p.polqual,p.polrelid) ilike '%visibility = ''PUBLIC''%'
    ),
    'public_live_chat_insert_guard',exists(
      select 1
      from pg_policy p
      join pg_class c on c.oid=p.polrelid
      where c.relname='tgg_live_chat_messages'
        and p.polname='tgg_live_chat_insert'
        and pg_get_expr(p.polwithcheck,p.polrelid) ilike '%chat_enabled = true%'
        and pg_get_expr(p.polwithcheck,p.polrelid) ilike '%status = ''LIVE''%'
        and pg_get_expr(p.polwithcheck,p.polrelid) ilike '%char_length(body)%'
    )
  ) checks
),
agg as (
  select
    count(*) total,
    count(*) filter(where published) published_count,
    count(*) filter(where rls_enabled) rls_count,
    count(*) filter(where auth_select) auth_select_count,
    count(*) filter(where anon_select=anon_expected) anon_contract_count,
    coalesce(jsonb_agg(name) filter(where not published),'[]'::jsonb) not_published,
    coalesce(jsonb_agg(name) filter(where not rls_enabled),'[]'::jsonb) no_rls,
    coalesce(jsonb_agg(name) filter(where anon_select<>anon_expected),'[]'::jsonb) anon_mismatch
  from state
)
select jsonb_build_object(
  'ok',
    published_count=total
    and rls_count=total
    and auth_select_count=total
    and anon_contract_count=total
    and not exists(
      select 1 from jsonb_each((select checks from policy_checks))
      where coalesce((value#>>'{}')::boolean,false)=false
    ),
  'version','REALTIME-SECURITY-1.1',
  'publication',jsonb_build_object(
    'ready',published_count,'total',total,'missing',not_published
  ),
  'rls',jsonb_build_object(
    'ready',rls_count,'total',total,'missing',no_rls
  ),
  'anonymous_contract',jsonb_build_object(
    'ready',anon_contract_count,'total',total,'mismatch',anon_mismatch,
    'public_table','tgg_live_chat_messages',
    'private_tables',jsonb_build_array(
      'tgg_call_signals','tgg_live_guest_requests','tgg_messages',
      'tgg_studio_project_events','tgg_studio_project_presence'
    )
  ),
  'policy_checks',(select checks from policy_checks),
  'generated_at',now()
)
from agg;
$function$


-- [40000001188] function public.tgg_record_creator_event(p_event_type text, p_mixtape_id uuid, p_session_id text, p_source text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_record_creator_event(p_event_type text, p_mixtape_id uuid DEFAULT NULL::uuid, p_session_id text DEFAULT NULL::text, p_source text DEFAULT 'web'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_creator_id uuid;
  v_event_id uuid;
  v_type text:=lower(trim(coalesce(p_event_type,'')));
  v_metadata jsonb:=coalesce(p_metadata,'{}'::jsonb);
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;

  if v_type not in ('play','download','release_view','track_play','video_view','merch_view','share') then
    raise exception 'unsupported analytics event type';
  end if;
  if jsonb_typeof(v_metadata)<>'object' then raise exception 'metadata must be an object'; end if;
  if octet_length(v_metadata::text)>8192 then raise exception 'metadata too large'; end if;

  if p_mixtape_id is not null then
    select m.artist_id into v_creator_id
    from public.mixtapes m
    join public.artists a on a.id=m.artist_id
    where m.id=p_mixtape_id
      and a.user_id=(select auth.uid());
    if v_creator_id is null then raise exception 'release unavailable or not owned'; end if;
  else
    select a.id into v_creator_id
    from public.artists a
    where a.user_id=(select auth.uid())
    order by a.created_at
    limit 1;
  end if;

  if v_creator_id is null then raise exception 'creator could not be resolved'; end if;

  insert into public.creator_analytics_events(
    creator_id,mixtape_id,event_type,session_id,source,metadata,occurred_at
  )
  values(
    v_creator_id,
    p_mixtape_id,
    v_type,
    nullif(left(trim(coalesce(p_session_id,'')),128),''),
    nullif(left(trim(coalesce(p_source,'web')),64),''),
    v_metadata,
    now()
  )
  returning id into v_event_id;

  return v_event_id;
end
$function$


-- [40000001189] function public.tgg_record_smart_link_event(p_link_id uuid, p_event_type text, p_destination text, p_referrer text, p_utm_source text, p_utm_medium text, p_utm_campaign text)
CREATE OR REPLACE FUNCTION public.tgg_record_smart_link_event(p_link_id uuid, p_event_type text DEFAULT 'click'::text, p_destination text DEFAULT NULL::text, p_referrer text DEFAULT NULL::text, p_utm_source text DEFAULT NULL::text, p_utm_medium text DEFAULT NULL::text, p_utm_campaign text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$
