$function$


-- [40000001190] function public.tgg_recording_add_take(p_session_id uuid, p_name text, p_storage_path text, p_duration_seconds numeric, p_notes text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_recording_add_take(p_session_id uuid, p_name text, p_storage_path text, p_duration_seconds numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS public.tgg_recording_takes
 LANGUAGE plpgsql
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_project uuid;
  v_next integer;
  v_asset uuid;
  v public.tgg_recording_takes;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select s.project_id into v_project
  from public.tgg_recording_sessions s
  where s.id=p_session_id
    and s.user_id=v_uid
    and s.status in ('open','paused');

  if v_project is null then raise exception 'SESSION_NOT_AVAILABLE'; end if;

  if p_storage_path is null
     or split_part(p_storage_path,'/',1)<>v_uid::text
     or p_storage_path !~ ('^' || v_uid::text || '/studio/') then
    raise exception 'INVALID_STORAGE_PATH';
  end if;

  if not exists(
    select 1 from storage.objects o
    where o.bucket_id='creator-media'
      and o.name=p_storage_path
      and (storage.foldername(o.name))[1]=v_uid::text
  ) then raise exception 'UPLOADED_AUDIO_NOT_FOUND'; end if;

  select coalesce(max(take_number),0)+1 into v_next
  from public.tgg_recording_takes
  where session_id=p_session_id;

  v_asset:=public.tgg_register_studio_asset(
    v_project,'recording',p_name,p_storage_path,
    coalesce(p_metadata,'{}'::jsonb)
      || jsonb_build_object('duration_seconds',p_duration_seconds,'recording_take',true)
  );

  insert into public.tgg_recording_takes(
    session_id,project_id,user_id,take_number,name,asset_id,storage_path,
    duration_seconds,notes,metadata
  )
  values(
    p_session_id,v_project,v_uid,v_next,btrim(p_name),v_asset,p_storage_path,
    p_duration_seconds,nullif(btrim(coalesce(p_notes,'')),''),coalesce(p_metadata,'{}'::jsonb)
  )
  returning * into v;

  perform public.tgg_mark_media_upload_finalized(p_storage_path);
  return v;
end
$function$


-- [40000001191] function public.tgg_recording_select_take(p_take_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_recording_select_take(p_take_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_session uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

      select session_id into v_session
      from public.tgg_recording_takes
      where id=p_take_id and user_id=v_uid;

      if v_session is null then raise exception 'TAKE_NOT_FOUND'; end if;

      update public.tgg_recording_takes
      set is_selected=(id=p_take_id)
      where session_id=v_session and user_id=v_uid;

      return jsonb_build_object('ok',true,'take_id',p_take_id,'selected',true);
    end;
    $function$


-- [40000001192] function public.tgg_recording_session_set_status(p_session_id uuid, p_status text)
CREATE OR REPLACE FUNCTION public.tgg_recording_session_set_status(p_session_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_status text:=lower(btrim(coalesce(p_status,'')));
      v_project uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if v_status not in ('open','paused','completed') then raise exception 'STATUS_INVALID'; end if;

      update public.tgg_recording_sessions
      set status=v_status,
          ended_at=case when v_status='completed' then coalesce(ended_at,now()) else null end,
          updated_at=now()
      where id=p_session_id and user_id=v_uid
      returning project_id into v_project;

      if v_project is null then raise exception 'SESSION_NOT_FOUND'; end if;

      update public.tgg_studio_projects
      set status=case when v_status='completed' then 'draft' else 'recording' end,
          updated_at=now()
      where id=v_project and user_id=v_uid;

      return jsonb_build_object('ok',true,'session_id',p_session_id,'status',v_status);
    end;
    $function$


-- [40000001193] function public.tgg_recording_start_session(p_project_id uuid, p_title text, p_sample_rate integer, p_bit_depth integer, p_notes text)
CREATE OR REPLACE FUNCTION public.tgg_recording_start_session(p_project_id uuid, p_title text DEFAULT 'Recording Session'::text, p_sample_rate integer DEFAULT 48000, p_bit_depth integer DEFAULT 24, p_notes text DEFAULT NULL::text)
 RETURNS public.tgg_recording_sessions
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v public.tgg_recording_sessions;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  if not (
    exists(
      select 1 from public.tgg_studio_projects p
      where p.id=p_project_id and p.user_id=v_uid
    )
    or exists(
      select 1 from public.tgg_studio_project_members m
      where m.project_id=p_project_id
        and m.user_id=v_uid
        and m.left_at is null
        and m.can_record
    )
  ) then raise exception 'PROJECT_NOT_AVAILABLE'; end if;

  insert into public.tgg_recording_sessions(
    project_id,user_id,title,status,sample_rate,bit_depth,notes
  )
  values(
    p_project_id,v_uid,btrim(coalesce(p_title,'Recording Session')),
    'open',p_sample_rate,p_bit_depth,nullif(btrim(coalesce(p_notes,'')),'')
  )
  returning * into v;

  update public.tgg_studio_projects
  set status='recording',updated_at=now()
  where id=p_project_id and user_id=v_uid;

  return v;
end
$function$


