-- [40000001196] function public.tgg_refresh_creator_action_queue(p_artist_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_refresh_creator_action_queue(p_artist_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ declare v_uid uuid:=(select auth.uid());v_artist uuid;v_added integer:=0; begin if v_uid is null then raise exception 'Authentication required';end if;select id into v_artist from public.artists where user_id=v_uid and (p_artist_id is null or id=p_artist_id) order by created_at nulls last limit 1;if v_artist is null then return 0;end if;delete from public.tgg_creator_action_queue where owner_user_id=v_uid and artist_id=v_artist and source_type='copilot' and status='open';insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,action_type,title,rationale,priority,metadata) select v_uid,v_artist,'copilot','release_readiness','Finish release checklist','One or more release-readiness items are still open.',90,jsonb_build_object('open_items',count(*)) from public.tgg_release_checklist_items where owner_user_id=v_uid and artist_id=v_artist and status<>'done' having count(*)>0;get diagnostics v_added=row_count;insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,action_type,title,rationale,priority,metadata) select v_uid,v_artist,'copilot','campaign','Create or activate a campaign','No active campaign is currently supporting this artist.',80,'{}'::jsonb where not exists(select 1 from public.tgg_campaigns where owner_user_id=v_uid and artist_id=v_artist and status in('active','scheduled'));v_added:=v_added+(case when found then 1 else 0 end);insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,action_type,title,rationale,priority,metadata) select v_uid,v_artist,'copilot','smart_link','Create a smart link','No active smart link exists for this artist.',70,'{}'::jsonb where not exists(select 1 from public.tgg_smart_links where owner_user_id=v_uid and artist_id=v_artist and is_active=true);v_added:=v_added+(case when found then 1 else 0 end);insert into public.tgg_creator_action_queue(owner_user_id,artist_id,source_type,action_type,title,rationale,priority,metadata) select v_uid,v_artist,'copilot','goal','Set a creator goal','No active creator goal is currently tracking progress.',60,'{}'::jsonb where not exists(select 1 from public.tgg_creator_goals where owner_user_id=v_uid and artist_id=v_artist and status='active');v_added:=v_added+(case when found then 1 else 0 end);return v_added;end $function$


-- [40000001197] function public.tgg_refresh_creator_command_center()
CREATE OR REPLACE FUNCTION public.tgg_refresh_creator_command_center()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_release int:=0; v_event int:=0; v_fan int:=0; v_support int:=0; v_total int:=0;
begin
 if v_uid is null then raise exception 'authentication required'; end if;
 begin v_release:=public.tgg_generate_release_campaign_actions(); exception when undefined_function then v_release:=0; end;
 begin v_event:=public.tgg_generate_event_booking_actions(); exception when undefined_function then v_event:=0; end;
 begin perform public.tgg_refresh_fan_intelligence(); perform public.tgg_sync_fan_crm_segments(); v_fan:=public.tgg_generate_fan_followup_actions(); exception when undefined_function then v_fan:=0; end;
 begin perform public.tgg_refresh_supporter_health(); v_support:=public.tgg_generate_supporter_retention_actions(); exception when undefined_function then v_support:=0; end;
 v_total:=coalesce(v_release,0)+coalesce(v_event,0)+coalesce(v_fan,0)+coalesce(v_support,0);
 return jsonb_build_object('release_campaign_actions',v_release,'event_booking_live_actions',v_event,'fan_actions',v_fan,'supporter_actions',v_support,'new_actions_total',v_total,'refreshed_at',now());
end $function$


