-- [40000001206] function public.tgg_release_embed_delete(p_release_id uuid, p_provider text)
CREATE OR REPLACE FUNCTION public.tgg_release_embed_delete(p_release_id uuid, p_provider text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_provider text:=lower(btrim(coalesce(p_provider,'')));v_deleted text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  delete from public.tgg_release_external_embeds
  where release_id=p_release_id and provider=v_provider and owner_user_id=v_uid
  returning provider into v_deleted;
  if v_deleted is null then raise exception 'EMBED_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'release_id',p_release_id,'provider',v_deleted,'deleted',true);
end $function$


-- [40000001207] function public.tgg_release_embed_upsert(p_release_id uuid, p_provider text, p_source_url text, p_title text, p_is_active boolean)
CREATE OR REPLACE FUNCTION public.tgg_release_embed_upsert(p_release_id uuid, p_provider text, p_source_url text, p_title text DEFAULT NULL::text, p_is_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_provider text:=lower(btrim(coalesce(p_provider,'')));
  v_url text:=btrim(coalesce(p_source_url,''));
  v_embed text;
  v_mode text:='iframe';
  v_artist uuid;
  v_match text[];
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select artist_id into v_artist from public.mixtapes where id=p_release_id and user_id=v_uid;
  if not found then raise exception 'RELEASE_NOT_FOUND_OR_NOT_OWNED'; end if;

  if v_provider='spotify' then
    if v_url !~ '^https://open\.spotify\.com/(track|album|playlist|artist|episode|show)/[A-Za-z0-9]+' then
      raise exception 'SPOTIFY_URL_INVALID';
    end if;
    v_embed:=regexp_replace(split_part(v_url,'?',1),'^https://open\.spotify\.com/','https://open.spotify.com/embed/');
  elsif v_provider='apple_music' then
    if v_url ~ '^https://embed\.music\.apple\.com/' then
      v_embed:=v_url; v_mode:='iframe';
    elsif v_url ~ '^https://music\.apple\.com/' then
      v_embed:=null; v_mode:='link';
    else
      raise exception 'APPLE_MUSIC_URL_INVALID';
    end if;
  elsif v_provider='youtube_music' then
    if v_url !~ '^https://music\.youtube\.com/watch\?' then
      raise exception 'YOUTUBE_MUSIC_URL_INVALID';
    end if;
    v_match:=regexp_match(v_url,'[?&]v=([A-Za-z0-9_-]{6,})');
    if v_match is null then raise exception 'YOUTUBE_MUSIC_VIDEO_ID_REQUIRED'; end if;
    v_embed:='https://www.youtube.com/embed/'||v_match[1];
    v_mode:='iframe';
  else
    raise exception 'PROVIDER_INVALID';
  end if;

  insert into public.tgg_release_external_embeds(
    release_id,owner_user_id,artist_id,provider,source_url,embed_url,embed_mode,title,is_active,updated_at
  ) values(
    p_release_id,v_uid,v_artist,v_provider,v_url,v_embed,v_mode,
    nullif(left(btrim(coalesce(p_title,'')),160),''),coalesce(p_is_active,true),now()
  )
  on conflict(release_id,provider) do update set
    source_url=excluded.source_url,
    embed_url=excluded.embed_url,
    embed_mode=excluded.embed_mode,
    title=excluded.title,
    is_active=excluded.is_active,
    updated_at=now();

  return jsonb_build_object(
    'ok',true,'release_id',p_release_id,'provider',v_provider,
    'embed_mode',v_mode,'embed_url',v_embed,'active',coalesce(p_is_active,true)
  );
end $function$


-- [40000001208] function public.tgg_release_train_plan(p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_release_train_plan(p_limit integer DEFAULT 15)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manifest jsonb:='[]'::jsonb;
  v_count integer:=0;
  v_key text;
  v_id uuid;
begin
  if p_limit<1 or p_limit>25 then raise exception 'p_limit must be 1..25'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'candidate_id',id,'candidate_key',candidate_key,'version',version,'channel',channel,
    'status',status,'rollback_candidate_key',rollback_candidate_key,
    'production_approval_required',production_approval_required
  ) order by created_at),'[]'::jsonb),
  count(*)
  into v_manifest,v_count
  from (
    select *
    from public.tgg_build_release_candidates
    where lower(coalesce(channel,'internal')) in ('internal','staging','development')
      and coalesce(canary_percent,0)=0
      and promoted_at is null
      and lower(status) in ('prepared','ready','verified','staged','passed')
      and coalesce((release_notes->>'production_touched')::boolean,false)=false
    order by created_at
    limit p_limit
  ) q;

  if v_count=0 then
    return jsonb_build_object(
      'ok',true,'status','no_candidates','candidate_count',0,'manifest','[]'::jsonb,
      'production_promotion_allowed',false,'production_change_performed',false
    );
  end if;

  v_key:='train:'||to_char(now(),'YYYYMMDDHH24MISS')||':'||replace(gen_random_uuid()::text,'-','');

  insert into public.tgg_release_trains(
    train_key,status,target_environment,candidate_count,production_promotion_allowed,manifest,validation
  )
  values(
    v_key,'ready','staging',v_count,false,v_manifest,
    jsonb_build_object(
      'canary_candidates_included',false,'production_promotion_allowed',false,
      'canonical_boundary','AB-006','canonical_source_version','V223'
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'train_id',v_id,'train_key',v_key,'status','ready',
    'candidate_count',v_count,'manifest',v_manifest,
    'production_promotion_allowed',false,'production_change_performed',false
  );
end $function$


-- [40000001209] function public.tgg_release_train_state()
