 RETURNS uuid
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select public.tgg_send_message(p_conversation_id,p_body,'text',null);
$function$


-- [40000001222] function public.tgg_send_message(p_conversation_id uuid, p_body text, p_message_type text, p_reply_to_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_send_message(p_conversation_id uuid, p_body text, p_message_type text DEFAULT 'text'::text, p_reply_to_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_id uuid;
  v_body text:=nullif(btrim(coalesce(p_body,'')),'');
  v_type text:=coalesce(nullif(btrim(coalesce(p_message_type,'')),''),'text');
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  if not exists(
    select 1
    from public.tgg_conversation_members
    where conversation_id=p_conversation_id
      and user_id=v_uid
  ) then
    raise exception 'NOT_A_MEMBER';
  end if;

  if v_body is null then raise exception 'EMPTY_MESSAGE'; end if;
  if char_length(v_body)>5000 then raise exception 'MESSAGE_TOO_LONG'; end if;
  if v_type not in ('text') then raise exception 'INVALID_MESSAGE_TYPE'; end if;

  if p_reply_to_id is not null and not exists(
    select 1
    from public.tgg_messages
    where id=p_reply_to_id
      and conversation_id=p_conversation_id
  ) then
    raise exception 'INVALID_REPLY';
  end if;

  insert into public.tgg_messages(
    conversation_id,sender_id,body,message_type,reply_to_message_id
  )
  values(
    p_conversation_id,v_uid,v_body,v_type,p_reply_to_id
  )
  returning id into v_id;

  update public.tgg_conversations
  set last_message_at=now(),updated_at=now()
  where id=p_conversation_id;

  return v_id;
end
$function$


-- [40000001223] function public.tgg_server_blogger_refresh_token(p_user_id uuid, p_connection_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_server_blogger_refresh_token(p_user_id uuid, p_connection_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text;
  v_secret_name text;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'') <> 'service_role'
     and coalesce(current_setting('request.jwt.claims',true),'') not like '%"role":"service_role"%'
  then
    raise exception 'service_role_required' using errcode='42501';
  end if;

  if not exists (
    select 1
    from public.v98_blogger_connections c
    where c.id=p_connection_id
      and c.user_id=p_user_id
      and c.status='connected'
      and c.revoked_at is null
  ) then
    raise exception 'connection_not_owned_or_inactive';
  end if;

  v_secret_name:='v98_blogger_refresh_' || replace(p_connection_id::text,'-','_');

  select decrypted_secret
  into v_token
  from vault.decrypted_secrets
  where name=v_secret_name
  limit 1;

  if v_token is null or length(v_token)=0 then
    raise exception 'refresh_token_unavailable';
  end if;

  return v_token;
end
$function$


-- [40000001224] function public.tgg_set_collection_visibility(p_collection_id uuid, p_is_public boolean)
CREATE OR REPLACE FUNCTION public.tgg_set_collection_visibility(p_collection_id uuid, p_is_public boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare v_user uuid:=auth.uid(); v_count integer; begin if v_user is null then raise exception 'authentication required'; end if; update public.fan_collections set is_public=coalesce(p_is_public,false),updated_at=now() where id=p_collection_id and user_id=v_user; get diagnostics v_count=row_count; return v_count>0; end $function$


-- [40000001225] function public.tgg_set_conversation_status(p_conversation_id uuid, p_status text)
CREATE OR REPLACE FUNCTION public.tgg_set_conversation_status(p_conversation_id uuid, p_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user uuid:=auth.uid();
  v_status text:=lower(btrim(coalesce(p_status,'')));
  v_count integer;
begin
  if v_user is null then raise exception 'authentication required'; end if;
  if v_status not in ('active','archived') then raise exception 'invalid status'; end if;

  update public.tgg_conversations
  set status=v_status,updated_at=now()
  where id=p_conversation_id
    and created_by=v_user;

  get diagnostics v_count=row_count;
  if v_count=0 then
    raise exception 'conversation unavailable or owner required';
  end if;

  return true;
end
$function$


-- [40000001226] function public.tgg_set_creator_action_status(p_action_id uuid, p_status text)
CREATE OR REPLACE FUNCTION public.tgg_set_creator_action_status(p_action_id uuid, p_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin if p_status not in('open','done','dismissed') then raise exception 'Invalid status';end if;update public.tgg_creator_action_queue set status=p_status,updated_at=now() where id=p_action_id and owner_user_id=(select auth.uid());return found;end $function$


-- [40000001227] function public.tgg_set_creator_ui_preferences(p_default_workspace text, p_compact_mode boolean, p_sidebar_collapsed boolean, p_reduce_motion boolean)
CREATE OR REPLACE FUNCTION public.tgg_set_creator_ui_preferences(p_default_workspace text DEFAULT NULL::text, p_compact_mode boolean DEFAULT NULL::boolean, p_sidebar_collapsed boolean DEFAULT NULL::boolean, p_reduce_motion boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); outrow jsonb; allowed text[]:=array['dashboard','releases','fans','growth','messages','live','opportunities','supporters','career','library'];
begin
 if uid is null then raise exception 'authentication required'; end if;
 if p_default_workspace is not null and not (p_default_workspace=any(allowed)) then raise exception 'invalid workspace'; end if;
 insert into public.tgg_creator_ui_preferences(user_id,default_workspace,compact_mode,sidebar_collapsed,reduce_motion)
 values(uid,coalesce(p_default_workspace,'dashboard'),coalesce(p_compact_mode,false),coalesce(p_sidebar_collapsed,false),coalesce(p_reduce_motion,false))
 on conflict(user_id) do update set
 default_workspace=coalesce(p_default_workspace,tgg_creator_ui_preferences.default_workspace),
 compact_mode=coalesce(p_compact_mode,tgg_creator_ui_preferences.compact_mode),
 sidebar_collapsed=coalesce(p_sidebar_collapsed,tgg_creator_ui_preferences.sidebar_collapsed),
 reduce_motion=coalesce(p_reduce_motion,tgg_creator_ui_preferences.reduce_motion),updated_at=now()
 returning to_jsonb(tgg_creator_ui_preferences.*) into outrow;
 return outrow;
end $function$


-- [40000001228] function public.tgg_set_creator_ui_workspace_state(p_workspace text, p_search_query text, p_filter_state jsonb, p_sort_key text, p_sort_direction text, p_view_mode text, p_page_size integer)
CREATE OR REPLACE FUNCTION public.tgg_set_creator_ui_workspace_state(p_workspace text, p_search_query text DEFAULT NULL::text, p_filter_state jsonb DEFAULT NULL::jsonb, p_sort_key text DEFAULT NULL::text, p_sort_direction text DEFAULT NULL::text, p_view_mode text DEFAULT NULL::text, p_page_size integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  uid uuid:=auth.uid();
  result jsonb;
begin
  if uid is null then raise exception 'authentication required'; end if;
  if p_workspace not in ('dashboard','releases','fans','growth','messages','live','opportunities','supporters','career','library') then raise exception 'invalid workspace'; end if;
  if p_search_query is not null and char_length(p_search_query)>500 then raise exception 'search query too long'; end if;
  if p_filter_state is not null and jsonb_typeof(p_filter_state)<>'object' then raise exception 'invalid filter state'; end if;
  if p_filter_state is not null and octet_length(p_filter_state::text)>8192 then raise exception 'filter state too large'; end if;
  if p_sort_key is not null and char_length(p_sort_key)>80 then raise exception 'sort key too long'; end if;
  if p_sort_direction is not null and p_sort_direction not in ('asc','desc') then raise exception 'invalid sort direction'; end if;
  if p_view_mode is not null and char_length(p_view_mode)>80 then raise exception 'view mode too long'; end if;
  if p_page_size is not null and (p_page_size<5 or p_page_size>100) then raise exception 'invalid page size'; end if;

  insert into public.tgg_creator_ui_workspace_state(
    user_id,workspace,search_query,filter_state,sort_key,sort_direction,view_mode,page_size
  )
  values(
    uid,p_workspace,p_search_query,coalesce(p_filter_state,'{}'::jsonb),
    p_sort_key,coalesce(p_sort_direction,'desc'),coalesce(p_view_mode,'default'),coalesce(p_page_size,25)
  )
  on conflict(user_id,workspace) do update set
    search_query=coalesce(p_search_query,tgg_creator_ui_workspace_state.search_query),
    filter_state=coalesce(p_filter_state,tgg_creator_ui_workspace_state.filter_state),
    sort_key=coalesce(p_sort_key,tgg_creator_ui_workspace_state.sort_key),
    sort_direction=coalesce(p_sort_direction,tgg_creator_ui_workspace_state.sort_direction),
    view_mode=coalesce(p_view_mode,tgg_creator_ui_workspace_state.view_mode),
    page_size=coalesce(p_page_size,tgg_creator_ui_workspace_state.page_size),
    updated_at=now()
  returning to_jsonb(tgg_creator_ui_workspace_state.*) into result;

  return result;
end
$function$


-- [40000001229] function public.tgg_set_release_date(p_release_id uuid, p_release_date timestamp with time zone)
CREATE OR REPLACE FUNCTION public.tgg_set_release_date(p_release_id uuid, p_release_date timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_artist_id uuid;
  v_title text;
begin
  if v_user_id is null then raise exception 'AUTH_REQUIRED'; end if;
  select a.id into v_artist_id from public.artists a where a.user_id=v_user_id;
  if v_artist_id is null then raise exception 'ARTIST_PROFILE_NOT_FOUND'; end if;
  update public.mixtapes
     set release_date=p_release_date
   where id=p_release_id and artist_id=v_artist_id
   returning title into v_title;
  if v_title is null then raise exception 'RELEASE_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'release_id',p_release_id,'title',v_title,'release_date',p_release_date);
end;
$function$


-- [40000001230] function public.tgg_set_release_reaction(p_mixtape_id uuid, p_reaction text)
CREATE OR REPLACE FUNCTION public.tgg_set_release_reaction(p_mixtape_id uuid, p_reaction text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare v_user uuid:=auth.uid(); v_reaction text:=lower(btrim(p_reaction)); begin if v_user is null then raise exception 'authentication required'; end if; if v_reaction not in ('like','fire') then raise exception 'invalid reaction'; end if; if not exists(select 1 from public.mixtapes m where m.id=p_mixtape_id and m.status='published') then raise exception 'release unavailable'; end if; insert into public.release_reactions(user_id,mixtape_id,reaction) values(v_user,p_mixtape_id,v_reaction) on conflict(user_id,mixtape_id) do update set reaction=excluded.reaction,updated_at=now(); return v_reaction; end $function$


-- [40000001231] function public.tgg_short_create_draft(p_caption text, p_media_url text, p_thumbnail_url text, p_linked_release_id uuid, p_visibility text, p_duration_seconds numeric)
CREATE OR REPLACE FUNCTION public.tgg_short_create_draft(p_caption text, p_media_url text, p_thumbnail_url text DEFAULT NULL::text, p_linked_release_id uuid DEFAULT NULL::uuid, p_visibility text DEFAULT 'public'::text, p_duration_seconds numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_vis text:=lower(coalesce(nullif(btrim(coalesce(p_visibility,'')),''),'public'));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_media_url,'')))<1 then raise exception 'MEDIA_URL_REQUIRED'; end if;
  if v_vis not in ('public','unlisted','private') then raise exception 'VISIBILITY_INVALID'; end if;
  if p_duration_seconds is not null and (p_duration_seconds<=0 or p_duration_seconds>600) then raise exception 'DURATION_INVALID'; end if;
  insert into public.tgg_shorts(user_id,caption,media_url,thumbnail_url,linked_release_id,visibility,status,duration_seconds)
  values(v_uid,nullif(btrim(coalesce(p_caption,'')),''),btrim(p_media_url),nullif(btrim(coalesce(p_thumbnail_url,'')),''),p_linked_release_id,v_vis,'draft',p_duration_seconds)
  returning id into v_id;
  return jsonb_build_object('ok',true,'short_id',v_id,'status','draft');
end $function$


-- [40000001232] function public.tgg_short_delete(p_short_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_short_delete(p_short_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  delete from public.tgg_shorts where id=p_short_id and user_id=v_uid returning id into v_id;
  if v_id is null then raise exception 'SHORT_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'short_id',v_id,'deleted',true);
end $function$


-- [40000001233] function public.tgg_short_set_published(p_short_id uuid, p_published boolean)
CREATE OR REPLACE FUNCTION public.tgg_short_set_published(p_short_id uuid, p_published boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_status text:=case when coalesce(p_published,false) then 'published' else 'draft' end;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  update public.tgg_shorts
  set status=v_status,updated_at=now()
  where id=p_short_id and user_id=v_uid
  returning id into v_id;
  if v_id is null then raise exception 'SHORT_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'short_id',v_id,'status',v_status);
end $function$


-- [40000001234] function public.tgg_short_update(p_short_id uuid, p_caption text, p_media_url text, p_thumbnail_url text, p_linked_release_id uuid, p_visibility text, p_duration_seconds numeric)
CREATE OR REPLACE FUNCTION public.tgg_short_update(p_short_id uuid, p_caption text, p_media_url text, p_thumbnail_url text, p_linked_release_id uuid, p_visibility text, p_duration_seconds numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
