-- [40000001235] function public.tgg_signup_approval_issue_service(p_token uuid, p_email_hash text, p_purpose text)
CREATE OR REPLACE FUNCTION public.tgg_signup_approval_issue_service(p_token uuid, p_email_hash text, p_purpose text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
begin
  if p_token is null or coalesce(length(p_email_hash),0) <> 64 then
    raise exception 'invalid signup approval payload';
  end if;
  if p_purpose not in ('creator_os_direct','call_validation_invite') then
    raise exception 'invalid signup approval purpose';
  end if;
  delete from private.tgg_signup_password_approvals where expires_at <= now();
  insert into private.tgg_signup_password_approvals(token,email_hash,purpose,expires_at)
  values (p_token,lower(p_email_hash),p_purpose,now()+interval '5 minutes')
  on conflict (token) do update set
    email_hash=excluded.email_hash,
    purpose=excluded.purpose,
    expires_at=excluded.expires_at,
    created_at=now();
  return jsonb_build_object('ok',true,'expires_in_seconds',300);
end;
$function$


-- [40000001236] function public.tgg_signup_approval_revoke_service(p_token uuid)
CREATE OR REPLACE FUNCTION public.tgg_signup_approval_revoke_service(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
declare n integer;
begin
  delete from private.tgg_signup_password_approvals where token=p_token;
  get diagnostics n = row_count;
  return jsonb_build_object('ok',true,'deleted',n);
end;
$function$


-- [40000001237] function public.tgg_smart_link_create(p_title text, p_release_id uuid, p_slug text, p_destinations jsonb, p_is_active boolean)
CREATE OR REPLACE FUNCTION public.tgg_smart_link_create(p_title text, p_release_id uuid DEFAULT NULL::uuid, p_slug text DEFAULT NULL::text, p_destinations jsonb DEFAULT '[]'::jsonb, p_is_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_artist uuid;
  v_slug text;
  v_id uuid;
  v_bad integer;
  v_dest jsonb:=coalesce(p_destinations,'[]'::jsonb);
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_title,'')))<1 or char_length(btrim(p_title))>160 then raise exception 'TITLE_INVALID'; end if;
  if jsonb_typeof(v_dest)<>'array' or jsonb_array_length(v_dest)<1 then raise exception 'DESTINATIONS_REQUIRED'; end if;

  select count(*) into v_bad
  from jsonb_array_elements(v_dest) x
  where lower(coalesce(x->>'provider','')) not in (
    'spotify','apple_music','youtube','youtube_music','soundcloud','tidal',
    'audiomack','bandcamp','deezer','amazon_music','tgg'
  )
  or coalesce(x->>'url','') !~* '^https?://'
  or char_length(coalesce(x->>'url',''))>2048;

  if v_bad>0 then raise exception 'DESTINATION_INVALID'; end if;

  select id into v_artist from public.artists where user_id=v_uid limit 1;
  if v_artist is null then raise exception 'ARTIST_PROFILE_REQUIRED'; end if;

  if p_release_id is not null and not exists(
    select 1 from public.mixtapes m where m.id=p_release_id and m.user_id=v_uid
  ) then raise exception 'RELEASE_NOT_FOUND_OR_NOT_OWNED'; end if;

  v_slug:=lower(regexp_replace(coalesce(nullif(btrim(p_slug),''),btrim(p_title)),'[^a-zA-Z0-9]+','-','g'));
  v_slug:=trim(both '-' from v_slug);
  if char_length(v_slug)<2 then v_slug:='link-'||left(replace(gen_random_uuid()::text,'-',''),8); end if;
  if exists(select 1 from public.tgg_smart_links where slug=v_slug) then
    v_slug:=left(v_slug,80)||'-'||left(replace(gen_random_uuid()::text,'-',''),6);
  end if;

  if p_release_id is not null and not exists(
    select 1 from jsonb_array_elements(v_dest) x where lower(x->>'provider')='tgg'
  ) then
    v_dest:=v_dest||jsonb_build_array(jsonb_build_object(
      'provider','tgg','label','Tru Go Getta','url','https://trugogettamixtapes.blogspot.com/p/mixtape.html?id='||p_release_id::text
    ));
  end if;

  insert into public.tgg_smart_links(
    owner_user_id,artist_id,release_id,title,slug,destination_type,destinations,is_active
  )
  values(
    v_uid,v_artist,p_release_id,btrim(p_title),v_slug,
    case when p_release_id is null then 'artist' else 'release' end,
    v_dest,coalesce(p_is_active,true)
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'link_id',v_id,'slug',v_slug,
    'public_url','/p/smart-link.html?slug='||v_slug,
    'is_active',coalesce(p_is_active,true)
  );
end $function$


-- [40000001238] function public.tgg_smart_link_delete(p_link_id uuid)
