end $function$


-- [40000001239] function public.tgg_smart_link_event_rollup()
CREATE OR REPLACE FUNCTION public.tgg_smart_link_event_rollup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.event_type='destination_click' then
    update public.tgg_smart_links
    set click_count=click_count+1,updated_at=now()
    where id=new.link_id and is_active=true;
  end if;
  return new;
end $function$


