          jsonb_build_object('key','tgg','label','Tru Go Getta','category','platform','supports_embed',true)
        )
      );
    $function$


-- [40000001241] function public.tgg_smart_link_update(p_link_id uuid, p_title text, p_destinations jsonb, p_is_active boolean)
CREATE OR REPLACE FUNCTION public.tgg_smart_link_update(p_link_id uuid, p_title text, p_destinations jsonb, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_bad integer;
  v_id uuid;
  v_dest jsonb:=coalesce(p_destinations,'[]'::jsonb);
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_title,'')))<1 or char_length(btrim(p_title))>160 then raise exception 'TITLE_INVALID'; end if;
  if jsonb_typeof(v_dest)<>'array' or jsonb_array_length(v_dest)<1 then raise exception 'DESTINATIONS_REQUIRED'; end if;

  select count(*) into v_bad
  from jsonb_array_elements(v_dest) x
  where lower(coalesce(x->>'provider','')) not in (
    'spotify','apple_music','youtube','youtube_music','soundcloud','tidal',
    'audiomack','bandcamp','deezer','amazon_music','tgg'
  )
  or coalesce(x->>'url','') !~* '^https?://'
  or char_length(coalesce(x->>'url',''))>2048;

  if v_bad>0 then raise exception 'DESTINATION_INVALID'; end if;

  update public.tgg_smart_links l
  set title=btrim(p_title),
      destinations=v_dest,
      is_active=coalesce(p_is_active,l.is_active),
      updated_at=now()
  where l.id=p_link_id and l.owner_user_id=v_uid
  returning id into v_id;

  if v_id is null then raise exception 'SMART_LINK_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'link_id',v_id);
end $function$


-- [40000001242] function public.tgg_sound_library_import(p_sound_id uuid, p_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_sound_library_import(p_sound_id uuid, p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_sound public.tgg_sound_library_items;
      v_asset public.tgg_studio_assets;
      v_import public.tgg_sound_library_imports;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

      if not exists(
        select 1 from public.tgg_studio_projects p
        where p.id=p_project_id and p.user_id=v_uid
      ) then raise exception 'PROJECT_NOT_FOUND_OR_NOT_OWNED'; end if;

      select * into v_sound
      from public.tgg_sound_library_items
      where id=p_sound_id and is_active=true
        and (owner_user_id is null or owner_user_id=v_uid);

      if v_sound.id is null then raise exception 'SOUND_NOT_FOUND'; end if;
      if not v_sound.import_allowed then raise exception 'IMPORT_NOT_ALLOWED_BY_LICENSE'; end if;
      if nullif(btrim(coalesce(v_sound.import_url,'')),'') is null
         and nullif(btrim(coalesce(v_sound.storage_path,'')),'') is null then
        raise exception 'IMPORT_SOURCE_UNAVAILABLE';
      end if;

      insert into public.tgg_studio_assets(
        project_id,user_id,asset_type,name,source_url,storage_path,
        license_name,license_url,source_name,source_item_url,metadata
      )
      values(
        p_project_id,v_uid,
        case when v_sound.asset_type in ('sample','loop','one_shot','drum','fx','vocal','instrument') then v_sound.asset_type else 'sample' end,
        v_sound.title,v_sound.import_url,v_sound.storage_path,
        v_sound.license_name,v_sound.license_url,v_sound.source_provider,v_sound.source_item_url,
        jsonb_build_object(
          'sound_library_id',v_sound.id,
          'bpm',v_sound.bpm,
          'musical_key',v_sound.musical_key,
          'tags',v_sound.tags,
          'duration_seconds',v_sound.duration_seconds,
          'license_kind',v_sound.license_kind,
          'commercial_use_allowed',v_sound.commercial_use_allowed,
          'attribution_required',v_sound.attribution_required,
          'attribution_text',v_sound.attribution_text
        )
      )
      returning * into v_asset;

      insert into public.tgg_sound_library_imports(
        user_id,sound_id,project_id,studio_asset_id,attribution_snapshot,license_snapshot
      )
      values(
        v_uid,v_sound.id,p_project_id,v_asset.id,v_sound.attribution_text,
        jsonb_build_object(
          'license_name',v_sound.license_name,
          'license_url',v_sound.license_url,
          'license_kind',v_sound.license_kind,
          'commercial_use_allowed',v_sound.commercial_use_allowed,
          'attribution_required',v_sound.attribution_required
        )
      )
      on conflict(user_id,sound_id,project_id)
      do update set studio_asset_id=excluded.studio_asset_id,
                    attribution_snapshot=excluded.attribution_snapshot,
                    license_snapshot=excluded.license_snapshot
      returning * into v_import;

      return jsonb_build_object(
        'ok',true,'sound_id',v_sound.id,'project_id',p_project_id,
        'studio_asset_id',v_asset.id,'import_id',v_import.id,
        'license_snapshot',v_import.license_snapshot,'attribution',v_import.attribution_snapshot
      );
    end;
    $function$


-- [40000001243] function public.tgg_sound_library_owned_access(p_sound_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_sound_library_owned_access(p_sound_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_sound public.tgg_sound_library_items;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select * into v_sound
      from public.tgg_sound_library_items
      where id=p_sound_id and is_active=true and owner_user_id=v_uid;
      if v_sound.id is null then raise exception 'OWNED_SOUND_NOT_FOUND'; end if;
      if nullif(btrim(coalesce(v_sound.storage_path,'')),'') is null then
        raise exception 'OWNED_SOUND_STORAGE_UNAVAILABLE';
      end if;
      return jsonb_build_object(
        'ok',true,
        'sound_id',v_sound.id,
        'bucket','creator-media',
        'storage_path',v_sound.storage_path,
        'title',v_sound.title
      );
    end;
    $function$


-- [40000001244] function public.tgg_sound_library_register_owned_asset(p_studio_asset_id uuid, p_asset_type text, p_bpm numeric, p_key text, p_tags text[])
CREATE OR REPLACE FUNCTION public.tgg_sound_library_register_owned_asset(p_studio_asset_id uuid, p_asset_type text, p_bpm numeric DEFAULT NULL::numeric, p_key text DEFAULT NULL::text, p_tags text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_asset public.tgg_studio_assets;
      v_sound public.tgg_sound_library_items;
      v_type text:=coalesce(nullif(btrim(p_asset_type),''),'sample');
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if v_type not in ('sample','loop','one_shot','drum','fx','vocal','instrument','other') then
        raise exception 'ASSET_TYPE_INVALID';
      end if;
      if p_bpm is not null and (p_bpm<30 or p_bpm>300) then raise exception 'BPM_INVALID'; end if;

      select * into v_asset
      from public.tgg_studio_assets
      where id=p_studio_asset_id and user_id=v_uid;

      if v_asset.id is null then raise exception 'STUDIO_ASSET_NOT_FOUND_OR_NOT_OWNED'; end if;
      if nullif(btrim(coalesce(v_asset.storage_path,'')),'') is null
         and nullif(btrim(coalesce(v_asset.source_url,'')),'') is null then
        raise exception 'ASSET_SOURCE_UNAVAILABLE';
      end if;

      insert into public.tgg_sound_library_items(
        source_provider,source_item_id,source_item_url,title,asset_type,bpm,musical_key,tags,
        preview_url,import_url,license_name,license_kind,commercial_use_allowed,
        attribution_required,import_allowed,metadata,is_active,owner_user_id,storage_path
      )
      values(
        'creator_upload',v_asset.id::text,v_asset.source_item_url,v_asset.name,v_type,p_bpm,
        nullif(btrim(coalesce(p_key,'')),''),coalesce(p_tags,'{}'::text[]),
        v_asset.source_url,v_asset.source_url,'User Owned','user_owned',true,false,true,
        jsonb_build_object(
          'studio_asset_id',v_asset.id,
          'origin_project_id',v_asset.project_id,
          'registered_from','studio_asset'
        ),
        true,v_uid,v_asset.storage_path
      )
      on conflict(source_provider,source_item_id)
      where source_item_id is not null
      do update set
        title=excluded.title,
        asset_type=excluded.asset_type,
        bpm=excluded.bpm,
        musical_key=excluded.musical_key,
        tags=excluded.tags,
        preview_url=excluded.preview_url,
        import_url=excluded.import_url,
        owner_user_id=excluded.owner_user_id,
        storage_path=excluded.storage_path,
        updated_at=now()
      returning * into v_sound;

      return jsonb_build_object(
        'ok',true,'sound_id',v_sound.id,'title',v_sound.title,
        'license_kind',v_sound.license_kind,'import_allowed',v_sound.import_allowed
      );
    end;
    $function$


-- [40000001245] function public.tgg_sound_library_register_owned_upload(p_project_id uuid, p_name text, p_storage_path text, p_asset_type text, p_bpm numeric, p_key text, p_tags text[], p_duration_seconds numeric)
CREATE OR REPLACE FUNCTION public.tgg_sound_library_register_owned_upload(p_project_id uuid, p_name text, p_storage_path text, p_asset_type text DEFAULT 'sample'::text, p_bpm numeric DEFAULT NULL::numeric, p_key text DEFAULT NULL::text, p_tags text[] DEFAULT '{}'::text[], p_duration_seconds numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_asset_id uuid;
      v_sound jsonb;
      v_path text:=btrim(coalesce(p_storage_path,''));
      v_name text:=btrim(coalesce(p_name,''));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if not exists(
        select 1 from public.tgg_studio_projects
        where id=p_project_id and user_id=v_uid and project_type='beat'
      ) then raise exception 'BEAT_PROJECT_NOT_FOUND_OR_NOT_OWNED'; end if;

      if char_length(v_name)<1 or char_length(v_name)>240 then raise exception 'NAME_INVALID'; end if;
      if split_part(v_path,'/',1)<>v_uid::text then raise exception 'STORAGE_PATH_NOT_OWNED'; end if;
      if p_duration_seconds is not null and (p_duration_seconds<0 or p_duration_seconds>7200) then
        raise exception 'DURATION_INVALID';
      end if;

      v_asset_id:=public.tgg_register_studio_asset(
        p_project_id,
        coalesce(nullif(btrim(p_asset_type),''),'sample'),
        v_name,
        v_path,
        jsonb_build_object(
          'source','beat_studio_upload',
          'duration_seconds',p_duration_seconds,
          'user_owned',true
        )
      );

      v_sound:=public.tgg_sound_library_register_owned_asset(
        v_asset_id,
        p_asset_type,
        p_bpm,
        p_key,
        coalesce(p_tags,'{}'::text[])
      );

      return v_sound || jsonb_build_object(
        'studio_asset_id',v_asset_id,
        'project_id',p_project_id,
        'storage_path',v_path
      );
    end;
    $function$


-- [40000001246] function public.tgg_sound_library_search(p_query text, p_asset_type text, p_bpm_min numeric, p_bpm_max numeric, p_key text, p_license_kind text, p_source_provider text, p_commercial_only boolean, p_importable_only boolean, p_favorites_only boolean, p_owned_only boolean, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_sound_library_search(p_query text DEFAULT NULL::text, p_asset_type text DEFAULT NULL::text, p_bpm_min numeric DEFAULT NULL::numeric, p_bpm_max numeric DEFAULT NULL::numeric, p_key text DEFAULT NULL::text, p_license_kind text DEFAULT NULL::text, p_source_provider text DEFAULT NULL::text, p_commercial_only boolean DEFAULT false, p_importable_only boolean DEFAULT true, p_favorites_only boolean DEFAULT false, p_owned_only boolean DEFAULT false, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_limit integer:=greatest(1,least(coalesce(p_limit,50),100));
  v_items jsonb;
  v_facets jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.favorited desc,x.title),'[]'::jsonb)
  into v_items
  from (
    select
      s.id,s.title,s.asset_type,s.bpm,s.musical_key,s.tags,s.duration_seconds,
      s.preview_url,s.source_provider,s.source_item_url,
      s.license_name,s.license_url,s.license_kind,
      s.commercial_use_allowed,s.attribution_required,s.attribution_text,s.import_allowed,
      (s.owner_user_id=v_uid) as owned,
      exists(
        select 1 from public.tgg_sound_library_favorites f
        where f.user_id=v_uid and f.sound_id=s.id
      ) as favorited
    from public.tgg_sound_library_items s
    where s.is_active=true
      and (s.owner_user_id is null or s.owner_user_id=v_uid)
      and (p_asset_type is null or s.asset_type=p_asset_type)
      and (p_bpm_min is null or s.bpm>=p_bpm_min)
      and (p_bpm_max is null or s.bpm<=p_bpm_max)
      and (p_key is null or lower(coalesce(s.musical_key,''))=lower(p_key))
      and (p_license_kind is null or s.license_kind=p_license_kind)
      and (p_source_provider is null or s.source_provider=p_source_provider)
      and (not coalesce(p_commercial_only,false) or s.commercial_use_allowed=true)
      and (not coalesce(p_importable_only,true) or s.import_allowed=true)
      and (not coalesce(p_owned_only,false) or s.owner_user_id=v_uid)
      and (
        not coalesce(p_favorites_only,false)
        or exists(
          select 1 from public.tgg_sound_library_favorites f
          where f.user_id=v_uid and f.sound_id=s.id
        )
      )
      and (
        nullif(btrim(coalesce(p_query,'')),'') is null
        or s.title ilike '%'||btrim(p_query)||'%'
        or s.source_provider ilike '%'||btrim(p_query)||'%'
        or s.license_name ilike '%'||btrim(p_query)||'%'
        or exists(select 1 from unnest(s.tags) t where t ilike '%'||btrim(p_query)||'%')
      )
    order by favorited desc,s.title
    limit v_limit
  ) x;

  select jsonb_build_object(
    'asset_types',coalesce((
      select jsonb_agg(asset_type order by asset_type)
      from (
        select distinct asset_type
        from public.tgg_sound_library_items
        where is_active=true and (owner_user_id is null or owner_user_id=v_uid)
      ) q
    ),'[]'::jsonb),
    'license_kinds',coalesce((
      select jsonb_agg(license_kind order by license_kind)
      from (
        select distinct license_kind
        from public.tgg_sound_library_items
        where is_active=true and (owner_user_id is null or owner_user_id=v_uid)
      ) q
    ),'[]'::jsonb),
    'source_providers',coalesce((
      select jsonb_agg(source_provider order by source_provider)
      from (
        select distinct source_provider
        from public.tgg_sound_library_items
        where is_active=true and (owner_user_id is null or owner_user_id=v_uid)
      ) q
    ),'[]'::jsonb),
    'keys',coalesce((
      select jsonb_agg(musical_key order by musical_key)
      from (
        select distinct musical_key
        from public.tgg_sound_library_items
        where is_active=true
          and musical_key is not null
          and (owner_user_id is null or owner_user_id=v_uid)
      ) q
    ),'[]'::jsonb)
  ) into v_facets;

  return jsonb_build_object(
    'ok',true,
    'version','SOUND-LIBRARY-CANONICAL-1.0',
    'items',v_items,
    'facets',v_facets,
    'filters',jsonb_build_object(
      'commercial_only',coalesce(p_commercial_only,false),
      'importable_only',coalesce(p_importable_only,true),
      'favorites_only',coalesce(p_favorites_only,false),
      'owned_only',coalesce(p_owned_only,false)
    ),
    'policy',jsonb_build_object(
      'copyrighted_scraping',false,
      'unverified_external_imports',false,
      'accepted_license_kinds',jsonb_build_array(
        'user_owned','public_domain','cc0','creative_commons','royalty_free','custom_reusable'
      )
    ),
    'generated_at',now()
  );
end;
$function$


-- [40000001247] function public.tgg_sound_library_search(p_query text, p_asset_type text, p_bpm_min numeric, p_bpm_max numeric, p_key text, p_limit integer)
CREATE OR REPLACE FUNCTION public.tgg_sound_library_search(p_query text DEFAULT NULL::text, p_asset_type text DEFAULT NULL::text, p_bpm_min numeric DEFAULT NULL::numeric, p_bpm_max numeric DEFAULT NULL::numeric, p_key text DEFAULT NULL::text, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_limit integer:=greatest(1,least(coalesce(p_limit,50),100));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

      return coalesce((
        select jsonb_agg(to_jsonb(x) order by x.title)
        from (
          select
            s.id,s.title,s.asset_type,s.bpm,s.musical_key,s.tags,s.duration_seconds,
            s.preview_url,s.source_provider,s.source_item_url,
            s.license_name,s.license_url,s.license_kind,
            s.commercial_use_allowed,s.attribution_required,s.attribution_text,s.import_allowed,
            exists(
              select 1 from public.tgg_sound_library_favorites f
              where f.user_id=v_uid and f.sound_id=s.id
            ) as favorited
          from public.tgg_sound_library_items s
          where s.is_active=true
            and (p_asset_type is null or s.asset_type=p_asset_type)
            and (p_bpm_min is null or s.bpm>=p_bpm_min)
            and (p_bpm_max is null or s.bpm<=p_bpm_max)
            and (p_key is null or lower(coalesce(s.musical_key,''))=lower(p_key))
            and (
              nullif(btrim(coalesce(p_query,'')),'') is null
              or s.title ilike '%'||btrim(p_query)||'%'
              or s.source_provider ilike '%'||btrim(p_query)||'%'
              or exists(select 1 from unnest(s.tags) t where t ilike '%'||btrim(p_query)||'%')
            )
          order by s.title
          limit v_limit
        ) x
      ),'[]'::jsonb);
    end;
    $function$


-- [40000001248] function public.tgg_sound_library_toggle_favorite(p_sound_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_sound_library_toggle_favorite(p_sound_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_now_favorite boolean;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if not exists(select 1 from public.tgg_sound_library_items where id=p_sound_id and is_active=true) then
        raise exception 'SOUND_NOT_FOUND';
      end if;

      if exists(select 1 from public.tgg_sound_library_favorites where user_id=v_uid and sound_id=p_sound_id) then
        delete from public.tgg_sound_library_favorites
        where user_id=v_uid and sound_id=p_sound_id;
        v_now_favorite:=false;
      else
        insert into public.tgg_sound_library_favorites(user_id,sound_id)
        values(v_uid,p_sound_id);
        v_now_favorite:=true;
      end if;

      return jsonb_build_object('ok',true,'sound_id',p_sound_id,'favorited',v_now_favorite);
    end;
    $function$


-- [40000001249] function public.tgg_speed_booster_effective_batch_size()
CREATE OR REPLACE FUNCTION public.tgg_speed_booster_effective_batch_size()
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select greatest(1,least(25,(public.tgg_speed_booster_state()->>'effective_batch_size')::integer))
$function$


-- [40000001250] function public.tgg_speed_booster_layer_plan()
CREATE OR REPLACE FUNCTION public.tgg_speed_booster_layer_plan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_speed jsonb;
begin
  v_speed := public.tgg_speed_booster_state();

  return jsonb_build_object(
    'speed',v_speed,
    'layers',coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'layer_no',layer_no,
          'layer_key',layer_key,
          'title',title,
          'max_items',case
            when layer_key='build' then least(max_items,(v_speed->>'effective_batch_size')::integer)
            else max_items
          end,
          'parallel_safe',parallel_safe,
          'requires_previous_layer',requires_previous_layer,
          'work_types',work_types,
          'notes',notes
        )
        order by layer_no
      )
      from public.tgg_speed_booster_layers
    ),'[]'::jsonb),
    'production_auto_publish',false,
    'high_risk_auto_execute',false,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end $function$


-- [40000001251] function public.tgg_speed_booster_state()
CREATE OR REPLACE FUNCTION public.tgg_speed_booster_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cfg public.tgg_speed_booster_config%rowtype;
  v_score jsonb;
  v_arch jsonb;
  v_conflicts jsonb;
  v_trace jsonb;
  v_safety numeric := 0;
  v_arch_clean boolean := false;
  v_conflict_clean boolean := false;
  v_trace_clean boolean := false;
  v_boost_allowed boolean := false;
  v_effective integer := 5;
  v_reason text := 'normal_mode';
begin
  select * into v_cfg from public.tgg_speed_booster_config where id=1;
  if not found then raise exception 'speed_booster_config_missing'; end if;

  v_score := public.tgg_brain_latest_scorecard();
  v_arch := public.tgg_brain_architecture_latest();
  v_conflicts := public.tgg_brain_conflict_state();
  v_trace := public.tgg_brain_execution_trace_state();

  v_safety := coalesce((v_score->>'safety_score')::numeric,0);

  v_arch_clean :=
    coalesce(v_arch->>'drift_status','warning') <> 'warning'
    and coalesce((v_arch->>'stale_components')::integer,0)=0
    and coalesce((v_arch->>'missing_since_previous')::integer,0)=0;

  v_conflict_clean :=
    coalesce((v_conflicts->>'critical_open')::integer,0)=0
    and coalesce((v_conflicts->>'blocked_open')::integer,0)=0;

  v_trace_clean :=
    coalesce((v_trace->>'production_touched')::integer,0)=0
    and coalesce((v_trace->>'high_risk_executed')::integer,0)=0
    and coalesce((v_trace->>'boundary_violations')::integer,0)=0;

  v_boost_allowed :=
    v_cfg.enabled
    and v_safety >= v_cfg.require_safety_score
    and (not v_cfg.require_clean_architecture or v_arch_clean)
    and (not v_cfg.require_zero_critical_conflicts or v_conflict_clean)
    and (not v_cfg.require_clean_execution_trace or v_trace_clean);

  if not v_cfg.enabled then
    v_effective := v_cfg.normal_batch_size;
    v_reason := 'booster_disabled';
  elsif v_cfg.mode='normal' then
    v_effective := v_cfg.normal_batch_size;
    v_reason := 'forced_normal';
  elsif v_cfg.mode='boosted' and v_boost_allowed then
    v_effective := least(v_cfg.boosted_batch_size,v_cfg.hard_max_batch_size);
    v_reason := 'forced_boosted_healthy';
  elsif v_cfg.mode='adaptive' and v_boost_allowed then
    v_effective := least(v_cfg.boosted_batch_size,v_cfg.hard_max_batch_size);
    v_reason := 'adaptive_boost_healthy';
  else
    v_effective := v_cfg.normal_batch_size;
    v_reason := 'health_gate_throttle';
  end if;

  return jsonb_build_object(
    'enabled',v_cfg.enabled,
    'mode',v_cfg.mode,
    'normal_batch_size',v_cfg.normal_batch_size,
    'boosted_batch_size',v_cfg.boosted_batch_size,
    'hard_max_batch_size',v_cfg.hard_max_batch_size,
    'effective_batch_size',v_effective,
    'boost_allowed',v_boost_allowed,
    'reason',v_reason,
    'health',jsonb_build_object(
      'safety_score',v_safety,
      'architecture_clean',v_arch_clean,
      'conflicts_clean',v_conflict_clean,
      'execution_trace_clean',v_trace_clean
    ),
    'production_auto_publish',false,
    'high_risk_auto_execute',false,
    'canonical_boundary','AB-006',
    'canonical_source_version','V223'
  );
end $function$


-- [40000001252] function public.tgg_start_call_room(p_conversation_id uuid, p_room_type text)
CREATE OR REPLACE FUNCTION public.tgg_start_call_room(p_conversation_id uuid, p_room_type text DEFAULT 'video'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_room uuid;
  v_type text := lower(btrim(coalesce(p_room_type,'video')));
  v_member_count int := 0;
  v_recipient uuid;
  v_availability text := 'available';
  v_caller_artist uuid;
  v_block_reason text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_type not in ('audio','video','listening','studio','drop') then raise exception 'ROOM_TYPE_INVALID' using errcode='22023'; end if;
  if not exists(select 1 from public.tgg_conversation_members m where m.conversation_id=p_conversation_id and m.user_id=v_uid) then
    raise exception 'CONVERSATION_ACCESS_DENIED' using errcode='42501';
  end if;

  if v_type in ('audio','video') then
    select count(*), max(m.user_id) filter (where m.user_id<>v_uid)
      into v_member_count, v_recipient
    from public.tgg_conversation_members m
    where m.conversation_id=p_conversation_id;

    if v_member_count=2 and v_recipient is not null then
      select lower(coalesce(nullif(btrim(s.preferences->>'call_availability'),''),'available'))
        into v_availability
      from public.tgg_world_phone_state s
      where s.user_id=v_recipient;
      v_availability:=coalesce(v_availability,'available');

      if v_availability in ('busy','dnd') then
        v_block_reason:='unavailable';
      elsif v_availability='favorites_only' then
        select a.id into v_caller_artist
        from public.artists a
        where a.user_id=v_uid
        order by a.created_at asc
        limit 1;
        if v_caller_artist is null or not exists(
          select 1 from public.tgg_phone_favorites f
          where f.user_id=v_recipient and f.artist_id=v_caller_artist
        ) then
          v_block_reason:='favorites_only';
        end if;
      end if;

      if v_block_reason is not null then
        delete from public.tgg_conversations c
        where c.id=p_conversation_id
          and c.created_by=v_uid
          and c.project_type='dm'
          and coalesce(c.title,'')='WORLD Call'
          and c.last_message_at is null
          and c.created_at >= now()-interval '30 seconds'
          and not exists(select 1 from public.tgg_messages x where x.conversation_id=c.id)
          and not exists(select 1 from public.tgg_call_rooms x where x.conversation_id=c.id);

        perform private.tgg_creator_mutation_audit_log(
          'calls.room_blocked',p_conversation_id::text,
          jsonb_build_object('room_type',v_type,'reason',v_block_reason)
        );
        return null;
      end if;
    end if;
  end if;

  perform private.tgg_creator_rate_limit_gate('calls.room_start.rpc',60,600);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_conversation_id::text||':'||v_type,0));

  select r.id into v_room
  from public.tgg_call_rooms r
  where r.conversation_id=p_conversation_id and r.room_type=v_type and r.status='active' and r.ended_at is null
  order by r.created_at desc limit 1;

  if v_room is null then
    insert into public.tgg_call_rooms(created_by,conversation_id,title,room_type,status,is_group,created_at)
    select v_uid,p_conversation_id,coalesce(nullif(btrim(c.title),''),'TGG Room'),v_type,'active',
      (select count(*)>2 from public.tgg_conversation_members m where m.conversation_id=p_conversation_id),now()
    from public.tgg_conversations c where c.id=p_conversation_id
    returning id into v_room;
    if v_room is null then raise exception 'CONVERSATION_NOT_FOUND'; end if;
  end if;

  insert into public.tgg_call_participants(room_id,user_id,mic_enabled,camera_enabled,joined_at,left_at)
  select v_room,m.user_id,true,(v_type<>'audio'),now(),null
  from public.tgg_conversation_members m where m.conversation_id=p_conversation_id
  on conflict(room_id,user_id) do update
  set left_at=null,mic_enabled=true,camera_enabled=(v_type<>'audio'),
      joined_at=case when public.tgg_call_participants.left_at is not null then now() else public.tgg_call_participants.joined_at end;

  perform private.tgg_creator_mutation_audit_log(
    'calls.room_start',v_room::text,
    jsonb_build_object('conversation_id',p_conversation_id,'room_type',v_type,'participant_count',(
      select count(*) from public.tgg_call_participants p where p.room_id=v_room and p.left_at is null
    ))
  );
  return v_room;
end;
$function$


-- [40000001253] function public.tgg_start_encounter(p_character_id uuid, p_encounter_key text)
CREATE OR REPLACE FUNCTION public.tgg_start_encounter(p_character_id uuid, p_encounter_key text)
