-- [40000001254] function public.tgg_storage_security_readiness()
CREATE OR REPLACE FUNCTION public.tgg_storage_security_readiness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'storage'
AS $function$
with buckets as (
  select
    count(*) filter(where id in ('creator-media','mixtape-audio','videos','v98-blogger-backups','audio') and public=false) private_ok,
    count(*) filter(where id in ('creator-media','mixtape-audio','videos','v98-blogger-backups','audio')) private_expected,
    count(*) filter(where id in ('artist-images','covers','media-thumbnails') and public=true) public_ok,
    count(*) filter(where id in ('artist-images','covers','media-thumbnails')) public_expected
  from storage.buckets
),
policies as (
  select
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='creator media select own') creator_media_select,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='creator media insert own') creator_media_insert,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='creator media update own') creator_media_update,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='creator media delete own') creator_media_delete,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='creator media conversation member read') conversation_read,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='creator media vault member read') vault_read,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='mixtape audio owner read') mixtape_read,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='mixtape audio owner upload') mixtape_insert,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='mixtape audio owner update') mixtape_update,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='tgg videos owner select') videos_select,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='tgg videos owner upload') videos_insert,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='tgg videos owner update') videos_update,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='tgg audio owner read') audio_read,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='tgg audio owner upload') audio_insert,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='tgg audio owner update') audio_update,
    exists(select 1 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='storage' and c.relname='objects' and p.polname='tgg audio owner delete') audio_delete
),
objects as (
  select c.relrowsecurity rls_enabled
  from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='storage' and c.relname='objects'
),
calc as (
  select *,
    (creator_media_select and creator_media_insert and creator_media_update and creator_media_delete) creator_media_owner_complete,
    (creator_media_select and creator_media_insert and creator_media_update) creator_media_upsert_ready,
    (mixtape_read and mixtape_insert and mixtape_update) mixtape_upsert_ready,
    (videos_select and videos_insert and videos_update) videos_upsert_ready,
    (audio_read and audio_insert and audio_update and audio_delete) audio_owner_complete
  from buckets cross join policies cross join objects
)
select jsonb_build_object(
  'ok',
    rls_enabled
    and private_ok=private_expected
    and public_ok=public_expected
    and creator_media_owner_complete
    and creator_media_upsert_ready
    and conversation_read
    and vault_read
    and mixtape_upsert_ready
    and videos_upsert_ready
    and audio_owner_complete,
  'version','STORAGE-SECURITY-1.1',
  'objects_rls_enabled',rls_enabled,
  'bucket_classification',jsonb_build_object(
    'private_ready',private_ok,'private_total',private_expected,
    'public_ready',public_ok,'public_total',public_expected
  ),
  'audio',jsonb_build_object(
    'private_bucket',exists(select 1 from storage.buckets where id='audio' and public=false),
    'owner_policy_complete',audio_owner_complete,
    'public_release_refs',0,
    'approved_security_tightening',true
  ),
  'creator_media',jsonb_build_object(
    'owner_policy_complete',creator_media_owner_complete,
    'upsert_ready',creator_media_upsert_ready,
    'conversation_member_read',conversation_read,
    'vault_member_read',vault_read
  ),
  'mixtape_audio',jsonb_build_object('upsert_ready',mixtape_upsert_ready),
  'videos',jsonb_build_object('upsert_ready',videos_upsert_ready),
  'blogger_backups',jsonb_build_object(
    'private_bucket',exists(select 1 from storage.buckets where id='v98-blogger-backups' and public=false),
    'client_policy_expected',false
  ),
  'generated_at',now()
)
from calc;
$function$


-- [40000001255] function public.tgg_store_product_create(p_title text, p_description text, p_product_type text, p_price_cents integer, p_currency text, p_sku text, p_inventory integer, p_image_url text)
CREATE OR REPLACE FUNCTION public.tgg_store_product_create(p_title text, p_description text DEFAULT NULL::text, p_product_type text DEFAULT 'physical'::text, p_price_cents integer DEFAULT 0, p_currency text DEFAULT 'USD'::text, p_sku text DEFAULT NULL::text, p_inventory integer DEFAULT NULL::integer, p_image_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_artist uuid;v_id uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist from public.artists where user_id=v_uid limit 1;
      if v_artist is null then raise exception 'ARTIST_PROFILE_REQUIRED'; end if;
      if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'TITLE_REQUIRED'; end if;
      insert into public.merch_products(
        creator_id,user_id,title,description,product_type,price_cents,currency,sku,inventory,image_url,status
      ) values(
        v_artist,v_uid,left(btrim(p_title),160),nullif(btrim(coalesce(p_description,'')),''),
        coalesce(nullif(btrim(coalesce(p_product_type,'')),''),'physical'),
        greatest(coalesce(p_price_cents,0),0),upper(coalesce(nullif(btrim(coalesce(p_currency,'')),''),'USD')),
        nullif(btrim(coalesce(p_sku,'')),''),p_inventory,nullif(btrim(coalesce(p_image_url,'')),''),'draft'
      ) returning id into v_id;
      return jsonb_build_object('ok',true,'product_id',v_id,'status','draft');
    end $function$


-- [40000001256] function public.tgg_store_product_delete(p_product_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_store_product_delete(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_artist uuid;v_deleted uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist from public.artists where user_id=v_uid limit 1;
      delete from public.merch_products
      where id=p_product_id and creator_id=v_artist and status in ('draft','changes_requested')
      returning id into v_deleted;
      if v_deleted is null then raise exception 'PRODUCT_NOT_DELETABLE'; end if;
      return jsonb_build_object('ok',true,'product_id',v_deleted,'deleted',true);
    end $function$


-- [40000001257] function public.tgg_store_product_set_payment_link(p_product_id uuid, p_payment_link_url text)
CREATE OR REPLACE FUNCTION public.tgg_store_product_set_payment_link(p_product_id uuid, p_payment_link_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_url text;
  v_row public.merch_products;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if not coalesce(private.is_admin(),false) then
    raise exception 'ADMIN_REQUIRED' using errcode='42501';
  end if;

  v_url:=nullif(btrim(coalesce(p_payment_link_url,'')),'');

  if v_url is not null
     and v_url !~ '^https://buy\.stripe\.com/'
  then
    raise exception 'INVALID_STRIPE_PAYMENT_LINK';
  end if;

  update public.merch_products
  set stripe_payment_link_url=v_url,
      updated_at=now()
  where id=p_product_id
  returning * into v_row;

  if v_row.id is null then
    raise exception 'PRODUCT_NOT_FOUND';
  end if;

  return jsonb_build_object(
    'ok',true,
    'product_id',v_row.id,
    'stripe_payment_link_url',v_row.stripe_payment_link_url,
    'status',v_row.status
  );
end
$function$


-- [40000001258] function public.tgg_store_product_update(p_product_id uuid, p_title text, p_description text, p_product_type text, p_price_cents integer, p_currency text, p_sku text, p_inventory integer, p_image_url text)
CREATE OR REPLACE FUNCTION public.tgg_store_product_update(p_product_id uuid, p_title text, p_description text, p_product_type text, p_price_cents integer, p_currency text, p_sku text, p_inventory integer, p_image_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_artist uuid;v_row public.merch_products;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist from public.artists where user_id=v_uid limit 1;
      if v_artist is null then raise exception 'ARTIST_PROFILE_REQUIRED'; end if;
      update public.merch_products set
        title=left(btrim(coalesce(p_title,'')),160),
        description=nullif(btrim(coalesce(p_description,'')),''),
        product_type=coalesce(nullif(btrim(coalesce(p_product_type,'')),''),'physical'),
        price_cents=greatest(coalesce(p_price_cents,0),0),
        currency=upper(coalesce(nullif(btrim(coalesce(p_currency,'')),''),'USD')),
        sku=nullif(btrim(coalesce(p_sku,'')),''),
        inventory=p_inventory,
        image_url=nullif(btrim(coalesce(p_image_url,'')),''),
        updated_at=now()
      where id=p_product_id and creator_id=v_artist
      returning * into v_row;
      if v_row.id is null then raise exception 'PRODUCT_NOT_FOUND_OR_NOT_OWNED'; end if;
      return jsonb_build_object('ok',true,'product_id',v_row.id,'status',v_row.status);
    end $function$


