-- [40000001260] function public.tgg_story_create(p_story_type text, p_caption text, p_media_url text, p_linked_release_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_story_create(p_story_type text DEFAULT 'text'::text, p_caption text DEFAULT NULL::text, p_media_url text DEFAULT NULL::text, p_linked_release_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_id uuid;
  v_type text:=lower(coalesce(nullif(btrim(coalesce(p_story_type,'')),''),'text'));
  v_caption text:=nullif(btrim(coalesce(p_caption,'')),'');
  v_media text:=nullif(btrim(coalesce(p_media_url,'')),'');
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_type not in ('text','image','video','audio','studio','collab','release') then
    raise exception 'STORY_TYPE_INVALID';
  end if;
  if v_caption is not null and char_length(v_caption)>2000 then
    raise exception 'CAPTION_TOO_LONG';
  end if;
  if v_media is not null and v_media !~* '^https://' then
    raise exception 'MEDIA_URL_HTTPS_REQUIRED';
  end if;
  if v_type in ('image','video','audio') and v_media is null then
    raise exception 'MEDIA_URL_REQUIRED';
  end if;
  if p_linked_release_id is not null and not exists(
    select 1
    from public.mixtapes m
    where m.id=p_linked_release_id
      and m.status='published'::public.mixtape_status
  ) then
    raise exception 'LINKED_RELEASE_MUST_BE_PUBLISHED';
  end if;

  insert into public.tgg_stories(
    user_id,story_type,caption,media_url,linked_release_id,created_at,expires_at
  )
  values(
    v_uid,v_type,v_caption,v_media,p_linked_release_id,now(),now()+interval '24 hours'
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,
    'story_id',v_id,
    'expires_at',now()+interval '24 hours'
  );
end
$function$


-- [40000001261] function public.tgg_story_delete(p_story_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_story_delete(p_story_id uuid)
 RETURNS jsonb
