      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      delete from public.tgg_stories where id=p_story_id and user_id=v_uid returning id into v_id;
      if v_id is null then raise exception 'STORY_NOT_FOUND_OR_NOT_OWNED'; end if;
      return jsonb_build_object('ok',true,'story_id',v_id,'deleted',true);
    end $function$


