-- [40000001267] function public.tgg_studio_create_project(p_title text, p_project_type text, p_bpm numeric, p_musical_key text, p_description text)
CREATE OR REPLACE FUNCTION public.tgg_studio_create_project(p_title text, p_project_type text DEFAULT 'recording'::text, p_bpm numeric DEFAULT 120, p_musical_key text DEFAULT NULL::text, p_description text DEFAULT NULL::text)
 RETURNS public.tgg_studio_projects
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v public.tgg_studio_projects;
      v_type text:=lower(btrim(coalesce(p_project_type,'recording')));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if char_length(btrim(coalesce(p_title,''))) < 1 or char_length(btrim(coalesce(p_title,''))) > 160 then
        raise exception 'TITLE_INVALID';
      end if;
      if v_type not in ('beat','recording','mix','master','podcast','audiobook') then
        raise exception 'PROJECT_TYPE_INVALID';
      end if;
      if p_bpm is not null and (p_bpm < 20 or p_bpm > 400) then
        raise exception 'BPM_INVALID';
      end if;

      insert into public.tgg_studio_projects(
        user_id,title,bpm,musical_key,status,project_data,project_type,description
      )
      values(
        v_uid,btrim(p_title),coalesce(p_bpm,120),
        nullif(btrim(coalesce(p_musical_key,'')),''),
        case when v_type='recording' then 'recording' else 'draft' end,
        '{}'::jsonb,v_type,nullif(btrim(coalesce(p_description,'')),'')
      )
      returning * into v;

      return v;
    end;
    $function$


