-- [40000001272] function public.tgg_studio_project_collab_invite(p_project_id uuid, p_recipient_id uuid, p_role text, p_note text)
CREATE OR REPLACE FUNCTION public.tgg_studio_project_collab_invite(p_project_id uuid, p_recipient_id uuid, p_role text DEFAULT 'editor'::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_recipient uuid;
      v_project public.tgg_studio_projects;
      v_request uuid;
      v_role text:=lower(btrim(coalesce(p_role,'editor')));
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select * into v_project from public.tgg_studio_projects where id=p_project_id and user_id=v_uid;
      if v_project.id is null then raise exception 'PROJECT_NOT_FOUND_OR_NOT_OWNED'; end if;
      if v_role not in ('editor','performer','viewer') then raise exception 'ROLE_INVALID'; end if;

      select a.user_id into v_recipient
      from public.public_artist_directory_v1 a
      where a.artist_id=p_recipient_id or a.user_id=p_recipient_id
      limit 1;

      if v_recipient is null or v_recipient=v_uid then raise exception 'RECIPIENT_INVALID'; end if;

      insert into public.tgg_collaboration_requests(
        sender_id,recipient_id,project_title,project_type,note,status,studio_project_id
      )
      values(
        v_uid,v_recipient,v_project.title,v_project.project_type,
        jsonb_build_object('role',v_role,'note',p_note)::text,'pending',v_project.id
      )
      returning id into v_request;

      update public.tgg_studio_projects
      set collaboration_enabled=true,updated_at=now()
      where id=v_project.id;

      return jsonb_build_object('ok',true,'request_id',v_request,'project_id',v_project.id,'role',v_role);
    end;
    $function$


