-- [40000001291] function public.tgg_toggle_collection_item(p_collection_id uuid, p_mixtape_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_toggle_collection_item(p_collection_id uuid, p_mixtape_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare v_user uuid:=auth.uid(); begin if v_user is null then raise exception 'authentication required'; end if; if not exists(select 1 from public.fan_collections c where c.id=p_collection_id and c.user_id=v_user) then raise exception 'collection unavailable'; end if; if not exists(select 1 from public.mixtapes m where m.id=p_mixtape_id and m.status='published') then raise exception 'release unavailable'; end if; if exists(select 1 from public.fan_collection_items i where i.collection_id=p_collection_id and i.mixtape_id=p_mixtape_id) then delete from public.fan_collection_items where collection_id=p_collection_id and mixtape_id=p_mixtape_id; return false; end if; insert into public.fan_collection_items(collection_id,mixtape_id) values(p_collection_id,p_mixtape_id); return true; end $function$


-- [40000001292] function public.tgg_toggle_message_reaction(p_message_id uuid, p_reaction text)
CREATE OR REPLACE FUNCTION public.tgg_toggle_message_reaction(p_message_id uuid, p_reaction text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid(); v_reaction text:=btrim(coalesce(p_reaction,''));
begin
 if v_user is null then raise exception 'authentication required'; end if;
 if char_length(v_reaction)<1 or char_length(v_reaction)>32 then raise exception 'invalid reaction'; end if;
 if not exists(select 1 from public.tgg_messages m join public.tgg_conversation_members cm on cm.conversation_id=m.conversation_id and cm.user_id=v_user where m.id=p_message_id) then raise exception 'message unavailable'; end if;
 delete from public.tgg_message_reactions where message_id=p_message_id and user_id=v_user and reaction=v_reaction;
 if found then return false; end if;
 insert into public.tgg_message_reactions(message_id,user_id,reaction) values(p_message_id,v_user,v_reaction); return true;
end $function$


