-- [40000001297] function public.tgg_tv_channel_create(p_title text, p_description text, p_artwork_url text, p_banner_url text, p_slug text)
CREATE OR REPLACE FUNCTION public.tgg_tv_channel_create(p_title text, p_description text DEFAULT NULL::text, p_artwork_url text DEFAULT NULL::text, p_banner_url text DEFAULT NULL::text, p_slug text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_artist uuid;v_slug text;v_id uuid;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'TITLE_REQUIRED'; end if;
 select id into v_artist from public.artists where user_id=v_uid limit 1;
 v_slug:=lower(regexp_replace(coalesce(nullif(btrim(p_slug),''),btrim(p_title)),'[^a-zA-Z0-9]+','-','g'));
 v_slug:=trim(both '-' from v_slug);
 if char_length(v_slug)<2 then v_slug:='tv-'||left(replace(gen_random_uuid()::text,'-',''),8); end if;
 if exists(select 1 from public.tgg_tv_channels where slug=v_slug) then v_slug:=left(v_slug,100)||'-'||left(replace(gen_random_uuid()::text,'-',''),6); end if;
 insert into public.tgg_tv_channels(owner_user_id,artist_id,title,description,artwork_url,banner_url,slug)
 values(v_uid,v_artist,left(btrim(p_title),160),nullif(btrim(coalesce(p_description,'')),''),nullif(btrim(coalesce(p_artwork_url,'')),''),nullif(btrim(coalesce(p_banner_url,'')),''),v_slug)
 returning id into v_id;
 return jsonb_build_object('ok',true,'channel_id',v_id,'slug',v_slug);
end $function$


-- [40000001298] function public.tgg_tv_channel_delete(p_channel_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_tv_channel_delete(p_channel_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  delete from public.tgg_tv_channels
  where id=p_channel_id and owner_user_id=v_uid and status='draft'
  returning id into v_id;
  if v_id is null then raise exception 'CHANNEL_NOT_DELETABLE'; end if;
  return jsonb_build_object('ok',true,'channel_id',v_id,'deleted',true);
end $function$


-- [40000001299] function public.tgg_tv_channel_set_published(p_channel_id uuid, p_published boolean)
CREATE OR REPLACE FUNCTION public.tgg_tv_channel_set_published(p_channel_id uuid, p_published boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_status text:=case when p_published then 'published' else 'draft' end;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 update public.tgg_tv_channels
 set status=v_status,published_at=case when p_published then coalesce(published_at,now()) else null end,updated_at=now()
 where id=p_channel_id and owner_user_id=v_uid
 returning id into v_id;
 if v_id is null then raise exception 'CHANNEL_NOT_FOUND_OR_NOT_OWNED'; end if;
 return jsonb_build_object('ok',true,'channel_id',v_id,'status',v_status);
end $function$


-- [40000001300] function public.tgg_tv_channel_update(p_channel_id uuid, p_title text, p_description text, p_artwork_url text, p_banner_url text)
CREATE OR REPLACE FUNCTION public.tgg_tv_channel_update(p_channel_id uuid, p_title text, p_description text, p_artwork_url text, p_banner_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'TITLE_REQUIRED'; end if;
  update public.tgg_tv_channels
  set title=left(btrim(p_title),160),
      description=nullif(btrim(coalesce(p_description,'')),''),
      artwork_url=nullif(btrim(coalesce(p_artwork_url,'')),''),
      banner_url=nullif(btrim(coalesce(p_banner_url,'')),''),
      updated_at=now()
  where id=p_channel_id and owner_user_id=v_uid
  returning id into v_id;
  if v_id is null then raise exception 'CHANNEL_NOT_FOUND_OR_NOT_OWNED'; end if;
  return jsonb_build_object('ok',true,'channel_id',v_id);
end $function$


-- [40000001301] function public.tgg_tv_episode_create(p_channel_id uuid, p_title text, p_description text, p_episode_type text, p_video_url text, p_thumbnail_url text, p_duration_seconds integer, p_season_number integer, p_episode_number integer, p_source_video_id uuid, p_source_live_replay_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_tv_episode_create(p_channel_id uuid, p_title text, p_description text, p_episode_type text, p_video_url text, p_thumbnail_url text, p_duration_seconds integer, p_season_number integer, p_episode_number integer, p_source_video_id uuid DEFAULT NULL::uuid, p_source_live_replay_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_artist uuid;v_id uuid;v_type text:=lower(btrim(coalesce(p_episode_type,'show')));
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if v_type not in ('show','interview','documentary','behind_the_scenes','live_replay','music_video','podcast_video','series_episode','special') then raise exception 'EPISODE_TYPE_INVALID'; end if;
 if not exists(select 1 from public.tgg_tv_channels c where c.id=p_channel_id and c.owner_user_id=v_uid) then raise exception 'CHANNEL_NOT_FOUND_OR_NOT_OWNED'; end if;
 if coalesce(p_video_url,'') !~* '^https?://' then raise exception 'VIDEO_URL_INVALID'; end if;
 select id into v_artist from public.artists where user_id=v_uid limit 1;
 if p_source_video_id is not null and not exists(select 1 from public.videos v where v.id=p_source_video_id and v.artist_id=v_artist) then raise exception 'SOURCE_VIDEO_NOT_OWNED'; end if;
 if p_source_live_replay_id is not null and not exists(select 1 from public.tgg_live_replays r where r.id=p_source_live_replay_id and r.creator_id=v_uid) then raise exception 'SOURCE_REPLAY_NOT_OWNED'; end if;
 insert into public.tgg_tv_episodes(channel_id,owner_user_id,artist_id,title,description,episode_type,video_url,thumbnail_url,duration_seconds,season_number,episode_number,source_video_id,source_live_replay_id)
 values(p_channel_id,v_uid,v_artist,left(btrim(p_title),200),nullif(btrim(coalesce(p_description,'')),''),v_type,btrim(p_video_url),nullif(btrim(coalesce(p_thumbnail_url,'')),''),p_duration_seconds,p_season_number,p_episode_number,p_source_video_id,p_source_live_replay_id)
 returning id into v_id;
 return jsonb_build_object('ok',true,'episode_id',v_id,'status','draft');
end $function$


-- [40000001302] function public.tgg_tv_episode_delete(p_episode_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_tv_episode_delete(p_episode_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  delete from public.tgg_tv_episodes
  where id=p_episode_id and owner_user_id=v_uid and status in ('draft','rejected')
  returning id into v_id;
  if v_id is null then raise exception 'EPISODE_NOT_DELETABLE'; end if;
  return jsonb_build_object('ok',true,'episode_id',v_id,'deleted',true);
end $function$


-- [40000001303] function public.tgg_tv_episode_submit(p_episode_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_tv_episode_submit(p_episode_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 update public.tgg_tv_episodes set status='pending',admin_note=null,updated_at=now()
 where id=p_episode_id and owner_user_id=v_uid and status in ('draft','rejected')
 returning id into v_id;
 if v_id is null then raise exception 'EPISODE_NOT_SUBMITTABLE'; end if;
 return jsonb_build_object('ok',true,'episode_id',v_id,'status','pending');
end $function$


-- [40000001304] function public.tgg_tv_episode_update(p_episode_id uuid, p_title text, p_description text, p_episode_type text, p_video_url text, p_thumbnail_url text, p_duration_seconds integer, p_season_number integer, p_episode_number integer)
CREATE OR REPLACE FUNCTION public.tgg_tv_episode_update(p_episode_id uuid, p_title text, p_description text, p_episode_type text, p_video_url text, p_thumbnail_url text, p_duration_seconds integer, p_season_number integer, p_episode_number integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_type text:=lower(btrim(coalesce(p_episode_type,'show')));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_type not in ('show','interview','documentary','behind_the_scenes','live_replay','music_video','podcast_video','series_episode','special') then raise exception 'EPISODE_TYPE_INVALID'; end if;
  if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'TITLE_REQUIRED'; end if;
  if coalesce(p_video_url,'') !~* '^https?://' then raise exception 'VIDEO_URL_INVALID'; end if;

  update public.tgg_tv_episodes
  set title=left(btrim(p_title),200),
      description=nullif(btrim(coalesce(p_description,'')),''),
      episode_type=v_type,
      video_url=btrim(p_video_url),
      thumbnail_url=nullif(btrim(coalesce(p_thumbnail_url,'')),''),
      duration_seconds=p_duration_seconds,
      season_number=p_season_number,
      episode_number=p_episode_number,
      status=case when status='rejected' then 'draft' else status end,
      admin_note=case when status='rejected' then null else admin_note end,
      updated_at=now()
  where id=p_episode_id and owner_user_id=v_uid and status in ('draft','rejected')
  returning id into v_id;

  if v_id is null then raise exception 'EPISODE_NOT_EDITABLE'; end if;
  return jsonb_build_object('ok',true,'episode_id',v_id,'status','draft');
end $function$


-- [40000001305] function public.tgg_tv_watch_progress(p_episode_id uuid, p_position_seconds integer, p_completed boolean)
CREATE OR REPLACE FUNCTION public.tgg_tv_watch_progress(p_episode_id uuid, p_position_seconds integer, p_completed boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_position_seconds<0 then raise exception 'POSITION_INVALID'; end if;
 if not exists(select 1 from public.tgg_tv_episodes where id=p_episode_id and status='published' and visibility in ('public','unlisted')) then raise exception 'EPISODE_UNAVAILABLE'; end if;
 insert into public.tgg_tv_watch_history(user_id,episode_id,position_seconds,completed,last_watched_at)
 values(v_uid,p_episode_id,p_position_seconds,coalesce(p_completed,false),now())
 on conflict(user_id,episode_id) do update set position_seconds=excluded.position_seconds,completed=excluded.completed,last_watched_at=now();
 return jsonb_build_object('ok',true,'episode_id',p_episode_id,'position_seconds',p_position_seconds,'completed',coalesce(p_completed,false));
end $function$


-- [40000001306] function public.tgg_tv_watchlist_toggle(p_episode_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_tv_watchlist_toggle(p_episode_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid();v_added boolean;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from public.tgg_tv_episodes where id=p_episode_id and status='published' and visibility in ('public','unlisted')) then raise exception 'EPISODE_UNAVAILABLE'; end if;
 if exists(select 1 from public.tgg_tv_watchlist where user_id=v_uid and episode_id=p_episode_id) then
   delete from public.tgg_tv_watchlist where user_id=v_uid and episode_id=p_episode_id; v_added:=false;
 else
   insert into public.tgg_tv_watchlist(user_id,episode_id) values(v_uid,p_episode_id); v_added:=true;
 end if;
 return jsonb_build_object('ok',true,'episode_id',p_episode_id,'in_watchlist',v_added);
end $function$


