-- [40000001308] function public.tgg_update_creator_profile(p_stage_name text, p_bio text, p_avatar_url text, p_instagram text, p_website text, p_youtube text, p_soundcloud text, p_spotify text)
CREATE OR REPLACE FUNCTION public.tgg_update_creator_profile(p_stage_name text, p_bio text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text, p_instagram text DEFAULT NULL::text, p_website text DEFAULT NULL::text, p_youtube text DEFAULT NULL::text, p_soundcloud text DEFAULT NULL::text, p_spotify text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare
      v_uid uuid:=auth.uid();
      v_name text:=btrim(coalesce(p_stage_name,''));
      v_artist public.artists;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      if char_length(v_name)<2 or char_length(v_name)>80 then raise exception 'STAGE_NAME_INVALID'; end if;

      if exists(
        select 1 from public.artists
        where lower(stage_name)=lower(v_name)
          and user_id<>v_uid
      ) then
        raise exception 'STAGE_NAME_TAKEN';
      end if;

      update public.artists
      set stage_name=v_name,
          bio=nullif(btrim(coalesce(p_bio,'')),''),
          avatar_url=nullif(btrim(coalesce(p_avatar_url,'')),''),
          instagram=nullif(btrim(coalesce(p_instagram,'')),''),
          website=nullif(btrim(coalesce(p_website,'')),''),
          youtube=nullif(btrim(coalesce(p_youtube,'')),''),
          soundcloud=nullif(btrim(coalesce(p_soundcloud,'')),''),
          spotify=nullif(btrim(coalesce(p_spotify,'')),'')
      where user_id=v_uid
      returning * into v_artist;

      if v_artist.id is null then raise exception 'CREATOR_PROFILE_REQUIRED'; end if;

      return jsonb_build_object(
        'ok',true,
        'artist_id',v_artist.id,
        'stage_name',v_artist.stage_name,
        'bio',v_artist.bio,
        'avatar_url',v_artist.avatar_url,
        'instagram',v_artist.instagram,
        'website',v_artist.website,
        'youtube',v_artist.youtube,
        'soundcloud',v_artist.soundcloud,
        'spotify',v_artist.spotify
      );
    end;
    $function$


-- [40000001309] function public.tgg_update_notification_preferences(p_follows boolean, p_saves boolean, p_reactions boolean, p_comments boolean, p_collaboration boolean)
CREATE OR REPLACE FUNCTION public.tgg_update_notification_preferences(p_follows boolean DEFAULT true, p_saves boolean DEFAULT true, p_reactions boolean DEFAULT true, p_comments boolean DEFAULT true, p_collaboration boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare v_user uuid:=auth.uid(); begin if v_user is null then raise exception 'authentication required'; end if; insert into public.notification_preferences(user_id,follows_enabled,saves_enabled,reactions_enabled,comments_enabled,collaboration_enabled) values(v_user,coalesce(p_follows,true),coalesce(p_saves,true),coalesce(p_reactions,true),coalesce(p_comments,true),coalesce(p_collaboration,true)) on conflict(user_id) do update set follows_enabled=excluded.follows_enabled,saves_enabled=excluded.saves_enabled,reactions_enabled=excluded.reactions_enabled,comments_enabled=excluded.comments_enabled,collaboration_enabled=excluded.collaboration_enabled,updated_at=now(); return true; end $function$


-- [40000001310] function public.tgg_upload_track(p_mixtape_id uuid, p_title text, p_track_number integer, p_audio_url text, p_youtube_url text, p_youtube_video_id text, p_audio_path text)
CREATE OR REPLACE FUNCTION public.tgg_upload_track(p_mixtape_id uuid, p_title text, p_track_number integer, p_audio_url text DEFAULT NULL::text, p_youtube_url text DEFAULT NULL::text, p_youtube_video_id text DEFAULT NULL::text, p_audio_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'storage', 'pg_temp'
AS $function$
declare
  v_user_id uuid:=auth.uid();
  v_artist_id uuid;
  v_track_id uuid;
  v_status public.mixtape_status;
  v_path text:=nullif(trim(p_audio_path),'');
  v_external text:=coalesce(
    nullif(trim(p_audio_url),''),
    nullif(trim(p_youtube_url),'')
  );
begin
  if v_user_id is null then raise exception 'AUTH_REQUIRED'; end if;

  select a.id into v_artist_id
  from public.artists a
  where a.user_id=v_user_id
  limit 1;

  if v_artist_id is null then raise exception 'ARTIST_PROFILE_NOT_FOUND'; end if;

  select m.status into v_status
  from public.mixtapes m
  where m.id=p_mixtape_id
    and m.artist_id=v_artist_id;

  if v_status is null then raise exception 'RELEASE_NOT_OWNED'; end if;

  if v_status not in (
    'draft'::public.mixtape_status,
    'changes_requested'::public.mixtape_status,
    'rejected'::public.mixtape_status
  ) then
    raise exception 'RELEASE_NOT_EDITABLE';
  end if;

  if coalesce(trim(p_title),'')='' then raise exception 'TRACK_TITLE_REQUIRED'; end if;
  if p_track_number is null or p_track_number<1 then raise exception 'TRACK_NUMBER_INVALID'; end if;

  if v_path is null and v_external is null then
    raise exception 'TRACK_AUDIO_OR_YOUTUBE_REQUIRED';
  end if;

  if v_path is not null then
    if split_part(v_path,'/',1)<>v_user_id::text then
      raise exception 'AUDIO_PATH_NOT_OWNED';
    end if;

    if not exists(
      select 1
      from storage.objects o
      where o.bucket_id='mixtape-audio'
        and o.name=v_path
        and (storage.foldername(o.name))[1]=v_user_id::text
    ) then
      raise exception 'AUDIO_OBJECT_NOT_FOUND';
    end if;
  end if;

  if v_external is not null and v_external !~* '^https://' then
    raise exception 'EXTERNAL_AUDIO_URL_INVALID';
  end if;

  select id into v_track_id
  from public.tracks
  where mixtape_id=p_mixtape_id
    and track_number=p_track_number
  for update;

  if v_track_id is null then
    insert into public.tracks(
      artist_id,user_id,audio_url,audio_path,has_secure_audio,
      mixtape_id,title,track_number
    )
    values(
      v_artist_id,v_user_id,
      case when v_path is null then v_external else null end,
      v_path,
      (v_path is not null),
      p_mixtape_id,
      trim(p_title),
      p_track_number
    )
    returning id into v_track_id;
  else
    update public.tracks
    set title=trim(p_title),
        user_id=v_user_id,
        artist_id=v_artist_id,
        audio_url=case
          when v_path is not null then null
          when v_external is not null then v_external
          else audio_url
        end,
        audio_path=case
          when v_path is not null then v_path
          when v_external is not null then null
          else audio_path
        end,
        has_secure_audio=case
          when v_path is not null then true
          when v_external is not null then false
          else (audio_path is not null)
        end
    where id=v_track_id;
  end if;

  return jsonb_build_object(
    'ok',true,
    'track_id',v_track_id,
    'mixtape_id',p_mixtape_id,
    'track_number',p_track_number,
    'upserted',true,
    'protected_audio',v_path is not null,
    'playback_mode',case when v_path is not null then 'protected' else 'external' end
  );
end
$function$


-- [40000001311] function public.tgg_v1685_reconcile_readiness()
CREATE OR REPLACE FUNCTION public.tgg_v1685_reconcile_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; passed integer:=0; failed integer:=0; pending integer:=0; total integer:=0; new_run uuid; score numeric:=0; decision text:='blocked'; blocker jsonb:='[]'::jsonb;
begin
select count(*) into total from public.tgg_browser_runtime_evidence_gate where evidence_required;
select count(*) into passed from public.tgg_browser_runtime_evidence_gate where evidence_required and browser_verified and status='passed';
select count(*) into failed from public.tgg_browser_runtime_evidence_gate where evidence_required and status='failed';
pending:=greatest(total-passed-failed,0); if total>0 then score:=round((passed::numeric/total::numeric)*100,2); end if;
if total>0 and passed=total and failed=0 then decision:='ready'; end if;
if pending>0 then blocker:=blocker||jsonb_build_array(jsonb_build_object('code','browser_qa_evidence','required',pending,'message','Real authenticated browser evidence is still required.')); end if;
if failed>0 then blocker:=blocker||jsonb_build_array(jsonb_build_object('code','browser_qa_failed','count',failed,'message','One or more browser runtime flows failed.')); end if;
insert into public.tgg_platform_readiness_runs(run_type,status,readiness_score,critical_failures,warnings,unknowns,started_at,completed_at,summary,metadata)
values('pre_release',decision,score,case when decision='blocked' then 1 else 0 end,0,pending,now(),now(),jsonb_build_object('version','V1685','scope','final evidence aggregation','browser_evidence_required',true,'browser_total',total,'browser_passed',passed,'browser_failed',failed,'browser_pending',pending),jsonb_build_object('production_gate','locked')) returning id into new_run;
insert into public.tgg_platform_readiness_signals(run_id,signal_source,signal_type,status,score,weight,blocking,evidence) values(new_run,'v1685_evidence_reconciliation','browser_qa_evidence',case when decision='ready' then 'passed' else 'blocked' end,score,1,true,jsonb_build_object('total',total,'passed',passed,'failed',failed,'pending',pending));
insert into public.tgg_platform_readiness_decisions(run_id,decision,rationale,blocking_reasons,warnings,decided_at) values(new_run,decision,case when decision='ready' then 'All required browser evidence is verified.' else 'Browser evidence is not fully verified.' end,blocker,'[]'::jsonb,now());
return jsonb_build_object('run_id',new_run,'decision',decision,'score',score,'total',total,'passed',passed,'failed',failed,'pending',pending,'production_gate','locked');
end; $function$


-- [40000001312] function public.tgg_v1687_refresh_readiness()
CREATE OR REPLACE FUNCTION public.tgg_v1687_refresh_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare v_run_id uuid; v_verified int:=0; v_required int:=0; v_contracts int:=0; v_contract_passed int:=0; v_gate text; v_score numeric:=0; v_status text:='blocked'; begin select count(*) into v_required from tgg_browser_runtime_evidence_gate where evidence_required; select count(*) into v_verified from tgg_browser_runtime_evidence_gate where evidence_required and browser_verified and status='passed'; select count(*) into v_contracts from tgg_runtime_contracts where status='active'; select count(distinct c.contract_id) into v_contract_passed from tgg_runtime_contract_checks c join tgg_runtime_contracts r on r.id=c.contract_id where r.status='active' and c.status='passed'; select gate_status into v_gate from tgg_release_gate where release_channel='production' limit 1; if v_required>0 and v_verified=v_required and v_contracts=v_contract_passed and coalesce(v_gate,'locked')<>'locked' then v_score:=100;v_status:='ready'; elsif v_required>0 then v_score:=round(((v_contract_passed::numeric/greatest(v_contracts,1))*90)+((v_verified::numeric/greatest(v_required,1))*10),2); end if; insert into tgg_platform_readiness_runs(run_type,status,readiness_score,critical_failures,warnings,unknowns,started_at,completed_at,summary,metadata) values('pre_release',v_status,v_score,case when v_verified<v_required then 1 else 0 end,0,case when v_verified<v_required then 1 else 0 end,now(),now(),jsonb_build_object('browser_evidence',jsonb_build_object('required',v_required,'verified',v_verified),'runtime_contracts',jsonb_build_object('active',v_contracts,'passed',v_contract_passed),'production_gate',coalesce(v_gate,'missing')),jsonb_build_object('engine','V1687','browser_execution_required',true)) returning id into v_run_id; insert into tgg_platform_readiness_signals(run_id,signal_source,signal_type,status,score,weight,blocking,evidence) values(v_run_id,'V1687','browser_qa_evidence',case when v_verified=v_required then 'passed' else 'blocked' end,case when v_required=0 then 0 else round(v_verified::numeric/greatest(v_required,1)*100,2) end,1,true,jsonb_build_object('required',v_required,'verified',v_verified)); insert into tgg_platform_readiness_decisions(run_id,decision,rationale,blocking_reasons,warnings,decided_at,decided_by) values(v_run_id,v_status,'V1687 blocker-aware aggregation; browser evidence remains independent from database contract checks',case when v_verified<v_required then jsonb_build_array('browser_qa_evidence') else '[]'::jsonb end,'[]'::jsonb,now(),null); return jsonb_build_object('run_id',v_run_id,'status',v_status,'score',v_score,'browser_required',v_required,'browser_verified',v_verified,'contracts',v_contracts,'contracts_passed',v_contract_passed,'production_gate',v_gate); end; $function$


-- [40000001313] function public.tgg_v1689_browser_evidence_integrity()
CREATE OR REPLACE FUNCTION public.tgg_v1689_browser_evidence_integrity()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
 required_count integer;
 verified_count integer;
 fabricated_count integer;
 expired_count integer;
 missing_count integer;
 result_status text;
begin
 select count(*) filter (where evidence_required),
        count(*) filter (where evidence_required and browser_verified),
        count(*) filter (where evidence_required and browser_verified and (evidence ? 'synthetic') and coalesce((evidence->>'synthetic')::boolean,false)),
        count(*) filter (where evidence_required and browser_verified and checked_at is not null and checked_at < now() - interval '30 days')
 into required_count, verified_count, fabricated_count, expired_count
 from public.tgg_browser_runtime_evidence_gate;
 missing_count := greatest(required_count - verified_count,0);
 result_status := case when fabricated_count > 0 then 'fail' when missing_count > 0 or expired_count > 0 then 'blocked' else 'pass' end;
 insert into public.tgg_browser_evidence_integrity_audit(audit_version,required_flows,verified_flows,fabricated_flows,expired_flows,missing_flows,integrity_status,details)
 values('V1689',required_count,verified_count,fabricated_count,expired_count,missing_count,result_status,jsonb_build_object('browser_evidence_only',true,'production_gate_remains_locked',true));
 return jsonb_build_object('required_flows',required_count,'verified_flows',verified_count,'fabricated_flows',fabricated_count,'expired_flows',expired_count,'missing_flows',missing_count,'integrity_status',result_status);
end;
$function$


-- [40000001314] function public.tgg_v5000_production_manifest()
CREATE OR REPLACE FUNCTION public.tgg_v5000_production_manifest()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_routes jsonb:=public.tgg_route_registry_final_health();
  v_drift jsonb:=public.tgg_get_production_drift();
  v_activation jsonb:=public.tgg_optional_upgrade_activation_health();
  v_blockers jsonb:=public.tgg_external_blockers_final();
  v_optional jsonb:=public.tgg_external_optional_upgrades_final();
  v_versions jsonb:=coalesce(public.tgg_unified_version_status(),'{}'::jsonb);
  v_url text:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-creator-os-app-v17?app=1';
  v_edge_version integer:=coalesce(nullif(v_versions#>>'{runtime,creator_os,version}','')::integer,161);
  v_edge_sha text:=coalesce(v_versions#>>'{runtime,creator_os,sha256}','');
  v_public_shell_version integer:=coalesce(nullif(v_versions#>>'{runtime,public_shell,version}','')::integer,16);
  v_builder_source text:=coalesce(v_versions->>'autobuilder_source_version','V223');
begin
  return jsonb_build_object(
    'ok',
      coalesce((v_routes->>'ok')::boolean,false)
      and coalesce((v_drift->>'ok')::boolean,false)
      and jsonb_array_length(v_blockers)=0,
    'product','TRU GO GETTA Creator OS',
    'version','V5000',
    'runtime',jsonb_build_object(
      'edge_function','tgg-creator-os-app-v17',
      'edge_version',v_edge_version,
      'edge_sha256',v_edge_sha,
      'public_shell_version',v_public_shell_version,
      'autobuilder_source_version',v_builder_source,
      'unified_upgrade_manifest','UNIFIED-UPGRADE-MANIFEST-1.0',
      'build','V5000-CODESYNC',
      'frontend','canonical_creator_os_edge_runtime',
