-- [40000001315] function public.tgg_v5000_runtime_integrity()
CREATE OR REPLACE FUNCTION public.tgg_v5000_runtime_integrity()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with m as (
  select public.tgg_v5000_production_manifest() as j
),
s as (
  select *
  from public.tgg_runtime_integrity_state_v1
  where id=1
)
select jsonb_build_object(
  'ok',
    coalesce((m.j->>'ok')::boolean,false)
    and coalesce(s.live_state,'')='ready'
    and coalesce(s.versioned_state,'')='ready'
    and m.j#>>'{recovery,checkpoint_key}'='creator_os_v5000_live'
    and (m.j#>>'{runtime,edge_version}')::integer=coalesce(s.live_edge_version,0)
    and m.j#>>'{runtime,edge_sha256}'=coalesce(s.live_fingerprint,'')
    and m.j#>>'{recovery,current_version_checkpoint}'=coalesce(s.current_checkpoint,'')
    and coalesce(s.versioned_fingerprint,'')=coalesce(s.live_fingerprint,''),
  'version','V5000-ONE-LOAD',
  'build','V5000-ONE-LOAD',
  'frontend','blogger_embedded_creator_os',
  'edge_version',s.live_edge_version,
  'checkpoint_key','creator_os_v5000_live',
  'current_version_checkpoint',s.current_checkpoint,
  'fingerprint',s.live_fingerprint,
  'manifest',m.j,
  'dynamic_checkpoint_validation',true,
  'generated_at',now()
)
from m
cross join s
$function$


-- [40000001316] function public.tgg_validate_runtime_evidence(p_flow_key text, p_evidence_type text, p_source_ref text, p_evidence jsonb)
CREATE OR REPLACE FUNCTION public.tgg_validate_runtime_evidence(p_flow_key text, p_evidence_type text, p_source_ref text, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare v_result jsonb; begin if p_flow_key is null or length(trim(p_flow_key))=0 then raise exception 'flow_key required'; end if; if p_evidence_type is null or length(trim(p_evidence_type))=0 then raise exception 'evidence_type required'; end if; if p_evidence is null then raise exception 'evidence required'; end if; if p_evidence_type not in ('browser_qa','authenticated_browser','screenshot','video_recording','manual_browser_check') then insert into public.tgg_runtime_evidence_validation_events(flow_key,validation_status,evidence_type,source_ref,evidence,validated_at) values(p_flow_key,'rejected',p_evidence_type,p_source_ref,p_evidence,now()); return jsonb_build_object('accepted',false,'status','rejected','reason','unsupported_evidence_type'); end if; if coalesce((p_evidence->>'executed')::boolean,false) is not true then insert into public.tgg_runtime_evidence_validation_events(flow_key,validation_status,evidence_type,source_ref,evidence,validated_at) values(p_flow_key,'rejected',p_evidence_type,p_source_ref,p_evidence,now()); return jsonb_build_object('accepted',false,'status','rejected','reason','browser_execution_not_confirmed'); end if; insert into public.tgg_runtime_evidence_validation_events(flow_key,validation_status,evidence_type,source_ref,evidence,validated_at) values(p_flow_key,'passed',p_evidence_type,p_source_ref,p_evidence,now()); update public.tgg_browser_runtime_evidence_gate set status='passed',browser_verified=true,evidence=p_evidence,checked_at=now(),updated_at=now() where flow_key=p_flow_key; update public.tgg_runtime_evidence_capture_workflow set status='passed',evidence_source=p_evidence_type,notes=coalesce(p_source_ref,'validated browser evidence'),updated_at=now() where flow_key=p_flow_key; return jsonb_build_object('accepted',true,'status','passed','flow_key',p_flow_key); exception when others then raise; end; $function$


-- [40000001317] function public.tgg_vault_item_create(p_title text, p_description text, p_item_type text, p_min_tier_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_vault_item_create(p_title text, p_description text DEFAULT NULL::text, p_item_type text DEFAULT 'post'::text, p_min_tier_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_artist uuid;v_id uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist from public.artists where user_id=v_uid limit 1;
      if v_artist is null then raise exception 'ARTIST_PROFILE_REQUIRED'; end if;
      if char_length(btrim(coalesce(p_title,'')))<1 then raise exception 'TITLE_REQUIRED'; end if;
      insert into public.tgg_vault_items(artist_id,title,description,item_type,min_tier_id,published_at)
      values(v_artist,left(btrim(p_title),160),nullif(btrim(coalesce(p_description,'')),''),coalesce(nullif(btrim(coalesce(p_item_type,'')),''),'post'),p_min_tier_id,now())
      returning id into v_id;
      return jsonb_build_object('ok',true,'vault_item_id',v_id);
    end $function$


-- [40000001318] function public.tgg_vault_item_delete(p_item_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_vault_item_delete(p_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_artist uuid;v_id uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist from public.artists where user_id=v_uid limit 1;
      delete from public.tgg_vault_items where id=p_item_id and artist_id=v_artist returning id into v_id;
      if v_id is null then raise exception 'VAULT_ITEM_NOT_FOUND_OR_NOT_OWNED'; end if;
      return jsonb_build_object('ok',true,'vault_item_id',v_id,'deleted',true);
    end $function$


-- [40000001319] function public.tgg_vault_item_update(p_item_id uuid, p_title text, p_description text, p_item_type text, p_min_tier_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_vault_item_update(p_item_id uuid, p_title text, p_description text, p_item_type text, p_min_tier_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    declare v_uid uuid:=auth.uid();v_artist uuid;v_id uuid;
    begin
      if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
      select id into v_artist from public.artists where user_id=v_uid limit 1;
      update public.tgg_vault_items set
        title=left(btrim(coalesce(p_title,'')),160),
        description=nullif(btrim(coalesce(p_description,'')),''),
        item_type=coalesce(nullif(btrim(coalesce(p_item_type,'')),''),item_type),
        min_tier_id=p_min_tier_id
      where id=p_item_id and artist_id=v_artist
      returning id into v_id;
      if v_id is null then raise exception 'VAULT_ITEM_NOT_FOUND_OR_NOT_OWNED'; end if;
      return jsonb_build_object('ok',true,'vault_item_id',v_id);
    end $function$


