-- [40000001321] function public.tgg_veil_health_refresh()
CREATE OR REPLACE FUNCTION public.tgg_veil_health_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry boolean:=false;
  v_rabbit boolean:=false;
  v_exit boolean:=false;
  v_rls boolean:=false;
  v_policies integer:=0;
  v_secret_ok boolean:=false;
  v_status text:='healthy';
  v_id uuid;
begin
  select coalesce(access_level in ('artist','admin'),false)
  into v_entry
  from public.tgg_site_routes
  where route_key='artist_world' and is_active=true
  limit 1;

  select coalesce(access_level in ('artist','admin'),false)
  into v_rabbit
  from public.tgg_site_routes
  where route_key='artist_games_tv' and is_active=true
  limit 1;

  select coalesce(access_level in ('artist','admin'),false)
  into v_exit
  from public.tgg_site_routes
  where route_key='artist_creator_os' and is_active=true
  limit 1;

  select c.relrowsecurity
  into v_rls
  from pg_class c
  join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='public' and c.relname='tgg_matrix_gateway_sessions';

  select count(*) into v_policies
  from pg_policies
  where schemaname='public'
    and tablename='tgg_matrix_gateway_sessions'
    and policyname in (
      'matrix_gateway_select_own',
      'matrix_gateway_insert_own',
      'matrix_gateway_update_own'
    );

  select not exists(
    select 1
    from pg_proc p
    join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public'
      and p.proname in (
        'tgg_get_provider_secret_service',
        'tgg_store_provider_secret'
      )
      and has_function_privilege('anon',p.oid,'EXECUTE')
  ) into v_secret_ok;

  if not v_rls or v_policies<3 or not v_secret_ok then
    v_status:='restricted';
  elsif not v_entry or not v_rabbit or not v_exit then
    v_status:='warning';
  end if;

  insert into public.tgg_veil_health_snapshots(
    status,entry_access_ok,rabbit_access_ok,exit_access_ok,
    matrix_rls_ok,session_owner_policies_ok,secret_boundary_ok,veil
  )
  values(
    v_status,v_entry,v_rabbit,v_exit,v_rls,(v_policies>=3),v_secret_ok,
    jsonb_build_object(
      'role','visibility_privacy_masking_boundary',
      'public_sees_public',true,
      'authenticated_sees_authenticated',true,
      'artist_routes_require_artist_or_admin',true,
      'admin_routes_require_admin',true,
      'secret_values_never_exposed_to_anon',true,
      'matrix_sessions_owner_only',true,
      'can_override_head',false,
      'production_change_performed',false
    )
  )
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,'snapshot_id',v_id,'status',v_status,
    'entry_access_ok',v_entry,'rabbit_access_ok',v_rabbit,'exit_access_ok',v_exit,
    'matrix_rls_ok',v_rls,'session_owner_policies_ok',(v_policies>=3),
    'secret_boundary_ok',v_secret_ok
  );
end $function$


-- [40000001322] function public.tgg_veil_health_state()
CREATE OR REPLACE FUNCTION public.tgg_veil_health_state()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'status',status,
    'entry_access_ok',entry_access_ok,
    'rabbit_access_ok',rabbit_access_ok,
    'exit_access_ok',exit_access_ok,
    'matrix_rls_ok',matrix_rls_ok,
    'session_owner_policies_ok',session_owner_policies_ok,
    'secret_boundary_ok',secret_boundary_ok,
    'veil',veil,
    'sensed_at',sensed_at
  )
  from public.tgg_veil_health_snapshots
  order by sensed_at desc
  limit 1
$function$


-- [40000001323] function public.tgg_veil_route_decision(p_route_key text)
CREATE OR REPLACE FUNCTION public.tgg_veil_route_decision(p_route_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_access text;
  v_path text;
  v_role text;
  v_artist boolean:=false;
  v_admin boolean:=false;
  v_allow boolean:=false;
  v_reason text:='denied';
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select access_level,path
  into v_access,v_path
  from public.tgg_site_routes
  where route_key=p_route_key and is_active=true
  limit 1;

  if v_access is null then
    return jsonb_build_object(
      'ok',false,'allow',false,'route_key',p_route_key,'reason','route_unavailable'
    );
  end if;

  select role::text into v_role
  from public.profiles
  where id=v_uid
  limit 1;

  select exists(
    select 1 from public.artists where user_id=v_uid
  ) into v_artist;

  v_admin:=coalesce(public.is_admin(),false)
    or lower(coalesce(v_role,'')) in ('admin','owner','superadmin');

  v_allow:=case lower(v_access)
    when 'public' then true
    when 'authenticated' then true
    when 'artist' then v_artist or v_admin or lower(coalesce(v_role,'')) in ('artist','creator')
    when 'admin' then v_admin
    else false
  end;

  v_reason:=case
    when v_allow then 'veil_open'
    when lower(v_access)='artist' then 'artist_access_required'
    when lower(v_access)='admin' then 'admin_access_required'
    else 'access_denied'
  end;

  return jsonb_build_object(
    'ok',true,
    'allow',v_allow,
    'route_key',p_route_key,
    'path',v_path,
    'access_level',v_access,
    'reason',v_reason,
    'veil','open_only_when_authorized'
  );
end $function$


-- [40000001324] function public.tgg_veil_route_decision_audited(p_route_key text)
CREATE OR REPLACE FUNCTION public.tgg_veil_route_decision_audited(p_route_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public,private'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_decision jsonb;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  v_decision:=public.tgg_veil_route_decision(p_route_key);

  insert into private.tgg_veil_audit_ledger(
    actor_user_id,route_key,allowed,access_level,reason,source,metadata
  )
  values(
    v_uid,
    p_route_key,
    coalesce((v_decision->>'allow')::boolean,false),
    nullif(v_decision->>'access_level',''),
    coalesce(v_decision->>'reason','unknown'),
    'tgg_veil_route_decision_audited',
    jsonb_build_object(
      'path_present',nullif(v_decision->>'path','') is not null,
      'stores_secret_values',false,
      'stores_message_body',false,
      'stores_provider_payload',false
    )
  );

  return v_decision;
end $function$


