-- [40000001329] function public.tgg_video_render_worker_claim(p_worker_id text, p_provider_key text, p_lease_seconds integer)
CREATE OR REPLACE FUNCTION public.tgg_video_render_worker_claim(p_worker_id text, p_provider_key text DEFAULT 'external.transcoder'::text, p_lease_seconds integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  j public.tgg_video_studio_render_jobs;
  tok uuid:=gen_random_uuid();
  lease_s integer:=least(1800,greatest(60,coalesce(p_lease_seconds,300)));
  manifest jsonb;
begin
  if nullif(btrim(coalesce(p_worker_id,'')),'') is null then raise exception 'WORKER_ID_REQUIRED'; end if;

  update public.tgg_video_studio_render_jobs r
  set status='failed',
      error_message='STALE_SOURCE_REVISION_REQUEUE_REQUIRED',
      finished_at=now(),
      lease_token=null,
      leased_by=null,
      lease_expires_at=null,
      worker_heartbeat_at=now(),
      updated_at=now()
  where r.status in ('queued','processing')
    and (r.status='queued' or r.lease_expires_at is null or r.lease_expires_at<now())
    and coalesce(r.request_payload->>'mode','')<>'browser_export'
    and exists (
      select 1
      from public.tgg_studio_projects sp
      where sp.id=r.project_id
        and coalesce(sp.revision,0)<>coalesce(r.source_revision,0)
    );

  select * into j
  from public.tgg_video_studio_render_jobs r
  where (r.status='queued' or (r.status='processing' and r.lease_expires_at<now()))
    and coalesce(r.request_payload->>'mode','')<>'browser_export'
    and exists (
      select 1
      from public.tgg_studio_projects sp
      where sp.id=r.project_id
        and coalesce(sp.revision,0)=coalesce(r.source_revision,0)
    )
  order by r.priority asc,r.created_at asc
  for update skip locked
  limit 1;

  if j.id is null then return jsonb_build_object('ok',true,'job',null); end if;

  update public.tgg_video_studio_render_jobs
  set status='processing',
      provider_key=coalesce(nullif(btrim(p_provider_key),''),'external.transcoder'),
      lease_token=tok,
      leased_by=left(p_worker_id,120),
      lease_expires_at=now()+make_interval(secs=>lease_s),
      worker_heartbeat_at=now(),
      started_at=coalesce(started_at,now()),
      finished_at=null,
      error_message=null,
      attempt_count=attempt_count+1,
      progress=greatest(progress,1),
      updated_at=now()
  where id=j.id
  returning * into j;

  select jsonb_build_object(
    'schema_version',6,
    'job',to_jsonb(j)-'lease_token',
    'lease_token',tok,
    'project',(select to_jsonb(c) from public.tgg_creative_projects c where c.id=j.project_id),
    'studio_project',(select to_jsonb(s) from public.tgg_studio_projects s where s.id=j.project_id),
    'timeline',coalesce((select jsonb_agg(to_jsonb(t) order by t.track_index,t.start_seconds,t.created_at) from public.tgg_video_timeline_items t where t.project_id=j.project_id),'[]'::jsonb),
    'assets',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at) from public.tgg_media_vault_assets a where a.id in (select distinct t.asset_id from public.tgg_video_timeline_items t where t.project_id=j.project_id and t.asset_id is not null)),'[]'::jsonb),
    'effects',coalesce((select jsonb_agg(to_jsonb(e) order by e.timeline_item_id,e.stack_order,e.created_at) from public.tgg_video_studio_effect_instances e where e.project_id=j.project_id),'[]'::jsonb),
    'keyframes',coalesce((select jsonb_agg(to_jsonb(k) order by k.timeline_item_id,k.parameter,k.time_seconds) from public.tgg_video_studio_keyframes k where k.project_id=j.project_id),'[]'::jsonb),
    'captions',coalesce((select jsonb_agg(to_jsonb(cu) order by cu.start_seconds,cu.track_index) from public.tgg_video_studio_caption_cues cu where cu.project_id=j.project_id),'[]'::jsonb),
    'markers',coalesce((select jsonb_agg(to_jsonb(m) order by m.time_seconds) from public.tgg_video_studio_markers m where m.project_id=j.project_id),'[]'::jsonb),
    'transitions',coalesce((select jsonb_agg(to_jsonb(tr) order by tr.created_at) from public.tgg_video_studio_transition_instances tr where tr.project_id=j.project_id),'[]'::jsonb),
    'track_states',coalesce((select jsonb_agg(to_jsonb(ts) order by ts.track_index) from private.tgg_video_studio_track_states ts where ts.project_id=j.project_id),'[]'::jsonb),
    'requested_output',jsonb_build_object('format',j.output_format,'preset',j.output_preset,'job_type',j.job_type,'payload',j.request_payload),
    'output_storage_prefix',j.user_id::text||'/video/'||j.project_id::text||'/server-renders/'||j.id::text||'/'
  ) into manifest;

  return jsonb_build_object('ok',true,'manifest',manifest);
end$function$


-- [40000001330] function public.tgg_video_render_worker_complete(p_job_id uuid, p_lease_token uuid, p_storage_path text, p_format text, p_aspect_ratio text, p_resolution text, p_duration_seconds numeric, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_video_render_worker_complete(p_job_id uuid, p_lease_token uuid, p_storage_path text, p_format text, p_aspect_ratio text, p_resolution text DEFAULT NULL::text, p_duration_seconds numeric DEFAULT NULL::numeric, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  j public.tgg_video_studio_render_jobs;
  out_id uuid;
  asset_id uuid;
  current_revision bigint;
  v_format text:=lower(btrim(coalesce(p_format,'mp4')));
  v_mime text;
  v_width integer;
  v_height integer;
  v_size bigint;
  v_title text;
begin
  select * into j from public.tgg_video_studio_render_jobs where id=p_job_id and status='processing' and lease_token=p_lease_token for update;
  if j.id is null then return jsonb_build_object('ok',false,'lease_valid',false); end if;
  select coalesce(revision,0) into current_revision from public.tgg_studio_projects where id=j.project_id;
  if current_revision is distinct from coalesce(j.source_revision,0) then
    update public.tgg_video_studio_render_jobs
    set status='failed',error_message='STALE_SOURCE_REVISION_RESULT_REJECTED',finished_at=now(),lease_token=null,lease_expires_at=null,worker_heartbeat_at=now(),updated_at=now()
    where id=j.id;
    return jsonb_build_object('ok',false,'stale_source_revision',true,'queued_revision',j.source_revision,'current_revision',current_revision);
  end if;
  if nullif(btrim(coalesce(p_storage_path,'')),'') is null then raise exception 'OUTPUT_STORAGE_PATH_REQUIRED'; end if;
  if position(j.user_id::text||'/video/'||j.project_id::text||'/server-renders/'||j.id::text||'/' in p_storage_path)<>1 then raise exception 'OUTPUT_STORAGE_PATH_INVALID'; end if;
  if v_format not in ('mp4','webm','mov') then raise exception 'FORMAT_INVALID'; end if;
  if jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))<>'object' then raise exception 'METADATA_INVALID'; end if;

  v_mime:=coalesce(nullif(p_metadata->>'mime_type',''),case v_format when 'mp4' then 'video/mp4' when 'webm' then 'video/webm' else 'video/quicktime' end);
  v_width:=case when coalesce(p_metadata->>'width','') ~ '^[0-9]{1,6}$' then (p_metadata->>'width')::integer else null end;
  v_height:=case when coalesce(p_metadata->>'height','') ~ '^[0-9]{1,6}$' then (p_metadata->>'height')::integer else null end;
  v_size:=case when coalesce(p_metadata->>'file_size_bytes','') ~ '^[0-9]{1,20}$' then (p_metadata->>'file_size_bytes')::bigint else null end;
  v_title:=coalesce(nullif(btrim(p_metadata->>'title'),''),'Server Render · '||coalesce(nullif(p_resolution,''),j.output_preset,'master'));

  insert into public.tgg_media_vault_assets(user_id,project_id,asset_type,title,source_kind,storage_path,public_url,mime_type,duration_seconds,width,height,file_size_bytes,metadata)
  values(j.user_id,j.project_id,'video',left(v_title,200),'generated',p_storage_path,null,v_mime,p_duration_seconds,v_width,v_height,v_size,
    coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('kind','server_render','render_job_id',j.id,'provider_key',j.provider_key,'source_revision',j.source_revision))
  returning id into asset_id;

  insert into public.tgg_video_studio_render_outputs(render_job_id,user_id,format,aspect_ratio,resolution,duration_seconds,storage_path,public_url,status,metadata)
  values(j.id,j.user_id,v_format,coalesce(nullif(p_aspect_ratio,''),'16:9'),p_resolution,p_duration_seconds,p_storage_path,null,'ready',
    coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('provider_key',j.provider_key,'worker',j.leased_by,'source_revision',j.source_revision,'asset_id',asset_id))
  returning id into out_id;

  update public.tgg_video_studio_render_jobs
  set status='ready',progress=100,result_payload=jsonb_build_object('output_id',out_id,'asset_id',asset_id,'storage_path',p_storage_path,'format',v_format,'completed_by',j.leased_by),
      finished_at=now(),lease_token=null,lease_expires_at=null,worker_heartbeat_at=now(),updated_at=now()
  where id=j.id;
  return jsonb_build_object('ok',true,'output_id',out_id,'asset_id',asset_id,'job_id',j.id,'status','ready');
end$function$


-- [40000001331] function public.tgg_video_render_worker_fail(p_job_id uuid, p_lease_token uuid, p_error text, p_retryable boolean)
CREATE OR REPLACE FUNCTION public.tgg_video_render_worker_fail(p_job_id uuid, p_lease_token uuid, p_error text, p_retryable boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare j public.tgg_video_studio_render_jobs; next_status text;
begin
 select * into j from public.tgg_video_studio_render_jobs where id=p_job_id and status='processing' and lease_token=p_lease_token for update;
 if j.id is null then return jsonb_build_object('ok',false,'lease_valid',false); end if;
 next_status:=case when coalesce(p_retryable,true) and j.attempt_count<3 then 'queued' else 'failed' end;
 update public.tgg_video_studio_render_jobs set status=next_status,error_message=left(coalesce(p_error,'worker_failed'),2000),finished_at=case when next_status='failed' then now() else null end,lease_token=null,leased_by=case when next_status='queued' then null else leased_by end,lease_expires_at=null,worker_heartbeat_at=now(),updated_at=now() where id=j.id;
 return jsonb_build_object('ok',true,'job_id',j.id,'status',next_status,'attempt_count',j.attempt_count);
end$function$


-- [40000001332] function public.tgg_video_render_worker_heartbeat(p_job_id uuid, p_lease_token uuid, p_progress numeric, p_lease_seconds integer)
CREATE OR REPLACE FUNCTION public.tgg_video_render_worker_heartbeat(p_job_id uuid, p_lease_token uuid, p_progress numeric DEFAULT NULL::numeric, p_lease_seconds integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare j public.tgg_video_studio_render_jobs; lease_s integer:=least(1800,greatest(60,coalesce(p_lease_seconds,300)));
begin
 update public.tgg_video_studio_render_jobs set worker_heartbeat_at=now(),lease_expires_at=now()+make_interval(secs=>lease_s),progress=case when p_progress is null then progress else least(99,greatest(progress,p_progress)) end,updated_at=now()
 where id=p_job_id and status='processing' and lease_token=p_lease_token and lease_expires_at>now()-interval '30 seconds' returning * into j;
 if j.id is null then return jsonb_build_object('ok',false,'lease_valid',false); end if;
 return jsonb_build_object('ok',true,'lease_valid',true,'progress',j.progress,'lease_expires_at',j.lease_expires_at);
end$function$


-- [40000001333] function public.tgg_video_render_worker_register(p_worker_key text, p_provider_key text, p_capabilities jsonb, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_video_render_worker_register(p_worker_key text, p_provider_key text DEFAULT 'github.ffmpeg.v1'::text, p_capabilities jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public', 'pg_catalog'
AS $function$
declare
  v private.tgg_video_render_worker_runtime;
  v_provider text:=left(coalesce(nullif(btrim(p_provider_key),''),'github.ffmpeg.v1'),120);
  v_pruned integer:=0;
begin
  if nullif(btrim(coalesce(p_worker_key,'')),'') is null then raise exception 'WORKER_KEY_REQUIRED'; end if;
  if char_length(p_worker_key)>160 or char_length(coalesce(p_provider_key,''))>120 then raise exception 'WORKER_IDENTITY_INVALID'; end if;
  if jsonb_typeof(coalesce(p_capabilities,'{}'::jsonb))<>'object' or jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))<>'object' then raise exception 'WORKER_METADATA_INVALID'; end if;

  insert into private.tgg_video_render_worker_runtime(worker_key,provider_key,status,capabilities,metadata,last_seen_at,created_at,updated_at)
  values(left(btrim(p_worker_key),160),v_provider,'online',coalesce(p_capabilities,'{}'::jsonb),coalesce(p_metadata,'{}'::jsonb),now(),now(),now())
  on conflict(worker_key) do update
    set provider_key=excluded.provider_key,status='online',capabilities=excluded.capabilities,metadata=excluded.metadata,last_seen_at=now(),updated_at=now()
  returning * into v;

  delete from private.tgg_video_render_worker_runtime r
  where r.provider_key=v_provider
    and r.worker_key<>v.worker_key
    and r.last_seen_at<now()-interval '24 hours';
  get diagnostics v_pruned = row_count;

  return jsonb_build_object('ok',true,'worker_key',v.worker_key,'provider_key',v.provider_key,'status',v.status,'last_seen_at',v.last_seen_at,'pruned_stale_rows',v_pruned);
end$function$


-- [40000001334] function public.tgg_video_studio_add_timeline_item(p_project_id uuid, p_asset_id uuid, p_track_index integer, p_item_type text, p_start_seconds numeric, p_duration_seconds numeric, p_source_in_seconds numeric, p_settings jsonb)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_add_timeline_item(p_project_id uuid, p_asset_id uuid DEFAULT NULL::uuid, p_track_index integer DEFAULT 0, p_item_type text DEFAULT 'video'::text, p_start_seconds numeric DEFAULT 0, p_duration_seconds numeric DEFAULT 0, p_source_in_seconds numeric DEFAULT 0, p_settings jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_item public.tgg_video_timeline_items;
  v_revision bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if p_track_index<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  if p_item_type not in ('video','audio','image','text','caption','overlay') then raise exception 'ITEM_TYPE_INVALID'; end if;
  if coalesce(p_start_seconds,0)<0 or coalesce(p_duration_seconds,0)<0 or coalesce(p_source_in_seconds,0)<0 then raise exception 'TIME_INVALID'; end if;
  if p_asset_id is not null and not exists(select 1 from public.tgg_media_vault_assets where id=p_asset_id and project_id=p_project_id) then raise exception 'ASSET_NOT_FOUND_IN_PROJECT'; end if;
  if jsonb_typeof(coalesce(p_settings,'{}'::jsonb))<>'object' then raise exception 'SETTINGS_INVALID'; end if;

  insert into public.tgg_video_timeline_items(user_id,project_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
  values(v_uid,p_project_id,p_asset_id,p_track_index,p_item_type,coalesce(p_start_seconds,0),coalesce(p_duration_seconds,0),coalesce(p_source_in_seconds,0),coalesce(p_settings,'{}'::jsonb))
  returning * into v_item;

  update public.tgg_creative_projects set updated_at=now() where id=p_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_revision;
  return to_jsonb(v_item)||jsonb_build_object('project_revision',v_revision);
end;
$function$


-- [40000001335] function public.tgg_video_studio_apply_effect(p_project_id uuid, p_timeline_item_id uuid, p_effect_catalog_id uuid, p_settings jsonb)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_apply_effect(p_project_id uuid, p_timeline_item_id uuid, p_effect_catalog_id uuid, p_settings jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_fx public.tgg_video_studio_fx_catalog; v_row public.tgg_video_studio_effect_instances; v_order int; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from public.tgg_video_timeline_items where id=p_timeline_item_id and project_id=p_project_id) then raise exception 'ITEM_NOT_FOUND'; end if;
 select * into v_fx from public.tgg_video_studio_fx_catalog where id=p_effect_catalog_id and enabled=true; if v_fx.id is null then raise exception 'EFFECT_NOT_FOUND'; end if;
 select coalesce(max(stack_order),-1)+1 into v_order from public.tgg_video_studio_effect_instances where timeline_item_id=p_timeline_item_id;
 insert into public.tgg_video_studio_effect_instances(project_id,timeline_item_id,user_id,effect_catalog_id,effect_type,stack_order,settings,enabled)
 values(p_project_id,p_timeline_item_id,v_uid,v_fx.id,v_fx.effect_type,v_order,coalesce(p_settings,'{}'::jsonb),true) returning * into v_row;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return to_jsonb(v_row)||jsonb_build_object('project_revision',v_rev);
end$function$


-- [40000001336] function public.tgg_video_studio_apply_transition(p_project_id uuid, p_from_item_id uuid, p_to_item_id uuid, p_transition_catalog_id uuid, p_duration_seconds numeric, p_settings jsonb)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_apply_transition(p_project_id uuid, p_from_item_id uuid, p_to_item_id uuid, p_transition_catalog_id uuid, p_duration_seconds numeric DEFAULT 0.35, p_settings jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_row public.tgg_video_studio_transition_instances; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 if p_from_item_id=p_to_item_id then raise exception 'TRANSITION_ITEMS_MUST_DIFFER'; end if;
 if (select count(*) from public.tgg_video_timeline_items where project_id=p_project_id and id in (p_from_item_id,p_to_item_id))<>2 then raise exception 'TRANSITION_ITEMS_INVALID'; end if;
 if not exists(select 1 from public.tgg_video_studio_transition_catalog where id=p_transition_catalog_id and enabled=true) then raise exception 'TRANSITION_NOT_FOUND'; end if;
 insert into public.tgg_video_studio_transition_instances(project_id,user_id,transition_catalog_id,from_item_id,to_item_id,duration_seconds,settings)
 values(p_project_id,v_uid,p_transition_catalog_id,p_from_item_id,p_to_item_id,least(10,greatest(0.05,coalesce(p_duration_seconds,0.35))),coalesce(p_settings,'{}'::jsonb)) returning * into v_row;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return to_jsonb(v_row)||jsonb_build_object('project_revision',v_rev);
end$function$


-- [40000001337] function public.tgg_video_studio_bundle(p_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_bundle(p_project_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_project_id uuid := p_project_id;
  v_permission jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  if v_project_id is null then
    select c.id into v_project_id
    from public.tgg_creative_projects c
    join public.tgg_studio_projects s on s.id=c.id and s.project_type='video'
    left join public.tgg_studio_project_members m on m.project_id=s.id and m.user_id=v_uid and m.left_at is null
    where c.project_type='video' and (s.user_id=v_uid or m.user_id=v_uid)
    order by c.updated_at desc
    limit 1;
  else
    v_permission:=tgg_private.video_studio_permission(v_project_id);
    if not coalesce((v_permission->>'allowed')::boolean,false) then raise exception 'PROJECT_NOT_FOUND_OR_NOT_ACCESSIBLE'; end if;
  end if;

  if v_project_id is not null then v_permission:=tgg_private.video_studio_permission(v_project_id); end if;

  return jsonb_build_object(
    'ok',true,
    'selected_project_id',v_project_id,
    'permission',v_permission,
    'projects',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.updated_at desc)
      from (
        select c.id,c.title,c.description,c.status,c.aspect_ratio,c.duration_seconds,c.settings,
               c.created_at,c.updated_at,coalesce(s.revision,0) revision,coalesce(s.collaboration_enabled,false) collaboration_enabled,
               case when s.user_id=v_uid then 'owner' else m.role end role
        from public.tgg_creative_projects c
        join public.tgg_studio_projects s on s.id=c.id and s.project_type='video'
        left join public.tgg_studio_project_members m on m.project_id=s.id and m.user_id=v_uid and m.left_at is null
        where c.project_type='video' and (s.user_id=v_uid or m.user_id=v_uid)
        order by c.updated_at desc
      ) x
    ),'[]'::jsonb),
    'project',case when v_project_id is null then null else (
      select to_jsonb(x) from (
        select c.id,c.title,c.description,c.status,c.aspect_ratio,c.duration_seconds,c.settings,
               c.created_at,c.updated_at,coalesce(s.revision,0) revision,coalesce(s.collaboration_enabled,false) collaboration_enabled
        from public.tgg_creative_projects c join public.tgg_studio_projects s on s.id=c.id
        where c.id=v_project_id and c.project_type='video'
      ) x
    ) end,
    'assets',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(a) order by a.created_at desc) from public.tgg_media_vault_assets a where a.project_id=v_project_id
    ),'[]'::jsonb) end,
    'timeline',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(t) order by t.track_index,t.start_seconds,t.created_at) from public.tgg_video_timeline_items t where t.project_id=v_project_id
    ),'[]'::jsonb) end,
    'render_jobs',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(r) order by r.created_at desc) from public.tgg_video_studio_render_jobs r where r.project_id=v_project_id
    ),'[]'::jsonb) end,
    'render_outputs',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(o) order by o.created_at desc)
      from public.tgg_video_studio_render_outputs o join public.tgg_video_studio_render_jobs r on r.id=o.render_job_id
      where r.project_id=v_project_id
    ),'[]'::jsonb) end,
    'publish_manifests',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(m) order by m.created_at desc) from public.tgg_video_studio_publish_manifests m where m.project_id=v_project_id
    ),'[]'::jsonb) end,
    'members',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(m) order by m.joined_at) from public.tgg_studio_project_members m where m.project_id=v_project_id and m.left_at is null
    ),'[]'::jsonb) end,
    'presence',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(p) order by p.last_seen_at desc) from public.tgg_studio_project_presence p where p.project_id=v_project_id
    ),'[]'::jsonb) end,
    'generated_at',now()
  );
end;
$function$


-- [40000001338] function public.tgg_video_studio_clear_speed_ramp_v1(p_item_id uuid, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_clear_speed_ramp_v1(p_item_id uuid, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_item public.tgg_video_timeline_items;
  v_perm jsonb;
  v_revision bigint;
  v_new_revision bigint;
  v_deleted integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
  if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_perm:=tgg_private.video_studio_permission(v_item.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if exists(select 1 from private.tgg_video_studio_track_states s where s.project_id=v_item.project_id and s.track_index=v_item.track_index and s.locked=true) then raise exception 'TRACK_LOCKED'; end if;
  select revision into v_revision from public.tgg_studio_projects where id=v_item.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_revision then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_revision);
  end if;
  delete from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='speed';
  get diagnostics v_deleted=row_count;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_new_revision;
  return jsonb_build_object('ok',true,'conflict',false,'deleted',v_deleted,'project_revision',v_new_revision);
end
$function$


