-- [40000001340] function public.tgg_video_studio_clone_timeline_item_v2(p_item_id uuid, p_start_seconds numeric, p_track_index integer, p_base_revision bigint, p_insert boolean)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_clone_timeline_item_v2(p_item_id uuid, p_start_seconds numeric, p_track_index integer DEFAULT NULL::integer, p_base_revision bigint DEFAULT NULL::bigint, p_insert boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_item public.tgg_video_timeline_items;
  v_new public.tgg_video_timeline_items;
  v_permission jsonb;
  v_revision bigint;
  v_new_revision bigint;
  v_track integer;
  v_start numeric;
  v_shifted integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
  if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_permission:=tgg_private.video_studio_permission(v_item.project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;

  select revision into v_revision from public.tgg_studio_projects where id=v_item.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_revision then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_revision);
  end if;

  v_track:=coalesce(p_track_index,v_item.track_index);
  if v_track<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  v_start:=greatest(0,coalesce(p_start_seconds,0));

  if coalesce(p_insert,false) then
    if exists(
      select 1 from public.tgg_video_timeline_items
      where project_id=v_item.project_id and track_index=v_track
        and start_seconds<v_start and start_seconds+duration_seconds>v_start
    ) then
      return jsonb_build_object('ok',false,'occupied',true,'reason','INSERT_POINT_INSIDE_CLIP_SPLIT_FIRST','current_revision',v_revision);
    end if;
    update public.tgg_video_timeline_items
    set start_seconds=start_seconds+v_item.duration_seconds,updated_at=now()
    where project_id=v_item.project_id and track_index=v_track and start_seconds>=v_start;
    get diagnostics v_shifted=row_count;
  end if;

  insert into public.tgg_video_timeline_items(project_id,user_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
  values(v_item.project_id,v_uid,v_item.asset_id,v_track,v_item.item_type,v_start,v_item.duration_seconds,v_item.source_in_seconds,v_item.settings)
  returning * into v_new;

  insert into public.tgg_video_studio_effect_instances(project_id,timeline_item_id,user_id,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled)
  select project_id,v_new.id,v_uid,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled
  from public.tgg_video_studio_effect_instances where timeline_item_id=v_item.id;

  insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
  select project_id,v_new.id,v_uid,parameter,time_seconds,value,easing
  from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id;

  update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_new_revision;

  return jsonb_build_object('ok',true,'conflict',false,'occupied',false,'item',to_jsonb(v_new),'shifted_items',v_shifted,'base_revision',v_revision,'project_revision',v_new_revision);
end$function$


-- [40000001341] function public.tgg_video_studio_complete_browser_render(p_project_id uuid, p_job_id uuid, p_asset_id uuid, p_storage_path text, p_format text, p_aspect_ratio text, p_resolution text, p_duration_seconds numeric, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_complete_browser_render(p_project_id uuid, p_job_id uuid, p_asset_id uuid, p_storage_path text, p_format text DEFAULT 'webm'::text, p_aspect_ratio text DEFAULT '16:9'::text, p_resolution text DEFAULT NULL::text, p_duration_seconds numeric DEFAULT NULL::numeric, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_job public.tgg_video_studio_render_jobs;
  v_output public.tgg_video_studio_render_outputs;
  v_format text:=lower(btrim(coalesce(p_format,'webm')));
  v_ratio text:=btrim(coalesce(p_aspect_ratio,'16:9'));
  v_is_owner boolean:=false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  v_is_owner:=coalesce((v_permission->>'is_owner')::boolean,false);
  select * into v_job from public.tgg_video_studio_render_jobs where id=p_job_id and project_id=p_project_id;
  if v_job.id is null then raise exception 'RENDER_JOB_NOT_FOUND'; end if;
  if v_job.user_id<>v_uid and not v_is_owner then raise exception 'RENDER_JOB_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if v_job.status not in ('queued','processing') then raise exception 'RENDER_JOB_NOT_COMPLETABLE'; end if;
  if v_format not in ('webm','mp4','mov') then raise exception 'FORMAT_INVALID'; end if;
  if v_ratio not in ('16:9','9:16','1:1','4:5') then raise exception 'ASPECT_RATIO_INVALID'; end if;
  if p_storage_path is null or p_storage_path='' then raise exception 'STORAGE_PATH_REQUIRED'; end if;
  if p_duration_seconds is not null and (p_duration_seconds<0 or p_duration_seconds>86400) then raise exception 'DURATION_INVALID'; end if;
  if p_resolution is not null and char_length(p_resolution)>64 then raise exception 'RESOLUTION_INVALID'; end if;
  if jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))<>'object' or octet_length(coalesce(p_metadata,'{}'::jsonb)::text)>16384 then raise exception 'METADATA_INVALID'; end if;
  if not exists(select 1 from public.tgg_media_vault_assets a where a.id=p_asset_id and a.project_id=p_project_id and a.storage_path=p_storage_path and a.asset_type='video') then raise exception 'RENDER_ASSET_NOT_FOUND_IN_PROJECT'; end if;

  update public.tgg_video_studio_render_jobs
  set status='ready',progress=100,started_at=coalesce(started_at,now()),finished_at=now(),updated_at=now(),error_message=null,
      result_payload=coalesce(result_payload,'{}'::jsonb)||jsonb_build_object('mode','browser_export','asset_id',p_asset_id,'storage_path',p_storage_path,'format',v_format,'aspect_ratio',v_ratio,'resolution',p_resolution,'duration_seconds',p_duration_seconds,'completed_by',v_uid,'completed_at',now())
  where id=p_job_id and project_id=p_project_id
  returning * into v_job;

  select * into v_output from public.tgg_video_studio_render_outputs where render_job_id=p_job_id order by created_at desc limit 1;
  if v_output.id is null then
    insert into public.tgg_video_studio_render_outputs(render_job_id,user_id,format,aspect_ratio,resolution,duration_seconds,storage_path,public_url,status,metadata,created_at,updated_at)
    values(p_job_id,v_uid,v_format,v_ratio,p_resolution,p_duration_seconds,p_storage_path,null,'ready',coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('mode','browser_export','asset_id',p_asset_id,'project_id',p_project_id),now(),now())
    returning * into v_output;
  else
    update public.tgg_video_studio_render_outputs
    set user_id=v_uid,format=v_format,aspect_ratio=v_ratio,resolution=p_resolution,duration_seconds=p_duration_seconds,storage_path=p_storage_path,public_url=null,status='ready',metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('mode','browser_export','asset_id',p_asset_id,'project_id',p_project_id),updated_at=now()
    where id=v_output.id returning * into v_output;
  end if;
  return jsonb_build_object('ok',true,'project_id',p_project_id,'job',to_jsonb(v_job),'output',to_jsonb(v_output));
end;
$function$


-- [40000001342] function public.tgg_video_studio_create_project(p_title text, p_description text, p_aspect_ratio text)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_create_project(p_title text, p_description text DEFAULT NULL::text, p_aspect_ratio text DEFAULT '16:9'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid := gen_random_uuid();
  v_title text := btrim(coalesce(p_title,''));
  v_ratio text := btrim(coalesce(p_aspect_ratio,'16:9'));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(v_title) < 1 or char_length(v_title) > 160 then raise exception 'TITLE_INVALID'; end if;
  if v_ratio not in ('16:9','9:16','1:1','4:5') then raise exception 'ASPECT_RATIO_INVALID'; end if;

  insert into public.tgg_creative_projects(
    id,user_id,project_type,title,description,status,aspect_ratio,settings
  ) values (
    v_id,v_uid,'video',v_title,nullif(btrim(coalesce(p_description,'')),''),'draft',v_ratio,
    jsonb_build_object('schema_version',2,'workspace','video-studio','linked_studio_project_id',v_id)
  );

  insert into public.tgg_studio_projects(
    id,user_id,title,bpm,musical_key,status,project_data,project_type,description,revision,collaboration_enabled
  ) values (
    v_id,v_uid,v_title,120,null,'draft',
    jsonb_build_object('schema_version',2,'workspace','video-studio','linked_creative_project_id',v_id),
    'video',nullif(btrim(coalesce(p_description,'')),''),0,true
  );

  insert into public.tgg_studio_project_members(project_id,user_id,role,can_edit,can_record,can_publish,joined_at,left_at)
  values(v_id,v_uid,'owner',true,true,true,now(),null)
  on conflict(project_id,user_id) do update
    set role='owner',can_edit=true,can_record=true,can_publish=true,left_at=null;

  return jsonb_build_object(
    'ok',true,'project_id',v_id,'title',v_title,'project_type','video','aspect_ratio',v_ratio,'revision',0,
    'permission',jsonb_build_object('role','owner','can_edit',true,'can_record',true,'can_publish',true)
  );
end;
$function$


