-- [40000001348] function public.tgg_video_studio_detach_audio_v1(p_item_id uuid, p_target_track integer, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_detach_audio_v1(p_item_id uuid, p_target_track integer DEFAULT NULL::integer, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_item public.tgg_video_timeline_items; v_asset public.tgg_media_vault_assets; v_audio public.tgg_video_timeline_items;
  v_perm jsonb; v_rev bigint; v_new_rev bigint; v_track integer; v_audio_settings jsonb; v_video_settings jsonb; v_prev_mute boolean:=false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_item from public.tgg_video_timeline_items where id=p_item_id for update;
  if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  if v_item.item_type<>'video' then raise exception 'VIDEO_CLIP_REQUIRED'; end if;
  v_perm:=tgg_private.video_studio_permission(v_item.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select * into v_asset from public.tgg_media_vault_assets where id=v_item.asset_id and project_id=v_item.project_id;
  if v_asset.id is null or lower(coalesce(v_asset.mime_type,'')) not like 'video/%' then raise exception 'VIDEO_ASSET_REQUIRED'; end if;
  select revision into v_rev from public.tgg_studio_projects where id=v_item.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_rev then return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_rev); end if;
  if nullif(v_item.settings->>'detached_audio_item_id','') is not null and exists(select 1 from public.tgg_video_timeline_items t where t.id=(v_item.settings->>'detached_audio_item_id')::uuid) then
    return jsonb_build_object('ok',false,'already_detached',true,'audio_item_id',v_item.settings->>'detached_audio_item_id','current_revision',v_rev);
  end if;
  if p_target_track is null then select coalesce(max(track_index),v_item.track_index)+1 into v_track from public.tgg_video_timeline_items where project_id=v_item.project_id;
  else v_track:=p_target_track; end if;
  if v_track<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  v_prev_mute:=lower(coalesce(v_item.settings->'audio'->>'mute','false'))='true';
  v_audio_settings:=jsonb_set(v_item.settings - 'detached_audio_item_id' - 'detached_audio_previous_mute','{audio}',coalesce(v_item.settings->'audio','{}'::jsonb)||jsonb_build_object('mute',false),true)||jsonb_build_object('detached_from_item_id',v_item.id,'detached_audio_v552',true);

  insert into public.tgg_video_timeline_items(user_id,project_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
  values(v_uid,v_item.project_id,v_item.asset_id,v_track,'audio',v_item.start_seconds,v_item.duration_seconds,v_item.source_in_seconds,v_audio_settings)
  returning * into v_audio;

  insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
  select project_id,v_audio.id,v_uid,parameter,time_seconds,value,easing from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='volume';
  delete from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='volume';

  v_video_settings:=jsonb_set(v_item.settings,'{audio}',coalesce(v_item.settings->'audio','{}'::jsonb)||jsonb_build_object('mute',true),true)||jsonb_build_object('detached_audio_item_id',v_audio.id,'detached_audio_previous_mute',v_prev_mute,'detached_audio_v552',true);
  update public.tgg_video_timeline_items set settings=v_video_settings,updated_at=now() where id=v_item.id;
  update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_new_rev;
  return jsonb_build_object('ok',true,'conflict',false,'video_item_id',v_item.id,'audio_item',to_jsonb(v_audio),'target_track',v_track,'base_revision',v_rev,'project_revision',v_new_rev);
end$function$


-- [40000001349] function public.tgg_video_studio_duplicate_timeline_item(p_item_id uuid, p_offset_seconds numeric)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_duplicate_timeline_item(p_item_id uuid, p_offset_seconds numeric DEFAULT 0.25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_item public.tgg_video_timeline_items; v_new public.tgg_video_timeline_items; v_perm jsonb; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
 if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
 v_perm:=tgg_private.video_studio_permission(v_item.project_id);
 if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 insert into public.tgg_video_timeline_items(project_id,user_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
 values(v_item.project_id,v_uid,v_item.asset_id,v_item.track_index,v_item.item_type,greatest(0,v_item.start_seconds+v_item.duration_seconds+coalesce(p_offset_seconds,0.25)),v_item.duration_seconds,v_item.source_in_seconds,v_item.settings)
 returning * into v_new;
 insert into public.tgg_video_studio_effect_instances(project_id,timeline_item_id,user_id,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled)
 select project_id,v_new.id,v_uid,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled from public.tgg_video_studio_effect_instances where timeline_item_id=v_item.id;
 insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
 select project_id,v_new.id,v_uid,parameter,time_seconds,value,easing from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id;
 insert into public.tgg_video_studio_timeline_actions(project_id,user_id,action_type,target_item_id,start_seconds,duration_seconds,action,source,status)
 values(v_item.project_id,v_uid,'duplicate',v_new.id,v_new.start_seconds,v_new.duration_seconds,jsonb_build_object('source_item_id',v_item.id),'manual','applied');
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_rev;
 update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
 return to_jsonb(v_new)||jsonb_build_object('ok',true,'project_revision',v_rev);
end$function$


-- [40000001350] function public.tgg_video_studio_editor_bundle(p_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_editor_bundle(p_project_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_base jsonb; v_pid uuid; v_perm jsonb;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_base:=public.tgg_video_studio_bundle(p_project_id); v_pid:=nullif(v_base->>'selected_project_id','')::uuid;
 if v_pid is not null then v_perm:=tgg_private.video_studio_permission(v_pid); end if;
 return v_base||jsonb_build_object(
  'editor_schema_version',3,
  'capabilities',jsonb_build_object('split',true,'duplicate',true,'trim',true,'layers',true,'effects',true,'transitions',true,'keyframes',true,'captions',true,'markers',true,'snapshots',true,'restore',coalesce((v_perm->>'is_owner')::boolean,false),'collaboration',true,'render',true,'publishing',true),
  'effects',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(e) order by e.stack_order,e.created_at) from public.tgg_video_studio_effect_instances e where e.project_id=v_pid),'[]'::jsonb) end,
  'keyframes',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(k) order by k.timeline_item_id,k.time_seconds) from public.tgg_video_studio_keyframes k where k.project_id=v_pid),'[]'::jsonb) end,
  'captions',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(c) order by c.start_seconds,c.track_index) from public.tgg_video_studio_caption_cues c where c.project_id=v_pid),'[]'::jsonb) end,
  'markers',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(m) order by m.time_seconds) from public.tgg_video_studio_markers m where m.project_id=v_pid),'[]'::jsonb) end,
  'transitions',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(t) order by t.created_at) from public.tgg_video_studio_transition_instances t where t.project_id=v_pid),'[]'::jsonb) end,
  'versions',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'version_number',v.version_number,'label',v.label,'created_at',v.created_at,'user_id',v.user_id) order by v.version_number desc) from public.tgg_studio_versions v where v.project_id=v_pid limit 50),'[]'::jsonb) end,
  'fx_catalog',coalesce((select jsonb_agg(to_jsonb(f) order by f.sort_order,f.name) from public.tgg_video_studio_fx_catalog f where f.enabled=true),'[]'::jsonb),
  'transition_catalog',coalesce((select jsonb_agg(to_jsonb(t) order by t.sort_order,t.name) from public.tgg_video_studio_transition_catalog t where t.enabled=true),'[]'::jsonb),
  'presets',coalesce((select jsonb_agg(to_jsonb(p) order by p.category,p.name) from public.tgg_video_studio_presets p where p.enabled=true and (p.is_public=true or p.user_id=v_uid)),'[]'::jsonb)
 );
end$function$


-- [40000001351] function public.tgg_video_studio_finalize_asset(p_project_id uuid, p_title text, p_storage_path text, p_mime_type text, p_file_size bigint, p_duration_seconds numeric, p_width integer, p_height integer, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_finalize_asset(p_project_id uuid, p_title text, p_storage_path text, p_mime_type text, p_file_size bigint, p_duration_seconds numeric DEFAULT NULL::numeric, p_width integer DEFAULT NULL::integer, p_height integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_asset_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if p_storage_path is null or p_storage_path !~ ('^'||v_uid::text||'/video/') then raise exception 'INVALID_VIDEO_STORAGE_PATH'; end if;
  if p_mime_type is null or p_mime_type not like 'video/%' then raise exception 'VIDEO_MIME_REQUIRED'; end if;
  if coalesce(p_file_size,0)<=0 or p_file_size>524288000 then raise exception 'INVALID_FILE_SIZE'; end if;
  if p_duration_seconds is not null and (p_duration_seconds<0 or p_duration_seconds>86400) then raise exception 'INVALID_DURATION'; end if;
  if p_width is not null and (p_width<1 or p_width>16384) then raise exception 'INVALID_WIDTH'; end if;
  if p_height is not null and (p_height<1 or p_height>16384) then raise exception 'INVALID_HEIGHT'; end if;
  if jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))<>'object' or octet_length(coalesce(p_metadata,'{}'::jsonb)::text)>16384 then raise exception 'METADATA_INVALID'; end if;
  if not exists(select 1 from public.tgg_pending_media_uploads p where p.user_id=v_uid and p.app_scope='video' and p.storage_bucket='creator-media' and p.storage_path=p_storage_path and p.status='pending') then raise exception 'PENDING_UPLOAD_REQUIRED'; end if;
  if not exists(select 1 from storage.objects o where o.bucket_id='creator-media' and o.name=p_storage_path and (storage.foldername(o.name))[1]=v_uid::text) then raise exception 'UPLOADED_STORAGE_OBJECT_NOT_FOUND'; end if;

  select a.id into v_asset_id from public.tgg_media_vault_assets a where a.project_id=p_project_id and a.storage_path=p_storage_path limit 1;
  if v_asset_id is null then
    insert into public.tgg_media_vault_assets(user_id,project_id,asset_type,title,source_kind,storage_path,mime_type,file_size_bytes,duration_seconds,width,height,metadata)
    values(v_uid,p_project_id,'video',btrim(coalesce(nullif(p_title,''),'Video clip')),'upload',p_storage_path,p_mime_type,p_file_size,p_duration_seconds,p_width,p_height,
      coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('secure_upload',true,'draft_media',true,'uploaded_by',v_uid,'collab_role',v_permission->>'role'))
    returning id into v_asset_id;
  end if;

  update public.tgg_pending_media_uploads set status='finalized',finalized_at=now()
  where user_id=v_uid and storage_bucket='creator-media' and storage_path=p_storage_path;
  return v_asset_id;
end;
$function$


-- [40000001352] function public.tgg_video_studio_mark_render_failed(p_project_id uuid, p_job_id uuid, p_error text)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_mark_render_failed(p_project_id uuid, p_job_id uuid, p_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_job public.tgg_video_studio_render_jobs;
  v_is_owner boolean:=false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  v_is_owner:=coalesce((v_permission->>'is_owner')::boolean,false);
  select * into v_job from public.tgg_video_studio_render_jobs where id=p_job_id and project_id=p_project_id;
  if v_job.id is null then raise exception 'RENDER_JOB_NOT_FOUND'; end if;
  if v_job.user_id<>v_uid and not v_is_owner then raise exception 'RENDER_JOB_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if v_job.status='ready' then raise exception 'READY_RENDER_CANNOT_FAIL'; end if;
  update public.tgg_video_studio_render_jobs
  set status='failed',progress=0,error_message=left(coalesce(nullif(btrim(p_error),''),'render_failed'),500),
      started_at=coalesce(started_at,now()),finished_at=now(),updated_at=now()
  where id=p_job_id and project_id=p_project_id
  returning * into v_job;
  return jsonb_build_object('ok',true,'job',to_jsonb(v_job));
end;
$function$


-- [40000001353] function public.tgg_video_studio_output_library(p_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_output_library(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'allowed')::boolean,false) then raise exception 'PROJECT_NOT_FOUND_OR_NOT_ACCESSIBLE' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'project_id',p_project_id,
    'permission',v_permission,
    'outputs',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',o.id,'job_id',o.job_id,'output_type',o.output_type,'title',o.title,'caption',o.caption,'storage_path',o.storage_path,'metadata',o.metadata,'status',o.status,'created_at',o.created_at,
        'job',jsonb_build_object('aspect_ratio',j.aspect_ratio,'duration_seconds',j.duration_seconds,'status',j.status),
        'asset_id',(select a.id from public.tgg_media_vault_assets a where a.project_id=p_project_id and a.storage_path=o.storage_path and a.asset_type='video' order by a.created_at desc limit 1),
        'publications',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'destination_type',p.destination_type,'destination_id',p.destination_id,'status',p.status,'expires_at',p.expires_at,'public_url','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-media-operations?public_output=1&key='||p.public_key::text) order by p.created_at desc) from public.tgg_video_studio_social_publications p where p.output_id=o.id),'[]'::jsonb)
      ) order by o.created_at desc)
      from public.tgg_video_studio_repurpose_outputs o
      join public.tgg_content_repurpose_jobs j on j.id=o.job_id
      where j.project_id=p_project_id and o.status='ready'
    ),'[]'::jsonb),
    'generated_at',now()
  );
end;
$function$


-- [40000001354] function public.tgg_video_studio_overwrite_asset_v1(p_project_id uuid, p_asset_id uuid, p_track_index integer, p_start_seconds numeric, p_duration_seconds numeric, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_overwrite_asset_v1(p_project_id uuid, p_asset_id uuid, p_track_index integer DEFAULT 0, p_start_seconds numeric DEFAULT 0, p_duration_seconds numeric DEFAULT NULL::numeric, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_perm jsonb;
  v_asset public.tgg_media_vault_assets;
  v_rev bigint;
  v_new_rev bigint;
  v_start numeric:=greatest(0,coalesce(p_start_seconds,0));
  v_duration numeric;
  v_end numeric;
  v_type text;
  v_old public.tgg_video_timeline_items;
  v_right public.tgg_video_timeline_items;
  v_old_start numeric;
  v_old_end numeric;
  v_left_duration numeric;
  v_right_duration numeric;
  v_offset numeric;
  v_speed numeric:=1;
  v_deleted integer:=0;
  v_trimmed integer:=0;
  v_split integer:=0;
  v_transitions integer:=0;
  v_rc integer:=0;
  v_item public.tgg_video_timeline_items;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if coalesce(p_track_index,-1)<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  v_perm:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;

  select * into v_asset from public.tgg_media_vault_assets where id=p_asset_id and project_id=p_project_id;
  if v_asset.id is null then raise exception 'ASSET_NOT_FOUND_IN_PROJECT'; end if;
  v_type:=case when lower(coalesce(v_asset.mime_type,'')) like 'audio/%' then 'audio'
               when lower(coalesce(v_asset.mime_type,'')) like 'image/%' then 'image'
               else 'video' end;
  v_duration:=coalesce(p_duration_seconds,v_asset.duration_seconds,case when v_type='image' then 5 else null end);
  if v_duration is null or v_duration<=0 then raise exception 'ASSET_DURATION_REQUIRED'; end if;
  if v_type in ('audio','video') and v_asset.duration_seconds is not null and v_duration>v_asset.duration_seconds+.05 then
    raise exception 'DURATION_EXCEEDS_ASSET';
  end if;
  v_end:=v_start+v_duration;

  select revision into v_rev from public.tgg_studio_projects where id=p_project_id for update;
  if v_rev is null then raise exception 'PROJECT_NOT_FOUND'; end if;
  if p_base_revision is not null and p_base_revision<>v_rev then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_rev);
  end if;

  if exists(
    select 1
    from public.tgg_video_timeline_items t
    join public.tgg_video_studio_keyframes k on k.timeline_item_id=t.id and k.parameter='speed'
    where t.project_id=p_project_id and t.track_index=p_track_index
      and t.start_seconds<v_end and t.start_seconds+t.duration_seconds>v_start
      and t.start_seconds+t.duration_seconds>v_end
  ) then
    return jsonb_build_object('ok',false,'unsupported',true,'reason','SPEED_RAMP_OVERWRITE_SPLIT_FIRST','current_revision',v_rev);
  end if;

  for v_old in
    select * from public.tgg_video_timeline_items
    where project_id=p_project_id and track_index=p_track_index
      and start_seconds<v_end and start_seconds+duration_seconds>v_start
    order by start_seconds,id
    for update
  loop
    v_old_start:=v_old.start_seconds;
    v_old_end:=v_old.start_seconds+v_old.duration_seconds;
    v_speed:=1;
    if coalesce(v_old.settings#>>'{editor_state,speed}','') ~ '^[0-9]+([.][0-9]+)?$' then
      v_speed:=greatest(.1,least(4,(v_old.settings#>>'{editor_state,speed}')::numeric/100));
    end if;

    delete from public.tgg_video_studio_transition_instances
     where from_item_id=v_old.id or to_item_id=v_old.id;
    get diagnostics v_rc=row_count;
    v_transitions:=v_transitions+v_rc;

    if v_old_start<v_start and v_old_end>v_end then
      v_left_duration:=v_start-v_old_start;
      v_right_duration:=v_old_end-v_end;
      v_offset:=v_end-v_old_start;

      insert into public.tgg_video_timeline_items(project_id,user_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
      values(v_old.project_id,v_uid,v_old.asset_id,v_old.track_index,v_old.item_type,v_end,v_right_duration,
        v_old.source_in_seconds+(v_offset*v_speed),v_old.settings)
      returning * into v_right;

      insert into public.tgg_video_studio_effect_instances(project_id,timeline_item_id,user_id,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled)
      select e.project_id,v_right.id,v_uid,e.effect_catalog_id,e.effect_type,e.stack_order,
        case when e.start_seconds is null then null else greatest(0,e.start_seconds-v_offset) end,
        case when e.duration_seconds is null then null else
          greatest(0,least(v_right_duration,e.start_seconds+e.duration_seconds-v_offset)-greatest(0,e.start_seconds-v_offset)) end,
        e.settings,e.enabled
      from public.tgg_video_studio_effect_instances e
      where e.timeline_item_id=v_old.id
        and (e.start_seconds is null or e.duration_seconds is null or e.start_seconds+e.duration_seconds>v_offset)
        and (e.start_seconds is null or e.start_seconds<v_offset+v_right_duration);
      delete from public.tgg_video_studio_effect_instances where timeline_item_id=v_right.id and duration_seconds is not null and duration_seconds<=0;

      insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
      select k.project_id,v_right.id,v_uid,k.parameter,k.time_seconds-v_offset,k.value,k.easing
      from public.tgg_video_studio_keyframes k
      where k.timeline_item_id=v_old.id and k.time_seconds>=v_offset and k.time_seconds<=v_offset+v_right_duration;

      update public.tgg_video_timeline_items set duration_seconds=v_left_duration,updated_at=now() where id=v_old.id;
      delete from public.tgg_video_studio_effect_instances where timeline_item_id=v_old.id and start_seconds is not null and start_seconds>=v_left_duration;
      update public.tgg_video_studio_effect_instances set duration_seconds=greatest(0,least(duration_seconds,v_left_duration-start_seconds)),updated_at=now()
       where timeline_item_id=v_old.id and start_seconds is not null and duration_seconds is not null and start_seconds<v_left_duration and start_seconds+duration_seconds>v_left_duration;
      delete from public.tgg_video_studio_keyframes where timeline_item_id=v_old.id and time_seconds>v_left_duration;
      v_split:=v_split+1;

    elsif v_old_start<v_start and v_old_end>v_start then
      v_left_duration:=v_start-v_old_start;
      update public.tgg_video_timeline_items set duration_seconds=v_left_duration,updated_at=now() where id=v_old.id;
      delete from public.tgg_video_studio_effect_instances where timeline_item_id=v_old.id and start_seconds is not null and start_seconds>=v_left_duration;
      update public.tgg_video_studio_effect_instances set duration_seconds=greatest(0,least(duration_seconds,v_left_duration-start_seconds)),updated_at=now()
       where timeline_item_id=v_old.id and start_seconds is not null and duration_seconds is not null and start_seconds<v_left_duration and start_seconds+duration_seconds>v_left_duration;
      delete from public.tgg_video_studio_keyframes where timeline_item_id=v_old.id and time_seconds>v_left_duration;
      v_trimmed:=v_trimmed+1;

    elsif v_old_start>=v_start and v_old_end<=v_end then
      delete from public.tgg_video_timeline_items where id=v_old.id;
      v_deleted:=v_deleted+1;

    elsif v_old_start<v_end and v_old_end>v_end then
      v_offset:=v_end-v_old_start;
      v_right_duration:=v_old_end-v_end;

      delete from public.tgg_video_studio_effect_instances
       where timeline_item_id=v_old.id and start_seconds is not null and duration_seconds is not null and start_seconds+duration_seconds<=v_offset;
      update public.tgg_video_studio_effect_instances
         set start_seconds=greatest(0,start_seconds-v_offset),
             duration_seconds=case when duration_seconds is null then null else
               greatest(0,least(v_right_duration,start_seconds+duration_seconds-v_offset)-greatest(0,start_seconds-v_offset)) end,
             updated_at=now()
       where timeline_item_id=v_old.id and start_seconds is not null;
      delete from public.tgg_video_studio_effect_instances where timeline_item_id=v_old.id and duration_seconds is not null and duration_seconds<=0;
      delete from public.tgg_video_studio_keyframes where timeline_item_id=v_old.id and time_seconds<v_offset;
      update public.tgg_video_studio_keyframes set time_seconds=time_seconds-v_offset,updated_at=now() where timeline_item_id=v_old.id;
      update public.tgg_video_timeline_items
         set start_seconds=v_end,duration_seconds=v_right_duration,
             source_in_seconds=v_old.source_in_seconds+(v_offset*v_speed),updated_at=now()
       where id=v_old.id;
      v_trimmed:=v_trimmed+1;
    end if;
  end loop;

  insert into public.tgg_video_timeline_items(user_id,project_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
  values(v_uid,p_project_id,v_asset.id,p_track_index,v_type,v_start,v_duration,0,
    jsonb_build_object('source','media-bin-v551','placement_mode','overwrite','asset_id',v_asset.id,'schema_version',5))
  returning * into v_item;

  update public.tgg_creative_projects set updated_at=now() where id=p_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now()
   where id=p_project_id returning revision into v_new_rev;

  return jsonb_build_object('ok',true,'conflict',false,'item',to_jsonb(v_item),'deleted_items',v_deleted,
    'trimmed_items',v_trimmed,'split_items',v_split,'removed_transitions',v_transitions,
    'base_revision',v_rev,'project_revision',v_new_rev);
end$function$


-- [40000001355] function public.tgg_video_studio_place_asset_range_v1(p_project_id uuid, p_asset_id uuid, p_track_index integer, p_start_seconds numeric, p_source_in_seconds numeric, p_duration_seconds numeric, p_mode text, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_place_asset_range_v1(p_project_id uuid, p_asset_id uuid, p_track_index integer DEFAULT 0, p_start_seconds numeric DEFAULT 0, p_source_in_seconds numeric DEFAULT 0, p_duration_seconds numeric DEFAULT NULL::numeric, p_mode text DEFAULT 'overlay'::text, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_asset public.tgg_media_vault_assets;
  v_revision bigint;
  v_new_revision bigint;
  v_start numeric;
  v_source_in numeric:=greatest(0,coalesce(p_source_in_seconds,0));
  v_duration numeric;
  v_mode text:=lower(btrim(coalesce(p_mode,'overlay')));
  v_type text;
  v_item public.tgg_video_timeline_items;
  v_shifted integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if coalesce(p_track_index,-1)<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  if v_mode not in ('overlay','append','insert') then raise exception 'PLACEMENT_MODE_INVALID'; end if;

  select * into v_asset from public.tgg_media_vault_assets where id=p_asset_id and project_id=p_project_id;
  if v_asset.id is null then raise exception 'ASSET_NOT_FOUND_IN_PROJECT'; end if;

  select revision into v_revision from public.tgg_studio_projects where id=p_project_id for update;
  if v_revision is null then raise exception 'PROJECT_NOT_FOUND'; end if;
  if p_base_revision is not null and p_base_revision<>v_revision then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_revision);
  end if;

  v_type:=case
    when lower(coalesce(v_asset.mime_type,'')) like 'audio/%' then 'audio'
    when lower(coalesce(v_asset.mime_type,'')) like 'image/%' then 'image'
    else 'video'
  end;

  if v_type='image' then
    if v_source_in<>0 then raise exception 'IMAGE_SOURCE_IN_INVALID'; end if;
    v_duration:=coalesce(p_duration_seconds,5);
  else
    if v_asset.duration_seconds is not null and v_source_in>=v_asset.duration_seconds then raise exception 'SOURCE_IN_OUT_OF_RANGE'; end if;
    v_duration:=coalesce(p_duration_seconds,
      case when v_asset.duration_seconds is not null then v_asset.duration_seconds-v_source_in else null end);
  end if;

  if v_duration is null or v_duration<=0 then raise exception 'SOURCE_RANGE_DURATION_REQUIRED'; end if;
  if v_asset.duration_seconds is not null and v_source_in+v_duration>v_asset.duration_seconds+0.02 then raise exception 'SOURCE_RANGE_EXCEEDS_ASSET'; end if;

  if v_mode='append' then
    select coalesce(max(start_seconds+duration_seconds),0) into v_start
    from public.tgg_video_timeline_items
    where project_id=p_project_id and track_index=p_track_index;
  else
    v_start:=greatest(0,coalesce(p_start_seconds,0));
  end if;

  if v_mode='insert' then
    if exists(
      select 1 from public.tgg_video_timeline_items
      where project_id=p_project_id and track_index=p_track_index
        and start_seconds<v_start and start_seconds+duration_seconds>v_start
    ) then
      return jsonb_build_object('ok',false,'occupied',true,'reason','INSERT_POINT_INSIDE_CLIP_SPLIT_FIRST','current_revision',v_revision);
    end if;
    update public.tgg_video_timeline_items
    set start_seconds=start_seconds+v_duration,updated_at=now()
    where project_id=p_project_id and track_index=p_track_index and start_seconds>=v_start;
    get diagnostics v_shifted=row_count;
  end if;

  insert into public.tgg_video_timeline_items(
    user_id,project_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings
  ) values (
    v_uid,p_project_id,v_asset.id,p_track_index,v_type,v_start,v_duration,v_source_in,
    jsonb_build_object('source','source-monitor-v554','placement_mode',v_mode,'asset_id',v_asset.id,'source_range',jsonb_build_object('in',v_source_in,'duration',v_duration),'schema_version',7)
  ) returning * into v_item;

  update public.tgg_creative_projects set updated_at=now() where id=p_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_new_revision;

  return jsonb_build_object('ok',true,'conflict',false,'occupied',false,'item',to_jsonb(v_item),'shifted_items',v_shifted,'base_revision',v_revision,'project_revision',v_new_revision);
end
$function$


-- [40000001356] function public.tgg_video_studio_place_asset_v2(p_project_id uuid, p_asset_id uuid, p_track_index integer, p_start_seconds numeric, p_mode text, p_base_revision bigint, p_duration_seconds numeric)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_place_asset_v2(p_project_id uuid, p_asset_id uuid, p_track_index integer DEFAULT 0, p_start_seconds numeric DEFAULT 0, p_mode text DEFAULT 'overlay'::text, p_base_revision bigint DEFAULT NULL::bigint, p_duration_seconds numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_asset public.tgg_media_vault_assets;
  v_revision bigint;
  v_new_revision bigint;
  v_start numeric;
  v_duration numeric;
  v_mode text:=lower(btrim(coalesce(p_mode,'overlay')));
  v_type text;
  v_item public.tgg_video_timeline_items;
  v_shifted integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if coalesce(p_track_index,-1)<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  if v_mode not in ('overlay','append','insert') then raise exception 'PLACEMENT_MODE_INVALID'; end if;

  select * into v_asset from public.tgg_media_vault_assets where id=p_asset_id and project_id=p_project_id;
  if v_asset.id is null then raise exception 'ASSET_NOT_FOUND_IN_PROJECT'; end if;

  select revision into v_revision from public.tgg_studio_projects where id=p_project_id for update;
  if v_revision is null then raise exception 'PROJECT_NOT_FOUND'; end if;
  if p_base_revision is not null and p_base_revision<>v_revision then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_revision);
  end if;

  v_type:=case
    when lower(coalesce(v_asset.mime_type,'')) like 'audio/%' then 'audio'
    when lower(coalesce(v_asset.mime_type,'')) like 'image/%' then 'image'
    else 'video'
  end;
  v_duration:=coalesce(p_duration_seconds,v_asset.duration_seconds,case when v_type='image' then 5 else null end);
  if v_duration is null or v_duration<=0 then raise exception 'ASSET_DURATION_REQUIRED'; end if;

  if v_mode='append' then
    select coalesce(max(start_seconds+duration_seconds),0) into v_start
    from public.tgg_video_timeline_items
    where project_id=p_project_id and track_index=p_track_index;
  else
    v_start:=greatest(0,coalesce(p_start_seconds,0));
  end if;

  if v_mode='insert' then
    if exists(
      select 1 from public.tgg_video_timeline_items
      where project_id=p_project_id
        and track_index=p_track_index
        and start_seconds<v_start
        and start_seconds+duration_seconds>v_start
    ) then
      return jsonb_build_object('ok',false,'occupied',true,'reason','INSERT_POINT_INSIDE_CLIP_SPLIT_FIRST','current_revision',v_revision);
    end if;
    update public.tgg_video_timeline_items
    set start_seconds=start_seconds+v_duration,updated_at=now()
    where project_id=p_project_id
      and track_index=p_track_index
      and start_seconds>=v_start;
    get diagnostics v_shifted=row_count;
  end if;

  insert into public.tgg_video_timeline_items(
    user_id,project_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings
  ) values (
    v_uid,p_project_id,v_asset.id,p_track_index,v_type,v_start,v_duration,0,
    jsonb_build_object('source','media-bin-v550','placement_mode',v_mode,'asset_id',v_asset.id,'schema_version',4)
  ) returning * into v_item;

  update public.tgg_creative_projects set updated_at=now() where id=p_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_new_revision;

  return jsonb_build_object('ok',true,'conflict',false,'occupied',false,'item',to_jsonb(v_item),'shifted_items',v_shifted,'base_revision',v_revision,'project_revision',v_new_revision);
end$function$


-- [40000001357] function public.tgg_video_studio_publish_output(p_project_id uuid, p_output_id uuid, p_destination text, p_caption text, p_visibility text)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_publish_output(p_project_id uuid, p_output_id uuid, p_destination text, p_caption text DEFAULT NULL::text, p_visibility text DEFAULT 'public'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_dest text:=lower(btrim(coalesce(p_destination,'')));
  v_audit_dest text;
  v_visibility text:=lower(btrim(coalesce(nullif(p_visibility,''),'public')));
  v_output public.tgg_video_studio_repurpose_outputs;
  v_job public.tgg_content_repurpose_jobs;
  v_pub public.tgg_video_studio_social_publications;
  v_media public.tgg_media_vault_assets;
  v_url text;
  v_result jsonb;
  v_destination_id uuid;
  v_expires timestamptz;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_publish')::boolean,false) then raise exception 'PUBLISH_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if v_dest not in ('short','story') then raise exception 'DESTINATION_INVALID'; end if;
  v_audit_dest:=case v_dest when 'short' then 'shorts' when 'story' then 'stories' end;
  if v_visibility not in ('public','unlisted','private') then raise exception 'VISIBILITY_INVALID'; end if;
  if p_caption is not null and char_length(p_caption)>2000 then raise exception 'CAPTION_TOO_LONG'; end if;

  select o.* into v_output
  from public.tgg_video_studio_repurpose_outputs o
  join public.tgg_content_repurpose_jobs j on j.id=o.job_id
  where o.id=p_output_id and j.project_id=p_project_id and o.status='ready' and j.status='ready';
  if v_output.id is null then raise exception 'READY_OUTPUT_NOT_FOUND_IN_PROJECT'; end if;

  select * into v_job from public.tgg_content_repurpose_jobs where id=v_output.job_id and project_id=p_project_id;
  if v_output.storage_path is null or btrim(v_output.storage_path)='' then raise exception 'OUTPUT_STORAGE_PATH_REQUIRED'; end if;

  select * into v_media
  from public.tgg_media_vault_assets a
  where a.project_id=p_project_id
    and a.storage_path=v_output.storage_path
    and a.asset_type='video'
  order by a.created_at desc
  limit 1;
  if v_media.id is null then raise exception 'OUTPUT_MEDIA_ASSET_NOT_FOUND'; end if;

  select * into v_pub
  from public.tgg_video_studio_social_publications
  where output_id=p_output_id and destination_type=v_dest
  for update;

  if v_pub.id is not null and v_pub.status='active' and v_pub.destination_id is not null then
    return jsonb_build_object('ok',true,'already_published',true,'publication_id',v_pub.id,'destination_type',v_pub.destination_type,'destination_id',v_pub.destination_id,'public_url','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-media-operations?public_output=1&key='||v_pub.public_key::text,'expires_at',v_pub.expires_at);
  end if;

  if v_pub.id is null then
    insert into public.tgg_video_studio_social_publications(project_id,output_id,user_id,destination_type,storage_path,status,metadata)
    values(p_project_id,p_output_id,v_uid,v_dest,v_output.storage_path,'pending',jsonb_build_object('output_type',v_output.output_type,'asset_id',v_media.id,'source','video-studio'))
    returning * into v_pub;
  else
    update public.tgg_video_studio_social_publications
    set user_id=v_uid,project_id=p_project_id,storage_path=v_output.storage_path,status='pending',destination_id=null,expires_at=null,public_key=gen_random_uuid(),updated_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('asset_id',v_media.id,'republished_at',now())
    where id=v_pub.id
    returning * into v_pub;
  end if;

  v_url:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-media-operations?public_output=1&key='||v_pub.public_key::text;

  begin
    if v_dest='short' then
      v_result:=public.tgg_short_create_draft(
        coalesce(nullif(btrim(coalesce(p_caption,'')),''),v_output.caption,v_output.title),
        v_url,
        null,
        null,
        v_visibility,
        v_job.duration_seconds
      );
      v_destination_id:=(v_result->>'short_id')::uuid;
      perform public.tgg_short_set_published(v_destination_id,true);
      v_expires:=null;
    else
      v_result:=public.tgg_story_create(
        'video',
        coalesce(nullif(btrim(coalesce(p_caption,'')),''),v_output.caption,v_output.title),
        v_url,
        null
      );
      v_destination_id:=(v_result->>'story_id')::uuid;
      v_expires:=(v_result->>'expires_at')::timestamptz;
    end if;

    update public.tgg_video_studio_social_publications
    set destination_id=v_destination_id,status='active',expires_at=v_expires,updated_at=now(),metadata=metadata||jsonb_build_object('published_at',now(),'visibility',v_visibility)
    where id=v_pub.id
    returning * into v_pub;

    insert into public.tgg_video_publish_jobs(project_id,user_id,destination_type,destination_id,payload,status,error_message,published_at,created_at,updated_at)
    values(p_project_id,v_uid,v_audit_dest,v_destination_id,jsonb_build_object('output_id',p_output_id,'publication_id',v_pub.id,'public_url',v_url,'output_type',v_output.output_type),'published',null,now(),now(),now());
  exception when others then
    update public.tgg_video_studio_social_publications
    set status='failed',metadata=metadata||jsonb_build_object('last_error',sqlerrm,'failed_at',now()),updated_at=now()
    where id=v_pub.id;
    raise;
  end;

  return jsonb_build_object('ok',true,'already_published',false,'publication_id',v_pub.id,'destination_type',v_dest,'destination_id',v_destination_id,'public_url',v_url,'expires_at',v_expires);
end;
$function$


-- [40000001358] function public.tgg_video_studio_queue_render(p_project_id uuid, p_output_format text, p_output_preset text, p_job_type text, p_request_payload jsonb)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_queue_render(p_project_id uuid, p_output_format text DEFAULT 'mp4'::text, p_output_preset text DEFAULT '1080p'::text, p_job_type text DEFAULT 'master'::text, p_request_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_permission jsonb; v_job public.tgg_video_studio_render_jobs; v_revision bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select revision into v_revision from public.tgg_studio_projects where id=p_project_id and project_type='video';
  if lower(btrim(coalesce(p_output_format,''))) not in ('mp4','webm','mov') then raise exception 'OUTPUT_FORMAT_INVALID'; end if;
  if lower(btrim(coalesce(p_job_type,''))) not in ('master','preview','short','social') then raise exception 'JOB_TYPE_INVALID'; end if;
  insert into public.tgg_video_studio_render_jobs(project_id,user_id,job_type,output_format,output_preset,source_revision,request_payload,status,progress)
  values(p_project_id,v_uid,lower(btrim(p_job_type)),lower(btrim(p_output_format)),btrim(coalesce(p_output_preset,'1080p')),coalesce(v_revision,0),coalesce(p_request_payload,'{}'::jsonb),'queued',0) returning * into v_job;
  return to_jsonb(v_job);
end;
$function$


-- [40000001359] function public.tgg_video_studio_queue_transcode_v1(p_project_id uuid, p_asset_id uuid, p_output_preset text, p_output_format text)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_queue_transcode_v1(p_project_id uuid, p_asset_id uuid, p_output_preset text DEFAULT '1080p'::text, p_output_format text DEFAULT 'mp4'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_perm jsonb;
  v_asset public.tgg_media_vault_assets;
  v_job public.tgg_video_studio_render_jobs;
  v_rev bigint;
  v_preset text:=lower(btrim(coalesce(p_output_preset,'1080p')));
  v_format text:=lower(btrim(coalesce(p_output_format,'mp4')));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_perm:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if v_format<>'mp4' then raise exception 'TRANSCODE_FORMAT_UNSUPPORTED'; end if;
  if v_preset not in ('720p','1080p','2160p','source') then raise exception 'TRANSCODE_PRESET_INVALID'; end if;
  select * into v_asset from public.tgg_media_vault_assets where id=p_asset_id and project_id=p_project_id and asset_type='video';
  if v_asset.id is null or nullif(btrim(coalesce(v_asset.storage_path,'')),'') is null then raise exception 'TRANSCODE_SOURCE_ASSET_INVALID'; end if;
  select coalesce(revision,0) into v_rev from public.tgg_studio_projects where id=p_project_id and project_type='video';
  if v_rev is null then raise exception 'PROJECT_NOT_FOUND'; end if;

  select * into v_job
  from public.tgg_video_studio_render_jobs j
  where j.project_id=p_project_id
    and j.user_id=v_uid
    and j.output_format='mp4'
    and j.output_preset=v_preset
    and j.source_revision=v_rev
    and j.status in ('queued','processing','ready')
    and coalesce(j.request_payload->>'mode','')='master_transcode'
    and j.request_payload->>'source_asset_id'=p_asset_id::text
  order by j.created_at desc
  limit 1;
  if v_job.id is not null then
    return to_jsonb(v_job)||jsonb_build_object('idempotent_reuse',true);
  end if;

  insert into public.tgg_video_studio_render_jobs(project_id,user_id,job_type,output_format,output_preset,source_revision,request_payload,status,progress,priority)
  values(
    p_project_id,v_uid,'master',v_format,v_preset,v_rev,
    jsonb_build_object(
      'mode','master_transcode','schema_version',7,
      'source_asset_id',v_asset.id,
      'source_storage_path',v_asset.storage_path,
      'source_mime_type',v_asset.mime_type,
      'source_duration_seconds',v_asset.duration_seconds,
      'source_width',v_asset.width,
      'source_height',v_asset.height,
      'storage_bucket','creator-media'
    ),'queued',0,50
  ) returning * into v_job;
  return to_jsonb(v_job)||jsonb_build_object('idempotent_reuse',false);
end$function$


-- [40000001360] function public.tgg_video_studio_reattach_audio_v1(p_audio_item_id uuid, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_reattach_audio_v1(p_audio_item_id uuid, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_audio public.tgg_video_timeline_items; v_video public.tgg_video_timeline_items; v_video_id uuid;
  v_perm jsonb; v_rev bigint; v_new_rev bigint; v_mix jsonb; v_settings jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_audio from public.tgg_video_timeline_items where id=p_audio_item_id for update;
  if v_audio.id is null or v_audio.item_type<>'audio' then raise exception 'DETACHED_AUDIO_CLIP_REQUIRED'; end if;
  if nullif(v_audio.settings->>'detached_from_item_id','') is null then raise exception 'DETACHED_AUDIO_RELATION_MISSING'; end if;
  v_video_id:=(v_audio.settings->>'detached_from_item_id')::uuid;
  select * into v_video from public.tgg_video_timeline_items where id=v_video_id for update;
  if v_video.id is null or v_video.project_id<>v_audio.project_id or v_video.item_type<>'video' then raise exception 'SOURCE_VIDEO_CLIP_MISSING'; end if;
  v_perm:=tgg_private.video_studio_permission(v_audio.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select revision into v_rev from public.tgg_studio_projects where id=v_audio.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_rev then return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_rev); end if;
  if abs(v_audio.start_seconds-v_video.start_seconds)>.001 or abs(v_audio.duration_seconds-v_video.duration_seconds)>.001 or abs(v_audio.source_in_seconds-v_video.source_in_seconds)>.001 then
    return jsonb_build_object('ok',false,'timing_changed',true,'reason','DETACHED_AUDIO_TIMING_CHANGED_KEEP_SEPARATE','current_revision',v_rev);
  end if;

  v_mix:=coalesce(v_audio.settings->'audio','{}'::jsonb);
  v_settings:=jsonb_set(v_video.settings - 'detached_audio_item_id' - 'detached_audio_previous_mute','{audio}',v_mix,true);
  update public.tgg_video_timeline_items set settings=v_settings,updated_at=now() where id=v_video.id;
  delete from public.tgg_video_studio_keyframes where timeline_item_id=v_video.id and parameter='volume';
  insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
  select project_id,v_video.id,v_uid,parameter,time_seconds,value,easing from public.tgg_video_studio_keyframes where timeline_item_id=v_audio.id and parameter='volume';
  delete from public.tgg_video_timeline_items where id=v_audio.id;
  update public.tgg_creative_projects set updated_at=now() where id=v_video.project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_video.project_id returning revision into v_new_rev;
  return jsonb_build_object('ok',true,'conflict',false,'video_item_id',v_video.id,'removed_audio_item_id',v_audio.id,'base_revision',v_rev,'project_revision',v_new_rev);
end$function$


-- [40000001361] function public.tgg_video_studio_remove_effect(p_effect_instance_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_remove_effect(p_effect_instance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
