 v_perm:=tgg_private.video_studio_permission(v_pid); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 delete from public.tgg_video_studio_effect_instances where id=p_effect_instance_id;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_pid returning revision into v_rev;
