-- [40000001363] function public.tgg_video_studio_render_readiness(p_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_render_readiness(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_provider_key text;
  v_provider_status text;
  v_provider_endpoint text;
  v_has_provider_secret boolean:=false;
  v_external_connected boolean:=false;
  v_worker private.tgg_video_render_worker_runtime;
  v_worker_live boolean:=false;
  v_connected boolean:=false;
  v_revision bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'allowed')::boolean,false) then raise exception 'PROJECT_ACCESS_REQUIRED' using errcode='42501'; end if;
  select revision into v_revision from public.tgg_studio_projects where id=p_project_id;

  select s.provider_key,s.status,s.endpoint_url into v_provider_key,v_provider_status,v_provider_endpoint
  from private.tgg_provider_activation_staging s
  where s.status='verified' and s.endpoint_url is not null and (
    lower(s.provider_key) like '%transcod%' or lower(s.provider_key) like '%render%' or lower(s.provider_key) like '%mux%' or lower(s.provider_key) like '%video.processing%' or lower(s.provider_key) like '%media.processing%'
  ) order by s.updated_at desc limit 1;
  if v_provider_key is not null then
    select exists(select 1 from private.tgg_provider_secret_registry r where r.provider_key=v_provider_key and r.status in ('stored','verified','active')) into v_has_provider_secret;
  end if;
  v_external_connected:=v_provider_key is not null and v_provider_status='verified' and v_provider_endpoint is not null and v_has_provider_secret;

  select * into v_worker from private.tgg_video_render_worker_runtime w
  where w.status='online' and w.last_seen_at>now()-interval '12 minutes' and coalesce((w.capabilities->>'mp4')::boolean,false)
  order by w.last_seen_at desc limit 1;
  v_worker_live:=v_worker.worker_key is not null;
  v_connected:=v_external_connected or v_worker_live;

  return jsonb_build_object(
    'ok',true,'project_id',p_project_id,'project_revision',coalesce(v_revision,0),
    'browser_master_webm',true,'browser_mp4_negotiated',true,'private_signed_media',true,'multi_track_compositor',true,'realtime_collaboration',true,
    'worker_queue_contract',true,'worker_manifest_schema_version',6,'master_transcode_request_schema_version',7,
    'server_transcoder_connected',v_connected,'server_mp4_available',v_connected,
    'provider',case
      when v_worker_live then jsonb_build_object('provider_key',v_worker.provider_key,'status','online','worker_key',v_worker.worker_key,'last_seen_at',v_worker.last_seen_at,'capabilities',v_worker.capabilities,'credential_verified_by_checkin',true)
      when v_external_connected then jsonb_build_object('provider_key',v_provider_key,'status',v_provider_status,'endpoint_configured',true,'secret_configured',true)
      when v_provider_key is not null then jsonb_build_object('provider_key',v_provider_key,'status',v_provider_status,'endpoint_configured',v_provider_endpoint is not null,'secret_configured',v_has_provider_secret)
      else null end,
    'queue_policy',jsonb_build_object('max_attempts',3,'lease_seconds_default',300,'stale_revision_guard',true),
    'recommended_export',case when v_connected then 'server_mp4' else 'browser_best' end
  );
end$function$


-- [40000001364] function public.tgg_video_studio_restore_version(p_project_id uuid, p_version_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_restore_version(p_project_id uuid, p_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_snap jsonb; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'is_owner')::boolean,false) then raise exception 'OWNER_REQUIRED' using errcode='42501'; end if;
 select snapshot into v_snap from public.tgg_studio_versions where id=p_version_id and project_id=p_project_id; if v_snap is null then raise exception 'VERSION_NOT_FOUND'; end if;
 delete from public.tgg_video_studio_keyframes where project_id=p_project_id;
 delete from public.tgg_video_studio_effect_instances where project_id=p_project_id;
 delete from public.tgg_video_studio_transition_instances where project_id=p_project_id;
 delete from public.tgg_video_studio_caption_cues where project_id=p_project_id;
 delete from public.tgg_video_studio_markers where project_id=p_project_id;
 delete from public.tgg_video_timeline_items where project_id=p_project_id;
 if jsonb_typeof(v_snap->'timeline_items')='array' then insert into public.tgg_video_timeline_items select * from jsonb_populate_recordset(null::public.tgg_video_timeline_items,v_snap->'timeline_items'); end if;
 if jsonb_typeof(v_snap->'effects')='array' then insert into public.tgg_video_studio_effect_instances select * from jsonb_populate_recordset(null::public.tgg_video_studio_effect_instances,v_snap->'effects'); end if;
 if jsonb_typeof(v_snap->'keyframes')='array' then insert into public.tgg_video_studio_keyframes select * from jsonb_populate_recordset(null::public.tgg_video_studio_keyframes,v_snap->'keyframes'); end if;
 if jsonb_typeof(v_snap->'captions')='array' then insert into public.tgg_video_studio_caption_cues select * from jsonb_populate_recordset(null::public.tgg_video_studio_caption_cues,v_snap->'captions'); end if;
 if jsonb_typeof(v_snap->'markers')='array' then insert into public.tgg_video_studio_markers select * from jsonb_populate_recordset(null::public.tgg_video_studio_markers,v_snap->'markers'); end if;
 if jsonb_typeof(v_snap->'transitions')='array' then insert into public.tgg_video_studio_transition_instances select * from jsonb_populate_recordset(null::public.tgg_video_studio_transition_instances,v_snap->'transitions'); end if;
 if v_snap?'creative_project' then update public.tgg_creative_projects set title=coalesce(v_snap->'creative_project'->>'title',title),description=v_snap->'creative_project'->>'description',status=coalesce(v_snap->'creative_project'->>'status',status),aspect_ratio=v_snap->'creative_project'->>'aspect_ratio',duration_seconds=nullif(v_snap->'creative_project'->>'duration_seconds','')::numeric,settings=coalesce(v_snap->'creative_project'->'settings',settings),updated_at=now() where id=p_project_id; end if;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return jsonb_build_object('ok',true,'project_id',p_project_id,'version_id',p_version_id,'project_revision',v_rev);
end$function$


-- [40000001365] function public.tgg_video_studio_revoke_output_publication(p_project_id uuid, p_publication_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_revoke_output_publication(p_project_id uuid, p_publication_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_pub public.tgg_video_studio_social_publications;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_publish')::boolean,false) then raise exception 'PUBLISH_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select * into v_pub from public.tgg_video_studio_social_publications where id=p_publication_id and project_id=p_project_id for update;
  if v_pub.id is null then raise exception 'PUBLICATION_NOT_FOUND'; end if;

  if v_pub.destination_type='short' and v_pub.destination_id is not null then
    perform public.tgg_short_set_published(v_pub.destination_id,false);
  elsif v_pub.destination_type='story' and v_pub.destination_id is not null then
    perform public.tgg_story_delete(v_pub.destination_id);
  end if;

  update public.tgg_video_studio_social_publications set status='revoked',updated_at=now(),metadata=metadata||jsonb_build_object('revoked_at',now(),'revoked_by',v_uid) where id=v_pub.id;
  return jsonb_build_object('ok',true,'publication_id',v_pub.id,'status','revoked');
end;
$function$


-- [40000001366] function public.tgg_video_studio_ripple_delete_timeline_item(p_item_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_ripple_delete_timeline_item(p_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
 v_uid uuid:=auth.uid();
 v_item public.tgg_video_timeline_items;
 v_perm jsonb;
 v_rev bigint;
 v_shifted integer:=0;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
 if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
 v_perm:=tgg_private.video_studio_permission(v_item.project_id);
 if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 delete from public.tgg_video_timeline_items where id=v_item.id;
 update public.tgg_video_timeline_items
 set start_seconds=greatest(0,start_seconds-v_item.duration_seconds),updated_at=now()
 where project_id=v_item.project_id and track_index=v_item.track_index and start_seconds>=v_item.start_seconds+v_item.duration_seconds;
 get diagnostics v_shifted=row_count;
 insert into public.tgg_video_studio_timeline_actions(project_id,user_id,action_type,target_item_id,start_seconds,duration_seconds,action,source,status)
 values(v_item.project_id,v_uid,'ripple_delete',null,v_item.start_seconds,v_item.duration_seconds,jsonb_build_object('deleted_item_id',v_item.id,'track_index',v_item.track_index,'shifted_items',v_shifted),'manual','applied');
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_rev;
 update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
 return jsonb_build_object('ok',true,'deleted_item_id',v_item.id,'shifted_items',v_shifted,'project_revision',v_rev);
end$function$


-- [40000001367] function public.tgg_video_studio_save_project_state(p_project_id uuid, p_title text, p_aspect_ratio text, p_editor_state jsonb)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_save_project_state(p_project_id uuid, p_title text, p_aspect_ratio text, p_editor_state jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_title text:=btrim(coalesce(p_title,''));
  v_ratio text:=btrim(coalesce(p_aspect_ratio,'16:9'));
  v_revision bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if char_length(v_title)<1 or char_length(v_title)>160 then raise exception 'TITLE_INVALID'; end if;
  if v_ratio not in ('16:9','9:16','1:1','4:5') then raise exception 'ASPECT_RATIO_INVALID'; end if;
  if jsonb_typeof(coalesce(p_editor_state,'{}'::jsonb))<>'object' or octet_length(coalesce(p_editor_state,'{}'::jsonb)::text)>32768 then raise exception 'EDITOR_STATE_INVALID'; end if;

  update public.tgg_creative_projects
  set title=v_title,aspect_ratio=v_ratio,settings=coalesce(settings,'{}'::jsonb)||jsonb_build_object('schema_version',2,'workspace','video-studio','editor_state',coalesce(p_editor_state,'{}'::jsonb)),updated_at=now()
  where id=p_project_id and project_type='video';

  update public.tgg_studio_projects
  set title=v_title,project_data=coalesce(project_data,'{}'::jsonb)||jsonb_build_object('schema_version',2,'workspace','video-studio','video_editor_state',coalesce(p_editor_state,'{}'::jsonb)),revision=coalesce(revision,0)+1,updated_at=now()
  where id=p_project_id and project_type='video'
  returning revision into v_revision;

  return jsonb_build_object('ok',true,'project_id',p_project_id,'revision',v_revision,'saved_at',now());
end;
$function$


-- [40000001368] function public.tgg_video_studio_server_render_status_v1(p_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_server_render_status_v1(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_perm jsonb;
  v_jobs jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_perm:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_perm->>'allowed')::boolean,false) then raise exception 'PROJECT_ACCESS_REQUIRED' using errcode='42501'; end if;

  select coalesce(jsonb_agg(x order by x->>'created_at' desc),'[]'::jsonb) into v_jobs
  from (
    select jsonb_build_object(
      'id',j.id,
      'status',j.status,
      'progress',j.progress,
      'output_format',j.output_format,
      'output_preset',j.output_preset,
      'source_revision',j.source_revision,
      'attempt_count',j.attempt_count,
      'provider_key',j.provider_key,
      'created_at',j.created_at,
      'started_at',j.started_at,
      'finished_at',j.finished_at,
      'error_message',j.error_message,
      'submitted_video_id',j.result_payload->>'submitted_video_id',
      'output',case when o.id is null then null else jsonb_build_object(
        'id',o.id,'format',o.format,'aspect_ratio',o.aspect_ratio,'resolution',o.resolution,
        'duration_seconds',o.duration_seconds,'storage_path',o.storage_path,'status',o.status,'metadata',o.metadata,
        'asset_id',(select a.id from public.tgg_media_vault_assets a where a.project_id=p_project_id and a.storage_path=o.storage_path order by a.created_at desc limit 1)
      ) end
    ) as x
    from public.tgg_video_studio_render_jobs j
    left join lateral (
      select ro.* from public.tgg_video_studio_render_outputs ro
      where ro.render_job_id=j.id order by ro.created_at desc limit 1
    ) o on true
    where j.project_id=p_project_id
      and coalesce(j.request_payload->>'mode','')='master_transcode'
      and (j.user_id=v_uid or coalesce((v_perm->>'is_owner')::boolean,false))
    order by j.created_at desc
    limit 12
  ) q;

  return jsonb_build_object(
    'ok',true,
    'project_id',p_project_id,
    'can_publish',coalesce((v_perm->>'can_publish')::boolean,false),
    'jobs',v_jobs
  );
end$function$


-- [40000001369] function public.tgg_video_studio_set_audio_mix(p_item_id uuid, p_gain_db numeric, p_pan numeric, p_mute boolean, p_normalize boolean, p_noise_reduction numeric, p_ducking boolean, p_ducking_reduction_db numeric)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_set_audio_mix(p_item_id uuid, p_gain_db numeric DEFAULT NULL::numeric, p_pan numeric DEFAULT NULL::numeric, p_mute boolean DEFAULT NULL::boolean, p_normalize boolean DEFAULT NULL::boolean, p_noise_reduction numeric DEFAULT NULL::numeric, p_ducking boolean DEFAULT NULL::boolean, p_ducking_reduction_db numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_item public.tgg_video_timeline_items; v_perm jsonb; v_audio jsonb; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
 if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
 v_perm:=tgg_private.video_studio_permission(v_item.project_id);
 if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 v_audio:=coalesce(v_item.settings->'audio','{}'::jsonb);
 if p_gain_db is not null then v_audio:=v_audio||jsonb_build_object('gain_db',least(24,greatest(-60,p_gain_db))); end if;
 if p_pan is not null then v_audio:=v_audio||jsonb_build_object('pan',least(1,greatest(-1,p_pan))); end if;
 if p_mute is not null then v_audio:=v_audio||jsonb_build_object('mute',p_mute); end if;
 if p_normalize is not null then v_audio:=v_audio||jsonb_build_object('normalize',p_normalize); end if;
 if p_noise_reduction is not null then v_audio:=v_audio||jsonb_build_object('noise_reduction',least(1,greatest(0,p_noise_reduction))); end if;
 if p_ducking is not null then v_audio:=v_audio||jsonb_build_object('ducking',p_ducking); end if;
 if p_ducking_reduction_db is not null then v_audio:=v_audio||jsonb_build_object('ducking_reduction_db',least(0,greatest(-48,p_ducking_reduction_db))); end if;
 update public.tgg_video_timeline_items
 set settings=jsonb_set(coalesce(settings,'{}'::jsonb),'{audio}',v_audio,true),updated_at=now()
 where id=v_item.id;
 insert into public.tgg_video_studio_timeline_actions(project_id,user_id,action_type,target_item_id,start_seconds,duration_seconds,action,source,status)
 values(v_item.project_id,v_uid,'audio_mix',v_item.id,v_item.start_seconds,v_item.duration_seconds,jsonb_build_object('audio',v_audio),'manual','applied');
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_rev;
 return jsonb_build_object('ok',true,'item_id',v_item.id,'audio',v_audio,'project_revision',v_rev);
end$function$


-- [40000001370] function public.tgg_video_studio_set_keyframe(p_project_id uuid, p_timeline_item_id uuid, p_parameter text, p_time_seconds numeric, p_value jsonb, p_easing text)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_set_keyframe(p_project_id uuid, p_timeline_item_id uuid, p_parameter text, p_time_seconds numeric, p_value jsonb, p_easing text DEFAULT 'linear'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_row public.tgg_video_studio_keyframes; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from public.tgg_video_timeline_items where id=p_timeline_item_id and project_id=p_project_id) then raise exception 'ITEM_NOT_FOUND'; end if;
 if nullif(btrim(coalesce(p_parameter,'')),'') is null or coalesce(p_time_seconds,-1)<0 then raise exception 'KEYFRAME_INVALID'; end if;
 delete from public.tgg_video_studio_keyframes where project_id=p_project_id and timeline_item_id=p_timeline_item_id and parameter=p_parameter and time_seconds=p_time_seconds;
 insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing) values(p_project_id,p_timeline_item_id,v_uid,p_parameter,p_time_seconds,coalesce(p_value,'{}'::jsonb),coalesce(nullif(p_easing,''),'linear')) returning * into v_row;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return to_jsonb(v_row)||jsonb_build_object('project_revision',v_rev);
end$function$


-- [40000001371] function public.tgg_video_studio_set_speed_keyframe_v1(p_item_id uuid, p_time_seconds numeric, p_speed numeric, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_set_speed_keyframe_v1(p_item_id uuid, p_time_seconds numeric, p_speed numeric, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_item public.tgg_video_timeline_items;
  v_perm jsonb;
  v_revision bigint;
  v_new_revision bigint;
  v_row public.tgg_video_studio_keyframes;
  v_asset_duration numeric;
  v_span numeric:=0;
  v_prev_t numeric:=0;
  v_prev_s numeric:=null;
  v_t numeric;
  v_s numeric;
  r record;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
  if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_perm:=tgg_private.video_studio_permission(v_item.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if exists(select 1 from private.tgg_video_studio_track_states s where s.project_id=v_item.project_id and s.track_index=v_item.track_index and s.locked=true) then raise exception 'TRACK_LOCKED'; end if;
  if coalesce(p_time_seconds,-1)<0 or p_time_seconds>v_item.duration_seconds then raise exception 'SPEED_KEYFRAME_TIME_INVALID'; end if;
  if coalesce(p_speed,0)<0.1 or p_speed>4 then raise exception 'SPEED_INVALID'; end if;

  select revision into v_revision from public.tgg_studio_projects where id=v_item.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_revision then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_revision);
  end if;

  delete from public.tgg_video_studio_keyframes where project_id=v_item.project_id and timeline_item_id=v_item.id and parameter='speed' and time_seconds=p_time_seconds;
  insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
  values(v_item.project_id,v_item.id,v_uid,'speed',p_time_seconds,jsonb_build_object('value',p_speed),'linear') returning * into v_row;

  for r in
    select time_seconds,
           case when jsonb_typeof(value)='object' then (value->>'value')::numeric else (value::text)::numeric end as speed_value
    from public.tgg_video_studio_keyframes
    where timeline_item_id=v_item.id and parameter='speed'
    order by time_seconds
  loop
    v_t:=least(v_item.duration_seconds,greatest(0,r.time_seconds));
    v_s:=least(4,greatest(.1,r.speed_value));
    if v_prev_s is null then
      v_span:=v_span + v_t*v_s;
    else
      v_span:=v_span + greatest(0,v_t-v_prev_t)*(v_prev_s+v_s)/2;
    end if;
    v_prev_t:=v_t;
    v_prev_s:=v_s;
  end loop;
  if v_prev_s is null then
    v_span:=v_item.duration_seconds*least(4,greatest(.1,coalesce(nullif(v_item.settings->'editor_state'->>'speed','')::numeric,100)/100));
  else
    v_span:=v_span + greatest(0,v_item.duration_seconds-v_prev_t)*v_prev_s;
  end if;

  select duration_seconds into v_asset_duration from public.tgg_media_vault_assets where id=v_item.asset_id;
  if v_asset_duration is not null and v_item.source_in_seconds+v_span>v_asset_duration+.02 then
    raise exception 'SPEED_RAMP_EXCEEDS_SOURCE';
  end if;

  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_new_revision;
  return jsonb_build_object('ok',true,'conflict',false,'keyframe',to_jsonb(v_row),'estimated_source_span',v_span,'project_revision',v_new_revision);
end
$function$


-- [40000001372] function public.tgg_video_studio_set_static_speed_v1(p_item_id uuid, p_speed numeric, p_ripple boolean, p_clear_ramp boolean, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_set_static_speed_v1(p_item_id uuid, p_speed numeric, p_ripple boolean DEFAULT true, p_clear_ramp boolean DEFAULT false, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_item public.tgg_video_timeline_items;
  v_perm jsonb;
  v_revision bigint;
  v_new_revision bigint;
  v_asset_duration numeric;
  v_span numeric:=0;
  v_prev_t numeric:=0;
  v_prev_s numeric:=null;
  v_t numeric;
  v_s numeric;
  v_old_speed numeric;
  v_new_duration numeric;
  v_ratio numeric;
  v_old_end numeric;
  v_delta numeric;
  v_ramps integer:=0;
  v_shifted integer:=0;
  r record;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
  if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_perm:=tgg_private.video_studio_permission(v_item.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if exists(select 1 from private.tgg_video_studio_track_states s where s.project_id=v_item.project_id and s.track_index=v_item.track_index and s.locked=true) then raise exception 'TRACK_LOCKED'; end if;
  if coalesce(p_speed,0)<0.1 or p_speed>4 then raise exception 'SPEED_INVALID'; end if;

  select revision into v_revision from public.tgg_studio_projects where id=v_item.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_revision then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_revision);
  end if;

  select count(*) into v_ramps from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='speed';
  if v_ramps>0 and not coalesce(p_clear_ramp,false) then raise exception 'SPEED_RAMP_EXISTS_CLEAR_OR_USE_RAMP'; end if;
  v_old_speed:=least(4,greatest(.1,coalesce(nullif(v_item.settings->'editor_state'->>'speed','')::numeric,100)/100));

  if v_ramps=0 then
    v_span:=v_item.duration_seconds*v_old_speed;
  else
    for r in
      select time_seconds,
             case when jsonb_typeof(value)='object' then (value->>'value')::numeric else (value::text)::numeric end as speed_value
      from public.tgg_video_studio_keyframes
      where timeline_item_id=v_item.id and parameter='speed'
      order by time_seconds
    loop
      v_t:=least(v_item.duration_seconds,greatest(0,r.time_seconds));
      v_s:=least(4,greatest(.1,r.speed_value));
      if v_prev_s is null then v_span:=v_span+v_t*v_s;
      else v_span:=v_span+greatest(0,v_t-v_prev_t)*(v_prev_s+v_s)/2;
      end if;
      v_prev_t:=v_t; v_prev_s:=v_s;
    end loop;
    v_span:=v_span+greatest(0,v_item.duration_seconds-v_prev_t)*coalesce(v_prev_s,v_old_speed);
  end if;

  select duration_seconds into v_asset_duration from public.tgg_media_vault_assets where id=v_item.asset_id;
  if v_asset_duration is not null then v_span:=least(v_span,greatest(.05,v_asset_duration-v_item.source_in_seconds)); end if;
  v_new_duration:=greatest(.05,v_span/p_speed);
  v_ratio:=v_new_duration/greatest(.05,v_item.duration_seconds);
  v_old_end:=v_item.start_seconds+v_item.duration_seconds;
  v_delta:=v_new_duration-v_item.duration_seconds;

  if not coalesce(p_ripple,true) and v_delta>0 and exists(
    select 1 from public.tgg_video_timeline_items t where t.project_id=v_item.project_id and t.track_index=v_item.track_index and t.id<>v_item.id and t.start_seconds>=v_old_end-.001 and t.start_seconds<v_item.start_seconds+v_new_duration-.001
  ) then raise exception 'RETIME_COLLISION_USE_RIPPLE'; end if;

  if coalesce(p_clear_ramp,false) then delete from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='speed'; end if;
  update public.tgg_video_studio_keyframes set time_seconds=time_seconds*v_ratio,updated_at=now() where timeline_item_id=v_item.id and parameter<>'speed';
  update public.tgg_video_studio_effect_instances set start_seconds=case when start_seconds is null then null else start_seconds*v_ratio end,duration_seconds=case when duration_seconds is null then null else duration_seconds*v_ratio end,updated_at=now() where timeline_item_id=v_item.id;
  update public.tgg_video_studio_caption_cues set start_seconds=v_item.start_seconds+(start_seconds-v_item.start_seconds)*v_ratio,end_seconds=v_item.start_seconds+(end_seconds-v_item.start_seconds)*v_ratio,updated_at=now() where timeline_item_id=v_item.id;
  update public.tgg_video_studio_markers set time_seconds=v_item.start_seconds+(time_seconds-v_item.start_seconds)*v_ratio,updated_at=now() where timeline_item_id=v_item.id;

  update public.tgg_video_timeline_items
  set duration_seconds=v_new_duration,
      settings=coalesce(settings,'{}'::jsonb)||jsonb_build_object('editor_state',coalesce(settings->'editor_state','{}'::jsonb)||jsonb_build_object('speed',p_speed*100)),
      updated_at=now()
  where id=v_item.id;

  if coalesce(p_ripple,true) and abs(v_delta)>.0001 then
    update public.tgg_video_timeline_items set start_seconds=greatest(0,start_seconds+v_delta),updated_at=now()
    where project_id=v_item.project_id and track_index=v_item.track_index and id<>v_item.id and start_seconds>=v_old_end-.001;
    get diagnostics v_shifted=row_count;
  end if;

  update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_new_revision;
  return jsonb_build_object('ok',true,'conflict',false,'speed',p_speed,'source_span',v_span,'old_duration',v_item.duration_seconds,'new_duration',v_new_duration,'shifted_items',v_shifted,'project_revision',v_new_revision);
end
$function$


-- [40000001373] function public.tgg_video_studio_set_track_state_v1(p_project_id uuid, p_track_index integer, p_label text, p_muted boolean, p_solo boolean, p_locked boolean, p_gain_db numeric, p_pan numeric, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_set_track_state_v1(p_project_id uuid, p_track_index integer, p_label text DEFAULT NULL::text, p_muted boolean DEFAULT NULL::boolean, p_solo boolean DEFAULT NULL::boolean, p_locked boolean DEFAULT NULL::boolean, p_gain_db numeric DEFAULT NULL::numeric, p_pan numeric DEFAULT NULL::numeric, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_rev bigint; v_new_rev bigint; v_state private.tgg_video_studio_track_states;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if coalesce(p_track_index,-1)<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  if p_gain_db is not null and (p_gain_db<-60 or p_gain_db>24) then raise exception 'GAIN_DB_INVALID'; end if;
  if p_pan is not null and (p_pan<-1 or p_pan>1) then raise exception 'PAN_INVALID'; end if;
  v_perm:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select revision into v_rev from public.tgg_studio_projects where id=p_project_id for update;
  if v_rev is null then raise exception 'PROJECT_NOT_FOUND'; end if;
  if p_base_revision is not null and p_base_revision<>v_rev then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_rev);
  end if;

  insert into private.tgg_video_studio_track_states as s(project_id,track_index,label,muted,solo,locked,gain_db,pan,updated_by,updated_at)
  values(p_project_id,p_track_index,left(nullif(btrim(coalesce(p_label,'')),''),60),coalesce(p_muted,false),coalesce(p_solo,false),coalesce(p_locked,false),coalesce(p_gain_db,0),coalesce(p_pan,0),v_uid,now())
  on conflict(project_id,track_index) do update set
    label=coalesce(left(nullif(btrim(coalesce(p_label,'')),''),60),s.label),
    muted=coalesce(p_muted,s.muted),
    solo=coalesce(p_solo,s.solo),
    locked=coalesce(p_locked,s.locked),
    gain_db=coalesce(p_gain_db,s.gain_db),
    pan=coalesce(p_pan,s.pan),
    updated_by=v_uid,
    updated_at=now()
  returning * into v_state;

  update public.tgg_creative_projects set updated_at=now() where id=p_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_new_rev;
  return jsonb_build_object('ok',true,'conflict',false,'state',jsonb_build_object('track_index',v_state.track_index,'label',v_state.label,'muted',v_state.muted,'solo',v_state.solo,'locked',v_state.locked,'gain_db',v_state.gain_db,'pan',v_state.pan),'base_revision',v_rev,'project_revision',v_new_rev);
end$function$


-- [40000001374] function public.tgg_video_studio_set_volume_envelope_v1(p_item_id uuid, p_fade_in_seconds numeric, p_fade_out_seconds numeric, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_set_volume_envelope_v1(p_item_id uuid, p_fade_in_seconds numeric DEFAULT 0, p_fade_out_seconds numeric DEFAULT 0, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_item public.tgg_video_timeline_items;
  v_perm jsonb;
  v_revision bigint;
  v_new_revision bigint;
  v_fi numeric:=greatest(0,coalesce(p_fade_in_seconds,0));
  v_fo numeric:=greatest(0,coalesce(p_fade_out_seconds,0));
  v_inserted integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
  if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_perm:=tgg_private.video_studio_permission(v_item.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if exists(select 1 from private.tgg_video_studio_track_states s where s.project_id=v_item.project_id and s.track_index=v_item.track_index and s.locked=true) then raise exception 'TRACK_LOCKED'; end if;
  if v_fi>v_item.duration_seconds or v_fo>v_item.duration_seconds or v_fi+v_fo>v_item.duration_seconds then raise exception 'FADE_RANGE_INVALID'; end if;
  select revision into v_revision from public.tgg_studio_projects where id=v_item.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_revision then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_revision);
  end if;

  delete from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='volume';
  insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
  select v_item.project_id,v_item.id,v_uid,'volume',x.t,jsonb_build_object('value',max(x.v)),'linear'
  from (values
    (0::numeric,case when v_fi>0 then 0::numeric else 1::numeric end),
    (v_fi,1::numeric),
    (v_item.duration_seconds-v_fo,1::numeric),
    (v_item.duration_seconds,case when v_fo>0 then 0::numeric else 1::numeric end)
  ) as x(t,v)
  group by x.t
  order by x.t;
  get diagnostics v_inserted=row_count;

  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_new_revision;
  return jsonb_build_object('ok',true,'conflict',false,'fade_in_seconds',v_fi,'fade_out_seconds',v_fo,'keyframes',v_inserted,'project_revision',v_new_revision);
end
$function$


-- [40000001375] function public.tgg_video_studio_set_volume_keyframe_v1(p_item_id uuid, p_time_seconds numeric, p_volume numeric, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_set_volume_keyframe_v1(p_item_id uuid, p_time_seconds numeric, p_volume numeric, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_item public.tgg_video_timeline_items;
  v_perm jsonb;
  v_revision bigint;
  v_new_revision bigint;
  v_row public.tgg_video_studio_keyframes;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
  if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_perm:=tgg_private.video_studio_permission(v_item.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if exists(select 1 from private.tgg_video_studio_track_states s where s.project_id=v_item.project_id and s.track_index=v_item.track_index and s.locked=true) then raise exception 'TRACK_LOCKED'; end if;
  if coalesce(p_time_seconds,-1)<0 or p_time_seconds>v_item.duration_seconds then raise exception 'VOLUME_KEYFRAME_TIME_INVALID'; end if;
  if coalesce(p_volume,-1)<0 or p_volume>2 then raise exception 'VOLUME_KEYFRAME_VALUE_INVALID'; end if;
  select revision into v_revision from public.tgg_studio_projects where id=v_item.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_revision then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_revision);
  end if;
  delete from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='volume' and time_seconds=p_time_seconds;
  insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
  values(v_item.project_id,v_item.id,v_uid,'volume',p_time_seconds,jsonb_build_object('value',p_volume),'linear') returning * into v_row;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_new_revision;
  return jsonb_build_object('ok',true,'conflict',false,'keyframe',to_jsonb(v_row),'project_revision',v_new_revision);
end
$function$


-- [40000001376] function public.tgg_video_studio_slip_clip_v1(p_item_id uuid, p_delta_seconds numeric, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_slip_clip_v1(p_item_id uuid, p_delta_seconds numeric, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_item public.tgg_video_timeline_items;
  v_asset public.tgg_media_vault_assets;
  v_perm jsonb;
  v_rev bigint;
  v_new_rev bigint;
  v_delta numeric:=coalesce(p_delta_seconds,0);
  v_speed numeric:=1;
  v_span numeric;
  v_source numeric;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if abs(v_delta)>3600 then raise exception 'SLIP_DELTA_INVALID'; end if;
  select * into v_item from public.tgg_video_timeline_items where id=p_item_id for update;
  if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  if v_item.item_type not in ('video','audio') then raise exception 'SLIP_MEDIA_REQUIRED'; end if;
  v_perm:=tgg_private.video_studio_permission(v_item.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select * into v_asset from public.tgg_media_vault_assets where id=v_item.asset_id and project_id=v_item.project_id;
  if v_asset.id is null or v_asset.duration_seconds is null then raise exception 'ASSET_DURATION_REQUIRED'; end if;
  select revision into v_rev from public.tgg_studio_projects where id=v_item.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_rev then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_rev);
  end if;
  if exists(select 1 from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='speed') then
    return jsonb_build_object('ok',false,'unsupported',true,'reason','SPEED_RAMP_SLIP_UNSUPPORTED','current_revision',v_rev);
  end if;
  if coalesce(v_item.settings#>>'{editor_state,speed}','') ~ '^[0-9]+([.][0-9]+)?$' then
    v_speed:=greatest(.1,least(4,(v_item.settings#>>'{editor_state,speed}')::numeric/100));
  end if;
  v_span:=v_item.duration_seconds*v_speed;
  v_source:=v_item.source_in_seconds+v_delta;
  if v_source<0 or v_source+v_span>v_asset.duration_seconds+.02 then
    return jsonb_build_object('ok',false,'bounds',true,'reason','SOURCE_BOUNDS_EXCEEDED','min_source_in',0,'max_source_in',greatest(0,v_asset.duration_seconds-v_span),'requested_source_in',v_source,'current_revision',v_rev);
  end if;
  update public.tgg_video_timeline_items set source_in_seconds=v_source,updated_at=now() where id=v_item.id;
  update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_new_rev;
  return jsonb_build_object('ok',true,'conflict',false,'item_id',v_item.id,'source_in_seconds',v_source,'delta_seconds',v_delta,'base_revision',v_rev,'project_revision',v_new_rev);
end$function$


-- [40000001377] function public.tgg_video_studio_smart_action(p_project_id uuid, p_action text, p_payload jsonb)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_smart_action(p_project_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_action text:=lower(btrim(coalesce(p_action,'')));
  v_style public.tgg_video_studio_style_recipes;
  v_style_id uuid;
  v_plan public.tgg_video_studio_edit_plans;
  v_scenes jsonb;
  v_scene_count integer:=0;
  v_output_type text;
  v_ratio text;
  v_duration numeric;
  v_job public.tgg_content_repurpose_jobs;
  v_job_id uuid;
  v_asset_id uuid;
  v_output public.tgg_video_studio_repurpose_outputs;
  v_is_owner boolean:=false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if jsonb_typeof(coalesce(p_payload,'{}'::jsonb))<>'object' then raise exception 'PAYLOAD_INVALID'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  v_is_owner:=coalesce((v_permission->>'is_owner')::boolean,false);

  if v_action='apply_style' then
    begin v_style_id:=(p_payload->>'style_id')::uuid; exception when others then raise exception 'STYLE_ID_INVALID'; end;
    select * into v_style from public.tgg_video_studio_style_recipes
    where id=v_style_id and enabled=true and (user_id=v_uid or is_public=true);
    if v_style.id is null then raise exception 'STYLE_NOT_FOUND_OR_NOT_ACCESSIBLE'; end if;
    insert into public.tgg_video_studio_edit_plans(project_id,user_id,plan_type,mood,prompt,score,plan,status)
    values(p_project_id,v_uid,'style_recipe',v_style.category,v_style.name,1,v_style.recipe||jsonb_build_object('style_id',v_style.id,'style_name',v_style.name,'engine','browser-v1'),'applied')
    returning * into v_plan;
    return jsonb_build_object('ok',true,'action','apply_style','style',to_jsonb(v_style),'edit_plan',to_jsonb(v_plan),'editor_patch',coalesce(v_style.recipe->'editor_patch','{}'::jsonb));

  elsif v_action='record_scene_scan' then
    v_scenes:=p_payload->'scenes';
    if jsonb_typeof(v_scenes)<>'array' then raise exception 'SCENES_ARRAY_REQUIRED'; end if;
    v_scene_count:=jsonb_array_length(v_scenes);
    if v_scene_count<1 or v_scene_count>120 then raise exception 'SCENE_COUNT_INVALID'; end if;
    delete from public.tgg_video_studio_scene_analysis where project_id=p_project_id;
    insert into public.tgg_video_studio_scene_analysis(project_id,user_id,scene_index,start_seconds,end_seconds,scene_type,mood,energy,quality_score,subjects,recommendations,metadata)
    select p_project_id,v_uid,
      ordinality::integer-1,
      greatest(0,coalesce((x->>'start_seconds')::numeric,0)),
      greatest(greatest(0,coalesce((x->>'start_seconds')::numeric,0)),coalesce((x->>'end_seconds')::numeric,0)),
      left(coalesce(nullif(btrim(x->>'scene_type'),''),'browser_cut'),60),
      left(coalesce(nullif(btrim(x->>'mood'),''),'unknown'),60),
      least(1,greatest(0,coalesce((x->>'energy')::numeric,0.5))),
      least(1,greatest(0,coalesce((x->>'quality_score')::numeric,0.75))),
      case when jsonb_typeof(x->'subjects')='array' then x->'subjects' else '[]'::jsonb end,
      case when jsonb_typeof(x->'recommendations')='array' then x->'recommendations' else '[]'::jsonb end,
      coalesce(x->'metadata','{}'::jsonb)||jsonb_build_object('analysis_engine','browser-frame-diff-v1','recorded_by',v_uid)
    from jsonb_array_elements(v_scenes) with ordinality q(x,ordinality);
    return jsonb_build_object('ok',true,'action','record_scene_scan','scene_count',v_scene_count,'analysis_engine','browser-frame-diff-v1');

  elsif v_action='create_repurpose' then
    v_output_type:=lower(btrim(coalesce(p_payload->>'output_type','')));
    v_ratio:=btrim(coalesce(p_payload->>'aspect_ratio','9:16'));
    if v_output_type not in ('full_video','short','social_clip','story','trailer') then raise exception 'OUTPUT_TYPE_INVALID'; end if;
    if v_ratio not in ('16:9','9:16','1:1','4:5') then raise exception 'ASPECT_RATIO_INVALID'; end if;
    begin v_duration:=nullif(p_payload->>'duration_seconds','')::numeric; exception when others then raise exception 'DURATION_INVALID'; end;
    if v_duration is not null and (v_duration<=0 or v_duration>300) then raise exception 'DURATION_INVALID'; end if;
    insert into public.tgg_content_repurpose_jobs(project_id,user_id,source_type,source_id,output_type,aspect_ratio,duration_seconds,instructions,status)
    values(p_project_id,v_uid,'project',p_project_id,v_output_type,v_ratio,v_duration,coalesce(p_payload->'instructions','{}'::jsonb)||jsonb_build_object('execution','browser_export','schema_version',1),'queued')
    returning * into v_job;
    return jsonb_build_object('ok',true,'action','create_repurpose','job',to_jsonb(v_job));

  elsif v_action='complete_repurpose' then
    begin v_job_id:=(p_payload->>'job_id')::uuid; exception when others then raise exception 'JOB_ID_INVALID'; end;
    begin v_asset_id:=(p_payload->>'asset_id')::uuid; exception when others then raise exception 'ASSET_ID_INVALID'; end;
    select * into v_job from public.tgg_content_repurpose_jobs where id=v_job_id and project_id=p_project_id;
    if v_job.id is null then raise exception 'REPURPOSE_JOB_NOT_FOUND'; end if;
    if v_job.user_id<>v_uid and not v_is_owner then raise exception 'REPURPOSE_JOB_PERMISSION_REQUIRED' using errcode='42501'; end if;
    if v_job.status not in ('queued','processing') then raise exception 'REPURPOSE_JOB_NOT_COMPLETABLE'; end if;
    if not exists(select 1 from public.tgg_media_vault_assets a where a.id=v_asset_id and a.project_id=p_project_id and a.asset_type='video' and a.storage_path=(p_payload->>'storage_path')) then raise exception 'REPURPOSE_ASSET_NOT_FOUND_IN_PROJECT'; end if;
    update public.tgg_content_repurpose_jobs set status='ready',output_asset_id=v_asset_id,error_message=null,updated_at=now() where id=v_job_id returning * into v_job;
    insert into public.tgg_video_studio_repurpose_outputs(job_id,user_id,output_type,title,caption,asset_url,storage_path,metadata,status)
    values(v_job_id,v_uid,v_job.output_type,left(coalesce(nullif(btrim(p_payload->>'title'),''),initcap(replace(v_job.output_type,'_',' '))),160),left(coalesce(p_payload->>'caption',''),2200),null,p_payload->>'storage_path',coalesce(p_payload->'metadata','{}'::jsonb)||jsonb_build_object('asset_id',v_asset_id,'project_id',p_project_id,'execution','browser_export'),'ready')
    returning * into v_output;
    return jsonb_build_object('ok',true,'action','complete_repurpose','job',to_jsonb(v_job),'output',to_jsonb(v_output));

  elsif v_action='cancel_repurpose' then
    begin v_job_id:=(p_payload->>'job_id')::uuid; exception when others then raise exception 'JOB_ID_INVALID'; end;
    update public.tgg_content_repurpose_jobs set status='cancelled',updated_at=now()
    where id=v_job_id and project_id=p_project_id and status in ('queued','processing') and (user_id=v_uid or v_is_owner)
    returning * into v_job;
    if v_job.id is null then raise exception 'REPURPOSE_JOB_NOT_CANCELLABLE'; end if;
    return jsonb_build_object('ok',true,'action','cancel_repurpose','job',to_jsonb(v_job));
  else
    raise exception 'SMART_ACTION_INVALID';
  end if;
end;
$function$


-- [40000001378] function public.tgg_video_studio_smart_tools_bundle(p_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_smart_tools_bundle(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'allowed')::boolean,false) then raise exception 'PROJECT_NOT_FOUND_OR_NOT_ACCESSIBLE' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'project_id',p_project_id,
    'permission',v_permission,
    'capabilities',jsonb_build_object(
      'smart_looks','browser-v1',
      'scene_scan','browser-v1',
      'short_form','browser-v1',
      'advanced_fx_catalog',true,
      'advanced_fx_renderer',false,
      'transition_catalog',true,
      'transition_renderer',false,
      'external_ai_inference',false
    ),
    'styles',coalesce((select jsonb_agg(to_jsonb(s) order by s.category,s.name) from public.tgg_video_studio_style_recipes s where s.enabled=true and (s.user_id=v_uid or (s.is_public=true))), '[]'::jsonb),
    'fx_catalog',coalesce((select jsonb_agg(to_jsonb(f) order by f.sort_order,f.name) from public.tgg_video_studio_fx_catalog f where f.enabled=true), '[]'::jsonb),
    'transitions',coalesce((select jsonb_agg(to_jsonb(t) order by t.sort_order,t.name) from public.tgg_video_studio_transition_catalog t where t.enabled=true), '[]'::jsonb),
    'edit_plans',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at desc) from public.tgg_video_studio_edit_plans e where e.project_id=p_project_id limit 30), '[]'::jsonb),
    'scene_analysis',coalesce((select jsonb_agg(to_jsonb(s) order by s.scene_index) from public.tgg_video_studio_scene_analysis s where s.project_id=p_project_id), '[]'::jsonb),
    'repurpose_jobs',coalesce((select jsonb_agg(to_jsonb(j) order by j.created_at desc) from public.tgg_content_repurpose_jobs j where j.project_id=p_project_id limit 30), '[]'::jsonb),
    'repurpose_outputs',coalesce((select jsonb_agg(to_jsonb(o) order by o.created_at desc) from public.tgg_video_studio_repurpose_outputs o join public.tgg_content_repurpose_jobs j on j.id=o.job_id where j.project_id=p_project_id limit 30), '[]'::jsonb),
    'generated_at',now()
  );
end;
$function$


-- [40000001379] function public.tgg_video_studio_split_timeline_item(p_item_id uuid, p_split_at_seconds numeric)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_split_timeline_item(p_item_id uuid, p_split_at_seconds numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
 v_uid uuid:=auth.uid();
 v_item public.tgg_video_timeline_items;
 v_new public.tgg_video_timeline_items;
 v_perm jsonb;
 v_left numeric;
 v_end numeric;
 v_right numeric;
 v_rev bigint;
 v_left_settings jsonb;
 v_right_settings jsonb;
 v_fx record;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
 if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
 v_perm:=tgg_private.video_studio_permission(v_item.project_id);
 if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 v_end:=v_item.start_seconds+v_item.duration_seconds;
 if p_split_at_seconds<=v_item.start_seconds or p_split_at_seconds>=v_end then raise exception 'SPLIT_OUTSIDE_CLIP'; end if;
 v_left:=p_split_at_seconds-v_item.start_seconds;
 v_right:=v_item.duration_seconds-v_left;
 v_left_settings:=coalesce(v_item.settings,'{}'::jsonb);
 v_right_settings:=coalesce(v_item.settings,'{}'::jsonb);
 if v_left_settings ? 'editor_state' then
   v_left_settings:=v_left_settings||jsonb_build_object('editor_state',coalesce(v_left_settings->'editor_state','{}'::jsonb)||jsonb_build_object('trimStart',v_item.source_in_seconds,'trimEnd',v_item.source_in_seconds+v_left));
   v_right_settings:=v_right_settings||jsonb_build_object('editor_state',coalesce(v_right_settings->'editor_state','{}'::jsonb)||jsonb_build_object('trimStart',v_item.source_in_seconds+v_left,'trimEnd',v_item.source_in_seconds+v_left+v_right));
 end if;
 update public.tgg_video_timeline_items set duration_seconds=v_left,settings=v_left_settings,updated_at=now() where id=v_item.id;
 insert into public.tgg_video_timeline_items(project_id,user_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
 values(v_item.project_id,v_uid,v_item.asset_id,v_item.track_index,v_item.item_type,p_split_at_seconds,v_right,v_item.source_in_seconds+v_left,v_right_settings)
 returning * into v_new;

 for v_fx in select * from public.tgg_video_studio_effect_instances where timeline_item_id=v_item.id order by stack_order,created_at loop
   if v_fx.start_seconds is null or v_fx.duration_seconds is null then
     insert into public.tgg_video_studio_effect_instances(project_id,timeline_item_id,user_id,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled)
     values(v_fx.project_id,v_new.id,v_uid,v_fx.effect_catalog_id,v_fx.effect_type,v_fx.stack_order,v_fx.start_seconds,v_fx.duration_seconds,v_fx.settings,v_fx.enabled);
   elsif v_fx.start_seconds>=v_left then
     update public.tgg_video_studio_effect_instances set timeline_item_id=v_new.id,user_id=v_uid,start_seconds=v_fx.start_seconds-v_left,updated_at=now() where id=v_fx.id;
   elsif v_fx.start_seconds+v_fx.duration_seconds>v_left then
     update public.tgg_video_studio_effect_instances set duration_seconds=v_left-v_fx.start_seconds,updated_at=now() where id=v_fx.id;
     insert into public.tgg_video_studio_effect_instances(project_id,timeline_item_id,user_id,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled)
     values(v_fx.project_id,v_new.id,v_uid,v_fx.effect_catalog_id,v_fx.effect_type,v_fx.stack_order,0,(v_fx.start_seconds+v_fx.duration_seconds)-v_left,v_fx.settings,v_fx.enabled);
   end if;
 end loop;

 update public.tgg_video_studio_keyframes set timeline_item_id=v_new.id,user_id=v_uid,time_seconds=time_seconds-v_left,updated_at=now() where timeline_item_id=v_item.id and time_seconds>=v_left;
 update public.tgg_video_studio_caption_cues set timeline_item_id=v_new.id,updated_at=now() where timeline_item_id=v_item.id and start_seconds>=p_split_at_seconds;
 update public.tgg_video_studio_markers set timeline_item_id=v_new.id,updated_at=now() where timeline_item_id=v_item.id and time_seconds>=p_split_at_seconds;
 update public.tgg_video_studio_transition_instances set from_item_id=v_new.id,updated_at=now() where from_item_id=v_item.id;

 insert into public.tgg_video_studio_timeline_actions(project_id,user_id,action_type,target_item_id,start_seconds,duration_seconds,action,source,status)
 values(v_item.project_id,v_uid,'split',v_item.id,p_split_at_seconds,v_item.duration_seconds,jsonb_build_object('left_item_id',v_item.id,'right_item_id',v_new.id,'source_split_seconds',v_item.source_in_seconds+v_left),'manual','applied');
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_rev;
 update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
 return jsonb_build_object('ok',true,'left_item',(select to_jsonb(t) from public.tgg_video_timeline_items t where t.id=v_item.id),'right_item',to_jsonb(v_new),'project_revision',v_rev);
end$function$


-- [40000001380] function public.tgg_video_studio_submit_server_render_v1(p_project_id uuid, p_job_id uuid, p_title text, p_description text, p_genre text, p_explicit_content boolean, p_allow_downloads boolean)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_submit_server_render_v1(p_project_id uuid, p_job_id uuid, p_title text, p_description text DEFAULT NULL::text, p_genre text DEFAULT NULL::text, p_explicit_content boolean DEFAULT false, p_allow_downloads boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'storage', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_perm jsonb;
  v_job public.tgg_video_studio_render_jobs;
  v_output public.tgg_video_studio_render_outputs;
  v_video public.videos;
  v_existing uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_perm:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_perm->>'can_publish')::boolean,false) then raise exception 'PUBLISH_PERMISSION_REQUIRED' using errcode='42501'; end if;

  select * into v_job from public.tgg_video_studio_render_jobs
  where id=p_job_id and project_id=p_project_id and status='ready' and output_format='mp4'
    and coalesce(request_payload->>'mode','')='master_transcode';
  if v_job.id is null then raise exception 'READY_SERVER_MP4_NOT_FOUND'; end if;
  if v_job.user_id<>v_uid then raise exception 'SERVER_RENDER_OWNER_REQUIRED' using errcode='42501'; end if;

  begin v_existing:=nullif(v_job.result_payload->>'submitted_video_id','')::uuid; exception when others then v_existing:=null; end;
  if v_existing is not null then
    return jsonb_build_object('ok',true,'idempotent_reuse',true,'video_id',v_existing,'job_id',v_job.id);
  end if;

  select * into v_output from public.tgg_video_studio_render_outputs
  where render_job_id=v_job.id and status='ready' and format='mp4'
  order by created_at desc limit 1;
  if v_output.id is null or nullif(btrim(coalesce(v_output.storage_path,'')),'') is null then raise exception 'SERVER_MP4_OUTPUT_NOT_FOUND'; end if;
  if split_part(v_output.storage_path,'/',1)<>v_uid::text then raise exception 'SERVER_MP4_STORAGE_OWNER_MISMATCH' using errcode='42501'; end if;

  select * into v_video from public.tgg_video_submit_from_storage(
    left(btrim(coalesce(p_title,'')),160),
    v_output.storage_path,
    p_description,p_genre,null,p_explicit_content,null,p_allow_downloads
  );

  update public.tgg_video_studio_render_jobs
  set result_payload=coalesce(result_payload,'{}'::jsonb)||jsonb_build_object(
      'submitted_video_id',v_video.id,'submitted_at',now(),'submitted_by',v_uid
    ),updated_at=now()
  where id=v_job.id;

  return jsonb_build_object('ok',true,'idempotent_reuse',false,'video_id',v_video.id,'job_id',v_job.id,'status',v_video.status);
end$function$


-- [40000001381] function public.tgg_video_studio_track_mix_v1(p_project_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_track_mix_v1(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'tgg_private', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_perm jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_perm:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_perm->>'allowed')::boolean,false) then raise exception 'PROJECT_NOT_FOUND_OR_NOT_ACCESSIBLE'; end if;
  return jsonb_build_object('ok',true,'project_id',p_project_id,'states',coalesce((
    select jsonb_agg(jsonb_build_object('track_index',s.track_index,'label',s.label,'muted',s.muted,'solo',s.solo,'locked',s.locked,'gain_db',s.gain_db,'pan',s.pan,'updated_at',s.updated_at) order by s.track_index)
    from private.tgg_video_studio_track_states s where s.project_id=p_project_id
  ),'[]'::jsonb));
end$function$


-- [40000001382] function public.tgg_video_studio_trim_clip_v1(p_item_id uuid, p_edge text, p_playhead_seconds numeric, p_ripple boolean, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_trim_clip_v1(p_item_id uuid, p_edge text, p_playhead_seconds numeric, p_ripple boolean DEFAULT false, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_item public.tgg_video_timeline_items;
  v_perm jsonb;
  v_rev bigint;
  v_new_rev bigint;
  v_edge text:=lower(btrim(coalesce(p_edge,'')));
  v_play numeric:=greatest(0,coalesce(p_playhead_seconds,0));
  v_old_start numeric;
  v_old_end numeric;
  v_old_duration numeric;
  v_delta numeric;
  v_new_duration numeric;
  v_speed numeric:=1;
  v_shifted integer:=0;
  v_transitions integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_edge not in ('in','out') then raise exception 'TRIM_EDGE_INVALID'; end if;

  select * into v_item from public.tgg_video_timeline_items where id=p_item_id for update;
  if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_perm:=tgg_private.video_studio_permission(v_item.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;

  select revision into v_rev from public.tgg_studio_projects where id=v_item.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_rev then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_rev);
  end if;

  v_old_start:=v_item.start_seconds;
  v_old_duration:=v_item.duration_seconds;
  v_old_end:=v_old_start+v_old_duration;
  if not (v_play>v_old_start and v_play<v_old_end) then
    return jsonb_build_object('ok',false,'outside',true,'reason','PLAYHEAD_MUST_BE_INSIDE_CLIP','current_revision',v_rev);
  end if;

  if v_edge='in' and exists(
    select 1 from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='speed'
  ) then
    return jsonb_build_object('ok',false,'unsupported',true,'reason','SPEED_RAMP_TRIM_IN_SPLIT_FIRST','current_revision',v_rev);
  end if;

  delete from public.tgg_video_studio_transition_instances
   where from_item_id=v_item.id or to_item_id=v_item.id;
  get diagnostics v_transitions=row_count;

  if v_edge='in' then
    v_delta:=v_play-v_old_start;
    v_new_duration:=v_old_end-v_play;
    if coalesce(v_item.settings#>>'{editor_state,speed}','') ~ '^[0-9]+([.][0-9]+)?$' then
      v_speed:=greatest(.1,least(4,(v_item.settings#>>'{editor_state,speed}')::numeric/100));
    end if;

    delete from public.tgg_video_studio_effect_instances
     where timeline_item_id=v_item.id
       and start_seconds is not null
       and duration_seconds is not null
       and start_seconds+duration_seconds<=v_delta;

    update public.tgg_video_studio_effect_instances
       set start_seconds=greatest(0,start_seconds-v_delta),
           duration_seconds=case
             when duration_seconds is null then null
             else greatest(0,least(v_new_duration,start_seconds+duration_seconds-v_delta)-greatest(0,start_seconds-v_delta))
           end,
           updated_at=now()
     where timeline_item_id=v_item.id and start_seconds is not null;

    delete from public.tgg_video_studio_effect_instances
     where timeline_item_id=v_item.id and duration_seconds is not null and duration_seconds<=0;

    delete from public.tgg_video_studio_keyframes
     where timeline_item_id=v_item.id and time_seconds<v_delta;
    update public.tgg_video_studio_keyframes
       set time_seconds=time_seconds-v_delta,updated_at=now()
     where timeline_item_id=v_item.id;

    update public.tgg_video_timeline_items
       set start_seconds=v_play,
           duration_seconds=v_new_duration,
           source_in_seconds=v_item.source_in_seconds+(v_delta*v_speed),
           updated_at=now()
     where id=v_item.id;
  else
    v_new_duration:=v_play-v_old_start;
    v_delta:=v_old_duration-v_new_duration;

    delete from public.tgg_video_studio_effect_instances
     where timeline_item_id=v_item.id and start_seconds is not null and start_seconds>=v_new_duration;
    update public.tgg_video_studio_effect_instances
       set duration_seconds=greatest(0,least(duration_seconds,v_new_duration-start_seconds)),updated_at=now()
     where timeline_item_id=v_item.id
       and start_seconds is not null
       and duration_seconds is not null
       and start_seconds<v_new_duration
       and start_seconds+duration_seconds>v_new_duration;
    delete from public.tgg_video_studio_keyframes
     where timeline_item_id=v_item.id and time_seconds>v_new_duration;

    update public.tgg_video_timeline_items
       set duration_seconds=v_new_duration,updated_at=now()
     where id=v_item.id;

    if coalesce(p_ripple,false) then
      update public.tgg_video_timeline_items
         set start_seconds=greatest(v_play,start_seconds-v_delta),updated_at=now()
       where project_id=v_item.project_id
         and track_index=v_item.track_index
         and id<>v_item.id
         and start_seconds>=v_old_end;
      get diagnostics v_shifted=row_count;
    end if;
  end if;

  update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now()
   where id=v_item.project_id returning revision into v_new_rev;

  return jsonb_build_object('ok',true,'conflict',false,'item_id',v_item.id,'edge',v_edge,
    'playhead_seconds',v_play,'shifted_items',v_shifted,'removed_transitions',v_transitions,
    'base_revision',v_rev,'project_revision',v_new_rev);
end$function$


-- [40000001383] function public.tgg_video_studio_update_timeline_item(p_item_id uuid, p_patch jsonb)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_update_timeline_item(p_item_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_item public.tgg_video_timeline_items; v_project_id uuid; v_permission jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select project_id into v_project_id from public.tgg_video_timeline_items where id=p_item_id;
  if v_project_id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_permission:=tgg_private.video_studio_permission(v_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if jsonb_typeof(coalesce(p_patch,'{}'::jsonb))<>'object' then raise exception 'PATCH_INVALID'; end if;

  update public.tgg_video_timeline_items
  set track_index=case when p_patch?'track_index' then greatest(0,(p_patch->>'track_index')::integer) else track_index end,
      start_seconds=case when p_patch?'start_seconds' then greatest(0,(p_patch->>'start_seconds')::numeric) else start_seconds end,
      duration_seconds=case when p_patch?'duration_seconds' then greatest(0,(p_patch->>'duration_seconds')::numeric) else duration_seconds end,
      source_in_seconds=case when p_patch?'source_in_seconds' then greatest(0,(p_patch->>'source_in_seconds')::numeric) else source_in_seconds end,
      settings=case when p_patch?'settings' then coalesce(p_patch->'settings','{}'::jsonb) else settings end,
      updated_at=now()
  where id=p_item_id returning * into v_item;
  update public.tgg_creative_projects set updated_at=now() where id=v_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_project_id;
  return to_jsonb(v_item);
end;
$function$


-- [40000001384] function public.tgg_video_studio_update_timeline_item_v2(p_item_id uuid, p_patch jsonb, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_update_timeline_item_v2(p_item_id uuid, p_patch jsonb, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_item public.tgg_video_timeline_items;
  v_project_id uuid;
  v_permission jsonb;
  v_revision bigint;
  v_new_revision bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select project_id into v_project_id from public.tgg_video_timeline_items where id=p_item_id;
  if v_project_id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_permission:=tgg_private.video_studio_permission(v_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if jsonb_typeof(coalesce(p_patch,'{}'::jsonb))<>'object' then raise exception 'PATCH_INVALID'; end if;

  select revision into v_revision from public.tgg_studio_projects where id=v_project_id for update;
  if v_revision is null then raise exception 'PROJECT_NOT_FOUND'; end if;
  if p_base_revision is not null and p_base_revision<>v_revision then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_revision,'item_id',p_item_id);
  end if;

  update public.tgg_video_timeline_items
  set track_index=case when p_patch?'track_index' then greatest(0,(p_patch->>'track_index')::integer) else track_index end,
      start_seconds=case when p_patch?'start_seconds' then greatest(0,(p_patch->>'start_seconds')::numeric) else start_seconds end,
      duration_seconds=case when p_patch?'duration_seconds' then greatest(.05,(p_patch->>'duration_seconds')::numeric) else duration_seconds end,
      source_in_seconds=case when p_patch?'source_in_seconds' then greatest(0,(p_patch->>'source_in_seconds')::numeric) else source_in_seconds end,
      settings=case when p_patch?'settings' then coalesce(p_patch->'settings','{}'::jsonb) else settings end,
      updated_at=now()
  where id=p_item_id returning * into v_item;

  update public.tgg_creative_projects set updated_at=now() where id=v_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_project_id returning revision into v_new_revision;
  return jsonb_build_object('ok',true,'conflict',false,'item',to_jsonb(v_item),'base_revision',v_revision,'project_revision',v_new_revision);
end$function$


-- [40000001385] function public.tgg_video_studio_upsert_caption(p_project_id uuid, p_caption_id uuid, p_start_seconds numeric, p_end_seconds numeric, p_text text, p_track_index integer, p_cue_type text, p_style jsonb, p_language_code text, p_speaker text, p_timeline_item_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_upsert_caption(p_project_id uuid, p_caption_id uuid, p_start_seconds numeric, p_end_seconds numeric, p_text text, p_track_index integer DEFAULT 0, p_cue_type text DEFAULT 'caption'::text, p_style jsonb DEFAULT '{}'::jsonb, p_language_code text DEFAULT 'en'::text, p_speaker text DEFAULT NULL::text, p_timeline_item_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_row public.tgg_video_studio_caption_cues; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 if coalesce(p_start_seconds,-1)<0 or coalesce(p_end_seconds,0)<=coalesce(p_start_seconds,-1) then raise exception 'CAPTION_TIME_INVALID'; end if;
 if nullif(btrim(coalesce(p_text,'')),'') is null then raise exception 'CAPTION_TEXT_REQUIRED'; end if;
 if p_caption_id is null then
  insert into public.tgg_video_studio_caption_cues(project_id,user_id,timeline_item_id,track_index,start_seconds,end_seconds,cue_type,text,speaker,language_code,style)
  values(p_project_id,v_uid,p_timeline_item_id,greatest(0,coalesce(p_track_index,0)),p_start_seconds,p_end_seconds,coalesce(p_cue_type,'caption'),p_text,nullif(btrim(coalesce(p_speaker,'')),''),coalesce(nullif(p_language_code,''),'en'),coalesce(p_style,'{}'::jsonb)) returning * into v_row;
 else
  update public.tgg_video_studio_caption_cues set timeline_item_id=p_timeline_item_id,track_index=greatest(0,coalesce(p_track_index,track_index)),start_seconds=p_start_seconds,end_seconds=p_end_seconds,cue_type=coalesce(p_cue_type,cue_type),text=p_text,speaker=nullif(btrim(coalesce(p_speaker,'')),''),language_code=coalesce(nullif(p_language_code,''),language_code),style=coalesce(p_style,style),updated_at=now() where id=p_caption_id and project_id=p_project_id returning * into v_row;
  if v_row.id is null then raise exception 'CAPTION_NOT_FOUND'; end if;
 end if;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return to_jsonb(v_row)||jsonb_build_object('project_revision',v_rev);
end$function$


-- [40000001386] function public.tgg_video_studio_upsert_caption_v2(p_project_id uuid, p_caption_id uuid, p_start_seconds numeric, p_end_seconds numeric, p_text text, p_track_index integer, p_cue_type text, p_style jsonb, p_language_code text, p_speaker text, p_timeline_item_id uuid, p_base_revision bigint)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_upsert_caption_v2(p_project_id uuid, p_caption_id uuid, p_start_seconds numeric, p_end_seconds numeric, p_text text, p_track_index integer DEFAULT 0, p_cue_type text DEFAULT 'caption'::text, p_style jsonb DEFAULT '{}'::jsonb, p_language_code text DEFAULT 'en'::text, p_speaker text DEFAULT NULL::text, p_timeline_item_id uuid DEFAULT NULL::uuid, p_base_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_perm jsonb;
  v_row public.tgg_video_studio_caption_cues;
  v_revision bigint;
  v_new_revision bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_perm:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if coalesce(p_start_seconds,-1)<0 or coalesce(p_end_seconds,0)<=coalesce(p_start_seconds,-1) then raise exception 'CAPTION_TIME_INVALID'; end if;
  if nullif(btrim(coalesce(p_text,'')),'') is null then raise exception 'CAPTION_TEXT_REQUIRED'; end if;
  if coalesce(p_cue_type,'caption') not in ('caption','subtitle','lyric','title','lower_third') then raise exception 'CAPTION_TYPE_INVALID'; end if;
  if jsonb_typeof(coalesce(p_style,'{}'::jsonb))<>'object' then raise exception 'CAPTION_STYLE_INVALID'; end if;

  select revision into v_revision from public.tgg_studio_projects where id=p_project_id for update;
  if v_revision is null then raise exception 'PROJECT_NOT_FOUND'; end if;
  if p_base_revision is not null and p_base_revision<>v_revision then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_revision);
  end if;

  if p_caption_id is null then
    insert into public.tgg_video_studio_caption_cues(project_id,user_id,timeline_item_id,track_index,start_seconds,end_seconds,cue_type,text,speaker,language_code,style)
    values(p_project_id,v_uid,p_timeline_item_id,greatest(0,coalesce(p_track_index,0)),p_start_seconds,p_end_seconds,coalesce(p_cue_type,'caption'),p_text,nullif(btrim(coalesce(p_speaker,'')),''),coalesce(nullif(p_language_code,''),'en'),coalesce(p_style,'{}'::jsonb))
    returning * into v_row;
  else
    update public.tgg_video_studio_caption_cues
    set timeline_item_id=p_timeline_item_id,
        track_index=greatest(0,coalesce(p_track_index,track_index)),
        start_seconds=p_start_seconds,
        end_seconds=p_end_seconds,
        cue_type=coalesce(p_cue_type,cue_type),
        text=p_text,
        speaker=nullif(btrim(coalesce(p_speaker,'')),''),
        language_code=coalesce(nullif(p_language_code,''),language_code),
        style=coalesce(p_style,style),
        updated_at=now()
    where id=p_caption_id and project_id=p_project_id
    returning * into v_row;
    if v_row.id is null then raise exception 'CAPTION_NOT_FOUND'; end if;
  end if;

  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_new_revision;
  return jsonb_build_object('ok',true,'conflict',false,'caption',to_jsonb(v_row),'base_revision',v_revision,'project_revision',v_new_revision);
end
$function$


-- [40000001387] function public.tgg_video_studio_upsert_marker(p_project_id uuid, p_marker_id uuid, p_time_seconds numeric, p_label text, p_marker_type text, p_metadata jsonb, p_timeline_item_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_video_studio_upsert_marker(p_project_id uuid, p_marker_id uuid, p_time_seconds numeric, p_label text DEFAULT ''::text, p_marker_type text DEFAULT 'marker'::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_timeline_item_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'tgg_private', 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_row public.tgg_video_studio_markers; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 if coalesce(p_time_seconds,-1)<0 then raise exception 'MARKER_TIME_INVALID'; end if;
 if p_marker_id is null then insert into public.tgg_video_studio_markers(project_id,user_id,timeline_item_id,time_seconds,marker_type,label,metadata) values(p_project_id,v_uid,p_timeline_item_id,p_time_seconds,coalesce(p_marker_type,'marker'),coalesce(p_label,''),coalesce(p_metadata,'{}'::jsonb)) returning * into v_row;
 else update public.tgg_video_studio_markers set timeline_item_id=p_timeline_item_id,time_seconds=p_time_seconds,marker_type=coalesce(p_marker_type,marker_type),label=coalesce(p_label,label),metadata=coalesce(p_metadata,metadata),updated_at=now() where id=p_marker_id and project_id=p_project_id returning * into v_row; if v_row.id is null then raise exception 'MARKER_NOT_FOUND'; end if; end if;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return to_jsonb(v_row)||jsonb_build_object('project_revision',v_rev);
end$function$


-- [40000001388] function public.tgg_video_submit_from_storage(p_title text, p_storage_path text, p_description text, p_genre text, p_release_date date, p_explicit_content boolean, p_thumbnail_url text, p_allow_downloads boolean)
CREATE OR REPLACE FUNCTION public.tgg_video_submit_from_storage(p_title text, p_storage_path text, p_description text DEFAULT NULL::text, p_genre text DEFAULT NULL::text, p_release_date date DEFAULT NULL::date, p_explicit_content boolean DEFAULT false, p_thumbnail_url text DEFAULT NULL::text, p_allow_downloads boolean DEFAULT false)
 RETURNS public.videos
 LANGUAGE plpgsql
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
    declare
      v_uid uuid := auth.uid();
      v_artist uuid;
      v_title text := btrim(coalesce(p_title,''));
      v_path text := btrim(coalesce(p_storage_path,''));
      v public.videos;
    begin
      if v_uid is null then
        raise exception 'authentication_required' using errcode='42501';
      end if;

      if char_length(v_title) < 1 or char_length(v_title) > 160 then
        raise exception 'title_invalid';
      end if;

      if v_path = '' or split_part(v_path,'/',1) <> v_uid::text then
        raise exception 'storage_path_not_owned';
      end if;

      if not exists (
        select 1 from storage.objects o
        where o.bucket_id='creator-media'
          and o.name=v_path
          and (storage.foldername(o.name))[1]=v_uid::text
      ) then
        raise exception 'uploaded_video_not_found';
      end if;

      select id into v_artist
      from public.artists
      where user_id=v_uid
      order by created_at asc
      limit 1;

      if v_artist is null then
        raise exception 'creator_profile_required';
      end if;

      insert into public.videos(
        artist_id,title,description,genre,release_date,explicit_content,
        video_url,thumbnail_url,visibility,featured,allow_downloads,status,
        storage_bucket,storage_path
      )
      values(
        v_artist,v_title,nullif(btrim(coalesce(p_description,'')),''),
        nullif(btrim(coalesce(p_genre,'')),''),
        p_release_date,p_explicit_content,'',
        nullif(btrim(coalesce(p_thumbnail_url,'')),''),
        'private',false,p_allow_downloads,'pending',
        'creator-media',v_path
      )
      returning * into v;

      insert into public.media_assets(
        id,owner_id,media_type,title,description,storage_bucket,storage_path,
        source_url,status,visibility,metadata,updated_at,published_at
      )
      values(
        v.id,v_uid,'video',v.title,v.description,'creator-media',v_path,
        null,'ready','private',
        jsonb_build_object(
          'source','videos',
          'video_id',v.id::text,
          'review_required',true,
          'review_status','pending'
        ),
        now(),null
      )
      on conflict(id) do update
      set owner_id=excluded.owner_id,
          title=excluded.title,
          description=excluded.description,
          storage_bucket=excluded.storage_bucket,
          storage_path=excluded.storage_path,
          source_url=null,
          status='ready',
          visibility='private',
          metadata=excluded.metadata,
          updated_at=now(),
          published_at=null;

      return v;
    end;
    $function$


