-- [40000001390] function public.tgg_visual_qa_record(p_run_id uuid, p_task_key text, p_spec_key text, p_viewport_key text, p_overlap_count integer, p_clipped_text_count integer, p_duplicate_shell_count integer, p_stuck_loading_count integer, p_accessibility_findings integer, p_findings jsonb, p_screenshot_uri text)
CREATE OR REPLACE FUNCTION public.tgg_visual_qa_record(p_run_id uuid, p_task_key text, p_spec_key text, p_viewport_key text, p_overlap_count integer DEFAULT 0, p_clipped_text_count integer DEFAULT 0, p_duplicate_shell_count integer DEFAULT 0, p_stuck_loading_count integer DEFAULT 0, p_accessibility_findings integer DEFAULT 0, p_findings jsonb DEFAULT '[]'::jsonb, p_screenshot_uri text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_task_id uuid;
  v_spec_id uuid;
  v_status text;
  v_qa_id uuid;
begin
  select id into v_task_id from public.tgg_build_tasks where task_key=p_task_key;
  select id into v_spec_id from public.tgg_design_specs where spec_key=p_spec_key;

  if v_task_id is null or v_spec_id is null then
    raise exception 'task/spec not found';
  end if;

  if coalesce(p_overlap_count,0) > 0
     or coalesce(p_clipped_text_count,0) > 0
     or coalesce(p_duplicate_shell_count,0) > 0
     or coalesce(p_stuck_loading_count,0) > 0
     or coalesce(p_accessibility_findings,0) > 0 then
    v_status := 'failed';
  else
    v_status := 'passed';
  end if;

  insert into public.tgg_visual_qa_results(
    run_id, task_id, design_spec_id, viewport_key, status,
    overlap_count, clipped_text_count, duplicate_shell_count,
    stuck_loading_count, accessibility_findings, findings, screenshot_uri
  )
  values(
    p_run_id, v_task_id, v_spec_id, p_viewport_key, v_status,
    greatest(coalesce(p_overlap_count,0),0),
    greatest(coalesce(p_clipped_text_count,0),0),
    greatest(coalesce(p_duplicate_shell_count,0),0),
    greatest(coalesce(p_stuck_loading_count,0),0),
    greatest(coalesce(p_accessibility_findings,0),0),
    coalesce(p_findings,'[]'::jsonb),
    p_screenshot_uri
  )
  returning id into v_qa_id;

  if v_status='failed' then
    insert into public.tgg_build_failures(
      run_id, task_id, failure_key, category, severity, status, message, detail
    )
    values(
      p_run_id,
      v_task_id,
      'visual:' || p_spec_key || ':' || coalesce(p_viewport_key,'unknown'),
      'visual_qa',
      'error',
      'open',
      'Visual QA failed for ' || p_spec_key || ' @ ' || coalesce(p_viewport_key,'unknown'),
      jsonb_build_object(
        'overlap_count',greatest(coalesce(p_overlap_count,0),0),
        'clipped_text_count',greatest(coalesce(p_clipped_text_count,0),0),
        'duplicate_shell_count',greatest(coalesce(p_duplicate_shell_count,0),0),
        'stuck_loading_count',greatest(coalesce(p_stuck_loading_count,0),0),
        'accessibility_findings',greatest(coalesce(p_accessibility_findings,0),0),
        'findings',coalesce(p_findings,'[]'::jsonb)
      )
    );
  end if;

  return jsonb_build_object('qa_id',v_qa_id,'status',v_status);
end;
$function$


