-- [40000001403] function public.tgg_world_character_bundle()
CREATE OR REPLACE FUNCTION public.tgg_world_character_bundle()
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select case
    when c.id is null then
      jsonb_build_object('character_required',true)
    else
      jsonb_build_object(
        'character_required',false,
        'character',to_jsonb(c),
        'stats',coalesce((
          select jsonb_object_agg(s.stat_key,s.stat_value order by s.stat_key)
          from public.world_character_stats s
          where s.character_id=c.id
        ),'{}'::jsonb),
        'careers',coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'career_key',cr.career_key,
              'career_level',cr.career_level,
              'career_xp',cr.career_xp,
              'unlocked',cr.unlocked,
              'metadata',cr.metadata
            )
            order by cr.career_key
          )
          from public.world_character_careers cr
          where cr.character_id=c.id
        ),'[]'::jsonb)
      )
  end
  from (select auth.uid() as uid) u
  left join public.world_characters c on c.user_id=u.uid;
$function$


