    jsonb_build_object(
      'location_key',p_location_key,
      'rotation',coalesce(p_rotation,'{"yaw":0}'::jsonb)
    )
  ) into v_heartbeat;

  return v_join || jsonb_build_object(
    'position',coalesce(p_position,'{"x":0,"y":0,"z":0}'::jsonb),
    'rotation',coalesce(p_rotation,'{"yaw":0}'::jsonb),
    'heartbeat',v_heartbeat
  );
end;
$function$


-- [40000001446] function public.tgg_world_leave()
CREATE OR REPLACE FUNCTION public.tgg_world_leave()
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_count integer := 0;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;

  update public.tgg_world_presence
  set presence_state='offline',last_seen_at=now(),activity='{}'::jsonb
  where user_id=(select auth.uid())
    and presence_state <> 'offline';

  get diagnostics v_count = row_count;
  return v_count > 0;
end;
$function$


