-- [40000001460] function public.tgg_world_mvp_v1_accept_mission(p_mission_code text)
CREATE OR REPLACE FUNCTION public.tgg_world_mvp_v1_accept_mission(p_mission_code text)
 RETURNS public.tgg_world_player_missions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_uid uuid:=auth.uid(); v_mission public.tgg_world_missions; v_pm public.tgg_world_player_missions; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; perform public.tgg_world_mvp_v1_bootstrap_player(); select * into v_mission from public.tgg_world_missions where code=p_mission_code and active=true; if v_mission.id is null then raise exception 'MISSION_NOT_FOUND'; end if; insert into public.tgg_world_player_missions(user_id,mission_id,status) values(v_uid,v_mission.id,'accepted') on conflict(user_id,mission_id) do update set updated_at=now() returning * into v_pm; update public.tgg_world_players set state='in_mission',updated_at=now() where user_id=v_uid; return v_pm; end $function$


-- [40000001461] function public.tgg_world_mvp_v1_bootstrap_player()
CREATE OR REPLACE FUNCTION public.tgg_world_mvp_v1_bootstrap_player()
 RETURNS public.tgg_world_players
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid(); v_player public.tgg_world_players; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; insert into public.tgg_world_players(user_id,state) values(v_uid,'initialized') on conflict(user_id) do update set last_seen_at=now(), updated_at=now() returning * into v_player; insert into public.tgg_world_wallets_v10(user_id) values(v_uid) on conflict(user_id) do nothing; return v_player; end $function$


-- [40000001462] function public.tgg_world_mvp_v1_complete_mission(p_mission_code text, p_evidence jsonb)
CREATE OR REPLACE FUNCTION public.tgg_world_mvp_v1_complete_mission(p_mission_code text, p_evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_uid uuid:=auth.uid(); v_mission public.tgg_world_missions; v_pm public.tgg_world_player_missions; v_key text; v_rows int; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; select * into v_mission from public.tgg_world_missions where code=p_mission_code and active=true; if v_mission.id is null then raise exception 'MISSION_NOT_FOUND'; end if; select * into v_pm from public.tgg_world_player_missions where user_id=v_uid and mission_id=v_mission.id for update; if v_pm.id is null then raise exception 'MISSION_NOT_ACCEPTED'; end if; update public.tgg_world_player_missions set status=case when status='rewarded' then status else 'completed' end,evidence=evidence||jsonb_build_array(coalesce(p_evidence,'{}'::jsonb)),completed_at=coalesce(completed_at,now()),updated_at=now() where id=v_pm.id; v_key:=v_uid::text||':'||v_pm.id::text||':completion'; insert into public.tgg_world_reward_ledger(user_id,mission_id,player_mission_id,grant_key,xp,reputation,audience,credits,unlocks,metadata) values(v_uid,v_mission.id,v_pm.id,v_key,v_mission.reward_xp,v_mission.reward_reputation,v_mission.reward_audience,v_mission.reward_credits,v_mission.reward_unlocks,jsonb_build_object('mission_code',v_mission.code)) on conflict(grant_key) do nothing; get diagnostics v_rows=row_count; if v_rows=1 then update public.tgg_world_players set xp=xp+v_mission.reward_xp,reputation=reputation+v_mission.reward_reputation,audience=audience+v_mission.reward_audience,state='active',updated_at=now() where user_id=v_uid; update public.tgg_world_wallets_v10 set credits=credits+v_mission.reward_credits,updated_at=now() where user_id=v_uid; update public.tgg_world_player_missions set status='rewarded',rewarded_at=now(),updated_at=now() where id=v_pm.id; end if; return jsonb_build_object('ok',true,'mission_code',v_mission.code,'reward_granted',(v_rows=1),'grant_key',v_key); end $function$


-- [40000001463] function public.tgg_world_mvp_v1_link_project(p_mission_code text, p_project_id uuid, p_session_id uuid, p_artifact_id uuid, p_source_tool text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.tgg_world_mvp_v1_link_project(p_mission_code text, p_project_id uuid, p_session_id uuid, p_artifact_id uuid DEFAULT NULL::uuid, p_source_tool text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS public.tgg_world_project_links
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid(); v_mid uuid; v_link public.tgg_world_project_links; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; if p_project_id is null or p_session_id is null then raise exception 'PROJECT_AND_SESSION_REQUIRED'; end if; select id into v_mid from public.tgg_world_missions where code=p_mission_code and active=true; insert into public.tgg_world_project_links(user_id,mission_id,project_id,session_id,artifact_id,source_tool,state,metadata) values(v_uid,v_mid,p_project_id,p_session_id,p_artifact_id,p_source_tool,'active',coalesce(p_metadata,'{}'::jsonb)) returning * into v_link; update public.tgg_world_players set state='in_session',updated_at=now() where user_id=v_uid; return v_link; end $function$


