      jsonb_build_object('key','crew','enabled',true)
    )
  );
$function$


-- [40000001482] function public.tgg_world_phone_save_state(p_active_module text, p_pinned_modules jsonb, p_preferences jsonb)
CREATE OR REPLACE FUNCTION public.tgg_world_phone_save_state(p_active_module text, p_pinned_modules jsonb DEFAULT NULL::jsonb, p_preferences jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_allowed text[] := array['home','messages','friends','music','map','creator_os','events','crew'];
  v_row public.tgg_world_phone_state%rowtype;
begin
  if v_user is null then raise exception 'authentication required'; end if;
  if p_active_module is null or not (p_active_module = any(v_allowed)) then
    raise exception 'unsupported phone module';
  end if;

  insert into public.tgg_world_phone_state(user_id,active_module,pinned_modules,preferences,updated_at)
  values(
    v_user,
    p_active_module,
    coalesce(p_pinned_modules,jsonb_build_array('messages','friends','music','map','creator_os')),
    coalesce(p_preferences,'{}'::jsonb),
    now()
  )
  on conflict(user_id) do update
  set active_module=excluded.active_module,
      pinned_modules=coalesce(p_pinned_modules,public.tgg_world_phone_state.pinned_modules),
      preferences=coalesce(p_preferences,public.tgg_world_phone_state.preferences),
      updated_at=now()
  returning * into v_row;

  return to_jsonb(v_row);
end;
$function$


