-- [40000001509] function public.tgg_world_studio_bundle(p_session_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_world_studio_bundle(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_session jsonb;
  v_members jsonb;
  v_project jsonb;
begin
  select to_jsonb(s) into v_session
  from public.tgg_world_studio_sessions s
  where s.id=p_session_id;

  if v_session is null then
    return null;
  end if;

  select coalesce(jsonb_agg(to_jsonb(m) order by m.joined_at),'[]'::jsonb)
  into v_members
  from public.tgg_world_studio_session_members m
  where m.session_id=p_session_id
    and m.left_at is null;

  select case
    when s.studio_project_id is null then null
    else (
      select jsonb_build_object(
        'id',p.id,
        'title',p.title,
        'project_type',p.project_type,
        'status',p.status,
        'revision',p.revision
      )
      from public.tgg_studio_projects p
      where p.id=s.studio_project_id
    )
  end
  into v_project
  from public.tgg_world_studio_sessions s
  where s.id=p_session_id;

  return jsonb_build_object(
    'session',v_session,
    'members',v_members,
    'creator_os_project',v_project,
    'rights_transfer',false,
    'real_money',false
  );
end;
$function$


