-- [40000001542] function public.tgg_world_v11_visual_bundle()
CREATE OR REPLACE FUNCTION public.tgg_world_v11_visual_bundle()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'ok', auth.uid() is not null,
    'version', 'WORLD-V11-VISUAL-1.0',
    'avatar', coalesce((
      select a.profile
      from public.tgg_world_avatar_profiles a
      where a.user_id = (select auth.uid())
      limit 1
    ), '{}'::jsonb),
    'equipped_style', coalesce((
      select jsonb_agg(jsonb_build_object(
        'item_key', c.item_key,
        'display_name', c.display_name,
        'slot_key', c.slot_key,
        'metadata', c.metadata
      ) order by c.slot_key, c.item_key)
      from public.tgg_world_inventory i
      join public.tgg_world_shop_catalog c on c.item_key = i.item_key
      where i.user_id = (select auth.uid())
        and i.equipped = true
        and (c.metadata->>'v11') = 'true'
    ), '[]'::jsonb),
    'active_loadout', coalesce((
      select jsonb_build_object('id',l.id,'name',l.name,'slots',l.slots)
      from public.tgg_world_style_loadouts l
      where l.user_id = (select auth.uid()) and l.active = true
      order by l.updated_at desc
      limit 1
    ), '{}'::jsonb),
    'custom_items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', i.id,
        'slot_key', i.slot_key,
        'display_name', i.display_name,
        'metadata', i.metadata
      ) order by i.created_at desc)
      from public.tgg_world_custom_style_items i
      where i.user_id = (select auth.uid())
    ), '[]'::jsonb)
  );
$function$


