 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_headers jsonb := '{}'::jsonb;
  v_origin text := '';
  v_build text := coalesce(p_capture->>'build','');
  v_path text := coalesce(p_capture->>'page_path','');
  v_move numeric := greatest(0,least(10000,coalesce((p_capture->>'moved_distance')::numeric,0)));
  v_frames integer := greatest(0,least(100000,coalesce((p_capture->>'frame_sample_count')::integer,0)));
  v_load integer := greatest(0,least(120000,coalesce((p_capture->>'load_ms')::integer,0)));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  begin
    v_headers := coalesce(nullif(current_setting('request.headers',true),'')::jsonb,'{}'::jsonb);
  exception when others then
    v_headers := '{}'::jsonb;
  end;
  v_origin := coalesce(v_headers->>'origin','');
  if not (
    v_origin='https://trugogettamixtapes.blogspot.com'
    or v_origin='https://xsofowzvwetamhyuvlpj.supabase.co'
    or v_origin ~ '^https://([a-z0-9-]+\.)?trugogettamixtapes\.com$'
  ) then raise exception 'BROWSER_ORIGIN_REQUIRED' using errcode='42501'; end if;
  if v_build<>'WORLD-V14.9-PLAYTEST-GATE' or v_path<>'/p/artist-world.html' then
    raise exception 'UNAPPROVED_WORLD_PLAYTEST_BUILD' using errcode='22023';
  end if;
  if coalesce((p_capture->>'browser_context')::boolean,false) is not true
     or coalesce((p_capture->>'auth_present')::boolean,false) is not true
     or coalesce((p_capture->>'rendered')::boolean,false) is not true
     or coalesce((p_capture->>'webgl_context')::boolean,false) is not true
     or coalesce((p_capture->>'avatar_moved')::boolean,false) is not true
     or coalesce((p_capture->>'all_v14_layers_present')::boolean,false) is not true
     or coalesce((p_capture->>'blocking_error_count')::integer,1) <> 0
     or v_move < 2
     or v_frames < 30
     or v_load <= 0
     or coalesce((p_capture->>'renderer_width')::integer,0) < 240
     or coalesce((p_capture->>'renderer_height')::integer,0) < 160
  then raise exception 'WORLD_PLAYTEST_EVIDENCE_INCOMPLETE' using errcode='22023'; end if;

  insert into public.tgg_world_v14_playtest_evidence(user_id,status,build,page_path,moved_distance,frame_sample_count,load_ms,capture,observed_at,updated_at)
  values(v_uid,'passed',v_build,v_path,v_move,v_frames,v_load,(p_capture-'access_token'-'refresh_token'-'user_id'-'email'),now(),now())
  on conflict(user_id) do update set
    status='passed',build=excluded.build,page_path=excluded.page_path,moved_distance=greatest(public.tgg_world_v14_playtest_evidence.moved_distance,excluded.moved_distance),
    frame_sample_count=greatest(public.tgg_world_v14_playtest_evidence.frame_sample_count,excluded.frame_sample_count),load_ms=excluded.load_ms,
    capture=excluded.capture,observed_at=excluded.observed_at,updated_at=excluded.updated_at;

  return jsonb_build_object('ok',true,'status','passed','build',v_build,'moved_distance',v_move,'frame_sample_count',v_frames,'observed_at',now());
end;
$function$


-- [40000001555] function public.tgg_world_v14_playtest_status()
CREATE OR REPLACE FUNCTION public.tgg_world_v14_playtest_status()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select coalesce(
    (select jsonb_build_object('status',e.status,'build',e.build,'moved_distance',e.moved_distance,'frame_sample_count',e.frame_sample_count,'observed_at',e.observed_at)
     from public.tgg_world_v14_playtest_evidence e where e.user_id=(select auth.uid())),
    jsonb_build_object('status','pending')
  );
$function$


-- [40000001556] function public.tgg_world_v2_create_crew(p_name text, p_slug text)
CREATE OR REPLACE FUNCTION public.tgg_world_v2_create_crew(p_name text, p_slug text DEFAULT NULL::text)
 RETURNS public.tgg_world_crews_v10
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_crew public.tgg_world_crews_v10;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;if coalesce(trim(p_name),'')='' then raise exception 'CREW_NAME_REQUIRED';end if;insert into public.tgg_world_crews_v10(owner_user_id,name,slug) values(v_uid,trim(p_name),nullif(trim(p_slug),'')) returning * into v_crew;insert into public.tgg_world_crew_members_v10(crew_id,user_id,role,status,joined_at) values(v_crew.id,v_uid,'owner','active',now()) on conflict(crew_id,user_id) do update set role='owner',status='active',joined_at=coalesce(tgg_world_crew_members_v10.joined_at,now());update public.tgg_world_players set crew_id=v_crew.id,updated_at=now() where user_id=v_uid;return v_crew;end $function$


-- [40000001557] function public.tgg_world_v2_create_event(p_event_type text, p_title text, p_starts_at timestamp with time zone, p_project_id uuid, p_session_id uuid, p_visibility text)
CREATE OR REPLACE FUNCTION public.tgg_world_v2_create_event(p_event_type text, p_title text, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_project_id uuid DEFAULT NULL::uuid, p_session_id uuid DEFAULT NULL::uuid, p_visibility text DEFAULT 'public'::text)
 RETURNS public.tgg_world_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_event public.tgg_world_events;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;if p_event_type not in('concert','rap_battle','beat_battle','listening_party','live_studio','supporter_event','crew_event') then raise exception 'INVALID_EVENT_TYPE';end if;insert into public.tgg_world_events(host_user_id,event_type,title,starts_at,project_id,session_id,visibility,status) values(v_uid,p_event_type,trim(p_title),p_starts_at,p_project_id,p_session_id,p_visibility,case when p_starts_at is null or p_starts_at<=now() then 'lobby_open' else 'scheduled' end) returning * into v_event;insert into public.tgg_world_event_participants(event_id,user_id,role,joined_at) values(v_event.id,v_uid,'host',now()) on conflict(event_id,user_id) do nothing;return v_event;end $function$


-- [40000001558] function public.tgg_world_v2_finalize_event(p_event_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_world_v2_finalize_event(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_event public.tgg_world_events;v_peak integer;v_reactions bigint;v_votes bigint;v_energy numeric;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_event from public.tgg_world_events where id=p_event_id for update;if v_event.id is null then raise exception 'EVENT_NOT_FOUND';end if;if v_event.host_user_id<>v_uid then raise exception 'HOST_REQUIRED';end if;select count(*) into v_peak from public.tgg_world_event_participants where event_id=p_event_id;select count(*) into v_reactions from public.tgg_world_event_signals where event_id=p_event_id and signal_type in('reaction','cheer');select count(*) into v_votes from public.tgg_world_event_signals where event_id=p_event_id and signal_type='vote';v_energy:=least(100,(coalesce(v_reactions,0)*1.5+coalesce(v_votes,0)*2.0+coalesce(v_peak,0)));insert into public.tgg_world_event_results(event_id,peak_audience,total_reactions,total_votes,crowd_energy,finalized_at) values(p_event_id,v_peak,v_reactions,v_votes,v_energy,now()) on conflict(event_id) do update set peak_audience=excluded.peak_audience,total_reactions=excluded.total_reactions,total_votes=excluded.total_votes,crowd_energy=excluded.crowd_energy,finalized_at=excluded.finalized_at;update public.tgg_world_events set status='completed',ends_at=coalesce(ends_at,now()),updated_at=now() where id=p_event_id;update public.tgg_world_players set state='active',updated_at=now() where user_id=v_uid;return jsonb_build_object('ok',true,'event_id',p_event_id,'peak_audience',v_peak,'reactions',v_reactions,'votes',v_votes,'crowd_energy',v_energy);end $function$


-- [40000001559] function public.tgg_world_v2_join_crew(p_crew_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_world_v2_join_crew(p_crew_id uuid)
 RETURNS public.tgg_world_crew_members_v10
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_crew public.tgg_world_crews_v10;v_member public.tgg_world_crew_members_v10;v_invite public.tgg_world_crew_invites;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_crew from public.tgg_world_crews_v10 where id=p_crew_id;if v_crew.id is null then raise exception 'CREW_NOT_FOUND';end if;if v_crew.visibility='private' then raise exception 'CREW_NOT_JOINABLE';end if;if v_crew.visibility='invite_only' then select * into v_invite from public.tgg_world_crew_invites where crew_id=p_crew_id and invited_user_id=v_uid and status='pending' and(expires_at is null or expires_at>=now()) for update;if v_invite.id is null then raise exception 'VALID_CREW_INVITE_REQUIRED';end if;update public.tgg_world_crew_invites set status='accepted',responded_at=now() where id=v_invite.id;end if;insert into public.tgg_world_crew_members_v10(crew_id,user_id,role,status,joined_at) values(p_crew_id,v_uid,'member','active',now()) on conflict(crew_id,user_id) do update set status='active',joined_at=coalesce(tgg_world_crew_members_v10.joined_at,now()) returning * into v_member;update public.tgg_world_players set crew_id=p_crew_id,updated_at=now() where user_id=v_uid;return v_member;end $function$


-- [40000001560] function public.tgg_world_v2_join_event(p_event_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_world_v2_join_event(p_event_id uuid)
 RETURNS public.tgg_world_event_participants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_event public.tgg_world_events;
  v_participant public.tgg_world_event_participants;
  v_allowed boolean:=false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  select * into v_event from public.tgg_world_events where id=p_event_id;
  if v_event.id is null then raise exception 'EVENT_NOT_FOUND'; end if;
  if v_event.status in ('completed','archived','cancelled') then raise exception 'EVENT_CLOSED'; end if;
  v_allowed := v_event.visibility='public' or v_event.host_user_id=v_uid or exists(select 1 from public.tgg_world_event_access a where a.event_id=p_event_id and a.user_id=v_uid and (a.expires_at is null or a.expires_at>=now())) or (v_event.visibility='crew' and v_event.crew_id is not null and exists(select 1 from public.tgg_world_crew_members_v10 cm where cm.crew_id=v_event.crew_id and cm.user_id=v_uid and cm.status='active'));
  if not v_allowed then raise exception 'EVENT_ACCESS_REQUIRED'; end if;
  insert into public.tgg_world_event_participants(event_id,user_id,role,joined_at) values(p_event_id,v_uid,'audience',now()) on conflict(event_id,user_id) do update set joined_at=coalesce(tgg_world_event_participants.joined_at,now()),left_at=null returning * into v_participant;
  insert into public.tgg_world_event_signals(event_id,user_id,signal_type) values(p_event_id,v_uid,'join');
  update public.tgg_world_players set state='in_event',updated_at=now() where user_id=v_uid;
  return v_participant;
end;$function$


-- [40000001561] function public.tgg_world_v2_signal_event(p_event_id uuid, p_signal_type text, p_value numeric, p_payload jsonb)
CREATE OR REPLACE FUNCTION public.tgg_world_v2_signal_event(p_event_id uuid, p_signal_type text, p_value numeric DEFAULT NULL::numeric, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_uid uuid:=auth.uid();v_id uuid;v_event_status text;begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_signal_type not in('reaction','cheer','vote','chat','tip_event') then raise exception 'INVALID_SIGNAL';end if;
 select status into v_event_status from public.tgg_world_events where id=p_event_id;
 if v_event_status is null then raise exception 'EVENT_NOT_FOUND';end if;
 if v_event_status not in('lobby_open','live','intermission') then raise exception 'EVENT_NOT_INTERACTIVE';end if;
 if not exists(select 1 from public.tgg_world_event_participants where event_id=p_event_id and user_id=v_uid and left_at is null) then raise exception 'EVENT_JOIN_REQUIRED';end if;
 if p_signal_type='vote' and exists(select 1 from public.tgg_world_event_signals where event_id=p_event_id and user_id=v_uid and signal_type='vote') then raise exception 'VOTE_ALREADY_CAST';end if;
 insert into public.tgg_world_event_signals(event_id,user_id,signal_type,value,payload) values(p_event_id,v_uid,p_signal_type,p_value,coalesce(p_payload,'{}'::jsonb)) returning id into v_id;
 return v_id;end$function$


-- [40000001562] function public.tgg_world_v3_queue_event_replay(p_event_id uuid, p_project_id uuid, p_session_id uuid, p_artifact_id uuid, p_target text, p_replay_kind text, p_payload jsonb)
CREATE OR REPLACE FUNCTION public.tgg_world_v3_queue_event_replay(p_event_id uuid, p_project_id uuid DEFAULT NULL::uuid, p_session_id uuid DEFAULT NULL::uuid, p_artifact_id uuid DEFAULT NULL::uuid, p_target text DEFAULT 'vault'::text, p_replay_kind text DEFAULT 'event_replay'::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS public.tgg_world_vault_handoffs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_event public.tgg_world_events;v_row public.tgg_world_vault_handoffs;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_event from public.tgg_world_events where id=p_event_id;if v_event.id is null then raise exception 'EVENT_NOT_FOUND';end if;if v_event.host_user_id<>v_uid and not exists(select 1 from public.tgg_world_event_participants ep where ep.event_id=p_event_id and ep.user_id=v_uid) then raise exception 'EVENT_ACCESS_REQUIRED';end if;insert into public.tgg_world_vault_handoffs(user_id,event_id,project_id,session_id,artifact_id,replay_kind,target,status,payload) values(v_uid,p_event_id,p_project_id,p_session_id,p_artifact_id,p_replay_kind,p_target,'queued',coalesce(p_payload,'{}'::jsonb)) returning * into v_row;return v_row;end $function$


-- [40000001563] function public.tgg_world_v3_request_session_launch(p_location_key text, p_property_id uuid, p_mission_code text, p_project_id uuid, p_session_id uuid, p_requested_tool text, p_handoff_payload jsonb)
CREATE OR REPLACE FUNCTION public.tgg_world_v3_request_session_launch(p_location_key text DEFAULT NULL::text, p_property_id uuid DEFAULT NULL::uuid, p_mission_code text DEFAULT NULL::text, p_project_id uuid DEFAULT NULL::uuid, p_session_id uuid DEFAULT NULL::uuid, p_requested_tool text DEFAULT 'recording'::text, p_handoff_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS public.tgg_world_session_launches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_location_id uuid;
  v_mission_id uuid;
  v_row public.tgg_world_session_launches;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;

  if p_requested_tool not in ('recording','beat','video') then
    raise exception 'UNSUPPORTED_CREATOR_TOOL';
  end if;

  if p_location_key is not null then
    select id into v_location_id
    from public.tgg_world_locations_v10
    where location_key=p_location_key and active=true;
    if v_location_id is null then raise exception 'LOCATION_NOT_FOUND'; end if;
  end if;

  if p_property_id is not null and not public.tgg_world_v10_can_view_property(p_property_id) then
    raise exception 'PROPERTY_ACCESS_REQUIRED';
  end if;

  if p_mission_code is not null then
    select id into v_mission_id
    from public.tgg_world_missions
    where code=p_mission_code and active=true;
    if v_mission_id is null then raise exception 'MISSION_NOT_FOUND'; end if;
    if not exists(
      select 1 from public.tgg_world_player_missions pm
      where pm.user_id=v_uid and pm.mission_id=v_mission_id
        and pm.status in ('accepted','in_progress','evidence_pending')
    ) then
      raise exception 'MISSION_NOT_ACCEPTED';
    end if;
  end if;

  insert into public.tgg_world_session_launches(
    user_id,location_id,property_id,mission_id,project_id,session_id,requested_tool,status,handoff_payload
  ) values (
    v_uid,v_location_id,p_property_id,v_mission_id,p_project_id,p_session_id,p_requested_tool,'requested',coalesce(p_handoff_payload,'{}'::jsonb)
  ) returning * into v_row;

  return v_row;
end
$function$


-- [40000001564] function public.tgg_world_v3_start_career_chain(p_chain_key text)
CREATE OR REPLACE FUNCTION public.tgg_world_v3_start_career_chain(p_chain_key text)
 RETURNS public.tgg_world_player_career
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_chain public.tgg_world_career_chains;v_first text;v_row public.tgg_world_player_career;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_chain from public.tgg_world_career_chains where chain_key=p_chain_key and active=true;if v_chain.id is null then raise exception 'CHAIN_NOT_FOUND';end if;select step_key into v_first from public.tgg_world_career_steps where chain_id=v_chain.id order by step_order asc limit 1;insert into public.tgg_world_player_career(user_id,chain_id,current_step_key,status) values(v_uid,v_chain.id,v_first,'active') on conflict(user_id,chain_id) do update set status='active',updated_at=now() returning * into v_row;return v_row;end $function$


