-- [40000001566] function public.tgg_world_v3_unlock_contact(p_contact_key text)
CREATE OR REPLACE FUNCTION public.tgg_world_v3_unlock_contact(p_contact_key text)
 RETURNS public.tgg_world_player_contacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_contact public.tgg_world_contacts;v_player public.tgg_world_players;v_row public.tgg_world_player_contacts;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_contact from public.tgg_world_contacts where contact_key=p_contact_key and availability<>'inactive';if v_contact.id is null then raise exception 'CONTACT_NOT_FOUND';end if;select * into v_player from public.tgg_world_players where user_id=v_uid;if v_player.id is null then perform public.tgg_world_mvp_v1_bootstrap_player();select * into v_player from public.tgg_world_players where user_id=v_uid;end if;if v_player.reputation<v_contact.reputation_required then raise exception 'REPUTATION_REQUIRED';end if;insert into public.tgg_world_player_contacts(user_id,contact_id,relationship_level,trust,unlocked_at,last_interaction_at) values(v_uid,v_contact.id,'introduced',5,now(),now()) on conflict(user_id,contact_id) do update set last_interaction_at=now() returning * into v_row;return v_row;end $function$


-- [40000001567] function public.tgg_world_v4_accept_offer(p_offer_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_world_v4_accept_offer(p_offer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_offer public.tgg_world_contact_offers;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_offer from public.tgg_world_contact_offers where id=p_offer_id and user_id=v_uid for update;if v_offer.id is null then raise exception 'OFFER_NOT_FOUND';end if;if v_offer.status<>'pending' then raise exception 'OFFER_NOT_PENDING';end if;if v_offer.expires_at is not null and v_offer.expires_at<now() then update public.tgg_world_contact_offers set status='expired',responded_at=now() where id=v_offer.id;raise exception 'OFFER_EXPIRED';end if;update public.tgg_world_contact_offers set status='accepted',responded_at=now() where id=v_offer.id;insert into public.tgg_world_contact_messages(user_id,contact_id,direction,message_type,body,payload) values(v_uid,v_offer.contact_id,'system','offer','Offer accepted: '||v_offer.title,jsonb_build_object('offer_id',v_offer.id,'offer_type',v_offer.offer_type));insert into public.tgg_world_notifications(user_id,notification_type,title,body,action_type,action_payload,priority) values(v_uid,case when v_offer.offer_type='show_booking' then 'calendar' else 'contact' end,'Offer accepted',v_offer.title,case when v_offer.project_id is not null then 'resume' else 'open' end,jsonb_build_object('offer_id',v_offer.id,'project_id',v_offer.project_id,'session_id',v_offer.session_id),'normal');return jsonb_build_object('ok',true,'offer_id',v_offer.id,'status','accepted');end $function$


-- [40000001568] function public.tgg_world_v4_buy_property_upgrade(p_property_id uuid, p_upgrade_key text)
CREATE OR REPLACE FUNCTION public.tgg_world_v4_buy_property_upgrade(p_property_id uuid, p_upgrade_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_property public.tgg_world_properties;v_upgrade public.tgg_world_property_upgrade_catalog;v_player public.tgg_world_players;v_wallet public.tgg_world_wallets_v10;v_grant_key text;v_inserted integer:=0;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_property from public.tgg_world_properties where id=p_property_id for update;if v_property.id is null then raise exception 'PROPERTY_NOT_FOUND';end if;if not(v_property.owner_user_id=v_uid or exists(select 1 from public.tgg_world_crew_members_v10 m where v_property.crew_id is not null and m.crew_id=v_property.crew_id and m.user_id=v_uid and m.status='active' and m.role in('owner','admin'))) then raise exception 'PROPERTY_UPGRADE_PERMISSION_REQUIRED';end if;select * into v_upgrade from public.tgg_world_property_upgrade_catalog where upgrade_key=p_upgrade_key and active=true;if v_upgrade.upgrade_key is null then raise exception 'UPGRADE_NOT_FOUND';end if;if v_upgrade.property_type<>v_property.property_type then raise exception 'UPGRADE_PROPERTY_TYPE_MISMATCH';end if;if v_property.tier<v_upgrade.tier_required then raise exception 'PROPERTY_TIER_REQUIRED';end if;select * into v_player from public.tgg_world_players where user_id=v_uid;if v_player.id is null then raise exception 'WORLD_PLAYER_REQUIRED';end if;if v_player.reputation<v_upgrade.unlock_reputation then raise exception 'REPUTATION_REQUIRED';end if;insert into public.tgg_world_wallets_v10(user_id) values(v_uid) on conflict(user_id) do nothing;select * into v_wallet from public.tgg_world_wallets_v10 where user_id=v_uid for update;if v_wallet.credits<v_upgrade.credit_cost then raise exception 'INSUFFICIENT_WORLD_CREDITS';end if;v_grant_key:=v_uid::text||':'||p_property_id::text||':'||p_upgrade_key;insert into public.tgg_world_property_upgrade_ledger(user_id,property_id,upgrade_key,grant_key,credit_cost,status) values(v_uid,p_property_id,p_upgrade_key,v_grant_key,v_upgrade.credit_cost,'granted') on conflict(grant_key) do nothing;get diagnostics v_inserted=row_count;if v_inserted=1 then update public.tgg_world_wallets_v10 set credits=credits-v_upgrade.credit_cost,updated_at=now() where user_id=v_uid;insert into public.tgg_world_property_upgrades_v10(property_id,upgrade_key,owner_user_id) values(p_property_id,p_upgrade_key,v_uid) on conflict(property_id,upgrade_key) do nothing;update public.tgg_world_properties set upgrades=upgrades||jsonb_build_object(p_upgrade_key,jsonb_build_object('installed_at',now(),'effects',v_upgrade.effects)),updated_at=now() where id=p_property_id;end if;return jsonb_build_object('ok',true,'property_id',p_property_id,'upgrade_key',p_upgrade_key,'new_grant',v_inserted=1,'credit_cost',v_upgrade.credit_cost);end $function$


-- [40000001569] function public.tgg_world_v4_mark_notification_read(p_notification_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_world_v4_mark_notification_read(p_notification_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_rows integer:=0;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;update public.tgg_world_notifications set read_at=coalesce(read_at,now()) where id=p_notification_id and user_id=v_uid;get diagnostics v_rows=row_count;perform public.tgg_world_v4_phone_bootstrap();return v_rows=1;end $function$


-- [40000001570] function public.tgg_world_v4_phone_bootstrap()
CREATE OR REPLACE FUNCTION public.tgg_world_v4_phone_bootstrap()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_unread integer;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;insert into public.tgg_world_phone_state_v10(user_id,last_opened_at) values(v_uid,now()) on conflict(user_id) do update set last_opened_at=now(),updated_at=now();select count(*) into v_unread from public.tgg_world_notifications where user_id=v_uid and read_at is null and dismissed_at is null;update public.tgg_world_phone_state_v10 set unread_count=v_unread,updated_at=now() where user_id=v_uid;return jsonb_build_object('ok',true,'unread_count',v_unread);end $function$


-- [40000001571] function public.tgg_world_v4_playable_loop_health()
CREATE OR REPLACE FUNCTION public.tgg_world_v4_playable_loop_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_player_ready boolean;v_wallet_ready boolean;v_missions_ready boolean;v_phone_ready boolean;v_locations_ready boolean;v_contacts_ready boolean;v_crew_ready boolean;v_events_ready boolean;v_session_bridge_ready boolean;v_vault_bridge_ready boolean;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select exists(select 1 from public.tgg_world_players where user_id=v_uid) into v_player_ready;select exists(select 1 from public.tgg_world_wallets_v10 where user_id=v_uid) into v_wallet_ready;select exists(select 1 from public.tgg_world_missions where active=true) into v_missions_ready;select exists(select 1 from public.tgg_world_phone_state_v10 where user_id=v_uid) into v_phone_ready;select exists(select 1 from public.tgg_world_locations_v10 where active=true) into v_locations_ready;select exists(select 1 from public.tgg_world_contacts where availability<>'inactive') into v_contacts_ready;select to_regclass('public.tgg_world_crews_v10') is not null into v_crew_ready;select to_regclass('public.tgg_world_events') is not null into v_events_ready;select to_regclass('public.tgg_world_session_launches') is not null into v_session_bridge_ready;select to_regclass('public.tgg_world_vault_handoffs') is not null into v_vault_bridge_ready;return jsonb_build_object('ok',v_player_ready and v_wallet_ready and v_missions_ready and v_phone_ready and v_locations_ready and v_contacts_ready and v_crew_ready and v_events_ready and v_session_bridge_ready and v_vault_bridge_ready,'version','TGG-WORLD-PLAYABLE-LOOP-V4','checks',jsonb_build_object('player',v_player_ready,'wallet',v_wallet_ready,'missions',v_missions_ready,'phone',v_phone_ready,'locations',v_locations_ready,'contacts',v_contacts_ready,'crews',v_crew_ready,'events',v_events_ready,'creator_session_bridge',v_session_bridge_ready,'vault_handoff_bridge',v_vault_bridge_ready));end $function$


-- [40000001572] function public.tgg_world_v4_record_mission_evidence(p_mission_code text, p_evidence_type text, p_source_table text, p_source_id uuid, p_source_key text, p_payload jsonb)
CREATE OR REPLACE FUNCTION public.tgg_world_v4_record_mission_evidence(p_mission_code text, p_evidence_type text, p_source_table text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid, p_source_key text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_mission public.tgg_world_missions;v_pm public.tgg_world_player_missions;v_evidence_id uuid;v_verified boolean:=false;v_project_id uuid;v_session_id uuid;v_event_id uuid;begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 select * into v_mission from public.tgg_world_missions where code=p_mission_code and active=true;if v_mission.id is null then raise exception 'MISSION_NOT_FOUND';end if;
 select * into v_pm from public.tgg_world_player_missions where user_id=v_uid and mission_id=v_mission.id;if v_pm.id is null then raise exception 'MISSION_NOT_ACCEPTED';end if;
 v_project_id:=nullif(p_payload->>'project_id','')::uuid;v_session_id:=nullif(p_payload->>'session_id','')::uuid;v_event_id:=nullif(p_payload->>'event_id','')::uuid;
 if p_evidence_type='studio_session' then v_verified:=exists(select 1 from public.tgg_world_session_launches sl where sl.user_id=v_uid and sl.status in('opened','active','saved','closed') and ((p_source_id is not null and sl.id=p_source_id) or(v_project_id is not null and sl.project_id=v_project_id) or(v_session_id is not null and sl.session_id=v_session_id)));
 elsif p_evidence_type='live_event' then v_verified:=exists(select 1 from public.tgg_world_events e where e.id=coalesce(v_event_id,p_source_id) and e.status='completed' and(e.host_user_id=v_uid or exists(select 1 from public.tgg_world_event_participants ep where ep.event_id=e.id and ep.user_id=v_uid)));
 else v_verified:=false;end if;
 insert into public.tgg_world_mission_evidence(user_id,player_mission_id,evidence_type,source_table,source_id,source_key,payload,verified,verified_at) values(v_uid,v_pm.id,p_evidence_type,p_source_table,p_source_id,p_source_key,coalesce(p_payload,'{}'::jsonb),v_verified,case when v_verified then now() else null end) on conflict do nothing returning id into v_evidence_id;
 update public.tgg_world_player_missions set status='evidence_pending',progress=greatest(progress,case when v_verified then 1 else 0 end),updated_at=now() where id=v_pm.id and status not in('completed','rewarded');
 return jsonb_build_object('ok',true,'mission_code',p_mission_code,'evidence_id',v_evidence_id,'verified',v_verified,'requires_trusted_adapter',not v_verified);end$function$


-- [40000001573] function public.tgg_world_v4_start_crew_mission(p_crew_id uuid, p_mission_code text, p_project_id uuid, p_session_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_world_v4_start_crew_mission(p_crew_id uuid, p_mission_code text, p_project_id uuid DEFAULT NULL::uuid, p_session_id uuid DEFAULT NULL::uuid)
 RETURNS public.tgg_world_crew_missions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_mission_id uuid;v_row public.tgg_world_crew_missions;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;if not exists(select 1 from public.tgg_world_crew_members_v10 where crew_id=p_crew_id and user_id=v_uid and status='active') then raise exception 'CREW_MEMBERSHIP_REQUIRED';end if;select id into v_mission_id from public.tgg_world_missions where code=p_mission_code and active=true;if v_mission_id is null then raise exception 'MISSION_NOT_FOUND';end if;insert into public.tgg_world_crew_missions(crew_id,mission_id,status,accepted_by,project_id,session_id,accepted_at) values(p_crew_id,v_mission_id,'in_progress',v_uid,p_project_id,p_session_id,now()) on conflict(crew_id,mission_id) do update set status='in_progress',project_id=coalesce(excluded.project_id,tgg_world_crew_missions.project_id),session_id=coalesce(excluded.session_id,tgg_world_crew_missions.session_id),updated_at=now() returning * into v_row;insert into public.tgg_world_crew_mission_members(crew_mission_id,user_id) values(v_row.id,v_uid) on conflict do nothing;return v_row;end $function$


-- [40000001574] function public.tgg_world_v4_verify_and_complete_mission(p_mission_code text)
CREATE OR REPLACE FUNCTION public.tgg_world_v4_verify_and_complete_mission(p_mission_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_uid uuid:=auth.uid();v_mission public.tgg_world_missions;v_pm public.tgg_world_player_missions;v_count integer;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_mission from public.tgg_world_missions where code=p_mission_code and active=true;if v_mission.id is null then raise exception 'MISSION_NOT_FOUND';end if;select * into v_pm from public.tgg_world_player_missions where user_id=v_uid and mission_id=v_mission.id;if v_pm.id is null then raise exception 'MISSION_NOT_ACCEPTED';end if;select count(*) into v_count from public.tgg_world_mission_evidence where player_mission_id=v_pm.id and user_id=v_uid and verified=true and evidence_type=v_mission.objective_type;if v_count<v_mission.objective_target then raise exception 'MISSION_EVIDENCE_INCOMPLETE';end if;return public.tgg_world_mvp_v1_complete_mission(p_mission_code,jsonb_build_object('verified_evidence_count',v_count,'objective_type',v_mission.objective_type));end $function$


