-- [40000001576] function public.tgg_world_v7_invite_to_crew(p_crew_id uuid, p_invited_user_id uuid, p_expires_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.tgg_world_v7_invite_to_crew(p_crew_id uuid, p_invited_user_id uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS public.tgg_world_crew_invites
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_row public.tgg_world_crew_invites;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;if p_invited_user_id is null then raise exception 'INVITED_USER_REQUIRED';end if;if p_invited_user_id=v_uid then raise exception 'CANNOT_INVITE_SELF';end if;if not exists(select 1 from public.tgg_world_crew_members_v10 where crew_id=p_crew_id and user_id=v_uid and status='active' and role in('owner','admin')) then raise exception 'CREW_ADMIN_REQUIRED';end if;insert into public.tgg_world_crew_invites(crew_id,invited_user_id,invited_by,status,expires_at) values(p_crew_id,p_invited_user_id,v_uid,'pending',p_expires_at) on conflict(crew_id,invited_user_id) do update set invited_by=excluded.invited_by,status='pending',expires_at=excluded.expires_at,created_at=now(),responded_at=null returning * into v_row;return v_row;end $function$


-- [40000001577] function public.tgg_world_v7_readiness()
CREATE OR REPLACE FUNCTION public.tgg_world_v7_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_player boolean;v_phone boolean;v_core_tables boolean;v_social_tables boolean;v_world_tables boolean;v_bridge_tables boolean;v_starters boolean;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select exists(select 1 from public.tgg_world_players where user_id=v_uid) into v_player;select exists(select 1 from public.tgg_world_phone_state_v10 where user_id=v_uid) into v_phone;v_core_tables:=to_regclass('public.tgg_world_players') is not null and to_regclass('public.tgg_world_missions') is not null and to_regclass('public.tgg_world_reward_ledger') is not null and to_regclass('public.tgg_world_wallets_v10') is not null;v_social_tables:=to_regclass('public.tgg_world_crews_v10') is not null and to_regclass('public.tgg_world_crew_members_v10') is not null and to_regclass('public.tgg_world_crew_invites') is not null and to_regclass('public.tgg_world_events') is not null;v_world_tables:=to_regclass('public.tgg_world_locations_v10') is not null and to_regclass('public.tgg_world_contacts') is not null and to_regclass('public.tgg_world_properties') is not null and to_regclass('public.tgg_world_vehicles_v10') is not null;v_bridge_tables:=to_regclass('public.tgg_world_session_launches') is not null and to_regclass('public.tgg_world_vault_handoffs') is not null and to_regclass('public.tgg_world_mission_evidence') is not null;select count(*)>=3 into v_starters from public.tgg_world_missions where code in('MVP_FIRST_SESSION','MVP_COLLAB_SESSION','MVP_LIVE_EVENT');return jsonb_build_object('ok',v_core_tables and v_social_tables and v_world_tables and v_bridge_tables and v_starters,'version','TGG-WORLD-V7-FINAL-READINESS','authenticated_user',true,'player_bootstrapped',v_player,'phone_bootstrapped',v_phone,'checks',jsonb_build_object('core_tables',v_core_tables,'crew_event_tables',v_social_tables,'world_tables',v_world_tables,'creator_os_bridge_tables',v_bridge_tables,'starter_missions',v_starters));end $function$


-- [40000001578] function public.tgg_world_v8_grant_event_access(p_event_id uuid, p_user_id uuid, p_access_type text, p_expires_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.tgg_world_v8_grant_event_access(p_event_id uuid, p_user_id uuid, p_access_type text DEFAULT 'invite'::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS public.tgg_world_event_access
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_event public.tgg_world_events;v_row public.tgg_world_event_access;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;if p_user_id is null then raise exception 'USER_REQUIRED';end if;select * into v_event from public.tgg_world_events where id=p_event_id;if v_event.id is null then raise exception 'EVENT_NOT_FOUND';end if;if v_event.host_user_id<>v_uid and not exists(select 1 from public.tgg_world_event_participants ep where ep.event_id=p_event_id and ep.user_id=v_uid and ep.role in('host','cohost','moderator')) then raise exception 'EVENT_ADMIN_REQUIRED';end if;insert into public.tgg_world_event_access(event_id,user_id,access_type,granted_by,expires_at) values(p_event_id,p_user_id,p_access_type,v_uid,p_expires_at) on conflict(event_id,user_id) do update set access_type=excluded.access_type,granted_by=excluded.granted_by,expires_at=excluded.expires_at,created_at=now() returning * into v_row;return v_row;end $function$


-- [40000001579] function public.tgg_world_v8_health()
CREATE OR REPLACE FUNCTION public.tgg_world_v8_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_readiness jsonb;v_direct_progression_write boolean;v_direct_inventory_write boolean;v_signal_insert_policy boolean;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;v_readiness:=public.tgg_world_v7_readiness();select exists(select 1 from pg_policies where schemaname='public' and tablename='tgg_world_players' and cmd in('ALL','UPDATE','INSERT') and roles::text like '%authenticated%') into v_direct_progression_write;select exists(select 1 from pg_policies where schemaname='public' and tablename in('tgg_world_inventory_v10','tgg_world_vehicles_v10') and cmd in('ALL','UPDATE','INSERT') and roles::text like '%authenticated%') into v_direct_inventory_write;select exists(select 1 from pg_policies where schemaname='public' and tablename='tgg_world_event_signals' and cmd='INSERT' and roles::text like '%authenticated%') into v_signal_insert_policy;return jsonb_build_object('ok',coalesce((v_readiness->>'ok')::boolean,false) and not v_direct_progression_write and not v_direct_inventory_write and not v_signal_insert_policy,'version','TGG-WORLD-V8-AUTHORITATIVE-RUNTIME','base_readiness',v_readiness,'security_checks',jsonb_build_object('direct_progression_write_blocked',not v_direct_progression_write,'direct_inventory_write_blocked',not v_direct_inventory_write,'event_signal_direct_insert_blocked',not v_signal_insert_policy,'event_access_table',to_regclass('public.tgg_world_event_access') is not null,'crew_invites_table',to_regclass('public.tgg_world_crew_invites') is not null));end$function$


-- [40000001580] function public.tgg_world_v8_mark_session_launch_opened(p_launch_id uuid)
CREATE OR REPLACE FUNCTION public.tgg_world_v8_mark_session_launch_opened(p_launch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
