 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_rows integer:=0;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;update public.tgg_world_session_launches set status=case when status='requested' then 'opened' else status end,updated_at=now() where id=p_launch_id and user_id=v_uid and status in('requested','opened');get diagnostics v_rows=row_count;return jsonb_build_object('ok',v_rows=1,'launch_id',p_launch_id);end $function$


-- [40000001581] function public.tgg_world_v8_set_phone_app(p_active_app text, p_preferences jsonb)
CREATE OR REPLACE FUNCTION public.tgg_world_v8_set_phone_app(p_active_app text, p_preferences jsonb DEFAULT NULL::jsonb)
 RETURNS public.tgg_world_phone_state_v10
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_row public.tgg_world_phone_state_v10;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;if p_active_app not in('home','calls','video','messages','crew','missions','calendar','map','wallet','music','live','contacts','store','projects') then raise exception 'INVALID_PHONE_APP';end if;insert into public.tgg_world_phone_state_v10(user_id,active_app,last_opened_at,preferences) values(v_uid,p_active_app,now(),coalesce(p_preferences,'{}'::jsonb)) on conflict(user_id) do update set active_app=excluded.active_app,last_opened_at=now(),preferences=case when p_preferences is null then tgg_world_phone_state_v10.preferences else p_preferences end,updated_at=now() returning * into v_row;return v_row;end $function$


-- [40000001582] function public.tgg_world_v8_transition_vault_handoff(p_handoff_id uuid, p_to_status text, p_error text)
CREATE OR REPLACE FUNCTION public.tgg_world_v8_transition_vault_handoff(p_handoff_id uuid, p_to_status text, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_uid uuid:=auth.uid();v_row public.tgg_world_vault_handoffs;v_allowed boolean:=false;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_row from public.tgg_world_vault_handoffs where id=p_handoff_id and user_id=v_uid for update;if v_row.id is null then raise exception 'HANDOFF_NOT_FOUND';end if;v_allowed:=(v_row.status='queued' and p_to_status in('ready','processing','cancelled')) or(v_row.status='ready' and p_to_status in('processing','cancelled')) or(v_row.status='processing' and p_to_status in('completed','failed')) or(v_row.status='failed' and p_to_status='queued');if not v_allowed then raise exception 'INVALID_HANDOFF_TRANSITION';end if;update public.tgg_world_vault_handoffs set status=p_to_status,payload=case when p_error is null then payload else payload||jsonb_build_object('error',p_error) end,updated_at=now() where id=p_handoff_id and user_id=v_uid;return jsonb_build_object('ok',true,'handoff_id',p_handoff_id,'from_status',v_row.status,'to_status',p_to_status);end $function$


-- [40000001583] function public.tgg_world_v8_trust_mission_evidence(p_evidence_id uuid, p_trust_payload jsonb)
CREATE OR REPLACE FUNCTION public.tgg_world_v8_trust_mission_evidence(p_evidence_id uuid, p_trust_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_role text:=coalesce(auth.jwt()->>'role','');v_rows integer:=0;begin if v_role<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;update public.tgg_world_mission_evidence set verified=true,verified_at=now(),payload=payload||jsonb_build_object('trusted_adapter',coalesce(p_trust_payload,'{}'::jsonb)) where id=p_evidence_id;get diagnostics v_rows=row_count;return jsonb_build_object('ok',v_rows=1,'evidence_id',p_evidence_id,'verified',v_rows=1);end$function$


-- [40000001584] function public.tgg_world_validate_blueprint(p_blueprint_key text)
CREATE OR REPLACE FUNCTION public.tgg_world_validate_blueprint(p_blueprint_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_blueprint_id uuid;
  v_locations integer;
  v_missing_spawns integer;
  v_missing_interactions integer;
  v_missing_audio integer;
  v_missing_budgets integer;
  v_status text;
begin
  select id into v_blueprint_id
  from public.tgg_world_blueprints
  where blueprint_key=p_blueprint_key;

  if v_blueprint_id is null then
    raise exception 'blueprint not found: %',p_blueprint_key;
  end if;

  select count(*) into v_locations
  from public.tgg_world_locations
  where blueprint_id=v_blueprint_id and enabled=true;

  select count(*) into v_missing_spawns
  from public.tgg_world_locations l
  where l.blueprint_id=v_blueprint_id and l.enabled=true
    and not exists(
      select 1 from public.tgg_world_spawn_points s
      where s.location_id=l.id and s.enabled=true
    );

  select count(*) into v_missing_interactions
  from public.tgg_world_locations l
  where l.blueprint_id=v_blueprint_id and l.enabled=true
    and not exists(
      select 1 from public.tgg_world_interaction_points i
      where i.location_id=l.id and i.enabled=true
    );

  select count(*) into v_missing_audio
  from public.tgg_world_locations l
  where l.blueprint_id=v_blueprint_id and l.enabled=true
    and not exists(
      select 1 from public.tgg_world_audio_zones a
      where a.location_id=l.id and a.enabled=true
    );

  select count(*) into v_missing_budgets
  from public.tgg_world_locations l
  where l.blueprint_id=v_blueprint_id and l.enabled=true
    and (
      select count(distinct b.device_tier)
      from public.tgg_world_performance_budgets b
      where b.location_id=l.id
    ) < 3;

  v_status := case
    when v_locations > 0
      and v_missing_spawns=0
      and v_missing_interactions=0
      and v_missing_audio=0
      and v_missing_budgets=0
    then 'passed'
    else 'blocked'
  end;

  update public.tgg_world_blueprints
  set status=case when v_status='passed' then 'passed' else 'testing' end,
      updated_at=now()
  where id=v_blueprint_id;

  return jsonb_build_object(
    'status',v_status,
    'locations',v_locations,
    'missing_spawns',v_missing_spawns,
    'missing_interactions',v_missing_interactions,
    'missing_audio_zones',v_missing_audio,
    'missing_device_budget_sets',v_missing_budgets
  );
end;
$function$


