-- [40000001604] function public.validate_content_owner()
CREATE OR REPLACE FUNCTION public.validate_content_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  parent_creator uuid;
begin

  select creator_id
  into parent_creator
  from public.content_items
  where id = new.content_id;

  if parent_creator is null then
    raise exception 'Referenced content item does not exist';
  end if;

  if parent_creator <> new.creator_id then
    raise exception
      'Creator mismatch between content_items and child content record';
  end if;

  return new;
end;
$function$


