-- [50000002007] constraint public.tgg_site_routes:tgg_site_routes_v516_canonical_aliases_check
alter table public.tgg_site_routes add constraint tgg_site_routes_v516_canonical_aliases_check CHECK (
CASE route_key
    WHEN 'merch'::text THEN path = '/p/creator-store.html'::text
    WHEN 'memberships'::text THEN path = '/p/memberships.html'::text
    WHEN 'artists'::text THEN path = '/p/artists.html'::text
    WHEN 'events'::text THEN path = '/p/events.html'::text
    WHEN 'opportunities_public'::text THEN path = '/p/opportunities.html'::text
    WHEN 'shorts'::text THEN path = '/p/shorts.html'::text
    WHEN 'radio'::text THEN path = '/p/tgg-radio.html'::text
    WHEN 'audiobooks'::text THEN path = '/p/audiobooks.html'::text
    WHEN 'fan_hub'::text THEN path = '/p/artist-world.html'::text
    WHEN 'fan_following'::text THEN path = '/p/artist-world.html'::text
    WHEN 'fan_library'::text THEN path = '/p/music-hub.html'::text
    WHEN 'fan_rewards'::text THEN path = '/p/backstage.html'::text
    WHEN 'discover'::text THEN path = '/p/homepage.html'::text
    WHEN 'charts'::text THEN path = '/p/homepage.html'::text
    WHEN 'releases'::text THEN path = '/search/label/Mixtapes'::text
    WHEN 'artist_settings'::text THEN path = '/p/artist-dashboard_0633467215.html'::text
    WHEN 'submit_music'::text THEN path = '/p/upload-mixtape.html'::text
    ELSE true
END);

