-- [70000000001] view public.active_stories_v1
create or replace view public.active_stories_v1 as  SELECT s.id,
    s.user_id,
    COALESCE(a.stage_name, 'TGG User'::text) AS display_name,
    a.avatar_url,
    s.story_type,
    s.caption,
    s.media_url,
    s.linked_release_id,
    s.created_at,
    s.expires_at
   FROM public.tgg_stories s
     LEFT JOIN public.public_artist_directory_v1 a ON a.user_id = s.user_id
  WHERE s.expires_at > now()
  ORDER BY s.created_at DESC;;
alter view public.active_stories_v1 set (security_invoker=true);

-- [70000000002] view public.creator_action_center
create or replace view public.creator_action_center as  SELECT a.id AS creator_id,
    a.stage_name,
        CASE
            WHEN NULLIF(TRIM(BOTH FROM COALESCE(a.stage_name, ''::text)), ''::text) IS NULL THEN 'complete_profile'::text
            WHEN NOT (EXISTS ( SELECT 1
               FROM public.mixtapes m
              WHERE m.artist_id = a.id)) THEN 'create_first_release'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.mixtapes m
              WHERE m.artist_id = a.id AND m.status = 'changes_requested'::public.mixtape_status)) THEN 'fix_release_changes'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.mixtapes m
              WHERE m.artist_id = a.id AND m.status = 'draft'::public.mixtape_status)) THEN 'finish_draft_release'::text
            WHEN NOT (EXISTS ( SELECT 1
               FROM public.mixtapes m
              WHERE m.artist_id = a.id AND m.status = 'published'::public.mixtape_status)) THEN 'submit_release'::text
            WHEN COALESCE(g.events_30d, 0::bigint) = 0 THEN 'promote_release'::text
            WHEN COALESCE(g.shares_30d, 0::bigint) = 0 THEN 'encourage_shares'::text
            ELSE 'keep_growing'::text
        END AS next_action,
        CASE
            WHEN NULLIF(TRIM(BOTH FROM COALESCE(a.stage_name, ''::text)), ''::text) IS NULL THEN 'Complete your artist profile'::text
            WHEN NOT (EXISTS ( SELECT 1
               FROM public.mixtapes m
              WHERE m.artist_id = a.id)) THEN 'Create your first mixtape'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.mixtapes m
              WHERE m.artist_id = a.id AND m.status = 'changes_requested'::public.mixtape_status)) THEN 'Review requested changes'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.mixtapes m
              WHERE m.artist_id = a.id AND m.status = 'draft'::public.mixtape_status)) THEN 'Finish your draft release'::text
            WHEN NOT (EXISTS ( SELECT 1
               FROM public.mixtapes m
              WHERE m.artist_id = a.id AND m.status = 'published'::public.mixtape_status)) THEN 'Submit a release for review'::text
            WHEN COALESCE(g.events_30d, 0::bigint) = 0 THEN 'Promote your published release'::text
            WHEN COALESCE(g.shares_30d, 0::bigint) = 0 THEN 'Drive more shares'::text
            ELSE 'Keep building momentum'::text
        END AS next_action_title,
    COALESCE(g.events_7d, 0::bigint) AS events_7d,
    COALESCE(g.events_30d, 0::bigint) AS events_30d,
    COALESCE(g.plays_30d, 0::bigint) AS plays_30d,
    COALESCE(g.downloads_30d, 0::bigint) AS downloads_30d,
    COALESCE(g.shares_30d, 0::bigint) AS shares_30d,
    g.top_release_30d_id,
    g.top_release_30d_title,
    ( SELECT count(*) AS count
           FROM public.mixtapes m
          WHERE m.artist_id = a.id AND m.status = 'draft'::public.mixtape_status) AS draft_releases,
    ( SELECT count(*) AS count
           FROM public.mixtapes m
          WHERE m.artist_id = a.id AND m.status = 'pending'::public.mixtape_status) AS pending_releases,
    ( SELECT count(*) AS count
           FROM public.mixtapes m
          WHERE m.artist_id = a.id AND m.status = 'changes_requested'::public.mixtape_status) AS changes_requested_releases
   FROM public.artists a
     LEFT JOIN public.creator_growth_insights g ON g.creator_id = a.id;;
alter view public.creator_action_center set (security_invoker=true);

-- [70000000003] view public.creator_analytics_30d_daily
create or replace view public.creator_analytics_30d_daily as  SELECT creator_id,
    date_trunc('day'::text, occurred_at)::date AS event_date,
    count(*) FILTER (WHERE event_type = ANY (ARRAY['play'::text, 'track_play'::text])) AS plays,
    count(*) FILTER (WHERE event_type = 'download'::text) AS downloads,
    count(*) FILTER (WHERE event_type = 'release_view'::text) AS release_views,
    count(*) FILTER (WHERE event_type = 'share'::text) AS shares,
    count(DISTINCT visitor_hash) FILTER (WHERE visitor_hash IS NOT NULL) AS unique_visitors
   FROM public.creator_analytics_events e
  WHERE occurred_at >= (now() - '30 days'::interval)
  GROUP BY creator_id, (date_trunc('day'::text, occurred_at)::date);;
alter view public.creator_analytics_30d_daily set (security_invoker=true);

-- [70000000004] view public.creator_analytics_daily
create or replace view public.creator_analytics_daily as  SELECT m.user_id,
    e.creator_id,
    e.mixtape_id,
    e.event_type,
    (e.occurred_at AT TIME ZONE 'UTC'::text)::date AS event_date,
    count(*) AS event_count,
    count(DISTINCT NULLIF(e.session_id, ''::text)) AS unique_sessions
   FROM public.creator_analytics_events e
     JOIN public.mixtapes m ON m.id = e.mixtape_id
  WHERE m.user_id = auth.uid()
  GROUP BY m.user_id, e.creator_id, e.mixtape_id, e.event_type, ((e.occurred_at AT TIME ZONE 'UTC'::text)::date);;
alter view public.creator_analytics_daily set (security_invoker=true);

-- [70000000005] view public.creator_analytics_event_summary
create or replace view public.creator_analytics_event_summary as  SELECT m.user_id,
    e.creator_id,
    e.event_type,
    count(*) AS total_events,
    count(*) FILTER (WHERE e.occurred_at >= (now() - '7 days'::interval)) AS events_7d,
    count(*) FILTER (WHERE e.occurred_at >= (now() - '30 days'::interval)) AS events_30d,
    count(DISTINCT NULLIF(e.session_id, ''::text)) AS unique_sessions
   FROM public.creator_analytics_events e
     JOIN public.mixtapes m ON m.id = e.mixtape_id
  WHERE m.user_id = auth.uid()
  GROUP BY m.user_id, e.creator_id, e.event_type;;
alter view public.creator_analytics_event_summary set (security_invoker=true);

-- [70000000006] view public.creator_audience_summary
create or replace view public.creator_audience_summary as  SELECT a.user_id,
    a.id AS artist_id,
    a.stage_name,
    COALESCE(f.followers, 0::bigint) AS followers,
    COALESCE(x.saved_releases, 0::bigint) AS total_release_saves,
    COALESCE(x.reactions, 0::bigint) AS total_reactions,
    COALESCE(x.comments, 0::bigint) AS total_comments,
    COALESCE(x.community_actions, 0::bigint) AS total_community_actions
   FROM public.artists a
     LEFT JOIN ( SELECT artist_follows.artist_id,
            count(*) AS followers
           FROM public.artist_follows
          GROUP BY artist_follows.artist_id) f ON f.artist_id = a.id
     LEFT JOIN ( SELECT creator_release_community_summary.artist_id,
            sum(creator_release_community_summary.saves)::bigint AS saved_releases,
            sum(creator_release_community_summary.reactions)::bigint AS reactions,
            sum(creator_release_community_summary.comments)::bigint AS comments,
            sum(creator_release_community_summary.total_community_actions)::bigint AS community_actions
           FROM public.creator_release_community_summary
          GROUP BY creator_release_community_summary.artist_id) x ON x.artist_id = a.id
  WHERE a.user_id = auth.uid();;
alter view public.creator_audience_summary set (security_invoker=true);

-- [70000000007] view public.creator_catalog_health
create or replace view public.creator_catalog_health as  SELECT a.id AS creator_id,
    a.user_id,
    count(DISTINCT m.id) AS mixtapes,
    count(DISTINCT m.id) FILTER (WHERE m.status = 'published'::public.mixtape_status) AS published_mixtapes,
    count(DISTINCT v.id) AS videos,
    count(DISTINCT v.id) FILTER (WHERE v.status = 'published'::text OR v.published = true) AS published_videos,
    count(DISTINCT mp.id) AS merch_products,
    count(DISTINCT mp.id) FILTER (WHERE mp.status = 'published'::text) AS published_merch,
    count(DISTINCT mp.id) FILTER (WHERE mp.inventory <= 0) AS out_of_stock_merch,
    count(DISTINCT mp.id) FILTER (WHERE mp.inventory >= 1 AND mp.inventory <= 5) AS low_stock_merch,
    count(DISTINCT i.id) AS interviews,
    count(DISTINCT i.id) FILTER (WHERE i.published = true OR i.status = 'published'::text) AS published_interviews,
    count(DISTINCT m.id) FILTER (WHERE m.status = 'changes_requested'::public.mixtape_status) AS mixtapes_needing_changes,
    count(DISTINCT v.id) FILTER (WHERE v.status = 'changes_requested'::text) AS videos_needing_changes,
    count(DISTINCT mp.id) FILTER (WHERE mp.status = 'changes_requested'::text) AS merch_needing_changes
   FROM public.artists a
     LEFT JOIN public.mixtapes m ON m.artist_id = a.id
     LEFT JOIN public.site_videos v ON v.user_id = a.user_id
     LEFT JOIN public.merch_products mp ON mp.user_id = a.user_id
     LEFT JOIN public.artist_interviews i ON i.user_id = a.user_id
  GROUP BY a.id, a.user_id;;
alter view public.creator_catalog_health set (security_invoker=true);

-- [70000000008] view public.creator_collaboration_inbox_v1
create or replace view public.creator_collaboration_inbox_v1 as  SELECT id,
    sender_id,
    recipient_id,
    project_title,
    project_type,
    note,
    status,
    conversation_id,
    created_at,
    updated_at,
        CASE
            WHEN recipient_id = (( SELECT auth.uid() AS uid)) THEN 'incoming'::text
            ELSE 'outgoing'::text
        END AS direction
   FROM public.tgg_collaboration_requests r
  WHERE sender_id = (( SELECT auth.uid() AS uid)) OR recipient_id = (( SELECT auth.uid() AS uid));;
alter view public.creator_collaboration_inbox_v1 set (security_invoker=true);

-- [70000000009] view public.creator_command_center
create or replace view public.creator_command_center as  SELECT a.id AS creator_id,
    a.user_id,
    a.stage_name,
    ac.next_action,
    ac.next_action_title,
    COALESCE(ac.draft_releases, 0::bigint) AS draft_releases,
    COALESCE(ac.pending_releases, 0::bigint) AS pending_releases,
    COALESCE(ac.changes_requested_releases, 0::bigint) AS changes_requested_releases,
    COALESCE(g.events_7d, 0::bigint) AS events_7d,
    COALESCE(g.events_30d, 0::bigint) AS events_30d,
    COALESCE(g.plays_30d, 0::bigint) AS plays_30d,
    COALESCE(g.downloads_30d, 0::bigint) AS downloads_30d,
    COALESCE(g.unique_visitors_30d, 0::bigint) AS unique_visitors_30d,
    g.top_release_30d_id,
    g.top_release_30d_title,
    COALESCE(ch.published_mixtapes, 0::bigint) AS published_mixtapes,
    COALESCE(ch.published_videos, 0::bigint) AS published_videos,
    COALESCE(ch.published_merch, 0::bigint) AS published_merch,
    COALESCE(ch.low_stock_merch, 0::bigint) AS low_stock_merch,
    COALESCE(ch.out_of_stock_merch, 0::bigint) AS out_of_stock_merch,
    COALESCE(cs.unread_messages, 0::bigint) AS unread_messages,
    COALESCE(cs.incoming_collab_requests, 0::bigint) AS incoming_collab_requests,
    cs.latest_message_at,
    COALESCE(ac.changes_requested_releases, 0::bigint) + COALESCE(ch.videos_needing_changes, 0::bigint) + COALESCE(ch.merch_needing_changes, 0::bigint) AS total_items_needing_changes,
    COALESCE(cs.unread_messages, 0::bigint) + COALESCE(cs.incoming_collab_requests, 0::bigint) + COALESCE(ch.low_stock_merch, 0::bigint) + COALESCE(ch.out_of_stock_merch, 0::bigint) + COALESCE(ac.changes_requested_releases, 0::bigint) + COALESCE(ch.videos_needing_changes, 0::bigint) + COALESCE(ch.merch_needing_changes, 0::bigint) AS attention_count
   FROM public.artists a
     LEFT JOIN public.creator_action_center ac ON ac.creator_id = a.id
     LEFT JOIN public.creator_growth_insights g ON g.creator_id = a.id
     LEFT JOIN public.creator_catalog_health ch ON ch.creator_id = a.id
     LEFT JOIN public.creator_communications_summary cs ON cs.user_id = a.user_id;;
alter view public.creator_command_center set (security_invoker=true);

-- [70000000010] view public.creator_command_center_v2
create or replace view public.creator_command_center_v2 as  SELECT cc.creator_id,
    cc.user_id,
    cc.stage_name,
    cc.next_action,
    cc.next_action_title,
    cc.draft_releases,
    cc.pending_releases,
    cc.changes_requested_releases,
    cc.events_7d,
    cc.events_30d,
    cc.plays_30d,
    cc.downloads_30d,
    cc.unique_visitors_30d,
    cc.top_release_30d_id,
    cc.top_release_30d_title,
    cc.published_mixtapes,
    cc.published_videos,
    cc.published_merch,
    cc.low_stock_merch,
    cc.out_of_stock_merch,
    cc.unread_messages,
    cc.incoming_collab_requests,
    cc.latest_message_at,
    cc.total_items_needing_changes,
    cc.attention_count,
    COALESCE(aud.followers, 0::bigint) AS followers,
    COALESCE(aud.total_release_saves, 0::bigint) AS total_release_saves,
    COALESCE(aud.total_reactions, 0::bigint) AS total_reactions,
    COALESCE(aud.total_comments, 0::bigint) AS total_comments,
    COALESCE(aud.total_community_actions, 0::bigint) AS total_community_actions,
    COALESCE(mod.pending_reports, 0::bigint) AS pending_comment_reports,
    COALESCE(ns.unread_notifications, 0::bigint) AS unread_notifications,
    COALESCE(cc.attention_count, 0::bigint) + COALESCE(mod.pending_reports, 0::bigint) + COALESCE(ns.unread_notifications, 0::bigint) AS total_attention_count
   FROM public.creator_command_center cc
     LEFT JOIN public.creator_audience_summary aud ON aud.artist_id = cc.creator_id
     LEFT JOIN ( SELECT creator_release_community_summary.artist_id,
            sum(creator_release_community_summary.pending_comment_reports)::bigint AS pending_reports
           FROM public.creator_release_community_summary
          GROUP BY creator_release_community_summary.artist_id) mod ON mod.artist_id = cc.creator_id
     LEFT JOIN public.user_notification_summary ns ON ns.user_id = cc.user_id
  WHERE cc.user_id = auth.uid();;
alter view public.creator_command_center_v2 set (security_invoker=true);

-- [70000000011] view public.creator_command_center_v3
create or replace view public.creator_command_center_v3 as  SELECT cc.creator_id,
    cc.user_id,
    cc.stage_name,
    cc.next_action,
    cc.next_action_title,
    cc.draft_releases,
    cc.pending_releases,
    cc.changes_requested_releases,
    cc.events_7d,
    cc.events_30d,
    cc.plays_30d,
    cc.downloads_30d,
    cc.unique_visitors_30d,
    cc.top_release_30d_id,
    cc.top_release_30d_title,
    cc.published_mixtapes,
    cc.published_videos,
    cc.published_merch,
    cc.low_stock_merch,
    cc.out_of_stock_merch,
    cc.unread_messages,
    cc.incoming_collab_requests,
    cc.latest_message_at,
    cc.total_items_needing_changes,
    cc.attention_count,
    cc.followers,
    cc.total_release_saves,
    cc.total_reactions,
    cc.total_comments,
    cc.total_community_actions,
    cc.pending_comment_reports,
    cc.unread_notifications,
    cc.total_attention_count,
    COALESCE(ps.total_releases, 0::bigint) AS pipeline_total_releases,
    COALESCE(ps.needs_setup, 0::bigint) AS releases_needing_setup,
    COALESCE(ps.ready_to_submit, 0::bigint) AS releases_ready_to_submit,
    COALESCE(ps.in_review, 0::bigint) AS releases_in_review,
    COALESCE(ps.changes_requested, 0::bigint) AS pipeline_changes_requested,
    COALESCE(ps.published, 0::bigint) AS pipeline_published,
    COALESCE(ps.rejected, 0::bigint) AS pipeline_rejected,
    COALESCE(ps.average_readiness_pct, 0) AS average_release_readiness_pct,
    COALESCE(cc.total_attention_count, 0::bigint) + COALESCE(ps.needs_setup, 0::bigint) + COALESCE(ps.changes_requested, 0::bigint) AS command_attention_count,
        CASE
            WHEN COALESCE(ps.changes_requested, 0::bigint) > 0 THEN 'fix_release_changes'::text
            WHEN COALESCE(ps.needs_setup, 0::bigint) > 0 THEN 'complete_release_setup'::text
            WHEN COALESCE(ps.ready_to_submit, 0::bigint) > 0 THEN 'submit_ready_release'::text
            ELSE cc.next_action
        END AS command_next_action,
        CASE
            WHEN COALESCE(ps.changes_requested, 0::bigint) > 0 THEN 'Review requested release changes'::text
            WHEN COALESCE(ps.needs_setup, 0::bigint) > 0 THEN 'Complete release setup'::text
            WHEN COALESCE(ps.ready_to_submit, 0::bigint) > 0 THEN 'Submit a ready release'::text
            ELSE cc.next_action_title
        END AS command_next_action_title
   FROM public.creator_command_center_v2 cc
     LEFT JOIN public.creator_release_pipeline_summary ps ON ps.user_id = cc.user_id AND ps.artist_id = cc.creator_id
  WHERE cc.user_id = auth.uid();;
alter view public.creator_command_center_v3 set (security_invoker=true);

-- [70000000012] view public.creator_comment_moderation_queue
create or replace view public.creator_comment_moderation_queue as  SELECT m.user_id,
    m.artist_id,
    m.id AS mixtape_id,
    m.title AS mixtape_title,
    c.id AS comment_id,
    c.user_id AS commenter_id,
    c.body,
    c.created_at,
    c.hidden_by_creator,
    c.hidden_at,
    count(r.id) FILTER (WHERE r.status = 'pending'::text) AS pending_reports,
    max(r.created_at) AS latest_report_at
   FROM public.mixtapes m
     JOIN public.release_comments c ON c.mixtape_id = m.id
     LEFT JOIN public.release_comment_reports r ON r.comment_id = c.id
  WHERE m.user_id = auth.uid()
  GROUP BY m.user_id, m.artist_id, m.id, m.title, c.id, c.user_id, c.body, c.created_at, c.hidden_by_creator, c.hidden_at
 HAVING count(r.id) FILTER (WHERE r.status = 'pending'::text) > 0 OR c.hidden_by_creator = true;;
alter view public.creator_comment_moderation_queue set (security_invoker=true);

-- [70000000013] view public.creator_comment_moderation_summary
create or replace view public.creator_comment_moderation_summary as  SELECT m.user_id,
    m.artist_id,
    m.id AS mixtape_id,
    m.title,
    count(DISTINCT c.id) AS comments,
    count(r.id) FILTER (WHERE r.status = 'pending'::text) AS pending_reports,
    count(r.id) FILTER (WHERE r.status = 'actioned'::text) AS actioned_reports,
    max(r.created_at) AS latest_report_at
   FROM public.mixtapes m
     LEFT JOIN public.release_comments c ON c.mixtape_id = m.id
     LEFT JOIN public.release_comment_reports r ON r.comment_id = c.id
  WHERE m.user_id = auth.uid()
  GROUP BY m.user_id, m.artist_id, m.id, m.title;;
alter view public.creator_comment_moderation_summary set (security_invoker=true);

-- [70000000014] view public.creator_communications_summary
create or replace view public.creator_communications_summary as  SELECT cm.user_id,
    count(DISTINCT cm.conversation_id) AS conversations,
    count(DISTINCT cm.conversation_id) FILTER (WHERE c.status = 'active'::text) AS active_conversations,
    count(DISTINCT r.id) FILTER (WHERE r.recipient_id = cm.user_id AND r.status = 'pending'::text) AS incoming_collab_requests,
    count(DISTINCT r.id) FILTER (WHERE r.sender_id = cm.user_id AND r.status = 'pending'::text) AS outgoing_collab_requests,
    count(DISTINCT m.id) FILTER (WHERE m.sender_id <> cm.user_id AND m.created_at > COALESCE(cm.last_read_at, '1970-01-01 00:00:00+00'::timestamp with time zone)) AS unread_messages,
    max(c.last_message_at) AS latest_message_at
   FROM public.tgg_conversation_members cm
     JOIN public.tgg_conversations c ON c.id = cm.conversation_id
     LEFT JOIN public.tgg_collaboration_requests r ON r.conversation_id = cm.conversation_id AND (r.sender_id = cm.user_id OR r.recipient_id = cm.user_id)
     LEFT JOIN public.tgg_messages m ON m.conversation_id = cm.conversation_id
  GROUP BY cm.user_id;;
alter view public.creator_communications_summary set (security_invoker=true);

