    ( SELECT count(*) AS count
           FROM public.merch_products p
          WHERE p.user_id = (( SELECT auth.uid() AS uid)) AND p.status = 'published'::text) AS published_merch
  WHERE (( SELECT auth.uid() AS uid)) IS NOT NULL;;
alter view public.creator_content_inventory_v1 set (security_invoker=true);

