    count(*) FILTER (WHERE event_type = 'download'::text) AS downloads,
    count(*) FILTER (WHERE event_type = 'release_view'::text) AS release_views,
    count(*) FILTER (WHERE event_type = 'track_play'::text) AS track_plays,
    count(*) FILTER (WHERE event_type = 'video_view'::text) AS video_views,
    count(*) FILTER (WHERE event_type = 'merch_view'::text) AS merch_views,
