    max(f.created_at) AS latest_follow_at
   FROM public.artists a
     LEFT JOIN public.artist_follows f ON f.artist_id = a.id
  WHERE a.user_id = auth.uid()
  GROUP BY a.user_id, a.id, a.stage_name;;
alter view public.creator_follower_summary set (security_invoker=true);

-- [70000000020] view public.creator_growth_insights
create or replace view public.creator_growth_insights as  WITH daily AS (
         SELECT e.creator_id,
            count(*) FILTER (WHERE e.occurred_at >= (now() - '7 days'::interval)) AS events_7d,
            count(*) FILTER (WHERE e.occurred_at >= (now() - '30 days'::interval)) AS events_30d,
            count(*) FILTER (WHERE (e.event_type = ANY (ARRAY['play'::text, 'track_play'::text])) AND e.occurred_at >= (now() - '30 days'::interval)) AS plays_30d,
            count(*) FILTER (WHERE e.event_type = 'download'::text AND e.occurred_at >= (now() - '30 days'::interval)) AS downloads_30d,
            count(*) FILTER (WHERE e.event_type = 'release_view'::text AND e.occurred_at >= (now() - '30 days'::interval)) AS release_views_30d,
            count(*) FILTER (WHERE e.event_type = 'share'::text AND e.occurred_at >= (now() - '30 days'::interval)) AS shares_30d,
            count(DISTINCT e.visitor_hash) FILTER (WHERE e.visitor_hash IS NOT NULL AND e.occurred_at >= (now() - '30 days'::interval)) AS unique_visitors_30d
           FROM public.creator_analytics_events e
          GROUP BY e.creator_id
        ), releases AS (
         SELECT m_1.artist_id AS creator_id,
            count(*) FILTER (WHERE m_1.status = 'published'::public.mixtape_status) AS published_releases,
            COALESCE(sum(m_1.play_count), 0::numeric)::bigint AS lifetime_plays,
            COALESCE(sum(m_1.download_count), 0::numeric)::bigint AS lifetime_downloads
           FROM public.mixtapes m_1
          GROUP BY m_1.artist_id
        ), ranked AS (
         SELECT e.creator_id,
            e.mixtape_id,
            count(*) AS engagement_events,
            row_number() OVER (PARTITION BY e.creator_id ORDER BY (count(*)) DESC, (max(e.occurred_at)) DESC) AS rn
           FROM public.creator_analytics_events e
          WHERE e.mixtape_id IS NOT NULL AND e.occurred_at >= (now() - '30 days'::interval)
          GROUP BY e.creator_id, e.mixtape_id
        )
 SELECT a.id AS creator_id,
    a.stage_name,
    COALESCE(d.events_7d, 0::bigint) AS events_7d,
    COALESCE(d.events_30d, 0::bigint) AS events_30d,
    COALESCE(d.plays_30d, 0::bigint) AS plays_30d,
    COALESCE(d.downloads_30d, 0::bigint) AS downloads_30d,
    COALESCE(d.release_views_30d, 0::bigint) AS release_views_30d,
    COALESCE(d.shares_30d, 0::bigint) AS shares_30d,
    COALESCE(d.unique_visitors_30d, 0::bigint) AS unique_visitors_30d,
    COALESCE(r.published_releases, 0::bigint) AS published_releases,
    COALESCE(r.lifetime_plays, 0::bigint) AS lifetime_plays,
    COALESCE(r.lifetime_downloads, 0::bigint) AS lifetime_downloads,
    rr.mixtape_id AS top_release_30d_id,
    m.title AS top_release_30d_title,
    COALESCE(rr.engagement_events, 0::bigint) AS top_release_30d_events
   FROM public.artists a
     LEFT JOIN daily d ON d.creator_id = a.id
     LEFT JOIN releases r ON r.creator_id = a.id
     LEFT JOIN ranked rr ON rr.creator_id = a.id AND rr.rn = 1
     LEFT JOIN public.mixtapes m ON m.id = rr.mixtape_id;;
alter view public.creator_growth_insights set (security_invoker=true);

-- [70000000021] view public.creator_inbox_priority
create or replace view public.creator_inbox_priority as  SELECT cm.user_id,
    c.id AS conversation_id,
    c.title,
    c.project_type,
    c.status,
    c.last_message_at,
    cm.last_read_at,
    count(m.id) FILTER (WHERE m.sender_id <> cm.user_id AND m.created_at > COALESCE(cm.last_read_at, '1970-01-01 00:00:00+00'::timestamp with time zone)) AS unread_messages,
    (EXISTS ( SELECT 1
           FROM public.tgg_collaboration_requests r
          WHERE r.conversation_id = c.id AND r.recipient_id = cm.user_id AND r.status = 'pending'::text)) AS has_pending_request
   FROM public.tgg_conversation_members cm
     JOIN public.tgg_conversations c ON c.id = cm.conversation_id
     LEFT JOIN public.tgg_messages m ON m.conversation_id = c.id
  GROUP BY cm.user_id, c.id, c.title, c.project_type, c.status, c.last_message_at, cm.last_read_at;;
alter view public.creator_inbox_priority set (security_invoker=true);

-- [70000000022] view public.creator_launch_readiness
create or replace view public.creator_launch_readiness as  SELECT user_id,
    creator_id,
    stage_name,
    pipeline_total_releases,
    releases_needing_setup,
    releases_ready_to_submit,
    releases_in_review,
    pipeline_changes_requested,
    pipeline_published,
    average_release_readiness_pct,
    followers,
    total_release_saves,
    total_reactions,
    total_comments,
    pending_comment_reports,
    unread_notifications,
        CASE
            WHEN pipeline_total_releases = 0 THEN 'create_first_release'::text
            WHEN pipeline_changes_requested > 0 THEN 'resolve_changes'::text
            WHEN releases_needing_setup > 0 THEN 'finish_release_setup'::text
            WHEN releases_ready_to_submit > 0 THEN 'submit_release'::text
            WHEN releases_in_review > 0 THEN 'await_review'::text
            WHEN pipeline_published > 0 THEN 'promote_published_music'::text
            ELSE command_next_action
        END AS launch_next_action,
        CASE
            WHEN pipeline_total_releases = 0 THEN 'Create your first release'::text
            WHEN pipeline_changes_requested > 0 THEN 'Resolve requested changes'::text
            WHEN releases_needing_setup > 0 THEN 'Finish release setup'::text
            WHEN releases_ready_to_submit > 0 THEN 'Submit a ready release'::text
            WHEN releases_in_review > 0 THEN 'Release is in review'::text
            WHEN pipeline_published > 0 THEN 'Promote your published music'::text
            ELSE command_next_action_title
        END AS launch_next_action_title,
    GREATEST(0, LEAST(100,
        CASE
            WHEN pipeline_total_releases = 0 THEN 10
            WHEN pipeline_published > 0 THEN 100
            ELSE COALESCE(average_release_readiness_pct, 0)
        END)) AS launch_readiness_pct
   FROM public.creator_command_center_v3 cc
  WHERE user_id = auth.uid();;
alter view public.creator_launch_readiness set (security_invoker=true);

-- [70000000023] view public.creator_merch_inventory_alerts
create or replace view public.creator_merch_inventory_alerts as  SELECT user_id,
    creator_id,
    id AS product_id,
    title,
    sku,
    inventory,
    status,
        CASE
            WHEN inventory <= 0 THEN 'out_of_stock'::text
            WHEN inventory <= 5 THEN 'low_stock'::text
            ELSE 'ok'::text
        END AS inventory_state,
    updated_at
   FROM public.merch_products mp
  WHERE inventory <= 5;;
alter view public.creator_merch_inventory_alerts set (security_invoker=true);

-- [70000000024] view public.creator_message_thread_v1
create or replace view public.creator_message_thread_v1 as  SELECT id AS message_id,
    conversation_id,
    sender_id,
    body,
    created_at
   FROM public.tgg_messages m
  WHERE private.tgg_is_conversation_member(conversation_id);;
alter view public.creator_message_thread_v1 set (security_invoker=true);

-- [70000000025] view public.creator_messenger_inbox_v1
create or replace view public.creator_messenger_inbox_v1 as  SELECT c.id AS conversation_id,
    c.title,
    c.project_type,
    c.status,
    c.last_message_at,
    c.created_at,
    cm.role,
    cm.last_read_at,
    ( SELECT count(*) AS count
           FROM public.tgg_messages m
          WHERE m.conversation_id = c.id AND m.created_at > COALESCE(cm.last_read_at, '1970-01-01 00:00:00+00'::timestamp with time zone) AND m.sender_id <> (( SELECT auth.uid() AS uid))) AS unread_messages,
    ( SELECT m.body
           FROM public.tgg_messages m
          WHERE m.conversation_id = c.id
          ORDER BY m.created_at DESC
         LIMIT 1) AS last_message
   FROM public.tgg_conversations c
     JOIN public.tgg_conversation_members cm ON cm.conversation_id = c.id
  WHERE cm.user_id = (( SELECT auth.uid() AS uid));;
alter view public.creator_messenger_inbox_v1 set (security_invoker=true);

-- [70000000026] view public.creator_performance_summary
create or replace view public.creator_performance_summary as  WITH m AS (
         SELECT mixtapes.user_id,
            count(*) AS total_mixtapes,
            count(*) FILTER (WHERE mixtapes.status::text = 'published'::text) AS published_mixtapes,
            count(*) FILTER (WHERE mixtapes.status::text = ANY (ARRAY['pending'::text, 'changes_requested'::text])) AS mixtapes_in_review,
            COALESCE(sum(mixtapes.play_count), 0::numeric)::bigint AS total_plays,
            COALESCE(sum(mixtapes.download_count), 0::numeric)::bigint AS total_downloads
           FROM public.mixtapes
          WHERE mixtapes.user_id IS NOT NULL
          GROUP BY mixtapes.user_id
        ), t AS (
         SELECT tracks.user_id,
            count(*) AS total_tracks
           FROM public.tracks
          WHERE tracks.user_id IS NOT NULL
          GROUP BY tracks.user_id
        ), v AS (
         SELECT site_videos.user_id,
            count(*) AS total_videos,
            count(*) FILTER (WHERE site_videos.status = 'published'::text OR site_videos.published IS TRUE) AS published_videos,
            count(*) FILTER (WHERE site_videos.status = ANY (ARRAY['pending'::text, 'changes_requested'::text])) AS videos_in_review
           FROM public.site_videos
          WHERE site_videos.user_id IS NOT NULL
          GROUP BY site_videos.user_id
        ), p AS (
         SELECT merch_products.user_id,
            count(*) AS total_merch,
            count(*) FILTER (WHERE merch_products.status = 'published'::text) AS published_merch,
            count(*) FILTER (WHERE merch_products.status = ANY (ARRAY['pending'::text, 'changes_requested'::text])) AS merch_in_review
           FROM public.merch_products
          WHERE merch_products.user_id IS NOT NULL
          GROUP BY merch_products.user_id
        )
 SELECT a.user_id,
    a.id AS artist_id,
    a.stage_name,
    COALESCE(m.total_mixtapes, 0::bigint) AS total_mixtapes,
    COALESCE(m.published_mixtapes, 0::bigint) AS published_mixtapes,
    COALESCE(t.total_tracks, 0::bigint) AS total_tracks,
    COALESCE(m.total_plays, 0::bigint) AS total_plays,
    COALESCE(m.total_downloads, 0::bigint) AS total_downloads,
        CASE
            WHEN COALESCE(m.total_plays, 0::bigint) > 0 THEN round(COALESCE(m.total_downloads, 0::bigint)::numeric / m.total_plays::numeric * 100::numeric, 2)
            ELSE 0::numeric
        END AS overall_download_rate_pct,
    COALESCE(v.total_videos, 0::bigint) AS total_videos,
    COALESCE(v.published_videos, 0::bigint) AS published_videos,
    COALESCE(p.total_merch, 0::bigint) AS total_merch,
    COALESCE(p.published_merch, 0::bigint) AS published_merch,
    COALESCE(m.mixtapes_in_review, 0::bigint) + COALESCE(v.videos_in_review, 0::bigint) + COALESCE(p.merch_in_review, 0::bigint) AS items_in_review
   FROM public.artists a
     LEFT JOIN m ON m.user_id = a.user_id
     LEFT JOIN t ON t.user_id = a.user_id
     LEFT JOIN v ON v.user_id = a.user_id
     LEFT JOIN p ON p.user_id = a.user_id
  WHERE a.user_id IS NOT NULL;;
alter view public.creator_performance_summary set (security_invoker=true);

