-- [70000000029] view public.creator_release_community_summary
create or replace view public.creator_release_community_summary as  SELECT m.user_id,
    m.artist_id,
    m.id AS mixtape_id,
    m.title,
    m.status,
    COALESCE(s.saves, 0::bigint) AS saves,
    COALESCE(r.reactions, 0::bigint) AS reactions,
    COALESCE(r.likes, 0::bigint) AS likes,
    COALESCE(r.fires, 0::bigint) AS fires,
    COALESCE(c.comments, 0::bigint) AS comments,
    COALESCE(rep.pending_reports, 0::bigint) AS pending_comment_reports,
    COALESCE(s.saves, 0::bigint) + COALESCE(r.reactions, 0::bigint) + COALESCE(c.comments, 0::bigint) AS total_community_actions
   FROM public.mixtapes m
     LEFT JOIN ( SELECT release_saves.mixtape_id,
            count(*) AS saves
           FROM public.release_saves
          GROUP BY release_saves.mixtape_id) s ON s.mixtape_id = m.id
     LEFT JOIN ( SELECT release_reactions.mixtape_id,
            count(*) AS reactions,
            count(*) FILTER (WHERE release_reactions.reaction = 'like'::text) AS likes,
            count(*) FILTER (WHERE release_reactions.reaction = 'fire'::text) AS fires
           FROM public.release_reactions
          GROUP BY release_reactions.mixtape_id) r ON r.mixtape_id = m.id
     LEFT JOIN ( SELECT release_comments.mixtape_id,
            count(*) FILTER (WHERE release_comments.hidden_by_creator = false) AS comments
           FROM public.release_comments
          GROUP BY release_comments.mixtape_id) c ON c.mixtape_id = m.id
     LEFT JOIN ( SELECT c_1.mixtape_id,
            count(*) FILTER (WHERE cr.status = 'pending'::text) AS pending_reports
           FROM public.release_comments c_1
             JOIN public.release_comment_reports cr ON cr.comment_id = c_1.id
          GROUP BY c_1.mixtape_id) rep ON rep.mixtape_id = m.id
  WHERE m.user_id = auth.uid();;
alter view public.creator_release_community_summary set (security_invoker=true);

