    COALESCE(t.track_count, 0::bigint) AS track_count,
        CASE
            WHEN COALESCE(m.play_count, 0::bigint) > 0 THEN round(COALESCE(m.download_count, 0::bigint)::numeric / m.play_count::numeric * 100::numeric, 2)
            ELSE 0::numeric
        END AS download_rate_pct,
    m.featured,
