-- [70000000032] view public.creator_release_pipeline
create or replace view public.creator_release_pipeline as  SELECT r.user_id,
    r.artist_id,
    r.mixtape_id,
    r.title,
    r.status,
    r.readiness_pct,
    r.issue_count,
    r.track_count,
    r.audio_track_count,
    r.next_requirement,
    r.next_requirement_title,
        CASE
            WHEN r.status = 'changes_requested'::public.mixtape_status THEN 1
            WHEN r.status = 'draft'::public.mixtape_status AND r.issue_count > 0 THEN 2
            WHEN r.status = 'draft'::public.mixtape_status AND r.issue_count = 0 THEN 3
            WHEN r.status = 'pending'::public.mixtape_status THEN 4
            WHEN r.status = 'rejected'::public.mixtape_status THEN 5
            WHEN r.status = 'published'::public.mixtape_status THEN 6
            ELSE 7
        END AS pipeline_priority,
        CASE
            WHEN r.status = 'changes_requested'::public.mixtape_status THEN 'Changes requested'::text
            WHEN r.status = 'draft'::public.mixtape_status AND r.issue_count > 0 THEN 'Needs setup'::text
            WHEN r.status = 'draft'::public.mixtape_status AND r.issue_count = 0 THEN 'Ready to submit'::text
            WHEN r.status = 'pending'::public.mixtape_status THEN 'In review'::text
            WHEN r.status = 'rejected'::public.mixtape_status THEN 'Rejected'::text
            WHEN r.status = 'published'::public.mixtape_status THEN 'Published'::text
            ELSE initcap(replace(r.status::text, '_'::text, ' '::text))
        END AS pipeline_stage,
    h.last_status_change_at,
    h.last_status_note
   FROM public.creator_release_readiness r
     LEFT JOIN LATERAL ( SELECT max(sh.created_at) AS last_status_change_at,
            (array_agg(sh.note ORDER BY sh.created_at DESC))[1] AS last_status_note
           FROM public.release_status_history sh
          WHERE sh.user_id = r.user_id AND sh.project_type = 'mixtape'::text AND sh.project_id = r.mixtape_id) h ON true
  WHERE r.user_id = auth.uid();;
alter view public.creator_release_pipeline set (security_invoker=true);

-- [70000000033] view public.creator_release_pipeline_summary
create or replace view public.creator_release_pipeline_summary as  SELECT user_id,
    artist_id,
