    count(*) FILTER (WHERE pipeline_stage = 'Needs setup'::text) AS needs_setup,
    count(*) FILTER (WHERE pipeline_stage = 'Ready to submit'::text) AS ready_to_submit,
    count(*) FILTER (WHERE pipeline_stage = 'In review'::text) AS in_review,
    count(*) FILTER (WHERE pipeline_stage = 'Changes requested'::text) AS changes_requested,
    count(*) FILTER (WHERE pipeline_stage = 'Published'::text) AS published,
    count(*) FILTER (WHERE pipeline_stage = 'Rejected'::text) AS rejected,
    round(avg(readiness_pct))::integer AS average_readiness_pct
   FROM public.creator_release_pipeline
  WHERE user_id = auth.uid()
  GROUP BY user_id, artist_id;;
alter view public.creator_release_pipeline_summary set (security_invoker=true);

