-- [70000000035] view public.creator_release_readiness
create or replace view public.creator_release_readiness as  WITH tc AS (
         SELECT tracks.mixtape_id,
            count(*) AS track_count,
            count(*) FILTER (WHERE COALESCE(NULLIF(btrim(tracks.audio_url), ''::text), NULLIF(btrim(tracks.audio_path), ''::text)) IS NOT NULL) AS audio_track_count
           FROM public.tracks
          GROUP BY tracks.mixtape_id
        ), base AS (
         SELECT m.user_id,
            m.artist_id,
            m.id AS mixtape_id,
            m.title,
            m.status,
            NULLIF(btrim(m.title), ''::text) IS NOT NULL AS has_title,
            NULLIF(btrim(m.genre), ''::text) IS NOT NULL AS has_genre,
            NULLIF(btrim(m.description), ''::text) IS NOT NULL AS has_description,
            COALESCE(NULLIF(btrim(m.cover_url), ''::text), NULLIF(btrim(m.cover_path), ''::text)) IS NOT NULL AS has_cover,
            m.release_date IS NOT NULL AS has_release_date,
            COALESCE(tc.track_count, 0::bigint) > 0 AS has_tracks,
            COALESCE(tc.audio_track_count, 0::bigint) > 0 OR NULLIF(btrim(m.audio_url), ''::text) IS NOT NULL AS has_audio,
            COALESCE(tc.track_count, 0::bigint) AS track_count,
            COALESCE(tc.audio_track_count, 0::bigint) AS audio_track_count
           FROM public.mixtapes m
             LEFT JOIN tc ON tc.mixtape_id = m.id
          WHERE m.user_id = auth.uid()
        )
 SELECT user_id,
    artist_id,
    mixtape_id,
    title,
    status,
    has_title,
    has_genre,
    has_description,
    has_cover,
    has_release_date,
    has_tracks,
    has_audio,
    track_count,
    audio_track_count,
    has_title::integer + has_genre::integer + has_description::integer + has_cover::integer + has_release_date::integer + has_tracks::integer + has_audio::integer AS completed_requirements,
    7 - (has_title::integer + has_genre::integer + has_description::integer + has_cover::integer + has_release_date::integer + has_tracks::integer + has_audio::integer) AS issue_count,
    round((has_title::integer + has_genre::integer + has_description::integer + has_cover::integer + has_release_date::integer + has_tracks::integer + has_audio::integer)::numeric / 7::numeric * 100::numeric)::integer AS readiness_pct,
        CASE
            WHEN NOT has_title THEN 'add_title'::text
            WHEN NOT has_genre THEN 'add_genre'::text
            WHEN NOT has_description THEN 'add_description'::text
            WHEN NOT has_cover THEN 'add_cover'::text
            WHEN NOT has_release_date THEN 'set_release_date'::text
            WHEN NOT has_tracks THEN 'add_tracks'::text
            WHEN NOT has_audio THEN 'upload_audio'::text
            ELSE 'ready'::text
        END AS next_requirement,
        CASE
            WHEN NOT has_title THEN 'Add a release title'::text
            WHEN NOT has_genre THEN 'Choose a genre'::text
            WHEN NOT has_description THEN 'Add a release description'::text
            WHEN NOT has_cover THEN 'Upload cover artwork'::text
            WHEN NOT has_release_date THEN 'Set a release date'::text
            WHEN NOT has_tracks THEN 'Add at least one track'::text
            WHEN NOT has_audio THEN 'Upload audio'::text
            ELSE 'Release is ready'::text
        END AS next_requirement_title
   FROM base b;;
alter view public.creator_release_readiness set (security_invoker=true);

