           FROM public.artist_follows f
          WHERE f.user_id = (( SELECT auth.uid() AS uid))) AS followed_artists,
    ( SELECT count(*) AS count
           FROM public.release_saves s
          WHERE s.user_id = (( SELECT auth.uid() AS uid))) AS saved_releases,
    ( SELECT count(*) AS count
           FROM public.release_reactions r
          WHERE r.user_id = (( SELECT auth.uid() AS uid))) AS reactions,
