           FROM public.release_comments c
          WHERE c.user_id = (( SELECT auth.uid() AS uid))) AS comments,
    ( SELECT count(*) AS count
           FROM public.fan_collections fc
          WHERE fc.user_id = (( SELECT auth.uid() AS uid))) AS collections,
    ( SELECT count(*) AS count
           FROM public.fan_listening_history h
          WHERE h.user_id = (( SELECT auth.uid() AS uid))) AS listening_events,
    ( SELECT count(*) AS count
           FROM public.notifications n
          WHERE n.recipient_id = (( SELECT auth.uid() AS uid)) AND n.read_at IS NULL) AS unread_notifications,
    GREATEST(( SELECT max(h.listened_at) AS max
           FROM public.fan_listening_history h
          WHERE h.user_id = (( SELECT auth.uid() AS uid))), ( SELECT max(n.created_at) AS max
           FROM public.notifications n
          WHERE n.recipient_id = (( SELECT auth.uid() AS uid)))) AS last_activity_at
  WHERE (( SELECT auth.uid() AS uid)) IS NOT NULL;;
