create or replace view public.fan_artist_discovery as  SELECT a.id AS artist_id,
    a.stage_name,
    a.bio,
    a.avatar_url,
    count(DISTINCT m.id) FILTER (WHERE m.status = 'published'::public.mixtape_status) AS published_releases,
