-- [70000000042] view public.fan_continue_listening
create or replace view public.fan_continue_listening as  SELECT DISTINCT ON (h.mixtape_id) h.user_id,
    h.mixtape_id,
    h.track_id,
    h.listened_at,
    h.progress_seconds,
    h.completed,
    m.artist_id,
    a.stage_name,
    m.title AS mixtape_title,
    m.cover_url,
    m.slug,
    t.track_number,
    t.title AS track_title,
    t.duration_seconds,
        CASE
            WHEN COALESCE(t.duration_seconds, 0) > 0 THEN LEAST(100, round(h.progress_seconds::numeric / t.duration_seconds::numeric * 100::numeric)::integer)
            ELSE NULL::integer
        END AS progress_pct
   FROM public.fan_listening_history h
     JOIN public.mixtapes m ON m.id = h.mixtape_id AND m.status = 'published'::public.mixtape_status
     JOIN public.artists a ON a.id = m.artist_id
     LEFT JOIN public.tracks t ON t.id = h.track_id AND t.mixtape_id = h.mixtape_id
  WHERE h.user_id = auth.uid() AND h.completed = false AND h.progress_seconds > 0
  ORDER BY h.mixtape_id, h.listened_at DESC;;
