    m.genre,
    m.description,
    m.cover_url,
    m.slug,
    m.release_date,
    m.created_at,
    m.play_count,
    m.download_count,
    (EXISTS ( SELECT 1
           FROM public.release_saves rs
          WHERE rs.user_id = af.user_id AND rs.mixtape_id = m.id)) AS saved
   FROM public.artist_follows af
     JOIN public.artists a ON a.id = af.artist_id
     JOIN public.mixtapes m ON m.artist_id = af.artist_id AND m.status = 'published'::public.mixtape_status
  WHERE af.user_id = auth.uid();;
