-- [70000000047] view public.fan_home_command_center
create or replace view public.fan_home_command_center as  SELECT h.user_id,
    h.followed_artists,
    h.saved_releases,
    h.collections,
    h.reactions,
    h.comments,
    h.unread_notifications,
    COALESCE(ls.listening_events, 0::bigint) AS listening_events,
    COALESCE(ls.releases_played, 0::bigint) AS releases_played,
    COALESCE(ls.tracks_played, 0::bigint) AS tracks_played,
    COALESCE(ls.completed_plays, 0::bigint) AS completed_plays,
    ls.last_listened_at,
    ( SELECT count(*) AS count
           FROM public.fan_continue_listening cl
          WHERE cl.user_id = auth.uid()) AS continue_listening_count,
    ( SELECT count(*) AS count
           FROM public.fan_following_feed ff
          WHERE ff.fan_user_id = auth.uid()) AS following_feed_releases,
        CASE
            WHEN COALESCE(h.unread_notifications, 0::bigint) > 0 THEN 'view_notifications'::text
            WHEN (( SELECT count(*) AS count
               FROM public.fan_continue_listening cl
              WHERE cl.user_id = auth.uid())) > 0 THEN 'continue_listening'::text
            WHEN COALESCE(h.saved_releases, 0::bigint) > 0 THEN 'open_library'::text
            WHEN COALESCE(h.followed_artists, 0::bigint) > 0 THEN 'view_following_feed'::text
            ELSE 'discover_music'::text
        END AS next_action,
        CASE
            WHEN COALESCE(h.unread_notifications, 0::bigint) > 0 THEN 'View new notifications'::text
            WHEN (( SELECT count(*) AS count
               FROM public.fan_continue_listening cl
              WHERE cl.user_id = auth.uid())) > 0 THEN 'Continue listening'::text
            WHEN COALESCE(h.saved_releases, 0::bigint) > 0 THEN 'Open your saved library'::text
            WHEN COALESCE(h.followed_artists, 0::bigint) > 0 THEN 'See releases from artists you follow'::text
            ELSE 'Discover music'::text
        END AS next_action_title
   FROM public.fan_home_summary h
     LEFT JOIN public.fan_listening_summary ls ON ls.user_id = h.user_id
  WHERE h.user_id = auth.uid();;
alter view public.fan_home_command_center set (security_invoker=true);

