-- [70000000051] view public.fan_personalized_discovery
create or replace view public.fan_personalized_discovery as  WITH prefs AS (
         SELECT m.genre,
            count(*) AS affinity
           FROM public.fan_listening_history h
             JOIN public.mixtapes m ON m.id = h.mixtape_id
          WHERE h.user_id = auth.uid() AND NULLIF(btrim(m.genre), ''::text) IS NOT NULL
          GROUP BY m.genre
        ), saved_prefs AS (
         SELECT m.genre,
            count(*) AS affinity
           FROM public.release_saves s
             JOIN public.mixtapes m ON m.id = s.mixtape_id
          WHERE s.user_id = auth.uid() AND NULLIF(btrim(m.genre), ''::text) IS NOT NULL
          GROUP BY m.genre
        ), combined AS (
         SELECT x.genre,
            sum(x.affinity)::bigint AS affinity
           FROM ( SELECT prefs.genre,
                    prefs.affinity * 2 AS affinity
                   FROM prefs
                UNION ALL
                 SELECT saved_prefs.genre,
                    saved_prefs.affinity * 3 AS affinity
                   FROM saved_prefs) x
          GROUP BY x.genre
        )
 SELECT d.mixtape_id,
    d.artist_id,
    d.stage_name,
    d.title,
    d.genre,
    d.description,
    d.cover_url,
    d.slug,
    d.release_date,
    d.created_at,
    d.featured,
    d.play_count,
    d.download_count,
    d.saves,
    d.reactions,
    d.comments,
    d.discovery_score,
    d.following_artist,
    d.saved,
    COALESCE(p.affinity, 0::bigint) AS genre_affinity,
    d.discovery_score + COALESCE(p.affinity, 0::bigint) * 10 +
        CASE
            WHEN d.following_artist THEN 30
            ELSE 0
        END +
        CASE
            WHEN d.saved THEN 15
            ELSE 0
        END AS personalized_score
   FROM public.fan_release_discovery d
     LEFT JOIN combined p ON lower(p.genre) = lower(d.genre)
  WHERE NOT (EXISTS ( SELECT 1
           FROM public.fan_listening_history h
          WHERE h.user_id = auth.uid() AND h.mixtape_id = d.mixtape_id AND h.listened_at > (now() - '24:00:00'::interval)));;
alter view public.fan_personalized_discovery set (security_invoker=true);

