-- [70000000054] view public.fan_release_discovery
create or replace view public.fan_release_discovery as  SELECT m.id AS mixtape_id,
    m.artist_id,
    a.stage_name,
    m.title,
    m.genre,
    m.description,
    m.cover_url,
    m.slug,
    m.release_date,
    m.created_at,
    m.featured,
    COALESCE(m.play_count, 0::bigint) AS play_count,
    COALESCE(m.download_count, 0::bigint) AS download_count,
    COALESCE(s.saves, 0::bigint) AS saves,
    COALESCE(r.reactions, 0::bigint) AS reactions,
    COALESCE(c.comments, 0::bigint) AS comments,
    COALESCE(m.play_count, 0::bigint) + COALESCE(m.download_count, 0::bigint) * 2 + COALESCE(s.saves, 0::bigint) * 3 + COALESCE(r.reactions, 0::bigint) * 2 + COALESCE(c.comments, 0::bigint) * 2 AS discovery_score,
    (EXISTS ( SELECT 1
           FROM public.artist_follows af
          WHERE af.user_id = auth.uid() AND af.artist_id = m.artist_id)) AS following_artist,
    (EXISTS ( SELECT 1
           FROM public.release_saves rs
          WHERE rs.user_id = auth.uid() AND rs.mixtape_id = m.id)) AS saved
   FROM public.mixtapes m
     JOIN public.artists a ON a.id = m.artist_id
     LEFT JOIN ( SELECT release_saves.mixtape_id,
            count(*) AS saves
           FROM public.release_saves
          GROUP BY release_saves.mixtape_id) s ON s.mixtape_id = m.id
     LEFT JOIN ( SELECT release_reactions.mixtape_id,
            count(*) AS reactions
           FROM public.release_reactions
          GROUP BY release_reactions.mixtape_id) r ON r.mixtape_id = m.id
     LEFT JOIN ( SELECT release_comments.mixtape_id,
            count(*) FILTER (WHERE release_comments.hidden_by_creator = false) AS comments
           FROM public.release_comments
          GROUP BY release_comments.mixtape_id) c ON c.mixtape_id = m.id
  WHERE m.status = 'published'::public.mixtape_status;;
alter view public.fan_release_discovery set (security_invoker=true);

