    t.download_policy,
    COALESCE(t.has_secure_audio, false) AS has_secure_audio,
        CASE
            WHEN COALESCE(t.has_secure_audio, false) AND t.audio_path IS NOT NULL THEN 'protected'::text
            WHEN NULLIF(btrim(t.audio_url), ''::text) IS NOT NULL THEN 'external'::text
            ELSE 'unavailable'::text
        END AS playback_mode,
