-- [70000000082] view public.tgg_build_progress_v1
create or replace view public.tgg_build_progress_v1 as  SELECT p.project_key,
    r.release_key,
    m.milestone_key,
    count(t.id) AS task_count,
    count(t.id) FILTER (WHERE t.status = ANY (ARRAY['complete'::text, 'passed'::text, 'skipped'::text])) AS done_count,
    round(100.0 * count(t.id) FILTER (WHERE t.status = ANY (ARRAY['complete'::text, 'passed'::text, 'skipped'::text]))::numeric / NULLIF(count(t.id), 0)::numeric, 1) AS task_progress_pct,
    m.weight
   FROM public.tgg_build_projects p
     JOIN public.tgg_build_releases r ON r.project_id = p.id
     JOIN public.tgg_build_milestones m ON m.release_id = r.id
     LEFT JOIN public.tgg_build_tasks t ON t.milestone_id = m.id
  GROUP BY p.project_key, r.release_key, m.milestone_key, m.weight;;
alter view public.tgg_build_progress_v1 set (security_invoker=true);

-- [70000000083] view public.tgg_build_ready_tasks_v1
create or replace view public.tgg_build_ready_tasks_v1 as  SELECT t.id,
    t.task_key,
    t.title,
    t.task_type,
    t.priority,
    t.risk_level,
    t.status,
    t.agent_type,
    t.retry_count,
    t.max_retries,
    m.milestone_key,
    r.release_key,
    p.project_key
   FROM public.tgg_build_tasks t
     JOIN public.tgg_build_milestones m ON m.id = t.milestone_id
     JOIN public.tgg_build_releases r ON r.id = m.release_id
     JOIN public.tgg_build_projects p ON p.id = r.project_id
  WHERE t.status = ANY (ARRAY['ready'::text, 'approval_required'::text])
  ORDER BY t.priority, t.created_at;;
alter view public.tgg_build_ready_tasks_v1 set (security_invoker=true);

-- [70000000084] view public.tgg_build_release_progress_v1
create or replace view public.tgg_build_release_progress_v1 as  WITH milestone_progress AS (
         SELECT p.id AS project_id,
            p.project_key,
            r.id AS release_id,
            r.release_key,
            m.id AS milestone_id,
            m.milestone_key,
            m.weight,
            count(t.id) AS task_count,
            count(t.id) FILTER (WHERE t.status = ANY (ARRAY['complete'::text, 'passed'::text, 'skipped'::text])) AS done_count
           FROM public.tgg_build_projects p
             JOIN public.tgg_build_releases r ON r.project_id = p.id
             JOIN public.tgg_build_milestones m ON m.release_id = r.id
             LEFT JOIN public.tgg_build_tasks t ON t.milestone_id = m.id
          GROUP BY p.id, p.project_key, r.id, r.release_key, m.id, m.milestone_key, m.weight
        )
 SELECT project_key,
    release_key,
    round(100.0 * sum(weight *
        CASE
            WHEN task_count = 0 THEN 0::numeric
            ELSE done_count::numeric / task_count::numeric
        END) / NULLIF(sum(weight), 0::numeric), 1) AS release_progress_pct,
    sum(task_count) AS task_count,
    sum(done_count) AS done_count
   FROM milestone_progress
  GROUP BY project_key, release_key;;
alter view public.tgg_build_release_progress_v1 set (security_invoker=true);

-- [70000000085] view public.tgg_code_sync_duplicate_families
create or replace view public.tgg_code_sync_duplicate_families as  SELECT family_key,
    count(*)::integer AS deployed_count,
    max(slug) FILTER (WHERE canonical AND runtime_state <> 'retired_stub'::text) AS canonical_slug,
    count(*) FILTER (WHERE duplicate_candidate)::integer AS duplicate_candidates,
    jsonb_agg(jsonb_build_object('slug', slug, 'version', deployment_version, 'updated_at', updated_at, 'hash', source_hash, 'verify_jwt', verify_jwt, 'canonical', canonical, 'runtime_state', runtime_state, 'retirement_state', retirement_state) ORDER BY canonical DESC, updated_at DESC NULLS LAST) AS members,
        CASE
            WHEN bool_and(runtime_state = 'retired_stub'::text) THEN 'fully_retired'::text
            WHEN bool_or(runtime_state = 'live'::text) THEN 'live'::text
            ELSE 'mixed_or_unknown'::text
        END AS family_runtime_state
   FROM private.tgg_edge_function_registry
  GROUP BY family_key
 HAVING count(*) > 1;;
alter view public.tgg_code_sync_duplicate_families set (security_invoker=true);

-- [70000000086] view public.tgg_code_sync_retirement_manifest
create or replace view public.tgg_code_sync_retirement_manifest as  SELECT family_key,
    slug,
    canonical_slug,
    reference_count,
    approved_state,
    reason,
    verified_at,
    retired_at
   FROM private.tgg_edge_retirement_manifest m
  ORDER BY family_key, slug;;
alter view public.tgg_code_sync_retirement_manifest set (security_invoker=true);

-- [70000000087] view public.tgg_code_sync_retirement_queue
create or replace view public.tgg_code_sync_retirement_queue as  SELECT r.family_key,
    r.slug,
    r.deployment_version,
    r.updated_at,
    r.verify_jwt,
    r.retirement_state,
    a.db_function_refs,
    a.cron_refs,
    a.blogger_job_refs,
    a.blogger_backup_refs,
    a.total_refs,
    a.checked_at
   FROM private.tgg_edge_function_registry r
     JOIN private.tgg_edge_function_dependency_audit a USING (slug)
  WHERE r.duplicate_candidate
  ORDER BY (
        CASE r.retirement_state
            WHEN 'safe_to_retire'::text THEN 0
            ELSE 1
        END), a.total_refs, r.family_key, r.updated_at;;
alter view public.tgg_code_sync_retirement_queue set (security_invoker=true);

