-- [70000000090] view public.tgg_creator_campaign_health
create or replace view public.tgg_creator_campaign_health as  SELECT c.owner_user_id AS creator_user_id,
    c.artist_id,
    c.id AS campaign_id,
    c.title,
    c.status,
    c.objective,
    c.target_value,
    c.current_value,
    c.starts_at,
    c.ends_at,
    COALESCE(count(t.id), 0::bigint) AS task_count,
    COALESCE(count(t.id) FILTER (WHERE t.status = ANY (ARRAY['done'::text, 'complete'::text, 'completed'::text])), 0::bigint) AS tasks_done,
        CASE
            WHEN c.target_value IS NULL OR c.target_value = 0 THEN NULL::numeric
            ELSE round(c.current_value::numeric / c.target_value::numeric * 100::numeric, 1)
        END AS objective_percent
   FROM public.tgg_campaigns c
     LEFT JOIN public.tgg_campaign_tasks t ON t.campaign_id = c.id AND t.owner_user_id = c.owner_user_id
  GROUP BY c.owner_user_id, c.artist_id, c.id, c.title, c.status, c.objective, c.target_value, c.current_value, c.starts_at, c.ends_at;;
alter view public.tgg_creator_campaign_health set (security_invoker=true);

-- [70000000091] view public.tgg_creator_command_center
create or replace view public.tgg_creator_command_center as  SELECT user_id AS creator_user_id,
    id AS artist_id,
    COALESCE(( SELECT count(*) AS count
           FROM public.tgg_creator_action_queue q
          WHERE q.owner_user_id = a.user_id AND q.artist_id = a.id AND q.status = 'open'::text), 0::bigint) AS open_actions,
    COALESCE(( SELECT count(*) AS count
           FROM public.tgg_creator_action_queue q
          WHERE q.owner_user_id = a.user_id AND q.artist_id = a.id AND q.status = 'open'::text AND q.priority >= 90), 0::bigint) AS urgent_actions,
    COALESCE(( SELECT count(*) AS count
           FROM public.tgg_creator_release_health r
          WHERE r.creator_user_id = a.user_id AND r.artist_id = a.id AND r.readiness_percent < 100), 0::bigint) AS releases_needing_work,
    COALESCE(( SELECT count(*) AS count
           FROM public.tgg_creator_campaign_health c
          WHERE c.creator_user_id = a.user_id AND c.artist_id = a.id AND (c.status <> ALL (ARRAY['complete'::text, 'completed'::text, 'cancelled'::text, 'canceled'::text]))), 0::bigint) AS active_campaigns,
    COALESCE(( SELECT m.active_supporters
           FROM public.tgg_creator_monetization_summary m
          WHERE m.creator_user_id = a.user_id AND m.artist_id = a.id), 0::bigint) AS active_supporters,
    COALESCE(( SELECT m.gross_support_cents
           FROM public.tgg_creator_monetization_summary m
          WHERE m.creator_user_id = a.user_id AND m.artist_id = a.id), 0::bigint) AS gross_support_cents,
    COALESCE(( SELECT sum(b.requests) AS sum
           FROM public.tgg_creator_booking_pipeline b
          WHERE b.creator_user_id = a.user_id AND (b.status = ANY (ARRAY['pending'::text, 'requested'::text, 'new'::text]))), 0::numeric)::bigint AS pending_bookings,
    COALESCE(( SELECT sum(e.checkins) AS sum
           FROM public.tgg_creator_event_performance e
          WHERE e.creator_user_id = a.user_id AND e.artist_id = a.id AND e.starts_at >= (now() - '30 days'::interval)), 0::numeric)::bigint AS recent_event_checkins
   FROM public.artists a;;
alter view public.tgg_creator_command_center set (security_invoker=true);

-- [70000000092] view public.tgg_creator_daily_brief
create or replace view public.tgg_creator_daily_brief as  SELECT owner_user_id,
    count(*) FILTER (WHERE status = 'open'::text) AS open_actions,
    count(*) FILTER (WHERE status = 'open'::text AND priority >= 80) AS urgent_actions,
    min(due_at) FILTER (WHERE status = 'open'::text) AS next_due_at,
    COALESCE(jsonb_agg(jsonb_build_object('id', id, 'title', title, 'action_type', action_type, 'priority', priority, 'due_at', due_at) ORDER BY priority DESC, created_at) FILTER (WHERE status = 'open'::text), '[]'::jsonb) AS actions
   FROM public.tgg_creator_action_queue q
  WHERE owner_user_id = (( SELECT auth.uid() AS uid))
  GROUP BY owner_user_id;;
alter view public.tgg_creator_daily_brief set (security_invoker=true);

-- [70000000093] view public.tgg_creator_event_performance
create or replace view public.tgg_creator_event_performance as  SELECT e.created_by AS creator_user_id,
    e.artist_id,
    e.id AS event_id,
    e.title,
    e.event_type,
    e.starts_at,
    e.status,
    count(ec.user_id) AS checkins,
    count(ec.user_id) FILTER (WHERE ec.badge_code IS NOT NULL) AS badge_checkins
   FROM public.tgg_events e
     LEFT JOIN public.tgg_event_checkins ec ON ec.event_id = e.id
  GROUP BY e.created_by, e.artist_id, e.id, e.title, e.event_type, e.starts_at, e.status;;
alter view public.tgg_creator_event_performance set (security_invoker=true);

-- [70000000094] view public.tgg_creator_fan_intelligence_summary
create or replace view public.tgg_creator_fan_intelligence_summary as  SELECT creator_user_id,
    artist_id,
    count(*) AS total_fans,
    count(*) FILTER (WHERE fan_state = 'new'::text) AS new_fans,
    count(*) FILTER (WHERE fan_state = 'active'::text) AS active_fans,
    count(*) FILTER (WHERE fan_state = 'superfan'::text) AS superfans,
    count(*) FILTER (WHERE fan_state = 'supporter'::text) AS supporters,
    count(*) FILTER (WHERE fan_state = 'slipping'::text) AS slipping_fans,
    count(*) FILTER (WHERE fan_state = 'dormant'::text) AS dormant_fans,
    round(avg(engagement_score), 1) AS avg_engagement_score,
    round(avg(recency_score), 1) AS avg_recency_score,
    round(avg(loyalty_score), 1) AS avg_loyalty_score,
    max(calculated_at) AS refreshed_at
   FROM public.tgg_fan_intelligence_snapshots
  GROUP BY creator_user_id, artist_id;;
alter view public.tgg_creator_fan_intelligence_summary set (security_invoker=true);

-- [70000000095] view public.tgg_creator_growth_snapshot
create or replace view public.tgg_creator_growth_snapshot as  SELECT a.user_id AS owner_user_id,
    a.id AS artist_id,
    count(DISTINCT g.id) FILTER (WHERE g.status <> ALL (ARRAY['completed'::text, 'cancelled'::text])) AS open_goals,
    count(DISTINCT c.id) FILTER (WHERE c.status = ANY (ARRAY['active'::text, 'scheduled'::text, 'draft'::text])) AS active_campaigns,
    count(DISTINCT o.id) FILTER (WHERE o.status = 'open'::text) AS open_opportunities,
    count(DISTINCT s.id) FILTER (WHERE s.is_active = true) AS active_smart_links
   FROM public.artists a
     LEFT JOIN public.tgg_creator_goals g ON g.artist_id = a.id
     LEFT JOIN public.tgg_campaigns c ON c.artist_id = a.id
     LEFT JOIN public.tgg_opportunities o ON o.artist_id = a.id
     LEFT JOIN public.tgg_smart_links s ON s.artist_id = a.id
  GROUP BY a.user_id, a.id;;
alter view public.tgg_creator_growth_snapshot set (security_invoker=true);

-- [70000000096] view public.tgg_creator_monetization_summary
create or replace view public.tgg_creator_monetization_summary as  SELECT a.user_id AS creator_user_id,
    a.id AS artist_id,
    COALESCE(sum(s.amount_cents) FILTER (WHERE s.status = ANY (ARRAY['paid'::text, 'succeeded'::text, 'complete'::text, 'completed'::text])), 0::bigint) AS gross_support_cents,
    COALESCE(sum(s.platform_fee_cents) FILTER (WHERE s.status = ANY (ARRAY['paid'::text, 'succeeded'::text, 'complete'::text, 'completed'::text])), 0::bigint) AS platform_fee_cents,
    count(s.id) FILTER (WHERE s.status = ANY (ARRAY['paid'::text, 'succeeded'::text, 'complete'::text, 'completed'::text])) AS paid_transactions,
    count(DISTINCT m.fan_user_id) FILTER (WHERE m.status = ANY (ARRAY['active'::text, 'trialing'::text])) AS active_supporters
   FROM public.artists a
     LEFT JOIN public.tgg_support_transactions s ON s.artist_id = a.id
     LEFT JOIN public.tgg_memberships m ON m.artist_id = a.id
  GROUP BY a.user_id, a.id;;
alter view public.tgg_creator_monetization_summary set (security_invoker=true);

-- [70000000097] view public.tgg_creator_os_command_center
create or replace view public.tgg_creator_os_command_center as  SELECT ( SELECT p.id
           FROM public.profiles p
          WHERE p.id = (( SELECT auth.uid() AS uid))
         LIMIT 1) AS user_id,
    ( SELECT a.id
           FROM public.artists a
          WHERE a.user_id = (( SELECT auth.uid() AS uid))
         LIMIT 1) AS artist_id,
    jsonb_build_object('releases', jsonb_build_object('total', COALESCE(( SELECT count(*) AS count
           FROM public.mixtapes m
             JOIN public.artists a ON a.id = m.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid))), 0::bigint), 'published', COALESCE(( SELECT count(*) AS count
           FROM public.mixtapes m
             JOIN public.artists a ON a.id = m.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid)) AND m.status = 'published'::public.mixtape_status), 0::bigint), 'drafts', COALESCE(( SELECT count(*) AS count
           FROM public.mixtapes m
             JOIN public.artists a ON a.id = m.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid)) AND m.status = 'draft'::public.mixtape_status), 0::bigint)), 'media', jsonb_build_object('videos', COALESCE(( SELECT count(*) AS count
           FROM public.videos v
             JOIN public.artists a ON a.id = v.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid))), 0::bigint), 'artwork', COALESCE(( SELECT count(*) AS count
           FROM public.artist_artwork aa
          WHERE aa.user_id = (( SELECT auth.uid() AS uid))), 0::bigint)), 'commerce', jsonb_build_object('products', COALESCE(( SELECT count(*) AS count
           FROM public.products pr
             JOIN public.artists a ON a.id = pr.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid))), 0::bigint), 'merch_products', COALESCE(( SELECT count(*) AS count
           FROM public.merch_products mp
             JOIN public.artists a ON a.id = mp.creator_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid))), 0::bigint)), 'community', jsonb_build_object('followers', COALESCE(( SELECT count(*) AS count
           FROM public.artist_follows af
             JOIN public.artists a ON a.id = af.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid))), 0::bigint), 'notifications', COALESCE(( SELECT count(*) AS count
           FROM public.notifications n
          WHERE n.recipient_id = (( SELECT auth.uid() AS uid))), 0::bigint), 'messages_sent', COALESCE(( SELECT count(*) AS count
           FROM public.tgg_messages m
          WHERE m.sender_id = (( SELECT auth.uid() AS uid))), 0::bigint)), 'growth', jsonb_build_object('goals', COALESCE(( SELECT count(*) AS count
           FROM public.tgg_creator_goals g
             JOIN public.artists a ON a.id = g.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid))), 0::bigint), 'campaigns', COALESCE(( SELECT count(*) AS count
           FROM public.tgg_campaigns c
             JOIN public.artists a ON a.id = c.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid))), 0::bigint), 'opportunities', COALESCE(( SELECT count(*) AS count
           FROM public.tgg_opportunities o
             JOIN public.artists a ON a.id = o.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid))), 0::bigint)), 'supporters', jsonb_build_object('memberships', COALESCE(( SELECT count(*) AS count
           FROM public.tgg_memberships ms
             JOIN public.artists a ON a.id = ms.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid))), 0::bigint), 'support_transactions', COALESCE(( SELECT count(*) AS count
           FROM public.tgg_support_transactions st
             JOIN public.artists a ON a.id = st.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid))), 0::bigint)), 'workflow', jsonb_build_object('active_runs', 0, 'legacy_runtime_retired', true, 'pending_actions', COALESCE(( SELECT count(*) AS count
           FROM public.tgg_creator_action_queue q
             JOIN public.artists a ON a.id = q.artist_id
          WHERE a.user_id = (( SELECT auth.uid() AS uid))), 0::bigint))) AS snapshot;;
alter view public.tgg_creator_os_command_center set (security_invoker=true);

-- [70000000098] view public.tgg_creator_release_health
create or replace view public.tgg_creator_release_health as  SELECT a.user_id AS creator_user_id,
    m.artist_id,
    m.id AS release_id,
    m.title,
    m.status,
    m.release_date,
    m.play_count,
    m.download_count,
    COALESCE(count(rc.id), 0::bigint) AS checklist_items,
    COALESCE(count(rc.id) FILTER (WHERE rc.status = 'done'::text), 0::bigint) AS checklist_done,
        CASE
            WHEN count(rc.id) = 0 THEN 0
            ELSE round(count(rc.id) FILTER (WHERE rc.status = 'done'::text)::numeric / count(rc.id)::numeric * 100::numeric)::integer
        END AS readiness_percent,
    COALESCE(sl.click_count, 0::bigint) AS smart_link_clicks
   FROM public.mixtapes m
     JOIN public.artists a ON a.id = m.artist_id
     LEFT JOIN public.tgg_release_checklist_items rc ON rc.release_id = m.id AND rc.owner_user_id = a.user_id
     LEFT JOIN LATERAL ( SELECT sum(s.click_count)::bigint AS click_count
           FROM public.tgg_smart_links s
          WHERE s.release_id = m.id AND s.owner_user_id = a.user_id AND s.is_active = true) sl ON true
  GROUP BY a.user_id, m.artist_id, m.id, m.title, m.status, m.release_date, m.play_count, m.download_count, sl.click_count;;
alter view public.tgg_creator_release_health set (security_invoker=true);

-- [70000000099] view public.tgg_creator_supporter_summary
create or replace view public.tgg_creator_supporter_summary as  SELECT creator_user_id,
    artist_id,
    count(*) AS supporter_records,
    count(*) FILTER (WHERE supporter_state = ANY (ARRAY['new'::text, 'active'::text, 'loyal'::text])) AS active_supporters,
    count(*) FILTER (WHERE supporter_state = 'at_risk'::text) AS at_risk_supporters,
    count(*) FILTER (WHERE supporter_state = 'churned'::text) AS churned_supporters,
    COALESCE(sum(lifetime_support_cents), 0::numeric)::bigint AS tracked_lifetime_support_cents,
    round(avg(health_score), 1) AS average_health_score,
    max(calculated_at) AS calculated_at
   FROM public.tgg_supporter_health_snapshots
  GROUP BY creator_user_id, artist_id;;
alter view public.tgg_creator_supporter_summary set (security_invoker=true);

-- [70000000100] view public.tgg_provider_activation_staging
create or replace view public.tgg_provider_activation_staging as  SELECT provider_key,
    status,
    endpoint_url,
    updated_at
   FROM private.tgg_provider_activation_staging;;
alter view public.tgg_provider_activation_staging set (security_barrier=true);

-- [70000000101] view public.user_notification_summary
create or replace view public.user_notification_summary as  SELECT recipient_id AS user_id,
    count(*) AS total_notifications,
    count(*) FILTER (WHERE read_at IS NULL) AS unread_notifications,
    max(created_at) AS latest_notification_at
   FROM public.notifications
  WHERE recipient_id = auth.uid()
  GROUP BY recipient_id;;
alter view public.user_notification_summary set (security_invoker=true);

